CREATE TABLE public.admin_accounts (
    id uuid NOT NULL,
    username character varying(32) NOT NULL,
    display_name character varying(100) NOT NULL,
    password_hash character varying(255) NOT NULL,
    is_enabled boolean DEFAULT true NOT NULL,
    failed_login_attempts integer DEFAULT 0 NOT NULL,
    locked_until timestamp(3) with time zone,
    last_login_at timestamp(3) with time zone,
    created_at timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp(3) with time zone NOT NULL,
    identity_type character varying(32) DEFAULT 'standard_user'::character varying NOT NULL,
    group_id uuid DEFAULT 'a0000000-0000-4000-8000-000000000000'::uuid NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    created_by character varying(100),
    updated_by character varying(100),
    deleted_by character varying(100),
    deleted_at timestamp(3) with time zone,
    email character varying(254),
    phone character varying(16),
    CONSTRAINT admin_accounts_deleted_disabled CHECK ("deleted_at" IS NULL OR NOT "is_enabled"),
    CONSTRAINT admin_accounts_email_canonical_check CHECK (
    "email" IS NULL OR (
      "email" = lower(btrim("email"))
      AND "email" ~ '^[a-z0-9.!#$%&''*+/=?^_`{|}~-]+@[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$'
    )
  ),
    CONSTRAINT admin_accounts_failed_attempts_nonnegative CHECK ("failed_login_attempts" >= 0),
    CONSTRAINT admin_accounts_identity_type_known CHECK ("identity_type" IN ('super_admin','standard_user')),
    CONSTRAINT admin_accounts_phone_canonical_check CHECK (
    "phone" IS NULL OR "phone" ~ '^\+[1-9][0-9]{5,14}$'
  ),
    CONSTRAINT admin_accounts_username_normalized CHECK ("username" ~ '^[a-z][a-z0-9._-]{3,31}$'),
    CONSTRAINT admin_accounts_version_positive CHECK ("version" > 0)
);



CREATE TABLE public.admin_groups (
    id uuid NOT NULL,
    name character varying(100) NOT NULL,
    description character varying(500) DEFAULT ''::character varying NOT NULL,
    sort integer DEFAULT 0 NOT NULL,
    is_enabled boolean DEFAULT true NOT NULL,
    permissions text[] DEFAULT ARRAY[]::text[] NOT NULL,
    page_ids text[] DEFAULT ARRAY[]::text[] NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    created_at timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by character varying(100),
    updated_by character varying(100),
    deleted_by character varying(100),
    deleted_at timestamp(3) with time zone,
    CONSTRAINT admin_groups_deleted_disabled CHECK ("deleted_at" IS NULL OR NOT "is_enabled"),
    CONSTRAINT admin_groups_name_nonempty CHECK (length(btrim("name")) > 0),
    CONSTRAINT admin_groups_pages_allowed CHECK (
    "page_ids" <@ ARRAY['users','audit','analytics','fitness_exercises','fitness_templates','fitness_plans','banners']::TEXT[]
  ),
    CONSTRAINT admin_groups_permissions_allowed CHECK (
    "permissions" <@ ARRAY[
      'users:read','users:write','devices:read','devices:revoke','audit:read','status:read',
      'analytics:read','fitness:read','fitness:write','banners:read','banners:write'
    ]::TEXT[]
  ),
    CONSTRAINT admin_groups_read_dependencies CHECK (
    (NOT ('users:write'=ANY("permissions")) OR 'users:read'=ANY("permissions")) AND
    (NOT ('devices:read'=ANY("permissions")) OR 'users:read'=ANY("permissions")) AND
    (NOT ('devices:revoke'=ANY("permissions")) OR 'devices:read'=ANY("permissions")) AND
    (NOT ('users'=ANY("page_ids")) OR 'users:read'=ANY("permissions")) AND
    (NOT ('audit'=ANY("page_ids")) OR 'audit:read'=ANY("permissions")) AND
    (NOT ('analytics'=ANY("page_ids")) OR 'analytics:read'=ANY("permissions")) AND
    (NOT ('fitness:write'=ANY("permissions")) OR 'fitness:read'=ANY("permissions")) AND
    (NOT ("page_ids" && ARRAY['fitness_exercises','fitness_templates','fitness_plans']::TEXT[]) OR 'fitness:read'=ANY("permissions")) AND
    (NOT ('banners:write'=ANY("permissions")) OR 'banners:read'=ANY("permissions")) AND
    (NOT ('banners'=ANY("page_ids")) OR 'banners:read'=ANY("permissions"))
  ),
    CONSTRAINT admin_groups_version_positive CHECK ("version" > 0)
);



