    file_name character varying(200) NOT NULL,
    byte_size integer NOT NULL,
    width integer NOT NULL,
    height integer NOT NULL,
    created_at timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by character varying(100),
    CONSTRAINT app_banner_media_dimensions_check CHECK (
        "width" BETWEEN 1 AND 4096 AND "height" BETWEEN 1 AND 4096
        AND "width"::bigint * "height" <= 16000000
    ),
    CONSTRAINT app_banner_media_hash_check CHECK ("id" ~ '^[a-f0-9]{64}$'),
    CONSTRAINT app_banner_media_size_check CHECK ("byte_size" > 0 AND "byte_size" <= 8388608)
);



CREATE TABLE public.app_banners (
    slot character varying(64) NOT NULL,
    image_id character varying(64),
    target character varying(64) NOT NULL,
    is_enabled boolean DEFAULT false NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    updated_at timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by character varying(100),
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    target_id character varying(128),
    sort_order integer DEFAULT 0 NOT NULL,
    deleted_at timestamp(3) with time zone,
    CONSTRAINT app_banners_deleted_disabled_check CHECK ("deleted_at" IS NULL OR NOT "is_enabled"),
    CONSTRAINT app_banners_enabled_image_check CHECK (NOT "is_enabled" OR "image_id" IS NOT NULL),
    CONSTRAINT app_banners_slot_check CHECK ("slot" IN ('fitness-plan-library', 'fitness-template-library')),
    CONSTRAINT app_banners_sort_order_check CHECK ("sort_order" BETWEEN 0 AND 9999),
    CONSTRAINT app_banners_target_check CHECK (
    ("target" IN ('fitness-plan-library', 'fitness-template-library', 'fitness-exercises', 'fitness-plans', 'fitness-templates')
      AND "target_id" IS NULL)
    OR ("target" IN ('official-plan', 'official-template') AND "target_id" IS NOT NULL AND length(btrim("target_id")) > 0)
  ),
    CONSTRAINT app_banners_version_check CHECK ("version" >= 1)
);



