    deleted_at timestamp(3) with time zone,
    CONSTRAINT day_books_name_check CHECK (char_length(name) BETWEEN 1 AND 100 AND name = btrim(name, U&'\0009\000a\000b\000c\000d\0020\0085\00a0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200a\2028\2029\202f\205f\3000\feff')),
    CONSTRAINT day_books_revision_check CHECK (revision >= 1)
);



CREATE TABLE public.day_events (
    id uuid NOT NULL,
    day_book_id uuid NOT NULL,
    name text NOT NULL,
    category text NOT NULL,
    countdown_mode text,
    interval_days integer,
    repeat_type text NOT NULL,
    statistic_type text NOT NULL,
    event_calendar_type text,
    event_original_year integer,
    event_original_month integer,
    event_original_day integer,
    event_is_leap_month boolean,
    event_solar_date date,
    start_calendar_type text,
    start_original_year integer,
    start_original_month integer,
    start_original_day integer,
    start_is_leap_month boolean,
    start_solar_date date,
    end_calendar_type text,
    end_original_year integer,
    end_original_month integer,
    end_original_day integer,
    end_is_leap_month boolean,
    end_solar_date date,
    revision integer DEFAULT 1 NOT NULL,
    created_at timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp(3) with time zone NOT NULL,
    deleted_at timestamp(3) with time zone,
    updated_by_device_id uuid,
    CONSTRAINT day_events_definition_check CHECK (
      statistic_type IN ('year', 'day') AND (
        (category IN ('birthday', 'anniversary') AND event_solar_date IS NOT NULL AND start_solar_date IS NULL AND end_solar_date IS NULL AND countdown_mode IS NULL AND interval_days IS NULL AND repeat_type = 'yearly')
        OR (category = 'countdown' AND countdown_mode IS NOT NULL AND countdown_mode = 'fixed_date' AND event_solar_date IS NOT NULL AND start_solar_date IS NULL AND end_solar_date IS NULL AND interval_days IS NULL AND repeat_type = 'none')
        OR (category = 'countdown' AND countdown_mode IS NOT NULL AND countdown_mode = 'interval_days' AND event_solar_date IS NULL AND start_solar_date IS NOT NULL AND end_solar_date IS NULL AND interval_days IS NOT NULL AND interval_days BETWEEN 1 AND 36500 AND start_solar_date + interval_days - 1 <= DATE '2100-12-31' AND repeat_type = 'none')
        OR (category = 'stage' AND event_solar_date IS NULL AND start_solar_date IS NOT NULL AND countdown_mode IS NULL AND interval_days IS NULL AND repeat_type = 'none' AND (end_solar_date IS NULL OR end_solar_date >= start_solar_date))
      )),
    CONSTRAINT day_events_end_date_check CHECK ((((end_calendar_type IS NULL) AND (end_original_year IS NULL) AND (end_original_month IS NULL) AND (end_original_day IS NULL) AND (end_is_leap_month IS NULL) AND (end_solar_date IS NULL)) OR ((end_calendar_type IS NOT NULL) AND (end_original_year IS NOT NULL) AND (end_original_month IS NOT NULL) AND (end_original_day IS NOT NULL) AND (end_is_leap_month IS NOT NULL) AND (end_solar_date IS NOT NULL) AND (end_calendar_type = ANY (ARRAY['solar'::text, 'lunar'::text])) AND ((end_original_month >= 1) AND (end_original_month <= 12)) AND ((end_original_day >= 1) AND (end_original_day <= 31)) AND ((end_solar_date >= '1901-01-01'::date) AND (end_solar_date <= '2100-12-31'::date)) AND (((end_calendar_type = 'lunar'::text) AND ((end_original_year >= 1900) AND (end_original_year <= 2100)) AND (end_original_day <= 30)) OR ((end_calendar_type = 'solar'::text) AND ((end_original_year >= 1901) AND (end_original_year <= 2100)) AND (NOT end_is_leap_month) AND (EXTRACT(year FROM end_solar_date) = (end_original_year)::numeric) AND (EXTRACT(month FROM end_solar_date) = (end_original_month)::numeric) AND (EXTRACT(day FROM end_solar_date) = (end_original_day)::numeric)))))),
    CONSTRAINT day_events_event_date_check CHECK ((((event_calendar_type IS NULL) AND (event_original_year IS NULL) AND (event_original_month IS NULL) AND (event_original_day IS NULL) AND (event_is_leap_month IS NULL) AND (event_solar_date IS NULL)) OR ((event_calendar_type IS NOT NULL) AND (event_original_year IS NOT NULL) AND (event_original_month IS NOT NULL) AND (event_original_day IS NOT NULL) AND (event_is_leap_month IS NOT NULL) AND (event_solar_date IS NOT NULL) AND (event_calendar_type = ANY (ARRAY['solar'::text, 'lunar'::text])) AND ((event_original_month >= 1) AND (event_original_month <= 12)) AND ((event_original_day >= 1) AND (event_original_day <= 31)) AND ((event_solar_date >= '1901-01-01'::date) AND (event_solar_date <= '2100-12-31'::date)) AND (((event_calendar_type = 'lunar'::text) AND ((event_original_year >= 1900) AND (event_original_year <= 2100)) AND (event_original_day <= 30)) OR ((event_calendar_type = 'solar'::text) AND ((event_original_year >= 1901) AND (event_original_year <= 2100)) AND (NOT event_is_leap_month) AND (EXTRACT(year FROM event_solar_date) = (event_original_year)::numeric) AND (EXTRACT(month FROM event_solar_date) = (event_original_month)::numeric) AND (EXTRACT(day FROM event_solar_date) = (event_original_day)::numeric)))))),
    CONSTRAINT day_events_name_check CHECK (char_length(name) BETWEEN 1 AND 100 AND name = btrim(name, U&'\0009\000a\000b\000c\000d\0020\0085\00a0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200a\2028\2029\202f\205f\3000\feff')),
    CONSTRAINT day_events_revision_check CHECK (revision >= 1),
    CONSTRAINT day_events_start_date_check CHECK ((((start_calendar_type IS NULL) AND (start_original_year IS NULL) AND (start_original_month IS NULL) AND (start_original_day IS NULL) AND (start_is_leap_month IS NULL) AND (start_solar_date IS NULL)) OR ((start_calendar_type IS NOT NULL) AND (start_original_year IS NOT NULL) AND (start_original_month IS NOT NULL) AND (start_original_day IS NOT NULL) AND (start_is_leap_month IS NOT NULL) AND (start_solar_date IS NOT NULL) AND (start_calendar_type = ANY (ARRAY['solar'::text, 'lunar'::text])) AND ((start_original_month >= 1) AND (start_original_month <= 12)) AND ((start_original_day >= 1) AND (start_original_day <= 31)) AND ((start_solar_date >= '1901-01-01'::date) AND (start_solar_date <= '2100-12-31'::date)) AND (((start_calendar_type = 'lunar'::text) AND ((start_original_year >= 1900) AND (start_original_year <= 2100)) AND (start_original_day <= 30)) OR ((start_calendar_type = 'solar'::text) AND ((start_original_year >= 1901) AND (start_original_year <= 2100)) AND (NOT start_is_leap_month) AND (EXTRACT(year FROM start_solar_date) = (start_original_year)::numeric) AND (EXTRACT(month FROM start_solar_date) = (start_original_month)::numeric) AND (EXTRACT(day FROM start_solar_date) = (start_original_day)::numeric))))))
);



