CREATE TABLE public.fitness_entities (
    id uuid NOT NULL,
    fitness_space_id uuid NOT NULL,
    entity_type character varying(64) NOT NULL,
    revision integer DEFAULT 1 NOT NULL,
    payload jsonb NOT NULL,
    status character varying(32),
    occurrence_key character varying(255),
    created_at timestamp(3) with time zone NOT NULL,
    updated_at timestamp(3) with time zone NOT NULL,
    deleted_at timestamp(3) with time zone,
    CONSTRAINT fitness_entities_occurrence_check CHECK (entity_type<>'fitness_workout' OR ((payload->>'source_kind'='plan' AND occurrence_key IS NOT NULL AND payload->>'source_plan_id' IS NOT NULL AND payload->>'source_plan_name' IS NOT NULL AND split_part(occurrence_key,':',1)=payload->>'source_plan_id' AND id=uuid_generate_v5((payload->>'source_plan_id')::uuid,occurrence_key)) OR (payload->>'source_kind' IN ('blank','template') AND occurrence_key IS NULL AND payload->>'source_plan_id' IS NULL AND payload->>'source_plan_name' IS NULL))),
    CONSTRAINT fitness_entities_shape_check CHECK (revision >= 1 AND fitness_payload_valid(entity_type,payload) IS TRUE AND created_at=(payload->>'created_at')::timestamptz AND (deleted_at IS NOT NULL OR updated_at=(payload->>'updated_at')::timestamptz) AND ((entity_type='fitness_workout' AND status IS NOT NULL AND status=payload->>'status' AND occurrence_key IS NOT DISTINCT FROM payload->>'occurrence_key') OR (entity_type<>'fitness_workout' AND status IS NULL AND occurrence_key IS NULL)) AND (entity_type<>'fitness_preferences' OR id=fitness_space_id))
);



