CREATE TABLE public.ledger_invites (
    id uuid NOT NULL,
    code_hash character varying(64) NOT NULL,
    code_prefix character varying(8) NOT NULL,
    ledger_id uuid NOT NULL,
    created_by_id uuid NOT NULL,
    role character varying(16) DEFAULT 'editor'::character varying NOT NULL,
    expires_at timestamp(3) with time zone NOT NULL,
    used_at timestamp(3) with time zone,
    used_by_id uuid,
    revoked_at timestamp(3) with time zone,
    created_at timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT ledger_invites_role_check CHECK ((role)::text = 'editor'::text)
);



CREATE TABLE public.ledger_members (
    id uuid NOT NULL,
    ledger_id uuid NOT NULL,
    display_name character varying(100) NOT NULL,
    member_type public."LedgerMemberType" NOT NULL,
    linked_account_id uuid,
    role public."LedgerMemberRole" NOT NULL,
    status public."LedgerMemberStatus" DEFAULT 'ACTIVE'::public."LedgerMemberStatus" NOT NULL,
    archived_at timestamp(3) with time zone,
    archive_updated_at timestamp(3) with time zone,
    archive_updated_by_device_id uuid,
    joined_at timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_at timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp(3) with time zone NOT NULL,
    updated_by_device_id uuid,
    CONSTRAINT ledger_members_registered_id_v5_check CHECK (((member_type <> 'REGISTERED'::public."LedgerMemberType") OR (id = public.uuid_generate_v5(ledger_id, ('user:'::text || (linked_account_id)::text))))),
    CONSTRAINT ledger_members_role_check CHECK (role = ANY (ARRAY['owner'::"LedgerMemberRole", 'editor'::"LedgerMemberRole"])),
    CONSTRAINT ledger_members_type_account_check CHECK (((member_type = 'REGISTERED'::"LedgerMemberType") AND (linked_account_id IS NOT NULL)) OR ((member_type = 'PLACEHOLDER'::"LedgerMemberType") AND (linked_account_id IS NULL)))
);



CREATE TABLE public.ledgers (
    id uuid NOT NULL,
    sync_id uuid NOT NULL,
    owner_id uuid NOT NULL,
    name character varying(255) NOT NULL,
    currency character varying(16) DEFAULT 'CNY'::character varying NOT NULL,
    month_start_day integer DEFAULT 1 NOT NULL,
    aa_enabled boolean DEFAULT false NOT NULL,
    updated_at timestamp(3) with time zone NOT NULL,
    updated_by_device_id uuid,
    deleted_at timestamp(3) with time zone,
    created_at timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT ledgers_currency_check CHECK ((currency)::text ~ '^[A-Z]{3}$'::text),
    CONSTRAINT ledgers_month_start_day_check CHECK ((month_start_day >= 1) AND (month_start_day <= 31))
);



CREATE TABLE public.memo_books (
    id uuid NOT NULL,
    owner_id uuid NOT NULL,
    name text NOT NULL,
    type text NOT NULL,
    sync_id uuid NOT NULL,
    revision integer DEFAULT 1 NOT NULL,
    created_at timestamp(3) with time zone NOT NULL,
    updated_at timestamp(3) with time zone NOT NULL,
    deleted_at timestamp(3) with time zone,
    CONSTRAINT memo_books_shape_check CHECK (type IN ('normal','credentials') AND revision>=1 AND char_length(name)>0)
);



CREATE TABLE public.memo_entries (
    id uuid NOT NULL,
    memo_book_id uuid NOT NULL,
    book_type text NOT NULL,
    title json NOT NULL,
    body_format text,
    body json,
    order_key bigint,
    revision integer DEFAULT 1 NOT NULL,
    created_at timestamp(3) with time zone NOT NULL,
    updated_at timestamp(3) with time zone NOT NULL,
    deleted_at timestamp(3) with time zone,
    CONSTRAINT memo_entries_shape_check CHECK (
  revision>=1 AND (
    (book_type='normal' AND body_format IS NOT NULL AND body_format='delta_v1' AND body IS NOT NULL AND json_typeof(body)='object' AND order_key IS NULL)
    OR (book_type='credentials' AND body_format IS NOT NULL AND body_format='fields_v1' AND body IS NOT NULL AND json_typeof(body)='object' AND order_key IS NOT NULL AND order_key>=0)
  )
),
    CONSTRAINT memo_entries_title_string_check CHECK (json_typeof("title") = 'string')
);



CREATE TABLE public.mutation_reservations (
    scope public."MutationReservationScope" NOT NULL,
    user_id uuid NOT NULL,
    scope_id uuid NOT NULL,
    mutation_id uuid NOT NULL,
    request_hash character(64) NOT NULL,
    created_at timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);



CREATE TABLE public.official_fitness_content (
    id character varying(128) NOT NULL,
    kind character varying(16) NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    content jsonb NOT NULL,
    is_enabled boolean DEFAULT true NOT NULL,
    created_at timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by character varying(100),
    CONSTRAINT official_fitness_content_content_check CHECK (
    jsonb_typeof("content") = 'object'
    AND "content"->>'id' IS NOT NULL
    AND "content"->>'id' = "id"
  ),
    CONSTRAINT official_fitness_content_exercise_fields_check CHECK (
    "kind" <> 'exercise' OR NOT ("content" ? 'aliases')
  ),
    CONSTRAINT official_fitness_content_kind_check CHECK ("kind" IN ('exercise','template','plan')),
    CONSTRAINT official_fitness_content_version_check CHECK ("version">0)
);



CREATE TABLE public.official_fitness_media (
    id character varying(64) NOT NULL,
    file_name character varying(255) NOT NULL,
    mime_type character varying(64) NOT NULL,
    byte_size integer NOT NULL,
    width integer NOT NULL,
    height integer NOT NULL,
    frames integer NOT NULL,
    created_at timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by character varying(100),
    CONSTRAINT official_fitness_media_hash_check CHECK ("id" ~ '^[a-f0-9]{64}$'),
    CONSTRAINT official_fitness_media_shape_check CHECK ("mime_type"='image/gif' AND "byte_size">0 AND "width">0 AND "height">0 AND "frames">0)
);



CREATE TABLE public.official_fitness_state (
    id integer DEFAULT 1 NOT NULL,
    content_version integer DEFAULT 1 NOT NULL,
    CONSTRAINT official_fitness_state_singleton CHECK ("id"=1 AND "content_version">0)
);



CREATE TABLE public.official_fitness_taxonomies (
    kind character varying(16) NOT NULL,
    id character varying(100) NOT NULL,
    name_zh character varying(100) NOT NULL,
    name_hant character varying(100) NOT NULL,
    name_en character varying(200) NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    deleted_at timestamp(3) with time zone,
    created_at timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by character varying(100),
    CONSTRAINT official_fitness_taxonomies_kind_check CHECK ("kind" IN ('body_part', 'equipment')),
    CONSTRAINT official_fitness_taxonomies_sort_check CHECK ("sort_order" >= 0),
    CONSTRAINT official_fitness_taxonomies_version_check CHECK ("version" >= 1)
);



CREATE TABLE public.product_analytics_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    actor_key character(64) NOT NULL,
    event_id uuid NOT NULL,
    kind character varying(24) NOT NULL,
    occurred_at timestamp(3) with time zone NOT NULL,
    received_at timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    platform character varying(8),
    page_id character varying(96),
    app_version character varying(64),
    event_name character varying(128),
    session_id uuid,
    flow_id uuid,
    event_sequence integer,
    banner_slot character varying(64),
    banner_source character varying(16),
    banner_version integer,
    banner_id character varying(96),
    CONSTRAINT product_analytics_actor_check CHECK ("actor_key" ~ '^[a-f0-9]{64}$'),
    CONSTRAINT product_analytics_banner_dimensions_check CHECK (
    CASE WHEN "event_name" IN ('banner_impression', 'banner_click') THEN
      "kind" = 'action' AND "platform" = 'app'
      AND "banner_slot" IS NOT NULL AND "banner_source" IS NOT NULL AND "banner_version" IS NOT NULL
      AND (
        ("banner_slot" = 'fitness-plan-library' AND "page_id" = 'fitness.plans')
        OR ("banner_slot" = 'fitness-template-library' AND "page_id" = 'fitness.templates')
      )
      AND (
        ("banner_source" = 'builtin' AND "banner_version" = 0)
        OR ("banner_source" = 'remote' AND "banner_version" >= 1)
      )
    ELSE "banner_slot" IS NULL AND "banner_source" IS NULL AND "banner_version" IS NULL END
  ),
    CONSTRAINT product_analytics_banner_slide_check CHECK (
    "banner_id" IS NULL OR (
      "event_name" IN ('banner_impression', 'banner_click')
      AND "banner_source" IS NOT NULL AND "banner_slot" IS NOT NULL
      AND (
        ("banner_source" = 'builtin' AND "banner_id" = 'builtin:' || "banner_slot")
        OR ("banner_source" = 'remote' AND "banner_id" ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
      )
    )
  ),
    CONSTRAINT product_analytics_kind_check CHECK ("kind" IN ('registration','active','page_view','action')),
    CONSTRAINT product_analytics_source_check CHECK (
    ("kind" = 'registration' AND ("platform" IS NULL OR "platform" IN ('app', 'web'))
      AND "page_id" IS NULL AND "app_version" IS NULL AND "event_name" IS NULL) OR
    ("kind" IN ('active', 'page_view', 'action') AND "platform" IN ('app', 'web') AND "platform" IS NOT NULL
      AND ("page_id" IS NULL OR "page_id" ~ '^[a-z][a-z0-9_.-]{0,95}$')
      AND ("kind" = 'active' OR "page_id" IS NOT NULL)
      AND (
        ("kind" = 'active' AND "event_name" IS NULL) OR
        ("kind" IN ('page_view', 'action') AND "event_name" IS NOT NULL
          AND "event_name" ~ '^[a-z][a-z0-9_]{0,127}$'
          AND ("kind" <> 'page_view' OR "event_name" = replace("page_id", '.', '_') || '_view'))
      ))
  )
);



CREATE TABLE public.product_analytics_state (
    id integer NOT NULL,
    started_at timestamp(3) with time zone NOT NULL,
    banner_started_at timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT product_analytics_state_singleton CHECK ("id"=1)
);



CREATE TABLE public.recurring_transactions (
    id uuid NOT NULL,
    ledger_id uuid NOT NULL,
    owner_id uuid NOT NULL,
    tx_type character varying(16) NOT NULL,
    amount numeric(38,10) NOT NULL,
    currency_code character varying(16) NOT NULL,
    category_id uuid,
    note text,
    frequency character varying(16) NOT NULL,
    "interval" integer DEFAULT 1 NOT NULL,
    day_of_month integer,
    day_of_week integer,
    month_of_year integer,
    start_date timestamp(3) with time zone NOT NULL,
    end_date timestamp(3) with time zone,
    last_generated_date timestamp(3) with time zone,
    enabled boolean DEFAULT true NOT NULL,
    updated_at timestamp(3) with time zone NOT NULL,
    updated_by_device_id uuid,
    deleted_at timestamp(3) with time zone,
    created_at timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    protocol_version integer DEFAULT 1 NOT NULL,
    time_zone character varying(100) DEFAULT 'UTC'::character varying NOT NULL,
    CONSTRAINT recurring_transactions_amount_check CHECK (amount > (0)::numeric),
    CONSTRAINT recurring_transactions_currency_check CHECK ((currency_code)::text ~ '^[A-Z]{3}$'::text),
    CONSTRAINT recurring_transactions_frequency_check CHECK (frequency IN ('daily', 'weekly', 'monthly', 'yearly')),
    CONSTRAINT recurring_transactions_rule_check CHECK (("interval" >= 1) AND ((day_of_month IS NULL) OR ((day_of_month >= 1) AND (day_of_month <= 31))) AND ((day_of_week IS NULL) OR ((day_of_week >= 1) AND (day_of_week <= 7))) AND ((month_of_year IS NULL) OR ((month_of_year >= 1) AND (month_of_year <= 12))) AND ((end_date IS NULL) OR (end_date >= start_date))),
    CONSTRAINT recurring_transactions_type_check CHECK (tx_type = 'expense')
);



CREATE TABLE public.refresh_tokens (
    id uuid NOT NULL,
    user_id uuid NOT NULL,
    device_id uuid NOT NULL,
    token_hash character varying(64) NOT NULL,
    expires_at timestamp(3) with time zone NOT NULL,
    revoked_at timestamp(3) with time zone,
    auth_generation uuid NOT NULL,
    created_at timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);



CREATE TABLE public.server_epochs (
    id integer DEFAULT 0 NOT NULL,
    auth_generation uuid NOT NULL,
    idempotency_generation uuid NOT NULL,
    updated_at timestamp(3) with time zone NOT NULL,
    sync_cutover_cursor bigint,
    sync_cutover_at timestamp(3) with time zone,
    sync_cursor_floor bigint DEFAULT 0 NOT NULL,
    CONSTRAINT server_epochs_id_check CHECK (id = 0),
    CONSTRAINT server_epochs_sync_cursor_floor_check CHECK ("sync_cursor_floor" >= 0),
    CONSTRAINT server_epochs_sync_cutover_check CHECK (
    ("sync_cutover_cursor" IS NULL AND "sync_cutover_at" IS NULL)
    OR ("sync_cutover_cursor" IS NOT NULL AND "sync_cutover_cursor" >= 0 AND "sync_cutover_at" IS NOT NULL)
  )
);



CREATE TABLE public.sync_changes (
    change_id bigint NOT NULL,
    user_id uuid,
    ledger_id uuid,
    day_book_id uuid,
    memo_book_id uuid,
    fitness_space_id uuid,
    scope character varying(16) NOT NULL,
    entity_type character varying(64) NOT NULL,
    entity_id uuid NOT NULL,
    action character varying(16) NOT NULL,
    mutation_id uuid NOT NULL,
    request_hash character varying(64),
    payload json NOT NULL,
    updated_at timestamp(3) with time zone NOT NULL,
    device_id uuid NOT NULL,
    recipient_user_id uuid,
    CONSTRAINT sync_changes_action_check CHECK (action IN ('upsert', 'delete')),
    CONSTRAINT sync_changes_day_scope_check CHECK ((entity_type IN ('day_book', 'day_event') AND scope = 'user' AND user_id IS NOT NULL AND ledger_id IS NULL AND recipient_user_id IS NULL AND day_book_id IS NOT NULL AND (entity_type <> 'day_book' OR entity_id = day_book_id)) OR (entity_type NOT IN ('day_book', 'day_event') AND day_book_id IS NULL)),
    CONSTRAINT sync_changes_entity_type_check CHECK (entity_type IN ('ledger', 'ledger_archive', 'transaction', 'category', 'recurring_transaction', 'exchange_rate_override', 'member', 'day_book', 'day_event', 'memo_book', 'memo_entry','fitness_space','fitness_template','fitness_plan','fitness_workout','fitness_preferences')),
    CONSTRAINT sync_changes_fitness_scope_check CHECK ((entity_type LIKE 'fitness_%' AND scope='user' AND user_id IS NOT NULL AND ledger_id IS NULL AND day_book_id IS NULL AND memo_book_id IS NULL AND fitness_space_id IS NOT NULL AND recipient_user_id IS NULL AND (entity_type<>'fitness_space' OR entity_id=fitness_space_id)) OR (entity_type NOT LIKE 'fitness_%' AND fitness_space_id IS NULL)),
    CONSTRAINT sync_changes_memo_scope_check CHECK ((entity_type IN ('memo_book','memo_entry') AND scope='user' AND user_id IS NOT NULL AND ledger_id IS NULL AND day_book_id IS NULL AND recipient_user_id IS NULL AND memo_book_id IS NOT NULL AND (entity_type<>'memo_book' OR entity_id=memo_book_id)) OR (entity_type NOT IN ('memo_book','memo_entry') AND memo_book_id IS NULL)),
    CONSTRAINT sync_changes_scope_check CHECK ((((scope)::text = 'user'::text) AND (ledger_id IS NULL)) OR (((scope)::text = 'ledger'::text) AND (ledger_id IS NOT NULL)))
);



CREATE SEQUENCE public.sync_changes_change_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;



ALTER SEQUENCE public.sync_changes_change_id_seq OWNED BY public.sync_changes.change_id;



CREATE TABLE public.transaction_edit_history (
    id uuid NOT NULL,
    transaction_id uuid NOT NULL,
    ledger_id uuid NOT NULL,
    version integer NOT NULL,
    operator_member_id uuid,
    changes jsonb NOT NULL,
    created_at timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);



CREATE TABLE public.transaction_splits (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    transaction_id uuid NOT NULL,
    ledger_id uuid NOT NULL,
    member_id uuid NOT NULL,
    amount numeric(38,10) NOT NULL,
    CONSTRAINT transaction_splits_amount_check CHECK (amount > (0)::numeric),
    CONSTRAINT transaction_splits_participant_check CHECK (member_id IS NOT NULL)
);



CREATE TABLE public.transactions (
    id uuid NOT NULL,
    ledger_id uuid NOT NULL,
    owner_id uuid NOT NULL,
    tx_type character varying(16) NOT NULL,
    amount numeric(38,10) NOT NULL,
    happened_at timestamp(3) with time zone NOT NULL,
    note text,
    category_id uuid,
    category_name text,
    category_kind character varying(16),
    currency_code character varying(16) NOT NULL,
    native_amount numeric(38,10) NOT NULL,
    recurring_id uuid,
    created_by_member_id uuid,
    last_edited_by_member_id uuid,
    payer_member_id uuid,
    aa_mode integer,
    revision integer DEFAULT 1 NOT NULL,
    last_edited_at timestamp(3) with time zone,
    updated_at timestamp(3) with time zone NOT NULL,
    updated_by_device_id uuid,
    deleted_at timestamp(3) with time zone,
    created_at timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    occurrence_date character varying(10),
    CONSTRAINT transactions_aa_mode_check CHECK ((aa_mode IS NULL) OR (aa_mode = ANY (ARRAY[0, 1, 2]))),
    CONSTRAINT transactions_amount_check CHECK ((amount > (0)::numeric) AND (native_amount > (0)::numeric)),
    CONSTRAINT transactions_category_kind_check CHECK (category_kind IS NULL OR category_kind = 'expense'),
    CONSTRAINT transactions_currency_check CHECK ((currency_code)::text ~ '^[A-Z]{3}$'::text),
    CONSTRAINT transactions_revision_check CHECK (revision >= 1),
    CONSTRAINT transactions_type_check CHECK (tx_type = 'expense')
);



CREATE TABLE public.user_profiles (
    id uuid NOT NULL,
    user_id uuid NOT NULL,
    display_name character varying(100),
    gender public."UserGender" DEFAULT 'UNSPECIFIED'::public."UserGender" NOT NULL,
    avatar_file_id character varying(128),
    avatar_version integer DEFAULT 0 NOT NULL,
    theme_primary_color character varying(7),
    appearance jsonb,
    ai_config jsonb,
    primary_currency character varying(16),
    updated_at timestamp(3) with time zone NOT NULL,
    CONSTRAINT user_profiles_avatar_version_check CHECK (avatar_version >= 0)
);



CREATE TABLE public.users (
    id uuid NOT NULL,
    phone_e164 character varying(16) NOT NULL,
    sesame_number character(9) NOT NULL,
    password_hash character varying(255) NOT NULL,
    is_enabled boolean DEFAULT true NOT NULL,
    created_at timestamp(3) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    credential_version integer DEFAULT 0 NOT NULL,
    CONSTRAINT users_phone_e164_check CHECK (((phone_e164)::text ~ '^\+[1-9][0-9]{1,14}$'::text)),
    CONSTRAINT users_sesame_number_check CHECK (sesame_number ~ '^[1-9][0-9]{8}$'::text)
);



