INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0029', 'exercise', 1, '{"id": "0029", "target": "glutes", "name_en": "barbell clean-grip front squat", "name_zh": "杠铃翻举握法前蹲", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0029-qi996YS.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴翻舉握法前蹲", "instructions_en": ["Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, with your elbows pointing forward.", "Lower your body by bending your knees and pushing your hips back, as if you are sitting back into a chair.", "Keep your chest up and your back straight as you lower down, making sure your knees do not go past your toes.", "Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.", "Pause for a moment at the bottom, then push through your heels to stand back up, extending your hips and knees.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先，双脚分开与肩同宽，将杠铃放在上胸部，肘部向前。", "弯曲膝盖并将臀部向后推，降低身体，就像坐在椅子上一样。", "下降时保持挺胸、背部挺直，确保膝盖不超过脚趾。", "继续降低，直到大腿与地面平行，或者尽可能低。", "在底部停顿片刻，然后用脚跟推动站起来，伸展臀部和膝盖。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves", "core"], "instructions_zh_hant": ["首先，雙腳分開與肩同寬，將杠鈴放在上胸部，肘部向前。", "彎曲膝蓋并將臀部向后推，降低身體，就像坐在椅子上一樣。", "下降時保持挺胸、背部挺直，確保膝蓋不超過腳趾。", "繼續降低，直到大腿與地面平行，或者盡可能低。", "在底部停頓片刻，然后用腳跟推動站起來，伸展臀部和膝蓋。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0150', 'exercise', 1, '{"id": "0150", "target": "lats", "name_en": "cable bar lateral pulldown", "name_zh": "绳索杆侧向下拉", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/0150-eYnzaCm.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索桿側向下拉", "instructions_en": ["Adjust the cable pulley to a high position and attach a straight bar.", "Sit facing the cable machine with your feet flat on the ground and your knees slightly bent.", "Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.", "Lean back slightly and keep your chest up, maintaining a slight arch in your lower back.", "Pull the bar down towards your chest, leading with your elbows and squeezing your shoulder blades together.", "Pause for a moment at the bottom of the movement, then slowly return the bar to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将电缆滑轮调整至较高位置并安装直杆。", "面向缆绳机坐着，双脚平放在地面上，膝盖稍微弯曲。", "正手握住杠铃，握距略宽于肩宽。", "稍微向后倾斜，挺胸，保持下背部轻微的拱形。", "将杠铃向下拉向胸部，用肘部引导并将肩胛骨挤压在一起。", "在动作底部暂停片刻，然后慢慢地将杠铃返回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "rhomboids", "rear deltoids"], "instructions_zh_hant": ["將電纜滑輪調整至較高位置并安裝直桿。", "面向纜繩機坐著，雙腳平放在地面上，膝蓋稍微彎曲。", "正手握住杠鈴，握距略寬于肩寬。", "稍微向后傾斜，挺胸，保持下背部輕微的拱形。", "將杠鈴向下拉向胸部，用肘部引導并將肩胛骨擠壓在一起。", "在動作底部暫停片刻，然后慢慢地將杠鈴返回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1707', 'exercise', 1, '{"id": "1707", "target": "abs", "name_en": "prone twist on stability ball", "name_zh": "俯卧转体（健身球）", "body_part": "waist", "equipment": "stability ball", "gif_asset": "assets/fitness/videos/1707-1IG6gVF.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "俯臥轉體（健身球）", "instructions_en": ["Start by lying face down on a stability ball with your feet shoulder-width apart and your toes touching the ground.", "Place your hands behind your head or cross them over your chest.", "Engage your core muscles and slowly lift your upper body off the ball, keeping your back straight.", "Rotate your torso to one side, bringing your shoulder towards your hip. Keep your hips and legs stable throughout the movement.", "Pause for a moment, then return to the starting position.", "Repeat the rotation to the other side.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["首先，面朝下躺在稳定球上，双脚分开与肩同宽，脚趾接触地面。", "将双手放在脑后或交叉放在胸前。", "启动核心肌肉，慢慢将上半身抬离球，保持背部挺直。", "将躯干旋转到一侧，使肩膀靠近臀部。在整个运动过程中保持臀部和腿部稳定。", "暂停片刻，然后回到起始位置。", "重复旋转到另一侧。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["obliques", "lower back"], "instructions_zh_hant": ["首先，面朝下躺在穩定球上，雙腳分開與肩同寬，腳趾接觸地面。", "將雙手放在腦后或交叉放在胸前。", "啟動核心肌肉，慢慢將上半身抬離球，保持背部挺直。", "將軀幹旋轉到一側，使肩膀靠近臀部。在整個運動過程中保持臀部和腿部穩定。", "暫停片刻，然后回到起始位置。", "重復旋轉到另一側。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0741', 'exercise', 1, '{"id": "0741", "target": "glutes", "name_en": "sled closer hack squat", "name_zh": "蹬腿机窄距哈克深蹲", "body_part": "upper legs", "equipment": "sled machine", "gif_asset": "assets/fitness/videos/0741-gf3ZjB9.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "蹬腿機窄距哈克深蹲", "instructions_en": ["Adjust the sled machine to a comfortable weight and position yourself with your back against the pad.", "Place your feet shoulder-width apart on the platform, toes slightly pointed outwards.", "Grip the handles on the sides of the machine for stability.", "Engage your core and slowly lower your body by bending your knees and hips, keeping your back straight.", "Continue lowering until your thighs are parallel to the ground or slightly below.", "Pause for a moment at the bottom, then push through your heels to extend your legs and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将雪橇机调整到舒适的重量，并将背部靠在垫子上。", "将双脚分开与肩同宽放在平台上，脚趾稍微向外。", "握住机器两侧的手柄以保持稳定性。", "弯曲膝盖和臀部，调动核心力量，慢慢降低身体，保持背部挺直。", "继续降低，直到大腿与地面平行或略低于地面。", "在底部停顿片刻，然后用脚跟推动双腿并返回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["將雪橇機調整到舒適的重量，并將背部靠在墊子上。", "將雙腳分開與肩同寬放在平臺上，腳趾稍微向外。", "握住機器兩側的手柄以保持穩定性。", "彎曲膝蓋和臀部，調動核心力量，慢慢降低身體，保持背部挺直。", "繼續降低，直到大腿與地面平行或略低于地面。", "在底部停頓片刻，然后用腳跟推動雙腿并返回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0798', 'exercise', 1, '{"id": "0798", "target": "cardiovascular system", "name_en": "stationary bike walk", "name_zh": "固定自行车慢速骑行", "body_part": "cardio", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0798-a8VDgLw.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "固定自行車慢速騎行", "instructions_en": ["Adjust the seat height and position on the stationary bike to ensure proper alignment.", "Place your feet on the pedals and secure them with the straps if available.", "Start pedaling at a comfortable pace, keeping your back straight and core engaged.", "Maintain a steady rhythm and increase the resistance level if desired.", "Continue pedaling for the desired duration of your cardio workout.", "Cool down by gradually reducing your pace and resistance level.", "Stretch your leg muscles after the workout to prevent tightness and promote recovery."], "instructions_zh": ["调整固定自行车上的座椅高度和位置，以确保正确对齐。", "将脚放在踏板上，并用带子（如果有）将其固定。", "以舒适的速度开始踩踏，保持背部挺直，核心参与。", "保持稳定的节奏，并根据需要增加阻力水平。", "继续踩踏您的有氧运动所需的持续时间。", "通过逐渐降低步速和阻力水平来冷静下来。", "锻炼后伸展腿部肌肉，以防止紧绷并促进恢复。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["調整固定自行車上的座椅高度和位置，以確保正確對齊。", "將腳放在踏板上，并用帶子（如果有）將其固定。", "以舒適的速度開始踩踏，保持背部挺直，核心參與。", "保持穩定的節奏，并根據需要增加阻力水平。", "繼續踩踏您的有氧運動所需的持續時間。", "通過逐漸降低步速和阻力水平來冷靜下來。", "鍛煉后伸展腿部肌肉，以防止緊繃并促進恢復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2141', 'exercise', 1, '{"id": "2141", "target": "cardiovascular system", "name_en": "walk elliptical cross trainer", "name_zh": "椭圆机行走", "body_part": "cardio", "equipment": "elliptical machine", "gif_asset": "assets/fitness/videos/2141-rjtuP6X.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "橢圓機行走", "instructions_en": ["Adjust the resistance level and incline of the elliptical machine to your desired settings.", "Step onto the pedals of the machine and grip the handles lightly.", "Begin by pushing down with your feet and pulling the handles towards your body.", "Continue this motion, alternating between pushing and pulling, to simulate a walking or running motion.", "Maintain a steady pace and keep your core engaged throughout the exercise.", "Continue for the desired duration of your cardio workout.", "Gradually decrease the intensity and speed of the machine before stepping off."], "instructions_zh": ["将椭圆机的阻力水平和倾斜度调整到您想要的设置。", "踩上机器的踏板并轻轻握住手柄。", "首先用脚向下压，然后将手柄拉向身体。", "继续这个动作，交替推和拉，以模拟行走或跑步动作。", "在整个练习过程中保持稳定的步伐并保持核心参与。", "继续进行有氧运动所需的持续时间。", "下车前逐渐降低机器的强度和速度。"], "secondary_muscles": ["quadriceps", "hamstrings", "glutes", "calves"], "instructions_zh_hant": ["將橢圓機的阻力水平和傾斜度調整到您想要的設置。", "踩上機器的踏板并輕輕握住手柄。", "首先用腳向下壓，然后將手柄拉向身體。", "繼續這個動作，交替推和拉，以模擬行走或跑步動作。", "在整個練習過程中保持穩定的步伐并保持核心參與。", "繼續進行有氧運動所需的持續時間。", "下車前逐漸降低機器的強度和速度。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('11111111-1111-4111-8111-000000000001', 'template', 1, '{"id": "11111111-1111-4111-8111-000000000001", "name": {"en": "Split · Chest & triceps", "zh": "三分化·胸三头", "zh_hant": "三分化·胸三頭"}, "goals": {"en": ["Hypertrophy", "Foundational strength"], "zh": ["增肌", "基础力量"], "zh_hant": ["增肌", "基礎力量"]}, "revision": 1, "equipment": ["barbell", "dumbbell", "cable", "body weight"], "exercises": [{"reps": 6, "sets": 4, "weight_kg": "30", "exercise_id": "0025", "weight_mode": "total", "rest_seconds": 60}, {"reps": 8, "sets": 4, "weight_kg": "8", "exercise_id": "0314", "weight_mode": "per_side", "rest_seconds": 60}, {"reps": 10, "sets": 3, "weight_kg": null, "exercise_id": "0251", "weight_mode": "body_weight", "rest_seconds": 60}, {"reps": 8, "sets": 4, "weight_kg": "10", "exercise_id": "0200", "weight_mode": "total", "rest_seconds": 60}], "difficulty": "beginner", "description": {"en": "Chest pressing and triceps work for the push day of a classic three-way split.", "zh": "胸部推举配合肱三头肌训练，适合作为常规三分化的推日。", "zh_hant": "胸部推舉配合肱三頭肌訓練，適合作為常規三分化的推日。"}, "duration_minutes": 45}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('11111111-1111-4111-8111-000000000002', 'template', 1, '{"id": "11111111-1111-4111-8111-000000000002", "name": {"en": "Split · Back & biceps", "zh": "三分化·背二头", "zh_hant": "三分化·背二頭"}, "goals": {"en": ["Hypertrophy", "Back strength"], "zh": ["增肌", "背部力量"], "zh_hant": ["增肌", "背部力量"]}, "revision": 1, "equipment": ["cable", "dumbbell", "body weight"], "exercises": [{"reps": 7, "sets": 4, "weight_kg": null, "exercise_id": "0652", "weight_mode": "body_weight", "rest_seconds": 60}, {"reps": 10, "sets": 5, "weight_kg": "30", "exercise_id": "0197", "weight_mode": "total", "rest_seconds": 60}, {"reps": 10, "sets": 4, "weight_kg": "30", "exercise_id": "2616", "weight_mode": "total", "rest_seconds": 60}, {"reps": 10, "sets": 4, "weight_kg": "30", "exercise_id": "0861", "weight_mode": "total", "rest_seconds": 60}, {"reps": 8, "sets": 3, "weight_kg": "6", "exercise_id": "0294", "weight_mode": "per_side", "rest_seconds": 60}, {"reps": 10, "sets": 3, "weight_kg": "6", "exercise_id": "0313", "weight_mode": "per_side", "rest_seconds": 60}], "difficulty": "beginner", "description": {"en": "Vertical and horizontal pulling combined with direct biceps work.", "zh": "垂直拉与水平拉结合肱二头肌训练，覆盖背部主要拉力模式。", "zh_hant": "垂直拉與水平拉結合肱二頭肌訓練，覆蓋背部主要拉力模式。"}, "duration_minutes": 55}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('11111111-1111-4111-8111-000000000003', 'template', 1, '{"id": "11111111-1111-4111-8111-000000000003", "name": {"en": "Split · Legs & shoulders", "zh": "三分化·腿肩", "zh_hant": "三分化·腿肩"}, "goals": {"en": ["Hypertrophy", "Lower-body strength"], "zh": ["增肌", "下肢力量"], "zh_hant": ["增肌", "下肢力量"]}, "revision": 1, "equipment": ["barbell", "dumbbell", "leverage machine"], "exercises": [{"reps": 6, "sets": 4, "weight_kg": "30", "exercise_id": "0043", "weight_mode": "total", "rest_seconds": 60}, {"reps": 12, "sets": 4, "weight_kg": "30", "exercise_id": "0585", "weight_mode": "total", "rest_seconds": 60}, {"reps": 10, "sets": 3, "weight_kg": "6", "exercise_id": "0336", "weight_mode": "per_side", "rest_seconds": 60}, {"reps": 8, "sets": 3, "weight_kg": "6", "exercise_id": "0405", "weight_mode": "per_side", "rest_seconds": 60}, {"reps": 12, "sets": 3, "weight_kg": "4", "exercise_id": "0334", "weight_mode": "per_side", "rest_seconds": 60}, {"reps": 15, "sets": 3, "weight_kg": "4", "exercise_id": "2292", "weight_mode": "per_side", "rest_seconds": 60}], "difficulty": "beginner", "description": {"en": "Lower-body compound work followed by shoulder pressing and raises.", "zh": "以下肢复合动作为主，搭配肩部推举和侧平举。", "zh_hant": "以下肢複合動作為主，搭配肩部推舉和側平舉。"}, "duration_minutes": 50}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('11111111-1111-4111-8111-000000000004', 'template', 1, '{"id": "11111111-1111-4111-8111-000000000004", "name": {"en": "Full body · Shoulders & back", "zh": "全身·肩背", "zh_hant": "全身·肩背"}, "goals": {"en": ["Full-body training", "Movement practice"], "zh": ["全身训练", "动作熟悉"], "zh_hant": ["全身訓練", "動作熟悉"]}, "revision": 1, "equipment": ["dumbbell", "cable"], "exercises": [{"reps": 8, "sets": 3, "weight_kg": "6", "exercise_id": "0405", "weight_mode": "per_side", "rest_seconds": 60}, {"reps": 12, "sets": 3, "weight_kg": "4", "exercise_id": "0334", "weight_mode": "per_side", "rest_seconds": 60}, {"reps": 12, "sets": 3, "weight_kg": "25", "exercise_id": "0861", "weight_mode": "total", "rest_seconds": 60}, {"reps": 12, "sets": 3, "weight_kg": "25", "exercise_id": "0197", "weight_mode": "total", "rest_seconds": 60}, {"reps": 10, "sets": 3, "weight_kg": "5", "exercise_id": "0294", "weight_mode": "per_side", "rest_seconds": 60}], "difficulty": "beginner", "description": {"en": "A full-body day emphasizing shoulders and back.", "zh": "以肩部和背部为重点的全身训练日。", "zh_hant": "以肩部和背部為重點的全身訓練日。"}, "duration_minutes": 40}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
