INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0032', 'exercise', 1, '{"id": "0032", "target": "glutes", "name_en": "barbell deadlift", "name_zh": "杠铃硬拉", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0032-ila4NZS.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴硬拉", "instructions_en": ["Stand with your feet shoulder-width apart and the barbell on the ground in front of you.", "Bend your knees and hinge at the hips to lower your torso and grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart.", "Keep your back straight and chest lifted as you drive through your heels to lift the barbell off the ground, extending your hips and knees.", "As you stand up straight, squeeze your glutes and keep your core engaged.", "Lower the barbell back down to the ground by bending at the hips and knees, keeping your back straight.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，杠铃放在你面前的地面上。", "弯曲膝盖并以臀部为铰链，降低躯干，正手握住杠铃，双手分开略宽于肩宽。", "当你通过脚后跟将杠铃抬离地面时，保持背部挺直，胸部抬起，伸展臀部和膝盖。", "当你站直时，挤压你的臀部并保持你的核心参与。", "弯曲臀部和膝盖，将杠铃放回地面，保持背部挺直。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "lower back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，杠鈴放在你面前的地面上。", "彎曲膝蓋并以臀部為鉸鏈，降低軀幹，正手握住杠鈴，雙手分開略寬于肩寬。", "當你通過腳后跟將杠鈴抬離地面時，保持背部挺直，胸部抬起，伸展臀部和膝蓋。", "當你站直時，擠壓你的臀部并保持你的核心參與。", "彎曲臀部和膝蓋，將杠鈴放回地面，保持背部挺直。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('11111111-1111-4111-8111-000000000013', 'template', 1, '{"id": "11111111-1111-4111-8111-000000000013", "name": {"en": "Five-day split · Shoulders", "zh": "五分化·肩", "zh_hant": "五分化·肩"}, "goals": {"en": ["Shoulder hypertrophy", "Scapular control"], "zh": ["肩部增肌", "肩胛控制"], "zh_hant": ["肩部增肌", "肩胛控制"]}, "revision": 1, "equipment": ["dumbbell", "cable"], "exercises": [{"reps": 8, "sets": 4, "weight_kg": "8", "exercise_id": "0405", "weight_mode": "per_side", "rest_seconds": 60}, {"reps": 12, "sets": 3, "weight_kg": "4", "exercise_id": "2292", "weight_mode": "per_side", "rest_seconds": 60}, {"reps": 15, "sets": 3, "weight_kg": "4", "exercise_id": "0334", "weight_mode": "per_side", "rest_seconds": 60}, {"reps": 15, "sets": 5, "weight_kg": "4", "exercise_id": "0380", "weight_mode": "per_side", "rest_seconds": 60}, {"reps": 15, "sets": 4, "weight_kg": "12.5", "exercise_id": "0233", "weight_mode": "total", "rest_seconds": 60}], "difficulty": "intermediate", "description": {"en": "Shoulder pressing, raises, rear-delt flyes, and face pulls.", "zh": "肩部推举、侧平举、后束飞鸟和面拉组成的肩部训练日。", "zh_hant": "肩部推舉、側平舉、後束飛鳥和面拉組成的肩部訓練日。"}, "duration_minutes": 50}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('22222222-2222-4222-8222-000000000001', 'plan', 1, '{"id": "22222222-2222-4222-8222-000000000001", "days": [{"day_index": 0, "template_id": "11111111-1111-4111-8111-000000000001"}, {"day_index": 1, "template_id": "11111111-1111-4111-8111-000000000002"}, {"day_index": 2, "template_id": "11111111-1111-4111-8111-000000000003"}, {"day_index": 3, "template_id": null}], "name": {"en": "Classic three-way split", "zh": "常规三分化训练", "zh_hant": "常規三分化訓練"}, "goals": {"en": ["Full-body hypertrophy", "Foundational strength"], "zh": ["全身增肌", "基础力量"], "zh_hant": ["全身增肌", "基礎力量"]}, "revision": 1, "cycle_days": 4, "difficulty": "beginner", "description": {"en": "Train chest and triceps, back and biceps, then legs and shoulders before one rest day. Start conservatively and adjust from performance.", "zh": "连续完成胸三头、背二头和腿肩训练后休息一天。建议先用保守重量熟悉动作，再按完成质量调整。", "zh_hant": "連續完成胸三頭、背二頭和腿肩訓練後休息一天。建議先用保守重量熟悉動作，再按完成質量調整。"}}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('22222222-2222-4222-8222-000000000002', 'plan', 1, '{"id": "22222222-2222-4222-8222-000000000002", "days": [{"day_index": 0, "template_id": "11111111-1111-4111-8111-000000000004"}, {"day_index": 1, "template_id": "11111111-1111-4111-8111-000000000005"}, {"day_index": 2, "template_id": "11111111-1111-4111-8111-000000000006"}, {"day_index": 3, "template_id": "11111111-1111-4111-8111-000000000007"}, {"day_index": 4, "template_id": "11111111-1111-4111-8111-000000000008"}, {"day_index": 5, "template_id": null}, {"day_index": 6, "template_id": null}], "name": {"en": "Full-body seven-day plan", "zh": "全身不分化", "zh_hant": "全身不分化"}, "goals": {"en": ["Full-body hypertrophy", "Work capacity"], "zh": ["全身增肌", "训练容量"], "zh_hant": ["全身增肌", "訓練容量"]}, "revision": 1, "cycle_days": 7, "difficulty": "intermediate", "description": {"en": "Five full-body days with rotating emphasis followed by two rest days. Reduce load or volume when recovery is insufficient.", "zh": "一周五个全身训练日，侧重点依次变化，最后两天休息。训练频率较高，应根据恢复情况主动降重或减少组数。", "zh_hant": "一週五個全身訓練日，側重點依次變化，最後兩天休息。訓練頻率較高，應根據恢復情況主動降重或減少組數。"}}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('22222222-2222-4222-8222-000000000003', 'plan', 1, '{"id": "22222222-2222-4222-8222-000000000003", "days": [{"day_index": 0, "template_id": "11111111-1111-4111-8111-000000000009"}, {"day_index": 1, "template_id": "11111111-1111-4111-8111-000000000010"}, {"day_index": 2, "template_id": "11111111-1111-4111-8111-000000000011"}, {"day_index": 3, "template_id": "11111111-1111-4111-8111-000000000012"}, {"day_index": 4, "template_id": "11111111-1111-4111-8111-000000000013"}, {"day_index": 5, "template_id": null}, {"day_index": 6, "template_id": null}], "name": {"en": "Five-day body-part split", "zh": "五分化训练计划", "zh_hant": "五分化訓練計劃"}, "goals": {"en": ["Body-part hypertrophy", "Targeted volume"], "zh": ["部位增肌", "专项容量"], "zh_hant": ["部位增肌", "專項容量"]}, "revision": 1, "cycle_days": 7, "difficulty": "intermediate", "description": {"en": "One day each for chest, back, legs, arms and abs, and shoulders, followed by two rest days. Intended for experienced trainees.", "zh": "胸、背、腿、手臂腹肌和肩部各安排一天，最后两天休息。适合已有稳定动作基础的训练者。", "zh_hant": "胸、背、腿、手臂腹肌和肩部各安排一天，最後兩天休息。適合已有穩定動作基礎的訓練者。"}}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0025', 'exercise', 1, '{"id": "0025", "target": "pectorals", "name_en": "barbell bench press", "name_zh": "杠铃卧推", "body_part": "chest", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0025-EIeI8Vf.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴臥推", "instructions_en": ["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.", "Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.", "Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.", "Lower the barbell slowly towards your chest, keeping your elbows tucked in.", "Pause for a moment when the barbell touches your chest.", "Push the barbell back up to the starting position by extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，双脚平放在地上，背部紧贴长凳。", "正手握住杠铃，握距略宽于肩宽。", "将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。", "将杠铃慢慢降低到胸部，保持肘部内收。", "当杠铃触及胸部时暂停片刻。", "伸展双臂，将杠铃推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["平躺在長凳上，雙腳平放在地上，背部緊貼長凳。", "正手握住杠鈴，握距略寬于肩寬。", "將杠鈴從架子上提起，并將其直接放在胸部上方，雙臂完全伸展。", "將杠鈴慢慢降低到胸部，保持肘部內收。", "當杠鈴觸及胸部時暫停片刻。", "伸展雙臂，將杠鈴推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0047', 'exercise', 1, '{"id": "0047", "target": "pectorals", "name_en": "barbell incline bench press", "name_zh": "杠铃上斜卧推", "body_part": "chest", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0047-3TZduzM.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴上斜臥推", "instructions_en": ["Set up an incline bench at a 45-degree angle.", "Lie down on the bench with your feet flat on the ground.", "Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.", "Unrack the barbell and lower it slowly towards your chest, keeping your elbows at a 45-degree angle.", "Pause for a moment at the bottom, then push the barbell back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["设置一个 45 度角的上斜凳。", "躺在长凳上，双脚平放在地上。", "正手握住杠铃，握距略宽于肩宽。", "松开杠铃并将其缓慢降低至胸部，保持肘部呈 45 度角。", "在底部停顿片刻，然后将杠铃推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["設置一個 45 度角的上斜凳。", "躺在長凳上，雙腳平放在地上。", "正手握住杠鈴，握距略寬于肩寬。", "松開杠鈴并將其緩慢降低至胸部，保持肘部呈 45 度角。", "在底部停頓片刻，然后將杠鈴推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0289', 'exercise', 1, '{"id": "0289", "target": "pectorals", "name_en": "dumbbell bench press", "name_zh": "哑铃卧推", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0289-SpYC0Kp.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴臥推", "instructions_en": ["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.", "Hold a dumbbell in each hand, with your palms facing forward and your arms extended above your chest.", "Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.", "Pause for a moment, then push the dumbbells back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，双脚平放在地上，背部紧贴长凳。", "双手各握一个哑铃，手掌朝前，双臂伸至胸部上方。", "慢慢地将哑铃降低到胸部两侧，保持肘部呈 90 度角。", "暂停片刻，然后将哑铃推回起始位置，完全伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["平躺在長凳上，雙腳平放在地上，背部緊貼長凳。", "雙手各握一個啞鈴，手掌朝前，雙臂伸至胸部上方。", "慢慢地將啞鈴降低到胸部兩側，保持肘部呈 90 度角。", "暫停片刻，然后將啞鈴推回起始位置，完全伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0314', 'exercise', 1, '{"id": "0314", "target": "pectorals", "name_en": "dumbbell incline bench press", "name_zh": "哑铃上斜卧推", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0314-ns0SIbU.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴上斜臥推", "instructions_en": ["Set up an incline bench at a 45-degree angle.", "Sit on the bench with your feet flat on the ground and your back pressed firmly against the bench.", "Hold a dumbbell in each hand, palms facing forward, and lift them to shoulder height.", "Slowly lower the dumbbells to the sides of your chest, keeping your elbows at a 90-degree angle.", "Push the dumbbells back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["设置一个 45 度角的上斜凳。", "坐在长凳上，双脚平放在地上，背部紧贴长凳。", "双手各握一个哑铃，掌心向前，将哑铃举至肩高。", "慢慢地将哑铃降低到胸部两侧，保持肘部呈 90 度角。", "将哑铃推回起始位置，充分伸展手臂。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["設置一個 45 度角的上斜凳。", "坐在長凳上，雙腳平放在地上，背部緊貼長凳。", "雙手各握一個啞鈴，掌心向前，將啞鈴舉至肩高。", "慢慢地將啞鈴降低到胸部兩側，保持肘部呈 90 度角。", "將啞鈴推回起始位置，充分伸展手臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0577', 'exercise', 1, '{"id": "0577", "target": "pectorals", "name_en": "lever chest press", "name_zh": "器械推胸", "body_part": "chest", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0577-T0yTjgW.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械推胸", "instructions_en": ["Adjust the seat height and position yourself on the machine with your back flat against the pad.", "Grasp the handles with an overhand grip and position your elbows at a 90-degree angle.", "Push the handles forward until your arms are fully extended, exhaling during the movement.", "Pause briefly at the end of the movement, then slowly return to the starting position, inhaling as you do so.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度，将自己放在机器上，背部平放在垫子上。", "正手握住手柄，肘部呈 90 度角。", "向前推动手柄，直到手臂完全伸展，运动过程中呼气。", "动作结束时短暂暂停，然后慢慢回到起始位置，同时吸气。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["調整座椅高度，將自己放在機器上，背部平放在墊子上。", "正手握住手柄，肘部呈 90 度角。", "向前推動手柄，直到手臂完全伸展，運動過程中呼氣。", "動作結束時短暫暫停，然后慢慢回到起始位置，同時吸氣。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0338', 'exercise', 1, '{"id": "0338", "target": "triceps", "name_en": "dumbbell lying elbow press", "name_zh": "哑铃卧姿肘部推举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0338-eOCOwIR.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴臥姿肘部推舉", "instructions_en": ["Lie flat on a bench with a dumbbell in each hand, palms facing each other and arms extended straight up over your chest.", "Lower the dumbbells towards your shoulders by bending your elbows, keeping your upper arms stationary.", "Pause for a moment at the bottom, then press the dumbbells back up to the starting position by extending your elbows.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，双手各握一个哑铃，手掌相对，双臂伸直越过胸部。", "弯曲肘部，将哑铃向肩膀方向降低，保持上臂静止。", "在底部暂停片刻，然后伸展肘部将哑铃推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["平躺在長凳上，雙手各握一個啞鈴，手掌相對，雙臂伸直越過胸部。", "彎曲肘部，將啞鈴向肩膀方向降低，保持上臂靜止。", "在底部暫停片刻，然后伸展肘部將啞鈴推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0662', 'exercise', 1, '{"id": "0662", "target": "pectorals", "name_en": "push-up", "name_zh": "俯卧撑", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0662-I4hDWkc.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "俯臥撐", "instructions_en": ["Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.", "Engage your core and lower your body towards the ground by bending your elbows, keeping your body in a straight line.", "Pause for a moment when your chest is just above the ground, then push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["从高位平板支撑开始，双手分开略宽于肩宽，双脚并拢。", "弯曲肘部，调动核心力量，将身体压向地面，保持身体呈一条直线。", "当你的胸部刚好高于地面时，暂停片刻，然后伸直手臂，将自己推回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "deltoids", "core"], "instructions_zh_hant": ["從高位平板支撐開始，雙手分開略寬于肩寬，雙腳并攏。", "彎曲肘部，調動核心力量，將身體壓向地面，保持身體呈一條直線。", "當你的胸部剛好高于地面時，暫停片刻，然后伸直手臂，將自己推回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0652', 'exercise', 1, '{"id": "0652", "target": "lats", "name_en": "pull-up", "name_zh": "引体向上", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0652-lBDjFxJ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "引體向上", "instructions_en": ["Hang from a pull-up bar with your palms facing away from you and your arms fully extended.", "Engage your core and squeeze your shoulder blades together.", "Pull your body up towards the bar by bending your elbows and bringing your chest towards the bar.", "Pause at the top of the movement, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["悬挂在引体向上杆上，手掌背向自己，手臂完全伸展。", "启动你的核心并将肩胛骨挤压在一起。", "弯曲肘部并将胸部拉向杠铃杆，将身体向上拉向杠铃杆。", "在动作的最高点暂停，然后慢慢降低身体回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["懸掛在引體向上桿上，手掌背向自己，手臂完全伸展。", "啟動你的核心并將肩胛骨擠壓在一起。", "彎曲肘部并將胸部拉向杠鈴桿，將身體向上拉向杠鈴桿。", "在動作的最高點暫停，然后慢慢降低身體回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0017', 'exercise', 1, '{"id": "0017", "target": "lats", "name_en": "assisted pull-up", "name_zh": "辅助引体向上", "body_part": "back", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0017-kiJ4Z2K.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "輔助引體向上", "instructions_en": ["Adjust the machine to your desired weight and height settings.", "Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.", "Hang with your arms fully extended and your feet off the ground.", "Engage your back muscles and pull your body up towards the handles, keeping your elbows close to your body.", "Continue pulling until your chin is above the handles.", "Pause for a moment at the top, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将机器调整至您所需的体重和高度设置。", "正手握住手柄，握距略宽于肩宽。", "双臂完全伸展，双脚离开地面。", "收紧背部肌肉，将身体拉向手柄，保持肘部靠近身体。", "继续拉，直到下巴位于手柄上方。", "在顶部停顿片刻，然后慢慢将身体放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["將機器調整至您所需的體重和高度設置。", "正手握住手柄，握距略寬于肩寬。", "雙臂完全伸展，雙腳離開地面。", "收緊背部肌肉，將身體拉向手柄，保持肘部靠近身體。", "繼續拉，直到下巴位于手柄上方。", "在頂部停頓片刻，然后慢慢將身體放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0027', 'exercise', 1, '{"id": "0027", "target": "upper back", "name_en": "barbell bent over row", "name_zh": "杠铃俯身划船", "body_part": "back", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0027-eZyBC3j.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴俯身劃船", "instructions_en": ["Stand with your feet shoulder-width apart and knees slightly bent.", "Bend forward at the hips while keeping your back straight and chest up.", "Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.", "Pull the barbell towards your lower chest by retracting your shoulder blades and squeezing your back muscles.", "Pause for a moment at the top, then slowly lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站立，双脚分开与肩同宽，膝盖稍微弯曲。", "臀部向前弯曲，同时保持背部挺直、挺胸。", "正手握住杠铃，双手间距略宽于肩宽。", "通过收缩肩胛骨并挤压背部肌肉，将杠铃拉向下胸部。", "在顶部停顿片刻，然后慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["站立，雙腳分開與肩同寬，膝蓋稍微彎曲。", "臀部向前彎曲，同時保持背部挺直、挺胸。", "正手握住杠鈴，雙手間距略寬于肩寬。", "通過收縮肩胛骨并擠壓背部肌肉，將杠鈴拉向下胸部。", "在頂部停頓片刻，然后慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0292', 'exercise', 1, '{"id": "0292", "target": "upper back", "name_en": "dumbbell one arm bent-over row", "name_zh": "哑铃单臂划船", "body_part": "back", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0292-C0MA9bC.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴單臂劃船", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing your body.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.", "Let the dumbbell hang straight down towards the floor, with your arm fully extended.", "Pull the dumbbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["双脚分开与肩同宽站立，一手握住哑铃，手掌朝向身体。", "稍微弯曲膝盖，髋部向前转动，保持背部挺直，核心肌群参与。", "让哑铃垂直垂向地板，手臂完全伸展。", "将哑铃向上拉向胸部，保持肘部靠近身体并将肩胛骨挤压在一起。", "在顶部停顿片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，一手握住啞鈴，手掌朝向身體。", "稍微彎曲膝蓋，髖部向前轉動，保持背部挺直，核心肌群參與。", "讓啞鈴垂直垂向地板，手臂完全伸展。", "將啞鈴向上拉向胸部，保持肘部靠近身體并將肩胛骨擠壓在一起。", "在頂部停頓片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0861', 'exercise', 1, '{"id": "0861", "target": "upper back", "name_en": "cable seated row", "name_zh": "坐姿绳索划船", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/0861-fUBheHs.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "坐姿繩索劃船", "instructions_en": ["Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.", "Grasp the handles with an overhand grip, keeping your back straight and your shoulders relaxed.", "Pull the handles towards your body, squeezing your shoulder blades together.", "Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在电缆划船机上，双脚平放在脚踏板上，膝盖稍微弯曲。", "正手握住手柄，保持背部挺直，肩膀放松。", "将手柄拉向身体，将肩胛骨挤压在一起。", "在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["坐在電纜劃船機上，雙腳平放在腳踏板上，膝蓋稍微彎曲。", "正手握住手柄，保持背部挺直，肩膀放松。", "將手柄拉向身體，將肩胛骨擠壓在一起。", "在動作的最高點暫停片刻，然后慢慢松開手柄回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0198', 'exercise', 1, '{"id": "0198", "target": "lats", "name_en": "cable pulldown", "name_zh": "高位下拉", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/0198-RVwzP10.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "高位下拉", "instructions_en": ["Adjust the cable pulldown machine so that the seat is at a comfortable height and the knee pad is secured.", "Sit on the seat with your back straight and your feet flat on the ground.", "Grasp the cable bar with an overhand grip, slightly wider than shoulder-width apart.", "Lean back slightly and engage your core.", "Pull the cable bar down towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the bottom of the movement, then slowly release the bar back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整拉索下拉机，使座椅处于舒适的高度并固定护膝。", "坐在座位上，背部挺直，双脚平放在地面上。", "正手握住电缆杆，握距略宽于肩宽。", "稍微向后倾斜并启动你的核心。", "将电缆杆向下拉向胸部，将肩胛骨挤压在一起。", "在动作底部暂停片刻，然后慢慢松开杠铃回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["調整拉索下拉機，使座椅處于舒適的高度并固定護膝。", "坐在座位上，背部挺直，雙腳平放在地面上。", "正手握住電纜桿，握距略寬于肩寬。", "稍微向后傾斜并啟動你的核心。", "將電纜桿向下拉向胸部，將肩胛骨擠壓在一起。", "在動作底部暫停片刻，然后慢慢松開杠鈴回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0213', 'exercise', 1, '{"id": "0213", "target": "lats", "name_en": "cable seated high row (v-bar)", "name_zh": "窄握高位划船", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/0213-pwt0pnM.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "窄握高位劃船", "instructions_en": ["Sit on the cable machine with your feet flat on the floor and your knees slightly bent.", "Grasp the v-bar attachment with an overhand grip, palms facing each other, and your hands shoulder-width apart.", "Keep your back straight and lean slightly forward from the hips.", "Pull the v-bar towards your torso by retracting your shoulder blades and squeezing your back muscles.", "Pause for a moment at the peak of the contraction, then slowly release the tension and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在缆绳机上，双脚平放在地板上，膝盖稍微弯曲。", "正手握住 V 形杆附件，手掌相对，双手与肩同宽。", "保持背部挺直，并从臀部稍微向前倾斜。", "通过收缩肩胛骨并挤压背部肌肉，将 V 形杆拉向躯干。", "在收缩的顶峰停顿片刻，然后慢慢释放张力，回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "rhomboids", "rear deltoids"], "instructions_zh_hant": ["坐在纜繩機上，雙腳平放在地板上，膝蓋稍微彎曲。", "正手握住 V 形桿附件，手掌相對，雙手與肩同寬。", "保持背部挺直，并從臀部稍微向前傾斜。", "通過收縮肩胛骨并擠壓背部肌肉，將 V 形桿拉向軀幹。", "在收縮的頂峰停頓片刻，然后慢慢釋放張力，回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0091', 'exercise', 1, '{"id": "0091", "target": "delts", "name_en": "barbell seated overhead press", "name_zh": "杠铃坐姿推举", "body_part": "shoulders", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0091-kTbSH9h.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴坐姿推舉", "instructions_en": ["Sit on a bench with your back straight and feet flat on the ground.", "Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.", "Lift the barbell off the rack and bring it to shoulder level, with your elbows bent and palms facing forward.", "Press the barbell overhead by extending your arms fully.", "Pause for a moment at the top, then slowly lower the barbell back to shoulder level.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，背部挺直，双脚平放在地上。", "正手握住杠铃，杠铃间距略宽于肩宽。", "将杠铃从架子上提起，并将其置于与肩同高的位置，肘部弯曲，手掌朝前。", "充分伸展双臂，将杠铃压过头顶。", "在顶部停顿片刻，然后慢慢将杠铃放回肩部水平。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "upper back"], "instructions_zh_hant": ["坐在長凳上，背部挺直，雙腳平放在地上。", "正手握住杠鈴，杠鈴間距略寬于肩寬。", "將杠鈴從架子上提起，并將其置于與肩同高的位置，肘部彎曲，手掌朝前。", "充分伸展雙臂，將杠鈴壓過頭頂。", "在頂部停頓片刻，然后慢慢將杠鈴放回肩部水平。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0405', 'exercise', 1, '{"id": "0405", "target": "delts", "name_en": "dumbbell seated shoulder press", "name_zh": "哑铃坐姿推举", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0405-znQUdHY.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴坐姿推舉", "instructions_en": ["Sit on a bench with a dumbbell in each hand, resting on your thighs.", "Raise the dumbbells to shoulder height, palms facing forward.", "Press the dumbbells upward until your arms are fully extended overhead.", "Pause for a moment at the top, then slowly lower the dumbbells back to shoulder height.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，每只手各拿一个哑铃，放在大腿上。", "将哑铃举至肩高，手掌朝前。", "向上推哑铃，直到手臂完全伸过头顶。", "在顶部停顿片刻，然后慢慢将哑铃放回肩部高度。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "upper back"], "instructions_zh_hant": ["坐在長凳上，每只手各拿一個啞鈴，放在大腿上。", "將啞鈴舉至肩高，手掌朝前。", "向上推啞鈴，直到手臂完全伸過頭頂。", "在頂部停頓片刻，然后慢慢將啞鈴放回肩部高度。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0334', 'exercise', 1, '{"id": "0334", "target": "delts", "name_en": "dumbbell lateral raise", "name_zh": "哑铃侧平举", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0334-DsgkuIt.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴側平舉", "instructions_en": ["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.", "Keep your back straight and engage your core.", "Raise your arms out to the sides until they are parallel to the floor, keeping a slight bend in your elbows.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。", "保持背部挺直并启动核心肌群。", "将手臂向两侧抬起，直到与地板平行，保持肘部稍微弯曲。", "在顶部暂停片刻，然后慢慢将手臂放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["traps"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴，手掌朝向身體。", "保持背部挺直并啟動核心肌群。", "將手臂向兩側抬起，直到與地板平行，保持肘部稍微彎曲。", "在頂部暫停片刻，然后慢慢將手臂放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1708', 'exercise', 1, '{"id": "1708", "target": "calves", "name_en": "assisted lying calves stretch", "name_zh": "辅助卧姿小腿拉伸", "body_part": "lower legs", "equipment": "assisted", "gif_asset": "assets/fitness/videos/1708-GxDwDX0.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "輔助臥姿小腿拉伸", "instructions_en": ["Lie on your back with your legs extended.", "Bend one knee and place your foot flat on the ground.", "Using your hands or a towel, gently pull your toes towards your body, feeling a stretch in your calf.", "Hold the stretch for 20-30 seconds.", "Release the stretch and repeat on the other leg."], "instructions_zh": ["仰卧，双腿伸展。", "弯曲一侧膝盖，将脚平放在地上。", "用手或毛巾轻轻地将脚趾拉向身体，感受小腿的拉伸。", "保持拉伸 20-30 秒。", "松开拉伸并在另一条腿上重复。"], "secondary_muscles": ["hamstrings"], "instructions_zh_hant": ["仰臥，雙腿伸展。", "彎曲一側膝蓋，將腳平放在地上。", "用手或毛巾輕輕地將腳趾拉向身體，感受小腿的拉伸。", "保持拉伸 20-30 秒。", "松開拉伸并在另一條腿上重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0215', 'exercise', 1, '{"id": "0215", "target": "delts", "name_en": "cable seated rear lateral raise", "name_zh": "坐姿绳索反向飞鸟", "body_part": "shoulders", "equipment": "cable", "gif_asset": "assets/fitness/videos/0215-x825CZm.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "坐姿繩索反向飛鳥", "instructions_en": ["Sit on a bench facing the cable machine with your feet flat on the ground.", "Grasp the cable handles with an overhand grip and extend your arms straight in front of you.", "Keeping your arms straight, slowly raise them out to the sides until they are parallel to the floor.", "Pause for a moment at the top, then slowly lower your arms back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，面向电缆机，双脚平放在地面上。", "正手握住电缆手柄，并将双臂伸直至前方。", "保持手臂伸直，慢慢向两侧举起，直到与地板平行。", "在顶部停顿片刻，然后慢慢将手臂放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["traps", "rhomboids"], "instructions_zh_hant": ["坐在長凳上，面向電纜機，雙腳平放在地面上。", "正手握住電纜手柄，并將雙臂伸直至前方。", "保持手臂伸直，慢慢向兩側舉起，直到與地板平行。", "在頂部停頓片刻，然后慢慢將手臂放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0031', 'exercise', 1, '{"id": "0031", "target": "biceps", "name_en": "barbell curl", "name_zh": "杠铃弯举", "body_part": "upper arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0031-25GPyDY.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴彎舉", "instructions_en": ["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing forward.", "Keep your elbows close to your torso and exhale as you curl the weights while contracting your biceps.", "Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale as you slowly begin to lower the bar back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站直，双脚分开与肩同宽，反手握住杠铃，手掌朝前。", "保持肘部靠近躯干，在弯举哑铃时呼气，同时收缩二头肌。", "继续抬高杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气，慢慢开始将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙腳分開與肩同寬，反手握住杠鈴，手掌朝前。", "保持肘部靠近軀幹，在彎舉啞鈴時呼氣，同時收縮二頭肌。", "繼續抬高杠鈴，直到二頭肌完全收縮并且杠鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣，慢慢開始將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0294', 'exercise', 1, '{"id": "0294", "target": "biceps", "name_en": "dumbbell biceps curl", "name_zh": "哑铃弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0294-NbVPDMW.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴彎舉", "instructions_en": ["Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站直，双手各握一个哑铃，手掌朝前，双臂完全伸展。", "保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。", "继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙手各握一個啞鈴，手掌朝前，雙臂完全伸展。", "保持上臂靜止，呼氣并彎舉啞鈴，同時收縮二頭肌。", "繼續舉重，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0313', 'exercise', 1, '{"id": "0313", "target": "biceps", "name_en": "dumbbell hammer curl", "name_zh": "哑铃锤式弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0313-slDvUAU.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴錘式彎舉", "instructions_en": ["Stand up straight with a dumbbell in each hand, palms facing your torso.", "Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.", "This will be your starting position.", "Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Then, inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the recommended amount of repetitions."], "instructions_zh": ["站直，双手各持一个哑铃，手掌朝向躯干。", "保持肘部靠近躯干，并旋转手掌，直到手掌朝前。", "这将是您的起始位置。", "现在，保持上臂静止，呼气并卷曲哑铃，同时收缩二头肌。", "继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "然后，吸气并慢慢开始将哑铃放回起始位置。", "重复建议的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙手各持一個啞鈴，手掌朝向軀幹。", "保持肘部靠近軀幹，并旋轉手掌，直到手掌朝前。", "這將是您的起始位置。", "現在，保持上臂靜止，呼氣并卷曲啞鈴，同時收縮二頭肌。", "繼續舉重，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "然后，吸氣并慢慢開始將啞鈴放回起始位置。", "重復建議的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1709', 'exercise', 1, '{"id": "1709", "target": "glutes", "name_en": "assisted lying glutes stretch", "name_zh": "辅助卧姿臀肌拉伸", "body_part": "upper legs", "equipment": "assisted", "gif_asset": "assets/fitness/videos/1709-yn0LjwL.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "輔助臥姿臀肌拉伸", "instructions_en": ["Lie on your back with your legs extended.", "Bend your right knee and place your right ankle on your left thigh, just above the knee.", "Grasp your left thigh with both hands and gently pull it towards your chest.", "Hold the stretch for 20-30 seconds.", "Release and repeat on the other side."], "instructions_zh": ["仰卧，双腿伸展。", "弯曲右膝盖，将右脚踝放在左大腿上，就在膝盖上方。", "用双手抓住左大腿，轻轻地将其拉向胸部。", "保持拉伸 20-30 秒。", "松开并在另一侧重复。"], "secondary_muscles": ["hamstrings"], "instructions_zh_hant": ["仰臥，雙腿伸展。", "彎曲右膝蓋，將右腳踝放在左大腿上，就在膝蓋上方。", "用雙手抓住左大腿，輕輕地將其拉向胸部。", "保持拉伸 20-30 秒。", "松開并在另一側重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0201', 'exercise', 1, '{"id": "0201", "target": "triceps", "name_en": "cable pushdown", "name_zh": "绳索下压", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/0201-3ZflifB.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索下壓", "instructions_en": ["Attach a straight bar to a high pulley cable machine.", "Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.", "Grasp the bar with an overhand grip, hands shoulder-width apart.", "Keep your elbows close to your sides and your upper arms stationary.", "Exhale and push the bar down until your elbows are fully extended.", "Pause for a moment, then inhale and slowly return the bar to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将直杆连接到高滑轮电缆机上。", "面向机器站立，双脚分开与肩同宽，膝盖稍微弯曲。", "正手握住杠铃，双手与肩同宽。", "保持肘部靠近身体两侧，上臂保持静止。", "呼气并将杠铃向下推，直到肘部完全伸展。", "暂停片刻，然后吸气，慢慢地将杠铃返回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["將直桿連接到高滑輪電纜機上。", "面向機器站立，雙腳分開與肩同寬，膝蓋稍微彎曲。", "正手握住杠鈴，雙手與肩同寬。", "保持肘部靠近身體兩側，上臂保持靜止。", "呼氣并將杠鈴向下推，直到肘部完全伸展。", "暫停片刻，然后吸氣，慢慢地將杠鈴返回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0200', 'exercise', 1, '{"id": "0200", "target": "triceps", "name_en": "cable pushdown (with rope attachment)", "name_zh": "绳索绳头下压", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/0200-dU605di.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索繩頭下壓", "instructions_en": ["Attach a rope attachment to a high pulley on a cable machine.", "Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.", "Grasp the rope with an overhand grip, palms facing each other.", "Keep your elbows close to your sides and your upper arms stationary throughout the exercise.", "Exhale and push the rope downward by extending your elbows until your arms are fully extended.", "Pause for a moment, then inhale and slowly return to the starting position by allowing your elbows to flex.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将绳索附件连接到缆绳机上的高滑轮上。", "面向机器站立，双脚分开与肩同宽，膝盖稍微弯曲。", "正手握住绳子，手掌相对。", "在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。", "呼气并伸展肘部将绳子向下推，直到手臂完全伸展。", "暂停片刻，然后吸气，并让肘部弯曲，慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["將繩索附件連接到纜繩機上的高滑輪上。", "面向機器站立，雙腳分開與肩同寬，膝蓋稍微彎曲。", "正手握住繩子，手掌相對。", "在整個練習過程中，保持肘部靠近身體兩側，上臂保持靜止。", "呼氣并伸展肘部將繩子向下推，直到手臂完全伸展。", "暫停片刻，然后吸氣，并讓肘部彎曲，慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0019', 'exercise', 1, '{"id": "0019", "target": "triceps", "name_en": "assisted triceps dip (kneeling)", "name_zh": "辅助双杠臂屈伸", "body_part": "upper arms", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0019-J60bN17.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "輔助雙槓臂屈伸", "instructions_en": ["Adjust the machine to your desired weight and height.", "Kneel down on the pad facing the machine, with your hands gripping the handles.", "Lower your body by bending your elbows, keeping your back straight and close to the machine.", "Pause for a moment at the bottom, then push yourself back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将机器调整到您想要的重量和高度。", "跪在面向机器的垫子上，双手握住手柄。", "弯曲肘部降低身体，保持背部挺直并靠近机器。", "在底部暂停片刻，然后将自己推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["將機器調整到您想要的重量和高度。", "跪在面向機器的墊子上，雙手握住手柄。", "彎曲肘部降低身體，保持背部挺直并靠近機器。", "在底部暫停片刻，然后將自己推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0043', 'exercise', 1, '{"id": "0043", "target": "glutes", "name_en": "barbell full squat", "name_zh": "杠铃深蹲", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0043-qXTaZnJ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴深蹲", "instructions_en": ["Stand with your feet shoulder-width apart, toes slightly turned out.", "Hold the barbell across your upper back, resting it on your traps or rear delts.", "Engage your core and keep your chest up as you begin to lower your body down.", "Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.", "Lower yourself until your thighs are parallel to the ground or slightly below.", "Keep your knees in line with your toes and your weight in your heels.", "Drive through your heels to stand back up, extending your hips and knees.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站立，双脚分开与肩同宽，脚趾稍微向外。", "将杠铃放在上背部，将其放在斜方肌或三角肌后束上。", "当你开始降低身体时，启动你的核心并保持胸部挺直。", "弯曲膝盖和臀部，向后和向下推臀部，就像坐在椅子上一样。", "放低身体，直到大腿与地面平行或稍低于地面。", "保持膝盖与脚趾对齐，并将重量放在脚后跟上。", "通过脚后跟站起来，伸展臀部和膝盖。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves", "core"], "instructions_zh_hant": ["站立，雙腳分開與肩同寬，腳趾稍微向外。", "將杠鈴放在上背部，將其放在斜方肌或三角肌后束上。", "當你開始降低身體時，啟動你的核心并保持胸部挺直。", "彎曲膝蓋和臀部，向后和向下推臀部，就像坐在椅子上一樣。", "放低身體，直到大腿與地面平行或稍低于地面。", "保持膝蓋與腳趾對齊，并將重量放在腳后跟上。", "通過腳后跟站起來，伸展臀部和膝蓋。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0054', 'exercise', 1, '{"id": "0054", "target": "glutes", "name_en": "barbell lunge", "name_zh": "杠铃弓步蹲", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0054-t8iSghb.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴弓步蹲", "instructions_en": ["Start by standing with your feet shoulder-width apart and a barbell resting on your upper back.", "Take a step forward with your right foot, keeping your torso upright.", "Lower your body by bending your right knee until your thigh is parallel to the ground.", "Push through your right heel to return to the starting position.", "Repeat with your left leg, alternating legs for the desired number of repetitions."], "instructions_zh": ["首先，双脚分开与肩同宽，将杠铃放在上背部。", "右脚向前迈出一步，保持躯干直立。", "弯曲右膝降低身体，直到大腿与地面平行。", "推动右脚跟回到起始位置。", "用左腿重复上述动作，交替腿进行所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["首先，雙腳分開與肩同寬，將杠鈴放在上背部。", "右腳向前邁出一步，保持軀幹直立。", "彎曲右膝降低身體，直到大腿與地面平行。", "推動右腳跟回到起始位置。", "用左腿重復上述動作，交替腿進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0336', 'exercise', 1, '{"id": "0336", "target": "glutes", "name_en": "dumbbell lunge", "name_zh": "哑铃弓步蹲", "body_part": "upper legs", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0336-RRWFUcw.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴弓步蹲", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.", "Take a step forward with your right foot, lowering your body into a lunge position.", "Keep your back straight and your chest up as you lower your body.", "Push through your right heel to return to the starting position.", "Repeat with your left leg.", "Alternate legs for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，每只手各握一个哑铃。", "右脚向前迈出一步，将身体降低至弓步位置。", "降低身体时保持背部挺直、挺胸。", "推动右脚跟回到起始位置。", "左腿重复上述动作。", "交替腿进行所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，每只手各握一個啞鈴。", "右腳向前邁出一步，將身體降低至弓步位置。", "降低身體時保持背部挺直、挺胸。", "推動右腳跟回到起始位置。", "左腿重復上述動作。", "交替腿進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0739', 'exercise', 1, '{"id": "0739", "target": "glutes", "name_en": "sled 45в° leg press", "name_zh": "45度腿举", "body_part": "upper legs", "equipment": "sled machine", "gif_asset": "assets/fitness/videos/0739-10Z2DXU.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "45度腿舉", "instructions_en": ["Adjust the seat and footplate of the sled machine to a comfortable position.", "Sit on the sled machine with your back against the backrest and your feet shoulder-width apart on the footplate.", "Grip the handles on the sides of the seat for stability.", "Push the footplate away from your body by extending your legs, keeping your heels on the footplate.", "Continue pushing until your legs are almost fully extended, but without locking your knees.", "Pause for a moment at the top of the movement, then slowly lower the footplate back towards your body by bending your knees.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将雪橇机的座椅和脚踏板调整到舒适的位置。", "坐在雪橇机上，背部靠在靠背上，双脚与肩同宽放在踏板上。", "握住座椅两侧的把手以保持稳定性。", "伸展双腿，将脚踏板推离身体，脚后跟保持在脚踏板上。", "继续推动，直到双腿几乎完全伸展，但不要锁住膝盖。", "在动作的最高点暂停片刻，然后弯曲膝盖，慢慢地将踏板放回到身体的方向。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["將雪橇機的座椅和腳踏板調整到舒適的位置。", "坐在雪橇機上，背部靠在靠背上，雙腳與肩同寬放在踏板上。", "握住座椅兩側的把手以保持穩定性。", "伸展雙腿，將腳踏板推離身體，腳后跟保持在腳踏板上。", "繼續推動，直到雙腿幾乎完全伸展，但不要鎖住膝蓋。", "在動作的最高點暫停片刻，然后彎曲膝蓋，慢慢地將踏板放回到身體的方向。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0585', 'exercise', 1, '{"id": "0585", "target": "quads", "name_en": "lever leg extension", "name_zh": "器械腿屈伸", "body_part": "upper legs", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0585-my33uHU.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械腿屈伸", "instructions_en": ["Adjust the seat height and backrest of the machine to fit your body.", "Sit on the machine with your back against the backrest and your feet on the footpad.", "Grasp the handles or sidebars for stability.", "Extend your legs forward by straightening your knees, lifting the weight.", "Pause for a moment at the top, then slowly lower the weight back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整机器的座椅高度和靠背以适合您的身体。", "坐在机器上，背部靠在靠背上，双脚放在脚垫上。", "抓住手柄或侧杆以保持稳定性。", "伸直膝盖，举起重物，向前伸展双腿。", "在顶部暂停片刻，然后慢慢将重量放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings"], "instructions_zh_hant": ["調整機器的座椅高度和靠背以適合您的身體。", "坐在機器上，背部靠在靠背上，雙腳放在腳墊上。", "抓住手柄或側桿以保持穩定性。", "伸直膝蓋，舉起重物，向前伸展雙腿。", "在頂部暫停片刻，然后慢慢將重量放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0472', 'exercise', 1, '{"id": "0472", "target": "abs", "name_en": "hanging leg raise", "name_zh": "悬垂举腿", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0472-I3tsCnC.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "懸垂舉腿", "instructions_en": ["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.", "Engage your core and lift your legs up in front of you, keeping them straight.", "Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。", "启动你的核心并将双腿抬起到你面前，保持伸直。", "继续抬起，直到双腿与地面平行或达到您可以舒适地达到的高度。", "在顶部暂停片刻，然后慢慢将双腿放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["懸掛在引體向上桿上，雙臂完全伸展，手掌背向自己。", "啟動你的核心并將雙腿抬起到你面前，保持伸直。", "繼續抬起，直到雙腿與地面平行或達到您可以舒適地達到的高度。", "在頂部暫停片刻，然后慢慢將雙腿放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0599', 'exercise', 1, '{"id": "0599", "target": "hamstrings", "name_en": "lever seated leg curl", "name_zh": "坐姿腿弯举", "body_part": "upper legs", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0599-Zg3XY7P.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "坐姿腿彎舉", "instructions_en": ["Adjust the machine to fit your body and sit on it with your back against the backrest.", "Place your lower legs under the padded lever, just above your ankles.", "Grasp the handles on the sides of the machine for support.", "Keeping your upper legs stationary, exhale and curl your legs up as far as possible.", "Hold the contracted position for a brief pause as you squeeze your hamstrings.", "Inhale and slowly lower the lever back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整机器以适合您的身体，然后坐在机器上，背部靠在靠背上。", "将小腿放在带衬垫的杠杆下方，就在脚踝上方。", "抓住机器两侧的手柄以提供支撑。", "保持大腿不动，呼气并尽可能向上弯曲双腿。", "挤压腿筋时，保持收缩位置短暂停顿。", "吸气并缓慢地将控制杆降低回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["calves"], "instructions_zh_hant": ["調整機器以適合您的身體，然后坐在機器上，背部靠在靠背上。", "將小腿放在帶襯墊的杠桿下方，就在腳踝上方。", "抓住機器兩側的手柄以提供支撐。", "保持大腿不動，呼氣并盡可能向上彎曲雙腿。", "擠壓腿筋時，保持收縮位置短暫停頓。", "吸氣并緩慢地將控制桿降低回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1373', 'exercise', 1, '{"id": "1373", "target": "calves", "name_en": "bodyweight standing calf raise", "name_zh": "站姿自重提踵", "body_part": "lower legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1373-bJYHBIN.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "站姿自重提踵", "instructions_en": ["Stand with your feet shoulder-width apart, toes pointing forward.", "Place your hands on a wall or stable surface for balance.", "Slowly raise your heels off the ground, lifting your body weight onto the balls of your feet.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，脚趾指向前方。", "将手放在墙壁或稳定的表面上以保持平衡。", "慢慢地将脚后跟抬离地面，将身体重量转移到脚掌上。", "在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["ankles", "feet"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，腳趾指向前方。", "將手放在墻壁或穩定的表面上以保持平衡。", "慢慢地將腳后跟抬離地面，將身體重量轉移到腳掌上。", "在頂部停頓片刻，然后慢慢降低腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0549', 'exercise', 1, '{"id": "0549", "target": "glutes", "name_en": "kettlebell swing", "name_zh": "壶铃摆荡", "body_part": "upper legs", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0549-UHJlbu3.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴擺蕩", "instructions_en": ["Stand with your feet shoulder-width apart, toes pointed slightly outward.", "Hold the kettlebell with both hands in front of your body, arms extended.", "Bend your knees slightly and hinge at the hips, pushing your butt back.", "Swing the kettlebell back between your legs, keeping your arms straight and maintaining a flat back.", "Drive your hips forward and swing the kettlebell up to shoulder height, using the momentum generated by your hips.", "Allow the kettlebell to swing back down between your legs and repeat the movement for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，脚趾稍微向外。", "双手握住壶铃放在身体前方，双臂伸展。", "稍微弯曲膝盖并铰接臀部，将臀部向后推。", "将壶铃在两腿之间向后摆动，保持手臂伸直并保持背部平坦。", "利用臀部产生的动量，向前推动臀部并将壶铃摆动到肩膀高度。", "让壶铃在双腿之间向下摆动，然后重复该动作达到所需的重复次数。"], "secondary_muscles": ["hamstrings", "core"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，腳趾稍微向外。", "雙手握住壺鈴放在身體前方，雙臂伸展。", "稍微彎曲膝蓋并鉸接臀部，將臀部向后推。", "將壺鈴在兩腿之間向后擺動，保持手臂伸直并保持背部平坦。", "利用臀部產生的動量，向前推動臀部并將壺鈴擺動到肩膀高度。", "讓壺鈴在雙腿之間向下擺動，然后重復該動作達到所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0274', 'exercise', 1, '{"id": "0274", "target": "abs", "name_en": "crunch floor", "name_zh": "卷腹", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0274-TFqbd8t.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "卷腹", "instructions_en": ["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engage your abs and lift your shoulders off the ground, curling forward towards your knees.", "Pause for a moment at the top, then slowly lower your shoulders back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，膝盖弯曲，双脚平放在地上。", "将双手放在脑后，肘部朝外。", "收紧腹肌，将肩膀抬离地面，向前向膝盖弯曲。", "在顶部停顿片刻，然后慢慢将肩膀放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["平躺，膝蓋彎曲，雙腳平放在地上。", "將雙手放在腦后，肘部朝外。", "收緊腹肌，將肩膀抬離地面，向前向膝蓋彎曲。", "在頂部停頓片刻，然后慢慢將肩膀放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0735', 'exercise', 1, '{"id": "0735", "target": "abs", "name_en": "sit-up v. 2", "name_zh": "仰卧起坐", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0735-Bn6TXyO.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "仰臥起坐", "instructions_en": ["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，膝盖弯曲，双脚平放在地上。", "将双手放在脑后，肘部朝外。", "收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。", "在顶部停顿片刻，然后慢慢将上半身放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["平躺，膝蓋彎曲，雙腳平放在地上。", "將雙手放在腦后，肘部朝外。", "收緊腹肌，慢慢將上半身抬離地面，向前卷曲，直到軀幹呈 45 度角。", "在頂部停頓片刻，然后慢慢將上半身放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2135', 'exercise', 1, '{"id": "2135", "target": "abs", "name_en": "weighted front plank", "name_zh": "负重平板支撑", "body_part": "waist", "equipment": "weighted", "gif_asset": "assets/fitness/videos/2135-VBAWRPG.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重平板支撐", "instructions_en": ["Start by lying face down on the floor.", "Place your forearms on the ground, with your elbows directly under your shoulders.", "Extend your legs straight out behind you, with your toes on the ground.", "Engage your core and lift your body off the ground, balancing on your forearms and toes.", "Keep your body in a straight line from your head to your heels.", "Hold this position for the desired amount of time.", "Lower your body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先脸朝下躺在地板上。", "将前臂放在地面上，肘部直接位于肩膀下方。", "将双腿伸直在身后，脚趾着地。", "启动你的核心并将你的身体抬离地面，用前臂和脚趾保持平衡。", "保持身体从头部到脚跟呈一条直线。", "保持此位置所需的时间。", "将身体放低至起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "lower back"], "instructions_zh_hant": ["首先臉朝下躺在地板上。", "將前臂放在地面上，肘部直接位于肩膀下方。", "將雙腿伸直在身后，腳趾著地。", "啟動你的核心并將你的身體抬離地面，用前臂和腳趾保持平衡。", "保持身體從頭部到腳跟呈一條直線。", "保持此位置所需的時間。", "將身體放低至起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0488', 'exercise', 1, '{"id": "0488", "target": "spine", "name_en": "hyperextension (on bench)", "name_zh": "背部挺身", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0488-zkgRrbK.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "背部挺身", "instructions_en": ["Adjust the hyperextension bench so that your hips are resting comfortably on the pad and your feet are secured.", "Cross your arms over your chest or place your hands behind your head.", "Slowly lower your upper body towards the ground while keeping your back straight.", "Pause for a moment at the bottom, then raise your upper body back up until it is in line with your legs.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整过度伸展凳，使臀部舒适地放在垫子上，并且双脚固定。", "双臂交叉放在胸前或将双手放在脑后。", "慢慢地将上半身降低到地面，同时保持背部挺直。", "在底部停顿片刻，然后抬起上半身，直到与双腿成一直线。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings"], "instructions_zh_hant": ["調整過度伸展凳，使臀部舒適地放在墊子上，并且雙腳固定。", "雙臂交叉放在胸前或將雙手放在腦后。", "慢慢地將上半身降低到地面，同時保持背部挺直。", "在底部停頓片刻，然后抬起上半身，直到與雙腿成一直線。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0001', 'exercise', 1, '{"id": "0001", "target": "abs", "name_en": "3/4 sit-up", "name_zh": "3/4仰卧起坐", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0001-2gPfomN.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "3/4仰臥起坐", "instructions_en": ["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，膝盖弯曲，双脚平放在地上。", "将双手放在脑后，肘部朝外。", "收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。", "在顶部停顿片刻，然后慢慢将上半身放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors", "lower back"], "instructions_zh_hant": ["平躺，膝蓋彎曲，雙腳平放在地上。", "將雙手放在腦后，肘部朝外。", "收緊腹肌，慢慢將上半身抬離地面，向前卷曲，直到軀幹呈 45 度角。", "在頂部停頓片刻，然后慢慢將上半身放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0002', 'exercise', 1, '{"id": "0002", "target": "abs", "name_en": "45° side bend", "name_zh": "45°侧屈", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0002-Hy9D21L.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "45°側屈", "instructions_en": ["Stand with your feet shoulder-width apart and your arms extended straight down by your sides.", "Keeping your back straight and your core engaged, slowly bend your torso to one side, lowering your hand towards your knee.", "Pause for a moment at the bottom, then slowly return to the starting position.", "Repeat on the other side.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双臂在身体两侧笔直向下伸展。", "保持背部挺直，核心肌群参与，慢慢将躯干向一侧弯曲，将手向膝盖方向放低。", "在底部停顿片刻，然后慢慢回到起始位置。", "在另一侧重复。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["obliques"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙臂在身體兩側筆直向下伸展。", "保持背部挺直，核心肌群參與，慢慢將軀幹向一側彎曲，將手向膝蓋方向放低。", "在底部停頓片刻，然后慢慢回到起始位置。", "在另一側重復。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0003', 'exercise', 1, '{"id": "0003", "target": "abs", "name_en": "air bike", "name_zh": "空中蹬车", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0003-1ZFqTDN.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "空中蹬車", "instructions_en": ["Lie flat on your back with your hands placed behind your head.", "Lift your legs off the ground and bend your knees at a 90-degree angle.", "Bring your right elbow towards your left knee while simultaneously straightening your right leg.", "Return to the starting position and repeat the movement on the opposite side, bringing your left elbow towards your right knee while straightening your left leg.", "Continue alternating sides in a pedaling motion for the desired number of repetitions."], "instructions_zh": ["平躺，双手放在脑后。", "将双腿抬离地面，并以 90 度角弯曲膝盖。", "将右肘靠近左膝盖，同时伸直右腿。", "返回起始位置，在另一侧重复该动作，将左肘拉向右膝盖，同时伸直左腿。", "继续交替进行蹬踏动作，达到所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["平躺，雙手放在腦后。", "將雙腿抬離地面，并以 90 度角彎曲膝蓋。", "將右肘靠近左膝蓋，同時伸直右腿。", "返回起始位置，在另一側重復該動作，將左肘拉向右膝蓋，同時伸直左腿。", "繼續交替進行蹬踏動作，達到所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1512', 'exercise', 1, '{"id": "1512", "target": "quads", "name_en": "all fours squad stretch", "name_zh": "四点跪姿股四头肌拉伸", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1512-qBcKorM.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "四點跪姿股四頭肌拉伸", "instructions_en": ["Start on all fours with your hands directly under your shoulders and your knees directly under your hips.", "Extend one leg straight back, keeping your knee bent and your foot flexed.", "Slowly lower your hips towards the ground, feeling a stretch in your quads.", "Hold this position for 20-30 seconds.", "Switch legs and repeat the stretch on the other side."], "instructions_zh": ["从四肢着地开始，双手直接放在肩膀下方，膝盖直接放在臀部下方。", "将一条腿向后伸直，保持膝盖弯曲和脚弯曲。", "慢慢地将臀部降低到地面，感觉股四头肌的伸展。", "保持这个姿势20-30秒。", "换腿并在另一侧重复拉伸。"], "secondary_muscles": ["hamstrings", "glutes"], "instructions_zh_hant": ["從四肢著地開始，雙手直接放在肩膀下方，膝蓋直接放在臀部下方。", "將一條腿向后伸直，保持膝蓋彎曲和腳彎曲。", "慢慢地將臀部降低到地面，感覺股四頭肌的伸展。", "保持這個姿勢20-30秒。", "換腿并在另一側重復拉伸。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0006', 'exercise', 1, '{"id": "0006", "target": "abs", "name_en": "alternate heel touchers", "name_zh": "交替触踝卷腹", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0006-qaZVsGk.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "交替觸踝卷腹", "instructions_en": ["Lie flat on your back with your knees bent and feet flat on the ground.", "Extend your arms straight out to the sides, parallel to the ground.", "Engaging your abs, lift your shoulders off the ground and reach your right hand towards your right heel.", "Return to the starting position and repeat on the left side, reaching your left hand towards your left heel.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["平躺，膝盖弯曲，双脚平放在地上。", "将双臂伸直至两侧，与地面平行。", "收紧腹肌，将肩膀抬离地面，并将右手伸向右脚跟。", "返回起始位置并在左侧重复，将左手伸向左脚跟。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["obliques"], "instructions_zh_hant": ["平躺，膝蓋彎曲，雙腳平放在地上。", "將雙臂伸直至兩側，與地面平行。", "收緊腹肌，將肩膀抬離地面，并將右手伸向右腳跟。", "返回起始位置并在左側重復，將左手伸向左腳跟。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0007', 'exercise', 1, '{"id": "0007", "target": "lats", "name_en": "alternate lateral pulldown", "name_zh": "交替侧向下拉", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/0007-4IKbhHV.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "交替側向下拉", "instructions_en": ["Sit on the cable machine with your back straight and feet flat on the ground.", "Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.", "Lean back slightly and pull the handles towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在缆绳机上，背部挺直，双脚平放在地面上。", "正手握住手柄，握距略宽于肩宽。", "稍微向后倾斜，将手柄拉向胸部，将肩胛骨挤压在一起。", "在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "rhomboids"], "instructions_zh_hant": ["坐在纜繩機上，背部挺直，雙腳平放在地面上。", "正手握住手柄，握距略寬于肩寬。", "稍微向后傾斜，將手柄拉向胸部，將肩胛骨擠壓在一起。", "在動作的最高點暫停片刻，然后慢慢松開手柄回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1368', 'exercise', 1, '{"id": "1368", "target": "calves", "name_en": "ankle circles", "name_zh": "踝关节绕环", "body_part": "lower legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1368-uL9CsKm.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "踝關節繞環", "instructions_en": ["Sit on the ground with your legs extended in front of you.", "Lift one leg off the ground and rotate your ankle in a circular motion.", "Perform the desired number of circles in one direction, then switch to the other direction.", "Repeat with the other leg."], "instructions_zh": ["坐在地上，双腿在身前伸展。", "将一条腿抬离地面，并以圆周运动旋转脚踝。", "在一个方向上转所需的圈数，然后切换到另一个方向。", "换另一条腿重复上述步骤。"], "secondary_muscles": ["ankle stabilizers"], "instructions_zh_hant": ["坐在地上，雙腿在身前伸展。", "將一條腿抬離地面，并以圓周運動旋轉腳踝。", "在一個方向上轉所需的圈數，然后切換到另一個方向。", "換另一條腿重復上述步驟。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3293', 'exercise', 1, '{"id": "3293", "target": "lats", "name_en": "archer pull up", "name_zh": "弓箭式引体向上", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3293-72BC5Za.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "弓箭式引體向上", "instructions_en": ["Start by hanging from a pull-up bar with an overhand grip, slightly wider than shoulder-width apart.", "Engage your core and pull your shoulder blades down and back.", "As you pull yourself up, bend one arm and bring your elbow towards your side, while keeping the other arm straight.", "Continue pulling until your chin is above the bar and your bent arm is fully flexed.", "Lower yourself back down with control, straightening the bent arm and repeating the movement on the other side.", "Alternate sides with each repetition."], "instructions_zh": ["首先，用正手握法悬挂在引体向上杆上，握距略宽于肩宽。", "启动你的核心并将肩胛骨向下拉和向后拉。", "当你站起来时，弯曲一只手臂并将肘部移向身体一侧，同时保持另一只手臂伸直。", "继续拉，直到下巴位于杠铃上方并且弯曲的手臂完全弯曲。", "有控制地放低自己，伸直弯曲的手臂并在另一侧重复该动作。", "每次重复时交替进行。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["首先，用正手握法懸掛在引體向上桿上，握距略寬于肩寬。", "啟動你的核心并將肩胛骨向下拉和向后拉。", "當你站起來時，彎曲一只手臂并將肘部移向身體一側，同時保持另一只手臂伸直。", "繼續拉，直到下巴位于杠鈴上方并且彎曲的手臂完全彎曲。", "有控制地放低自己，伸直彎曲的手臂并在另一側重復該動作。", "每次重復時交替進行。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3672', 'exercise', 1, '{"id": "3672", "target": "cardiovascular system", "name_en": "back and forth step", "name_zh": "前后交替踏步", "body_part": "cardio", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3672-fNGumX0.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "前后交替踏步", "instructions_en": ["Stand with your feet shoulder-width apart.", "Step forward with your right foot, bending your knee and lowering your body into a lunge position.", "Push off with your right foot and step back to the starting position.", "Repeat the movement with your left foot, alternating legs with each step.", "Continue stepping back and forth, maintaining a steady pace.", "Repeat for the desired duration or number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立。", "右脚向前迈出一步，弯曲膝盖，将身体降低到弓步位置。", "用右脚蹬地，然后回到起始位置。", "用左脚重复该动作，每一步交替双腿。", "继续来回走动，保持稳定的步伐。", "重复所需的持续时间或重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "glutes", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立。", "右腳向前邁出一步，彎曲膝蓋，將身體降低到弓步位置。", "用右腳蹬地，然后回到起始位置。", "用左腳重復該動作，每一步交替雙腿。", "繼續來回走動，保持穩定的步伐。", "重復所需的持續時間或重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3294', 'exercise', 1, '{"id": "3294", "target": "pectorals", "name_en": "archer push up", "name_zh": "弓箭式俯卧撑", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3294-A9qxk2F.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "弓箭式俯臥撐", "instructions_en": ["Start in a push-up position with your hands slightly wider than shoulder-width apart.", "Extend one arm straight out to the side, parallel to the ground.", "Lower your body by bending your elbows, keeping your back straight and core engaged.", "Push back up to the starting position.", "Repeat on the other side, extending the opposite arm out to the side.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["从俯卧撑位置开始，双手分开略宽于肩宽。", "将一只手臂伸直至一侧，与地面平行。", "弯曲肘部降低身体，保持背部挺直，核心参与。", "推回到起始位置。", "在另一侧重复上述步骤，将另一只手臂伸出到一侧。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders", "core"], "instructions_zh_hant": ["從俯臥撐位置開始，雙手分開略寬于肩寬。", "將一只手臂伸直至一側，與地面平行。", "彎曲肘部降低身體，保持背部挺直，核心參與。", "推回到起始位置。", "在另一側重復上述步驟，將另一只手臂伸出到一側。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2355', 'exercise', 1, '{"id": "2355", "target": "abs", "name_en": "arm slingers hanging bent knee legs", "name_zh": "吊带悬垂屈膝举腿", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/2355-uWpxD4v.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "吊帶懸垂屈膝舉腿", "instructions_en": ["Hang from a pull-up bar with your arms fully extended and your knees bent at a 90-degree angle.", "Engage your core and lift your knees towards your chest, bringing them as close to your elbows as possible.", "Slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["悬挂在引体向上杆上，双臂完全伸展，膝盖弯曲成 90 度角。", "收紧核心并将膝盖抬向胸部，尽可能靠近肘部。", "慢慢地将双腿放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "back"], "instructions_zh_hant": ["懸掛在引體向上桿上，雙臂完全伸展，膝蓋彎曲成 90 度角。", "收緊核心并將膝蓋抬向胸部，盡可能靠近肘部。", "慢慢地將雙腿放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2333', 'exercise', 1, '{"id": "2333", "target": "abs", "name_en": "arm slingers hanging straight legs", "name_zh": "吊带悬垂直腿举腿", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/2333-PXTIwgu.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "吊帶懸垂直腿舉腿", "instructions_en": ["Hang from a pull-up bar with your arms fully extended and your legs straight down.", "Engage your core and lift your legs up in front of you until they are parallel to the ground.", "Hold for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["悬挂在引体向上杆上，双臂完全伸展，双腿伸直向下。", "启动你的核心并将双腿抬起到你面前，直到它们与地面平行。", "在顶部保持片刻，然后慢慢将双腿放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "back"], "instructions_zh_hant": ["懸掛在引體向上桿上，雙臂完全伸展，雙腿伸直向下。", "啟動你的核心并將雙腿抬起到你面前，直到它們與地面平行。", "在頂部保持片刻，然后慢慢將雙腿放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3214', 'exercise', 1, '{"id": "3214", "target": "glutes", "name_en": "arms apart circular toe touch (male)", "name_zh": "双臂展开绕环触脚尖（男性示范）", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3214-RtyAsy1.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "雙臂展開繞環觸腳尖（男性示范）", "instructions_en": ["Stand with your feet shoulder-width apart and arms extended to the sides.", "Keeping your legs straight, bend forward at the waist and reach down towards your toes with your right hand.", "As you reach down, simultaneously lift your left leg straight up behind you, maintaining balance.", "Return to the starting position and repeat the movement with your left hand reaching towards your toes and your right leg lifting up behind you.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双臂向两侧伸展。", "保持双腿伸直，腰部向前弯曲，右手向下伸向脚趾。", "当你向下伸展时，同时将左腿在身后伸直，保持平衡。", "返回起始位置，重复该动作，左手伸向脚趾，右腿在身后抬起。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["hamstrings", "quadriceps", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙臂向兩側伸展。", "保持雙腿伸直，腰部向前彎曲，右手向下伸向腳趾。", "當你向下伸展時，同時將左腿在身后伸直，保持平衡。", "返回起始位置，重復該動作，左手伸向腳趾，右腿在身后抬起。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3204', 'exercise', 1, '{"id": "3204", "target": "abs", "name_en": "arms overhead full sit-up (male)", "name_zh": "双臂过顶全程仰卧起坐（男性示范）", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3204-NAkmgdx.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "雙臂過頂全程仰臥起坐（男性示范）", "instructions_en": ["Lie flat on your back with your knees bent and feet flat on the ground.", "Extend your arms overhead, keeping them straight.", "Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is upright.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，膝盖弯曲，双脚平放在地上。", "将手臂伸过头顶，保持伸直。", "收紧腹肌，慢慢将上半身抬离地面，向前卷曲直到躯干直立。", "在顶部停顿片刻，然后慢慢将上半身放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors", "lower back"], "instructions_zh_hant": ["平躺，膝蓋彎曲，雙腳平放在地上。", "將手臂伸過頭頂，保持伸直。", "收緊腹肌，慢慢將上半身抬離地面，向前卷曲直到軀幹直立。", "在頂部停頓片刻，然后慢慢將上半身放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0009', 'exercise', 1, '{"id": "0009", "target": "pectorals", "name_en": "assisted chest dip (kneeling)", "name_zh": "辅助双杠臂屈伸（偏胸）（跪姿）", "body_part": "chest", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0009-PAgTVaK.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "輔助雙槓臂屈伸（偏胸）（跪姿）", "instructions_en": ["Adjust the machine to your desired height and secure your knees on the pad.", "Grasp the handles with your palms facing down and your arms fully extended.", "Lower your body by bending your elbows until your upper arms are parallel to the floor.", "Pause for a moment, then push yourself back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将机器调整到您想要的高度，并将膝盖固定在垫子上。", "手掌朝下，抓住手柄，双臂完全伸展。", "弯曲肘部降低身体，直到上臂与地板平行。", "暂停片刻，然后将自己推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["將機器調整到您想要的高度，并將膝蓋固定在墊子上。", "手掌朝下，抓住手柄，雙臂完全伸展。", "彎曲肘部降低身體，直到上臂與地板平行。", "暫停片刻，然后將自己推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0011', 'exercise', 1, '{"id": "0011", "target": "abs", "name_en": "assisted hanging knee raise", "name_zh": "辅助悬垂提膝", "body_part": "waist", "equipment": "assisted", "gif_asset": "assets/fitness/videos/0011-03lzqwk.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "輔助懸垂提膝", "instructions_en": ["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.", "Engage your core muscles and lift your knees towards your chest, bending at the hips and knees.", "Pause for a moment at the top of the movement, squeezing your abs.", "Slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。", "调动你的核心肌肉，将膝盖抬向胸部，弯曲臀部和膝盖。", "在动作的最高点暂停片刻，挤压腹肌。", "慢慢地将双腿放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["懸掛在引體向上桿上，雙臂完全伸展，手掌背向自己。", "調動你的核心肌肉，將膝蓋抬向胸部，彎曲臀部和膝蓋。", "在動作的最高點暫停片刻，擠壓腹肌。", "慢慢地將雙腿放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0010', 'exercise', 1, '{"id": "0010", "target": "abs", "name_en": "assisted hanging knee raise with throw down", "name_zh": "伙伴下压辅助悬垂提膝", "body_part": "waist", "equipment": "assisted", "gif_asset": "assets/fitness/videos/0010-8K0w2yA.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "伙伴下壓輔助懸垂提膝", "instructions_en": ["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.", "Engage your core and lift your knees towards your chest, keeping your legs together.", "Once your knees are at chest level, explosively throw your legs down towards the ground, extending them fully.", "Allow your legs to swing back up and repeat the movement for the desired number of repetitions."], "instructions_zh": ["悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。", "收紧核心并将膝盖抬向胸部，保持双腿并拢。", "一旦你的膝盖与胸部齐平，爆发性地将你的双腿向地面扔去，将它们完全伸展。", "让双腿向后摆动并重复该动作达到所需的重复次数。"], "secondary_muscles": ["hip flexors", "lower back"], "instructions_zh_hant": ["懸掛在引體向上桿上，雙臂完全伸展，手掌背向自己。", "收緊核心并將膝蓋抬向胸部，保持雙腿并攏。", "一旦你的膝蓋與胸部齊平，爆發性地將你的雙腿向地面扔去，將它們完全伸展。", "讓雙腿向后擺動并重復該動作達到所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1710', 'exercise', 1, '{"id": "1710", "target": "glutes", "name_en": "assisted lying gluteus and piriformis stretch", "name_zh": "辅助卧姿臀肌与梨状肌拉伸", "body_part": "upper legs", "equipment": "assisted", "gif_asset": "assets/fitness/videos/1710-RQNVT10.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "輔助臥姿臀肌與梨狀肌拉伸", "instructions_en": ["Lie on your back with your legs extended.", "Bend your right knee and place your right ankle on your left thigh, just above the knee.", "Grasp your left thigh with both hands and gently pull it towards your chest.", "Hold the stretch for 20-30 seconds.", "Release the stretch and repeat on the other side."], "instructions_zh": ["仰卧，双腿伸展。", "弯曲右膝盖，将右脚踝放在左大腿上，就在膝盖上方。", "用双手抓住左大腿，轻轻地将其拉向胸部。", "保持拉伸 20-30 秒。", "松开拉伸并在另一侧重复。"], "secondary_muscles": ["hamstrings"], "instructions_zh_hant": ["仰臥，雙腿伸展。", "彎曲右膝蓋，將右腳踝放在左大腿上，就在膝蓋上方。", "用雙手抓住左大腿，輕輕地將其拉向胸部。", "保持拉伸 20-30 秒。", "松開拉伸并在另一側重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0012', 'exercise', 1, '{"id": "0012", "target": "abs", "name_en": "assisted lying leg raise with lateral throw down", "name_zh": "伙伴侧向下压仰卧举腿", "body_part": "waist", "equipment": "assisted", "gif_asset": "assets/fitness/videos/0012-UGhRD1A.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "伙伴側向下壓仰臥舉腿", "instructions_en": ["Lie flat on your back with your legs extended and your arms by your sides.", "Place your hands under your glutes for support.", "Engage your abs and lift your legs off the ground, keeping them straight.", "While keeping your legs together, lower them to one side until they are a few inches above the ground.", "Pause for a moment, then lift your legs back to the starting position.", "Repeat the movement to the other side.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["平躺，双腿伸展，双臂放在身体两侧。", "将双手放在臀部下方以获得支撑。", "收紧腹肌，将双腿抬离地面，保持伸直。", "双腿并拢的同时，将它们降低到一侧，直到离地几英寸。", "暂停片刻，然后抬起双腿回到起始位置。", "到另一侧重复该动作。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["hip flexors", "obliques"], "instructions_zh_hant": ["平躺，雙腿伸展，雙臂放在身體兩側。", "將雙手放在臀部下方以獲得支撐。", "收緊腹肌，將雙腿抬離地面，保持伸直。", "雙腿并攏的同時，將它們降低到一側，直到離地幾英寸。", "暫停片刻，然后抬起雙腿回到起始位置。", "到另一側重復該動作。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0013', 'exercise', 1, '{"id": "0013", "target": "abs", "name_en": "assisted lying leg raise with throw down", "name_zh": "伙伴下压仰卧举腿", "body_part": "waist", "equipment": "assisted", "gif_asset": "assets/fitness/videos/0013-VX5YKR5.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "伙伴下壓仰臥舉腿", "instructions_en": ["Lie flat on your back with your legs extended and your arms by your sides.", "Place your hands under your glutes for support.", "Engage your core and lift your legs off the ground, keeping them straight.", "Raise your legs until they are perpendicular to the ground.", "Lower your legs back down to the starting position.", "Simultaneously, throw your legs down towards the ground, keeping them straight.", "Raise your legs back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，双腿伸展，双臂放在身体两侧。", "将双手放在臀部下方以获得支撑。", "启动你的核心并将双腿抬离地面，保持伸直。", "抬起双腿，直到它们垂直于地面。", "将双腿放低回到起始位置。", "同时，将双腿向地面放下，保持伸直。", "将双腿抬回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors", "quadriceps"], "instructions_zh_hant": ["平躺，雙腿伸展，雙臂放在身體兩側。", "將雙手放在臀部下方以獲得支撐。", "啟動你的核心并將雙腿抬離地面，保持伸直。", "抬起雙腿，直到它們垂直于地面。", "將雙腿放低回到起始位置。", "同時，將雙腿向地面放下，保持伸直。", "將雙腿抬回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0014', 'exercise', 1, '{"id": "0014", "target": "abs", "name_en": "assisted motion russian twist", "name_zh": "辅助动态俄罗斯转体", "body_part": "waist", "equipment": "medicine ball", "gif_asset": "assets/fitness/videos/0014-r7cT9YD.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "輔助動態俄羅斯轉體", "instructions_en": ["Sit on the ground with your knees bent and feet flat on the floor.", "Hold the medicine ball with both hands in front of your chest.", "Lean back slightly, engaging your abs and keeping your back straight.", "Slowly twist your torso to the right, bringing the medicine ball towards the right side of your body.", "Pause for a moment, then twist your torso to the left, bringing the medicine ball towards the left side of your body.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["坐在地上，膝盖弯曲，双脚平放在地板上。", "双手将健身球放在胸前。", "稍微向后倾斜，收紧腹肌并保持背部挺直。", "慢慢地将你的躯干向右扭转，将健身球移向身体的右侧。", "暂停片刻，然后将躯干向左扭转，将健身球移向身体左侧。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["obliques", "lower back"], "instructions_zh_hant": ["坐在地上，膝蓋彎曲，雙腳平放在地板上。", "雙手將健身球放在胸前。", "稍微向后傾斜，收緊腹肌并保持背部挺直。", "慢慢地將你的軀幹向右扭轉，將健身球移向身體的右側。", "暫停片刻，然后將軀幹向左扭轉，將健身球移向身體左側。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0015', 'exercise', 1, '{"id": "0015", "target": "lats", "name_en": "assisted parallel close grip pull-up", "name_zh": "辅助窄距对握引体向上", "body_part": "back", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0015-vrhHa6D.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "輔助窄距對握引體向上", "instructions_en": ["Adjust the machine to your desired weight and height.", "Place your hands on the parallel bars with a close grip, palms facing each other.", "Hang from the bars with your arms fully extended and your feet off the ground.", "Engage your back muscles and pull your body up towards the bars, keeping your elbows close to your body.", "Continue pulling until your chin is above the bars.", "Pause for a moment at the top, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将机器调整到您想要的重量和高度。", "将双手紧紧握在双杠上，手掌相对。", "悬挂在杠上，双臂完全伸展，双脚离开地面。", "收紧背部肌肉，将身体拉向杠铃，保持肘部靠近身体。", "继续拉，直到下巴高于杠铃。", "在顶部停顿片刻，然后慢慢将身体放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["將機器調整到您想要的重量和高度。", "將雙手緊緊握在雙杠上，手掌相對。", "懸掛在杠上，雙臂完全伸展，雙腳離開地面。", "收緊背部肌肉，將身體拉向杠鈴，保持肘部靠近身體。", "繼續拉，直到下巴高于杠鈴。", "在頂部停頓片刻，然后慢慢將身體放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0016', 'exercise', 1, '{"id": "0016", "target": "hamstrings", "name_en": "assisted prone hamstring", "name_zh": "辅助俯卧腿弯举", "body_part": "upper legs", "equipment": "assisted", "gif_asset": "assets/fitness/videos/0016-VedGSby.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "輔助俯臥腿彎舉", "instructions_en": ["Lie face down on a mat or bench with your legs fully extended.", "Have a partner or use a resistance band to secure your ankles.", "Engage your hamstrings and lift your legs towards your glutes, keeping your knees straight.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["脸朝下躺在垫子或长凳上，双腿完全伸展。", "找一个伙伴或使用阻力带来固定脚踝。", "收紧腿筋，将双腿抬向臀肌，保持膝盖伸直。", "在顶部暂停片刻，然后慢慢将双腿放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "lower back"], "instructions_zh_hant": ["臉朝下躺在墊子或長凳上，雙腿完全伸展。", "找一個伙伴或使用阻力帶來固定腳踝。", "收緊腿筋，將雙腿抬向臀肌，保持膝蓋伸直。", "在頂部暫停片刻，然后慢慢將雙腿放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1713', 'exercise', 1, '{"id": "1713", "target": "quads", "name_en": "assisted prone lying quads stretch", "name_zh": "辅助俯卧股四头肌拉伸", "body_part": "upper legs", "equipment": "assisted", "gif_asset": "assets/fitness/videos/1713-YUYAMEj.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "輔助俯臥股四頭肌拉伸", "instructions_en": ["Lie face down on the ground with your legs extended.", "Bend your left knee and reach back with your left hand to grab your left foot or ankle.", "Gently pull your left foot towards your glutes, feeling a stretch in your left quad.", "Hold the stretch for 20-30 seconds, then release.", "Repeat with your right leg."], "instructions_zh": ["脸朝下躺在地上，双腿伸直。", "弯曲左膝，用左手向后抓住左脚或脚踝。", "轻轻地将左脚拉向臀肌，感受左股四头肌的拉伸。", "保持拉伸 20-30 秒，然后放松。", "右腿重复上述动作。"], "secondary_muscles": ["hamstrings", "glutes"], "instructions_zh_hant": ["臉朝下躺在地上，雙腿伸直。", "彎曲左膝，用左手向后抓住左腳或腳踝。", "輕輕地將左腳拉向臀肌，感受左股四頭肌的拉伸。", "保持拉伸 20-30 秒，然后放松。", "右腿重復上述動作。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1714', 'exercise', 1, '{"id": "1714", "target": "abs", "name_en": "assisted prone rectus femoris stretch", "name_zh": "辅助俯卧股直肌拉伸", "body_part": "waist", "equipment": "assisted", "gif_asset": "assets/fitness/videos/1714-2Ryn564.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "輔助俯臥股直肌拉伸", "instructions_en": ["Lie face down on the ground with your legs straight.", "Bend your right knee and reach back with your right hand to grab your right foot or ankle.", "Gently pull your right foot or ankle towards your glutes, feeling a stretch in the front of your right thigh.", "Hold the stretch for 20-30 seconds.", "Release and repeat on the other side."], "instructions_zh": ["脸朝下躺在地上，双腿伸直。", "弯曲右膝，用右手向后伸抓住右脚或脚踝。", "轻轻地将右脚或脚踝拉向臀部，感受右大腿前部的拉伸。", "保持拉伸 20-30 秒。", "松开并在另一侧重复。"], "secondary_muscles": ["quadriceps"], "instructions_zh_hant": ["臉朝下躺在地上，雙腿伸直。", "彎曲右膝，用右手向后伸抓住右腳或腳踝。", "輕輕地將右腳或腳踝拉向臀部，感受右大腿前部的拉伸。", "保持拉伸 20-30 秒。", "松開并在另一側重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1716', 'exercise', 1, '{"id": "1716", "target": "pectorals", "name_en": "assisted seated pectoralis major stretch with stability ball", "name_zh": "辅助坐姿胸大肌拉伸配合健身球", "body_part": "chest", "equipment": "assisted", "gif_asset": "assets/fitness/videos/1716-RoV1Rfa.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "輔助坐姿胸大肌拉伸配合健身球", "instructions_en": ["Sit on a stability ball with your feet flat on the ground and your back straight.", "Hold a stability ball with both hands and extend your arms straight out in front of you.", "Slowly lower the stability ball towards your chest, feeling a stretch in your pectoral muscles.", "Hold the stretch for a few seconds, then slowly return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在稳定球上，双脚平放在地面上，背部挺直。", "双手握住稳定球，并将双臂伸直至身前。", "慢慢地将稳定球降低到胸部，感受胸肌的拉伸。", "保持伸展几秒钟，然后慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["坐在穩定球上，雙腳平放在地面上，背部挺直。", "雙手握住穩定球，并將雙臂伸直至身前。", "慢慢地將穩定球降低到胸部，感受胸肌的拉伸。", "保持伸展幾秒鐘，然后慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1712', 'exercise', 1, '{"id": "1712", "target": "adductors", "name_en": "assisted side lying adductor stretch", "name_zh": "辅助侧卧内收肌拉伸", "body_part": "upper legs", "equipment": "assisted", "gif_asset": "assets/fitness/videos/1712-hC6oYY5.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "輔助側臥內收肌拉伸", "instructions_en": ["Lie on your side with your legs straight and stacked on top of each other.", "Bend your bottom leg slightly for stability.", "Place your top foot on a stable surface, such as a bench or step.", "Keeping your top leg straight, slowly lower it towards the ground, feeling a stretch in your inner thigh.", "Hold the stretch for 20-30 seconds.", "Return to the starting position and repeat on the other side."], "instructions_zh": ["侧躺，双腿伸直并叠放在一起。", "稍微弯曲下面的腿以保持稳定。", "将上脚放在稳定的表面上，例如长凳或台阶上。", "保持上腿伸直，慢慢将其降低到地面，感觉大腿内侧有拉伸感。", "保持拉伸 20-30 秒。", "返回起始位置并在另一侧重复。"], "secondary_muscles": ["hamstrings", "glutes"], "instructions_zh_hant": ["側躺，雙腿伸直并疊放在一起。", "稍微彎曲下面的腿以保持穩定。", "將上腳放在穩定的表面上，例如長凳或臺階上。", "保持上腿伸直，慢慢將其降低到地面，感覺大腿內側有拉伸感。", "保持拉伸 20-30 秒。", "返回起始位置并在另一側重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1758', 'exercise', 1, '{"id": "1758", "target": "abs", "name_en": "assisted sit-up", "name_zh": "辅助仰卧起坐", "body_part": "waist", "equipment": "assisted", "gif_asset": "assets/fitness/videos/1758-aumB2IV.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "輔助仰臥起坐", "instructions_en": ["Sit on the edge of a bench or have someone hold your feet down.", "Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳边缘或让某人按住你的脚。", "平躺，膝盖弯曲，双脚平放在地上。", "将双手放在脑后，肘部朝外。", "收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。", "在顶部停顿片刻，然后慢慢将上半身放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["坐在長凳邊緣或讓某人按住你的腳。", "平躺，膝蓋彎曲，雙腳平放在地上。", "將雙手放在腦后，肘部朝外。", "收緊腹肌，慢慢將上半身抬離地面，向前卷曲，直到軀幹呈 45 度角。", "在頂部停頓片刻，然后慢慢將上半身放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1431', 'exercise', 1, '{"id": "1431", "target": "lats", "name_en": "assisted standing chin-up", "name_zh": "辅助站姿反握引体向上", "body_part": "back", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/1431-7OeHptV.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "輔助站姿反握引體向上", "instructions_en": ["Adjust the machine to your desired assistance level.", "Stand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart.", "Keep your chest up and shoulders back, engage your core, and slightly bend your knees.", "Pull your body up by flexing your elbows and driving your elbows down towards your sides.", "Continue pulling until your chin is above the bar.", "Pause for a moment at the top, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将机器调整至您所需的辅助级别。", "站在脚踏板上，正手握住手柄，握距略宽于肩宽。", "保持挺胸、肩膀向后，收紧核心肌群，并稍微弯曲膝盖。", "弯曲肘部并将肘部向身体两侧压低，将身体向上拉。", "继续拉，直到下巴位于杠铃上方。", "在顶部停顿片刻，然后慢慢将身体放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["將機器調整至您所需的輔助級別。", "站在腳踏板上，正手握住手柄，握距略寬于肩寬。", "保持挺胸、肩膀向后，收緊核心肌群，并稍微彎曲膝蓋。", "彎曲肘部并將肘部向身體兩側壓低，將身體向上拉。", "繼續拉，直到下巴位于杠鈴上方。", "在頂部停頓片刻，然后慢慢將身體放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1432', 'exercise', 1, '{"id": "1432", "target": "lats", "name_en": "assisted standing pull-up", "name_zh": "辅助站姿引体向上", "body_part": "back", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/1432-f4xtKBj.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "輔助站姿引體向上", "instructions_en": ["Adjust the machine to your desired weight and height settings.", "Stand facing the machine with your feet shoulder-width apart.", "Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.", "Engage your lats and biceps, and pull yourself up towards the handles.", "Pause for a moment at the top, squeezing your back muscles.", "Slowly lower yourself back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将机器调整至您所需的体重和高度设置。", "面向机器站立，双脚分开与肩同宽。", "正手握住手柄，握距略宽于肩宽。", "启动你的背阔肌和二头肌，并将自己拉向手柄。", "在顶部暂停片刻，挤压背部肌肉。", "慢慢地将自己放回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["將機器調整至您所需的體重和高度設置。", "面向機器站立，雙腳分開與肩同寬。", "正手握住手柄，握距略寬于肩寬。", "啟動你的背闊肌和二頭肌，并將自己拉向手柄。", "在頂部暫停片刻，擠壓背部肌肉。", "慢慢地將自己放回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0018', 'exercise', 1, '{"id": "0018", "target": "triceps", "name_en": "assisted standing triceps extension (with towel)", "name_zh": "辅助站姿臂屈伸（配合毛巾）", "body_part": "upper arms", "equipment": "assisted", "gif_asset": "assets/fitness/videos/0018-7HcfMBP.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "輔助站姿臂屈伸（配合毛巾）", "instructions_en": ["Stand with your feet shoulder-width apart and hold a towel with both hands behind your head.", "Keep your elbows close to your ears and your upper arms stationary.", "Slowly extend your forearms upward, squeezing your triceps at the top.", "Pause for a moment, then slowly lower the towel back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手握住毛巾放在脑后。", "保持肘部靠近耳朵，上臂保持静止。", "慢慢向上伸展前臂，在顶部挤压三头肌。", "暂停片刻，然后慢慢将毛巾放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手握住毛巾放在腦后。", "保持肘部靠近耳朵，上臂保持靜止。", "慢慢向上伸展前臂，在頂部擠壓三頭肌。", "暫停片刻，然后慢慢將毛巾放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2364', 'exercise', 1, '{"id": "2364", "target": "pectorals", "name_en": "assisted wide-grip chest dip (kneeling)", "name_zh": "辅助宽握双杠臂屈伸（偏胸）（跪姿）", "body_part": "chest", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/2364-PnZJIrk.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "輔助寬握雙槓臂屈伸（偏胸）（跪姿）", "instructions_en": ["Adjust the machine to your desired height and secure your knees on the pad.", "Grasp the handles with a wide grip and keep your elbows slightly bent.", "Lower your body by bending your elbows until your upper arms are parallel to the floor.", "Push yourself back up to the starting position by extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将机器调整到您想要的高度，并将膝盖固定在垫子上。", "宽握手柄并保持肘部稍微弯曲。", "弯曲肘部降低身体，直到上臂与地板平行。", "伸展双臂，将自己推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["將機器調整到您想要的高度，并將膝蓋固定在墊子上。", "寬握手柄并保持肘部稍微彎曲。", "彎曲肘部降低身體，直到上臂與地板平行。", "伸展雙臂，將自己推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3220', 'exercise', 1, '{"id": "3220", "target": "cardiovascular system", "name_en": "astride jumps (male)", "name_zh": "开合跳（男性示范）", "body_part": "cardio", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3220-f9lVSSI.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "開合跳（男性示范）", "instructions_en": ["Stand with your feet shoulder-width apart.", "Bend your knees and lower your body into a squat position.", "Jump explosively upwards, extending your legs and arms.", "While in the air, spread your legs apart and bring your arms out to the sides.", "Land softly with your feet shoulder-width apart, bending your knees to absorb the impact.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立。", "弯曲膝盖并将身体降低至蹲姿。", "爆发性向上跳跃，伸展双腿和手臂。", "在空中时，将双腿分开，并将双臂向两侧伸出。", "双脚分开与肩同宽，轻轻落地，弯曲膝盖以吸收冲击力。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立。", "彎曲膝蓋并將身體降低至蹲姿。", "爆發性向上跳躍，伸展雙腿和手臂。", "在空中時，將雙腿分開，并將雙臂向兩側伸出。", "雙腳分開與肩同寬，輕輕落地，彎曲膝蓋以吸收沖擊力。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1314', 'exercise', 1, '{"id": "1314", "target": "spine", "name_en": "back extension on exercise ball", "name_zh": "健身球背部挺身", "body_part": "back", "equipment": "stability ball", "gif_asset": "assets/fitness/videos/1314-qLpO4vV.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球背部挺身", "instructions_en": ["Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall or other stable surface.", "Position your hands behind your head or crossed over your chest.", "Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将稳定球放在地面上，面朝下躺在上面，臀部放在球上，双脚靠在墙壁或其他稳定的表面上。", "将双手放在脑后或交叉在胸前。", "启动你的核心，慢慢地将你的上半身抬离球，伸展你的背部，直到你的身体从头部到脚后跟形成一条直线。", "在顶部停顿片刻，然后慢慢将上半身放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings"], "instructions_zh_hant": ["將穩定球放在地面上，面朝下躺在上面，臀部放在球上，雙腳靠在墻壁或其他穩定的表面上。", "將雙手放在腦后或交叉在胸前。", "啟動你的核心，慢慢地將你的上半身抬離球，伸展你的背部，直到你的身體從頭部到腳后跟形成一條直線。", "在頂部停頓片刻，然后慢慢將上半身放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0977', 'exercise', 1, '{"id": "0977", "target": "delts", "name_en": "band front lateral raise", "name_zh": "弹力带前侧平举", "body_part": "shoulders", "equipment": "band", "gif_asset": "assets/fitness/videos/0977-sTg7iys.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶前側平舉", "instructions_en": ["Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing down.", "Keep your arms straight and lift the band up in front of you until your arms are parallel to the ground.", "Pause for a moment at the top, then slowly lower the band back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，将弹力带放在大腿前面，手掌朝下。", "保持双臂伸直，将弹力带举到身前，直到双臂与地面平行。", "在顶部暂停片刻，然后慢慢将弹力带放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["traps", "upper back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，將彈力帶放在大腿前面，手掌朝下。", "保持雙臂伸直，將彈力帶舉到身前，直到雙臂與地面平行。", "在頂部暫停片刻，然后慢慢將彈力帶放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3297', 'exercise', 1, '{"id": "3297", "target": "upper back", "name_en": "back lever", "name_zh": "后水平", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3297-GaSzzuh.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "后水平", "instructions_en": ["Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.", "Engage your core and pull your shoulder blades down and back.", "Bend your knees and tuck them towards your chest.", "Slowly lift your legs up, keeping them straight, until your body is parallel to the ground.", "Hold this position for a few seconds, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先，用正手握法悬挂在引体向上杆上，双手分开的距离略大于肩宽。", "启动你的核心并将肩胛骨向下拉和向后拉。", "弯曲膝盖并将其向胸部靠拢。", "慢慢抬起双腿，保持伸直，直到身体与地面平行。", "保持这个姿势几秒钟，然后慢慢地将双腿放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms", "core"], "instructions_zh_hant": ["首先，用正手握法懸掛在引體向上桿上，雙手分開的距離略大于肩寬。", "啟動你的核心并將肩胛骨向下拉和向后拉。", "彎曲膝蓋并將其向胸部靠攏。", "慢慢抬起雙腿，保持伸直，直到身體與地面平行。", "保持這個姿勢幾秒鐘，然后慢慢地將雙腿放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1405', 'exercise', 1, '{"id": "1405", "target": "lats", "name_en": "back pec stretch", "name_zh": "背后合手胸肌拉伸", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1405-chfnQnM.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "背后合手胸肌拉伸", "instructions_en": ["Stand tall with your feet shoulder-width apart.", "Extend your arms straight out in front of you, parallel to the ground.", "Cross your arms in front of your body, with your right arm over your left arm.", "Interlock your fingers and rotate your palms away from your body.", "Slowly raise your arms up and away from your body, feeling a stretch in your back and chest.", "Hold the stretch for 15-30 seconds, then release.", "Repeat on the opposite side."], "instructions_zh": ["站直，双脚分开与肩同宽。", "将双臂伸直在身前，与地面平行。", "双臂交叉在身体前方，右臂放在左臂上方。", "手指交叉，手掌旋转远离身体。", "慢慢抬起手臂并远离身体，感觉背部和胸部有拉伸感。", "保持拉伸 15-30 秒，然后放松。", "在另一侧重复。"], "secondary_muscles": ["shoulders", "chest"], "instructions_zh_hant": ["站直，雙腳分開與肩同寬。", "將雙臂伸直在身前，與地面平行。", "雙臂交叉在身體前方，右臂放在左臂上方。", "手指交叉，手掌旋轉遠離身體。", "慢慢抬起手臂并遠離身體，感覺背部和胸部有拉伸感。", "保持拉伸 15-30 秒，然后放松。", "在另一側重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1473', 'exercise', 1, '{"id": "1473", "target": "quads", "name_en": "backward jump", "name_zh": "向后跳跃", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1473-SaDOwk7.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "向后跳躍", "instructions_en": ["Stand with your feet shoulder-width apart.", "Bend your knees slightly and jump backwards, pushing off with both feet.", "Land softly on the balls of your feet, bending your knees to absorb the impact.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立。", "稍微弯曲膝盖，向后跳跃，用双脚蹬地。", "脚掌轻轻着地，弯曲膝盖以吸收冲击力。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "glutes", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立。", "稍微彎曲膝蓋，向后跳躍，用雙腳蹬地。", "腳掌輕輕著地，彎曲膝蓋以吸收沖擊力。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0020', 'exercise', 1, '{"id": "0020", "target": "quads", "name_en": "balance board", "name_zh": "平衡板", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0020-xAySMB0.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "平衡板", "instructions_en": ["Place the balance board on a flat surface.", "Step onto the balance board with one foot, ensuring it is centered.", "Slowly shift your weight onto the foot on the balance board, keeping your core engaged.", "Maintain your balance and stability as you hold the position for a desired amount of time.", "Repeat the exercise with the other foot."], "instructions_zh": ["将平衡板放在平坦的表面上。", "用一只脚踩在平衡板上，确保其居中。", "慢慢地将体重转移到平衡板上的脚上，保持核心肌群参与。", "在保持该姿势所需的时间内保持平衡和稳定。", "用另一只脚重复该练习。"], "secondary_muscles": ["calves", "hamstrings", "glutes"], "instructions_zh_hant": ["將平衡板放在平坦的表面上。", "用一只腳踩在平衡板上，確保其居中。", "慢慢地將體重轉移到平衡板上的腳上，保持核心肌群參與。", "在保持該姿勢所需的時間內保持平衡和穩定。", "用另一只腳重復該練習。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0030', 'exercise', 1, '{"id": "0030", "target": "triceps", "name_en": "barbell close-grip bench press", "name_zh": "杠铃窄握卧推", "body_part": "upper arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0030-J6Dx1Mu.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴窄握臥推", "instructions_en": ["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.", "Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.", "Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.", "Pause for a moment when the barbell touches your chest.", "Push the barbell back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，双脚平放在地上，背部紧贴长凳。", "紧紧握住杠铃，握距略窄于肩宽。", "松开杠铃并将其缓慢降低至胸部，保持肘部靠近身体。", "当杠铃触及胸部时暂停片刻。", "将杠铃推回到起始位置，完全伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["平躺在長凳上，雙腳平放在地上，背部緊貼長凳。", "緊緊握住杠鈴，握距略窄于肩寬。", "松開杠鈴并將其緩慢降低至胸部，保持肘部靠近身體。", "當杠鈴觸及胸部時暫停片刻。", "將杠鈴推回到起始位置，完全伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0968', 'exercise', 1, '{"id": "0968", "target": "biceps", "name_en": "band alternating biceps curl", "name_zh": "弹力带交替二头弯举", "body_part": "upper arms", "equipment": "band", "gif_asset": "assets/fitness/videos/0968-3omWx6P.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶交替二頭彎舉", "instructions_en": ["Stand with your feet shoulder-width apart and hold the band with an underhand grip, palms facing up.", "Keep your elbows close to your sides and slowly curl one arm up towards your shoulder, squeezing your biceps at the top.", "Lower the arm back down to the starting position and repeat with the other arm.", "Continue alternating arms for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，反手握住弹力带，手掌朝上。", "保持肘部靠近身体两侧，慢慢地将一只手臂向肩膀弯曲，在顶部挤压二头肌。", "将手臂放回起始位置，然后用另一只手臂重复此动作。", "继续交替手臂进行所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，反手握住彈力帶，手掌朝上。", "保持肘部靠近身體兩側，慢慢地將一只手臂向肩膀彎曲，在頂部擠壓二頭肌。", "將手臂放回起始位置，然后用另一只手臂重復此動作。", "繼續交替手臂進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0969', 'exercise', 1, '{"id": "0969", "target": "abs", "name_en": "band alternating v-up", "name_zh": "弹力带交替两头起", "body_part": "waist", "equipment": "band", "gif_asset": "assets/fitness/videos/0969-ztAa1RK.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶交替兩頭起", "instructions_en": ["Lie flat on your back with your legs straight and your arms extended overhead, holding the band.", "Engage your abs and lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes.", "As you lower your legs and upper body back down, switch the position of your legs, crossing one over the other.", "Repeat the movement, alternating the position of your legs with each repetition.", "Continue for the desired number of repetitions."], "instructions_zh": ["平躺，双腿伸直，手臂伸过头顶，握住弹力带。", "收紧腹肌，同时将双腿和上半身抬离地面，将双手伸向脚趾。", "当你降低双腿和上半身时，交换双腿的位置，将一条腿交叉在另一条腿上。", "重复该动作，每次重复时交替变换双腿的位置。", "继续进行所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["平躺，雙腿伸直，手臂伸過頭頂，握住彈力帶。", "收緊腹肌，同時將雙腿和上半身抬離地面，將雙手伸向腳趾。", "當你降低雙腿和上半身時，交換雙腿的位置，將一條腿交叉在另一條腿上。", "重復該動作，每次重復時交替變換雙腿的位置。", "繼續進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0970', 'exercise', 1, '{"id": "0970", "target": "lats", "name_en": "band assisted pull-up", "name_zh": "弹力带辅助引体向上", "body_part": "back", "equipment": "band", "gif_asset": "assets/fitness/videos/0970-r1XNRYB.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶輔助引體向上", "instructions_en": ["Attach the band to a pull-up bar or sturdy anchor point.", "Step onto the band and grip the bar with your palms facing away from you, hands slightly wider than shoulder-width apart.", "Hang with your arms fully extended, keeping your core engaged and your shoulders down and back.", "Pull your body up towards the bar by squeezing your shoulder blades together and driving your elbows down towards your hips.", "Continue pulling until your chin is above the bar, then slowly lower yourself back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将弹力带固定在上拉杆或坚固的锚点上。", "踏上弹力带，手掌背向自己，握住杠铃，双手之间的距离略宽于肩宽。", "双臂完全伸展，保持核心收紧，肩膀向下并向后倾斜。", "将肩胛骨挤压在一起并将肘部向下推向臀部，将身体向上拉向杠铃杆。", "继续拉，直到下巴高于杠铃，然后慢慢降低回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["將彈力帶固定在上拉桿或堅固的錨點上。", "踏上彈力帶，手掌背向自己，握住杠鈴，雙手之間的距離略寬于肩寬。", "雙臂完全伸展，保持核心收緊，肩膀向下并向后傾斜。", "將肩胛骨擠壓在一起并將肘部向下推向臀部，將身體向上拉向杠鈴桿。", "繼續拉，直到下巴高于杠鈴，然后慢慢降低回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0971', 'exercise', 1, '{"id": "0971", "target": "abs", "name_en": "band assisted wheel rollerout", "name_zh": "弹力带辅助健腹轮前推", "body_part": "waist", "equipment": "band", "gif_asset": "assets/fitness/videos/0971-zhF9lW4.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶輔助健腹輪前推", "instructions_en": ["Kneel on the floor and hold the handles of the band with both hands, palms facing down.", "Place the band on the ground in front of you and position your hands shoulder-width apart.", "Engage your core and slowly roll the wheel forward, extending your body as far as you can while maintaining control.", "Pause for a moment at the furthest point, then slowly roll the wheel back towards your knees to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["跪在地板上，双手握住弹力带的手柄，手掌朝下。", "将弹力带放在您面前的地面上，双手分开与肩同宽。", "启动你的核心并缓慢地向前滚动轮子，在保持控制的同时尽可能地伸展你的身体。", "在最远点暂停片刻，然后慢慢地将轮子向膝盖方向滚动，回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["lower back"], "instructions_zh_hant": ["跪在地板上，雙手握住彈力帶的手柄，手掌朝下。", "將彈力帶放在您面前的地面上，雙手分開與肩同寬。", "啟動你的核心并緩慢地向前滾動輪子，在保持控制的同時盡可能地伸展你的身體。", "在最遠點暫停片刻，然后慢慢地將輪子向膝蓋方向滾動，回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1254', 'exercise', 1, '{"id": "1254", "target": "pectorals", "name_en": "band bench press", "name_zh": "弹力带卧推", "body_part": "chest", "equipment": "band", "gif_asset": "assets/fitness/videos/1254-khlHMqs.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶臥推", "instructions_en": ["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.", "Grasp the band handles with an overhand grip, slightly wider than shoulder-width apart.", "Extend your arms fully, pushing the bands away from your chest.", "Slowly lower the bands back down to your chest, keeping your elbows at a 90-degree angle.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，双脚平放在地上，背部紧贴长凳。", "正手握住带子手柄，间距略宽于肩宽。", "充分伸展双臂，将弹力带推离胸部。", "慢慢将弹力带放回到胸部，保持肘部呈 90 度角。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["平躺在長凳上，雙腳平放在地上，背部緊貼長凳。", "正手握住帶子手柄，間距略寬于肩寬。", "充分伸展雙臂，將彈力帶推離胸部。", "慢慢將彈力帶放回到胸部，保持肘部呈 90 度角。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0980', 'exercise', 1, '{"id": "0980", "target": "glutes", "name_en": "band bent-over hip extension", "name_zh": "弹力带俯身髋伸展", "body_part": "upper legs", "equipment": "band", "gif_asset": "assets/fitness/videos/0980-wSScovH.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶俯身髖伸展", "instructions_en": ["Attach the band to a sturdy anchor point at ankle height.", "Stand facing away from the anchor point with your feet shoulder-width apart.", "Step back to create tension in the band, keeping your knees slightly bent.", "Hinge at the hips and lean forward, maintaining a neutral spine.", "Extend your right leg straight back, squeezing your glutes at the top.", "Lower your right leg back down and repeat with the left leg.", "Continue alternating legs for the desired number of repetitions."], "instructions_zh": ["将带子固定在脚踝高度的坚固锚点上。", "背对锚点站立，双脚与肩同宽。", "向后退一步，在弹力带上产生张力，保持膝盖稍微弯曲。", "铰接臀部并向前倾斜，保持脊柱中立。", "将右腿向后伸直，在顶部挤压臀部。", "将右腿放回原位，然后换左腿重复此动作。", "继续交替双腿达到所需的重复次数。"], "secondary_muscles": ["hamstrings", "lower back"], "instructions_zh_hant": ["將帶子固定在腳踝高度的堅固錨點上。", "背對錨點站立，雙腳與肩同寬。", "向后退一步，在彈力帶上產生張力，保持膝蓋稍微彎曲。", "鉸接臀部并向前傾斜，保持脊柱中立。", "將右腿向后伸直，在頂部擠壓臀部。", "將右腿放回原位，然后換左腿重復此動作。", "繼續交替雙腿達到所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0972', 'exercise', 1, '{"id": "0972", "target": "abs", "name_en": "band bicycle crunch", "name_zh": "弹力带自行车卷腹", "body_part": "waist", "equipment": "band", "gif_asset": "assets/fitness/videos/0972-tZkGYZ9.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶自行車卷腹", "instructions_en": ["Lie flat on your back with your hands behind your head and your knees bent.", "Lift your feet off the ground and bring your right knee towards your chest while simultaneously twisting your torso to bring your left elbow towards your right knee.", "Straighten your right leg while bringing your left knee towards your chest and twisting your torso to bring your right elbow towards your left knee.", "Continue alternating the twisting motion, as if you are pedaling a bicycle, while keeping your core engaged throughout the movement.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，双手放在脑后，膝盖弯曲。", "将脚抬离地面，将右膝盖靠近胸部，同时扭转躯干，将左肘靠近右膝盖。", "伸直右腿，同时将左膝靠近胸部，并扭转躯干，使右肘靠近左膝。", "继续交替扭转运动，就像踩自行车一样，同时在整个运动过程中保持核心参与。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors", "obliques"], "instructions_zh_hant": ["平躺，雙手放在腦后，膝蓋彎曲。", "將腳抬離地面，將右膝蓋靠近胸部，同時扭轉軀幹，將左肘靠近右膝蓋。", "伸直右腿，同時將左膝靠近胸部，并扭轉軀幹，使右肘靠近左膝。", "繼續交替扭轉運動，就像踩自行車一樣，同時在整個運動過程中保持核心參與。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0974', 'exercise', 1, '{"id": "0974", "target": "lats", "name_en": "band close-grip pulldown", "name_zh": "弹力带窄握下拉", "body_part": "back", "equipment": "band", "gif_asset": "assets/fitness/videos/0974-DptumMx.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶窄握下拉", "instructions_en": ["Attach the band to a high anchor point, such as a pull-up bar or sturdy beam.", "Stand facing the anchor point and grab the band with an underhand grip, hands shoulder-width apart.", "Step back to create tension in the band, keeping your feet hip-width apart.", "Engage your core and keep your back straight as you pull the band down towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the bottom of the movement, then slowly release the band back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将弹力带固定在较高的锚点上，例如上拉杆或坚固的横梁。", "面向锚点站立，用反手抓住弹力带，双手与肩同宽。", "后退一步，在弹力带上产生张力，双脚分开与臀部同宽。", "当你将弹力带向下拉向胸部时，收紧你的核心并保持背部挺直，将肩胛骨挤压在一起。", "在动作底部暂停片刻，然后慢慢松开弹力带回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["將彈力帶固定在較高的錨點上，例如上拉桿或堅固的橫梁。", "面向錨點站立，用反手抓住彈力帶，雙手與肩同寬。", "后退一步，在彈力帶上產生張力，雙腳分開與臀部同寬。", "當你將彈力帶向下拉向胸部時，收緊你的核心并保持背部挺直，將肩胛骨擠壓在一起。", "在動作底部暫停片刻，然后慢慢松開彈力帶回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0672', 'exercise', 1, '{"id": "0672", "target": "triceps", "name_en": "reverse dip", "name_zh": "反向臂屈伸", "body_part": "upper arms", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0672-NZ5Qqkz.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "反向臂屈伸", "instructions_en": ["Position yourself between two parallel bars with your arms fully extended and your body straight.", "Lower your body by bending your elbows until your upper arms are parallel to the ground.", "Pause for a moment, then push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将自己定位在两个双杠之间，双臂完全伸展，身体伸直。", "弯曲肘部降低身体，直到上臂与地面平行。", "暂停片刻，然后伸直手臂，将自己推回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["將自己定位在兩個雙杠之間，雙臂完全伸展，身體伸直。", "彎曲肘部降低身體，直到上臂與地面平行。", "暫停片刻，然后伸直手臂，將自己推回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0975', 'exercise', 1, '{"id": "0975", "target": "triceps", "name_en": "band close-grip push-up", "name_zh": "弹力带窄握俯卧撑", "body_part": "upper arms", "equipment": "band", "gif_asset": "assets/fitness/videos/0975-ufaxB52.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶窄握俯臥撐", "instructions_en": ["Place a band around your upper arms, just above the elbows.", "Assume a push-up position with your hands directly under your shoulders and your body in a straight line from head to heels.", "Bend your elbows and lower your chest towards the ground, keeping your elbows close to your sides.", "Push through your palms to extend your arms and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将一条带子绕在你的上臂上，就在肘部上方。", "采取俯卧撑姿势，双手直接放在肩膀下方，身体从头到脚跟呈一条直线。", "弯曲肘部，将胸部降低到地面，保持肘部靠近身体两侧。", "推动手掌以伸展手臂并返回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["將一條帶子繞在你的上臂上，就在肘部上方。", "采取俯臥撐姿勢，雙手直接放在肩膀下方，身體從頭到腳跟呈一條直線。", "彎曲肘部，將胸部降低到地面，保持肘部靠近身體兩側。", "推動手掌以伸展手臂并返回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0976', 'exercise', 1, '{"id": "0976", "target": "biceps", "name_en": "band concentration curl", "name_zh": "弹力带集中弯举", "body_part": "upper arms", "equipment": "band", "gif_asset": "assets/fitness/videos/0976-kmVVAfu.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶集中彎舉", "instructions_en": ["Sit on a bench or chair with your legs spread apart and your feet flat on the ground.", "Hold one end of the band in your hand and step on the other end with your foot on the same side.", "Lean forward slightly and rest your elbow on the inside of your thigh, just above the knee.", "With your palm facing up, slowly curl your hand towards your shoulder, keeping your upper arm stationary.", "Pause for a moment at the top, then slowly lower your hand back down to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["坐在长凳或椅子上，双腿分开，双脚平放在地上。", "用手握住带子的一端，用脚踩在另一端上，同时将脚放在同一侧。", "稍微向前倾，将肘部放在大腿内侧，膝盖上方。", "手掌朝上，慢慢地将手向肩膀弯曲，保持上臂静止。", "在顶部暂停片刻，然后慢慢将手放回起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在長凳或椅子上，雙腿分開，雙腳平放在地上。", "用手握住帶子的一端，用腳踩在另一端上，同時將腳放在同一側。", "稍微向前傾，將肘部放在大腿內側，膝蓋上方。", "手掌朝上，慢慢地將手向肩膀彎曲，保持上臂靜止。", "在頂部暫停片刻，然后慢慢將手放回起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3117', 'exercise', 1, '{"id": "3117", "target": "lats", "name_en": "band fixed back close grip pulldown", "name_zh": "弹力带固定背部窄握下拉", "body_part": "back", "equipment": "band", "gif_asset": "assets/fitness/videos/3117-4LoWllp.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶固定背部窄握下拉", "instructions_en": ["Attach the band to a fixed point above you, such as a pull-up bar or sturdy beam.", "Sit down on a bench or chair facing the band, with your feet flat on the ground and your knees bent.", "Grasp the band with a close grip, palms facing towards you.", "Keep your back straight and engage your core.", "Pull the band down towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the bottom of the movement, feeling the contraction in your lats.", "Slowly release the band back to the starting position, maintaining control throughout the movement.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将弹力带固定在您上方的固定点上，例如上拉杆或坚固的横梁。", "坐在面向乐队的长凳或椅子上，双脚平放在地上，膝盖弯曲。", "紧紧握住弹力带，手掌朝向您。", "保持背部挺直并启动核心肌群。", "将弹力带向下拉向胸部，将肩胛骨挤压在一起。", "在动作的底部暂停片刻，感受背阔肌的收缩。", "慢慢地将弹力带释放回起始位置，在整个运动过程中保持控制。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["將彈力帶固定在您上方的固定點上，例如上拉桿或堅固的橫梁。", "坐在面向樂隊的長凳或椅子上，雙腳平放在地上，膝蓋彎曲。", "緊緊握住彈力帶，手掌朝向您。", "保持背部挺直并啟動核心肌群。", "將彈力帶向下拉向胸部，將肩胛骨擠壓在一起。", "在動作的底部暫停片刻，感受背闊肌的收縮。", "慢慢地將彈力帶釋放回起始位置，在整個運動過程中保持控制。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3116', 'exercise', 1, '{"id": "3116", "target": "lats", "name_en": "band fixed back underhand pulldown", "name_zh": "弹力带固定背部反握下拉", "body_part": "back", "equipment": "band", "gif_asset": "assets/fitness/videos/3116-ZH68exZ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶固定背部反握下拉", "instructions_en": ["Attach the band to a sturdy anchor point above your head.", "Stand facing the anchor point with your feet shoulder-width apart.", "Grasp the band with an underhand grip, hands slightly wider than shoulder-width apart.", "Step back to create tension in the band, keeping your arms fully extended.", "Engage your core and squeeze your shoulder blades together.", "Pull the band down towards your chest, leading with your elbows.", "Pause for a moment at the bottom of the movement, feeling the contraction in your lats.", "Slowly release the tension in the band and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将带子固定在头顶上方坚固的锚点上。", "面向锚点站立，双脚分开与肩同宽。", "反手握住弹力带，双手间距略宽于肩宽。", "后退一步，在弹力带上产生张力，保持手臂完全伸展。", "启动你的核心并将肩胛骨挤压在一起。", "将弹力带向下拉向胸部，用肘部引导。", "在动作的底部暂停片刻，感受背阔肌的收缩。", "慢慢释放带子的张力并返回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "rhomboids", "rear deltoids"], "instructions_zh_hant": ["將帶子固定在頭頂上方堅固的錨點上。", "面向錨點站立，雙腳分開與肩同寬。", "反手握住彈力帶，雙手間距略寬于肩寬。", "后退一步，在彈力帶上產生張力，保持手臂完全伸展。", "啟動你的核心并將肩胛骨擠壓在一起。", "將彈力帶向下拉向胸部，用肘部引導。", "在動作的底部暫停片刻，感受背闊肌的收縮。", "慢慢釋放帶子的張力并返回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0978', 'exercise', 1, '{"id": "0978", "target": "delts", "name_en": "band front raise", "name_zh": "弹力带前平举", "body_part": "shoulders", "equipment": "band", "gif_asset": "assets/fitness/videos/0978-TFA88iB.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶前平舉", "instructions_en": ["Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing down.", "Keep your arms straight and slowly raise them forward until they are parallel to the ground.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，将弹力带放在大腿前面，手掌朝下。", "保持手臂伸直，慢慢向前举起，直到与地面平行。", "在顶部暂停片刻，然后慢慢将手臂放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "upper back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，將彈力帶放在大腿前面，手掌朝下。", "保持手臂伸直，慢慢向前舉起，直到與地面平行。", "在頂部暫停片刻，然后慢慢將手臂放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1408', 'exercise', 1, '{"id": "1408", "target": "glutes", "name_en": "band hip lift", "name_zh": "弹力带提髋", "body_part": "upper legs", "equipment": "band", "gif_asset": "assets/fitness/videos/1408-E4R8Hz1.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶提髖", "instructions_en": ["Lie on your back with your knees bent and feet flat on the ground.", "Place a resistance band just above your knees.", "Engage your glutes and core muscles.", "Press your heels into the ground and lift your hips off the floor, squeezing your glutes at the top.", "Pause for a moment at the top, then slowly lower your hips back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["仰卧，膝盖弯曲，双脚平放在地上。", "将阻力带放在膝盖上方。", "调动你的臀肌和核心肌肉。", "将脚后跟压入地面，将臀部抬离地板，在顶部挤压臀部。", "在顶部暂停片刻，然后慢慢将臀部放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "quadriceps"], "instructions_zh_hant": ["仰臥，膝蓋彎曲，雙腳平放在地上。", "將阻力帶放在膝蓋上方。", "調動你的臀肌和核心肌肉。", "將腳后跟壓入地面，將臀部抬離地板，在頂部擠壓臀部。", "在頂部暫停片刻，然后慢慢將臀部放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0979', 'exercise', 1, '{"id": "0979", "target": "abs", "name_en": "band horizontal pallof press", "name_zh": "弹力带水平帕洛夫抗旋转推举", "body_part": "waist", "equipment": "band", "gif_asset": "assets/fitness/videos/0979-9pa4H5m.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶水平帕洛夫抗旋轉推舉", "instructions_en": ["Attach the band to a sturdy anchor point at waist height.", "Stand perpendicular to the anchor point with your feet shoulder-width apart.", "Grasp the band handle with both hands and step away from the anchor point to create tension in the band.", "Bring your hands to your chest, keeping your elbows bent and close to your body.", "Engage your core and maintain a stable stance.", "Extend your arms straight out in front of you, pushing the band away from your body.", "Hold the extended position for a few seconds, focusing on maintaining tension in your core.", "Slowly bring your hands back to your chest, resisting the pull of the band.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将带子固定在腰部高度的坚固锚点上。", "垂直于锚点站立，双脚分开与肩同宽。", "用双手抓住带子手柄并远离锚点以在带子中产生张力。", "将双手放在胸前，保持肘部弯曲并靠近身体。", "调动你的核心并保持稳定的姿势。", "将手臂伸直至前方，将弹力带推离身体。", "保持伸展姿势几秒钟，专注于保持核心紧张。", "慢慢地将双手放回胸前，抵抗弹力带的拉力。", "重复所需的重复次数。"], "secondary_muscles": ["obliques", "glutes"], "instructions_zh_hant": ["將帶子固定在腰部高度的堅固錨點上。", "垂直于錨點站立，雙腳分開與肩同寬。", "用雙手抓住帶子手柄并遠離錨點以在帶子中產生張力。", "將雙手放在胸前，保持肘部彎曲并靠近身體。", "調動你的核心并保持穩定的姿勢。", "將手臂伸直至前方，將彈力帶推離身體。", "保持伸展姿勢幾秒鐘，專注于保持核心緊張。", "慢慢地將雙手放回胸前，抵抗彈力帶的拉力。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0981', 'exercise', 1, '{"id": "0981", "target": "abs", "name_en": "band jack knife sit-up", "name_zh": "弹力带折刀式仰卧起坐", "body_part": "waist", "equipment": "band", "gif_asset": "assets/fitness/videos/0981-KCBKjma.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶折刀式仰臥起坐", "instructions_en": ["Lie flat on your back with your legs straight and your arms extended overhead, holding the band.", "Engage your abs and lift your legs and upper body simultaneously, bringing your hands towards your feet.", "Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，双腿伸直，手臂伸过头顶，握住弹力带。", "收紧腹肌，同时抬起双腿和上半身，将双手移向脚部。", "在顶部停顿片刻，然后慢慢放下双腿和上半身回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["平躺，雙腿伸直，手臂伸過頭頂，握住彈力帶。", "收緊腹肌，同時抬起雙腿和上半身，將雙手移向腳部。", "在頂部停頓片刻，然后慢慢放下雙腿和上半身回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0983', 'exercise', 1, '{"id": "0983", "target": "lats", "name_en": "band kneeling one arm pulldown", "name_zh": "弹力带跪姿单臂下拉", "body_part": "back", "equipment": "band", "gif_asset": "assets/fitness/videos/0983-pmnrOp0.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶跪姿單臂下拉", "instructions_en": ["Attach the band to a sturdy anchor point above your head.", "Kneel down and hold the band with one hand, palm facing down.", "Extend your arm fully overhead, keeping your elbow slightly bent.", "Engage your lat muscles and pull the band down towards your side, bringing your elbow towards your ribcage.", "Pause for a moment at the bottom, then slowly release the tension and return to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["将带子固定在头顶上方坚固的锚点上。", "跪下，用一只手握住弹力带，手掌朝下。", "将手臂完全伸过头顶，保持肘部稍微弯曲。", "调动你的背阔肌，将弹力带拉向你的一侧，使你的肘部靠近你的胸腔。", "在底部停顿片刻，然后慢慢释放张力，回到起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["biceps", "rhomboids"], "instructions_zh_hant": ["將帶子固定在頭頂上方堅固的錨點上。", "跪下，用一只手握住彈力帶，手掌朝下。", "將手臂完全伸過頭頂，保持肘部稍微彎曲。", "調動你的背闊肌，將彈力帶拉向你的一側，使你的肘部靠近你的胸腔。", "在底部停頓片刻，然后慢慢釋放張力，回到起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0985', 'exercise', 1, '{"id": "0985", "target": "abs", "name_en": "band kneeling twisting crunch", "name_zh": "弹力带跪姿转体卷腹", "body_part": "waist", "equipment": "band", "gif_asset": "assets/fitness/videos/0985-225x2Vd.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶跪姿轉體卷腹", "instructions_en": ["Attach the band to a sturdy anchor point at waist height.", "Kneel down facing away from the anchor point and hold the band with both hands, keeping your elbows bent and close to your sides.", "Engage your abs and slowly twist your torso to one side, bringing your hands towards your opposite hip.", "Pause for a moment, then slowly return to the starting position.", "Repeat on the other side.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["将带子固定在腰部高度的坚固锚点上。", "面向远离锚点的方向跪下，用双手握住弹力带，保持肘部弯曲并靠近身体两侧。", "收紧腹肌，慢慢地将躯干扭向一侧，将双手移向另一侧的臀部。", "暂停片刻，然后慢慢回到起始位置。", "在另一侧重复。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["obliques"], "instructions_zh_hant": ["將帶子固定在腰部高度的堅固錨點上。", "面向遠離錨點的方向跪下，用雙手握住彈力帶，保持肘部彎曲并靠近身體兩側。", "收緊腹肌，慢慢地將軀幹扭向一側，將雙手移向另一側的臀部。", "暫停片刻，然后慢慢回到起始位置。", "在另一側重復。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0984', 'exercise', 1, '{"id": "0984", "target": "glutes", "name_en": "band lying hip internal rotation", "name_zh": "弹力带卧姿髋部内旋", "body_part": "upper legs", "equipment": "band", "gif_asset": "assets/fitness/videos/0984-vIICElP.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶臥姿髖部內旋", "instructions_en": ["Lie on your back with your legs straight and a resistance band looped around your feet.", "Bend your knees and bring them towards your chest, keeping your feet together.", "Slowly rotate your knees outwards, away from each other, while keeping your feet together.", "Pause for a moment at the end of the rotation, then slowly return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["仰卧，双腿伸直，将阻力带绕在脚上。", "弯曲膝盖并将其靠近胸部，双脚并拢。", "慢慢向外旋转膝盖，使膝盖彼此远离，同时保持双脚并拢。", "旋转结束时暂停片刻，然后慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "quadriceps"], "instructions_zh_hant": ["仰臥，雙腿伸直，將阻力帶繞在腳上。", "彎曲膝蓋并將其靠近胸部，雙腳并攏。", "慢慢向外旋轉膝蓋，使膝蓋彼此遠離，同時保持雙腳并攏。", "旋轉結束時暫停片刻，然后慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1002', 'exercise', 1, '{"id": "1002", "target": "abs", "name_en": "band lying straight leg raise", "name_zh": "弹力带卧姿直腿举腿", "body_part": "waist", "equipment": "band", "gif_asset": "assets/fitness/videos/1002-bbLR7fB.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶臥姿直腿舉腿", "instructions_en": ["Lie flat on your back with your legs straight and your feet together.", "Place the band around the arches of your feet and hold the ends of the band with your hands.", "Engaging your abs, lift both legs off the ground until they are perpendicular to the floor.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，双腿伸直，双脚并拢。", "将带子放在脚弓周围，并用手握住带子的末端。", "收紧腹肌，将双腿抬离地面，直到它们垂直于地板。", "在顶部暂停片刻，然后慢慢将双腿放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["平躺，雙腿伸直，雙腳并攏。", "將帶子放在腳弓周圍，并用手握住帶子的末端。", "收緊腹肌，將雙腿抬離地面，直到它們垂直于地板。", "在頂部暫停片刻，然后慢慢將雙腿放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0986', 'exercise', 1, '{"id": "0986", "target": "biceps", "name_en": "band one arm overhead biceps curl", "name_zh": "弹力带单臂过顶二头弯举", "body_part": "upper arms", "equipment": "band", "gif_asset": "assets/fitness/videos/0986-UNAB8ak.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶單臂過頂二頭彎舉", "instructions_en": ["Stand with your feet shoulder-width apart and place one end of the band under your foot.", "Hold the other end of the band with your arm fully extended overhead, palm facing forward.", "Keeping your upper arm stationary, curl your forearm towards your shoulder, squeezing your biceps.", "Pause for a moment at the top, then slowly lower your forearm back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["双脚分开与肩同宽站立，将弹力带的一端放在脚下。", "握住弹力带的另一端，手臂完全伸过头顶，手掌朝前。", "保持上臂静止，将前臂向肩膀弯曲，挤压二头肌。", "在顶部停顿片刻，然后慢慢将前臂放回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["forearms", "shoulders"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，將彈力帶的一端放在腳下。", "握住彈力帶的另一端，手臂完全伸過頭頂，手掌朝前。", "保持上臂靜止，將前臂向肩膀彎曲，擠壓二頭肌。", "在頂部停頓片刻，然后慢慢將前臂放回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1014', 'exercise', 1, '{"id": "1014", "target": "abs", "name_en": "band v-up", "name_zh": "弹力带两头起", "body_part": "waist", "equipment": "band", "gif_asset": "assets/fitness/videos/1014-H6ETwO9.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶兩頭起", "instructions_en": ["Lie flat on your back with your legs straight and your arms extended overhead, holding the band.", "Engaging your abs, lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes.", "Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，双腿伸直，手臂伸过头顶，握住弹力带。", "收紧腹肌，同时将双腿和上半身抬离地面，双手伸向脚趾。", "在顶部停顿片刻，然后慢慢放下双腿和上半身回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["平躺，雙腿伸直，手臂伸過頭頂，握住彈力帶。", "收緊腹肌，同時將雙腿和上半身抬離地面，雙手伸向腳趾。", "在頂部停頓片刻，然后慢慢放下雙腿和上半身回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0987', 'exercise', 1, '{"id": "0987", "target": "quads", "name_en": "band one arm single leg split squat", "name_zh": "弹力带单臂单腿分腿蹲", "body_part": "upper legs", "equipment": "band", "gif_asset": "assets/fitness/videos/0987-arsYEd3.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶單臂單腿分腿蹲", "instructions_en": ["Stand with your feet hip-width apart and place a resistance band around your ankles.", "Extend one leg forward and rest the top of your foot on a bench or step behind you.", "Hold onto a support with one hand for balance.", "Bend your standing leg and lower your body down into a squat position, keeping your knee in line with your toes.", "Push through your heel to return to the starting position.", "Repeat for the desired number of repetitions, then switch legs."], "instructions_zh": ["双脚分开站立，与臀部同宽，将阻力带绕在脚踝上。", "向前伸出一条腿，将脚尖放在长凳上或身后的一步上。", "用一只手握住支撑物以保持平衡。", "弯曲站立的腿，将身体降低到蹲姿，保持膝盖与脚趾在一条直线上。", "推动脚后跟返回到起始位置。", "重复所需的重复次数，然后换腿。"], "secondary_muscles": ["glutes", "hamstrings"], "instructions_zh_hant": ["雙腳分開站立，與臀部同寬，將阻力帶繞在腳踝上。", "向前伸出一條腿，將腳尖放在長凳上或身后的一步上。", "用一只手握住支撐物以保持平衡。", "彎曲站立的腿，將身體降低到蹲姿，保持膝蓋與腳趾在一條直線上。", "推動腳后跟返回到起始位置。", "重復所需的重復次數，然后換腿。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0988', 'exercise', 1, '{"id": "0988", "target": "upper back", "name_en": "band one arm standing low row", "name_zh": "弹力带单臂站姿低位划船", "body_part": "back", "equipment": "band", "gif_asset": "assets/fitness/videos/0988-km0sQC0.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶單臂站姿低位劃船", "instructions_en": ["Attach the band to a stable anchor point at waist height.", "Stand facing the anchor point with your feet shoulder-width apart.", "Hold the band with one hand, palm facing inward, and step back to create tension in the band.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Pull the band towards your waist, squeezing your shoulder blades together.", "Pause for a moment at the top of the movement, then slowly release the band back to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["将带子固定在腰部高度的稳定锚点上。", "面向锚点站立，双脚分开与肩同宽。", "用一只手握住弹力带，手掌朝内，然后后退以在弹力带中产生张力。", "稍微弯曲膝盖，髋部向前转动，保持背部挺直。", "将带子拉向腰部，将肩胛骨挤压在一起。", "在动作的最高点暂停片刻，然后慢慢松开弹力带回到起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["biceps", "shoulders"], "instructions_zh_hant": ["將帶子固定在腰部高度的穩定錨點上。", "面向錨點站立，雙腳分開與肩同寬。", "用一只手握住彈力帶，手掌朝內，然后后退以在彈力帶中產生張力。", "稍微彎曲膝蓋，髖部向前轉動，保持背部挺直。", "將帶子拉向腰部，將肩胛骨擠壓在一起。", "在動作的最高點暫停片刻，然后慢慢松開彈力帶回到起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0989', 'exercise', 1, '{"id": "0989", "target": "pectorals", "name_en": "band one arm twisting chest press", "name_zh": "弹力带单臂转体推胸", "body_part": "chest", "equipment": "band", "gif_asset": "assets/fitness/videos/0989-c16nYGA.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶單臂轉體推胸", "instructions_en": ["Attach the band to a sturdy anchor point at chest height.", "Stand with your side facing the anchor point and grab the band with one hand.", "Step away from the anchor point to create tension in the band.", "Position your feet shoulder-width apart and slightly bend your knees.", "Bring your hand holding the band across your body, towards the opposite shoulder.", "While maintaining tension in the band, push your hand forward and away from your body, extending your arm.", "Slowly return to the starting position and repeat for the desired number of repetitions.", "Switch sides and repeat the exercise with the other hand."], "instructions_zh": ["将带子固定在胸部高度的坚固锚点上。", "站立，一侧面向锚点，用一只手抓住带子。", "远离锚点以在带子中产生张力。", "将双脚分开与肩同宽，并稍微弯曲膝盖。", "将握住弹力带的手穿过身体，朝向对侧的肩膀。", "在保持弹力带张力的同时，将手向前推离身体，伸展手臂。", "慢慢回到起始位置并重复所需的重复次数。", "换边并用另一只手重复练习。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["將帶子固定在胸部高度的堅固錨點上。", "站立，一側面向錨點，用一只手抓住帶子。", "遠離錨點以在帶子中產生張力。", "將雙腳分開與肩同寬，并稍微彎曲膝蓋。", "將握住彈力帶的手穿過身體，朝向對側的肩膀。", "在保持彈力帶張力的同時，將手向前推離身體，伸展手臂。", "慢慢回到起始位置并重復所需的重復次數。", "換邊并用另一只手重復練習。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0990', 'exercise', 1, '{"id": "0990", "target": "upper back", "name_en": "band one arm twisting seated row", "name_zh": "弹力带单臂转体坐姿划船", "body_part": "back", "equipment": "band", "gif_asset": "assets/fitness/videos/0990-DKBwJrL.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶單臂轉體坐姿劃船", "instructions_en": ["Sit on a bench or chair with your feet flat on the ground and your back straight.", "Hold the band with one hand and extend your arm fully in front of you.", "Keeping your back straight, pull the band towards your body by bending your elbow and squeezing your shoulder blades together.", "At the same time, twist your torso towards the side of the pulling arm.", "Pause for a moment at the top, then slowly release the tension in the band and return to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."], "instructions_zh": ["坐在长凳或椅子上，双脚平放在地上，背部挺直。", "用一只手握住弹力带，并将手臂完全伸到身前。", "保持背部挺直，弯曲肘部并将肩胛骨挤压在一起，将弹力带拉向身体。", "同时，将躯干向拉动手臂的一侧扭转。", "在顶部暂停片刻，然后慢慢释放弹力带的张力并返回到起始位置。", "重复所需的重复次数，然后换到另一只手臂。"], "secondary_muscles": ["biceps", "shoulders"], "instructions_zh_hant": ["坐在長凳或椅子上，雙腳平放在地上，背部挺直。", "用一只手握住彈力帶，并將手臂完全伸到身前。", "保持背部挺直，彎曲肘部并將肩胛骨擠壓在一起，將彈力帶拉向身體。", "同時，將軀幹向拉動手臂的一側扭轉。", "在頂部暫停片刻，然后慢慢釋放彈力帶的張力并返回到起始位置。", "重復所需的重復次數，然后換到另一只手臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0991', 'exercise', 1, '{"id": "0991", "target": "glutes", "name_en": "band pull through", "name_zh": "弹力带胯下拉", "body_part": "upper legs", "equipment": "band", "gif_asset": "assets/fitness/videos/0991-VtTbiP3.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶胯下拉", "instructions_en": ["Attach a resistance band to a sturdy anchor point at ground level.", "Stand facing away from the anchor point with your feet shoulder-width apart.", "Step forward to create tension in the band, keeping your knees slightly bent.", "Hinge at the hips and push your glutes back, maintaining a slight bend in your knees.", "Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.", "Drive your hips forward and squeeze your glutes to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将阻力带连接到地面上坚固的锚点上。", "背对锚点站立，双脚与肩同宽。", "向前迈一步，在弹力带中产生张力，保持膝盖稍微弯曲。", "铰接臀部并将臀部向后推，保持膝盖轻微弯曲。", "降低躯干直到与地面平行，感觉腿筋被拉伸。", "向前推动臀部并挤压臀部以返回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "lower back"], "instructions_zh_hant": ["將阻力帶連接到地面上堅固的錨點上。", "背對錨點站立，雙腳與肩同寬。", "向前邁一步，在彈力帶中產生張力，保持膝蓋稍微彎曲。", "鉸接臀部并將臀部向后推，保持膝蓋輕微彎曲。", "降低軀幹直到與地面平行，感覺腿筋被拉伸。", "向前推動臀部并擠壓臀部以返回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0992', 'exercise', 1, '{"id": "0992", "target": "abs", "name_en": "band push sit-up", "name_zh": "弹力带推举仰卧起坐", "body_part": "waist", "equipment": "band", "gif_asset": "assets/fitness/videos/0992-zFzbBfL.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶推舉仰臥起坐", "instructions_en": ["Attach the band securely to a stable anchor point.", "Lie flat on your back with your knees bent and feet flat on the ground.", "Hold the band with both hands and extend your arms straight up towards the ceiling.", "Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将带子牢固地固定在稳定的锚点上。", "平躺，膝盖弯曲，双脚平放在地上。", "用双手握住弹力带，并将双臂伸向天花板。", "收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。", "在顶部停顿片刻，然后慢慢将上半身放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "chest"], "instructions_zh_hant": ["將帶子牢固地固定在穩定的錨點上。", "平躺，膝蓋彎曲，雙腳平放在地上。", "用雙手握住彈力帶，并將雙臂伸向天花板。", "收緊腹肌，慢慢將上半身抬離地面，向前卷曲，直到軀幹呈 45 度角。", "在頂部停頓片刻，然后慢慢將上半身放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0993', 'exercise', 1, '{"id": "0993", "target": "delts", "name_en": "band reverse fly", "name_zh": "弹力带反向飞鸟", "body_part": "shoulders", "equipment": "band", "gif_asset": "assets/fitness/videos/0993-sTfvVsG.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶反向飛鳥", "instructions_en": ["Attach the band to a stationary object at chest height.", "Stand with your feet shoulder-width apart and hold the band with both hands in front of you.", "Keep your arms straight and lift them out to the sides until they are parallel to the ground.", "Squeeze your shoulder blades together at the top of the movement.", "Slowly lower your arms back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将带子固定在胸部高度的固定物体上。", "双脚分开与肩同宽站立，双手握住弹力带放在身前。", "保持手臂伸直并将其向两侧抬起，直到与地面平行。", "在动作的最高点将肩胛骨挤压在一起。", "慢慢地将手臂放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["upper back", "trapezius"], "instructions_zh_hant": ["將帶子固定在胸部高度的固定物體上。", "雙腳分開與肩同寬站立，雙手握住彈力帶放在身前。", "保持手臂伸直并將其向兩側抬起，直到與地面平行。", "在動作的最高點將肩胛骨擠壓在一起。", "慢慢地將手臂放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0994', 'exercise', 1, '{"id": "0994", "target": "forearms", "name_en": "band reverse wrist curl", "name_zh": "弹力带反握腕弯举", "body_part": "lower arms", "equipment": "band", "gif_asset": "assets/fitness/videos/0994-Ezpnw9d.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶反握腕彎舉", "instructions_en": ["Sit on a bench or chair with your feet flat on the ground.", "Hold the band with an overhand grip, palms facing down, and wrap it around your fingers.", "Rest your forearms on your thighs, with your wrists hanging off the edge.", "Slowly curl your wrists upward, squeezing your forearms.", "Pause for a moment at the top, then slowly lower your wrists back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳或椅子上，双脚平放在地面上。", "正手握住弹力带，手掌朝下，然后将其缠绕在手指上。", "将前臂放在大腿上，手腕悬在边缘上。", "慢慢向上弯曲手腕，挤压前臂。", "在顶部暂停片刻，然后慢慢将手腕放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在長凳或椅子上，雙腳平放在地面上。", "正手握住彈力帶，手掌朝下，然后將其纏繞在手指上。", "將前臂放在大腿上，手腕懸在邊緣上。", "慢慢向上彎曲手腕，擠壓前臂。", "在頂部暫停片刻，然后慢慢將手腕放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0996', 'exercise', 1, '{"id": "0996", "target": "glutes", "name_en": "band seated hip internal rotation", "name_zh": "弹力带坐姿髋部内旋", "body_part": "upper legs", "equipment": "band", "gif_asset": "assets/fitness/videos/0996-9gbyYKk.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶坐姿髖部內旋", "instructions_en": ["Sit on a chair or bench with your back straight and feet flat on the ground.", "Place a resistance band around your thighs, just above your knees.", "Keep your knees bent at a 90-degree angle and your feet shoulder-width apart.", "Engage your glutes and slowly rotate your knees outward, pushing against the resistance of the band.", "Pause for a moment at the end of the movement, then slowly return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在椅子或长凳上，背部挺直，双脚平放在地面上。", "在大腿周围、膝盖上方放置一条阻力带。", "保持膝盖弯曲 90 度，双脚分开与肩同宽。", "收紧臀肌，慢慢向外旋转膝盖，克服弹力带的阻力。", "动作结束时暂停片刻，然后慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "quadriceps"], "instructions_zh_hant": ["坐在椅子或長凳上，背部挺直，雙腳平放在地面上。", "在大腿周圍、膝蓋上方放置一條阻力帶。", "保持膝蓋彎曲 90 度，雙腳分開與肩同寬。", "收緊臀肌，慢慢向外旋轉膝蓋，克服彈力帶的阻力。", "動作結束時暫停片刻，然后慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1011', 'exercise', 1, '{"id": "1011", "target": "abs", "name_en": "band seated twist", "name_zh": "弹力带坐姿转体", "body_part": "waist", "equipment": "band", "gif_asset": "assets/fitness/videos/1011-S1JXDAG.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶坐姿轉體", "instructions_en": ["Sit on the ground with your legs extended in front of you and your back straight.", "Wrap the band around your waist and hold the ends with both hands.", "Engage your abs and slowly twist your torso to one side, keeping your back straight and your feet on the ground.", "Pause for a moment at the end of the twist, then slowly return to the starting position.", "Repeat the twist to the other side.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["坐在地上，双腿向前伸展，背部挺直。", "将带子绕在腰上，并用双手握住两端。", "收紧腹肌，慢慢将躯干扭向一侧，保持背部挺直，双脚着地。", "扭转结束时暂停片刻，然后慢慢回到起始位置。", "重复扭转到另一侧。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["obliques"], "instructions_zh_hant": ["坐在地上，雙腿向前伸展，背部挺直。", "將帶子繞在腰上，并用雙手握住兩端。", "收緊腹肌，慢慢將軀幹扭向一側，保持背部挺直，雙腳著地。", "扭轉結束時暫停片刻，然后慢慢回到起始位置。", "重復扭轉到另一側。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0997', 'exercise', 1, '{"id": "0997", "target": "delts", "name_en": "band shoulder press", "name_zh": "弹力带肩上推举", "body_part": "shoulders", "equipment": "band", "gif_asset": "assets/fitness/videos/0997-peAeMR3.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶肩上推舉", "instructions_en": ["Stand with your feet shoulder-width apart and place the band under your feet.", "Hold the band with your palms facing forward and raise your hands to shoulder height, elbows bent.", "Press the band overhead, fully extending your arms.", "Pause for a moment at the top, then slowly lower the band back to shoulder height.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，将弹力带放在脚下。", "手掌朝前握住弹力带，将双手举至肩高，肘部弯曲。", "将弹力带压过头顶，充分伸展双臂。", "在顶部暂停片刻，然后慢慢将阻力带降低至肩部高度。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "upper back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，將彈力帶放在腳下。", "手掌朝前握住彈力帶，將雙手舉至肩高，肘部彎曲。", "將彈力帶壓過頭頂，充分伸展雙臂。", "在頂部暫停片刻，然后慢慢將阻力帶降低至肩部高度。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1018', 'exercise', 1, '{"id": "1018", "target": "traps", "name_en": "band shrug", "name_zh": "弹力带耸肩", "body_part": "back", "equipment": "band", "gif_asset": "assets/fitness/videos/1018-trmte8s.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶聳肩", "instructions_en": ["Stand with your feet shoulder-width apart and place the band under your feet, holding the ends with your hands.", "Keep your arms straight and relaxed, and let the band hang in front of your thighs.", "Engage your traps by shrugging your shoulders upward, lifting the band as high as possible.", "Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，将弹力带放在脚下，用手握住两端。", "保持手臂伸直并放松，让弹力带悬挂在大腿前面。", "向上耸肩，尽可能高地举起弹力带，以启动斜方肌。", "保持收缩一会儿，然后慢慢将肩膀放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，將彈力帶放在腳下，用手握住兩端。", "保持手臂伸直并放松，讓彈力帶懸掛在大腿前面。", "向上聳肩，盡可能高地舉起彈力帶，以啟動斜方肌。", "保持收縮一會兒，然后慢慢將肩膀放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1016', 'exercise', 1, '{"id": "1016", "target": "forearms", "name_en": "band wrist curl", "name_zh": "弹力带腕弯举", "body_part": "lower arms", "equipment": "band", "gif_asset": "assets/fitness/videos/1016-vUTfFHw.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶腕彎舉", "instructions_en": ["Sit on a bench or chair with your feet flat on the ground.", "Hold the band with both hands, palms facing up, and rest your forearms on your thighs.", "Slowly curl your wrists upward, squeezing your forearms.", "Pause for a moment at the top, then slowly lower your wrists back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳或椅子上，双脚平放在地面上。", "双手握住弹力带，手掌朝上，前臂放在大腿上。", "慢慢向上弯曲手腕，挤压前臂。", "在顶部暂停片刻，然后慢慢将手腕放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "triceps"], "instructions_zh_hant": ["坐在長凳或椅子上，雙腳平放在地面上。", "雙手握住彈力帶，手掌朝上，前臂放在大腿上。", "慢慢向上彎曲手腕，擠壓前臂。", "在頂部暫停片刻，然后慢慢將手腕放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0998', 'exercise', 1, '{"id": "0998", "target": "triceps", "name_en": "band side triceps extension", "name_zh": "弹力带侧臂屈伸", "body_part": "upper arms", "equipment": "band", "gif_asset": "assets/fitness/videos/0998-obe5LMq.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶側臂屈伸", "instructions_en": ["Stand with your feet shoulder-width apart and hold the band with both hands, palms facing down.", "Extend your arms straight out to the sides, keeping them parallel to the ground.", "Slowly bend your elbows and bring your hands towards your shoulders, keeping your upper arms still.", "Pause for a moment, then slowly extend your arms back out to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手握住弹力带，掌心朝下。", "将手臂伸直至两侧，保持与地面平行。", "慢慢弯曲肘部，将双手放在肩膀上，保持上臂不动。", "暂停片刻，然后慢慢将手臂伸回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手握住彈力帶，掌心朝下。", "將手臂伸直至兩側，保持與地面平行。", "慢慢彎曲肘部，將雙手放在肩膀上，保持上臂不動。", "暫停片刻，然后慢慢將手臂伸回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0999', 'exercise', 1, '{"id": "0999", "target": "calves", "name_en": "band single leg calf raise", "name_zh": "弹力带单腿提踵", "body_part": "lower legs", "equipment": "band", "gif_asset": "assets/fitness/videos/0999-9JprnPh.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶單腿提踵", "instructions_en": ["Stand with your feet hip-width apart and place the band around the ball of your left foot.", "Hold onto a stable object for balance if needed.", "Slowly raise your left heel off the ground, lifting your body weight onto the ball of your foot.", "Pause for a moment at the top, then slowly lower your left heel back down to the starting position.", "Repeat for the desired number of repetitions, then switch to the right leg."], "instructions_zh": ["双脚分开站立，与臀部同宽，将弹力带绕在左脚掌上。", "如果需要，请抓住一个稳定的物体以保持平衡。", "慢慢地将左脚跟抬离地面，将身体重量转移到脚掌上。", "在顶部暂停片刻，然后慢慢将左脚跟放回起始位置。", "重复所需的重复次数，然后换右腿。"], "secondary_muscles": ["ankles", "feet"], "instructions_zh_hant": ["雙腳分開站立，與臀部同寬，將彈力帶繞在左腳掌上。", "如果需要，請抓住一個穩定的物體以保持平衡。", "慢慢地將左腳跟抬離地面，將身體重量轉移到腳掌上。", "在頂部暫停片刻，然后慢慢將左腳跟放回起始位置。", "重復所需的重復次數，然后換右腿。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1000', 'exercise', 1, '{"id": "1000", "target": "calves", "name_en": "band single leg reverse calf raise", "name_zh": "弹力带单腿反向提踵", "body_part": "lower legs", "equipment": "band", "gif_asset": "assets/fitness/videos/1000-QsSQWbf.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶單腿反向提踵", "instructions_en": ["Stand with your feet hip-width apart and place the band around the ball of your foot.", "Hold onto a stable object for balance.", "Slowly raise your heel off the ground, lifting your body weight onto the ball of your foot.", "Pause for a moment at the top, then slowly lower your heel back down to the starting position.", "Repeat for the desired number of repetitions, then switch to the other leg."], "instructions_zh": ["双脚分开站立，与臀部同宽，将弹力带放在脚掌周围。", "抓住稳定的物体以保持平衡。", "慢慢地将脚跟抬离地面，将身体重量转移到脚掌上。", "在顶部暂停片刻，然后慢慢将脚跟放回起始位置。", "重复所需的重复次数，然后换另一条腿。"], "secondary_muscles": ["hamstrings", "glutes"], "instructions_zh_hant": ["雙腳分開站立，與臀部同寬，將彈力帶放在腳掌周圍。", "抓住穩定的物體以保持平衡。", "慢慢地將腳跟抬離地面，將身體重量轉移到腳掌上。", "在頂部暫停片刻，然后慢慢將腳跟放回起始位置。", "重復所需的重復次數，然后換另一條腿。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1001', 'exercise', 1, '{"id": "1001", "target": "quads", "name_en": "band single leg split squat", "name_zh": "弹力带单腿分腿蹲", "body_part": "upper legs", "equipment": "band", "gif_asset": "assets/fitness/videos/1001-y8bYM8w.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶單腿分腿蹲", "instructions_en": ["Stand with your feet hip-width apart and place a resistance band around your ankles.", "Take a big step forward with your right foot and a smaller step back with your left foot.", "Bend your knees and lower your body until your right thigh is parallel to the ground, keeping your left knee slightly above the ground.", "Push through your right heel to return to the starting position.", "Repeat on the other side."], "instructions_zh": ["双脚分开站立，与臀部同宽，将阻力带绕在脚踝上。", "右脚向前迈一大步，左脚向后退一小步。", "弯曲膝盖并降低身体，直到右大腿与地面平行，保持左膝盖略高于地面。", "推动右脚跟回到起始位置。", "在另一侧重复。"], "secondary_muscles": ["glutes", "hamstrings"], "instructions_zh_hant": ["雙腳分開站立，與臀部同寬，將阻力帶繞在腳踝上。", "右腳向前邁一大步，左腳向后退一小步。", "彎曲膝蓋并降低身體，直到右大腿與地面平行，保持左膝蓋略高于地面。", "推動右腳跟回到起始位置。", "在另一側重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1004', 'exercise', 1, '{"id": "1004", "target": "glutes", "name_en": "band squat", "name_zh": "弹力带深蹲", "body_part": "upper legs", "equipment": "band", "gif_asset": "assets/fitness/videos/1004-TUZLh71.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶深蹲", "instructions_en": ["Stand with your feet shoulder-width apart, with the band placed just above your knees.", "Keeping your chest up and core engaged, push your hips back and bend your knees to lower into a squat position.", "Make sure your knees are tracking over your toes and your weight is in your heels.", "Pause for a moment at the bottom, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开站立，与肩同宽，弹力带放在膝盖上方。", "保持挺胸、核心收紧，将臀部向后推，弯曲膝盖，形成下蹲姿势。", "确保膝盖位于脚趾上方，并且重量位于脚后跟。", "在底部停顿片刻，然后推动脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開站立，與肩同寬，彈力帶放在膝蓋上方。", "保持挺胸、核心收緊，將臀部向后推，彎曲膝蓋，形成下蹲姿勢。", "確保膝蓋位于腳趾上方，并且重量位于腳后跟。", "在底部停頓片刻，然后推動腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1003', 'exercise', 1, '{"id": "1003", "target": "glutes", "name_en": "band squat row", "name_zh": "弹力带深蹲划船", "body_part": "upper legs", "equipment": "band", "gif_asset": "assets/fitness/videos/1003-w1NOByi.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶深蹲劃船", "instructions_en": ["Attach the band to a sturdy anchor point at waist height.", "Stand facing the anchor point with your feet shoulder-width apart.", "Hold the band handles with your palms facing each other and your arms extended in front of you.", "Bend your knees and lower into a squat position, keeping your back straight and chest lifted.", "From the squat position, pull the band handles towards your body, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly release the tension and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将带子固定在腰部高度的坚固锚点上。", "面向锚点站立，双脚分开与肩同宽。", "双手握住弹力带手柄，手掌相对，双臂向前伸展。", "弯曲膝盖并蹲下，保持背部挺直，挺胸。", "从蹲姿开始，将弹力带手柄拉向身体，将肩胛骨挤压在一起。", "在最高点停顿片刻，然后慢慢释放张力，回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "quadriceps", "back"], "instructions_zh_hant": ["將帶子固定在腰部高度的堅固錨點上。", "面向錨點站立，雙腳分開與肩同寬。", "雙手握住彈力帶手柄，手掌相對，雙臂向前伸展。", "彎曲膝蓋并蹲下，保持背部挺直，挺胸。", "從蹲姿開始，將彈力帶手柄拉向身體，將肩胛骨擠壓在一起。", "在最高點停頓片刻，然后慢慢釋放張力，回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1005', 'exercise', 1, '{"id": "1005", "target": "abs", "name_en": "band standing crunch", "name_zh": "弹力带站姿卷腹", "body_part": "waist", "equipment": "band", "gif_asset": "assets/fitness/videos/1005-Kzg30R7.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶站姿卷腹", "instructions_en": ["Attach the band to a sturdy anchor point at waist height.", "Stand facing away from the anchor point with your feet shoulder-width apart.", "Hold the band with both hands and bring it up to your chest, keeping your elbows bent and close to your body.", "Engage your abs and slowly crunch forward, bringing your chest towards your knees.", "Pause for a moment at the top of the crunch, then slowly return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将带子固定在腰部高度的坚固锚点上。", "背对锚点站立，双脚与肩同宽。", "用双手握住弹力带并将其举至胸前，保持肘部弯曲并靠近身体。", "收紧腹肌，慢慢向前挺胸，使胸部靠近膝盖。", "在卷腹的最高点暂停片刻，然后慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["obliques"], "instructions_zh_hant": ["將帶子固定在腰部高度的堅固錨點上。", "背對錨點站立，雙腳與肩同寬。", "用雙手握住彈力帶并將其舉至胸前，保持肘部彎曲并靠近身體。", "收緊腹肌，慢慢向前挺胸，使胸部靠近膝蓋。", "在卷腹的最高點暫停片刻，然后慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1022', 'exercise', 1, '{"id": "1022", "target": "delts", "name_en": "band standing rear delt row", "name_zh": "弹力带站姿三角肌后束划船", "body_part": "shoulders", "equipment": "band", "gif_asset": "assets/fitness/videos/1022-tc5dYrf.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶站姿三角肌后束劃船", "instructions_en": ["Stand with your feet shoulder-width apart and place the band under your feet.", "Hold the band handles with your palms facing each other and your arms extended in front of you.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Pull the band towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly release the tension and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，将弹力带放在脚下。", "双手握住弹力带手柄，手掌相对，双臂向前伸展。", "稍微弯曲膝盖，髋部向前转动，保持背部挺直。", "将弹力带拉向胸部，将肩胛骨挤压在一起。", "在最高点停顿片刻，然后慢慢释放张力，回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["trapezius", "rhomboids", "biceps"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，將彈力帶放在腳下。", "雙手握住彈力帶手柄，手掌相對，雙臂向前伸展。", "稍微彎曲膝蓋，髖部向前轉動，保持背部挺直。", "將彈力帶拉向胸部，將肩胛骨擠壓在一起。", "在最高點停頓片刻，然后慢慢釋放張力，回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1007', 'exercise', 1, '{"id": "1007", "target": "abs", "name_en": "band standing twisting crunch", "name_zh": "弹力带站姿转体卷腹", "body_part": "waist", "equipment": "band", "gif_asset": "assets/fitness/videos/1007-euq4pwp.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶站姿轉體卷腹", "instructions_en": ["Stand with your feet shoulder-width apart and place the band around your upper back, crossing it in front of your chest.", "Hold the ends of the band with your hands, keeping your elbows bent and close to your sides.", "Engage your abs and twist your torso to one side, bringing your elbow towards the opposite knee.", "Pause for a moment, then return to the starting position.", "Repeat on the other side.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，将弹力带绕在上背部，穿过胸前。", "用手握住带子的末端，保持肘部弯曲并靠近身体两侧。", "收紧腹肌并将躯干向一侧扭转，将肘部移向另一侧的膝盖。", "暂停片刻，然后回到起始位置。", "在另一侧重复。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["obliques"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，將彈力帶繞在上背部，穿過胸前。", "用手握住帶子的末端，保持肘部彎曲并靠近身體兩側。", "收緊腹肌并將軀幹向一側扭轉，將肘部移向另一側的膝蓋。", "暫停片刻，然后回到起始位置。", "在另一側重復。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1008', 'exercise', 1, '{"id": "1008", "target": "glutes", "name_en": "band step-up", "name_zh": "弹力带踏台上步", "body_part": "upper legs", "equipment": "band", "gif_asset": "assets/fitness/videos/1008-d5bTEPV.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶踏臺上步", "instructions_en": ["Place a band around your thighs, just above your knees.", "Stand facing a step or platform with your feet hip-width apart.", "Step up onto the platform with your right foot, pushing through your heel.", "Extend your left leg behind you, keeping it straight.", "Lower your left foot back down to the ground.", "Repeat with your left foot stepping up onto the platform.", "Continue alternating legs for the desired number of repetitions."], "instructions_zh": ["将一条带子绕在大腿上，就在膝盖上方。", "面向台阶或平台站立，双脚分开与臀部同宽。", "用右脚踩上平台，用脚后跟推动。", "将左腿伸到身后，保持伸直。", "将左脚放回地面。", "重复左脚踩上平台的动作。", "继续交替双腿达到所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["將一條帶子繞在大腿上，就在膝蓋上方。", "面向臺階或平臺站立，雙腳分開與臀部同寬。", "用右腳踩上平臺，用腳后跟推動。", "將左腿伸到身后，保持伸直。", "將左腳放回地面。", "重復左腳踩上平臺的動作。", "繼續交替雙腿達到所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1009', 'exercise', 1, '{"id": "1009", "target": "glutes", "name_en": "band stiff leg deadlift", "name_zh": "弹力带直腿硬拉", "body_part": "upper legs", "equipment": "band", "gif_asset": "assets/fitness/videos/1009-kuMiR2T.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶直腿硬拉", "instructions_en": ["Stand with your feet shoulder-width apart and place the band around your ankles.", "Hold the band with both hands in front of your thighs, palms facing your body.", "Keeping your back straight and your core engaged, hinge at the hips and slowly lower your upper body towards the ground.", "As you lower, push your hips back and allow your knees to bend slightly.", "Lower the band towards the ground, feeling a stretch in your hamstrings.", "Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your upper body back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开站立，与肩同宽，将弹力带绕在脚踝上。", "用双手将弹力带放在大腿前面，手掌朝向身体。", "保持背部挺直，核心收紧，铰接臀部，慢慢将上半身降低到地面。", "当你降低时，将臀部向后推，并让膝盖稍微弯曲。", "将弹力带降低至地面，感受腿筋的拉伸。", "在底部暂停片刻，然后启动臀肌和腿筋，将上半身抬回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "lower back"], "instructions_zh_hant": ["雙腳分開站立，與肩同寬，將彈力帶繞在腳踝上。", "用雙手將彈力帶放在大腿前面，手掌朝向身體。", "保持背部挺直，核心收緊，鉸接臀部，慢慢將上半身降低到地面。", "當你降低時，將臀部向后推，并讓膝蓋稍微彎曲。", "將彈力帶降低至地面，感受腿筋的拉伸。", "在底部暫停片刻，然后啟動臀肌和腿筋，將上半身抬回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0033', 'exercise', 1, '{"id": "0033", "target": "pectorals", "name_en": "barbell decline bench press", "name_zh": "杠铃下斜卧推", "body_part": "chest", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0033-GrO65fd.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴下斜臥推", "instructions_en": ["Lie on a decline bench with your feet secured and your head lower than your hips.", "Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.", "Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.", "Pause for a moment at the bottom, then push the barbell back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["躺在倾斜的长凳上，双脚固定，头部低于臀部。", "正手握住杠铃，握距略宽于肩宽。", "松开杠铃，慢慢将其降低到胸部，保持肘部内收。", "在底部停顿片刻，然后将杠铃推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["躺在傾斜的長凳上，雙腳固定，頭部低于臀部。", "正手握住杠鈴，握距略寬于肩寬。", "松開杠鈴，慢慢將其降低到胸部，保持肘部內收。", "在底部停頓片刻，然后將杠鈴推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1023', 'exercise', 1, '{"id": "1023", "target": "glutes", "name_en": "band straight back stiff leg deadlift", "name_zh": "弹力带背部挺直直腿硬拉", "body_part": "upper legs", "equipment": "band", "gif_asset": "assets/fitness/videos/1023-lHeUULr.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶背部挺直直腿硬拉", "instructions_en": ["Stand with your feet shoulder-width apart and place the band around your upper legs.", "Hold the band with both hands in front of your thighs, palms facing your body.", "Keeping your back straight and your knees slightly bent, hinge at the hips and lower the band towards the ground.", "Feel the stretch in your hamstrings as you lower the band.", "Engage your glutes and hamstrings to lift your body back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，将弹力带绕在大腿上。", "用双手将弹力带放在大腿前面，手掌朝向身体。", "保持背部挺直，膝盖稍微弯曲，铰接臀部并将弹力带降低到地面。", "当你降低弹力带时，感受腿筋的拉伸。", "启动臀肌和腿筋，将身体抬回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "lower back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，將彈力帶繞在大腿上。", "用雙手將彈力帶放在大腿前面，手掌朝向身體。", "保持背部挺直，膝蓋稍微彎曲，鉸接臀部并將彈力帶降低到地面。", "當你降低彈力帶時，感受腿筋的拉伸。", "啟動臀肌和腿筋，將身體抬回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1015', 'exercise', 1, '{"id": "1015", "target": "abs", "name_en": "band vertical pallof press", "name_zh": "弹力带垂直帕洛夫抗旋转推举", "body_part": "waist", "equipment": "band", "gif_asset": "assets/fitness/videos/1015-G7PXMlT.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶垂直帕洛夫抗旋轉推舉", "instructions_en": ["Stand with your feet shoulder-width apart and wrap the band around a sturdy object at chest height.", "Hold the band with both hands and step away from the anchor point, creating tension in the band.", "Position yourself perpendicular to the anchor point, with your side facing the band.", "Extend your arms straight out in front of you, keeping your hands at chest height.", "Engage your core and press the band away from your chest, fully extending your arms.", "Hold the position for a few seconds, then slowly bring the band back towards your chest.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["双脚分开与肩同宽站立，将弹力带缠绕在胸部高度的坚固物体上。", "用双手握住弹力带并远离锚点，在弹力带中产生张力。", "使自己垂直于锚点，一侧面向弹力带。", "将双臂伸直在身前，保持双手与胸同高。", "收紧核心肌群，将弹力带压离胸部，充分伸展手臂。", "保持该姿势几秒钟，然后慢慢将弹力带拉回到胸部。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["obliques", "glutes"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，將彈力帶纏繞在胸部高度的堅固物體上。", "用雙手握住彈力帶并遠離錨點，在彈力帶中產生張力。", "使自己垂直于錨點，一側面向彈力帶。", "將雙臂伸直在身前，保持雙手與胸同高。", "收緊核心肌群，將彈力帶壓離胸部，充分伸展手臂。", "保持該姿勢幾秒鐘，然后慢慢將彈力帶拉回到胸部。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1010', 'exercise', 1, '{"id": "1010", "target": "spine", "name_en": "band straight leg deadlift", "name_zh": "弹力带直腿硬拉", "body_part": "back", "equipment": "band", "gif_asset": "assets/fitness/videos/1010-KUaoUV8.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶直腿硬拉", "instructions_en": ["Stand with your feet shoulder-width apart and place the band around your feet.", "Hold the band with both hands, palms facing your body, and keep your arms straight.", "Engage your core and maintain a slight bend in your knees.", "Slowly hinge forward at your hips, keeping your back straight and chest lifted.", "Lower the band towards the ground while keeping your legs straight.", "Pause for a moment at the bottom, then squeeze your glutes and hamstrings to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，将弹力带绕在脚上。", "双手握住弹力带，手掌朝向身体，手臂伸直。", "收紧核心并保持膝盖轻微弯曲。", "慢慢地以臀部为中心向前转动，保持背部挺直，挺胸。", "将弹力带降低至地面，同时保持双腿伸直。", "在底部暂停片刻，然后挤压臀肌和腿筋，回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "glutes"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，將彈力帶繞在腳上。", "雙手握住彈力帶，手掌朝向身體，手臂伸直。", "收緊核心并保持膝蓋輕微彎曲。", "慢慢地以臀部為中心向前轉動，保持背部挺直，挺胸。", "將彈力帶降低至地面，同時保持雙腿伸直。", "在底部暫停片刻，然后擠壓臀肌和腿筋，回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1012', 'exercise', 1, '{"id": "1012", "target": "delts", "name_en": "band twisting overhead press", "name_zh": "弹力带转体过顶推举", "body_part": "shoulders", "equipment": "band", "gif_asset": "assets/fitness/videos/1012-u4bAmKp.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶轉體過頂推舉", "instructions_en": ["Stand with your feet shoulder-width apart and place the band under your feet.", "Hold the band handles at shoulder height with your palms facing forward.", "Engage your core and press the band overhead, fully extending your arms.", "As you press, twist your torso to one side, keeping your hips stable.", "Pause for a moment at the top, then return to the starting position.", "Repeat the press and twist on the opposite side.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，将弹力带放在脚下。", "将弹力带手柄保持在与肩同高的位置，手掌朝前。", "启动你的核心并将弹力带压过头顶，充分伸展你的手臂。", "当你按压时，将你的躯干扭转到一侧，保持臀部稳定。", "在顶部暂停片刻，然后回到起始位置。", "在另一侧重复按压和扭转。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["triceps", "upper back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，將彈力帶放在腳下。", "將彈力帶手柄保持在與肩同高的位置，手掌朝前。", "啟動你的核心并將彈力帶壓過頭頂，充分伸展你的手臂。", "當你按壓時，將你的軀幹扭轉到一側，保持臀部穩定。", "在頂部暫停片刻，然后回到起始位置。", "在另一側重復按壓和扭轉。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1369', 'exercise', 1, '{"id": "1369", "target": "calves", "name_en": "band two legs calf raise - (band under both legs) v. 2", "name_zh": "弹力带双腿提踵（带置于脚下，变式2）", "body_part": "lower legs", "equipment": "band", "gif_asset": "assets/fitness/videos/1369-jl6uxZV.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶雙腿提踵（帶置于腳下，變式2）", "instructions_en": ["Stand with your feet shoulder-width apart and place a resistance band under both feet.", "Hold the ends of the band with your hands for stability.", "Raise your heels off the ground as high as possible, using your calves.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，并将阻力带放在双脚下方。", "用手握住带子的末端以保持稳定。", "用小腿将脚跟抬离地面，尽可能高。", "在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["ankles", "feet"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，并將阻力帶放在雙腳下方。", "用手握住帶子的末端以保持穩定。", "用小腿將腳跟抬離地面，盡可能高。", "在頂部停頓片刻，然后慢慢降低腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1013', 'exercise', 1, '{"id": "1013", "target": "lats", "name_en": "band underhand pulldown", "name_zh": "弹力带反握下拉", "body_part": "back", "equipment": "band", "gif_asset": "assets/fitness/videos/1013-k6tUeqS.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶反握下拉", "instructions_en": ["Attach the band to a high anchor point, such as a pull-up bar or sturdy beam.", "Stand facing the anchor point with your feet shoulder-width apart.", "Grasp the band with an underhand grip, hands slightly wider than shoulder-width apart.", "Extend your arms fully overhead, keeping your elbows slightly bent.", "Engage your lats and pull the band down towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the bottom of the movement, then slowly release the tension and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将弹力带固定在较高的锚点上，例如上拉杆或坚固的横梁。", "面向锚点站立，双脚分开与肩同宽。", "反手握住弹力带，双手间距略宽于肩宽。", "将手臂完全伸过头顶，保持肘部稍微弯曲。", "收紧背阔肌，将弹力带向下拉向胸部，将肩胛骨挤压在一起。", "在动作底部停顿片刻，然后慢慢释放张力，回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["將彈力帶固定在較高的錨點上，例如上拉桿或堅固的橫梁。", "面向錨點站立，雙腳分開與肩同寬。", "反手握住彈力帶，雙手間距略寬于肩寬。", "將手臂完全伸過頭頂，保持肘部稍微彎曲。", "收緊背闊肌，將彈力帶向下拉向胸部，將肩胛骨擠壓在一起。", "在動作底部停頓片刻，然后慢慢釋放張力，回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1017', 'exercise', 1, '{"id": "1017", "target": "delts", "name_en": "band y-raise", "name_zh": "弹力带Y字上举", "body_part": "shoulders", "equipment": "band", "gif_asset": "assets/fitness/videos/1017-aHDy5O5.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彈力帶Y字上舉", "instructions_en": ["Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing inwards.", "Keep your arms straight and lift them up and out to the sides, forming a ''Y'' shape with your body.", "Squeeze your shoulder blades together at the top of the movement.", "Slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，将弹力带放在大腿前面，手掌朝内。", "保持双臂伸直，将其向上举至两侧，与身体形成“Y”形。", "在动作的最高点将肩胛骨挤压在一起。", "慢慢地将手臂放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["traps", "rhomboids"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，將彈力帶放在大腿前面，手掌朝內。", "保持雙臂伸直，將其向上舉至兩側，與身體形成“Y”形。", "在動作的最高點將肩胛骨擠壓在一起。", "慢慢地將手臂放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0023', 'exercise', 1, '{"id": "0023", "target": "biceps", "name_en": "barbell alternate biceps curl", "name_zh": "杠铃交替二头弯举", "body_part": "upper arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0023-Yza7XrQ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴交替二頭彎舉", "instructions_en": ["Stand up straight with your feet shoulder-width apart and hold a barbell in each hand, palms facing forward.", "Keep your upper arms stationary and exhale as you curl the weights while contracting your biceps.", "Continue to raise the barbells until your biceps are fully contracted and the barbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale as you slowly begin to lower the barbells back to the starting position.", "Repeat for the desired number of repetitions, alternating arms."], "instructions_zh": ["站直，双脚分开与肩同宽，每只手握住一个杠铃，手掌朝前。", "保持上臂静止，在弯举哑铃时呼气，同时收缩二头肌。", "继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气，慢慢开始将杠铃放回起始位置。", "重复所需的重复次数，交替手臂。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙腳分開與肩同寬，每只手握住一個杠鈴，手掌朝前。", "保持上臂靜止，在彎舉啞鈴時呼氣，同時收縮二頭肌。", "繼續舉起杠鈴，直到二頭肌完全收縮并且杠鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣，慢慢開始將杠鈴放回起始位置。", "重復所需的重復次數，交替手臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0024', 'exercise', 1, '{"id": "0024", "target": "quads", "name_en": "barbell bench front squat", "name_zh": "杠铃凳上前蹲", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0024-Y7YcmIJ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴凳上前蹲", "instructions_en": ["Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, just below your collarbone.", "Hold the barbell with an overhand grip, keeping your elbows up and your upper arms parallel to the ground.", "Lower your body down into a squat position by bending at the knees and hips, keeping your back straight and your chest up.", "Pause for a moment at the bottom of the squat, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先站立，双脚分开与肩同宽，将杠铃放在上胸部，锁骨下方。", "正手握住杠铃，保持肘部向上，上臂与地面平行。", "弯曲膝盖和臀部，将身体降低到蹲姿，保持背部挺直，挺胸。", "在深蹲底部暂停片刻，然后用脚后跟恢复到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "glutes", "calves"], "instructions_zh_hant": ["首先站立，雙腳分開與肩同寬，將杠鈴放在上胸部，鎖骨下方。", "正手握住杠鈴，保持肘部向上，上臂與地面平行。", "彎曲膝蓋和臀部，將身體降低到蹲姿，保持背部挺直，挺胸。", "在深蹲底部暫停片刻，然后用腳后跟恢復到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0026', 'exercise', 1, '{"id": "0026", "target": "quads", "name_en": "barbell bench squat", "name_zh": "杠铃凳上深蹲", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0026-W9pFVv1.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴凳上深蹲", "instructions_en": ["Set up a barbell on a squat rack at chest height.", "Stand facing away from the rack, with your feet shoulder-width apart.", "Bend your knees and lower your body down into a squat position, keeping your back straight and chest up.", "Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.", "Lift the barbell off the rack and step back, ensuring your feet are still shoulder-width apart.", "Lower your body down into a squat, keeping your knees in line with your toes.", "Pause for a moment at the bottom, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将杠铃放在深蹲架上，与胸部同高。", "背对架子站立，双脚与肩同宽。", "弯曲膝盖，将身体降低至蹲姿，保持背部挺直，挺胸。", "正手握住杠铃，握距略宽于肩宽。", "将杠铃从架子上提起并向后退一步，确保双脚仍与肩同宽。", "降低身体蹲下，保持膝盖与脚趾在一条线上。", "在底部停顿片刻，然后推动脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings", "calves"], "instructions_zh_hant": ["將杠鈴放在深蹲架上，與胸部同高。", "背對架子站立，雙腳與肩同寬。", "彎曲膝蓋，將身體降低至蹲姿，保持背部挺直，挺胸。", "正手握住杠鈴，握距略寬于肩寬。", "將杠鈴從架子上提起并向后退一步，確保雙腳仍與肩同寬。", "降低身體蹲下，保持膝蓋與腳趾在一條線上。", "在底部停頓片刻，然后推動腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1316', 'exercise', 1, '{"id": "1316", "target": "lats", "name_en": "barbell bent arm pullover", "name_zh": "杠铃屈臂仰卧上拉", "body_part": "back", "equipment": "barbell", "gif_asset": "assets/fitness/videos/1316-cA9FuWG.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴屈臂仰臥上拉", "instructions_en": ["Lie flat on a bench with your head at one end and your feet on the floor.", "Hold a barbell with a shoulder-width grip and extend your arms straight above your chest.", "Lower the barbell behind your head while keeping your arms slightly bent.", "Pause for a moment, then raise the barbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，头放在一端，双脚放在地板上。", "握距与肩同宽，握住杠铃，将手臂伸直至胸部上方。", "将杠铃放在脑后，同时保持手臂稍微弯曲。", "暂停片刻，然后将杠铃举回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "chest"], "instructions_zh_hant": ["平躺在長凳上，頭放在一端，雙腳放在地板上。", "握距與肩同寬，握住杠鈴，將手臂伸直至胸部上方。", "將杠鈴放在腦后，同時保持手臂稍微彎曲。", "暫停片刻，然后將杠鈴舉回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2407', 'exercise', 1, '{"id": "2407", "target": "biceps", "name_en": "barbell biceps curl (with arm blaster)", "name_zh": "杠铃二头弯举（配合弯举护板）", "body_part": "upper arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/2407-aee2Fcj.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴二頭彎舉（配合彎舉護板）", "instructions_en": ["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.", "Place your upper arms against the arm blaster, keeping your elbows close to your torso.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站直，双脚分开与肩同宽，反手握住杠铃，手掌朝上。", "将上臂靠在手臂冲击波上，保持肘部靠近躯干。", "保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。", "继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙腳分開與肩同寬，反手握住杠鈴，手掌朝上。", "將上臂靠在手臂沖擊波上，保持肘部靠近軀幹。", "保持上臂靜止，呼氣并彎舉啞鈴，同時收縮二頭肌。", "繼續舉起杠鈴，直到二頭肌完全收縮并且杠鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0028', 'exercise', 1, '{"id": "0028", "target": "quads", "name_en": "barbell clean and press", "name_zh": "杠铃翻举推举", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0028-SGY8Zui.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴翻舉推舉", "instructions_en": ["Stand with your feet shoulder-width apart and the barbell on the floor in front of you.", "Bend your knees and hinge at the hips to lower down and grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart.", "Drive through your heels and extend your hips and knees to lift the barbell off the floor, keeping it close to your body.", "As the barbell reaches your thighs, explosively extend your hips, shrug your shoulders, and pull the barbell up towards your chest.", "As the barbell reaches chest height, quickly drop under it and catch it at shoulder level, with your elbows pointing forward and your palms facing up.", "From the catch position, press the barbell overhead by extending your arms and pushing the barbell straight up.", "Lower the barbell back down to the starting position and repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，杠铃放在你面前的地板上。", "弯曲膝盖并以臀部为铰链降低并用正手握住杠铃，双手分开略宽于肩宽。", "通过脚后跟发力，伸展臀部和膝盖，将杠铃抬离地板，使其靠近身体。", "当杠铃到达大腿时，爆发性伸展臀部，耸肩，并将杠铃拉向胸部。", "当杠铃到达胸部高度时，迅速将其降至肩部水平，肘部向前，手掌朝上。", "从接球位置开始，伸展双臂并将杠铃笔直向上推，将杠铃压过头顶。", "将杠铃放回起始位置，然后重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "glutes", "shoulders", "triceps"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，杠鈴放在你面前的地板上。", "彎曲膝蓋并以臀部為鉸鏈降低并用正手握住杠鈴，雙手分開略寬于肩寬。", "通過腳后跟發力，伸展臀部和膝蓋，將杠鈴抬離地板，使其靠近身體。", "當杠鈴到達大腿時，爆發性伸展臀部，聳肩，并將杠鈴拉向胸部。", "當杠鈴到達胸部高度時，迅速將其降至肩部水平，肘部向前，手掌朝上。", "從接球位置開始，伸展雙臂并將杠鈴筆直向上推，將杠鈴壓過頭頂。", "將杠鈴放回起始位置，然后重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0034', 'exercise', 1, '{"id": "0034", "target": "lats", "name_en": "barbell decline bent arm pullover", "name_zh": "杠铃下斜屈臂仰卧上拉", "body_part": "back", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0034-hMEptv0.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴下斜屈臂仰臥上拉", "instructions_en": ["Lie down on a decline bench with your head lower than your hips and your feet secured.", "Hold a barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest.", "Lower the barbell behind your head in a controlled manner, keeping your arms slightly bent.", "Pause for a moment, then raise the barbell back to the starting position by contracting your lats.", "Repeat for the desired number of repetitions."], "instructions_zh": ["躺在倾斜的长凳上，头部低于臀部，双脚固定。", "旋前握住杠铃（手掌背向您），并将手臂伸直至胸部上方。", "有控制地将杠铃降低到头后，保持手臂稍微弯曲。", "暂停片刻，然后收缩背阔肌，将杠铃抬回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "chest"], "instructions_zh_hant": ["躺在傾斜的長凳上，頭部低于臀部，雙腳固定。", "旋前握住杠鈴（手掌背向您），并將手臂伸直至胸部上方。", "有控制地將杠鈴降低到頭后，保持手臂稍微彎曲。", "暫停片刻，然后收縮背闊肌，將杠鈴抬回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0035', 'exercise', 1, '{"id": "0035", "target": "triceps", "name_en": "barbell decline close grip to skull press", "name_zh": "杠铃下斜窄握卧推接臂屈伸", "body_part": "upper arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0035-LMGXZn8.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴下斜窄握臥推接臂屈伸", "instructions_en": ["Lie on a decline bench with your head lower than your feet and hold a barbell with a close grip.", "Lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary.", "Pause for a moment, then extend your arms to press the barbell back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["躺在下斜长凳上，头低于脚，紧紧握住杠铃。", "弯曲肘部，将杠铃向前额降低，保持上臂静止。", "暂停片刻，然后伸展双臂将杠铃推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["躺在下斜長凳上，頭低于腳，緊緊握住杠鈴。", "彎曲肘部，將杠鈴向前額降低，保持上臂靜止。", "暫停片刻，然后伸展雙臂將杠鈴推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1255', 'exercise', 1, '{"id": "1255", "target": "pectorals", "name_en": "barbell decline pullover", "name_zh": "杠铃下斜仰卧上拉", "body_part": "chest", "equipment": "barbell", "gif_asset": "assets/fitness/videos/1255-9sgNE2O.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴下斜仰臥上拉", "instructions_en": ["Lie down on a decline bench with your head lower than your hips and your feet secured.", "Hold the barbell with a pronated grip (palms facing away from you) and your hands slightly wider than shoulder-width apart.", "Extend your arms above your chest, keeping a slight bend in your elbows.", "Lower the barbell in an arc motion behind your head, feeling a stretch in your chest and shoulders.", "Pause for a moment, then return the barbell to the starting position by reversing the motion.", "Repeat for the desired number of repetitions."], "instructions_zh": ["躺在倾斜的长凳上，头部低于臀部，双脚固定。", "旋前握住杠铃（手掌背向自己），双手之间的距离略宽于肩宽。", "将手臂伸至胸部上方，保持肘部轻微弯曲。", "以弧线动作将杠铃降低到头后，感受胸部和肩膀的伸展。", "暂停片刻，然后反向动作将杠铃恢复到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["躺在傾斜的長凳上，頭部低于臀部，雙腳固定。", "旋前握住杠鈴（手掌背向自己），雙手之間的距離略寬于肩寬。", "將手臂伸至胸部上方，保持肘部輕微彎曲。", "以弧線動作將杠鈴降低到頭后，感受胸部和肩膀的伸展。", "暫停片刻，然后反向動作將杠鈴恢復到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0036', 'exercise', 1, '{"id": "0036", "target": "pectorals", "name_en": "barbell decline wide-grip press", "name_zh": "杠铃下斜宽握推举", "body_part": "chest", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0036-hl8DUh8.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴下斜寬握推舉", "instructions_en": ["Lie on a decline bench with your feet secured and your head lower than your hips.", "Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.", "Lower the barbell to your chest, keeping your elbows out to the sides.", "Push the barbell back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["躺在倾斜的长凳上，双脚固定，头部低于臀部。", "宽握距抓住杠铃，握距略宽于肩宽。", "将杠铃降低到胸部，保持肘部向两侧伸出。", "将杠铃推回到起始位置，完全伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["躺在傾斜的長凳上，雙腳固定，頭部低于臀部。", "寬握距抓住杠鈴，握距略寬于肩寬。", "將杠鈴降低到胸部，保持肘部向兩側伸出。", "將杠鈴推回到起始位置，完全伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0037', 'exercise', 1, '{"id": "0037", "target": "lats", "name_en": "barbell decline wide-grip pullover", "name_zh": "杠铃下斜宽握仰卧上拉", "body_part": "back", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0037-Hj4FOCd.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴下斜寬握仰臥上拉", "instructions_en": ["Lie on a decline bench with your head lower than your hips and your feet secured.", "Hold a barbell with a wide grip and extend your arms straight above your chest.", "Lower the barbell behind your head in a controlled manner, keeping your arms straight.", "Pause for a moment, then raise the barbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["躺在倾斜的长凳上，头部低于臀部，双脚固定。", "宽握距握住杠铃，并将双臂伸直至胸部上方。", "有控制地将杠铃降低到头后，保持手臂伸直。", "暂停片刻，然后将杠铃举回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "chest"], "instructions_zh_hant": ["躺在傾斜的長凳上，頭部低于臀部，雙腳固定。", "寬握距握住杠鈴，并將雙臂伸直至胸部上方。", "有控制地將杠鈴降低到頭后，保持手臂伸直。", "暫停片刻，然后將杠鈴舉回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0042', 'exercise', 1, '{"id": "0042", "target": "glutes", "name_en": "barbell front squat", "name_zh": "杠铃前蹲", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0042-zG0zs85.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴前蹲", "instructions_en": ["Start by standing with your feet shoulder-width apart, toes slightly turned out.", "Hold the barbell in front of your shoulders, resting it on your collarbone and shoulders.", "Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.", "Lower until your thighs are parallel to the ground, or as low as you can comfortably go.", "Pause for a moment at the bottom, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先站立，双脚分开与肩同宽，脚趾稍微向外。", "将杠铃放在肩膀前面，将其放在锁骨和肩膀上。", "当你将身体降低到蹲姿时，收紧核心并保持挺胸，将臀部向后推并弯曲膝盖。", "降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。", "在底部停顿片刻，然后推动脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves", "core"], "instructions_zh_hant": ["首先站立，雙腳分開與肩同寬，腳趾稍微向外。", "將杠鈴放在肩膀前面，將其放在鎖骨和肩膀上。", "當你將身體降低到蹲姿時，收緊核心并保持挺胸，將臀部向后推并彎曲膝蓋。", "降低直到大腿與地面平行，或者盡可能降低到您能舒服的高度。", "在底部停頓片刻，然后推動腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0038', 'exercise', 1, '{"id": "0038", "target": "biceps", "name_en": "barbell drag curl", "name_zh": "杠铃拖拉弯举", "body_part": "upper arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0038-IENzBdA.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴拖拉彎舉", "instructions_en": ["Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.", "Let the barbell hang at arm''s length in front of your thighs.", "Keeping your upper arms stationary, curl the barbell up towards your chest by contracting your biceps.", "Pause for a moment at the top, then slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，反手握住杠铃，手掌朝上。", "让杠铃悬挂在大腿前面，与手臂保持一定距离。", "保持上臂静止，通过收缩二头肌将杠铃向上卷曲至胸部。", "在顶部停顿片刻，然后慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，反手握住杠鈴，手掌朝上。", "讓杠鈴懸掛在大腿前面，與手臂保持一定距離。", "保持上臂靜止，通過收縮二頭肌將杠鈴向上卷曲至胸部。", "在頂部停頓片刻，然后慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1370', 'exercise', 1, '{"id": "1370", "target": "calves", "name_en": "barbell floor calf raise", "name_zh": "杠铃地板提踵", "body_part": "lower legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/1370-2IHEa2T.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴地板提踵", "instructions_en": ["Place a barbell on the floor in front of you.", "Stand with the balls of your feet on the edge of the barbell, with your heels hanging off.", "Hold onto a stable object for balance if needed.", "Raise your heels as high as possible, using your calves to lift your body.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将杠铃放在您面前的地板上。", "站立，脚掌放在杠铃边缘，脚跟悬垂。", "如果需要，请抓住一个稳定的物体以保持平衡。", "尽可能高地抬高脚后跟，用小腿来抬起身体。", "在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings"], "instructions_zh_hant": ["將杠鈴放在您面前的地板上。", "站立，腳掌放在杠鈴邊緣，腳跟懸垂。", "如果需要，請抓住一個穩定的物體以保持平衡。", "盡可能高地抬高腳后跟，用小腿來抬起身體。", "在頂部停頓片刻，然后慢慢降低腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0039', 'exercise', 1, '{"id": "0039", "target": "glutes", "name_en": "barbell front chest squat", "name_zh": "杠铃前蹲", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0039-IeTIEqg.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴前蹲", "instructions_en": ["Start by standing with your feet shoulder-width apart, toes slightly turned out.", "Hold the barbell in front of your chest with your hands shoulder-width apart, elbows pointing forward.", "Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.", "Lower until your thighs are parallel to the ground, or as low as you can comfortably go.", "Pause for a moment at the bottom, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先站立，双脚分开与肩同宽，脚趾稍微向外。", "将杠铃放在胸前，双手与肩同宽，肘部向前。", "当你将身体降低到蹲姿时，收紧核心并保持挺胸，将臀部向后推并弯曲膝盖。", "降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。", "在底部停顿片刻，然后推动脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves", "core"], "instructions_zh_hant": ["首先站立，雙腳分開與肩同寬，腳趾稍微向外。", "將杠鈴放在胸前，雙手與肩同寬，肘部向前。", "當你將身體降低到蹲姿時，收緊核心并保持挺胸，將臀部向后推并彎曲膝蓋。", "降低直到大腿與地面平行，或者盡可能降低到您能舒服的高度。", "在底部停頓片刻，然后推動腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0041', 'exercise', 1, '{"id": "0041", "target": "delts", "name_en": "barbell front raise", "name_zh": "杠铃前平举", "body_part": "shoulders", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0041-b2Uoz54.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴前平舉", "instructions_en": ["Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip.", "Keep your arms straight and lift the barbell forward and upward until it reaches shoulder level.", "Pause for a moment at the top, then slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，正手握住杠铃于大腿前方。", "保持手臂伸直，向前向上举起杠铃，直至达到肩部水平。", "在顶部停顿片刻，然后慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "triceps"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，正手握住杠鈴于大腿前方。", "保持手臂伸直，向前向上舉起杠鈴，直至達到肩部水平。", "在頂部停頓片刻，然后慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0090', 'exercise', 1, '{"id": "0090", "target": "glutes", "name_en": "barbell seated good morning", "name_zh": "杠铃坐姿早安式", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0090-d960PgE.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴坐姿早安式", "instructions_en": ["Sit on a bench with your feet flat on the ground and a barbell resting on your upper back.", "Keep your back straight and your chest up.", "Slowly hinge forward at the hips, lowering your torso towards the ground.", "Pause for a moment at the bottom, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双脚平放在地上，上背部放一个杠铃。", "保持背部挺直，挺胸。", "慢慢地向前转动臀部，将躯干降低到地面。", "在底部停顿片刻，然后推动脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "lower back"], "instructions_zh_hant": ["坐在長凳上，雙腳平放在地上，上背部放一個杠鈴。", "保持背部挺直，挺胸。", "慢慢地向前轉動臀部，將軀幹降低到地面。", "在底部停頓片刻，然后推動腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0040', 'exercise', 1, '{"id": "0040", "target": "pectorals", "name_en": "barbell front raise and pullover", "name_zh": "杠铃前平举与仰卧上拉", "body_part": "chest", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0040-33AzZeV.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴前平舉與仰臥上拉", "instructions_en": ["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.", "Keep your arms straight and raise the barbell in front of you until it reaches shoulder height.", "Pause for a moment at the top, then slowly lower the barbell back down to the starting position.", "Next, lower the barbell behind your head, keeping your arms straight.", "Pause for a moment at the bottom, then raise the barbell back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，正手握住杠铃，手掌朝下。", "保持双臂伸直，将杠铃举至身前，直至达到肩膀高度。", "在顶部停顿片刻，然后慢慢将杠铃放回起始位置。", "接下来，将杠铃放低到头后，保持手臂伸直。", "在底部停顿片刻，然后将杠铃举回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["deltoids", "triceps"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，正手握住杠鈴，手掌朝下。", "保持雙臂伸直，將杠鈴舉至身前，直至達到肩膀高度。", "在頂部停頓片刻，然后慢慢將杠鈴放回起始位置。", "接下來，將杠鈴放低到頭后，保持手臂伸直。", "在底部停頓片刻，然后將杠鈴舉回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1461', 'exercise', 1, '{"id": "1461", "target": "glutes", "name_en": "barbell full squat (back pov)", "name_zh": "杠铃全蹲（背面视角）", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/1461-DhMl549.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴全蹲（背面視角）", "instructions_en": ["Stand with your feet shoulder-width apart, toes slightly turned out.", "Hold the barbell across your upper back, resting it on your traps or rear delts.", "Engage your core and keep your chest up as you begin to lower your body down.", "Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.", "Lower your body until your thighs are parallel to the ground or slightly below.", "Keep your knees in line with your toes and your weight in your heels.", "Drive through your heels to stand back up, extending your hips and knees.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站立，双脚分开与肩同宽，脚趾稍微向外。", "将杠铃放在上背部，将其放在斜方肌或三角肌后束上。", "当你开始降低身体时，启动你的核心并保持胸部挺直。", "弯曲膝盖和臀部，向后和向下推臀部，就像坐在椅子上一样。", "降低身体，直到大腿与地面平行或稍低于地面。", "保持膝盖与脚趾对齐，并将重量放在脚后跟上。", "通过脚后跟站起来，伸展臀部和膝盖。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves", "core"], "instructions_zh_hant": ["站立，雙腳分開與肩同寬，腳趾稍微向外。", "將杠鈴放在上背部，將其放在斜方肌或三角肌后束上。", "當你開始降低身體時，啟動你的核心并保持胸部挺直。", "彎曲膝蓋和臀部，向后和向下推臀部，就像坐在椅子上一樣。", "降低身體，直到大腿與地面平行或稍低于地面。", "保持膝蓋與腳趾對齊，并將重量放在腳后跟上。", "通過腳后跟站起來，伸展臀部和膝蓋。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1462', 'exercise', 1, '{"id": "1462", "target": "glutes", "name_en": "barbell full squat (side pov)", "name_zh": "杠铃全蹲（侧面视角）", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/1462-iYzB0Cz.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴全蹲（側面視角）", "instructions_en": ["Stand with your feet shoulder-width apart, toes slightly turned out.", "Hold the barbell across your upper back, resting it on your traps or rear delts.", "Engage your core and keep your chest up as you begin to lower your body down.", "Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.", "Lower your body until your thighs are parallel to the ground or slightly below.", "Keep your knees in line with your toes and your weight in your heels.", "Drive through your heels to stand back up, extending your hips and knees.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站立，双脚分开与肩同宽，脚趾稍微向外。", "将杠铃放在上背部，将其放在斜方肌或三角肌后束上。", "当你开始降低身体时，启动你的核心并保持胸部挺直。", "弯曲膝盖和臀部，向后和向下推臀部，就像坐在椅子上一样。", "降低身体，直到大腿与地面平行或稍低于地面。", "保持膝盖与脚趾对齐，并将重量放在脚后跟上。", "通过脚后跟站起来，伸展臀部和膝盖。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves", "core"], "instructions_zh_hant": ["站立，雙腳分開與肩同寬，腳趾稍微向外。", "將杠鈴放在上背部，將其放在斜方肌或三角肌后束上。", "當你開始降低身體時，啟動你的核心并保持胸部挺直。", "彎曲膝蓋和臀部，向后和向下推臀部，就像坐在椅子上一樣。", "降低身體，直到大腿與地面平行或稍低于地面。", "保持膝蓋與腳趾對齊，并將重量放在腳后跟上。", "通過腳后跟站起來，伸展臀部和膝蓋。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1545', 'exercise', 1, '{"id": "1545", "target": "glutes", "name_en": "barbell full zercher squat", "name_zh": "杠铃全程泽奇深蹲", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/1545-vR1vold.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴全程澤奇深蹲", "instructions_en": ["Stand with your feet shoulder-width apart and toes slightly turned out.", "Hold the barbell in the crooks of your elbows, with your hands gripping the barbell for stability.", "Engage your core and keep your chest lifted as you lower your hips back and down into a squat position.", "Keep your knees in line with your toes and your weight in your heels.", "Lower until your thighs are parallel to the ground, or as low as you can comfortably go.", "Drive through your heels to stand back up, squeezing your glutes at the top of the movement.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站立，双脚分开与肩同宽，脚趾稍微外翻。", "将杠铃放在肘部的弯曲处，双手握住杠铃以保持稳定。", "当你将臀部向后降低到蹲姿时，启动你的核心并保持胸部抬起。", "保持膝盖与脚趾对齐，并将重量放在脚后跟上。", "降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。", "通过脚跟发力站起来，在动作的最高点挤压臀部。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves", "core"], "instructions_zh_hant": ["站立，雙腳分開與肩同寬，腳趾稍微外翻。", "將杠鈴放在肘部的彎曲處，雙手握住杠鈴以保持穩定。", "當你將臀部向后降低到蹲姿時，啟動你的核心并保持胸部抬起。", "保持膝蓋與腳趾對齊，并將重量放在腳后跟上。", "降低直到大腿與地面平行，或者盡可能降低到您能舒服的高度。", "通過腳跟發力站起來，在動作的最高點擠壓臀部。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1409', 'exercise', 1, '{"id": "1409", "target": "glutes", "name_en": "barbell glute bridge", "name_zh": "杠铃臀桥", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/1409-qKBpF7I.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴臀橋", "instructions_en": ["Start by lying flat on your back on the ground with your knees bent and feet flat on the floor.", "Place a barbell across your hips, holding it securely with both hands.", "Engage your glutes and core muscles, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.", "Pause for a moment at the top, squeezing your glutes.", "Slowly lower your hips back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先平躺在地上，膝盖弯曲，双脚平放在地板上。", "将杠铃放在臀部上，用双手牢牢握住它。", "锻炼臀部和核心肌肉，然后将臀部抬离地面，直到身体从膝盖到肩膀形成一条直线。", "在顶部暂停片刻，挤压臀部。", "慢慢地将臀部放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "lower back"], "instructions_zh_hant": ["首先平躺在地上，膝蓋彎曲，雙腳平放在地板上。", "將杠鈴放在臀部上，用雙手牢牢握住它。", "鍛煉臀部和核心肌肉，然后將臀部抬離地面，直到身體從膝蓋到肩膀形成一條直線。", "在頂部暫停片刻，擠壓臀部。", "慢慢地將臀部放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3562', 'exercise', 1, '{"id": "3562", "target": "glutes", "name_en": "barbell glute bridge two legs on bench (male)", "name_zh": "杠铃凳上垫脚臀桥（男性示范）", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/3562-qg2PGl6.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴凳上墊腳臀橋（男性示范）", "instructions_en": ["Start by sitting on the edge of a bench with your upper back resting against it and your feet flat on the ground, hip-width apart.", "Place a barbell across your hips, holding it securely with both hands.", "Engage your glutes and core muscles, then press through your heels to lift your hips off the bench, creating a straight line from your knees to your shoulders.", "Pause for a moment at the top, squeezing your glutes.", "Slowly lower your hips back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先坐在长凳边缘，上背部靠在长凳上，双脚平放在地面上，与臀部同宽。", "将杠铃放在臀部上，用双手牢牢握住它。", "锻炼臀肌和核心肌肉，然后用脚后跟将臀部抬离长凳，形成从膝盖到肩膀的一条直线。", "在顶部暂停片刻，挤压臀部。", "慢慢地将臀部放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "core"], "instructions_zh_hant": ["首先坐在長凳邊緣，上背部靠在長凳上，雙腳平放在地面上，與臀部同寬。", "將杠鈴放在臀部上，用雙手牢牢握住它。", "鍛煉臀肌和核心肌肉，然后用腳后跟將臀部抬離長凳，形成從膝蓋到肩膀的一條直線。", "在頂部暫停片刻，擠壓臀部。", "慢慢地將臀部放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0044', 'exercise', 1, '{"id": "0044", "target": "hamstrings", "name_en": "barbell good morning", "name_zh": "杠铃早安式", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0044-XlZ4lAC.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴早安式", "instructions_en": ["Start by standing with your feet shoulder-width apart and the barbell resting on your upper back.", "Keeping your back straight and your core engaged, hinge forward at the hips, pushing your buttocks back as if you were trying to touch the wall behind you with your glutes.", "Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.", "Pause for a moment, then return to the starting position by squeezing your glutes and pushing your hips forward.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先站立，双脚分开与肩同宽，将杠铃放在上背部。", "保持背部挺直，核心肌群参与，臀部向前转动，将臀部向后推，就好像你试图用臀部触碰身后的墙壁一样。", "降低躯干直到与地面平行，感觉腿筋被拉伸。", "暂停片刻，然后通过挤压臀部并将臀部向前推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["lower back"], "instructions_zh_hant": ["首先站立，雙腳分開與肩同寬，將杠鈴放在上背部。", "保持背部挺直，核心肌群參與，臀部向前轉動，將臀部向后推，就好像你試圖用臀部觸碰身后的墻壁一樣。", "降低軀幹直到與地面平行，感覺腿筋被拉伸。", "暫停片刻，然后通過擠壓臀部并將臀部向前推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0045', 'exercise', 1, '{"id": "0045", "target": "pectorals", "name_en": "barbell guillotine bench press", "name_zh": "杠铃颈前卧推", "body_part": "chest", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0045-GXoaSgn.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴頸前臥推", "instructions_en": ["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.", "Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.", "Lower the barbell slowly towards your neck, keeping your elbows pointed outwards.", "Pause for a moment when the barbell is just above your neck.", "Push the barbell back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，双脚平放在地上，背部紧贴长凳。", "正手握住杠铃，握距略宽于肩宽。", "慢慢地将杠铃降低到颈部，保持肘部朝外。", "当杠铃位于颈部上方时，暂停片刻。", "将杠铃推回到起始位置，完全伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["平躺在長凳上，雙腳平放在地上，背部緊貼長凳。", "正手握住杠鈴，握距略寬于肩寬。", "慢慢地將杠鈴降低到頸部，保持肘部朝外。", "當杠鈴位于頸部上方時，暫停片刻。", "將杠鈴推回到起始位置，完全伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0046', 'exercise', 1, '{"id": "0046", "target": "glutes", "name_en": "barbell hack squat", "name_zh": "杠铃哈克深蹲", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0046-5VCj6iH.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴哈克深蹲", "instructions_en": ["Start by standing with your feet shoulder-width apart and your toes slightly turned out.", "Hold the barbell behind your legs, resting it on your upper thighs.", "Lower your body by bending at the knees and hips, keeping your back straight and your chest up.", "Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.", "Pause for a moment, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先站立，双脚分开与肩同宽，脚趾稍微向外。", "将杠铃放在腿后面，将其放在大腿上部。", "弯曲膝盖和臀部，降低身体，保持背部挺直，挺胸。", "继续降低，直到大腿与地面平行，或者尽可能低。", "暂停片刻，然后用力推动脚后跟，回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["首先站立，雙腳分開與肩同寬，腳趾稍微向外。", "將杠鈴放在腿后面，將其放在大腿上部。", "彎曲膝蓋和臀部，降低身體，保持背部挺直，挺胸。", "繼續降低，直到大腿與地面平行，或者盡可能低。", "暫停片刻，然后用力推動腳后跟，回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1436', 'exercise', 1, '{"id": "1436", "target": "glutes", "name_en": "barbell high bar squat", "name_zh": "杠铃高杠位深蹲", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/1436-Gnfo4FM.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴高槓位深蹲", "instructions_en": ["Stand with your feet shoulder-width apart, toes slightly turned out.", "Place the barbell on your upper back, resting it on your traps.", "Engage your core and keep your chest up as you begin to squat down, pushing your hips back and bending your knees.", "Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go.", "Drive through your heels to stand back up, extending your hips and knees.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站立，双脚分开与肩同宽，脚趾稍微向外。", "将杠铃放在上背部，放在斜方肌上。", "当你开始蹲下时，启动你的核心并保持胸部挺直，将臀部向后推并弯曲膝盖。", "放低身体，直到大腿与地面平行，或者尽可能低到您能舒服的高度。", "通过脚后跟站起来，伸展臀部和膝盖。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves", "core"], "instructions_zh_hant": ["站立，雙腳分開與肩同寬，腳趾稍微向外。", "將杠鈴放在上背部，放在斜方肌上。", "當你開始蹲下時，啟動你的核心并保持胸部挺直，將臀部向后推并彎曲膝蓋。", "放低身體，直到大腿與地面平行，或者盡可能低到您能舒服的高度。", "通過腳后跟站起來，伸展臀部和膝蓋。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0052', 'exercise', 1, '{"id": "0052", "target": "triceps", "name_en": "barbell jm bench press", "name_zh": "杠铃JM卧推", "body_part": "upper arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0052-ZsiqXYa.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴JM臥推", "instructions_en": ["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.", "Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.", "Lower the barbell to your chest, keeping your elbows tucked in close to your body.", "Push the barbell back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，双脚平放在地上，背部紧贴长凳。", "正手握住杠铃，握距略宽于肩宽。", "将杠铃降低到胸部，保持肘部靠近身体。", "将杠铃推回到起始位置，完全伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["平躺在長凳上，雙腳平放在地上，背部緊貼長凳。", "正手握住杠鈴，握距略寬于肩寬。", "將杠鈴降低到胸部，保持肘部靠近身體。", "將杠鈴推回到起始位置，完全伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1719', 'exercise', 1, '{"id": "1719", "target": "triceps", "name_en": "barbell incline close grip bench press", "name_zh": "杠铃上斜窄握卧推", "body_part": "upper arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/1719-gx7s7uF.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴上斜窄握臥推", "instructions_en": ["Set up an incline bench at a 45-degree angle.", "Lie down on the bench with your feet flat on the ground.", "Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.", "Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.", "Pause for a moment when the barbell touches your chest.", "Push the barbell back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["设置一个 45 度角的上斜凳。", "躺在长凳上，双脚平放在地上。", "紧紧握住杠铃，握距略窄于肩宽。", "松开杠铃并将其缓慢降低至胸部，保持肘部靠近身体。", "当杠铃触及胸部时暂停片刻。", "将杠铃推回到起始位置，完全伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["設置一個 45 度角的上斜凳。", "躺在長凳上，雙腳平放在地上。", "緊緊握住杠鈴，握距略窄于肩寬。", "松開杠鈴并將其緩慢降低至胸部，保持肘部靠近身體。", "當杠鈴觸及胸部時暫停片刻。", "將杠鈴推回到起始位置，完全伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0048', 'exercise', 1, '{"id": "0048", "target": "triceps", "name_en": "barbell incline reverse-grip press", "name_zh": "杠铃上斜反握推举", "body_part": "upper arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0048-641mIfk.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴上斜反握推舉", "instructions_en": ["Set up an incline bench at a 45-degree angle.", "Lie back on the bench and grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.", "Unrack the barbell and lower it towards your upper chest, keeping your elbows tucked in.", "Pause for a moment at the bottom, then push the barbell back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["设置一个 45 度角的上斜凳。", "仰卧在长凳上，反握抓住杠铃，双手距离略宽于肩宽。", "松开杠铃并将其向上胸部降低，保持肘部内收。", "在底部停顿片刻，然后将杠铃推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["設置一個 45 度角的上斜凳。", "仰臥在長凳上，反握抓住杠鈴，雙手距離略寬于肩寬。", "松開杠鈴并將其向上胸部降低，保持肘部內收。", "在底部停頓片刻，然后將杠鈴推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0049', 'exercise', 1, '{"id": "0049", "target": "upper back", "name_en": "barbell incline row", "name_zh": "杠铃上斜划船", "body_part": "back", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0049-dmgMp3n.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴上斜劃船", "instructions_en": ["Set up an incline bench at a 45-degree angle.", "Lie face down on the bench with your chest against the pad and your feet flat on the ground.", "Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.", "Keep your back straight and your core engaged.", "Pull the barbell towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["设置一个 45 度角的上斜凳。", "脸朝下躺在长凳上，胸部靠在垫子上，双脚平放在地上。", "正手握住杠铃，握距略宽于肩宽。", "保持背部挺直，核心肌群参与。", "将杠铃拉向胸部，将肩胛骨挤压在一起。", "在顶部停顿片刻，然后慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["設置一個 45 度角的上斜凳。", "臉朝下躺在長凳上，胸部靠在墊子上，雙腳平放在地上。", "正手握住杠鈴，握距略寬于肩寬。", "保持背部挺直，核心肌群參與。", "將杠鈴拉向胸部，將肩胛骨擠壓在一起。", "在頂部停頓片刻，然后慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0050', 'exercise', 1, '{"id": "0050", "target": "serratus anterior", "name_en": "barbell incline shoulder raise", "name_zh": "杠铃上斜肩部抬举", "body_part": "chest", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0050-xi0yckC.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴上斜肩部抬舉", "instructions_en": ["Set up an incline bench at a 45-degree angle.", "Sit on the bench with your back against the pad and feet flat on the ground.", "Hold a barbell with an overhand grip, slightly wider than shoulder-width apart.", "Lift the barbell up to shoulder height, keeping your elbows slightly bent.", "Slowly raise the barbell overhead, extending your arms fully.", "Pause for a moment at the top, then slowly lower the barbell back to shoulder height.", "Repeat for the desired number of repetitions."], "instructions_zh": ["设置一个 45 度角的上斜凳。", "坐在长凳上，背部靠在垫子上，双脚平放在地面上。", "正手握住杠铃，杠铃间距略宽于肩宽。", "将杠铃举至肩膀高度，保持肘部稍微弯曲。", "慢慢地将杠铃举过头顶，充分伸展双臂。", "在顶部停顿片刻，然后慢慢将杠铃放回肩部高度。", "重复所需的重复次数。"], "secondary_muscles": ["deltoids", "trapezius"], "instructions_zh_hant": ["設置一個 45 度角的上斜凳。", "坐在長凳上，背部靠在墊子上，雙腳平放在地面上。", "正手握住杠鈴，杠鈴間距略寬于肩寬。", "將杠鈴舉至肩膀高度，保持肘部稍微彎曲。", "慢慢地將杠鈴舉過頭頂，充分伸展雙臂。", "在頂部停頓片刻，然后慢慢將杠鈴放回肩部高度。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0051', 'exercise', 1, '{"id": "0051", "target": "glutes", "name_en": "barbell jefferson squat", "name_zh": "杠铃杰斐逊深蹲", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0051-pkSoCW9.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴杰斐遜深蹲", "instructions_en": ["Stand with your feet shoulder-width apart and toes slightly turned out.", "Hold the barbell with an overhand grip, resting it on the front of your body, just below your waist.", "Step your left foot forward and your right foot back, keeping your feet shoulder-width apart.", "Bend your knees and lower your body down into a squat position, keeping your back straight and chest up.", "Push through your heels to stand back up to the starting position.", "Repeat the movement, alternating your forward and back foot with each repetition."], "instructions_zh": ["站立，双脚分开与肩同宽，脚趾稍微外翻。", "正手握住杠铃，将其放在身体前部、腰部下方。", "左脚向前迈出，右脚向后迈出，双脚分开与肩同宽。", "弯曲膝盖，将身体降低至蹲姿，保持背部挺直，挺胸。", "脚后跟用力，站回起始位置。", "重复该动作，每次重复时交替使用前脚和后脚。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["站立，雙腳分開與肩同寬，腳趾稍微外翻。", "正手握住杠鈴，將其放在身體前部、腰部下方。", "左腳向前邁出，右腳向后邁出，雙腳分開與肩同寬。", "彎曲膝蓋，將身體降低至蹲姿，保持背部挺直，挺胸。", "腳后跟用力，站回起始位置。", "重復該動作，每次重復時交替使用前腳和后腳。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0053', 'exercise', 1, '{"id": "0053", "target": "glutes", "name_en": "barbell jump squat", "name_zh": "杠铃跳跃深蹲", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0053-1gFNTZV.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴跳躍深蹲", "instructions_en": ["Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.", "Lower your body into a squat position by bending your knees and pushing your hips back.", "Once you reach the bottom of the squat, explode upwards by jumping off the ground.", "As you jump, extend your hips, knees, and ankles, pushing through your toes.", "Land softly back into the squat position and immediately repeat the movement for the desired number of repetitions."], "instructions_zh": ["首先，双脚分开与肩同宽站立，将杠铃放在上背部。", "弯曲膝盖并将臀部向后推，将身体降低至蹲姿。", "一旦到达深蹲底部，就从地面跳起向上爆发。", "跳跃时，伸展臀部、膝盖和脚踝，推动脚趾。", "轻轻地回到蹲姿，然后立即重复该动作达到所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["首先，雙腳分開與肩同寬站立，將杠鈴放在上背部。", "彎曲膝蓋并將臀部向后推，將身體降低至蹲姿。", "一旦到達深蹲底部，就從地面跳起向上爆發。", "跳躍時，伸展臀部、膝蓋和腳踝，推動腳趾。", "輕輕地回到蹲姿，然后立即重復該動作達到所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1410', 'exercise', 1, '{"id": "1410", "target": "glutes", "name_en": "barbell lateral lunge", "name_zh": "杠铃侧弓步", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/1410-py1HSzx.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴側弓步", "instructions_en": ["Stand with your feet shoulder-width apart, holding a barbell across your upper back.", "Take a big step to the side with your right foot, keeping your left foot planted.", "Bend your right knee and lower your body down into a lunge position, keeping your left leg straight.", "Push off with your right foot and return to the starting position.", "Repeat on the other side, stepping with your left foot."], "instructions_zh": ["双脚分开与肩同宽站立，将杠铃放在上背部。", "右脚向一侧迈出一大步，保持左脚踩地。", "弯曲右膝，将身体降低到弓步位置，保持左腿伸直。", "用右脚推出并返回到起始位置。", "在另一侧重复，用左脚迈步。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，將杠鈴放在上背部。", "右腳向一側邁出一大步，保持左腳踩地。", "彎曲右膝，將身體降低到弓步位置，保持左腿伸直。", "用右腳推出并返回到起始位置。", "在另一側重復，用左腳邁步。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1435', 'exercise', 1, '{"id": "1435", "target": "glutes", "name_en": "barbell low bar squat", "name_zh": "杠铃低杠位深蹲", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/1435-bTpEUcm.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴低槓位深蹲", "instructions_en": ["Stand with your feet shoulder-width apart and the barbell resting on your upper back.", "Keeping your chest up and core engaged, slowly lower your body by bending your knees and pushing your hips back.", "Continue lowering until your thighs are parallel to the ground or slightly below.", "Pause for a moment, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，杠铃放在上背部。", "保持挺胸，核心收紧，弯曲膝盖并向后推臀部，慢慢降低身体。", "继续降低，直到大腿与地面平行或略低于地面。", "暂停片刻，然后用力推动脚后跟，回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，杠鈴放在上背部。", "保持挺胸，核心收緊，彎曲膝蓋并向后推臀部，慢慢降低身體。", "繼續降低，直到大腿與地面平行或略低于地面。", "暫停片刻，然后用力推動腳后跟，回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1720', 'exercise', 1, '{"id": "1720", "target": "triceps", "name_en": "barbell lying back of the head tricep extension", "name_zh": "杠铃卧姿颈后臂屈伸", "body_part": "upper arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/1720-yg8Totb.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴臥姿頸后臂屈伸", "instructions_en": ["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.", "Hold a barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.", "Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows.", "Pause for a moment, then extend your arms back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，双脚平放在地上，头放在长凳的末端。", "正手握住杠铃，双手与肩同宽，将手臂伸直至胸部上方。", "保持上臂静止，弯曲肘部，慢慢将杠铃降低到脑后。", "暂停片刻，然后将手臂伸回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["平躺在長凳上，雙腳平放在地上，頭放在長凳的末端。", "正手握住杠鈴，雙手與肩同寬，將手臂伸直至胸部上方。", "保持上臂靜止，彎曲肘部，慢慢將杠鈴降低到腦后。", "暫停片刻，然后將手臂伸回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0082', 'exercise', 1, '{"id": "0082", "target": "forearms", "name_en": "barbell reverse wrist curl", "name_zh": "杠铃反握腕弯举", "body_part": "lower arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0082-LsZkfU6.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴反握腕彎舉", "instructions_en": ["Sit on a bench with your feet flat on the ground and hold a barbell with an overhand grip, palms facing down.", "Rest your forearms on your thighs, allowing your wrists to hang off the edge.", "Slowly curl your wrists upward, bringing the barbell towards your body.", "Pause for a moment at the top, then slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双脚平放在地上，正手握住杠铃，手掌朝下。", "将前臂放在大腿上，让手腕悬在边缘。", "慢慢向上弯曲手腕，将杠铃拉向身体。", "在顶部停顿片刻，然后慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "brachialis"], "instructions_zh_hant": ["坐在長凳上，雙腳平放在地上，正手握住杠鈴，手掌朝下。", "將前臂放在大腿上，讓手腕懸在邊緣。", "慢慢向上彎曲手腕，將杠鈴拉向身體。", "在頂部停頓片刻，然后慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0055', 'exercise', 1, '{"id": "0055", "target": "triceps", "name_en": "barbell lying close-grip press", "name_zh": "杠铃卧姿窄握推举", "body_part": "upper arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0055-EcaV7aL.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴臥姿窄握推舉", "instructions_en": ["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.", "Grasp the barbell with a close grip, hands shoulder-width apart, palms facing towards your feet.", "Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.", "Slowly lower the barbell towards your chest, keeping your elbows close to your body.", "Pause for a moment when the barbell touches your chest, then push it back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，双脚平放在地上，背部紧贴长凳。", "紧紧握住杠铃，双手与肩同宽，手掌朝向脚部。", "将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。", "慢慢地将杠铃降低到胸部，保持肘部靠近身体。", "当杠铃接触胸部时暂停片刻，然后将其推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["平躺在長凳上，雙腳平放在地上，背部緊貼長凳。", "緊緊握住杠鈴，雙手與肩同寬，手掌朝向腳部。", "將杠鈴從架子上提起，并將其直接放在胸部上方，雙臂完全伸展。", "慢慢地將杠鈴降低到胸部，保持肘部靠近身體。", "當杠鈴接觸胸部時暫停片刻，然后將其推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0056', 'exercise', 1, '{"id": "0056", "target": "triceps", "name_en": "barbell lying close-grip triceps extension", "name_zh": "杠铃卧姿窄握臂屈伸", "body_part": "upper arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0056-HJ63mSO.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴臥姿窄握臂屈伸", "instructions_en": ["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.", "Grasp the barbell with a close grip, hands shoulder-width apart, palms facing up.", "Extend your arms fully, lifting the barbell above your chest.", "Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.", "Pause for a moment at the bottom, then extend your arms back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，双脚平放在地上，头放在长凳的末端。", "紧握杠铃，双手与肩同宽，掌心向上。", "充分伸展双臂，将杠铃举至胸部上方。", "保持上臂静止，弯曲肘部，慢慢将杠铃降低到前额。", "在底部停顿片刻，然后将手臂伸展回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["平躺在長凳上，雙腳平放在地上，頭放在長凳的末端。", "緊握杠鈴，雙手與肩同寬，掌心向上。", "充分伸展雙臂，將杠鈴舉至胸部上方。", "保持上臂靜止，彎曲肘部，慢慢將杠鈴降低到前額。", "在底部停頓片刻，然后將手臂伸展回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0057', 'exercise', 1, '{"id": "0057", "target": "triceps", "name_en": "barbell lying extension", "name_zh": "杠铃仰卧臂屈伸", "body_part": "upper arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0057-EMpUwRI.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴仰臥臂屈伸", "instructions_en": ["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.", "Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.", "Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.", "Pause for a moment, then extend your arms back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，双脚平放在地上，头放在长凳的末端。", "正手握住杠铃，双手与肩同宽，将手臂伸直至胸部上方。", "保持上臂静止，弯曲肘部，慢慢将杠铃降低到前额。", "暂停片刻，然后将手臂伸回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["平躺在長凳上，雙腳平放在地上，頭放在長凳的末端。", "正手握住杠鈴，雙手與肩同寬，將手臂伸直至胸部上方。", "保持上臂靜止，彎曲肘部，慢慢將杠鈴降低到前額。", "暫停片刻，然后將手臂伸回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0058', 'exercise', 1, '{"id": "0058", "target": "glutes", "name_en": "barbell lying lifting (on hip)", "name_zh": "杠铃仰卧挺髋", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0058-SNFfUff.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴仰臥挺髖", "instructions_en": ["Lie flat on your back on a bench with your feet flat on the ground and your knees bent.", "Hold the barbell with an overhand grip and position it on your hips.", "Engaging your glutes, lift your hips off the bench until your body forms a straight line from your knees to your shoulders.", "Pause for a moment at the top, then slowly lower your hips back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["仰卧在长凳上，双脚平放在地上，膝盖弯曲。", "正手握住杠铃并将其放在臀部上。", "收紧臀部，将臀部抬离长凳，直到身体从膝盖到肩膀形成一条直线。", "在顶部暂停片刻，然后慢慢将臀部放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "quadriceps"], "instructions_zh_hant": ["仰臥在長凳上，雙腳平放在地上，膝蓋彎曲。", "正手握住杠鈴并將其放在臀部上。", "收緊臀部，將臀部抬離長凳，直到身體從膝蓋到肩膀形成一條直線。", "在頂部暫停片刻，然后慢慢將臀部放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0059', 'exercise', 1, '{"id": "0059", "target": "biceps", "name_en": "barbell lying preacher curl", "name_zh": "杠铃卧姿牧师凳弯举", "body_part": "upper arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0059-SYJ4Bkt.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴臥姿牧師凳彎舉", "instructions_en": ["Sit on a preacher bench with your chest against the pad and your arms extended over the edge, holding a barbell with an underhand grip.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在牧师长凳上，胸部靠在垫子上，手臂伸出边缘，反手握住杠铃。", "保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。", "继续抬高杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在牧師長凳上，胸部靠在墊子上，手臂伸出邊緣，反手握住杠鈴。", "保持上臂靜止，呼氣并彎舉啞鈴，同時收縮二頭肌。", "繼續抬高杠鈴，直到二頭肌完全收縮并且杠鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0061', 'exercise', 1, '{"id": "0061", "target": "triceps", "name_en": "barbell lying triceps extension", "name_zh": "杠铃卧姿臂屈伸", "body_part": "upper arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0061-iZop9xO.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴臥姿臂屈伸", "instructions_en": ["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.", "Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.", "Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.", "Pause for a moment at the bottom, then extend your arms back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，双脚平放在地上，头放在长凳的末端。", "正手握住杠铃，双手与肩同宽，将手臂伸直至胸部上方。", "保持上臂静止，弯曲肘部，慢慢将杠铃降低到前额。", "在底部停顿片刻，然后将手臂伸回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["平躺在長凳上，雙腳平放在地上，頭放在長凳的末端。", "正手握住杠鈴，雙手與肩同寬，將手臂伸直至胸部上方。", "保持上臂靜止，彎曲肘部，慢慢將杠鈴降低到前額。", "在底部停頓片刻，然后將手臂伸回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0060', 'exercise', 1, '{"id": "0060", "target": "triceps", "name_en": "barbell lying triceps extension skull crusher", "name_zh": "杠铃仰卧额前臂屈伸", "body_part": "upper arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0060-h8LFzo9.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴仰臥額前臂屈伸", "instructions_en": ["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.", "Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.", "Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.", "Pause for a moment when the barbell is just above your forehead, then extend your arms back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，双脚平放在地上，头放在长凳的末端。", "正手握住杠铃，双手与肩同宽，将手臂伸直至胸部上方。", "保持上臂静止，弯曲肘部，慢慢将杠铃降低到前额。", "当杠铃位于前额上方时暂停片刻，然后将手臂向后伸展至起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["平躺在長凳上，雙腳平放在地上，頭放在長凳的末端。", "正手握住杠鈴，雙手與肩同寬，將手臂伸直至胸部上方。", "保持上臂靜止，彎曲肘部，慢慢將杠鈴降低到前額。", "當杠鈴位于前額上方時暫停片刻，然后將手臂向后伸展至起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0063', 'exercise', 1, '{"id": "0063", "target": "glutes", "name_en": "barbell narrow stance squat", "name_zh": "杠铃窄站距深蹲", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0063-elhhVgj.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴窄站距深蹲", "instructions_en": ["Stand with your feet shoulder-width apart and toes pointing slightly outward.", "Hold the barbell across your upper back, resting it on your traps or rear delts.", "Engage your core and keep your chest up as you slowly lower your body by bending your knees and pushing your hips back.", "Continue lowering until your thighs are parallel to the ground or slightly below.", "Pause for a moment, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站立，双脚分开与肩同宽，脚趾稍微向外。", "将杠铃放在上背部，将其放在斜方肌或三角肌后束上。", "收紧核心并保持挺胸，同时弯曲膝盖并向后推臀部，慢慢降低身体。", "继续降低，直到大腿与地面平行或略低于地面。", "暂停片刻，然后用力推动脚后跟，回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["站立，雙腳分開與肩同寬，腳趾稍微向外。", "將杠鈴放在上背部，將其放在斜方肌或三角肌后束上。", "收緊核心并保持挺胸，同時彎曲膝蓋并向后推臀部，慢慢降低身體。", "繼續降低，直到大腿與地面平行或略低于地面。", "暫停片刻，然后用力推動腳后跟，回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0064', 'exercise', 1, '{"id": "0064", "target": "upper back", "name_en": "barbell one arm bent over row", "name_zh": "杠铃单臂俯身划船", "body_part": "back", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0064-Jsgsc27.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴單臂俯身劃船", "instructions_en": ["Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with one hand using an overhand grip.", "Bend forward at the hips, keeping your back straight and your head in a neutral position.", "Pull the barbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.", "Lower the barbell back down to the starting position in a controlled manner.", "Repeat for the desired number of repetitions, then switch to the other arm."], "instructions_zh": ["双脚分开与肩同宽站立，膝盖稍微弯曲，用一只手正握握住杠铃。", "臀部向前弯曲，保持背部挺直，头部处于中立位置。", "将杠铃向上拉向胸部，保持肘部靠近身体并将肩胛骨挤压在一起。", "以受控的方式将杠铃降低回起始位置。", "重复所需的重复次数，然后换到另一只手臂。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，膝蓋稍微彎曲，用一只手正握握住杠鈴。", "臀部向前彎曲，保持背部挺直，頭部處于中立位置。", "將杠鈴向上拉向胸部，保持肘部靠近身體并將肩胛骨擠壓在一起。", "以受控的方式將杠鈴降低回起始位置。", "重復所需的重復次數，然后換到另一只手臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0065', 'exercise', 1, '{"id": "0065", "target": "triceps", "name_en": "barbell one arm floor press", "name_zh": "杠铃单臂地板卧推", "body_part": "upper arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0065-vtusOWT.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴單臂地板臥推", "instructions_en": ["Lie flat on your back on the floor with your knees bent and feet flat on the ground.", "Hold the barbell with one hand, palm facing up, and extend your arm straight up over your chest.", "Slowly lower the barbell towards your chest, keeping your elbow close to your body.", "Pause for a moment at the bottom, then push the barbell back up to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["仰卧在地板上，膝盖弯曲，双脚平放在地面上。", "用一只手握住杠铃，掌心朝上，将手臂伸直至胸部上方。", "慢慢地将杠铃降低到胸部，保持肘部靠近身体。", "在底部停顿片刻，然后将杠铃推回到起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["仰臥在地板上，膝蓋彎曲，雙腳平放在地面上。", "用一只手握住杠鈴，掌心朝上，將手臂伸直至胸部上方。", "慢慢地將杠鈴降低到胸部，保持肘部靠近身體。", "在底部停頓片刻，然后將杠鈴推回到起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0066', 'exercise', 1, '{"id": "0066", "target": "glutes", "name_en": "barbell one arm side deadlift", "name_zh": "杠铃单臂侧硬拉", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0066-2DxtqHL.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴單臂側硬拉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a barbell in one hand with an overhand grip.", "Keep your back straight and your core engaged.", "Bend at the hips and lower the barbell towards the outside of your leg, keeping your arm straight and your chest up.", "Lower the barbell as far as you can while maintaining good form.", "Pause for a moment, then slowly return to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["双脚分开与肩同宽站立，一只手握住杠铃，正握。", "保持背部挺直，核心肌群参与。", "臀部弯曲，将杠铃向腿外侧放低，保持手臂伸直，挺胸。", "尽可能降低杠铃，同时保持良好的姿势。", "暂停片刻，然后慢慢回到起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["hamstrings", "quadriceps", "lower back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，一只手握住杠鈴，正握。", "保持背部挺直，核心肌群參與。", "臀部彎曲，將杠鈴向腿外側放低，保持手臂伸直，挺胸。", "盡可能降低杠鈴，同時保持良好的姿勢。", "暫停片刻，然后慢慢回到起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0067', 'exercise', 1, '{"id": "0067", "target": "delts", "name_en": "barbell one arm snatch", "name_zh": "杠铃单臂抓举", "body_part": "shoulders", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0067-xHKN2s8.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴單臂抓舉", "instructions_en": ["Stand with your feet shoulder-width apart, toes pointing slightly outwards.", "Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.", "Bend your knees and lower your hips into a squat position, keeping your back straight and chest up.", "Explosively extend your hips, knees, and ankles, driving the barbell upwards.", "As the barbell reaches chest level, pull it upwards with your arm, keeping it close to your body.", "Rotate your elbow under the barbell and extend your arm fully overhead, locking out your elbow.", "Lower the barbell back down to the starting position in a controlled manner.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["双脚分开与肩同宽站立，脚趾稍微向外。", "正手握住杠铃，双手分开略宽于肩宽。", "弯曲膝盖，降低臀部至下蹲位置，保持背部挺直，挺胸。", "爆发性伸展臀部、膝盖和脚踝，将杠铃向上推。", "当杠铃到达胸部水平时，用手臂将其向上拉，使其靠近身体。", "将肘部旋转到杠铃下方，并将手臂完全伸过头顶，锁定肘部。", "以受控的方式将杠铃降低回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["traps", "forearms", "core"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，腳趾稍微向外。", "正手握住杠鈴，雙手分開略寬于肩寬。", "彎曲膝蓋，降低臀部至下蹲位置，保持背部挺直，挺胸。", "爆發性伸展臀部、膝蓋和腳踝，將杠鈴向上推。", "當杠鈴到達胸部水平時，用手臂將其向上拉，使其靠近身體。", "將肘部旋轉到杠鈴下方，并將手臂完全伸過頭頂，鎖定肘部。", "以受控的方式將杠鈴降低回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0068', 'exercise', 1, '{"id": "0068", "target": "quads", "name_en": "barbell one leg squat", "name_zh": "杠铃单腿深蹲", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0068-uKyN64F.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴單腿深蹲", "instructions_en": ["Stand with your feet shoulder-width apart and hold a barbell across your upper back.", "Lift one foot off the ground and extend it forward, keeping it parallel to the ground.", "Bend your standing leg and lower your body down as if sitting back into a chair, keeping your chest up and your back straight.", "Lower yourself until your thigh is parallel to the ground, then push through your heel to return to the starting position.", "Repeat for the desired number of repetitions, then switch legs and repeat."], "instructions_zh": ["双脚分开与肩同宽站立，将杠铃放在上背部。", "将一只脚抬离地面并向前伸展，保持与地面平行。", "弯曲站立的腿，放低身体，就像坐回椅子上一样，保持挺胸、背部挺直。", "降低身体直到大腿与地面平行，然后通过脚后跟推回到起始位置。", "重复所需的重复次数，然后换腿并重复。"], "secondary_muscles": ["glutes", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，將杠鈴放在上背部。", "將一只腳抬離地面并向前伸展，保持與地面平行。", "彎曲站立的腿，放低身體，就像坐回椅子上一樣，保持挺胸、背部挺直。", "降低身體直到大腿與地面平行，然后通過腳后跟推回到起始位置。", "重復所需的重復次數，然后換腿并重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0069', 'exercise', 1, '{"id": "0069", "target": "quads", "name_en": "barbell overhead squat", "name_zh": "杠铃过顶深蹲", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0069-gfk9kD4.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴過頂深蹲", "instructions_en": ["Stand with your feet shoulder-width apart and toes slightly turned out.", "Hold the barbell with a wide grip, positioning it overhead with your arms fully extended.", "Engage your core and lower your body down into a squat position, keeping your chest up and knees tracking over your toes.", "Pause for a moment at the bottom, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站立，双脚分开与肩同宽，脚趾稍微外翻。", "宽握距握住杠铃，将其置于头顶，双臂完全伸展。", "收紧核心肌群，将身体放低至蹲姿，保持胸部向上，膝盖位于脚趾上方。", "在底部停顿片刻，然后推动脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings", "calves", "core"], "instructions_zh_hant": ["站立，雙腳分開與肩同寬，腳趾稍微外翻。", "寬握距握住杠鈴，將其置于頭頂，雙臂完全伸展。", "收緊核心肌群，將身體放低至蹲姿，保持胸部向上，膝蓋位于腳趾上方。", "在底部停頓片刻，然后推動腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1411', 'exercise', 1, '{"id": "1411", "target": "forearms", "name_en": "barbell palms down wrist curl over a bench", "name_zh": "杠铃凳上正握腕弯举", "body_part": "lower arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/1411-yzYH9pI.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴凳上正握腕彎舉", "instructions_en": ["Sit on a bench with your feet flat on the ground and your forearms resting on your thighs, palms facing down.", "Hold a barbell with an overhand grip, hands shoulder-width apart.", "Lower the barbell towards the ground by flexing your wrists, keeping your forearms stationary.", "Pause for a moment at the bottom, then slowly raise the barbell back up by extending your wrists.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双脚平放在地上，前臂放在大腿上，手掌朝下。", "正手握住杠铃，双手与肩同宽。", "弯曲手腕，将杠铃降低到地面，保持前臂静止。", "在底部停顿片刻，然后通过伸展手腕慢慢将杠铃举起。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "brachialis"], "instructions_zh_hant": ["坐在長凳上，雙腳平放在地上，前臂放在大腿上，手掌朝下。", "正手握住杠鈴，雙手與肩同寬。", "彎曲手腕，將杠鈴降低到地面，保持前臂靜止。", "在底部停頓片刻，然后通過伸展手腕慢慢將杠鈴舉起。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1412', 'exercise', 1, '{"id": "1412", "target": "forearms", "name_en": "barbell palms up wrist curl over a bench", "name_zh": "杠铃凳上反握腕弯举", "body_part": "lower arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/1412-SJAA2IQ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴凳上反握腕彎舉", "instructions_en": ["Sit on a bench with your feet flat on the ground and hold a barbell with an underhand grip, palms facing up.", "Rest your forearms on the bench, allowing your wrists to hang off the edge.", "Keeping your forearms stationary, exhale and curl your wrists upwards as far as possible.", "Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双脚平放在地面上，反手握住杠铃，手掌朝上。", "将前臂放在长凳上，让手腕悬在长凳边缘。", "保持前臂静止，呼气并尽可能向上弯曲手腕。", "保持收缩位置短暂停顿，然后吸气并慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "shoulders"], "instructions_zh_hant": ["坐在長凳上，雙腳平放在地面上，反手握住杠鈴，手掌朝上。", "將前臂放在長凳上，讓手腕懸在長凳邊緣。", "保持前臂靜止，呼氣并盡可能向上彎曲手腕。", "保持收縮位置短暫停頓，然后吸氣并慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3017', 'exercise', 1, '{"id": "3017", "target": "upper back", "name_en": "barbell pendlay row", "name_zh": "杠铃潘德雷划船", "body_part": "back", "equipment": "barbell", "gif_asset": "assets/fitness/videos/3017-r0z6xzQ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴潘德雷劃船", "instructions_en": ["Stand with your feet shoulder-width apart and your knees slightly bent.", "Bend forward at the hips, keeping your back straight and your chest up.", "Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.", "Pull the barbell towards your upper abdomen, squeezing your shoulder blades together.", "Lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，膝盖稍微弯曲。", "臀部向前弯曲，保持背部挺直，挺胸。", "正手握住杠铃，握距略宽于肩宽。", "将杠铃拉向上腹部，将肩胛骨挤压在一起。", "将杠铃降低回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，膝蓋稍微彎曲。", "臀部向前彎曲，保持背部挺直，挺胸。", "正手握住杠鈴，握距略寬于肩寬。", "將杠鈴拉向上腹部，將肩胛骨擠壓在一起。", "將杠鈴降低回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1751', 'exercise', 1, '{"id": "1751", "target": "triceps", "name_en": "barbell pin presses", "name_zh": "杠铃架上推举", "body_part": "upper arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/1751-bndCa3Q.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴架上推舉", "instructions_en": ["Set up a barbell on a power rack at chest height.", "Stand facing the barbell and position yourself underneath it, with your feet shoulder-width apart.", "Grip the barbell with an overhand grip, slightly wider than shoulder-width apart.", "Lift the barbell off the rack and hold it directly above your chest, with your arms fully extended.", "Lower the barbell down towards your chest, keeping your elbows tucked in close to your body.", "Pause for a moment when the barbell touches your chest.", "Push the barbell back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将杠铃放在与胸部同高的力量架上。", "面向杠铃站立，将自己置于杠铃下方，双脚分开与肩同宽。", "正手握住杠铃，握距略宽于肩宽。", "将杠铃从架子上提起，并将其保持在胸部正上方，双臂完全伸展。", "将杠铃向胸部方向降低，保持肘部靠近身体。", "当杠铃触及胸部时暂停片刻。", "将杠铃推回到起始位置，完全伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["將杠鈴放在與胸部同高的力量架上。", "面向杠鈴站立，將自己置于杠鈴下方，雙腳分開與肩同寬。", "正手握住杠鈴，握距略寬于肩寬。", "將杠鈴從架子上提起，并將其保持在胸部正上方，雙臂完全伸展。", "將杠鈴向胸部方向降低，保持肘部靠近身體。", "當杠鈴觸及胸部時暫停片刻。", "將杠鈴推回到起始位置，完全伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0070', 'exercise', 1, '{"id": "0070", "target": "biceps", "name_en": "barbell preacher curl", "name_zh": "杠铃牧师凳弯举", "body_part": "upper arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0070-qOgPVf6.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴牧師凳彎舉", "instructions_en": ["Sit on a preacher bench with your upper arms resting on the pad and your chest against the support.", "Grasp the barbell with an underhand grip, slightly wider than shoulder-width apart.", "Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.", "Pause for a moment at the top, squeezing your biceps.", "Inhale and slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在牧师凳上，上臂放在垫子上，胸部靠在支撑物上。", "反手握住杠铃，握距略宽于肩宽。", "保持上臂静止，呼气并将杠铃向上弯向肩膀。", "在顶部暂停片刻，挤压你的二头肌。", "吸气并慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在牧師凳上，上臂放在墊子上，胸部靠在支撐物上。", "反手握住杠鈴，握距略寬于肩寬。", "保持上臂靜止，呼氣并將杠鈴向上彎向肩膀。", "在頂部暫停片刻，擠壓你的二頭肌。", "吸氣并慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0071', 'exercise', 1, '{"id": "0071", "target": "abs", "name_en": "barbell press sit-up", "name_zh": "杠铃推举仰卧起坐", "body_part": "waist", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0071-wnEscH8.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴推舉仰臥起坐", "instructions_en": ["Lie flat on your back on a mat with your knees bent and feet flat on the ground.", "Hold the barbell with an overhand grip, resting it on your chest.", "Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在垫子上，膝盖弯曲，双脚平放在地上。", "正手握住杠铃，将其放在胸前。", "收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。", "在顶部停顿片刻，然后慢慢将上半身放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "chest"], "instructions_zh_hant": ["平躺在墊子上，膝蓋彎曲，雙腳平放在地上。", "正手握住杠鈴，將其放在胸前。", "收緊腹肌，慢慢將上半身抬離地面，向前卷曲，直到軀幹呈 45 度角。", "在頂部停頓片刻，然后慢慢將上半身放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0072', 'exercise', 1, '{"id": "0072", "target": "biceps", "name_en": "barbell prone incline curl", "name_zh": "杠铃俯卧上斜弯举", "body_part": "upper arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0072-WLvTAv5.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴俯臥上斜彎舉", "instructions_en": ["Set up an incline bench at a 45-degree angle.", "Lie face down on the bench with your chest and stomach resting against it.", "Hold a barbell with an underhand grip, shoulder-width apart.", "Extend your arms fully, allowing the barbell to hang down towards the floor.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["设置一个 45 度角的上斜凳。", "脸朝下躺在长凳上，胸部和腹部靠在长凳上。", "反手握住杠铃，距离与肩同宽。", "充分伸展双臂，让杠铃垂向地板。", "保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。", "继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["設置一個 45 度角的上斜凳。", "臉朝下躺在長凳上，胸部和腹部靠在長凳上。", "反手握住杠鈴，距離與肩同寬。", "充分伸展雙臂，讓杠鈴垂向地板。", "保持上臂靜止，呼氣并彎舉啞鈴，同時收縮二頭肌。", "繼續舉起杠鈴，直到二頭肌完全收縮并且杠鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0073', 'exercise', 1, '{"id": "0073", "target": "lats", "name_en": "barbell pullover", "name_zh": "杠铃仰卧上拉", "body_part": "back", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0073-i6LWjok.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴仰臥上拉", "instructions_en": ["Lie flat on a bench with your head at one end and your feet on the floor.", "Hold a barbell with a shoulder-width grip and extend your arms straight above your chest.", "Keeping your arms straight, lower the barbell behind your head in a controlled manner until you feel a stretch in your lats.", "Pause for a moment, then raise the barbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，头放在一端，双脚放在地板上。", "握距与肩同宽，握住杠铃，将手臂伸直至胸部上方。", "保持手臂伸直，以受控的方式将杠铃降低到头后，直到感觉到背阔肌被拉伸。", "暂停片刻，然后将杠铃举回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "triceps"], "instructions_zh_hant": ["平躺在長凳上，頭放在一端，雙腳放在地板上。", "握距與肩同寬，握住杠鈴，將手臂伸直至胸部上方。", "保持手臂伸直，以受控的方式將杠鈴降低到頭后，直到感覺到背闊肌被拉伸。", "暫停片刻，然后將杠鈴舉回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1371', 'exercise', 1, '{"id": "1371", "target": "calves", "name_en": "barbell seated calf raise", "name_zh": "杠铃坐姿提踵", "body_part": "lower legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/1371-ipvgBnC.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴坐姿提踵", "instructions_en": ["Sit on a bench with your feet flat on the floor and a barbell resting on your thighs.", "Place the balls of your feet on a raised platform, such as a block or step.", "Lower your heels as far as possible, feeling a stretch in your calves.", "Raise your heels as high as possible, contracting your calves.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双脚平放在地板上，杠铃放在大腿上。", "将脚掌放在升高的平台上，例如木块或台阶。", "尽可能降低脚后跟，感受小腿的拉伸。", "尽可能高地抬高脚后跟，收缩小腿。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings"], "instructions_zh_hant": ["坐在長凳上，雙腳平放在地板上，杠鈴放在大腿上。", "將腳掌放在升高的平臺上，例如木塊或臺階。", "盡可能降低腳后跟，感受小腿的拉伸。", "盡可能高地抬高腳后跟，收縮小腿。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0022', 'exercise', 1, '{"id": "0022", "target": "lats", "name_en": "barbell pullover to press", "name_zh": "杠铃仰卧上拉至推举", "body_part": "back", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0022-znLogoF.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴仰臥上拉至推舉", "instructions_en": ["Lie flat on a bench with your head at one end and your feet on the ground.", "Hold the barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest.", "Keeping your arms straight, lower the barbell behind your head in an arc-like motion until you feel a stretch in your lats.", "Pause for a moment, then reverse the motion and press the barbell back to the starting position above your chest.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，头朝一端，双脚着地。", "旋前握住杠铃（手掌背向您），并将手臂伸直至胸部上方。", "保持手臂伸直，以弧形动作将杠铃降低到脑后，直到感觉到背阔肌有拉伸感。", "暂停片刻，然后反转动作，将杠铃推回到胸部上方的起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "chest", "shoulders"], "instructions_zh_hant": ["平躺在長凳上，頭朝一端，雙腳著地。", "旋前握住杠鈴（手掌背向您），并將手臂伸直至胸部上方。", "保持手臂伸直，以弧形動作將杠鈴降低到腦后，直到感覺到背闊肌有拉伸感。", "暫停片刻，然后反轉動作，將杠鈴推回到胸部上方的起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0074', 'exercise', 1, '{"id": "0074", "target": "glutes", "name_en": "barbell rack pull", "name_zh": "杠铃架上硬拉", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0074-za9Ni4z.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴架上硬拉", "instructions_en": ["Set up a barbell on a rack at knee height.", "Stand with your feet shoulder-width apart, toes pointing slightly outwards.", "Bend at the hips and knees to lower yourself down and grip the barbell with an overhand grip, hands shoulder-width apart.", "Engage your core and lift the barbell by extending your hips and knees, pulling your shoulders back and squeezing your glutes at the top.", "Lower the barbell back down to the starting position by bending at the hips and knees.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将杠铃放在膝盖高度的架子上。", "双脚分开与肩同宽站立，脚趾稍微向外。", "弯曲臀部和膝盖，降低身体高度，正手握住杠铃，双手与肩同宽。", "通过伸展臀部和膝盖、向后拉肩膀并在顶部挤压臀部来收紧核心并举起杠铃。", "弯曲臀部和膝盖，将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "lower back"], "instructions_zh_hant": ["將杠鈴放在膝蓋高度的架子上。", "雙腳分開與肩同寬站立，腳趾稍微向外。", "彎曲臀部和膝蓋，降低身體高度，正手握住杠鈴，雙手與肩同寬。", "通過伸展臀部和膝蓋、向后拉肩膀并在頂部擠壓臀部來收緊核心并舉起杠鈴。", "彎曲臀部和膝蓋，將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0075', 'exercise', 1, '{"id": "0075", "target": "delts", "name_en": "barbell rear delt raise", "name_zh": "杠铃后束飞鸟", "body_part": "shoulders", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0075-Ln9iTbU.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴后束飛鳥", "instructions_en": ["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Raise the barbell out to the sides, keeping your arms straight, until they are parallel to the ground.", "Pause for a moment at the top, then slowly lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，正手握住杠铃，手掌朝下。", "稍微弯曲膝盖，髋部向前转动，保持背部挺直。", "将杠铃向两侧举起，保持手臂伸直，直到它们与地面平行。", "在顶部停顿片刻，然后慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["traps", "rhomboids"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，正手握住杠鈴，手掌朝下。", "稍微彎曲膝蓋，髖部向前轉動，保持背部挺直。", "將杠鈴向兩側舉起，保持手臂伸直，直到它們與地面平行。", "在頂部停頓片刻，然后慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0076', 'exercise', 1, '{"id": "0076", "target": "delts", "name_en": "barbell rear delt row", "name_zh": "杠铃三角肌后束划船", "body_part": "shoulders", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0076-S9zHIvU.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴三角肌后束劃船", "instructions_en": ["Stand with your feet shoulder-width apart and knees slightly bent.", "Hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.", "Bend forward at the hips, keeping your back straight and chest up.", "Pull the barbell towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站立，双脚分开与肩同宽，膝盖稍微弯曲。", "正手握住杠铃，双手分开略宽于肩宽。", "臀部向前弯曲，保持背部挺直，挺胸。", "将杠铃拉向胸部，将肩胛骨挤压在一起。", "在顶部停顿片刻，然后慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["trapezius", "rhomboids", "biceps"], "instructions_zh_hant": ["站立，雙腳分開與肩同寬，膝蓋稍微彎曲。", "正手握住杠鈴，雙手分開略寬于肩寬。", "臀部向前彎曲，保持背部挺直，挺胸。", "將杠鈴拉向胸部，將肩胛骨擠壓在一起。", "在頂部停頓片刻，然后慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0078', 'exercise', 1, '{"id": "0078", "target": "glutes", "name_en": "barbell rear lunge", "name_zh": "杠铃后撤弓步", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0078-VaP75jl.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴后撤弓步", "instructions_en": ["Start by standing with your feet shoulder-width apart and a barbell resting on your upper back.", "Take a step backward with your right foot, landing on the ball of your foot.", "Bend both knees to lower your body until your left thigh is parallel to the ground.", "Push through your left heel to return to the starting position.", "Repeat with the other leg."], "instructions_zh": ["首先，双脚分开与肩同宽，将杠铃放在上背部。", "右脚向后退一步，用脚掌着地。", "弯曲双膝降低身体，直到左大腿与地面平行。", "推动左脚跟返回到起始位置。", "换另一条腿重复上述步骤。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["首先，雙腳分開與肩同寬，將杠鈴放在上背部。", "右腳向后退一步，用腳掌著地。", "彎曲雙膝降低身體，直到左大腿與地面平行。", "推動左腳跟返回到起始位置。", "換另一條腿重復上述步驟。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0077', 'exercise', 1, '{"id": "0077", "target": "glutes", "name_en": "barbell rear lunge v. 2", "name_zh": "杠铃后撤弓步变式2", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0077-62Nw60O.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴后撤弓步變式2", "instructions_en": ["Stand with your feet shoulder-width apart and hold a barbell across your upper back.", "Take a step backward with your right foot, landing on the ball of your foot.", "Bend both knees to lower your body until your left thigh is parallel to the ground.", "Push through your left heel to return to the starting position.", "Repeat with the other leg."], "instructions_zh": ["双脚分开与肩同宽站立，将杠铃放在上背部。", "右脚向后退一步，用脚掌着地。", "弯曲双膝降低身体，直到左大腿与地面平行。", "推动左脚跟返回到起始位置。", "换另一条腿重复上述步骤。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，將杠鈴放在上背部。", "右腳向后退一步，用腳掌著地。", "彎曲雙膝降低身體，直到左大腿與地面平行。", "推動左腳跟返回到起始位置。", "換另一條腿重復上述步驟。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0079', 'exercise', 1, '{"id": "0079", "target": "forearms", "name_en": "barbell revers wrist curl v. 2", "name_zh": "杠铃反向腕弯举变式2", "body_part": "lower arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0079-qDnGfDb.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴反向腕彎舉變式2", "instructions_en": ["Sit on a bench with your feet flat on the ground and your knees bent.", "Hold a barbell with an overhand grip, palms facing down, and your hands shoulder-width apart.", "Rest your forearms on your thighs, allowing your wrists to hang off the edge.", "Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.", "Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双脚平放在地上，膝盖弯曲。", "正手握住杠铃，手掌朝下，双手与肩同宽。", "将前臂放在大腿上，让手腕悬在边缘。", "保持前臂静止，呼气并尽可能向上弯曲手腕。", "保持收缩位置短暂停顿，然后吸气并慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "brachialis"], "instructions_zh_hant": ["坐在長凳上，雙腳平放在地上，膝蓋彎曲。", "正手握住杠鈴，手掌朝下，雙手與肩同寬。", "將前臂放在大腿上，讓手腕懸在邊緣。", "保持前臂靜止，呼氣并盡可能向上彎曲手腕。", "保持收縮位置短暫停頓，然后吸氣并慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2187', 'exercise', 1, '{"id": "2187", "target": "triceps", "name_en": "barbell reverse close-grip bench press", "name_zh": "杠铃反向窄握卧推", "body_part": "upper arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/2187-YqJw82s.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴反向窄握臥推", "instructions_en": ["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.", "Grasp the barbell with a reverse grip, hands shoulder-width apart.", "Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.", "Slowly lower the barbell down towards your chest, keeping your elbows close to your body.", "Pause for a moment when the barbell is just above your chest.", "Push the barbell back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，双脚平放在地上，背部紧贴长凳。", "反握抓住杠铃，双手与肩同宽。", "将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。", "慢慢地将杠铃向胸部降低，保持肘部靠近身体。", "当杠铃位于胸部正上方时，暂停片刻。", "将杠铃推回到起始位置，完全伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["平躺在長凳上，雙腳平放在地上，背部緊貼長凳。", "反握抓住杠鈴，雙手與肩同寬。", "將杠鈴從架子上提起，并將其直接放在胸部上方，雙臂完全伸展。", "慢慢地將杠鈴向胸部降低，保持肘部靠近身體。", "當杠鈴位于胸部正上方時，暫停片刻。", "將杠鈴推回到起始位置，完全伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0080', 'exercise', 1, '{"id": "0080", "target": "biceps", "name_en": "barbell reverse curl", "name_zh": "杠铃反向弯举", "body_part": "upper arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0080-xNrS20v.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴反向彎舉", "instructions_en": ["Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.", "Keep your upper arms stationary and exhale as you curl the barbell upward, contracting your biceps.", "Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale as you slowly lower the barbell back to the starting position, keeping your upper arms stationary.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站直，双脚分开与肩同宽，正手握住杠铃，手掌朝下。", "保持上臂静止，向上弯举杠铃时呼气，收缩二头肌。", "继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气，慢慢将杠铃放回起始位置，保持上臂静止。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙腳分開與肩同寬，正手握住杠鈴，手掌朝下。", "保持上臂靜止，向上彎舉杠鈴時呼氣，收縮二頭肌。", "繼續舉起杠鈴，直到二頭肌完全收縮并且杠鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣，慢慢將杠鈴放回起始位置，保持上臂靜止。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0118', 'exercise', 1, '{"id": "0118", "target": "upper back", "name_en": "barbell reverse grip bent over row", "name_zh": "杠铃反握俯身划船", "body_part": "back", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0118-SzX3uzM.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴反握俯身劃船", "instructions_en": ["Stand with your feet shoulder-width apart and knees slightly bent.", "Hold a barbell with an overhand grip, palms facing down, and hands slightly wider than shoulder-width apart.", "Bend forward at the hips, keeping your back straight and chest up, until your torso is almost parallel to the floor.", "Pull the barbell towards your lower chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站立，双脚分开与肩同宽，膝盖稍微弯曲。", "正手握住杠铃，手掌朝下，双手分开略宽于肩宽。", "臀部向前弯曲，保持背部挺直，挺胸，直到躯干几乎与地板平行。", "将杠铃拉向下胸部，将肩胛骨挤压在一起。", "在顶部停顿片刻，然后慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["站立，雙腳分開與肩同寬，膝蓋稍微彎曲。", "正手握住杠鈴，手掌朝下，雙手分開略寬于肩寬。", "臀部向前彎曲，保持背部挺直，挺胸，直到軀幹幾乎與地板平行。", "將杠鈴拉向下胸部，將肩胛骨擠壓在一起。", "在頂部停頓片刻，然后慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1256', 'exercise', 1, '{"id": "1256", "target": "pectorals", "name_en": "barbell reverse grip decline bench press", "name_zh": "杠铃反握下斜卧推", "body_part": "chest", "equipment": "barbell", "gif_asset": "assets/fitness/videos/1256-DotAgEF.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴反握下斜臥推", "instructions_en": ["Lie on a decline bench with your feet secured and your head lower than your hips.", "Grasp the barbell with a reverse grip, slightly wider than shoulder-width apart.", "Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.", "Pause for a moment at the bottom, then push the barbell back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["躺在倾斜的长凳上，双脚固定，头部低于臀部。", "反握抓住杠铃，握距略宽于肩宽。", "松开杠铃，慢慢将其降低到胸部，保持肘部内收。", "在底部停顿片刻，然后将杠铃推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["躺在傾斜的長凳上，雙腳固定，頭部低于臀部。", "反握抓住杠鈴，握距略寬于肩寬。", "松開杠鈴，慢慢將其降低到胸部，保持肘部內收。", "在底部停頓片刻，然后將杠鈴推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1257', 'exercise', 1, '{"id": "1257", "target": "pectorals", "name_en": "barbell reverse grip incline bench press", "name_zh": "杠铃反握上斜卧推", "body_part": "chest", "equipment": "barbell", "gif_asset": "assets/fitness/videos/1257-DU7I633.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴反握上斜臥推", "instructions_en": ["Set up an incline bench at a 45-degree angle.", "Lie down on the bench with your feet flat on the ground.", "Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.", "Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.", "Pause for a moment when the barbell touches your chest.", "Push the barbell back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["设置一个 45 度角的上斜凳。", "躺在长凳上，双脚平放在地上。", "反握抓住杠铃，双手分开略宽于肩宽。", "松开杠铃，慢慢将其降低到胸部，保持肘部内收。", "当杠铃触及胸部时暂停片刻。", "将杠铃推回到起始位置，完全伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["設置一個 45 度角的上斜凳。", "躺在長凳上，雙腳平放在地上。", "反握抓住杠鈴，雙手分開略寬于肩寬。", "松開杠鈴，慢慢將其降低到胸部，保持肘部內收。", "當杠鈴觸及胸部時暫停片刻。", "將杠鈴推回到起始位置，完全伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1317', 'exercise', 1, '{"id": "1317", "target": "upper back", "name_en": "barbell reverse grip incline bench row", "name_zh": "杠铃反握上斜凳上划船", "body_part": "back", "equipment": "barbell", "gif_asset": "assets/fitness/videos/1317-8d8qJQI.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴反握上斜凳上劃船", "instructions_en": ["Set up an incline bench at a 45-degree angle.", "Sit on the bench facing the backrest with your chest against it.", "Grab the barbell with a reverse grip (palms facing down) and hands slightly wider than shoulder-width apart.", "Keep your back straight and core engaged.", "Pull the barbell towards your upper abdomen, squeezing your shoulder blades together.", "Pause for a moment at the top of the movement.", "Slowly lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["设置一个 45 度角的上斜凳。", "坐在长凳上，面向靠背，胸部靠在靠背上。", "反握（手掌朝下）抓住杠铃，双手距离略宽于肩宽。", "保持背部挺直，核心参与。", "将杠铃拉向上腹部，将肩胛骨挤压在一起。", "在动作的最高点停顿片刻。", "慢慢地将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["設置一個 45 度角的上斜凳。", "坐在長凳上，面向靠背，胸部靠在靠背上。", "反握（手掌朝下）抓住杠鈴，雙手距離略寬于肩寬。", "保持背部挺直，核心參與。", "將杠鈴拉向上腹部，將肩胛骨擠壓在一起。", "在動作的最高點停頓片刻。", "慢慢地將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1721', 'exercise', 1, '{"id": "1721", "target": "triceps", "name_en": "barbell reverse grip skullcrusher", "name_zh": "杠铃反握仰卧臂屈伸", "body_part": "upper arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/1721-yRLPCLu.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴反握仰臥臂屈伸", "instructions_en": ["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.", "Hold the barbell with a reverse grip, palms facing towards your face, and your hands shoulder-width apart.", "Extend your arms straight up over your chest, keeping your elbows in and your wrists straight.", "Slowly lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary.", "Pause for a moment at the bottom, then extend your arms back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，双脚平放在地上，头放在长凳的末端。", "反握握住杠铃，手掌朝向脸部，双手与肩同宽。", "将手臂伸直越过胸部，保持肘部内收和手腕伸直。", "弯曲肘部，慢慢将杠铃降低到前额，保持上臂静止。", "在底部停顿片刻，然后将手臂伸回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["平躺在長凳上，雙腳平放在地上，頭放在長凳的末端。", "反握握住杠鈴，手掌朝向臉部，雙手與肩同寬。", "將手臂伸直越過胸部，保持肘部內收和手腕伸直。", "彎曲肘部，慢慢將杠鈴降低到前額，保持上臂靜止。", "在底部停頓片刻，然后將手臂伸回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0081', 'exercise', 1, '{"id": "0081", "target": "biceps", "name_en": "barbell reverse preacher curl", "name_zh": "杠铃反向牧师凳弯举", "body_part": "upper arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0081-4LIG9xr.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴反向牧師凳彎舉", "instructions_en": ["Sit on a preacher bench with your chest against the pad and your arms extended straight down, holding a barbell with an overhand grip.", "Keeping your upper arms stationary, exhale and curl the barbell upward while contracting your biceps.", "Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在牧师凳上，胸部靠在垫子上，手臂伸直向下，正手握住杠铃。", "保持上臂静止，呼气并向上弯曲杠铃，同时收缩二头肌。", "继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在牧師凳上，胸部靠在墊子上，手臂伸直向下，正手握住杠鈴。", "保持上臂靜止，呼氣并向上彎曲杠鈴，同時收縮二頭肌。", "繼續舉起杠鈴，直到二頭肌完全收縮并且杠鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0084', 'exercise', 1, '{"id": "0084", "target": "abs", "name_en": "barbell rollerout", "name_zh": "杠铃滚轮前推", "body_part": "waist", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0084-7M66AVi.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴滾輪前推", "instructions_en": ["Kneel on the floor and hold a barbell with both hands, shoulder-width apart.", "Roll the barbell forward, extending your arms and keeping your core engaged.", "Continue rolling forward until your body is fully extended and your arms are overhead.", "Pause for a moment, then slowly roll the barbell back towards your knees, maintaining control.", "Repeat for the desired number of repetitions."], "instructions_zh": ["跪在地板上，双手握住杠铃，距离与肩同宽。", "向前滚动杠铃，伸展手臂并保持核心收紧。", "继续向前滚动，直到身体完全伸展并且手臂举过头顶。", "暂停片刻，然后慢慢将杠铃向膝盖方向滚动，保持控制。", "重复所需的重复次数。"], "secondary_muscles": ["lower back"], "instructions_zh_hant": ["跪在地板上，雙手握住杠鈴，距離與肩同寬。", "向前滾動杠鈴，伸展手臂并保持核心收緊。", "繼續向前滾動，直到身體完全伸展并且手臂舉過頭頂。", "暫停片刻，然后慢慢將杠鈴向膝蓋方向滾動，保持控制。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0083', 'exercise', 1, '{"id": "0083", "target": "abs", "name_en": "barbell rollerout from bench", "name_zh": "杠铃凳上健腹前推", "body_part": "waist", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0083-Gxg9lDc.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴凳上健腹前推", "instructions_en": ["Start by kneeling on the floor with a barbell placed on a bench in front of you.", "Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.", "Keeping your core engaged and your back straight, slowly roll the barbell forward, extending your arms in front of you.", "Continue rolling the barbell forward until your body is fully extended and your arms are overhead.", "Pause for a moment at the fully extended position, then slowly roll the barbell back towards your body, returning to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先跪在地板上，将杠铃放在你面前的长凳上。", "正手握住杠铃，握距略宽于肩宽。", "保持核心收紧，背部挺直，慢慢向前滚动杠铃，将手臂伸到身前。", "继续向前滚动杠铃，直到身体完全伸展并且手臂举过头顶。", "在完全伸展的位置暂停片刻，然后慢慢地将杠铃向身体方向滚动，回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["首先跪在地板上，將杠鈴放在你面前的長凳上。", "正手握住杠鈴，握距略寬于肩寬。", "保持核心收緊，背部挺直，慢慢向前滾動杠鈴，將手臂伸到身前。", "繼續向前滾動杠鈴，直到身體完全伸展并且手臂舉過頭頂。", "在完全伸展的位置暫停片刻，然后慢慢地將杠鈴向身體方向滾動，回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0085', 'exercise', 1, '{"id": "0085", "target": "glutes", "name_en": "barbell romanian deadlift", "name_zh": "杠铃罗马尼亚硬拉", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0085-wQ2c4XD.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴羅馬尼亞硬拉", "instructions_en": ["Stand with your feet shoulder-width apart and your toes pointing forward.", "Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.", "Bend at the hips, keeping your back straight and your knees slightly bent.", "Lower the barbell towards the ground, keeping it close to your body.", "Feel the stretch in your hamstrings as you lower the barbell.", "Once you feel a stretch in your hamstrings, push your hips forward and stand up straight.", "Squeeze your glutes at the top of the movement.", "Lower the barbell back down to the starting position and repeat for the desired number of repetitions."], "instructions_zh": ["站立，双脚分开与肩同宽，脚趾指向前方。", "正手握住杠铃，双手分开略宽于肩宽。", "弯曲臀部，保持背部挺直，膝盖稍微弯曲。", "将杠铃向地面降低，使其靠近身体。", "当你降低杠铃时，感受腿筋的拉伸。", "一旦感觉到腿筋拉伸，就将臀部向前推并站直。", "在动作的最高点挤压臀部。", "将杠铃放回起始位置，然后重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "lower back"], "instructions_zh_hant": ["站立，雙腳分開與肩同寬，腳趾指向前方。", "正手握住杠鈴，雙手分開略寬于肩寬。", "彎曲臀部，保持背部挺直，膝蓋稍微彎曲。", "將杠鈴向地面降低，使其靠近身體。", "當你降低杠鈴時，感受腿筋的拉伸。", "一旦感覺到腿筋拉伸，就將臀部向前推并站直。", "在動作的最高點擠壓臀部。", "將杠鈴放回起始位置，然后重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0086', 'exercise', 1, '{"id": "0086", "target": "delts", "name_en": "barbell seated behind head military press", "name_zh": "杠铃坐姿颈后肩上推举", "body_part": "shoulders", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0086-ngPpyRS.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴坐姿頸后肩上推舉", "instructions_en": ["Sit on a bench with your back straight and feet flat on the ground.", "Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.", "Lift the barbell off the rack and bring it down to shoulder level, behind your head.", "Press the barbell upward until your arms are fully extended.", "Lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，背部挺直，双脚平放在地上。", "正手握住杠铃，杠铃间距略宽于肩宽。", "将杠铃从架子上提起，然后将其降至与肩同高，位于头后。", "向上推杠铃，直到手臂完全伸展。", "将杠铃降低回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "upper back"], "instructions_zh_hant": ["坐在長凳上，背部挺直，雙腳平放在地上。", "正手握住杠鈴，杠鈴間距略寬于肩寬。", "將杠鈴從架子上提起，然后將其降至與肩同高，位于頭后。", "向上推杠鈴，直到手臂完全伸展。", "將杠鈴降低回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0140', 'exercise', 1, '{"id": "0140", "target": "biceps", "name_en": "biceps pull-up", "name_zh": "肱二头肌引体向上", "body_part": "upper arms", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0140-guT8YnS.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "肱二頭肌引體向上", "instructions_en": ["Hang from a pull-up bar with your palms facing away from you and your hands shoulder-width apart.", "Engage your core and pull yourself up by bending your elbows, bringing your chest towards the bar.", "Pause at the top of the movement, then slowly lower yourself back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["悬挂在引体向上杆上，手掌背向自己，双手与肩同宽。", "启动核心肌群，弯曲肘部将自己拉起，使胸部靠近杠铃。", "在动作的最高点暂停，然后慢慢降低回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms", "shoulders"], "instructions_zh_hant": ["懸掛在引體向上桿上，手掌背向自己，雙手與肩同寬。", "啟動核心肌群，彎曲肘部將自己拉起，使胸部靠近杠鈴。", "在動作的最高點暫停，然后慢慢降低回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0087', 'exercise', 1, '{"id": "0087", "target": "delts", "name_en": "barbell seated bradford rocky press", "name_zh": "杠铃坐姿布拉德福德颈前后推举", "body_part": "shoulders", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0087-0dCyly0.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴坐姿布拉德福德頸前后推舉", "instructions_en": ["Sit on a bench with your back straight and feet flat on the ground.", "Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.", "Lift the barbell to shoulder height, keeping your elbows slightly bent and pointing forward.", "Press the barbell overhead, fully extending your arms.", "Lower the barbell back to shoulder height and repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，背部挺直，双脚平放在地上。", "正手握住杠铃，杠铃间距略宽于肩宽。", "将杠铃举至肩膀高度，保持肘部稍微弯曲并指向前方。", "将杠铃推过头顶，充分伸展双臂。", "将杠铃降低回肩部高度，然后重复所需的重复次数。"], "secondary_muscles": ["triceps", "upper back"], "instructions_zh_hant": ["坐在長凳上，背部挺直，雙腳平放在地上。", "正手握住杠鈴，杠鈴間距略寬于肩寬。", "將杠鈴舉至肩膀高度，保持肘部稍微彎曲并指向前方。", "將杠鈴推過頭頂，充分伸展雙臂。", "將杠鈴降低回肩部高度，然后重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0088', 'exercise', 1, '{"id": "0088", "target": "calves", "name_en": "barbell seated calf raise", "name_zh": "杠铃坐姿提踵", "body_part": "lower legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0088-ktsFQAZ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴坐姿提踵", "instructions_en": ["Sit on a bench with your feet flat on the floor and a barbell resting on your thighs.", "Place the balls of your feet on a raised platform, such as a block or step.", "Position the barbell across your thighs and hold it securely with your hands.", "Keeping your back straight and your core engaged, lift your heels off the ground by extending your ankles.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双脚平放在地板上，杠铃放在大腿上。", "将脚掌放在升高的平台上，例如木块或台阶。", "将杠铃放在大腿上，并用手牢牢握住它。", "保持背部挺直，核心收紧，伸展脚踝，将脚后跟抬离地面。", "在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "quadriceps"], "instructions_zh_hant": ["坐在長凳上，雙腳平放在地板上，杠鈴放在大腿上。", "將腳掌放在升高的平臺上，例如木塊或臺階。", "將杠鈴放在大腿上，并用手牢牢握住它。", "保持背部挺直，核心收緊，伸展腳踝，將腳后跟抬離地面。", "在頂部停頓片刻，然后慢慢降低腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1718', 'exercise', 1, '{"id": "1718", "target": "triceps", "name_en": "barbell seated close grip behind neck triceps extension", "name_zh": "杠铃坐姿窄握颈后臂屈伸", "body_part": "upper arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/1718-4CBIBOM.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴坐姿窄握頸后臂屈伸", "instructions_en": ["Sit on a bench with your back straight and feet flat on the ground.", "Hold the barbell with a close grip behind your neck, palms facing forward.", "Keep your elbows close to your head and slowly lower the barbell towards the back of your head.", "Pause for a moment, then extend your arms back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，背部挺直，双脚平放在地上。", "紧紧抓住颈后的杠铃，手掌朝前。", "保持肘部靠近头部，慢慢将杠铃放低至脑后。", "暂停片刻，然后将手臂伸回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["坐在長凳上，背部挺直，雙腳平放在地上。", "緊緊抓住頸后的杠鈴，手掌朝前。", "保持肘部靠近頭部，慢慢將杠鈴放低至腦后。", "暫停片刻，然后將手臂伸回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0089', 'exercise', 1, '{"id": "0089", "target": "biceps", "name_en": "barbell seated close-grip concentration curl", "name_zh": "杠铃坐姿窄握集中弯举", "body_part": "upper arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0089-1V1gj1u.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴坐姿窄握集中彎舉", "instructions_en": ["Sit on a bench with your feet flat on the floor and hold a barbell with an underhand grip, hands shoulder-width apart.", "Rest your upper arms against your inner thighs, just above your knees, and let the barbell hang down in front of you.", "Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders, contracting your biceps.", "Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双脚平放在地板上，反手握住杠铃，双手与肩同宽。", "将你的上臂靠在大腿内侧，就在膝盖上方，让杠铃垂在你面前。", "保持上臂静止，呼气并将杠铃向上卷曲至肩膀，收缩二头肌。", "保持收缩位置短暂停顿，然后吸气并慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在長凳上，雙腳平放在地板上，反手握住杠鈴，雙手與肩同寬。", "將你的上臂靠在大腿內側，就在膝蓋上方，讓杠鈴垂在你面前。", "保持上臂靜止，呼氣并將杠鈴向上卷曲至肩膀，收縮二頭肌。", "保持收縮位置短暫停頓，然后吸氣并慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0092', 'exercise', 1, '{"id": "0092", "target": "triceps", "name_en": "barbell seated overhead triceps extension", "name_zh": "杠铃坐姿过顶臂屈伸", "body_part": "upper arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0092-5uFK1xr.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴坐姿過頂臂屈伸", "instructions_en": ["Sit on a bench with your back straight and feet flat on the ground.", "Hold a barbell with an overhand grip, hands shoulder-width apart, and raise it overhead.", "Lower the barbell behind your head by bending your elbows, keeping your upper arms close to your head.", "Pause for a moment, then extend your arms to raise the barbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，背部挺直，双脚平放在地上。", "正手握住杠铃，双手与肩同宽，并将其举过头顶。", "弯曲肘部，将杠铃降低到脑后，保持上臂靠近头部。", "暂停片刻，然后伸展双臂将杠铃举回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["坐在長凳上，背部挺直，雙腳平放在地上。", "正手握住杠鈴，雙手與肩同寬，并將其舉過頭頂。", "彎曲肘部，將杠鈴降低到腦后，保持上臂靠近頭部。", "暫停片刻，然后伸展雙臂將杠鈴舉回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0094', 'exercise', 1, '{"id": "0094", "target": "abs", "name_en": "barbell seated twist", "name_zh": "杠铃坐姿转体", "body_part": "waist", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0094-dFSNDOA.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴坐姿轉體", "instructions_en": ["Sit on a flat bench with your feet flat on the ground and your knees bent.", "Hold a barbell with both hands in front of your chest, keeping your elbows slightly bent.", "Engage your core and slowly twist your torso to one side, keeping your back straight.", "Pause for a moment at the end of the twist, then slowly rotate back to the starting position.", "Repeat the twist to the other side.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["坐在平坦的长凳上，双脚平放在地上，膝盖弯曲。", "双手握住杠铃于胸前，保持肘部稍微弯曲。", "启动你的核心，慢慢地将你的躯干扭转到一侧，保持背部挺直。", "扭转结束时暂停片刻，然后慢慢旋转回到起始位置。", "重复扭转到另一侧。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["obliques", "lower back"], "instructions_zh_hant": ["坐在平坦的長凳上，雙腳平放在地上，膝蓋彎曲。", "雙手握住杠鈴于胸前，保持肘部稍微彎曲。", "啟動你的核心，慢慢地將你的軀幹扭轉到一側，保持背部挺直。", "扭轉結束時暫停片刻，然后慢慢旋轉回到起始位置。", "重復扭轉到另一側。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0103', 'exercise', 1, '{"id": "0103", "target": "abs", "name_en": "barbell standing ab rollerout", "name_zh": "杠铃站姿健腹前推", "body_part": "waist", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0103-xnInPfE.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴站姿健腹前推", "instructions_en": ["Stand upright with your feet shoulder-width apart and hold the barbell with both hands in front of your thighs.", "Engage your core and slowly roll the barbell down towards the ground, keeping your back straight and your arms extended.", "Continue rolling the barbell forward until your body is fully extended and your hands are directly above your head.", "Pause for a moment, then slowly roll the barbell back towards your thighs, maintaining control and keeping your core engaged.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站直，双脚分开与肩同宽，双手握住杠铃于大腿前方。", "启动你的核心肌群，慢慢地将杠铃向地面滚动，保持背部挺直，手臂伸展。", "继续向前滚动杠铃，直到身体完全伸展，双手位于头顶正上方。", "暂停片刻，然后慢慢地将杠铃向大腿方向滚动，保持控制并保持核心参与。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "lower back"], "instructions_zh_hant": ["站直，雙腳分開與肩同寬，雙手握住杠鈴于大腿前方。", "啟動你的核心肌群，慢慢地將杠鈴向地面滾動，保持背部挺直，手臂伸展。", "繼續向前滾動杠鈴，直到身體完全伸展，雙手位于頭頂正上方。", "暫停片刻，然后慢慢地將杠鈴向大腿方向滾動，保持控制并保持核心參與。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0095', 'exercise', 1, '{"id": "0095", "target": "traps", "name_en": "barbell shrug", "name_zh": "杠铃耸肩", "body_part": "back", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0095-dG7tG5y.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴聳肩", "instructions_en": ["Stand with your feet shoulder-width apart and hold a barbell in front of you with an overhand grip.", "Keep your arms straight and your back straight throughout the exercise.", "Lift your shoulders up towards your ears as high as possible, squeezing your traps at the top.", "Hold for a moment, then slowly lower your shoulders back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，正手握住杠铃。", "在整个练习过程中保持手臂伸直和背部挺直。", "将肩膀尽可能高地抬向耳朵，挤压斜方肌顶部。", "保持一会儿，然后慢慢将肩膀放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，正手握住杠鈴。", "在整個練習過程中保持手臂伸直和背部挺直。", "將肩膀盡可能高地抬向耳朵，擠壓斜方肌頂部。", "保持一會兒，然后慢慢將肩膀放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0096', 'exercise', 1, '{"id": "0096", "target": "abs", "name_en": "barbell side bent v. 2", "name_zh": "杠铃侧屈变式2", "body_part": "waist", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0096-i4JkUaL.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴側屈變式2", "instructions_en": ["Stand with your feet shoulder-width apart and hold a barbell with both hands, palms facing down.", "Keep your back straight and core engaged throughout the exercise.", "Slowly bend your torso to the right side, lowering the barbell towards your right knee.", "Pause for a moment, then return to the starting position.", "Repeat the movement on the left side.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手握住杠铃，掌心朝下。", "在整个练习过程中保持背部挺直并保持核心参与。", "慢慢地将你的躯干弯曲到右侧，将杠铃向右膝方向降低。", "暂停片刻，然后回到起始位置。", "在左侧重复该动作。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["obliques", "lower back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手握住杠鈴，掌心朝下。", "在整個練習過程中保持背部挺直并保持核心參與。", "慢慢地將你的軀幹彎曲到右側，將杠鈴向右膝方向降低。", "暫停片刻，然后回到起始位置。", "在左側重復該動作。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0098', 'exercise', 1, '{"id": "0098", "target": "quads", "name_en": "barbell side split squat", "name_zh": "杠铃侧分腿蹲", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0098-W31mMjd.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴側分腿蹲", "instructions_en": ["Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.", "Hold a barbell across your upper back, resting it on your traps.", "Engage your core and keep your chest up as you lower your body down into a squat position, bending at the knees and hips.", "As you lower, push your knees out to the sides and keep your weight on your heels.", "Lower until your thighs are parallel to the ground, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站立，双脚分开比肩宽，脚趾稍微向外。", "将杠铃放在上背部，将其放在斜方肌上。", "当你将身体降低到蹲姿时，收紧你的核心并保持胸部向上，弯曲膝盖和臀部。", "当你下降时，将膝盖向两侧推出，并将体重保持在脚后跟上。", "降低直到大腿与地面平行，然后通过脚后跟推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings", "calves"], "instructions_zh_hant": ["站立，雙腳分開比肩寬，腳趾稍微向外。", "將杠鈴放在上背部，將其放在斜方肌上。", "當你將身體降低到蹲姿時，收緊你的核心并保持胸部向上，彎曲膝蓋和臀部。", "當你下降時，將膝蓋向兩側推出，并將體重保持在腳后跟上。", "降低直到大腿與地面平行，然后通過腳后跟推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0097', 'exercise', 1, '{"id": "0097", "target": "quads", "name_en": "barbell side split squat v. 2", "name_zh": "杠铃侧分腿蹲变式2", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0097-HUEqZ1y.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴側分腿蹲變式2", "instructions_en": ["Stand with your feet wider than shoulder-width apart, toes pointing slightly outwards.", "Hold a barbell across your upper back, resting it on your shoulders.", "Take a big step to the side with your right foot, keeping your left foot planted.", "Bend your right knee and lower your body down into a squat position, keeping your chest up and your back straight.", "Push through your right heel to return to the starting position.", "Repeat on the other side, stepping out with your left foot.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["站立，双脚分开比肩宽，脚趾稍微向外。", "将杠铃放在上背部，将其放在肩膀上。", "右脚向一侧迈出一大步，保持左脚踩地。", "弯曲右膝，将身体放低至蹲姿，保持挺胸、背部挺直。", "推动右脚跟回到起始位置。", "在另一侧重复，左脚迈出。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings", "calves"], "instructions_zh_hant": ["站立，雙腳分開比肩寬，腳趾稍微向外。", "將杠鈴放在上背部，將其放在肩膀上。", "右腳向一側邁出一大步，保持左腳踩地。", "彎曲右膝，將身體放低至蹲姿，保持挺胸、背部挺直。", "推動右腳跟回到起始位置。", "在另一側重復，左腳邁出。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1756', 'exercise', 1, '{"id": "1756", "target": "glutes", "name_en": "barbell single leg deadlift", "name_zh": "杠铃单腿硬拉", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/1756-gEyURal.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴單腿硬拉", "instructions_en": ["Stand with your feet hip-width apart, holding a barbell in front of your thighs with an overhand grip.", "Shift your weight onto your left foot and lift your right foot slightly off the ground.", "Hinge forward at the hips, keeping your back straight and your right leg extended behind you for balance.", "Lower the barbell towards the ground, keeping it close to your body and your left leg slightly bent.", "Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your torso back up to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["站立，双脚分开与臀部同宽，正手握住杠铃在大腿前面。", "将重心转移到左脚上，并将右脚稍微抬离地面。", "臀部向前转动，保持背部挺直，右腿向后伸展以保持平衡。", "将杠铃向地面降低，使其靠近身体，左腿稍微弯曲。", "在底部暂停片刻，然后启动臀肌和腿筋，将躯干抬回到起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["hamstrings", "lower back"], "instructions_zh_hant": ["站立，雙腳分開與臀部同寬，正手握住杠鈴在大腿前面。", "將重心轉移到左腳上，并將右腳稍微抬離地面。", "臀部向前轉動，保持背部挺直，右腿向后伸展以保持平衡。", "將杠鈴向地面降低，使其靠近身體，左腿稍微彎曲。", "在底部暫停片刻，然后啟動臀肌和腿筋，將軀幹抬回到起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0099', 'exercise', 1, '{"id": "0099", "target": "quads", "name_en": "barbell single leg split squat", "name_zh": "杠铃单腿分腿蹲", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0099-gGNQmVt.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴單腿分腿蹲", "instructions_en": ["Stand with your feet shoulder-width apart, holding a barbell across your upper back.", "Take a large step forward with one leg, keeping your torso upright.", "Lower your body by bending your front knee and hip, while keeping your back leg straight.", "Continue lowering until your front thigh is parallel to the ground.", "Pause for a moment, then push through your front heel to return to the starting position.", "Repeat for the desired number of repetitions, then switch legs."], "instructions_zh": ["双脚分开与肩同宽站立，将杠铃放在上背部。", "单腿向前迈出一大步，保持躯干直立。", "弯曲前膝盖和臀部，降低身体，同时保持后腿伸直。", "继续降低，直到大腿前侧与地面平行。", "暂停片刻，然后推动前脚跟回到起始位置。", "重复所需的重复次数，然后换腿。"], "secondary_muscles": ["glutes", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，將杠鈴放在上背部。", "單腿向前邁出一大步，保持軀幹直立。", "彎曲前膝蓋和臀部，降低身體，同時保持后腿伸直。", "繼續降低，直到大腿前側與地面平行。", "暫停片刻，然后推動前腳跟回到起始位置。", "重復所需的重復次數，然后換腿。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2799', 'exercise', 1, '{"id": "2799", "target": "abs", "name_en": "barbell sitted alternate leg raise", "name_zh": "杠铃坐姿交替举腿", "body_part": "waist", "equipment": "barbell", "gif_asset": "assets/fitness/videos/2799-G7xoEzr.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴坐姿交替舉腿", "instructions_en": ["Sit on a bench with your back straight and hold a barbell across your thighs.", "Keeping your legs straight, lift one leg up as high as possible while keeping the other leg on the ground.", "Lower the raised leg back down and repeat with the other leg.", "Continue alternating legs for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，背部挺直，将杠铃放在大腿上。", "保持双腿伸直，将一条腿尽可能高地抬起，同时将另一条腿放在地上。", "将抬起的腿放回原位，然后换另一条腿重复上述步骤。", "继续交替双腿达到所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["坐在長凳上，背部挺直，將杠鈴放在大腿上。", "保持雙腿伸直，將一條腿盡可能高地抬起，同時將另一條腿放在地上。", "將抬起的腿放回原位，然后換另一條腿重復上述步驟。", "繼續交替雙腿達到所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2800', 'exercise', 1, '{"id": "2800", "target": "abs", "name_en": "barbell sitted alternate leg raise (female)", "name_zh": "杠铃坐姿交替举腿（女性示范）", "body_part": "waist", "equipment": "barbell", "gif_asset": "assets/fitness/videos/2800-BCs0G2F.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴坐姿交替舉腿（女性示范）", "instructions_en": ["Sit on a bench with your back straight and hold a barbell across your thighs.", "Place your hands on the sides of the bench for support.", "Keeping your legs straight, lift one leg up as high as possible while keeping it parallel to the ground.", "Lower the leg back down and repeat with the other leg.", "Continue alternating legs for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，背部挺直，将杠铃放在大腿上。", "将双手放在长凳两侧以获得支撑。", "保持双腿伸直，将一条腿尽可能抬高，同时保持与地面平行。", "将腿放回原位，然后换另一条腿重复此动作。", "继续交替双腿达到所需的重复次数。"], "secondary_muscles": ["hip flexors", "quadriceps"], "instructions_zh_hant": ["坐在長凳上，背部挺直，將杠鈴放在大腿上。", "將雙手放在長凳兩側以獲得支撐。", "保持雙腿伸直，將一條腿盡可能抬高，同時保持與地面平行。", "將腿放回原位，然后換另一條腿重復此動作。", "繼續交替雙腿達到所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0100', 'exercise', 1, '{"id": "0100", "target": "delts", "name_en": "barbell skier", "name_zh": "杠铃滑雪式", "body_part": "shoulders", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0100-4Leypho.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴滑雪式", "instructions_en": ["Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.", "Simultaneously lift the barbell up towards your shoulders while jumping slightly off the ground.", "As you reach the top of the movement, quickly reverse the motion and lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，正手握住杠铃于大腿前方。", "稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。", "同时将杠铃举向肩膀，同时稍微离开地面。", "当您到达动作的最高点时，快速反转动作并将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "core"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，正手握住杠鈴于大腿前方。", "稍微彎曲膝蓋，臀部向前轉動，保持背部挺直，挺胸。", "同時將杠鈴舉向肩膀，同時稍微離開地面。", "當您到達動作的最高點時，快速反轉動作并將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1456', 'exercise', 1, '{"id": "1456", "target": "delts", "name_en": "barbell standing close grip military press", "name_zh": "杠铃站姿窄握肩上推举", "body_part": "shoulders", "equipment": "barbell", "gif_asset": "assets/fitness/videos/1456-wdRZISl.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴站姿窄握肩上推舉", "instructions_en": ["Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, hands slightly closer than shoulder-width apart.", "Lift the barbell to shoulder height, keeping your elbows close to your body.", "Press the barbell overhead, extending your arms fully.", "Lower the barbell back to shoulder height.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，正手握住杠铃，双手距离略小于肩宽。", "将杠铃举至肩膀高度，保持肘部靠近身体。", "将杠铃推过头顶，充分伸展双臂。", "将杠铃降低回肩部高度。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "upper back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，正手握住杠鈴，雙手距離略小于肩寬。", "將杠鈴舉至肩膀高度，保持肘部靠近身體。", "將杠鈴推過頭頂，充分伸展雙臂。", "將杠鈴降低回肩部高度。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0104', 'exercise', 1, '{"id": "0104", "target": "forearms", "name_en": "barbell standing back wrist curl", "name_zh": "杠铃站姿背后腕弯举", "body_part": "lower arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0104-2qTvJAZ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴站姿背后腕彎舉", "instructions_en": ["Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip.", "Rest the barbell on the back of your hands with your palms facing down and your fingers pointing towards your body.", "Keeping your upper arms stationary, exhale and curl your wrists upwards as far as possible.", "Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站直，双脚分开与肩同宽，正手握住杠铃。", "将杠铃放在手背上，手掌朝下，手指指向身体。", "保持上臂静止，呼气并尽可能向上弯曲手腕。", "保持收缩位置短暂停顿，然后吸气并慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "shoulders"], "instructions_zh_hant": ["站直，雙腳分開與肩同寬，正手握住杠鈴。", "將杠鈴放在手背上，手掌朝下，手指指向身體。", "保持上臂靜止，呼氣并盡可能向上彎曲手腕。", "保持收縮位置短暫停頓，然后吸氣并慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0101', 'exercise', 1, '{"id": "0101", "target": "glutes", "name_en": "barbell speed squat", "name_zh": "杠铃快速深蹲", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0101-euI1BwR.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴快速深蹲", "instructions_en": ["Stand with your feet shoulder-width apart, toes slightly turned out.", "Hold the barbell across your upper back, resting it on your traps or rear delts.", "Engage your core and keep your chest up as you lower your hips back and down, as if sitting into a chair.", "Lower until your thighs are parallel to the ground, or as low as you can comfortably go.", "Drive through your heels to stand back up, squeezing your glutes at the top.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站立，双脚分开与肩同宽，脚趾稍微向外。", "将杠铃放在上背部，将其放在斜方肌或三角肌后束上。", "收紧核心肌群，保持挺胸，同时向后和向下降低臀部，就像坐在椅子上一样。", "降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。", "通过脚跟发力站起来，在顶部挤压臀部。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["站立，雙腳分開與肩同寬，腳趾稍微向外。", "將杠鈴放在上背部，將其放在斜方肌或三角肌后束上。", "收緊核心肌群，保持挺胸，同時向后和向下降低臀部，就像坐在椅子上一樣。", "降低直到大腿與地面平行，或者盡可能降低到您能舒服的高度。", "通過腳跟發力站起來，在頂部擠壓臀部。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2810', 'exercise', 1, '{"id": "2810", "target": "quads", "name_en": "barbell split squat v. 2", "name_zh": "杠铃分腿蹲变式2", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/2810-HBYyX94.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴分腿蹲變式2", "instructions_en": ["Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.", "Take a large step forward with your right foot, keeping your torso upright.", "Lower your body by bending your knees and hips until your right thigh is parallel to the ground.", "Pause for a moment, then push through your right heel to return to the starting position.", "Repeat with your left leg forward for the desired number of repetitions."], "instructions_zh": ["首先，双脚分开与肩同宽站立，将杠铃放在上背部。", "右脚向前迈出一大步，保持躯干直立。", "弯曲膝盖和臀部，降低身体，直到右大腿与地面平行。", "暂停片刻，然后推动右脚跟回到起始位置。", "左腿向前重复此动作，达到所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings", "calves"], "instructions_zh_hant": ["首先，雙腳分開與肩同寬站立，將杠鈴放在上背部。", "右腳向前邁出一大步，保持軀幹直立。", "彎曲膝蓋和臀部，降低身體，直到右大腿與地面平行。", "暫停片刻，然后推動右腳跟回到起始位置。", "左腿向前重復此動作，達到所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0102', 'exercise', 1, '{"id": "0102", "target": "quads", "name_en": "barbell squat (on knees)", "name_zh": "杠铃跪姿深蹲", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0102-oR7O9LW.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴跪姿深蹲", "instructions_en": ["Start by kneeling on the ground with your knees hip-width apart and your toes pointing forward.", "Place a barbell across your shoulders, gripping it with an overhand grip and your hands slightly wider than shoulder-width apart.", "Engage your core and keep your chest lifted as you slowly lower your body down by bending your knees, keeping your back straight.", "Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.", "Pause for a moment at the bottom, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先跪在地上，膝盖分开与臀部同宽，脚趾向前。", "将杠铃放在肩膀上，正手握住杠铃，双手分开的距离略大于肩宽。", "收紧核心并保持胸部抬起，同时弯曲膝盖慢慢降低身体，保持背部挺直。", "继续降低，直到大腿与地面平行，或者尽可能低。", "在底部停顿片刻，然后推动脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings", "calves"], "instructions_zh_hant": ["首先跪在地上，膝蓋分開與臀部同寬，腳趾向前。", "將杠鈴放在肩膀上，正手握住杠鈴，雙手分開的距離略大于肩寬。", "收緊核心并保持胸部抬起，同時彎曲膝蓋慢慢降低身體，保持背部挺直。", "繼續降低，直到大腿與地面平行，或者盡可能低。", "在底部停頓片刻，然后推動腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0111', 'exercise', 1, '{"id": "0111", "target": "calves", "name_en": "barbell standing rocking leg calf raise", "name_zh": "杠铃站姿摇摆提踵", "body_part": "lower legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0111-6HiHHe0.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴站姿搖擺提踵", "instructions_en": ["Stand with your feet shoulder-width apart and hold a barbell across your upper back.", "Raise your heels off the ground as high as possible, balancing on the balls of your feet.", "Slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，将杠铃放在上背部。", "将脚跟抬离地面，尽可能高，用脚掌保持平衡。", "慢慢降低脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "quadriceps"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，將杠鈴放在上背部。", "將腳跟抬離地面，盡可能高，用腳掌保持平衡。", "慢慢降低腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2798', 'exercise', 1, '{"id": "2798", "target": "quads", "name_en": "barbell squat jump step rear lunge", "name_zh": "杠铃深蹲跳接后撤弓步", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/2798-RYcV1kH.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴深蹲跳接后撤弓步", "instructions_en": ["Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.", "Lower your body into a squat position by bending your knees and pushing your hips back.", "Explode upwards, jumping off the ground as high as you can.", "Land softly on your feet and immediately step back with one leg into a reverse lunge.", "Lower your body down until your front thigh is parallel to the ground, keeping your back straight.", "Push through your front heel to return to the starting position.", "Repeat the jump and lunge sequence on the other leg.", "Continue alternating legs for the desired number of repetitions."], "instructions_zh": ["首先，双脚分开与肩同宽站立，将杠铃放在上背部。", "弯曲膝盖并将臀部向后推，将身体降低至蹲姿。", "向上爆炸，尽可能高地跳离地面。", "双脚轻轻落地，然后立即单腿向后退一步，形成反向弓步。", "降低身体，直到大腿前侧与地面平行，保持背部挺直。", "推动前脚跟以返回到起始位置。", "在另一条腿上重复跳跃和弓步序列。", "继续交替双腿达到所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings", "calves"], "instructions_zh_hant": ["首先，雙腳分開與肩同寬站立，將杠鈴放在上背部。", "彎曲膝蓋并將臀部向后推，將身體降低至蹲姿。", "向上爆炸，盡可能高地跳離地面。", "雙腳輕輕落地，然后立即單腿向后退一步，形成反向弓步。", "降低身體，直到大腿前側與地面平行，保持背部挺直。", "推動前腳跟以返回到起始位置。", "在另一條腿上重復跳躍和弓步序列。", "繼續交替雙腿達到所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0126', 'exercise', 1, '{"id": "0126", "target": "forearms", "name_en": "barbell wrist curl", "name_zh": "杠铃腕弯举", "body_part": "lower arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0126-82LxxkW.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴腕彎舉", "instructions_en": ["Sit on a bench with your feet flat on the ground and your forearms resting on your thighs, holding a barbell with an underhand grip.", "Allow the barbell to roll down to your fingertips, keeping your wrists straight.", "Slowly curl the barbell up towards your forearms by flexing your wrists.", "Pause for a moment at the top, then slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双脚平放在地面上，前臂放在大腿上，反握杠铃。", "让杠铃向下滚动到指尖，保持手腕伸直。", "弯曲手腕，慢慢地将杠铃向上卷向前臂。", "在顶部停顿片刻，然后慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "brachialis"], "instructions_zh_hant": ["坐在長凳上，雙腳平放在地面上，前臂放在大腿上，反握杠鈴。", "讓杠鈴向下滾動到指尖，保持手腕伸直。", "彎曲手腕，慢慢地將杠鈴向上卷向前臂。", "在頂部停頓片刻，然后慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0105', 'exercise', 1, '{"id": "0105", "target": "delts", "name_en": "barbell standing bradford press", "name_zh": "杠铃站姿布拉德福德推举", "body_part": "shoulders", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0105-dCPESfR.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴站姿布拉德福德推舉", "instructions_en": ["Stand with your feet shoulder-width apart and hold the barbell in front of your shoulders with an overhand grip.", "Press the barbell overhead, fully extending your arms.", "Lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，正手握住杠铃于肩前。", "将杠铃推过头顶，充分伸展双臂。", "将杠铃降低回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "upper back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，正手握住杠鈴于肩前。", "將杠鈴推過頭頂，充分伸展雙臂。", "將杠鈴降低回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1372', 'exercise', 1, '{"id": "1372", "target": "calves", "name_en": "barbell standing calf raise", "name_zh": "杠铃站姿提踵", "body_part": "lower legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/1372-8ozhUIZ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴站姿提踵", "instructions_en": ["Stand with your feet shoulder-width apart and place a barbell across your upper back.", "Raise your heels off the ground as high as possible, using only your toes.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，将杠铃放在上背部。", "仅用脚趾将脚后跟抬离地面，尽可能高。", "在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "glutes"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，將杠鈴放在上背部。", "僅用腳趾將腳后跟抬離地面，盡可能高。", "在頂部停頓片刻，然后慢慢降低腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0106', 'exercise', 1, '{"id": "0106", "target": "biceps", "name_en": "barbell standing close grip curl", "name_zh": "杠铃站姿窄握弯举", "body_part": "upper arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0106-4dUn2iv.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴站姿窄握彎舉", "instructions_en": ["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, hands close together.", "Keep your elbows close to your torso and your upper arms stationary throughout the movement.", "Exhale as you curl the weights while contracting your biceps. Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale as you slowly begin to bring the barbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站直，双脚分开与肩同宽，反手握住杠铃，双手并拢。", "在整个运动过程中，保持肘部靠近躯干，上臂保持静止。", "弯举哑铃时呼气，同时收缩二头肌。继续抬高杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气，慢慢开始将杠铃拉回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙腳分開與肩同寬，反手握住杠鈴，雙手并攏。", "在整個運動過程中，保持肘部靠近軀幹，上臂保持靜止。", "彎舉啞鈴時呼氣，同時收縮二頭肌。繼續抬高杠鈴，直到二頭肌完全收縮并且杠鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣，慢慢開始將杠鈴拉回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2414', 'exercise', 1, '{"id": "2414", "target": "biceps", "name_en": "barbell standing concentration curl", "name_zh": "杠铃站姿集中弯举", "body_part": "upper arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/2414-vsMcDi9.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴站姿集中彎舉", "instructions_en": ["Stand with your feet shoulder-width apart and hold a barbell in one hand, palm facing up.", "Rest your opposite hand on your thigh for support.", "Keeping your upper arm stationary, exhale and curl the weight up towards your shoulder.", "Pause for a moment at the top, squeezing your biceps.", "Inhale and slowly lower the weight back down to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["双脚分开与肩同宽站立，一手握住杠铃，掌心朝上。", "将另一只手放在大腿上以获得支撑。", "保持上臂静止，呼气并将重量向上弯向肩膀。", "在顶部暂停片刻，挤压你的二头肌。", "吸气并慢慢将重量放回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，一手握住杠鈴，掌心朝上。", "將另一只手放在大腿上以獲得支撐。", "保持上臂靜止，呼氣并將重量向上彎向肩膀。", "在頂部暫停片刻，擠壓你的二頭肌。", "吸氣并慢慢將重量放回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0107', 'exercise', 1, '{"id": "0107", "target": "delts", "name_en": "barbell standing front raise over head", "name_zh": "杠铃站姿过顶前平举", "body_part": "shoulders", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0107-S8mo30S.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴站姿過頂前平舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a barbell in front of your thighs with an overhand grip.", "Keep your back straight and engage your core.", "Slowly raise the barbell in front of you, keeping your arms straight and your palms facing down.", "Continue lifting until the barbell is slightly above shoulder level.", "Pause for a moment at the top, then slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，正手握住杠铃于大腿前方。", "保持背部挺直并启动核心肌群。", "慢慢地将杠铃举到你面前，保持手臂伸直，手掌朝下。", "继续举起杠铃，直到杠铃略高于肩部水平。", "在顶部停顿片刻，然后慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "upper back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，正手握住杠鈴于大腿前方。", "保持背部挺直并啟動核心肌群。", "慢慢地將杠鈴舉到你面前，保持手臂伸直，手掌朝下。", "繼續舉起杠鈴，直到杠鈴略高于肩部水平。", "在頂部停頓片刻，然后慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0108', 'exercise', 1, '{"id": "0108", "target": "calves", "name_en": "barbell standing leg calf raise", "name_zh": "杠铃站姿提踵", "body_part": "lower legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0108-rGwhJ5o.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴站姿提踵", "instructions_en": ["Stand with your feet shoulder-width apart and place a barbell across your upper back.", "Raise your heels off the ground as high as possible, using your calves.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，将杠铃放在上背部。", "用小腿将脚跟抬离地面，尽可能高。", "在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "glutes"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，將杠鈴放在上背部。", "用小腿將腳跟抬離地面，盡可能高。", "在頂部停頓片刻，然后慢慢降低腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0109', 'exercise', 1, '{"id": "0109", "target": "triceps", "name_en": "barbell standing overhead triceps extension", "name_zh": "杠铃站姿过顶臂屈伸", "body_part": "upper arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0109-dZl9Q27.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴站姿過頂臂屈伸", "instructions_en": ["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip.", "Raise the barbell overhead, fully extending your arms.", "Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.", "Pause for a moment, then raise the barbell back to the starting position by extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，正手握住杠铃。", "将杠铃举过头顶，充分伸展双臂。", "保持上臂靠近头部，弯曲肘部，慢慢将杠铃降低到脑后。", "暂停片刻，然后伸展双臂将杠铃举回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，正手握住杠鈴。", "將杠鈴舉過頭頂，充分伸展雙臂。", "保持上臂靠近頭部，彎曲肘部，慢慢將杠鈴降低到腦后。", "暫停片刻，然后伸展雙臂將杠鈴舉回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0110', 'exercise', 1, '{"id": "0110", "target": "biceps", "name_en": "barbell standing reverse grip curl", "name_zh": "杠铃站姿反握弯举", "body_part": "upper arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0110-LWuA3aZ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴站姿反握彎舉", "instructions_en": ["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.", "Keep your elbows close to your torso and your upper arms stationary.", "Exhale and curl the weights while contracting your biceps, bringing the barbell as close to your shoulders as possible.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站直，双脚分开与肩同宽，反手握住杠铃，手掌朝上。", "保持肘部靠近躯干，上臂保持静止。", "呼气并弯举杠铃，同时收缩二头肌，使杠铃尽可能靠近肩膀。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙腳分開與肩同寬，反手握住杠鈴，手掌朝上。", "保持肘部靠近軀幹，上臂保持靜止。", "呼氣并彎舉杠鈴，同時收縮二頭肌，使杠鈴盡可能靠近肩膀。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0115', 'exercise', 1, '{"id": "0115", "target": "glutes", "name_en": "barbell stiff leg good morning", "name_zh": "杠铃直腿早安式", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0115-JrOHAZc.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴直腿早安式", "instructions_en": ["Stand with your feet shoulder-width apart and your knees slightly bent.", "Hold the barbell across your upper back, resting it on your traps.", "Keeping your back straight, hinge forward at the hips, pushing your glutes back.", "Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.", "Engage your glutes and hamstrings to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，膝盖稍微弯曲。", "将杠铃放在上背部，将其放在斜方肌上。", "保持背部挺直，臀部向前转动，将臀部向后推。", "降低躯干直到与地面平行，感觉腿筋被拉伸。", "启动臀肌和腿筋以返回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "lower back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，膝蓋稍微彎曲。", "將杠鈴放在上背部，將其放在斜方肌上。", "保持背部挺直，臀部向前轉動，將臀部向后推。", "降低軀幹直到與地面平行，感覺腿筋被拉伸。", "啟動臀肌和腿筋以返回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0112', 'exercise', 1, '{"id": "0112", "target": "abs", "name_en": "barbell standing twist", "name_zh": "杠铃站姿转体", "body_part": "waist", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0112-yQe5HpE.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴站姿轉體", "instructions_en": ["Stand with your feet shoulder-width apart and hold a barbell in front of your chest with both hands, palms facing down.", "Engage your core and keep your back straight throughout the exercise.", "Slowly twist your torso to the right, pivoting on your feet and hips, while keeping your lower body stable.", "Pause for a moment at the end of the twist, then slowly return to the starting position.", "Repeat the twist to the left side.", "Continue alternating twists for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手握住杠铃于胸前，掌心朝下。", "在整个练习过程中启动你的核心并保持背部挺直。", "慢慢地将躯干向右扭转，以脚和臀部为轴，同时保持下半身稳定。", "扭转结束时暂停片刻，然后慢慢回到起始位置。", "向左侧重复扭转。", "继续交替扭转所需的重复次数。"], "secondary_muscles": ["obliques", "lower back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手握住杠鈴于胸前，掌心朝下。", "在整個練習過程中啟動你的核心并保持背部挺直。", "慢慢地將軀幹向右扭轉，以腳和臀部為軸，同時保持下半身穩定。", "扭轉結束時暫停片刻，然后慢慢回到起始位置。", "向左側重復扭轉。", "繼續交替扭轉所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1629', 'exercise', 1, '{"id": "1629", "target": "biceps", "name_en": "barbell standing wide grip biceps curl", "name_zh": "杠铃站姿宽握二头弯举", "body_part": "upper arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/1629-faHKVkK.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴站姿寬握二頭彎舉", "instructions_en": ["Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, hands wider than shoulder-width apart.", "Keep your back straight and your elbows close to your torso.", "Exhale and curl the barbell up towards your shoulders, keeping your upper arms stationary.", "Pause for a moment at the top, squeezing your biceps.", "Inhale and slowly lower the barbell back to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，反握握住杠铃，双手分开比肩宽。", "保持背部挺直，肘部靠近躯干。", "呼气并将杠铃向上弯向肩膀，保持上臂静止。", "在顶部暂停片刻，挤压你的二头肌。", "吸气，慢慢将杠铃放回起始位置，充分伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，反握握住杠鈴，雙手分開比肩寬。", "保持背部挺直，肘部靠近軀幹。", "呼氣并將杠鈴向上彎向肩膀，保持上臂靜止。", "在頂部暫停片刻，擠壓你的二頭肌。", "吸氣，慢慢將杠鈴放回起始位置，充分伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1457', 'exercise', 1, '{"id": "1457", "target": "delts", "name_en": "barbell standing wide military press", "name_zh": "杠铃站姿宽距肩上推举", "body_part": "shoulders", "equipment": "barbell", "gif_asset": "assets/fitness/videos/1457-Kyd9Rz5.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴站姿寬距肩上推舉", "instructions_en": ["Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, slightly wider than shoulder-width.", "Lift the barbell to shoulder height, keeping your elbows slightly in front of the bar.", "Press the barbell overhead, extending your arms fully.", "Lower the barbell back to shoulder height and repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，正手握杠铃，握距略宽于肩。", "将杠铃举至肩膀高度，保持肘部稍微位于杠铃前方。", "将杠铃推过头顶，充分伸展双臂。", "将杠铃降低回肩部高度，然后重复所需的重复次数。"], "secondary_muscles": ["triceps", "upper back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，正手握杠鈴，握距略寬于肩。", "將杠鈴舉至肩膀高度，保持肘部稍微位于杠鈴前方。", "將杠鈴推過頭頂，充分伸展雙臂。", "將杠鈴降低回肩部高度，然后重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0113', 'exercise', 1, '{"id": "0113", "target": "biceps", "name_en": "barbell standing wide-grip curl", "name_zh": "杠铃站姿宽握弯举", "body_part": "upper arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0113-NdIb5Z1.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴站姿寬握彎舉", "instructions_en": ["Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart.", "Let the barbell hang at arm''s length in front of your thighs, with your palms facing away from your body.", "Keeping your upper arms stationary, exhale and curl the barbell upward by contracting your biceps.", "Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站直，双脚分开与肩同宽，正手握住杠铃，双手分开比肩宽。", "让杠铃悬挂在大腿前面，与手掌保持一臂距离，手掌背向身体。", "保持上臂静止，呼气并通过收缩二头肌向上弯曲杠铃。", "继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms", "shoulders"], "instructions_zh_hant": ["站直，雙腳分開與肩同寬，正手握住杠鈴，雙手分開比肩寬。", "讓杠鈴懸掛在大腿前面，與手掌保持一臂距離，手掌背向身體。", "保持上臂靜止，呼氣并通過收縮二頭肌向上彎曲杠鈴。", "繼續舉起杠鈴，直到二頭肌完全收縮并且杠鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0114', 'exercise', 1, '{"id": "0114", "target": "glutes", "name_en": "barbell step-up", "name_zh": "杠铃踏台上步", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0114-Kxquu2E.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴踏臺上步", "instructions_en": ["Stand in front of a bench or step with a barbell resting on your upper back.", "Place one foot on the bench or step, ensuring your entire foot is in contact with the surface.", "Push through your heel and step up onto the bench or step, fully extending your hip and knee.", "Pause briefly at the top, then lower yourself back down to the starting position.", "Repeat with the opposite leg.", "Continue alternating legs for the desired number of repetitions."], "instructions_zh": ["站在长凳或台阶前，将杠铃放在上背部。", "将一只脚放在长凳或台阶上，确保整个脚与表面接触。", "穿过你的脚后跟，走上长凳或台阶，充分伸展你的臀部和膝盖。", "在顶部短暂停顿，然后放低自己回到起始位置。", "用另一条腿重复上述步骤。", "继续交替双腿达到所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["站在長凳或臺階前，將杠鈴放在上背部。", "將一只腳放在長凳或臺階上，確保整個腳與表面接觸。", "穿過你的腳后跟，走上長凳或臺階，充分伸展你的臀部和膝蓋。", "在頂部短暫停頓，然后放低自己回到起始位置。", "用另一條腿重復上述步驟。", "繼續交替雙腿達到所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0116', 'exercise', 1, '{"id": "0116", "target": "hamstrings", "name_en": "barbell straight leg deadlift", "name_zh": "杠铃直腿硬拉", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0116-hrVQWvE.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴直腿硬拉", "instructions_en": ["Stand with your feet shoulder-width apart and your toes pointing forward.", "Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.", "Bend at your hips and lower the barbell towards the ground, keeping your back straight and your knees slightly bent.", "Lower the barbell until you feel a stretch in your hamstrings.", "Engage your hamstrings and glutes to lift the barbell back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站立，双脚分开与肩同宽，脚趾指向前方。", "正手握住杠铃，双手分开略宽于肩宽。", "弯曲臀部，将杠铃放低至地面，保持背部挺直，膝盖稍微弯曲。", "降低杠铃，直到感觉到腿筋拉伸。", "启动腿筋和臀肌，将杠铃举回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "lower back"], "instructions_zh_hant": ["站立，雙腳分開與肩同寬，腳趾指向前方。", "正手握住杠鈴，雙手分開略寬于肩寬。", "彎曲臀部，將杠鈴放低至地面，保持背部挺直，膝蓋稍微彎曲。", "降低杠鈴，直到感覺到腿筋拉伸。", "啟動腿筋和臀肌，將杠鈴舉回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0117', 'exercise', 1, '{"id": "0117", "target": "glutes", "name_en": "barbell sumo deadlift", "name_zh": "杠铃相扑硬拉", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0117-KgI0tqW.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴相撲硬拉", "instructions_en": ["Stand with your feet wider than shoulder-width apart, toes pointing outwards.", "Place a barbell on the ground in front of you, centered between your feet.", "Bend your knees and lower your hips, keeping your back straight and chest up, to grip the barbell with an overhand grip.", "Engage your core and drive through your heels to lift the barbell off the ground, extending your hips and knees simultaneously.", "As you lift, keep your chest up and back straight, and push your hips forward to fully engage your glutes.", "Pause for a moment at the top, then slowly lower the barbell back down to the starting position, maintaining control throughout the movement.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站立，双脚分开比肩宽，脚趾朝外。", "将杠铃放在您面前的地面上，位于双脚之间的中心。", "弯曲膝盖，降低臀部，保持背部挺直，挺胸，用正手握法抓住杠铃。", "启动你的核心并通过你的脚后跟发力，将杠铃抬离地面，同时伸展你的臀部和膝盖。", "当你举起时，保持胸部挺直，背部挺直，向前推动臀部以充分锻炼臀部。", "在顶部停顿片刻，然后慢慢将杠铃放回起始位置，在整个动作过程中保持控制。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "quadriceps", "lower back"], "instructions_zh_hant": ["站立，雙腳分開比肩寬，腳趾朝外。", "將杠鈴放在您面前的地面上，位于雙腳之間的中心。", "彎曲膝蓋，降低臀部，保持背部挺直，挺胸，用正手握法抓住杠鈴。", "啟動你的核心并通過你的腳后跟發力，將杠鈴抬離地面，同時伸展你的臀部和膝蓋。", "當你舉起時，保持胸部挺直，背部挺直，向前推動臀部以充分鍛煉臀部。", "在頂部停頓片刻，然后慢慢將杠鈴放回起始位置，在整個動作過程中保持控制。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3305', 'exercise', 1, '{"id": "3305", "target": "delts", "name_en": "barbell thruster", "name_zh": "杠铃深蹲推举", "body_part": "shoulders", "equipment": "barbell", "gif_asset": "assets/fitness/videos/3305-f7Y9eDZ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴深蹲推舉", "instructions_en": ["Start by standing with your feet shoulder-width apart, holding a barbell at shoulder height with an overhand grip.", "Lower into a squat position by bending your knees and pushing your hips back.", "As you reach the bottom of the squat, explosively drive through your heels to stand up, simultaneously pressing the barbell overhead.", "Lower the barbell back to shoulder height as you lower back into the squat position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先，双脚分开与肩同宽站立，正手握住杠铃，与肩同高。", "弯曲膝盖并将臀部向后推，降低至蹲姿。", "当你到达深蹲底部时，爆发性地通过脚后跟站起来，同时将杠铃压过头顶。", "当你回到深蹲位置时，将杠铃降低到肩膀高度。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "glutes", "hamstrings", "core"], "instructions_zh_hant": ["首先，雙腳分開與肩同寬站立，正手握住杠鈴，與肩同高。", "彎曲膝蓋并將臀部向后推，降低至蹲姿。", "當你到達深蹲底部時，爆發性地通過腳后跟站起來，同時將杠鈴壓過頭頂。", "當你回到深蹲位置時，將杠鈴降低到肩膀高度。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0120', 'exercise', 1, '{"id": "0120", "target": "delts", "name_en": "barbell upright row", "name_zh": "杠铃直立划船", "body_part": "shoulders", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0120-UDlhcO8.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴直立劃船", "instructions_en": ["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.", "Let the barbell hang in front of your thighs, arms fully extended.", "Keeping your back straight and core engaged, exhale and lift the barbell straight up towards your chin, leading with your elbows.", "Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，正手握住杠铃，双手分开略宽于肩宽。", "让杠铃悬挂在大腿前面，双臂完全伸展。", "保持背部挺直，核心收紧，呼气，将杠铃笔直向上举向下巴，用肘部引导。", "在顶部停顿片刻，然后吸气，慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["traps", "biceps"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，正手握住杠鈴，雙手分開略寬于肩寬。", "讓杠鈴懸掛在大腿前面，雙臂完全伸展。", "保持背部挺直，核心收緊，呼氣，將杠鈴筆直向上舉向下巴，用肘部引導。", "在頂部停頓片刻，然后吸氣，慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0119', 'exercise', 1, '{"id": "0119", "target": "delts", "name_en": "barbell upright row v. 2", "name_zh": "杠铃直立划船变式2", "body_part": "shoulders", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0119-83HoW9X.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴直立劃船變式2", "instructions_en": ["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.", "Let the barbell hang in front of your thighs, arms fully extended.", "Keeping your back straight, exhale and lift the barbell straight up towards your chin, leading with your elbows.", "Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，正手握住杠铃，双手分开略宽于肩宽。", "让杠铃悬挂在大腿前面，双臂完全伸展。", "保持背部挺直，呼气，将杠铃向上举至下巴，用肘部引导。", "在顶部停顿片刻，然后吸气，慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["traps", "biceps"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，正手握住杠鈴，雙手分開略寬于肩寬。", "讓杠鈴懸掛在大腿前面，雙臂完全伸展。", "保持背部挺直，呼氣，將杠鈴向上舉至下巴，用肘部引導。", "在頂部停頓片刻，然后吸氣，慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0121', 'exercise', 1, '{"id": "0121", "target": "delts", "name_en": "barbell upright row v. 3", "name_zh": "杠铃直立划船变式3", "body_part": "shoulders", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0121-fI18Rbc.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴直立劃船變式3", "instructions_en": ["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.", "Let the barbell hang in front of your thighs, arms fully extended.", "Keeping your core engaged and back straight, exhale as you lift the barbell straight up towards your chin, leading with your elbows.", "Pause for a moment at the top, then inhale as you slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，正手握住杠铃，双手分开略宽于肩宽。", "让杠铃悬挂在大腿前面，双臂完全伸展。", "保持核心收紧，背部挺直，呼气，将杠铃向上举至下巴，用肘部引导。", "在顶部暂停片刻，然后吸气，慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["traps", "biceps"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，正手握住杠鈴，雙手分開略寬于肩寬。", "讓杠鈴懸掛在大腿前面，雙臂完全伸展。", "保持核心收緊，背部挺直，呼氣，將杠鈴向上舉至下巴，用肘部引導。", "在頂部暫停片刻，然后吸氣，慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0122', 'exercise', 1, '{"id": "0122", "target": "pectorals", "name_en": "barbell wide bench press", "name_zh": "杠铃宽距卧推", "body_part": "chest", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0122-JsKq9so.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴寬距臥推", "instructions_en": ["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.", "Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.", "Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.", "Lower the barbell slowly towards your chest, keeping your elbows slightly flared out.", "Pause for a moment when the barbell touches your chest, then push it back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，双脚平放在地上，背部紧贴长凳。", "宽握距抓住杠铃，握距略宽于肩宽。", "将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。", "慢慢地将杠铃向胸部降低，保持肘部稍微张开。", "当杠铃接触胸部时暂停片刻，然后将其推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["平躺在長凳上，雙腳平放在地上，背部緊貼長凳。", "寬握距抓住杠鈴，握距略寬于肩寬。", "將杠鈴從架子上提起，并將其直接放在胸部上方，雙臂完全伸展。", "慢慢地將杠鈴向胸部降低，保持肘部稍微張開。", "當杠鈴接觸胸部時暫停片刻，然后將其推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1258', 'exercise', 1, '{"id": "1258", "target": "pectorals", "name_en": "barbell wide reverse grip bench press", "name_zh": "杠铃宽距反握卧推", "body_part": "chest", "equipment": "barbell", "gif_asset": "assets/fitness/videos/1258-945zpRg.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴寬距反握臥推", "instructions_en": ["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.", "Grasp the barbell with a wide reverse grip, slightly wider than shoulder-width apart.", "Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.", "Lower the barbell slowly towards your chest, keeping your elbows tucked in and your wrists straight.", "Pause for a moment when the barbell touches your chest, then push it back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，双脚平放在地上，背部紧贴长凳。", "反握宽握杠铃，握距略宽于肩宽。", "将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。", "将杠铃慢慢降低到胸部，保持肘部内收，手腕伸直。", "当杠铃接触胸部时暂停片刻，然后将其推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["平躺在長凳上，雙腳平放在地上，背部緊貼長凳。", "反握寬握杠鈴，握距略寬于肩寬。", "將杠鈴從架子上提起，并將其直接放在胸部上方，雙臂完全伸展。", "將杠鈴慢慢降低到胸部，保持肘部內收，手腕伸直。", "當杠鈴接觸胸部時暫停片刻，然后將其推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0124', 'exercise', 1, '{"id": "0124", "target": "quads", "name_en": "barbell wide squat", "name_zh": "杠铃宽距深蹲", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0124-s7HX1BY.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴寬距深蹲", "instructions_en": ["Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.", "Hold the barbell across your upper back, resting it on your traps or rear delts.", "Engage your core and keep your chest up as you lower your body down into a squat, pushing your hips back and bending your knees.", "Lower until your thighs are parallel to the ground, or as low as you can comfortably go.", "Pause for a moment at the bottom, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站立，双脚分开比肩宽，脚趾稍微向外。", "将杠铃放在上背部，将其放在斜方肌或三角肌后束上。", "当你下蹲时，收紧你的核心并保持胸部挺直，将臀部向后推并弯曲膝盖。", "降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。", "在底部停顿片刻，然后推动脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings", "calves"], "instructions_zh_hant": ["站立，雙腳分開比肩寬，腳趾稍微向外。", "將杠鈴放在上背部，將其放在斜方肌或三角肌后束上。", "當你下蹲時，收緊你的核心并保持胸部挺直，將臀部向后推并彎曲膝蓋。", "降低直到大腿與地面平行，或者盡可能降低到您能舒服的高度。", "在底部停頓片刻，然后推動腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0123', 'exercise', 1, '{"id": "0123", "target": "delts", "name_en": "barbell wide-grip upright row", "name_zh": "杠铃宽握直立划船", "body_part": "shoulders", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0123-RgJDRR1.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴寬握直立劃船", "instructions_en": ["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart.", "Let the barbell hang in front of your thighs, arms fully extended.", "Keeping your back straight, exhale and lift the barbell straight up towards your chin, leading with your elbows.", "Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，正手握住杠铃，双手分开比肩宽。", "让杠铃悬挂在大腿前面，双臂完全伸展。", "保持背部挺直，呼气，将杠铃向上举至下巴，用肘部引导。", "在顶部停顿片刻，然后吸气，慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["traps", "biceps"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，正手握住杠鈴，雙手分開比肩寬。", "讓杠鈴懸掛在大腿前面，雙臂完全伸展。", "保持背部挺直，呼氣，將杠鈴向上舉至下巴，用肘部引導。", "在頂部停頓片刻，然后吸氣，慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0125', 'exercise', 1, '{"id": "0125", "target": "forearms", "name_en": "barbell wrist curl v. 2", "name_zh": "杠铃腕弯举变式2", "body_part": "lower arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0125-6kSxYnw.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴腕彎舉變式2", "instructions_en": ["Sit on a bench with your feet flat on the ground and your knees bent.", "Hold a barbell with an underhand grip, palms facing up, and your hands shoulder-width apart.", "Rest your forearms on your thighs, allowing your wrists to hang off the edge.", "Slowly curl your wrists upward, bringing the barbell towards your forearms.", "Pause for a moment at the top, then slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双脚平放在地上，膝盖弯曲。", "反手握住杠铃，手掌朝上，双手与肩同宽。", "将前臂放在大腿上，让手腕悬在边缘。", "慢慢向上弯曲手腕，将杠铃拉向前臂。", "在顶部停顿片刻，然后慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "brachialis"], "instructions_zh_hant": ["坐在長凳上，雙腳平放在地上，膝蓋彎曲。", "反手握住杠鈴，手掌朝上，雙手與肩同寬。", "將前臂放在大腿上，讓手腕懸在邊緣。", "慢慢向上彎曲手腕，將杠鈴拉向前臂。", "在頂部停頓片刻，然后慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0127', 'exercise', 1, '{"id": "0127", "target": "glutes", "name_en": "barbell zercher squat", "name_zh": "杠铃泽奇深蹲", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0127-LSTChY9.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "槓鈴澤奇深蹲", "instructions_en": ["Stand with your feet shoulder-width apart and toes slightly turned out.", "Hold the barbell in the crooks of your elbows, with your hands gripping the bar for stability.", "Engage your core and keep your chest lifted as you lower your hips back and down into a squat position.", "Keep your knees in line with your toes and your weight in your heels.", "Pause for a moment at the bottom of the squat, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站立，双脚分开与肩同宽，脚趾稍微外翻。", "将杠铃放在肘部的弯曲处，双手握住杠铃以保持稳定。", "当你将臀部向后降低到蹲姿时，启动你的核心并保持胸部抬起。", "保持膝盖与脚趾对齐，并将重量放在脚后跟上。", "在深蹲底部暂停片刻，然后用脚后跟恢复到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves", "core"], "instructions_zh_hant": ["站立，雙腳分開與肩同寬，腳趾稍微外翻。", "將杠鈴放在肘部的彎曲處，雙手握住杠鈴以保持穩定。", "當你將臀部向后降低到蹲姿時，啟動你的核心并保持胸部抬起。", "保持膝蓋與腳趾對齊，并將重量放在腳后跟上。", "在深蹲底部暫停片刻，然后用腳后跟恢復到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3212', 'exercise', 1, '{"id": "3212", "target": "glutes", "name_en": "basic toe touch (male)", "name_zh": "基础触脚尖（男性示范）", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3212-BbfB8Gb.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "基礎觸腳尖（男性示范）", "instructions_en": ["Stand with your feet shoulder-width apart and your arms by your sides.", "Bend forward at the waist, keeping your back straight and your knees slightly bent.", "Reach down towards your toes with your hands, keeping your legs as straight as possible.", "Pause for a moment at the bottom, then slowly return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双臂放在身体两侧。", "腰部向前弯曲，保持背部挺直，膝盖稍微弯曲。", "双手向下伸向脚趾，尽可能保持双腿伸直。", "在底部停顿片刻，然后慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙臂放在身體兩側。", "腰部向前彎曲，保持背部挺直，膝蓋稍微彎曲。", "雙手向下伸向腳趾，盡可能保持雙腿伸直。", "在底部停頓片刻，然后慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0128', 'exercise', 1, '{"id": "0128", "target": "delts", "name_en": "battling ropes", "name_zh": "战绳", "body_part": "shoulders", "equipment": "rope", "gif_asset": "assets/fitness/videos/0128-RJa4tCo.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "戰繩", "instructions_en": ["Stand with your feet shoulder-width apart and knees slightly bent.", "Hold one end of the rope in each hand, with your palms facing each other.", "Raise your arms to shoulder height, keeping your elbows slightly bent.", "Begin making alternating waves with the ropes by rapidly raising and lowering each arm.", "Continue for the desired duration or number of repetitions."], "instructions_zh": ["站立，双脚分开与肩同宽，膝盖稍微弯曲。", "双手握住绳子的一端，手掌相对。", "将手臂举至肩膀高度，保持肘部稍微弯曲。", "快速抬起和放下每只手臂，开始用绳索产生交替的波浪。", "继续所需的持续时间或重复次数。"], "secondary_muscles": ["forearms", "core"], "instructions_zh_hant": ["站立，雙腳分開與肩同寬，膝蓋稍微彎曲。", "雙手握住繩子的一端，手掌相對。", "將手臂舉至肩膀高度，保持肘部稍微彎曲。", "快速抬起和放下每只手臂，開始用繩索產生交替的波浪。", "繼續所需的持續時間或重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0139', 'exercise', 1, '{"id": "0139", "target": "biceps", "name_en": "biceps narrow pull-ups", "name_zh": "肱二头肌窄距引体向上", "body_part": "upper arms", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0139-50BETrz.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "肱二頭肌窄距引體向上", "instructions_en": ["Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart.", "Engage your core and pull yourself up towards the bar, focusing on using your biceps to lift your body.", "Pause for a moment at the top, then slowly lower yourself back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["悬挂在引体向上杆上，手掌朝向自己，双手与肩同宽。", "启动你的核心并将自己拉向杠铃，专注于使用二头肌来抬起你的身体。", "在最高点暂停片刻，然后慢慢降低回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms", "shoulders"], "instructions_zh_hant": ["懸掛在引體向上桿上，手掌朝向自己，雙手與肩同寬。", "啟動你的核心并將自己拉向杠鈴，專注于使用二頭肌來抬起你的身體。", "在最高點暫停片刻，然后慢慢降低回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3360', 'exercise', 1, '{"id": "3360", "target": "cardiovascular system", "name_en": "bear crawl", "name_zh": "熊爬", "body_part": "cardio", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3360-0Yz8WdV.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "熊爬", "instructions_en": ["Start on all fours with your hands directly under your shoulders and your knees directly under your hips.", "Lift your knees slightly off the ground, keeping your back flat and your core engaged.", "Move your right hand and left foot forward simultaneously, followed by your left hand and right foot.", "Continue crawling forward, alternating your hand and foot movements.", "Maintain a steady pace and keep your core tight throughout the exercise.", "Continue for the desired distance or time."], "instructions_zh": ["从四肢着地开始，双手直接放在肩膀下方，膝盖直接放在臀部下方。", "将膝盖稍微抬离地面，保持背部平坦并收紧核心。", "同时向前移动右手和左脚，然后是左手和右脚。", "继续向前爬行，手脚交替动作。", "在整个练习过程中保持稳定的节奏并保持核心紧张。", "继续所需的距离或时间。"], "secondary_muscles": ["core", "shoulders", "triceps"], "instructions_zh_hant": ["從四肢著地開始，雙手直接放在肩膀下方，膝蓋直接放在臀部下方。", "將膝蓋稍微抬離地面，保持背部平坦并收緊核心。", "同時向前移動右手和左腳，然后是左手和右腳。", "繼續向前爬行，手腳交替動作。", "在整個練習過程中保持穩定的節奏并保持核心緊張。", "繼續所需的距離或時間。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1259', 'exercise', 1, '{"id": "1259", "target": "pectorals", "name_en": "behind head chest stretch", "name_zh": "颈后胸部拉伸", "body_part": "chest", "equipment": "assisted", "gif_asset": "assets/fitness/videos/1259-QoHIhPl.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "頸后胸部拉伸", "instructions_en": ["Stand tall with your feet shoulder-width apart.", "Interlace your fingers behind your head with your elbows pointing outwards.", "Slowly squeeze your shoulder blades together and push your chest forward.", "Hold the stretch for 15-30 seconds.", "Release the stretch and repeat as desired."], "instructions_zh": ["站直，双脚分开与肩同宽。", "将手指交叉放在脑后，肘部朝外。", "慢慢地将肩胛骨挤压在一起，并将胸部向前推。", "保持拉伸 15-30 秒。", "松开拉伸并根据需要重复。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["站直，雙腳分開與肩同寬。", "將手指交叉放在腦后，肘部朝外。", "慢慢地將肩胛骨擠壓在一起，并將胸部向前推。", "保持拉伸 15-30 秒。", "松開拉伸并根據需要重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0129', 'exercise', 1, '{"id": "0129", "target": "triceps", "name_en": "bench dip (knees bent)", "name_zh": "凳上臂屈伸（双膝弯曲）", "body_part": "upper arms", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0129-RrLske5.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "凳上臂屈伸（雙膝彎曲）", "instructions_en": ["Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.", "Slide your butt off the bench and straighten your legs in front of you, keeping your heels on the ground.", "Bend your elbows and lower your body towards the ground, keeping your back close to the bench.", "Pause for a moment at the bottom, then push yourself back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳或椅子的边缘，双手抓住臀部旁边的边缘。", "将臀部从长凳上滑下来，在身前伸直双腿，脚后跟保持在地面上。", "弯曲肘部，将身体放低至地面，保持背部靠近长凳。", "在底部暂停片刻，然后将自己推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["坐在長凳或椅子的邊緣，雙手抓住臀部旁邊的邊緣。", "將臀部從長凳上滑下來，在身前伸直雙腿，腳后跟保持在地面上。", "彎曲肘部，將身體放低至地面，保持背部靠近長凳。", "在底部暫停片刻，然后將自己推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1399', 'exercise', 1, '{"id": "1399", "target": "triceps", "name_en": "bench dip on floor", "name_zh": "凳上臂屈伸（地板）", "body_part": "upper arms", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1399-9RT8oQW.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "凳上臂屈伸（地板）", "instructions_en": ["Sit on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward.", "Slide your butt off the bench, supporting your weight with your hands.", "Lower your body by bending your elbows until your upper arms are parallel to the floor.", "Push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳或椅子的边缘，双手抓住边缘，手指指向前方。", "将臀部滑离长凳，用手支撑体重。", "弯曲肘部降低身体，直到上臂与地板平行。", "伸直手臂，将自己推回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["坐在長凳或椅子的邊緣，雙手抓住邊緣，手指指向前方。", "將臀部滑離長凳，用手支撐體重。", "彎曲肘部降低身體，直到上臂與地板平行。", "伸直手臂，將自己推回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0130', 'exercise', 1, '{"id": "0130", "target": "glutes", "name_en": "bench hip extension", "name_zh": "凳上髋伸展", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0130-u27Kcdz.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "凳上髖伸展", "instructions_en": ["Sit on a bench with your back against the bench and your feet flat on the ground.", "Place your hands on the bench for support.", "Engage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders.", "Pause for a moment at the top, then slowly lower your hips back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，背部靠在长凳上，双脚平放在地上。", "将双手放在长凳上以获得支撑。", "收紧臀肌和腿筋，然后将臀部抬离长凳，直到身体从膝盖到肩膀形成一条直线。", "在顶部暂停片刻，然后慢慢将臀部放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings"], "instructions_zh_hant": ["坐在長凳上，背部靠在長凳上，雙腳平放在地上。", "將雙手放在長凳上以獲得支撐。", "收緊臀肌和腿筋，然后將臀部抬離長凳，直到身體從膝蓋到肩膀形成一條直線。", "在頂部暫停片刻，然后慢慢將臀部放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3019', 'exercise', 1, '{"id": "3019", "target": "lats", "name_en": "bench pull-ups", "name_zh": "凳上引体向上", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3019-mExgrF9.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "凳上引體向上", "instructions_en": ["Position yourself under a bar or a sturdy horizontal surface that is at chest height.", "Grab the bar or surface with an overhand grip, slightly wider than shoulder-width apart.", "Hang with your arms fully extended and your body straight.", "Pull your chest towards the bar or surface by squeezing your shoulder blades together and bending your elbows.", "Continue pulling until your chin is above the bar or surface.", "Lower yourself back down to the starting position with control.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将自己置于与胸部同高的横杆或坚固的水平表面下方。", "正手握住杠铃或杠铃表面，握距略宽于肩宽。", "双臂完全伸展，身体伸直。", "将肩胛骨挤压在一起并弯曲肘部，将胸部拉向杠铃或地面。", "继续拉，直到下巴位于杆或表面上方。", "有控制地降低自己回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["將自己置于與胸部同高的橫桿或堅固的水平表面下方。", "正手握住杠鈴或杠鈴表面，握距略寬于肩寬。", "雙臂完全伸展，身體伸直。", "將肩胛骨擠壓在一起并彎曲肘部，將胸部拉向杠鈴或地面。", "繼續拉，直到下巴位于桿或表面上方。", "有控制地降低自己回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3543', 'exercise', 1, '{"id": "3543", "target": "glutes", "name_en": "bodyweight drop jump squat", "name_zh": "自重落地跳跃深蹲", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3543-wfotm7S.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "自重落地跳躍深蹲", "instructions_en": ["Stand with your feet shoulder-width apart.", "Lower your body into a squat position by bending your knees and pushing your hips back.", "Jump up explosively, extending your hips, knees, and ankles.", "While in mid-air, quickly bring your feet together.", "Land softly on the balls of your feet and immediately drop back into a squat position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立。", "弯曲膝盖并将臀部向后推，将身体降低至蹲姿。", "爆发性地跳起来，伸展臀部、膝盖和脚踝。", "在半空中时，快速将双脚并拢。", "脚掌轻轻着地，然后立即回到蹲姿。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立。", "彎曲膝蓋并將臀部向后推，將身體降低至蹲姿。", "爆發性地跳起來，伸展臀部、膝蓋和腳踝。", "在半空中時，快速將雙腳并攏。", "腳掌輕輕著地，然后立即回到蹲姿。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3639', 'exercise', 1, '{"id": "3639", "target": "glutes", "name_en": "bent knee lying twist (male)", "name_zh": "屈膝卧姿转体（男性示范）", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3639-6sYyrRX.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "屈膝臥姿轉體（男性示范）", "instructions_en": ["Lie flat on your back with your knees bent and feet flat on the ground.", "Extend your arms out to the sides, perpendicular to your body.", "Keeping your knees together, slowly lower them to one side, aiming to touch the ground with your knees.", "Pause for a moment, then engage your core and slowly lift your knees back to the starting position.", "Repeat the movement to the other side.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["平躺，膝盖弯曲，双脚平放在地上。", "将手臂向两侧伸展，与身体垂直。", "保持膝盖并拢，慢慢地将它们降低到一侧，旨在用膝盖接触地面。", "暂停片刻，然后启动核心并慢慢将膝盖抬回到起始位置。", "到另一侧重复该动作。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["obliques", "hip flexors"], "instructions_zh_hant": ["平躺，膝蓋彎曲，雙腳平放在地上。", "將手臂向兩側伸展，與身體垂直。", "保持膝蓋并攏，慢慢地將它們降低到一側，旨在用膝蓋接觸地面。", "暫停片刻，然后啟動核心并慢慢將膝蓋抬回到起始位置。", "到另一側重復該動作。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1770', 'exercise', 1, '{"id": "1770", "target": "biceps", "name_en": "biceps leg concentration curl", "name_zh": "肱二头肌腿部集中弯举", "body_part": "upper arms", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1770-sJFIDIp.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "肱二頭肌腿部集中彎舉", "instructions_en": ["Sit on a bench with your legs spread apart and your feet flat on the ground.", "Hold a dumbbell in one hand and place your elbow on the inside of your thigh, just above the knee.", "With your palm facing up, curl the dumbbell towards your shoulder while keeping your upper arm stationary.", "Squeeze your biceps at the top of the movement, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["坐在长凳上，双腿分开，双脚平放在地上。", "一只手握住哑铃，将肘部放在大腿内侧，膝盖上方。", "手掌朝上，将哑铃向肩膀弯曲，同时保持上臂静止。", "在动作的最高点挤压二头肌，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在長凳上，雙腿分開，雙腳平放在地上。", "一只手握住啞鈴，將肘部放在大腿內側，膝蓋上方。", "手掌朝上，將啞鈴向肩膀彎曲，同時保持上臂靜止。", "在動作的最高點擠壓二頭肌，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0137', 'exercise', 1, '{"id": "0137", "target": "triceps", "name_en": "body-up", "name_zh": "自重臂屈伸", "body_part": "upper arms", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0137-U6G2gk9.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "自重臂屈伸", "instructions_en": ["Start by placing your hands on a raised surface, such as a bench or parallel bars, with your palms facing down and fingers pointing forward.", "Extend your legs out in front of you, keeping your heels on the ground and your body straight.", "Lower your body by bending your elbows, keeping them close to your sides, until your upper arms are parallel to the ground.", "Pause for a moment, then push through your palms to straighten your arms and lift your body back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先将双手放在凸起的表面上，例如长凳或双杠上，手掌朝下，手指向前。", "将双腿向前方伸展，脚跟保持在地面上，身体伸直。", "弯曲肘部降低身体，使其靠近身体两侧，直到上臂与地面平行。", "暂停片刻，然后用手掌伸直手臂，将身体抬回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["首先將雙手放在凸起的表面上，例如長凳或雙杠上，手掌朝下，手指向前。", "將雙腿向前方伸展，腳跟保持在地面上，身體伸直。", "彎曲肘部降低身體，使其靠近身體兩側，直到上臂與地面平行。", "暫停片刻，然后用手掌伸直手臂，將身體抬回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3544', 'exercise', 1, '{"id": "3544", "target": "abs", "name_en": "bodyweight incline side plank", "name_zh": "自重上斜侧平板支撑", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3544-5VXmnV5.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "自重上斜側平板支撐", "instructions_en": ["Start by lying on your side with your legs extended and stacked on top of each other.", "Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.", "Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.", "Hold this position for the desired amount of time.", "Lower your hips back down to the ground and repeat on the other side."], "instructions_zh": ["首先侧躺，双腿伸展并叠放在一起。", "将前臂放在肩膀正下方的地面上，肘部弯曲成 90 度角。", "启动你的核心并将臀部抬离地面，从头到脚形成一条直线。", "保持此位置所需的时间。", "将臀部放回到地面，然后在另一侧重复。"], "secondary_muscles": ["obliques", "shoulders"], "instructions_zh_hant": ["首先側躺，雙腿伸展并疊放在一起。", "將前臂放在肩膀正下方的地面上，肘部彎曲成 90 度角。", "啟動你的核心并將臀部抬離地面，從頭到腳形成一條直線。", "保持此位置所需的時間。", "將臀部放回到地面，然后在另一側重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1771', 'exercise', 1, '{"id": "1771", "target": "triceps", "name_en": "bodyweight kneeling triceps extension", "name_zh": "自重跪姿臂屈伸", "body_part": "upper arms", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1771-s0HKO2I.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "自重跪姿臂屈伸", "instructions_en": ["Kneel down on the ground with your knees hip-width apart.", "Place your hands on the ground in front of you, shoulder-width apart, fingers pointing forward.", "Extend your legs straight behind you, balancing on your toes and hands, forming a straight line from head to heels.", "Bend your elbows and lower your upper body towards the ground, keeping your elbows close to your sides.", "Pause for a moment at the bottom, then push through your hands to straighten your arms and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["跪在地上，膝盖分开与臀部同宽。", "将双手放在身前的地面上，与肩同宽，手指指向前方。", "将双腿伸直在身后，用脚趾和双手保持平衡，从头到脚跟形成一条直线。", "弯曲肘部，将上半身向地面降低，保持肘部靠近身体两侧。", "在底部停顿片刻，然后双手用力伸直手臂，回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "chest"], "instructions_zh_hant": ["跪在地上，膝蓋分開與臀部同寬。", "將雙手放在身前的地面上，與肩同寬，手指指向前方。", "將雙腿伸直在身后，用腳趾和雙手保持平衡，從頭到腳跟形成一條直線。", "彎曲肘部，將上半身向地面降低，保持肘部靠近身體兩側。", "在底部停頓片刻，然后雙手用力伸直手臂，回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1769', 'exercise', 1, '{"id": "1769", "target": "biceps", "name_en": "bodyweight side lying biceps curl", "name_zh": "自重侧卧二头弯举", "body_part": "upper arms", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1769-gscGLOU.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "自重側臥二頭彎舉", "instructions_en": ["Lie on your side with your legs extended and your head supported by your arm.", "Hold your upper arm against your side and bend your elbow to curl your forearm towards your shoulder.", "Pause for a moment at the top, then slowly lower your forearm back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["侧躺，双腿伸直，用手臂支撑头部。", "将上臂靠在身体两侧，弯曲肘部，将前臂卷向肩膀。", "在顶部暂停片刻，然后慢慢将前臂放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["側躺，雙腿伸直，用手臂支撐頭部。", "將上臂靠在身體兩側，彎曲肘部，將前臂卷向肩膀。", "在頂部暫停片刻，然后慢慢將前臂放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3168', 'exercise', 1, '{"id": "3168", "target": "upper back", "name_en": "bodyweight squatting row", "name_zh": "自重蹲姿划船", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3168-3xK09Sk.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "自重蹲姿劃船", "instructions_en": ["Stand with your feet shoulder-width apart, holding onto a sturdy object or suspension trainer with your arms extended.", "Lower your body into a squat position, keeping your back straight and your knees behind your toes.", "From the squat position, pull your body up towards the object or suspension trainer, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，伸直手臂抓住坚固的物体或悬挂训练器。", "将身体降低至蹲姿，保持背部挺直，膝盖位于脚趾后面。", "从蹲姿开始，将身体向上拉向物体或悬挂训练器，将肩胛骨挤压在一起。", "在顶部停顿片刻，然后慢慢将身体放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "shoulders"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，伸直手臂抓住堅固的物體或懸掛訓練器。", "將身體降低至蹲姿，保持背部挺直，膝蓋位于腳趾后面。", "從蹲姿開始，將身體向上拉向物體或懸掛訓練器，將肩胛骨擠壓在一起。", "在頂部停頓片刻，然后慢慢將身體放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3167', 'exercise', 1, '{"id": "3167", "target": "upper back", "name_en": "bodyweight squatting row (with towel)", "name_zh": "自重蹲姿划船（配合毛巾）", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3167-BReCuOn.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "自重蹲姿劃船（配合毛巾）", "instructions_en": ["Stand with your feet shoulder-width apart, holding a towel in front of you with your palms facing down.", "Bend your knees and lower your body into a squat position, keeping your back straight and your chest up.", "As you lower into the squat, simultaneously pull the towel towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the bottom of the squat, then slowly return to the starting position while extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，手掌朝下，将毛巾放在身前。", "弯曲膝盖，将身体降低至蹲姿，保持背部挺直，挺胸。", "当你下蹲时，同时将毛巾拉向胸部，将肩胛骨挤压在一起。", "在深蹲底部停顿片刻，然后慢慢回到起始位置，同时伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "shoulders"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，手掌朝下，將毛巾放在身前。", "彎曲膝蓋，將身體降低至蹲姿，保持背部挺直，挺胸。", "當你下蹲時，同時將毛巾拉向胸部，將肩胛骨擠壓在一起。", "在深蹲底部停頓片刻，然后慢慢回到起始位置，同時伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3156', 'exercise', 1, '{"id": "3156", "target": "upper back", "name_en": "bodyweight standing close-grip one arm row", "name_zh": "自重站姿窄握单臂划船", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3156-v2DfH14.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "自重站姿窄握單臂劃船", "instructions_en": ["Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand with a neutral grip.", "Bend forward at the hips, keeping your back straight and your core engaged.", "Pull the dumbbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["双脚分开与肩同宽站立，膝盖稍微弯曲，一只手握住哑铃，握姿中立。", "臀部向前弯曲，保持背部挺直，核心肌群参与。", "将哑铃向上拉向胸部，保持肘部靠近身体并将肩胛骨挤压在一起。", "在顶部停顿片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，膝蓋稍微彎曲，一只手握住啞鈴，握姿中立。", "臀部向前彎曲，保持背部挺直，核心肌群參與。", "將啞鈴向上拉向胸部，保持肘部靠近身體并將肩胛骨擠壓在一起。", "在頂部停頓片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3158', 'exercise', 1, '{"id": "3158", "target": "upper back", "name_en": "bodyweight standing close-grip row", "name_zh": "自重站姿窄握划船", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3158-tig3PXb.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "自重站姿窄握劃船", "instructions_en": ["Stand with your feet shoulder-width apart and knees slightly bent.", "Bend forward at the waist, keeping your back straight and your core engaged.", "Extend your arms straight in front of you, gripping the bar or handles with a close grip.", "Pull the bar or handles towards your body, squeezing your shoulder blades together.", "Pause for a moment at the top of the movement, then slowly release and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站立，双脚分开与肩同宽，膝盖稍微弯曲。", "腰部向前弯曲，保持背部挺直，核心肌群参与。", "将双臂伸直在身前，紧紧抓住杆或手柄。", "将杠铃或手柄拉向身体，将肩胛骨挤压在一起。", "在动作的最高点停顿片刻，然后慢慢松开并回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["站立，雙腳分開與肩同寬，膝蓋稍微彎曲。", "腰部向前彎曲，保持背部挺直，核心肌群參與。", "將雙臂伸直在身前，緊緊抓住桿或手柄。", "將杠鈴或手柄拉向身體，將肩胛骨擠壓在一起。", "在動作的最高點停頓片刻，然后慢慢松開并回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3162', 'exercise', 1, '{"id": "3162", "target": "upper back", "name_en": "bodyweight standing one arm row", "name_zh": "自重站姿单臂划船", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3162-xbkPfaw.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "自重站姿單臂劃船", "instructions_en": ["Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand.", "Bend forward at the hips, keeping your back straight and your core engaged.", "Let the dumbbell hang straight down in front of you, with your arm fully extended.", "Pull the dumbbell up towards your chest, keeping your elbow close to your body.", "Squeeze your shoulder blades together at the top of the movement.", "Lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["双脚分开与肩同宽站立，膝盖稍微弯曲，一手握住哑铃。", "臀部向前弯曲，保持背部挺直，核心肌群参与。", "让哑铃垂直悬挂在您面前，手臂完全伸展。", "将哑铃向上拉向胸部，保持肘部靠近身体。", "在动作的最高点将肩胛骨挤压在一起。", "将哑铃放回起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，膝蓋稍微彎曲，一手握住啞鈴。", "臀部向前彎曲，保持背部挺直，核心肌群參與。", "讓啞鈴垂直懸掛在您面前，手臂完全伸展。", "將啞鈴向上拉向胸部，保持肘部靠近身體。", "在動作的最高點將肩胛骨擠壓在一起。", "將啞鈴放回起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3161', 'exercise', 1, '{"id": "3161", "target": "upper back", "name_en": "bodyweight standing one arm row (with towel)", "name_zh": "自重站姿单臂划船（配合毛巾）", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3161-O4oIqQD.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "自重站姿單臂劃船（配合毛巾）", "instructions_en": ["Stand with your feet shoulder-width apart, knees slightly bent, and hold a towel with one hand.", "Bend forward at the hips, keeping your back straight and your core engaged.", "Pull the towel towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the towel back to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."], "instructions_zh": ["双脚分开与肩同宽站立，膝盖微曲，单手握住毛巾。", "臀部向前弯曲，保持背部挺直，核心肌群参与。", "将毛巾拉向胸部，将肩胛骨挤压在一起。", "在顶部停顿片刻，然后慢慢将毛巾放回起始位置。", "重复所需的重复次数，然后换到另一只手臂。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，膝蓋微曲，單手握住毛巾。", "臀部向前彎曲，保持背部挺直，核心肌群參與。", "將毛巾拉向胸部，將肩胛骨擠壓在一起。", "在頂部停頓片刻，然后慢慢將毛巾放回起始位置。", "重復所需的重復次數，然后換到另一只手臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1160', 'exercise', 1, '{"id": "1160", "target": "cardiovascular system", "name_en": "burpee", "name_zh": "波比跳", "body_part": "cardio", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1160-dK9394r.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "波比跳", "instructions_en": ["Start in a standing position with your feet shoulder-width apart.", "Lower your body into a squat position by bending your knees and placing your hands on the floor in front of you.", "Kick your feet back into a push-up position.", "Perform a push-up, keeping your body in a straight line.", "Jump your feet back into the squat position.", "Jump up explosively, reaching your arms overhead.", "Land softly and immediately lower back into a squat position to begin the next repetition."], "instructions_zh": ["从站立位置开始，双脚分开与肩同宽。", "弯曲膝盖并将双手放在身前的地板上，将身体降低至蹲姿。", "将脚踢回到俯卧撑位置。", "进行俯卧撑，保持身体呈一条直线。", "将双脚跳回蹲姿。", "爆发性地跳起，将双臂举过头顶。", "轻轻落地并立即回到蹲姿，开始下一次重复。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves", "shoulders", "chest"], "instructions_zh_hant": ["從站立位置開始，雙腳分開與肩同寬。", "彎曲膝蓋并將雙手放在身前的地板上，將身體降低至蹲姿。", "將腳踢回到俯臥撐位置。", "進行俯臥撐，保持身體呈一條直線。", "將雙腳跳回蹲姿。", "爆發性地跳起，將雙臂舉過頭頂。", "輕輕落地并立即回到蹲姿，開始下一次重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3166', 'exercise', 1, '{"id": "3166", "target": "upper back", "name_en": "bodyweight standing row", "name_zh": "自重站姿划船", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3166-wd4ds3s.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "自重站姿劃船", "instructions_en": ["Stand with your feet shoulder-width apart and knees slightly bent.", "Grasp a bar or handles with an overhand grip, palms facing down.", "Keep your back straight and core engaged.", "Pull the bar or handles towards your body, squeezing your shoulder blades together.", "Pause for a moment at the top of the movement.", "Slowly release and extend your arms back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站立，双脚分开与肩同宽，膝盖稍微弯曲。", "正手握住杆或手柄，手掌朝下。", "保持背部挺直，核心参与。", "将杠铃或手柄拉向身体，将肩胛骨挤压在一起。", "在动作的最高点停顿片刻。", "慢慢释放并伸展双臂回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "shoulders"], "instructions_zh_hant": ["站立，雙腳分開與肩同寬，膝蓋稍微彎曲。", "正手握住桿或手柄，手掌朝下。", "保持背部挺直，核心參與。", "將杠鈴或手柄拉向身體，將肩胛骨擠壓在一起。", "在動作的最高點停頓片刻。", "慢慢釋放并伸展雙臂回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3165', 'exercise', 1, '{"id": "3165", "target": "upper back", "name_en": "bodyweight standing row (with towel)", "name_zh": "自重站姿划船（配合毛巾）", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3165-uTv34oq.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "自重站姿劃船（配合毛巾）", "instructions_en": ["Stand with your feet shoulder-width apart and hold a towel in front of you with both hands.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Pull the towel towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly release the tension and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手握住毛巾放在身前。", "稍微弯曲膝盖，髋部向前转动，保持背部挺直。", "将毛巾拉向胸部，将肩胛骨挤压在一起。", "在最高点停顿片刻，然后慢慢释放张力，回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "shoulders"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手握住毛巾放在身前。", "稍微彎曲膝蓋，髖部向前轉動，保持背部挺直。", "將毛巾拉向胸部，將肩胛骨擠壓在一起。", "在最高點停頓片刻，然后慢慢釋放張力，回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0138', 'exercise', 1, '{"id": "0138", "target": "abs", "name_en": "bottoms-up", "name_zh": "仰卧屈膝抬臀", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0138-CI6baTY.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "仰臥屈膝抬臀", "instructions_en": ["Lie flat on your back with your legs extended and your arms by your sides.", "Bend your knees and bring them towards your chest, keeping your feet off the ground.", "Engaging your abs, lift your hips off the ground, bringing your knees towards your head.", "Pause for a moment at the top, then slowly lower your hips back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，双腿伸展，双臂放在身体两侧。", "弯曲膝盖并将其靠近胸部，保持双脚离开地面。", "收紧腹肌，将臀部抬离地面，将膝盖靠近头部。", "在顶部暂停片刻，然后慢慢将臀部放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["obliques", "hip flexors"], "instructions_zh_hant": ["平躺，雙腿伸展，雙臂放在身體兩側。", "彎曲膝蓋并將其靠近胸部，保持雙腳離開地面。", "收緊腹肌，將臀部抬離地面，將膝蓋靠近頭部。", "在頂部暫停片刻，然后慢慢將臀部放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1374', 'exercise', 1, '{"id": "1374", "target": "calves", "name_en": "box jump down with one leg stabilization", "name_zh": "跳箱落地单腿稳定", "body_part": "lower legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1374-iPm26QU.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "跳箱落地單腿穩定", "instructions_en": ["Stand in front of a box or platform with your feet shoulder-width apart.", "Bend your knees and jump onto the box, landing softly with one foot on the box and the other foot hanging off the edge.", "Stabilize yourself on the box with the foot that is on it, while keeping the other foot off the ground.", "Hold this position for a few seconds, engaging your calf muscles to maintain balance.", "Slowly step down with the foot that is on the box, returning to the starting position.", "Repeat the exercise with the other leg."], "instructions_zh": ["站在盒子或平台前，双脚分开与肩同宽。", "弯曲膝盖，跳到盒子上，一只脚轻轻落地，另一只脚悬在盒子边缘。", "将脚踩在盒子上，将自己稳定在盒子上，同时保持另一只脚离开地面。", "保持这个姿势几秒钟，锻炼小腿肌肉以保持平衡。", "将放在盒子上的脚慢慢放下，回到起始位置。", "用另一条腿重复该练习。"], "secondary_muscles": ["quadriceps", "hamstrings", "glutes"], "instructions_zh_hant": ["站在盒子或平臺前，雙腳分開與肩同寬。", "彎曲膝蓋，跳到盒子上，一只腳輕輕落地，另一只腳懸在盒子邊緣。", "將腳踩在盒子上，將自己穩定在盒子上，同時保持另一只腳離開地面。", "保持這個姿勢幾秒鐘，鍛煉小腿肌肉以保持平衡。", "將放在盒子上的腳慢慢放下，回到起始位置。", "用另一條腿重復該練習。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2466', 'exercise', 1, '{"id": "2466", "target": "abs", "name_en": "bridge - mountain climber (cross body)", "name_zh": "桥式-登山跑（交叉身体）", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/2466-9c6T1YX.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "橋式-登山跑（交叉身體）", "instructions_en": ["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.", "Engage your core and lift your right foot off the ground, bringing your right knee towards your left elbow.", "Return your right foot to the starting position and repeat the movement with your left foot towards your right elbow.", "Continue alternating sides, moving at a controlled pace.", "Keep your hips level and avoid lifting your hips too high or sagging them too low.", "Maintain a steady breathing pattern throughout the exercise.", "Repeat for the desired number of repetitions."], "instructions_zh": ["从高平板支撑位置开始，双手直接放在肩膀下方，身体呈一条直线。", "启动你的核心并将右脚抬离地面，将右膝移向左肘。", "将右脚放回到起始位置，然后将左脚朝向右肘重复该动作。", "继续交替两侧，以受控的速度移动。", "保持臀部水平，避免臀部抬得太高或下垂得太低。", "在整个练习过程中保持稳定的呼吸模式。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "quadriceps", "hamstrings", "shoulders", "triceps"], "instructions_zh_hant": ["從高平板支撐位置開始，雙手直接放在肩膀下方，身體呈一條直線。", "啟動你的核心并將右腳抬離地面，將右膝移向左肘。", "將右腳放回到起始位置，然后將左腳朝向右肘重復該動作。", "繼續交替兩側，以受控的速度移動。", "保持臀部水平，避免臀部抬得太高或下垂得太低。", "在整個練習過程中保持穩定的呼吸模式。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0870', 'exercise', 1, '{"id": "0870", "target": "abs", "name_en": "butt-ups", "name_zh": "俯撑提臀", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0870-qcNN2FN.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "俯撐提臀", "instructions_en": ["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands by your sides, palms facing down.", "Engaging your abs, lift your legs off the ground, bringing your knees towards your chest.", "At the top of the movement, squeeze your abs and pause for a moment.", "Slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，膝盖弯曲，双脚平放在地上。", "将双手放在身体两侧，掌心朝下。", "收紧腹肌，将双腿抬离地面，将膝盖靠近胸部。", "在动作的最高点，挤压腹肌并暂停片刻。", "慢慢地将双腿放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors", "lower back"], "instructions_zh_hant": ["平躺，膝蓋彎曲，雙腳平放在地上。", "將雙手放在身體兩側，掌心朝下。", "收緊腹肌，將雙腿抬離地面，將膝蓋靠近胸部。", "在動作的最高點，擠壓腹肌并暫停片刻。", "慢慢地將雙腿放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1494', 'exercise', 1, '{"id": "1494", "target": "adductors", "name_en": "butterfly yoga pose", "name_zh": "瑜伽蝴蝶式", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1494-bWlZvXh.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "瑜伽蝴蝶式", "instructions_en": ["Sit on the floor with your legs extended in front of you.", "Bend your knees and bring the soles of your feet together, allowing your knees to fall out to the sides.", "Hold onto your ankles or feet with your hands.", "Sit up tall and lengthen your spine.", "Gently press your knees down towards the floor, feeling a stretch in your inner thighs.", "Hold this position for a few breaths.", "To release, slowly bring your knees back up and extend your legs."], "instructions_zh": ["坐在地板上，双腿伸到身前。", "弯曲膝盖，将脚底并拢，让膝盖向两侧倾斜。", "用手抓住脚踝或脚。", "坐直并拉长脊柱。", "轻轻地将膝盖压向地板，感觉大腿内侧有拉伸感。", "保持这个姿势几个呼吸。", "要放松，请慢慢抬起膝盖并伸展双腿。"], "secondary_muscles": ["hamstrings", "groin"], "instructions_zh_hant": ["坐在地板上，雙腿伸到身前。", "彎曲膝蓋，將腳底并攏，讓膝蓋向兩側傾斜。", "用手抓住腳踝或腳。", "坐直并拉長脊柱。", "輕輕地將膝蓋壓向地板，感覺大腿內側有拉伸感。", "保持這個姿勢幾個呼吸。", "要放松，請慢慢抬起膝蓋并伸展雙腿。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0148', 'exercise', 1, '{"id": "0148", "target": "delts", "name_en": "cable alternate shoulder press", "name_zh": "绳索交替肩上推举", "body_part": "shoulders", "equipment": "cable", "gif_asset": "assets/fitness/videos/0148-KHPZL0b.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索交替肩上推舉", "instructions_en": ["Stand with your feet shoulder-width apart and grasp the handles of the cable machine with an overhand grip.", "Position your hands at shoulder height, with your palms facing forward.", "Keep your core engaged and your back straight.", "Press one handle up and forward until your arm is fully extended.", "Pause for a moment at the top, then slowly lower the handle back to the starting position.", "Repeat with the other arm.", "Alternate between arms for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，并用正手握住绳索机的手柄。", "将双手放在与肩同高的位置，手掌朝前。", "保持核心参与并保持背部挺直。", "向上并向前按下一个手柄，直到您的手臂完全伸展。", "在最高点暂停片刻，然后慢慢将手柄放回起始位置。", "用另一只手臂重复上述步骤。", "双臂交替进行所需的重复次数。"], "secondary_muscles": ["triceps", "upper back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，并用正手握住繩索機的手柄。", "將雙手放在與肩同高的位置，手掌朝前。", "保持核心參與并保持背部挺直。", "向上并向前按下一個手柄，直到您的手臂完全伸展。", "在最高點暫停片刻，然后慢慢將手柄放回起始位置。", "用另一只手臂重復上述步驟。", "雙臂交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0149', 'exercise', 1, '{"id": "0149", "target": "triceps", "name_en": "cable alternate triceps extension", "name_zh": "绳索交替臂屈伸", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/0149-Gchi5Tr.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索交替臂屈伸", "instructions_en": ["Stand facing the cable machine with your feet shoulder-width apart.", "Hold the cable handle with your right hand and bring your arm up so that your upper arm is parallel to the ground and your elbow is bent at a 90-degree angle.", "Keep your upper arm stationary and extend your forearm backward, fully straightening your arm.", "Pause for a moment, then slowly return to the starting position.", "Repeat with your left arm.", "Continue alternating arms for the desired number of repetitions."], "instructions_zh": ["面对电缆机站立，双脚与肩同宽。", "右手握住电缆手柄，抬起手臂，使上臂与地面平行，肘部弯曲成 90 度角。", "保持上臂静止，前臂向后伸展，完全伸直手臂。", "暂停片刻，然后慢慢回到起始位置。", "用左臂重复此动作。", "继续交替手臂进行所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["面對電纜機站立，雙腳與肩同寬。", "右手握住電纜手柄，抬起手臂，使上臂與地面平行，肘部彎曲成 90 度角。", "保持上臂靜止，前臂向后伸展，完全伸直手臂。", "暫停片刻，然后慢慢回到起始位置。", "用左臂重復此動作。", "繼續交替手臂進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3235', 'exercise', 1, '{"id": "3235", "target": "hamstrings", "name_en": "cable assisted inverse leg curl", "name_zh": "绳索辅助反向腿弯举", "body_part": "upper legs", "equipment": "cable", "gif_asset": "assets/fitness/videos/3235-zHEpuuc.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索輔助反向腿彎舉", "instructions_en": ["Adjust the cable machine so that the ankle attachment is at the lowest setting.", "Lie face down on the bench with your legs straight and the ankle attachment secured to your ankles.", "Hold onto the handles of the bench for stability.", "Keeping your upper body stationary, exhale and curl your legs up towards your glutes by flexing your knees.", "Pause for a moment at the top of the movement, squeezing your hamstrings.", "Inhale and slowly lower your legs back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整缆绳机，使脚踝附件处于最低设置。", "面朝下躺在长凳上，双腿伸直，将脚踝固定装置固定在脚踝上。", "握住长凳的把手以保持稳定。", "保持上半身静止，呼气，弯曲膝盖，将双腿向臀肌方向卷起。", "在动作的最高点暂停片刻，挤压你的腿筋。", "吸气并慢慢降低双腿回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "calves"], "instructions_zh_hant": ["調整纜繩機，使腳踝附件處于最低設置。", "面朝下躺在長凳上，雙腿伸直，將腳踝固定裝置固定在腳踝上。", "握住長凳的把手以保持穩定。", "保持上半身靜止，呼氣，彎曲膝蓋，將雙腿向臀肌方向卷起。", "在動作的最高點暫停片刻，擠壓你的腿筋。", "吸氣并慢慢降低雙腿回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0151', 'exercise', 1, '{"id": "0151", "target": "pectorals", "name_en": "cable bench press", "name_zh": "绳索卧推", "body_part": "chest", "equipment": "cable", "gif_asset": "assets/fitness/videos/0151-7xI5MXA.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索臥推", "instructions_en": ["Adjust the cable machine to chest height and attach the handles.", "Stand facing away from the machine with your feet shoulder-width apart.", "Grasp the handles with an overhand grip and step forward to create tension in the cables.", "Position your feet firmly on the ground and engage your core.", "Bend your elbows and bring your hands to shoulder level, keeping your elbows at a 90-degree angle.", "Push the handles forward, extending your arms fully in front of you.", "Pause for a moment, then slowly reverse the movement, bringing your hands back to shoulder level.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将绳索机调整至胸部高度并安装手柄。", "背对机器站立，双脚与肩同宽。", "正手握住手柄并向前迈一步，以在电缆中产生张力。", "将双脚牢牢放在地面上并启动核心。", "弯曲肘部，将双手置于肩部水平，保持肘部呈 90 度角。", "向前推动手柄，将双臂完全伸展到身前。", "暂停片刻，然后慢慢扭转动作，将双手放回肩部水平。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["將繩索機調整至胸部高度并安裝手柄。", "背對機器站立，雙腳與肩同寬。", "正手握住手柄并向前邁一步，以在電纜中產生張力。", "將雙腳牢牢放在地面上并啟動核心。", "彎曲肘部，將雙手置于肩部水平，保持肘部呈 90 度角。", "向前推動手柄，將雙臂完全伸展到身前。", "暫停片刻，然后慢慢扭轉動作，將雙手放回肩部水平。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1630', 'exercise', 1, '{"id": "1630", "target": "biceps", "name_en": "cable close grip curl", "name_zh": "绳索窄握弯举", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/1630-BCGQ6J5.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索窄握彎舉", "instructions_en": ["Attach a straight bar to a low pulley cable machine.", "Stand facing the machine with your feet shoulder-width apart and your knees slightly bent.", "Grasp the bar with an underhand grip, hands shoulder-width apart.", "Keep your elbows close to your sides and your upper arms stationary throughout the exercise.", "Exhale and curl the bar up towards your shoulders, contracting your biceps.", "Pause for a moment at the top of the movement, squeezing your biceps.", "Inhale and slowly lower the bar back to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将直杆连接到低滑轮电缆机上。", "面向机器站立，双脚分开与肩同宽，膝盖稍微弯曲。", "反手握住杠铃，双手与肩同宽。", "在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。", "呼气并将杠铃向上卷向肩膀，收缩二头肌。", "在动作的最高点暂停片刻，挤压你的二头肌。", "吸气，慢慢将杠铃放回起始位置，充分伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["將直桿連接到低滑輪電纜機上。", "面向機器站立，雙腳分開與肩同寬，膝蓋稍微彎曲。", "反手握住杠鈴，雙手與肩同寬。", "在整個練習過程中，保持肘部靠近身體兩側，上臂保持靜止。", "呼氣并將杠鈴向上卷向肩膀，收縮二頭肌。", "在動作的最高點暫停片刻，擠壓你的二頭肌。", "吸氣，慢慢將杠鈴放回起始位置，充分伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1631', 'exercise', 1, '{"id": "1631", "target": "biceps", "name_en": "cable concentration curl", "name_zh": "绳索集中弯举", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/1631-NvfE43H.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索集中彎舉", "instructions_en": ["Sit on a bench or chair with your feet flat on the floor and your knees slightly bent.", "Hold the cable handle with an underhand grip and rest your elbow against the inside of your thigh.", "Keeping your upper arm stationary, exhale and curl the cable handle towards your shoulder while contracting your biceps.", "Pause for a moment at the top of the movement, then inhale and slowly lower the cable handle back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["坐在长凳或椅子上，双脚平放在地板上，膝盖稍微弯曲。", "用手握住电缆手柄，并将肘部靠在大腿内侧。", "保持上臂静止，呼气并将电缆手柄向肩膀卷曲，同时收缩二头肌。", "在动作的最高点暂停片刻，然后吸气并慢慢将拉索手柄放回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在長凳或椅子上，雙腳平放在地板上，膝蓋稍微彎曲。", "用手握住電纜手柄，并將肘部靠在大腿內側。", "保持上臂靜止，呼氣并將電纜手柄向肩膀卷曲，同時收縮二頭肌。", "在動作的最高點暫停片刻，然后吸氣并慢慢將拉索手柄放回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0152', 'exercise', 1, '{"id": "0152", "target": "triceps", "name_en": "cable concentration extension (on knee)", "name_zh": "绳索膝部支撑集中臂屈伸", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/0152-Db7eEgw.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索膝部支撐集中臂屈伸", "instructions_en": ["Sit on a bench or chair with your knees bent and feet flat on the ground.", "Hold the cable handle with your right hand and place your elbow on the inside of your right knee.", "Extend your arm fully, keeping your elbow stationary and close to your knee.", "Pause for a moment at the top, then slowly lower your arm back to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["坐在长凳或椅子上，膝盖弯曲，双脚平放在地上。", "用右手握住电缆手柄，并将肘部放在右膝盖内侧。", "充分伸展手臂，保持肘部静止并靠近膝盖。", "在顶部停顿片刻，然后慢慢将手臂放回起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在長凳或椅子上，膝蓋彎曲，雙腳平放在地上。", "用右手握住電纜手柄，并將肘部放在右膝蓋內側。", "充分伸展手臂，保持肘部靜止并靠近膝蓋。", "在頂部停頓片刻，然后慢慢將手臂放回起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0153', 'exercise', 1, '{"id": "0153", "target": "lats", "name_en": "cable cross-over lateral pulldown", "name_zh": "绳索交叉侧向下拉", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/0153-OQ1otBN.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索交叉側向下拉", "instructions_en": ["Attach a cable handle to each side of a cable machine at shoulder height.", "Stand in the middle of the machine with your feet shoulder-width apart.", "Grasp the handles with an overhand grip and step back to create tension in the cables.", "Lean forward slightly from the hips, keeping your back straight and your chest up.", "Pull the handles down and across your body, squeezing your shoulder blades together.", "Pause for a moment at the bottom of the movement, then slowly return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将电缆手柄连接到电缆机器两侧与肩同高的位置。", "站在机器中间，双脚分开与肩同宽。", "正手握住手柄并后退以在电缆中产生张力。", "从臀部开始稍微向前倾，保持背部挺直，挺胸。", "将手柄向下拉并穿过身体，将肩胛骨挤压在一起。", "在动作底部暂停片刻，然后慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "rhomboids", "rear deltoids"], "instructions_zh_hant": ["將電纜手柄連接到電纜機器兩側與肩同高的位置。", "站在機器中間，雙腳分開與肩同寬。", "正手握住手柄并后退以在電纜中產生張力。", "從臀部開始稍微向前傾，保持背部挺直，挺胸。", "將手柄向下拉并穿過身體，將肩胛骨擠壓在一起。", "在動作底部暫停片刻，然后慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0154', 'exercise', 1, '{"id": "0154", "target": "delts", "name_en": "cable cross-over revers fly", "name_zh": "绳索交叉反向飞鸟", "body_part": "shoulders", "equipment": "cable", "gif_asset": "assets/fitness/videos/0154-aqvSOQE.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索交叉反向飛鳥", "instructions_en": ["Attach a D-handle to each low pulley cable and stand in the middle of the cable crossover machine.", "Grasp the handles with a pronated grip (palms facing down) and take a step forward, positioning your feet shoulder-width apart.", "Bend your knees slightly and lean forward at the waist, keeping your back straight and your abs engaged.", "With your arms extended out to the sides and slightly bent at the elbows, exhale and squeeze your shoulder blades together as you pull the cables back and upward in a reverse fly motion.", "Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将 D 形手柄连接到每根低滑轮电缆上，并站在电缆交叉机的中间。", "旋前抓住手柄（手掌朝下），向前迈出一步，双脚分开与肩同宽。", "稍微弯曲膝盖，腰部前倾，保持背部挺直，腹部收紧。", "双臂向两侧伸展，肘部稍微弯曲，呼气并将肩胛骨挤压在一起，同时以反向飞翔动作向后和向上拉动绳索。", "在收缩峰值时停顿片刻，然后吸气，慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["rhomboids", "trapezius"], "instructions_zh_hant": ["將 D 形手柄連接到每根低滑輪電纜上，并站在電纜交叉機的中間。", "旋前抓住手柄（手掌朝下），向前邁出一步，雙腳分開與肩同寬。", "稍微彎曲膝蓋，腰部前傾，保持背部挺直，腹部收緊。", "雙臂向兩側伸展，肘部稍微彎曲，呼氣并將肩胛骨擠壓在一起，同時以反向飛翔動作向后和向上拉動繩索。", "在收縮峰值時停頓片刻，然后吸氣，慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0155', 'exercise', 1, '{"id": "0155", "target": "pectorals", "name_en": "cable cross-over variation", "name_zh": "绳索交叉夹胸变式", "body_part": "chest", "equipment": "cable", "gif_asset": "assets/fitness/videos/0155-0CXGHya.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索交叉夾胸變式", "instructions_en": ["Adjust the cable pulleys to chest height.", "Stand in the center of the cable machine with one foot in front of the other.", "Grasp the handles with your palms facing down and your arms extended out to the sides.", "Take a step forward, keeping your arms slightly bent.", "With a slight bend in your elbows, bring your hands together in front of your chest.", "Pause for a moment, then slowly return your arms back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将电缆滑轮调整至胸部高度。", "站在电缆机的中央，一只脚在另一只脚前面。", "手掌朝下抓住手柄，手臂向两侧伸展。", "向前迈出一步，保持手臂稍微弯曲。", "肘部稍微弯曲，双手并拢放在胸前。", "暂停片刻，然后慢慢将手臂放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["deltoids", "triceps"], "instructions_zh_hant": ["將電纜滑輪調整至胸部高度。", "站在電纜機的中央，一只腳在另一只腳前面。", "手掌朝下抓住手柄，手臂向兩側伸展。", "向前邁出一步，保持手臂稍微彎曲。", "肘部稍微彎曲，雙手并攏放在胸前。", "暫停片刻，然后慢慢將手臂放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0868', 'exercise', 1, '{"id": "0868", "target": "biceps", "name_en": "cable curl", "name_zh": "绳索弯举", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/0868-G08RZcQ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索彎舉", "instructions_en": ["Stand facing the cable machine with your feet shoulder-width apart.", "Grasp the cable attachment with an underhand grip, palms facing up.", "Keep your elbows close to your sides and your upper arms stationary.", "Exhale and curl the cable attachment towards your shoulders, contracting your biceps.", "Pause for a moment at the top of the movement, squeezing your biceps.", "Inhale and slowly lower the cable attachment back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["面对电缆机站立，双脚与肩同宽。", "用手握住电缆附件，手掌朝上。", "保持肘部靠近身体两侧，上臂保持静止。", "呼气并将电缆附件卷向肩膀，收缩二头肌。", "在动作的最高点暂停片刻，挤压你的二头肌。", "吸气并缓慢地将电缆附件放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["面對電纜機站立，雙腳與肩同寬。", "用手握住電纜附件，手掌朝上。", "保持肘部靠近身體兩側，上臂保持靜止。", "呼氣并將電纜附件卷向肩膀，收縮二頭肌。", "在動作的最高點暫停片刻，擠壓你的二頭肌。", "吸氣并緩慢地將電纜附件放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0157', 'exercise', 1, '{"id": "0157", "target": "glutes", "name_en": "cable deadlift", "name_zh": "绳索硬拉", "body_part": "upper legs", "equipment": "cable", "gif_asset": "assets/fitness/videos/0157-eGDudUV.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索硬拉", "instructions_en": ["Stand facing the cable machine with your feet shoulder-width apart.", "Bend at the hips and knees, lowering your torso until your back is parallel to the ground.", "Grasp the cable handles with an overhand grip, keeping your arms straight and your shoulders back.", "Engage your glutes and hamstrings to lift the cable handles, extending your hips and standing up straight.", "Pause for a moment at the top, then slowly lower the cable handles back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["面对电缆机站立，双脚与肩同宽。", "弯曲臀部和膝盖，降低躯干，直到背部与地面平行。", "正手握住电缆手柄，保持手臂伸直，肩膀向后。", "调动臀肌和腿筋来抬起拉索手柄，伸展臀部并站直。", "在顶部暂停片刻，然后慢慢将缆索手柄放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "quadriceps", "lower back"], "instructions_zh_hant": ["面對電纜機站立，雙腳與肩同寬。", "彎曲臀部和膝蓋，降低軀幹，直到背部與地面平行。", "正手握住電纜手柄，保持手臂伸直，肩膀向后。", "調動臀肌和腿筋來抬起拉索手柄，伸展臀部并站直。", "在頂部暫停片刻，然后慢慢將纜索手柄放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0158', 'exercise', 1, '{"id": "0158", "target": "pectorals", "name_en": "cable decline fly", "name_zh": "绳索下斜飞鸟", "body_part": "chest", "equipment": "cable", "gif_asset": "assets/fitness/videos/0158-7saC5zz.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索下斜飛鳥", "instructions_en": ["Adjust the cable machine to a decline position.", "Stand facing away from the machine with your feet shoulder-width apart.", "Hold the handles with your palms facing forward and your arms extended straight out in front of you.", "Keeping a slight bend in your elbows, open your arms out to the sides in a controlled motion.", "Pause for a moment at the fully extended position, then slowly return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将拉线机调整至下降位置。", "背对机器站立，双脚与肩同宽。", "握住手柄，手掌朝前，双臂在身前伸直。", "保持肘部轻微弯曲，以受控的动作向两侧张开双臂。", "在完全伸展位置停顿片刻，然后慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["將拉線機調整至下降位置。", "背對機器站立，雙腳與肩同寬。", "握住手柄，手掌朝前，雙臂在身前伸直。", "保持肘部輕微彎曲，以受控的動作向兩側張開雙臂。", "在完全伸展位置停頓片刻，然后慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1260', 'exercise', 1, '{"id": "1260", "target": "pectorals", "name_en": "cable decline one arm press", "name_zh": "绳索下斜单臂推举", "body_part": "chest", "equipment": "cable", "gif_asset": "assets/fitness/videos/1260-KHGNa16.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索下斜單臂推舉", "instructions_en": ["Adjust the cable machine to a decline position.", "Stand facing away from the machine and grab the handle with one hand.", "Position yourself with your back against the decline bench and your arm extended straight in front of you.", "Bend your elbow and lower the handle towards your chest while keeping your upper arm stationary.", "Pause for a moment at the bottom, then push the handle back up to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["将拉线机调整至下降位置。", "背对机器站立，用一只手抓住手柄。", "将背部靠在下斜长凳上，手臂伸直在身前。", "弯曲肘部，将手柄向胸部方向降低，同时保持上臂静止。", "在底部暂停片刻，然后将手柄推回到起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["將拉線機調整至下降位置。", "背對機器站立，用一只手抓住手柄。", "將背部靠在下斜長凳上，手臂伸直在身前。", "彎曲肘部，將手柄向胸部方向降低，同時保持上臂靜止。", "在底部暫停片刻，然后將手柄推回到起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1261', 'exercise', 1, '{"id": "1261", "target": "pectorals", "name_en": "cable decline press", "name_zh": "绳索下斜推举", "body_part": "chest", "equipment": "cable", "gif_asset": "assets/fitness/videos/1261-2Pya1cP.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索下斜推舉", "instructions_en": ["Adjust the cable machine to a decline position.", "Sit on the decline bench facing the cable machine.", "Grasp the handles with an overhand grip and position them at chest level.", "Keep your feet flat on the ground and your back firmly against the bench.", "Exhale and push the handles away from your body, extending your arms fully.", "Pause for a moment at the end of the movement, squeezing your chest muscles.", "Inhale and slowly return the handles back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将拉线机调整至下降位置。", "坐在面向缆绳机的下降长凳上。", "正手握住手柄并将其置于胸部水平。", "将双脚平放在地面上，并将背部牢牢靠在长凳上。", "呼气并将手柄推离身体，充分伸展双臂。", "动作结束时暂停片刻，挤压胸部肌肉。", "吸气并慢慢地将手柄放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["將拉線機調整至下降位置。", "坐在面向纜繩機的下降長凳上。", "正手握住手柄并將其置于胸部水平。", "將雙腳平放在地面上，并將背部牢牢靠在長凳上。", "呼氣并將手柄推離身體，充分伸展雙臂。", "動作結束時暫停片刻，擠壓胸部肌肉。", "吸氣并慢慢地將手柄放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0159', 'exercise', 1, '{"id": "0159", "target": "upper back", "name_en": "cable decline seated wide-grip row", "name_zh": "绳索下斜坐姿宽握划船", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/0159-kesXOpB.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索下斜坐姿寬握劃船", "instructions_en": ["Sit on the decline bench facing the cable machine with your feet securely placed on the footrests.", "Grasp the cable attachment with a wide overhand grip, palms facing down.", "Lean back slightly, keeping your back straight and your core engaged.", "Pull the cable towards your lower chest, squeezing your shoulder blades together.", "Pause for a moment at the peak of the contraction, then slowly release the cable back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在面向缆绳机的下斜长凳上，双脚牢固地放在脚踏板上。", "用宽的正手握法抓住电缆附件，手掌朝下。", "稍微向后倾斜，保持背部挺直，核心肌群参与。", "将电缆拉向下胸部，将肩胛骨挤压在一起。", "在收缩的峰值处暂停片刻，然后慢慢地将电缆释放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["坐在面向纜繩機的下斜長凳上，雙腳牢固地放在腳踏板上。", "用寬的正手握法抓住電纜附件，手掌朝下。", "稍微向后傾斜，保持背部挺直，核心肌群參與。", "將電纜拉向下胸部，將肩胛骨擠壓在一起。", "在收縮的峰值處暫停片刻，然后慢慢地將電纜釋放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1632', 'exercise', 1, '{"id": "1632", "target": "biceps", "name_en": "cable drag curl", "name_zh": "绳索拖拉弯举", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/1632-dXz8zjF.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索拖拉彎舉", "instructions_en": ["Stand facing a cable machine with your feet shoulder-width apart.", "Grasp the cable attachment with an underhand grip, palms facing up, and arms fully extended.", "Keeping your upper arms stationary, exhale and curl the cable attachment towards your shoulders by contracting your biceps.", "Pause for a moment at the top of the movement, squeezing your biceps.", "Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["面向缆绳机站立，双脚与肩同宽。", "用手握住电缆附件，手掌朝上，手臂完全伸展。", "保持上臂静止，呼气并通过收缩二头肌将电缆附件卷曲至肩膀。", "在动作的最高点暂停片刻，挤压你的二头肌。", "吸气并慢慢将电缆附件放回起始位置，充分伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["面向纜繩機站立，雙腳與肩同寬。", "用手握住電纜附件，手掌朝上，手臂完全伸展。", "保持上臂靜止，呼氣并通過收縮二頭肌將電纜附件卷曲至肩膀。", "在動作的最高點暫停片刻，擠壓你的二頭肌。", "吸氣并慢慢將電纜附件放回起始位置，充分伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0160', 'exercise', 1, '{"id": "0160", "target": "upper back", "name_en": "cable floor seated wide-grip row", "name_zh": "绳索地板坐姿宽握划船", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/0160-veXwo0D.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索地板坐姿寬握劃船", "instructions_en": ["Sit on the floor with your legs extended and your back straight.", "Attach a cable handle to a low pulley and position the cable machine behind you.", "Grasp the handle with a wide overhand grip, palms facing down.", "Lean back slightly, keeping your back straight and your chest lifted.", "Pull the handle towards your waist, squeezing your shoulder blades together.", "Pause for a moment at the top of the movement, then slowly release the handle back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在地板上，双腿伸直，背部挺直。", "将缆绳手柄连接到低滑轮上，并将缆绳机放在您身后。", "正手宽握握住手柄，手掌朝下。", "稍微向后倾斜，保持背部挺直，挺胸。", "将手柄拉向腰部，将肩胛骨挤压在一起。", "在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["坐在地板上，雙腿伸直，背部挺直。", "將纜繩手柄連接到低滑輪上，并將纜繩機放在您身后。", "正手寬握握住手柄，手掌朝下。", "稍微向后傾斜，保持背部挺直，挺胸。", "將手柄拉向腰部，將肩胛骨擠壓在一起。", "在動作的最高點暫停片刻，然后慢慢松開手柄回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0161', 'exercise', 1, '{"id": "0161", "target": "delts", "name_en": "cable forward raise", "name_zh": "绳索前平举", "body_part": "shoulders", "equipment": "cable", "gif_asset": "assets/fitness/videos/0161-hvHhCv8.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索前平舉", "instructions_en": ["Stand with your feet shoulder-width apart and your knees slightly bent.", "Hold the cable handle with an overhand grip, palms facing down, and your arms fully extended in front of you.", "Keeping your arms straight, raise the cable handle up to shoulder level.", "Pause for a moment at the top, then slowly lower the cable handle back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，膝盖稍微弯曲。", "正手握住电缆手柄，手掌朝下，双臂在身前完全伸展。", "保持手臂伸直，将电缆手柄抬高至肩部水平。", "在顶部暂停片刻，然后慢慢将缆索手柄放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，膝蓋稍微彎曲。", "正手握住電纜手柄，手掌朝下，雙臂在身前完全伸展。", "保持手臂伸直，將電纜手柄抬高至肩部水平。", "在頂部暫停片刻，然后慢慢將纜索手柄放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0162', 'exercise', 1, '{"id": "0162", "target": "delts", "name_en": "cable front raise", "name_zh": "绳索前平举", "body_part": "shoulders", "equipment": "cable", "gif_asset": "assets/fitness/videos/0162-u2X71Np.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索前平舉", "instructions_en": ["Stand with your feet shoulder-width apart and grasp the cable handle with an overhand grip.", "Keep your back straight and your core engaged.", "Raise the cable handle in front of you, keeping your arms straight and your palms facing down.", "Continue lifting until your arms are parallel to the floor.", "Pause for a moment at the top, then slowly lower the cable handle back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，并用正手握住电缆手柄。", "保持背部挺直，核心肌群参与。", "将电缆手柄举到您面前，保持手臂伸直，手掌朝下。", "继续抬起，直到手臂与地板平行。", "在顶部暂停片刻，然后慢慢将拉索手柄放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，并用正手握住電纜手柄。", "保持背部挺直，核心肌群參與。", "將電纜手柄舉到您面前，保持手臂伸直，手掌朝下。", "繼續抬起，直到手臂與地板平行。", "在頂部暫停片刻，然后慢慢將拉索手柄放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0164', 'exercise', 1, '{"id": "0164", "target": "delts", "name_en": "cable front shoulder raise", "name_zh": "绳索肩部前平举", "body_part": "shoulders", "equipment": "cable", "gif_asset": "assets/fitness/videos/0164-mTT3KLn.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索肩部前平舉", "instructions_en": ["Stand with your feet shoulder-width apart and grasp the cable handle with an overhand grip.", "Keep your back straight and your core engaged.", "Raise the cable handle in front of you, keeping your arms straight and your palms facing down.", "Continue lifting until your arms are parallel to the floor.", "Pause for a moment at the top, then slowly lower the cable handle back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，并用正手握住电缆手柄。", "保持背部挺直，核心肌群参与。", "将电缆手柄举到您面前，保持手臂伸直，手掌朝下。", "继续抬起，直到手臂与地板平行。", "在顶部暂停片刻，然后慢慢将拉索手柄放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["trapezius", "biceps"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，并用正手握住電纜手柄。", "保持背部挺直，核心肌群參與。", "將電纜手柄舉到您面前，保持手臂伸直，手掌朝下。", "繼續抬起，直到手臂與地板平行。", "在頂部暫停片刻，然后慢慢將拉索手柄放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0165', 'exercise', 1, '{"id": "0165", "target": "biceps", "name_en": "cable hammer curl (with rope)", "name_zh": "绳索锤式弯举（配合绳索）", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/0165-HPlPoQA.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索錘式彎舉（配合繩索）", "instructions_en": ["Stand upright with your feet shoulder-width apart and a slight bend in your knees.", "Hold the cable rope attachment with an underhand grip, palms facing each other, and your arms fully extended.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the cable rope attachment until your biceps are fully contracted and the rope is at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the cable rope attachment back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站直，双脚分开与肩同宽，膝盖稍微弯曲。", "双手握住缆绳附件，手掌相对，手臂完全伸展。", "保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。", "继续提升缆绳附件，直到您的二头肌完全收缩并且绳索与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将缆绳附件降低回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙腳分開與肩同寬，膝蓋稍微彎曲。", "雙手握住纜繩附件，手掌相對，手臂完全伸展。", "保持上臂靜止，呼氣并彎舉啞鈴，同時收縮二頭肌。", "繼續提升纜繩附件，直到您的二頭肌完全收縮并且繩索與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將纜繩附件降低回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1722', 'exercise', 1, '{"id": "1722", "target": "triceps", "name_en": "cable high pulley overhead tricep extension", "name_zh": "绳索高位滑轮过顶臂屈伸", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/1722-1xHyxys.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索高位滑輪過頂臂屈伸", "instructions_en": ["Attach a rope to a high pulley and stand facing away from the machine.", "Grasp the rope with both hands and extend your arms overhead.", "Keep your elbows close to your head and your upper arms stationary.", "Slowly lower the rope behind your head by bending your elbows.", "Pause for a moment, then extend your arms back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将绳子连接到高滑轮上，背对机器站立。", "双手抓住绳子，并将双臂伸过头顶。", "保持肘部靠近头部，上臂保持静止。", "弯曲肘部，慢慢将绳子降低到头后。", "暂停片刻，然后将手臂伸回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["將繩子連接到高滑輪上，背對機器站立。", "雙手抓住繩子，并將雙臂伸過頭頂。", "保持肘部靠近頭部，上臂保持靜止。", "彎曲肘部，慢慢將繩子降低到頭后。", "暫停片刻，然后將手臂伸回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0184', 'exercise', 1, '{"id": "0184", "target": "lats", "name_en": "cable lying extension pullover (with rope attachment)", "name_zh": "绳索卧姿伸展仰卧上拉（配合绳索把手）", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/0184-Q2Eu1Ax.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索臥姿伸展仰臥上拉（配合繩索把手）", "instructions_en": ["Attach a rope to a cable machine and set the pulley at the highest position.", "Lie down on a bench with your head towards the cable machine.", "Hold the rope with both hands and extend your arms straight up above your chest.", "Keeping your arms straight, slowly lower the rope behind your head while maintaining control.", "Pause for a moment at the bottom, then slowly raise the rope back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将绳子连接到缆绳机上，并将滑轮设置在最高位置。", "躺在长凳上，头朝向电缆机。", "双手握住绳子，将双臂伸直至胸部上方。", "保持双臂伸直，在保持控制的同时慢慢将绳子放到脑后。", "在底部停顿片刻，然后慢慢将绳子拉回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["將繩子連接到纜繩機上，并將滑輪設置在最高位置。", "躺在長凳上，頭朝向電纜機。", "雙手握住繩子，將雙臂伸直至胸部上方。", "保持雙臂伸直，在保持控制的同時慢慢將繩子放到腦后。", "在底部停頓片刻，然后慢慢將繩子拉回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0167', 'exercise', 1, '{"id": "0167", "target": "upper back", "name_en": "cable high row (kneeling)", "name_zh": "绳索高位划船（跪姿）", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/0167-ZSJNetl.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索高位劃船（跪姿）", "instructions_en": ["Attach a straight bar to a cable machine at chest height.", "Kneel down in front of the cable machine and grab the bar with an overhand grip, hands shoulder-width apart.", "Sit back on your heels, keeping your back straight and your core engaged.", "Pull the bar towards your upper abdomen, squeezing your shoulder blades together.", "Pause for a moment at the top of the movement, then slowly release the bar back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将直杆连接到胸部高度的缆绳机上。", "跪在缆绳机前，用正握方式抓住杠铃，双手与肩同宽。", "坐在脚后跟上，保持背部挺直，核心肌群参与。", "将杠铃拉向上腹部，将肩胛骨挤压在一起。", "在动作的最高点暂停片刻，然后慢慢松开杠铃回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "shoulders"], "instructions_zh_hant": ["將直桿連接到胸部高度的纜繩機上。", "跪在纜繩機前，用正握方式抓住杠鈴，雙手與肩同寬。", "坐在腳后跟上，保持背部挺直，核心肌群參與。", "將杠鈴拉向上腹部，將肩胛骨擠壓在一起。", "在動作的最高點暫停片刻，然后慢慢松開杠鈴回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0168', 'exercise', 1, '{"id": "0168", "target": "adductors", "name_en": "cable hip adduction", "name_zh": "绳索髋部内收", "body_part": "upper legs", "equipment": "cable", "gif_asset": "assets/fitness/videos/0168-hBGWILP.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索髖部內收", "instructions_en": ["Attach the ankle cuff to your ankle and stand facing the cable machine.", "Position yourself far enough away from the machine so that there is tension on the cable.", "Place your hands on the machine for support.", "Keeping your leg straight, slowly move your leg across your body towards the midline.", "Pause for a moment at the end of the movement, then slowly return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将脚踝套戴到脚踝上，面向电缆机站立。", "将自己放置在距离机器足够远的位置，以便电缆上有张力。", "将手放在机器上以获得支撑。", "保持腿伸直，慢慢将腿移向身体中线。", "动作结束时暂停片刻，然后慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "quadriceps"], "instructions_zh_hant": ["將腳踝套戴到腳踝上，面向電纜機站立。", "將自己放置在距離機器足夠遠的位置，以便電纜上有張力。", "將手放在機器上以獲得支撐。", "保持腿伸直，慢慢將腿移向身體中線。", "動作結束時暫停片刻，然后慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0169', 'exercise', 1, '{"id": "0169", "target": "pectorals", "name_en": "cable incline bench press", "name_zh": "绳索上斜卧推", "body_part": "chest", "equipment": "cable", "gif_asset": "assets/fitness/videos/0169-Vh0GsK4.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索上斜臥推", "instructions_en": ["Adjust the bench to a 45-degree incline.", "Attach the cable handles to the high pulleys.", "Sit on the bench facing the cable machine with your feet flat on the ground.", "Grasp the handles with an overhand grip and bring them to shoulder height.", "Push the handles forward and upward until your arms are fully extended.", "Pause for a moment, then slowly lower the handles back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将长凳调整至 45 度倾斜。", "将电缆手柄连接到高滑轮上。", "坐在长凳上，面向电缆机，双脚平放在地面上。", "正手握住手柄，并将其拉至肩部高度。", "向前和向上推动手柄，直到手臂完全伸展。", "暂停片刻，然后慢慢将手柄放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["deltoids", "triceps"], "instructions_zh_hant": ["將長凳調整至 45 度傾斜。", "將電纜手柄連接到高滑輪上。", "坐在長凳上，面向電纜機，雙腳平放在地面上。", "正手握住手柄，并將其拉至肩部高度。", "向前和向上推動手柄，直到手臂完全伸展。", "暫停片刻，然后慢慢將手柄放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1318', 'exercise', 1, '{"id": "1318", "target": "upper back", "name_en": "cable incline bench row", "name_zh": "绳索上斜凳上划船", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/1318-yaMIo4D.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索上斜凳上劃船", "instructions_en": ["Set up an incline bench at a 45-degree angle and attach a cable handle to the low pulley.", "Sit on the bench facing the cable machine with your feet flat on the floor and your knees slightly bent.", "Grasp the cable handle with an overhand grip and extend your arms fully in front of you.", "Lean forward from your hips while keeping your back straight and your core engaged.", "Pull the cable handle towards your chest by retracting your shoulder blades and bending your elbows.", "Squeeze your back muscles at the top of the movement, then slowly extend your arms back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["以 45 度角设置一个上斜凳，并将绳索手柄连接到低滑轮上。", "坐在长凳上，面向电缆机，双脚平放在地板上，膝盖稍微弯曲。", "正手握住电缆手柄，并将双臂完全伸展到身前。", "从臀部开始向前倾，同时保持背部挺直，核心肌群参与。", "缩回肩胛骨并弯曲肘部，将电缆手柄拉向胸部。", "在动作的最高点挤压背部肌肉，然后慢慢伸展手臂回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "rear deltoids"], "instructions_zh_hant": ["以 45 度角設置一個上斜凳，并將繩索手柄連接到低滑輪上。", "坐在長凳上，面向電纜機，雙腳平放在地板上，膝蓋稍微彎曲。", "正手握住電纜手柄，并將雙臂完全伸展到身前。", "從臀部開始向前傾，同時保持背部挺直，核心肌群參與。", "縮回肩胛骨并彎曲肘部，將電纜手柄拉向胸部。", "在動作的最高點擠壓背部肌肉，然后慢慢伸展手臂回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0171', 'exercise', 1, '{"id": "0171", "target": "pectorals", "name_en": "cable incline fly", "name_zh": "绳索上斜飞鸟", "body_part": "chest", "equipment": "cable", "gif_asset": "assets/fitness/videos/0171-tBWXbIT.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索上斜飛鳥", "instructions_en": ["Adjust the cable machine to a low position and attach the handles.", "Sit on an incline bench with your back against the pad and feet flat on the floor.", "Grasp the handles with an overhand grip and extend your arms straight out in front of you.", "Keeping a slight bend in your elbows, open your arms out to the sides in a controlled motion.", "Pause for a moment at the fully extended position, then slowly return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将电缆机调整至较低位置并安装手柄。", "坐在倾斜的长凳上，背部靠在垫子上，双脚平放在地板上。", "正手握住手柄，并将双臂伸直至身前。", "保持肘部轻微弯曲，以受控的动作向两侧张开双臂。", "在完全伸展位置停顿片刻，然后慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["deltoids", "triceps"], "instructions_zh_hant": ["將電纜機調整至較低位置并安裝手柄。", "坐在傾斜的長凳上，背部靠在墊子上，雙腳平放在地板上。", "正手握住手柄，并將雙臂伸直至身前。", "保持肘部輕微彎曲，以受控的動作向兩側張開雙臂。", "在完全伸展位置停頓片刻，然后慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0170', 'exercise', 1, '{"id": "0170", "target": "pectorals", "name_en": "cable incline fly (on stability ball)", "name_zh": "健身球绳索上斜飞鸟", "body_part": "chest", "equipment": "cable", "gif_asset": "assets/fitness/videos/0170-27NNGFr.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球繩索上斜飛鳥", "instructions_en": ["Set up a stability ball at an incline angle.", "Attach the cable handles to the high pulleys of a cable machine.", "Sit on the stability ball facing away from the machine, with your feet firmly planted on the ground.", "Grasp the cable handles with an overhand grip, palms facing forward.", "Lean forward slightly, keeping your back straight and core engaged.", "With a controlled motion, bring your arms out to the sides, keeping a slight bend in your elbows.", "Continue the motion until your arms are parallel to the ground.", "Pause for a moment, then slowly return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["以倾斜角度设置稳定球。", "将电缆手柄连接到电缆机的高滑轮上。", "背对机器坐在稳定球上，双脚牢牢踩在地面上。", "正手握住电缆手柄，手掌朝前。", "稍微向前倾，保持背部挺直，核心参与。", "控制动作，将手臂向两侧伸出，保持肘部轻微弯曲。", "继续这个动作，直到手臂与地面平行。", "暂停片刻，然后慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["deltoids", "triceps"], "instructions_zh_hant": ["以傾斜角度設置穩定球。", "將電纜手柄連接到電纜機的高滑輪上。", "背對機器坐在穩定球上，雙腳牢牢踩在地面上。", "正手握住電纜手柄，手掌朝前。", "稍微向前傾，保持背部挺直，核心參與。", "控制動作，將手臂向兩側伸出，保持肘部輕微彎曲。", "繼續這個動作，直到手臂與地面平行。", "暫停片刻，然后慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0172', 'exercise', 1, '{"id": "0172", "target": "lats", "name_en": "cable incline pushdown", "name_zh": "绳索上斜下压", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/0172-1PK5Uo3.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索上斜下壓", "instructions_en": ["Attach a straight bar to a high pulley cable machine.", "Stand facing away from the machine with your feet shoulder-width apart.", "Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.", "Lean forward slightly and keep your back straight.", "Pull the bar down towards your thighs by extending your elbows.", "Pause for a moment at the bottom, then slowly return the bar to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将直杆连接到高滑轮电缆机上。", "背对机器站立，双脚与肩同宽。", "正手握住杠铃，双手距离略宽于肩宽。", "稍微向前倾并保持背部挺直。", "伸展肘部，将杠铃向下拉向大腿。", "在底部暂停片刻，然后慢慢地将杠铃返回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["將直桿連接到高滑輪電纜機上。", "背對機器站立，雙腳與肩同寬。", "正手握住杠鈴，雙手距離略寬于肩寬。", "稍微向前傾并保持背部挺直。", "伸展肘部，將杠鈴向下拉向大腿。", "在底部暫停片刻，然后慢慢地將杠鈴返回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1476', 'exercise', 1, '{"id": "1476", "target": "glutes", "name_en": "one leg squat", "name_zh": "单腿深蹲", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1476-C31LMnP.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "單腿深蹲", "instructions_en": ["Stand with your feet shoulder-width apart.", "Extend one leg forward, keeping it off the ground.", "Bend your standing leg and lower your body down as if sitting back into a chair.", "Keep your chest up and your back straight.", "Push through your heel to return to the starting position.", "Repeat with the other leg."], "instructions_zh": ["双脚分开与肩同宽站立。", "向前伸出一条腿，使其离开地面。", "弯曲站立的腿并降低身体，就像坐回椅子上一样。", "保持挺胸、背部挺直。", "推动脚后跟返回到起始位置。", "换另一条腿重复上述步骤。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立。", "向前伸出一條腿，使其離開地面。", "彎曲站立的腿并降低身體，就像坐回椅子上一樣。", "保持挺胸、背部挺直。", "推動腳后跟返回到起始位置。", "換另一條腿重復上述步驟。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0173', 'exercise', 1, '{"id": "0173", "target": "triceps", "name_en": "cable incline triceps extension", "name_zh": "绳索上斜臂屈伸", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/0173-Hx1WC8I.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索上斜臂屈伸", "instructions_en": ["Adjust the cable machine to a low pulley position.", "Attach a straight bar to the cable.", "Stand facing away from the machine with your feet shoulder-width apart.", "Grasp the bar with an overhand grip and extend your arms straight overhead.", "Lean forward slightly, keeping your back straight and core engaged.", "Bend your elbows and lower the bar behind your head, keeping your upper arms close to your ears.", "Pause for a moment, then extend your arms back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将拉索机调整至低滑轮位置。", "将直杆连接到电缆上。", "背对机器站立，双脚与肩同宽。", "正手握住杠铃，并将手臂伸直过头顶。", "稍微向前倾，保持背部挺直，核心参与。", "弯曲肘部，将杠铃放低到脑后，保持上臂靠近耳朵。", "暂停片刻，然后将手臂伸回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["將拉索機調整至低滑輪位置。", "將直桿連接到電纜上。", "背對機器站立，雙腳與肩同寬。", "正手握住杠鈴，并將手臂伸直過頭頂。", "稍微向前傾，保持背部挺直，核心參與。", "彎曲肘部，將杠鈴放低到腦后，保持上臂靠近耳朵。", "暫停片刻，然后將手臂伸回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0174', 'exercise', 1, '{"id": "0174", "target": "abs", "name_en": "cable judo flip", "name_zh": "绳索柔道翻转", "body_part": "waist", "equipment": "cable", "gif_asset": "assets/fitness/videos/0174-MvQPqVW.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索柔道翻轉", "instructions_en": ["Stand facing the cable machine with your feet shoulder-width apart.", "Hold the cable handle with both hands at chest level, palms facing down.", "Engage your core and rotate your torso to the right, pulling the cable across your body.", "As you rotate, pivot your back foot and allow your hips to rotate naturally.", "Extend your arms fully and finish the movement by flipping the cable handle over your shoulder.", "Return to the starting position by reversing the movement, rotating your torso back to the center.", "Repeat the movement on the opposite side.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["面对电缆机站立，双脚与肩同宽。", "用双手握住电缆手柄，使其与胸部齐平，手掌朝下。", "启动你的核心并将你的躯干向右旋转，将电缆拉过你的身体。", "当你旋转时，转动后脚并让臀部自然旋转。", "充分伸展双臂，将绳索手柄翻转到肩膀上来完成动作。", "通过反向运动返回起始位置，将躯干旋转回中心。", "在另一侧重复该动作。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["obliques", "shoulders"], "instructions_zh_hant": ["面對電纜機站立，雙腳與肩同寬。", "用雙手握住電纜手柄，使其與胸部齊平，手掌朝下。", "啟動你的核心并將你的軀幹向右旋轉，將電纜拉過你的身體。", "當你旋轉時，轉動后腳并讓臀部自然旋轉。", "充分伸展雙臂，將繩索手柄翻轉到肩膀上來完成動作。", "通過反向運動返回起始位置，將軀幹旋轉回中心。", "在另一側重復該動作。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0860', 'exercise', 1, '{"id": "0860", "target": "triceps", "name_en": "cable kickback", "name_zh": "绳索臂后屈伸", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/0860-HEJ6DIX.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索臂后屈伸", "instructions_en": ["Stand facing a cable machine with your feet shoulder-width apart.", "Hold the cable handle with your right hand and step back to create tension in the cable.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Keep your upper arm close to your body and your elbow bent at a 90-degree angle.", "Extend your forearm backward, straightening your arm fully.", "Pause for a moment, then slowly return to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["面向缆绳机站立，双脚与肩同宽。", "用右手握住电缆手柄并后退以在电缆中产生张力。", "稍微弯曲膝盖，髋部向前转动，保持背部挺直。", "保持上臂靠近身体，肘部弯曲成 90 度角。", "向后伸展前臂，完全伸直手臂。", "暂停片刻，然后慢慢回到起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["面向纜繩機站立，雙腳與肩同寬。", "用右手握住電纜手柄并后退以在電纜中產生張力。", "稍微彎曲膝蓋，髖部向前轉動，保持背部挺直。", "保持上臂靠近身體，肘部彎曲成 90 度角。", "向后伸展前臂，完全伸直手臂。", "暫停片刻，然后慢慢回到起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0175', 'exercise', 1, '{"id": "0175", "target": "abs", "name_en": "cable kneeling crunch", "name_zh": "绳索跪姿卷腹", "body_part": "waist", "equipment": "cable", "gif_asset": "assets/fitness/videos/0175-WW95auq.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索跪姿卷腹", "instructions_en": ["Attach a rope handle to a high pulley and kneel down facing away from the machine.", "Hold the rope handle with both hands and place it behind your head, keeping your elbows out to the sides.", "Keeping your hips stationary, flex your waist and crunch your torso down towards your thighs.", "Pause for a moment at the bottom, then slowly return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将绳索手柄连接到高滑轮上，然后面向远离机器的方向跪下。", "双手握住绳柄，将其放在脑后，肘部向两侧伸出。", "保持臀部不动，弯曲腰部并将躯干向大腿方向挤压。", "在底部停顿片刻，然后慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["obliques"], "instructions_zh_hant": ["將繩索手柄連接到高滑輪上，然后面向遠離機器的方向跪下。", "雙手握住繩柄，將其放在腦后，肘部向兩側伸出。", "保持臀部不動，彎曲腰部并將軀幹向大腿方向擠壓。", "在底部停頓片刻，然后慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3697', 'exercise', 1, '{"id": "3697", "target": "delts", "name_en": "cable kneeling rear delt row (with rope) (male)", "name_zh": "绳索跪姿三角肌后束划船（配合绳索）（男性示范）", "body_part": "shoulders", "equipment": "cable", "gif_asset": "assets/fitness/videos/3697-G61cXLk.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索跪姿三角肌后束劃船（配合繩索）（男性示范）", "instructions_en": ["Attach a rope handle to a low cable pulley and kneel down facing the machine.", "Grasp the rope with a neutral grip (palms facing each other) and extend your arms fully in front of you.", "Keeping your back straight and core engaged, pull the rope towards your body by retracting your shoulder blades.", "Squeeze your shoulder blades together at the end of the movement and hold for a brief pause.", "Slowly release the tension and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将绳索手柄连接到低电缆滑轮上，面向机器跪下。", "以中立握法（手掌相对）抓住绳子，并将双臂完全伸展到身前。", "保持背部挺直，核心收紧，通过收缩肩胛骨将绳子拉向身体。", "在动作结束时将肩胛骨挤压在一起并保持短暂的停顿。", "慢慢释放张力并回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["trapezius", "rhomboids", "biceps"], "instructions_zh_hant": ["將繩索手柄連接到低電纜滑輪上，面向機器跪下。", "以中立握法（手掌相對）抓住繩子，并將雙臂完全伸展到身前。", "保持背部挺直，核心收緊，通過收縮肩胛骨將繩子拉向身體。", "在動作結束時將肩胛骨擠壓在一起并保持短暫的停頓。", "慢慢釋放張力并回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0176', 'exercise', 1, '{"id": "0176", "target": "triceps", "name_en": "cable kneeling triceps extension", "name_zh": "绳索跪姿臂屈伸", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/0176-KWdF2JI.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索跪姿臂屈伸", "instructions_en": ["Attach a rope handle to a high pulley and kneel down facing the cable machine.", "Grasp the rope with a neutral grip (palms facing each other) and bring your hands to the sides of your head.", "Keep your elbows close to your head and your upper arms stationary throughout the exercise.", "Extend your forearms by contracting your triceps until your arms are fully extended.", "Pause for a moment, then slowly return to the starting position by bending your elbows.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将绳索手柄连接到高滑轮上，面向绳索机跪下。", "以中立握法（手掌相对）抓住绳子，并将双手放在头的两侧。", "在整个练习过程中，保持肘部靠近头部，上臂保持静止。", "通过收缩三头肌来伸展前臂，直到手臂完全伸展。", "暂停片刻，然后弯曲肘部慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["將繩索手柄連接到高滑輪上，面向繩索機跪下。", "以中立握法（手掌相對）抓住繩子，并將雙手放在頭的兩側。", "在整個練習過程中，保持肘部靠近頭部，上臂保持靜止。", "通過收縮三頭肌來伸展前臂，直到手臂完全伸展。", "暫停片刻，然后彎曲肘部慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2330', 'exercise', 1, '{"id": "2330", "target": "lats", "name_en": "cable lat pulldown full range of motion", "name_zh": "绳索全程高位下拉", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/2330-LEprlgG.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索全程高位下拉", "instructions_en": ["Sit on the lat pulldown machine with your knees positioned under the pads.", "Grasp the cable bar with an overhand grip, slightly wider than shoulder-width apart.", "Lean back slightly and keep your chest up, maintaining a slight arch in your lower back.", "Pull the bar down towards your upper chest, squeezing your shoulder blades together.", "Pause for a moment at the bottom of the movement, then slowly release the bar back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在高位下拉机上，膝盖位于护垫下方。", "正手握住电缆杆，握距略宽于肩宽。", "稍微向后倾斜，挺胸，保持下背部轻微的拱形。", "将杠铃向下拉至上胸部，将肩胛骨挤压在一起。", "在动作底部暂停片刻，然后慢慢松开杠铃回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "rhomboids", "rear deltoids"], "instructions_zh_hant": ["坐在高位下拉機上，膝蓋位于護墊下方。", "正手握住電纜桿，握距略寬于肩寬。", "稍微向后傾斜，挺胸，保持下背部輕微的拱形。", "將杠鈴向下拉至上胸部，將肩胛骨擠壓在一起。", "在動作底部暫停片刻，然后慢慢松開杠鈴回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0177', 'exercise', 1, '{"id": "0177", "target": "lats", "name_en": "cable lateral pulldown (with rope attachment)", "name_zh": "绳索侧向下拉（配合绳索把手）", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/0177-CuaWCmC.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索側向下拉（配合繩索把手）", "instructions_en": ["Attach a rope attachment to the cable machine at a high position.", "Stand facing the machine with your feet shoulder-width apart.", "Grasp the rope with an overhand grip, palms facing each other.", "Keep your back straight and lean slightly back.", "Pull the rope down towards your sides, squeezing your shoulder blades together.", "Pause for a moment at the bottom of the movement.", "Slowly release the tension and allow the rope to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将绳索附件连接到电缆机的高位置。", "面向机器站立，双脚分开与肩同宽。", "正手握住绳子，手掌相对。", "保持背部挺直并稍微向后倾斜。", "将绳子向下拉向身体两侧，将肩胛骨挤压在一起。", "在动作的底部停顿片刻。", "慢慢释放张力，让绳子回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["將繩索附件連接到電纜機的高位置。", "面向機器站立，雙腳分開與肩同寬。", "正手握住繩子，手掌相對。", "保持背部挺直并稍微向后傾斜。", "將繩子向下拉向身體兩側，將肩胛骨擠壓在一起。", "在動作的底部停頓片刻。", "慢慢釋放張力，讓繩子回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2616', 'exercise', 1, '{"id": "2616", "target": "lats", "name_en": "cable lateral pulldown with v-bar", "name_zh": "绳索侧向下拉配合V形把手", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/2616-4c9BhzB.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索側向下拉配合V形把手", "instructions_en": ["Sit down on the cable pulldown machine and grab the v-bar attachment with an overhand grip.", "Adjust the knee pad so that your thighs are secured under it.", "Keep your back straight and lean back slightly.", "Pull the v-bar down towards your upper chest while keeping your elbows close to your body.", "Squeeze your back muscles at the bottom of the movement.", "Slowly return the v-bar to the starting position and repeat for the desired number of repetitions."], "instructions_zh": ["坐在电缆下拉机上，用正手抓住 V 形杆附件。", "调整护膝，使大腿固定在其下方。", "保持背部挺直并稍微向后倾斜。", "将 V 形杆向下拉至上胸部，同时保持肘部靠近身体。", "在动作底部挤压背部肌肉。", "慢慢地将 v 形杆返回到起始位置，然后重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["坐在電纜下拉機上，用正手抓住 V 形桿附件。", "調整護膝，使大腿固定在其下方。", "保持背部挺直并稍微向后傾斜。", "將 V 形桿向下拉至上胸部，同時保持肘部靠近身體。", "在動作底部擠壓背部肌肉。", "慢慢地將 v 形桿返回到起始位置，然后重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0178', 'exercise', 1, '{"id": "0178", "target": "delts", "name_en": "cable lateral raise", "name_zh": "绳索侧平举", "body_part": "shoulders", "equipment": "cable", "gif_asset": "assets/fitness/videos/0178-goJ6ezq.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索側平舉", "instructions_en": ["Stand with your feet shoulder-width apart and grasp the cable handles with an overhand grip.", "Keep your arms straight and your core engaged.", "Raise your arms out to the sides until they are parallel to the floor.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，并用正手握住电缆手柄。", "保持双臂伸直，核心肌群参与。", "将手臂向两侧举起，直到与地板平行。", "在顶部暂停片刻，然后慢慢将手臂放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["traps", "triceps"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，并用正手握住電纜手柄。", "保持雙臂伸直，核心肌群參與。", "將手臂向兩側舉起，直到與地板平行。", "在頂部暫停片刻，然后慢慢將手臂放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0179', 'exercise', 1, '{"id": "0179", "target": "pectorals", "name_en": "cable low fly", "name_zh": "绳索低位飞鸟", "body_part": "chest", "equipment": "cable", "gif_asset": "assets/fitness/videos/0179-FVmZVhk.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索低位飛鳥", "instructions_en": ["Attach the handles to the low pulleys of a cable machine and select an appropriate weight.", "Stand in the middle of the machine with your feet shoulder-width apart and a slight bend in your knees.", "Grasp the handles with an overhand grip and extend your arms out to the sides, keeping a slight bend in your elbows.", "Maintaining control, slowly bring your arms forward in a sweeping motion, crossing them in front of your body.", "Pause for a moment at the peak of the movement, feeling the stretch in your chest muscles.", "Reverse the motion and slowly return your arms to the starting position, keeping tension on your chest muscles throughout.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将手柄连接到缆绳机的低滑轮上，并选择合适的重量。", "站在机器中间，双脚分开与肩同宽，膝盖稍微弯曲。", "正手握住手柄，将手臂向两侧伸展，肘部保持轻微弯曲。", "保持控制，以扫过的动作缓慢地将手臂向前伸，交叉在身体前面。", "在运动的最高点暂停片刻，感受胸部肌肉的拉伸。", "反转动作，慢慢将手臂恢复到起始位置，始终保持胸部肌肉紧张。", "重复所需的重复次数。"], "secondary_muscles": ["deltoids", "triceps"], "instructions_zh_hant": ["將手柄連接到纜繩機的低滑輪上，并選擇合適的重量。", "站在機器中間，雙腳分開與肩同寬，膝蓋稍微彎曲。", "正手握住手柄，將手臂向兩側伸展，肘部保持輕微彎曲。", "保持控制，以掃過的動作緩慢地將手臂向前伸，交叉在身體前面。", "在運動的最高點暫停片刻，感受胸部肌肉的拉伸。", "反轉動作，慢慢將手臂恢復到起始位置，始終保持胸部肌肉緊張。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0180', 'exercise', 1, '{"id": "0180", "target": "upper back", "name_en": "cable low seated row", "name_zh": "绳索低位坐姿划船", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/0180-hvV79Si.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索低位坐姿劃船", "instructions_en": ["Sit on the machine with your feet flat on the footrests and your knees slightly bent.", "Grasp the handles with an overhand grip, palms facing down.", "Keep your back straight and lean slightly forward, maintaining a slight bend in your elbows.", "Pull the handles towards your body, squeezing your shoulder blades together.", "Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在机器上，双脚平放在脚踏板上，膝盖稍微弯曲。", "正手握住手柄，手掌朝下。", "保持背部挺直，稍微向前倾斜，肘部保持轻微弯曲。", "将手柄拉向身体，将肩胛骨挤压在一起。", "在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["坐在機器上，雙腳平放在腳踏板上，膝蓋稍微彎曲。", "正手握住手柄，手掌朝下。", "保持背部挺直，稍微向前傾斜，肘部保持輕微彎曲。", "將手柄拉向身體，將肩胛骨擠壓在一起。", "在動作的最高點暫停片刻，然后慢慢松開手柄回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0445', 'exercise', 1, '{"id": "0445", "target": "delts", "name_en": "ez barbell anti gravity press", "name_zh": "曲杆杠铃反重力推举", "body_part": "shoulders", "equipment": "ez barbell", "gif_asset": "assets/fitness/videos/0445-fprd84i.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "曲桿槓鈴反重力推舉", "instructions_en": ["Start by standing with your feet shoulder-width apart and holding the ez barbell with an overhand grip.", "Raise the barbell to shoulder height, keeping your elbows slightly bent and your palms facing forward.", "Press the barbell overhead, extending your arms fully.", "Lower the barbell back to shoulder height and repeat for the desired number of repetitions."], "instructions_zh": ["首先，双脚分开与肩同宽站立，并用正手握住杠铃。", "将杠铃举至肩膀高度，保持肘部稍微弯曲，手掌朝前。", "将杠铃推过头顶，充分伸展双臂。", "将杠铃降低回肩部高度，然后重复所需的重复次数。"], "secondary_muscles": ["triceps", "chest"], "instructions_zh_hant": ["首先，雙腳分開與肩同寬站立，并用正手握住杠鈴。", "將杠鈴舉至肩膀高度，保持肘部稍微彎曲，手掌朝前。", "將杠鈴推過頭頂，充分伸展雙臂。", "將杠鈴降低回肩部高度，然后重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1634', 'exercise', 1, '{"id": "1634", "target": "biceps", "name_en": "cable lying bicep curl", "name_zh": "绳索卧姿二头弯举", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/1634-otqIxU4.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索臥姿二頭彎舉", "instructions_en": ["Attach a straight bar to a low pulley cable machine.", "Lie face up on a flat bench with your feet flat on the ground.", "Grasp the bar with an underhand grip, hands shoulder-width apart.", "Extend your arms fully, keeping your elbows close to your sides.", "Keeping your upper arms stationary, exhale and curl the bar up towards your shoulders.", "Pause for a moment at the top, squeezing your biceps.", "Inhale and slowly lower the bar back to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将直杆连接到低滑轮电缆机上。", "面朝上躺在平坦的长凳上，双脚平放在地上。", "反手握住杠铃，双手与肩同宽。", "充分伸展双臂，保持肘部靠近身体两侧。", "保持上臂静止，呼气并将杠铃向上弯向肩膀。", "在顶部暂停片刻，挤压你的二头肌。", "吸气，慢慢将杠铃放回起始位置，充分伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["將直桿連接到低滑輪電纜機上。", "面朝上躺在平坦的長凳上，雙腳平放在地上。", "反手握住杠鈴，雙手與肩同寬。", "充分伸展雙臂，保持肘部靠近身體兩側。", "保持上臂靜止，呼氣并將杠鈴向上彎向肩膀。", "在頂部暫停片刻，擠壓你的二頭肌。", "吸氣，慢慢將杠鈴放回起始位置，充分伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0182', 'exercise', 1, '{"id": "0182", "target": "biceps", "name_en": "cable lying close-grip curl", "name_zh": "绳索卧姿窄握弯举", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/0182-61GrD55.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索臥姿窄握彎舉", "instructions_en": ["Attach a straight bar to a low pulley cable machine.", "Lie face up on a flat bench with your feet flat on the ground.", "Grasp the bar with an underhand grip, hands shoulder-width apart.", "Extend your arms fully, keeping your elbows close to your sides.", "Keeping your upper arms stationary, curl the bar towards your chest by contracting your biceps.", "Pause for a moment at the top, squeezing your biceps.", "Slowly lower the bar back to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将直杆连接到低滑轮电缆机上。", "面朝上躺在平坦的长凳上，双脚平放在地上。", "反手握住杠铃，双手与肩同宽。", "充分伸展双臂，保持肘部靠近身体两侧。", "保持上臂静止，通过收缩二头肌将杠铃卷向胸部。", "在顶部暂停片刻，挤压你的二头肌。", "慢慢地将杠铃放回起始位置，充分伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["將直桿連接到低滑輪電纜機上。", "面朝上躺在平坦的長凳上，雙腳平放在地上。", "反手握住杠鈴，雙手與肩同寬。", "充分伸展雙臂，保持肘部靠近身體兩側。", "保持上臂靜止，通過收縮二頭肌將杠鈴卷向胸部。", "在頂部暫停片刻，擠壓你的二頭肌。", "慢慢地將杠鈴放回起始位置，充分伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0185', 'exercise', 1, '{"id": "0185", "target": "pectorals", "name_en": "cable lying fly", "name_zh": "绳索卧姿飞鸟", "body_part": "chest", "equipment": "cable", "gif_asset": "assets/fitness/videos/0185-lJJ7Yq8.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索臥姿飛鳥", "instructions_en": ["Attach the handles to the cables and lie flat on a bench with your feet flat on the ground.", "Hold the handles with your palms facing each other and your arms extended straight above your chest.", "Keeping a slight bend in your elbows, lower your arms out to the sides in a wide arc until you feel a stretch in your chest.", "Pause for a moment, then squeeze your chest muscles to bring your arms back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将手柄连接到电缆上，平放在长凳上，双脚平放在地面上。", "手掌相对，握住手柄，双臂伸直至胸部上方。", "保持肘部轻微弯曲，将手臂以宽弧线向两侧放低，直到感觉到胸部有拉伸感。", "暂停片刻，然后挤压胸部肌肉，使手臂回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["deltoids", "triceps"], "instructions_zh_hant": ["將手柄連接到電纜上，平放在長凳上，雙腳平放在地面上。", "手掌相對，握住手柄，雙臂伸直至胸部上方。", "保持肘部輕微彎曲，將手臂以寬弧線向兩側放低，直到感覺到胸部有拉伸感。", "暫停片刻，然后擠壓胸部肌肉，使手臂回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0186', 'exercise', 1, '{"id": "0186", "target": "triceps", "name_en": "cable lying triceps extension v. 2", "name_zh": "绳索卧姿臂屈伸变式2", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/0186-uxJcFUU.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索臥姿臂屈伸變式2", "instructions_en": ["Attach a rope handle to a low pulley cable machine.", "Lie down on a flat bench facing up, with your head towards the cable machine.", "Grasp the rope handle with both hands, palms facing each other, and extend your arms straight up over your chest.", "Keeping your upper arms stationary, slowly lower the rope handle towards your forehead by bending your elbows.", "Pause for a moment at the bottom, then extend your arms back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将绳索手柄连接到低滑轮电缆机器上。", "面朝上躺在平坦的长凳上，头朝向电缆机。", "双手抓住绳柄，掌心相对，将双臂伸直至胸前。", "保持上臂静止，弯曲肘部，慢慢将绳索手柄放低至前额。", "在底部停顿片刻，然后将手臂伸回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["將繩索手柄連接到低滑輪電纜機器上。", "面朝上躺在平坦的長凳上，頭朝向電纜機。", "雙手抓住繩柄，掌心相對，將雙臂伸直至胸前。", "保持上臂靜止，彎曲肘部，慢慢將繩索手柄放低至前額。", "在底部停頓片刻，然后將手臂伸回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0188', 'exercise', 1, '{"id": "0188", "target": "pectorals", "name_en": "cable middle fly", "name_zh": "绳索中位飞鸟", "body_part": "chest", "equipment": "cable", "gif_asset": "assets/fitness/videos/0188-xLYSdtg.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索中位飛鳥", "instructions_en": ["Attach cables to both sides of a cable machine at chest height.", "Stand in the center of the machine with one foot slightly in front of the other.", "Grasp the handles with an overhand grip and extend your arms out to the sides.", "Keep a slight bend in your elbows and maintain a slight forward lean.", "Engage your chest muscles and bring your arms forward in a sweeping motion.", "Pause for a moment at the center, then slowly return your arms back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将电缆连接到电缆机两侧胸部高度处。", "站在机器的中央，一只脚稍微在另一只脚前面。", "正手握住手柄，并将手臂向两侧伸展。", "保持肘部轻微弯曲并保持轻微前倾。", "收紧胸部肌肉，并以扫过的动作将手臂向前伸。", "在中心停顿片刻，然后慢慢将手臂放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["deltoids", "triceps"], "instructions_zh_hant": ["將電纜連接到電纜機兩側胸部高度處。", "站在機器的中央，一只腳稍微在另一只腳前面。", "正手握住手柄，并將手臂向兩側伸展。", "保持肘部輕微彎曲并保持輕微前傾。", "收緊胸部肌肉，并以掃過的動作將手臂向前伸。", "在中心停頓片刻，然后慢慢將手臂放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0189', 'exercise', 1, '{"id": "0189", "target": "upper back", "name_en": "cable one arm bent over row", "name_zh": "绳索单臂俯身划船", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/0189-EIsE3u8.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索單臂俯身劃船", "instructions_en": ["Stand facing a cable machine with your feet shoulder-width apart.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Grasp the cable handle with one hand, palm facing inward, and extend your arm fully.", "Pull the cable handle towards your body, keeping your elbow close to your side, until your hand reaches your lower chest.", "Pause for a moment, then slowly extend your arm back to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["面向缆绳机站立，双脚与肩同宽。", "稍微弯曲膝盖，髋部向前转动，保持背部挺直。", "用一只手抓住电缆手柄，手掌朝内，然后完全伸展手臂。", "将电缆手柄拉向身体，保持肘部靠近身体一侧，直到手到达下胸部。", "暂停片刻，然后慢慢将手臂伸回起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["面向纜繩機站立，雙腳與肩同寬。", "稍微彎曲膝蓋，髖部向前轉動，保持背部挺直。", "用一只手抓住電纜手柄，手掌朝內，然后完全伸展手臂。", "將電纜手柄拉向身體，保持肘部靠近身體一側，直到手到達下胸部。", "暫停片刻，然后慢慢將手臂伸回起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0190', 'exercise', 1, '{"id": "0190", "target": "biceps", "name_en": "cable one arm curl", "name_zh": "绳索单臂弯举", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/0190-YTur5nR.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索單臂彎舉", "instructions_en": ["Stand facing the cable machine with your feet shoulder-width apart.", "Grasp the cable handle with an underhand grip, palm facing up.", "Keep your elbow close to your side and slowly curl your forearm up towards your shoulder.", "Pause for a moment at the top, then slowly lower your forearm back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["面对电缆机站立，双脚与肩同宽。", "反手握住电缆手柄，手掌朝上。", "保持肘部靠近身体两侧，慢慢地将前臂向上卷向肩膀。", "在顶部暂停片刻，然后慢慢将前臂放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["面對電纜機站立，雙腳與肩同寬。", "反手握住電纜手柄，手掌朝上。", "保持肘部靠近身體兩側，慢慢地將前臂向上卷向肩膀。", "在頂部暫停片刻，然后慢慢將前臂放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1262', 'exercise', 1, '{"id": "1262", "target": "pectorals", "name_en": "cable one arm decline chest fly", "name_zh": "绳索单臂下斜胸部飞鸟", "body_part": "chest", "equipment": "cable", "gif_asset": "assets/fitness/videos/1262-w4dLzSx.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索單臂下斜胸部飛鳥", "instructions_en": ["Attach a D-handle to a low pulley cable machine and set the bench to a decline angle.", "Lie down on the bench with your head towards the machine and grab the handle with your right hand.", "Extend your arm straight up above your chest, keeping a slight bend in your elbow.", "With a controlled motion, lower your arm out to the side until your hand is in line with your shoulder.", "Pause for a moment, then reverse the motion and bring your arm back to the starting position.", "Repeat for the desired number of repetitions, then switch to your left arm and repeat the exercise."], "instructions_zh": ["将 D 形手柄连接到低滑轮绳索机器上，并将长凳设置为下降角度。", "躺在长凳上，头朝向机器，用右手抓住手柄。", "将手臂伸直至胸部上方，保持肘部轻微弯曲。", "控制动作，将手臂向一侧放低，直到手与肩膀在一条直线上。", "暂停片刻，然后反转动作并将手臂恢复到起始位置。", "重复所需的重复次数，然后切换到左臂并重复练习。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["將 D 形手柄連接到低滑輪繩索機器上，并將長凳設置為下降角度。", "躺在長凳上，頭朝向機器，用右手抓住手柄。", "將手臂伸直至胸部上方，保持肘部輕微彎曲。", "控制動作，將手臂向一側放低，直到手與肩膀在一條直線上。", "暫停片刻，然后反轉動作并將手臂恢復到起始位置。", "重復所需的重復次數，然后切換到左臂并重復練習。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3665', 'exercise', 1, '{"id": "3665", "target": "abs", "name_en": "power point plank", "name_zh": "爆发点地平板支撑", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3665-hCjGsRQ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "爆發點地平板支撐", "instructions_en": ["Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.", "Engage your core and squeeze your glutes to maintain a stable position.", "Lower your body down onto your forearms, one arm at a time, maintaining a straight line from head to toe.", "Hold this position for the desired amount of time, keeping your core and glutes engaged.", "To return to the starting position, push through your forearms and lift your body back up into a high plank position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["从高平板支撑位置开始，双手直接放在肩膀下方，身体从头到脚成一条直线。", "启动你的核心并挤压你的臀肌以保持稳定的位置。", "将身体放低到前臂上，一次一只手臂，从头到脚保持一条直线。", "保持这个姿势所需的时间，保持核心肌群和臀肌的参与。", "要返回到起始位置，请推动前臂并将身体抬回到高位平板支撑位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps", "glutes"], "instructions_zh_hant": ["從高平板支撐位置開始，雙手直接放在肩膀下方，身體從頭到腳成一條直線。", "啟動你的核心并擠壓你的臀肌以保持穩定的位置。", "將身體放低到前臂上，一次一只手臂，從頭到腳保持一條直線。", "保持這個姿勢所需的時間，保持核心肌群和臀肌的參與。", "要返回到起始位置，請推動前臂并將身體抬回到高位平板支撐位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1263', 'exercise', 1, '{"id": "1263", "target": "pectorals", "name_en": "cable one arm fly on exercise ball", "name_zh": "健身球绳索单臂飞鸟", "body_part": "chest", "equipment": "cable", "gif_asset": "assets/fitness/videos/1263-hHy8tQG.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球繩索單臂飛鳥", "instructions_en": ["Sit on an exercise ball with your feet flat on the ground and your back straight.", "Hold a cable handle in one hand and extend your arm out to the side, parallel to the ground.", "Keep your elbow slightly bent and your palm facing forward.", "Slowly bring your arm across your body, squeezing your chest muscles.", "Pause for a moment at the end of the movement, then slowly return to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["坐在健身球上，双脚平放在地上，背部挺直。", "一只手握住电缆手柄，并将手臂向一侧伸出，与地面平行。", "保持肘部稍微弯曲，手掌朝前。", "慢慢地将手臂放在身体上，挤压胸部肌肉。", "动作结束时暂停片刻，然后慢慢回到起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["deltoids", "triceps"], "instructions_zh_hant": ["坐在健身球上，雙腳平放在地上，背部挺直。", "一只手握住電纜手柄，并將手臂向一側伸出，與地面平行。", "保持肘部稍微彎曲，手掌朝前。", "慢慢地將手臂放在身體上，擠壓胸部肌肉。", "動作結束時暫停片刻，然后慢慢回到起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1264', 'exercise', 1, '{"id": "1264", "target": "pectorals", "name_en": "cable one arm incline fly on exercise ball", "name_zh": "健身球绳索单臂上斜飞鸟", "body_part": "chest", "equipment": "cable", "gif_asset": "assets/fitness/videos/1264-P14Dz9D.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球繩索單臂上斜飛鳥", "instructions_en": ["Sit on an exercise ball with your feet flat on the ground and your back against an incline bench.", "Hold a cable handle in one hand with your arm extended and palm facing inward.", "Keeping a slight bend in your elbow, slowly lower your arm out to the side until your hand is in line with your shoulder.", "Pause for a moment, then squeeze your chest muscles to bring your arm back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["坐在健身球上，双脚平放在地面上，背部靠在倾斜的长凳上。", "一只手握住电缆手柄，手臂伸展，手掌朝内。", "保持肘部轻微弯曲，慢慢地将手臂向一侧放低，直到手与肩膀在一条直线上。", "暂停片刻，然后挤压胸部肌肉，使手臂回到起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["deltoids", "triceps"], "instructions_zh_hant": ["坐在健身球上，雙腳平放在地面上，背部靠在傾斜的長凳上。", "一只手握住電纜手柄，手臂伸展，手掌朝內。", "保持肘部輕微彎曲，慢慢地將手臂向一側放低，直到手與肩膀在一條直線上。", "暫停片刻，然后擠壓胸部肌肉，使手臂回到起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1265', 'exercise', 1, '{"id": "1265", "target": "pectorals", "name_en": "cable one arm incline press", "name_zh": "绳索单臂上斜推举", "body_part": "chest", "equipment": "cable", "gif_asset": "assets/fitness/videos/1265-GKEH6jj.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索單臂上斜推舉", "instructions_en": ["Adjust the cable machine to a low pulley position.", "Sit on an incline bench facing away from the cable machine.", "Grasp the handle with one hand and bring it up to shoulder height.", "Position your feet firmly on the ground and maintain a stable position.", "Press the handle forward and upward, extending your arm fully.", "Pause for a moment at the top, then slowly lower the handle back to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["将拉索机调整至低滑轮位置。", "坐在倾斜的长凳上，背对缆绳机。", "用一只手抓住手柄并将其举至肩膀高度。", "将双脚牢牢放在地面上并保持稳定的位置。", "向前和向上按下手柄，充分伸展手臂。", "在最高点暂停片刻，然后慢慢将手柄放回起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["deltoids", "triceps"], "instructions_zh_hant": ["將拉索機調整至低滑輪位置。", "坐在傾斜的長凳上，背對纜繩機。", "用一只手抓住手柄并將其舉至肩膀高度。", "將雙腳牢牢放在地面上并保持穩定的位置。", "向前和向上按下手柄，充分伸展手臂。", "在最高點暫停片刻，然后慢慢將手柄放回起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1266', 'exercise', 1, '{"id": "1266", "target": "pectorals", "name_en": "cable one arm incline press on exercise ball", "name_zh": "健身球绳索单臂上斜推举", "body_part": "chest", "equipment": "cable", "gif_asset": "assets/fitness/videos/1266-6t00BsF.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球繩索單臂上斜推舉", "instructions_en": ["Sit on an exercise ball with your feet flat on the ground and your back resting against an incline bench.", "Hold a cable handle in one hand and position your arm at a 90-degree angle with your elbow bent.", "Press the cable handle forward and upward, extending your arm fully.", "Pause for a moment at the top, then slowly lower the cable handle back to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."], "instructions_zh": ["坐在健身球上，双脚平放在地上，背部靠在倾斜的长凳上。", "一只手握住电缆手柄，将手臂呈 90 度角，肘部弯曲。", "向前和向上按下电缆手柄，完全伸展手臂。", "在顶部暂停片刻，然后慢慢将拉索手柄放回起始位置。", "重复所需的重复次数，然后换到另一只手臂。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["坐在健身球上，雙腳平放在地上，背部靠在傾斜的長凳上。", "一只手握住電纜手柄，將手臂呈 90 度角，肘部彎曲。", "向前和向上按下電纜手柄，完全伸展手臂。", "在頂部暫停片刻，然后慢慢將拉索手柄放回起始位置。", "重復所需的重復次數，然后換到另一只手臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0191', 'exercise', 1, '{"id": "0191", "target": "pectorals", "name_en": "cable one arm lateral bent-over", "name_zh": "绳索单臂侧屈", "body_part": "chest", "equipment": "cable", "gif_asset": "assets/fitness/videos/0191-dB07vDu.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索單臂側屈", "instructions_en": ["Stand with your feet shoulder-width apart, facing a cable machine.", "Grasp the handle with one hand and step back to create tension on the cable.", "Bend forward at the waist, keeping your back straight and your core engaged.", "Extend your arm out to the side, parallel to the ground, with a slight bend in your elbow.", "Slowly bring your arm back to the starting position, maintaining control throughout the movement.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["双脚分开与肩同宽站立，面向缆绳机。", "用一只手抓住手柄并向后退一步以在电缆上产生张力。", "腰部向前弯曲，保持背部挺直，核心肌群参与。", "将手臂向侧面伸展，与地面平行，肘部稍微弯曲。", "慢慢地将手臂放回起始位置，在整个运动过程中保持控制。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["deltoids", "trapezius"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，面向纜繩機。", "用一只手抓住手柄并向后退一步以在電纜上產生張力。", "腰部向前彎曲，保持背部挺直，核心肌群參與。", "將手臂向側面伸展，與地面平行，肘部稍微彎曲。", "慢慢地將手臂放回起始位置，在整個運動過程中保持控制。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0192', 'exercise', 1, '{"id": "0192", "target": "delts", "name_en": "cable one arm lateral raise", "name_zh": "绳索单臂侧平举", "body_part": "shoulders", "equipment": "cable", "gif_asset": "assets/fitness/videos/0192-wEulIzp.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索單臂側平舉", "instructions_en": ["Stand with your feet shoulder-width apart, facing the cable machine.", "Hold the cable handle with one hand, palm facing down, and stand far enough away from the machine so that there is tension on the cable.", "Keep your arm straight and slowly raise it out to the side until it is parallel to the ground.", "Pause for a moment at the top, then slowly lower your arm back down to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["双脚分开与肩同宽站立，面向绳索机。", "用一只手握住电缆手柄，手掌朝下，站得离机器足够远，以便电缆上有张力。", "保持手臂伸直，慢慢向一侧举起，直到与地面平行。", "在顶部暂停片刻，然后慢慢将手臂放回起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["traps", "triceps"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，面向繩索機。", "用一只手握住電纜手柄，手掌朝下，站得離機器足夠遠，以便電纜上有張力。", "保持手臂伸直，慢慢向一側舉起，直到與地面平行。", "在頂部暫停片刻，然后慢慢將手臂放回起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1633', 'exercise', 1, '{"id": "1633", "target": "biceps", "name_en": "cable one arm preacher curl", "name_zh": "绳索单臂牧师凳弯举", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/1633-eHBlPsa.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索單臂牧師凳彎舉", "instructions_en": ["Adjust the cable machine so that the preacher curl pad is at chest height.", "Stand facing the cable machine with your feet shoulder-width apart.", "Grasp the cable handle with an underhand grip and position your upper arm against the preacher curl pad.", "Keep your back straight and your core engaged.", "Slowly curl the cable handle towards your shoulder, keeping your upper arm against the pad.", "Pause for a moment at the top of the movement, squeezing your biceps.", "Slowly lower the cable handle back to the starting position.", "Repeat for the desired number of repetitions.", "Switch arms and repeat the exercise."], "instructions_zh": ["调整绳索机，使牧师弯举垫处于胸部高度。", "面对电缆机站立，双脚与肩同宽。", "用手握住电缆手柄，并将上臂靠在牧师弯举垫上。", "保持背部挺直，核心肌群参与。", "慢慢地将电缆手柄卷向肩膀，保持上臂靠在垫子上。", "在动作的最高点暂停片刻，挤压你的二头肌。", "慢慢地将电缆手柄放回起始位置。", "重复所需的重复次数。", "交换手臂并重复练习。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["調整繩索機，使牧師彎舉墊處于胸部高度。", "面對電纜機站立，雙腳與肩同寬。", "用手握住電纜手柄，并將上臂靠在牧師彎舉墊上。", "保持背部挺直，核心肌群參與。", "慢慢地將電纜手柄卷向肩膀，保持上臂靠在墊子上。", "在動作的最高點暫停片刻，擠壓你的二頭肌。", "慢慢地將電纜手柄放回起始位置。", "重復所需的重復次數。", "交換手臂并重復練習。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1267', 'exercise', 1, '{"id": "1267", "target": "pectorals", "name_en": "cable one arm press on exercise ball", "name_zh": "健身球绳索单臂推举", "body_part": "chest", "equipment": "cable", "gif_asset": "assets/fitness/videos/1267-MKIelrR.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球繩索單臂推舉", "instructions_en": ["Sit on an exercise ball with your feet flat on the ground and your back straight.", "Hold a cable handle in one hand and position your arm at chest height, elbow bent.", "Place your other hand on your hip for stability.", "Press the cable handle forward, extending your arm fully.", "Pause for a moment, then slowly return to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["坐在健身球上，双脚平放在地上，背部挺直。", "一只手握住电缆手柄，将手臂置于胸部高度，肘部弯曲。", "将另一只手放在臀部上以保持稳定。", "向前按电缆手柄，完全伸展手臂。", "暂停片刻，然后慢慢回到起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["坐在健身球上，雙腳平放在地上，背部挺直。", "一只手握住電纜手柄，將手臂置于胸部高度，肘部彎曲。", "將另一只手放在臀部上以保持穩定。", "向前按電纜手柄，完全伸展手臂。", "暫停片刻，然后慢慢回到起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0669', 'exercise', 1, '{"id": "0669", "target": "delts", "name_en": "rear deltoid stretch", "name_zh": "后三角肌拉伸", "body_part": "shoulders", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0669-xifhB5W.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "后三角肌拉伸", "instructions_en": ["Stand tall with your feet shoulder-width apart.", "Extend your right arm across your chest, placing your left hand on your right elbow.", "Gently pull your right arm towards your left shoulder, feeling a stretch in your right shoulder.", "Hold the stretch for 15-30 seconds, then release.", "Repeat on the other side."], "instructions_zh": ["站直，双脚分开与肩同宽。", "将右臂伸过胸部，将左手放在右肘上。", "轻轻地将右臂拉向左肩，感受右肩的拉伸。", "保持拉伸 15-30 秒，然后放松。", "在另一侧重复。"], "secondary_muscles": ["trapezius", "rhomboids"], "instructions_zh_hant": ["站直，雙腳分開與肩同寬。", "將右臂伸過胸部，將左手放在右肘上。", "輕輕地將右臂拉向左肩，感受右肩的拉伸。", "保持拉伸 15-30 秒，然后放松。", "在另一側重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3563', 'exercise', 1, '{"id": "3563", "target": "lats", "name_en": "cable one arm pulldown", "name_zh": "绳索单臂下拉", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/3563-U5INZY6.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索單臂下拉", "instructions_en": ["Attach a single handle to a high pulley cable machine.", "Stand facing the machine with your feet shoulder-width apart.", "Grasp the handle with an overhand grip and extend your arm fully.", "Keep your back straight and your core engaged.", "Pull the handle down towards your side while keeping your elbow close to your body.", "Pause for a moment at the bottom of the movement, squeezing your lat muscle.", "Slowly release the handle back to the starting position.", "Repeat for the desired number of repetitions.", "Switch sides and repeat the exercise with the other arm."], "instructions_zh": ["将单个手柄连接到高滑轮电缆机上。", "面向机器站立，双脚分开与肩同宽。", "正手握住手柄并完全伸展手臂。", "保持背部挺直，核心肌群参与。", "将手柄向一侧拉，同时保持肘部靠近身体。", "在动作底部暂停片刻，挤压背阔肌。", "慢慢松开手柄回到起始位置。", "重复所需的重复次数。", "换边并用另一只手臂重复练习。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["將單個手柄連接到高滑輪電纜機上。", "面向機器站立，雙腳分開與肩同寬。", "正手握住手柄并完全伸展手臂。", "保持背部挺直，核心肌群參與。", "將手柄向一側拉，同時保持肘部靠近身體。", "在動作底部暫停片刻，擠壓背闊肌。", "慢慢松開手柄回到起始位置。", "重復所需的重復次數。", "換邊并用另一只手臂重復練習。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1635', 'exercise', 1, '{"id": "1635", "target": "biceps", "name_en": "cable one arm reverse preacher curl", "name_zh": "绳索单臂反向牧师凳弯举", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/1635-ZXnjcOQ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索單臂反向牧師凳彎舉", "instructions_en": ["Adjust the cable machine so that the pulley is at the lowest position.", "Stand facing the cable machine with your feet shoulder-width apart.", "Grasp the cable handle with an underhand grip and position your upper arm against the preacher bench pad.", "Keep your back straight and your core engaged throughout the exercise.", "Slowly curl your forearm towards your bicep, keeping your upper arm stationary against the pad.", "Pause for a moment at the top of the movement, squeezing your bicep.", "Slowly lower the cable handle back to the starting position.", "Repeat for the desired number of repetitions.", "Switch arms and repeat the exercise."], "instructions_zh": ["调整拉索机，使滑轮处于最低位置。", "面对电缆机站立，双脚与肩同宽。", "用反手抓住电缆手柄，并将上臂靠在牧师凳垫上。", "在整个练习过程中保持背部挺直，核心肌群参与其中。", "慢慢地将前臂向二头肌方向卷曲，保持上臂固定在垫子上。", "在动作的最高点暂停片刻，挤压你的二头肌。", "慢慢地将电缆手柄放回起始位置。", "重复所需的重复次数。", "交换手臂并重复练习。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["調整拉索機，使滑輪處于最低位置。", "面對電纜機站立，雙腳與肩同寬。", "用反手抓住電纜手柄，并將上臂靠在牧師凳墊上。", "在整個練習過程中保持背部挺直，核心肌群參與其中。", "慢慢地將前臂向二頭肌方向卷曲，保持上臂固定在墊子上。", "在動作的最高點暫停片刻，擠壓你的二頭肌。", "慢慢地將電纜手柄放回起始位置。", "重復所需的重復次數。", "交換手臂并重復練習。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0193', 'exercise', 1, '{"id": "0193", "target": "upper back", "name_en": "cable one arm straight back high row (kneeling)", "name_zh": "绳索单臂背部挺直高位划船（跪姿）", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/0193-WrYPP2g.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索單臂背部挺直高位劃船（跪姿）", "instructions_en": ["Attach a handle to a cable machine at waist height.", "Kneel down facing the cable machine and grab the handle with one hand.", "Keep your back straight and your core engaged.", "Pull the handle towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top of the movement.", "Slowly release the handle back to the starting position.", "Repeat for the desired number of repetitions.", "Switch sides and repeat the exercise with the other arm."], "instructions_zh": ["将手柄连接到腰部高度的缆绳机上。", "面向电缆机跪下，用一只手抓住手柄。", "保持背部挺直，核心肌群参与。", "将手柄拉向胸部，将肩胛骨挤压在一起。", "在动作的最高点停顿片刻。", "慢慢松开手柄回到起始位置。", "重复所需的重复次数。", "换边并用另一只手臂重复练习。"], "secondary_muscles": ["biceps", "shoulders"], "instructions_zh_hant": ["將手柄連接到腰部高度的纜繩機上。", "面向電纜機跪下，用一只手抓住手柄。", "保持背部挺直，核心肌群參與。", "將手柄拉向胸部，將肩胛骨擠壓在一起。", "在動作的最高點停頓片刻。", "慢慢松開手柄回到起始位置。", "重復所需的重復次數。", "換邊并用另一只手臂重復練習。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1723', 'exercise', 1, '{"id": "1723", "target": "triceps", "name_en": "cable one arm tricep pushdown", "name_zh": "绳索单臂肱三头肌下压", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/1723-qRZ5S1N.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索單臂肱三頭肌下壓", "instructions_en": ["Stand facing a cable machine with a straight bar attachment at chest height.", "Grasp the bar with an overhand grip and step back to create tension in the cable.", "Position your feet shoulder-width apart and slightly bend your knees.", "Keep your back straight and core engaged throughout the exercise.", "Start with your arm fully extended and perpendicular to the floor.", "Keeping your upper arm stationary, exhale and push the bar down until your arm is fully extended.", "Pause for a moment, then inhale and slowly return to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["面向缆绳机站立，并在胸部高度处安装直杆附件。", "正手握住杠铃，然后后退以在绳索上产生张力。", "将双脚分开与肩同宽，并稍微弯曲膝盖。", "在整个练习过程中保持背部挺直并保持核心参与。", "首先，手臂完全伸展并垂直于地板。", "保持上臂静止，呼气并将杠铃向下推，直到手臂完全伸展。", "暂停片刻，然后吸气，慢慢回到起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["面向纜繩機站立，并在胸部高度處安裝直桿附件。", "正手握住杠鈴，然后后退以在繩索上產生張力。", "將雙腳分開與肩同寬，并稍微彎曲膝蓋。", "在整個練習過程中保持背部挺直并保持核心參與。", "首先，手臂完全伸展并垂直于地板。", "保持上臂靜止，呼氣并將杠鈴向下推，直到手臂完全伸展。", "暫停片刻，然后吸氣，慢慢回到起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1636', 'exercise', 1, '{"id": "1636", "target": "biceps", "name_en": "cable overhead curl", "name_zh": "绳索过顶弯举", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/1636-wDUqY2u.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索過頂彎舉", "instructions_en": ["Attach a straight bar to a high pulley cable machine.", "Stand facing the machine with your feet shoulder-width apart.", "Grasp the bar with an underhand grip, hands shoulder-width apart.", "Keep your elbows close to your sides and your upper arms stationary.", "Exhale and curl the bar down towards your forehead, keeping your upper arms stationary.", "Pause for a moment at the bottom of the movement, squeezing your biceps.", "Inhale and slowly return the bar to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将直杆连接到高滑轮电缆机上。", "面向机器站立，双脚分开与肩同宽。", "反手握住杠铃，双手与肩同宽。", "保持肘部靠近身体两侧，上臂保持静止。", "呼气并将杠铃向下卷向前额，保持上臂静止。", "在动作底部暂停片刻，挤压二头肌。", "吸气，慢慢地将杠铃返回到起始位置，充分伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["forearms", "shoulders"], "instructions_zh_hant": ["將直桿連接到高滑輪電纜機上。", "面向機器站立，雙腳分開與肩同寬。", "反手握住杠鈴，雙手與肩同寬。", "保持肘部靠近身體兩側，上臂保持靜止。", "呼氣并將杠鈴向下卷向前額，保持上臂靜止。", "在動作底部暫停片刻，擠壓二頭肌。", "吸氣，慢慢地將杠鈴返回到起始位置，充分伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1637', 'exercise', 1, '{"id": "1637", "target": "biceps", "name_en": "cable overhead curl on exercise ball", "name_zh": "健身球绳索过顶弯举", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/1637-ioTf098.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球繩索過頂彎舉", "instructions_en": ["Sit on an exercise ball and hold the cable handle with an underhand grip.", "Extend your arms fully overhead, keeping your elbows close to your ears.", "Slowly curl the cable down towards your forehead, keeping your upper arms stationary.", "Pause for a moment at the bottom of the movement, then slowly return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在健身球上，用反手握住电缆手柄。", "将手臂完全伸过头顶，保持肘部靠近耳朵。", "慢慢地将电缆朝前额卷曲，保持上臂静止。", "在动作底部暂停片刻，然后慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms", "shoulders"], "instructions_zh_hant": ["坐在健身球上，用反手握住電纜手柄。", "將手臂完全伸過頭頂，保持肘部靠近耳朵。", "慢慢地將電纜朝前額卷曲，保持上臂靜止。", "在動作底部暫停片刻，然后慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0194', 'exercise', 1, '{"id": "0194", "target": "triceps", "name_en": "cable overhead triceps extension (rope attachment)", "name_zh": "绳索过顶臂屈伸（绳索把手）", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/0194-2IxROQ1.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索過頂臂屈伸（繩索把手）", "instructions_en": ["Attach a rope to a cable machine at a high position.", "Stand facing away from the machine with your feet shoulder-width apart.", "Grasp the rope with both hands, palms facing each other, and bring your hands above your head.", "Keep your upper arms close to your head and your elbows pointing forward.", "Slowly lower the rope behind your head by bending your elbows.", "Pause for a moment, then extend your arms back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将绳索连接到高处的缆绳机上。", "背对机器站立，双脚与肩同宽。", "双手抓住绳子，掌心相对，将双手举过头顶。", "保持上臂靠近头部，肘部向前。", "弯曲肘部，慢慢将绳子降低到头后。", "暂停片刻，然后将手臂伸回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["將繩索連接到高處的纜繩機上。", "背對機器站立，雙腳與肩同寬。", "雙手抓住繩子，掌心相對，將雙手舉過頭頂。", "保持上臂靠近頭部，肘部向前。", "彎曲肘部，慢慢將繩子降低到頭后。", "暫停片刻，然后將手臂伸回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1319', 'exercise', 1, '{"id": "1319", "target": "upper back", "name_en": "cable palm rotational row", "name_zh": "绳索掌心旋转划船", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/1319-OmQ8w0p.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索掌心旋轉劃船", "instructions_en": ["Attach a handle to a cable machine at waist height.", "Stand facing the machine with your feet shoulder-width apart.", "Grasp the handle with an overhand grip, palms facing down.", "Step back to create tension on the cable, keeping your back straight and knees slightly bent.", "Pull the handle towards your body, rotating your palms to face upwards as you do so.", "Squeeze your shoulder blades together at the end of the movement.", "Slowly release the handle back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将手柄连接到腰部高度的缆绳机上。", "面向机器站立，双脚分开与肩同宽。", "正手握住手柄，手掌朝下。", "向后退一步，在绳索上产生张力，保持背部挺直，膝盖稍微弯曲。", "将手柄拉向身体，同时将手掌旋转至向上。", "在动作结束时将肩胛骨挤压在一起。", "慢慢松开手柄回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["將手柄連接到腰部高度的纜繩機上。", "面向機器站立，雙腳分開與肩同寬。", "正手握住手柄，手掌朝下。", "向后退一步，在繩索上產生張力，保持背部挺直，膝蓋稍微彎曲。", "將手柄拉向身體，同時將手掌旋轉至向上。", "在動作結束時將肩胛骨擠壓在一起。", "慢慢松開手柄回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0195', 'exercise', 1, '{"id": "0195", "target": "biceps", "name_en": "cable preacher curl", "name_zh": "绳索牧师凳弯举", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/0195-P2lNrGL.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索牧師凳彎舉", "instructions_en": ["Adjust the cable machine so that the preacher curl pad is at chest height.", "Sit on the preacher curl bench and place your upper arms on the pad, gripping the cable attachment with an underhand grip.", "Keep your back straight and your elbows tucked in at your sides.", "Slowly curl the cable attachment up towards your shoulders, squeezing your biceps at the top of the movement.", "Pause for a moment, then slowly lower the cable attachment back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整绳索机，使牧师弯举垫处于胸部高度。", "坐在牧师弯举凳上，将上臂放在垫子上，用反手抓住电缆附件。", "保持背部挺直，肘部放在身体两侧。", "慢慢地将电缆附件向肩膀方向卷曲，在动作的最高点挤压二头肌。", "暂停片刻，然后慢慢将电缆附件放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["調整繩索機，使牧師彎舉墊處于胸部高度。", "坐在牧師彎舉凳上，將上臂放在墊子上，用反手抓住電纜附件。", "保持背部挺直，肘部放在身體兩側。", "慢慢地將電纜附件向肩膀方向卷曲，在動作的最高點擠壓二頭肌。", "暫停片刻，然后慢慢將電纜附件放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1268', 'exercise', 1, '{"id": "1268", "target": "pectorals", "name_en": "cable press on exercise ball", "name_zh": "健身球绳索推举", "body_part": "chest", "equipment": "cable", "gif_asset": "assets/fitness/videos/1268-vAwm6rK.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球繩索推舉", "instructions_en": ["Sit on an exercise ball with your feet flat on the ground and your knees at a 90-degree angle.", "Hold the cable handles at chest height with your palms facing down and your elbows bent.", "Engage your core and press the cable handles forward until your arms are fully extended.", "Pause for a moment, then slowly release the tension and bring the cable handles back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在健身球上，双脚平放在地上，膝盖呈 90 度角。", "将电缆手柄保持在胸部高度，手掌朝下，肘部弯曲。", "收紧核心并向前按压缆索手柄，直到手臂完全伸展。", "暂停片刻，然后慢慢释放张力，并将电缆手柄拉回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["坐在健身球上，雙腳平放在地上，膝蓋呈 90 度角。", "將電纜手柄保持在胸部高度，手掌朝下，肘部彎曲。", "收緊核心并向前按壓纜索手柄，直到手臂完全伸展。", "暫停片刻，然后慢慢釋放張力，并將電纜手柄拉回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0196', 'exercise', 1, '{"id": "0196", "target": "glutes", "name_en": "cable pull through (with rope)", "name_zh": "绳索胯下拉（配合绳索）", "body_part": "upper legs", "equipment": "cable", "gif_asset": "assets/fitness/videos/0196-OM46QHm.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索胯下拉（配合繩索）", "instructions_en": ["Stand facing away from the cable machine with your feet shoulder-width apart.", "Grab the rope attachment with both hands and step forward, creating tension in the cable.", "Bend at the hips and lower your upper body until it is parallel to the ground, keeping your back straight.", "Engage your glutes and hamstrings to pull your body back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["背对缆绳机站立，双脚与肩同宽。", "双手抓住绳索附件并向前迈一步，在绳索中产生张力。", "弯曲臀部并降低上身直至与地面平行，保持背部挺直。", "启动臀肌和腿筋，将身体拉回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "lower back"], "instructions_zh_hant": ["背對纜繩機站立，雙腳與肩同寬。", "雙手抓住繩索附件并向前邁一步，在繩索中產生張力。", "彎曲臀部并降低上身直至與地面平行，保持背部挺直。", "啟動臀肌和腿筋，將身體拉回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0197', 'exercise', 1, '{"id": "0197", "target": "lats", "name_en": "cable pulldown (pro lat bar)", "name_zh": "绳索下拉（宽握背阔肌杆）", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/0197-qdRxqCj.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索下拉（寬握背闊肌桿）", "instructions_en": ["Adjust the seat height so that your thighs are parallel to the ground and your feet are flat on the floor.", "Grasp the lat bar with an overhand grip, slightly wider than shoulder-width apart.", "Sit down and lean back slightly, keeping your chest up and your back straight.", "Pull the bar down towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度，使大腿与地面平行，双脚平放在地板上。", "正手握住背阔肌杠铃，握距略宽于肩宽。", "坐下来，稍微向后倾斜，保持挺胸、背部挺直。", "将杠铃向下拉向胸部，将肩胛骨挤压在一起。", "在动作底部暂停片刻，然后慢慢将杠铃释放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["調整座椅高度，使大腿與地面平行，雙腳平放在地板上。", "正手握住背闊肌杠鈴，握距略寬于肩寬。", "坐下來，稍微向后傾斜，保持挺胸、背部挺直。", "將杠鈴向下拉向胸部，將肩胛骨擠壓在一起。", "在動作底部暫停片刻，然后慢慢將杠鈴釋放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1638', 'exercise', 1, '{"id": "1638", "target": "biceps", "name_en": "cable pulldown bicep curl", "name_zh": "绳索下拉二头弯举", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/1638-QTXKWPh.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索下拉二頭彎舉", "instructions_en": ["Attach a straight bar to the cable machine at the highest setting.", "Stand facing the machine with your feet shoulder-width apart.", "Grasp the bar with an underhand grip, hands shoulder-width apart.", "Keep your elbows close to your sides and your upper arms stationary.", "Exhale and slowly curl the bar down towards your thighs, keeping your wrists straight.", "Pause for a moment at the bottom of the movement, squeezing your biceps.", "Inhale and slowly return the bar to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["在最高设置下将直杆连接到电缆机上。", "面向机器站立，双脚分开与肩同宽。", "反手握住杠铃，双手与肩同宽。", "保持肘部靠近身体两侧，上臂保持静止。", "呼气，慢慢将杠铃向大腿方向卷曲，保持手腕伸直。", "在动作底部暂停片刻，挤压二头肌。", "吸气，慢慢地将杠铃返回到起始位置，充分伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["在最高設置下將直桿連接到電纜機上。", "面向機器站立，雙腳分開與肩同寬。", "反手握住杠鈴，雙手與肩同寬。", "保持肘部靠近身體兩側，上臂保持靜止。", "呼氣，慢慢將杠鈴向大腿方向卷曲，保持手腕伸直。", "在動作底部暫停片刻，擠壓二頭肌。", "吸氣，慢慢地將杠鈴返回到起始位置，充分伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0199', 'exercise', 1, '{"id": "0199", "target": "lats", "name_en": "cable pushdown (straight arm) v. 2", "name_zh": "绳索下压（直臂）变式2", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/0199-PskORrA.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索下壓（直臂）變式2", "instructions_en": ["Attach a straight bar to a high pulley cable machine.", "Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.", "Grasp the bar with an overhand grip, keeping your arms straight and your palms facing down.", "Engage your core and keep your back straight as you exhale and push the bar down towards your thighs.", "Pause for a moment at the bottom, then slowly return the bar to the starting position while inhaling.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将直杆连接到高滑轮电缆机上。", "面向机器站立，双脚分开与肩同宽，膝盖稍微弯曲。", "正手握住杠铃，保持手臂伸直，手掌朝下。", "呼气时，收紧核心并保持背部挺直，并将杠铃向下推向大腿。", "在底部暂停片刻，然后一边吸气，一边慢慢地将杠铃返回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["將直桿連接到高滑輪電纜機上。", "面向機器站立，雙腳分開與肩同寬，膝蓋稍微彎曲。", "正手握住杠鈴，保持手臂伸直，手掌朝下。", "呼氣時，收緊核心并保持背部挺直，并將杠鈴向下推向大腿。", "在底部暫停片刻，然后一邊吸氣，一邊慢慢地將杠鈴返回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0202', 'exercise', 1, '{"id": "0202", "target": "delts", "name_en": "cable rear delt row (stirrups)", "name_zh": "绳索三角肌后束划船（环形握把）", "body_part": "shoulders", "equipment": "cable", "gif_asset": "assets/fitness/videos/0202-yUdIGNs.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索三角肌后束劃船（環形握把）", "instructions_en": ["Attach a stirrup handle to a low cable pulley and stand facing the machine.", "Grasp the handle with your left hand and take a step back with your right foot, positioning your body at a slight angle.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.", "With your left arm extended and your palm facing down, pull the handle towards your chest by retracting your shoulder blade.", "Pause for a moment at the top of the movement, squeezing your shoulder blade.", "Slowly release the handle back to the starting position and repeat for the desired number of repetitions.", "Switch sides and repeat the exercise with your right arm."], "instructions_zh": ["将马镫手柄连接到低电缆滑轮上，面向机器站立。", "左手抓住手柄，右脚后退一步，身体保持一个轻微的角度。", "稍微弯曲膝盖，髋部向前转动，保持背部挺直，核心肌群参与。", "左臂伸展，手掌朝下，通过缩回肩胛骨将手柄拉向胸部。", "在动作的最高点暂停片刻，挤压肩胛骨。", "慢慢地将手柄释放回起始位置，然后重复所需的重复次数。", "换边并用右臂重复练习。"], "secondary_muscles": ["trapezius", "rhomboids", "biceps"], "instructions_zh_hant": ["將馬鐙手柄連接到低電纜滑輪上，面向機器站立。", "左手抓住手柄，右腳后退一步，身體保持一個輕微的角度。", "稍微彎曲膝蓋，髖部向前轉動，保持背部挺直，核心肌群參與。", "左臂伸展，手掌朝下，通過縮回肩胛骨將手柄拉向胸部。", "在動作的最高點暫停片刻，擠壓肩胛骨。", "慢慢地將手柄釋放回起始位置，然后重復所需的重復次數。", "換邊并用右臂重復練習。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0203', 'exercise', 1, '{"id": "0203", "target": "delts", "name_en": "cable rear delt row (with rope)", "name_zh": "绳索三角肌后束划船（配合绳索）", "body_part": "shoulders", "equipment": "cable", "gif_asset": "assets/fitness/videos/0203-wqNPGCg.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索三角肌后束劃船（配合繩索）", "instructions_en": ["Attach a rope handle to a low pulley cable machine.", "Stand facing the machine with your feet shoulder-width apart.", "Grasp the rope handle with an overhand grip, palms facing each other.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Keep your elbows slightly bent and pull the rope towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top of the movement, then slowly release the tension and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将绳索手柄连接到低滑轮电缆机器上。", "面向机器站立，双脚分开与肩同宽。", "正手握住绳索手柄，手掌相对。", "稍微弯曲膝盖，髋部向前转动，保持背部挺直。", "保持肘部稍微弯曲，将绳子拉向胸部，将肩胛骨挤压在一起。", "在动作的最高点停顿片刻，然后慢慢释放张力，回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["trapezius", "rhomboids", "biceps"], "instructions_zh_hant": ["將繩索手柄連接到低滑輪電纜機器上。", "面向機器站立，雙腳分開與肩同寬。", "正手握住繩索手柄，手掌相對。", "稍微彎曲膝蓋，髖部向前轉動，保持背部挺直。", "保持肘部稍微彎曲，將繩子拉向胸部，將肩胛骨擠壓在一起。", "在動作的最高點停頓片刻，然后慢慢釋放張力，回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0204', 'exercise', 1, '{"id": "0204", "target": "triceps", "name_en": "cable rear drive", "name_zh": "绳索后蹬伸", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/0204-c3QQLPi.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索后蹬伸", "instructions_en": ["Attach a handle to a low pulley cable machine and stand facing away from the machine.", "Grasp the handle with an overhand grip and extend your arms straight out in front of you.", "Keeping your elbows stationary, pull the handle back towards your body, squeezing your triceps at the end of the movement.", "Slowly return the handle to the starting position and repeat for the desired number of repetitions."], "instructions_zh": ["将手柄连接到低滑轮电缆机器上，并背对机器站立。", "正手握住手柄，并将双臂伸直至身前。", "保持肘部不动，将手柄拉回身体，在动作结束时挤压三头肌。", "慢慢地将手柄返回到起始位置，然后重复所需的重复次数。"], "secondary_muscles": ["shoulders", "back"], "instructions_zh_hant": ["將手柄連接到低滑輪電纜機器上，并背對機器站立。", "正手握住手柄，并將雙臂伸直至身前。", "保持肘部不動，將手柄拉回身體，在動作結束時擠壓三頭肌。", "慢慢地將手柄返回到起始位置，然后重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0205', 'exercise', 1, '{"id": "0205", "target": "lats", "name_en": "cable rear pulldown", "name_zh": "绳索后下拉", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/0205-SpsOSXk.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索后下拉", "instructions_en": ["Adjust the cable machine so that the pulley is at the highest position.", "Sit facing the machine with your feet flat on the ground and your knees slightly bent.", "Grasp the cable attachment with an overhand grip, hands slightly wider than shoulder-width apart.", "Lean back slightly, keeping your back straight and your chest up.", "Pull the cable attachment down towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the bottom of the movement, then slowly release the cable back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整拉索机，使滑轮处于最高位置。", "面向机器坐着，双脚平放在地面上，膝盖稍微弯曲。", "正手握住电缆附件，双手之间的距离略大于肩宽。", "稍微向后倾斜，保持背部挺直，挺胸。", "将电缆附件向下拉向胸部，将肩胛骨挤压在一起。", "在动作底部停顿片刻，然后慢慢松开绳索回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "rhomboids", "rear deltoids"], "instructions_zh_hant": ["調整拉索機，使滑輪處于最高位置。", "面向機器坐著，雙腳平放在地面上，膝蓋稍微彎曲。", "正手握住電纜附件，雙手之間的距離略大于肩寬。", "稍微向后傾斜，保持背部挺直，挺胸。", "將電纜附件向下拉向胸部，將肩胛骨擠壓在一起。", "在動作底部停頓片刻，然后慢慢松開繩索回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0873', 'exercise', 1, '{"id": "0873", "target": "abs", "name_en": "cable reverse crunch", "name_zh": "绳索反向卷腹", "body_part": "waist", "equipment": "cable", "gif_asset": "assets/fitness/videos/0873-RqOtqD7.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索反向卷腹", "instructions_en": ["Attach a cable to a low pulley and lie down facing up on a mat.", "Hold the cable with both hands and extend your arms straight up towards the ceiling.", "Bend your knees and lift your legs up, bringing your thighs towards your chest.", "While keeping your upper body stable, curl your pelvis up towards your chest, lifting your hips off the mat.", "Pause for a moment at the top, then slowly lower your hips back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将电缆连接到低滑轮上，然后面朝上躺在垫子上。", "用双手握住电缆，并将双臂伸向天花板。", "弯曲膝盖并抬起双腿，使大腿靠近胸部。", "在保持上半身稳定的同时，将骨盆向胸部弯曲，将臀部抬离垫子。", "在顶部暂停片刻，然后慢慢将臀部放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["將電纜連接到低滑輪上，然后面朝上躺在墊子上。", "用雙手握住電纜，并將雙臂伸向天花板。", "彎曲膝蓋并抬起雙腿，使大腿靠近胸部。", "在保持上半身穩定的同時，將骨盆向胸部彎曲，將臀部抬離墊子。", "在頂部暫停片刻，然后慢慢將臀部放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0206', 'exercise', 1, '{"id": "0206", "target": "biceps", "name_en": "cable reverse curl", "name_zh": "绳索反向弯举", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/0206-eOG0r6v.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索反向彎舉", "instructions_en": ["Attach a straight bar to a low pulley cable machine.", "Stand facing the machine with your feet shoulder-width apart and your knees slightly bent.", "Grasp the bar with an underhand grip, hands shoulder-width apart.", "Keep your elbows close to your sides and your upper arms stationary throughout the exercise.", "Exhale and curl the bar up towards your shoulders, contracting your biceps.", "Pause for a moment at the top, squeezing your biceps.", "Inhale and slowly lower the bar back to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将直杆连接到低滑轮电缆机上。", "面向机器站立，双脚分开与肩同宽，膝盖稍微弯曲。", "反手握住杠铃，双手与肩同宽。", "在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。", "呼气并将杠铃向上卷向肩膀，收缩二头肌。", "在顶部暂停片刻，挤压你的二头肌。", "吸气，慢慢将杠铃放回起始位置，充分伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["將直桿連接到低滑輪電纜機上。", "面向機器站立，雙腳分開與肩同寬，膝蓋稍微彎曲。", "反手握住杠鈴，雙手與肩同寬。", "在整個練習過程中，保持肘部靠近身體兩側，上臂保持靜止。", "呼氣并將杠鈴向上卷向肩膀，收縮二頭肌。", "在頂部暫停片刻，擠壓你的二頭肌。", "吸氣，慢慢將杠鈴放回起始位置，充分伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2406', 'exercise', 1, '{"id": "2406", "target": "triceps", "name_en": "cable reverse grip triceps pushdown (sz-bar) (with arm blaster)", "name_zh": "绳索反握肱三头肌下压（曲杆）（配合弯举护板）", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/2406-ThKP69G.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索反握肱三頭肌下壓（曲桿）（配合彎舉護板）", "instructions_en": ["Attach a straight bar to the cable machine at the highest setting.", "Stand facing the cable machine with your feet shoulder-width apart.", "Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.", "Keep your elbows close to your sides and your upper arms stationary throughout the exercise.", "Engage your triceps and slowly push the bar down until your arms are fully extended.", "Pause for a moment at the bottom, then slowly return the bar to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["在最高设置下将直杆连接到电缆机上。", "面对电缆机站立，双脚与肩同宽。", "反手握住杠铃，手掌朝上，双手与肩同宽。", "在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。", "启动你的三头肌，慢慢地向下推杠铃，直到你的手臂完全伸展。", "在底部暂停片刻，然后慢慢地将杠铃返回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["在最高設置下將直桿連接到電纜機上。", "面對電纜機站立，雙腳與肩同寬。", "反手握住杠鈴，手掌朝上，雙手與肩同寬。", "在整個練習過程中，保持肘部靠近身體兩側，上臂保持靜止。", "啟動你的三頭肌，慢慢地向下推杠鈴，直到你的手臂完全伸展。", "在底部暫停片刻，然后慢慢地將杠鈴返回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1413', 'exercise', 1, '{"id": "1413", "target": "biceps", "name_en": "cable reverse one arm curl", "name_zh": "绳索反向单臂弯举", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/1413-gVlnLIJ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索反向單臂彎舉", "instructions_en": ["Stand facing a cable machine with your feet shoulder-width apart.", "Grasp the cable handle with an underhand grip, palm facing down.", "Keep your elbow close to your side and slowly curl your forearm up towards your shoulder.", "Pause for a moment at the top, then slowly lower your forearm back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["面向缆绳机站立，双脚与肩同宽。", "反手握住电缆手柄，手掌朝下。", "保持肘部靠近身体两侧，慢慢地将前臂向上卷向肩膀。", "在顶部暂停片刻，然后慢慢将前臂放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["面向纜繩機站立，雙腳與肩同寬。", "反手握住電纜手柄，手掌朝下。", "保持肘部靠近身體兩側，慢慢地將前臂向上卷向肩膀。", "在頂部暫停片刻，然后慢慢將前臂放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0209', 'exercise', 1, '{"id": "0209", "target": "biceps", "name_en": "cable reverse preacher curl", "name_zh": "绳索反向牧师凳弯举", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/0209-IwX5NqK.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索反向牧師凳彎舉", "instructions_en": ["Adjust the cable machine so that the preacher curl pad is at chest height.", "Sit on the preacher curl bench and place your upper arms on the pad, with your palms facing down and your elbows fully extended.", "Grab the cable handles with an underhand grip, shoulder-width apart.", "Keeping your upper arms stationary, exhale and curl the handles towards your shoulders, contracting your biceps.", "Pause for a moment at the top of the movement, squeezing your biceps.", "Inhale and slowly lower the handles back to the starting position, fully extending your elbows.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整绳索机，使牧师弯举垫处于胸部高度。", "坐在牧师弯举凳上，将上臂放在垫子上，手掌朝下，肘部完全伸展。", "反手抓住电缆手柄，距离与肩同宽。", "保持上臂静止，呼气并将手柄向肩膀卷曲，收缩二头肌。", "在动作的最高点暂停片刻，挤压你的二头肌。", "吸气，慢慢将手柄放回起始位置，充分伸展肘部。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["調整繩索機，使牧師彎舉墊處于胸部高度。", "坐在牧師彎舉凳上，將上臂放在墊子上，手掌朝下，肘部完全伸展。", "反手抓住電纜手柄，距離與肩同寬。", "保持上臂靜止，呼氣并將手柄向肩膀卷曲，收縮二頭肌。", "在動作的最高點暫停片刻，擠壓你的二頭肌。", "吸氣，慢慢將手柄放回起始位置，充分伸展肘部。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0210', 'exercise', 1, '{"id": "0210", "target": "forearms", "name_en": "cable reverse wrist curl", "name_zh": "绳索反握腕弯举", "body_part": "lower arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/0210-eYmsEPR.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索反握腕彎舉", "instructions_en": ["Attach a cable to a low pulley and sit on a bench facing the cable machine.", "Grasp the cable handle with an overhand grip, palms facing down.", "Rest your forearms on your thighs, with your wrists hanging off the edge.", "Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.", "Pause for a moment at the top, then inhale and slowly lower your wrists back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将电缆连接到低滑轮上，然后坐在面向电缆机的长凳上。", "正手握住电缆手柄，手掌朝下。", "将前臂放在大腿上，手腕悬在边缘上。", "保持前臂静止，呼气并尽可能向上弯曲手腕。", "在顶部暂停片刻，然后吸气并慢慢将手腕放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms", "wrists"], "instructions_zh_hant": ["將電纜連接到低滑輪上，然后坐在面向電纜機的長凳上。", "正手握住電纜手柄，手掌朝下。", "將前臂放在大腿上，手腕懸在邊緣上。", "保持前臂靜止，呼氣并盡可能向上彎曲手腕。", "在頂部暫停片刻，然后吸氣并慢慢將手腕放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1322', 'exercise', 1, '{"id": "1322", "target": "upper back", "name_en": "cable rope extension incline bench row", "name_zh": "绳索绳头伸展上斜凳上划船", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/1322-MgKwAAo.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索繩頭伸展上斜凳上劃船", "instructions_en": ["Set up an incline bench at a 45-degree angle and attach a cable machine to the low pulley.", "Attach a rope handle to the cable machine and sit on the incline bench facing the machine.", "Grab the rope handle with an overhand grip and lean forward, keeping your back straight.", "Extend your arms fully, pulling the rope towards your upper chest while keeping your elbows close to your body.", "Squeeze your shoulder blades together at the end of the movement.", "Slowly release the tension and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["以 45 度角设置上斜凳，并将绳索机连接到低滑轮上。", "将绳索手柄连接到缆绳机上，然后坐在面向机器的倾斜长凳上。", "正手抓住绳索把手，身体前倾，保持背部挺直。", "充分伸展双臂，将绳子拉向上胸部，同时保持肘部靠近身体。", "在动作结束时将肩胛骨挤压在一起。", "慢慢释放张力并回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "shoulders"], "instructions_zh_hant": ["以 45 度角設置上斜凳，并將繩索機連接到低滑輪上。", "將繩索手柄連接到纜繩機上，然后坐在面向機器的傾斜長凳上。", "正手抓住繩索把手，身體前傾，保持背部挺直。", "充分伸展雙臂，將繩子拉向上胸部，同時保持肘部靠近身體。", "在動作結束時將肩胛骨擠壓在一起。", "慢慢釋放張力并回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0207', 'exercise', 1, '{"id": "0207", "target": "triceps", "name_en": "cable reverse-grip pushdown", "name_zh": "绳索反握下压", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/0207-VjYliFZ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索反握下壓", "instructions_en": ["Attach a straight bar to a high pulley cable machine.", "Stand facing the machine with your feet shoulder-width apart.", "Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.", "Keep your elbows close to your sides and your upper arms stationary throughout the exercise.", "Using your triceps, push the bar down until your arms are fully extended and your triceps are contracted.", "Pause for a moment, then slowly return the bar to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将直杆连接到高滑轮电缆机上。", "面向机器站立，双脚分开与肩同宽。", "反手握住杠铃，手掌朝上，双手与肩同宽。", "在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。", "使用三头肌，将杠铃向下推，直到手臂完全伸展并且三头肌收缩。", "暂停片刻，然后慢慢地将杠铃返回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["將直桿連接到高滑輪電纜機上。", "面向機器站立，雙腳分開與肩同寬。", "反手握住杠鈴，手掌朝上，雙手與肩同寬。", "在整個練習過程中，保持肘部靠近身體兩側，上臂保持靜止。", "使用三頭肌，將杠鈴向下推，直到手臂完全伸展并且三頭肌收縮。", "暫停片刻，然后慢慢地將杠鈴返回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0208', 'exercise', 1, '{"id": "0208", "target": "upper back", "name_en": "cable reverse-grip straight back seated high row", "name_zh": "绳索反握背部挺直坐姿高位划船", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/0208-PNtsX17.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索反握背部挺直坐姿高位劃船", "instructions_en": ["Sit on the seat facing the cable machine with your feet flat on the floor.", "Grasp the cable attachment with an underhand grip, palms facing up, and your hands shoulder-width apart.", "Keep your back straight and lean slightly forward from your hips.", "Pull the cable towards your torso by retracting your shoulder blades and squeezing your back muscles.", "Pause for a moment at the peak of the contraction, then slowly release the cable back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在面向电缆机的座位上，双脚平放在地板上。", "用手握住电缆附件，手掌朝上，双手与肩同宽。", "保持背部挺直，并从臀部稍微向前倾斜。", "通过缩回肩胛骨并挤压背部肌肉，将电缆拉向躯干。", "在收缩的峰值处暂停片刻，然后慢慢地将电缆释放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["坐在面向電纜機的座位上，雙腳平放在地板上。", "用手握住電纜附件，手掌朝上，雙手與肩同寬。", "保持背部挺直，并從臀部稍微向前傾斜。", "通過縮回肩胛骨并擠壓背部肌肉，將電纜拉向軀幹。", "在收縮的峰值處暫停片刻，然后慢慢地將電纜釋放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1320', 'exercise', 1, '{"id": "1320", "target": "upper back", "name_en": "cable rope crossover seated row", "name_zh": "绳索绳头交叉坐姿划船", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/1320-UFGF6gk.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索繩頭交叉坐姿劃船", "instructions_en": ["Sit on the rowing machine with your feet flat on the footrests and your knees slightly bent.", "Grasp the cable ropes with an overhand grip, palms facing each other.", "Lean back slightly, keeping your back straight and your core engaged.", "Pull the cable ropes towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在划船机上，双脚平放在脚踏板上，膝盖稍微弯曲。", "正手握住缆绳，手掌相对。", "稍微向后倾斜，保持背部挺直，核心肌群参与。", "将缆绳拉向胸部，将肩胛骨挤压在一起。", "在动作的最高点停顿片刻，然后慢慢释放张力，回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["坐在劃船機上，雙腳平放在腳踏板上，膝蓋稍微彎曲。", "正手握住纜繩，手掌相對。", "稍微向后傾斜，保持背部挺直，核心肌群參與。", "將纜繩拉向胸部，將肩胛骨擠壓在一起。", "在動作的最高點停頓片刻，然后慢慢釋放張力，回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1321', 'exercise', 1, '{"id": "1321", "target": "upper back", "name_en": "cable rope elevated seated row", "name_zh": "绳索绳头垫高坐姿划船", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/1321-c8oybX6.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索繩頭墊高坐姿劃船", "instructions_en": ["Sit on the elevated seat facing the cable machine.", "Grab the cable rope handles with an overhand grip, palms facing each other.", "Keep your back straight and lean slightly back, maintaining a slight bend in your knees.", "Pull the cable towards your body by retracting your shoulder blades and squeezing your back muscles.", "Pause for a moment at the fully contracted position.", "Slowly release the tension and extend your arms back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在面向电缆机的高架座椅上。", "正手握住缆绳手柄，手掌相对。", "保持背部挺直并稍微向后倾斜，保持膝盖轻微弯曲。", "通过缩回肩胛骨并挤压背部肌肉，将电缆拉向您的身体。", "在完全收缩的位置暂停片刻。", "慢慢释放压力并将手臂伸回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["坐在面向電纜機的高架座椅上。", "正手握住纜繩手柄，手掌相對。", "保持背部挺直并稍微向后傾斜，保持膝蓋輕微彎曲。", "通過縮回肩胛骨并擠壓背部肌肉，將電纜拉向您的身體。", "在完全收縮的位置暫停片刻。", "慢慢釋放壓力并將手臂伸回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1639', 'exercise', 1, '{"id": "1639", "target": "biceps", "name_en": "cable rope hammer preacher curl", "name_zh": "绳索绳头锤式牧师凳弯举", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/1639-PcPe0P5.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索繩頭錘式牧師凳彎舉", "instructions_en": ["Attach a rope attachment to a low pulley cable machine.", "Stand facing the machine with your feet shoulder-width apart.", "Grasp the rope with a neutral grip (palms facing each other).", "Position your upper arms against the preacher bench pad, keeping your elbows slightly bent.", "Keeping your upper arms stationary, exhale and curl the rope towards your shoulders by contracting your biceps.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly lower the rope back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将绳索附件连接到低滑轮缆绳机上。", "面向机器站立，双脚分开与肩同宽。", "以中立握法（手掌相对）抓住绳子。", "将上臂靠在牧师凳垫上，保持肘部稍微弯曲。", "保持上臂静止，呼气并通过收缩二头肌将绳子卷向肩膀。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气，慢慢将绳子放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["將繩索附件連接到低滑輪纜繩機上。", "面向機器站立，雙腳分開與肩同寬。", "以中立握法（手掌相對）抓住繩子。", "將上臂靠在牧師凳墊上，保持肘部稍微彎曲。", "保持上臂靜止，呼氣并通過收縮二頭肌將繩子卷向肩膀。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣，慢慢將繩子放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1724', 'exercise', 1, '{"id": "1724", "target": "triceps", "name_en": "cable rope high pulley overhead tricep extension", "name_zh": "绳索绳头高位滑轮过顶臂屈伸", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/1724-NN8nSNT.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索繩頭高位滑輪過頂臂屈伸", "instructions_en": ["Attach a rope to a high pulley and adjust the weight accordingly.", "Stand facing away from the pulley machine with your feet shoulder-width apart.", "Grasp the rope with both hands, palms facing down, and bring your hands above your head.", "Keep your upper arms close to your head and perpendicular to the floor.", "Slowly lower the rope behind your head by bending your elbows.", "Pause for a moment, then extend your arms back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将绳子连接到高滑轮上并相应地调整重量。", "背对滑轮机站立，双脚与肩同宽。", "双手抓住绳子，掌心朝下，双手举过头顶。", "保持上臂靠近头部并垂直于地板。", "弯曲肘部，慢慢将绳子降低到头后。", "暂停片刻，然后将手臂伸回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["將繩子連接到高滑輪上并相應地調整重量。", "背對滑輪機站立，雙腳與肩同寬。", "雙手抓住繩子，掌心朝下，雙手舉過頭頂。", "保持上臂靠近頭部并垂直于地板。", "彎曲肘部，慢慢將繩子降低到頭后。", "暫停片刻，然后將手臂伸回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1725', 'exercise', 1, '{"id": "1725", "target": "triceps", "name_en": "cable rope incline tricep extension", "name_zh": "绳索绳头上斜臂屈伸", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/1725-ZujAdR9.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索繩頭上斜臂屈伸", "instructions_en": ["Attach a rope to a high pulley and adjust the incline bench to a comfortable angle.", "Stand facing away from the pulley with your feet shoulder-width apart.", "Grasp the rope with an overhand grip and extend your arms straight overhead.", "Keep your elbows close to your head and your upper arms stationary throughout the exercise.", "Lower the rope behind your head by bending your elbows until your forearms touch your biceps.", "Pause for a moment, then extend your arms back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将绳子连接到高滑轮上，并将倾斜长凳调整到舒适的角度。", "背对滑轮站立，双脚与肩同宽。", "正手抓住绳子，并将双臂伸直过头顶。", "在整个练习过程中，保持肘部靠近头部，上臂保持静止。", "弯曲肘部，直到前臂接触二头肌，将绳子降低到头后。", "暂停片刻，然后将手臂伸回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["將繩子連接到高滑輪上，并將傾斜長凳調整到舒適的角度。", "背對滑輪站立，雙腳與肩同寬。", "正手抓住繩子，并將雙臂伸直過頭頂。", "在整個練習過程中，保持肘部靠近頭部，上臂保持靜止。", "彎曲肘部，直到前臂接觸二頭肌，將繩子降低到頭后。", "暫停片刻，然后將手臂伸回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1726', 'exercise', 1, '{"id": "1726", "target": "triceps", "name_en": "cable rope lying on floor tricep extension", "name_zh": "绳索绳头地板仰卧臂屈伸", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/1726-U3ffHlY.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索繩頭地板仰臥臂屈伸", "instructions_en": ["Attach a rope to a cable machine and set it to the lowest position.", "Lie on the floor facing up, with your head towards the cable machine.", "Hold the rope with both hands, palms facing each other, and extend your arms straight up towards the ceiling.", "Keep your upper arms stationary and slowly lower the rope towards your forehead, bending your elbows.", "Pause for a moment, then extend your arms back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将绳子连接到缆绳机上并将其设置到最低位置。", "面朝上躺在地板上，头朝向电缆机。", "双手握住绳子，掌心相对，双臂伸直向上伸向天花板。", "保持上臂静止，慢慢地将绳子放低到前额，弯曲肘部。", "暂停片刻，然后将手臂伸回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["將繩子連接到纜繩機上并將其設置到最低位置。", "面朝上躺在地板上，頭朝向電纜機。", "雙手握住繩子，掌心相對，雙臂伸直向上伸向天花板。", "保持上臂靜止，慢慢地將繩子放低到前額，彎曲肘部。", "暫停片刻，然后將手臂伸回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1640', 'exercise', 1, '{"id": "1640", "target": "biceps", "name_en": "cable rope one arm hammer preacher curl", "name_zh": "绳索绳头单臂锤式牧师凳弯举", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/1640-4hATdoB.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索繩頭單臂錘式牧師凳彎舉", "instructions_en": ["Attach a rope handle to a low pulley cable machine.", "Stand facing the machine with your feet shoulder-width apart.", "Grasp the rope handle with an underhand grip, palms facing up.", "Position your upper arm against the preacher bench pad, keeping your elbow slightly bent.", "Keep your back straight and your core engaged throughout the exercise.", "Slowly curl the rope handle towards your shoulder, keeping your upper arm stationary.", "Squeeze your biceps at the top of the movement, then slowly lower the rope handle back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["将绳索手柄连接到低滑轮电缆机器上。", "面向机器站立，双脚分开与肩同宽。", "反手握住绳索手柄，手掌朝上。", "将上臂靠在牧师凳垫上，保持肘部稍微弯曲。", "在整个练习过程中保持背部挺直，核心肌群参与其中。", "慢慢地将绳索手柄卷向肩膀，保持上臂静止。", "在动作的最高点挤压二头肌，然后慢慢将绳柄放回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["將繩索手柄連接到低滑輪電纜機器上。", "面向機器站立，雙腳分開與肩同寬。", "反手握住繩索手柄，手掌朝上。", "將上臂靠在牧師凳墊上，保持肘部稍微彎曲。", "在整個練習過程中保持背部挺直，核心肌群參與其中。", "慢慢地將繩索手柄卷向肩膀，保持上臂靜止。", "在動作的最高點擠壓二頭肌，然后慢慢將繩柄放回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1323', 'exercise', 1, '{"id": "1323", "target": "upper back", "name_en": "cable rope seated row", "name_zh": "绳索绳头坐姿划船", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/1323-SJqRxOt.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索繩頭坐姿劃船", "instructions_en": ["Sit on the rowing machine with your feet flat on the footrests and knees slightly bent.", "Grasp the cable ropes with an overhand grip, palms facing each other.", "Keep your back straight and lean slightly forward, maintaining a slight bend in your elbows.", "Pull the cable ropes towards your body, squeezing your shoulder blades together.", "Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在划船机上，双脚平放在脚踏板上，膝盖稍微弯曲。", "正手握住缆绳，手掌相对。", "保持背部挺直，稍微向前倾斜，肘部保持轻微弯曲。", "将缆绳拉向身体，将肩胛骨挤压在一起。", "在动作的最高点停顿片刻，然后慢慢释放张力，回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["坐在劃船機上，雙腳平放在腳踏板上，膝蓋稍微彎曲。", "正手握住纜繩，手掌相對。", "保持背部挺直，稍微向前傾斜，肘部保持輕微彎曲。", "將纜繩拉向身體，將肩胛骨擠壓在一起。", "在動作的最高點停頓片刻，然后慢慢釋放張力，回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0211', 'exercise', 1, '{"id": "0211", "target": "abs", "name_en": "cable russian twists (on stability ball)", "name_zh": "健身球绳索俄罗斯转体", "body_part": "waist", "equipment": "cable", "gif_asset": "assets/fitness/videos/0211-d9Xaxq6.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球繩索俄羅斯轉體", "instructions_en": ["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.", "Hold the cable handle with both hands and extend your arms straight out in front of you.", "Lean back slightly while keeping your back straight and your core engaged.", "Twist your torso to the right, bringing the cable handle towards your right hip.", "Pause for a moment, then twist your torso to the left, bringing the cable handle towards your left hip.", "Continue alternating twists for the desired number of repetitions."], "instructions_zh": ["坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。", "双手握住电缆手柄，并将双臂伸直至前方。", "稍微向后倾斜，同时保持背部挺直并且核心参与。", "将躯干向右扭转，将电缆手柄拉向右臀部。", "暂停片刻，然后将躯干向左扭转，将电缆手柄拉向左臀部。", "继续交替扭转所需的重复次数。"], "secondary_muscles": ["obliques", "lower back"], "instructions_zh_hant": ["坐在穩定球上，雙腳平放在地面上，膝蓋彎曲成 90 度角。", "雙手握住電纜手柄，并將雙臂伸直至前方。", "稍微向后傾斜，同時保持背部挺直并且核心參與。", "將軀幹向右扭轉，將電纜手柄拉向右臀部。", "暫停片刻，然后將軀幹向左扭轉，將電纜手柄拉向左臀部。", "繼續交替扭轉所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2144', 'exercise', 1, '{"id": "2144", "target": "pectorals", "name_en": "cable seated chest press", "name_zh": "绳索坐姿推胸", "body_part": "chest", "equipment": "cable", "gif_asset": "assets/fitness/videos/2144-nIR4Rwl.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索坐姿推胸", "instructions_en": ["Adjust the seat height and cable handles to a comfortable position.", "Sit on the bench with your back straight and feet flat on the floor.", "Grasp the cable handles with an overhand grip at shoulder height.", "Push the handles forward and away from your body, extending your arms fully.", "Pause for a moment, then slowly bring the handles back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将座椅高度和电缆手柄调整至舒适的位置。", "坐在长凳上，背部挺直，双脚平放在地板上。", "正手握住电缆手柄，与肩同高。", "向前推动手柄并使其远离身体，充分伸展双臂。", "暂停片刻，然后慢慢将手柄放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["將座椅高度和電纜手柄調整至舒適的位置。", "坐在長凳上，背部挺直，雙腳平放在地板上。", "正手握住電纜手柄，與肩同高。", "向前推動手柄并使其遠離身體，充分伸展雙臂。", "暫停片刻，然后慢慢將手柄放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0212', 'exercise', 1, '{"id": "0212", "target": "abs", "name_en": "cable seated crunch", "name_zh": "绳索坐姿卷腹", "body_part": "waist", "equipment": "cable", "gif_asset": "assets/fitness/videos/0212-8xUv4J7.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索坐姿卷腹", "instructions_en": ["Sit on a cable machine with your feet flat on the ground and your knees bent.", "Hold the cable handle with both hands and position it behind your head.", "Engage your abs and slowly curl your upper body forward, bringing your chest towards your knees.", "Pause for a moment at the top, then slowly return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在缆绳机上，双脚平放在地面上，膝盖弯曲。", "用双手握住电缆手柄并将其放在脑后。", "收紧腹肌，慢慢向前弯曲上半身，使胸部靠近膝盖。", "在顶部停顿片刻，然后慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["obliques"], "instructions_zh_hant": ["坐在纜繩機上，雙腳平放在地面上，膝蓋彎曲。", "用雙手握住電纜手柄并將其放在腦后。", "收緊腹肌，慢慢向前彎曲上半身，使胸部靠近膝蓋。", "在頂部停頓片刻，然后慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1641', 'exercise', 1, '{"id": "1641", "target": "biceps", "name_en": "cable seated curl", "name_zh": "绳索坐姿弯举", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/1641-8oYqOt9.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索坐姿彎舉", "instructions_en": ["Sit on a cable machine with your feet flat on the ground and your back straight.", "Grasp the cable attachment with an underhand grip, palms facing up, and your arms fully extended.", "Keeping your upper arms stationary, exhale and curl the cable attachment towards your shoulders, contracting your biceps.", "Pause for a moment at the top of the movement, squeezing your biceps.", "Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在缆绳机上，双脚平放在地面上，背部挺直。", "反手抓住电缆附件，手掌朝上，双臂完全伸展。", "保持上臂静止，呼气并将电缆附件卷向肩膀，收缩二头肌。", "在动作的最高点暂停片刻，挤压你的二头肌。", "吸气并慢慢将电缆附件放回起始位置，充分伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在纜繩機上，雙腳平放在地面上，背部挺直。", "反手抓住電纜附件，手掌朝上，雙臂完全伸展。", "保持上臂靜止，呼氣并將電纜附件卷向肩膀，收縮二頭肌。", "在動作的最高點暫停片刻，擠壓你的二頭肌。", "吸氣并慢慢將電纜附件放回起始位置，充分伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0214', 'exercise', 1, '{"id": "0214", "target": "upper back", "name_en": "cable seated one arm alternate row", "name_zh": "绳索坐姿单臂交替划船", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/0214-vpp9Ku2.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索坐姿單臂交替劃船", "instructions_en": ["Sit on a bench facing a cable machine with your feet flat on the ground and knees slightly bent.", "Grasp the handle with one hand and keep your arm fully extended in front of you.", "Pull the handle towards your body, retracting your shoulder blade and keeping your elbow close to your side.", "Pause for a moment at the top of the movement, squeezing your back muscles.", "Slowly release the handle back to the starting position.", "Repeat with the other arm.", "Alternate between arms for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，面对缆绳机，双脚平放在地面上，膝盖稍微弯曲。", "用一只手抓住手柄，并将手臂完全伸展到身前。", "将手柄拉向身体，缩回肩胛骨并保持肘部靠近身体两侧。", "在动作的最高点暂停片刻，挤压背部肌肉。", "慢慢松开手柄回到起始位置。", "用另一只手臂重复上述步骤。", "双臂交替进行所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["坐在長凳上，面對纜繩機，雙腳平放在地面上，膝蓋稍微彎曲。", "用一只手抓住手柄，并將手臂完全伸展到身前。", "將手柄拉向身體，縮回肩胛骨并保持肘部靠近身體兩側。", "在動作的最高點暫停片刻，擠壓背部肌肉。", "慢慢松開手柄回到起始位置。", "用另一只手臂重復上述步驟。", "雙臂交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1642', 'exercise', 1, '{"id": "1642", "target": "biceps", "name_en": "cable seated one arm concentration curl", "name_zh": "绳索坐姿单臂集中弯举", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/1642-rZ80Gbp.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索坐姿單臂集中彎舉", "instructions_en": ["Sit on a bench with your feet flat on the floor and your back straight.", "Hold a cable handle with one hand and place your elbow on the inside of your thigh, just above the knee.", "Keep your upper arm stationary and curl the cable handle towards your shoulder while exhaling.", "Pause for a moment at the top of the movement, squeezing your biceps.", "Slowly lower the cable handle back to the starting position while inhaling.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["坐在长凳上，双脚平放在地板上，背部挺直。", "用一只手握住电缆手柄，并将肘部放在大腿内侧、膝盖上方。", "呼气时，保持上臂静止并将电缆手柄向肩膀卷曲。", "在动作的最高点暂停片刻，挤压你的二头肌。", "吸气时慢慢将电缆手柄放回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在長凳上，雙腳平放在地板上，背部挺直。", "用一只手握住電纜手柄，并將肘部放在大腿內側、膝蓋上方。", "呼氣時，保持上臂靜止并將電纜手柄向肩膀卷曲。", "在動作的最高點暫停片刻，擠壓你的二頭肌。", "吸氣時慢慢將電纜手柄放回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1643', 'exercise', 1, '{"id": "1643", "target": "biceps", "name_en": "cable seated overhead curl", "name_zh": "绳索坐姿过顶弯举", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/1643-DpWMFP5.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索坐姿過頂彎舉", "instructions_en": ["Sit on a bench facing the cable machine with your feet flat on the ground.", "Grasp the cable attachment with an underhand grip, palms facing up, and your hands shoulder-width apart.", "Keep your upper arms stationary and your elbows close to your sides.", "Exhale and curl the cable attachment towards your shoulders, contracting your biceps.", "Pause for a moment at the top of the movement, squeezing your biceps.", "Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，面向电缆机，双脚平放在地面上。", "用手握住电缆附件，手掌朝上，双手与肩同宽。", "保持上臂不动，肘部靠近身体两侧。", "呼气并将电缆附件卷向肩膀，收缩二头肌。", "在动作的最高点暂停片刻，挤压你的二头肌。", "吸气并慢慢将电缆附件放回起始位置，充分伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["forearms", "shoulders"], "instructions_zh_hant": ["坐在長凳上，面向電纜機，雙腳平放在地面上。", "用手握住電纜附件，手掌朝上，雙手與肩同寬。", "保持上臂不動，肘部靠近身體兩側。", "呼氣并將電纜附件卷向肩膀，收縮二頭肌。", "在動作的最高點暫停片刻，擠壓你的二頭肌。", "吸氣并慢慢將電纜附件放回起始位置，充分伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0216', 'exercise', 1, '{"id": "0216", "target": "delts", "name_en": "cable seated shoulder internal rotation", "name_zh": "绳索坐姿肩部内旋", "body_part": "shoulders", "equipment": "cable", "gif_asset": "assets/fitness/videos/0216-YPoVrBi.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索坐姿肩部內旋", "instructions_en": ["Sit on a bench or chair facing the cable machine with your feet flat on the ground.", "Hold the cable handle with your arm extended straight out in front of you, parallel to the ground.", "Keep your elbow slightly bent and your shoulder blades pulled back and down.", "Slowly rotate your arm inward, bringing the cable handle towards the center of your body.", "Pause for a moment at the end of the movement, then slowly return to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["坐在长凳或椅子上，面向电缆机，双脚平放在地面上。", "握住电缆手柄，手臂在身前伸直，与地面平行。", "保持肘部稍微弯曲，肩胛骨向后和向下拉。", "慢慢向内旋转手臂，将电缆手柄拉向身体中心。", "动作结束时暂停片刻，然后慢慢回到起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["rotator cuff", "triceps"], "instructions_zh_hant": ["坐在長凳或椅子上，面向電纜機，雙腳平放在地面上。", "握住電纜手柄，手臂在身前伸直，與地面平行。", "保持肘部稍微彎曲，肩胛骨向后和向下拉。", "慢慢向內旋轉手臂，將電纜手柄拉向身體中心。", "動作結束時暫停片刻，然后慢慢回到起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2399', 'exercise', 1, '{"id": "2399", "target": "abs", "name_en": "cable seated twist", "name_zh": "绳索坐姿转体", "body_part": "waist", "equipment": "cable", "gif_asset": "assets/fitness/videos/2399-UEjSrKI.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索坐姿轉體", "instructions_en": ["Sit on a cable machine with your feet flat on the ground and your knees slightly bent.", "Hold the cable handle with both hands and extend your arms straight in front of you.", "Keeping your core engaged, slowly rotate your torso to one side, pulling the cable across your body.", "Pause for a moment at the end of the range of motion, then slowly rotate back to the starting position.", "Repeat on the other side.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["坐在缆绳机上，双脚平放在地面上，膝盖稍微弯曲。", "双手握住电缆手柄，并将双臂伸直至身前。", "保持核心参与，慢慢地将躯干旋转到一侧，将电缆拉过身体。", "在动作范围结束时暂停片刻，然后慢慢旋转回到起始位置。", "在另一侧重复。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["obliques"], "instructions_zh_hant": ["坐在纜繩機上，雙腳平放在地面上，膝蓋稍微彎曲。", "雙手握住電纜手柄，并將雙臂伸直至身前。", "保持核心參與，慢慢地將軀幹旋轉到一側，將電纜拉過身體。", "在動作范圍結束時暫停片刻，然后慢慢旋轉回到起始位置。", "在另一側重復。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0218', 'exercise', 1, '{"id": "0218", "target": "upper back", "name_en": "cable seated wide-grip row", "name_zh": "绳索坐姿宽握划船", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/0218-qcY50ZD.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索坐姿寬握劃船", "instructions_en": ["Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.", "Grasp the handle with a wide overhand grip, palms facing down.", "Keep your back straight and lean slightly forward from the hips.", "Pull the handle towards your lower chest, squeezing your shoulder blades together.", "Pause for a moment at the peak of the contraction.", "Slowly release the handle back to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在电缆划船机上，双脚平放在脚踏板上，膝盖稍微弯曲。", "正手宽握握住手柄，手掌朝下。", "保持背部挺直，并从臀部稍微向前倾斜。", "将手柄拉向下胸部，将肩胛骨挤压在一起。", "在收缩高峰时暂停片刻。", "慢慢松开手柄回到起始位置，充分伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["坐在電纜劃船機上，雙腳平放在腳踏板上，膝蓋稍微彎曲。", "正手寬握握住手柄，手掌朝下。", "保持背部挺直，并從臀部稍微向前傾斜。", "將手柄拉向下胸部，將肩胛骨擠壓在一起。", "在收縮高峰時暫停片刻。", "慢慢松開手柄回到起始位置，充分伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0219', 'exercise', 1, '{"id": "0219", "target": "delts", "name_en": "cable shoulder press", "name_zh": "绳索肩上推举", "body_part": "shoulders", "equipment": "cable", "gif_asset": "assets/fitness/videos/0219-PzQanLE.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索肩上推舉", "instructions_en": ["Adjust the cable machine so that the handles are at shoulder height.", "Stand facing away from the machine with your feet shoulder-width apart.", "Grasp the handles with an overhand grip and bring them up to shoulder level, with your elbows bent and pointing outwards.", "Press the handles upwards until your arms are fully extended overhead.", "Pause for a moment at the top, then slowly lower the handles back down to shoulder level.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整绳索机，使手柄位于肩部高度。", "背对机器站立，双脚与肩同宽。", "正手握住手柄，将其提升至肩部水平，肘部弯曲并指向外侧。", "向上按压手柄，直到手臂完全伸过头顶。", "在顶部暂停片刻，然后慢慢将手柄放回至肩部水平。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "upper back"], "instructions_zh_hant": ["調整繩索機，使手柄位于肩部高度。", "背對機器站立，雙腳與肩同寬。", "正手握住手柄，將其提升至肩部水平，肘部彎曲并指向外側。", "向上按壓手柄，直到手臂完全伸過頭頂。", "在頂部暫停片刻，然后慢慢將手柄放回至肩部水平。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0220', 'exercise', 1, '{"id": "0220", "target": "traps", "name_en": "cable shrug", "name_zh": "绳索耸肩", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/0220-Eg98Ft9.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索聳肩", "instructions_en": ["Stand facing the cable machine with your feet shoulder-width apart.", "Grasp the cable handles with an overhand grip and let your arms hang down in front of you.", "Keeping your arms straight, shrug your shoulders up towards your ears.", "Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["面对电缆机站立，双脚与肩同宽。", "正手握住电缆手柄，让手臂垂在身前。", "保持手臂伸直，耸肩向耳朵方向向上。", "保持收缩一会儿，然后慢慢将肩膀放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["面對電纜機站立，雙腳與肩同寬。", "正手握住電纜手柄，讓手臂垂在身前。", "保持手臂伸直，聳肩向耳朵方向向上。", "保持收縮一會兒，然后慢慢將肩膀放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0222', 'exercise', 1, '{"id": "0222", "target": "abs", "name_en": "cable side bend", "name_zh": "绳索侧屈", "body_part": "waist", "equipment": "cable", "gif_asset": "assets/fitness/videos/0222-wPypxFY.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索側屈", "instructions_en": ["Stand with your feet shoulder-width apart and grasp the cable handle with one hand.", "Keep your back straight and your core engaged.", "Slowly bend sideways at the waist, lowering the cable handle towards your knee.", "Pause for a moment, then return to the starting position.", "Repeat on the other side.", "Alternate sides for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，用一只手抓住电缆手柄。", "保持背部挺直，核心肌群参与。", "腰部慢慢向侧面弯曲，将电缆手柄向膝盖方向降低。", "暂停片刻，然后回到起始位置。", "在另一侧重复。", "交替进行所需的重复次数。"], "secondary_muscles": ["obliques"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，用一只手抓住電纜手柄。", "保持背部挺直，核心肌群參與。", "腰部慢慢向側面彎曲，將電纜手柄向膝蓋方向降低。", "暫停片刻，然后回到起始位置。", "在另一側重復。", "交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0221', 'exercise', 1, '{"id": "0221", "target": "abs", "name_en": "cable side bend crunch (bosu ball)", "name_zh": "绳索侧屈卷腹（波速球）", "body_part": "waist", "equipment": "cable", "gif_asset": "assets/fitness/videos/0221-qatbkEd.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索側屈卷腹（波速球）", "instructions_en": ["Stand with your feet shoulder-width apart, holding a cable handle in one hand.", "Place the other hand on your hip.", "Engage your core and slowly bend sideways towards the hand holding the cable, keeping your back straight.", "Pause for a moment at the bottom of the movement, then slowly return to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["双脚分开与肩同宽站立，一只手握住电缆手柄。", "将另一只手放在臀部上。", "启动你的核心，慢慢向握住电缆的手侧弯，保持背部挺直。", "在动作底部暂停片刻，然后慢慢回到起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["obliques"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，一只手握住電纜手柄。", "將另一只手放在臀部上。", "啟動你的核心，慢慢向握住電纜的手側彎，保持背部挺直。", "在動作底部暫停片刻，然后慢慢回到起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0223', 'exercise', 1, '{"id": "0223", "target": "abs", "name_en": "cable side crunch", "name_zh": "绳索侧卷腹", "body_part": "waist", "equipment": "cable", "gif_asset": "assets/fitness/videos/0223-q2ADGqV.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索側卷腹", "instructions_en": ["Attach a cable handle to a low pulley and stand sideways to the machine.", "Grasp the handle with the hand furthest from the machine and place your other hand on your hip.", "Keep your feet shoulder-width apart and your knees slightly bent.", "With your abs engaged, bend sideways at the waist, bringing your elbow down towards your hip.", "Pause for a moment at the bottom, then slowly return to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["将电缆手柄连接到低滑轮上并站在机器旁边。", "用距离机器最远的手抓住手柄，并将另一只手放在臀部上。", "双脚分开与肩同宽，膝盖稍微弯曲。", "收紧腹肌，腰部向侧面弯曲，将肘部向下拉向臀部。", "在底部停顿片刻，然后慢慢回到起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["obliques"], "instructions_zh_hant": ["將電纜手柄連接到低滑輪上并站在機器旁邊。", "用距離機器最遠的手抓住手柄，并將另一只手放在臀部上。", "雙腳分開與肩同寬，膝蓋稍微彎曲。", "收緊腹肌，腰部向側面彎曲，將肘部向下拉向臀部。", "在底部停頓片刻，然后慢慢回到起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1717', 'exercise', 1, '{"id": "1717", "target": "lats", "name_en": "cable squat row (with rope attachment)", "name_zh": "绳索深蹲划船（配合绳索把手）", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/1717-f7fnAIB.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索深蹲劃船（配合繩索把手）", "instructions_en": ["Attach a rope to a cable machine at waist height.", "Stand facing the cable machine with your feet shoulder-width apart.", "Bend your knees and lower your body into a squat position, keeping your back straight and chest up.", "Grasp the rope with an overhand grip, with your hands shoulder-width apart.", "Engage your core and pull the rope towards your body, squeezing your shoulder blades together.", "Keep your elbows close to your body and continue pulling until your hands reach your chest.", "Pause for a moment at the top of the movement, then slowly release the rope and extend your arms back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将绳子连接到腰部高度的缆绳机上。", "面对电缆机站立，双脚与肩同宽。", "弯曲膝盖，将身体降低至蹲姿，保持背部挺直，挺胸。", "正手握住绳子，双手与肩同宽。", "收紧核心并将绳子拉向身体，将肩胛骨挤压在一起。", "保持肘部靠近身体并继续拉，直到双手到达胸部。", "在动作的最高点停顿片刻，然后慢慢松开绳子，并将手臂伸回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "rhomboids", "rear deltoids"], "instructions_zh_hant": ["將繩子連接到腰部高度的纜繩機上。", "面對電纜機站立，雙腳與肩同寬。", "彎曲膝蓋，將身體降低至蹲姿，保持背部挺直，挺胸。", "正手握住繩子，雙手與肩同寬。", "收緊核心并將繩子拉向身體，將肩胛骨擠壓在一起。", "保持肘部靠近身體并繼續拉，直到雙手到達胸部。", "在動作的最高點停頓片刻，然后慢慢松開繩子，并將手臂伸回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1644', 'exercise', 1, '{"id": "1644", "target": "biceps", "name_en": "cable squatting curl", "name_zh": "绳索蹲姿弯举", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/1644-3XFdb1Z.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索蹲姿彎舉", "instructions_en": ["Attach a cable handle to the lowest setting on a cable machine.", "Stand facing the machine with your feet shoulder-width apart.", "Hold the cable handle with an underhand grip, palms facing up, and arms fully extended.", "Lower your body into a squat position, keeping your back straight and knees behind your toes.", "As you squat down, curl the cable handle towards your shoulders, keeping your elbows close to your sides.", "Pause for a moment at the top of the curl, squeezing your biceps.", "Slowly lower the cable handle back to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将电缆手柄连接到电缆机器上的最低设置。", "面向机器站立，双脚分开与肩同宽。", "反手握住电缆手柄，手掌朝上，手臂完全伸展。", "将身体降低至蹲姿，保持背部挺直，膝盖位于脚趾后面。", "当你蹲下时，将电缆手柄卷向肩膀，保持肘部靠近身体两侧。", "在弯举的顶部暂停片刻，挤压二头肌。", "慢慢地将电缆手柄放回起始位置，完全伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["將電纜手柄連接到電纜機器上的最低設置。", "面向機器站立，雙腳分開與肩同寬。", "反手握住電纜手柄，手掌朝上，手臂完全伸展。", "將身體降低至蹲姿，保持背部挺直，膝蓋位于腳趾后面。", "當你蹲下時，將電纜手柄卷向肩膀，保持肘部靠近身體兩側。", "在彎舉的頂部暫停片刻，擠壓二頭肌。", "慢慢地將電纜手柄放回起始位置，完全伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0224', 'exercise', 1, '{"id": "0224", "target": "forearms", "name_en": "cable standing back wrist curl", "name_zh": "绳索站姿背部腕弯举", "body_part": "lower arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/0224-VhX2JdE.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索站姿背部腕彎舉", "instructions_en": ["Stand facing a cable machine with your feet shoulder-width apart.", "Hold the cable handle with an overhand grip, palms facing down.", "Keep your arms straight and your elbows close to your sides.", "Slowly curl your wrists upward, bringing the cable handle towards your body.", "Pause for a moment at the top, then slowly lower the cable handle back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["面向缆绳机站立，双脚与肩同宽。", "正手握住电缆手柄，手掌朝下。", "保持手臂伸直，肘部靠近身体两侧。", "慢慢向上弯曲手腕，将电缆手柄拉向身体。", "在顶部暂停片刻，然后慢慢将拉索手柄放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "brachialis"], "instructions_zh_hant": ["面向纜繩機站立，雙腳與肩同寬。", "正手握住電纜手柄，手掌朝下。", "保持手臂伸直，肘部靠近身體兩側。", "慢慢向上彎曲手腕，將電纜手柄拉向身體。", "在頂部暫停片刻，然后慢慢將拉索手柄放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1375', 'exercise', 1, '{"id": "1375", "target": "calves", "name_en": "cable standing calf raise", "name_zh": "绳索站姿提踵", "body_part": "lower legs", "equipment": "cable", "gif_asset": "assets/fitness/videos/1375-yl2IYyy.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索站姿提踵", "instructions_en": ["Stand facing a cable machine with your feet shoulder-width apart.", "Hold onto the cable machine handles or attach a cable ankle strap to your ankles.", "Raise your heels off the ground by extending your ankles as high as possible.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["面向缆绳机站立，双脚与肩同宽。", "握住电缆机手柄或将电缆脚踝带固定在脚踝上。", "尽可能高地伸展脚踝，将脚后跟抬离地面。", "在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "glutes"], "instructions_zh_hant": ["面向纜繩機站立，雙腳與肩同寬。", "握住電纜機手柄或將電纜腳踝帶固定在腳踝上。", "盡可能高地伸展腳踝，將腳后跟抬離地面。", "在頂部停頓片刻，然后慢慢降低腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0225', 'exercise', 1, '{"id": "0225", "target": "delts", "name_en": "cable standing cross-over high reverse fly", "name_zh": "绳索站姿交叉高位反向飞鸟", "body_part": "shoulders", "equipment": "cable", "gif_asset": "assets/fitness/videos/0225-P5p0j8B.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索站姿交叉高位反向飛鳥", "instructions_en": ["Attach a D-handle to each side of a cable machine at shoulder height.", "Stand in the middle of the cable machine with your feet shoulder-width apart.", "Grasp the handles with an overhand grip and extend your arms out to the sides, palms facing forward.", "Keep a slight bend in your elbows and maintain a straight back throughout the exercise.", "Engage your shoulder muscles and squeeze your shoulder blades together as you pull the handles towards the front of your body.", "Pause for a moment at the peak of the movement, then slowly return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将 D 形手柄安装到缆绳机两侧与肩同高的位置。", "站在缆绳机的中间，双脚分开与肩同宽。", "正手握住手柄，并将手臂向两侧伸展，手掌朝前。", "在整个练习过程中保持肘部轻微弯曲并保持背部挺直。", "当您将手柄拉向身体前方时，收紧肩部肌肉并将肩胛骨挤压在一起。", "在动作的最高点停顿片刻，然后慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["trapezius", "rhomboids", "rear deltoids"], "instructions_zh_hant": ["將 D 形手柄安裝到纜繩機兩側與肩同高的位置。", "站在纜繩機的中間，雙腳分開與肩同寬。", "正手握住手柄，并將手臂向兩側伸展，手掌朝前。", "在整個練習過程中保持肘部輕微彎曲并保持背部挺直。", "當您將手柄拉向身體前方時，收緊肩部肌肉并將肩胛骨擠壓在一起。", "在動作的最高點停頓片刻，然后慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0226', 'exercise', 1, '{"id": "0226", "target": "abs", "name_en": "cable standing crunch", "name_zh": "绳索站姿卷腹", "body_part": "waist", "equipment": "cable", "gif_asset": "assets/fitness/videos/0226-jpgqxiS.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索站姿卷腹", "instructions_en": ["Attach a cable handle to a high pulley and stand facing away from the machine.", "Hold the handle with both hands and place it behind your head, keeping your elbows bent.", "Stand with your feet shoulder-width apart and your knees slightly bent.", "Keeping your abs engaged, exhale and crunch your torso down towards your knees, bringing your elbows towards your thighs.", "Pause for a moment at the bottom of the movement, then slowly return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将电缆手柄连接到高滑轮上，并背对机器站立。", "双手握住手柄并将其放在脑后，保持肘部弯曲。", "双脚分开与肩同宽站立，膝盖稍微弯曲。", "保持腹肌收紧，呼气，将躯干压向膝盖，将肘部拉向大腿。", "在动作底部暂停片刻，然后慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["obliques"], "instructions_zh_hant": ["將電纜手柄連接到高滑輪上，并背對機器站立。", "雙手握住手柄并將其放在腦后，保持肘部彎曲。", "雙腳分開與肩同寬站立，膝蓋稍微彎曲。", "保持腹肌收緊，呼氣，將軀幹壓向膝蓋，將肘部拉向大腿。", "在動作底部暫停片刻，然后慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0874', 'exercise', 1, '{"id": "0874", "target": "abs", "name_en": "cable standing crunch (with rope attachment)", "name_zh": "绳索站姿卷腹（配合绳索把手）", "body_part": "waist", "equipment": "cable", "gif_asset": "assets/fitness/videos/0874-XU3ePuv.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索站姿卷腹（配合繩索把手）", "instructions_en": ["Attach a rope to a cable machine at chest height.", "Stand facing away from the machine with your feet shoulder-width apart.", "Hold the rope with both hands and bring it behind your head, keeping your elbows bent.", "Engage your abs and slowly crunch your torso forward, bringing your elbows towards your knees.", "Pause for a moment at the top of the crunch, then slowly return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将一根绳子连接到胸部高度的缆绳机上。", "背对机器站立，双脚与肩同宽。", "双手握住绳子并将其放在脑后，保持肘部弯曲。", "收紧腹肌，慢慢向前挤压躯干，使肘部靠近膝盖。", "在卷腹的最高点暂停片刻，然后慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["obliques"], "instructions_zh_hant": ["將一根繩子連接到胸部高度的纜繩機上。", "背對機器站立，雙腳與肩同寬。", "雙手握住繩子并將其放在腦后，保持肘部彎曲。", "收緊腹肌，慢慢向前擠壓軀幹，使肘部靠近膝蓋。", "在卷腹的最高點暫停片刻，然后慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0227', 'exercise', 1, '{"id": "0227", "target": "pectorals", "name_en": "cable standing fly", "name_zh": "绳索站姿飞鸟", "body_part": "chest", "equipment": "cable", "gif_asset": "assets/fitness/videos/0227-Pr9Rhf4.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索站姿飛鳥", "instructions_en": ["Attach the handles to the cables at chest height.", "Stand with your feet shoulder-width apart, facing away from the cable machine.", "Grasp the handles with an overhand grip, palms facing forward.", "Step forward slightly to create tension in the cables.", "Keep your core engaged and your back straight throughout the exercise.", "With a slight bend in your elbows, slowly bring your arms forward and together in front of your chest.", "Squeeze your chest muscles at the peak of the movement.", "Slowly reverse the movement, returning your arms to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将手柄连接到胸部高度的电缆上。", "双脚分开与肩同宽站立，背对缆绳机。", "正手握住手柄，手掌朝前。", "稍微向前一步以在缆绳中产生张力。", "在整个练习过程中保持核心参与并保持背部挺直。", "肘部稍微弯曲，慢慢地将双臂向前并拢在胸前。", "在运动的最高点挤压胸部肌肉。", "慢慢扭转动作，将手臂恢复到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["deltoids", "triceps"], "instructions_zh_hant": ["將手柄連接到胸部高度的電纜上。", "雙腳分開與肩同寬站立，背對纜繩機。", "正手握住手柄，手掌朝前。", "稍微向前一步以在纜繩中產生張力。", "在整個練習過程中保持核心參與并保持背部挺直。", "肘部稍微彎曲，慢慢地將雙臂向前并攏在胸前。", "在運動的最高點擠壓胸部肌肉。", "慢慢扭轉動作，將手臂恢復到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0228', 'exercise', 1, '{"id": "0228", "target": "glutes", "name_en": "cable standing hip extension", "name_zh": "绳索站姿髋伸展", "body_part": "upper legs", "equipment": "cable", "gif_asset": "assets/fitness/videos/0228-Kpajagk.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索站姿髖伸展", "instructions_en": ["Attach a cable to a low pulley and stand facing away from the machine.", "Place the cable around your ankle and stand with your feet shoulder-width apart.", "Keep your core engaged and your back straight throughout the exercise.", "Slowly extend your leg straight back, squeezing your glutes at the top of the movement.", "Pause for a moment, then return to the starting position.", "Repeat for the desired number of repetitions.", "Switch sides and repeat with the other leg."], "instructions_zh": ["将电缆连接到低滑轮上，并背对机器站立。", "将电缆绕在脚踝上，双脚分开与肩同宽站立。", "在整个练习过程中保持核心参与并保持背部挺直。", "慢慢地将腿向后伸直，在动作的最高点挤压臀部。", "暂停片刻，然后回到起始位置。", "重复所需的重复次数。", "换边并用另一条腿重复。"], "secondary_muscles": ["hamstrings", "quadriceps"], "instructions_zh_hant": ["將電纜連接到低滑輪上，并背對機器站立。", "將電纜繞在腳踝上，雙腳分開與肩同寬站立。", "在整個練習過程中保持核心參與并保持背部挺直。", "慢慢地將腿向后伸直，在動作的最高點擠壓臀部。", "暫停片刻，然后回到起始位置。", "重復所需的重復次數。", "換邊并用另一條腿重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0229', 'exercise', 1, '{"id": "0229", "target": "biceps", "name_en": "cable standing inner curl", "name_zh": "绳索站姿内侧弯举", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/0229-YwnI4ja.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索站姿內側彎舉", "instructions_en": ["Stand facing a cable machine with your feet shoulder-width apart.", "Grasp the cable handle with an underhand grip, palms facing up.", "Keep your elbows close to your sides and your upper arms stationary.", "Exhale and curl the cable handle towards your shoulders, contracting your biceps.", "Pause for a moment at the top of the movement, squeezing your biceps.", "Inhale and slowly lower the cable handle back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["面向缆绳机站立，双脚与肩同宽。", "反手握住电缆手柄，手掌朝上。", "保持肘部靠近身体两侧，上臂保持静止。", "呼气并将绳索手柄卷向肩膀，收缩二头肌。", "在动作的最高点暂停片刻，挤压你的二头肌。", "吸气并缓慢地将电缆手柄放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["面向纜繩機站立，雙腳與肩同寬。", "反手握住電纜手柄，手掌朝上。", "保持肘部靠近身體兩側，上臂保持靜止。", "呼氣并將繩索手柄卷向肩膀，收縮二頭肌。", "在動作的最高點暫停片刻，擠壓你的二頭肌。", "吸氣并緩慢地將電纜手柄放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0230', 'exercise', 1, '{"id": "0230", "target": "abs", "name_en": "cable standing lift", "name_zh": "绳索站姿斜向上拉", "body_part": "waist", "equipment": "cable", "gif_asset": "assets/fitness/videos/0230-qFpAkpP.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索站姿斜向上拉", "instructions_en": ["Stand facing the cable machine with your feet shoulder-width apart.", "Hold the cable handle with both hands and position it at waist height.", "Engage your core and maintain a straight back throughout the exercise.", "Keeping your arms straight, exhale and lift the cable handle up towards your opposite shoulder, rotating your torso.", "Pause for a moment at the top, then inhale and slowly lower the cable handle back to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["面对电缆机站立，双脚与肩同宽。", "双手握住电缆手柄并将其置于腰部高度。", "在整个练习过程中启动核心并保持背部挺直。", "保持手臂伸直，呼气并将电缆手柄向另一侧的肩膀向上提起，同时旋转躯干。", "在顶部暂停片刻，然后吸气并慢慢将拉索手柄放回起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["obliques", "lower back"], "instructions_zh_hant": ["面對電纜機站立，雙腳與肩同寬。", "雙手握住電纜手柄并將其置于腰部高度。", "在整個練習過程中啟動核心并保持背部挺直。", "保持手臂伸直，呼氣并將電纜手柄向另一側的肩膀向上提起，同時旋轉軀幹。", "在頂部暫停片刻，然后吸氣并慢慢將拉索手柄放回起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0231', 'exercise', 1, '{"id": "0231", "target": "triceps", "name_en": "cable standing one arm triceps extension", "name_zh": "绳索站姿单臂臂屈伸", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/0231-sYCcnon.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索站姿單臂臂屈伸", "instructions_en": ["Stand with your feet shoulder-width apart, facing the cable machine.", "Hold the cable handle with your right hand, palm facing down, and position your arm so that it is fully extended and parallel to the ground.", "Keep your elbow stationary and close to your body.", "Slowly bend your elbow, lowering the cable handle towards the back of your head.", "Pause for a moment at the bottom of the movement, then extend your arm back to the starting position.", "Repeat for the desired number of repetitions, then switch sides and perform the exercise with your left arm."], "instructions_zh": ["双脚分开与肩同宽站立，面向绳索机。", "用右手握住电缆手柄，掌心朝下，调整手臂位置，使其完全伸展并与地面平行。", "保持肘部静止并靠近身体。", "慢慢弯曲肘部，将电缆手柄向脑后降低。", "在动作底部停顿片刻，然后将手臂伸回起始位置。", "重复所需的重复次数，然后换边并用左臂进行练习。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，面向繩索機。", "用右手握住電纜手柄，掌心朝下，調整手臂位置，使其完全伸展并與地面平行。", "保持肘部靜止并靠近身體。", "慢慢彎曲肘部，將電纜手柄向腦后降低。", "在動作底部停頓片刻，然后將手臂伸回起始位置。", "重復所需的重復次數，然后換邊并用左臂進行練習。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1376', 'exercise', 1, '{"id": "1376", "target": "calves", "name_en": "cable standing one leg calf raise", "name_zh": "绳索站姿单腿提踵", "body_part": "lower legs", "equipment": "cable", "gif_asset": "assets/fitness/videos/1376-fgc9Xdl.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索站姿單腿提踵", "instructions_en": ["Stand facing a cable machine with your feet shoulder-width apart.", "Hold onto the cable machine for support.", "Lift one leg off the ground and balance on the other leg.", "Slowly raise your heel off the ground, lifting your body up onto your toes.", "Pause for a moment at the top, then slowly lower your heel back down to the starting position.", "Repeat for the desired number of repetitions, then switch legs."], "instructions_zh": ["面向缆绳机站立，双脚与肩同宽。", "抓住电缆机以获得支撑。", "将一条腿抬离地面并用另一条腿保持平衡。", "慢慢地将脚跟抬离地面，将身体抬起到脚趾上。", "在顶部暂停片刻，然后慢慢将脚跟放回起始位置。", "重复所需的重复次数，然后换腿。"], "secondary_muscles": ["ankles", "feet"], "instructions_zh_hant": ["面向纜繩機站立，雙腳與肩同寬。", "抓住電纜機以獲得支撐。", "將一條腿抬離地面并用另一條腿保持平衡。", "慢慢地將腳跟抬離地面，將身體抬起到腳趾上。", "在頂部暫停片刻，然后慢慢將腳跟放回起始位置。", "重復所需的重復次數，然后換腿。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0232', 'exercise', 1, '{"id": "0232", "target": "biceps", "name_en": "cable standing pulldown (with rope)", "name_zh": "绳索站姿下拉（配合绳索）", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/0232-CvPn9WV.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索站姿下拉（配合繩索）", "instructions_en": ["Attach a rope to the cable machine at the highest setting.", "Stand facing the machine with your feet shoulder-width apart.", "Grasp the rope with an overhand grip, palms facing down.", "Keep your back straight and core engaged throughout the exercise.", "Pull the rope down towards your thighs, squeezing your biceps.", "Pause for a moment at the bottom, then slowly release the rope back up.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将绳索连接到最高设置的缆绳机上。", "面向机器站立，双脚分开与肩同宽。", "正手握住绳子，手掌朝下。", "在整个练习过程中保持背部挺直并保持核心参与。", "将绳子向下拉向大腿，挤压二头肌。", "在底部停顿片刻，然后慢慢地将绳子放回原位。", "重复所需的重复次数。"], "secondary_muscles": ["forearms", "shoulders"], "instructions_zh_hant": ["將繩索連接到最高設置的纜繩機上。", "面向機器站立，雙腳分開與肩同寬。", "正手握住繩子，手掌朝下。", "在整個練習過程中保持背部挺直并保持核心參與。", "將繩子向下拉向大腿，擠壓二頭肌。", "在底部停頓片刻，然后慢慢地將繩子放回原位。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0233', 'exercise', 1, '{"id": "0233", "target": "delts", "name_en": "cable standing rear delt row (with rope)", "name_zh": "绳索站姿三角肌后束划船（配合绳索）", "body_part": "shoulders", "equipment": "cable", "gif_asset": "assets/fitness/videos/0233-ZfyAGhK.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索站姿三角肌后束劃船（配合繩索）", "instructions_en": ["Stand facing a cable machine with your feet shoulder-width apart.", "Hold the cable attachment with both hands, palms facing each other, and step back to create tension in the cable.", "Keep your back straight and your core engaged.", "Pull the cable towards your body, squeezing your shoulder blades together.", "Pause for a moment at the peak of the movement, then slowly release the cable back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["面向缆绳机站立，双脚与肩同宽。", "用双手握住电缆附件，手掌相对，然后后退以在电缆中产生张力。", "保持背部挺直，核心肌群参与。", "将电缆拉向您的身体，将肩胛骨挤压在一起。", "在运动的最高点停顿片刻，然后慢慢松开绳索回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["trapezius", "rhomboids", "biceps"], "instructions_zh_hant": ["面向纜繩機站立，雙腳與肩同寬。", "用雙手握住電纜附件，手掌相對，然后后退以在電纜中產生張力。", "保持背部挺直，核心肌群參與。", "將電纜拉向您的身體，將肩胛骨擠壓在一起。", "在運動的最高點停頓片刻，然后慢慢松開繩索回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1727', 'exercise', 1, '{"id": "1727", "target": "triceps", "name_en": "cable standing reverse grip one arm overhead tricep extension", "name_zh": "绳索站姿反握单臂过顶臂屈伸", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/1727-i11JWU7.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索站姿反握單臂過頂臂屈伸", "instructions_en": ["Stand facing away from the cable machine with your feet shoulder-width apart.", "Hold the cable handle with an underhand grip and extend your arm overhead, keeping your elbow close to your head.", "Keep your upper arm stationary and slowly lower the cable handle behind your head by bending your elbow.", "Pause for a moment at the bottom, then extend your arm back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["背对缆绳机站立，双脚与肩同宽。", "用手握住电缆手柄，并将手臂伸过头顶，保持肘部靠近头部。", "保持上臂静止，弯曲肘部，慢慢将电缆手柄降低到脑后。", "在底部停顿片刻，然后将手臂伸回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["背對纜繩機站立，雙腳與肩同寬。", "用手握住電纜手柄，并將手臂伸過頭頂，保持肘部靠近頭部。", "保持上臂靜止，彎曲肘部，慢慢將電纜手柄降低到腦后。", "在底部停頓片刻，然后將手臂伸回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0234', 'exercise', 1, '{"id": "0234", "target": "upper back", "name_en": "cable standing row (v-bar)", "name_zh": "绳索站姿划船（V形把手）", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/0234-4f8RXP8.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索站姿劃船（V形把手）", "instructions_en": ["Stand facing the cable machine with your feet shoulder-width apart.", "Grasp the v-bar attachment with an overhand grip, palms facing down.", "Keep your back straight and your core engaged.", "Pull the v-bar towards your body, squeezing your shoulder blades together.", "Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["面对电缆机站立，双脚与肩同宽。", "正手握住 V 形杆附件，手掌朝下。", "保持背部挺直，核心肌群参与。", "将 V 形杆拉向身体，将肩胛骨挤压在一起。", "在动作的最高点停顿片刻，然后慢慢释放张力，回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "shoulders"], "instructions_zh_hant": ["面對電纜機站立，雙腳與肩同寬。", "正手握住 V 形桿附件，手掌朝下。", "保持背部挺直，核心肌群參與。", "將 V 形桿拉向身體，將肩胛骨擠壓在一起。", "在動作的最高點停頓片刻，然后慢慢釋放張力，回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0235', 'exercise', 1, '{"id": "0235", "target": "delts", "name_en": "cable standing shoulder external rotation", "name_zh": "绳索站姿肩部外旋", "body_part": "shoulders", "equipment": "cable", "gif_asset": "assets/fitness/videos/0235-FWdVhcW.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索站姿肩部外旋", "instructions_en": ["Stand with your feet shoulder-width apart and your knees slightly bent.", "Hold the cable handle with your arm extended in front of you, parallel to the ground.", "Keep your elbow slightly bent and your shoulder blades pulled back.", "Slowly rotate your arm outward, away from your body, while keeping your elbow in the same position.", "Pause for a moment at the end of the movement, then slowly return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，膝盖稍微弯曲。", "将手臂伸向前方，与地面平行，握住电缆手柄。", "保持肘部稍微弯曲，肩胛骨向后拉。", "慢慢地向外旋转手臂，远离身体，同时保持肘部处于同一位置。", "动作结束时暂停片刻，然后慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["rotator cuff", "trapezius"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，膝蓋稍微彎曲。", "將手臂伸向前方，與地面平行，握住電纜手柄。", "保持肘部稍微彎曲，肩胛骨向后拉。", "慢慢地向外旋轉手臂，遠離身體，同時保持肘部處于同一位置。", "動作結束時暫停片刻，然后慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0236', 'exercise', 1, '{"id": "0236", "target": "upper back", "name_en": "cable standing twist row (v-bar)", "name_zh": "绳索站姿转体划船（V形把手）", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/0236-JOZhu2h.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索站姿轉體劃船（V形把手）", "instructions_en": ["Attach a v-bar attachment to a cable machine at chest height.", "Stand facing the cable machine with your feet shoulder-width apart.", "Grasp the v-bar with an overhand grip, palms facing down.", "Take a step back to create tension in the cable.", "Keep your back straight and core engaged throughout the exercise.", "Pull the v-bar towards your torso by retracting your shoulder blades and bending your elbows.", "As you pull, twist your torso to one side, squeezing your shoulder blades together.", "Pause for a moment at the top of the movement, feeling the contraction in your upper back.", "Slowly release the tension and return to the starting position, untwisting your torso.", "Repeat the movement for the desired number of repetitions, alternating the twisting direction with each rep."], "instructions_zh": ["将 V 形杆附件连接到胸部高度的缆绳机上。", "面对电缆机站立，双脚与肩同宽。", "正手握住 V 形杆，手掌朝下。", "后退一步以在电缆中产生张力。", "在整个练习过程中保持背部挺直并保持核心参与。", "缩回肩胛骨并弯曲肘部，将 V 形杆拉向躯干。", "当你拉的时候，将你的躯干扭转到一侧，将肩胛骨挤压在一起。", "在动作的最高点暂停片刻，感受上背部的收缩。", "慢慢释放紧张并回到起始位置，松开躯干。", "重复该动作达到所需的重复次数，每次重复交替扭转方向。"], "secondary_muscles": ["biceps", "shoulders"], "instructions_zh_hant": ["將 V 形桿附件連接到胸部高度的纜繩機上。", "面對電纜機站立，雙腳與肩同寬。", "正手握住 V 形桿，手掌朝下。", "后退一步以在電纜中產生張力。", "在整個練習過程中保持背部挺直并保持核心參與。", "縮回肩胛骨并彎曲肘部，將 V 形桿拉向軀幹。", "當你拉的時候，將你的軀幹扭轉到一側，將肩胛骨擠壓在一起。", "在動作的最高點暫停片刻，感受上背部的收縮。", "慢慢釋放緊張并回到起始位置，松開軀幹。", "重復該動作達到所需的重復次數，每次重復交替扭轉方向。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1269', 'exercise', 1, '{"id": "1269", "target": "pectorals", "name_en": "cable standing up straight crossovers", "name_zh": "绳索站姿低位向上夹胸", "body_part": "chest", "equipment": "cable", "gif_asset": "assets/fitness/videos/1269-UKWTJWR.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索站姿低位向上夾胸", "instructions_en": ["Stand in the middle of a cable machine with your feet shoulder-width apart.", "Hold the handles of the cables with your palms facing down and your arms extended straight out to the sides.", "Keeping your arms straight, bring your hands together in front of your body, crossing them over each other.", "Pause for a moment, then slowly return to the starting position, keeping your arms extended.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站在缆绳机中间，双脚分开与肩同宽。", "手掌朝下握住电缆手柄，手臂伸直至两侧。", "保持双臂伸直，将双手放在身体前面，相互交叉。", "暂停片刻，然后慢慢回到起始位置，保持双臂伸展。", "重复所需的重复次数。"], "secondary_muscles": ["deltoids", "triceps"], "instructions_zh_hant": ["站在纜繩機中間，雙腳分開與肩同寬。", "手掌朝下握住電纜手柄，手臂伸直至兩側。", "保持雙臂伸直，將雙手放在身體前面，相互交叉。", "暫停片刻，然后慢慢回到起始位置，保持雙臂伸展。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0238', 'exercise', 1, '{"id": "0238", "target": "lats", "name_en": "cable straight arm pulldown", "name_zh": "绳索直臂下拉", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/0238-x69MAlq.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索直臂下拉", "instructions_en": ["Attach a straight bar to the high pulley of a cable machine.", "Stand facing the machine with your feet shoulder-width apart.", "Grasp the bar with an overhand grip, keeping your arms straight and your palms facing down.", "Engage your lats and pull the bar down towards your thighs, keeping your arms straight throughout the movement.", "Pause for a moment at the bottom, then slowly return the bar to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将直杆连接到缆绳机的高滑轮上。", "面向机器站立，双脚分开与肩同宽。", "正手握住杠铃，保持手臂伸直，手掌朝下。", "收紧背阔肌并将杠铃向下拉向大腿，在整个运动过程中保持手臂伸直。", "在底部暂停片刻，然后慢慢地将杠铃返回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "biceps"], "instructions_zh_hant": ["將直桿連接到纜繩機的高滑輪上。", "面向機器站立，雙腳分開與肩同寬。", "正手握住杠鈴，保持手臂伸直，手掌朝下。", "收緊背闊肌并將杠鈴向下拉向大腿，在整個運動過程中保持手臂伸直。", "在底部暫停片刻，然后慢慢地將杠鈴返回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0237', 'exercise', 1, '{"id": "0237", "target": "lats", "name_en": "cable straight arm pulldown (with rope)", "name_zh": "绳索直臂下拉（配合绳索）", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/0237-DT14T9T.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索直臂下拉（配合繩索）", "instructions_en": ["Attach a rope to the cable machine at the highest setting.", "Stand facing the machine with your feet shoulder-width apart.", "Grasp the rope with both hands, palms facing down.", "Extend your arms fully in front of you, keeping your elbows slightly bent.", "Engage your lats and slowly pull the rope down towards your thighs, keeping your arms straight.", "Pause for a moment at the bottom, then slowly release the tension and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将绳索连接到最高设置的缆绳机上。", "面向机器站立，双脚分开与肩同宽。", "双手抓住绳子，掌心朝下。", "将手臂完全伸展到身前，保持肘部稍微弯曲。", "收紧背阔肌，慢慢地将绳子向下拉向大腿，保持手臂伸直。", "在底部停顿片刻，然后慢慢释放张力，回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["將繩索連接到最高設置的纜繩機上。", "面向機器站立，雙腳分開與肩同寬。", "雙手抓住繩子，掌心朝下。", "將手臂完全伸展到身前，保持肘部稍微彎曲。", "收緊背闊肌，慢慢地將繩子向下拉向大腿，保持手臂伸直。", "在底部停頓片刻，然后慢慢釋放張力，回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0239', 'exercise', 1, '{"id": "0239", "target": "upper back", "name_en": "cable straight back seated row", "name_zh": "绳索背部挺直坐姿划船", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/0239-Tq6gbK6.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索背部挺直坐姿劃船", "instructions_en": ["Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.", "Grasp the cable handles with an overhand grip, palms facing down.", "Keep your back straight and lean slightly forward from the hips.", "Pull the cable handles towards your body, squeezing your shoulder blades together.", "Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在电缆划船机上，双脚平放在脚踏板上，膝盖稍微弯曲。", "正手握住电缆手柄，手掌朝下。", "保持背部挺直，并从臀部稍微向前倾斜。", "将电缆手柄拉向身体，将肩胛骨挤压在一起。", "在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms", "shoulders"], "instructions_zh_hant": ["坐在電纜劃船機上，雙腳平放在腳踏板上，膝蓋稍微彎曲。", "正手握住電纜手柄，手掌朝下。", "保持背部挺直，并從臀部稍微向前傾斜。", "將電纜手柄拉向身體，將肩胛骨擠壓在一起。", "在動作的最高點暫停片刻，然后慢慢松開手柄回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0240', 'exercise', 1, '{"id": "0240", "target": "delts", "name_en": "cable supine reverse fly", "name_zh": "绳索仰卧反向飞鸟", "body_part": "shoulders", "equipment": "cable", "gif_asset": "assets/fitness/videos/0240-PQcUlDi.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索仰臥反向飛鳥", "instructions_en": ["Attach a D-handle to a low pulley cable machine and lie face down on a flat bench.", "Grasp the D-handle with each hand, palms facing down, and extend your arms straight out in front of you.", "Keeping your arms straight, raise them out to the sides until they are parallel to the floor.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将 D 形手柄连接到低滑轮缆绳机上，并面朝下躺在平凳上。", "每只手握住 D 形手柄，手掌朝下，并将双臂伸直至前方。", "保持手臂伸直，将它们向两侧举起，直到与地板平行。", "在顶部暂停片刻，然后慢慢将手臂放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["trapezius", "rhomboids"], "instructions_zh_hant": ["將 D 形手柄連接到低滑輪纜繩機上，并面朝下躺在平凳上。", "每只手握住 D 形手柄，手掌朝下，并將雙臂伸直至前方。", "保持手臂伸直，將它們向兩側舉起，直到與地板平行。", "在頂部暫停片刻，然后慢慢將手臂放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2464', 'exercise', 1, '{"id": "2464", "target": "lats", "name_en": "cable thibaudeau kayak row", "name_zh": "绳索蒂博多皮划艇式划船", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/2464-ZgwWBoC.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索蒂博多皮劃艇式劃船", "instructions_en": ["Attach a cable handle to a low pulley and sit facing the machine with your feet flat on the floor.", "Grasp the handle with your right hand and extend your arm fully, keeping a slight bend in your elbow.", "Lean forward from your hips, keeping your back straight and your abs engaged.", "Pull the handle towards your torso by retracting your shoulder blade and bending your elbow, keeping your arm close to your body.", "Squeeze your back muscles at the top of the movement, then slowly return to the starting position.", "Repeat for the desired number of repetitions, then switch sides and perform with your left arm."], "instructions_zh": ["将电缆手柄连接到低滑轮上，面向机器坐着，双脚平放在地板上。", "用右手抓住手柄，完全伸展手臂，保持肘部轻微弯曲。", "从臀部开始向前倾斜，保持背部挺直并收紧腹肌。", "缩回肩胛骨并弯曲肘部，将手柄拉向躯干，保持手臂靠近身体。", "在动作的最高点挤压背部肌肉，然后慢慢回到起始位置。", "重复所需的重复次数，然后换边并用左臂执行。"], "secondary_muscles": ["biceps", "rhomboids", "rear deltoids"], "instructions_zh_hant": ["將電纜手柄連接到低滑輪上，面向機器坐著，雙腳平放在地板上。", "用右手抓住手柄，完全伸展手臂，保持肘部輕微彎曲。", "從臀部開始向前傾斜，保持背部挺直并收緊腹肌。", "縮回肩胛骨并彎曲肘部，將手柄拉向軀幹，保持手臂靠近身體。", "在動作的最高點擠壓背部肌肉，然后慢慢回到起始位置。", "重復所需的重復次數，然后換邊并用左臂執行。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0241', 'exercise', 1, '{"id": "0241", "target": "triceps", "name_en": "cable triceps pushdown (v-bar)", "name_zh": "绳索肱三头肌下压（V形把手）", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/0241-gAwDzB3.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索肱三頭肌下壓（V形把手）", "instructions_en": ["Attach a v-bar attachment to the cable machine at the highest setting.", "Stand facing the cable machine with your feet shoulder-width apart.", "Grasp the v-bar with an overhand grip, palms facing down, and your hands shoulder-width apart.", "Keep your elbows close to your sides and your upper arms stationary throughout the exercise.", "Engage your triceps and exhale as you push the v-bar down until your arms are fully extended.", "Pause for a moment at the bottom of the movement, squeezing your triceps.", "Inhale as you slowly return the v-bar to the starting position, maintaining control.", "Repeat for the desired number of repetitions."], "instructions_zh": ["在最高设置下将 V 形杆附件连接到电缆机上。", "面对电缆机站立，双脚与肩同宽。", "正手握住 V 形杆，手掌朝下，双手与肩同宽。", "在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。", "收紧三头肌并呼气，同时向下推 V 形杆，直到手臂完全伸展。", "在动作的底部暂停片刻，挤压你的三头肌。", "吸气，同时缓慢地将 V 形杆返回到起始位置，保持控制。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["在最高設置下將 V 形桿附件連接到電纜機上。", "面對電纜機站立，雙腳與肩同寬。", "正手握住 V 形桿，手掌朝下，雙手與肩同寬。", "在整個練習過程中，保持肘部靠近身體兩側，上臂保持靜止。", "收緊三頭肌并呼氣，同時向下推 V 形桿，直到手臂完全伸展。", "在動作的底部暫停片刻，擠壓你的三頭肌。", "吸氣，同時緩慢地將 V 形桿返回到起始位置，保持控制。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2405', 'exercise', 1, '{"id": "2405", "target": "triceps", "name_en": "cable triceps pushdown (v-bar) (with arm blaster)", "name_zh": "绳索肱三头肌下压（V形把手）（配合弯举护板）", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/2405-OxJk1fg.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索肱三頭肌下壓（V形把手）（配合彎舉護板）", "instructions_en": ["Attach a v-bar attachment to the cable machine at the highest setting.", "Stand facing the cable machine with your feet shoulder-width apart.", "Grasp the v-bar with an overhand grip, palms facing down, and your hands shoulder-width apart.", "Keep your elbows close to your sides and your upper arms stationary throughout the exercise.", "Engage your triceps and exhale as you push the v-bar down until your arms are fully extended.", "Pause for a moment at the bottom of the movement, squeezing your triceps.", "Inhale as you slowly return the v-bar to the starting position, maintaining control.", "Repeat for the desired number of repetitions."], "instructions_zh": ["在最高设置下将 V 形杆附件连接到电缆机上。", "面对电缆机站立，双脚与肩同宽。", "正手握住 V 形杆，手掌朝下，双手与肩同宽。", "在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。", "收紧三头肌并呼气，同时向下推 V 形杆，直到手臂完全伸展。", "在动作的底部暂停片刻，挤压你的三头肌。", "吸气，同时缓慢地将 V 形杆返回到起始位置，保持控制。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["在最高設置下將 V 形桿附件連接到電纜機上。", "面對電纜機站立，雙腳與肩同寬。", "正手握住 V 形桿，手掌朝下，雙手與肩同寬。", "在整個練習過程中，保持肘部靠近身體兩側，上臂保持靜止。", "收緊三頭肌并呼氣，同時向下推 V 形桿，直到手臂完全伸展。", "在動作的底部暫停片刻，擠壓你的三頭肌。", "吸氣，同時緩慢地將 V 形桿返回到起始位置，保持控制。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0242', 'exercise', 1, '{"id": "0242", "target": "abs", "name_en": "cable tuck reverse crunch", "name_zh": "绳索团身反向卷腹", "body_part": "waist", "equipment": "cable", "gif_asset": "assets/fitness/videos/0242-TXtXc84.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索團身反向卷腹", "instructions_en": ["Attach a cable to a low pulley and lie down on a mat facing up.", "Hold the cable with both hands and extend your arms straight up above your chest.", "Bend your knees and lift your legs up, bringing your knees towards your chest.", "At the same time, curl your pelvis up towards your chest, lifting your hips off the ground.", "Pause for a moment at the top, then slowly lower your legs and hips back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将电缆连接到低滑轮上，然后面朝上躺在垫子上。", "用双手握住电缆并将双臂伸直至胸部上方。", "弯曲膝盖并抬起双腿，使膝盖靠近胸部。", "同时，将骨盆向胸部弯曲，将臀部抬离地面。", "在顶部暂停片刻，然后慢慢降低双腿和臀部回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["將電纜連接到低滑輪上，然后面朝上躺在墊子上。", "用雙手握住電纜并將雙臂伸直至胸部上方。", "彎曲膝蓋并抬起雙腿，使膝蓋靠近胸部。", "同時，將骨盆向胸部彎曲，將臀部抬離地面。", "在頂部暫停片刻，然后慢慢降低雙腿和臀部回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0243', 'exercise', 1, '{"id": "0243", "target": "abs", "name_en": "cable twist", "name_zh": "绳索转体", "body_part": "waist", "equipment": "cable", "gif_asset": "assets/fitness/videos/0243-aVs3BR3.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索轉體", "instructions_en": ["Stand with your feet shoulder-width apart, facing the cable machine.", "Hold the cable handle with both hands in front of your chest, keeping your arms slightly bent.", "Engage your core and twist your torso to the right, pulling the cable across your body.", "Pause for a moment at the end of the movement, feeling the contraction in your abs and obliques.", "Slowly return to the starting position, resisting the cable''s pull.", "Repeat the movement to the left side.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，面向绳索机。", "双手握住电缆手柄于胸前，保持双臂略微弯曲。", "启动你的核心并将你的躯干向右扭转，将电缆拉过你的身体。", "动作结束时暂停片刻，感受腹肌和斜肌的收缩。", "缓慢返回起始位置，抵抗绳索的拉力。", "向左侧重复该动作。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["obliques"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，面向繩索機。", "雙手握住電纜手柄于胸前，保持雙臂略微彎曲。", "啟動你的核心并將你的軀幹向右扭轉，將電纜拉過你的身體。", "動作結束時暫停片刻，感受腹肌和斜肌的收縮。", "緩慢返回起始位置，抵抗繩索的拉力。", "向左側重復該動作。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0862', 'exercise', 1, '{"id": "0862", "target": "abs", "name_en": "cable twist (up-down)", "name_zh": "绳索转体（上下交替）", "body_part": "waist", "equipment": "cable", "gif_asset": "assets/fitness/videos/0862-fhZQPlV.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索轉體（上下交替）", "instructions_en": ["Stand with your feet shoulder-width apart, facing the cable machine.", "Hold the cable handle with both hands in front of your chest, keeping your arms slightly bent.", "Engage your core and slowly rotate your torso to one side, keeping your hips and legs stable.", "Pause for a moment at the end of the rotation, then slowly return to the starting position.", "Repeat the rotation to the opposite side.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，面向绳索机。", "双手握住电缆手柄于胸前，保持双臂略微弯曲。", "启动你的核心并慢慢地将你的躯干旋转到一侧，保持你的臀部和腿部稳定。", "旋转结束时暂停片刻，然后慢慢回到起始位置。", "向另一侧重复旋转。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["obliques", "lower back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，面向繩索機。", "雙手握住電纜手柄于胸前，保持雙臂略微彎曲。", "啟動你的核心并慢慢地將你的軀幹旋轉到一側，保持你的臀部和腿部穩定。", "旋轉結束時暫停片刻，然后慢慢回到起始位置。", "向另一側重復旋轉。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0244', 'exercise', 1, '{"id": "0244", "target": "lats", "name_en": "cable twisting pull", "name_zh": "绳索转体拉", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/0244-zCgxPbV.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索轉體拉", "instructions_en": ["Attach a cable handle to a low pulley and stand facing the machine.", "Grasp the handle with your left hand and step away from the machine, extending your arm fully.", "Position your feet shoulder-width apart, with your knees slightly bent.", "Keep your back straight and your core engaged throughout the exercise.", "Pull the handle towards your body, rotating your torso to the right as you do so.", "Squeeze your back muscles at the end of the movement.", "Slowly return to the starting position, keeping tension on the cable.", "Repeat for the desired number of repetitions, then switch sides and perform with your right hand."], "instructions_zh": ["将电缆手柄连接到低滑轮上并面向机器站立。", "用左手抓住手柄，离开机器，完全伸展手臂。", "双脚分开与肩同宽，膝盖稍微弯曲。", "在整个练习过程中保持背部挺直，核心肌群参与其中。", "将手柄拉向您的身体，同时将您的躯干向右旋转。", "动作结束时挤压背部肌肉。", "慢慢回到起始位置，保持绳索的张力。", "重复所需的重复次数，然后换边并用右手执行。"], "secondary_muscles": ["shoulders", "biceps"], "instructions_zh_hant": ["將電纜手柄連接到低滑輪上并面向機器站立。", "用左手抓住手柄，離開機器，完全伸展手臂。", "雙腳分開與肩同寬，膝蓋稍微彎曲。", "在整個練習過程中保持背部挺直，核心肌群參與其中。", "將手柄拉向您的身體，同時將您的軀幹向右旋轉。", "動作結束時擠壓背部肌肉。", "慢慢回到起始位置，保持繩索的張力。", "重復所需的重復次數，然后換邊并用右手執行。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0246', 'exercise', 1, '{"id": "0246", "target": "delts", "name_en": "cable upright row", "name_zh": "绳索直立划船", "body_part": "shoulders", "equipment": "cable", "gif_asset": "assets/fitness/videos/0246-cALKspW.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索直立劃船", "instructions_en": ["Stand with your feet shoulder-width apart, knees slightly bent, and hold the cable attachment with an overhand grip.", "Keep your back straight and your core engaged throughout the exercise.", "Pull the cable attachment straight up towards your chin, leading with your elbows.", "Pause for a moment at the top, squeezing your shoulder blades together.", "Slowly lower the cable attachment back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，膝盖稍微弯曲，并用正手握住电缆附件。", "在整个练习过程中保持背部挺直，核心肌群参与其中。", "用肘部引导，将电缆附件笔直向上拉向下巴。", "在顶部暂停片刻，将肩胛骨挤压在一起。", "缓慢地将电缆附件放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["traps", "biceps"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，膝蓋稍微彎曲，并用正手握住電纜附件。", "在整個練習過程中保持背部挺直，核心肌群參與其中。", "用肘部引導，將電纜附件筆直向上拉向下巴。", "在頂部暫停片刻，將肩胛骨擠壓在一起。", "緩慢地將電纜附件放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1645', 'exercise', 1, '{"id": "1645", "target": "biceps", "name_en": "cable two arm curl on incline bench", "name_zh": "绳索双臂弯举于上斜凳上", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/1645-H9y3Dkr.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索雙臂彎舉于上斜凳上", "instructions_en": ["Sit on an incline bench with your back against the pad and your feet flat on the ground.", "Grasp the cable handles with an underhand grip, palms facing up, and your arms fully extended.", "Keeping your upper arms stationary, exhale and curl the handles towards your shoulders while contracting your biceps.", "Pause for a moment at the top of the movement, squeezing your biceps.", "Inhale and slowly lower the handles back to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在倾斜的长凳上，背部靠在垫子上，双脚平放在地面上。", "反手握住电缆手柄，手掌朝上，手臂完全伸展。", "保持上臂静止，呼气并将手柄向肩膀弯曲，同时收缩二头肌。", "在动作的最高点暂停片刻，挤压你的二头肌。", "吸气，慢慢将手柄放回起始位置，充分伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在傾斜的長凳上，背部靠在墊子上，雙腳平放在地面上。", "反手握住電纜手柄，手掌朝上，手臂完全伸展。", "保持上臂靜止，呼氣并將手柄向肩膀彎曲，同時收縮二頭肌。", "在動作的最高點暫停片刻，擠壓你的二頭肌。", "吸氣，慢慢將手柄放回起始位置，充分伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1728', 'exercise', 1, '{"id": "1728", "target": "triceps", "name_en": "cable two arm tricep kickback", "name_zh": "绳索双臂肱三头肌臂后屈伸", "body_part": "upper arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/1728-vvNjDJS.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索雙臂肱三頭肌臂后屈伸", "instructions_en": ["Stand with your feet shoulder-width apart and knees slightly bent.", "Hold the cable handle in each hand with your palms facing inwards and your arms bent at a 90-degree angle.", "Keeping your upper arms stationary, extend your forearms backwards until your arms are fully extended.", "Pause for a moment, then slowly return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站立，双脚分开与肩同宽，膝盖稍微弯曲。", "双手握住电缆手柄，手掌朝内，手臂弯曲成 90 度角。", "保持上臂静止，向后伸展前臂，直到手臂完全伸展。", "暂停片刻，然后慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["站立，雙腳分開與肩同寬，膝蓋稍微彎曲。", "雙手握住電纜手柄，手掌朝內，手臂彎曲成 90 度角。", "保持上臂靜止，向后伸展前臂，直到手臂完全伸展。", "暫停片刻，然后慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0245', 'exercise', 1, '{"id": "0245", "target": "lats", "name_en": "cable underhand pulldown", "name_zh": "绳索反握下拉", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/0245-xBYcQHj.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索反握下拉", "instructions_en": ["Adjust the cable machine so that the pulldown bar is at a height above your head.", "Sit down on the seat and grab the pulldown bar with an underhand grip, hands slightly wider than shoulder-width apart.", "Keep your back straight and lean back slightly.", "Pull the bar down towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整缆绳机，使下拉杆位于您头部上方的高度。", "坐在座椅上，用反手抓住下拉杆，双手分开的距离略大于肩宽。", "保持背部挺直并稍微向后倾斜。", "将杠铃向下拉向胸部，将肩胛骨挤压在一起。", "在动作底部暂停片刻，然后慢慢将杠铃释放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["調整纜繩機，使下拉桿位于您頭部上方的高度。", "坐在座椅上，用反手抓住下拉桿，雙手分開的距離略大于肩寬。", "保持背部挺直并稍微向后傾斜。", "將杠鈴向下拉向胸部，將肩胛骨擠壓在一起。", "在動作底部暫停片刻，然后慢慢將杠鈴釋放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1270', 'exercise', 1, '{"id": "1270", "target": "pectorals", "name_en": "cable upper chest crossovers", "name_zh": "绳索上胸夹胸", "body_part": "chest", "equipment": "cable", "gif_asset": "assets/fitness/videos/1270-j7XMAyn.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索上胸夾胸", "instructions_en": ["Attach the handles to the cables at chest height.", "Stand in the center of the cable machine with one foot slightly in front of the other.", "Grasp the handles with your palms facing down and your arms extended out to the sides.", "Keep a slight bend in your elbows and engage your core.", "Pull the cables together in front of your chest, crossing them over each other.", "Squeeze your chest muscles at the peak of the movement.", "Slowly release the cables back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将手柄连接到胸部高度的电缆上。", "站在绳索机的中央，一只脚稍微在另一只脚前面。", "手掌朝下抓住手柄，手臂向两侧伸展。", "保持肘部轻微弯曲并启动核心肌群。", "将电缆在胸前拉到一起，使它们相互交叉。", "在运动的最高点挤压胸部肌肉。", "慢慢地将电缆释放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["deltoids", "triceps"], "instructions_zh_hant": ["將手柄連接到胸部高度的電纜上。", "站在繩索機的中央，一只腳稍微在另一只腳前面。", "手掌朝下抓住手柄，手臂向兩側伸展。", "保持肘部輕微彎曲并啟動核心肌群。", "將電纜在胸前拉到一起，使它們相互交叉。", "在運動的最高點擠壓胸部肌肉。", "慢慢地將電纜釋放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1324', 'exercise', 1, '{"id": "1324", "target": "upper back", "name_en": "cable upper row", "name_zh": "绳索上部划船", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/1324-PQStVXH.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索上部劃船", "instructions_en": ["Attach a straight bar to a cable machine at chest height.", "Stand facing the machine with your feet shoulder-width apart.", "Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.", "Keep your back straight and your core engaged.", "Pull the bar towards your upper chest, squeezing your shoulder blades together.", "Pause for a moment at the top of the movement.", "Slowly release the bar back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将直杆连接到胸部高度的缆绳机上。", "面向机器站立，双脚分开与肩同宽。", "正手握住杠铃，双手距离略宽于肩宽。", "保持背部挺直，核心肌群参与。", "将杠铃拉向上胸部，将肩胛骨挤压在一起。", "在动作的最高点停顿片刻。", "慢慢地将杠铃释放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "shoulders"], "instructions_zh_hant": ["將直桿連接到胸部高度的纜繩機上。", "面向機器站立，雙腳分開與肩同寬。", "正手握住杠鈴，雙手距離略寬于肩寬。", "保持背部挺直，核心肌群參與。", "將杠鈴拉向上胸部，將肩胛骨擠壓在一起。", "在動作的最高點停頓片刻。", "慢慢地將杠鈴釋放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1325', 'exercise', 1, '{"id": "1325", "target": "lats", "name_en": "cable wide grip rear pulldown behind neck", "name_zh": "绳索宽握颈后下拉", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/1325-CmEr4pM.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索寬握頸后下拉", "instructions_en": ["Adjust the cable machine so that the pulldown bar is at a height above your head.", "Sit down on the seat and grab the pulldown bar with a wide overhand grip.", "Keep your back straight and your chest up as you lean back slightly.", "Pull the bar down towards your upper chest, squeezing your shoulder blades together.", "Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整缆绳机，使下拉杆位于您头部上方的高度。", "坐在座椅上，用宽的正手握法抓住下拉杆。", "稍微向后倾斜时，保持背部挺直，挺胸。", "将杠铃向下拉至上胸部，将肩胛骨挤压在一起。", "在动作底部暂停片刻，然后慢慢将杠铃释放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "rhomboids", "rear deltoids"], "instructions_zh_hant": ["調整纜繩機，使下拉桿位于您頭部上方的高度。", "坐在座椅上，用寬的正手握法抓住下拉桿。", "稍微向后傾斜時，保持背部挺直，挺胸。", "將杠鈴向下拉至上胸部，將肩胛骨擠壓在一起。", "在動作底部暫停片刻，然后慢慢將杠鈴釋放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0247', 'exercise', 1, '{"id": "0247", "target": "forearms", "name_en": "cable wrist curl", "name_zh": "绳索腕弯举", "body_part": "lower arms", "equipment": "cable", "gif_asset": "assets/fitness/videos/0247-LrV4s90.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索腕彎舉", "instructions_en": ["Attach a straight bar to a low pulley cable machine.", "Stand facing the machine with your feet shoulder-width apart.", "Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.", "Rest your forearms on a bench or pad, with your wrists hanging off the edge.", "Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.", "Pause for a moment at the top, then inhale and slowly lower the bar back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将直杆连接到低滑轮电缆机上。", "面向机器站立，双脚分开与肩同宽。", "反手握住杠铃，手掌朝上，双手与肩同宽。", "将前臂放在长凳或垫子上，手腕悬在边缘上。", "保持前臂静止，呼气并尽可能向上弯曲手腕。", "在顶部暂停片刻，然后吸气并慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "brachialis"], "instructions_zh_hant": ["將直桿連接到低滑輪電纜機上。", "面向機器站立，雙腳分開與肩同寬。", "反手握住杠鈴，手掌朝上，雙手與肩同寬。", "將前臂放在長凳或墊子上，手腕懸在邊緣上。", "保持前臂靜止，呼氣并盡可能向上彎曲手腕。", "在頂部暫停片刻，然后吸氣并慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1407', 'exercise', 1, '{"id": "1407", "target": "calves", "name_en": "calf push stretch with hands against wall", "name_zh": "扶墙小腿推伸", "body_part": "lower legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1407-PzNxakt.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "扶墻小腿推伸", "instructions_en": ["Stand facing a wall with your feet hip-width apart.", "Place your hands against the wall at shoulder height.", "Step back with one foot, keeping your heel on the ground and your leg straight.", "Bend your front knee slightly and lean forward, feeling a stretch in your calf.", "Hold the stretch for 20-30 seconds.", "Switch legs and repeat the stretch."], "instructions_zh": ["面向墙壁站立，双脚分开与臀部同宽。", "将双手靠在墙上，与肩同高。", "一只脚向后退一步，脚跟保持在地面上，腿伸直。", "稍微弯曲前膝盖并向前倾斜，感觉小腿有拉伸感。", "保持拉伸 20-30 秒。", "换腿并重复拉伸。"], "secondary_muscles": ["hamstrings"], "instructions_zh_hant": ["面向墻壁站立，雙腳分開與臀部同寬。", "將雙手靠在墻上，與肩同高。", "一只腳向后退一步，腳跟保持在地面上，腿伸直。", "稍微彎曲前膝蓋并向前傾斜，感覺小腿有拉伸感。", "保持拉伸 20-30 秒。", "換腿并重復拉伸。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1377', 'exercise', 1, '{"id": "1377", "target": "calves", "name_en": "calf stretch with hands against wall", "name_zh": "扶墙小腿拉伸", "body_part": "lower legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1377-m0tCHqc.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "扶墻小腿拉伸", "instructions_en": ["Stand facing a wall with your feet hip-width apart.", "Place your hands against the wall at shoulder height.", "Step your right foot back, keeping your heel on the ground and your leg straight.", "Bend your left knee and lean forward, keeping your back leg straight and your heel on the ground.", "Hold the stretch for 20-30 seconds.", "Switch legs and repeat the stretch."], "instructions_zh": ["面向墙壁站立，双脚分开与臀部同宽。", "将双手靠在墙上，与肩同高。", "右脚向后退一步，保持脚后跟着地，腿伸直。", "弯曲左膝并向前倾斜，保持后腿伸直，脚后跟着地。", "保持拉伸 20-30 秒。", "换腿并重复拉伸。"], "secondary_muscles": ["hamstrings"], "instructions_zh_hant": ["面向墻壁站立，雙腳分開與臀部同寬。", "將雙手靠在墻上，與肩同高。", "右腳向后退一步，保持腳后跟著地，腿伸直。", "彎曲左膝并向前傾斜，保持后腿伸直，腳后跟著地。", "保持拉伸 20-30 秒。", "換腿并重復拉伸。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1548', 'exercise', 1, '{"id": "1548", "target": "quads", "name_en": "chair leg extended stretch", "name_zh": "椅上直腿拉伸", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1548-xGgAGPm.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "椅上直腿拉伸", "instructions_en": ["Sit on the edge of a chair with your back straight and feet flat on the ground.", "Extend one leg straight out in front of you, keeping your heel on the ground.", "Lean forward slightly, feeling a stretch in your quadriceps.", "Hold this position for 20-30 seconds.", "Switch legs and repeat the stretch."], "instructions_zh": ["坐在椅子边缘，背部挺直，双脚平放在地面上。", "将一只腿伸直在身前，脚跟保持在地面上。", "稍微向前倾，感受股四头肌的拉伸。", "保持这个姿势20-30秒。", "换腿并重复拉伸。"], "secondary_muscles": ["hamstrings", "calves"], "instructions_zh_hant": ["坐在椅子邊緣，背部挺直，雙腳平放在地面上。", "將一只腿伸直在身前，腳跟保持在地面上。", "稍微向前傾，感受股四頭肌的拉伸。", "保持這個姿勢20-30秒。", "換腿并重復拉伸。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1378', 'exercise', 1, '{"id": "1378", "target": "calves", "name_en": "calf stretch with rope", "name_zh": "绳带辅助小腿拉伸", "body_part": "lower legs", "equipment": "rope", "gif_asset": "assets/fitness/videos/1378-1LVFcEn.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩帶輔助小腿拉伸", "instructions_en": ["Stand facing a wall or sturdy object with your feet hip-width apart.", "Hold the ends of the rope in each hand and place the middle of the rope around the ball of your right foot.", "Step back with your left foot, keeping your heel on the ground and your leg straight.", "Lean forward, keeping your back straight, and gently pull on the rope to stretch your calf.", "Hold the stretch for 20-30 seconds, then release.", "Repeat on the other leg."], "instructions_zh": ["面向墙壁或坚固物体站立，双脚分开与臀部同宽。", "双手握住绳子的两端，将绳子的中间放在右脚掌周围。", "左脚向后退一步，脚跟保持在地面上，腿伸直。", "身体前倾，保持背部挺直，轻轻拉动绳子以伸展小腿。", "保持拉伸 20-30 秒，然后放松。", "在另一条腿上重复。"], "secondary_muscles": ["hamstrings"], "instructions_zh_hant": ["面向墻壁或堅固物體站立，雙腳分開與臀部同寬。", "雙手握住繩子的兩端，將繩子的中間放在右腳掌周圍。", "左腳向后退一步，腳跟保持在地面上，腿伸直。", "身體前傾，保持背部挺直，輕輕拉動繩子以伸展小腿。", "保持拉伸 20-30 秒，然后放松。", "在另一條腿上重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0253', 'exercise', 1, '{"id": "0253", "target": "upper back", "name_en": "chin-ups (narrow parallel grip)", "name_zh": "窄距对握引体向上", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0253-G70mEAJ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "窄距對握引體向上", "instructions_en": ["Hang from a pull-up bar with a narrow parallel grip, palms facing towards you.", "Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.", "Continue pulling until your chin is above the bar.", "Pause for a moment at the top, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["用狭窄的平行握距悬挂在引体向上杆上，手掌朝向您。", "收紧背部肌肉，将身体拉向杠铃杆，保持肘部靠近身体。", "继续拉，直到下巴位于杠铃上方。", "在顶部停顿片刻，然后慢慢将身体放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["用狹窄的平行握距懸掛在引體向上桿上，手掌朝向您。", "收緊背部肌肉，將身體拉向杠鈴桿，保持肘部靠近身體。", "繼續拉，直到下巴位于杠鈴上方。", "在頂部停頓片刻，然后慢慢將身體放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0248', 'exercise', 1, '{"id": "0248", "target": "upper back", "name_en": "cambered bar lying row", "name_zh": "弯杆俯卧划船", "body_part": "back", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0248-R5swFnc.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "彎桿俯臥劃船", "instructions_en": ["Set up a barbell on the floor and lie face down on a bench with your chest just off the edge.", "Reach down and grab the barbell with an overhand grip, slightly wider than shoulder-width apart.", "With your legs straight and feet on the ground, lift the barbell off the floor by extending your arms.", "Pull the barbell towards your chest, squeezing your shoulder blades together.", "Lower the barbell back down to the starting position and repeat for the desired number of repetitions."], "instructions_zh": ["在地板上放一个杠铃，脸朝下躺在长凳上，胸部刚好离开边缘。", "向下伸手，正手抓住杠铃，距离略宽于肩宽。", "双腿伸直，双脚着地，伸展双臂，将杠铃提离地面。", "将杠铃拉向胸部，将肩胛骨挤压在一起。", "将杠铃放回起始位置，然后重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["在地板上放一個杠鈴，臉朝下躺在長凳上，胸部剛好離開邊緣。", "向下伸手，正手抓住杠鈴，距離略寬于肩寬。", "雙腿伸直，雙腳著地，伸展雙臂，將杠鈴提離地面。", "將杠鈴拉向胸部，將肩胛骨擠壓在一起。", "將杠鈴放回起始位置，然后重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2963', 'exercise', 1, '{"id": "2963", "target": "abs", "name_en": "captains chair straight leg raise", "name_zh": "船长椅直腿举腿", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/2963-weoDEpH.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "船長椅直腿舉腿", "instructions_en": ["Sit on the captain''s chair with your back against the backrest and your forearms resting on the arm pads.", "Keep your upper body stable and your back straight.", "Engage your abs and lift your legs up in front of you, keeping them straight.", "Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在船长椅上，背部靠在靠背上，前臂放在扶手垫上。", "保持上半身稳定，背部挺直。", "收紧腹肌并将双腿抬起到身前，保持伸直。", "继续抬起，直到双腿与地面平行或达到您可以舒适地达到的高度。", "在顶部暂停片刻，然后慢慢将双腿放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["坐在船長椅上，背部靠在靠背上，前臂放在扶手墊上。", "保持上半身穩定，背部挺直。", "收緊腹肌并將雙腿抬起到身前，保持伸直。", "繼續抬起，直到雙腿與地面平行或達到您可以舒適地達到的高度。", "在頂部暫停片刻，然后慢慢將雙腿放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1271', 'exercise', 1, '{"id": "1271", "target": "pectorals", "name_en": "chest and front of shoulder stretch", "name_zh": "胸肌与肩前束拉伸", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1271-Uto7l43.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "胸肌與肩前束拉伸", "instructions_en": ["Stand tall with your feet shoulder-width apart.", "Extend your arms straight out in front of you at shoulder height.", "Cross your arms in front of your body, with your right arm on top of your left arm.", "Interlace your fingers and press your palms together.", "Gently squeeze your shoulder blades together and push your hands forward, feeling a stretch in your chest and front of your shoulders.", "Hold the stretch for 20-30 seconds, then release.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站直，双脚分开与肩同宽。", "将双臂伸直至前方，与肩同高。", "双臂交叉在身体前方，右臂放在左臂上方。", "手指交叉并将手掌压在一起。", "轻轻地将肩胛骨挤压在一起，然后将双手向前推，感觉胸部和肩膀前部有拉伸感。", "保持拉伸 20-30 秒，然后放松。", "重复所需的重复次数。"], "secondary_muscles": ["deltoids"], "instructions_zh_hant": ["站直，雙腳分開與肩同寬。", "將雙臂伸直至前方，與肩同高。", "雙臂交叉在身體前方，右臂放在左臂上方。", "手指交叉并將手掌壓在一起。", "輕輕地將肩胛骨擠壓在一起，然后將雙手向前推，感覺胸部和肩膀前部有拉伸感。", "保持拉伸 20-30 秒，然后放松。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0251', 'exercise', 1, '{"id": "0251", "target": "pectorals", "name_en": "chest dip", "name_zh": "双杠臂屈伸（偏胸）", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0251-9WTm7dq.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "雙槓臂屈伸（偏胸）", "instructions_en": ["Position yourself on parallel bars with your arms fully extended and your body straight.", "Lower your body by bending your elbows until your shoulders are below your elbows.", "Push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将自己置于双杠上，双臂完全伸展，身体伸直。", "弯曲肘部，降低身体，直到肩膀低于肘部。", "伸直手臂，将自己推回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["將自己置于雙杠上，雙臂完全伸展，身體伸直。", "彎曲肘部，降低身體，直到肩膀低于肘部。", "伸直手臂，將自己推回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1430', 'exercise', 1, '{"id": "1430", "target": "pectorals", "name_en": "chest dip (on dip-pull-up cage)", "name_zh": "双杠臂屈伸（偏胸）（于双杠引体组合支架）", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1430-XgWyAiA.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "雙槓臂屈伸（偏胸）（于雙槓引體組合支架）", "instructions_en": ["Adjust the dip bars to a height that allows you to comfortably grip them.", "Stand between the bars and place your hands on each bar, slightly wider than shoulder-width apart.", "Jump up and straighten your arms, supporting your body weight on the bars.", "Bend your knees and cross your ankles behind you.", "Lower your body by bending your elbows, keeping your chest up and your shoulders down.", "Continue lowering until your shoulders are below your elbows or until you feel a stretch in your chest.", "Push through your palms and extend your elbows to raise your body back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将倾斜杆调整到您可以舒适地握住它们的高度。", "站在杠铃之间，将双手放在每个杠铃上，距离略宽于肩宽。", "跳起来并伸直双臂，将体重支撑在杠上。", "弯曲膝盖并将脚踝交叉在身后。", "弯曲肘部降低身体，保持胸部向上，肩膀向下。", "继续降低，直到肩膀低于肘部或直到您感到胸部有拉伸感。", "推动手掌并伸展肘部，将身体抬回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["將傾斜桿調整到您可以舒適地握住它們的高度。", "站在杠鈴之間，將雙手放在每個杠鈴上，距離略寬于肩寬。", "跳起來并伸直雙臂，將體重支撐在杠上。", "彎曲膝蓋并將腳踝交叉在身后。", "彎曲肘部降低身體，保持胸部向上，肩膀向下。", "繼續降低，直到肩膀低于肘部或直到您感到胸部有拉伸感。", "推動手掌并伸展肘部，將身體抬回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2462', 'exercise', 1, '{"id": "2462", "target": "pectorals", "name_en": "chest dip on straight bar", "name_zh": "单杠臂屈伸（偏胸）", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/2462-LQFOrMn.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "單槓臂屈伸（偏胸）", "instructions_en": ["Grab the parallel bars with your palms facing down and your arms fully extended.", "Bend your knees and cross your ankles.", "Lower your body by bending your arms until your shoulders are below your elbows.", "Push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["手掌朝下，双臂完全伸展，抓住双杠。", "弯曲膝盖并交叉脚踝。", "弯曲手臂，降低身体，直到肩膀低于肘部。", "伸直手臂，将自己推回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["手掌朝下，雙臂完全伸展，抓住雙杠。", "彎曲膝蓋并交叉腳踝。", "彎曲手臂，降低身體，直到肩膀低于肘部。", "伸直手臂，將自己推回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1272', 'exercise', 1, '{"id": "1272", "target": "pectorals", "name_en": "chest stretch with exercise ball", "name_zh": "胸部拉伸配合健身球", "body_part": "chest", "equipment": "stability ball", "gif_asset": "assets/fitness/videos/1272-ykA5tU7.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "胸部拉伸配合健身球", "instructions_en": ["Sit on the stability ball with your feet flat on the ground and your back straight.", "Hold the exercise ball with both hands and extend your arms straight out in front of you.", "Slowly bring the exercise ball towards your chest, feeling a stretch in your chest muscles.", "Hold the stretch for a few seconds, then slowly return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在稳定球上，双脚平放在地面上，背部挺直。", "双手握住健身球，并将双臂伸直至身前。", "慢慢地将健身球移向胸部，感受胸部肌肉的拉伸。", "保持伸展几秒钟，然后慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["坐在穩定球上，雙腳平放在地面上，背部挺直。", "雙手握住健身球，并將雙臂伸直至身前。", "慢慢地將健身球移向胸部，感受胸部肌肉的拉伸。", "保持伸展幾秒鐘，然后慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3216', 'exercise', 1, '{"id": "3216", "target": "pectorals", "name_en": "chest tap push-up (male)", "name_zh": "胸部点触俯卧撑（男性示范）", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3216-7E06s6d.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "胸部點觸俯臥撐（男性示范）", "instructions_en": ["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line.", "Lower your body towards the ground by bending your elbows, keeping them close to your sides.", "As you lower yourself, tap your chest with your right hand.", "Push yourself back up to the starting position.", "Repeat the movement, this time tapping your chest with your left hand.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["从高平板支撑位置开始，双手分开略宽于肩宽，身体呈一条直线。", "弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。", "当你降低身体时，用右手拍打胸部。", "将自己推回到起始位置。", "重复这个动作，这次用左手敲击胸部。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["從高平板支撐位置開始，雙手分開略寬于肩寬，身體呈一條直線。", "彎曲肘部，使肘部靠近身體兩側，將身體降低到地面。", "當你降低身體時，用右手拍打胸部。", "將自己推回到起始位置。", "重復這個動作，這次用左手敲擊胸部。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1326', 'exercise', 1, '{"id": "1326", "target": "lats", "name_en": "chin-up", "name_zh": "反握引体向上", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1326-T2mxWqc.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "反握引體向上", "instructions_en": ["Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart.", "Engage your core and pull your body up towards the bar, leading with your chest.", "Continue pulling until your chin is above the bar.", "Pause for a moment at the top, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["悬挂在引体向上杆上，手掌朝向自己，双手与肩同宽。", "启动核心肌群，将身体拉向杠铃杆，以胸部为主导。", "继续拉，直到下巴位于杠铃上方。", "在顶部停顿片刻，然后慢慢将身体放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["懸掛在引體向上桿上，手掌朝向自己，雙手與肩同寬。", "啟動核心肌群，將身體拉向杠鈴桿，以胸部為主導。", "繼續拉，直到下巴位于杠鈴上方。", "在頂部停頓片刻，然后慢慢將身體放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0257', 'exercise', 1, '{"id": "0257", "target": "calves", "name_en": "circles knee stretch", "name_zh": "膝关节绕环拉伸", "body_part": "lower legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0257-X7jbxra.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "膝關節繞環拉伸", "instructions_en": ["Stand with your feet shoulder-width apart and your hands on your hips.", "Bend your knees slightly and lift your heels off the ground, balancing on the balls of your feet.", "Keeping your knees bent, rotate your knees in a circular motion, first clockwise and then counterclockwise.", "Perform the movement for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手放在臀部。", "稍微弯曲膝盖，将脚跟抬离地面，用脚掌保持平衡。", "保持膝盖弯曲，先顺时针旋转膝盖，然后逆时针旋转膝盖。", "执行所需的重复运动次数。"], "secondary_muscles": ["hamstrings", "quadriceps"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手放在臀部。", "稍微彎曲膝蓋，將腳跟抬離地面，用腳掌保持平衡。", "保持膝蓋彎曲，先順時針旋轉膝蓋，然后逆時針旋轉膝蓋。", "執行所需的重復運動次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1273', 'exercise', 1, '{"id": "1273", "target": "pectorals", "name_en": "clap push up", "name_zh": "击掌俯卧撑", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1273-wigSg76.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "擊掌俯臥撐", "instructions_en": ["Start in a high plank position with your hands slightly wider than shoulder-width apart.", "Lower your body towards the ground by bending your elbows, keeping your core engaged.", "Push through your palms explosively to propel your body off the ground.", "While in mid-air, clap your hands together before landing back in the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["从高平板支撑位置开始，双手分开略宽于肩宽。", "弯曲肘部，将身体降低到地面，保持核心参与。", "爆发性地推动手掌，将身体推离地面。", "在半空中时，拍手，然后回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["從高平板支撐位置開始，雙手分開略寬于肩寬。", "彎曲肘部，將身體降低到地面，保持核心參與。", "爆發性地推動手掌，將身體推離地面。", "在半空中時，拍手，然后回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0260', 'exercise', 1, '{"id": "0260", "target": "abs", "name_en": "cocoons", "name_zh": "团身卷腹", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0260-SLKj2pX.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "團身卷腹", "instructions_en": ["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，膝盖弯曲，双脚平放在地上。", "将双手放在脑后，肘部朝外。", "收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。", "在顶部停顿片刻，然后慢慢将上半身放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors", "lower back"], "instructions_zh_hant": ["平躺，膝蓋彎曲，雙腳平放在地上。", "將雙手放在腦后，肘部朝外。", "收緊腹肌，慢慢將上半身抬離地面，向前卷曲，直到軀幹呈 45 度角。", "在頂部停頓片刻，然后慢慢將上半身放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0258', 'exercise', 1, '{"id": "0258", "target": "pectorals", "name_en": "clock push-up", "name_zh": "时钟式俯卧撑", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0258-CMAxnsG.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "時鐘式俯臥撐", "instructions_en": ["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.", "Lower your body towards the ground by bending your elbows, keeping them close to your sides.", "As you lower, rotate your body to the left, extending your left arm straight out to the side.", "Push back up to the starting position, while rotating your body to the center.", "Repeat the push-up, this time rotating your body to the right and extending your right arm out to the side.", "Continue alternating sides with each repetition."], "instructions_zh": ["从高平板支撑位置开始，双手直接放在肩膀下方，身体呈一条直线。", "弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。", "当你下降时，将你的身体向左旋转，将你的左臂伸直到侧面。", "向上推回到起始位置，同时将身体旋转到中心。", "重复俯卧撑，这次将身体向右旋转，并将右臂向侧面伸出。", "每次重复时继续交替进行。"], "secondary_muscles": ["triceps", "shoulders", "core"], "instructions_zh_hant": ["從高平板支撐位置開始，雙手直接放在肩膀下方，身體呈一條直線。", "彎曲肘部，使肘部靠近身體兩側，將身體降低到地面。", "當你下降時，將你的身體向左旋轉，將你的左臂伸直到側面。", "向上推回到起始位置，同時將身體旋轉到中心。", "重復俯臥撐，這次將身體向右旋轉，并將右臂向側面伸出。", "每次重復時繼續交替進行。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1327', 'exercise', 1, '{"id": "1327", "target": "lats", "name_en": "close grip chin-up", "name_zh": "窄握反握引体向上", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1327-VnfUNW7.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "窄握反握引體向上", "instructions_en": ["Grab the pull-up bar with your palms facing towards you and your hands shoulder-width apart.", "Hang from the bar with your arms fully extended and your feet off the ground.", "Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.", "Continue pulling until your chin is above the bar.", "Pause for a moment at the top, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["抓住引体向上杆，手掌朝向自己，双手与肩同宽。", "悬挂在杠上，双臂完全伸展，双脚离开地面。", "收紧背部肌肉，将身体拉向杠铃杆，保持肘部靠近身体。", "继续拉，直到下巴位于杠铃上方。", "在顶部停顿片刻，然后慢慢将身体放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["抓住引體向上桿，手掌朝向自己，雙手與肩同寬。", "懸掛在杠上，雙臂完全伸展，雙腳離開地面。", "收緊背部肌肉，將身體拉向杠鈴桿，保持肘部靠近身體。", "繼續拉，直到下巴位于杠鈴上方。", "在頂部停頓片刻，然后慢慢將身體放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0259', 'exercise', 1, '{"id": "0259", "target": "triceps", "name_en": "close-grip push-up", "name_zh": "窄握俯卧撑", "body_part": "upper arms", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0259-x6KpKpq.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "窄握俯臥撐", "instructions_en": ["Start in a high plank position with your hands placed close together, directly under your shoulders.", "Engage your core and lower your body towards the ground, keeping your elbows close to your sides.", "Push through your palms to extend your arms and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["从高位平板支撑开始，双手并拢，位于肩膀正下方。", "收紧核心，将身体降低到地面，保持肘部靠近身体两侧。", "推动手掌以伸展手臂并返回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["從高位平板支撐開始，雙手并攏，位于肩膀正下方。", "收緊核心，將身體降低到地面，保持肘部靠近身體兩側。", "推動手掌以伸展手臂并返回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2398', 'exercise', 1, '{"id": "2398", "target": "triceps", "name_en": "close-grip push-up (on knees)", "name_zh": "跪姿窄距俯卧撑", "body_part": "upper arms", "equipment": "body weight", "gif_asset": "assets/fitness/videos/2398-v3vLFW0.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "跪姿窄距俯臥撐", "instructions_en": ["Start by getting on your hands and knees, with your hands shoulder-width apart and your knees hip-width apart.", "Lower your upper body towards the ground by bending your elbows, keeping them close to your sides.", "Pause for a moment when your chest is just above the ground.", "Push through your palms to straighten your arms and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先双手和膝盖着地，双手与肩同宽，膝盖与臀部同宽。", "弯曲肘部，将上身压向地面，使其靠近身体两侧。", "当你的胸部刚好高于地面时，暂停片刻。", "推动手掌以伸直手臂并返回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["首先雙手和膝蓋著地，雙手與肩同寬，膝蓋與臀部同寬。", "彎曲肘部，將上身壓向地面，使其靠近身體兩側。", "當你的胸部剛好高于地面時，暫停片刻。", "推動手掌以伸直手臂并返回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1274', 'exercise', 1, '{"id": "1274", "target": "pectorals", "name_en": "deep push up", "name_zh": "深度俯卧撑", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1274-vptOQ4N.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "深度俯臥撐", "instructions_en": ["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line.", "Lower your chest towards the ground by bending your elbows, keeping them close to your body.", "Push through your palms to extend your arms and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["从高平板支撑位置开始，双手分开略宽于肩宽，身体呈一条直线。", "弯曲肘部，使胸部靠近地面，使胸部靠近地面。", "推动手掌以伸展手臂并返回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["從高平板支撐位置開始，雙手分開略寬于肩寬，身體呈一條直線。", "彎曲肘部，使胸部靠近地面，使胸部靠近地面。", "推動手掌以伸展手臂并返回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1468', 'exercise', 1, '{"id": "1468", "target": "abs", "name_en": "crab twist toe touch", "name_zh": "螃蟹式转体触脚尖", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1468-xgsGFVM.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "螃蟹式轉體觸腳尖", "instructions_en": ["Start by sitting on the ground with your knees bent and feet flat on the floor.", "Place your hands behind you, fingers pointing towards your feet, and lift your hips off the ground.", "Extend one leg straight out in front of you while simultaneously reaching your opposite hand towards your toes.", "Return to the starting position and repeat on the other side.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["首先坐在地上，膝盖弯曲，双脚平放在地板上。", "将双手放在身后，手指指向脚部，并将臀部抬离地面。", "将一条腿伸直到您面前，同时将另一只手伸向脚趾。", "返回起始位置并在另一侧重复。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["obliques", "hip flexors"], "instructions_zh_hant": ["首先坐在地上，膝蓋彎曲，雙腳平放在地板上。", "將雙手放在身后，手指指向腳部，并將臀部抬離地面。", "將一條腿伸直到您面前，同時將另一只手伸向腳趾。", "返回起始位置并在另一側重復。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0262', 'exercise', 1, '{"id": "0262", "target": "abs", "name_en": "cross body crunch", "name_zh": "交叉身体卷腹", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0262-rbu5UUb.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "交叉身體卷腹", "instructions_en": ["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, lift your upper body off the ground and twist to bring your right elbow towards your left knee.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat on the other side, bringing your left elbow towards your right knee.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，膝盖弯曲，双脚平放在地上。", "将双手放在脑后，肘部朝外。", "收紧腹肌，将上半身抬离地面，然后扭转，使右肘靠近左膝盖。", "在顶部停顿片刻，然后慢慢将上半身放回起始位置。", "在另一侧重复，将左肘靠近右膝盖。", "重复所需的重复次数。"], "secondary_muscles": ["obliques"], "instructions_zh_hant": ["平躺，膝蓋彎曲，雙腳平放在地上。", "將雙手放在腦后，肘部朝外。", "收緊腹肌，將上半身抬離地面，然后扭轉，使右肘靠近左膝蓋。", "在頂部停頓片刻，然后慢慢將上半身放回起始位置。", "在另一側重復，將左肘靠近右膝蓋。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0267', 'exercise', 1, '{"id": "0267", "target": "abs", "name_en": "crunch (hands overhead)", "name_zh": "卷腹（双手过顶）", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0267-kjJ3VoQ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "卷腹（雙手過頂）", "instructions_en": ["Lie flat on your back with your knees bent and feet flat on the ground.", "Extend your arms straight above your head.", "Engaging your abs, lift your upper body off the ground, curling forward towards your knees.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，膝盖弯曲，双脚平放在地上。", "将双臂伸直至头顶上方。", "收紧腹肌，将上半身抬离地面，向前向膝盖弯曲。", "在顶部停顿片刻，然后慢慢将上半身放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["平躺，膝蓋彎曲，雙腳平放在地上。", "將雙臂伸直至頭頂上方。", "收緊腹肌，將上半身抬離地面，向前向膝蓋彎曲。", "在頂部停頓片刻，然后慢慢將上半身放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0271', 'exercise', 1, '{"id": "0271", "target": "abs", "name_en": "crunch (on stability ball)", "name_zh": "卷腹（健身球）", "body_part": "waist", "equipment": "stability ball", "gif_asset": "assets/fitness/videos/0271-MCUhf1F.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "卷腹（健身球）", "instructions_en": ["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.", "Lie back on the ball until your lower back is supported and your upper body is parallel to the floor.", "Place your hands behind your head or across your chest.", "Engage your abs and lift your upper body towards your knees, curling your torso forward.", "Pause for a moment at the top of the movement, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。", "仰卧在球上，直到下背部得到支撑并且上半身与地板平行。", "将双手放在脑后或放在胸前。", "收紧腹肌，将上身抬向膝盖，躯干向前卷曲。", "在动作的最高点暂停片刻，然后慢慢将上半身放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["坐在穩定球上，雙腳平放在地面上，膝蓋彎曲成 90 度角。", "仰臥在球上，直到下背部得到支撐并且上半身與地板平行。", "將雙手放在腦后或放在胸前。", "收緊腹肌，將上身抬向膝蓋，軀幹向前卷曲。", "在動作的最高點暫停片刻，然后慢慢將上半身放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1661', 'exercise', 1, '{"id": "1661", "target": "biceps", "name_en": "dumbbell lying supine biceps curl", "name_zh": "哑铃仰卧二头弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1661-XVzF3iZ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴仰臥二頭彎舉", "instructions_en": ["Lie flat on a bench with your back and head supported, and your feet flat on the ground.", "Hold a dumbbell in each hand with your palms facing up and your arms fully extended.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，背部和头部得到支撑，双脚平放在地面上。", "每只手握住一个哑铃，手掌朝上，双臂完全伸展。", "保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。", "继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["平躺在長凳上，背部和頭部得到支撐，雙腳平放在地面上。", "每只手握住一個啞鈴，手掌朝上，雙臂完全伸展。", "保持上臂靜止，呼氣并彎舉啞鈴，同時收縮二頭肌。", "繼續舉重，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0272', 'exercise', 1, '{"id": "0272", "target": "abs", "name_en": "crunch (on stability ball, arms straight)", "name_zh": "卷腹（健身球），双臂伸直）", "body_part": "waist", "equipment": "stability ball", "gif_asset": "assets/fitness/videos/0272-Sn8wxAI.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "卷腹（健身球），雙臂伸直）", "instructions_en": ["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.", "Lie back on the ball until your lower back is supported and your upper body is parallel to the floor.", "Place your hands behind your head or cross them over your chest.", "Engage your abs and lift your upper body off the ball, curling your shoulders towards your hips.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。", "仰卧在球上，直到下背部得到支撑并且上半身与地板平行。", "将双手放在脑后或交叉放在胸前。", "收紧腹肌，将上半身抬离球，将肩膀向臀部弯曲。", "在顶部停顿片刻，然后慢慢将上半身放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["坐在穩定球上，雙腳平放在地面上，膝蓋彎曲成 90 度角。", "仰臥在球上，直到下背部得到支撐并且上半身與地板平行。", "將雙手放在腦后或交叉放在胸前。", "收緊腹肌，將上半身抬離球，將肩膀向臀部彎曲。", "在頂部停頓片刻，然后慢慢將上半身放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3016', 'exercise', 1, '{"id": "3016", "target": "abs", "name_en": "curl-up", "name_zh": "卷腹", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3016-g2oKspu.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "卷腹", "instructions_en": ["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，膝盖弯曲，双脚平放在地上。", "将双手放在脑后，肘部朝外。", "收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。", "在顶部停顿片刻，然后慢慢将上半身放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["平躺，膝蓋彎曲，雙腳平放在地上。", "將雙手放在腦后，肘部朝外。", "收緊腹肌，慢慢將上半身抬離地面，向前卷曲，直到軀幹呈 45 度角。", "在頂部停頓片刻，然后慢慢將上半身放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3769', 'exercise', 1, '{"id": "3769", "target": "glutes", "name_en": "curtsey squat", "name_zh": "交叉后撤弓步深蹲", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3769-gUjqdei.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "交叉后撤弓步深蹲", "instructions_en": ["Stand with your feet shoulder-width apart.", "Take a step diagonally behind and across your body with your right foot, crossing it behind your left leg.", "Bend both knees as if you were curtsying, lowering your body towards the ground.", "Keep your torso upright and your weight on your front foot.", "Push through your front foot to return to the starting position.", "Repeat on the other side, stepping diagonally behind and across your body with your left foot."], "instructions_zh": ["双脚分开与肩同宽站立。", "右脚向斜后方跨出一步，跨过身体，交叉在左腿后面。", "弯曲双膝，就像行屈膝礼一样，将身体降低到地面。", "保持躯干直立，将体重放在前脚上。", "推动前脚返回起始位置。", "在另一侧重复，用左脚斜向后方跨过身体。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立。", "右腳向斜后方跨出一步，跨過身體，交叉在左腿后面。", "彎曲雙膝，就像行屈膝禮一樣，將身體降低到地面。", "保持軀幹直立，將體重放在前腳上。", "推動前腳返回起始位置。", "在另一側重復，用左腳斜向后方跨過身體。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2331', 'exercise', 1, '{"id": "2331", "target": "cardiovascular system", "name_en": "cycle cross trainer", "name_zh": "椭圆机骑行", "body_part": "cardio", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/2331-XSCHmiI.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "橢圓機騎行", "instructions_en": ["Adjust the seat height and position yourself on the cycle cross trainer.", "Place your feet on the pedals and grip the handlebars.", "Start pedaling in a smooth and controlled motion.", "Maintain a steady pace and increase the resistance if desired.", "Continue pedaling for the desired duration of your cardio workout."], "instructions_zh": ["调整座椅高度并将自己放在自行车交叉训练机上。", "将脚放在踏板上并抓住车把。", "开始以平稳且受控的动作踩踏。", "保持稳定的步伐并根据需要增加阻力。", "继续踩踏您的有氧运动所需的持续时间。"], "secondary_muscles": ["quadriceps", "hamstrings", "glutes"], "instructions_zh_hant": ["調整座椅高度并將自己放在自行車交叉訓練機上。", "將腳放在踏板上并抓住車把。", "開始以平穩且受控的動作踩踏。", "保持穩定的步伐并根據需要增加阻力。", "繼續踩踏您的有氧運動所需的持續時間。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2402', 'exercise', 1, '{"id": "2402", "target": "biceps", "name_en": "dumbbell hammer curls (with arm blaster)", "name_zh": "哑铃锤式弯举（配合弯举护板）", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/2402-GNhAeJ0.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴錘式彎舉（配合彎舉護板）", "instructions_en": ["Stand up straight with a dumbbell in each hand, palms facing your torso.", "Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.", "This will be your starting position.", "Now, while holding your upper arm stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Then, inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the recommended amount of repetitions."], "instructions_zh": ["站直，双手各持一个哑铃，手掌朝向躯干。", "保持肘部靠近躯干，并旋转手掌，直到手掌朝前。", "这将是您的起始位置。", "现在，保持上臂不动，呼气并卷曲哑铃，同时收缩二头肌。", "继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "然后，吸气并慢慢开始将哑铃放回起始位置。", "重复建议的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙手各持一個啞鈴，手掌朝向軀幹。", "保持肘部靠近軀幹，并旋轉手掌，直到手掌朝前。", "這將是您的起始位置。", "現在，保持上臂不動，呼氣并卷曲啞鈴，同時收縮二頭肌。", "繼續舉重，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "然后，吸氣并慢慢開始將啞鈴放回起始位置。", "重復建議的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0283', 'exercise', 1, '{"id": "0283", "target": "triceps", "name_en": "diamond push-up", "name_zh": "钻石式俯卧撑", "body_part": "upper arms", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0283-soIB2rj.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "鉆石式俯臥撐", "instructions_en": ["Start in a high plank position with your hands close together, forming a diamond shape with your thumbs and index fingers.", "Keep your body in a straight line from head to toe, engaging your core and glutes.", "Lower your chest towards the diamond shape formed by your hands, keeping your elbows close to your body.", "Pause for a moment at the bottom, then push yourself back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["从高位平板支撑开始，双手并拢，拇指和食指形成菱形。", "让你的身体从头到脚保持一条直线，锻炼你的核心和臀部。", "将胸部降低至双手形成的菱形，保持肘部靠近身体。", "在底部暂停片刻，然后将自己推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["從高位平板支撐開始，雙手并攏，拇指和食指形成菱形。", "讓你的身體從頭到腳保持一條直線，鍛煉你的核心和臀部。", "將胸部降低至雙手形成的菱形，保持肘部靠近身體。", "在底部暫停片刻，然后將自己推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0276', 'exercise', 1, '{"id": "0276", "target": "abs", "name_en": "dead bug", "name_zh": "死虫式", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0276-iny3m5y.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "死蟲式", "instructions_en": ["Lie flat on your back with your arms extended towards the ceiling.", "Bend your knees and lift your legs off the ground, creating a 90-degree angle at your hips and knees.", "Engage your core and lower back to press your lower back into the ground.", "Slowly lower your right arm and left leg towards the ground, keeping them straight and hovering just above the floor.", "Pause for a moment, then return to the starting position.", "Repeat the movement with your left arm and right leg.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["平躺，双臂伸向天花板。", "弯曲膝盖，将双腿抬离地面，使臀部和膝盖形成 90 度角。", "接合你的核心和下背部，将你的下背部压入地面。", "慢慢地将右臂和左腿放低至地面，保持它们伸直并悬停在地板上方。", "暂停片刻，然后回到起始位置。", "用左臂和右腿重复该动作。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["hip flexors", "lower back"], "instructions_zh_hant": ["平躺，雙臂伸向天花板。", "彎曲膝蓋，將雙腿抬離地面，使臀部和膝蓋形成 90 度角。", "接合你的核心和下背部，將你的下背部壓入地面。", "慢慢地將右臂和左腿放低至地面，保持它們伸直并懸停在地板上方。", "暫停片刻，然后回到起始位置。", "用左臂和右腿重復該動作。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0277', 'exercise', 1, '{"id": "0277", "target": "abs", "name_en": "decline crunch", "name_zh": "下斜卷腹", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0277-9Ap7miY.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "下斜卷腹", "instructions_en": ["Lie on a decline bench with your feet secured and your knees bent at a 90-degree angle.", "Place your hands behind your head or across your chest.", "Engage your abs and lift your upper body towards your knees, curling your torso.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["躺在倾斜的长凳上，双脚固定，膝盖弯曲成 90 度角。", "将双手放在脑后或放在胸前。", "收紧腹肌，将上半身抬向膝盖，卷曲躯干。", "在顶部停顿片刻，然后慢慢将上半身放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["躺在傾斜的長凳上，雙腳固定，膝蓋彎曲成 90 度角。", "將雙手放在腦后或放在胸前。", "收緊腹肌，將上半身抬向膝蓋，卷曲軀幹。", "在頂部停頓片刻，然后慢慢將上半身放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0279', 'exercise', 1, '{"id": "0279", "target": "pectorals", "name_en": "decline push-up", "name_zh": "下斜俯卧撑", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0279-i5cEhka.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "下斜俯臥撐", "instructions_en": ["Place your hands on the ground slightly wider than shoulder-width apart, with your feet elevated on a stable surface.", "Keep your body in a straight line from head to toe, engaging your core muscles.", "Lower your chest towards the ground by bending your elbows, keeping them close to your body.", "Push through your palms to extend your arms and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将双手放在地面上，距离略宽于肩宽，双脚放在稳定的表面上。", "保持身体从头到脚呈一条直线，锻炼核心肌肉。", "弯曲肘部，使胸部靠近地面，使胸部靠近地面。", "推动手掌以伸展手臂并返回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["將雙手放在地面上，距離略寬于肩寬，雙腳放在穩定的表面上。", "保持身體從頭到腳呈一條直線，鍛煉核心肌肉。", "彎曲肘部，使胸部靠近地面，使胸部靠近地面。", "推動手掌以伸展手臂并返回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0282', 'exercise', 1, '{"id": "0282", "target": "abs", "name_en": "decline sit-up", "name_zh": "下斜仰卧起坐", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0282-QLL2gdc.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "下斜仰臥起坐", "instructions_en": ["Lie on a decline bench with your feet secured and your knees bent.", "Place your hands behind your head or across your chest.", "Engage your abs and lift your upper body off the bench, curling forward towards your knees.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["躺在倾斜的长凳上，双脚固定，膝盖弯曲。", "将双手放在脑后或放在胸前。", "收紧腹肌，将上半身抬离长凳，向前向膝盖弯曲。", "在顶部停顿片刻，然后慢慢将上半身放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors", "lower back"], "instructions_zh_hant": ["躺在傾斜的長凳上，雙腳固定，膝蓋彎曲。", "將雙手放在腦后或放在胸前。", "收緊腹肌，將上半身抬離長凳，向前向膝蓋彎曲。", "在頂部停頓片刻，然后慢慢將上半身放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0284', 'exercise', 1, '{"id": "0284", "target": "calves", "name_en": "donkey calf raise", "name_zh": "驴式提踵", "body_part": "lower legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0284-u5ESqzH.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "驢式提踵", "instructions_en": ["Stand with your toes on an elevated surface, such as a step or block.", "Place your hands on a stable support, such as a wall or railing, for balance.", "Raise your heels as high as possible, lifting your body weight onto the balls of your feet.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将脚趾站立在升高的表面上，例如台阶或木块。", "将双手放在稳定的支撑物上，例如墙壁或栏杆，以保持平衡。", "尽可能高地抬高脚后跟，将身体重量转移到脚掌上。", "在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "glutes"], "instructions_zh_hant": ["將腳趾站立在升高的表面上，例如臺階或木塊。", "將雙手放在穩定的支撐物上，例如墻壁或欄桿，以保持平衡。", "盡可能高地抬高腳后跟，將身體重量轉移到腳掌上。", "在頂部停頓片刻，然后慢慢降低腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1275', 'exercise', 1, '{"id": "1275", "target": "pectorals", "name_en": "drop push up", "name_zh": "下落式俯卧撑", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1275-Q497lAE.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "下落式俯臥撐", "instructions_en": ["Start in a high plank position with your hands slightly wider than shoulder-width apart.", "Lower your chest towards the ground, keeping your elbows close to your body.", "Once your chest is just above the ground, quickly drop your knees to the ground.", "Push yourself back up to the starting position by extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["从高平板支撑位置开始，双手分开略宽于肩宽。", "将胸部压向地面，保持肘部靠近身体。", "当你的胸部刚好高于地面时，迅速将膝盖放在地上。", "伸展双臂，将自己推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["從高平板支撐位置開始，雙手分開略寬于肩寬。", "將胸部壓向地面，保持肘部靠近身體。", "當你的胸部剛好高于地面時，迅速將膝蓋放在地上。", "伸展雙臂，將自己推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0285', 'exercise', 1, '{"id": "0285", "target": "biceps", "name_en": "dumbbell alternate biceps curl", "name_zh": "哑铃交替二头弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0285-BU15nH4.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴交替二頭彎舉", "instructions_en": ["Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions, alternating arms."], "instructions_zh": ["站直，双手各握一个哑铃，手掌朝前，双臂完全伸展。", "保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。", "继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将哑铃放回起始位置。", "重复所需的重复次数，交替手臂。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙手各握一個啞鈴，手掌朝前，雙臂完全伸展。", "保持上臂靜止，呼氣并彎舉啞鈴，同時收縮二頭肌。", "繼續舉起啞鈴，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將啞鈴放回起始位置。", "重復所需的重復次數，交替手臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2403', 'exercise', 1, '{"id": "2403", "target": "biceps", "name_en": "dumbbell alternate biceps curl (with arm blaster)", "name_zh": "哑铃交替二头弯举（配合弯举护板）", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/2403-CfKsRbG.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴交替二頭彎舉（配合彎舉護板）", "instructions_en": ["Stand up straight with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.", "Place the arm blaster on your upper arms, ensuring a secure fit.", "Keeping your upper arms stationary, exhale and curl one dumbbell up towards your shoulder while contracting your biceps.", "Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly lower the dumbbell back to the starting position.", "Repeat the movement with the opposite arm.", "Continue alternating arms for the desired number of repetitions."], "instructions_zh": ["站直，双脚分开与肩同宽，双手各握一个哑铃，手掌朝前。", "将手臂冲击波放在上臂上，确保牢固贴合。", "保持上臂静止，呼气并将一只哑铃向上弯向肩膀，同时收缩二头肌。", "继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气，慢慢将哑铃放回起始位置。", "用另一只手臂重复该动作。", "继续交替手臂进行所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙腳分開與肩同寬，雙手各握一個啞鈴，手掌朝前。", "將手臂沖擊波放在上臂上，確保牢固貼合。", "保持上臂靜止，呼氣并將一只啞鈴向上彎向肩膀，同時收縮二頭肌。", "繼續舉起啞鈴，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣，慢慢將啞鈴放回起始位置。", "用另一只手臂重復該動作。", "繼續交替手臂進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1664', 'exercise', 1, '{"id": "1664", "target": "biceps", "name_en": "dumbbell high curl", "name_zh": "哑铃高位弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1664-qAmNMJY.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴高位彎舉", "instructions_en": ["Stand up straight with a dumbbell in each hand, palms facing forward.", "Keep your upper arms stationary and curl the dumbbells as high as possible while contracting your biceps.", "Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站直，双手各持一个哑铃，手掌朝前。", "保持上臂静止，将哑铃尽可能高地卷起，同时收缩二头肌。", "在最高点暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙手各持一個啞鈴，手掌朝前。", "保持上臂靜止，將啞鈴盡可能高地卷起，同時收縮二頭肌。", "在最高點暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1646', 'exercise', 1, '{"id": "1646", "target": "biceps", "name_en": "dumbbell alternate hammer preacher curl", "name_zh": "哑铃交替锤式牧师凳弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1646-fy7Tgy4.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴交替錘式牧師凳彎舉", "instructions_en": ["Sit on a preacher bench with a dumbbell in each hand, palms facing your torso and arms fully extended.", "Keep your upper arms stationary and exhale as you curl the weights while contracting your biceps.", "Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the recommended amount of repetitions."], "instructions_zh": ["坐在牧师凳上，双手各持一个哑铃，手掌面向躯干，双臂完全伸展。", "保持上臂静止，在弯举哑铃时呼气，同时收缩二头肌。", "继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将哑铃放回起始位置。", "重复建议的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在牧師凳上，雙手各持一個啞鈴，手掌面向軀幹，雙臂完全伸展。", "保持上臂靜止，在彎舉啞鈴時呼氣，同時收縮二頭肌。", "繼續舉起啞鈴，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將啞鈴放回起始位置。", "重復建議的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1647', 'exercise', 1, '{"id": "1647", "target": "biceps", "name_en": "dumbbell alternate preacher curl", "name_zh": "哑铃交替牧师凳弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1647-NlfIbzq.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴交替牧師凳彎舉", "instructions_en": ["Sit on a preacher bench with a dumbbell in each hand, palms facing up.", "Rest your upper arms on the pad of the preacher bench, allowing your arms to fully extend.", "Keeping your upper arms stationary, exhale and curl the dumbbell in your right hand as you contract your biceps.", "Continue to curl the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.", "Pause for a moment, then inhale and slowly lower the dumbbell back to the starting position.", "Repeat the movement with your left arm.", "Continue alternating arms for the desired number of repetitions."], "instructions_zh": ["坐在牧师凳上，每只手各握一个哑铃，手掌朝上。", "将上臂放在牧师凳的垫子上，让手臂完全伸展。", "保持上臂静止，呼气并弯曲右手的哑铃，同时收缩二头肌。", "继续弯举哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。", "暂停片刻，然后吸气，慢慢将哑铃放回起始位置。", "用左臂重复该动作。", "继续交替手臂进行所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在牧師凳上，每只手各握一個啞鈴，手掌朝上。", "將上臂放在牧師凳的墊子上，讓手臂完全伸展。", "保持上臂靜止，呼氣并彎曲右手的啞鈴，同時收縮二頭肌。", "繼續彎舉啞鈴，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "暫停片刻，然后吸氣，慢慢將啞鈴放回起始位置。", "用左臂重復該動作。", "繼續交替手臂進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1648', 'exercise', 1, '{"id": "1648", "target": "biceps", "name_en": "dumbbell alternate seated hammer curl", "name_zh": "哑铃交替坐姿锤式弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1648-6em2Dxj.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴交替坐姿錘式彎舉", "instructions_en": ["Sit on a bench with a dumbbell in each hand, palms facing your torso and arms extended down.", "Keep your back straight and your elbows close to your torso.", "Exhale and curl the dumbbell in your right hand towards your shoulder, keeping your upper arm stationary.", "Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.", "Pause for a brief moment, then inhale and slowly lower the dumbbell back to the starting position.", "Repeat the movement with your left arm.", "Continue alternating arms for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双手各握一个哑铃，手掌朝向躯干，手臂向下伸展。", "保持背部挺直，肘部靠近躯干。", "呼气，将右手的哑铃向肩膀弯曲，保持上臂静止。", "继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。", "暂停片刻，然后吸气，慢慢将哑铃放回起始位置。", "用左臂重复该动作。", "继续交替手臂进行所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在長凳上，雙手各握一個啞鈴，手掌朝向軀幹，手臂向下伸展。", "保持背部挺直，肘部靠近軀幹。", "呼氣，將右手的啞鈴向肩膀彎曲，保持上臂靜止。", "繼續舉起啞鈴，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "暫停片刻，然后吸氣，慢慢將啞鈴放回起始位置。", "用左臂重復該動作。", "繼續交替手臂進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0286', 'exercise', 1, '{"id": "0286", "target": "delts", "name_en": "dumbbell alternate side press", "name_zh": "哑铃交替侧推举", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0286-izMnLqz.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴交替側推舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height.", "Press one dumbbell overhead while keeping the other dumbbell at shoulder height.", "Lower the pressed dumbbell back to shoulder height while pressing the other dumbbell overhead.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高。", "将一个哑铃推过头顶，同时将另一个哑铃保持在与肩同高的位置。", "将按下的哑铃放回肩部高度，同时将另一个哑铃压过头顶。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["triceps", "core"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴，與肩同高。", "將一個啞鈴推過頭頂，同時將另一個啞鈴保持在與肩同高的位置。", "將按下的啞鈴放回肩部高度，同時將另一個啞鈴壓過頭頂。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0287', 'exercise', 1, '{"id": "0287", "target": "delts", "name_en": "dumbbell arnold press v. 2", "name_zh": "哑铃阿诺德推举变式2", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0287-eOrFCnx.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴阿諾德推舉變式2", "instructions_en": ["Sit on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent.", "Press the dumbbells upward until your arms are fully extended and your palms are facing forward.", "Rotate your wrists as you lift, so that your palms end up facing forward at the top of the movement.", "Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在有背部支撑的长凳上，双手各握一个哑铃，与肩同高，手掌朝向身体，肘部弯曲。", "向上推哑铃，直到手臂完全伸展，手掌朝前。", "抬起时旋转手腕，使手掌在动作的最高点朝前。", "在最高点暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "upper chest"], "instructions_zh_hant": ["坐在有背部支撐的長凳上，雙手各握一個啞鈴，與肩同高，手掌朝向身體，肘部彎曲。", "向上推啞鈴，直到手臂完全伸展，手掌朝前。", "抬起時旋轉手腕，使手掌在動作的最高點朝前。", "在最高點暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1649', 'exercise', 1, '{"id": "1649", "target": "biceps", "name_en": "dumbbell alternating bicep curl with leg raised on exercise ball", "name_zh": "健身球单腿支撑哑铃交替弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1649-Zwiw7XR.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球單腿支撐啞鈴交替彎舉", "instructions_en": ["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.", "Place an exercise ball behind you and position one foot on top of it, keeping your balance.", "With your arms fully extended and elbows close to your sides, curl one dumbbell towards your shoulder while keeping your upper arm stationary.", "Lower the dumbbell back down to the starting position and repeat with the other arm.", "Continue alternating arms for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝前。", "将健身球放在身后，并将一只脚放在上面，保持平衡。", "双臂完全伸展，肘部靠近身体两侧，将一只哑铃向肩膀弯曲，同时保持上臂静止。", "将哑铃放回起始位置，然后用另一只手臂重复该动作。", "继续交替手臂进行所需的重复次数。"], "secondary_muscles": ["forearms", "shoulders"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴，手掌朝前。", "將健身球放在身后，并將一只腳放在上面，保持平衡。", "雙臂完全伸展，肘部靠近身體兩側，將一只啞鈴向肩膀彎曲，同時保持上臂靜止。", "將啞鈴放回起始位置，然后用另一只手臂重復該動作。", "繼續交替手臂進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1650', 'exercise', 1, '{"id": "1650", "target": "biceps", "name_en": "dumbbell alternating seated bicep curl on exercise ball", "name_zh": "健身球哑铃交替坐姿二头弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1650-J74XlNf.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球啞鈴交替坐姿二頭彎舉", "instructions_en": ["Sit on an exercise ball with your feet flat on the ground and your back straight.", "Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.", "Keeping your upper arms stationary, exhale and curl one dumbbell while rotating your forearm until your palm is facing your shoulder.", "Inhale and slowly lower the dumbbell back to the starting position.", "Repeat the curl with the other arm.", "Continue alternating curls for the desired number of repetitions."], "instructions_zh": ["坐在健身球上，双脚平放在地上，背部挺直。", "每只手握住一个哑铃，手掌朝前，双臂完全伸展。", "保持上臂静止，呼气并弯举一只哑铃，同时旋转前臂，直到手掌面向肩膀。", "吸气，慢慢将哑铃放回起始位置。", "用另一只手臂重复弯举动作。", "继续交替卷发达到所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在健身球上，雙腳平放在地上，背部挺直。", "每只手握住一個啞鈴，手掌朝前，雙臂完全伸展。", "保持上臂靜止，呼氣并彎舉一只啞鈴，同時旋轉前臂，直到手掌面向肩膀。", "吸氣，慢慢將啞鈴放回起始位置。", "用另一只手臂重復彎舉動作。", "繼續交替卷發達到所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0306', 'exercise', 1, '{"id": "0306", "target": "triceps", "name_en": "dumbbell decline triceps extension", "name_zh": "哑铃下斜臂屈伸", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0306-OTgkHwR.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴下斜臂屈伸", "instructions_en": ["Lie on a decline bench with your head lower than your feet and hold a dumbbell in each hand, palms facing each other.", "Extend your arms fully, keeping your elbows close to your head.", "Lower the dumbbells slowly behind your head, bending your elbows.", "Pause for a moment, then raise the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["躺在斜凳上，头低于脚，双手各握一个哑铃，手掌相对。", "充分伸展双臂，保持肘部靠近头部。", "将哑铃慢慢降低到脑后，弯曲肘部。", "暂停片刻，然后将哑铃举回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["躺在斜凳上，頭低于腳，雙手各握一個啞鈴，手掌相對。", "充分伸展雙臂，保持肘部靠近頭部。", "將啞鈴慢慢降低到腦后，彎曲肘部。", "暫停片刻，然后將啞鈴舉回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2137', 'exercise', 1, '{"id": "2137", "target": "delts", "name_en": "dumbbell arnold press", "name_zh": "哑铃阿诺德推举", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/2137-Xy4jlWA.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴阿諾德推舉", "instructions_en": ["Sit on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent.", "Press the dumbbells upward until your arms are fully extended and your palms are facing forward.", "Rotate your wrists as you lift, so that your palms are facing forward at the top of the movement.", "Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在有背部支撑的长凳上，双手各握一个哑铃，与肩同高，手掌朝向身体，肘部弯曲。", "向上推哑铃，直到手臂完全伸展，手掌朝前。", "抬起时旋转手腕，使手掌在动作的最高点朝前。", "在最高点暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "upper chest"], "instructions_zh_hant": ["坐在有背部支撐的長凳上，雙手各握一個啞鈴，與肩同高，手掌朝向身體，肘部彎曲。", "向上推啞鈴，直到手臂完全伸展，手掌朝前。", "抬起時旋轉手腕，使手掌在動作的最高點朝前。", "在最高點暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0288', 'exercise', 1, '{"id": "0288", "target": "pectorals", "name_en": "dumbbell around pullover", "name_zh": "哑铃绕环仰卧上拉", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0288-vi8EhoE.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴繞環仰臥上拉", "instructions_en": ["Lie flat on a bench with your head at one end and your feet firmly on the ground.", "Hold a dumbbell with both hands and extend your arms straight above your chest.", "Keeping your arms straight, slowly lower the dumbbell behind your head in an arc motion.", "Pause for a moment at the bottom, then raise the dumbbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，头放在一端，双脚牢牢踩在地上。", "双手握住哑铃，将手臂伸直至胸部上方。", "保持手臂伸直，以弧线动作慢慢将哑铃降低到脑后。", "在底部停顿片刻，然后将哑铃举回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "latissimus dorsi"], "instructions_zh_hant": ["平躺在長凳上，頭放在一端，雙腳牢牢踩在地上。", "雙手握住啞鈴，將手臂伸直至胸部上方。", "保持手臂伸直，以弧線動作慢慢將啞鈴降低到腦后。", "在底部停頓片刻，然后將啞鈴舉回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0290', 'exercise', 1, '{"id": "0290", "target": "delts", "name_en": "dumbbell bench seated press", "name_zh": "哑铃凳上坐姿推举", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0290-3d7wHyd.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴凳上坐姿推舉", "instructions_en": ["Sit on a bench with a dumbbell in each hand, resting on your thighs.", "Lean back and position the dumbbells to the sides of your chest, palms facing forward.", "Press the dumbbells upward until your arms are fully extended.", "Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，每只手各拿一个哑铃，放在大腿上。", "向后倾斜，将哑铃放在胸部两侧，手掌朝前。", "向上推哑铃，直到手臂完全伸展。", "在最高点暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "chest"], "instructions_zh_hant": ["坐在長凳上，每只手各拿一個啞鈴，放在大腿上。", "向后傾斜，將啞鈴放在胸部兩側，手掌朝前。", "向上推啞鈴，直到手臂完全伸展。", "在最高點暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0291', 'exercise', 1, '{"id": "0291", "target": "glutes", "name_en": "dumbbell bench squat", "name_zh": "哑铃凳上深蹲", "body_part": "upper legs", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0291-mnzcrIB.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴凳上深蹲", "instructions_en": ["Place a dumbbell on the ground in front of a bench.", "Stand facing away from the bench with your feet shoulder-width apart.", "Bend at the knees and hips to lower yourself down towards the bench, keeping your chest up and back straight.", "Once your glutes touch the bench, push through your heels to stand back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将哑铃放在长凳前的地面上。", "背对长凳站立，双脚与肩同宽。", "弯曲膝盖和臀部，将自己降低到长凳上，保持胸部挺直，背部挺直。", "一旦你的臀部接触到长凳，就用脚后跟站起来，回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["將啞鈴放在長凳前的地面上。", "背對長凳站立，雙腳與肩同寬。", "彎曲膝蓋和臀部，將自己降低到長凳上，保持胸部挺直，背部挺直。", "一旦你的臀部接觸到長凳，就用腳后跟站起來，回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0293', 'exercise', 1, '{"id": "0293", "target": "upper back", "name_en": "dumbbell bent over row", "name_zh": "哑铃俯身划船", "body_part": "back", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0293-BJ0Hz5L.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴俯身劃船", "instructions_en": ["Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in each hand with your palms facing your body.", "Bend forward at the hips, keeping your back straight and your core engaged.", "Let your arms hang straight down towards the floor, with your elbows slightly bent.", "Pull the dumbbells up towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，膝盖稍微弯曲，双手各握一个哑铃，手掌朝向身体。", "臀部向前弯曲，保持背部挺直，核心肌群参与。", "让你的手臂垂直垂向地板，肘部稍微弯曲。", "将哑铃拉向胸部，将肩胛骨挤压在一起。", "在顶部停顿片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，膝蓋稍微彎曲，雙手各握一個啞鈴，手掌朝向身體。", "臀部向前彎曲，保持背部挺直，核心肌群參與。", "讓你的手臂垂直垂向地板，肘部稍微彎曲。", "將啞鈴拉向胸部，將肩胛骨擠壓在一起。", "在頂部停頓片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0295', 'exercise', 1, '{"id": "0295", "target": "glutes", "name_en": "dumbbell clean", "name_zh": "哑铃翻举", "body_part": "upper legs", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0295-7Hg55JG.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴翻舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.", "Bend your knees and lower your hips into a squat position, keeping your back straight and chest up.", "Explosively extend your hips and knees, driving through your heels to jump off the ground.", "As you jump, shrug your shoulders and pull the dumbbells up towards your shoulders, keeping them close to your body.", "Catch the dumbbells at shoulder height, with your elbows pointing forward and your palms facing up.", "Lower the dumbbells back down to the starting position by reversing the movement.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃，正握。", "弯曲膝盖，降低臀部至下蹲位置，保持背部挺直，挺胸。", "爆发性地伸展臀部和膝盖，通过脚后跟跳离地面。", "当你跳跃时，耸肩并将哑铃拉向你的肩膀，保持它们靠近你的身体。", "在与肩同高的位置抓住哑铃，肘部向前，手掌朝上。", "通过反向运动将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "quadriceps", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴，正握。", "彎曲膝蓋，降低臀部至下蹲位置，保持背部挺直，挺胸。", "爆發性地伸展臀部和膝蓋，通過腳后跟跳離地面。", "當你跳躍時，聳肩并將啞鈴拉向你的肩膀，保持它們靠近你的身體。", "在與肩同高的位置抓住啞鈴，肘部向前，手掌朝上。", "通過反向運動將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1651', 'exercise', 1, '{"id": "1651", "target": "biceps", "name_en": "dumbbell bicep curl lunge with bowling motion", "name_zh": "哑铃二头弯举弓步配合保龄球式动态", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1651-1VpF8db.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴二頭彎舉弓步配合保齡球式動態", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.", "Take a step forward with your right foot, bending your right knee and lowering your body into a lunge position.", "As you lunge forward, curl the dumbbells up towards your shoulders, keeping your elbows close to your body.", "At the bottom of the lunge, rotate your torso to the right, as if you were bowling a ball.", "Reverse the motion, stepping back with your right foot and returning to the starting position while lowering the dumbbells back down.", "Repeat the lunge and curl motion, this time rotating your torso to the left.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝前。", "右脚向前迈出一步，弯曲右膝，将身体降低至弓步位置。", "当你向前弓步时，将哑铃向上弯向肩膀，保持肘部靠近身体。", "在弓步底部，将躯干向右旋转，就像打保龄球一样。", "反转动作，右脚向后退一步，回到起始位置，同时放下哑铃。", "重复弓步和弯举动作，这次将躯干向左旋转。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["forearms", "shoulders"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴，手掌朝前。", "右腳向前邁出一步，彎曲右膝，將身體降低至弓步位置。", "當你向前弓步時，將啞鈴向上彎向肩膀，保持肘部靠近身體。", "在弓步底部，將軀幹向右旋轉，就像打保齡球一樣。", "反轉動作，右腳向后退一步，回到起始位置，同時放下啞鈴。", "重復弓步和彎舉動作，這次將軀幹向左旋轉。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1652', 'exercise', 1, '{"id": "1652", "target": "biceps", "name_en": "dumbbell bicep curl on exercise ball with leg raised", "name_zh": "健身球单腿支撑哑铃弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1652-2NImIAG.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球單腿支撐啞鈴彎舉", "instructions_en": ["Sit on an exercise ball with your feet flat on the ground and your back straight.", "Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.", "Slowly curl the dumbbells towards your shoulders, keeping your elbows close to your sides.", "Pause for a moment at the top of the movement, then slowly lower the dumbbells back to the starting position.", "While performing the bicep curl, raise one leg off the ground and hold it in the air for the duration of the exercise.", "Repeat for the desired number of repetitions, then switch legs and repeat."], "instructions_zh": ["坐在健身球上，双脚平放在地上，背部挺直。", "每只手握住一个哑铃，手掌朝前，双臂完全伸展。", "慢慢地将哑铃向肩膀弯曲，保持肘部靠近身体两侧。", "在动作的最高点暂停片刻，然后慢慢将哑铃放回起始位置。", "在进行二头肌弯举时，将一条腿抬离地面，并在整个练习过程中将其保持在空中。", "重复所需的重复次数，然后换腿并重复。"], "secondary_muscles": ["forearms", "shoulders"], "instructions_zh_hant": ["坐在健身球上，雙腳平放在地上，背部挺直。", "每只手握住一個啞鈴，手掌朝前，雙臂完全伸展。", "慢慢地將啞鈴向肩膀彎曲，保持肘部靠近身體兩側。", "在動作的最高點暫停片刻，然后慢慢將啞鈴放回起始位置。", "在進行二頭肌彎舉時，將一條腿抬離地面，并在整個練習過程中將其保持在空中。", "重復所需的重復次數，然后換腿并重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1653', 'exercise', 1, '{"id": "1653", "target": "biceps", "name_en": "dumbbell bicep curl with stork stance", "name_zh": "哑铃单腿站姿二头弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1653-uSkDMYl.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴單腿站姿二頭彎舉", "instructions_en": ["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.", "Extend one leg behind you, balancing on the toes of that foot.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions, then switch legs and repeat."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝前。", "将一条腿伸到身后，用脚趾保持平衡。", "保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。", "继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将哑铃放回起始位置。", "重复所需的重复次数，然后换腿并重复。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴，手掌朝前。", "將一條腿伸到身后，用腳趾保持平衡。", "保持上臂靜止，呼氣并彎舉啞鈴，同時收縮二頭肌。", "繼續舉重，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將啞鈴放回起始位置。", "重復所需的重復次數，然后換腿并重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2401', 'exercise', 1, '{"id": "2401", "target": "biceps", "name_en": "dumbbell biceps curl (with arm blaster)", "name_zh": "哑铃二头弯举（配合弯举护板）", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/2401-nlJsbkW.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴二頭彎舉（配合彎舉護板）", "instructions_en": ["Stand up straight with a dumbbell in each hand, palms facing forward.", "Keep your elbows close to your torso and your upper arms stationary.", "Exhale and curl the weights while contracting your biceps.", "Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站直，双手各持一个哑铃，手掌朝前。", "保持肘部靠近躯干，上臂保持静止。", "呼气并弯举哑铃，同时收缩二头肌。", "继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙手各持一個啞鈴，手掌朝前。", "保持肘部靠近軀幹，上臂保持靜止。", "呼氣并彎舉啞鈴，同時收縮二頭肌。", "繼續舉重，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0331', 'exercise', 1, '{"id": "0331", "target": "pectorals", "name_en": "dumbbell incline twisted flyes", "name_zh": "哑铃上斜转体飞鸟", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0331-1PLE8e9.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴上斜轉體飛鳥", "instructions_en": ["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing each other.", "Lie back on the bench and press the dumbbells up to the starting position, directly above your chest, with your arms extended.", "Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.", "As you lower the dumbbells, rotate your wrists so that your palms face forward at the bottom of the movement.", "Reverse the motion and bring the dumbbells back up to the starting position, squeezing your chest muscles together at the top.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将上斜凳摆成 45 度角，坐在上面，双手各握一个哑铃，掌心相对。", "仰卧在长凳上，将哑铃推至起始位置，位于胸部正上方，双臂伸展。", "将哑铃以宽弧线向两侧放低，直到感觉到胸部有拉伸感。", "放下哑铃时，旋转手腕，使手掌在动作底部朝前。", "反转动作，将哑铃拉回起始位置，在顶部将胸部肌肉挤压在一起。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["將上斜凳擺成 45 度角，坐在上面，雙手各握一個啞鈴，掌心相對。", "仰臥在長凳上，將啞鈴推至起始位置，位于胸部正上方，雙臂伸展。", "將啞鈴以寬弧線向兩側放低，直到感覺到胸部有拉伸感。", "放下啞鈴時，旋轉手腕，使手掌在動作底部朝前。", "反轉動作，將啞鈴拉回起始位置，在頂部將胸部肌肉擠壓在一起。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1654', 'exercise', 1, '{"id": "1654", "target": "biceps", "name_en": "dumbbell biceps curl reverse", "name_zh": "哑铃二头弯举反向", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1654-nFc4FyV.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴二頭彎舉反向", "instructions_en": ["Stand up straight with a dumbbell in each hand, palms facing down and arms fully extended.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站直，双手各握一个哑铃，手掌朝下，双臂完全伸展。", "保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。", "继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙手各握一個啞鈴，手掌朝下，雙臂完全伸展。", "保持上臂靜止，呼氣并彎舉啞鈴，同時收縮二頭肌。", "繼續舉起啞鈴，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1655', 'exercise', 1, '{"id": "1655", "target": "biceps", "name_en": "dumbbell biceps curl squat", "name_zh": "哑铃二头弯举深蹲", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1655-niXESDw.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴二頭彎舉深蹲", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.", "Keeping your back straight and your elbows close to your sides, exhale and curl the dumbbells up towards your shoulders.", "Pause for a moment at the top, squeezing your biceps.", "Inhale and slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝前。", "保持背部挺直，肘部靠近身体两侧，呼气并将哑铃向上弯向肩膀。", "在顶部暂停片刻，挤压你的二头肌。", "吸气并慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴，手掌朝前。", "保持背部挺直，肘部靠近身體兩側，呼氣并將啞鈴向上彎向肩膀。", "在頂部暫停片刻，擠壓你的二頭肌。", "吸氣并慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1656', 'exercise', 1, '{"id": "1656", "target": "biceps", "name_en": "dumbbell biceps curl v sit on bosu ball", "name_zh": "波速球V形坐姿哑铃弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1656-H1XAdpk.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "波速球V形坐姿啞鈴彎舉", "instructions_en": ["Sit on a bosu ball with your feet flat on the ground and your knees bent at a 90-degree angle.", "Hold a dumbbell in each hand with your palms facing forward and your arms fully extended down by your sides.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在博苏球上，双脚平放在地上，膝盖弯曲成 90 度角。", "每只手握住一个哑铃，手掌朝前，双臂在身体两侧完全向下伸展。", "保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。", "继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms", "shoulders"], "instructions_zh_hant": ["坐在博蘇球上，雙腳平放在地上，膝蓋彎曲成 90 度角。", "每只手握住一個啞鈴，手掌朝前，雙臂在身體兩側完全向下伸展。", "保持上臂靜止，呼氣并彎舉啞鈴，同時收縮二頭肌。", "繼續舉起啞鈴，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1201', 'exercise', 1, '{"id": "1201", "target": "cardiovascular system", "name_en": "dumbbell burpee", "name_zh": "哑铃波比跳", "body_part": "cardio", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1201-0JtKWum.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴波比跳", "instructions_en": ["Start in a standing position with your feet shoulder-width apart and a dumbbell in each hand.", "Lower your body into a squat position, placing the dumbbells on the ground in front of you.", "Kick your feet back into a push-up position, keeping your body in a straight line.", "Perform a push-up, bending your elbows and lowering your chest towards the ground.", "Jump your feet back towards your hands, landing in a squat position.", "Stand up explosively, lifting the dumbbells off the ground and bringing them to your shoulders.", "Press the dumbbells overhead, fully extending your arms.", "Lower the dumbbells back to your shoulders and repeat the entire sequence for the desired number of repetitions."], "instructions_zh": ["从站立位置开始，双脚分开与肩同宽，每只手各拿一个哑铃。", "将身体降低至蹲姿，将哑铃放在您面前的地面上。", "将双脚踢回到俯卧撑位置，保持身体呈一条直线。", "进行俯卧撑，弯曲肘部并将胸部降低到地面。", "将脚向后跳向双手，以蹲姿着地。", "爆发性地站起来，将哑铃从地上举起，放到肩膀上。", "将哑铃举过头顶，充分伸展手臂。", "将哑铃放回到肩膀上，然后重复整个序列，达到所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves", "shoulders", "triceps", "core"], "instructions_zh_hant": ["從站立位置開始，雙腳分開與肩同寬，每只手各拿一個啞鈴。", "將身體降低至蹲姿，將啞鈴放在您面前的地面上。", "將雙腳踢回到俯臥撐位置，保持身體呈一條直線。", "進行俯臥撐，彎曲肘部并將胸部降低到地面。", "將腳向后跳向雙手，以蹲姿著地。", "爆發性地站起來，將啞鈴從地上舉起，放到肩膀上。", "將啞鈴舉過頭頂，充分伸展手臂。", "將啞鈴放回到肩膀上，然后重復整個序列，達到所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0390', 'exercise', 1, '{"id": "0390", "target": "biceps", "name_en": "dumbbell seated biceps curl (on stability ball)", "name_zh": "健身球哑铃坐姿二头弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0390-WgJnBH5.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球啞鈴坐姿二頭彎舉", "instructions_en": ["Sit on a stability ball with your feet flat on the ground and your back straight.", "Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.", "Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.", "Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在稳定球上，双脚平放在地面上，背部挺直。", "每只手握住一个哑铃，手掌朝前，双臂完全伸展。", "保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。", "继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在穩定球上，雙腳平放在地面上，背部挺直。", "每只手握住一個啞鈴，手掌朝前，雙臂完全伸展。", "保持上臂靜止，呼氣并彎舉啞鈴，同時收縮二頭肌。", "繼續舉起啞鈴，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1731', 'exercise', 1, '{"id": "1731", "target": "triceps", "name_en": "dumbbell close grip press", "name_zh": "哑铃窄握推举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1731-7jGOBF3.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴窄握推舉", "instructions_en": ["Sit on a flat bench with a dumbbell in each hand, resting on your thighs.", "Using your thighs to help raise the dumbbells, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.", "Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.", "As you breathe in, slowly lower the dumbbells to your side until they are about level with your chest.", "As you exhale, use your triceps to lift the dumbbells back to the starting position. Make sure to use only your triceps and do not use your forearms or biceps to help lift the dumbbells.", "After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."], "instructions_zh": ["坐在平坦的长凳上，每只手各拿一个哑铃，放在大腿上。", "用你的大腿帮助举起哑铃，一次举起一个哑铃，这样你就可以将它们保持在与肩同宽的位置。", "一旦与肩同宽，向前旋转手腕，使手掌背向自己。这将是您的起始位置。", "当你吸气时，慢慢地将哑铃降低到你的身边，直到它们与你的胸部齐平。", "呼气时，用三头肌将哑铃举回到起始位置。确保只使用三头肌，不要使用前臂或二头肌来帮助举起哑铃。", "在收缩位置第二次暂停后，重复该动作达到规定的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["坐在平坦的長凳上，每只手各拿一個啞鈴，放在大腿上。", "用你的大腿幫助舉起啞鈴，一次舉起一個啞鈴，這樣你就可以將它們保持在與肩同寬的位置。", "一旦與肩同寬，向前旋轉手腕，使手掌背向自己。這將是您的起始位置。", "當你吸氣時，慢慢地將啞鈴降低到你的身邊，直到它們與你的胸部齊平。", "呼氣時，用三頭肌將啞鈴舉回到起始位置。確保只使用三頭肌，不要使用前臂或二頭肌來幫助舉起啞鈴。", "在收縮位置第二次暫停后，重復該動作達到規定的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0296', 'exercise', 1, '{"id": "0296", "target": "triceps", "name_en": "dumbbell close-grip press", "name_zh": "哑铃窄握推举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0296-RxayqAZ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴窄握推舉", "instructions_en": ["Sit on a flat bench with a dumbbell in each hand, resting on your thighs.", "Using your thighs to help raise the dumbbells, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.", "Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.", "As you breathe in, slowly lower the dumbbells to your side until they are about level with your chest.", "As you exhale, use your triceps to lift the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在平坦的长凳上，每只手各拿一个哑铃，放在大腿上。", "用你的大腿帮助举起哑铃，一次举起一个哑铃，这样你就可以将它们保持在与肩同宽的位置。", "一旦与肩同宽，向前旋转手腕，使手掌背向自己。这将是您的起始位置。", "当你吸气时，慢慢地将哑铃降低到你的身边，直到它们与你的胸部齐平。", "呼气时，用三头肌将哑铃举回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["坐在平坦的長凳上，每只手各拿一個啞鈴，放在大腿上。", "用你的大腿幫助舉起啞鈴，一次舉起一個啞鈴，這樣你就可以將它們保持在與肩同寬的位置。", "一旦與肩同寬，向前旋轉手腕，使手掌背向自己。這將是您的起始位置。", "當你吸氣時，慢慢地將啞鈴降低到你的身邊，直到它們與你的胸部齊平。", "呼氣時，用三頭肌將啞鈴舉回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0297', 'exercise', 1, '{"id": "0297", "target": "biceps", "name_en": "dumbbell concentration curl", "name_zh": "哑铃集中弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0297-gvsWLQw.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴集中彎舉", "instructions_en": ["Sit on a bench with your legs spread apart and a dumbbell in one hand, resting your elbow on the inside of your thigh.", "Fully extend your arm and hold the dumbbell with an underhand grip.", "Keeping your upper arm stationary, exhale and curl the weight up towards your shoulder while contracting your biceps.", "Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["坐在长凳上，双腿分开，一只手拿着哑铃，肘部放在大腿内侧。", "完全伸展手臂并用反手握住哑铃。", "保持上臂静止，呼气并将重量向上弯向肩膀，同时收缩二头肌。", "继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气，慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在長凳上，雙腿分開，一只手拿著啞鈴，肘部放在大腿內側。", "完全伸展手臂并用反手握住啞鈴。", "保持上臂靜止，呼氣并將重量向上彎向肩膀，同時收縮二頭肌。", "繼續舉起啞鈴，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣，慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3635', 'exercise', 1, '{"id": "3635", "target": "glutes", "name_en": "dumbbell contralateral forward lunge", "name_zh": "哑铃对侧向前弓步", "body_part": "upper legs", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/3635-ecl28tP.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴對側向前弓步", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.", "Take a step forward with your right foot, keeping your back straight and core engaged.", "Lower your body by bending both knees until your right thigh is parallel to the ground.", "Push through your right heel to return to the starting position.", "Repeat with your left leg.", "Alternate legs for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，每只手各握一个哑铃。", "右脚向前迈出一步，保持背部挺直并启动核心。", "弯曲双膝降低身体，直到右大腿与地面平行。", "推动右脚跟回到起始位置。", "左腿重复上述动作。", "交替腿进行所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，每只手各握一個啞鈴。", "右腳向前邁出一步，保持背部挺直并啟動核心。", "彎曲雙膝降低身體，直到右大腿與地面平行。", "推動右腳跟回到起始位置。", "左腿重復上述動作。", "交替腿進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0298', 'exercise', 1, '{"id": "0298", "target": "biceps", "name_en": "dumbbell cross body hammer curl", "name_zh": "哑铃交叉身体锤式弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0298-Qyk5J3p.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴交叉身體錘式彎舉", "instructions_en": ["Stand up straight with a dumbbell in each hand, palms facing your body.", "Keep your elbows close to your torso and your upper arms stationary.", "Exhale and curl the weights while contracting your biceps, bringing the dumbbells across your body towards your opposite shoulder.", "Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站直，双手各持一个哑铃，手掌朝向身体。", "保持肘部靠近躯干，上臂保持静止。", "呼气并弯举哑铃，同时收缩二头肌，将哑铃穿过身体拉向对侧的肩膀。", "继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙手各持一個啞鈴，手掌朝向身體。", "保持肘部靠近軀幹，上臂保持靜止。", "呼氣并彎舉啞鈴，同時收縮二頭肌，將啞鈴穿過身體拉向對側的肩膀。", "繼續舉起啞鈴，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1657', 'exercise', 1, '{"id": "1657", "target": "biceps", "name_en": "dumbbell cross body hammer curl v. 2", "name_zh": "哑铃交叉身体锤式弯举变式2", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1657-HDYiZcY.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴交叉身體錘式彎舉變式2", "instructions_en": ["Stand up straight with a dumbbell in each hand, palms facing your body.", "Keep your elbows close to your torso and your upper arms stationary.", "Exhale and curl the weights while contracting your biceps, bringing the dumbbells as close to your opposite shoulder as possible.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站直，双手各持一个哑铃，手掌朝向身体。", "保持肘部靠近躯干，上臂保持静止。", "呼气并弯举哑铃，同时收缩二头肌，使哑铃尽可能靠近另一侧的肩膀。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙手各持一個啞鈴，手掌朝向身體。", "保持肘部靠近軀幹，上臂保持靜止。", "呼氣并彎舉啞鈴，同時收縮二頭肌，使啞鈴盡可能靠近另一側的肩膀。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0299', 'exercise', 1, '{"id": "0299", "target": "delts", "name_en": "dumbbell cuban press", "name_zh": "哑铃古巴式推举", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0299-QfAKy1G.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴古巴式推舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height with your palms facing down.", "Keeping your core engaged and your elbows slightly bent, press the dumbbells up and overhead until your arms are fully extended.", "Rotate your wrists so that your palms are facing forward.", "Slowly lower the dumbbells back to the starting position, rotating your wrists back to the starting position as you do so.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高，手掌朝下。", "保持核心收紧，肘部稍微弯曲，将哑铃向上举过头顶，直到手臂完全伸展。", "旋转手腕，使手掌朝前。", "慢慢地将哑铃放回起始位置，同时将手腕旋转回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "upper back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴，與肩同高，手掌朝下。", "保持核心收緊，肘部稍微彎曲，將啞鈴向上舉過頭頂，直到手臂完全伸展。", "旋轉手腕，使手掌朝前。", "慢慢地將啞鈴放回起始位置，同時將手腕旋轉回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2136', 'exercise', 1, '{"id": "2136", "target": "delts", "name_en": "dumbbell cuban press v. 2", "name_zh": "哑铃古巴式推举变式2", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/2136-BqgCRif.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴古巴式推舉變式2", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height with your palms facing down.", "Keeping your core engaged and your back straight, press the dumbbells straight up overhead until your arms are fully extended.", "Rotate your wrists so that your palms are facing forward.", "Lower the dumbbells back down to shoulder height, rotating your wrists back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高，手掌朝下。", "保持核心收紧，背部挺直，将哑铃垂直推过头顶，直到手臂完全伸展。", "旋转手腕，使手掌朝前。", "将哑铃放回至肩膀高度，将手腕旋转回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "upper back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴，與肩同高，手掌朝下。", "保持核心收緊，背部挺直，將啞鈴垂直推過頭頂，直到手臂完全伸展。", "旋轉手腕，使手掌朝前。", "將啞鈴放回至肩膀高度，將手腕旋轉回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0300', 'exercise', 1, '{"id": "0300", "target": "glutes", "name_en": "dumbbell deadlift", "name_zh": "哑铃硬拉", "body_part": "upper legs", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0300-nUwVh7b.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴硬拉", "instructions_en": ["Stand with your feet shoulder-width apart, toes pointing forward.", "Hold a dumbbell in each hand, palms facing your body, arms extended downwards.", "Bend at your hips and knees, lowering the dumbbells towards the ground while keeping your back straight.", "Push through your heels and extend your hips and knees, lifting the dumbbells back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，脚趾指向前方。", "双手各握一个哑铃，手掌朝向身体，手臂向下伸展。", "弯曲臀部和膝盖，将哑铃向地面降低，同时保持背部挺直。", "脚跟用力，伸展臀部和膝盖，将哑铃举回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "lower back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，腳趾指向前方。", "雙手各握一個啞鈴，手掌朝向身體，手臂向下伸展。", "彎曲臀部和膝蓋，將啞鈴向地面降低，同時保持背部挺直。", "腳跟用力，伸展臀部和膝蓋，將啞鈴舉回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0301', 'exercise', 1, '{"id": "0301", "target": "pectorals", "name_en": "dumbbell decline bench press", "name_zh": "哑铃下斜卧推", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0301-DwhEmmE.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴下斜臥推", "instructions_en": ["Lie down on a decline bench with your feet secured and your head lower than your hips.", "Hold a dumbbell in each hand and extend your arms straight up above your chest, palms facing forward.", "Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.", "Push the dumbbells back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["躺在倾斜的长凳上，双脚固定，头部低于臀部。", "双手各握一个哑铃，双臂伸直至胸部上方，手掌朝前。", "慢慢地将哑铃降低到胸部两侧，保持肘部呈 90 度角。", "将哑铃推回起始位置，充分伸展手臂。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["躺在傾斜的長凳上，雙腳固定，頭部低于臀部。", "雙手各握一個啞鈴，雙臂伸直至胸部上方，手掌朝前。", "慢慢地將啞鈴降低到胸部兩側，保持肘部呈 90 度角。", "將啞鈴推回起始位置，充分伸展手臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0302', 'exercise', 1, '{"id": "0302", "target": "pectorals", "name_en": "dumbbell decline fly", "name_zh": "哑铃下斜飞鸟", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0302-xXm4nYq.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴下斜飛鳥", "instructions_en": ["Lie on a decline bench with your feet secured and your head lower than your hips.", "Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.", "Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.", "Pause for a moment, then squeeze your chest muscles to bring the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["躺在倾斜的长凳上，双脚固定，头部低于臀部。", "双手各握一个哑铃，手掌相对，双臂伸至胸部上方。", "将哑铃以宽弧线向两侧放低，直到感觉到胸部有拉伸感。", "暂停片刻，然后挤压胸部肌肉，使哑铃回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["躺在傾斜的長凳上，雙腳固定，頭部低于臀部。", "雙手各握一個啞鈴，手掌相對，雙臂伸至胸部上方。", "將啞鈴以寬弧線向兩側放低，直到感覺到胸部有拉伸感。", "暫停片刻，然后擠壓胸部肌肉，使啞鈴回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0303', 'exercise', 1, '{"id": "0303", "target": "pectorals", "name_en": "dumbbell decline hammer press", "name_zh": "哑铃下斜锤式推举", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0303-1qrWgZ2.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴下斜錘式推舉", "instructions_en": ["Lie on a decline bench with your feet secured and your head lower than your hips.", "Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.", "Lower the dumbbells to the sides of your chest, keeping your elbows slightly bent.", "Press the dumbbells back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["躺在倾斜的长凳上，双脚固定，头部低于臀部。", "双手各握一个哑铃，手掌相对，双臂伸至胸部上方。", "将哑铃降低到胸部两侧，保持肘部稍微弯曲。", "将哑铃推回到起始位置，充分伸展手臂。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["躺在傾斜的長凳上，雙腳固定，頭部低于臀部。", "雙手各握一個啞鈴，手掌相對，雙臂伸至胸部上方。", "將啞鈴降低到胸部兩側，保持肘部稍微彎曲。", "將啞鈴推回到起始位置，充分伸展手臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1276', 'exercise', 1, '{"id": "1276", "target": "pectorals", "name_en": "dumbbell decline one arm fly", "name_zh": "哑铃下斜单臂飞鸟", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1276-NL6YBwN.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴下斜單臂飛鳥", "instructions_en": ["Lie down on a decline bench with a dumbbell in one hand, resting it on your thigh.", "Using your thigh to help raise the dumbbell, lift it up to shoulder width with your palm facing your torso.", "Rotate your wrist so that the palm of your hand is facing forward.", "As you breathe in, lower the dumbbell slowly to the side until you feel a stretch in your chest.", "Exhale and use your chest muscles to bring the dumbbell back up to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["躺在斜凳上，一只手拿着哑铃，将其放在大腿上。", "用大腿帮助举起哑铃，将其举至与肩同宽，手掌朝向躯干。", "旋转手腕，使手掌朝前。", "吸气时，将哑铃慢慢降低到一侧，直到感觉到胸部有拉伸感。", "呼气并使用胸部肌肉将哑铃拉回到起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["躺在斜凳上，一只手拿著啞鈴，將其放在大腿上。", "用大腿幫助舉起啞鈴，將其舉至與肩同寬，手掌朝向軀幹。", "旋轉手腕，使手掌朝前。", "吸氣時，將啞鈴慢慢降低到一側，直到感覺到胸部有拉伸感。", "呼氣并使用胸部肌肉將啞鈴拉回到起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1617', 'exercise', 1, '{"id": "1617", "target": "triceps", "name_en": "dumbbell decline one arm hammer press", "name_zh": "哑铃下斜单臂锤式推举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1617-SHUMp5H.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴下斜單臂錘式推舉", "instructions_en": ["Lie on a decline bench with a dumbbell in one hand, resting on your chest.", "Extend your arm straight up, keeping your elbow slightly bent.", "Lower the dumbbell down towards your shoulder, keeping your elbow close to your body.", "Press the dumbbell back up to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["躺在下斜长凳上，一只手握住哑铃，放在胸前。", "将手臂伸直向上，保持肘部稍微弯曲。", "将哑铃向肩膀方向降低，保持肘部靠近身体。", "将哑铃推回到起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["躺在下斜長凳上，一只手握住啞鈴，放在胸前。", "將手臂伸直向上，保持肘部稍微彎曲。", "將啞鈴向肩膀方向降低，保持肘部靠近身體。", "將啞鈴推回到起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0305', 'exercise', 1, '{"id": "0305", "target": "traps", "name_en": "dumbbell decline shrug", "name_zh": "哑铃下斜耸肩", "body_part": "back", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0305-cwsAI4G.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴下斜聳肩", "instructions_en": ["Set up a decline bench at a 45-degree angle.", "Lie face down on the bench with your chest and stomach resting against it.", "Hold a dumbbell in each hand with your arms fully extended towards the floor.", "Keeping your arms straight, raise your shoulders towards your ears as high as possible.", "Hold the contraction for a moment, then slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["设置一个 45 度角的下斜凳。", "脸朝下躺在长凳上，胸部和腹部靠在长凳上。", "每只手握住一个哑铃，双臂完全伸向地板。", "保持手臂伸直，将肩膀尽可能高地抬向耳朵。", "保持收缩一会儿，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "rhomboids"], "instructions_zh_hant": ["設置一個 45 度角的下斜凳。", "臉朝下躺在長凳上，胸部和腹部靠在長凳上。", "每只手握住一個啞鈴，雙臂完全伸向地板。", "保持手臂伸直，將肩膀盡可能高地抬向耳朵。", "保持收縮一會兒，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0304', 'exercise', 1, '{"id": "0304", "target": "traps", "name_en": "dumbbell decline shrug v. 2", "name_zh": "哑铃下斜耸肩变式2", "body_part": "back", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0304-bRlbdjK.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴下斜聳肩變式2", "instructions_en": ["Set up a decline bench at a 45-degree angle.", "Lie face down on the bench with your chest and stomach resting on it.", "Hold a dumbbell in each hand with your palms facing each other and your arms fully extended.", "Keeping your arms straight, raise your shoulders as high as possible while squeezing your shoulder blades together.", "Hold the contraction for a brief pause, then lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["设置一个 45 度角的下斜凳。", "脸朝下躺在长凳上，胸部和腹部靠在长凳上。", "每只手握住一个哑铃，手掌相对，双臂完全伸展。", "保持手臂伸直，尽可能高地抬高肩膀，同时将肩胛骨挤压在一起。", "保持收缩短暂停顿，然后将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "rhomboids"], "instructions_zh_hant": ["設置一個 45 度角的下斜凳。", "臉朝下躺在長凳上，胸部和腹部靠在長凳上。", "每只手握住一個啞鈴，手掌相對，雙臂完全伸展。", "保持手臂伸直，盡可能高地抬高肩膀，同時將肩胛骨擠壓在一起。", "保持收縮短暫停頓，然后將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0307', 'exercise', 1, '{"id": "0307", "target": "pectorals", "name_en": "dumbbell decline twist fly", "name_zh": "哑铃下斜转体飞鸟", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0307-reFHapa.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴下斜轉體飛鳥", "instructions_en": ["Lie down on a decline bench with your head lower than your hips.", "Hold a dumbbell in each hand with your palms facing each other and your arms extended straight up over your chest.", "Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.", "As you lower the dumbbells, twist your wrists so that your palms face forward at the bottom of the movement.", "Reverse the motion and bring the dumbbells back up to the starting position, squeezing your chest muscles at the top.", "Repeat for the desired number of repetitions."], "instructions_zh": ["躺在倾斜的长凳上，头部低于臀部。", "双手各握一个哑铃，手掌相对，双臂伸直越过胸部。", "将哑铃以宽弧线向两侧放低，直到感觉到胸部有拉伸感。", "当你降低哑铃时，扭转手腕，使手掌在动作底部朝前。", "反转动作，将哑铃拉回到起始位置，在顶部挤压胸部肌肉。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["躺在傾斜的長凳上，頭部低于臀部。", "雙手各握一個啞鈴，手掌相對，雙臂伸直越過胸部。", "將啞鈴以寬弧線向兩側放低，直到感覺到胸部有拉伸感。", "當你降低啞鈴時，扭轉手腕，使手掌在動作底部朝前。", "反轉動作，將啞鈴拉回到起始位置，在頂部擠壓胸部肌肉。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1437', 'exercise', 1, '{"id": "1437", "target": "forearms", "name_en": "dumbbell finger curls", "name_zh": "哑铃手指弯举", "body_part": "lower arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1437-mtXengz.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴手指彎舉", "instructions_en": ["Sit on a bench or chair with your feet flat on the ground and your back straight.", "Hold a dumbbell in one hand with an underhand grip, resting your forearm on your thigh, palm facing up.", "Allow the dumbbell to roll down to your fingertips, then curl it back up by flexing your fingers.", "Repeat for the desired number of repetitions, then switch to the other hand."], "instructions_zh": ["坐在长凳或椅子上，双脚平放在地上，背部挺直。", "一只手握住哑铃，反手握住，将前臂放在大腿上，手掌朝上。", "让哑铃向下滚动到指尖，然后弯曲手指将其卷起。", "重复所需的重复次数，然后换另一只手。"], "secondary_muscles": ["wrist flexors", "wrist extensors"], "instructions_zh_hant": ["坐在長凳或椅子上，雙腳平放在地上，背部挺直。", "一只手握住啞鈴，反手握住，將前臂放在大腿上，手掌朝上。", "讓啞鈴向下滾動到指尖，然后彎曲手指將其卷起。", "重復所需的重復次數，然后換另一只手。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0308', 'exercise', 1, '{"id": "0308", "target": "pectorals", "name_en": "dumbbell fly", "name_zh": "哑铃飞鸟", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0308-yz9nUhF.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴飛鳥", "instructions_en": ["Lie flat on a bench with a dumbbell in each hand, palms facing each other.", "Extend your arms straight up over your chest, with a slight bend in your elbows.", "Keeping a slight bend in your elbows, lower your arms out to the sides in a wide arc until you feel a stretch in your chest.", "Pause for a moment, then reverse the movement and bring the dumbbells back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，双手各握一个哑铃，手掌相对。", "将手臂伸直越过胸部，肘部稍微弯曲。", "保持肘部轻微弯曲，将手臂以宽弧线向两侧放低，直到感觉到胸部有拉伸感。", "暂停片刻，然后反转动作，将哑铃拉回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["平躺在長凳上，雙手各握一個啞鈴，手掌相對。", "將手臂伸直越過胸部，肘部稍微彎曲。", "保持肘部輕微彎曲，將手臂以寬弧線向兩側放低，直到感覺到胸部有拉伸感。", "暫停片刻，然后反轉動作，將啞鈴拉回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1277', 'exercise', 1, '{"id": "1277", "target": "pectorals", "name_en": "dumbbell fly on exercise ball", "name_zh": "健身球哑铃飞鸟", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1277-Lt3iWnf.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球啞鈴飛鳥", "instructions_en": ["Sit on an exercise ball and hold a dumbbell in each hand.", "Walk your feet forward and roll your body down until your head, neck, and upper back are supported by the ball.", "Extend your arms straight up above your chest, palms facing each other.", "Bend your elbows slightly and lower your arms out to the sides in a wide arc until you feel a stretch in your chest.", "Pause for a moment, then reverse the movement and squeeze your chest muscles as you bring the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在健身球上，每只手各握一个哑铃。", "双脚向前走，身体向下滚动，直到头部、颈部和上背部得到球的支撑。", "将双臂伸直至胸部上方，手掌相对。", "稍微弯曲肘部，将手臂以宽弧线向两侧放低，直到感觉到胸部有拉伸感。", "暂停片刻，然后反向运动并挤压胸部肌肉，同时将​​哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["坐在健身球上，每只手各握一個啞鈴。", "雙腳向前走，身體向下滾動，直到頭部、頸部和上背部得到球的支撐。", "將雙臂伸直至胸部上方，手掌相對。", "稍微彎曲肘部，將手臂以寬弧線向兩側放低，直到感覺到胸部有拉伸感。", "暫停片刻，然后反向運動并擠壓胸部肌肉，同時將​​啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1732', 'exercise', 1, '{"id": "1732", "target": "triceps", "name_en": "dumbbell forward lunge triceps extension", "name_zh": "哑铃向前弓步臂屈伸", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1732-XalXcvM.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴向前弓步臂屈伸", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.", "Take a step forward with your right foot, lowering your body into a lunge position.", "Keep your back straight and your chest up.", "Extend your arms straight overhead, keeping your elbows close to your ears.", "Lower the dumbbells behind your head by bending your elbows.", "Pause for a moment, then straighten your arms to return to the starting position.", "Repeat the movement for the desired number of repetitions, then switch legs and repeat."], "instructions_zh": ["双脚分开与肩同宽站立，每只手各握一个哑铃。", "右脚向前迈出一步，将身体降低至弓步位置。", "保持背部挺直，挺胸。", "将手臂伸直过头顶，保持肘部靠近耳朵。", "弯曲肘部，将哑铃降低到脑后。", "暂停片刻，然后伸直手臂回到起始位置。", "重复该动作达到所需的重复次数，然后换腿并重复。"], "secondary_muscles": ["shoulders", "core"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，每只手各握一個啞鈴。", "右腳向前邁出一步，將身體降低至弓步位置。", "保持背部挺直，挺胸。", "將手臂伸直過頭頂，保持肘部靠近耳朵。", "彎曲肘部，將啞鈴降低到腦后。", "暫停片刻，然后伸直手臂回到起始位置。", "重復該動作達到所需的重復次數，然后換腿并重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0310', 'exercise', 1, '{"id": "0310", "target": "delts", "name_en": "dumbbell front raise", "name_zh": "哑铃前平举", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0310-3eGE2JC.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴前平舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.", "Keeping your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level.", "Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向大腿。", "保持双臂伸直，呼气并将哑铃举至身前，直至与肩齐平。", "在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "trapezius"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴，手掌朝向大腿。", "保持雙臂伸直，呼氣并將啞鈴舉至身前，直至與肩齊平。", "在頂部停頓片刻，然后吸氣，慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0309', 'exercise', 1, '{"id": "0309", "target": "delts", "name_en": "dumbbell front raise v. 2", "name_zh": "哑铃前平举变式2", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0309-Rr7S3yg.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴前平舉變式2", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.", "Keep your back straight and engage your core.", "Slowly lift the dumbbells in front of you, with your arms straight, until they are at shoulder level.", "Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向大腿。", "保持背部挺直并启动核心肌群。", "慢慢举起你面前的哑铃，手臂伸直，直到与肩齐平。", "在顶部停顿片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["trapezius", "biceps"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴，手掌朝向大腿。", "保持背部挺直并啟動核心肌群。", "慢慢舉起你面前的啞鈴，手臂伸直，直到與肩齊平。", "在頂部停頓片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0311', 'exercise', 1, '{"id": "0311", "target": "delts", "name_en": "dumbbell full can lateral raise", "name_zh": "哑铃满罐式侧平举", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0311-AQ0mC4Y.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴滿罐式側平舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.", "Keep your back straight and engage your core.", "Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the ground.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。", "保持背部挺直并启动核心肌群。", "将手臂向两侧举起，肘部保持轻微弯曲，直到与地面平行。", "在顶部暂停片刻，然后慢慢将手臂放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["traps", "rotator cuff"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴，手掌朝向身體。", "保持背部挺直并啟動核心肌群。", "將手臂向兩側舉起，肘部保持輕微彎曲，直到與地面平行。", "在頂部暫停片刻，然后慢慢將手臂放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1760', 'exercise', 1, '{"id": "1760", "target": "quads", "name_en": "dumbbell goblet squat", "name_zh": "哑铃高脚杯深蹲", "body_part": "upper legs", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1760-yn8yg1r.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴高腳杯深蹲", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell vertically against your chest with both hands.", "Keeping your chest up and core engaged, lower your body down into a squat position by pushing your hips back and bending your knees.", "Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.", "Pause for a moment at the bottom, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手握住哑铃垂直放在胸前。", "保持胸部挺直，核心收紧，通过向后推臀部并弯曲膝盖，将身体降低至蹲姿。", "继续降低，直到大腿与地面平行，或者尽可能低。", "在底部停顿片刻，然后推动脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手握住啞鈴垂直放在胸前。", "保持胸部挺直，核心收緊，通過向后推臀部并彎曲膝蓋，將身體降低至蹲姿。", "繼續降低，直到大腿與地面平行，或者盡可能低。", "在底部停頓片刻，然后推動腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1659', 'exercise', 1, '{"id": "1659", "target": "biceps", "name_en": "dumbbell hammer curl on exercise ball", "name_zh": "健身球哑铃锤式弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1659-fY68AyX.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球啞鈴錘式彎舉", "instructions_en": ["Sit on an exercise ball with your feet flat on the ground and your back straight.", "Hold a dumbbell in each hand with your palms facing your body and your arms fully extended.", "Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.", "Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在健身球上，双脚平放在地上，背部挺直。", "每只手握住一个哑铃，手掌朝向身体，双臂完全伸展。", "保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。", "继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在健身球上，雙腳平放在地上，背部挺直。", "每只手握住一個啞鈴，手掌朝向身體，雙臂完全伸展。", "保持上臂靜止，呼氣并彎舉啞鈴，同時收縮二頭肌。", "繼續舉起啞鈴，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0312', 'exercise', 1, '{"id": "0312", "target": "biceps", "name_en": "dumbbell hammer curl v. 2", "name_zh": "哑铃锤式弯举变式2", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0312-2NpxjC1.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴錘式彎舉變式2", "instructions_en": ["Stand up straight with a dumbbell in each hand, palms facing your torso.", "Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.", "This will be your starting position.", "Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Then, inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the recommended amount of repetitions."], "instructions_zh": ["站直，双手各持一个哑铃，手掌朝向躯干。", "保持肘部靠近躯干，并旋转手掌，直到手掌朝前。", "这将是您的起始位置。", "现在，保持上臂静止，呼气并卷曲哑铃，同时收缩二头肌。", "继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "然后，吸气并慢慢开始将哑铃放回起始位置。", "重复建议的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙手各持一個啞鈴，手掌朝向軀幹。", "保持肘部靠近軀幹，并旋轉手掌，直到手掌朝前。", "這將是您的起始位置。", "現在，保持上臂靜止，呼氣并卷曲啞鈴，同時收縮二頭肌。", "繼續舉重，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "然后，吸氣并慢慢開始將啞鈴放回起始位置。", "重復建議的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3545', 'exercise', 1, '{"id": "3545", "target": "pectorals", "name_en": "dumbbell incline alternate press", "name_zh": "哑铃上斜交替推举", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/3545-TVdivgY.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴上斜交替推舉", "instructions_en": ["Sit on an incline bench with a dumbbell in each hand, resting on your thighs.", "Lean back on the bench and use your thighs to help raise the dumbbells to shoulder height, palms facing forward.", "Once at shoulder height, rotate your wrists so that the palms of your hands are facing forward.", "Push the dumbbells up with your chest and shoulders, extending your arms fully.", "Lower the dumbbells back down to the starting position, keeping your elbows slightly bent.", "Repeat for the desired number of repetitions, alternating arms."], "instructions_zh": ["坐在上斜凳上，每只手各拿一个哑铃，放在大腿上。", "向后靠在长凳上，用大腿帮助将哑铃举至肩高，手掌朝前。", "到达肩膀高度后，旋转手腕，使手掌朝前。", "用胸部和肩膀将哑铃向上推，充分伸展手臂。", "将哑铃放回起始位置，保持肘部稍微弯曲。", "重复所需的重复次数，交替手臂。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["坐在上斜凳上，每只手各拿一個啞鈴，放在大腿上。", "向后靠在長凳上，用大腿幫助將啞鈴舉至肩高，手掌朝前。", "到達肩膀高度后，旋轉手腕，使手掌朝前。", "用胸部和肩膀將啞鈴向上推，充分伸展手臂。", "將啞鈴放回起始位置，保持肘部稍微彎曲。", "重復所需的重復次數，交替手臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0315', 'exercise', 1, '{"id": "0315", "target": "biceps", "name_en": "dumbbell incline biceps curl", "name_zh": "哑铃上斜二头弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0315-F3xgbjF.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴上斜二頭彎舉", "instructions_en": ["Sit on an incline bench with a dumbbell in each hand, palms facing forward, and arms fully extended.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在上斜凳上，双手各握一个哑铃，手掌朝前，双臂完全伸展。", "保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。", "继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在上斜凳上，雙手各握一個啞鈴，手掌朝前，雙臂完全伸展。", "保持上臂靜止，呼氣并彎舉啞鈴，同時收縮二頭肌。", "繼續舉起啞鈴，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0316', 'exercise', 1, '{"id": "0316", "target": "pectorals", "name_en": "dumbbell incline breeding", "name_zh": "哑铃上斜外展", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0316-B3Rxp6L.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴上斜外展", "instructions_en": ["Set up an incline bench at a 45-degree angle.", "Sit on the bench with your back against the pad and feet flat on the ground.", "Hold a dumbbell in each hand with an overhand grip, palms facing forward.", "Start with your arms fully extended, perpendicular to the ground.", "Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.", "Pause for a moment at the bottom, then push the dumbbells back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["设置一个 45 度角的上斜凳。", "坐在长凳上，背部靠在垫子上，双脚平放在地面上。", "双手各握一个哑铃，正手握握，手掌朝前。", "首先，双臂完全伸展，垂直于地面。", "慢慢地将哑铃降低到胸部两侧，保持肘部呈 90 度角。", "在底部暂停片刻，然后将哑铃推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["設置一個 45 度角的上斜凳。", "坐在長凳上，背部靠在墊子上，雙腳平放在地面上。", "雙手各握一個啞鈴，正手握握，手掌朝前。", "首先，雙臂完全伸展，垂直于地面。", "慢慢地將啞鈴降低到胸部兩側，保持肘部呈 90 度角。", "在底部暫停片刻，然后將啞鈴推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0318', 'exercise', 1, '{"id": "0318", "target": "biceps", "name_en": "dumbbell incline curl", "name_zh": "哑铃上斜弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0318-ae9UoXQ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴上斜彎舉", "instructions_en": ["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing forward.", "Rest your upper arms on the incline bench and let your elbows hang down, fully extending your arms.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将上斜凳摆成 45 度角，坐在上面，双手各握一个哑铃，掌心向前。", "将上臂放在上斜凳上，让肘部下垂，充分伸展手臂。", "保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。", "继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["將上斜凳擺成 45 度角，坐在上面，雙手各握一個啞鈴，掌心向前。", "將上臂放在上斜凳上，讓肘部下垂，充分伸展手臂。", "保持上臂靜止，呼氣并彎舉啞鈴，同時收縮二頭肌。", "繼續舉起啞鈴，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0317', 'exercise', 1, '{"id": "0317", "target": "biceps", "name_en": "dumbbell incline curl v. 2", "name_zh": "哑铃上斜弯举变式2", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0317-RaflbWD.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴上斜彎舉變式2", "instructions_en": ["Sit on an incline bench with a dumbbell in each hand, palms facing forward and arms fully extended.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在上斜凳上，双手各握一个哑铃，手掌朝前，双臂完全伸展。", "保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。", "继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在上斜凳上，雙手各握一個啞鈴，手掌朝前，雙臂完全伸展。", "保持上臂靜止，呼氣并彎舉啞鈴，同時收縮二頭肌。", "繼續舉起啞鈴，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0319', 'exercise', 1, '{"id": "0319", "target": "pectorals", "name_en": "dumbbell incline fly", "name_zh": "哑铃上斜飞鸟", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0319-ESOd5Pl.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴上斜飛鳥", "instructions_en": ["Set an incline bench to a 45-degree angle.", "Sit on the bench with a dumbbell in each hand, palms facing each other.", "Lie back on the bench and press the dumbbells up to the starting position, directly above your chest.", "Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.", "Pause for a moment, then squeeze your chest muscles to bring the dumbbells back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将上斜凳设置为 45 度角。", "坐在长凳上，双手各握一个哑铃，手掌相对。", "仰卧在长凳上，将哑铃推至起始位置，位于胸部正上方。", "将哑铃以宽弧线向两侧放低，直到感觉到胸部有拉伸感。", "暂停片刻，然后挤压胸部肌肉，将哑铃拉回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["將上斜凳設置為 45 度角。", "坐在長凳上，雙手各握一個啞鈴，手掌相對。", "仰臥在長凳上，將啞鈴推至起始位置，位于胸部正上方。", "將啞鈴以寬弧線向兩側放低，直到感覺到胸部有拉伸感。", "暫停片刻，然后擠壓胸部肌肉，將啞鈴拉回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1278', 'exercise', 1, '{"id": "1278", "target": "pectorals", "name_en": "dumbbell incline fly on exercise ball", "name_zh": "健身球哑铃上斜飞鸟", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1278-HYe1ZqR.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球啞鈴上斜飛鳥", "instructions_en": ["Set up an incline bench at a 45-degree angle.", "Sit on an exercise ball and roll forward until your upper back is resting on the incline bench.", "Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.", "Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.", "Pause for a moment, then squeeze your chest muscles to bring the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["设置一个 45 度角的上斜凳。", "坐在健身球上，向前滚动，直到上背部靠在倾斜的长凳上。", "双手各握一个哑铃，手掌相对，双臂伸至胸部上方。", "将哑铃以宽弧线向两侧放低，直到感觉到胸部有拉伸感。", "暂停片刻，然后挤压胸部肌肉，使哑铃回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["設置一個 45 度角的上斜凳。", "坐在健身球上，向前滾動，直到上背部靠在傾斜的長凳上。", "雙手各握一個啞鈴，手掌相對，雙臂伸至胸部上方。", "將啞鈴以寬弧線向兩側放低，直到感覺到胸部有拉伸感。", "暫停片刻，然后擠壓胸部肌肉，使啞鈴回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0320', 'exercise', 1, '{"id": "0320", "target": "biceps", "name_en": "dumbbell incline hammer curl", "name_zh": "哑铃上斜锤式弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0320-ByX0WxV.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴上斜錘式彎舉", "instructions_en": ["Sit on an incline bench with a dumbbell in each hand, palms facing your torso and arms fully extended.", "Keep your back against the bench and your feet flat on the floor.", "While keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在上斜凳上，每只手各握一个哑铃，手掌朝向躯干，手臂完全伸展。", "背部靠在长凳上，双脚平放在地板上。", "保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。", "继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在上斜凳上，每只手各握一個啞鈴，手掌朝向軀幹，手臂完全伸展。", "背部靠在長凳上，雙腳平放在地板上。", "保持上臂靜止，呼氣并彎舉啞鈴，同時收縮二頭肌。", "繼續舉重，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0321', 'exercise', 1, '{"id": "0321", "target": "pectorals", "name_en": "dumbbell incline hammer press", "name_zh": "哑铃上斜锤式推举", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0321-PG1kcIb.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴上斜錘式推舉", "instructions_en": ["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, resting on your thighs.", "Lie back on the bench and position the dumbbells at shoulder level with your palms facing each other.", "Press the dumbbells up and away from your body until your arms are fully extended.", "Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将上斜凳设置成 45 度角，坐在上面，双手各握一个哑铃，放在大腿上。", "仰卧在长凳上，将哑铃置于与肩同高的位置，手掌相对。", "将哑铃向上推离身体，直到手臂完全伸展。", "在顶部停顿片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["將上斜凳設置成 45 度角，坐在上面，雙手各握一個啞鈴，放在大腿上。", "仰臥在長凳上，將啞鈴置于與肩同高的位置，手掌相對。", "將啞鈴向上推離身體，直到手臂完全伸展。", "在頂部停頓片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1618', 'exercise', 1, '{"id": "1618", "target": "triceps", "name_en": "dumbbell incline hammer press on exercise ball", "name_zh": "健身球哑铃上斜锤式推举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1618-wkgnGfb.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球啞鈴上斜錘式推舉", "instructions_en": ["Sit on an exercise ball with a dumbbell in each hand, palms facing each other.", "Walk your feet forward and roll your body down the ball until your head, neck, and upper back are supported on the ball.", "Hold the dumbbells at shoulder level, elbows bent and pointing out to the sides.", "Press the dumbbells up and slightly inward, keeping your palms facing each other.", "Extend your arms fully, squeezing your triceps at the top of the movement.", "Slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在健身球上，双手各握一个哑铃，手掌相对。", "双脚向前走，身体沿着球滚动，直到头部、颈部和上背部得到球的支撑。", "将哑铃保持在与肩同高的位置，肘部弯曲并指向两侧。", "将哑铃向上并稍微向内推，保持手掌相对。", "充分伸展双臂，在动作的最高点挤压三头肌。", "慢慢地将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["坐在健身球上，雙手各握一個啞鈴，手掌相對。", "雙腳向前走，身體沿著球滾動，直到頭部、頸部和上背部得到球的支撐。", "將啞鈴保持在與肩同高的位置，肘部彎曲并指向兩側。", "將啞鈴向上并稍微向內推，保持手掌相對。", "充分伸展雙臂，在動作的最高點擠壓三頭肌。", "慢慢地將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0322', 'exercise', 1, '{"id": "0322", "target": "biceps", "name_en": "dumbbell incline inner biceps curl", "name_zh": "哑铃上斜内侧二头弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0322-LCtQPn8.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴上斜內側二頭彎舉", "instructions_en": ["Sit on an incline bench with a dumbbell in each hand, palms facing each other.", "Rest your upper arms on the bench, allowing your elbows to hang down and your palms to face forward.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在上斜凳上，双手各握一个哑铃，手掌相对。", "将上臂放在长凳上，让肘部下垂，手掌朝前。", "保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。", "继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在上斜凳上，雙手各握一個啞鈴，手掌相對。", "將上臂放在長凳上，讓肘部下垂，手掌朝前。", "保持上臂靜止，呼氣并彎舉啞鈴，同時收縮二頭肌。", "繼續舉起啞鈴，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1279', 'exercise', 1, '{"id": "1279", "target": "pectorals", "name_en": "dumbbell incline one arm fly", "name_zh": "哑铃上斜单臂飞鸟", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1279-Gw2HFvW.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴上斜單臂飛鳥", "instructions_en": ["Adjust the incline bench to a 30-45 degree angle.", "Sit on the bench with a dumbbell in one hand, resting it on your thigh.", "Lie back on the bench, keeping your feet flat on the ground.", "Hold the dumbbell with your arm extended straight up over your chest.", "Lower the dumbbell out to the side in a wide arc, keeping a slight bend in your elbow.", "Pause when your arm is parallel to the ground, then reverse the motion to bring the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["将倾斜凳调整至 30-45 度角。", "坐在长凳上，一只手拿着哑铃，将其放在大腿上。", "向后躺在长凳上，双脚平放在地面上。", "握住哑铃，手臂伸直越过胸部。", "将哑铃以宽弧线向一侧放低，保持肘部轻微弯曲。", "当手臂与地面平行时暂停，然后反向运动，使哑铃回到起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["deltoids", "triceps"], "instructions_zh_hant": ["將傾斜凳調整至 30-45 度角。", "坐在長凳上，一只手拿著啞鈴，將其放在大腿上。", "向后躺在長凳上，雙腳平放在地面上。", "握住啞鈴，手臂伸直越過胸部。", "將啞鈴以寬弧線向一側放低，保持肘部輕微彎曲。", "當手臂與地面平行時暫停，然后反向運動，使啞鈴回到起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1167', 'exercise', 1, '{"id": "1167", "target": "pectorals", "name_en": "dynamic chest stretch (male)", "name_zh": "动态胸部拉伸（男性示范）", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1167-3uj0Ozg.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "動態胸部拉伸（男性示范）", "instructions_en": ["Stand tall with your feet shoulder-width apart.", "Extend your arms straight out to the sides, parallel to the ground.", "Slowly bring your arms forward, crossing them in front of your body.", "Feel the stretch in your chest muscles.", "Hold the stretch for 10-30 seconds.", "Return to the starting position and repeat for the desired number of repetitions."], "instructions_zh": ["站直，双脚分开与肩同宽。", "将双臂伸直至两侧，与地面平行。", "慢慢地将双臂向前伸，交叉在身体前面。", "感受胸部肌肉的伸展。", "保持拉伸 10-30 秒。", "返回起始位置并重复所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["站直，雙腳分開與肩同寬。", "將雙臂伸直至兩側，與地面平行。", "慢慢地將雙臂向前伸，交叉在身體前面。", "感受胸部肌肉的伸展。", "保持拉伸 10-30 秒。", "返回起始位置并重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1280', 'exercise', 1, '{"id": "1280", "target": "pectorals", "name_en": "dumbbell incline one arm fly on exercise ball", "name_zh": "健身球哑铃上斜单臂飞鸟", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1280-LLNh6q5.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球啞鈴上斜單臂飛鳥", "instructions_en": ["Sit on an exercise ball with a dumbbell in one hand.", "Walk your feet forward and roll your body down until your head, neck, and upper back are supported on the ball.", "Hold the dumbbell with your arm extended straight up over your chest, palm facing inwards.", "Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.", "Pause for a moment when your arm is parallel to the ground.", "Engage your chest muscles to bring the dumbbell back up to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["坐在健身球上，一只手拿着哑铃。", "双脚向前走，身体向下滚动，直到头部、颈部和上背部得到球的支撑。", "握住哑铃，手臂伸直越过胸部，手掌朝内。", "慢慢地将哑铃向一侧放低，保持肘部轻微弯曲。", "当手臂与地面平行时暂停片刻。", "启动胸部肌肉，将哑铃拉回到起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["坐在健身球上，一只手拿著啞鈴。", "雙腳向前走，身體向下滾動，直到頭部、頸部和上背部得到球的支撐。", "握住啞鈴，手臂伸直越過胸部，手掌朝內。", "慢慢地將啞鈴向一側放低，保持肘部輕微彎曲。", "當手臂與地面平行時暫停片刻。", "啟動胸部肌肉，將啞鈴拉回到起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1619', 'exercise', 1, '{"id": "1619", "target": "triceps", "name_en": "dumbbell incline one arm hammer press", "name_zh": "哑铃上斜单臂锤式推举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1619-LL1UiTX.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴上斜單臂錘式推舉", "instructions_en": ["Sit on an incline bench with a dumbbell in one hand, resting on your thigh.", "Lean back on the bench and use your thigh to help raise the dumbbell to shoulder height.", "Rotate your wrist so that your palm is facing inward, towards your body.", "Press the dumbbell up and away from your body, extending your arm fully.", "Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["坐在上斜凳上，一只手拿着哑铃，放在大腿上。", "向后靠在长凳上，用大腿帮助将哑铃举至肩膀高度。", "旋转手腕，使手掌朝内，朝向身体。", "将哑铃向上推离身体，完全伸展手臂。", "在顶部停顿片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["shoulders", "chest"], "instructions_zh_hant": ["坐在上斜凳上，一只手拿著啞鈴，放在大腿上。", "向后靠在長凳上，用大腿幫助將啞鈴舉至肩膀高度。", "旋轉手腕，使手掌朝內，朝向身體。", "將啞鈴向上推離身體，完全伸展手臂。", "在頂部停頓片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1620', 'exercise', 1, '{"id": "1620", "target": "triceps", "name_en": "dumbbell incline one arm hammer press on exercise ball", "name_zh": "健身球哑铃上斜单臂锤式推举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1620-jDnrkar.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球啞鈴上斜單臂錘式推舉", "instructions_en": ["Sit on an exercise ball with a dumbbell in one hand.", "Walk your feet forward and roll your body down until your head, neck, and upper back are supported on the ball.", "Hold the dumbbell with your palm facing inward and your elbow bent at a 90-degree angle.", "Press the dumbbell up towards the ceiling, straightening your arm.", "Lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["坐在健身球上，一只手拿着哑铃。", "双脚向前走，身体向下滚动，直到头部、颈部和上背部得到球的支撑。", "握住哑铃，手掌朝内，肘部弯曲成 90 度角。", "将哑铃向上推向天花板，伸直手臂。", "将哑铃放回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["shoulders", "chest"], "instructions_zh_hant": ["坐在健身球上，一只手拿著啞鈴。", "雙腳向前走，身體向下滾動，直到頭部、頸部和上背部得到球的支撐。", "握住啞鈴，手掌朝內，肘部彎曲成 90 度角。", "將啞鈴向上推向天花板，伸直手臂。", "將啞鈴放回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0323', 'exercise', 1, '{"id": "0323", "target": "delts", "name_en": "dumbbell incline one arm lateral raise", "name_zh": "哑铃上斜单臂侧平举", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0323-aTNKZiC.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴上斜單臂側平舉", "instructions_en": ["Sit on an incline bench with a dumbbell in one hand, resting it on your thigh.", "Lean forward and position your upper arm against the inside of your thigh.", "Raise the dumbbell to the side, keeping your arm slightly bent and your palm facing down.", "Continue lifting until your arm is parallel to the floor.", "Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."], "instructions_zh": ["坐在上斜凳上，一只手拿着哑铃，将其放在大腿上。", "身体前倾，将上臂靠在大腿内侧。", "将哑铃举到一侧，保持手臂稍微弯曲，手掌朝下。", "继续抬起，直到手臂与地板平行。", "在最高点暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换到另一只手臂。"], "secondary_muscles": ["trapezius", "triceps"], "instructions_zh_hant": ["坐在上斜凳上，一只手拿著啞鈴，將其放在大腿上。", "身體前傾，將上臂靠在大腿內側。", "將啞鈴舉到一側，保持手臂稍微彎曲，手掌朝下。", "繼續抬起，直到手臂與地板平行。", "在最高點暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換到另一只手臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1281', 'exercise', 1, '{"id": "1281", "target": "pectorals", "name_en": "dumbbell incline one arm press", "name_zh": "哑铃上斜单臂推举", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1281-rDAiRf9.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴上斜單臂推舉", "instructions_en": ["Sit on an incline bench with a dumbbell in one hand, resting on your thigh.", "Lie back on the bench and position the dumbbell at shoulder level, palm facing forward.", "Press the dumbbell upward and slightly inward, extending your arm fully.", "Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."], "instructions_zh": ["坐在上斜凳上，一只手拿着哑铃，放在大腿上。", "仰卧在长凳上，将哑铃置于与肩同高的位置，手掌朝前。", "将哑铃向上并稍微向内推，充分伸展手臂。", "在最高点暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换到另一只手臂。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["坐在上斜凳上，一只手拿著啞鈴，放在大腿上。", "仰臥在長凳上，將啞鈴置于與肩同高的位置，手掌朝前。", "將啞鈴向上并稍微向內推，充分伸展手臂。", "在最高點暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換到另一只手臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1734', 'exercise', 1, '{"id": "1734", "target": "triceps", "name_en": "dumbbell kickbacks on exercise ball", "name_zh": "健身球哑铃臂后屈伸", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1734-cAvTaSg.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球啞鈴臂后屈伸", "instructions_en": ["Sit on an exercise ball with your feet flat on the ground and your back straight.", "Hold a dumbbell in each hand with your palms facing inwards and your arms bent at a 90-degree angle.", "Extend your arms straight back, squeezing your triceps at the top of the movement.", "Pause for a moment, then slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在健身球上，双脚平放在地上，背部挺直。", "双手各握一个哑铃，掌心向内，手臂弯曲成 90 度角。", "将手臂向后伸直，在动作的最高点挤压三头肌。", "暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "back"], "instructions_zh_hant": ["坐在健身球上，雙腳平放在地上，背部挺直。", "雙手各握一個啞鈴，掌心向內，手臂彎曲成 90 度角。", "將手臂向后伸直，在動作的最高點擠壓三頭肌。", "暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1282', 'exercise', 1, '{"id": "1282", "target": "pectorals", "name_en": "dumbbell incline one arm press on exercise ball", "name_zh": "健身球哑铃上斜单臂推举", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1282-Bg5JKSH.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球啞鈴上斜單臂推舉", "instructions_en": ["Sit on an exercise ball with a dumbbell in one hand, feet flat on the ground.", "Slowly walk your feet forward, rolling the ball until your head, neck, and upper back are supported on the ball.", "Hold the dumbbell at shoulder height with your palm facing forward.", "Press the dumbbell upward until your arm is fully extended.", "Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."], "instructions_zh": ["坐在健身球上，一只手拿着哑铃，双脚平放在地上。", "慢慢地向前移动你的脚，滚动球，直到你的头、脖子和上背部得到球的支撑。", "将哑铃握在与肩同高的位置，手掌朝前。", "向上推哑铃，直到手臂完全伸展。", "在最高点暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换到另一只手臂。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["坐在健身球上，一只手拿著啞鈴，雙腳平放在地上。", "慢慢地向前移動你的腳，滾動球，直到你的頭、脖子和上背部得到球的支撐。", "將啞鈴握在與肩同高的位置，手掌朝前。", "向上推啞鈴，直到手臂完全伸展。", "在最高點暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換到另一只手臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0324', 'exercise', 1, '{"id": "0324", "target": "pectorals", "name_en": "dumbbell incline palm-in press", "name_zh": "哑铃上斜掌心向内推举", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0324-OVLmUuL.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴上斜掌心向內推舉", "instructions_en": ["Set up an incline bench at a 45-degree angle.", "Sit on the bench with a dumbbell in each hand, palms facing each other.", "Plant your feet firmly on the ground and keep your back straight against the bench.", "Start with the dumbbells at shoulder level, elbows bent and palms facing each other.", "Press the dumbbells up and away from your body, extending your arms fully.", "Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["设置一个 45 度角的上斜凳。", "坐在长凳上，双手各握一个哑铃，手掌相对。", "将双脚牢牢踩在地面上，并保持背部挺直靠在长凳上。", "从与肩同高的哑铃开始，肘部弯曲，手掌相对。", "将哑铃向上推离身体，充分伸展手臂。", "在最高点暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["設置一個 45 度角的上斜凳。", "坐在長凳上，雙手各握一個啞鈴，手掌相對。", "將雙腳牢牢踩在地面上，并保持背部挺直靠在長凳上。", "從與肩同高的啞鈴開始，肘部彎曲，手掌相對。", "將啞鈴向上推離身體，充分伸展手臂。", "在最高點暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1283', 'exercise', 1, '{"id": "1283", "target": "pectorals", "name_en": "dumbbell incline press on exercise ball", "name_zh": "健身球哑铃上斜推举", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1283-bfiHMpI.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球啞鈴上斜推舉", "instructions_en": ["Sit on an exercise ball with a dumbbell in each hand, palms facing forward.", "Slowly walk your feet forward, rolling your body down the ball until your head, neck, and upper back are supported on the ball.", "Hold the dumbbells at shoulder level, elbows bent and pointing out to the sides.", "Press the dumbbells upward, extending your arms fully.", "Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在健身球上，每只手各握一个哑铃，手掌朝前。", "双脚慢慢向前移动，身体沿着球滚动，直到头部、颈部和上背部得到球的支撑。", "将哑铃保持在与肩同高的位置，肘部弯曲并指向两侧。", "向上推哑铃，充分伸展手臂。", "在最高点暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["坐在健身球上，每只手各握一個啞鈴，手掌朝前。", "雙腳慢慢向前移動，身體沿著球滾動，直到頭部、頸部和上背部得到球的支撐。", "將啞鈴保持在與肩同高的位置，肘部彎曲并指向兩側。", "向上推啞鈴，充分伸展手臂。", "在最高點暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0325', 'exercise', 1, '{"id": "0325", "target": "delts", "name_en": "dumbbell incline raise", "name_zh": "哑铃上斜抬举", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0325-nxW6BkN.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴上斜抬舉", "instructions_en": ["Sit on an incline bench with a dumbbell in each hand, resting on your thighs.", "Lean back on the bench and raise the dumbbells to shoulder height, palms facing forward.", "Keeping your back against the bench, exhale and raise the dumbbells above your head, fully extending your arms.", "Pause for a moment at the top, then inhale and slowly lower the dumbbells back to shoulder height.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在上斜凳上，每只手各拿一个哑铃，放在大腿上。", "向后靠在长凳上，将哑铃举至肩高，手掌朝前。", "背部靠在长凳上，呼气并将哑铃举过头顶，充分伸展双臂。", "在顶部停顿片刻，然后吸气，慢慢将哑铃放回肩部高度。", "重复所需的重复次数。"], "secondary_muscles": ["trapezius", "triceps"], "instructions_zh_hant": ["坐在上斜凳上，每只手各拿一個啞鈴，放在大腿上。", "向后靠在長凳上，將啞鈴舉至肩高，手掌朝前。", "背部靠在長凳上，呼氣并將啞鈴舉過頭頂，充分伸展雙臂。", "在頂部停頓片刻，然后吸氣，慢慢將啞鈴放回肩部高度。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0326', 'exercise', 1, '{"id": "0326", "target": "delts", "name_en": "dumbbell incline rear lateral raise", "name_zh": "哑铃上斜后束飞鸟", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0326-vYk8lqw.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴上斜后束飛鳥", "instructions_en": ["Set up an incline bench at a 45-degree angle.", "Sit on the bench with your chest against the backrest and hold a dumbbell in each hand.", "Extend your arms straight down with your palms facing each other.", "Keeping a slight bend in your elbows, raise your arms out to the sides until they are parallel to the ground.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["设置一个 45 度角的上斜凳。", "坐在长凳上，胸部靠在靠背上，双手各握一个哑铃。", "双臂伸直向下，手掌相对。", "保持肘部轻微弯曲，将手臂向两侧抬起，直到与地面平行。", "在顶部暂停片刻，然后慢慢将手臂放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["traps", "rhomboids"], "instructions_zh_hant": ["設置一個 45 度角的上斜凳。", "坐在長凳上，胸部靠在靠背上，雙手各握一個啞鈴。", "雙臂伸直向下，手掌相對。", "保持肘部輕微彎曲，將手臂向兩側抬起，直到與地面平行。", "在頂部暫停片刻，然后慢慢將手臂放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0327', 'exercise', 1, '{"id": "0327", "target": "upper back", "name_en": "dumbbell incline row", "name_zh": "哑铃上斜划船", "body_part": "back", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0327-7vG5o25.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴上斜劃船", "instructions_en": ["Set up an incline bench at a 45-degree angle.", "Grab a dumbbell in each hand and sit on the bench with your chest against the incline.", "Extend your arms fully, allowing the dumbbells to hang straight down from your shoulders.", "Pull the dumbbells up towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["设置一个 45 度角的上斜凳。", "双手各握一个哑铃，坐在长凳上，胸部靠在斜坡上。", "充分伸展双臂，让哑铃从肩膀上垂直垂下。", "将哑铃拉向胸部，将肩胛骨挤压在一起。", "在最高点暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "shoulders"], "instructions_zh_hant": ["設置一個 45 度角的上斜凳。", "雙手各握一個啞鈴，坐在長凳上，胸部靠在斜坡上。", "充分伸展雙臂，讓啞鈴從肩膀上垂直垂下。", "將啞鈴拉向胸部，將肩胛骨擠壓在一起。", "在最高點暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0328', 'exercise', 1, '{"id": "0328", "target": "serratus anterior", "name_en": "dumbbell incline shoulder raise", "name_zh": "哑铃上斜肩部抬举", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0328-6e2DcYX.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴上斜肩部抬舉", "instructions_en": ["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing down.", "Rest the dumbbells on your thighs and lean back onto the bench.", "Use your thighs to help raise the dumbbells to shoulder height, then rotate your wrists so that your palms are facing forward.", "Exhale and slowly raise the dumbbells above your head, keeping a slight bend in your elbows.", "Pause for a moment at the top, then inhale and slowly lower the dumbbells back to shoulder height.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将上斜凳摆成 45 度角，坐在上面，双手各握一个哑铃，掌心朝下。", "将哑铃放在大腿上，然后靠在长凳上。", "用大腿帮助将哑铃举至肩膀高度，然后旋转手腕，使手掌朝前。", "呼气，慢慢将哑铃举过头顶，保持肘部轻微弯曲。", "在顶部停顿片刻，然后吸气，慢慢将哑铃放回肩部高度。", "重复所需的重复次数。"], "secondary_muscles": ["deltoids", "trapezius"], "instructions_zh_hant": ["將上斜凳擺成 45 度角，坐在上面，雙手各握一個啞鈴，掌心朝下。", "將啞鈴放在大腿上，然后靠在長凳上。", "用大腿幫助將啞鈴舉至肩膀高度，然后旋轉手腕，使手掌朝前。", "呼氣，慢慢將啞鈴舉過頭頂，保持肘部輕微彎曲。", "在頂部停頓片刻，然后吸氣，慢慢將啞鈴放回肩部高度。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0329', 'exercise', 1, '{"id": "0329", "target": "traps", "name_en": "dumbbell incline shrug", "name_zh": "哑铃上斜耸肩", "body_part": "back", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0329-JymLInS.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴上斜聳肩", "instructions_en": ["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand.", "Place your feet flat on the ground and let your arms hang straight down with your palms facing your body.", "Keeping your arms straight, shrug your shoulders up towards your ears as high as possible.", "Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将上斜凳设置为 45 度角，坐在上面，双手各握一个哑铃。", "将双脚平放在地面上，让双臂笔直下垂，手掌朝向身体。", "保持手臂伸直，耸肩，尽可能高地靠近耳朵。", "保持收缩一会儿，然后慢慢将肩膀放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["將上斜凳設置為 45 度角，坐在上面，雙手各握一個啞鈴。", "將雙腳平放在地面上，讓雙臂筆直下垂，手掌朝向身體。", "保持手臂伸直，聳肩，盡可能高地靠近耳朵。", "保持收縮一會兒，然后慢慢將肩膀放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3542', 'exercise', 1, '{"id": "3542", "target": "delts", "name_en": "dumbbell incline t-raise", "name_zh": "哑铃上斜T字侧平举", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/3542-jgbvVJ0.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴上斜T字側平舉", "instructions_en": ["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards.", "Lean forward and let your arms hang straight down, perpendicular to the floor.", "Keeping your arms straight, raise them out to the sides until they are parallel to the floor, forming a ''T'' shape with your body.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将上斜凳摆成 45 度角，坐在上面，双手各握一个哑铃，掌心向内。", "向前倾斜，让手臂笔直向下垂，垂直于地板。", "保持手臂伸直，将它们向两侧举起，直到与地板平行，与身体形成“T”形。", "在顶部暂停片刻，然后慢慢将手臂放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["traps", "rhomboids"], "instructions_zh_hant": ["將上斜凳擺成 45 度角，坐在上面，雙手各握一個啞鈴，掌心向內。", "向前傾斜，讓手臂筆直向下垂，垂直于地板。", "保持手臂伸直，將它們向兩側舉起，直到與地板平行，與身體形成“T”形。", "在頂部暫停片刻，然后慢慢將手臂放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0330', 'exercise', 1, '{"id": "0330", "target": "triceps", "name_en": "dumbbell incline triceps extension", "name_zh": "哑铃上斜臂屈伸", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0330-OVIKwsd.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴上斜臂屈伸", "instructions_en": ["Sit on an incline bench with a dumbbell in each hand, palms facing inwards.", "Extend your arms fully overhead, keeping your elbows close to your head.", "Lower the dumbbells behind your head by bending your elbows, keeping your upper arms stationary.", "Pause for a moment, then raise the dumbbells back to the starting position by extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在上斜凳上，双手各握一个哑铃，掌心向内。", "将手臂完全伸过头顶，保持肘部靠近头部。", "弯曲肘部，将哑铃降低到头后，保持上臂静止。", "暂停片刻，然后伸展双臂将哑铃举回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["坐在上斜凳上，雙手各握一個啞鈴，掌心向內。", "將手臂完全伸過頭頂，保持肘部靠近頭部。", "彎曲肘部，將啞鈴降低到頭后，保持上臂靜止。", "暫停片刻，然后伸展雙臂將啞鈴舉回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1733', 'exercise', 1, '{"id": "1733", "target": "triceps", "name_en": "dumbbell incline two arm extension", "name_zh": "哑铃上斜双臂伸展", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1733-U7D9Fx3.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴上斜雙臂伸展", "instructions_en": ["Sit on an incline bench with a dumbbell in each hand, resting on your thighs.", "Slowly lie back on the bench, keeping the dumbbells close to your chest.", "Once you are fully lying down, extend your arms straight up towards the ceiling, keeping your elbows slightly bent.", "Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在上斜凳上，每只手各拿一个哑铃，放在大腿上。", "慢慢地躺在长凳上，保持哑铃靠近胸部。", "完全躺下后，将手臂伸向天花板，保持肘部稍微弯曲。", "在顶部停顿片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["坐在上斜凳上，每只手各拿一個啞鈴，放在大腿上。", "慢慢地躺在長凳上，保持啞鈴靠近胸部。", "完全躺下后，將手臂伸向天花板，保持肘部稍微彎曲。", "在頂部停頓片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3541', 'exercise', 1, '{"id": "3541", "target": "upper back", "name_en": "dumbbell incline y-raise", "name_zh": "哑铃上斜Y字上举", "body_part": "back", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/3541-PbzNu7c.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴上斜Y字上舉", "instructions_en": ["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards.", "Lean forward slightly and let your arms hang straight down, keeping a slight bend in your elbows.", "Raise your arms out to the sides and up in a Y shape until they are parallel to the ground.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将上斜凳摆成 45 度角，坐在上面，双手各握一个哑铃，掌心向内。", "稍微向前倾，让手臂伸直垂下，肘部保持轻微弯曲。", "将手臂向两侧抬起并呈 Y 形，直到与地面平行。", "在顶部暂停片刻，然后慢慢将手臂放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "rear deltoids"], "instructions_zh_hant": ["將上斜凳擺成 45 度角，坐在上面，雙手各握一個啞鈴，掌心向內。", "稍微向前傾，讓手臂伸直垂下，肘部保持輕微彎曲。", "將手臂向兩側抬起并呈 Y 形，直到與地面平行。", "在頂部暫停片刻，然后慢慢將手臂放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0332', 'exercise', 1, '{"id": "0332", "target": "delts", "name_en": "dumbbell iron cross", "name_zh": "哑铃十字支撑", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0332-cALkHHX.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴十字支撐", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.", "Raise your arms out to the sides until they are parallel to the ground, forming a T shape with your body.", "Pause for a moment, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃放在身体两侧。", "将双臂向两侧举起，直至与地面平行，与身体形成T字形。", "暂停片刻，然后慢慢将手臂放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "chest"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴放在身體兩側。", "將雙臂向兩側舉起，直至與地面平行，與身體形成T字形。", "暫停片刻，然后慢慢將手臂放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0333', 'exercise', 1, '{"id": "0333", "target": "triceps", "name_en": "dumbbell kickback", "name_zh": "哑铃臂后屈伸", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0333-W6PxUkg.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴臂后屈伸", "instructions_en": ["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Bring your upper arms close to your sides, with your elbows bent at a 90-degree angle.", "Extend your arms straight back, squeezing your triceps at the top of the movement.", "Pause for a moment, then slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，每只手各握一个哑铃。", "稍微弯曲膝盖，髋部向前转动，保持背部挺直。", "将上臂靠近身体两侧，肘部弯曲成 90 度角。", "将手臂向后伸直，在动作的最高点挤压三头肌。", "暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，每只手各握一個啞鈴。", "稍微彎曲膝蓋，髖部向前轉動，保持背部挺直。", "將上臂靠近身體兩側，肘部彎曲成 90 度角。", "將手臂向后伸直，在動作的最高點擠壓三頭肌。", "暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0341', 'exercise', 1, '{"id": "0341", "target": "delts", "name_en": "dumbbell lying one arm deltoid rear", "name_zh": "哑铃俯卧单臂后束飞鸟", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0341-gSw59a4.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴俯臥單臂后束飛鳥", "instructions_en": ["Lie face down on a flat bench with a dumbbell in one hand, palm facing inwards.", "Extend your arm straight down towards the floor, keeping it close to your body.", "Raise your arm up and back, squeezing your shoulder blade towards your spine.", "Pause for a moment at the top, then slowly lower your arm back down to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["脸朝下躺在平坦的长凳上，一只手握住哑铃，手掌朝内。", "将手臂笔直向下伸向地板，保持靠近身体。", "向上和向后举起手臂，将肩胛骨挤压向脊柱。", "在顶部暂停片刻，然后慢慢将手臂放回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["trapezius", "rhomboids"], "instructions_zh_hant": ["臉朝下躺在平坦的長凳上，一只手握住啞鈴，手掌朝內。", "將手臂筆直向下伸向地板，保持靠近身體。", "向上和向后舉起手臂，將肩胛骨擠壓向脊柱。", "在頂部暫停片刻，然后慢慢將手臂放回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1660', 'exercise', 1, '{"id": "1660", "target": "biceps", "name_en": "dumbbell kneeling bicep curl exercise ball", "name_zh": "哑铃跪姿二头弯举健身球", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1660-2JCuFTU.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴跪姿二頭彎舉健身球", "instructions_en": ["Kneel on the floor with an exercise ball in front of you.", "Place your elbows on top of the exercise ball, holding a dumbbell in each hand with your palms facing up.", "Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.", "Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["跪在地板上，面前放一个健身球。", "将肘部放在健身球上，双手各握一个哑铃，手掌朝上。", "保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。", "继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["跪在地板上，面前放一個健身球。", "將肘部放在健身球上，雙手各握一個啞鈴，手掌朝上。", "保持上臂靜止，呼氣并彎舉啞鈴，同時收縮二頭肌。", "繼續舉起啞鈴，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0335', 'exercise', 1, '{"id": "0335", "target": "delts", "name_en": "dumbbell lateral to front raise", "name_zh": "哑铃侧向至前平举", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0335-xMjBKwn.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴側向至前平舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.", "Keep your back straight and engage your core.", "Raise your arms out to the sides until they are parallel to the ground, keeping a slight bend in your elbows.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Next, raise your arms in front of you until they are parallel to the ground, again keeping a slight bend in your elbows.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。", "保持背部挺直并启动核心肌群。", "将手臂向两侧举起，直到与地面平行，保持肘部稍微弯曲。", "在顶部暂停片刻，然后慢慢将手臂放回起始位置。", "接下来，将手臂举到身前，直到它们与地面平行，再次保持肘部稍微弯曲。", "在顶部暂停片刻，然后慢慢将手臂放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["trapezius", "biceps"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴，手掌朝向身體。", "保持背部挺直并啟動核心肌群。", "將手臂向兩側舉起，直到與地面平行，保持肘部稍微彎曲。", "在頂部暫停片刻，然后慢慢將手臂放回起始位置。", "接下來，將手臂舉到身前，直到它們與地面平行，再次保持肘部稍微彎曲。", "在頂部暫停片刻，然后慢慢將手臂放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1658', 'exercise', 1, '{"id": "1658", "target": "biceps", "name_en": "dumbbell lunge with bicep curl", "name_zh": "哑铃弓步配合二头弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1658-Mz6lLcW.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴弓步配合二頭彎舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.", "Take a step forward with your right foot, lowering your body into a lunge position. Your right knee should be bent at a 90-degree angle and your left knee should be hovering just above the ground.", "As you lunge forward, simultaneously curl the dumbbells towards your shoulders, keeping your elbows close to your body.", "Pause for a moment at the bottom of the lunge, then push through your right heel to return to the starting position, lowering the dumbbells back down to your sides.", "Repeat the lunge and bicep curl on the opposite side, stepping forward with your left foot.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝前。", "右脚向前迈出一步，将身体降低至弓步位置。你的右膝应该弯曲成 90 度角，左膝应该悬停在地面上方。", "当你向前弓步时，同时将哑铃向肩膀弯曲，保持肘部靠近身体。", "在弓步底部停顿片刻，然后通过右脚跟推动回到起始位置，将哑铃放回身体两侧。", "在另一侧重复弓步和二头肌弯举，左脚向前迈出。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴，手掌朝前。", "右腳向前邁出一步，將身體降低至弓步位置。你的右膝應該彎曲成 90 度角，左膝應該懸停在地面上方。", "當你向前弓步時，同時將啞鈴向肩膀彎曲，保持肘部靠近身體。", "在弓步底部停頓片刻，然后通過右腳跟推動回到起始位置，將啞鈴放回身體兩側。", "在另一側重復弓步和二頭肌彎舉，左腳向前邁出。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0337', 'exercise', 1, '{"id": "0337", "target": "triceps", "name_en": "dumbbell lying extension (across face)", "name_zh": "哑铃仰卧跨面臂屈伸", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0337-L2V5Nan.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴仰臥跨面臂屈伸", "instructions_en": ["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.", "Hold a dumbbell with both hands and extend your arms straight up above your chest, palms facing each other.", "Keeping your upper arms stationary, slowly lower the dumbbell in an arc behind your head until your forearms are parallel to the ground.", "Pause for a moment, then contract your triceps to bring the dumbbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，双脚平放在地上，头放在长凳的末端。", "双手握住哑铃，双臂伸直至胸部上方，手掌相对。", "保持上臂静止，将哑铃在头后呈弧形缓慢降低，直到前臂与地面平行。", "暂停片刻，然后收缩三头肌，将哑铃带回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["平躺在長凳上，雙腳平放在地上，頭放在長凳的末端。", "雙手握住啞鈴，雙臂伸直至胸部上方，手掌相對。", "保持上臂靜止，將啞鈴在頭后呈弧形緩慢降低，直到前臂與地面平行。", "暫停片刻，然后收縮三頭肌，將啞鈴帶回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1729', 'exercise', 1, '{"id": "1729", "target": "triceps", "name_en": "dumbbell lying alternate extension", "name_zh": "哑铃卧姿交替伸展", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1729-NfP83rA.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴臥姿交替伸展", "instructions_en": ["Lie flat on a bench with a dumbbell in each hand, palms facing each other.", "Extend your arms straight up over your chest, keeping a slight bend in your elbows.", "Lower one dumbbell down towards your head, bending at the elbow, while keeping the other arm extended.", "Pause for a moment at the bottom, then raise the dumbbell back up to the starting position.", "Repeat with the other arm, alternating sides for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，双手各握一个哑铃，手掌相对。", "将手臂伸直越过胸部，保持肘部轻微弯曲。", "将一个哑铃朝头部方向放下，肘部弯曲，同时保持另一只手臂伸展。", "在底部停顿片刻，然后将哑铃举回到起始位置。", "用另一只手臂重复上述动作，交替进行所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["平躺在長凳上，雙手各握一個啞鈴，手掌相對。", "將手臂伸直越過胸部，保持肘部輕微彎曲。", "將一個啞鈴朝頭部方向放下，肘部彎曲，同時保持另一只手臂伸展。", "在底部停頓片刻，然后將啞鈴舉回到起始位置。", "用另一只手臂重復上述動作，交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0863', 'exercise', 1, '{"id": "0863", "target": "delts", "name_en": "dumbbell lying external shoulder rotation", "name_zh": "哑铃卧姿肩部外旋", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0863-bmBf7LN.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴臥姿肩部外旋", "instructions_en": ["Lie on your side on a flat bench with your upper arm against your side and your elbow bent 90 degrees.", "Hold a dumbbell in your hand with your palm facing down.", "Keeping your upper arm against your side, slowly rotate your forearm upward as far as possible.", "Pause for a moment at the top, then slowly lower your forearm back down to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["侧躺在平坦的长凳上，上臂靠在身体两侧，肘部弯曲 90 度。", "手中握住哑铃，手掌朝下。", "保持上臂靠在身体两侧，尽可能缓慢地向上旋转前臂。", "在顶部暂停片刻，然后慢慢将前臂放回起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["rotator cuff", "triceps"], "instructions_zh_hant": ["側躺在平坦的長凳上，上臂靠在身體兩側，肘部彎曲 90 度。", "手中握住啞鈴，手掌朝下。", "保持上臂靠在身體兩側，盡可能緩慢地向上旋轉前臂。", "在頂部暫停片刻，然后慢慢將前臂放回起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0339', 'exercise', 1, '{"id": "0339", "target": "hamstrings", "name_en": "dumbbell lying femoral", "name_zh": "哑铃卧姿腿弯举", "body_part": "upper legs", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0339-FkBIE6a.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴臥姿腿彎舉", "instructions_en": ["Lie flat on your back with your legs extended and a dumbbell resting on your lower abdomen.", "Bend your knees and bring the dumbbell towards your glutes, keeping your feet flat on the ground.", "Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，双腿伸直，将哑铃放在下腹部。", "弯曲膝盖，将哑铃拉向臀部，保持双脚平放在地面上。", "在最高点暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes"], "instructions_zh_hant": ["平躺，雙腿伸直，將啞鈴放在下腹部。", "彎曲膝蓋，將啞鈴拉向臀部，保持雙腳平放在地面上。", "在最高點暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0340', 'exercise', 1, '{"id": "0340", "target": "pectorals", "name_en": "dumbbell lying hammer press", "name_zh": "哑铃卧姿锤式推举", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0340-7gdLIXa.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴臥姿錘式推舉", "instructions_en": ["Lie flat on a bench with a dumbbell in each hand, palms facing each other and arms extended straight up.", "Lower the dumbbells to the sides of your chest, keeping your elbows at a 90-degree angle.", "Press the dumbbells back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，双手各握一个哑铃，手掌相对，双臂伸直向上。", "将哑铃放低至胸部两侧，保持肘部呈 90 度角。", "将哑铃推回到起始位置，充分伸展手臂。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["平躺在長凳上，雙手各握一個啞鈴，手掌相對，雙臂伸直向上。", "將啞鈴放低至胸部兩側，保持肘部呈 90 度角。", "將啞鈴推回到起始位置，充分伸展手臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2470', 'exercise', 1, '{"id": "2470", "target": "delts", "name_en": "dumbbell lying on floor rear delt raise", "name_zh": "哑铃地板仰卧后束飞鸟", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/2470-Ion0XWz.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴地板仰臥后束飛鳥", "instructions_en": ["Lie face down on the floor with a dumbbell in each hand, palms facing each other.", "Extend your arms straight out in front of you, keeping a slight bend in your elbows.", "Engaging your shoulder muscles, lift your arms up and out to the sides, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["脸朝下躺在地板上，双手各握一个哑铃，手掌相对。", "将手臂伸直在身前，保持肘部轻微弯曲。", "调动肩部肌肉，将手臂向上并向两侧抬起，将肩胛骨挤压在一起。", "在顶部暂停片刻，然后慢慢将手臂放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["trapezius", "rhomboids"], "instructions_zh_hant": ["臉朝下躺在地板上，雙手各握一個啞鈴，手掌相對。", "將手臂伸直在身前，保持肘部輕微彎曲。", "調動肩部肌肉，將手臂向上并向兩側抬起，將肩胛骨擠壓在一起。", "在頂部暫停片刻，然后慢慢將手臂放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0343', 'exercise', 1, '{"id": "0343", "target": "pectorals", "name_en": "dumbbell lying one arm press", "name_zh": "哑铃卧姿单臂推举", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0343-zGSIWQi.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴臥姿單臂推舉", "instructions_en": ["Lie flat on a bench with a dumbbell in one hand and your feet flat on the ground.", "Hold the dumbbell at shoulder level with your palm facing forward.", "Press the dumbbell upward until your arm is fully extended.", "Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."], "instructions_zh": ["平躺在长凳上，一只手拿着哑铃，双脚平放在地上。", "将哑铃举至肩部水平，手掌朝前。", "向上推哑铃，直到手臂完全伸展。", "在最高点暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换到另一只手臂。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["平躺在長凳上，一只手拿著啞鈴，雙腳平放在地上。", "將啞鈴舉至肩部水平，手掌朝前。", "向上推啞鈴，直到手臂完全伸展。", "在最高點暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換到另一只手臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0342', 'exercise', 1, '{"id": "0342", "target": "pectorals", "name_en": "dumbbell lying one arm press v. 2", "name_zh": "哑铃卧姿单臂推举变式2", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0342-K3dIO25.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴臥姿單臂推舉變式2", "instructions_en": ["Lie flat on a bench with your back supported and feet flat on the ground.", "Hold a dumbbell in one hand with your palm facing towards your feet.", "Extend your arm straight up towards the ceiling, keeping your elbow slightly bent.", "Slowly lower the dumbbell down towards your chest, keeping your elbow close to your body.", "Pause for a moment at the bottom, then push the dumbbell back up to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."], "instructions_zh": ["平躺在长凳上，背部支撑，双脚平放在地面上。", "一只手握住哑铃，手掌朝向脚部。", "将手臂伸向天花板，保持肘部稍微弯曲。", "慢慢地将哑铃向胸部方向降低，保持肘部靠近身体。", "在底部暂停片刻，然后将哑铃推回到起始位置。", "重复所需的重复次数，然后换到另一只手臂。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["平躺在長凳上，背部支撐，雙腳平放在地面上。", "一只手握住啞鈴，手掌朝向腳部。", "將手臂伸向天花板，保持肘部稍微彎曲。", "慢慢地將啞鈴向胸部方向降低，保持肘部靠近身體。", "在底部暫停片刻，然后將啞鈴推回到起始位置。", "重復所需的重復次數，然后換到另一只手臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0344', 'exercise', 1, '{"id": "0344", "target": "triceps", "name_en": "dumbbell lying one arm pronated triceps extension", "name_zh": "哑铃卧姿单臂正握臂屈伸", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0344-wyaqzOS.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴臥姿單臂正握臂屈伸", "instructions_en": ["Lie flat on a bench with your back and head supported, and your feet flat on the ground.", "Hold a dumbbell in one hand with your palm facing down, and extend your arm straight up above your shoulder.", "Keeping your upper arm stationary, slowly lower the dumbbell behind your head by bending your elbow.", "Pause for a moment at the bottom, then extend your arm back up to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["平躺在长凳上，背部和头部得到支撑，双脚平放在地面上。", "一只手握住哑铃，手掌朝下，将手臂伸直至肩膀上方。", "保持上臂静止，弯曲肘部，慢慢将哑铃降低到脑后。", "在底部停顿片刻，然后将手臂伸回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["平躺在長凳上，背部和頭部得到支撐，雙腳平放在地面上。", "一只手握住啞鈴，手掌朝下，將手臂伸直至肩膀上方。", "保持上臂靜止，彎曲肘部，慢慢將啞鈴降低到腦后。", "在底部停頓片刻，然后將手臂伸回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0345', 'exercise', 1, '{"id": "0345", "target": "delts", "name_en": "dumbbell lying one arm rear lateral raise", "name_zh": "哑铃卧姿单臂后束飞鸟", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0345-KwFGiEP.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴臥姿單臂后束飛鳥", "instructions_en": ["Lie face down on a flat bench with a dumbbell in one hand, hanging towards the floor.", "Keep your arm straight and lift the dumbbell out to the side, away from your body.", "Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."], "instructions_zh": ["脸朝下躺在平坦的长凳上，一只手拿着哑铃，垂向地板。", "保持手臂伸直，将哑铃举到一侧，远离身体。", "在顶部停顿片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换到另一只手臂。"], "secondary_muscles": ["traps", "rhomboids"], "instructions_zh_hant": ["臉朝下躺在平坦的長凳上，一只手拿著啞鈴，垂向地板。", "保持手臂伸直，將啞鈴舉到一側，遠離身體。", "在頂部停頓片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換到另一只手臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0536', 'exercise', 1, '{"id": "0536", "target": "glutes", "name_en": "kettlebell lunge pass through", "name_zh": "壶铃弓步胯下传递", "body_part": "upper legs", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0536-WKMQzCD.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴弓步胯下傳遞", "instructions_en": ["Stand with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands.", "Take a step forward with your right foot, lowering your body into a lunge position.", "As you lunge forward, pass the kettlebell under your right thigh and transfer it to your left hand.", "Push off with your right foot to return to the starting position, while simultaneously passing the kettlebell back to your right hand.", "Repeat the lunge on the opposite side, passing the kettlebell under your left thigh.", "Continue alternating lunges and passing the kettlebell between hands for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手握住壶铃放在胸前。", "右脚向前迈出一步，将身体降低至弓步位置。", "当你向前弓步时，将壶铃传递到右大腿下方，然后将其转移到左手。", "用右脚蹬地回到起始位置，同时将壶铃传回右手。", "在另一侧重复弓步，将壶铃传递到左大腿下方。", "继续交替弓步并在双手之间传递壶铃，达到所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手握住壺鈴放在胸前。", "右腳向前邁出一步，將身體降低至弓步位置。", "當你向前弓步時，將壺鈴傳遞到右大腿下方，然后將其轉移到左手。", "用右腳蹬地回到起始位置，同時將壺鈴傳回右手。", "在另一側重復弓步，將壺鈴傳遞到左大腿下方。", "繼續交替弓步并在雙手之間傳遞壺鈴，達到所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0346', 'exercise', 1, '{"id": "0346", "target": "triceps", "name_en": "dumbbell lying one arm supinated triceps extension", "name_zh": "哑铃卧姿单臂反握臂屈伸", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0346-zZlORz6.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴臥姿單臂反握臂屈伸", "instructions_en": ["Lie flat on a bench with your back and head supported, and your feet flat on the ground.", "Hold a dumbbell in one hand with an underhand grip, and extend your arm straight up above your shoulder.", "Keeping your upper arm stationary, slowly lower the dumbbell behind your head by bending your elbow.", "Pause for a moment at the bottom, then extend your arm back up to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["平躺在长凳上，背部和头部得到支撑，双脚平放在地面上。", "一只手握住哑铃，反握，将手臂伸直至肩膀上方。", "保持上臂静止，弯曲肘部，慢慢将哑铃降低到脑后。", "在底部停顿片刻，然后将手臂伸回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["平躺在長凳上，背部和頭部得到支撐，雙腳平放在地面上。", "一只手握住啞鈴，反握，將手臂伸直至肩膀上方。", "保持上臂靜止，彎曲肘部，慢慢將啞鈴降低到腦后。", "在底部停頓片刻，然后將手臂伸回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0347', 'exercise', 1, '{"id": "0347", "target": "forearms", "name_en": "dumbbell lying pronation", "name_zh": "哑铃卧姿旋前", "body_part": "lower arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0347-mym4hJo.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴臥姿旋前", "instructions_en": ["Lie flat on a bench with your chest facing down and your arms extended straight down, holding a dumbbell in each hand.", "Rotate your palms so they are facing up.", "Keeping your upper arms stationary, exhale and curl the dumbbells as you rotate your palms to face down.", "Inhale and slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，胸部朝下，双臂伸直向下，每只手各握一个哑铃。", "旋转手掌，使手掌朝上。", "保持上臂静止，呼气并弯曲哑铃，同时将手掌旋转至面朝下。", "吸气并慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "shoulders"], "instructions_zh_hant": ["平躺在長凳上，胸部朝下，雙臂伸直向下，每只手各握一個啞鈴。", "旋轉手掌，使手掌朝上。", "保持上臂靜止，呼氣并彎曲啞鈴，同時將手掌旋轉至面朝下。", "吸氣并慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2705', 'exercise', 1, '{"id": "2705", "target": "forearms", "name_en": "dumbbell lying pronation on floor", "name_zh": "哑铃卧姿旋前（地板）", "body_part": "lower arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/2705-7RWNjiB.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴臥姿旋前（地板）", "instructions_en": ["Lie flat on the floor with your face down and your arms extended straight out in front of you, holding a dumbbell in each hand.", "Rotate your palms so they are facing down towards the floor.", "Keeping your arms straight, lift the dumbbells off the floor by contracting your forearms.", "Continue lifting until your forearms are fully contracted and the dumbbells are at shoulder level.", "Hold for a moment, then slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在地板上，脸朝下，双臂伸直在身前，每只手各握一个哑铃。", "旋转手掌，使其朝下朝向地板。", "保持手臂伸直，收缩前臂将哑铃提离地板。", "继续举起，直到前臂完全收缩并且哑铃与肩部齐平。", "保持一会儿，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "triceps"], "instructions_zh_hant": ["平躺在地板上，臉朝下，雙臂伸直在身前，每只手各握一個啞鈴。", "旋轉手掌，使其朝下朝向地板。", "保持手臂伸直，收縮前臂將啞鈴提離地板。", "繼續舉起，直到前臂完全收縮并且啞鈴與肩部齊平。", "保持一會兒，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1284', 'exercise', 1, '{"id": "1284", "target": "pectorals", "name_en": "dumbbell lying pullover on exercise ball", "name_zh": "健身球哑铃仰卧上拉", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1284-iK59oEA.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球啞鈴仰臥上拉", "instructions_en": ["Sit on an exercise ball and roll forward until your upper back is resting on the ball.", "Hold a dumbbell with both hands and extend your arms straight up over your chest.", "Slowly lower the dumbbell behind your head while keeping your arms straight.", "Pause for a moment, then raise the dumbbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在健身球上，向前滚动，直到上背部靠在球上。", "双手握住哑铃，将手臂伸直至胸部上方。", "慢慢地将哑铃放到脑后，同时保持手臂伸直。", "暂停片刻，然后将哑铃举回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders", "back"], "instructions_zh_hant": ["坐在健身球上，向前滾動，直到上背部靠在球上。", "雙手握住啞鈴，將手臂伸直至胸部上方。", "慢慢地將啞鈴放到腦后，同時保持手臂伸直。", "暫停片刻，然后將啞鈴舉回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0552', 'exercise', 1, '{"id": "0552", "target": "delts", "name_en": "kettlebell two arm clean", "name_zh": "壶铃双臂翻举", "body_part": "shoulders", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0552-7Ba7bQ2.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴雙臂翻舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a kettlebell in front of your thighs with both hands, palms facing towards you.", "Bend your knees slightly and hinge at the hips, lowering the kettlebell towards the ground.", "Explosively extend your hips and knees, using the momentum to pull the kettlebell up towards your shoulders.", "As the kettlebell reaches shoulder height, rotate your wrists and catch the kettlebell in the rack position, with your elbows tucked in and the kettlebell resting on the back of your forearm.", "Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手握住壶铃放在大腿前，手掌朝向自己。", "稍微弯曲膝盖并铰接臀部，将壶铃降低到地面。", "爆发性伸展臀部和膝盖，利用动量将壶铃拉向肩膀。", "当壶铃达到肩膀高度时，旋转手腕，将壶铃放在架子上，肘部内收，壶铃放在前臂背面。", "将壶铃放回起始位置，然后重复所需的重复次数。"], "secondary_muscles": ["traps", "forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手握住壺鈴放在大腿前，手掌朝向自己。", "稍微彎曲膝蓋并鉸接臀部，將壺鈴降低到地面。", "爆發性伸展臀部和膝蓋，利用動量將壺鈴拉向肩膀。", "當壺鈴達到肩膀高度時，旋轉手腕，將壺鈴放在架子上，肘部內收，壺鈴放在前臂背面。", "將壺鈴放回起始位置，然后重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1328', 'exercise', 1, '{"id": "1328", "target": "upper back", "name_en": "dumbbell lying rear delt row", "name_zh": "哑铃卧姿三角肌后束划船", "body_part": "back", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1328-XUUD0Fs.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴臥姿三角肌后束劃船", "instructions_en": ["Lie face down on a flat bench with a dumbbell in each hand, palms facing inwards.", "Extend your arms straight down towards the floor, keeping a slight bend in your elbows.", "Engaging your back muscles, lift the dumbbells up towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["脸朝下躺在平坦的长凳上，每只手各握一个哑铃，手掌朝内。", "将手臂伸直向下伸向地板，肘部保持轻微弯曲。", "调动背部肌肉，将哑铃举向胸部，将肩胛骨挤压在一起。", "在顶部停顿片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "biceps"], "instructions_zh_hant": ["臉朝下躺在平坦的長凳上，每只手各握一個啞鈴，手掌朝內。", "將手臂伸直向下伸向地板，肘部保持輕微彎曲。", "調動背部肌肉，將啞鈴舉向胸部，將肩胛骨擠壓在一起。", "在頂部停頓片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0348', 'exercise', 1, '{"id": "0348", "target": "delts", "name_en": "dumbbell lying rear lateral raise", "name_zh": "哑铃卧姿后束飞鸟", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0348-53Ttlck.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴臥姿后束飛鳥", "instructions_en": ["Lie face down on a flat bench with a dumbbell in each hand, palms facing each other.", "Extend your arms straight down towards the floor, keeping a slight bend in your elbows.", "Engaging your shoulder muscles, lift your arms out to the sides until they are parallel to the floor.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["脸朝下躺在平坦的长凳上，双手各握一个哑铃，手掌相对。", "将手臂伸直向下伸向地板，肘部保持轻微弯曲。", "调动肩部肌肉，将手臂向两侧抬起，直到与地板平行。", "在顶部暂停片刻，然后慢慢将手臂放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["traps", "rhomboids"], "instructions_zh_hant": ["臉朝下躺在平坦的長凳上，雙手各握一個啞鈴，手掌相對。", "將手臂伸直向下伸向地板，肘部保持輕微彎曲。", "調動肩部肌肉，將手臂向兩側抬起，直到與地板平行。", "在頂部暫停片刻，然后慢慢將手臂放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1735', 'exercise', 1, '{"id": "1735", "target": "triceps", "name_en": "dumbbell lying single extension", "name_zh": "哑铃卧姿单侧伸展", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1735-6MfS53i.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴臥姿單側伸展", "instructions_en": ["Lie flat on a bench with a dumbbell in one hand and your arm fully extended above your chest.", "Lower the dumbbell in a controlled manner towards your forehead, keeping your upper arm stationary.", "Pause briefly at the bottom of the movement, then extend your arm back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["平躺在长凳上，一只手拿着哑铃，手臂完全伸展到胸部上方。", "以受控的方式将哑铃降低到前额，保持上臂静止。", "在动作底部短暂暂停，然后将手臂伸展回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["平躺在長凳上，一只手拿著啞鈴，手臂完全伸展到胸部上方。", "以受控的方式將啞鈴降低到前額，保持上臂靜止。", "在動作底部短暫暫停，然后將手臂伸展回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0349', 'exercise', 1, '{"id": "0349", "target": "forearms", "name_en": "dumbbell lying supination", "name_zh": "哑铃卧姿旋后", "body_part": "lower arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0349-M2Pm3zj.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴臥姿旋后", "instructions_en": ["Lie flat on a bench with your feet flat on the ground.", "Hold a dumbbell in each hand with your palms facing up and your arms fully extended.", "Keeping your upper arms stationary, curl the dumbbells towards your shoulders by contracting your forearms.", "Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，双脚平放在地上。", "每只手握住一个哑铃，手掌朝上，双臂完全伸展。", "保持上臂不动，收缩前臂，将哑铃向肩膀方向卷曲。", "在最高点暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "shoulders"], "instructions_zh_hant": ["平躺在長凳上，雙腳平放在地上。", "每只手握住一個啞鈴，手掌朝上，雙臂完全伸展。", "保持上臂不動，收縮前臂，將啞鈴向肩膀方向卷曲。", "在最高點暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2706', 'exercise', 1, '{"id": "2706", "target": "forearms", "name_en": "dumbbell lying supination on floor", "name_zh": "哑铃卧姿旋后（地板）", "body_part": "lower arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/2706-rEhi2o5.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴臥姿旋后（地板）", "instructions_en": ["Lie flat on your back on the floor with your legs extended and your arms by your sides, holding a dumbbell in each hand.", "Rotate your palms to face up, keeping your elbows close to your sides.", "Slowly curl the dumbbells towards your shoulders, squeezing your forearms.", "Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["仰卧在地板上，双腿伸直，双臂放在身体两侧，每只手各握一个哑铃。", "将手掌旋转至向上，保持肘部靠近身体两侧。", "慢慢地将哑铃向肩膀弯曲，挤压前臂。", "在顶部停顿片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "shoulders"], "instructions_zh_hant": ["仰臥在地板上，雙腿伸直，雙臂放在身體兩側，每只手各握一個啞鈴。", "將手掌旋轉至向上，保持肘部靠近身體兩側。", "慢慢地將啞鈴向肩膀彎曲，擠壓前臂。", "在頂部停頓片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0350', 'exercise', 1, '{"id": "0350", "target": "biceps", "name_en": "dumbbell lying supine curl", "name_zh": "哑铃仰卧弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0350-KUaZst7.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴仰臥彎舉", "instructions_en": ["Lie flat on a bench with a dumbbell in each hand, palms facing up and arms fully extended.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，双手各握一个哑铃，手掌朝上，双臂完全伸展。", "保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。", "继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["平躺在長凳上，雙手各握一個啞鈴，手掌朝上，雙臂完全伸展。", "保持上臂靜止，呼氣并彎舉啞鈴，同時收縮二頭肌。", "繼續舉起啞鈴，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0351', 'exercise', 1, '{"id": "0351", "target": "triceps", "name_en": "dumbbell lying triceps extension", "name_zh": "哑铃卧姿臂屈伸", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0351-mpKZGWz.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴臥姿臂屈伸", "instructions_en": ["Lie flat on a bench with a dumbbell in each hand, palms facing each other.", "Extend your arms straight up over your chest, keeping your elbows close to your body.", "Lower the dumbbells down towards your forehead, bending your elbows.", "Pause for a moment, then extend your arms back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，双手各握一个哑铃，手掌相对。", "将手臂伸直越过胸部，保持肘部靠近身体。", "将哑铃向前额方向降低，弯曲肘部。", "暂停片刻，然后将手臂伸回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["平躺在長凳上，雙手各握一個啞鈴，手掌相對。", "將手臂伸直越過胸部，保持肘部靠近身體。", "將啞鈴向前額方向降低，彎曲肘部。", "暫停片刻，然后將手臂伸回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0364', 'exercise', 1, '{"id": "0364", "target": "forearms", "name_en": "dumbbell one arm wrist curl", "name_zh": "哑铃单臂腕弯举", "body_part": "lower arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0364-q8aHNoF.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴單臂腕彎舉", "instructions_en": ["Sit on a bench or chair with your feet flat on the ground.", "Hold a dumbbell in one hand with an underhand grip, resting your forearm on your thigh.", "Allow your wrist to extend, letting the dumbbell roll down towards your fingers.", "Slowly curl your wrist back up, bringing the dumbbell towards your forearm.", "Repeat for the desired number of repetitions, then switch to the other hand."], "instructions_zh": ["坐在长凳或椅子上，双脚平放在地面上。", "一只手握住哑铃，反握，将前臂放在大腿上。", "让你的手腕伸展，让哑铃向你的手指方向滚动。", "慢慢地向后弯曲手腕，将哑铃拉向前臂。", "重复所需的重复次数，然后换另一只手。"], "secondary_muscles": ["biceps", "brachialis"], "instructions_zh_hant": ["坐在長凳或椅子上，雙腳平放在地面上。", "一只手握住啞鈴，反握，將前臂放在大腿上。", "讓你的手腕伸展，讓啞鈴向你的手指方向滾動。", "慢慢地向后彎曲手腕，將啞鈴拉向前臂。", "重復所需的重復次數，然后換另一只手。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1662', 'exercise', 1, '{"id": "1662", "target": "biceps", "name_en": "dumbbell lying wide curl", "name_zh": "哑铃卧姿宽距弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1662-qm9veZw.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴臥姿寬距彎舉", "instructions_en": ["Lie flat on a bench with a dumbbell in each hand, palms facing up and arms fully extended.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，双手各握一个哑铃，手掌朝上，双臂完全伸展。", "保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。", "继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["平躺在長凳上，雙手各握一個啞鈴，手掌朝上，雙臂完全伸展。", "保持上臂靜止，呼氣并彎舉啞鈴，同時收縮二頭肌。", "繼續舉重，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1496', 'exercise', 1, '{"id": "1496", "target": "abs", "name_en": "sledge hammer", "name_zh": "大锤砸击", "body_part": "waist", "equipment": "hammer", "gif_asset": "assets/fitness/videos/1496-REXmfVC.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "大錘砸擊", "instructions_en": ["Stand with your feet shoulder-width apart and hold the sledge hammer with both hands.", "Engage your core and keep your back straight.", "Swing the sledge hammer down towards the ground, using your core and upper body strength.", "As you swing down, pivot your hips and transfer the force to the hammer.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手握住大锤。", "启动你的核心并保持背部挺直。", "使用核心和上半身的力量，将大锤向下挥向地面。", "当你向下挥杆时，转动臀部并将力量传递到锤子上。", "重复所需的重复次数。"], "secondary_muscles": ["forearms", "shoulders"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手握住大錘。", "啟動你的核心并保持背部挺直。", "使用核心和上半身的力量，將大錘向下揮向地面。", "當你向下揮桿時，轉動臀部并將力量傳遞到錘子上。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0352', 'exercise', 1, '{"id": "0352", "target": "triceps", "name_en": "dumbbell neutral grip bench press", "name_zh": "哑铃中立握卧推", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0352-pP8wP2P.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴中立握臥推", "instructions_en": ["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.", "Hold a dumbbell in each hand with a neutral grip (palms facing each other) and your arms extended straight up over your chest.", "Slowly lower the dumbbells down towards your chest, keeping your elbows close to your body.", "Pause for a moment at the bottom, then push the dumbbells back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，双脚平放在地上，背部紧贴长凳。", "每只手握一个哑铃，中立握法（手掌相对），双臂伸直越过胸部。", "慢慢地将哑铃降低到胸部，保持肘部靠近身体。", "在底部停顿片刻，然后将哑铃推回起始位置，完全伸展手臂。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["平躺在長凳上，雙腳平放在地上，背部緊貼長凳。", "每只手握一個啞鈴，中立握法（手掌相對），雙臂伸直越過胸部。", "慢慢地將啞鈴降低到胸部，保持肘部靠近身體。", "在底部停頓片刻，然后將啞鈴推回起始位置，完全伸展手臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1285', 'exercise', 1, '{"id": "1285", "target": "pectorals", "name_en": "dumbbell one arm bench fly", "name_zh": "哑铃单臂凳上飞鸟", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1285-o5Jsk92.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴單臂凳上飛鳥", "instructions_en": ["Sit on a flat bench with a dumbbell in one hand, resting it on top of your thigh.", "Lie back on the bench, keeping the dumbbell pressed against your thigh.", "Using your free hand, help lift the dumbbell up to the starting position.", "Hold the dumbbell directly above your shoulder with your arm extended and palm facing inward.", "Lower the dumbbell out to the side in a wide arc, keeping a slight bend in your elbow.", "Pause when your arm is parallel to the ground, then reverse the movement and bring the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms and repeat."], "instructions_zh": ["坐在平坦的长凳上，一只手拿着哑铃，将其放在大腿上方。", "向后躺在长凳上，将哑铃压在大腿上。", "用空着的那只手帮助将哑铃举至起始位置。", "将哑铃握在肩膀正上方，手臂伸展，手掌朝内。", "将哑铃以宽弧线向一侧放低，保持肘部轻微弯曲。", "当手臂与地面平行时暂停，然后反向运动并将哑铃带回起始位置。", "重复所需的重复次数，然后换臂重复。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["坐在平坦的長凳上，一只手拿著啞鈴，將其放在大腿上方。", "向后躺在長凳上，將啞鈴壓在大腿上。", "用空著的那只手幫助將啞鈴舉至起始位置。", "將啞鈴握在肩膀正上方，手臂伸展，手掌朝內。", "將啞鈴以寬弧線向一側放低，保持肘部輕微彎曲。", "當手臂與地面平行時暫停，然后反向運動并將啞鈴帶回起始位置。", "重復所需的重復次數，然后換臂重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1286', 'exercise', 1, '{"id": "1286", "target": "pectorals", "name_en": "dumbbell one arm chest fly on exercise ball", "name_zh": "健身球哑铃单臂胸部飞鸟", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1286-Bpkf41o.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球啞鈴單臂胸部飛鳥", "instructions_en": ["Sit on an exercise ball with a dumbbell in one hand and your feet flat on the ground.", "Walk your feet forward, rolling the ball until your upper back is supported on the ball and your head, neck, and shoulders are off the ball.", "Extend your arm with the dumbbell straight up above your chest, palm facing inward.", "Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.", "Pause for a moment when your arm is parallel to the ground.", "Engage your chest muscles to bring the dumbbell back up to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["坐在健身球上，一只手拿着哑铃，双脚平放在地上。", "双脚向前走，滚动球，直到你的上背部受到球的支撑，并且你的头、脖子和肩膀离开球。", "将手臂伸直，将哑铃举至胸部上方，手掌朝内。", "慢慢地将哑铃向一侧放低，保持肘部轻微弯曲。", "当手臂与地面平行时暂停片刻。", "启动胸部肌肉，将哑铃拉回到起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["坐在健身球上，一只手拿著啞鈴，雙腳平放在地上。", "雙腳向前走，滾動球，直到你的上背部受到球的支撐，并且你的頭、脖子和肩膀離開球。", "將手臂伸直，將啞鈴舉至胸部上方，手掌朝內。", "慢慢地將啞鈴向一側放低，保持肘部輕微彎曲。", "當手臂與地面平行時暫停片刻。", "啟動胸部肌肉，將啞鈴拉回到起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0353', 'exercise', 1, '{"id": "0353", "target": "biceps", "name_en": "dumbbell one arm concentration curl (on stability ball)", "name_zh": "健身球哑铃单臂集中弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0353-k5IpyHg.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球啞鈴單臂集中彎舉", "instructions_en": ["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.", "Hold a dumbbell in one hand with your palm facing up and your arm extended down towards the floor.", "Rest your elbow on the inside of your thigh, just above the knee.", "Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder while contracting your biceps.", "Pause for a moment at the top of the movement, then inhale and slowly lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch arms and repeat."], "instructions_zh": ["坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。", "一只手握住哑铃，手掌朝上，手臂向下伸向地板。", "将肘部放在大腿内侧、膝盖上方。", "保持上臂静止，呼气并将哑铃向上弯向肩膀，同时收缩二头肌。", "在动作的最高点停顿片刻，然后吸气，慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换臂重复。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在穩定球上，雙腳平放在地面上，膝蓋彎曲成 90 度角。", "一只手握住啞鈴，手掌朝上，手臂向下伸向地板。", "將肘部放在大腿內側、膝蓋上方。", "保持上臂靜止，呼氣并將啞鈴向上彎向肩膀，同時收縮二頭肌。", "在動作的最高點停頓片刻，然后吸氣，慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換臂重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1287', 'exercise', 1, '{"id": "1287", "target": "pectorals", "name_en": "dumbbell one arm decline chest press", "name_zh": "哑铃单臂下斜推胸", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1287-REGM1dE.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴單臂下斜推胸", "instructions_en": ["Lie on a decline bench with a dumbbell in one hand, resting on your chest.", "Place your feet flat on the ground and keep your back pressed against the bench.", "Extend your arm and push the dumbbell up towards the ceiling, fully extending your elbow.", "Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."], "instructions_zh": ["躺在下斜长凳上，一只手握住哑铃，放在胸前。", "将双脚平放在地面上，并将背部压在长凳上。", "伸展手臂，将哑铃推向天花板，充分伸展肘部。", "在顶部停顿片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换到另一只手臂。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["躺在下斜長凳上，一只手握住啞鈴，放在胸前。", "將雙腳平放在地面上，并將背部壓在長凳上。", "伸展手臂，將啞鈴推向天花板，充分伸展肘部。", "在頂部停頓片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換到另一只手臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1288', 'exercise', 1, '{"id": "1288", "target": "pectorals", "name_en": "dumbbell one arm fly on exercise ball", "name_zh": "健身球哑铃单臂飞鸟", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1288-Am02iPd.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球啞鈴單臂飛鳥", "instructions_en": ["Sit on an exercise ball with a dumbbell in one hand and your feet flat on the ground.", "Walk your feet forward and roll your body down until your upper back is resting on the exercise ball.", "Extend your arm with the dumbbell straight up above your chest, palm facing inwards.", "Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.", "Pause for a moment, then squeeze your chest muscles to bring the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["坐在健身球上，一只手拿着哑铃，双脚平放在地上。", "双脚向前走，身体向下滚动，直到上背部靠在健身球上。", "将手臂伸直，将哑铃举至胸部上方，手掌朝内。", "慢慢地将哑铃向一侧放低，保持肘部轻微弯曲。", "暂停片刻，然后挤压胸部肌肉，使哑铃回到起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["坐在健身球上，一只手拿著啞鈴，雙腳平放在地上。", "雙腳向前走，身體向下滾動，直到上背部靠在健身球上。", "將手臂伸直，將啞鈴舉至胸部上方，手掌朝內。", "慢慢地將啞鈴向一側放低，保持肘部輕微彎曲。", "暫停片刻，然后擠壓胸部肌肉，使啞鈴回到起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1736', 'exercise', 1, '{"id": "1736", "target": "triceps", "name_en": "dumbbell one arm french press on exercise ball", "name_zh": "健身球哑铃单臂法式推举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1736-ziFKQXP.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球啞鈴單臂法式推舉", "instructions_en": ["Sit on an exercise ball with your feet flat on the ground and your back straight.", "Hold a dumbbell in one hand with your palm facing up and your elbow bent at a 90-degree angle.", "Extend your arm straight up towards the ceiling, keeping your elbow stationary.", "Slowly lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["坐在健身球上，双脚平放在地上，背部挺直。", "一只手握住哑铃，手掌朝上，肘部弯曲成 90 度角。", "将手臂伸向天花板，保持肘部不动。", "慢慢地将哑铃放回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["坐在健身球上，雙腳平放在地上，背部挺直。", "一只手握住啞鈴，手掌朝上，肘部彎曲成 90 度角。", "將手臂伸向天花板，保持肘部不動。", "慢慢地將啞鈴放回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1663', 'exercise', 1, '{"id": "1663", "target": "biceps", "name_en": "dumbbell one arm hammer preacher curl", "name_zh": "哑铃单臂锤式牧师凳弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1663-4dF3maG.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴單臂錘式牧師凳彎舉", "instructions_en": ["Sit on a preacher bench with a dumbbell in one hand and your upper arm resting on the pad.", "Hold the dumbbell with a neutral grip (palms facing your body).", "Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.", "Pause for a moment at the top, squeezing your biceps.", "Inhale and slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["坐在牧师凳上，一只手拿着哑铃，上臂放在垫子上。", "以中立握法握住哑铃（手掌朝向身体）。", "保持上臂静止，呼气并将哑铃向上弯向肩膀。", "在顶部暂停片刻，挤压你的二头肌。", "吸气，慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在牧師凳上，一只手拿著啞鈴，上臂放在墊子上。", "以中立握法握住啞鈴（手掌朝向身體）。", "保持上臂靜止，呼氣并將啞鈴向上彎向肩膀。", "在頂部暫停片刻，擠壓你的二頭肌。", "吸氣，慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1621', 'exercise', 1, '{"id": "1621", "target": "triceps", "name_en": "dumbbell one arm hammer press on exercise ball", "name_zh": "健身球哑铃单臂锤式推举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1621-VYmYxK5.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球啞鈴單臂錘式推舉", "instructions_en": ["Sit on an exercise ball with your feet flat on the ground and your back straight.", "Hold a dumbbell in one hand with your palm facing inwards and your elbow bent at a 90-degree angle.", "Place your other hand on your hip for stability.", "Press the dumbbell upwards, extending your arm fully.", "Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["坐在健身球上，双脚平放在地上，背部挺直。", "一只手握住哑铃，掌心向内，肘部弯曲成 90 度角。", "将另一只手放在臀部上以保持稳定。", "向上推哑铃，充分伸展手臂。", "在最高点暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["shoulders", "chest"], "instructions_zh_hant": ["坐在健身球上，雙腳平放在地上，背部挺直。", "一只手握住啞鈴，掌心向內，肘部彎曲成 90 度角。", "將另一只手放在臀部上以保持穩定。", "向上推啞鈴，充分伸展手臂。", "在最高點暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1289', 'exercise', 1, '{"id": "1289", "target": "pectorals", "name_en": "dumbbell one arm incline chest press", "name_zh": "哑铃单臂上斜推胸", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1289-PDaMuyV.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴單臂上斜推胸", "instructions_en": ["Adjust the incline bench to a 45-degree angle.", "Sit on the bench with your back against the pad and feet flat on the ground.", "Hold a dumbbell in one hand with an overhand grip, resting it on your shoulder.", "Push the dumbbell up and away from your body, extending your arm fully.", "Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."], "instructions_zh": ["将上斜凳调整至 45 度角。", "坐在长凳上，背部靠在垫子上，双脚平放在地面上。", "一只手握住哑铃，正手握住，将其放在肩膀上。", "将哑铃向上推离身体，完全伸展手臂。", "在顶部停顿片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换到另一只手臂。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["將上斜凳調整至 45 度角。", "坐在長凳上，背部靠在墊子上，雙腳平放在地面上。", "一只手握住啞鈴，正手握住，將其放在肩膀上。", "將啞鈴向上推離身體，完全伸展手臂。", "在頂部停頓片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換到另一只手臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0354', 'exercise', 1, '{"id": "0354", "target": "triceps", "name_en": "dumbbell one arm kickback", "name_zh": "哑铃单臂臂后屈伸", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0354-bQy2Eni.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴單臂臂后屈伸", "instructions_en": ["Stand with your feet shoulder-width apart and hold a dumbbell in your right hand.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Bring your right elbow up to your side, keeping it bent at a 90-degree angle.", "Extend your right arm straight back, squeezing your triceps at the top of the movement.", "Slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["双脚分开与肩同宽站立，右手握住哑铃。", "稍微弯曲膝盖，髋部向前转动，保持背部挺直。", "将右肘举至身体一侧，保持弯曲 90 度角。", "将右臂向后伸直，在动作的最高点挤压三头肌。", "慢慢地将哑铃放回起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，右手握住啞鈴。", "稍微彎曲膝蓋，髖部向前轉動，保持背部挺直。", "將右肘舉至身體一側，保持彎曲 90 度角。", "將右臂向后伸直，在動作的最高點擠壓三頭肌。", "慢慢地將啞鈴放回起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0355', 'exercise', 1, '{"id": "0355", "target": "delts", "name_en": "dumbbell one arm lateral raise", "name_zh": "哑铃单臂侧平举", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0355-n5cWCsI.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴單臂側平舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing your body.", "Keep your back straight and your core engaged throughout the exercise.", "Raise the dumbbell to the side, keeping your arm straight and your palm facing down.", "Continue lifting until your arm is parallel to the ground.", "Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."], "instructions_zh": ["双脚分开与肩同宽站立，一手握住哑铃，手掌朝向身体。", "在整个练习过程中保持背部挺直，核心肌群参与其中。", "将哑铃举至一侧，保持手臂伸直，手掌朝下。", "继续抬起，直到手臂与地面平行。", "在最高点暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换到另一只手臂。"], "secondary_muscles": ["trapezius", "triceps"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，一手握住啞鈴，手掌朝向身體。", "在整個練習過程中保持背部挺直，核心肌群參與其中。", "將啞鈴舉至一側，保持手臂伸直，手掌朝下。", "繼續抬起，直到手臂與地面平行。", "在最高點暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換到另一只手臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0356', 'exercise', 1, '{"id": "0356", "target": "delts", "name_en": "dumbbell one arm lateral raise with support", "name_zh": "哑铃单臂侧平举配合支撑", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0356-Yg7MJAT.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴單臂側平舉配合支撐", "instructions_en": ["Stand with your feet shoulder-width apart and hold a dumbbell in one hand, with your palm facing your body.", "Place your other hand on a stable surface, such as a bench or wall, for support.", "Keep your back straight and engage your core.", "Raise the dumbbell out to the side, keeping your arm straight and your palm facing down.", "Continue lifting until your arm is parallel to the ground.", "Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["双脚分开与肩同宽站立，一手握住哑铃，手掌朝向身体。", "将另一只手放在稳定的表面（例如长凳或墙壁）上以获得支撑。", "保持背部挺直并启动核心肌群。", "将哑铃向一侧举起，保持手臂伸直，手掌朝下。", "继续抬起，直到手臂与地面平行。", "在顶部停顿片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["trapezius", "rotator cuff"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，一手握住啞鈴，手掌朝向身體。", "將另一只手放在穩定的表面（例如長凳或墻壁）上以獲得支撐。", "保持背部挺直并啟動核心肌群。", "將啞鈴向一側舉起，保持手臂伸直，手掌朝下。", "繼續抬起，直到手臂與地面平行。", "在頂部停頓片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1290', 'exercise', 1, '{"id": "1290", "target": "pectorals", "name_en": "dumbbell one arm press on exercise ball", "name_zh": "健身球哑铃单臂推举", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1290-QZFv5ui.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球啞鈴單臂推舉", "instructions_en": ["Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.", "Hold a dumbbell in one hand and position it at shoulder height, with your elbow bent and palm facing forward.", "Slowly press the dumbbell upward until your arm is fully extended, while keeping your core engaged and maintaining balance on the exercise ball.", "Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."], "instructions_zh": ["坐在健身球上，双脚平放在地上，膝盖弯曲成 90 度角。", "一只手握住哑铃，将其置于与肩同高的位置，肘部弯曲，手掌朝前。", "慢慢向上推哑铃，直到手臂完全伸展，同时保持核心收紧并在健身球上保持平衡。", "在最高点暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换到另一只手臂。"], "secondary_muscles": ["shoulders", "triceps", "core"], "instructions_zh_hant": ["坐在健身球上，雙腳平放在地上，膝蓋彎曲成 90 度角。", "一只手握住啞鈴，將其置于與肩同高的位置，肘部彎曲，手掌朝前。", "慢慢向上推啞鈴，直到手臂完全伸展，同時保持核心收緊并在健身球上保持平衡。", "在最高點暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換到另一只手臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1665', 'exercise', 1, '{"id": "1665", "target": "biceps", "name_en": "dumbbell one arm prone curl", "name_zh": "哑铃单臂俯卧弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1665-JWjujiY.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴單臂俯臥彎舉", "instructions_en": ["Lie face down on a flat bench with a dumbbell in one hand, palm facing down.", "Extend your arm fully, letting it hang straight down towards the floor.", "Keeping your upper arm stationary, curl the dumbbell up towards your shoulder by contracting your biceps.", "Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["脸朝下躺在平坦的长凳上，一只手握住哑铃，掌心朝下。", "完全伸展你的手臂，让它垂直垂向地板。", "保持上臂静止，通过收缩二头肌将哑铃向上卷曲至肩膀。", "在顶部停顿片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["臉朝下躺在平坦的長凳上，一只手握住啞鈴，掌心朝下。", "完全伸展你的手臂，讓它垂直垂向地板。", "保持上臂靜止，通過收縮二頭肌將啞鈴向上卷曲至肩膀。", "在頂部停頓片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1666', 'exercise', 1, '{"id": "1666", "target": "biceps", "name_en": "dumbbell one arm prone hammer curl", "name_zh": "哑铃单臂俯卧锤式弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1666-LIGZSTA.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴單臂俯臥錘式彎舉", "instructions_en": ["Lie face down on a flat bench with a dumbbell in one hand, palm facing your body and arm fully extended.", "Keep your upper arm stationary and curl the dumbbell towards your shoulder, contracting your biceps.", "Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["面朝下躺在平坦的长凳上，一只手拿着哑铃，手掌面向身体，手臂完全伸展。", "保持上臂静止，将哑铃向肩膀弯曲，收缩二头肌。", "在最高点暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["面朝下躺在平坦的長凳上，一只手拿著啞鈴，手掌面向身體，手臂完全伸展。", "保持上臂靜止，將啞鈴向肩膀彎曲，收縮二頭肌。", "在最高點暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1291', 'exercise', 1, '{"id": "1291", "target": "pectorals", "name_en": "dumbbell one arm pullover on exercise ball", "name_zh": "健身球哑铃单臂仰卧上拉", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1291-bQHPBU3.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球啞鈴單臂仰臥上拉", "instructions_en": ["Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.", "Hold a dumbbell with one hand and extend your arm straight up above your chest.", "Slowly lower the dumbbell behind your head while keeping your arm straight.", "Pause for a moment, then raise the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["坐在健身球上，双脚平放在地上，膝盖弯曲成 90 度角。", "用一只手握住哑铃，将手臂伸直至胸部上方。", "慢慢地将哑铃放到脑后，同时保持手臂伸直。", "暂停片刻，然后将哑铃举回到起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["triceps", "latissimus dorsi", "rhomboids"], "instructions_zh_hant": ["坐在健身球上，雙腳平放在地上，膝蓋彎曲成 90 度角。", "用一只手握住啞鈴，將手臂伸直至胸部上方。", "慢慢地將啞鈴放到腦后，同時保持手臂伸直。", "暫停片刻，然后將啞鈴舉回到起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0358', 'exercise', 1, '{"id": "0358", "target": "forearms", "name_en": "dumbbell one arm reverse wrist curl", "name_zh": "哑铃单臂反握腕弯举", "body_part": "lower arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0358-BwSNDGt.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴單臂反握腕彎舉", "instructions_en": ["Sit on a bench or chair with your feet flat on the ground.", "Hold a dumbbell in one hand with an overhand grip, palm facing down.", "Rest your forearm on your thigh, with your wrist hanging off the edge.", "Slowly lower the dumbbell towards the ground by flexing your wrist.", "Pause for a moment at the bottom, then slowly curl your wrist back up towards your body.", "Repeat for the desired number of repetitions, then switch to the other arm."], "instructions_zh": ["坐在长凳或椅子上，双脚平放在地面上。", "一只手握住哑铃，正手握住，手掌朝下。", "将前臂放在大腿上，手腕悬在边缘。", "弯曲手腕，慢慢地将哑铃降低到地面。", "在底部停顿片刻，然后慢慢地将手腕向上卷向身体。", "重复所需的重复次数，然后换到另一只手臂。"], "secondary_muscles": ["wrist extensors"], "instructions_zh_hant": ["坐在長凳或椅子上，雙腳平放在地面上。", "一只手握住啞鈴，正手握住，手掌朝下。", "將前臂放在大腿上，手腕懸在邊緣。", "彎曲手腕，慢慢地將啞鈴降低到地面。", "在底部停頓片刻，然后慢慢地將手腕向上卷向身體。", "重復所需的重復次數，然后換到另一只手臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0359', 'exercise', 1, '{"id": "0359", "target": "delts", "name_en": "dumbbell one arm reverse fly (with support)", "name_zh": "哑铃单臂反向飞鸟（配合支撑）", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0359-e25F58f.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴單臂反向飛鳥（配合支撐）", "instructions_en": ["Sit on a bench with your feet flat on the ground and your back straight.", "Hold a dumbbell in one hand with your palm facing inwards.", "Lean forward and place your free hand on the bench for support.", "Keep your arm slightly bent and raise it out to the side until it is parallel to the ground.", "Pause for a moment at the top, then slowly lower your arm back down to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["坐在长凳上，双脚平放在地上，背部挺直。", "一只手握住哑铃，手掌朝内。", "身体前倾，将空着的手放在长凳上以获得支撑。", "保持手臂稍微弯曲并将其向侧面抬起，直到与地面平行。", "在顶部暂停片刻，然后慢慢将手臂放回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["trapezius", "rhomboids"], "instructions_zh_hant": ["坐在長凳上，雙腳平放在地上，背部挺直。", "一只手握住啞鈴，手掌朝內。", "身體前傾，將空著的手放在長凳上以獲得支撐。", "保持手臂稍微彎曲并將其向側面抬起，直到與地面平行。", "在頂部暫停片刻，然后慢慢將手臂放回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1622', 'exercise', 1, '{"id": "1622", "target": "pectorals", "name_en": "dumbbell one arm reverse grip press", "name_zh": "哑铃单臂反握推举", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1622-Ze7MoIb.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴單臂反握推舉", "instructions_en": ["Sit on a flat bench with a dumbbell in one hand, palm facing towards your body.", "Place your feet flat on the ground and keep your back straight.", "Raise the dumbbell to shoulder height, keeping your elbow close to your body.", "Press the dumbbell upwards until your arm is fully extended.", "Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."], "instructions_zh": ["坐在平坦的长凳上，一只手拿着哑铃，手掌朝向身体。", "将双脚平放在地面上，并保持背部挺直。", "将哑铃举至肩膀高度，保持肘部靠近身体。", "向上推哑铃，直到手臂完全伸展。", "在最高点暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换到另一只手臂。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["坐在平坦的長凳上，一只手拿著啞鈴，手掌朝向身體。", "將雙腳平放在地面上，并保持背部挺直。", "將啞鈴舉至肩膀高度，保持肘部靠近身體。", "向上推啞鈴，直到手臂完全伸展。", "在最高點暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換到另一只手臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0360', 'exercise', 1, '{"id": "0360", "target": "delts", "name_en": "dumbbell one arm shoulder press v. 2", "name_zh": "哑铃单臂肩上推举变式2", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0360-1TkiAFK.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴單臂肩上推舉變式2", "instructions_en": ["Stand with your feet shoulder-width apart and hold a dumbbell in one hand at shoulder level, palm facing forward.", "Engage your core and press the dumbbell straight up overhead, fully extending your arm.", "Pause for a moment at the top, then slowly lower the dumbbell back to shoulder level.", "Repeat for the desired number of repetitions, then switch to the other arm."], "instructions_zh": ["双脚分开与肩同宽站立，一只手握住哑铃，与肩同高，手掌朝前。", "启动核心肌群，将哑铃垂直推过头顶，充分伸展手臂。", "在顶部停顿片刻，然后慢慢将哑铃放回肩部水平。", "重复所需的重复次数，然后换到另一只手臂。"], "secondary_muscles": ["triceps", "upper back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，一只手握住啞鈴，與肩同高，手掌朝前。", "啟動核心肌群，將啞鈴垂直推過頭頂，充分伸展手臂。", "在頂部停頓片刻，然后慢慢將啞鈴放回肩部水平。", "重復所需的重復次數，然后換到另一只手臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1414', 'exercise', 1, '{"id": "1414", "target": "biceps", "name_en": "dumbbell one arm reverse preacher curl", "name_zh": "哑铃单臂反向牧师凳弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1414-bWxq4op.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴單臂反向牧師凳彎舉", "instructions_en": ["Sit on a preacher bench with your chest against the pad and your arm extended over the edge of the bench, holding a dumbbell with an underhand grip.", "Lower the dumbbell slowly until your arm is fully extended.", "Curl the dumbbell back up towards your shoulder, keeping your upper arm stationary.", "Squeeze your biceps at the top of the movement, then slowly lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["坐在牧师凳上，胸部靠在垫子上，手臂伸出长凳边缘，反握哑铃。", "慢慢降低哑铃，直到手臂完全伸展。", "将哑铃向后弯向肩膀，保持上臂静止。", "在动作的最高点挤压二头肌，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在牧師凳上，胸部靠在墊子上，手臂伸出長凳邊緣，反握啞鈴。", "慢慢降低啞鈴，直到手臂完全伸展。", "將啞鈴向后彎向肩膀，保持上臂靜止。", "在動作的最高點擠壓二頭肌，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1667', 'exercise', 1, '{"id": "1667", "target": "biceps", "name_en": "dumbbell one arm reverse spider curl", "name_zh": "哑铃单臂反向蜘蛛式弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1667-VdLZ3nB.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴單臂反向蜘蛛式彎舉", "instructions_en": ["Stand up straight with a dumbbell in one hand, palm facing down and arm fully extended.", "Keeping your upper arm stationary, curl the dumbbell towards your shoulder by flexing your elbow.", "Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["站直，一只手握住哑铃，手掌朝下，手臂完全伸展。", "保持上臂静止，弯曲肘部，将哑铃向肩膀方向卷曲。", "在最高点暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，一只手握住啞鈴，手掌朝下，手臂完全伸展。", "保持上臂靜止，彎曲肘部，將啞鈴向肩膀方向卷曲。", "在最高點暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1668', 'exercise', 1, '{"id": "1668", "target": "biceps", "name_en": "dumbbell one arm seated bicep curl on exercise ball", "name_zh": "健身球哑铃单臂坐姿二头弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1668-s999Hdo.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球啞鈴單臂坐姿二頭彎舉", "instructions_en": ["Sit on an exercise ball with your feet flat on the ground and your back straight.", "Hold a dumbbell in one hand with your palm facing up and your arm fully extended.", "Keeping your upper arm stationary, curl the dumbbell towards your shoulder by contracting your biceps.", "Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["坐在健身球上，双脚平放在地上，背部挺直。", "一只手握住哑铃，手掌朝上，手臂完全伸展。", "保持上臂静止，通过收缩二头肌将哑铃向肩膀弯曲。", "在最高点暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在健身球上，雙腳平放在地上，背部挺直。", "一只手握住啞鈴，手掌朝上，手臂完全伸展。", "保持上臂靜止，通過收縮二頭肌將啞鈴向肩膀彎曲。", "在最高點暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1669', 'exercise', 1, '{"id": "1669", "target": "biceps", "name_en": "dumbbell one arm seated hammer curl", "name_zh": "哑铃单臂坐姿锤式弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1669-jK2hZ6n.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴單臂坐姿錘式彎舉", "instructions_en": ["Sit on a bench with your back straight and feet flat on the ground.", "Hold a dumbbell in one hand with a neutral grip (palms facing each other).", "Rest your elbow on the inside of your thigh, just above the knee.", "Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.", "Pause for a moment at the top, squeezing your biceps.", "Inhale and slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["坐在长凳上，背部挺直，双脚平放在地上。", "一只手握住哑铃，保持中立握姿（手掌相对）。", "将肘部放在大腿内侧、膝盖上方。", "保持上臂静止，呼气并将哑铃向上弯向肩膀。", "在顶部暂停片刻，挤压你的二头肌。", "吸气，慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在長凳上，背部挺直，雙腳平放在地上。", "一只手握住啞鈴，保持中立握姿（手掌相對）。", "將肘部放在大腿內側、膝蓋上方。", "保持上臂靜止，呼氣并將啞鈴向上彎向肩膀。", "在頂部暫停片刻，擠壓你的二頭肌。", "吸氣，慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1415', 'exercise', 1, '{"id": "1415", "target": "forearms", "name_en": "dumbbell one arm seated neutral wrist curl", "name_zh": "哑铃单臂坐姿中立握腕弯举", "body_part": "lower arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1415-YtaCTYl.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴單臂坐姿中立握腕彎舉", "instructions_en": ["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing up.", "Rest your forearm on your thigh, allowing your wrist to hang off the edge.", "Keeping your forearm stationary, curl your wrist upward as far as possible.", "Pause for a moment at the top, then slowly lower your wrist back down to the starting position.", "Repeat for the desired number of repetitions, then switch to the other hand."], "instructions_zh": ["坐在长凳上，双脚平放在地上，一手握住哑铃，掌心朝上。", "将前臂放在大腿上，让手腕悬在边缘。", "保持前臂静止，尽可能向上弯曲手腕。", "在顶部暂停片刻，然后慢慢将手腕放回起始位置。", "重复所需的重复次数，然后换另一只手。"], "secondary_muscles": ["biceps", "brachialis"], "instructions_zh_hant": ["坐在長凳上，雙腳平放在地上，一手握住啞鈴，掌心朝上。", "將前臂放在大腿上，讓手腕懸在邊緣。", "保持前臂靜止，盡可能向上彎曲手腕。", "在頂部暫停片刻，然后慢慢將手腕放回起始位置。", "重復所需的重復次數，然后換另一只手。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0361', 'exercise', 1, '{"id": "0361", "target": "delts", "name_en": "dumbbell one arm shoulder press", "name_zh": "哑铃单臂肩上推举", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0361-84RyJf8.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴單臂肩上推舉", "instructions_en": ["Stand with your feet shoulder-width apart and hold a dumbbell in one hand at shoulder level, palm facing forward.", "Press the dumbbell upward until your arm is fully extended overhead.", "Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."], "instructions_zh": ["双脚分开与肩同宽站立，一只手握住哑铃，与肩同高，手掌朝前。", "向上推哑铃，直到手臂完全伸过头顶。", "在最高点暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换到另一只手臂。"], "secondary_muscles": ["triceps", "upper back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，一只手握住啞鈴，與肩同高，手掌朝前。", "向上推啞鈴，直到手臂完全伸過頭頂。", "在最高點暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換到另一只手臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3888', 'exercise', 1, '{"id": "3888", "target": "glutes", "name_en": "dumbbell one arm snatch", "name_zh": "哑铃单臂抓举", "body_part": "upper legs", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/3888-6pTkI99.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴單臂抓舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with an overhand grip.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.", "Lower the dumbbell towards the ground, keeping it close to your body.", "Explosively extend your hips, knees, and ankles, driving the dumbbell upwards in a straight line.", "As the dumbbell reaches shoulder height, quickly rotate your hand and punch it overhead, fully extending your arm.", "Catch the dumbbell overhead with a slight bend in your knees and hips.", "Lower the dumbbell back down to the starting position in a controlled manner.", "Repeat for the desired number of repetitions, then switch to the other arm."], "instructions_zh": ["双脚分开与肩同宽站立，一只手握住哑铃，正握。", "稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。", "将哑铃向地面放低，使其靠近身体。", "爆发性伸展臀部、膝盖和脚踝，将哑铃沿直线向上推。", "当哑铃到达肩膀高度时，快速旋转你的手并将其击打过头顶，充分伸展你的手臂。", "将哑铃举过头顶，膝盖和臀部稍微弯曲。", "以受控的方式将哑铃放回起始位置。", "重复所需的重复次数，然后换到另一只手臂。"], "secondary_muscles": ["hamstrings", "quadriceps", "core"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，一只手握住啞鈴，正握。", "稍微彎曲膝蓋，臀部向前轉動，保持背部挺直，挺胸。", "將啞鈴向地面放低，使其靠近身體。", "爆發性伸展臀部、膝蓋和腳踝，將啞鈴沿直線向上推。", "當啞鈴到達肩膀高度時，快速旋轉你的手并將其擊打過頭頂，充分伸展你的手臂。", "將啞鈴舉過頭頂，膝蓋和臀部稍微彎曲。", "以受控的方式將啞鈴放回起始位置。", "重復所需的重復次數，然后換到另一只手臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1670', 'exercise', 1, '{"id": "1670", "target": "biceps", "name_en": "dumbbell one arm standing curl", "name_zh": "哑铃单臂站姿弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1670-ffQsyBj.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴單臂站姿彎舉", "instructions_en": ["Stand up straight with a dumbbell in one hand, palm facing forward and arm fully extended.", "Keeping your upper arm stationary, exhale and curl the weight upward while contracting your biceps.", "Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["站直，一手握哑铃，手掌朝前，手臂完全伸展。", "保持上臂静止，呼气并向上弯曲重量，同时收缩二头肌。", "继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气，慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，一手握啞鈴，手掌朝前，手臂完全伸展。", "保持上臂靜止，呼氣并向上彎曲重量，同時收縮二頭肌。", "繼續舉起啞鈴，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣，慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1671', 'exercise', 1, '{"id": "1671", "target": "biceps", "name_en": "dumbbell one arm standing hammer curl", "name_zh": "哑铃单臂站姿锤式弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1671-2sQGZ5b.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴單臂站姿錘式彎舉", "instructions_en": ["Stand up straight with a dumbbell in each hand, palms facing your torso.", "Keep your elbows close to your torso and your upper arms stationary.", "Exhale and curl the weights while contracting your biceps.", "Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站直，双手各持一个哑铃，手掌朝向躯干。", "保持肘部靠近躯干，上臂保持静止。", "呼气并弯举哑铃，同时收缩二头肌。", "继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙手各持一個啞鈴，手掌朝向軀幹。", "保持肘部靠近軀幹，上臂保持靜止。", "呼氣并彎舉啞鈴，同時收縮二頭肌。", "繼續舉重，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0362', 'exercise', 1, '{"id": "0362", "target": "triceps", "name_en": "dumbbell one arm triceps extension (on bench)", "name_zh": "哑铃单臂臂屈伸（凳上）", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0362-nAuHPcD.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴單臂臂屈伸（凳上）", "instructions_en": ["Sit on a bench with your back straight and feet flat on the ground.", "Hold a dumbbell in one hand and place your other hand on the bench for support.", "Raise the dumbbell overhead, keeping your upper arm close to your head and your elbow pointing forward.", "Lower the dumbbell behind your head by bending your elbow, keeping your upper arm stationary.", "Extend your arm back up to the starting position, fully straightening your elbow.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["坐在长凳上，背部挺直，双脚平放在地上。", "一手握住哑铃，另一只手放在长凳上以获得支撑。", "将哑铃举过头顶，保持上臂靠近头部，肘部向前。", "弯曲肘部，将哑铃降低到头后，保持上臂静止。", "将手臂向后伸展至起始位置，完全伸直肘部。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["坐在長凳上，背部挺直，雙腳平放在地上。", "一手握住啞鈴，另一只手放在長凳上以獲得支撐。", "將啞鈴舉過頭頂，保持上臂靠近頭部，肘部向前。", "彎曲肘部，將啞鈴降低到頭后，保持上臂靜止。", "將手臂向后伸展至起始位置，完全伸直肘部。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0363', 'exercise', 1, '{"id": "0363", "target": "delts", "name_en": "dumbbell one arm upright row", "name_zh": "哑铃单臂直立划船", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0363-6cKQC5E.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴單臂直立劃船", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with an overhand grip.", "Let the dumbbell hang at arm''s length in front of your thighs, with your palm facing your body.", "Keeping your back straight and your core engaged, exhale and lift the dumbbell straight up towards your chin, leading with your elbow.", "Pause for a moment at the top, then inhale and slowly lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."], "instructions_zh": ["双脚分开与肩同宽站立，一只手握住哑铃，正握。", "让哑铃悬挂在大腿前面，与手臂保持一定距离，手掌朝向身体。", "保持背部挺直，核心收紧，呼气，将哑铃笔直向上举至下巴，用肘部引导。", "在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换到另一只手臂。"], "secondary_muscles": ["traps", "biceps"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，一只手握住啞鈴，正握。", "讓啞鈴懸掛在大腿前面，與手臂保持一定距離，手掌朝向身體。", "保持背部挺直，核心收緊，呼氣，將啞鈴筆直向上舉至下巴，用肘部引導。", "在頂部停頓片刻，然后吸氣，慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換到另一只手臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1672', 'exercise', 1, '{"id": "1672", "target": "biceps", "name_en": "dumbbell one arm zottman preacher curl", "name_zh": "哑铃单臂佐特曼牧师凳弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1672-sxY5Biu.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴單臂佐特曼牧師凳彎舉", "instructions_en": ["Sit on a preacher curl bench and hold a dumbbell in one hand with an underhand grip.", "Rest your upper arm on the preacher bench pad, allowing your arm to fully extend.", "Curl the dumbbell up towards your shoulder, keeping your upper arm stationary.", "At the top of the curl, rotate your wrist so that your palm faces up.", "Slowly lower the dumbbell back down to the starting position, rotating your wrist back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["坐在牧师弯举凳上，单手握哑铃，反握。", "将上臂放在牧师凳垫上，让手臂完全伸展。", "将哑铃向上弯向肩膀，保持上臂静止。", "在卷曲的顶部，旋转手腕，使手掌朝上。", "慢慢地将哑铃放回起始位置，同时将手腕旋转回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在牧師彎舉凳上，單手握啞鈴，反握。", "將上臂放在牧師凳墊上，讓手臂完全伸展。", "將啞鈴向上彎向肩膀，保持上臂靜止。", "在卷曲的頂部，旋轉手腕，使手掌朝上。", "慢慢地將啞鈴放回起始位置，同時將手腕旋轉回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1292', 'exercise', 1, '{"id": "1292", "target": "pectorals", "name_en": "dumbbell one leg fly on exercise ball", "name_zh": "健身球哑铃单腿飞鸟", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1292-pH2x2jj.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球啞鈴單腿飛鳥", "instructions_en": ["Sit on an exercise ball with a dumbbell in each hand, palms facing each other.", "Place one foot on the ground and extend the other leg straight out in front of you.", "Lean forward slightly and bring your arms out to the sides, keeping a slight bend in your elbows.", "Slowly lower the dumbbells down and out to the sides, feeling a stretch in your chest.", "Pause for a moment at the bottom, then squeeze your chest muscles to bring the dumbbells back up to the starting position.", "Repeat for the desired number of repetitions, then switch legs and repeat."], "instructions_zh": ["坐在健身球上，双手各握一个哑铃，手掌相对。", "将一只脚放在地面上，并将另一条腿伸直到您面前。", "稍微向前倾，将手臂向两侧伸出，保持肘部轻微弯曲。", "慢慢地将哑铃向两侧放低，感觉胸部有拉伸感。", "在底部暂停片刻，然后挤压胸部肌肉，使哑铃回到起始位置。", "重复所需的重复次数，然后换腿并重复。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["坐在健身球上，雙手各握一個啞鈴，手掌相對。", "將一只腳放在地面上，并將另一條腿伸直到您面前。", "稍微向前傾，將手臂向兩側伸出，保持肘部輕微彎曲。", "慢慢地將啞鈴向兩側放低，感覺胸部有拉伸感。", "在底部暫停片刻，然后擠壓胸部肌肉，使啞鈴回到起始位置。", "重復所需的重復次數，然后換腿并重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0365', 'exercise', 1, '{"id": "0365", "target": "biceps", "name_en": "dumbbell over bench neutral wrist curl", "name_zh": "哑铃凳上支撑中立握腕弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0365-BKa8dmT.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴凳上支撐中立握腕彎舉", "instructions_en": ["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.", "Rest your forearms on the bench, allowing your wrists to hang off the edge.", "Keeping your upper arms stationary, exhale and curl the dumbbells up towards your shoulders.", "Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双脚平放在地上，双手各握一个哑铃，掌心朝上。", "将前臂放在长凳上，让手腕悬在长凳边缘。", "保持上臂静止，呼气并将哑铃向上弯向肩膀。", "在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在長凳上，雙腳平放在地上，雙手各握一個啞鈴，掌心朝上。", "將前臂放在長凳上，讓手腕懸在長凳邊緣。", "保持上臂靜止，呼氣并將啞鈴向上彎向肩膀。", "在頂部停頓片刻，然后吸氣，慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0366', 'exercise', 1, '{"id": "0366", "target": "biceps", "name_en": "dumbbell over bench one arm neutral wrist curl", "name_zh": "哑铃凳上支撑单臂中立握腕弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0366-IvV6C9M.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴凳上支撐單臂中立握腕彎舉", "instructions_en": ["Sit on a bench with a dumbbell in one hand and your arm extended over the bench, palm facing up.", "Keep your upper arm stationary and curl the dumbbell towards your shoulder, keeping your wrist in a neutral position.", "Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["坐在长凳上，一只手拿着哑铃，手臂伸过长凳，手掌朝上。", "保持上臂静止，将哑铃向肩膀弯曲，使手腕保持在中立位置。", "在最高点暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在長凳上，一只手拿著啞鈴，手臂伸過長凳，手掌朝上。", "保持上臂靜止，將啞鈴向肩膀彎曲，使手腕保持在中立位置。", "在最高點暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1441', 'exercise', 1, '{"id": "1441", "target": "forearms", "name_en": "dumbbell over bench one arm reverse wrist curl", "name_zh": "哑铃凳上支撑单臂反握腕弯举", "body_part": "lower arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1441-4Jc36XM.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴凳上支撐單臂反握腕彎舉", "instructions_en": ["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing down.", "Rest your forearm on the bench with your wrist hanging off the edge.", "Slowly curl your wrist upwards, bringing the dumbbell towards your forearm.", "Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."], "instructions_zh": ["坐在长凳上，双脚平放在地上，一手握住哑铃，掌心朝下。", "将前臂放在长凳上，手腕悬在长凳边缘。", "慢慢向上弯曲手腕，将哑铃拉向前臂。", "在顶部停顿片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换到另一只手臂。"], "secondary_muscles": ["biceps", "brachialis"], "instructions_zh_hant": ["坐在長凳上，雙腳平放在地上，一手握住啞鈴，掌心朝下。", "將前臂放在長凳上，手腕懸在長凳邊緣。", "慢慢向上彎曲手腕，將啞鈴拉向前臂。", "在頂部停頓片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換到另一只手臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0367', 'exercise', 1, '{"id": "0367", "target": "forearms", "name_en": "dumbbell over bench one arm wrist curl", "name_zh": "哑铃凳上支撑单臂腕弯举", "body_part": "lower arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0367-KI1DjNN.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴凳上支撐單臂腕彎舉", "instructions_en": ["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing down.", "Rest your forearm on the bench with your wrist hanging off the edge.", "Slowly curl your wrist upwards, bringing the dumbbell towards your forearm.", "Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."], "instructions_zh": ["坐在长凳上，双脚平放在地上，一手握住哑铃，掌心朝下。", "将前臂放在长凳上，手腕悬在长凳边缘。", "慢慢向上弯曲手腕，将哑铃拉向前臂。", "在顶部停顿片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换到另一只手臂。"], "secondary_muscles": ["biceps", "shoulders"], "instructions_zh_hant": ["坐在長凳上，雙腳平放在地上，一手握住啞鈴，掌心朝下。", "將前臂放在長凳上，手腕懸在長凳邊緣。", "慢慢向上彎曲手腕，將啞鈴拉向前臂。", "在頂部停頓片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換到另一只手臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0368', 'exercise', 1, '{"id": "0368", "target": "forearms", "name_en": "dumbbell over bench revers wrist curl", "name_zh": "哑铃凳上支撑反向腕弯举", "body_part": "lower arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0368-3tAXPQ6.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴凳上支撐反向腕彎舉", "instructions_en": ["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing down.", "Rest your forearms on the bench, allowing your wrists to hang off the edge.", "Slowly curl your wrists upward, bringing the dumbbells towards your body.", "Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双脚平放在地上，双手各握一个哑铃，掌心朝下。", "将前臂放在长凳上，让手腕悬在长凳边缘。", "慢慢向上弯曲手腕，将哑铃拉向身体。", "在顶部停顿片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "brachialis"], "instructions_zh_hant": ["坐在長凳上，雙腳平放在地上，雙手各握一個啞鈴，掌心朝下。", "將前臂放在長凳上，讓手腕懸在長凳邊緣。", "慢慢向上彎曲手腕，將啞鈴拉向身體。", "在頂部停頓片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0369', 'exercise', 1, '{"id": "0369", "target": "forearms", "name_en": "dumbbell over bench wrist curl", "name_zh": "哑铃凳上支撑腕弯举", "body_part": "lower arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0369-D1xYJAU.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴凳上支撐腕彎舉", "instructions_en": ["Sit on a bench with your forearms resting on the bench and your palms facing up, holding a dumbbell in each hand.", "Allow your wrists to hang over the edge of the bench.", "Slowly curl your wrists upward, squeezing your forearms at the top of the movement.", "Pause for a moment, then slowly lower your wrists back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，前臂放在长凳上，手掌朝上，每只手各握一个哑铃。", "让手腕悬在长凳边缘。", "慢慢向上弯曲手腕，在动作的最高点挤压前臂。", "暂停片刻，然后慢慢将手腕放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "brachialis"], "instructions_zh_hant": ["坐在長凳上，前臂放在長凳上，手掌朝上，每只手各握一個啞鈴。", "讓手腕懸在長凳邊緣。", "慢慢向上彎曲手腕，在動作的最高點擠壓前臂。", "暫停片刻，然后慢慢將手腕放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1329', 'exercise', 1, '{"id": "1329", "target": "upper back", "name_en": "dumbbell palm rotational bent over row", "name_zh": "哑铃掌心旋转俯身划船", "body_part": "back", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1329-wt6rwjk.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴掌心旋轉俯身劃船", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.", "Bend forward at the hips, keeping your back straight and your knees slightly bent.", "Let your arms hang straight down, palms facing your body.", "Engage your core and pull the dumbbells up towards your chest, keeping your elbows close to your body.", "As you pull the dumbbells up, rotate your palms so they face away from your body.", "Squeeze your shoulder blades together at the top of the movement.", "Slowly lower the dumbbells back down to the starting position, rotating your palms back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃，正握。", "臀部向前弯曲，保持背部挺直，膝盖稍微弯曲。", "让你的手臂笔直下垂，手掌朝向身体。", "收紧核心肌群，将哑铃拉向胸部，保持肘部靠近身体。", "当你向上拉哑铃时，旋转手掌，使其背向身体。", "在动作的最高点将肩胛骨挤压在一起。", "慢慢地将哑铃放回起始位置，将手掌旋转回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴，正握。", "臀部向前彎曲，保持背部挺直，膝蓋稍微彎曲。", "讓你的手臂筆直下垂，手掌朝向身體。", "收緊核心肌群，將啞鈴拉向胸部，保持肘部靠近身體。", "當你向上拉啞鈴時，旋轉手掌，使其背向身體。", "在動作的最高點將肩胛骨擠壓在一起。", "慢慢地將啞鈴放回起始位置，將手掌旋轉回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1673', 'exercise', 1, '{"id": "1673", "target": "biceps", "name_en": "dumbbell preacher curl over exercise ball", "name_zh": "哑铃牧师凳弯举越过健身球", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1673-hwygydB.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴牧師凳彎舉越過健身球", "instructions_en": ["Sit on an exercise ball with your feet flat on the ground and your back straight.", "Hold a dumbbell in one hand with an underhand grip, resting your elbow on the exercise ball.", "Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.", "Pause for a moment at the top, then inhale and slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["坐在健身球上，双脚平放在地上，背部挺直。", "一只手握住哑铃，反握，将肘部放在健身球上。", "保持上臂静止，呼气并将哑铃向上弯向肩膀。", "在最高点停顿片刻，然后吸气，慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在健身球上，雙腳平放在地上，背部挺直。", "一只手握住啞鈴，反握，將肘部放在健身球上。", "保持上臂靜止，呼氣并將啞鈴向上彎向肩膀。", "在最高點停頓片刻，然后吸氣，慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1623', 'exercise', 1, '{"id": "1623", "target": "triceps", "name_en": "dumbbell palms in incline bench press", "name_zh": "哑铃掌心向内上斜卧推", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1623-8eqjhOl.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴掌心向內上斜臥推", "instructions_en": ["Set up an incline bench at a 45-degree angle.", "Sit on the bench with your back against the backrest and feet flat on the ground.", "Hold a dumbbell in each hand with an overhand grip, palms facing inwards.", "Extend your arms straight up above your chest, keeping a slight bend in your elbows.", "Lower the dumbbells slowly towards your shoulders, keeping your elbows close to your body.", "Pause for a moment at the bottom, then press the dumbbells back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["设置一个 45 度角的上斜凳。", "坐在长凳上，背部靠在靠背上，双脚平放在地上。", "双手各握一个哑铃，正手握握，手掌朝内。", "将手臂伸直至胸部上方，保持肘部轻微弯曲。", "将哑铃慢慢向肩膀方向降低，保持肘部靠近身体。", "在底部暂停片刻，然后将哑铃推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["設置一個 45 度角的上斜凳。", "坐在長凳上，背部靠在靠背上，雙腳平放在地上。", "雙手各握一個啞鈴，正手握握，手掌朝內。", "將手臂伸直至胸部上方，保持肘部輕微彎曲。", "將啞鈴慢慢向肩膀方向降低，保持肘部靠近身體。", "在底部暫停片刻，然后將啞鈴推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0370', 'exercise', 1, '{"id": "0370", "target": "biceps", "name_en": "dumbbell peacher hammer curl", "name_zh": "哑铃牧师凳锤式弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0370-F1KxjBa.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴牧師凳錘式彎舉", "instructions_en": ["Stand up straight with a dumbbell in each hand, palms facing your torso.", "Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.", "This will be your starting position.", "Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Then, inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the recommended amount of repetitions."], "instructions_zh": ["站直，双手各持一个哑铃，手掌朝向躯干。", "保持肘部靠近躯干，并旋转手掌，直到手掌朝前。", "这将是您的起始位置。", "现在，保持上臂静止，呼气并卷曲哑铃，同时收缩二头肌。", "继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "然后，吸气并慢慢开始将哑铃放回起始位置。", "重复建议的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙手各持一個啞鈴，手掌朝向軀幹。", "保持肘部靠近軀幹，并旋轉手掌，直到手掌朝前。", "這將是您的起始位置。", "現在，保持上臂靜止，呼氣并卷曲啞鈴，同時收縮二頭肌。", "繼續舉重，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "然后，吸氣并慢慢開始將啞鈴放回起始位置。", "重復建議的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0371', 'exercise', 1, '{"id": "0371", "target": "glutes", "name_en": "dumbbell plyo squat", "name_zh": "哑铃爆发式深蹲", "body_part": "upper legs", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0371-S4pwGlc.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴爆發式深蹲", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.", "Lower your body into a squat position by bending your knees and pushing your hips back.", "As you reach the bottom of the squat, explode upward, jumping off the ground.", "While in the air, quickly switch the position of your feet, landing with your opposite foot forward.", "Immediately lower your body back into a squat position and repeat the jump, switching your feet again.", "Continue alternating the position of your feet with each jump for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃放在身体两侧。", "弯曲膝盖并将臀部向后推，将身体降低至蹲姿。", "当你到达深蹲底部时，向上爆发，跳离地面。", "在空中时，快速改变双脚的位置，落地时另一只脚向前。", "立即将身体放回蹲姿，然后重复跳跃，再次换脚。", "每次跳跃时继续交替双脚的位置，达到所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴放在身體兩側。", "彎曲膝蓋并將臀部向后推，將身體降低至蹲姿。", "當你到達深蹲底部時，向上爆發，跳離地面。", "在空中時，快速改變雙腳的位置，落地時另一只腳向前。", "立即將身體放回蹲姿，然后重復跳躍，再次換腳。", "每次跳躍時繼續交替雙腳的位置，達到所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0372', 'exercise', 1, '{"id": "0372", "target": "biceps", "name_en": "dumbbell preacher curl", "name_zh": "哑铃牧师凳弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0372-jivWf8n.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴牧師凳彎舉", "instructions_en": ["Sit on a preacher curl bench with your upper arms resting on the pad and your chest against it.", "Hold a dumbbell in each hand with your palms facing up and your arms fully extended.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在牧师弯举凳上，上臂放在垫子上，胸部靠在垫子上。", "每只手握住一个哑铃，手掌朝上，双臂完全伸展。", "保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。", "继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在牧師彎舉凳上，上臂放在墊子上，胸部靠在墊子上。", "每只手握住一個啞鈴，手掌朝上，雙臂完全伸展。", "保持上臂靜止，呼氣并彎舉啞鈴，同時收縮二頭肌。", "繼續舉起啞鈴，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1293', 'exercise', 1, '{"id": "1293", "target": "pectorals", "name_en": "dumbbell press on exercise ball", "name_zh": "健身球哑铃推举", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1293-O8o7q4d.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球啞鈴推舉", "instructions_en": ["Sit on an exercise ball with your feet flat on the ground and dumbbells in each hand, resting on your thighs.", "Slowly walk your feet forward, rolling the exercise ball until your lower back is supported on the ball and your knees are at a 90-degree angle.", "Raise the dumbbells to shoulder height, palms facing forward.", "Press the dumbbells upward until your arms are fully extended.", "Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在健身球上，双脚平放在地上，双手各握哑铃，放在大腿上。", "慢慢地向前移动双脚，滚动健身球，直到下背部受到球的支撑并且膝盖呈 90 度角。", "将哑铃举至肩高，手掌朝前。", "向上推哑铃，直到手臂完全伸展。", "在最高点暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["坐在健身球上，雙腳平放在地上，雙手各握啞鈴，放在大腿上。", "慢慢地向前移動雙腳，滾動健身球，直到下背部受到球的支撐并且膝蓋呈 90 度角。", "將啞鈴舉至肩高，手掌朝前。", "向上推啞鈴，直到手臂完全伸展。", "在最高點暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0373', 'exercise', 1, '{"id": "0373", "target": "triceps", "name_en": "dumbbell pronate-grip triceps extension", "name_zh": "哑铃正握臂屈伸", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0373-bpJL2Qs.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴正握臂屈伸", "instructions_en": ["Sit on a bench or chair with your back straight and feet flat on the ground.", "Hold a dumbbell with both hands, palms facing down, and extend your arms straight up overhead.", "Keeping your upper arms close to your head and elbows pointing forward, slowly lower the dumbbell behind your head by bending your elbows.", "Pause for a moment, then extend your arms back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳或椅子上，背部挺直，双脚平放在地面上。", "双手握住哑铃，掌心朝下，双臂伸直举过头顶。", "保持上臂靠近头部，肘部向前，弯曲肘部，慢慢将哑铃降低到脑后。", "暂停片刻，然后将手臂伸回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在長凳或椅子上，背部挺直，雙腳平放在地面上。", "雙手握住啞鈴，掌心朝下，雙臂伸直舉過頭頂。", "保持上臂靠近頭部，肘部向前，彎曲肘部，慢慢將啞鈴降低到腦后。", "暫停片刻，然后將手臂伸回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0690', 'exercise', 1, '{"id": "0690", "target": "lats", "name_en": "seated lower back stretch", "name_zh": "坐姿下背拉伸", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0690-QFmz6ch.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "坐姿下背拉伸", "instructions_en": ["Sit on the edge of a chair with your feet flat on the ground.", "Place your hands on your thighs or on the sides of the chair for support.", "Slowly lean forward from your hips, keeping your back straight.", "Feel the stretch in your lower back and hold for 20-30 seconds.", "Slowly return to the starting position and repeat for the desired number of repetitions."], "instructions_zh": ["坐在椅子边缘，双脚平放在地面上。", "将双手放在大腿上或椅子两侧以获得支撑。", "从臀部开始慢慢向前倾斜，保持背部挺直。", "感受下背部的拉伸并保持 20-30 秒。", "慢慢回到起始位置并重复所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings"], "instructions_zh_hant": ["坐在椅子邊緣，雙腳平放在地面上。", "將雙手放在大腿上或椅子兩側以獲得支撐。", "從臀部開始慢慢向前傾斜，保持背部挺直。", "感受下背部的拉伸并保持 20-30 秒。", "慢慢回到起始位置并重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0374', 'exercise', 1, '{"id": "0374", "target": "biceps", "name_en": "dumbbell prone incline curl", "name_zh": "哑铃俯卧上斜弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0374-mwpPcr1.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴俯臥上斜彎舉", "instructions_en": ["Adjust the bench to a 45-degree incline.", "Lie face down on the bench with your chest and stomach resting against it.", "Hold a dumbbell in each hand with your palms facing down and your arms fully extended.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将长凳调整至 45 度倾斜。", "脸朝下躺在长凳上，胸部和腹部靠在长凳上。", "每只手握住一个哑铃，手掌朝下，双臂完全伸展。", "保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。", "继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["將長凳調整至 45 度傾斜。", "臉朝下躺在長凳上，胸部和腹部靠在長凳上。", "每只手握住一個啞鈴，手掌朝下，雙臂完全伸展。", "保持上臂靜止，呼氣并彎舉啞鈴，同時收縮二頭肌。", "繼續舉重，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0420', 'exercise', 1, '{"id": "0420", "target": "triceps", "name_en": "dumbbell standing kickback", "name_zh": "哑铃站姿臂后屈伸", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0420-UmpPAAe.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴站姿臂后屈伸", "instructions_en": ["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Extend your arms straight back, squeezing your triceps at the top of the movement.", "Pause for a moment, then slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，每只手各握一个哑铃。", "稍微弯曲膝盖，髋部向前转动，保持背部挺直。", "将手臂向后伸直，在动作的最高点挤压三头肌。", "暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，每只手各握一個啞鈴。", "稍微彎曲膝蓋，髖部向前轉動，保持背部挺直。", "將手臂向后伸直，在動作的最高點擠壓三頭肌。", "暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1674', 'exercise', 1, '{"id": "1674", "target": "biceps", "name_en": "dumbbell prone incline hammer curl", "name_zh": "哑铃俯卧上斜锤式弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1674-cWemPG8.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴俯臥上斜錘式彎舉", "instructions_en": ["Adjust the bench to a 45-degree incline.", "Lie face down on the bench with a dumbbell in each hand, palms facing each other.", "Allow your arms to hang straight down towards the floor, keeping your elbows slightly bent.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将长凳调整至 45 度倾斜。", "脸朝下躺在长凳上，双手各握一个哑铃，手掌相对。", "让你的手臂垂直垂向地板，保持肘部稍微弯曲。", "保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。", "继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["將長凳調整至 45 度傾斜。", "臉朝下躺在長凳上，雙手各握一個啞鈴，手掌相對。", "讓你的手臂垂直垂向地板，保持肘部稍微彎曲。", "保持上臂靜止，呼氣并彎舉啞鈴，同時收縮二頭肌。", "繼續舉起啞鈴，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0375', 'exercise', 1, '{"id": "0375", "target": "pectorals", "name_en": "dumbbell pullover", "name_zh": "哑铃仰卧上拉", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0375-9XjtHvS.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴仰臥上拉", "instructions_en": ["Lie flat on a bench with your head at one end and your feet on the floor.", "Hold a dumbbell with both hands and extend your arms straight above your chest.", "Keeping a slight bend in your elbows, slowly lower the dumbbell behind your head until you feel a stretch in your chest and shoulders.", "Pause for a moment, then raise the dumbbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，头放在一端，双脚放在地板上。", "双手握住哑铃，将手臂伸直至胸部上方。", "保持肘部轻微弯曲，慢慢地将哑铃放到脑后，直到感觉胸部和肩膀有拉伸感。", "暂停片刻，然后将哑铃举回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["latissimus dorsi", "triceps"], "instructions_zh_hant": ["平躺在長凳上，頭放在一端，雙腳放在地板上。", "雙手握住啞鈴，將手臂伸直至胸部上方。", "保持肘部輕微彎曲，慢慢地將啞鈴放到腦后，直到感覺胸部和肩膀有拉伸感。", "暫停片刻，然后將啞鈴舉回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1294', 'exercise', 1, '{"id": "1294", "target": "pectorals", "name_en": "dumbbell pullover hip extension on exercise ball", "name_zh": "健身球哑铃仰卧上拉髋伸展", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1294-lI7easp.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球啞鈴仰臥上拉髖伸展", "instructions_en": ["Sit on an exercise ball with your feet flat on the ground and the dumbbell resting on your thighs.", "Slowly walk your feet forward, rolling the exercise ball down your back until your head, neck, and upper back are supported on the ball.", "Hold the dumbbell with both hands and extend your arms straight up over your chest, keeping a slight bend in your elbows.", "Lower the dumbbell behind your head, keeping your arms straight and maintaining control.", "Pause for a moment, then raise the dumbbell back to the starting position.", "While keeping your arms extended, lift your hips off the ground, squeezing your glutes and engaging your core.", "Lower your hips back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在健身球上，双脚平放在地面上，哑铃放在大腿上。", "慢慢地向前移动你的脚，将健身球沿着你的背部滚动，直到你的头部、颈部和上背部得到球的支撑。", "双手握住哑铃，将手臂伸直至胸部上方，肘部保持轻微弯曲。", "将哑铃放在脑后，保持手臂伸直并保持控制。", "暂停片刻，然后将哑铃举回到起始位置。", "在保持双臂伸展的同时，将臀部抬离地面，挤压臀肌并启动核心肌群。", "将臀部放低至起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders", "core"], "instructions_zh_hant": ["坐在健身球上，雙腳平放在地面上，啞鈴放在大腿上。", "慢慢地向前移動你的腳，將健身球沿著你的背部滾動，直到你的頭部、頸部和上背部得到球的支撐。", "雙手握住啞鈴，將手臂伸直至胸部上方，肘部保持輕微彎曲。", "將啞鈴放在腦后，保持手臂伸直并保持控制。", "暫停片刻，然后將啞鈴舉回到起始位置。", "在保持雙臂伸展的同時，將臀部抬離地面，擠壓臀肌并啟動核心肌群。", "將臀部放低至起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1295', 'exercise', 1, '{"id": "1295", "target": "pectorals", "name_en": "dumbbell pullover on exercise ball", "name_zh": "健身球哑铃仰卧上拉", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1295-FSD6PGL.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球啞鈴仰臥上拉", "instructions_en": ["Sit on an exercise ball and hold a dumbbell with both hands above your chest, arms extended.", "Slowly lower the dumbbell behind your head while keeping your arms straight.", "Pause for a moment, then raise the dumbbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在健身球上，双手握住哑铃，置于胸前，双臂伸展。", "慢慢地将哑铃放到脑后，同时保持手臂伸直。", "暂停片刻，然后将哑铃举回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "latissimus dorsi"], "instructions_zh_hant": ["坐在健身球上，雙手握住啞鈴，置于胸前，雙臂伸展。", "慢慢地將啞鈴放到腦后，同時保持手臂伸直。", "暫停片刻，然后將啞鈴舉回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1700', 'exercise', 1, '{"id": "1700", "target": "delts", "name_en": "dumbbell push press", "name_zh": "哑铃借力推举", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1700-FS63wTN.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴借力推舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level.", "Bend your knees slightly and dip your body down, then explosively extend your legs and press the dumbbells overhead.", "Lock out your arms at the top of the movement, then lower the dumbbells back to shoulder level.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高。", "稍微弯曲膝盖，身体下沉，然后爆发性伸展双腿，将哑铃压过头顶。", "在动作的最高点锁定手臂，然后将哑铃放回肩部水平。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "core"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴，與肩同高。", "稍微彎曲膝蓋，身體下沉，然后爆發性伸展雙腿，將啞鈴壓過頭頂。", "在動作的最高點鎖定手臂，然后將啞鈴放回肩部水平。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0376', 'exercise', 1, '{"id": "0376", "target": "delts", "name_en": "dumbbell raise", "name_zh": "哑铃抬举", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0376-c9MnDRp.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴抬舉", "instructions_en": ["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.", "Keep your back straight and engage your core.", "Raise your arms out to the sides until they are parallel to the floor, keeping a slight bend in your elbows.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。", "保持背部挺直并启动核心肌群。", "将手臂向两侧抬起，直到与地板平行，保持肘部稍微弯曲。", "在顶部暂停片刻，然后慢慢将手臂放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["traps", "rhomboids"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴，手掌朝向身體。", "保持背部挺直并啟動核心肌群。", "將手臂向兩側抬起，直到與地板平行，保持肘部稍微彎曲。", "在頂部暫停片刻，然后慢慢將手臂放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2292', 'exercise', 1, '{"id": "2292", "target": "delts", "name_en": "dumbbell rear delt raise", "name_zh": "哑铃后束飞鸟", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/2292-mu5Guxt.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴后束飛鳥", "instructions_en": ["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。", "稍微弯曲膝盖，髋部向前转动，保持背部挺直。", "将手臂向两侧举起，肘部保持轻微弯曲，直到与地板平行。", "在顶部暂停片刻，然后慢慢将手臂放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["trapezius", "rhomboids"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴，手掌朝向身體。", "稍微彎曲膝蓋，髖部向前轉動，保持背部挺直。", "將手臂向兩側舉起，肘部保持輕微彎曲，直到與地板平行。", "在頂部暫停片刻，然后慢慢將手臂放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0377', 'exercise', 1, '{"id": "0377", "target": "delts", "name_en": "dumbbell rear delt row_shoulder", "name_zh": "哑铃三角肌后束肩部划船", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0377-EKXOMEh.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴三角肌后束肩部劃船", "instructions_en": ["Stand with your feet shoulder-width apart and knees slightly bent.", "Hold a dumbbell in each hand with your palms facing your body.", "Bend forward at the waist, keeping your back straight and your core engaged.", "Extend your arms straight down towards the floor, with a slight bend in your elbows.", "Raise the dumbbells out to the sides, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站立，双脚分开与肩同宽，膝盖稍微弯曲。", "每只手握住一个哑铃，手掌朝向身体。", "腰部向前弯曲，保持背部挺直，核心肌群参与。", "将手臂伸直向下伸向地板，肘部稍微弯曲。", "将哑铃向两侧举起，将肩胛骨挤压在一起。", "在最高点暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["trapezius", "rhomboids"], "instructions_zh_hant": ["站立，雙腳分開與肩同寬，膝蓋稍微彎曲。", "每只手握住一個啞鈴，手掌朝向身體。", "腰部向前彎曲，保持背部挺直，核心肌群參與。", "將手臂伸直向下伸向地板，肘部稍微彎曲。", "將啞鈴向兩側舉起，將肩胛骨擠壓在一起。", "在最高點暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1624', 'exercise', 1, '{"id": "1624", "target": "pectorals", "name_en": "dumbbell reverse bench press", "name_zh": "哑铃反向卧推", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1624-UIbGx6H.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴反向臥推", "instructions_en": ["Lie flat on a bench with your feet flat on the ground and your knees bent.", "Hold a dumbbell in each hand with an overhand grip, palms facing towards your feet.", "Extend your arms straight up towards the ceiling, keeping a slight bend in your elbows.", "Slowly lower the dumbbells towards your chest, allowing your elbows to flare out to the sides.", "Pause for a moment at the bottom, then push the dumbbells back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，双脚平放在地上，膝盖弯曲。", "双手各握一个哑铃，正手握住，手掌朝向脚部。", "将手臂伸直向上伸向天花板，保持肘部轻微弯曲。", "慢慢地将哑铃降低到胸部，让肘部向两侧张开。", "在底部暂停片刻，然后将哑铃推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["平躺在長凳上，雙腳平放在地上，膝蓋彎曲。", "雙手各握一個啞鈴，正手握住，手掌朝向腳部。", "將手臂伸直向上伸向天花板，保持肘部輕微彎曲。", "慢慢地將啞鈴降低到胸部，讓肘部向兩側張開。", "在底部暫停片刻，然后將啞鈴推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0378', 'exercise', 1, '{"id": "0378", "target": "delts", "name_en": "dumbbell rear fly", "name_zh": "哑铃后飞鸟", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0378-8DiFDVA.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴后飛鳥", "instructions_en": ["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Extend your arms straight down towards the ground, palms facing each other.", "Keeping a slight bend in your elbows, lift your arms out to the sides and squeeze your shoulder blades together.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，每只手各握一个哑铃。", "稍微弯曲膝盖，髋部向前转动，保持背部挺直。", "将双臂笔直向下伸向地面，手掌相对。", "保持肘部轻微弯曲，将手臂向两侧抬起，并将肩胛骨挤压在一起。", "在顶部暂停片刻，然后慢慢将手臂放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["trapezius", "rhomboids"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，每只手各握一個啞鈴。", "稍微彎曲膝蓋，髖部向前轉動，保持背部挺直。", "將雙臂筆直向下伸向地面，手掌相對。", "保持肘部輕微彎曲，將手臂向兩側抬起，并將肩胛骨擠壓在一起。", "在頂部暫停片刻，然后慢慢將手臂放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0380', 'exercise', 1, '{"id": "0380", "target": "delts", "name_en": "dumbbell rear lateral raise", "name_zh": "哑铃后束飞鸟", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0380-v1qBec9.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴后束飛鳥", "instructions_en": ["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight and core engaged.", "Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。", "稍微弯曲膝盖，髋部向前转动，保持背部挺直，核心参与。", "将手臂向两侧举起，肘部保持轻微弯曲，直到与地板平行。", "在顶部暂停片刻，然后慢慢将手臂放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["traps", "rhomboids"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴，手掌朝向身體。", "稍微彎曲膝蓋，髖部向前轉動，保持背部挺直，核心參與。", "將手臂向兩側舉起，肘部保持輕微彎曲，直到與地板平行。", "在頂部暫停片刻，然后慢慢將手臂放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0379', 'exercise', 1, '{"id": "0379", "target": "delts", "name_en": "dumbbell rear lateral raise (support head)", "name_zh": "哑铃后束飞鸟（支撑头部）", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0379-UzkLrem.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴后束飛鳥（支撐頭部）", "instructions_en": ["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the ground.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，每只手各握一个哑铃。", "稍微弯曲膝盖，髋部向前转动，保持背部挺直。", "将手臂向两侧举起，肘部保持轻微弯曲，直到与地面平行。", "在顶部暂停片刻，然后慢慢将手臂放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["traps", "rhomboids"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，每只手各握一個啞鈴。", "稍微彎曲膝蓋，髖部向前轉動，保持背部挺直。", "將手臂向兩側舉起，肘部保持輕微彎曲，直到與地面平行。", "在頂部暫停片刻，然后慢慢將手臂放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0381', 'exercise', 1, '{"id": "0381", "target": "glutes", "name_en": "dumbbell rear lunge", "name_zh": "哑铃后撤弓步", "body_part": "upper legs", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0381-SSsBDwB.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴后撤弓步", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.", "Take a step backward with your right foot, lowering your body into a lunge position.", "Bend your left knee and lower your body until your left thigh is parallel to the ground.", "Pause for a moment, then push through your left heel to return to the starting position.", "Repeat on the other side, stepping back with your left foot."], "instructions_zh": ["双脚分开与肩同宽站立，每只手各握一个哑铃。", "右脚向后退一步，将身体降低至弓步位置。", "弯曲左膝并降低身体，直到左大腿与地面平行。", "暂停片刻，然后推动左脚跟回到起始位置。", "在另一侧重复，左脚向后退一步。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，每只手各握一個啞鈴。", "右腳向后退一步，將身體降低至弓步位置。", "彎曲左膝并降低身體，直到左大腿與地面平行。", "暫停片刻，然后推動左腳跟回到起始位置。", "在另一側重復，左腳向后退一步。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0382', 'exercise', 1, '{"id": "0382", "target": "biceps", "name_en": "dumbbell revers grip biceps curl", "name_zh": "哑铃反握二头弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0382-e4ojVhP.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴反握二頭彎舉", "instructions_en": ["Stand up straight with a dumbbell in each hand, palms facing down and arms fully extended.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站直，双手各握一个哑铃，手掌朝下，双臂完全伸展。", "保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。", "继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙手各握一個啞鈴，手掌朝下，雙臂完全伸展。", "保持上臂靜止，呼氣并彎舉啞鈴，同時收縮二頭肌。", "繼續舉重，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0383', 'exercise', 1, '{"id": "0383", "target": "delts", "name_en": "dumbbell reverse fly", "name_zh": "哑铃反向飞鸟", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0383-EAs3xL9.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴反向飛鳥", "instructions_en": ["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Extend your arms straight down in front of you, palms facing each other.", "Keeping a slight bend in your elbows, raise your arms out to the sides until they are parallel to the ground.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，每只手各握一个哑铃。", "稍微弯曲膝盖，髋部向前转动，保持背部挺直。", "将双臂伸直在身前，手掌相对。", "保持肘部轻微弯曲，将手臂向两侧抬起，直到与地面平行。", "在顶部暂停片刻，然后慢慢将手臂放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["trapezius", "rhomboids"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，每只手各握一個啞鈴。", "稍微彎曲膝蓋，髖部向前轉動，保持背部挺直。", "將雙臂伸直在身前，手掌相對。", "保持肘部輕微彎曲，將手臂向兩側抬起，直到與地面平行。", "在頂部暫停片刻，然后慢慢將手臂放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1330', 'exercise', 1, '{"id": "1330", "target": "upper back", "name_en": "dumbbell reverse grip incline bench one arm row", "name_zh": "哑铃反握上斜凳上单臂划船", "body_part": "back", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1330-ZIViNh1.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴反握上斜凳上單臂劃船", "instructions_en": ["Set up an incline bench at a 45-degree angle.", "Place a dumbbell on the floor next to the bench.", "Stand facing the bench with your feet shoulder-width apart.", "Bend at the waist and place your left knee and left hand on the bench for support.", "Pick up the dumbbell with your right hand using a reverse grip (palm facing down).", "Keep your back straight and your core engaged.", "Pull the dumbbell up towards your chest, keeping your elbow close to your body.", "Squeeze your back muscles at the top of the movement.", "Lower the dumbbell back down to the starting position in a controlled manner.", "Repeat for the desired number of repetitions.", "Switch sides and repeat the exercise with your left arm."], "instructions_zh": ["设置一个 45 度角的上斜凳。", "将哑铃放在长凳旁边的地板上。", "面对长凳站立，双脚分开与肩同宽。", "弯曲腰部，将左膝和左手放在长凳上以获得支撑。", "用右手反握（手掌朝下）拿起哑铃。", "保持背部挺直，核心肌群参与。", "将哑铃向上拉向胸部，保持肘部靠近身体。", "在动作的最高点挤压背部肌肉。", "以受控的方式将哑铃放回起始位置。", "重复所需的重复次数。", "换边并用左臂重复练习。"], "secondary_muscles": ["biceps", "shoulders"], "instructions_zh_hant": ["設置一個 45 度角的上斜凳。", "將啞鈴放在長凳旁邊的地板上。", "面對長凳站立，雙腳分開與肩同寬。", "彎曲腰部，將左膝和左手放在長凳上以獲得支撐。", "用右手反握（手掌朝下）拿起啞鈴。", "保持背部挺直，核心肌群參與。", "將啞鈴向上拉向胸部，保持肘部靠近身體。", "在動作的最高點擠壓背部肌肉。", "以受控的方式將啞鈴放回起始位置。", "重復所需的重復次數。", "換邊并用左臂重復練習。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1331', 'exercise', 1, '{"id": "1331", "target": "upper back", "name_en": "dumbbell reverse grip incline bench two arm row", "name_zh": "哑铃反握上斜凳上双臂划船", "body_part": "back", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1331-9pQSkH8.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴反握上斜凳上雙臂劃船", "instructions_en": ["Set up an incline bench at a 45-degree angle.", "Sit on the bench with your chest against the backrest and your feet flat on the ground.", "Hold a dumbbell in each hand with an underhand grip.", "Lean forward and let your arms hang straight down, fully extended.", "Pull the dumbbells up towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["设置一个 45 度角的上斜凳。", "坐在长凳上，胸部靠在靠背上，双脚平放在地上。", "双手各握一个哑铃，反握。", "身体前倾，双臂伸直下垂，完全伸展。", "将哑铃拉向胸部，将肩胛骨挤压在一起。", "在顶部停顿片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["設置一個 45 度角的上斜凳。", "坐在長凳上，胸部靠在靠背上，雙腳平放在地上。", "雙手各握一個啞鈴，反握。", "身體前傾，雙臂伸直下垂，完全伸展。", "將啞鈴拉向胸部，將肩胛骨擠壓在一起。", "在頂部停頓片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2327', 'exercise', 1, '{"id": "2327", "target": "upper back", "name_en": "dumbbell reverse grip row (female)", "name_zh": "哑铃反握划船（女性示范）", "body_part": "back", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/2327-Nh3mvOO.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴反握劃船（女性示范）", "instructions_en": ["Stand with your feet shoulder-width apart and knees slightly bent.", "Hold a dumbbell in each hand with an overhand grip, palms facing your body.", "Bend forward at the waist, keeping your back straight and your core engaged.", "Let your arms hang straight down, fully extended, with a slight bend in your elbows.", "Pull the dumbbells up towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站立，双脚分开与肩同宽，膝盖稍微弯曲。", "双手各握一个哑铃，正手握握，手掌朝向身体。", "腰部向前弯曲，保持背部挺直，核心肌群参与。", "让你的手臂伸直垂下，完全伸展，肘部稍微弯曲。", "将哑铃拉向胸部，将肩胛骨挤压在一起。", "在顶部停顿片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["站立，雙腳分開與肩同寬，膝蓋稍微彎曲。", "雙手各握一個啞鈴，正手握握，手掌朝向身體。", "腰部向前彎曲，保持背部挺直，核心肌群參與。", "讓你的手臂伸直垂下，完全伸展，肘部稍微彎曲。", "將啞鈴拉向胸部，將肩胛骨擠壓在一起。", "在頂部停頓片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0384', 'exercise', 1, '{"id": "0384", "target": "biceps", "name_en": "dumbbell reverse preacher curl", "name_zh": "哑铃反向牧师凳弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0384-O8Aq69u.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴反向牧師凳彎舉", "instructions_en": ["Sit on a preacher bench with your upper arms resting on the pad and your chest against the support.", "Hold a dumbbell in each hand with an underhand grip, palms facing up.", "Keeping your upper arms stationary, exhale and curl the dumbbells as you contract your biceps.", "Continue to curl the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在牧师凳上，上臂放在垫子上，胸部靠在支撑物上。", "每只手握住一个哑铃，反握，手掌朝上。", "保持上臂静止，呼气并弯曲哑铃，同时收缩二头肌。", "继续弯举哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在牧師凳上，上臂放在墊子上，胸部靠在支撐物上。", "每只手握住一個啞鈴，反握，手掌朝上。", "保持上臂靜止，呼氣并彎曲啞鈴，同時收縮二頭肌。", "繼續彎舉啞鈴，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1675', 'exercise', 1, '{"id": "1675", "target": "biceps", "name_en": "dumbbell reverse spider curl", "name_zh": "哑铃反向蜘蛛式弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1675-6sMAmNv.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴反向蜘蛛式彎舉", "instructions_en": ["Stand up straight with a dumbbell in each hand, palms facing your body and arms fully extended.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站直，双手各握一个哑铃，手掌朝向身体，双臂完全伸展。", "保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。", "继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙手各握一個啞鈴，手掌朝向身體，雙臂完全伸展。", "保持上臂靜止，呼氣并彎舉啞鈴，同時收縮二頭肌。", "繼續舉起啞鈴，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0385', 'exercise', 1, '{"id": "0385", "target": "forearms", "name_en": "dumbbell reverse wrist curl", "name_zh": "哑铃反握腕弯举", "body_part": "lower arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0385-BLCvwr2.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴反握腕彎舉", "instructions_en": ["Sit on a bench or chair with your feet flat on the ground.", "Hold a dumbbell in each hand with an overhand grip, palms facing down.", "Rest your forearms on your thighs, allowing your wrists to hang off the edge.", "Slowly curl your wrists upward, bringing the dumbbells towards your body.", "Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳或椅子上，双脚平放在地面上。", "双手各握一个哑铃，正手握握，手掌朝下。", "将前臂放在大腿上，让手腕悬在边缘。", "慢慢向上弯曲手腕，将哑铃拉向身体。", "在顶部停顿片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "brachialis"], "instructions_zh_hant": ["坐在長凳或椅子上，雙腳平放在地面上。", "雙手各握一個啞鈴，正手握握，手掌朝下。", "將前臂放在大腿上，讓手腕懸在邊緣。", "慢慢向上彎曲手腕，將啞鈴拉向身體。", "在頂部停頓片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1459', 'exercise', 1, '{"id": "1459", "target": "glutes", "name_en": "dumbbell romanian deadlift", "name_zh": "哑铃罗马尼亚硬拉", "body_part": "upper legs", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1459-rR0LJzx.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴羅馬尼亞硬拉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.", "Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing your knees to bend slightly.", "Lower the dumbbells until you feel a stretch in your hamstrings, then push through your heels and engage your glutes to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃，正握。", "保持背部挺直，核心收紧，以臀部为铰链，将哑铃向地面降低，让膝盖稍微弯曲。", "降低哑铃，直到感觉到腿筋拉伸，然后推动脚后跟并收紧臀肌，回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "lower back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴，正握。", "保持背部挺直，核心收緊，以臀部為鉸鏈，將啞鈴向地面降低，讓膝蓋稍微彎曲。", "降低啞鈴，直到感覺到腿筋拉伸，然后推動腳后跟并收緊臀肌，回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0386', 'exercise', 1, '{"id": "0386", "target": "delts", "name_en": "dumbbell rotation reverse fly", "name_zh": "哑铃旋转反向飞鸟", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0386-prbWx1D.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴旋轉反向飛鳥", "instructions_en": ["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing inwards.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.", "Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.", "Rotate your arms so that your palms are facing downwards.", "Slowly lower your arms back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃，掌心向内。", "稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。", "将手臂向两侧举起，肘部保持轻微弯曲，直到与地板平行。", "旋转手臂，使手掌朝下。", "慢慢地将手臂放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["trapezius", "rhomboids"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴，掌心向內。", "稍微彎曲膝蓋，臀部向前轉動，保持背部挺直，挺胸。", "將手臂向兩側舉起，肘部保持輕微彎曲，直到與地板平行。", "旋轉手臂，使手掌朝下。", "慢慢地將手臂放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2397', 'exercise', 1, '{"id": "2397", "target": "delts", "name_en": "dumbbell scott press", "name_zh": "哑铃斯科特推举", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/2397-5vfAI0I.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴斯科特推舉", "instructions_en": ["Sit on a bench with a dumbbell in each hand, palms facing forward.", "Raise the dumbbells to shoulder height, with your elbows bent and palms facing forward.", "Press the dumbbells upward until your arms are fully extended.", "Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双手各握一个哑铃，手掌朝前。", "将哑铃举至肩部高度，肘部弯曲，手掌朝前。", "向上推哑铃，直到手臂完全伸展。", "在最高点暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "chest"], "instructions_zh_hant": ["坐在長凳上，雙手各握一個啞鈴，手掌朝前。", "將啞鈴舉至肩部高度，肘部彎曲，手掌朝前。", "向上推啞鈴，直到手臂完全伸展。", "在最高點暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0387', 'exercise', 1, '{"id": "0387", "target": "delts", "name_en": "dumbbell seated alternate front raise", "name_zh": "哑铃坐姿交替前平举", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0387-gH5fRsC.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴坐姿交替前平舉", "instructions_en": ["Sit on a bench with your back straight and feet flat on the ground.", "Hold a dumbbell in each hand with your palms facing your body and arms extended down by your sides.", "Keeping your arms straight, raise one dumbbell in front of you until it is parallel to the ground.", "Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.", "Repeat with the other arm.", "Alternate between arms for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，背部挺直，双脚平放在地上。", "每只手握住一个哑铃，手掌朝向身体，手臂向下伸展到身体两侧。", "保持双臂伸直，将一只哑铃举至身前，直至其与地面平行。", "在顶部停顿片刻，然后慢慢将哑铃放回起始位置。", "用另一只手臂重复上述步骤。", "双臂交替进行所需的重复次数。"], "secondary_muscles": ["trapezius", "biceps"], "instructions_zh_hant": ["坐在長凳上，背部挺直，雙腳平放在地上。", "每只手握住一個啞鈴，手掌朝向身體，手臂向下伸展到身體兩側。", "保持雙臂伸直，將一只啞鈴舉至身前，直至其與地面平行。", "在頂部停頓片刻，然后慢慢將啞鈴放回起始位置。", "用另一只手臂重復上述步驟。", "雙臂交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1676', 'exercise', 1, '{"id": "1676", "target": "biceps", "name_en": "dumbbell seated alternate hammer curl on exercise ball", "name_zh": "健身球哑铃坐姿交替锤式弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1676-QLRmNeT.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球啞鈴坐姿交替錘式彎舉", "instructions_en": ["Sit on an exercise ball with your feet flat on the ground and your back straight.", "Hold a dumbbell in each hand with your palms facing your body and your arms fully extended.", "Keeping your upper arms stationary, exhale and curl one dumbbell up towards your shoulder while keeping your palm facing your body.", "Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly lower the dumbbell back to the starting position.", "Repeat the movement with the opposite arm.", "Continue alternating arms for the desired number of repetitions."], "instructions_zh": ["坐在健身球上，双脚平放在地上，背部挺直。", "每只手握住一个哑铃，手掌朝向身体，双臂完全伸展。", "保持上臂静止，呼气并将一只哑铃向上弯向肩膀，同时保持手掌朝向身体。", "继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气，慢慢将哑铃放回起始位置。", "用另一只手臂重复该动作。", "继续交替手臂进行所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在健身球上，雙腳平放在地上，背部挺直。", "每只手握住一個啞鈴，手掌朝向身體，雙臂完全伸展。", "保持上臂靜止，呼氣并將一只啞鈴向上彎向肩膀，同時保持手掌朝向身體。", "繼續舉起啞鈴，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣，慢慢將啞鈴放回起始位置。", "用另一只手臂重復該動作。", "繼續交替手臂進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0388', 'exercise', 1, '{"id": "0388", "target": "delts", "name_en": "dumbbell seated alternate press", "name_zh": "哑铃坐姿交替推举", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0388-QT5Q0nK.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴坐姿交替推舉", "instructions_en": ["Sit on a bench with a dumbbell in each hand, palms facing forward.", "Raise the dumbbells to shoulder height, with your elbows bent and palms facing forward.", "Press one dumbbell up overhead, fully extending your arm.", "Lower the dumbbell back down to shoulder height.", "Repeat with the other arm.", "Continue alternating arms for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双手各握一个哑铃，手掌朝前。", "将哑铃举至肩部高度，肘部弯曲，手掌朝前。", "将一只哑铃举过头顶，完全伸展手臂。", "将哑铃放回至肩膀高度。", "用另一只手臂重复上述步骤。", "继续交替手臂进行所需的重复次数。"], "secondary_muscles": ["triceps", "chest"], "instructions_zh_hant": ["坐在長凳上，雙手各握一個啞鈴，手掌朝前。", "將啞鈴舉至肩部高度，肘部彎曲，手掌朝前。", "將一只啞鈴舉過頭頂，完全伸展手臂。", "將啞鈴放回至肩膀高度。", "用另一只手臂重復上述步驟。", "繼續交替手臂進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3546', 'exercise', 1, '{"id": "3546", "target": "delts", "name_en": "dumbbell seated alternate shoulder", "name_zh": "哑铃坐姿交替肩上推举", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/3546-q7qkONO.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴坐姿交替肩上推舉", "instructions_en": ["Sit on a bench with your back straight and feet flat on the ground.", "Hold a dumbbell in each hand, palms facing inwards, and raise them to shoulder height.", "Press one dumbbell up overhead while keeping the other dumbbell at shoulder height.", "Lower the raised dumbbell back to shoulder height while simultaneously pressing the other dumbbell up overhead.", "Continue alternating between arms for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，背部挺直，双脚平放在地上。", "双手各握一个哑铃，掌心向内，将哑铃举至肩高。", "将一个哑铃举过头顶，同时将另一个哑铃保持在与肩同高的位置。", "将举起的哑铃放回肩高，同时将另一个哑铃推过头顶。", "继续交替手臂进行所需的重复次数。"], "secondary_muscles": ["triceps", "upper back"], "instructions_zh_hant": ["坐在長凳上，背部挺直，雙腳平放在地上。", "雙手各握一個啞鈴，掌心向內，將啞鈴舉至肩高。", "將一個啞鈴舉過頭頂，同時將另一個啞鈴保持在與肩同高的位置。", "將舉起的啞鈴放回肩高，同時將另一個啞鈴推過頭頂。", "繼續交替手臂進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0389', 'exercise', 1, '{"id": "0389", "target": "triceps", "name_en": "dumbbell seated bench extension", "name_zh": "哑铃凳上坐姿臂屈伸", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0389-JhYSVwT.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴凳上坐姿臂屈伸", "instructions_en": ["Sit on a bench with your back straight and feet flat on the ground.", "Hold a dumbbell with both hands and extend your arms straight up above your head.", "Slowly lower the dumbbell behind your head, keeping your elbows close to your ears.", "Pause for a moment, then raise the dumbbell back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，背部挺直，双脚平放在地上。", "双手握住哑铃，将手臂伸直至头顶上方。", "慢慢地将哑铃放到脑后，保持肘部靠近耳朵。", "暂停片刻，然后将哑铃举回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["坐在長凳上，背部挺直，雙腳平放在地上。", "雙手握住啞鈴，將手臂伸直至頭頂上方。", "慢慢地將啞鈴放到腦后，保持肘部靠近耳朵。", "暫停片刻，然后將啞鈴舉回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1677', 'exercise', 1, '{"id": "1677", "target": "biceps", "name_en": "dumbbell seated bicep curl", "name_zh": "哑铃坐姿二头弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1677-xiA6lRr.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴坐姿二頭彎舉", "instructions_en": ["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.", "Keep your back straight and your elbows close to your torso.", "Exhale and curl the dumbbells up towards your shoulders, contracting your biceps.", "Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双脚平放在地上，双手各握一个哑铃，掌心朝上。", "保持背部挺直，肘部靠近躯干。", "呼气并将哑铃向上弯向肩膀，收缩二头肌。", "在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在長凳上，雙腳平放在地上，雙手各握一個啞鈴，掌心朝上。", "保持背部挺直，肘部靠近軀幹。", "呼氣并將啞鈴向上彎向肩膀，收縮二頭肌。", "在頂部停頓片刻，然后吸氣，慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3547', 'exercise', 1, '{"id": "3547", "target": "biceps", "name_en": "dumbbell seated biceps curl to shoulder press", "name_zh": "哑铃坐姿二头弯举至肩上推举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/3547-OeL23VY.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴坐姿二頭彎舉至肩上推舉", "instructions_en": ["Sit on a bench with your back straight and feet flat on the ground.", "Hold a dumbbell in each hand with your palms facing forward and arms fully extended.", "Keeping your elbows close to your sides, curl the dumbbells up towards your shoulders.", "Once your forearms are vertical, rotate your wrists so that your palms are facing forward.", "Press the dumbbells overhead until your arms are fully extended.", "Lower the dumbbells back down to the starting position by reversing the movement.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，背部挺直，双脚平放在地上。", "每只手握住一个哑铃，手掌朝前，双臂完全伸展。", "保持肘部靠近身体两侧，将哑铃向上弯向肩膀。", "前臂垂直后，旋转手腕，使手掌朝前。", "将哑铃推过头顶，直到手臂完全伸展。", "通过反向运动将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["坐在長凳上，背部挺直，雙腳平放在地上。", "每只手握住一個啞鈴，手掌朝前，雙臂完全伸展。", "保持肘部靠近身體兩側，將啞鈴向上彎向肩膀。", "前臂垂直后，旋轉手腕，使手掌朝前。", "將啞鈴推過頭頂，直到手臂完全伸展。", "通過反向運動將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2317', 'exercise', 1, '{"id": "2317", "target": "delts", "name_en": "dumbbell seated bent arm lateral raise", "name_zh": "哑铃坐姿屈臂侧平举", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/2317-JzQbv7J.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴坐姿屈臂側平舉", "instructions_en": ["Sit on a bench with your back straight and feet flat on the ground.", "Hold a dumbbell in each hand with your palms facing your body and your arms bent at a 90-degree angle.", "Keeping your elbows bent, raise your arms out to the sides until they are parallel to the ground.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，背部挺直，双脚平放在地上。", "双手各握一个哑铃，手掌朝向身体，手臂弯曲成 90 度角。", "保持肘部弯曲，将手臂向两侧抬起，直到与地面平行。", "在顶部暂停片刻，然后慢慢将手臂放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["trapezius", "rhomboids"], "instructions_zh_hant": ["坐在長凳上，背部挺直，雙腳平放在地上。", "雙手各握一個啞鈴，手掌朝向身體，手臂彎曲成 90 度角。", "保持肘部彎曲，將手臂向兩側抬起，直到與地面平行。", "在頂部暫停片刻，然后慢慢將手臂放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1730', 'exercise', 1, '{"id": "1730", "target": "triceps", "name_en": "dumbbell seated bent over alternate kickback", "name_zh": "哑铃坐姿俯身交替臂后屈伸", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1730-x0lwvfq.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴坐姿俯身交替臂后屈伸", "instructions_en": ["Sit on a bench with a dumbbell in each hand, palms facing inwards.", "Bend forward at the waist, keeping your back straight and parallel to the ground.", "Extend one arm straight back, keeping it close to your body, until your arm is fully extended.", "Pause for a moment, then slowly lower the dumbbell back to the starting position.", "Repeat with the other arm.", "Continue alternating arms for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双手各握一个哑铃，手掌朝内。", "腰部向前弯曲，保持背部挺直并与地面平行。", "将一只手臂向后伸直，保持靠近身体，直到手臂完全伸展。", "暂停片刻，然后慢慢将哑铃放回起始位置。", "用另一只手臂重复上述步骤。", "继续交替手臂进行所需的重复次数。"], "secondary_muscles": ["shoulders", "back"], "instructions_zh_hant": ["坐在長凳上，雙手各握一個啞鈴，手掌朝內。", "腰部向前彎曲，保持背部挺直并與地面平行。", "將一只手臂向后伸直，保持靠近身體，直到手臂完全伸展。", "暫停片刻，然后慢慢將啞鈴放回起始位置。", "用另一只手臂重復上述步驟。", "繼續交替手臂進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1737', 'exercise', 1, '{"id": "1737", "target": "triceps", "name_en": "dumbbell seated bent over triceps extension", "name_zh": "哑铃坐姿俯身臂屈伸", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1737-4ievMJ9.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴坐姿俯身臂屈伸", "instructions_en": ["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand.", "Bend forward at the waist, keeping your back straight and your head up.", "Extend your arms straight back, keeping your elbows close to your head.", "Pause for a moment, then slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双脚平放在地上，每只手各握一个哑铃。", "腰部向前弯曲，保持背部挺直，头部抬起。", "将手臂向后伸直，保持肘部靠近头部。", "暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "back"], "instructions_zh_hant": ["坐在長凳上，雙腳平放在地上，每只手各握一個啞鈴。", "腰部向前彎曲，保持背部挺直，頭部抬起。", "將手臂向后伸直，保持肘部靠近頭部。", "暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1379', 'exercise', 1, '{"id": "1379", "target": "calves", "name_en": "dumbbell seated calf raise", "name_zh": "哑铃坐姿提踵", "body_part": "lower legs", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1379-r29jP7S.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴坐姿提踵", "instructions_en": ["Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your thighs.", "Place the balls of your feet on a raised surface such as a step or block, with your heels hanging off the edge.", "Hold onto the dumbbell for stability.", "Raise your heels as high as possible, lifting your body weight onto the balls of your feet.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳或椅子上，双脚平放在地面上，并将哑铃放在大腿上。", "将脚掌放在升高的表面（例如台阶或木块）上，脚跟悬在边缘外。", "握住哑铃以保持稳定。", "尽可能高地抬高脚后跟，将身体重量转移到脚掌上。", "在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings"], "instructions_zh_hant": ["坐在長凳或椅子上，雙腳平放在地面上，并將啞鈴放在大腿上。", "將腳掌放在升高的表面（例如臺階或木塊）上，腳跟懸在邊緣外。", "握住啞鈴以保持穩定。", "盡可能高地抬高腳后跟，將身體重量轉移到腳掌上。", "在頂部停頓片刻，然后慢慢降低腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0391', 'exercise', 1, '{"id": "0391", "target": "biceps", "name_en": "dumbbell seated curl", "name_zh": "哑铃坐姿弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0391-TiaZTxx.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴坐姿彎舉", "instructions_en": ["Sit on a bench with your feet flat on the ground and a dumbbell in each hand, palms facing forward.", "Keep your back straight and your elbows close to your torso.", "Exhale and curl the dumbbells up towards your shoulders, contracting your biceps.", "Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双脚平放在地面上，每只手各握一个哑铃，手掌朝前。", "保持背部挺直，肘部靠近躯干。", "呼气并将哑铃向上弯向肩膀，收缩二头肌。", "在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在長凳上，雙腳平放在地面上，每只手各握一個啞鈴，手掌朝前。", "保持背部挺直，肘部靠近軀幹。", "呼氣并將啞鈴向上彎向肩膀，收縮二頭肌。", "在頂部停頓片刻，然后吸氣，慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0392', 'exercise', 1, '{"id": "0392", "target": "delts", "name_en": "dumbbell seated front raise", "name_zh": "哑铃坐姿前平举", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0392-Ys97II0.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴坐姿前平舉", "instructions_en": ["Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.", "Keep your back straight and core engaged.", "Raise the dumbbells in front of you, with your palms facing down, until they are at shoulder level.", "Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双脚平放在地上，每只手各拿一个哑铃，放在大腿上。", "保持背部挺直，核心参与。", "将哑铃举到身前，手掌朝下，直到与肩同高。", "在顶部停顿片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["trapezius", "biceps"], "instructions_zh_hant": ["坐在長凳上，雙腳平放在地上，每只手各拿一個啞鈴，放在大腿上。", "保持背部挺直，核心參與。", "將啞鈴舉到身前，手掌朝下，直到與肩同高。", "在頂部停頓片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1678', 'exercise', 1, '{"id": "1678", "target": "biceps", "name_en": "dumbbell seated hammer curl", "name_zh": "哑铃坐姿锤式弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1678-IGtBdNT.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴坐姿錘式彎舉", "instructions_en": ["Sit on a bench with a dumbbell in each hand, palms facing your torso and arms extended straight down.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双手各握一个哑铃，手掌朝向躯干，手臂伸直向下。", "保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。", "继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在長凳上，雙手各握一個啞鈴，手掌朝向軀幹，手臂伸直向下。", "保持上臂靜止，呼氣并彎舉啞鈴，同時收縮二頭肌。", "繼續舉起啞鈴，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0393', 'exercise', 1, '{"id": "0393", "target": "biceps", "name_en": "dumbbell seated inner biceps curl", "name_zh": "哑铃坐姿内侧二头弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0393-KXyoEtA.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴坐姿內側二頭彎舉", "instructions_en": ["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.", "Rest your upper arms on your thighs, allowing the dumbbells to hang down.", "Keeping your upper arms stationary, curl the dumbbells up towards your shoulders by contracting your biceps.", "Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双脚平放在地上，双手各握一个哑铃，掌心朝上。", "将上臂放在大腿上，让哑铃垂下。", "保持上臂不动，通过收缩二头肌将哑铃向肩膀方向卷曲。", "在顶部停顿片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在長凳上，雙腳平放在地上，雙手各握一個啞鈴，掌心朝上。", "將上臂放在大腿上，讓啞鈴垂下。", "保持上臂不動，通過收縮二頭肌將啞鈴向肩膀方向卷曲。", "在頂部停頓片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0394', 'exercise', 1, '{"id": "0394", "target": "triceps", "name_en": "dumbbell seated kickback", "name_zh": "哑铃坐姿臂后屈伸", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0394-en550rk.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴坐姿臂后屈伸", "instructions_en": ["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand.", "Bend your knees slightly and lean forward from your hips, keeping your back straight.", "Bring your upper arms close to your sides and keep your elbows bent at a 90-degree angle.", "Extend your arms straight back, squeezing your triceps at the top of the movement.", "Pause for a moment, then slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双脚平放在地上，每只手各握一个哑铃。", "稍微弯曲膝盖，从臀部向前倾斜，保持背部挺直。", "将上臂靠近身体两侧，并保持肘部弯曲成 90 度角。", "将手臂向后伸直，在动作的最高点挤压三头肌。", "暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["坐在長凳上，雙腳平放在地上，每只手各握一個啞鈴。", "稍微彎曲膝蓋，從臀部向前傾斜，保持背部挺直。", "將上臂靠近身體兩側，并保持肘部彎曲成 90 度角。", "將手臂向后伸直，在動作的最高點擠壓三頭肌。", "暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0396', 'exercise', 1, '{"id": "0396", "target": "delts", "name_en": "dumbbell seated lateral raise", "name_zh": "哑铃坐姿侧平举", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0396-hxyTtWj.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴坐姿側平舉", "instructions_en": ["Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.", "Keep your back straight and core engaged.", "Raise the dumbbells to your sides with a slight bend in your elbows, until your arms are parallel to the ground.", "Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双脚平放在地上，每只手各拿一个哑铃，放在大腿上。", "保持背部挺直，核心参与。", "将哑铃举至身体两侧，肘部稍微弯曲，直到手臂与地面平行。", "在顶部停顿片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["traps", "upper back"], "instructions_zh_hant": ["坐在長凳上，雙腳平放在地上，每只手各拿一個啞鈴，放在大腿上。", "保持背部挺直，核心參與。", "將啞鈴舉至身體兩側，肘部稍微彎曲，直到手臂與地面平行。", "在頂部停頓片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0395', 'exercise', 1, '{"id": "0395", "target": "delts", "name_en": "dumbbell seated lateral raise v. 2", "name_zh": "哑铃坐姿侧平举变式2", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0395-hrrS0Ed.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴坐姿側平舉變式2", "instructions_en": ["Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.", "Keep your back straight and core engaged.", "Raise the dumbbells to your sides with a slight bend in your elbows, until your arms are parallel to the ground.", "Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双脚平放在地上，每只手各拿一个哑铃，放在大腿上。", "保持背部挺直，核心参与。", "将哑铃举至身体两侧，肘部稍微弯曲，直到手臂与地面平行。", "在顶部停顿片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["traps", "triceps"], "instructions_zh_hant": ["坐在長凳上，雙腳平放在地上，每只手各拿一個啞鈴，放在大腿上。", "保持背部挺直，核心參與。", "將啞鈴舉至身體兩側，肘部稍微彎曲，直到手臂與地面平行。", "在頂部停頓片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0397', 'exercise', 1, '{"id": "0397", "target": "biceps", "name_en": "dumbbell seated neutral wrist curl", "name_zh": "哑铃坐姿中立握腕弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0397-uJmK7Z1.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴坐姿中立握腕彎舉", "instructions_en": ["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing each other.", "Rest your forearms on your thighs, allowing the dumbbells to hang down.", "Keeping your wrists in a neutral position, curl the dumbbells up towards your shoulders.", "Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双脚平放在地上，双手各握一个哑铃，手掌相对。", "将前臂放在大腿上，让哑铃垂下。", "保持手腕处于中立位置，将哑铃向上弯向肩膀。", "在顶部停顿片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在長凳上，雙腳平放在地上，雙手各握一個啞鈴，手掌相對。", "將前臂放在大腿上，讓啞鈴垂下。", "保持手腕處于中立位置，將啞鈴向上彎向肩膀。", "在頂部停頓片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1679', 'exercise', 1, '{"id": "1679", "target": "biceps", "name_en": "dumbbell seated one arm bicep curl on exercise ball with leg raised", "name_zh": "健身球单腿支撑坐姿单臂哑铃弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1679-84sESNy.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球單腿支撐坐姿單臂啞鈴彎舉", "instructions_en": ["Sit on an exercise ball with your feet flat on the ground and your back straight.", "Hold a dumbbell in one hand with your palm facing up and your arm fully extended.", "Place your other hand on your hip for stability.", "Slowly curl the dumbbell towards your shoulder, keeping your upper arm stationary.", "Pause for a moment at the top of the movement, squeezing your bicep.", "Slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions.", "Switch arms and repeat the exercise."], "instructions_zh": ["坐在健身球上，双脚平放在地上，背部挺直。", "一只手握住哑铃，手掌朝上，手臂完全伸展。", "将另一只手放在臀部上以保持稳定。", "慢慢地将哑铃向肩膀弯曲，保持上臂静止。", "在动作的最高点暂停片刻，挤压你的二头肌。", "慢慢地将哑铃放回起始位置。", "重复所需的重复次数。", "交换手臂并重复练习。"], "secondary_muscles": ["forearms", "shoulders"], "instructions_zh_hant": ["坐在健身球上，雙腳平放在地上，背部挺直。", "一只手握住啞鈴，手掌朝上，手臂完全伸展。", "將另一只手放在臀部上以保持穩定。", "慢慢地將啞鈴向肩膀彎曲，保持上臂靜止。", "在動作的最高點暫停片刻，擠壓你的二頭肌。", "慢慢地將啞鈴放回起始位置。", "重復所需的重復次數。", "交換手臂并重復練習。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0398', 'exercise', 1, '{"id": "0398", "target": "triceps", "name_en": "dumbbell seated one arm kickback", "name_zh": "哑铃坐姿单臂臂后屈伸", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0398-VQ3sNCn.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴坐姿單臂臂后屈伸", "instructions_en": ["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand.", "Bend your torso forward at the waist, keeping your back straight and parallel to the ground.", "Extend your arm straight back, keeping your elbow close to your body.", "Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["坐在长凳上，双脚平放在地上，一手握住哑铃。", "将躯干的腰部向前弯曲，保持背部挺直并与地面平行。", "将手臂向后伸直，保持肘部靠近身体。", "在最高点暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["坐在長凳上，雙腳平放在地上，一手握住啞鈴。", "將軀幹的腰部向前彎曲，保持背部挺直并與地面平行。", "將手臂向后伸直，保持肘部靠近身體。", "在最高點暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0399', 'exercise', 1, '{"id": "0399", "target": "forearms", "name_en": "dumbbell seated one arm rotate", "name_zh": "哑铃坐姿单臂旋转", "body_part": "lower arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0399-7f2jsqP.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴坐姿單臂旋轉", "instructions_en": ["Sit on a bench with your back straight and hold a dumbbell in one hand, resting it on your thigh.", "Raise the dumbbell up to shoulder height, keeping your elbow close to your body.", "Rotate your forearm outward, away from your body, while keeping your upper arm stationary.", "Pause for a moment at the top, then slowly rotate your forearm back to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."], "instructions_zh": ["坐在长凳上，背部挺直，一只手握住哑铃，将其放在大腿上。", "将哑铃举至肩膀高度，保持肘部靠近身体。", "向外旋转前臂，远离身体，同时保持上臂静止。", "在顶部停顿片刻，然后慢慢旋转前臂回到起始位置。", "重复所需的重复次数，然后换到另一只手臂。"], "secondary_muscles": ["shoulders", "biceps"], "instructions_zh_hant": ["坐在長凳上，背部挺直，一只手握住啞鈴，將其放在大腿上。", "將啞鈴舉至肩膀高度，保持肘部靠近身體。", "向外旋轉前臂，遠離身體，同時保持上臂靜止。", "在頂部停頓片刻，然后慢慢旋轉前臂回到起始位置。", "重復所需的重復次數，然后換到另一只手臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0400', 'exercise', 1, '{"id": "0400", "target": "calves", "name_en": "dumbbell seated one leg calf raise", "name_zh": "哑铃坐姿单腿提踵", "body_part": "lower legs", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0400-Ia7tumC.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴坐姿單腿提踵", "instructions_en": ["Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your right thigh.", "Extend your left leg straight out in front of you, keeping your foot flexed.", "Place the ball of your right foot on an elevated surface, such as a step or weight plate.", "Using your calf muscles, raise your right heel as high as possible.", "Pause for a moment at the top, then slowly lower your heel back down to the starting position.", "Repeat for the desired number of repetitions, then switch legs."], "instructions_zh": ["坐在长凳或椅子上，双脚平放在地面上，将哑铃放在右大腿上。", "将左腿伸直到身前，保持脚部弯曲。", "将右脚掌放在升高的表面上，例如台阶或配重板。", "使用小腿肌肉，尽可能高地抬高右脚跟。", "在顶部暂停片刻，然后慢慢将脚跟放回起始位置。", "重复所需的重复次数，然后换腿。"], "secondary_muscles": ["hamstrings", "glutes"], "instructions_zh_hant": ["坐在長凳或椅子上，雙腳平放在地面上，將啞鈴放在右大腿上。", "將左腿伸直到身前，保持腳部彎曲。", "將右腳掌放在升高的表面上，例如臺階或配重板。", "使用小腿肌肉，盡可能高地抬高右腳跟。", "在頂部暫停片刻，然后慢慢將腳跟放回起始位置。", "重復所需的重復次數，然后換腿。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1380', 'exercise', 1, '{"id": "1380", "target": "calves", "name_en": "dumbbell seated one leg calf raise - hammer grip", "name_zh": "哑铃坐姿单腿提踵-锤式握", "body_part": "lower legs", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1380-FxhcxUW.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴坐姿單腿提踵-錘式握", "instructions_en": ["Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your thighs.", "Place one foot on a raised surface, such as a step or block, with your heel hanging off the edge.", "Hold the dumbbell with a hammer grip, meaning your palms are facing each other and your fingers are wrapped around the handle.", "Keeping your core engaged and your back straight, slowly raise your heel as high as possible by pushing through the ball of your foot.", "Pause for a moment at the top, then slowly lower your heel back down to the starting position.", "Repeat for the desired number of repetitions, then switch to the other leg."], "instructions_zh": ["坐在长凳或椅子上，双脚平放在地面上，并将哑铃放在大腿上。", "将一只脚放在凸起的表面上，例如台阶或木块，脚跟悬在边缘之外。", "用锤式握法握住哑铃，这意味着您的手掌相对，手指缠绕在手柄上。", "保持核心收紧，背部挺直，通过脚掌推动，将脚后跟慢慢抬高，尽可能高。", "在顶部暂停片刻，然后慢慢将脚跟放回起始位置。", "重复所需的重复次数，然后换另一条腿。"], "secondary_muscles": ["hamstrings", "glutes"], "instructions_zh_hant": ["坐在長凳或椅子上，雙腳平放在地面上，并將啞鈴放在大腿上。", "將一只腳放在凸起的表面上，例如臺階或木塊，腳跟懸在邊緣之外。", "用錘式握法握住啞鈴，這意味著您的手掌相對，手指纏繞在手柄上。", "保持核心收緊，背部挺直，通過腳掌推動，將腳后跟慢慢抬高，盡可能高。", "在頂部暫停片刻，然后慢慢將腳跟放回起始位置。", "重復所需的重復次數，然后換另一條腿。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1381', 'exercise', 1, '{"id": "1381", "target": "calves", "name_en": "dumbbell seated one leg calf raise - palm up", "name_zh": "哑铃坐姿单腿提踵-掌心向上", "body_part": "lower legs", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1381-VW88JNd.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴坐姿單腿提踵-掌心向上", "instructions_en": ["Sit on a bench or chair with your back straight and your feet flat on the ground.", "Hold a dumbbell in one hand and place it on top of your thigh, palm facing up.", "Lift one leg off the ground and extend it in front of you, keeping your knee slightly bent.", "Raise your heel as high as possible by pushing through the ball of your foot.", "Pause for a moment at the top, then slowly lower your heel back down.", "Repeat for the desired number of repetitions, then switch legs and repeat."], "instructions_zh": ["坐在长凳或椅子上，背部挺直，双脚平放在地面上。", "一只手握住哑铃，将其放在大腿上方，掌心朝上。", "将一条腿抬离地面并将其延伸到您面前，保持膝盖稍微弯曲。", "通过脚掌推动，尽可能高地抬起脚后跟。", "在顶部停顿片刻，然后慢慢降低脚跟。", "重复所需的重复次数，然后换腿并重复。"], "secondary_muscles": ["hamstrings", "glutes"], "instructions_zh_hant": ["坐在長凳或椅子上，背部挺直，雙腳平放在地面上。", "一只手握住啞鈴，將其放在大腿上方，掌心朝上。", "將一條腿抬離地面并將其延伸到您面前，保持膝蓋稍微彎曲。", "通過腳掌推動，盡可能高地抬起腳后跟。", "在頂部停頓片刻，然后慢慢降低腳跟。", "重復所需的重復次數，然后換腿并重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0401', 'exercise', 1, '{"id": "0401", "target": "forearms", "name_en": "dumbbell seated palms up wrist curl", "name_zh": "哑铃坐姿掌心向上腕弯举", "body_part": "lower arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0401-2dImyQ8.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴坐姿掌心向上腕彎舉", "instructions_en": ["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.", "Rest your forearms on your thighs, allowing your wrists to hang off the edge.", "Slowly curl your wrists upward, squeezing your forearms at the top of the movement.", "Pause for a moment, then lower your wrists back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双脚平放在地上，双手各握一个哑铃，掌心朝上。", "将前臂放在大腿上，让手腕悬在边缘。", "慢慢向上弯曲手腕，在动作的最高点挤压前臂。", "暂停片刻，然后将手腕放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "shoulders"], "instructions_zh_hant": ["坐在長凳上，雙腳平放在地上，雙手各握一個啞鈴，掌心朝上。", "將前臂放在大腿上，讓手腕懸在邊緣。", "慢慢向上彎曲手腕，在動作的最高點擠壓前臂。", "暫停片刻，然后將手腕放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0402', 'exercise', 1, '{"id": "0402", "target": "biceps", "name_en": "dumbbell seated preacher curl", "name_zh": "哑铃坐姿牧师凳弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0402-7D5bgLT.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴坐姿牧師凳彎舉", "instructions_en": ["Sit on a preacher curl bench with your feet flat on the floor.", "Hold a dumbbell in one hand with an underhand grip, resting your upper arm against the preacher pad.", "Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.", "Pause for a moment at the top, then inhale and slowly lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["坐在牧师弯举凳上，双脚平放在地板上。", "一只手握住哑铃，反手握住，将上臂靠在讲道垫上。", "保持上臂静止，呼气并将哑铃向上弯向肩膀。", "在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在牧師彎舉凳上，雙腳平放在地板上。", "一只手握住啞鈴，反手握住，將上臂靠在講道墊上。", "保持上臂靜止，呼氣并將啞鈴向上彎向肩膀。", "在頂部停頓片刻，然后吸氣，慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0403', 'exercise', 1, '{"id": "0403", "target": "biceps", "name_en": "dumbbell seated revers grip concentration curl", "name_zh": "哑铃坐姿反握集中弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0403-lyKCLmK.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴坐姿反握集中彎舉", "instructions_en": ["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing up.", "Rest your elbow on the inside of your thigh, just above the knee.", "Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder.", "Pause for a moment at the top, squeezing your biceps.", "Inhale and slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["坐在长凳上，双脚平放在地上，一手握住哑铃，掌心朝上。", "将肘部放在大腿内侧、膝盖上方。", "保持上臂静止，呼气并将哑铃向肩膀弯曲。", "在顶部暂停片刻，挤压你的二头肌。", "吸气，慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在長凳上，雙腳平放在地上，一手握住啞鈴，掌心朝上。", "將肘部放在大腿內側、膝蓋上方。", "保持上臂靜止，呼氣并將啞鈴向肩膀彎曲。", "在頂部暫停片刻，擠壓你的二頭肌。", "吸氣，慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1738', 'exercise', 1, '{"id": "1738", "target": "triceps", "name_en": "dumbbell seated reverse grip one arm overhead tricep extension", "name_zh": "哑铃坐姿反握单臂过顶臂屈伸", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1738-5fKX7wi.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴坐姿反握單臂過頂臂屈伸", "instructions_en": ["Sit on a bench with your back straight and feet flat on the ground.", "Hold a dumbbell with an underhand grip and extend your arm straight up overhead.", "Lower the dumbbell behind your head by bending your elbow, keeping your upper arm stationary.", "Pause for a moment, then extend your arm back up to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["坐在长凳上，背部挺直，双脚平放在地上。", "反手握住哑铃，将手臂伸直至头顶。", "弯曲肘部，将哑铃降低到头后，保持上臂静止。", "暂停片刻，然后将手臂伸回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["坐在長凳上，背部挺直，雙腳平放在地上。", "反手握住啞鈴，將手臂伸直至頭頂。", "彎曲肘部，將啞鈴降低到頭后，保持上臂靜止。", "暫停片刻，然后將手臂伸回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0404', 'exercise', 1, '{"id": "0404", "target": "delts", "name_en": "dumbbell seated shoulder press (parallel grip)", "name_zh": "哑铃坐姿肩上推举（对握）", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0404-f1jf47L.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴坐姿肩上推舉（對握）", "instructions_en": ["Sit on a bench with a dumbbell in each hand, palms facing inward.", "Raise the dumbbells to shoulder height, elbows bent and palms facing forward.", "Press the dumbbells upward until your arms are fully extended overhead.", "Pause for a moment at the top, then slowly lower the dumbbells back to shoulder height.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双手各握一个哑铃，掌心向内。", "将哑铃举至肩高，肘部弯曲，手掌朝前。", "向上推哑铃，直到手臂完全伸过头顶。", "在顶部停顿片刻，然后慢慢将哑铃放回肩部高度。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "upper back"], "instructions_zh_hant": ["坐在長凳上，雙手各握一個啞鈴，掌心向內。", "將啞鈴舉至肩高，肘部彎曲，手掌朝前。", "向上推啞鈴，直到手臂完全伸過頭頂。", "在頂部停頓片刻，然后慢慢將啞鈴放回肩部高度。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2188', 'exercise', 1, '{"id": "2188", "target": "triceps", "name_en": "dumbbell seated triceps extension", "name_zh": "哑铃坐姿臂屈伸", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/2188-kont8Ut.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴坐姿臂屈伸", "instructions_en": ["Sit on a bench with your back straight and feet flat on the ground.", "Hold a dumbbell with both hands and extend your arms straight up overhead.", "Bend your elbows and lower the dumbbell behind your head, keeping your upper arms close to your ears.", "Pause for a moment, then straighten your arms and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，背部挺直，双脚平放在地上。", "双手握住哑铃，双臂伸直举过头顶。", "弯曲肘部，将哑铃放在脑后，保持上臂靠近耳朵。", "暂停片刻，然后伸直手臂，回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["坐在長凳上，背部挺直，雙腳平放在地上。", "雙手握住啞鈴，雙臂伸直舉過頭頂。", "彎曲肘部，將啞鈴放在腦后，保持上臂靠近耳朵。", "暫停片刻，然后伸直手臂，回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0406', 'exercise', 1, '{"id": "0406", "target": "traps", "name_en": "dumbbell shrug", "name_zh": "哑铃耸肩", "body_part": "back", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0406-NJzBsGJ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴聳肩", "instructions_en": ["Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your body.", "Keep your arms straight and let the dumbbells hang by your sides.", "Raise your shoulders as high as possible, as if you are trying to touch your ears with your shoulders.", "Hold the contraction for a second, then slowly lower your shoulders back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。", "保持手臂伸直，让哑铃垂在身体两侧。", "尽可能高地抬高肩膀，就像试图用肩膀触碰耳朵一样。", "保持收缩一秒钟，然后慢慢将肩膀放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴，手掌朝向身體。", "保持手臂伸直，讓啞鈴垂在身體兩側。", "盡可能高地抬高肩膀，就像試圖用肩膀觸碰耳朵一樣。", "保持收縮一秒鐘，然后慢慢將肩膀放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0407', 'exercise', 1, '{"id": "0407", "target": "abs", "name_en": "dumbbell side bend", "name_zh": "哑铃侧屈", "body_part": "waist", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0407-IpONWYv.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴側屈", "instructions_en": ["Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand, letting it hang down by your side.", "Keeping your back straight and your core engaged, slowly bend sideways at the waist towards the opposite side of the dumbbell, lowering the weight as far as you comfortably can.", "Pause for a moment, then slowly return to the starting position.", "Repeat for the desired number of repetitions, then switch sides and repeat."], "instructions_zh": ["站直，双脚分开与肩同宽，一手握住哑铃，让它垂在身侧。", "保持背部挺直，核心肌群参与，慢慢地将腰部向哑铃的另一侧侧弯，在舒适的范围内尽可能降低重量。", "暂停片刻，然后慢慢回到起始位置。", "重复所需的重复次数，然后换边重复。"], "secondary_muscles": ["obliques"], "instructions_zh_hant": ["站直，雙腳分開與肩同寬，一手握住啞鈴，讓它垂在身側。", "保持背部挺直，核心肌群參與，慢慢地將腰部向啞鈴的另一側側彎，在舒適的范圍內盡可能降低重量。", "暫停片刻，然后慢慢回到起始位置。", "重復所需的重復次數，然后換邊重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0408', 'exercise', 1, '{"id": "0408", "target": "delts", "name_en": "dumbbell side lying one hand raise", "name_zh": "哑铃侧卧单臂侧平举", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0408-fTlkJop.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴側臥單臂側平舉", "instructions_en": ["Lie on your side with your legs extended and your head supported by your arm.", "Hold a dumbbell in your top hand with your palm facing down.", "Keeping your arm straight, raise the dumbbell up to shoulder height.", "Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["侧躺，双腿伸直，用手臂支撑头部。", "用你的上手握住哑铃，手掌朝下。", "保持手臂伸直，将哑铃举至肩膀高度。", "在顶部停顿片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["trapezius", "rhomboids"], "instructions_zh_hant": ["側躺，雙腿伸直，用手臂支撐頭部。", "用你的上手握住啞鈴，手掌朝下。", "保持手臂伸直，將啞鈴舉至肩膀高度。", "在頂部停頓片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3664', 'exercise', 1, '{"id": "3664", "target": "upper back", "name_en": "dumbbell side plank with rear fly", "name_zh": "哑铃侧平板支撑配合后飞鸟", "body_part": "back", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/3664-X6ytgYZ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴側平板支撐配合后飛鳥", "instructions_en": ["Start by lying on your side with your legs extended and stacked on top of each other.", "Place your forearm on the ground directly below your shoulder, keeping your elbow bent at a 90-degree angle.", "Hold a dumbbell in your top hand, with your arm extended straight down towards the ground.", "Engage your core and lift your hips off the ground, creating a straight line from your head to your heels.", "While maintaining the side plank position, lift the dumbbell up towards the ceiling, squeezing your shoulder blades together.", "Lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["首先侧躺，双腿伸展并叠放在一起。", "将前臂放在肩膀正下方的地面上，保持肘部弯曲成 90 度角。", "用你的上手握住哑铃，手臂垂直向下伸向地面。", "收紧核心并将臀部抬离地面，从头部到脚后跟形成一条直线。", "在保持侧平板支撑位置的同时，将哑铃向天花板方向举起，将肩胛骨挤压在一起。", "将哑铃放回起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["shoulders", "core"], "instructions_zh_hant": ["首先側躺，雙腿伸展并疊放在一起。", "將前臂放在肩膀正下方的地面上，保持肘部彎曲成 90 度角。", "用你的上手握住啞鈴，手臂垂直向下伸向地面。", "收緊核心并將臀部抬離地面，從頭部到腳后跟形成一條直線。", "在保持側平板支撐位置的同時，將啞鈴向天花板方向舉起，將肩胛骨擠壓在一起。", "將啞鈴放回起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3548', 'exercise', 1, '{"id": "3548", "target": "delts", "name_en": "dumbbell single arm overhead carry", "name_zh": "哑铃单臂过顶行走", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/3548-mWBtgmb.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴單臂過頂行走", "instructions_en": ["Stand tall with your feet shoulder-width apart, holding a dumbbell in one hand.", "Raise the dumbbell overhead, fully extending your arm.", "Engage your core and keep your back straight as you walk forward, maintaining the dumbbell overhead.", "Continue walking for the desired distance or time.", "Switch hands and repeat the exercise."], "instructions_zh": ["站直，双脚分开与肩同宽，一手握住哑铃。", "将哑铃举过头顶，充分伸展手臂。", "向前行走时，启动核心肌群并保持背部挺直，将哑铃举过头顶。", "继续步行所需的距离或时间。", "交换双手并重复练习。"], "secondary_muscles": ["traps", "core"], "instructions_zh_hant": ["站直，雙腳分開與肩同寬，一手握住啞鈴。", "將啞鈴舉過頭頂，充分伸展手臂。", "向前行走時，啟動核心肌群并保持背部挺直，將啞鈴舉過頭頂。", "繼續步行所需的距離或時間。", "交換雙手并重復練習。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0409', 'exercise', 1, '{"id": "0409", "target": "calves", "name_en": "dumbbell single leg calf raise", "name_zh": "哑铃单腿提踵", "body_part": "lower legs", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0409-1kB3Wmk.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴單腿提踵", "instructions_en": ["Stand on the edge of a step or platform with your heels hanging off and your toes on the step.", "Hold a dumbbell in one hand and place your other hand on a wall or railing for support.", "Raise your heel as high as possible, lifting your body up onto your toes.", "Pause for a moment at the top, then slowly lower your heel back down below the step.", "Repeat for the desired number of repetitions, then switch to the other leg."], "instructions_zh": ["站在台阶或平台的边缘，脚后跟悬垂，脚趾放在台阶上。", "一手握住哑铃，另一只手放在墙壁或栏杆上以获得支撑。", "尽可能高地抬高脚跟，将身体抬起到脚趾上。", "在顶部停顿片刻，然后慢慢将脚跟放回到台阶下方。", "重复所需的重复次数，然后换另一条腿。"], "secondary_muscles": ["ankles"], "instructions_zh_hant": ["站在臺階或平臺的邊緣，腳后跟懸垂，腳趾放在臺階上。", "一手握住啞鈴，另一只手放在墻壁或欄桿上以獲得支撐。", "盡可能高地抬高腳跟，將身體抬起到腳趾上。", "在頂部停頓片刻，然后慢慢將腳跟放回到臺階下方。", "重復所需的重復次數，然后換另一條腿。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1757', 'exercise', 1, '{"id": "1757", "target": "glutes", "name_en": "dumbbell single leg deadlift", "name_zh": "哑铃单腿硬拉", "body_part": "upper legs", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1757-gKozT8X.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴單腿硬拉", "instructions_en": ["Stand with your feet hip-width apart, holding a dumbbell in your right hand.", "Shift your weight onto your left leg and lift your right foot slightly off the ground.", "Keeping your back straight, hinge forward at the hips and lower the dumbbell towards the ground.", "At the same time, extend your right leg straight behind you, maintaining a slight bend in your left knee.", "Lower the dumbbell until your torso and right leg are parallel to the ground.", "Pause for a moment, then engage your glutes and hamstrings to return to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["双脚分开与臀部同宽站立，右手握住哑铃。", "将体重转移到左腿上，并将右脚稍微抬离地面。", "保持背部挺直，臀部向前转动，将哑铃放低至地面。", "同时，将右腿伸直在身后，保持左膝轻微弯曲。", "降低哑铃，直到躯干和右腿与地面平行。", "暂停片刻，然后收紧臀肌和腿筋，回到起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["hamstrings", "lower back"], "instructions_zh_hant": ["雙腳分開與臀部同寬站立，右手握住啞鈴。", "將體重轉移到左腿上，并將右腳稍微抬離地面。", "保持背部挺直，臀部向前轉動，將啞鈴放低至地面。", "同時，將右腿伸直在身后，保持左膝輕微彎曲。", "降低啞鈴，直到軀幹和右腿與地面平行。", "暫停片刻，然后收緊臀肌和腿筋，回到起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2805', 'exercise', 1, '{"id": "2805", "target": "glutes", "name_en": "dumbbell single leg deadlift with stepbox support", "name_zh": "哑铃单腿硬拉配合踏台支撑", "body_part": "upper legs", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/2805-daBmy1Y.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴單腿硬拉配合踏臺支撐", "instructions_en": ["Stand with your feet hip-width apart, holding a dumbbell in your right hand.", "Place your left foot on a stepbox or elevated surface behind you.", "Keeping your back straight and core engaged, hinge forward at the hips, lowering the dumbbell towards the ground.", "As you lower the dumbbell, simultaneously lift your left leg behind you, maintaining a straight line from head to heel.", "Lower the dumbbell until you feel a stretch in your right hamstring, then return to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["双脚分开与臀部同宽站立，右手握住哑铃。", "将左脚放在身后的台阶或高架表面上。", "保持背部挺直，核心收紧，髋部向前转动，将哑铃放低至地面。", "当你放下哑铃时，同时将左腿抬起到身后，从头到脚跟保持一条直线。", "降低哑铃，直到感觉到右腿筋拉伸，然后回到起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["hamstrings", "lower back"], "instructions_zh_hant": ["雙腳分開與臀部同寬站立，右手握住啞鈴。", "將左腳放在身后的臺階或高架表面上。", "保持背部挺直，核心收緊，髖部向前轉動，將啞鈴放低至地面。", "當你放下啞鈴時，同時將左腿抬起到身后，從頭到腳跟保持一條直線。", "降低啞鈴，直到感覺到右腿筋拉伸，然后回到起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0410', 'exercise', 1, '{"id": "0410", "target": "quads", "name_en": "dumbbell single leg split squat", "name_zh": "哑铃单腿分腿蹲", "body_part": "upper legs", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0410-qx4fgX7.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴單腿分腿蹲", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.", "Take a step forward with one foot and position your feet so that your front foot is flat on the ground and your back foot is elevated on a bench or step.", "Lower your body by bending your front knee and hip, keeping your back knee slightly bent and your back heel off the ground.", "Continue lowering until your front thigh is parallel to the ground, then push through your front heel to return to the starting position.", "Repeat for the desired number of repetitions, then switch legs and repeat."], "instructions_zh": ["双脚分开与肩同宽站立，每只手各握一个哑铃。", "一只脚向前迈出一步，调整双脚的位置，使前脚平放在地面上，后脚抬高在长凳或台阶上。", "弯曲前膝盖和臀部，降低身体，保持后膝盖稍微弯曲，后脚跟离开地面。", "继续降低，直到大腿前部与地面平行，然后通过前脚跟推回到起始位置。", "重复所需的重复次数，然后换腿并重复。"], "secondary_muscles": ["glutes", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，每只手各握一個啞鈴。", "一只腳向前邁出一步，調整雙腳的位置，使前腳平放在地面上，后腳抬高在長凳或臺階上。", "彎曲前膝蓋和臀部，降低身體，保持后膝蓋稍微彎曲，后腳跟離開地面。", "繼續降低，直到大腿前部與地面平行，然后通過前腳跟推回到起始位置。", "重復所需的重復次數，然后換腿并重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1739', 'exercise', 1, '{"id": "1739", "target": "triceps", "name_en": "dumbbell standing alternating tricep kickback", "name_zh": "哑铃站姿交替肱三头肌臂后屈伸", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1739-Gi2BXfK.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴站姿交替肱三頭肌臂后屈伸", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Extend your arms straight back, keeping your elbows close to your body.", "Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.", "Repeat with the other arm, alternating sides with each repetition."], "instructions_zh": ["双脚分开与肩同宽站立，每只手各握一个哑铃。", "稍微弯曲膝盖，髋部向前转动，保持背部挺直。", "双臂向后伸直，保持肘部靠近身体。", "在最高点暂停片刻，然后慢慢将哑铃放回起始位置。", "用另一只手臂重复上述动作，每次重复时交替进行。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，每只手各握一個啞鈴。", "稍微彎曲膝蓋，髖部向前轉動，保持背部挺直。", "雙臂向后伸直，保持肘部靠近身體。", "在最高點暫停片刻，然后慢慢將啞鈴放回起始位置。", "用另一只手臂重復上述動作，每次重復時交替進行。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0411', 'exercise', 1, '{"id": "0411", "target": "glutes", "name_en": "dumbbell single leg squat", "name_zh": "哑铃单腿深蹲", "body_part": "upper legs", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0411-H6ybluc.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴單腿深蹲", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.", "Extend one leg forward and keep it off the ground throughout the exercise.", "Bend your standing leg and lower your body down as if sitting back into a chair.", "Keep your chest up and your back straight.", "Pause for a moment at the bottom, then push through your heel to return to the starting position.", "Repeat for the desired number of repetitions, then switch legs."], "instructions_zh": ["双脚分开与肩同宽站立，每只手各握一个哑铃。", "向前伸展一条腿，并在整个练习过程中保持其离开地面。", "弯曲站立的腿并降低身体，就像坐回椅子上一样。", "保持挺胸、背部挺直。", "在底部停顿片刻，然后用脚跟推动回到起始位置。", "重复所需的重复次数，然后换腿。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，每只手各握一個啞鈴。", "向前伸展一條腿，并在整個練習過程中保持其離開地面。", "彎曲站立的腿并降低身體，就像坐回椅子上一樣。", "保持挺胸、背部挺直。", "在底部停頓片刻，然后用腳跟推動回到起始位置。", "重復所需的重復次數，然后換腿。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0413', 'exercise', 1, '{"id": "0413", "target": "glutes", "name_en": "dumbbell squat", "name_zh": "哑铃深蹲", "body_part": "upper legs", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0413-HsvHqgf.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴深蹲", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.", "Keeping your chest up and core engaged, lower your body down by bending at the knees and hips, as if sitting back into a chair.", "Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.", "Pause for a moment at the bottom, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃放在身体两侧。", "保持胸部挺直，核心收紧，弯曲膝盖和臀部，降低身体，就像坐回椅子上一样。", "继续降低，直到大腿与地面平行，或者尽可能低。", "在底部停顿片刻，然后推动脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴放在身體兩側。", "保持胸部挺直，核心收緊，彎曲膝蓋和臀部，降低身體，就像坐回椅子上一樣。", "繼續降低，直到大腿與地面平行，或者盡可能低。", "在底部停頓片刻，然后推動腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3560', 'exercise', 1, '{"id": "3560", "target": "biceps", "name_en": "dumbbell standing alternate hammer curl and press", "name_zh": "哑铃站姿交替锤式弯举与推举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/3560-LeaZOIz.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴站姿交替錘式彎舉與推舉", "instructions_en": ["Stand up straight with a dumbbell in each hand, palms facing your body.", "Keep your elbows close to your torso and your back straight.", "Exhale and curl the dumbbell in your right hand towards your shoulder, keeping your upper arm stationary.", "Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.", "Inhale and slowly lower the dumbbell back to the starting position.", "Repeat the curl with your left hand.", "After completing the curl with your left hand, exhale and press the dumbbell in your right hand overhead.", "Extend your arm fully and hold for a moment at the top.", "Inhale and slowly lower the dumbbell back to the starting position.", "Repeat the press with your left hand.", "Continue alternating between curls and presses for the desired number of repetitions."], "instructions_zh": ["站直，双手各持一个哑铃，手掌朝向身体。", "保持肘部靠近躯干，背部挺直。", "呼气，将右手的哑铃向肩膀弯曲，保持上臂静止。", "继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。", "吸气，慢慢将哑铃放回起始位置。", "用左手重复卷发动作。", "左手完成弯举后，呼气，将右手的哑铃压过头顶。", "完全伸展手臂并在顶部保持片刻。", "吸气，慢慢将哑铃放回起始位置。", "用左手重复按压。", "继续交替进行弯举和推举，达到所需的重复次数。"], "secondary_muscles": ["forearms", "shoulders"], "instructions_zh_hant": ["站直，雙手各持一個啞鈴，手掌朝向身體。", "保持肘部靠近軀幹，背部挺直。", "呼氣，將右手的啞鈴向肩膀彎曲，保持上臂靜止。", "繼續舉起啞鈴，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "吸氣，慢慢將啞鈴放回起始位置。", "用左手重復卷發動作。", "左手完成彎舉后，呼氣，將右手的啞鈴壓過頭頂。", "完全伸展手臂并在頂部保持片刻。", "吸氣，慢慢將啞鈴放回起始位置。", "用左手重復按壓。", "繼續交替進行彎舉和推舉，達到所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0414', 'exercise', 1, '{"id": "0414", "target": "delts", "name_en": "dumbbell standing alternate overhead press", "name_zh": "哑铃站姿交替过顶推举", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0414-bBi35y3.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴站姿交替過頂推舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing forward.", "Press one dumbbell overhead, fully extending your arm.", "Lower the dumbbell back to shoulder level.", "Repeat with the other arm.", "Continue alternating arms for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高，手掌朝前。", "将一只哑铃举过头顶，完全伸展手臂。", "将哑铃放低至肩部水平。", "用另一只手臂重复上述步骤。", "继续交替手臂进行所需的重复次数。"], "secondary_muscles": ["triceps", "core"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴，與肩同高，手掌朝前。", "將一只啞鈴舉過頭頂，完全伸展手臂。", "將啞鈴放低至肩部水平。", "用另一只手臂重復上述步驟。", "繼續交替手臂進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0833', 'exercise', 1, '{"id": "0833", "target": "calves", "name_en": "weighted donkey calf raise", "name_zh": "负重驴式提踵", "body_part": "lower legs", "equipment": "weighted", "gif_asset": "assets/fitness/videos/0833-LmaFNZS.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重驢式提踵", "instructions_en": ["Stand on a raised platform with your toes on the edge and your heels hanging off.", "Hold onto a stable object for support.", "Raise your heels as high as possible by extending your ankles.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站在一个升高的平台上，脚趾放在边缘，脚后跟悬垂。", "抓住一个稳定的物体作为支撑。", "伸展脚踝，将脚后跟尽可能抬高。", "在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "glutes"], "instructions_zh_hant": ["站在一個升高的平臺上，腳趾放在邊緣，腳后跟懸垂。", "抓住一個穩定的物體作為支撐。", "伸展腳踝，將腳后跟盡可能抬高。", "在頂部停頓片刻，然后慢慢降低腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0415', 'exercise', 1, '{"id": "0415", "target": "delts", "name_en": "dumbbell standing alternate raise", "name_zh": "哑铃站姿交替抬举", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0415-SxHteRW.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴站姿交替抬舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.", "Keep your back straight and your core engaged.", "Raise one dumbbell to the side, keeping your arm straight and your palm facing down.", "Continue lifting until your arm is parallel to the ground.", "Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.", "Repeat with the other arm.", "Alternate between arms for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。", "保持背部挺直，核心肌群参与。", "将一个哑铃举到一侧，保持手臂伸直，手掌朝下。", "继续抬起，直到手臂与地面平行。", "在最高点暂停片刻，然后慢慢将哑铃放回起始位置。", "用另一只手臂重复上述步骤。", "双臂交替进行所需的重复次数。"], "secondary_muscles": ["traps", "forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴，手掌朝向身體。", "保持背部挺直，核心肌群參與。", "將一個啞鈴舉到一側，保持手臂伸直，手掌朝下。", "繼續抬起，直到手臂與地面平行。", "在最高點暫停片刻，然后慢慢將啞鈴放回起始位置。", "用另一只手臂重復上述步驟。", "雙臂交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2143', 'exercise', 1, '{"id": "2143", "target": "delts", "name_en": "dumbbell standing around world", "name_zh": "哑铃站姿绕头环举", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/2143-RSOsp5d.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴站姿繞頭環舉", "instructions_en": ["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.", "Extend your arms straight out to the sides at shoulder height, palms facing down.", "Keeping your arms straight, slowly rotate your arms in a circular motion, bringing the dumbbells in front of your body and then overhead.", "Continue the circular motion, bringing the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，每只手各握一个哑铃。", "将手臂伸直至两侧，与肩同高，手掌朝下。", "保持手臂伸直，慢慢地以圆周运动旋转手臂，将哑铃放在身体前面，然后举过头顶。", "继续圆周运动，将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，每只手各握一個啞鈴。", "將手臂伸直至兩側，與肩同高，手掌朝下。", "保持手臂伸直，慢慢地以圓周運動旋轉手臂，將啞鈴放在身體前面，然后舉過頭頂。", "繼續圓周運動，將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1740', 'exercise', 1, '{"id": "1740", "target": "triceps", "name_en": "dumbbell standing bent over one arm triceps extension", "name_zh": "哑铃站姿俯身单臂臂屈伸", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1740-CJwa0vD.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴站姿俯身單臂臂屈伸", "instructions_en": ["Stand with your feet shoulder-width apart and hold a dumbbell in one hand.", "Bend forward at the waist, keeping your back straight and parallel to the ground.", "Extend your arm straight back, keeping your elbow close to your body.", "Slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["双脚分开与肩同宽站立，一只手握住哑铃。", "腰部向前弯曲，保持背部挺直并与地面平行。", "将手臂向后伸直，保持肘部靠近身体。", "慢慢地将哑铃放回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["shoulders", "back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，一只手握住啞鈴。", "腰部向前彎曲，保持背部挺直并與地面平行。", "將手臂向后伸直，保持肘部靠近身體。", "慢慢地將啞鈴放回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1741', 'exercise', 1, '{"id": "1741", "target": "triceps", "name_en": "dumbbell standing bent over two arm triceps extension", "name_zh": "哑铃站姿俯身双臂臂屈伸", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1741-3T12T87.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴站姿俯身雙臂臂屈伸", "instructions_en": ["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.", "Bend forward at the waist, keeping your back straight and your knees slightly bent.", "Extend your arms straight back, keeping your elbows close to your body.", "Slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，每只手各握一个哑铃。", "腰部向前弯曲，保持背部挺直，膝盖稍微弯曲。", "双臂向后伸直，保持肘部靠近身体。", "慢慢地将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，每只手各握一個啞鈴。", "腰部向前彎曲，保持背部挺直，膝蓋稍微彎曲。", "雙臂向后伸直，保持肘部靠近身體。", "慢慢地將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0421', 'exercise', 1, '{"id": "0421", "target": "biceps", "name_en": "dumbbell standing one arm concentration curl", "name_zh": "哑铃站姿单臂集中弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0421-8fgqP5a.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴站姿單臂集中彎舉", "instructions_en": ["Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand, palm facing up.", "Place your free hand on your thigh for support.", "Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.", "Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["站直，双脚分开与肩同宽，一手握住哑铃，掌心朝上。", "将空着的手放在大腿上以获得支撑。", "保持上臂静止，呼气，通过收缩二头肌将哑铃向肩膀弯曲。", "继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气，慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙腳分開與肩同寬，一手握住啞鈴，掌心朝上。", "將空著的手放在大腿上以獲得支撐。", "保持上臂靜止，呼氣，通過收縮二頭肌將啞鈴向肩膀彎曲。", "繼續舉起啞鈴，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣，慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0416', 'exercise', 1, '{"id": "0416", "target": "biceps", "name_en": "dumbbell standing biceps curl", "name_zh": "哑铃站姿二头弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0416-3s4NnTh.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴站姿二頭彎舉", "instructions_en": ["Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站直，双手各握一个哑铃，手掌朝前，双臂完全伸展。", "保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。", "继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙手各握一個啞鈴，手掌朝前，雙臂完全伸展。", "保持上臂靜止，呼氣并彎舉啞鈴，同時收縮二頭肌。", "繼續舉起啞鈴，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0417', 'exercise', 1, '{"id": "0417", "target": "calves", "name_en": "dumbbell standing calf raise", "name_zh": "哑铃站姿提踵", "body_part": "lower legs", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0417-dPmaUaU.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴站姿提踵", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.", "Raise your heels off the ground as high as possible, using your calves.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，每只手各握一个哑铃。", "用小腿将脚跟抬离地面，尽可能高。", "在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["ankles"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，每只手各握一個啞鈴。", "用小腿將腳跟抬離地面，盡可能高。", "在頂部停頓片刻，然后慢慢降低腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0418', 'exercise', 1, '{"id": "0418", "target": "biceps", "name_en": "dumbbell standing concentration curl", "name_zh": "哑铃站姿集中弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0418-7inpWch.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴站姿集中彎舉", "instructions_en": ["Stand with your feet shoulder-width apart and hold a dumbbell in one hand, with your arm fully extended and palm facing inwards.", "Place your opposite hand on your thigh for support.", "Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.", "Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["双脚分开与肩同宽站立，一手握住哑铃，手臂完全伸展，手掌朝内。", "将另一只手放在大腿上以获得支撑。", "保持上臂静止，呼气，通过收缩二头肌将哑铃向肩膀弯曲。", "继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气，慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，一手握住啞鈴，手臂完全伸展，手掌朝內。", "將另一只手放在大腿上以獲得支撐。", "保持上臂靜止，呼氣，通過收縮二頭肌將啞鈴向肩膀彎曲。", "繼續舉起啞鈴，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣，慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0419', 'exercise', 1, '{"id": "0419", "target": "delts", "name_en": "dumbbell standing front raise above head", "name_zh": "哑铃站姿过顶前平举", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0419-laVRfDf.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴站姿過頂前平舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.", "Keep your arms straight and lift the dumbbells in front of you, raising them above your head.", "Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃，正握。", "保持双臂伸直，将哑铃举至身前，举过头顶。", "在最高点暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["trapezius", "biceps"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴，正握。", "保持雙臂伸直，將啞鈴舉至身前，舉過頭頂。", "在最高點暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2321', 'exercise', 1, '{"id": "2321", "target": "biceps", "name_en": "dumbbell standing inner biceps curl v. 2", "name_zh": "哑铃站姿内侧二头弯举变式2", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/2321-vKilzz3.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴站姿內側二頭彎舉變式2", "instructions_en": ["Stand up straight with a dumbbell in each hand, palms facing your torso.", "Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.", "While holding your upper arms stationary, curl the weights while contracting your biceps.", "Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Slowly begin to bring the dumbbells back to the starting position as your breathe in.", "Repeat for the recommended amount of repetitions."], "instructions_zh": ["站直，双手各持一个哑铃，手掌朝向躯干。", "保持肘部靠近躯干，并旋转手掌，直到手掌朝前。", "保持上臂不动，弯曲哑铃，同时收缩二头肌。", "继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气时慢慢开始将哑铃放回起始位置。", "重复建议的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙手各持一個啞鈴，手掌朝向軀幹。", "保持肘部靠近軀幹，并旋轉手掌，直到手掌朝前。", "保持上臂不動，彎曲啞鈴，同時收縮二頭肌。", "繼續舉重，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣時慢慢開始將啞鈴放回起始位置。", "重復建議的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0422', 'exercise', 1, '{"id": "0422", "target": "biceps", "name_en": "dumbbell standing one arm curl (over incline bench)", "name_zh": "哑铃站姿单臂弯举（上斜凳支撑）", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0422-BIb1tGo.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴站姿單臂彎舉（上斜凳支撐）", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing forward.", "Place your other hand on an incline bench for support.", "Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.", "Pause for a moment at the top, then inhale and slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["双脚分开与肩同宽站立，一手握住哑铃，手掌朝前。", "将另一只手放在倾斜的长凳上以获得支撑。", "保持上臂静止，呼气，通过收缩二头肌将哑铃向肩膀弯曲。", "在最高点停顿片刻，然后吸气，慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，一手握住啞鈴，手掌朝前。", "將另一只手放在傾斜的長凳上以獲得支撐。", "保持上臂靜止，呼氣，通過收縮二頭肌將啞鈴向肩膀彎曲。", "在最高點停頓片刻，然后吸氣，慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1680', 'exercise', 1, '{"id": "1680", "target": "biceps", "name_en": "dumbbell standing one arm curl over incline bench", "name_zh": "哑铃站姿单臂弯举上斜凳支撑", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1680-EmlJR2y.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴站姿單臂彎舉上斜凳支撐", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in one hand.", "Place your other hand on an incline bench for support.", "Keeping your upper arm stationary, curl the dumbbell towards your shoulder by contracting your biceps.", "Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["双脚分开与肩同宽站立，一只手握住哑铃。", "将另一只手放在倾斜的长凳上以获得支撑。", "保持上臂静止，通过收缩二头肌将哑铃向肩膀弯曲。", "在最高点暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，一只手握住啞鈴。", "將另一只手放在傾斜的長凳上以獲得支撐。", "保持上臂靜止，通過收縮二頭肌將啞鈴向肩膀彎曲。", "在最高點暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0423', 'exercise', 1, '{"id": "0423", "target": "triceps", "name_en": "dumbbell standing one arm extension", "name_zh": "哑铃站姿单臂臂屈伸", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0423-BCUR88E.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴站姿單臂臂屈伸", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in one hand.", "Raise the dumbbell overhead, fully extending your arm.", "Keep your upper arm close to your head and perpendicular to the ground.", "Slowly lower the dumbbell behind your head, bending your elbow.", "Pause for a moment, then raise the dumbbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，一只手握住哑铃。", "将哑铃举过头顶，充分伸展手臂。", "保持上臂靠近头部并垂直于地面。", "慢慢地将哑铃放到脑后，弯曲肘部。", "暂停片刻，然后将哑铃举回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，一只手握住啞鈴。", "將啞鈴舉過頭頂，充分伸展手臂。", "保持上臂靠近頭部并垂直于地面。", "慢慢地將啞鈴放到腦后，彎曲肘部。", "暫停片刻，然后將啞鈴舉回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0424', 'exercise', 1, '{"id": "0424", "target": "delts", "name_en": "dumbbell standing one arm palm in press", "name_zh": "哑铃站姿单臂掌心向内推举", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0424-ocYc6Db.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴站姿單臂掌心向內推舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in one hand at shoulder height with your palm facing inwards.", "Engage your core and keep your back straight.", "Press the dumbbell upwards until your arm is fully extended.", "Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."], "instructions_zh": ["双脚分开与肩同宽站立，一只手握住哑铃，与肩同高，手掌朝内。", "启动你的核心并保持背部挺直。", "向上推哑铃，直到手臂完全伸展。", "在最高点暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换到另一只手臂。"], "secondary_muscles": ["triceps", "core"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，一只手握住啞鈴，與肩同高，手掌朝內。", "啟動你的核心并保持背部挺直。", "向上推啞鈴，直到手臂完全伸展。", "在最高點暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換到另一只手臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3313', 'exercise', 1, '{"id": "3313", "target": "pectorals", "name_en": "weighted straight bar dip", "name_zh": "负重伸直杆臂屈伸", "body_part": "chest", "equipment": "weighted", "gif_asset": "assets/fitness/videos/3313-Ff18ItA.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重伸直桿臂屈伸", "instructions_en": ["Position yourself between parallel bars with your arms fully extended and your body straight.", "Lower your body by bending your elbows until your upper arms are parallel to the ground.", "Pause for a moment, then push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将自己置于双杠之间，双臂完全伸展，身体伸直。", "弯曲肘部降低身体，直到上臂与地面平行。", "暂停片刻，然后伸直手臂，将自己推回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["將自己置于雙杠之間，雙臂完全伸展，身體伸直。", "彎曲肘部降低身體，直到上臂與地面平行。", "暫停片刻，然后伸直手臂，將自己推回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0425', 'exercise', 1, '{"id": "0425", "target": "biceps", "name_en": "dumbbell standing one arm reverse curl", "name_zh": "哑铃站姿单臂反向弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0425-DU5Kkj2.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴站姿單臂反向彎舉", "instructions_en": ["Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand with an overhand grip.", "Keep your arm fully extended and close to your body, with your palm facing down.", "Slowly curl the dumbbell up towards your shoulder, keeping your upper arm stationary.", "Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."], "instructions_zh": ["站直，双脚分开与肩同宽，一只手握住哑铃，正握。", "保持手臂完全伸展并靠近身体，手掌朝下。", "慢慢地将哑铃向上弯向肩膀，保持上臂静止。", "在顶部停顿片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换到另一只手臂。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙腳分開與肩同寬，一只手握住啞鈴，正握。", "保持手臂完全伸展并靠近身體，手掌朝下。", "慢慢地將啞鈴向上彎向肩膀，保持上臂靜止。", "在頂部停頓片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換到另一只手臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0436', 'exercise', 1, '{"id": "0436", "target": "triceps", "name_en": "dumbbell tate press", "name_zh": "哑铃泰特推举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0436-s5PdDyY.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴泰特推舉", "instructions_en": ["Sit on a flat bench with a dumbbell in each hand, palms facing each other.", "Raise the dumbbells to shoulder height, then rotate your wrists so that your palms are facing away from you.", "Press the dumbbells up until your arms are fully extended, then lower them back down to shoulder height.", "Rotate your wrists back to the starting position and repeat for the desired number of repetitions."], "instructions_zh": ["坐在平坦的长凳上，双手各握一个哑铃，手掌相对。", "将哑铃举至肩膀高度，然后旋转手腕，使手掌背向自己。", "向上推哑铃，直到手臂完全伸展，然后将其放回至肩膀高度。", "将手腕旋转回起始位置，然后重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["坐在平坦的長凳上，雙手各握一個啞鈴，手掌相對。", "將啞鈴舉至肩膀高度，然后旋轉手腕，使手掌背向自己。", "向上推啞鈴，直到手臂完全伸展，然后將其放回至肩膀高度。", "將手腕旋轉回起始位置，然后重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0426', 'exercise', 1, '{"id": "0426", "target": "delts", "name_en": "dumbbell standing overhead press", "name_zh": "哑铃站姿过顶推举", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0426-A6wtbuL.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴站姿過頂推舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing forward.", "Press the dumbbells upward until your arms are fully extended overhead.", "Pause for a moment at the top, then slowly lower the dumbbells back down to shoulder level.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高，手掌朝前。", "向上推哑铃，直到手臂完全伸过头顶。", "在顶部停顿片刻，然后慢慢将哑铃放回至肩部水平。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "upper back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴，與肩同高，手掌朝前。", "向上推啞鈴，直到手臂完全伸過頭頂。", "在頂部停頓片刻，然后慢慢將啞鈴放回至肩部水平。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0427', 'exercise', 1, '{"id": "0427", "target": "delts", "name_en": "dumbbell standing palms in press", "name_zh": "哑铃站姿掌心向内推举", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0427-UilDHSs.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴站姿掌心向內推舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing inwards.", "Keeping your core engaged and your back straight, press the dumbbells upwards until your arms are fully extended overhead.", "Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高，手掌朝内。", "保持核心收紧，背部挺直，向上推哑铃，直到手臂完全伸过头顶。", "在最高点暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "chest"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴，與肩同高，手掌朝內。", "保持核心收緊，背部挺直，向上推啞鈴，直到手臂完全伸過頭頂。", "在最高點暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0428', 'exercise', 1, '{"id": "0428", "target": "biceps", "name_en": "dumbbell standing preacher curl", "name_zh": "哑铃站姿牧师凳弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0428-hq2hyDH.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴站姿牧師凳彎舉", "instructions_en": ["Stand upright with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.", "Rest the back of your upper arms against the preacher bench or an incline bench, with your elbows slightly bent.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站直，双脚分开与肩同宽，每只手各握一个哑铃，手掌朝前。", "将上臂后部靠在牧师凳或上斜凳上，肘部稍微弯曲。", "保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。", "继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙腳分開與肩同寬，每只手各握一個啞鈴，手掌朝前。", "將上臂后部靠在牧師凳或上斜凳上，肘部稍微彎曲。", "保持上臂靜止，呼氣并彎舉啞鈴，同時收縮二頭肌。", "繼續舉起啞鈴，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0429', 'exercise', 1, '{"id": "0429", "target": "biceps", "name_en": "dumbbell standing reverse curl", "name_zh": "哑铃站姿反向弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0429-0IgNjSM.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴站姿反向彎舉", "instructions_en": ["Stand up straight with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站直，双脚分开与肩同宽，双手各握一个哑铃，手掌朝向身体。", "保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙腳分開與肩同寬，雙手各握一個啞鈴，手掌朝向身體。", "保持上臂靜止，呼氣并彎舉啞鈴，同時收縮二頭肌。繼續舉重，直到二頭肌完全收縮并且啞鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0430', 'exercise', 1, '{"id": "0430", "target": "triceps", "name_en": "dumbbell standing triceps extension", "name_zh": "哑铃站姿臂屈伸", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0430-PdmaD0N.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴站姿臂屈伸", "instructions_en": ["Stand with your feet shoulder-width apart and hold a dumbbell in one hand.", "Raise the dumbbell overhead, keeping your arm straight.", "Bend your elbow and lower the dumbbell behind your head, keeping your upper arm stationary.", "Extend your arm back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，一只手握住哑铃。", "将哑铃举过头顶，保持手臂伸直。", "弯曲肘部，将哑铃放到脑后，保持上臂静止。", "将手臂向后伸展至起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，一只手握住啞鈴。", "將啞鈴舉過頭頂，保持手臂伸直。", "彎曲肘部，將啞鈴放到腦后，保持上臂靜止。", "將手臂向后伸展至起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2293', 'exercise', 1, '{"id": "2293", "target": "biceps", "name_en": "dumbbell standing zottman preacher curl", "name_zh": "哑铃站姿佐特曼牧师凳弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/2293-P2nRiUa.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴站姿佐特曼牧師凳彎舉", "instructions_en": ["Stand up straight with a dumbbell in each hand, palms facing forward.", "Place your upper arms against the preacher bench and keep your elbows slightly bent.", "Curl the dumbbells up towards your shoulders while keeping your upper arms stationary.", "At the top of the movement, rotate your wrists so that your palms are facing downward.", "Slowly lower the dumbbells back to the starting position, rotating your wrists back to the starting position as well.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站直，双手各持一个哑铃，手掌朝前。", "将上臂靠在牧师凳上，并保持肘部稍微弯曲。", "将哑铃向上弯向肩膀，同时保持上臂静止。", "在动作的最高点，旋转手腕，使手掌朝下。", "慢慢地将哑铃放回起始位置，同时将手腕旋转回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙手各持一個啞鈴，手掌朝前。", "將上臂靠在牧師凳上，并保持肘部稍微彎曲。", "將啞鈴向上彎向肩膀，同時保持上臂靜止。", "在動作的最高點，旋轉手腕，使手掌朝下。", "慢慢地將啞鈴放回起始位置，同時將手腕旋轉回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1684', 'exercise', 1, '{"id": "1684", "target": "biceps", "name_en": "dumbbell step up single leg balance with bicep curl", "name_zh": "哑铃踏台单腿平衡接弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1684-76vfTdU.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴踏臺單腿平衡接彎舉", "instructions_en": ["Stand in front of a step or platform with a dumbbell in each hand, palms facing your body.", "Place your right foot on the step, ensuring your entire foot is in contact with the surface.", "Engage your core and push through your right heel to lift your body up onto the step, bringing your left knee up towards your chest.", "At the top of the movement, perform a bicep curl by bending your elbows and bringing the dumbbells towards your shoulders.", "Lower the dumbbells back down and simultaneously lower your left foot back to the ground.", "Repeat the movement on the opposite side, stepping up with your left foot and curling the dumbbells.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["站在台阶或平台前，每只手各握一个哑铃，手掌朝向身体。", "将右脚放在台阶上，确保整个脚与表面接触。", "启动核心并推动右脚跟，将身体抬起到台阶上，将左膝抬向胸部。", "在动作的最高点，弯曲肘部并将哑铃拉向肩膀，进行二头肌弯举。", "将哑铃放回原处，同时将左脚放回地面。", "在另一侧重复该动作，左脚向上并弯举哑铃。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["quadriceps", "glutes", "hamstrings"], "instructions_zh_hant": ["站在臺階或平臺前，每只手各握一個啞鈴，手掌朝向身體。", "將右腳放在臺階上，確保整個腳與表面接觸。", "啟動核心并推動右腳跟，將身體抬起到臺階上，將左膝抬向胸部。", "在動作的最高點，彎曲肘部并將啞鈴拉向肩膀，進行二頭肌彎舉。", "將啞鈴放回原處，同時將左腳放回地面。", "在另一側重復該動作，左腳向上并彎舉啞鈴。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0858', 'exercise', 1, '{"id": "0858", "target": "abs", "name_en": "wind sprints", "name_zh": "间歇冲刺跑", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0858-Qoujh3Q.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "間歇沖刺跑", "instructions_en": ["Find an open space or a track to perform the exercise.", "Start by standing with your feet shoulder-width apart.", "Begin running as fast as you can, pumping your arms and driving your knees up.", "Continue sprinting for a specific distance or time period.", "Rest and repeat for the desired number of repetitions."], "instructions_zh": ["找一个空地或跑道来进行练习。", "首先站立，双脚分开与肩同宽。", "开始尽可能快地跑步，挥动手臂并抬起膝盖。", "继续冲刺特定的距离或时间。", "休息并重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["找一個空地或跑道來進行練習。", "首先站立，雙腳分開與肩同寬。", "開始盡可能快地跑步，揮動手臂并抬起膝蓋。", "繼續沖刺特定的距離或時間。", "休息并重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0431', 'exercise', 1, '{"id": "0431", "target": "glutes", "name_en": "dumbbell step-up", "name_zh": "哑铃踏台上步", "body_part": "upper legs", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0431-aXtJhlg.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴踏臺上步", "instructions_en": ["Stand in front of a bench or step with a dumbbell in each hand, palms facing your body.", "Place your right foot on the bench or step, ensuring your entire foot is in contact with the surface.", "Push through your right heel and lift your body up onto the bench or step, straightening your right leg.", "Bring your left foot up onto the bench or step, standing fully upright.", "Step back down with your left foot, followed by your right foot, returning to the starting position.", "Repeat for the desired number of repetitions, then switch legs."], "instructions_zh": ["站在长凳或台阶前，每只手各握一个哑铃，手掌朝向身体。", "将右脚放在长凳或台阶上，确保整个脚与表面接触。", "推动右脚跟，将身体抬起到长凳或台阶上，伸直右腿。", "将左脚放在长凳或台阶上，完全直立。", "左脚向后退一步，然后是右脚，回到起始位置。", "重复所需的重复次数，然后换腿。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["站在長凳或臺階前，每只手各握一個啞鈴，手掌朝向身體。", "將右腳放在長凳或臺階上，確保整個腳與表面接觸。", "推動右腳跟，將身體抬起到長凳或臺階上，伸直右腿。", "將左腳放在長凳或臺階上，完全直立。", "左腳向后退一步，然后是右腳，回到起始位置。", "重復所需的重復次數，然后換腿。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2796', 'exercise', 1, '{"id": "2796", "target": "quads", "name_en": "dumbbell step-up lunge", "name_zh": "哑铃踏台上步弓步", "body_part": "upper legs", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/2796-gFyFj9z.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴踏臺上步弓步", "instructions_en": ["Stand in front of a step or platform with a dumbbell in each hand, palms facing your sides.", "Place your right foot on the step, ensuring your entire foot is on the surface.", "Push through your right heel and lift your body up onto the step, bringing your left foot up as well.", "Once both feet are on the step, lower your left foot back down to the starting position, keeping your right foot on the step.", "Repeat the movement, alternating which foot you step up with each time.", "Continue for the desired number of repetitions."], "instructions_zh": ["站在台阶或平台前，每只手各持一个哑铃，手掌朝向身体两侧。", "将右脚放在台阶上，确保整个脚都踩在台阶上。", "推动右脚跟，将身体抬起到台阶上，同时将左脚抬起。", "双脚踩在台阶上后，将左脚放回起始位置，并将右脚保持在台阶上。", "重复该动作，每次交替使用哪只脚。", "继续进行所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings", "calves"], "instructions_zh_hant": ["站在臺階或平臺前，每只手各持一個啞鈴，手掌朝向身體兩側。", "將右腳放在臺階上，確保整個腳都踩在臺階上。", "推動右腳跟，將身體抬起到臺階上，同時將左腳抬起。", "雙腳踩在臺階上后，將左腳放回起始位置，并將右腳保持在臺階上。", "重復該動作，每次交替使用哪只腳。", "繼續進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2812', 'exercise', 1, '{"id": "2812", "target": "quads", "name_en": "dumbbell step-up split squat", "name_zh": "哑铃踏台上步分腿蹲", "body_part": "upper legs", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/2812-QjE2DcA.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴踏臺上步分腿蹲", "instructions_en": ["Stand in front of a bench or step with a dumbbell in each hand, palms facing your body.", "Place your right foot on the bench or step, ensuring your entire foot is in contact with the surface.", "Step up onto the bench or step with your right foot, pushing through your heel to lift your body up.", "As you step up, simultaneously lift your left knee towards your chest.", "Pause at the top of the movement, then slowly lower your left foot back to the ground while keeping your right foot on the bench or step.", "Repeat the movement with your left foot on the bench or step.", "Continue alternating between your right and left foot for the desired number of repetitions."], "instructions_zh": ["站在长凳或台阶前，每只手各握一个哑铃，手掌朝向身体。", "将右脚放在长凳或台阶上，确保整个脚与表面接触。", "走到长凳上或用右脚踩上，用脚跟推动身体抬起。", "当你向上迈步时，同时将左膝抬向胸部。", "在动作的最高点暂停，然后慢慢将左脚放回地面，同时将右脚放在长凳或台阶上。", "将左脚放在长凳或台阶上，重复该动作。", "继续交替左右脚，达到所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings", "calves"], "instructions_zh_hant": ["站在長凳或臺階前，每只手各握一個啞鈴，手掌朝向身體。", "將右腳放在長凳或臺階上，確保整個腳與表面接觸。", "走到長凳上或用右腳踩上，用腳跟推動身體抬起。", "當你向上邁步時，同時將左膝抬向胸部。", "在動作的最高點暫停，然后慢慢將左腳放回地面，同時將右腳放在長凳或臺階上。", "將左腳放在長凳或臺階上，重復該動作。", "繼續交替左右腳，達到所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0432', 'exercise', 1, '{"id": "0432", "target": "glutes", "name_en": "dumbbell stiff leg deadlift", "name_zh": "哑铃直腿硬拉", "body_part": "upper legs", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0432-5eLRITT.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴直腿硬拉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.", "Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing a slight bend in your knees.", "Lower the dumbbells until you feel a stretch in your hamstrings, then squeeze your glutes and push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃，正握。", "保持背部挺直，核心收紧，铰接臀部并将哑铃向地面降低，让膝盖稍微弯曲。", "降低哑铃，直到感觉到腿筋拉伸，然后挤压臀肌并通过脚后跟推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "lower back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴，正握。", "保持背部挺直，核心收緊，鉸接臀部并將啞鈴向地面降低，讓膝蓋稍微彎曲。", "降低啞鈴，直到感覺到腿筋拉伸，然后擠壓臀肌并通過腳后跟推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0433', 'exercise', 1, '{"id": "0433", "target": "pectorals", "name_en": "dumbbell straight arm pullover", "name_zh": "哑铃直臂仰卧上拉", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0433-i8BdLTK.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴直臂仰臥上拉", "instructions_en": ["Lie flat on a bench with your head at one end and your feet planted firmly on the ground.", "Hold a dumbbell with both hands and extend your arms straight above your chest.", "Keeping your arms straight, slowly lower the dumbbell behind your head in an arc-like motion.", "Pause for a moment, then raise the dumbbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，头朝一端，双脚牢牢踩在地上。", "双手握住哑铃，将手臂伸直至胸部上方。", "保持手臂伸直，以弧线动作慢慢将哑铃降低到脑后。", "暂停片刻，然后将哑铃举回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["latissimus dorsi", "triceps"], "instructions_zh_hant": ["平躺在長凳上，頭朝一端，雙腳牢牢踩在地上。", "雙手握住啞鈴，將手臂伸直至胸部上方。", "保持手臂伸直，以弧線動作慢慢將啞鈴降低到腦后。", "暫停片刻，然后將啞鈴舉回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0434', 'exercise', 1, '{"id": "0434", "target": "glutes", "name_en": "dumbbell straight leg deadlift", "name_zh": "哑铃直腿硬拉", "body_part": "upper legs", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0434-oom75KC.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴直腿硬拉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.", "Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing your torso to lean forward.", "Continue lowering the dumbbells until you feel a stretch in your hamstrings, keeping your knees slightly bent.", "Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your torso back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃，正握。", "保持背部挺直，核心收紧，以臀部为铰链，将哑铃向地面降低，让躯干向前倾斜。", "继续降低哑铃，直到感觉到腿筋拉伸，保持膝盖稍微弯曲。", "在底部暂停片刻，然后启动臀肌和腿筋，将躯干抬回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "lower back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴，正握。", "保持背部挺直，核心收緊，以臀部為鉸鏈，將啞鈴向地面降低，讓軀幹向前傾斜。", "繼續降低啞鈴，直到感覺到腿筋拉伸，保持膝蓋稍微彎曲。", "在底部暫停片刻，然后啟動臀肌和腿筋，將軀幹抬回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2808', 'exercise', 1, '{"id": "2808", "target": "glutes", "name_en": "dumbbell sumo pull through", "name_zh": "哑铃相扑式胯下拉", "body_part": "upper legs", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/2808-BmrwWzo.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴相撲式胯下拉", "instructions_en": ["Stand with your feet wider than shoulder-width apart, toes pointed outwards.", "Hold a dumbbell with both hands in front of your body, arms extended.", "Bend your knees and lower your hips down into a squat position, keeping your back straight.", "Lower the dumbbell down between your legs, keeping your arms straight.", "Drive through your heels and extend your hips forward, pulling the dumbbell up and in front of your body.", "Squeeze your glutes at the top of the movement, then lower the dumbbell back down between your legs.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站立，双脚分开比肩宽，脚趾朝外。", "双手握住哑铃置于身体前方，双臂伸展。", "弯曲膝盖，将臀部放低至下蹲位置，保持背部挺直。", "将哑铃放在两腿之间，保持手臂伸直。", "通过脚后跟发力，向前伸展臀部，将哑铃向上拉至身体前方。", "在动作的最高点挤压臀部，然后将哑铃放回双腿之间。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "quadriceps", "core"], "instructions_zh_hant": ["站立，雙腳分開比肩寬，腳趾朝外。", "雙手握住啞鈴置于身體前方，雙臂伸展。", "彎曲膝蓋，將臀部放低至下蹲位置，保持背部挺直。", "將啞鈴放在兩腿之間，保持手臂伸直。", "通過腳后跟發力，向前伸展臀部，將啞鈴向上拉至身體前方。", "在動作的最高點擠壓臀部，然后將啞鈴放回雙腿之間。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2803', 'exercise', 1, '{"id": "2803", "target": "quads", "name_en": "dumbbell supported squat", "name_zh": "哑铃支撑深蹲", "body_part": "upper legs", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/2803-r5DgrW9.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴支撐深蹲", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.", "Keeping your chest up and core engaged, slowly lower your body down by bending your knees and pushing your hips back.", "Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.", "Pause for a moment at the bottom, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃放在身体两侧。", "保持挺胸，核心收紧，弯曲膝盖并向后推臀部，慢慢降低身体。", "继续降低，直到大腿与地面平行，或者尽可能低。", "在底部停顿片刻，然后推动脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴放在身體兩側。", "保持挺胸，核心收緊，彎曲膝蓋并向后推臀部，慢慢降低身體。", "繼續降低，直到大腿與地面平行，或者盡可能低。", "在底部停頓片刻，然后推動腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1742', 'exercise', 1, '{"id": "1742", "target": "triceps", "name_en": "dumbbell tricep kickback with stork stance", "name_zh": "哑铃单腿站姿臂后屈伸", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1742-wOLmCXc.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴單腿站姿臂后屈伸", "instructions_en": ["Stand with your feet shoulder-width apart and hold a dumbbell in your right hand.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Bring your right elbow up to your side, keeping it bent at a 90-degree angle.", "Extend your right arm straight back, squeezing your triceps.", "Pause for a moment, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["双脚分开与肩同宽站立，右手握住哑铃。", "稍微弯曲膝盖，髋部向前转动，保持背部挺直。", "将右肘举至身体一侧，保持弯曲 90 度角。", "将右臂向后伸直，挤压三头肌。", "暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，右手握住啞鈴。", "稍微彎曲膝蓋，髖部向前轉動，保持背部挺直。", "將右肘舉至身體一側，保持彎曲 90 度角。", "將右臂向后伸直，擠壓三頭肌。", "暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1743', 'exercise', 1, '{"id": "1743", "target": "triceps", "name_en": "dumbbell twisting bench press", "name_zh": "哑铃转体卧推", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1743-z6TAHoT.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴轉體臥推", "instructions_en": ["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.", "Hold a dumbbell in each hand with an overhand grip, palms facing away from you.", "Extend your arms straight up over your chest, keeping a slight bend in your elbows.", "Lower the dumbbells down towards your chest, keeping your elbows close to your body.", "As you lower the dumbbells, twist your wrists so that your palms face towards you at the bottom of the movement.", "Pause for a moment at the bottom, then reverse the movement by pressing the dumbbells back up to the starting position.", "As you press the dumbbells up, twist your wrists back to the starting position with palms facing away from you.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，双脚平放在地上，背部紧贴长凳。", "双手各握一个哑铃，正手握握，手掌背向自己。", "将手臂伸直越过胸部，保持肘部轻微弯曲。", "将哑铃向胸部方向降低，保持肘部靠近身体。", "放下哑铃时，扭转手腕，使手掌在动作底部面向自己。", "在底部暂停片刻，然后通过将哑铃推回到起始位置来反转动作。", "当你向上推哑铃时，将手腕扭转回起始位置，手掌背向自己。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["平躺在長凳上，雙腳平放在地上，背部緊貼長凳。", "雙手各握一個啞鈴，正手握握，手掌背向自己。", "將手臂伸直越過胸部，保持肘部輕微彎曲。", "將啞鈴向胸部方向降低，保持肘部靠近身體。", "放下啞鈴時，扭轉手腕，使手掌在動作底部面向自己。", "在底部暫停片刻，然后通過將啞鈴推回到起始位置來反轉動作。", "當你向上推啞鈴時，將手腕扭轉回起始位置，手掌背向自己。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0437', 'exercise', 1, '{"id": "0437", "target": "delts", "name_en": "dumbbell upright row", "name_zh": "哑铃直立划船", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0437-ainizkb.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴直立劃船", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.", "Let the dumbbells hang in front of your thighs, with your arms fully extended.", "Keeping your back straight and your core engaged, exhale and lift the dumbbells straight up towards your chin, leading with your elbows.", "Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃，正握。", "让哑铃悬挂在大腿前面，双臂完全伸展。", "保持背部挺直，核心收紧，呼气，将哑铃笔直向上举至下巴，用肘部引导。", "在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["traps", "biceps"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴，正握。", "讓啞鈴懸掛在大腿前面，雙臂完全伸展。", "保持背部挺直，核心收緊，呼氣，將啞鈴筆直向上舉至下巴，用肘部引導。", "在頂部停頓片刻，然后吸氣，慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1765', 'exercise', 1, '{"id": "1765", "target": "delts", "name_en": "dumbbell upright row (back pov)", "name_zh": "哑铃直立划船（背面视角）", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1765-Iptlv6x.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴直立劃船（背面視角）", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.", "Let the dumbbells hang in front of your thighs, with your arms fully extended and your palms facing your body.", "Keeping your back straight and your core engaged, exhale and lift the dumbbells straight up towards your chin, leading with your elbows.", "Continue lifting until the dumbbells are at shoulder height, with your elbows pointing out to the sides.", "Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃，正握。", "让哑铃悬挂在大腿前面，双臂完全伸展，手掌面向身体。", "保持背部挺直，核心收紧，呼气，将哑铃笔直向上举至下巴，用肘部引导。", "继续举起哑铃，直到哑铃与肩同高，肘部指向两侧。", "在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["traps", "biceps"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴，正握。", "讓啞鈴懸掛在大腿前面，雙臂完全伸展，手掌面向身體。", "保持背部挺直，核心收緊，呼氣，將啞鈴筆直向上舉至下巴，用肘部引導。", "繼續舉起啞鈴，直到啞鈴與肩同高，肘部指向兩側。", "在頂部停頓片刻，然后吸氣，慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2189', 'exercise', 1, '{"id": "2189", "target": "triceps", "name_en": "dumbbells seated triceps extension", "name_zh": "哑铃坐姿臂屈伸", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/2189-FQXdXzY.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴坐姿臂屈伸", "instructions_en": ["Sit on a bench with your back straight and feet flat on the ground.", "Hold a dumbbell in both hands with an overhand grip, and raise it above your head.", "Bend your elbows and lower the dumbbell behind your head, keeping your upper arms close to your ears.", "Extend your arms and raise the dumbbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，背部挺直，双脚平放在地上。", "双手握住哑铃，正握，将其举过头顶。", "弯曲肘部，将哑铃放在脑后，保持上臂靠近耳朵。", "伸展双臂，将哑铃举回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["坐在長凳上，背部挺直，雙腳平放在地上。", "雙手握住啞鈴，正握，將其舉過頭頂。", "彎曲肘部，將啞鈴放在腦后，保持上臂靠近耳朵。", "伸展雙臂，將啞鈴舉回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0864', 'exercise', 1, '{"id": "0864", "target": "delts", "name_en": "dumbbell upright shoulder external rotation", "name_zh": "哑铃直立肩部外旋", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0864-x306lCW.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴直立肩部外旋", "instructions_en": ["Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your body.", "Raise your arms out to the sides until they are parallel to the ground, keeping your elbows slightly bent.", "Rotate your arms externally, bringing the dumbbells up towards your head while keeping your elbows in the same position.", "Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。", "将手臂向两侧抬起，直到与地面平行，保持肘部稍微弯曲。", "向外旋转手臂，将哑铃举向头部，同时保持肘部处于同一位置。", "在最高点暂停片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["rotator cuff", "trapezius"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴，手掌朝向身體。", "將手臂向兩側抬起，直到與地面平行，保持肘部稍微彎曲。", "向外旋轉手臂，將啞鈴舉向頭部，同時保持肘部處于同一位置。", "在最高點暫停片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('5201', 'exercise', 1, '{"id": "5201", "target": "biceps", "name_en": "dumbbell waiter biceps curl", "name_zh": "哑铃侍者式二头弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/5201-KOpzGBL.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴侍者式二頭彎舉", "instructions_en": ["Stand up straight with a dumbbell in each hand, palms facing forward.", "Keep your upper arms close to your body and your elbows tucked in.", "Slowly curl the dumbbells up towards your shoulders, keeping your wrists straight.", "Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站直，双手各持一个哑铃，手掌朝前。", "保持上臂靠近身体，肘部内收。", "慢慢地将哑铃向上弯向肩膀，保持手腕伸直。", "在顶部停顿片刻，然后慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms", "shoulders"], "instructions_zh_hant": ["站直，雙手各持一個啞鈴，手掌朝前。", "保持上臂靠近身體，肘部內收。", "慢慢地將啞鈴向上彎向肩膀，保持手腕伸直。", "在頂部停頓片刻，然后慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0438', 'exercise', 1, '{"id": "0438", "target": "delts", "name_en": "dumbbell w-press", "name_zh": "哑铃W形推举", "body_part": "shoulders", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0438-vmwLyCg.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴W形推舉", "instructions_en": ["Sit on a bench with a dumbbell in each hand, palms facing forward.", "Raise the dumbbells to shoulder height, elbows bent and palms facing forward.", "Press the dumbbells upward until your arms are fully extended overhead.", "Lower the dumbbells back to shoulder height.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双手各握一个哑铃，手掌朝前。", "将哑铃举至肩高，肘部弯曲，手掌朝前。", "向上推哑铃，直到手臂完全伸过头顶。", "将哑铃放低至肩部高度。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "chest"], "instructions_zh_hant": ["坐在長凳上，雙手各握一個啞鈴，手掌朝前。", "將啞鈴舉至肩高，肘部彎曲，手掌朝前。", "向上推啞鈴，直到手臂完全伸過頭頂。", "將啞鈴放低至肩部高度。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0439', 'exercise', 1, '{"id": "0439", "target": "biceps", "name_en": "dumbbell zottman curl", "name_zh": "哑铃佐特曼弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0439-kXaIn5A.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴佐特曼彎舉", "instructions_en": ["Stand up straight with a dumbbell in each hand, palms facing your body.", "Keep your elbows close to your torso and rotate your palms to face forward.", "Curl the dumbbells up to your shoulders while keeping your upper arms stationary.", "At the top of the movement, rotate your wrists so that your palms are facing away from your body.", "Slowly lower the dumbbells back to the starting position, rotating your palms back to facing your body.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站直，双手各持一个哑铃，手掌朝向身体。", "保持肘部靠近躯干，并旋转手掌以面向前方。", "将哑铃举至肩膀处，同时保持上臂静止。", "在动作的最高点，旋转手腕，使手掌背向身体。", "慢慢地将哑铃放回起始位置，将手掌旋转回面向身体。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙手各持一個啞鈴，手掌朝向身體。", "保持肘部靠近軀幹，并旋轉手掌以面向前方。", "將啞鈴舉至肩膀處，同時保持上臂靜止。", "在動作的最高點，旋轉手腕，使手掌背向身體。", "慢慢地將啞鈴放回起始位置，將手掌旋轉回面向身體。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2294', 'exercise', 1, '{"id": "2294", "target": "biceps", "name_en": "dumbbell zottman preacher curl", "name_zh": "哑铃佐特曼牧师凳弯举", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/2294-y5U5B9Y.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴佐特曼牧師凳彎舉", "instructions_en": ["Sit on a preacher bench with a dumbbell in each hand, palms facing up and elbows resting on the pad.", "Curl the dumbbells up towards your shoulders, keeping your upper arms stationary and your palms facing up.", "At the top of the curl, rotate your wrists so that your palms are facing down.", "Slowly lower the dumbbells back down to the starting position, rotating your wrists back to the starting position as you do so.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在牧师凳上，双手各持一个哑铃，手掌朝上，肘部放在垫子上。", "将哑铃向上弯向肩膀，保持上臂静止，手掌朝上。", "在弯举的顶部，旋转手腕，使手掌朝下。", "慢慢地将哑铃放回起始位置，同时将手腕旋转回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在牧師凳上，雙手各持一個啞鈴，手掌朝上，肘部放在墊子上。", "將啞鈴向上彎向肩膀，保持上臂靜止，手掌朝上。", "在彎舉的頂部，旋轉手腕，使手掌朝下。", "慢慢地將啞鈴放回起始位置，同時將手腕旋轉回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3287', 'exercise', 1, '{"id": "3287", "target": "triceps", "name_en": "elbow dips", "name_zh": "肘部臂屈伸", "body_part": "upper arms", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3287-LkoAWAE.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "肘部臂屈伸", "instructions_en": ["Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.", "Slide your hips forward off the bench and straighten your legs, keeping your heels on the ground.", "Bend your elbows and lower your body towards the ground, keeping your back close to the bench.", "Pause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳或椅子的边缘，双手抓住臀部旁边的边缘。", "将臀部向前滑离长凳，伸直双腿，保持脚后跟着地。", "弯曲肘部，将身体放低至地面，保持背部靠近长凳。", "在底部停顿片刻，然后双手用力伸直手臂，将身体抬回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["坐在長凳或椅子的邊緣，雙手抓住臀部旁邊的邊緣。", "將臀部向前滑離長凳，伸直雙腿，保持腳后跟著地。", "彎曲肘部，將身體放低至地面，保持背部靠近長凳。", "在底部停頓片刻，然后雙手用力伸直手臂，將身體抬回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1772', 'exercise', 1, '{"id": "1772", "target": "upper back", "name_en": "elbow lift - reverse push-up", "name_zh": "肘部抬举-反向俯卧撑", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1772-wbUYILZ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "肘部抬舉-反向俯臥撐", "instructions_en": ["Start by lying face down on the ground with your legs extended and your hands placed directly under your shoulders.", "Engage your core and press through your palms to lift your upper body off the ground, keeping your elbows close to your sides.", "Pause at the top for a moment, squeezing your upper back muscles.", "Slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先，脸朝下躺在地上，双腿伸展，双手直接放在肩膀下方。", "收紧核心并用手掌按压，将上半身抬离地面，保持肘部靠近身体两侧。", "在顶部暂停片刻，挤压上背部肌肉。", "慢慢地将身体放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["首先，臉朝下躺在地上，雙腿伸展，雙手直接放在肩膀下方。", "收緊核心并用手掌按壓，將上半身抬離地面，保持肘部靠近身體兩側。", "在頂部暫停片刻，擠壓上背部肌肉。", "慢慢地將身體放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0443', 'exercise', 1, '{"id": "0443", "target": "abs", "name_en": "elbow-to-knee", "name_zh": "肘触膝", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0443-jvp6DiD.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "肘觸膝", "instructions_en": ["Start by lying flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engage your abs and lift your upper body off the ground, bringing your right elbow towards your left knee.", "At the same time, bring your left knee towards your right elbow, creating a twisting motion.", "Pause for a moment at the top, then slowly lower your upper body and extend your legs back to the starting position.", "Repeat the movement, this time bringing your left elbow towards your right knee and your right knee towards your left elbow.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["首先平躺，膝盖弯曲，双脚平放在地上。", "将双手放在脑后，肘部朝外。", "收紧腹肌，将上半身抬离地面，将右肘靠近左膝盖。", "同时，将左膝移向右肘，形成扭转动作。", "在顶部停顿片刻，然后慢慢降低上半身并将双腿伸展回到起始位置。", "重复该动作，这次将左肘移向右膝，将右膝移向左肘。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["obliques"], "instructions_zh_hant": ["首先平躺，膝蓋彎曲，雙腳平放在地上。", "將雙手放在腦后，肘部朝外。", "收緊腹肌，將上半身抬離地面，將右肘靠近左膝蓋。", "同時，將左膝移向右肘，形成扭轉動作。", "在頂部停頓片刻，然后慢慢降低上半身并將雙腿伸展回到起始位置。", "重復該動作，這次將左肘移向右膝，將右膝移向左肘。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3292', 'exercise', 1, '{"id": "3292", "target": "upper back", "name_en": "elevator", "name_zh": "升降蹲", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3292-zYmNaoY.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "升降蹲", "instructions_en": ["Stand with your feet shoulder-width apart and your knees slightly bent.", "Place your hands on your hips or cross them in front of your chest.", "Keeping your back straight, slowly bend forward at the waist, lowering your upper body towards the ground.", "Pause for a moment at the bottom, then slowly raise your upper body back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，膝盖稍微弯曲。", "将双手放在臀部或交叉放在胸前。", "保持背部挺直，腰部慢慢向前弯曲，将上半身向地面降低。", "在底部停顿片刻，然后慢慢抬起上半身回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "trapezius"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，膝蓋稍微彎曲。", "將雙手放在臀部或交叉放在胸前。", "保持背部挺直，腰部慢慢向前彎曲，將上半身向地面降低。", "在底部停頓片刻，然后慢慢抬起上半身回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1336', 'exercise', 1, '{"id": "1336", "target": "spine", "name_en": "exercise ball back extension with rotation", "name_zh": "健身球背伸展配合旋转", "body_part": "back", "equipment": "stability ball", "gif_asset": "assets/fitness/videos/1336-WVD66ff.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球背伸展配合旋轉", "instructions_en": ["Start by lying face down on the stability ball with your hips resting on the ball and your feet firmly planted on the ground.", "Place your hands behind your head or cross them over your chest.", "Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.", "Pause for a moment at the top, then slowly rotate your torso to one side, keeping your hips and legs stable.", "Return to the center and repeat the rotation to the other side.", "Lower your upper body back down to the starting position and repeat for the desired number of repetitions."], "instructions_zh": ["首先，面朝下躺在稳定球上，臀部放在球上，双脚牢牢踩在地面上。", "将双手放在脑后或交叉放在胸前。", "启动你的核心，慢慢地将你的上半身抬离球，伸展你的背部，直到你的身体从头部到脚后跟形成一条直线。", "在顶部停顿片刻，然后慢慢将躯干旋转到一侧，保持臀部和腿部稳定。", "返回中心并重复旋转到另一侧。", "将上半身放低至起始位置，然后重复所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings"], "instructions_zh_hant": ["首先，面朝下躺在穩定球上，臀部放在球上，雙腳牢牢踩在地面上。", "將雙手放在腦后或交叉放在胸前。", "啟動你的核心，慢慢地將你的上半身抬離球，伸展你的背部，直到你的身體從頭部到腳后跟形成一條直線。", "在頂部停頓片刻，然后慢慢將軀幹旋轉到一側，保持臀部和腿部穩定。", "返回中心并重復旋轉到另一側。", "將上半身放低至起始位置，然后重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1332', 'exercise', 1, '{"id": "1332", "target": "lats", "name_en": "exercise ball alternating arm ups", "name_zh": "健身球交替手臂抬起", "body_part": "back", "equipment": "stability ball", "gif_asset": "assets/fitness/videos/1332-EyLrNC2.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球交替手臂抬起", "instructions_en": ["Sit on the stability ball with your feet flat on the ground and your back straight.", "Hold a dumbbell in each hand with your palms facing inwards and your arms extended down by your sides.", "Engage your core and slowly lift one arm up towards your shoulder, keeping your elbow slightly bent.", "Pause for a moment at the top, then slowly lower your arm back down to the starting position.", "Repeat the movement with the other arm.", "Continue alternating arms for the desired number of repetitions."], "instructions_zh": ["坐在稳定球上，双脚平放在地面上，背部挺直。", "双手各握一个哑铃，手掌朝内，双臂在身体两侧向下伸展。", "启动你的核心，慢慢地将一只手臂向肩膀抬起，保持肘部稍微弯曲。", "在顶部暂停片刻，然后慢慢将手臂放回起始位置。", "用另一只手臂重复该动作。", "继续交替手臂进行所需的重复次数。"], "secondary_muscles": ["shoulders", "core"], "instructions_zh_hant": ["坐在穩定球上，雙腳平放在地面上，背部挺直。", "雙手各握一個啞鈴，手掌朝內，雙臂在身體兩側向下伸展。", "啟動你的核心，慢慢地將一只手臂向肩膀抬起，保持肘部稍微彎曲。", "在頂部暫停片刻，然后慢慢將手臂放回起始位置。", "用另一只手臂重復該動作。", "繼續交替手臂進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1333', 'exercise', 1, '{"id": "1333", "target": "spine", "name_en": "exercise ball back extension with arms extended", "name_zh": "健身球背伸展配合双臂伸展", "body_part": "back", "equipment": "stability ball", "gif_asset": "assets/fitness/videos/1333-PERjVm8.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球背伸展配合雙臂伸展", "instructions_en": ["Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall for stability.", "Extend your arms straight out in front of you, with your palms facing down.", "Engage your core and slowly lift your upper body off the ball, keeping your back straight and your neck in line with your spine.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将稳定球放在地上，面朝下躺在上面，臀部放在球上，双脚靠在墙上以保持稳定。", "将双臂伸直在身前，手掌朝下。", "启动你的核心，慢慢地将上半身抬离球，保持背部挺直，颈部与脊柱成一直线。", "在顶部停顿片刻，然后慢慢将上半身放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings"], "instructions_zh_hant": ["將穩定球放在地上，面朝下躺在上面，臀部放在球上，雙腳靠在墻上以保持穩定。", "將雙臂伸直在身前，手掌朝下。", "啟動你的核心，慢慢地將上半身抬離球，保持背部挺直，頸部與脊柱成一直線。", "在頂部停頓片刻，然后慢慢將上半身放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1334', 'exercise', 1, '{"id": "1334", "target": "spine", "name_en": "exercise ball back extension with hands behind head", "name_zh": "健身球背伸展配合双手颈后", "body_part": "back", "equipment": "stability ball", "gif_asset": "assets/fitness/videos/1334-o1HGDSq.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球背伸展配合雙手頸后", "instructions_en": ["Place the stability ball on the ground and lie face down on top of it with your hips resting on the ball.", "Position your feet against a wall or other stable surface for support.", "Cross your arms behind your head, with your hands touching the back of your head.", "Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your hips.", "Pause for a moment at the top of the movement, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将稳定球放在地上，面朝下躺在上面，臀部放在球上。", "将脚靠在墙壁或其他稳定的表面上以获得支撑。", "双臂交叉于脑后，双手触碰后脑勺。", "启动你的核心，慢慢地将你的上半身抬离球，伸展你的背部，直到你的身体从头部到臀部形成一条直线。", "在动作的最高点暂停片刻，然后慢慢将上半身放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings"], "instructions_zh_hant": ["將穩定球放在地上，面朝下躺在上面，臀部放在球上。", "將腳靠在墻壁或其他穩定的表面上以獲得支撐。", "雙臂交叉于腦后，雙手觸碰后腦勺。", "啟動你的核心，慢慢地將你的上半身抬離球，伸展你的背部，直到你的身體從頭部到臀部形成一條直線。", "在動作的最高點暫停片刻，然后慢慢將上半身放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1335', 'exercise', 1, '{"id": "1335", "target": "spine", "name_en": "exercise ball back extension with knees off ground", "name_zh": "健身球背伸展配合双膝离开地面", "body_part": "back", "equipment": "stability ball", "gif_asset": "assets/fitness/videos/1335-WME869U.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球背伸展配合雙膝離開地面", "instructions_en": ["Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall for stability.", "Position your hands behind your head or crossed over your chest.", "Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将稳定球放在地上，面朝下躺在上面，臀部放在球上，双脚靠在墙上以保持稳定。", "将双手放在脑后或交叉在胸前。", "启动你的核心，慢慢地将你的上半身抬离球，伸展你的背部，直到你的身体从头部到脚后跟形成一条直线。", "在顶部停顿片刻，然后慢慢将上半身放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings"], "instructions_zh_hant": ["將穩定球放在地上，面朝下躺在上面，臀部放在球上，雙腳靠在墻上以保持穩定。", "將雙手放在腦后或交叉在胸前。", "啟動你的核心，慢慢地將你的上半身抬離球，伸展你的背部，直到你的身體從頭部到腳后跟形成一條直線。", "在頂部停頓片刻，然后慢慢將上半身放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1744', 'exercise', 1, '{"id": "1744", "target": "triceps", "name_en": "exercise ball dip", "name_zh": "健身球臂屈伸", "body_part": "upper arms", "equipment": "stability ball", "gif_asset": "assets/fitness/videos/1744-kprile3.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球臂屈伸", "instructions_en": ["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.", "Place your hands on the ball beside your hips, fingers pointing forward.", "Engage your triceps and push through your hands to lift your body off the ball, straightening your arms.", "Lower your body back down by bending your elbows, keeping them close to your sides.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。", "将双手放在臀部旁边的球上，手指指向前方。", "启动你的三头肌并用力推动你的身体，将你的身体抬离球，伸直你的手臂。", "弯曲肘部，将身体放低，使其靠近身体两侧。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["坐在穩定球上，雙腳平放在地面上，膝蓋彎曲成 90 度角。", "將雙手放在臀部旁邊的球上，手指指向前方。", "啟動你的三頭肌并用力推動你的身體，將你的身體抬離球，伸直你的手臂。", "彎曲肘部，將身體放低，使其靠近身體兩側。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1559', 'exercise', 1, '{"id": "1559", "target": "glutes", "name_en": "exercise ball hip flexor stretch", "name_zh": "健身球髋部屈肌拉伸", "body_part": "upper legs", "equipment": "stability ball", "gif_asset": "assets/fitness/videos/1559-2LQkNPW.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球髖部屈肌拉伸", "instructions_en": ["Place the stability ball on the ground and kneel in front of it.", "Place your right foot on top of the stability ball, with your knee bent at a 90-degree angle.", "Extend your left leg behind you, keeping it straight.", "Lean forward, pushing your hips towards the stability ball, until you feel a stretch in your right hip flexor.", "Hold the stretch for 20-30 seconds, then switch sides and repeat."], "instructions_zh": ["将稳定球放在地上并跪在其前面。", "将右脚放在稳定球上，膝盖弯曲成 90 度角。", "将左腿伸到身后，保持伸直。", "身体前倾，将臀部推向稳定球，直到感觉到右髋屈肌有拉伸感。", "保持拉伸 20-30 秒，然后换边重复。"], "secondary_muscles": ["quadriceps", "hamstrings"], "instructions_zh_hant": ["將穩定球放在地上并跪在其前面。", "將右腳放在穩定球上，膝蓋彎曲成 90 度角。", "將左腿伸到身后，保持伸直。", "身體前傾，將臀部推向穩定球，直到感覺到右髖屈肌有拉伸感。", "保持拉伸 20-30 秒，然后換邊重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1338', 'exercise', 1, '{"id": "1338", "target": "spine", "name_en": "exercise ball hug", "name_zh": "健身球抱膝", "body_part": "back", "equipment": "stability ball", "gif_asset": "assets/fitness/videos/1338-d7z1Y7V.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球抱膝", "instructions_en": ["Sit on the stability ball with your feet flat on the ground and your back straight.", "Hold the stability ball with both hands, hugging it close to your chest.", "Engage your core muscles and slowly lean back, keeping your back straight and your feet planted on the ground.", "Continue leaning back until you feel a stretch in your back muscles.", "Hold the position for a few seconds, then slowly return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在稳定球上，双脚平放在地面上，背部挺直。", "用双手握住稳定球，将其抱在靠近胸部的位置。", "启动你的核心肌肉，慢慢向后倾斜，保持背部挺直，双脚踩在地上。", "继续向后倾斜，直到感觉到背部肌肉伸展。", "保持该姿势几秒钟，然后慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "chest"], "instructions_zh_hant": ["坐在穩定球上，雙腳平放在地面上，背部挺直。", "用雙手握住穩定球，將其抱在靠近胸部的位置。", "啟動你的核心肌肉，慢慢向后傾斜，保持背部挺直，雙腳踩在地上。", "繼續向后傾斜，直到感覺到背部肌肉伸展。", "保持該姿勢幾秒鐘，然后慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1339', 'exercise', 1, '{"id": "1339", "target": "lats", "name_en": "exercise ball lat stretch", "name_zh": "健身球背阔肌拉伸", "body_part": "back", "equipment": "stability ball", "gif_asset": "assets/fitness/videos/1339-sM84pE4.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球背闊肌拉伸", "instructions_en": ["Sit on a stability ball with your feet flat on the ground and your back straight.", "Hold a dumbbell in one hand and extend your arm straight up overhead.", "Slowly lean to the opposite side, feeling a stretch in your lat muscle.", "Hold the stretch for 20-30 seconds, then return to the starting position.", "Repeat on the other side."], "instructions_zh": ["坐在稳定球上，双脚平放在地面上，背部挺直。", "一只手握住哑铃，然后将手臂伸直至头顶。", "慢慢地向另一侧倾斜，感受背阔肌的拉伸。", "保持伸展动作 20-30 秒，然后回到起始位置。", "在另一侧重复。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["坐在穩定球上，雙腳平放在地面上，背部挺直。", "一只手握住啞鈴，然后將手臂伸直至頭頂。", "慢慢地向另一側傾斜，感受背闊肌的拉伸。", "保持伸展動作 20-30 秒，然后回到起始位置。", "在另一側重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1749', 'exercise', 1, '{"id": "1749", "target": "triceps", "name_en": "ez bar standing french press", "name_zh": "曲杆杠铃站姿法式推举", "body_part": "upper arms", "equipment": "ez barbell", "gif_asset": "assets/fitness/videos/1749-1cTf2Ux.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "曲桿槓鈴站姿法式推舉", "instructions_en": ["Stand with your feet shoulder-width apart and hold the ez barbell with an overhand grip.", "Raise the barbell above your head, fully extending your arms.", "Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.", "Pause for a moment, then extend your arms back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，正手握住杠铃。", "将杠铃举过头顶，充分伸展双臂。", "保持上臂靠近头部，弯曲肘部，慢慢将杠铃降低到脑后。", "暂停片刻，然后将手臂伸回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，正手握住杠鈴。", "將杠鈴舉過頭頂，充分伸展雙臂。", "保持上臂靠近頭部，彎曲肘部，慢慢將杠鈴降低到腦后。", "暫停片刻，然后將手臂伸回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1341', 'exercise', 1, '{"id": "1341", "target": "lats", "name_en": "exercise ball lower back stretch (pyramid)", "name_zh": "健身球下背拉伸（金字塔式）", "body_part": "back", "equipment": "stability ball", "gif_asset": "assets/fitness/videos/1341-yU7w7CA.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球下背拉伸（金字塔式）", "instructions_en": ["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.", "Slowly walk your feet forward, rolling the ball down your back until your lower back is resting on the ball.", "Place your hands behind your head or cross them over your chest.", "Engage your core and slowly lower your upper body towards the ground, allowing your lower back to stretch over the ball.", "Hold the stretch for a few seconds, then slowly return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。", "慢慢地向前移动你的脚，将球沿着你的背部滚动，直到你的下背部靠在球上。", "将双手放在脑后或交叉放在胸前。", "启动你的核心，慢慢地将你的上半身降低到地面，让你的下背部伸展到球上方。", "保持伸展几秒钟，然后慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings"], "instructions_zh_hant": ["坐在穩定球上，雙腳平放在地面上，膝蓋彎曲成 90 度角。", "慢慢地向前移動你的腳，將球沿著你的背部滾動，直到你的下背部靠在球上。", "將雙手放在腦后或交叉放在胸前。", "啟動你的核心，慢慢地將你的上半身降低到地面，讓你的下背部伸展到球上方。", "保持伸展幾秒鐘，然后慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1342', 'exercise', 1, '{"id": "1342", "target": "lats", "name_en": "exercise ball lying side lat stretch", "name_zh": "健身球卧姿侧背阔肌拉伸", "body_part": "back", "equipment": "stability ball", "gif_asset": "assets/fitness/videos/1342-rTbyBYV.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球臥姿側背闊肌拉伸", "instructions_en": ["Lie on your side with your legs extended and your head supported by the stability ball.", "Place your top arm on the ball for stability.", "Reach your top arm overhead and allow your torso to rotate slightly.", "Feel the stretch in your lat muscles on the side of your body.", "Hold the stretch for 20-30 seconds, then switch sides and repeat."], "instructions_zh": ["侧躺，双腿伸展，头部由稳定球支撑。", "将上臂放在球上以保持稳定性。", "将上臂举过头顶，让躯干稍微旋转。", "感受身体一侧背阔肌的拉伸。", "保持拉伸 20-30 秒，然后换边重复。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["側躺，雙腿伸展，頭部由穩定球支撐。", "將上臂放在球上以保持穩定性。", "將上臂舉過頭頂，讓軀幹稍微旋轉。", "感受身體一側背闊肌的拉伸。", "保持拉伸 20-30 秒，然后換邊重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1382', 'exercise', 1, '{"id": "1382", "target": "calves", "name_en": "exercise ball on the wall calf raise", "name_zh": "健身球靠墙提踵", "body_part": "lower legs", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1382-xo6sENf.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球靠墻提踵", "instructions_en": ["Stand with your back against a wall and place an exercise ball between your lower back and the wall.", "Position your feet shoulder-width apart, with your toes pointing forward.", "Hold a dumbbell in each hand, with your arms extended by your sides.", "Raise your heels off the ground, lifting your body weight onto the balls of your feet.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["背靠墙站立，将健身球放在下背部和墙壁之间。", "双脚分开与肩同宽，脚趾指向前方。", "每只手握住一个哑铃，双臂伸向身体两侧。", "将脚跟抬离地面，将身体重量转移到脚掌上。", "在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "quadriceps"], "instructions_zh_hant": ["背靠墻站立，將健身球放在下背部和墻壁之間。", "雙腳分開與肩同寬，腳趾指向前方。", "每只手握住一個啞鈴，雙臂伸向身體兩側。", "將腳跟抬離地面，將身體重量轉移到腳掌上。", "在頂部停頓片刻，然后慢慢降低腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3241', 'exercise', 1, '{"id": "3241", "target": "calves", "name_en": "exercise ball on the wall calf raise (tennis ball between ankles)", "name_zh": "健身球靠墙提踵（踝间夹网球）", "body_part": "lower legs", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/3241-FY3UdNT.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球靠墻提踵（踝間夾網球）", "instructions_en": ["Stand facing a wall with your feet shoulder-width apart.", "Place an exercise ball between the wall and your lower back.", "Hold a dumbbell in each hand, with your arms extended by your sides.", "Place a tennis ball between your ankles.", "Raise your heels off the ground, lifting your body up onto your toes.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["面向墙壁站立，双脚分开与肩同宽。", "在墙壁和下背部之间放置一个健身球。", "每只手握住一个哑铃，双臂伸向身体两侧。", "将网球放在脚踝之间。", "将脚后跟抬离地面，将身体抬起到脚趾上。", "在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "quadriceps"], "instructions_zh_hant": ["面向墻壁站立，雙腳分開與肩同寬。", "在墻壁和下背部之間放置一個健身球。", "每只手握住一個啞鈴，雙臂伸向身體兩側。", "將網球放在腳踝之間。", "將腳后跟抬離地面，將身體抬起到腳趾上。", "在頂部停頓片刻，然后慢慢降低腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3240', 'exercise', 1, '{"id": "3240", "target": "calves", "name_en": "exercise ball on the wall calf raise (tennis ball between knees)", "name_zh": "健身球靠墙提踵（膝间夹网球）", "body_part": "lower legs", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/3240-j74M6Zn.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球靠墻提踵（膝間夾網球）", "instructions_en": ["Stand with your back against a wall and place an exercise ball between your lower back and the wall.", "Position your feet shoulder-width apart and slightly in front of you.", "Hold a dumbbell in each hand, with your arms extended by your sides.", "Place a tennis ball between your knees.", "Raise your heels off the ground, lifting your body up onto your toes.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["背靠墙站立，将健身球放在下背部和墙壁之间。", "将双脚分开与肩同宽，并稍微位于您的前方。", "每只手握住一个哑铃，双臂伸向身体两侧。", "将网球放在膝盖之间。", "将脚后跟抬离地面，将身体抬起到脚趾上。", "在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings"], "instructions_zh_hant": ["背靠墻站立，將健身球放在下背部和墻壁之間。", "將雙腳分開與肩同寬，并稍微位于您的前方。", "每只手握住一個啞鈴，雙臂伸向身體兩側。", "將網球放在膝蓋之間。", "將腳后跟抬離地面，將身體抬起到腳趾上。", "在頂部停頓片刻，然后慢慢降低腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1416', 'exercise', 1, '{"id": "1416", "target": "glutes", "name_en": "exercise ball one leg prone lower body rotation", "name_zh": "健身球单腿俯卧下身旋转", "body_part": "upper legs", "equipment": "stability ball", "gif_asset": "assets/fitness/videos/1416-M72BExt.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球單腿俯臥下身旋轉", "instructions_en": ["Lie face down on the stability ball with your hips resting on the ball and your legs extended straight behind you.", "Place your hands on the ground in front of you for support.", "Engage your glutes and core muscles to stabilize your body.", "Slowly lift one leg off the ground, keeping it straight and parallel to the floor.", "Rotate your leg outward, away from your body, while keeping your hips and upper body stable.", "Pause for a moment at the end of the rotation, then slowly return your leg to the starting position.", "Repeat the rotation with the other leg.", "Continue alternating legs for the desired number of repetitions."], "instructions_zh": ["面朝下躺在稳定球上，臀部放在球上，双腿伸直在身后。", "将双手放在身前的地面上以获得支撑。", "调动你的臀肌和核心肌肉来稳定你的身体。", "慢慢地将一条腿抬离地面，保持笔直并与地板平行。", "向外旋转腿部，远离身体，同时保持臀部和上半身稳定。", "旋转结束时暂停片刻，然后慢慢地将腿放回起始位置。", "用另一条腿重复旋转。", "继续交替双腿达到所需的重复次数。"], "secondary_muscles": ["hamstrings", "quadriceps", "core"], "instructions_zh_hant": ["面朝下躺在穩定球上，臀部放在球上，雙腿伸直在身后。", "將雙手放在身前的地面上以獲得支撐。", "調動你的臀肌和核心肌肉來穩定你的身體。", "慢慢地將一條腿抬離地面，保持筆直并與地板平行。", "向外旋轉腿部，遠離身體，同時保持臀部和上半身穩定。", "旋轉結束時暫停片刻，然后慢慢地將腿放回起始位置。", "用另一條腿重復旋轉。", "繼續交替雙腿達到所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1417', 'exercise', 1, '{"id": "1417", "target": "glutes", "name_en": "exercise ball one legged diagonal kick hamstring curl", "name_zh": "健身球单腿对角踢腿腘绳肌弯举", "body_part": "upper legs", "equipment": "stability ball", "gif_asset": "assets/fitness/videos/1417-GOJKFfO.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球單腿對角踢腿腘繩肌彎舉", "instructions_en": ["Start by lying on your back with your legs extended and your heels resting on top of the stability ball.", "Place your arms by your sides for stability.", "Engage your glutes and core muscles to lift your hips off the ground, creating a straight line from your shoulders to your heels.", "Bend your right knee and bring it towards your chest, keeping your left leg extended and your foot flexed.", "Kick your right leg diagonally across your body, extending it fully and engaging your hamstrings.", "Slowly return your right leg to the starting position, maintaining control and stability.", "Repeat the movement with your left leg, alternating sides for the desired number of repetitions."], "instructions_zh": ["首先仰卧，双腿伸展，脚跟放在稳定球上。", "将手臂放在身体两侧以保持稳定。", "调动臀肌和核心肌肉，将臀部抬离地面，从肩膀到脚后跟形成一条直线。", "弯曲右膝并将其靠近胸部，保持左腿伸展，脚部弯曲。", "将右腿斜踢过身体，完全伸展并拉动腿筋。", "慢慢地将右腿返回到起始位置，保持控制和稳定性。", "用左腿重复该动作，交替进行所需的重复次数。"], "secondary_muscles": ["hamstrings", "calves"], "instructions_zh_hant": ["首先仰臥，雙腿伸展，腳跟放在穩定球上。", "將手臂放在身體兩側以保持穩定。", "調動臀肌和核心肌肉，將臀部抬離地面，從肩膀到腳后跟形成一條直線。", "彎曲右膝并將其靠近胸部，保持左腿伸展，腳部彎曲。", "將右腿斜踢過身體，完全伸展并拉動腿筋。", "慢慢地將右腿返回到起始位置，保持控制和穩定性。", "用左腿重復該動作，交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1296', 'exercise', 1, '{"id": "1296", "target": "pectorals", "name_en": "exercise ball pike push up", "name_zh": "健身球折髋俯卧撑", "body_part": "chest", "equipment": "stability ball", "gif_asset": "assets/fitness/videos/1296-sVvXT5J.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球折髖俯臥撐", "instructions_en": ["Start in a push-up position with your hands on the floor and your shins resting on the stability ball.", "Engage your core and lift your hips up towards the ceiling, rolling the ball towards your hands.", "Keep your legs straight and your body in a pike position, forming an inverted V shape.", "Bend your elbows and lower your upper body towards the floor, keeping your head in line with your hands.", "Push through your hands and extend your arms to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["从俯卧撑位置开始，双手放在地板上，小腿放在稳定球上。", "收紧核心肌群，将臀部抬向天花板，将球滚向双手。", "保持双腿伸直，身体呈屈体姿势，形成倒V字形。", "弯曲肘部，将上半身降低到地板上，保持头部与双手在一条直线上。", "用手推动并伸展双臂以返回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps", "core"], "instructions_zh_hant": ["從俯臥撐位置開始，雙手放在地板上，小腿放在穩定球上。", "收緊核心肌群，將臀部抬向天花板，將球滾向雙手。", "保持雙腿伸直，身體呈屈體姿勢，形成倒V字形。", "彎曲肘部，將上半身降低到地板上，保持頭部與雙手在一條直線上。", "用手推動并伸展雙臂以返回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1343', 'exercise', 1, '{"id": "1343", "target": "spine", "name_en": "exercise ball prone leg raise", "name_zh": "健身球俯卧举腿", "body_part": "back", "equipment": "stability ball", "gif_asset": "assets/fitness/videos/1343-lCKm4Rs.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球俯臥舉腿", "instructions_en": ["Lie face down on a mat with your legs extended and your toes resting on top of the stability ball.", "Place your hands on the ground, shoulder-width apart, and engage your core muscles.", "Keeping your legs straight, slowly lift them off the ground, using your lower back and glutes to raise them as high as possible.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["面朝下躺在垫子上，双腿伸展，脚趾放在稳定球上。", "将双手放在地上，与肩同宽，锻炼核心肌肉。", "保持双腿伸直，慢慢将它们抬离地面，用下背部和臀部将它们尽可能抬高。", "在顶部暂停片刻，然后慢慢将双腿放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["abdominals", "glutes"], "instructions_zh_hant": ["面朝下躺在墊子上，雙腿伸展，腳趾放在穩定球上。", "將雙手放在地上，與肩同寬，鍛煉核心肌肉。", "保持雙腿伸直，慢慢將它們抬離地面，用下背部和臀部將它們盡可能抬高。", "在頂部暫停片刻，然后慢慢將雙腿放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1560', 'exercise', 1, '{"id": "1560", "target": "hamstrings", "name_en": "exercise ball seated hamstring stretch", "name_zh": "健身球坐姿腘绳肌拉伸", "body_part": "upper legs", "equipment": "stability ball", "gif_asset": "assets/fitness/videos/1560-yRYyfdA.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球坐姿腘繩肌拉伸", "instructions_en": ["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.", "Slowly roll the ball forward, walking your feet out until your upper back is resting on the ball and your legs are extended straight in front of you.", "Place your hands on your hips for support.", "Engage your core and slowly lower your upper body towards the ground, keeping your back straight and your chest lifted.", "Stop when you feel a stretch in your hamstrings, and hold the position for 20-30 seconds.", "Slowly return to the starting position by pushing through your heels and using your hamstrings to pull yourself back up.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。", "慢慢地向前滚动球，双脚向外走，直到上背部靠在球上，双腿在身前伸直。", "将双手放在臀部上以获得支撑。", "启动你的核心，慢慢地将上半身降低到地面，保持背部挺直，胸部抬起。", "当您感觉到腿筋拉伸时停止，并保持该姿势 20-30 秒。", "通过推动脚后跟并使用腿筋将自己拉回来，慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "lower back"], "instructions_zh_hant": ["坐在穩定球上，雙腳平放在地面上，膝蓋彎曲成 90 度角。", "慢慢地向前滾動球，雙腳向外走，直到上背部靠在球上，雙腿在身前伸直。", "將雙手放在臀部上以獲得支撐。", "啟動你的核心，慢慢地將上半身降低到地面，保持背部挺直，胸部抬起。", "當您感覺到腿筋拉伸時停止，并保持該姿勢 20-30 秒。", "通過推動腳后跟并使用腿筋將自己拉回來，慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1745', 'exercise', 1, '{"id": "1745", "target": "triceps", "name_en": "exercise ball seated triceps stretch", "name_zh": "健身球坐姿肱三头肌拉伸", "body_part": "upper arms", "equipment": "stability ball", "gif_asset": "assets/fitness/videos/1745-7ePTw4B.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球坐姿肱三頭肌拉伸", "instructions_en": ["Sit on a stability ball with your feet flat on the ground and your back straight.", "Hold a dumbbell in one hand and extend your arm straight up above your head.", "Bend your elbow and lower the dumbbell behind your head, keeping your upper arm close to your ear.", "Hold the stretch for a few seconds, then return to the starting position.", "Repeat with the other arm."], "instructions_zh": ["坐在稳定球上，双脚平放在地面上，背部挺直。", "一只手握住哑铃，将手臂伸直至头顶上方。", "弯曲肘部，将哑铃放在脑后，保持上臂靠近耳朵。", "保持伸展几秒钟，然后回到起始位置。", "用另一只手臂重复上述步骤。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["坐在穩定球上，雙腳平放在地面上，背部挺直。", "一只手握住啞鈴，將手臂伸直至頭頂上方。", "彎曲肘部，將啞鈴放在腦后，保持上臂靠近耳朵。", "保持伸展幾秒鐘，然后回到起始位置。", "用另一只手臂重復上述步驟。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1746', 'exercise', 1, '{"id": "1746", "target": "triceps", "name_en": "exercise ball supine triceps extension", "name_zh": "健身球仰卧臂屈伸", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/1746-Gm2Uv1z.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球仰臥臂屈伸", "instructions_en": ["Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.", "Hold a dumbbell with both hands and extend your arms straight up towards the ceiling.", "Slowly lower the dumbbell behind your head, keeping your elbows close to your ears.", "Pause for a moment, then raise the dumbbell back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在健身球上，双脚平放在地上，膝盖弯曲成 90 度角。", "双手握住哑铃，双臂伸直向天花板方向伸展。", "慢慢地将哑铃放到脑后，保持肘部靠近耳朵。", "暂停片刻，然后将哑铃举回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["坐在健身球上，雙腳平放在地上，膝蓋彎曲成 90 度角。", "雙手握住啞鈴，雙臂伸直向天花板方向伸展。", "慢慢地將啞鈴放到腦后，保持肘部靠近耳朵。", "暫停片刻，然后將啞鈴舉回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1747', 'exercise', 1, '{"id": "1747", "target": "triceps", "name_en": "ez bar french press on exercise ball", "name_zh": "曲杆杠铃法式推举（健身球）", "body_part": "upper arms", "equipment": "ez barbell", "gif_asset": "assets/fitness/videos/1747-CFN9P8G.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "曲桿槓鈴法式推舉（健身球）", "instructions_en": ["Sit on an exercise ball and hold an EZ barbell with an overhand grip.", "Extend your arms straight up, keeping your elbows close to your head.", "Slowly lower the barbell behind your head by bending your elbows.", "Pause for a moment, then extend your arms back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在健身球上，正手握住 EZ 杠铃。", "向上伸展双臂，保持肘部靠近头部。", "弯曲肘部，慢慢将杠铃降低到脑后。", "暂停片刻，然后将手臂伸回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["坐在健身球上，正手握住 EZ 杠鈴。", "向上伸展雙臂，保持肘部靠近頭部。", "彎曲肘部，慢慢將杠鈴降低到腦后。", "暫停片刻，然后將手臂伸回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3010', 'exercise', 1, '{"id": "3010", "target": "lats", "name_en": "ez bar lying bent arms pullover", "name_zh": "曲杆杠铃卧姿弯曲双臂仰卧上拉", "body_part": "back", "equipment": "ez barbell", "gif_asset": "assets/fitness/videos/3010-nDK1HJ0.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "曲桿槓鈴臥姿彎曲雙臂仰臥上拉", "instructions_en": ["Lie flat on a bench with your head at one end and your feet on the floor.", "Hold the EZ barbell with a pronated grip (palms facing away from you) and your hands shoulder-width apart.", "Extend your arms straight above your chest, keeping a slight bend in your elbows.", "Lower the barbell in an arc motion behind your head, maintaining the slight bend in your elbows.", "Pause for a moment, then return the barbell to the starting position by reversing the arc motion.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，头放在一端，双脚放在地板上。", "旋前握住 EZ 杠铃（手掌背向您），双手与肩同宽。", "将手臂伸直至胸部上方，保持肘部轻微弯曲。", "以弧线动作将杠铃降低到头后，保持肘部轻微弯曲。", "暂停片刻，然后通过反向弧线运动将杠铃返回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "chest"], "instructions_zh_hant": ["平躺在長凳上，頭放在一端，雙腳放在地板上。", "旋前握住 EZ 杠鈴（手掌背向您），雙手與肩同寬。", "將手臂伸直至胸部上方，保持肘部輕微彎曲。", "以弧線動作將杠鈴降低到頭后，保持肘部輕微彎曲。", "暫停片刻，然后通過反向弧線運動將杠鈴返回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1748', 'exercise', 1, '{"id": "1748", "target": "triceps", "name_en": "ez bar lying close grip triceps extension behind head", "name_zh": "曲杆杠铃卧姿窄握臂屈伸颈后", "body_part": "upper arms", "equipment": "ez barbell", "gif_asset": "assets/fitness/videos/1748-6CKUx7o.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "曲桿槓鈴臥姿窄握臂屈伸頸后", "instructions_en": ["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.", "Hold the ez barbell with a close grip, palms facing up, and extend your arms straight up over your chest.", "Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows.", "Pause for a moment, then extend your arms back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，双脚平放在地上，头放在长凳的末端。", "紧紧握住 ez 杠铃，手掌朝上，将手臂伸直至胸部上方。", "保持上臂静止，弯曲肘部，慢慢将杠铃降低到脑后。", "暂停片刻，然后将手臂伸回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["平躺在長凳上，雙腳平放在地上，頭放在長凳的末端。", "緊緊握住 ez 杠鈴，手掌朝上，將手臂伸直至胸部上方。", "保持上臂靜止，彎曲肘部，慢慢將杠鈴降低到腦后。", "暫停片刻，然后將手臂伸回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1344', 'exercise', 1, '{"id": "1344", "target": "upper back", "name_en": "ez bar reverse grip bent over row", "name_zh": "曲杆杠铃反握俯身划船", "body_part": "back", "equipment": "ez barbell", "gif_asset": "assets/fitness/videos/1344-G8dXpNG.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "曲桿槓鈴反握俯身劃船", "instructions_en": ["Stand with your feet shoulder-width apart and knees slightly bent.", "Hold the ez barbell with an underhand grip, palms facing up, and hands shoulder-width apart.", "Bend forward at the hips, keeping your back straight and chest up, until your torso is almost parallel to the floor.", "Pull the ez barbell towards your lower chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the ez barbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站立，双脚分开与肩同宽，膝盖稍微弯曲。", "反手握住 ez 杠铃，手掌朝上，双手与肩同宽。", "臀部向前弯曲，保持背部挺直，挺胸，直到躯干几乎与地板平行。", "将 ez 杠铃拉向下胸部，将肩胛骨挤压在一起。", "在顶部暂停片刻，然后慢慢将 ez 杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["站立，雙腳分開與肩同寬，膝蓋稍微彎曲。", "反手握住 ez 杠鈴，手掌朝上，雙手與肩同寬。", "臀部向前彎曲，保持背部挺直，挺胸，直到軀幹幾乎與地板平行。", "將 ez 杠鈴拉向下胸部，將肩胛骨擠壓在一起。", "在頂部暫停片刻，然后慢慢將 ez 杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1682', 'exercise', 1, '{"id": "1682", "target": "biceps", "name_en": "ez bar seated close grip concentration curl", "name_zh": "曲杆杠铃坐姿窄握集中弯举", "body_part": "upper arms", "equipment": "ez barbell", "gif_asset": "assets/fitness/videos/1682-Dsfz0Id.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "曲桿槓鈴坐姿窄握集中彎舉", "instructions_en": ["Sit on a bench with your feet flat on the ground and hold an EZ barbell with an underhand grip.", "Rest your elbow on the inside of your thigh, just above the knee.", "Curl the barbell up towards your shoulder while keeping your upper arm stationary.", "Squeeze your biceps at the top of the movement, then slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双脚平放在地面上，反手握住 EZ 杠铃。", "将肘部放在大腿内侧、膝盖上方。", "将杠铃向上弯向肩膀，同时保持上臂静止。", "在动作的最高点挤压二头肌，然后慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在長凳上，雙腳平放在地面上，反手握住 EZ 杠鈴。", "將肘部放在大腿內側、膝蓋上方。", "將杠鈴向上彎向肩膀，同時保持上臂靜止。", "在動作的最高點擠壓二頭肌，然后慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1627', 'exercise', 1, '{"id": "1627", "target": "biceps", "name_en": "ez barbell close grip preacher curl", "name_zh": "曲杆杠铃窄握牧师凳弯举", "body_part": "upper arms", "equipment": "ez barbell", "gif_asset": "assets/fitness/videos/1627-hacCyUv.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "曲桿槓鈴窄握牧師凳彎舉", "instructions_en": ["Sit on a preacher curl bench and place your upper arms on the pad, gripping the ez barbell with an underhand grip.", "Rest your triceps on the pad and fully extend your arms, keeping your back straight.", "Slowly curl the barbell towards your shoulders, contracting your biceps.", "Pause for a moment at the top, squeezing your biceps.", "Lower the barbell back to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在牧师弯举凳上，将上臂放在垫子上，反手握住 ez 杠铃。", "将三头肌放在垫子上，充分伸展手臂，保持背部挺直。", "慢慢地将杠铃向肩膀弯曲，收缩二头肌。", "在顶部暂停片刻，挤压你的二头肌。", "将杠铃放回起始位置，充分伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在牧師彎舉凳上，將上臂放在墊子上，反手握住 ez 杠鈴。", "將三頭肌放在墊子上，充分伸展手臂，保持背部挺直。", "慢慢地將杠鈴向肩膀彎曲，收縮二頭肌。", "在頂部暫停片刻，擠壓你的二頭肌。", "將杠鈴放回起始位置，充分伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0446', 'exercise', 1, '{"id": "0446", "target": "biceps", "name_en": "ez barbell close-grip curl", "name_zh": "曲杆杠铃窄握弯举", "body_part": "upper arms", "equipment": "ez barbell", "gif_asset": "assets/fitness/videos/0446-V4ryaZa.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "曲桿槓鈴窄握彎舉", "instructions_en": ["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, hands shoulder-width apart.", "Keep your elbows close to your torso and your upper arms stationary throughout the movement.", "Curl the barbell up towards your shoulders, contracting your biceps.", "Pause for a moment at the top, then slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站直，双脚分开与肩同宽，反手握住杠铃，双手分开与肩同宽。", "在整个运动过程中，保持肘部靠近躯干，上臂保持静止。", "将杠铃向上弯向肩膀，收缩二头肌。", "在顶部停顿片刻，然后慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙腳分開與肩同寬，反手握住杠鈴，雙手分開與肩同寬。", "在整個運動過程中，保持肘部靠近軀幹，上臂保持靜止。", "將杠鈴向上彎向肩膀，收縮二頭肌。", "在頂部停頓片刻，然后慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0447', 'exercise', 1, '{"id": "0447", "target": "biceps", "name_en": "ez barbell curl", "name_zh": "曲杆杠铃弯举", "body_part": "upper arms", "equipment": "ez barbell", "gif_asset": "assets/fitness/videos/0447-6TG6x2w.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "曲桿槓鈴彎舉", "instructions_en": ["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.", "Keep your elbows close to your torso and your upper arms stationary throughout the movement.", "Exhale as you curl the barbell up towards your shoulders, contracting your biceps.", "Pause for a moment at the top, then inhale as you slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站直，双脚分开与肩同宽，反手握住 ez 杠铃，手掌朝上。", "在整个运动过程中，保持肘部靠近躯干，上臂保持静止。", "当你将杠铃向肩膀方向卷曲时呼气，收缩二头肌。", "在顶部暂停片刻，然后吸气，慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙腳分開與肩同寬，反手握住 ez 杠鈴，手掌朝上。", "在整個運動過程中，保持肘部靠近軀幹，上臂保持靜止。", "當你將杠鈴向肩膀方向卷曲時呼氣，收縮二頭肌。", "在頂部暫停片刻，然后吸氣，慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0448', 'exercise', 1, '{"id": "0448", "target": "triceps", "name_en": "ez barbell decline close grip face press", "name_zh": "曲杆杠铃下斜窄握额前臂屈伸", "body_part": "upper arms", "equipment": "ez barbell", "gif_asset": "assets/fitness/videos/0448-DgZQ11d.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "曲桿槓鈴下斜窄握額前臂屈伸", "instructions_en": ["Lie on a decline bench with your head lower than your feet.", "Grasp the ez barbell with a close grip, palms facing each other.", "Extend your arms straight up above your chest, keeping your elbows close to your body.", "Lower the barbell towards your forehead by bending your elbows.", "Pause for a moment, then press the barbell back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["躺在倾斜的长凳上，头低于脚。", "紧紧抓住 ez 杠铃，手掌相对。", "将手臂伸直至胸部上方，保持肘部靠近身体。", "弯曲肘部，将杠铃降低到前额。", "暂停片刻，然后将杠铃推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["躺在傾斜的長凳上，頭低于腳。", "緊緊抓住 ez 杠鈴，手掌相對。", "將手臂伸直至胸部上方，保持肘部靠近身體。", "彎曲肘部，將杠鈴降低到前額。", "暫停片刻，然后將杠鈴推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2186', 'exercise', 1, '{"id": "2186", "target": "triceps", "name_en": "ez barbell decline triceps extension", "name_zh": "曲杆杠铃下斜臂屈伸", "body_part": "upper arms", "equipment": "ez barbell", "gif_asset": "assets/fitness/videos/2186-CQHoDm0.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "曲桿槓鈴下斜臂屈伸", "instructions_en": ["Lie on a decline bench with your head lower than your feet and your feet secured.", "Hold the ez barbell with an overhand grip, hands shoulder-width apart.", "Extend your arms fully, keeping your elbows close to your head.", "Lower the barbell slowly towards your forehead, bending your elbows.", "Pause for a moment, then extend your arms back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["躺在倾斜的长凳上，头低于脚，双脚固定。", "正手握住 ez 杠铃，双手与肩同宽。", "充分伸展双臂，保持肘部靠近头部。", "将杠铃慢慢降低到前额，弯曲肘部。", "暂停片刻，然后将手臂伸回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["躺在傾斜的長凳上，頭低于腳，雙腳固定。", "正手握住 ez 杠鈴，雙手與肩同寬。", "充分伸展雙臂，保持肘部靠近頭部。", "將杠鈴慢慢降低到前額，彎曲肘部。", "暫停片刻，然后將手臂伸回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0449', 'exercise', 1, '{"id": "0449", "target": "triceps", "name_en": "ez barbell incline triceps extension", "name_zh": "曲杆杠铃上斜臂屈伸", "body_part": "upper arms", "equipment": "ez barbell", "gif_asset": "assets/fitness/videos/0449-KyLtiLT.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "曲桿槓鈴上斜臂屈伸", "instructions_en": ["Set up an incline bench at a 45-degree angle.", "Sit on the bench with your back against the pad and hold the ez barbell with an overhand grip.", "Extend your arms fully overhead, keeping your elbows close to your head.", "Lower the barbell behind your head by bending your elbows, keeping your upper arms stationary.", "Pause for a moment, then extend your arms back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["设置一个 45 度角的上斜凳。", "坐在长凳上，背部靠在垫子上，正手握住 ez 杠铃。", "将手臂完全伸过头顶，保持肘部靠近头部。", "弯曲肘部，将杠铃降低到头后，保持上臂静止。", "暂停片刻，然后将手臂伸回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["設置一個 45 度角的上斜凳。", "坐在長凳上，背部靠在墊子上，正手握住 ez 杠鈴。", "將手臂完全伸過頭頂，保持肘部靠近頭部。", "彎曲肘部，將杠鈴降低到頭后，保持上臂靜止。", "暫停片刻，然后將手臂伸回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0450', 'exercise', 1, '{"id": "0450", "target": "triceps", "name_en": "ez barbell jm bench press", "name_zh": "曲杆杠铃JM卧推", "body_part": "upper arms", "equipment": "ez barbell", "gif_asset": "assets/fitness/videos/0450-hnOYgH3.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "曲桿槓鈴JM臥推", "instructions_en": ["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.", "Grasp the ez barbell with an overhand grip, slightly wider than shoulder-width apart.", "Lower the barbell to your chest, keeping your elbows tucked in close to your body.", "Push the barbell back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，双脚平放在地上，背部紧贴长凳。", "正手握住杠铃，握距略宽于肩宽。", "将杠铃降低到胸部，保持肘部靠近身体。", "将杠铃推回到起始位置，完全伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["平躺在長凳上，雙腳平放在地上，背部緊貼長凳。", "正手握住杠鈴，握距略寬于肩寬。", "將杠鈴降低到胸部，保持肘部靠近身體。", "將杠鈴推回到起始位置，完全伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0451', 'exercise', 1, '{"id": "0451", "target": "biceps", "name_en": "ez barbell reverse grip curl", "name_zh": "曲杆杠铃反握弯举", "body_part": "upper arms", "equipment": "ez barbell", "gif_asset": "assets/fitness/videos/0451-Y5X65IB.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "曲桿槓鈴反握彎舉", "instructions_en": ["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip.", "Keep your elbows close to your torso and your upper arms stationary throughout the exercise.", "Curl the barbell upwards by contracting your biceps, while exhaling.", "Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Slowly begin to bring the barbell back to the starting position as you inhale.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站直，双脚分开与肩同宽，反手握住 ez 杠铃。", "在整个练习过程中，保持肘部靠近躯干，上臂保持静止。", "通过收缩二头肌将杠铃向上卷曲，同时呼气。", "继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气时慢慢开始将杠铃拉回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙腳分開與肩同寬，反手握住 ez 杠鈴。", "在整個練習過程中，保持肘部靠近軀幹，上臂保持靜止。", "通過收縮二頭肌將杠鈴向上卷曲，同時呼氣。", "繼續舉起杠鈴，直到二頭肌完全收縮并且杠鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣時慢慢開始將杠鈴拉回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0452', 'exercise', 1, '{"id": "0452", "target": "biceps", "name_en": "ez barbell reverse grip preacher curl", "name_zh": "曲杆杠铃反握牧师凳弯举", "body_part": "upper arms", "equipment": "ez barbell", "gif_asset": "assets/fitness/videos/0452-vBNyir7.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "曲桿槓鈴反握牧師凳彎舉", "instructions_en": ["Sit on a preacher bench with your chest against the pad and your feet flat on the floor.", "Grasp the ez barbell with an underhand grip, hands shoulder-width apart.", "Rest your upper arms on the pad, allowing your forearms to hang down.", "Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.", "Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在牧师凳上，胸部靠在垫子上，双脚平放在地板上。", "反手抓住 ez 杠铃，双手与肩同宽。", "将上臂放在垫子上，让前臂下垂。", "保持上臂静止，呼气并将杠铃向上弯向肩膀。", "在顶部停顿片刻，然后吸气，慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在牧師凳上，胸部靠在墊子上，雙腳平放在地板上。", "反手抓住 ez 杠鈴，雙手與肩同寬。", "將上臂放在墊子上，讓前臂下垂。", "保持上臂靜止，呼氣并將杠鈴向上彎向肩膀。", "在頂部停頓片刻，然后吸氣，慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1458', 'exercise', 1, '{"id": "1458", "target": "biceps", "name_en": "ez barbell seated curls", "name_zh": "曲杆杠铃坐姿弯举", "body_part": "upper arms", "equipment": "ez barbell", "gif_asset": "assets/fitness/videos/1458-jtFKbt5.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "曲桿槓鈴坐姿彎舉", "instructions_en": ["Sit on a bench with your feet flat on the ground and your back straight.", "Hold the ez barbell with an underhand grip, palms facing up, and your hands shoulder-width apart.", "Rest your upper arms on your thighs, allowing the ez barbell to hang down in front of you.", "Keeping your upper arms stationary, exhale and curl the ez barbell upwards towards your shoulders.", "Pause for a moment at the top, squeezing your biceps.", "Inhale and slowly lower the ez barbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双脚平放在地上，背部挺直。", "反手握住 ez 杠铃，手掌朝上，双手与肩同宽。", "将上臂放在大腿上，让 ez 杠铃垂在您面前。", "保持上臂静止，呼气并将杠铃向上卷曲至肩膀。", "在顶部暂停片刻，挤压你的二头肌。", "吸气并缓慢地将 ez 杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在長凳上，雙腳平放在地上，背部挺直。", "反手握住 ez 杠鈴，手掌朝上，雙手與肩同寬。", "將上臂放在大腿上，讓 ez 杠鈴垂在您面前。", "保持上臂靜止，呼氣并將杠鈴向上卷曲至肩膀。", "在頂部暫停片刻，擠壓你的二頭肌。", "吸氣并緩慢地將 ez 杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0453', 'exercise', 1, '{"id": "0453", "target": "triceps", "name_en": "ez barbell seated triceps extension", "name_zh": "曲杆杠铃坐姿臂屈伸", "body_part": "upper arms", "equipment": "ez barbell", "gif_asset": "assets/fitness/videos/0453-iaapw0g.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "曲桿槓鈴坐姿臂屈伸", "instructions_en": ["Sit on a bench with your back straight and feet flat on the ground.", "Hold the ez barbell with an overhand grip, hands shoulder-width apart.", "Raise the barbell overhead, fully extending your arms.", "Keeping your upper arms stationary, lower the barbell behind your head by bending your elbows.", "Pause for a moment, then raise the barbell back to the starting position by extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，背部挺直，双脚平放在地上。", "正手握住 ez 杠铃，双手与肩同宽。", "将杠铃举过头顶，充分伸展双臂。", "保持上臂静止，弯曲肘部将杠铃降低到脑后。", "暂停片刻，然后伸展双臂将杠铃举回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["坐在長凳上，背部挺直，雙腳平放在地上。", "正手握住 ez 杠鈴，雙手與肩同寬。", "將杠鈴舉過頭頂，充分伸展雙臂。", "保持上臂靜止，彎曲肘部將杠鈴降低到腦后。", "暫停片刻，然后伸展雙臂將杠鈴舉回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0454', 'exercise', 1, '{"id": "0454", "target": "biceps", "name_en": "ez barbell spider curl", "name_zh": "曲杆杠铃蜘蛛式弯举", "body_part": "upper arms", "equipment": "ez barbell", "gif_asset": "assets/fitness/videos/0454-Ye5Qxb0.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "曲桿槓鈴蜘蛛式彎舉", "instructions_en": ["Stand with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.", "Rest your upper arms on a preacher bench or stability ball, allowing your elbows to hang down.", "Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.", "Pause for a moment at the top, squeezing your biceps.", "Inhale and slowly lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，反手握住杠铃，手掌朝上。", "将上臂放在牧师凳或稳定球上，让肘部下垂。", "保持上臂静止，呼气并将杠铃向上弯向肩膀。", "在顶部暂停片刻，挤压你的二头肌。", "吸气并慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，反手握住杠鈴，手掌朝上。", "將上臂放在牧師凳或穩定球上，讓肘部下垂。", "保持上臂靜止，呼氣并將杠鈴向上彎向肩膀。", "在頂部暫停片刻，擠壓你的二頭肌。", "吸氣并慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1628', 'exercise', 1, '{"id": "1628", "target": "biceps", "name_en": "ez barbell spider curl", "name_zh": "曲杆杠铃蜘蛛式弯举", "body_part": "upper arms", "equipment": "ez barbell", "gif_asset": "assets/fitness/videos/1628-2kattbR.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "曲桿槓鈴蜘蛛式彎舉", "instructions_en": ["Stand with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.", "Rest your upper arms on a preacher bench or stability ball, allowing your elbows to hang down.", "Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.", "Pause for a moment at the top, squeezing your biceps.", "Inhale and slowly lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，反手握住杠铃，手掌朝上。", "将上臂放在牧师凳或稳定球上，让肘部下垂。", "保持上臂静止，呼气并将杠铃向上弯向肩膀。", "在顶部暂停片刻，挤压你的二头肌。", "吸气并慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，反手握住杠鈴，手掌朝上。", "將上臂放在牧師凳或穩定球上，讓肘部下垂。", "保持上臂靜止，呼氣并將杠鈴向上彎向肩膀。", "在頂部暫停片刻，擠壓你的二頭肌。", "吸氣并慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2404', 'exercise', 1, '{"id": "2404", "target": "biceps", "name_en": "ez-bar biceps curl (with arm blaster)", "name_zh": "曲杆杠铃二头弯举（配合弯举护板）", "body_part": "upper arms", "equipment": "ez barbell", "gif_asset": "assets/fitness/videos/2404-tJ5nYqo.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "曲桿槓鈴二頭彎舉（配合彎舉護板）", "instructions_en": ["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.", "Place your upper arms against the arm blaster, keeping them stationary throughout the exercise.", "Keeping your elbows close to your body, exhale and curl the barbell up towards your shoulders.", "Pause for a moment at the top, squeezing your biceps.", "Inhale and slowly lower the barbell back to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站直，双脚分开与肩同宽，反手握住 ez 杠铃，手掌朝上。", "将上臂靠在手臂冲击波上，在整个练习过程中保持静止。", "保持肘部靠近身体，呼气并将杠铃向上弯向肩膀。", "在顶部暂停片刻，挤压你的二头肌。", "吸气，慢慢将杠铃放回起始位置，充分伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙腳分開與肩同寬，反手握住 ez 杠鈴，手掌朝上。", "將上臂靠在手臂沖擊波上，在整個練習過程中保持靜止。", "保持肘部靠近身體，呼氣并將杠鈴向上彎向肩膀。", "在頂部暫停片刻，擠壓你的二頭肌。", "吸氣，慢慢將杠鈴放回起始位置，充分伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2432', 'exercise', 1, '{"id": "2432", "target": "triceps", "name_en": "ez-bar close-grip bench press", "name_zh": "曲杆杠铃窄握卧推", "body_part": "upper arms", "equipment": "ez barbell", "gif_asset": "assets/fitness/videos/2432-da4cXST.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "曲桿槓鈴窄握臥推", "instructions_en": ["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.", "Grasp the ez barbell with a close grip, hands shoulder-width apart, palms facing forward.", "Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.", "Slowly lower the barbell towards your chest, keeping your elbows close to your body.", "Pause for a moment when the barbell touches your chest.", "Push the barbell back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，双脚平放在地上，背部紧贴长凳。", "紧握杠铃，双手与肩同宽，掌心向前。", "将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。", "慢慢地将杠铃降低到胸部，保持肘部靠近身体。", "当杠铃触及胸部时暂停片刻。", "将杠铃推回到起始位置，完全伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["平躺在長凳上，雙腳平放在地上，背部緊貼長凳。", "緊握杠鈴，雙手與肩同寬，掌心向前。", "將杠鈴從架子上提起，并將其直接放在胸部上方，雙臂完全伸展。", "慢慢地將杠鈴降低到胸部，保持肘部靠近身體。", "當杠鈴觸及胸部時暫停片刻。", "將杠鈴推回到起始位置，完全伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0457', 'exercise', 1, '{"id": "0457", "target": "abs", "name_en": "flexion leg sit up (straight arm)", "name_zh": "直臂收腿仰卧起坐", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0457-KZn52RC.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "直臂收腿仰臥起坐", "instructions_en": ["Lie flat on your back with your legs extended and arms straight above your head.", "Engaging your abs, lift your upper body off the ground while simultaneously lifting your legs towards your chest.", "Reach your hands towards your toes as you lift your upper body and legs.", "Pause for a moment at the top, then slowly lower your upper body and legs back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，双腿伸直，双臂伸直至头顶上方。", "收紧腹肌，将上半身抬离地面，同时将双腿抬向胸部。", "抬起上半身和腿部时，将双手伸向脚趾。", "在顶部停顿片刻，然后慢慢降低上半身和双腿回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors", "quadriceps"], "instructions_zh_hant": ["平躺，雙腿伸直，雙臂伸直至頭頂上方。", "收緊腹肌，將上半身抬離地面，同時將雙腿抬向胸部。", "抬起上半身和腿部時，將雙手伸向腳趾。", "在頂部停頓片刻，然后慢慢降低上半身和雙腿回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2741', 'exercise', 1, '{"id": "2741", "target": "biceps", "name_en": "ez-barbell standing wide grip biceps curl", "name_zh": "曲杆杠铃站姿宽握二头弯举", "body_part": "upper arms", "equipment": "ez barbell", "gif_asset": "assets/fitness/videos/2741-OVTZ65k.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "曲桿槓鈴站姿寬握二頭彎舉", "instructions_en": ["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, hands wider than shoulder-width apart.", "Keep your elbows close to your torso and your upper arms stationary throughout the movement.", "Curl the barbell up towards your shoulders by contracting your biceps.", "Pause for a moment at the top, then slowly lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站直，双脚分开与肩同宽，反手握住杠铃，双手分开比肩宽。", "在整个运动过程中，保持肘部靠近躯干，上臂保持静止。", "收缩二头肌，将杠铃向上弯向肩膀。", "在顶部停顿片刻，然后慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙腳分開與肩同寬，反手握住杠鈴，雙手分開比肩寬。", "在整個運動過程中，保持肘部靠近軀幹，上臂保持靜止。", "收縮二頭肌，將杠鈴向上彎向肩膀。", "在頂部停頓片刻，然后慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2133', 'exercise', 1, '{"id": "2133", "target": "quads", "name_en": "farmers walk", "name_zh": "农夫行走", "body_part": "upper legs", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/2133-qPEzJjA.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "農夫行走", "instructions_en": ["Stand up straight with a dumbbell in each hand, palms facing your sides.", "Keep your back straight and your shoulders back.", "Take small, controlled steps forward, maintaining an upright posture.", "Continue walking for the desired distance or time.", "To finish, stop walking and carefully lower the dumbbells to your sides."], "instructions_zh": ["站直，双手各握一个哑铃，手掌朝向身体两侧。", "保持背部挺直，肩膀向后。", "向前迈出小步，控制住，保持直立姿势。", "继续步行所需的距离或时间。", "最后，停止行走并小心地将哑铃降低到身体两侧。"], "secondary_muscles": ["calves", "forearms", "core"], "instructions_zh_hant": ["站直，雙手各握一個啞鈴，手掌朝向身體兩側。", "保持背部挺直，肩膀向后。", "向前邁出小步，控制住，保持直立姿勢。", "繼續步行所需的距離或時間。", "最后，停止行走并小心地將啞鈴降低到身體兩側。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0455', 'exercise', 1, '{"id": "0455", "target": "forearms", "name_en": "finger curls", "name_zh": "手指弯举", "body_part": "lower arms", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0455-awG04cF.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "手指彎舉", "instructions_en": ["Sit on a bench with your feet flat on the ground and hold a barbell with an underhand grip, palms facing up.", "Rest your forearms on your thighs, allowing your wrists to hang off the edge.", "Slowly curl your fingers towards your palms, squeezing the barbell tightly.", "Hold the contraction for a moment, then slowly release your fingers back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双脚平放在地面上，反手握住杠铃，手掌朝上。", "将前臂放在大腿上，让手腕悬在边缘。", "慢慢地将手指向手掌弯曲，紧紧挤压杠铃。", "保持收缩一会儿，然后慢慢松开手指回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["wrist flexors", "grip muscles"], "instructions_zh_hant": ["坐在長凳上，雙腳平放在地面上，反手握住杠鈴，手掌朝上。", "將前臂放在大腿上，讓手腕懸在邊緣。", "慢慢地將手指向手掌彎曲，緊緊擠壓杠鈴。", "保持收縮一會兒，然后慢慢松開手指回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3303', 'exercise', 1, '{"id": "3303", "target": "abs", "name_en": "flag", "name_zh": "旗帜式", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3303-pQ0Mx1Z.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "旗幟式", "instructions_en": ["Start by gripping a vertical pole with both hands, palms facing each other, and arms fully extended.", "Engage your core and lift your legs off the ground, keeping them straight.", "Using your core and upper body strength, raise your legs until they are parallel to the ground.", "Hold this position for as long as you can, maintaining a straight body line.", "Slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先，双手握住一根垂直杆，手掌相对，双臂完全伸展。", "启动你的核心并将双腿抬离地面，保持伸直。", "利用核心和上半身的力量，抬起双腿，直到它们与地面平行。", "尽可能长时间地保持这个姿势，保持身体线条笔直。", "慢慢地将双腿放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["obliques", "shoulders"], "instructions_zh_hant": ["首先，雙手握住一根垂直桿，手掌相對，雙臂完全伸展。", "啟動你的核心并將雙腿抬離地面，保持伸直。", "利用核心和上半身的力量，抬起雙腿，直到它們與地面平行。", "盡可能長時間地保持這個姿勢，保持身體線條筆直。", "慢慢地將雙腿放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3194', 'exercise', 1, '{"id": "3194", "target": "glutes", "name_en": "frankenstein squat", "name_zh": "直腿踢步深蹲", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/3194-bdWcbaU.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "直腿踢步深蹲", "instructions_en": ["Stand with your feet shoulder-width apart and hold the barbell in front of your body with straight arms.", "Keeping your back straight, lower your body by bending at the knees and hips, as if sitting back into a chair.", "Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.", "Pause for a moment, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双臂伸直将杠铃举在身体前方。", "保持背部挺直，弯曲膝盖和臀部，降低身体，就像坐回椅子上一样。", "继续降低，直到大腿与地面平行，或者尽可能低。", "暂停片刻，然后用力推动脚后跟，回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙臂伸直將杠鈴舉在身體前方。", "保持背部挺直，彎曲膝蓋和臀部，降低身體，就像坐回椅子上一樣。", "繼續降低，直到大腿與地面平行，或者盡可能低。", "暫停片刻，然后用力推動腳后跟，回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0456', 'exercise', 1, '{"id": "0456", "target": "abs", "name_en": "flexion leg sit up (bent knee)", "name_zh": "屈膝收腿仰卧起坐", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0456-AR0ig3o.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "屈膝收腿仰臥起坐", "instructions_en": ["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.", "At the same time, lift your legs off the ground, bending your knees and bringing them towards your chest.", "Pause for a moment at the top, then slowly lower your upper body and legs back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，膝盖弯曲，双脚平放在地上。", "将双手放在脑后，肘部朝外。", "收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。", "同时，将双腿抬离地面，弯曲膝盖并将其拉向胸部。", "在顶部停顿片刻，然后慢慢降低上半身和双腿回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["平躺，膝蓋彎曲，雙腳平放在地上。", "將雙手放在腦后，肘部朝外。", "收緊腹肌，慢慢將上半身抬離地面，向前卷曲，直到軀幹呈 45 度角。", "同時，將雙腿抬離地面，彎曲膝蓋并將其拉向胸部。", "在頂部停頓片刻，然后慢慢降低上半身和雙腿回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0458', 'exercise', 1, '{"id": "0458", "target": "pectorals", "name_en": "floor fly (with barbell)", "name_zh": "地板飞鸟（配合杠铃）", "body_part": "chest", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0458-neonEDL.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "地板飛鳥（配合槓鈴）", "instructions_en": ["Lie flat on your back on the floor with your knees bent and feet flat on the ground.", "Hold a barbell with an overhand grip, arms extended straight up over your chest.", "Slowly lower the barbell out to the sides, keeping a slight bend in your elbows.", "Lower the barbell until your arms are parallel to the floor, feeling a stretch in your chest.", "Pause for a moment, then squeeze your chest muscles to bring the barbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["仰卧在地板上，膝盖弯曲，双脚平放在地面上。", "正手握住杠铃，双臂伸直越过胸部。", "慢慢地将杠铃向两侧放低，保持肘部轻微弯曲。", "降低杠铃，直到手臂与地板平行，感觉胸部有拉伸感。", "暂停片刻，然后挤压胸部肌肉，使杠铃回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["deltoids", "triceps"], "instructions_zh_hant": ["仰臥在地板上，膝蓋彎曲，雙腳平放在地面上。", "正手握住杠鈴，雙臂伸直越過胸部。", "慢慢地將杠鈴向兩側放低，保持肘部輕微彎曲。", "降低杠鈴，直到手臂與地板平行，感覺胸部有拉伸感。", "暫停片刻，然后擠壓胸部肌肉，使杠鈴回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0459', 'exercise', 1, '{"id": "0459", "target": "glutes", "name_en": "flutter kicks", "name_zh": "仰卧交替打腿", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0459-UVo2Qs2.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "仰臥交替打腿", "instructions_en": ["Lie flat on your back with your legs extended and your hands by your sides.", "Engage your core and lift your legs off the ground about 6 inches.", "Keeping your legs straight, alternate lifting one leg slightly higher than the other.", "Continue this fluttering motion for the desired number of repetitions."], "instructions_zh": ["平躺，双腿伸展，双手放在身体两侧。", "收紧核心肌群并将双腿抬离地面约 6 英寸。", "保持双腿伸直，交替将一条腿抬得比另一条腿稍高。", "继续这个颤动动作达到所需的重复次数。"], "secondary_muscles": ["hip flexors", "lower abs"], "instructions_zh_hant": ["平躺，雙腿伸展，雙手放在身體兩側。", "收緊核心肌群并將雙腿抬離地面約 6 英寸。", "保持雙腿伸直，交替將一條腿抬得比另一條腿稍高。", "繼續這個顫動動作達到所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1472', 'exercise', 1, '{"id": "1472", "target": "quads", "name_en": "forward jump", "name_zh": "向前跳跃", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1472-uZKq7lo.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "向前跳躍", "instructions_en": ["Stand with your feet shoulder-width apart.", "Bend your knees and lower your body into a squat position.", "Swing your arms back for momentum.", "Jump forward explosively, extending your hips, knees, and ankles.", "Land softly on the balls of your feet and immediately go into the next jump.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立。", "弯曲膝盖并将身体降低至蹲姿。", "向后摆动手臂以获得动力。", "爆发性地向前跳跃，伸展臀部、膝盖和脚踝。", "脚掌轻轻落地，然后立即进入下一个跳跃。", "重复所需的重复次数。"], "secondary_muscles": ["calves", "hamstrings", "glutes"], "instructions_zh_hant": ["雙腳分開與肩同寬站立。", "彎曲膝蓋并將身體降低至蹲姿。", "向后擺動手臂以獲得動力。", "爆發性地向前跳躍，伸展臀部、膝蓋和腳踝。", "腳掌輕輕落地，然后立即進入下一個跳躍。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3470', 'exercise', 1, '{"id": "3470", "target": "glutes", "name_en": "forward lunge (male)", "name_zh": "向前弓步（男性示范）", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3470-kMzUs9Y.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "向前弓步（男性示范）", "instructions_en": ["Stand with your feet hip-width apart and hands on your hips.", "Take a big step forward with your right foot, lowering your body into a lunge position.", "Bend your right knee to about 90 degrees, keeping your knee aligned with your ankle.", "Push off with your right foot and return to the starting position.", "Repeat with your left leg, alternating sides for the desired number of repetitions."], "instructions_zh": ["站立，双脚分开与臀部同宽，双手放在臀部。", "右脚向前迈出一大步，将身体降低到弓步位置。", "将右膝盖弯曲约 90 度，保持膝盖与脚踝对齐。", "用右脚推出并返回到起始位置。", "用左腿重复上述动作，交替进行所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["站立，雙腳分開與臀部同寬，雙手放在臀部。", "右腳向前邁出一大步，將身體降低到弓步位置。", "將右膝蓋彎曲約 90 度，保持膝蓋與腳踝對齊。", "用右腳推出并返回到起始位置。", "用左腿重復上述動作，交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2429', 'exercise', 1, '{"id": "2429", "target": "abs", "name_en": "frog crunch", "name_zh": "蛙式卷腹", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/2429-FFRP97T.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "蛙式卷腹", "instructions_en": ["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，膝盖弯曲，双脚平放在地上。", "将双手放在脑后，肘部朝外。", "收紧腹肌，将上半身抬离地面，向前卷曲直到躯干呈 45 度角。", "在顶部停顿片刻，然后慢慢将上半身放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["平躺，膝蓋彎曲，雙腳平放在地上。", "將雙手放在腦后，肘部朝外。", "收緊腹肌，將上半身抬離地面，向前卷曲直到軀幹呈 45 度角。", "在頂部停頓片刻，然后慢慢將上半身放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3301', 'exercise', 1, '{"id": "3301", "target": "abs", "name_en": "frog planche", "name_zh": "蛙式俄式挺身", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3301-rQhGcin.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "蛙式俄式挺身", "instructions_en": ["Start in a push-up position with your hands shoulder-width apart and your feet together.", "Bend your elbows and lower your body towards the ground, keeping your back straight.", "As you lower your body, lift your feet off the ground and bring your knees towards your chest.", "Hold this position for a few seconds, then extend your legs back out and push yourself back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["从俯卧撑位置开始，双手与肩同宽，双脚并拢。", "弯曲肘部，将身体放低至地面，保持背部挺直。", "当你降低身体时，将双脚抬离地面，并将膝盖靠近胸部。", "保持这个姿势几秒钟，然后向后伸展双腿，并将自己推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "chest", "triceps"], "instructions_zh_hant": ["從俯臥撐位置開始，雙手與肩同寬，雙腳并攏。", "彎曲肘部，將身體放低至地面，保持背部挺直。", "當你降低身體時，將雙腳抬離地面，并將膝蓋靠近胸部。", "保持這個姿勢幾秒鐘，然后向后伸展雙腿，并將自己推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3296', 'exercise', 1, '{"id": "3296", "target": "abs", "name_en": "front lever", "name_zh": "前水平", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3296-PkCN2lv.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "前水平", "instructions_en": ["Start by hanging from a pull-up bar with an overhand grip, hands shoulder-width apart.", "Engage your core and pull your shoulder blades down and back.", "Bend your knees and tuck them towards your chest.", "Simultaneously, lift your legs up and extend them straight out in front of you, keeping your body parallel to the ground.", "Hold this position for as long as you can, aiming for a full front lever position.", "To release, slowly lower your legs back down and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先，用正手握法悬挂在引体向上杆上，双手与肩同宽。", "启动你的核心并将肩胛骨向下拉和向后拉。", "弯曲膝盖并将其向胸部靠拢。", "同时，抬起双腿并将其伸直在您面前，保持身体与地面平行。", "尽可能长时间地保持此位置，以达到完全前杆位置。", "要释放，请慢慢降低双腿并返回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["lats", "shoulders", "forearms"], "instructions_zh_hant": ["首先，用正手握法懸掛在引體向上桿上，雙手與肩同寬。", "啟動你的核心并將肩胛骨向下拉和向后拉。", "彎曲膝蓋并將其向胸部靠攏。", "同時，抬起雙腿并將其伸直在您面前，保持身體與地面平行。", "盡可能長時間地保持此位置，以達到完全前桿位置。", "要釋放，請慢慢降低雙腿并返回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3295', 'exercise', 1, '{"id": "3295", "target": "upper back", "name_en": "front lever reps", "name_zh": "动态前水平", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3295-hbY9wqG.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "動態前水平", "instructions_en": ["Hang from a pull-up bar with an overhand grip, palms facing away from you.", "Engage your core and pull your shoulder blades down and back.", "Keeping your body straight, lift your legs up until they are parallel to the ground.", "Hold this position for as long as you can, aiming for 10-20 seconds.", "Slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["正手握住引体向上杆，手掌背向自己。", "启动你的核心并将肩胛骨向下拉和向后拉。", "保持身体挺直，抬起双腿直至与地面平行。", "尽可能长时间地保持这个姿势，目标是 10-20 秒。", "慢慢地将双腿放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["core", "shoulders"], "instructions_zh_hant": ["正手握住引體向上桿，手掌背向自己。", "啟動你的核心并將肩胛骨向下拉和向后拉。", "保持身體挺直，抬起雙腿直至與地面平行。", "盡可能長時間地保持這個姿勢，目標是 10-20 秒。", "慢慢地將雙腿放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0464', 'exercise', 1, '{"id": "0464", "target": "abs", "name_en": "front plank with twist", "name_zh": "前平板支撑配合转体", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0464-CosupLu.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "前平板支撐配合轉體", "instructions_en": ["Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.", "Engage your core and glutes to maintain a stable position.", "Rotate your torso to the right, lifting your right arm and extending it towards the ceiling.", "Keep your hips and legs stable as you twist.", "Hold for a moment, then return to the starting position.", "Repeat the twist on the left side.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["从高平板支撑位置开始，双手直接放在肩膀下方，身体从头到脚成一条直线。", "调动你的核心和臀部以保持稳定的位置。", "将躯干向右旋转，抬起右臂并向天花板延伸。", "扭转时保持臀部和腿部稳定。", "保持片刻，然后回到起始位置。", "在左侧重复扭转。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["obliques", "shoulders"], "instructions_zh_hant": ["從高平板支撐位置開始，雙手直接放在肩膀下方，身體從頭到腳成一條直線。", "調動你的核心和臀部以保持穩定的位置。", "將軀幹向右旋轉，抬起右臂并向天花板延伸。", "扭轉時保持臀部和腿部穩定。", "保持片刻，然后回到起始位置。", "在左側重復扭轉。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3315', 'exercise', 1, '{"id": "3315", "target": "abs", "name_en": "full maltese", "name_zh": "全程马耳他十字", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3315-YRaCa5Y.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "全程馬耳他十字", "instructions_en": ["Start by standing with your feet shoulder-width apart and your arms extended straight out to the sides.", "Slowly lean forward, keeping your arms straight, until your upper body is parallel to the ground.", "Engage your core and hold this position for a few seconds.", "Return to the starting position by pushing through your feet and standing back up.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先站立，双脚分开与肩同宽，双臂伸直至两侧。", "慢慢向前倾斜，保持手臂伸直，直到上半身与地面平行。", "启动你的核心并保持这个姿势几秒钟。", "通过双脚推动并站起来，回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "chest"], "instructions_zh_hant": ["首先站立，雙腳分開與肩同寬，雙臂伸直至兩側。", "慢慢向前傾斜，保持手臂伸直，直到上半身與地面平行。", "啟動你的核心并保持這個姿勢幾秒鐘。", "通過雙腳推動并站起來，回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3299', 'exercise', 1, '{"id": "3299", "target": "abs", "name_en": "full planche", "name_zh": "全程俄式挺身", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3299-YZ4961r.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "全程俄式挺身", "instructions_en": ["Start in a push-up position with your hands shoulder-width apart and your fingers pointing forward.", "Engage your core and slowly shift your weight forward, lifting your feet off the ground.", "Continue shifting your weight forward until your body is parallel to the ground, balancing on your hands.", "Hold this position for as long as you can, maintaining a straight body line.", "Slowly lower your feet back to the ground and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["从俯卧撑位置开始，双手与肩同宽，手指指向前方。", "启动你的核心并缓慢地将你的重心向前移动，将你的脚抬离地面。", "继续向前移动体重，直到身体与地面平行，并用双手保持平衡。", "尽可能长时间地保持这个姿势，保持身体线条笔直。", "慢慢地将双脚放回地面，然后回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "chest", "triceps"], "instructions_zh_hant": ["從俯臥撐位置開始，雙手與肩同寬，手指指向前方。", "啟動你的核心并緩慢地將你的重心向前移動，將你的腳抬離地面。", "繼續向前移動體重，直到身體與地面平行，并用雙手保持平衡。", "盡可能長時間地保持這個姿勢，保持身體線條筆直。", "慢慢地將雙腳放回地面，然后回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3327', 'exercise', 1, '{"id": "3327", "target": "pectorals", "name_en": "full planche push-up", "name_zh": "全程俄式挺身俯卧撑", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3327-gw9PqGk.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "全程俄式挺身俯臥撐", "instructions_en": ["Start in a push-up position with your hands placed slightly wider than shoulder-width apart.", "Engage your core and lower your body down towards the ground, keeping your elbows close to your sides.", "As you lower yourself, lean your body forward and lift your feet off the ground, balancing on your hands.", "Continue to lower your body until your chest is just above the ground.", "Push through your hands and extend your arms to lift your body back up to the starting position.", "Maintain a straight line from your head to your heels throughout the movement.", "Repeat for the desired number of repetitions."], "instructions_zh": ["从俯卧撑位置开始，双手分开略宽于肩宽。", "收紧核心肌群，将身体放低至地面，保持肘部靠近身体两侧。", "当你降低身体高度时，身体向前倾斜，双脚离开地面，用双手保持平衡。", "继续降低身体，直到胸部略高于地面。", "用手推动并伸展双臂，将身体抬回到起始位置。", "在整个运动过程中，从头部到脚后跟保持一条直线。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps", "core"], "instructions_zh_hant": ["從俯臥撐位置開始，雙手分開略寬于肩寬。", "收緊核心肌群，將身體放低至地面，保持肘部靠近身體兩側。", "當你降低身體高度時，身體向前傾斜，雙腳離開地面，用雙手保持平衡。", "繼續降低身體，直到胸部略高于地面。", "用手推動并伸展雙臂，將身體抬回到起始位置。", "在整個運動過程中，從頭部到腳后跟保持一條直線。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0466', 'exercise', 1, '{"id": "0466", "target": "lats", "name_en": "gironda sternum chin", "name_zh": "吉隆达触胸引体向上", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0466-IL0JUxR.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "吉隆達觸胸引體向上", "instructions_en": ["Stand facing a high bar with your feet shoulder-width apart.", "Reach up and grab the bar with an overhand grip, slightly wider than shoulder-width apart.", "Hang from the bar with your arms fully extended and your body straight.", "Engage your lats and biceps to pull your chest up towards the bar, leading with your sternum.", "Pause for a moment at the top, then slowly lower yourself back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["面向高杠站立，双脚分开与肩同宽。", "向上伸手，正手握住杠铃，握距略宽于肩宽。", "悬挂在杠上，双臂完全伸展，身体伸直。", "用你的背阔肌和二头肌将你的胸部拉向杠铃杆，以胸骨为主导。", "在最高点暂停片刻，然后慢慢降低回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "rhomboids", "rear deltoids"], "instructions_zh_hant": ["面向高杠站立，雙腳分開與肩同寬。", "向上伸手，正手握住杠鈴，握距略寬于肩寬。", "懸掛在杠上，雙臂完全伸展，身體伸直。", "用你的背闊肌和二頭肌將你的胸部拉向杠鈴桿，以胸骨為主導。", "在最高點暫停片刻，然后慢慢降低回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3561', 'exercise', 1, '{"id": "3561", "target": "glutes", "name_en": "glute bridge march", "name_zh": "臀桥踏步", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3561-GibBPPg.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "臀橋踏步", "instructions_en": ["Lie flat on your back with your knees bent and feet flat on the ground.", "Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.", "While keeping your hips lifted, lift one foot off the ground and bring your knee towards your chest.", "Lower your foot back to the ground and repeat the movement with the other leg.", "Continue alternating legs in a marching motion while maintaining the bridge position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，膝盖弯曲，双脚平放在地上。", "收紧臀部并将臀部抬离地面，从膝盖到肩膀形成一条直线。", "在保持臀部抬起的同时，将一只脚抬离地面，并将膝盖靠近胸部。", "将脚放回地面，然后用另一条腿重复该动作。", "继续交替双腿进行行进动作，同时保持桥式姿势。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "quadriceps"], "instructions_zh_hant": ["平躺，膝蓋彎曲，雙腳平放在地上。", "收緊臀部并將臀部抬離地面，從膝蓋到肩膀形成一條直線。", "在保持臀部抬起的同時，將一只腳抬離地面，并將膝蓋靠近胸部。", "將腳放回地面，然后用另一條腿重復該動作。", "繼續交替雙腿進行行進動作，同時保持橋式姿勢。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3523', 'exercise', 1, '{"id": "3523", "target": "glutes", "name_en": "glute bridge two legs on bench (male)", "name_zh": "凳上垫脚臀桥（男性示范）", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3523-aWedzZX.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "凳上墊腳臀橋（男性示范）", "instructions_en": ["Sit on the edge of a bench with your back against it and your feet flat on the ground.", "Place your hands on the bench beside your hips for support.", "Engage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders.", "Pause for a moment at the top, then slowly lower your hips back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳边缘，背靠着长凳，双脚平放在地上。", "将双手放在臀部旁边的长凳上以获得支撑。", "收紧臀肌和腿筋，然后将臀部抬离长凳，直到身体从膝盖到肩膀形成一条直线。", "在顶部暂停片刻，然后慢慢将臀部放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "core"], "instructions_zh_hant": ["坐在長凳邊緣，背靠著長凳，雙腳平放在地上。", "將雙手放在臀部旁邊的長凳上以獲得支撐。", "收緊臀肌和腿筋，然后將臀部抬離長凳，直到身體從膝蓋到肩膀形成一條直線。", "在頂部暫停片刻，然后慢慢將臀部放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3193', 'exercise', 1, '{"id": "3193", "target": "hamstrings", "name_en": "glute-ham raise", "name_zh": "臀腿挺身", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3193-Vvwjz6N.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "臀腿挺身", "instructions_en": ["Adjust the glute-ham raise machine to fit your body.", "Position yourself face down on the machine with your ankles secured.", "Place your hands on your chest or cross them over your chest.", "Engage your hamstrings and glutes to lift your upper body up towards the ceiling.", "Continue lifting until your body is in a straight line from your head to your heels.", "Pause for a moment at the top, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整臀肌提升机以适合您的身体。", "将自己面朝下放在机器上，固定脚踝。", "将双手放在胸前或交叉在胸前。", "调动腿筋和臀肌，将上半身抬向天花板。", "继续抬起，直到身体从头部到脚后跟成一条直线。", "在顶部停顿片刻，然后慢慢将身体放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "lower back"], "instructions_zh_hant": ["調整臀肌提升機以適合您的身體。", "將自己面朝下放在機器上，固定腳踝。", "將雙手放在胸前或交叉在胸前。", "調動腿筋和臀肌，將上半身抬向天花板。", "繼續抬起，直到身體從頭部到腳后跟成一條直線。", "在頂部停頓片刻，然后慢慢將身體放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0467', 'exercise', 1, '{"id": "0467", "target": "abs", "name_en": "gorilla chin", "name_zh": "大猩猩式引体向上", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0467-bmwlYvD.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "大猩猩式引體向上", "instructions_en": ["Stand with your feet shoulder-width apart and your knees slightly bent.", "Grasp a pull-up bar with an overhand grip, slightly wider than shoulder-width apart.", "Hang from the bar with your arms fully extended and your palms facing away from you.", "Engage your core and pull your body up towards the bar, bringing your chin above the bar.", "Pause for a moment at the top, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，膝盖稍微弯曲。", "正手握住引体向上杆，握距略宽于肩宽。", "悬挂在杠上，双臂完全伸展，手掌背向自己。", "收紧核心肌群，将身体拉向杠铃杆，将下巴置于杠铃上方。", "在顶部停顿片刻，然后慢慢将身体放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms", "biceps"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，膝蓋稍微彎曲。", "正手握住引體向上桿，握距略寬于肩寬。", "懸掛在杠上，雙臂完全伸展，手掌背向自己。", "收緊核心肌群，將身體拉向杠鈴桿，將下巴置于杠鈴上方。", "在頂部停頓片刻，然后慢慢將身體放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0469', 'exercise', 1, '{"id": "0469", "target": "abs", "name_en": "groin crunch", "name_zh": "腹股沟卷腹", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0469-mWppALS.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "腹股溝卷腹", "instructions_en": ["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, lift your legs off the ground, bringing your knees towards your chest.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，膝盖弯曲，双脚平放在地上。", "将双手放在脑后，肘部朝外。", "收紧腹肌，将双腿抬离地面，将膝盖靠近胸部。", "在顶部暂停片刻，然后慢慢将双腿放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors", "inner thighs"], "instructions_zh_hant": ["平躺，膝蓋彎曲，雙腳平放在地上。", "將雙手放在腦后，肘部朝外。", "收緊腹肌，將雙腿抬離地面，將膝蓋靠近胸部。", "在頂部暫停片刻，然后慢慢將雙腿放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1383', 'exercise', 1, '{"id": "1383", "target": "calves", "name_en": "hack calf raise", "name_zh": "哈克式提踵", "body_part": "lower legs", "equipment": "sled machine", "gif_asset": "assets/fitness/videos/1383-2ORFMoR.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "哈克式提踵", "instructions_en": ["Adjust the sled machine to a comfortable weight.", "Stand on the sled machine with your toes on the platform and your heels hanging off.", "Hold onto the handles for stability.", "Raise your heels as high as possible by pushing through the balls of your feet.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将雪橇机调整至舒适的重量。", "站在雪橇机上，脚趾放在平台上，脚后跟悬空。", "握住手柄以保持稳定性。", "通过推动脚掌将脚后跟尽可能抬高。", "在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "glutes"], "instructions_zh_hant": ["將雪橇機調整至舒適的重量。", "站在雪橇機上，腳趾放在平臺上，腳后跟懸空。", "握住手柄以保持穩定性。", "通過推動腳掌將腳后跟盡可能抬高。", "在頂部停頓片刻，然后慢慢降低腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1384', 'exercise', 1, '{"id": "1384", "target": "calves", "name_en": "hack one leg calf raise", "name_zh": "哈克式单腿提踵", "body_part": "lower legs", "equipment": "sled machine", "gif_asset": "assets/fitness/videos/1384-AxFoqAD.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "哈克式單腿提踵", "instructions_en": ["Adjust the sled machine to an appropriate weight.", "Stand on the sled machine with one foot, keeping the other foot off the ground.", "Hold onto the handles for stability.", "Raise your heel as high as possible, lifting your body up on the ball of your foot.", "Pause for a moment at the top, then slowly lower your heel back down to the starting position.", "Repeat for the desired number of repetitions.", "Switch legs and repeat the exercise."], "instructions_zh": ["将雪橇机调整到合适的重量。", "一脚站在雪橇机上，另一只脚离开地面。", "握住手柄以保持稳定性。", "尽可能高地抬高脚跟，用脚掌抬起身体。", "在顶部暂停片刻，然后慢慢将脚跟放回起始位置。", "重复所需的重复次数。", "换腿并重复练习。"], "secondary_muscles": ["hamstrings", "glutes"], "instructions_zh_hant": ["將雪橇機調整到合適的重量。", "一腳站在雪橇機上，另一只腳離開地面。", "握住手柄以保持穩定性。", "盡可能高地抬高腳跟，用腳掌抬起身體。", "在頂部暫停片刻，然后慢慢將腳跟放回起始位置。", "重復所需的重復次數。", "換腿并重復練習。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3221', 'exercise', 1, '{"id": "3221", "target": "cardiovascular system", "name_en": "half knee bends (male)", "name_zh": "半程膝部屈曲（男性示范）", "body_part": "cardio", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3221-ia6kIIl.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "半程膝部屈曲（男性示范）", "instructions_en": ["Stand with your feet shoulder-width apart.", "Bend your knees and lower your body down as if you were sitting back into a chair.", "Keep your chest up and your weight in your heels.", "Pause for a moment at the bottom, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立。", "弯曲膝盖并降低身体，就像坐回椅子上一样。", "保持挺胸，将体重放在脚后跟上。", "在底部停顿片刻，然后推动脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "glutes"], "instructions_zh_hant": ["雙腳分開與肩同寬站立。", "彎曲膝蓋并降低身體，就像坐回椅子上一樣。", "保持挺胸，將體重放在腳后跟上。", "在底部停頓片刻，然后推動腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3202', 'exercise', 1, '{"id": "3202", "target": "abs", "name_en": "half sit-up (male)", "name_zh": "半程仰卧起坐（男性示范）", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3202-iQ241UP.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "半程仰臥起坐（男性示范）", "instructions_en": ["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，膝盖弯曲，双脚平放在地上。", "将双手放在脑后，肘部朝外。", "收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。", "在顶部停顿片刻，然后慢慢将上半身放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["平躺，膝蓋彎曲，雙腳平放在地上。", "將雙手放在腦后，肘部朝外。", "收緊腹肌，慢慢將上半身抬離地面，向前卷曲，直到軀幹呈 45 度角。", "在頂部停頓片刻，然后慢慢將上半身放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1511', 'exercise', 1, '{"id": "1511", "target": "hamstrings", "name_en": "hamstring stretch", "name_zh": "腘绳肌拉伸", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1511-99rWm7w.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "腘繩肌拉伸", "instructions_en": ["Stand with your feet shoulder-width apart.", "Step forward with your right foot and shift your weight onto your right leg.", "Keeping your back straight, slowly bend forward at the hips, reaching towards your right foot with both hands.", "Hold the stretch for 20-30 seconds, then return to the starting position.", "Repeat on the other side."], "instructions_zh": ["双脚分开与肩同宽站立。", "右脚向前迈出一步，将重心转移到右腿上。", "保持背部挺直，臀部慢慢向前弯曲，双手伸向右脚。", "保持伸展动作 20-30 秒，然后回到起始位置。", "在另一侧重复。"], "secondary_muscles": ["glutes"], "instructions_zh_hant": ["雙腳分開與肩同寬站立。", "右腳向前邁出一步，將重心轉移到右腿上。", "保持背部挺直，臀部慢慢向前彎曲，雙手伸向右腳。", "保持伸展動作 20-30 秒，然后回到起始位置。", "在另一側重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2139', 'exercise', 1, '{"id": "2139", "target": "pectorals", "name_en": "hands bike", "name_zh": "手摇自行车", "body_part": "chest", "equipment": "upper body ergometer", "gif_asset": "assets/fitness/videos/2139-pAIWRGu.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "手搖自行車", "instructions_en": ["Adjust the seat height and handlebar position to a comfortable level.", "Sit on the ergometer with your back straight and feet on the pedals.", "Grasp the handles with your hands and position your arms at a 90-degree angle.", "Start pedaling with your hands, pushing and pulling the handles in a controlled motion.", "Continue pedaling for the desired duration or number of repetitions."], "instructions_zh": ["将座椅高度和车把位置调整至舒适的水平。", "坐在测力计上，背部挺直，双脚放在踏板上。", "双手抓住手柄，并将手臂呈 90 度角。", "开始用手踩踏板，以受控的动作推拉手柄。", "继续踩踏所需的持续时间或重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["將座椅高度和車把位置調整至舒適的水平。", "坐在測力計上，背部挺直，雙腳放在踏板上。", "雙手抓住手柄，并將手臂呈 90 度角。", "開始用手踩踏板，以受控的動作推拉手柄。", "繼續踩踏所需的持續時間或重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3218', 'exercise', 1, '{"id": "3218", "target": "glutes", "name_en": "hands clasped circular toe touch (male)", "name_zh": "双手交握绕环触脚尖（男性示范）", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3218-B5xca8s.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "雙手交握繞環觸腳尖（男性示范）", "instructions_en": ["Stand with your feet shoulder-width apart and your hands clasped together in front of your chest.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Lower your hands towards your toes in a circular motion, reaching as far as you can without straining.", "Pause for a moment at the bottom, then slowly return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手合十放在胸前。", "稍微弯曲膝盖，髋部向前转动，保持背部挺直。", "将双手向脚趾方向以打圈的方式降低，尽量伸得尽可能远，但不要用力。", "在底部停顿片刻，然后慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "quadriceps", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手合十放在胸前。", "稍微彎曲膝蓋，髖部向前轉動，保持背部挺直。", "將雙手向腳趾方向以打圈的方式降低，盡量伸得盡可能遠，但不要用力。", "在底部停頓片刻，然后慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1761', 'exercise', 1, '{"id": "1761", "target": "abs", "name_en": "hanging oblique knee raise", "name_zh": "悬垂腹斜肌提膝", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1761-BaE7O6U.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "懸垂腹斜肌提膝", "instructions_en": ["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.", "Engage your core and lift your knees towards your chest, twisting your torso to the side as you do so.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat on the other side, twisting your torso in the opposite direction.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。", "收紧核心并将膝盖抬向胸部，同时将躯干扭转到一侧。", "在顶部暂停片刻，然后慢慢将双腿放回起始位置。", "在另一侧重复上述步骤，向相反方向扭转躯干。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["obliques"], "instructions_zh_hant": ["懸掛在引體向上桿上，雙臂完全伸展，手掌背向自己。", "收緊核心并將膝蓋抬向胸部，同時將軀幹扭轉到一側。", "在頂部暫停片刻，然后慢慢將雙腿放回起始位置。", "在另一側重復上述步驟，向相反方向扭轉軀幹。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3215', 'exercise', 1, '{"id": "3215", "target": "glutes", "name_en": "hands reversed clasped circular toe touch (male)", "name_zh": "双手反向交握绕环触脚尖（男性示范）", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3215-yq3GAJX.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "雙手反向交握繞環觸腳尖（男性示范）", "instructions_en": ["Stand with your feet shoulder-width apart and your arms extended to the sides.", "Bend forward at the waist, keeping your back straight and your knees slightly bent.", "Reach down with your hands and clasp them together behind your legs.", "Slowly raise your hands up and over your head in a circular motion, keeping your legs straight.", "Continue the circular motion until your hands touch your toes.", "Reverse the motion and bring your hands back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双臂向两侧伸展。", "腰部向前弯曲，保持背部挺直，膝盖稍微弯曲。", "双手向下伸，并在腿后将它们握在一起。", "慢慢地将双手举过头顶，做圆周运动，保持双腿伸直。", "继续圆周运动，直到双手触及脚趾。", "反转动作并将双手放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "quadriceps", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙臂向兩側伸展。", "腰部向前彎曲，保持背部挺直，膝蓋稍微彎曲。", "雙手向下伸，并在腿后將它們握在一起。", "慢慢地將雙手舉過頭頂，做圓周運動，保持雙腿伸直。", "繼續圓周運動，直到雙手觸及腳趾。", "反轉動作并將雙手放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3302', 'exercise', 1, '{"id": "3302", "target": "triceps", "name_en": "handstand", "name_zh": "倒立", "body_part": "upper arms", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3302-XooAdhl.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "倒立", "instructions_en": ["Find an open space with enough room to perform a handstand.", "Place your hands on the ground shoulder-width apart, fingers pointing forward.", "Kick your legs up towards the wall, using your core and shoulders to maintain balance.", "Once in a handstand position, engage your triceps to support your body weight.", "Hold the handstand for as long as you can maintain balance.", "To come down, slowly lower your legs back to the ground.", "Repeat for the desired number of repetitions."], "instructions_zh": ["找到一个有足够空间的空地来进行倒立。", "将双手放在地上，与肩同宽，手指指向前方。", "将双腿向上踢向墙壁，用核心和肩膀保持平衡。", "处于倒立位置后，用三头肌来支撑体重。", "只要能保持平衡，就保持倒立。", "下降时，慢慢将双腿放回地面。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "core"], "instructions_zh_hant": ["找到一個有足夠空間的空地來進行倒立。", "將雙手放在地上，與肩同寬，手指指向前方。", "將雙腿向上踢向墻壁，用核心和肩膀保持平衡。", "處于倒立位置后，用三頭肌來支撐體重。", "只要能保持平衡，就保持倒立。", "下降時，慢慢將雙腿放回地面。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0471', 'exercise', 1, '{"id": "0471", "target": "triceps", "name_en": "handstand push-up", "name_zh": "倒立俯卧撑", "body_part": "upper arms", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0471-rQxwMxO.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "倒立俯臥撐", "instructions_en": ["Find a wall and face away from it, standing a few feet away.", "Place your hands on the ground shoulder-width apart and kick your feet up against the wall, coming into a handstand position.", "Bend your elbows and lower your head towards the ground, keeping your body in a straight line.", "Push through your hands and extend your arms to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["找到一堵墙，背对墙，站在几英尺远的地方。", "将双手放在地面上，与肩同宽，然后将脚踢到墙上，形成倒立姿势。", "弯曲肘部，将头低向地面，保持身体呈一条直线。", "用手推动并伸展双臂以返回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "chest", "core"], "instructions_zh_hant": ["找到一堵墻，背對墻，站在幾英尺遠的地方。", "將雙手放在地面上，與肩同寬，然后將腳踢到墻上，形成倒立姿勢。", "彎曲肘部，將頭低向地面，保持身體呈一條直線。", "用手推動并伸展雙臂以返回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1764', 'exercise', 1, '{"id": "1764", "target": "abs", "name_en": "hanging leg hip raise", "name_zh": "悬垂举腿提髋", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1764-VEcJRo2.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "懸垂舉腿提髖", "instructions_en": ["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.", "Engage your core and lift your legs up by flexing your hips and knees until your thighs are parallel to the ground.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。", "弯曲臀部和膝盖，收紧核心并抬起双腿，直到大腿与地面平行。", "在顶部暂停片刻，然后慢慢将双腿放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors", "lower back"], "instructions_zh_hant": ["懸掛在引體向上桿上，雙臂完全伸展，手掌背向自己。", "彎曲臀部和膝蓋，收緊核心并抬起雙腿，直到大腿與地面平行。", "在頂部暫停片刻，然后慢慢將雙腿放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0473', 'exercise', 1, '{"id": "0473", "target": "abs", "name_en": "hanging pike", "name_zh": "悬垂折髋", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0473-nuBF9MO.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "懸垂折髖", "instructions_en": ["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.", "Engage your core and lift your legs up towards the bar, keeping them straight.", "Continue lifting until your body forms a ''V'' shape, with your legs parallel to the ground.", "Hold the position for a moment, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。", "收紧核心肌群，将双腿向杠铃方向抬起，保持伸直。", "继续抬起身体，直到身体形成“V”形，双腿与地面平行。", "保持该姿势片刻，然后慢慢将双腿放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors", "shoulders"], "instructions_zh_hant": ["懸掛在引體向上桿上，雙臂完全伸展，手掌背向自己。", "收緊核心肌群，將雙腿向杠鈴方向抬起，保持伸直。", "繼續抬起身體，直到身體形成“V”形，雙腿與地面平行。", "保持該姿勢片刻，然后慢慢將雙腿放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0474', 'exercise', 1, '{"id": "0474", "target": "abs", "name_en": "hanging straight leg hip raise", "name_zh": "悬垂直腿提髋", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0474-pj0X0tF.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "懸垂直腿提髖", "instructions_en": ["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.", "Engage your core and lift your legs up in front of you until they are parallel to the ground.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。", "启动你的核心并将双腿抬起到你面前，直到它们与地面平行。", "在顶部暂停片刻，然后慢慢将双腿放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["懸掛在引體向上桿上，雙臂完全伸展，手掌背向自己。", "啟動你的核心并將雙腿抬起到你面前，直到它們與地面平行。", "在頂部暫停片刻，然后慢慢將雙腿放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0475', 'exercise', 1, '{"id": "0475", "target": "abs", "name_en": "hanging straight leg raise", "name_zh": "悬垂直腿举腿", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0475-4Ml7QFO.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "懸垂直腿舉腿", "instructions_en": ["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.", "Engage your core and lift your legs up in front of you, keeping them straight.", "Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。", "启动你的核心并将双腿抬起到你面前，保持伸直。", "继续抬起，直到双腿与地面平行或达到您可以舒适地达到的高度。", "在顶部暂停片刻，然后慢慢将双腿放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["懸掛在引體向上桿上，雙臂完全伸展，手掌背向自己。", "啟動你的核心并將雙腿抬起到你面前，保持伸直。", "繼續抬起，直到雙腿與地面平行或達到您可以舒適地達到的高度。", "在頂部暫停片刻，然后慢慢將雙腿放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0476', 'exercise', 1, '{"id": "0476", "target": "abs", "name_en": "hanging straight twisting leg hip raise", "name_zh": "悬垂直腿转体提髋", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0476-Q6bvyen.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "懸垂直腿轉體提髖", "instructions_en": ["Hang from a pull-up bar with your arms fully extended and your legs straight.", "Engage your core and lift your legs up towards your chest, keeping them straight.", "Once your legs are parallel to the ground, twist your hips to one side, bringing your legs towards that side.", "Pause for a moment, then return to the starting position.", "Repeat the movement, but this time twist your hips to the opposite side.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["悬挂在引体向上杆上，双臂完全伸展，双腿伸直。", "启动你的核心并将双腿抬向胸部，保持伸直。", "一旦双腿与地面平行，将臀部向一侧扭转，将双腿移向一侧。", "暂停片刻，然后回到起始位置。", "重复这个动作，但这次将臀部扭向另一侧。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["obliques", "hip flexors"], "instructions_zh_hant": ["懸掛在引體向上桿上，雙臂完全伸展，雙腿伸直。", "啟動你的核心并將雙腿抬向胸部，保持伸直。", "一旦雙腿與地面平行，將臀部向一側扭轉，將雙腿移向一側。", "暫停片刻，然后回到起始位置。", "重復這個動作，但這次將臀部扭向另一側。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0489', 'exercise', 1, '{"id": "0489", "target": "spine", "name_en": "hyperextension", "name_zh": "挺身", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0489-zhMwOwE.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "挺身", "instructions_en": ["Adjust the hyperextension bench so that your upper thighs are resting on the pad and your feet are secured.", "Cross your arms over your chest or place your hands behind your head.", "Lower your upper body towards the ground while keeping your back straight.", "Pause for a moment at the bottom, then raise your upper body back up until it is in line with your legs.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整过度伸展凳，使大腿上部放在垫子上并且双脚固定。", "双臂交叉放在胸前或将双手放在脑后。", "将上半身压向地面，同时保持背部挺直。", "在底部停顿片刻，然后抬起上半身，直到与双腿成一直线。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings"], "instructions_zh_hant": ["調整過度伸展凳，使大腿上部放在墊子上并且雙腳固定。", "雙臂交叉放在胸前或將雙手放在腦后。", "將上半身壓向地面，同時保持背部挺直。", "在底部停頓片刻，然后抬起上半身，直到與雙腿成一直線。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3636', 'exercise', 1, '{"id": "3636", "target": "cardiovascular system", "name_en": "high knee against wall", "name_zh": "扶墙高抬腿", "body_part": "cardio", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3636-ealLwvX.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "扶墻高抬腿", "instructions_en": ["Stand facing a wall with your feet hip-width apart.", "Place your hands on the wall for support.", "Engage your core and lift your right knee up towards your chest, while keeping your left foot on the ground.", "Quickly switch legs, bringing your left knee up towards your chest and lowering your right foot back down.", "Continue alternating legs in a running motion, bringing your knees up as high as possible.", "Maintain a fast pace and keep your upper body stable throughout the exercise.", "Repeat for the desired duration or number of repetitions."], "instructions_zh": ["面向墙壁站立，双脚分开与臀部同宽。", "将双手放在墙上以获得支撑。", "启动你的核心并将右膝抬向胸部，同时将左脚保持在地面上。", "快速换腿，将左膝抬向胸部，然后将右脚放低。", "继续交替双腿进行跑步动作，将膝盖尽可能抬高。", "在整个练习过程中保持快节奏并保持上半身稳定。", "重复所需的持续时间或重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "glutes", "calves"], "instructions_zh_hant": ["面向墻壁站立，雙腳分開與臀部同寬。", "將雙手放在墻上以獲得支撐。", "啟動你的核心并將右膝抬向胸部，同時將左腳保持在地面上。", "快速換腿，將左膝抬向胸部，然后將右腳放低。", "繼續交替雙腿進行跑步動作，將膝蓋盡可能抬高。", "在整個練習過程中保持快節奏并保持上半身穩定。", "重復所需的持續時間或重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0484', 'exercise', 1, '{"id": "0484", "target": "abs", "name_en": "hip raise (bent knee)", "name_zh": "髋部抬举（屈膝）", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0484-196HJGw.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "髖部抬舉（屈膝）", "instructions_en": ["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands by your sides, palms facing down.", "Engage your core and glutes, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.", "Pause for a moment at the top, then slowly lower your hips back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，膝盖弯曲，双脚平放在地上。", "将双手放在身体两侧，掌心朝下。", "收紧核心肌群和臀肌，然后将臀部抬离地面，直到身体从膝盖到肩膀形成一条直线。", "在顶部暂停片刻，然后慢慢将臀部放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings"], "instructions_zh_hant": ["平躺，膝蓋彎曲，雙腳平放在地上。", "將雙手放在身體兩側，掌心朝下。", "收緊核心肌群和臀肌，然后將臀部抬離地面，直到身體從膝蓋到肩膀形成一條直線。", "在頂部暫停片刻，然后慢慢將臀部放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1418', 'exercise', 1, '{"id": "1418", "target": "glutes", "name_en": "hug keens to chest", "name_zh": "仰卧抱膝至胸", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1418-znP9SIh.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "仰臥抱膝至胸", "instructions_en": ["Start by standing with your feet shoulder-width apart.", "Bend your knees and lower your body down into a squat position.", "As you squat down, bring your knees up towards your chest and hug them with your arms.", "Hold this position for a moment, then slowly return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先站立，双脚分开与肩同宽。", "弯曲膝盖并将身体降低至蹲姿。", "当你蹲下时，将膝盖抬向胸部，并用手臂抱住它们。", "保持这个姿势一会儿，然后慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "quadriceps"], "instructions_zh_hant": ["首先站立，雙腳分開與肩同寬。", "彎曲膝蓋并將身體降低至蹲姿。", "當你蹲下時，將膝蓋抬向胸部，并用手臂抱住它們。", "保持這個姿勢一會兒，然后慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3234', 'exercise', 1, '{"id": "3234", "target": "pectorals", "name_en": "hyght dumbbell fly", "name_zh": "海特哑铃飞鸟", "body_part": "chest", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/3234-P9ZRyLT.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "海特啞鈴飛鳥", "instructions_en": ["Lie flat on a bench with a dumbbell in each hand, palms facing each other.", "Extend your arms straight up over your chest, with a slight bend in your elbows.", "Keeping a slight bend in your elbows, lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.", "Pause for a moment, then reverse the movement and bring the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，双手各握一个哑铃，手掌相对。", "将手臂伸直越过胸部，肘部稍微弯曲。", "保持肘部轻微弯曲，以宽弧线将哑铃向两侧放低，直到感觉到胸部有拉伸感。", "暂停片刻，然后反转动作，将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["平躺在長凳上，雙手各握一個啞鈴，手掌相對。", "將手臂伸直越過胸部，肘部稍微彎曲。", "保持肘部輕微彎曲，以寬弧線將啞鈴向兩側放低，直到感覺到胸部有拉伸感。", "暫停片刻，然后反轉動作，將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3224', 'exercise', 1, '{"id": "3224", "target": "cardiovascular system", "name_en": "jack jump (male)", "name_zh": "开合跳跃（男性示范）", "body_part": "cardio", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3224-1g5bPpA.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "開合跳躍（男性示范）", "instructions_en": ["Stand with your feet together and your arms by your sides.", "Jump up, spreading your feet apart and raising your arms above your head.", "As you land, quickly jump back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚并拢站立，双臂放在身体两侧。", "跳起来，分开双脚，将手臂举过头顶。", "当你落地时，迅速跳回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "calves"], "instructions_zh_hant": ["雙腳并攏站立，雙臂放在身體兩側。", "跳起來，分開雙腳，將手臂舉過頭頂。", "當你落地時，迅速跳回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3289', 'exercise', 1, '{"id": "3289", "target": "triceps", "name_en": "impossible dips", "name_zh": "进阶后倾式臂屈伸", "body_part": "upper arms", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3289-05Cf2v8.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "進階后傾式臂屈伸", "instructions_en": ["Position yourself between two parallel bars with your arms fully extended and your body suspended in the air.", "Bend your knees and cross your ankles.", "Lower your body by bending your elbows until your upper arms are parallel to the ground.", "Pause for a moment, then push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将自己定位在两个双杠之间，双臂完全伸展，身体悬浮在空中。", "弯曲膝盖并交叉脚踝。", "弯曲肘部降低身体，直到上臂与地面平行。", "暂停片刻，然后伸直手臂，将自己推回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["將自己定位在兩個雙杠之間，雙臂完全伸展，身體懸浮在空中。", "彎曲膝蓋并交叉腳踝。", "彎曲肘部降低身體，直到上臂與地面平行。", "暫停片刻，然后伸直手臂，將自己推回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1471', 'exercise', 1, '{"id": "1471", "target": "abs", "name_en": "inchworm", "name_zh": "毛毛虫爬行", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1471-ZgsNQ6d.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "毛毛蟲爬行", "instructions_en": ["Start in a standing position with your feet hip-width apart.", "Bend forward at the waist and place your hands on the ground in front of you.", "Walk your hands forward until you are in a high plank position, with your body in a straight line from head to toe.", "Pause for a moment, then walk your hands back towards your feet, keeping your legs as straight as possible.", "Once your hands reach your feet, stand back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["从站立位置开始，双脚分开与臀部同宽。", "腰部向前弯曲，双手放在身前的地面上。", "双手向前移动，直到处于高位平板支撑位置，身体从头到脚成一条直线。", "暂停片刻，然后将双手移回双脚，尽可能保持双腿伸直。", "一旦你的手到达你的脚，站回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "hamstrings"], "instructions_zh_hant": ["從站立位置開始，雙腳分開與臀部同寬。", "腰部向前彎曲，雙手放在身前的地面上。", "雙手向前移動，直到處于高位平板支撐位置，身體從頭到腳成一條直線。", "暫停片刻，然后將雙手移回雙腳，盡可能保持雙腿伸直。", "一旦你的手到達你的腳，站回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3698', 'exercise', 1, '{"id": "3698", "target": "abs", "name_en": "inchworm v. 2", "name_zh": "毛毛虫爬行变式2", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3698-TV87DNB.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "毛毛蟲爬行變式2", "instructions_en": ["Start in a standing position with your feet hip-width apart.", "Bend forward at the waist and place your hands on the ground in front of you.", "Walk your hands forward until you are in a high plank position, with your body in a straight line from head to toe.", "Keeping your legs straight, walk your feet towards your hands, bringing your hips up towards the ceiling.", "Continue walking your hands forward, repeating the movement for the desired number of repetitions."], "instructions_zh": ["从站立位置开始，双脚分开与臀部同宽。", "腰部向前弯曲，双手放在身前的地面上。", "双手向前移动，直到处于高位平板支撑位置，身体从头到脚成一条直线。", "保持双腿伸直，将脚移向双手，将臀部抬向天花板。", "继续向前移动双手，重复该动作达到所需的重复次数。"], "secondary_muscles": ["shoulders", "hamstrings"], "instructions_zh_hant": ["從站立位置開始，雙腳分開與臀部同寬。", "腰部向前彎曲，雙手放在身前的地面上。", "雙手向前移動，直到處于高位平板支撐位置，身體從頭到腳成一條直線。", "保持雙腿伸直，將腳移向雙手，將臀部抬向天花板。", "繼續向前移動雙手，重復該動作達到所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0490', 'exercise', 1, '{"id": "0490", "target": "triceps", "name_en": "incline close-grip push-up", "name_zh": "上斜窄握俯卧撑", "body_part": "upper arms", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0490-1YB40kg.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "上斜窄握俯臥撐", "instructions_en": ["Place your hands on an elevated surface, such as a bench or step, slightly wider than shoulder-width apart.", "Extend your legs behind you, resting on the balls of your feet, with your body forming a straight line from head to heels.", "Lower your chest towards the elevated surface by bending your elbows, keeping them close to your sides.", "Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将双手放在较高的表面上，例如长凳或台阶上，双手之间的距离略宽于肩宽。", "将双腿伸到身后，放在脚掌上，身体从头到脚跟形成一条直线。", "弯曲肘部，使肘部靠近身体两侧，将胸部降低到升高的表面。", "在底部暂停片刻，然后伸直手臂将自己推回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["將雙手放在較高的表面上，例如長凳或臺階上，雙手之間的距離略寬于肩寬。", "將雙腿伸到身后，放在腳掌上，身體從頭到腳跟形成一條直線。", "彎曲肘部，使肘部靠近身體兩側，將胸部降低到升高的表面。", "在底部暫停片刻，然后伸直手臂將自己推回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0491', 'exercise', 1, '{"id": "0491", "target": "abs", "name_en": "incline leg hip raise (leg straight)", "name_zh": "上斜直腿举腿提髋", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0491-eVxAzgz.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "上斜直腿舉腿提髖", "instructions_en": ["Lie on an incline bench with your back flat against the bench and your legs extended straight out in front of you.", "Place your hands on the sides of the bench for support.", "Engaging your abs, lift your legs off the bench, raising them as high as you can while keeping them straight.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["躺在倾斜的长凳上，背部平放在长凳上，双腿伸直在身前。", "将双手放在长凳两侧以获得支撑。", "收紧腹肌，将双腿抬离长凳，尽可能抬高双腿，同时保持伸直。", "在顶部暂停片刻，然后慢慢将双腿放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["躺在傾斜的長凳上，背部平放在長凳上，雙腿伸直在身前。", "將雙手放在長凳兩側以獲得支撐。", "收緊腹肌，將雙腿抬離長凳，盡可能抬高雙腿，同時保持伸直。", "在頂部暫停片刻，然后慢慢將雙腿放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0492', 'exercise', 1, '{"id": "0492", "target": "pectorals", "name_en": "incline push up depth jump", "name_zh": "上斜俯卧撑落地反弹跳跃", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0492-CB8WET1.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "上斜俯臥撐落地反彈跳躍", "instructions_en": ["Find an elevated surface, such as a bench or step, and place your hands shoulder-width apart on the edge.", "Step your feet back, keeping your body in a straight line from head to heels.", "Lower your chest towards the edge of the surface, bending your elbows and keeping your body aligned.", "Push through your palms to extend your arms and return to the starting position.", "Jump off the edge of the surface, landing softly with your knees slightly bent.", "Repeat the push-up and depth jump for the desired number of repetitions."], "instructions_zh": ["找到一个较高的表面，例如长凳或台阶，并将双手与肩同宽放在边缘。", "双脚向后退一步，保持身体从头到脚跟呈一条直线。", "将胸部向水面边缘降低，弯曲肘部并保持身体对齐。", "推动手掌以伸展手臂并返回到起始位置。", "从水面边缘跳下，膝盖稍微弯曲，轻轻落地。", "重复俯卧撑和深度跳跃达到所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders", "core"], "instructions_zh_hant": ["找到一個較高的表面，例如長凳或臺階，并將雙手與肩同寬放在邊緣。", "雙腳向后退一步，保持身體從頭到腳跟呈一條直線。", "將胸部向水面邊緣降低，彎曲肘部并保持身體對齊。", "推動手掌以伸展手臂并返回到起始位置。", "從水面邊緣跳下，膝蓋稍微彎曲，輕輕落地。", "重復俯臥撐和深度跳躍達到所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0493', 'exercise', 1, '{"id": "0493", "target": "pectorals", "name_en": "incline push-up", "name_zh": "上斜俯卧撑", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0493-B1EVP9F.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "上斜俯臥撐", "instructions_en": ["Place your hands on an elevated surface, such as a bench or step, slightly wider than shoulder-width apart.", "Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.", "Lower your chest towards the elevated surface by bending your elbows, keeping your body in a straight line.", "Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将双手放在较高的表面上，例如长凳或台阶上，双手之间的距离略宽于肩宽。", "将双腿伸到身后，放在脚掌上，从头到脚跟形成一条直线。", "弯曲肘部，将胸部向升高的表面降低，保持身体呈一条直线。", "在底部暂停片刻，然后伸直手臂将自己推回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["將雙手放在較高的表面上，例如長凳或臺階上，雙手之間的距離略寬于肩寬。", "將雙腿伸到身后，放在腳掌上，從頭到腳跟形成一條直線。", "彎曲肘部，將胸部向升高的表面降低，保持身體呈一條直線。", "在底部暫停片刻，然后伸直手臂將自己推回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3785', 'exercise', 1, '{"id": "3785", "target": "pectorals", "name_en": "incline push-up (on box)", "name_zh": "上斜俯卧撑（于箱式）", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3785-F7vjXqT.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "上斜俯臥撐（于箱式）", "instructions_en": ["Place your hands on the edge of a box or elevated surface, slightly wider than shoulder-width apart.", "Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.", "Lower your chest towards the box by bending your elbows, keeping your body in a straight line.", "Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将双手放在盒子或高架表面的边缘，距离略宽于肩宽。", "将双腿伸到身后，放在脚掌上，从头到脚跟形成一条直线。", "弯曲肘部，将胸部向箱子方向降低，保持身体呈一条直线。", "在底部暂停片刻，然后伸直手臂将自己推回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["將雙手放在盒子或高架表面的邊緣，距離略寬于肩寬。", "將雙腿伸到身后，放在腳掌上，從頭到腳跟形成一條直線。", "彎曲肘部，將胸部向箱子方向降低，保持身體呈一條直線。", "在底部暫停片刻，然后伸直手臂將自己推回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0494', 'exercise', 1, '{"id": "0494", "target": "pectorals", "name_en": "incline reverse grip push-up", "name_zh": "上斜反握俯卧撑", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0494-XaaRnRn.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "上斜反握俯臥撐", "instructions_en": ["Place your hands on the edge of a bench or elevated surface, slightly wider than shoulder-width apart.", "Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.", "Lower your chest towards the bench by bending your elbows, keeping them close to your sides.", "Pause for a moment at the bottom, then push yourself back up to the starting position by extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将双手放在长凳或高架表面的边缘，距离略宽于肩宽。", "将双腿伸到身后，放在脚掌上，从头到脚跟形成一条直线。", "弯曲肘部，将胸部向长凳方向降低，使其靠近身体两侧。", "在底部暂停片刻，然后伸展双臂将自己推回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["將雙手放在長凳或高架表面的邊緣，距離略寬于肩寬。", "將雙腿伸到身后，放在腳掌上，從頭到腳跟形成一條直線。", "彎曲肘部，將胸部向長凳方向降低，使其靠近身體兩側。", "在底部暫停片刻，然后伸展雙臂將自己推回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3011', 'exercise', 1, '{"id": "3011", "target": "serratus anterior", "name_en": "incline scapula push up", "name_zh": "上斜肩胛俯卧撑", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3011-GdMa1ET.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "上斜肩胛俯臥撐", "instructions_en": ["Set up an incline bench at a 45-degree angle.", "Place your hands on the bench slightly wider than shoulder-width apart.", "Position your feet on the ground, hip-width apart.", "Lower your chest towards the bench, keeping your elbows tucked in.", "As you lower, retract your shoulder blades, squeezing your scapulae together.", "Push through your palms to extend your arms and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["设置一个 45 度角的上斜凳。", "将双手放在长凳上，距离略比肩宽。", "将双脚放在地面上，距离与臀部同宽。", "将胸部向长凳方向降低，保持肘部内收。", "当你降低时，缩回肩胛骨，将肩胛骨挤压在一起。", "推动手掌以伸展手臂并返回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["設置一個 45 度角的上斜凳。", "將雙手放在長凳上，距離略比肩寬。", "將雙腳放在地面上，距離與臀部同寬。", "將胸部向長凳方向降低，保持肘部內收。", "當你降低時，縮回肩胛骨，將肩胛骨擠壓在一起。", "推動手掌以伸展手臂并返回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0495', 'exercise', 1, '{"id": "0495", "target": "abs", "name_en": "incline twisting sit-up", "name_zh": "上斜转体仰卧起坐", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0495-9ZGZuOD.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "上斜轉體仰臥起坐", "instructions_en": ["Set up an incline bench at a 45-degree angle.", "Lie down on the bench with your feet secured under the foot pads.", "Place your hands behind your head or across your chest.", "Engage your abs and lift your upper body off the bench, curling forward.", "As you curl up, twist your torso to one side, bringing your elbow towards the opposite knee.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat the movement, this time twisting your torso to the other side.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["设置一个 45 度角的上斜凳。", "躺在长凳上，双脚固定在脚垫下。", "将双手放在脑后或放在胸前。", "收紧腹肌，将上半身抬离长凳，向前卷曲。", "当你蜷缩起来时，将你的躯干扭转到一侧，将你的肘部拉向另一侧的膝盖。", "在顶部停顿片刻，然后慢慢将上半身放回起始位置。", "重复这个动作，这次将你的躯干扭转到另一侧。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["obliques"], "instructions_zh_hant": ["設置一個 45 度角的上斜凳。", "躺在長凳上，雙腳固定在腳墊下。", "將雙手放在腦后或放在胸前。", "收緊腹肌，將上半身抬離長凳，向前卷曲。", "當你蜷縮起來時，將你的軀幹扭轉到一側，將你的肘部拉向另一側的膝蓋。", "在頂部停頓片刻，然后慢慢將上半身放回起始位置。", "重復這個動作，這次將你的軀幹扭轉到另一側。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1564', 'exercise', 1, '{"id": "1564", "target": "quads", "name_en": "intermediate hip flexor and quad stretch", "name_zh": "中级髋部屈肌与股四头肌拉伸", "body_part": "upper legs", "equipment": "rope", "gif_asset": "assets/fitness/videos/1564-tFGKm99.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "中級髖部屈肌與股四頭肌拉伸", "instructions_en": ["Stand upright with your feet shoulder-width apart.", "Hold onto a stable object for support.", "Bend your right knee and bring your right foot towards your glutes, grabbing the rope with your right hand.", "Slowly pull your right foot towards your glutes, feeling a stretch in your right quad.", "Hold the stretch for 20-30 seconds.", "Release the stretch and repeat on the left side."], "instructions_zh": ["站直，双脚分开与肩同宽。", "抓住一个稳定的物体作为支撑。", "弯曲右膝，将右脚移向臀部，用右手抓住绳子。", "慢慢地将右脚拉向臀部，感受右股四头肌的拉伸。", "保持拉伸 20-30 秒。", "松开拉伸并在左侧重复。"], "secondary_muscles": ["hamstrings", "glutes"], "instructions_zh_hant": ["站直，雙腳分開與肩同寬。", "抓住一個穩定的物體作為支撐。", "彎曲右膝，將右腳移向臀部，用右手抓住繩子。", "慢慢地將右腳拉向臀部，感受右股四頭肌的拉伸。", "保持拉伸 20-30 秒。", "松開拉伸并在左側重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0507', 'exercise', 1, '{"id": "0507", "target": "abs", "name_en": "jackknife sit-up", "name_zh": "折刀式仰卧起坐", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0507-mbkgB44.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "折刀式仰臥起坐", "instructions_en": ["Lie flat on your back with your legs extended and your arms overhead.", "Engage your core and lift your legs and upper body simultaneously, reaching your hands towards your toes.", "Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，双腿伸展，双臂举过头顶。", "启动你的核心，同时抬起双腿和上半身，将双手伸向脚趾。", "在顶部停顿片刻，然后慢慢放下双腿和上半身回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["平躺，雙腿伸展，雙臂舉過頭頂。", "啟動你的核心，同時抬起雙腿和上半身，將雙手伸向腳趾。", "在頂部停頓片刻，然后慢慢放下雙腿和上半身回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0496', 'exercise', 1, '{"id": "0496", "target": "hamstrings", "name_en": "inverse leg curl (bench support)", "name_zh": "反向腿弯举（凳上支撑）", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0496-ms7tjSG.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "反向腿彎舉（凳上支撐）", "instructions_en": ["Lie face down on a bench with your hips at the edge and your legs extended straight behind you.", "Hold onto the bench for support.", "Keeping your upper body still, bend your knees and curl your legs towards your glutes.", "Pause for a moment at the top, then slowly extend your legs back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["脸朝下躺在长凳上，臀部位于边缘，双腿伸直在身后。", "抓住长凳以获得支撑。", "保持上半身不动，弯曲膝盖并将双腿向臀部弯曲。", "在顶部停顿片刻，然后慢慢将双腿伸展回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "calves"], "instructions_zh_hant": ["臉朝下躺在長凳上，臀部位于邊緣，雙腿伸直在身后。", "抓住長凳以獲得支撐。", "保持上半身不動，彎曲膝蓋并將雙腿向臀部彎曲。", "在頂部停頓片刻，然后慢慢將雙腿伸展回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2400', 'exercise', 1, '{"id": "2400", "target": "hamstrings", "name_en": "inverse leg curl (on pull-up cable machine)", "name_zh": "反向腿弯举（于引体向上绳索器械）", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/2400-0rHfvy9.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "反向腿彎舉（于引體向上繩索器械）", "instructions_en": ["Adjust the cable machine so that the ankle straps are at the lowest setting.", "Lie face down on the bench with your legs extended and the ankle straps attached to your feet.", "Hold onto the handles of the bench for stability.", "Bend your knees and curl your legs towards your glutes, squeezing your hamstrings.", "Pause for a moment at the top of the movement, then slowly lower your legs back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整缆绳机，使踝带处于最低设置。", "面朝下躺在长凳上，双腿伸展，脚踝带固定在脚上。", "握住长凳的把手以保持稳定。", "弯曲膝盖，将双腿向臀部弯曲，挤压腿筋。", "在动作的最高点暂停片刻，然后慢慢将双腿放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "calves"], "instructions_zh_hant": ["調整纜繩機，使踝帶處于最低設置。", "面朝下躺在長凳上，雙腿伸展，腳踝帶固定在腳上。", "握住長凳的把手以保持穩定。", "彎曲膝蓋，將雙腿向臀部彎曲，擠壓腿筋。", "在動作的最高點暫停片刻，然后慢慢將雙腿放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0499', 'exercise', 1, '{"id": "0499", "target": "upper back", "name_en": "inverted row", "name_zh": "反向划船", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0499-bZGHsAZ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "反向劃船", "instructions_en": ["Set up a bar at waist height or use a suspension trainer.", "Stand facing the bar or suspension trainer, with your feet shoulder-width apart.", "Grab the bar or handles with an overhand grip, slightly wider than shoulder-width apart.", "Lean back, keeping your body straight and your heels on the ground.", "Pull your chest towards the bar or handles, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower yourself back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["在腰部高度设置一个杠铃或使用悬挂训练器。", "面向杠铃或悬吊训练器站立，双脚分开与肩同宽。", "正手握住杠铃或手柄，握距略宽于肩宽。", "向后倾斜，保持身体挺直，脚后跟着地。", "将胸部拉向杠铃或手柄，将肩胛骨挤压在一起。", "在顶部停顿片刻，然后慢慢降低回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["在腰部高度設置一個杠鈴或使用懸掛訓練器。", "面向杠鈴或懸吊訓練器站立，雙腳分開與肩同寬。", "正手握住杠鈴或手柄，握距略寬于肩寬。", "向后傾斜，保持身體挺直，腳后跟著地。", "將胸部拉向杠鈴或手柄，將肩胛骨擠壓在一起。", "在頂部停頓片刻，然后慢慢降低回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2300', 'exercise', 1, '{"id": "2300", "target": "upper back", "name_en": "inverted row bent knees", "name_zh": "屈膝反向划船", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/2300-VPPtusI.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "屈膝反向劃船", "instructions_en": ["Set up a bar at waist height and lie underneath it.", "Grab the bar with an overhand grip, slightly wider than shoulder-width apart.", "Position your body so that your heels are on the ground and your body is straight.", "Pull your chest up towards the bar by squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["在腰部高度设置一根横杆，然后躺在其下方。", "正手握住杠铃，握距略宽于肩宽。", "调整身体位置，使脚后跟着地，身体伸直。", "将肩胛骨挤压在一起，将胸部向上拉向杠铃。", "在顶部停顿片刻，然后慢慢将身体放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["在腰部高度設置一根橫桿，然后躺在其下方。", "正手握住杠鈴，握距略寬于肩寬。", "調整身體位置，使腳后跟著地，身體伸直。", "將肩胛骨擠壓在一起，將胸部向上拉向杠鈴。", "在頂部停頓片刻，然后慢慢將身體放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2298', 'exercise', 1, '{"id": "2298", "target": "upper back", "name_en": "inverted row on bench", "name_zh": "反向划船（凳上）", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/2298-Mxa7Cr8.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "反向劃船（凳上）", "instructions_en": ["Set up a bench at a height that allows your body to hang freely underneath it.", "Lie face up on the ground with your head towards the bench.", "Reach up and grab the bench with an overhand grip, slightly wider than shoulder-width apart.", "Position your body so that your heels are on the ground and your arms are fully extended.", "Engage your core and squeeze your shoulder blades together as you pull your chest up towards the bench.", "Pause for a moment at the top of the movement, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["设置一张长凳，其高度应让您的身体可以自由地悬挂在其下方。", "面朝上躺在地上，头朝向长凳。", "向上伸手，正手握住长凳，握距略宽于肩宽。", "调整身体位置，使脚后跟着地，手臂完全伸展。", "当你将胸部拉向长凳时，启动你的核心并将肩胛骨挤压在一起。", "在动作的最高点停顿片刻，然后慢慢降低身体回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["設置一張長凳，其高度應讓您的身體可以自由地懸掛在其下方。", "面朝上躺在地上，頭朝向長凳。", "向上伸手，正手握住長凳，握距略寬于肩寬。", "調整身體位置，使腳后跟著地，手臂完全伸展。", "當你將胸部拉向長凳時，啟動你的核心并將肩胛骨擠壓在一起。", "在動作的最高點停頓片刻，然后慢慢降低身體回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0497', 'exercise', 1, '{"id": "0497", "target": "upper back", "name_en": "inverted row v. 2", "name_zh": "反向划船变式2", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0497-uX3sUBz.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "反向劃船變式2", "instructions_en": ["Set up a bar at waist height on a Smith machine or use a suspension trainer.", "Stand facing the bar or suspension trainer and grab it with an overhand grip, hands shoulder-width apart.", "Walk your feet forward, leaning back until your body is at a slight angle.", "Keep your body straight and pull your chest up towards the bar or handles, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower yourself back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["在史密斯机上在腰部高度设置一根杠铃或使用悬挂训练器。", "面向杠铃或悬吊训练器站立，用正手握法抓住它，双手与肩同宽。", "双脚向前走，向后倾斜，直到身体呈轻微角度。", "保持身体挺直，将胸部向上拉向杠铃或手柄，将肩胛骨挤压在一起。", "在最高点暂停片刻，然后慢慢降低回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["在史密斯機上在腰部高度設置一根杠鈴或使用懸掛訓練器。", "面向杠鈴或懸吊訓練器站立，用正手握法抓住它，雙手與肩同寬。", "雙腳向前走，向后傾斜，直到身體呈輕微角度。", "保持身體挺直，將胸部向上拉向杠鈴或手柄，將肩胛骨擠壓在一起。", "在最高點暫停片刻，然后慢慢降低回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0498', 'exercise', 1, '{"id": "0498", "target": "upper back", "name_en": "inverted row with straps", "name_zh": "反向划船配合吊带", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0498-jdiExfW.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "反向劃船配合吊帶", "instructions_en": ["Set up a suspension trainer or straps at chest height.", "Stand facing the anchor point and grab the handles with an overhand grip.", "Walk your feet forward, leaning back until your body is at an angle.", "Keep your body straight and engage your core.", "Pull your chest towards the handles, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower yourself back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["在胸部高度设置悬挂训练器或带子。", "面向锚点站立，并用正手握住手柄。", "双脚向前走，向后倾斜，直到身体呈一定角度。", "保持身体挺直并启动核心。", "将胸部拉向手柄，将肩胛骨挤压在一起。", "在顶部停顿片刻，然后慢慢降低回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["在胸部高度設置懸掛訓練器或帶子。", "面向錨點站立，并用正手握住手柄。", "雙腳向前走，向后傾斜，直到身體呈一定角度。", "保持身體挺直并啟動核心。", "將胸部拉向手柄，將肩胛骨擠壓在一起。", "在頂部停頓片刻，然后慢慢降低回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0522', 'exercise', 1, '{"id": "0522", "target": "upper back", "name_en": "kettlebell alternating row", "name_zh": "壶铃交替划船", "body_part": "back", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0522-Ca76jUE.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴交替劃船", "instructions_en": ["Stand with your feet shoulder-width apart, knees slightly bent, and hold a kettlebell in each hand with your palms facing your body.", "Bend forward at the hips, keeping your back straight and your core engaged.", "Pull one kettlebell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.", "Lower the kettlebell back down to the starting position and repeat with the other arm.", "Continue alternating arms for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，膝盖稍微弯曲，双手各握一个壶铃，手掌朝向身体。", "臀部向前弯曲，保持背部挺直，核心肌群参与。", "将一个壶铃向上拉向胸部，保持肘部靠近身体并将肩胛骨挤压在一起。", "将壶铃放回起始位置，然后用另一只手臂重复该动作。", "继续交替手臂进行所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，膝蓋稍微彎曲，雙手各握一個壺鈴，手掌朝向身體。", "臀部向前彎曲，保持背部挺直，核心肌群參與。", "將一個壺鈴向上拉向胸部，保持肘部靠近身體并將肩胛骨擠壓在一起。", "將壺鈴放回起始位置，然后用另一只手臂重復該動作。", "繼續交替手臂進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1419', 'exercise', 1, '{"id": "1419", "target": "glutes", "name_en": "iron cross stretch", "name_zh": "十字支撑拉伸", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1419-pZwUsKB.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "十字支撐拉伸", "instructions_en": ["Lie flat on your back with your arms extended out to the sides.", "Raise your legs up towards the ceiling, keeping them straight.", "Slowly lower your legs to one side, aiming to touch the floor with your feet.", "Hold the stretch for a few seconds, then return your legs to the starting position.", "Repeat the stretch on the other side.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["平躺，双臂向两侧伸展。", "将双腿抬向天花板，保持伸直。", "慢慢地将双腿降低到一侧，旨在用脚接触地板。", "保持伸展几秒钟，然后将双腿恢复到起始位置。", "在另一侧重复拉伸。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["hamstrings", "quadriceps"], "instructions_zh_hant": ["平躺，雙臂向兩側伸展。", "將雙腿抬向天花板，保持伸直。", "慢慢地將雙腿降低到一側，旨在用腳接觸地板。", "保持伸展幾秒鐘，然后將雙腿恢復到起始位置。", "在另一側重復拉伸。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1297', 'exercise', 1, '{"id": "1297", "target": "pectorals", "name_en": "isometric chest squeeze", "name_zh": "等长收缩胸部夹压", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1297-HbSG1Pw.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "等長收縮胸部夾壓", "instructions_en": ["Stand with your feet shoulder-width apart and your knees slightly bent.", "Extend your arms straight out in front of you, parallel to the ground, with your palms facing each other.", "Squeeze your chest muscles together as hard as you can, while keeping your arms straight.", "Hold this position for a few seconds, focusing on contracting your chest muscles.", "Release the squeeze and relax your chest muscles.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，膝盖稍微弯曲。", "将双臂伸直在身前，与地面平行，手掌相对。", "尽可能用力挤压胸部肌肉，同时保持手臂伸直。", "保持这个姿势几秒钟，专注于收缩胸部肌肉。", "释放挤压并放松胸部肌肉。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，膝蓋稍微彎曲。", "將雙臂伸直在身前，與地面平行，手掌相對。", "盡可能用力擠壓胸部肌肉，同時保持手臂伸直。", "保持這個姿勢幾秒鐘，專注于收縮胸部肌肉。", "釋放擠壓并放松胸部肌肉。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0500', 'exercise', 1, '{"id": "0500", "target": "pectorals", "name_en": "isometric wipers", "name_zh": "等长收缩雨刷式", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0500-11wrviz.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "等長收縮雨刷式", "instructions_en": ["Start by lying flat on your back on a mat or bench.", "Extend your arms straight out to the sides, perpendicular to your body.", "Engage your core and lift both legs off the ground, keeping them together and straight.", "Slowly lower your legs to one side, aiming to touch the ground with your feet while maintaining control.", "Pause for a moment, then use your core to lift your legs back to the starting position.", "Repeat the movement, this time lowering your legs to the opposite side.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["首先平躺在垫子或长凳上。", "将手臂伸直至两侧，与身体垂直。", "启动你的核心并将双腿抬离地面，保持它们并拢并伸直。", "慢慢地将双腿向一侧降低，目标是用脚接触地面，同时保持控制。", "暂停片刻，然后用核心力量将双腿抬回到起始位置。", "重复该动作，这次将双腿降低到另一侧。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps", "core"], "instructions_zh_hant": ["首先平躺在墊子或長凳上。", "將手臂伸直至兩側，與身體垂直。", "啟動你的核心并將雙腿抬離地面，保持它們并攏并伸直。", "慢慢地將雙腿向一側降低，目標是用腳接觸地面，同時保持控制。", "暫停片刻，然后用核心力量將雙腿抬回到起始位置。", "重復該動作，這次將雙腿降低到另一側。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0501', 'exercise', 1, '{"id": "0501", "target": "cardiovascular system", "name_en": "jack burpee", "name_zh": "开合波比跳", "body_part": "cardio", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0501-mr7pkqP.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "開合波比跳", "instructions_en": ["Start in a standing position with your feet shoulder-width apart.", "Lower your body into a squat position, placing your hands on the ground in front of you.", "Kick your feet back, landing in a push-up position.", "Perform a push-up, lowering your chest to the ground and then pushing back up.", "Jump your feet forward, landing in a squat position.", "Jump up explosively, reaching your arms overhead.", "Land softly and immediately lower back into the squat position to begin the next repetition."], "instructions_zh": ["从站立位置开始，双脚分开与肩同宽。", "将身体降低至蹲姿，将双手放在身前的地面上。", "双脚向后踢，以俯卧撑姿势落地。", "进行俯卧撑，将胸部降低到地面，然后再向上推。", "双脚向前跳，以蹲姿落地。", "爆发性地跳起，将双臂举过头顶。", "轻轻落地并立即回到蹲姿，开始下一次重复。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves", "shoulders", "triceps", "core"], "instructions_zh_hant": ["從站立位置開始，雙腳分開與肩同寬。", "將身體降低至蹲姿，將雙手放在身前的地面上。", "雙腳向后踢，以俯臥撐姿勢落地。", "進行俯臥撐，將胸部降低到地面，然后再向上推。", "雙腳向前跳，以蹲姿落地。", "爆發性地跳起，將雙臂舉過頭頂。", "輕輕落地并立即回到蹲姿，開始下一次重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0508', 'exercise', 1, '{"id": "0508", "target": "abs", "name_en": "janda sit-up", "name_zh": "詹达仰卧起坐", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0508-1GPHRyK.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "詹達仰臥起坐", "instructions_en": ["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，膝盖弯曲，双脚平放在地上。", "将双手放在脑后，肘部朝外。", "收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。", "在顶部停顿片刻，然后慢慢将上半身放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors", "lower back"], "instructions_zh_hant": ["平躺，膝蓋彎曲，雙腳平放在地上。", "將雙手放在腦后，肘部朝外。", "收緊腹肌，慢慢將上半身抬離地面，向前卷曲，直到軀幹呈 45 度角。", "在頂部停頓片刻，然后慢慢將上半身放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2612', 'exercise', 1, '{"id": "2612", "target": "cardiovascular system", "name_en": "jump rope", "name_zh": "跳绳", "body_part": "cardio", "equipment": "rope", "gif_asset": "assets/fitness/videos/2612-e1e76I2.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "跳繩", "instructions_en": ["Hold the handles of the jump rope with your hands, palms facing inward.", "Stand with your feet shoulder-width apart and knees slightly bent.", "Swing the rope over your head and jump over it as it comes towards your feet.", "Land softly on the balls of your feet and repeat the jump as the rope comes around again.", "Continue jumping for the desired duration or number of repetitions."], "instructions_zh": ["双手握住跳绳的手柄，掌心向内。", "站立，双脚分开与肩同宽，膝盖稍微弯曲。", "将绳子甩过头顶，当绳子靠近你的脚时跳过它。", "轻轻地用脚掌着地，当绳子再次绕回时重复跳跃。", "继续跳跃所需的持续时间或重复次数。"], "secondary_muscles": ["calves", "quadriceps", "hamstrings", "glutes"], "instructions_zh_hant": ["雙手握住跳繩的手柄，掌心向內。", "站立，雙腳分開與肩同寬，膝蓋稍微彎曲。", "將繩子甩過頭頂，當繩子靠近你的腳時跳過它。", "輕輕地用腳掌著地，當繩子再次繞回時重復跳躍。", "繼續跳躍所需的持續時間或重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0514', 'exercise', 1, '{"id": "0514", "target": "glutes", "name_en": "jump squat", "name_zh": "跳跃深蹲", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0514-LIlE5Tn.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "跳躍深蹲", "instructions_en": ["Stand with your feet shoulder-width apart.", "Lower your body into a squat position by bending your knees and pushing your hips back.", "Jump explosively off the ground, extending your hips, knees, and ankles.", "While in mid-air, quickly bring your arms forward for balance.", "Land softly on the balls of your feet and immediately go into the next repetition.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立。", "弯曲膝盖并将臀部向后推，将身体降低至蹲姿。", "爆发性地跳离地面，伸展臀部、膝盖和脚踝。", "在半空中时，快速将手臂向前伸以保持平衡。", "脚掌轻轻落地，然后立即进入下一个重复动作。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立。", "彎曲膝蓋并將臀部向后推，將身體降低至蹲姿。", "爆發性地跳離地面，伸展臀部、膝蓋和腳踝。", "在半空中時，快速將手臂向前伸以保持平衡。", "腳掌輕輕落地，然后立即進入下一個重復動作。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0513', 'exercise', 1, '{"id": "0513", "target": "glutes", "name_en": "jump squat v. 2", "name_zh": "跳跃深蹲变式2", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0513-TDYiji6.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "跳躍深蹲變式2", "instructions_en": ["Stand with your feet shoulder-width apart.", "Lower your body into a squat position by bending your knees and pushing your hips back.", "Jump explosively, extending your hips and knees fully.", "Land softly on the balls of your feet and immediately lower your body back into a squat position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立。", "弯曲膝盖并将臀部向后推，将身体降低至蹲姿。", "爆发力跳跃，充分伸展臀部和膝盖。", "脚掌轻轻着地，然后立即将身体放回蹲姿。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立。", "彎曲膝蓋并將臀部向后推，將身體降低至蹲姿。", "爆發力跳躍，充分伸展臀部和膝蓋。", "腳掌輕輕著地，然后立即將身體放回蹲姿。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0517', 'exercise', 1, '{"id": "0517", "target": "abs", "name_en": "kettlebell advanced windmill", "name_zh": "壶铃进阶风车", "body_part": "waist", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0517-Kal9cQQ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴進階風車", "instructions_en": ["Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.", "Hold a kettlebell in your right hand, with your arm extended overhead and your palm facing forward.", "Rotate your left foot slightly to the right, and shift your weight onto your left leg.", "Bend your left knee and hinge at the hip, lowering your torso towards the left side.", "Keep your right arm extended overhead and your eyes on the kettlebell.", "As you lower your torso, allow your right leg to straighten and your right foot to pivot slightly.", "Lower your torso until you feel a stretch in your left hamstring and your right arm is pointing towards the ground.", "Pause for a moment, then engage your core and push through your left heel to return to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["站立，双脚分开比肩宽，脚趾稍微向外。", "右手握住壶铃，手臂伸过头顶，手掌朝前。", "将左脚稍微向右旋转，并将重量转移到左腿上。", "弯曲左膝并铰接在臀部，将躯干向左侧降低。", "保持右臂伸过头顶，眼睛盯着壶铃。", "当你降低躯干时，让右腿伸直，右脚稍微转动。", "降低躯干，直到感觉到左腿筋拉伸并且右臂指向地面。", "暂停片刻，然后启动核心并推动左脚跟返回到起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["obliques", "shoulders"], "instructions_zh_hant": ["站立，雙腳分開比肩寬，腳趾稍微向外。", "右手握住壺鈴，手臂伸過頭頂，手掌朝前。", "將左腳稍微向右旋轉，并將重量轉移到左腿上。", "彎曲左膝并鉸接在臀部，將軀幹向左側降低。", "保持右臂伸過頭頂，眼睛盯著壺鈴。", "當你降低軀幹時，讓右腿伸直，右腳稍微轉動。", "降低軀幹，直到感覺到左腿筋拉伸并且右臂指向地面。", "暫停片刻，然后啟動核心并推動左腳跟返回到起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0518', 'exercise', 1, '{"id": "0518", "target": "forearms", "name_en": "kettlebell alternating hang clean", "name_zh": "壶铃交替悬垂翻举", "body_part": "lower arms", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0518-I4tibZG.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴交替懸垂翻舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a kettlebell in each hand with an overhand grip.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.", "Allow the kettlebells to hang in front of your body with your arms fully extended.", "In one fluid motion, explosively extend your hips, shrug your shoulders, and pull the kettlebells up towards your shoulders.", "As the kettlebells reach shoulder height, rotate your wrists and catch the kettlebells in the rack position, with your palms facing inward and the kettlebells resting on the outside of your forearms.", "Lower the kettlebells back down to the starting position and repeat the movement with the opposite arm.", "Continue alternating arms for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个壶铃，正手握住。", "稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。", "让壶铃悬挂在身体前方，双臂完全伸展。", "以一种流畅的动作，爆发性地伸展臀部，耸肩，并将壶铃拉向肩膀。", "当壶铃到达肩膀高度时，旋转手腕并将壶铃抓住在架子位置，手掌朝内，壶铃放在前臂外侧。", "将壶铃放回起始位置，然后用另一只手臂重复该动作。", "继续交替手臂进行所需的重复次数。"], "secondary_muscles": ["shoulders", "traps", "core"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個壺鈴，正手握住。", "稍微彎曲膝蓋，臀部向前轉動，保持背部挺直，挺胸。", "讓壺鈴懸掛在身體前方，雙臂完全伸展。", "以一種流暢的動作，爆發性地伸展臀部，聳肩，并將壺鈴拉向肩膀。", "當壺鈴到達肩膀高度時，旋轉手腕并將壺鈴抓住在架子位置，手掌朝內，壺鈴放在前臂外側。", "將壺鈴放回起始位置，然后用另一只手臂重復該動作。", "繼續交替手臂進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0520', 'exercise', 1, '{"id": "0520", "target": "delts", "name_en": "kettlebell alternating press", "name_zh": "壶铃交替推举", "body_part": "shoulders", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0520-5KLbZWx.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴交替推舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.", "Press one kettlebell overhead, fully extending your arm.", "Lower the kettlebell back to shoulder height.", "Repeat with the other arm.", "Continue alternating arms for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个壶铃，与肩同高。", "将一只壶铃按过头顶，完全伸展手臂。", "将壶铃降低至肩膀高度。", "用另一只手臂重复上述步骤。", "继续交替手臂进行所需的重复次数。"], "secondary_muscles": ["triceps", "core"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個壺鈴，與肩同高。", "將一只壺鈴按過頭頂，完全伸展手臂。", "將壺鈴降低至肩膀高度。", "用另一只手臂重復上述步驟。", "繼續交替手臂進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0519', 'exercise', 1, '{"id": "0519", "target": "pectorals", "name_en": "kettlebell alternating press on floor", "name_zh": "壶铃交替推举（地板）", "body_part": "chest", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0519-7w6i0vE.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴交替推舉（地板）", "instructions_en": ["Start by lying on your back on the floor with your knees bent and feet flat on the ground.", "Hold a kettlebell in each hand, with your palms facing towards your feet and your arms extended straight up towards the ceiling.", "Lower one kettlebell down towards your shoulder while keeping the other kettlebell extended straight up.", "Press the lowered kettlebell back up to the starting position while simultaneously lowering the other kettlebell down towards your shoulder.", "Continue alternating the press motion with each kettlebell for the desired number of repetitions."], "instructions_zh": ["首先仰卧在地板上，膝盖弯曲，双脚平放在地面上。", "每只手握住一个壶铃，手掌朝向脚部，手臂伸直向天花板。", "将一个壶铃向肩膀方向降低，同时保持另一个壶铃向上伸直。", "将降低的壶铃按回到起始位置，同时将另一个壶铃向肩膀方向降低。", "继续用每个壶铃交替进行推举动作，达到所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["首先仰臥在地板上，膝蓋彎曲，雙腳平放在地面上。", "每只手握住一個壺鈴，手掌朝向腳部，手臂伸直向天花板。", "將一個壺鈴向肩膀方向降低，同時保持另一個壺鈴向上伸直。", "將降低的壺鈴按回到起始位置，同時將另一個壺鈴向肩膀方向降低。", "繼續用每個壺鈴交替進行推舉動作，達到所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0521', 'exercise', 1, '{"id": "0521", "target": "upper back", "name_en": "kettlebell alternating renegade row", "name_zh": "壶铃交替俯撑划船", "body_part": "back", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0521-b9kqlBy.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴交替俯撐劃船", "instructions_en": ["Start in a high plank position with your hands gripping the kettlebells and your feet hip-width apart.", "Engage your core and keep your body in a straight line from head to heels.", "Pull one kettlebell up towards your chest, keeping your elbow close to your body.", "Lower the kettlebell back down to the starting position and repeat with the other arm.", "Continue alternating arms for the desired number of repetitions."], "instructions_zh": ["从高平板支撑位置开始，双手握住壶铃，双脚分开与臀部同宽。", "收紧核心肌群，保持身体从头到脚跟呈一条直线。", "将一个壶铃向上拉向胸部，保持肘部靠近身体。", "将壶铃放回起始位置，然后用另一只手臂重复该动作。", "继续交替手臂进行所需的重复次数。"], "secondary_muscles": ["core", "shoulders"], "instructions_zh_hant": ["從高平板支撐位置開始，雙手握住壺鈴，雙腳分開與臀部同寬。", "收緊核心肌群，保持身體從頭到腳跟呈一條直線。", "將一個壺鈴向上拉向胸部，保持肘部靠近身體。", "將壺鈴放回起始位置，然后用另一只手臂重復該動作。", "繼續交替手臂進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0523', 'exercise', 1, '{"id": "0523", "target": "delts", "name_en": "kettlebell arnold press", "name_zh": "壶铃阿诺德推举", "body_part": "shoulders", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0523-UM8mgyG.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴阿諾德推舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height with your palms facing towards you.", "Engage your core and press the kettlebells overhead, rotating your palms to face forward as you extend your arms.", "Pause at the top of the movement, then slowly lower the kettlebells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个壶铃，与肩同高，手掌朝向自己。", "启动你的核心并将壶铃压过头顶，在伸展手臂时旋转手掌以面向前方。", "在动作的最高点暂停，然后慢慢将壶铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "upper back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個壺鈴，與肩同高，手掌朝向自己。", "啟動你的核心并將壺鈴壓過頭頂，在伸展手臂時旋轉手掌以面向前方。", "在動作的最高點暫停，然后慢慢將壺鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0524', 'exercise', 1, '{"id": "0524", "target": "abs", "name_en": "kettlebell bent press", "name_zh": "壶铃侧弯推举", "body_part": "waist", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0524-kjE55n5.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴側彎推舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a kettlebell in your right hand.", "Bend your knees slightly and press the kettlebell overhead with your right arm, keeping your elbow locked.", "Rotate your torso to the left, shifting your weight onto your left foot.", "Bend your left knee and lower your torso towards the ground, keeping your right arm extended overhead.", "As you lower, keep your eyes on the kettlebell and your chest lifted.", "Once your left hand touches the ground, push through your left foot and straighten your left leg, driving your hips forward.", "As you drive your hips forward, use your core and right arm to press the kettlebell back up to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["双脚分开与肩同宽站立，右手握住壶铃。", "稍微弯曲膝盖，用右臂将壶铃压过头顶，保持肘部锁定。", "将躯干向左旋转，将重量转移到左脚上。", "弯曲左膝，将躯干压向地面，保持右臂伸过头顶。", "当你下降时，眼睛盯着壶铃，胸部抬起。", "左手接触地面后，将左脚推入并伸直左腿，推动臀部向前。", "当你向前推动臀部时，用你的核心和右臂将壶铃推回到起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["shoulders", "triceps", "obliques"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，右手握住壺鈴。", "稍微彎曲膝蓋，用右臂將壺鈴壓過頭頂，保持肘部鎖定。", "將軀幹向左旋轉，將重量轉移到左腳上。", "彎曲左膝，將軀幹壓向地面，保持右臂伸過頭頂。", "當你下降時，眼睛盯著壺鈴，胸部抬起。", "左手接觸地面后，將左腳推入并伸直左腿，推動臀部向前。", "當你向前推動臀部時，用你的核心和右臂將壺鈴推回到起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0525', 'exercise', 1, '{"id": "0525", "target": "biceps", "name_en": "kettlebell bottoms up clean from the hang position", "name_zh": "壶铃悬垂倒置翻举", "body_part": "upper arms", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0525-4KJEpzb.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴懸垂倒置翻舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.", "Allow the kettlebell to hang down between your legs, with your arm fully extended.", "In one fluid motion, explosively extend your hips and knees while pulling the kettlebell up towards your shoulder.", "As the kettlebell reaches shoulder height, rotate your wrist so that the bottom of the kettlebell is facing up.", "Catch the kettlebell at shoulder height with your elbow bent and your palm facing up.", "Lower the kettlebell back down to the starting position by reversing the movement.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["双脚分开与肩同宽站立，一只手握住壶铃，正手握住。", "稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。", "让壶铃垂在双腿之间，手臂完全伸展。", "以一种流畅的动作，爆发性地伸展你的臀部和膝盖，同时将壶铃拉向你的肩膀。", "当壶铃到达肩膀高度时，旋转手腕，使壶铃底部朝上。", "在与肩同高的位置抓住壶铃，肘部弯曲，手掌朝上。", "通过反向运动将壶铃降低回到起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["forearms", "shoulders"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，一只手握住壺鈴，正手握住。", "稍微彎曲膝蓋，臀部向前轉動，保持背部挺直，挺胸。", "讓壺鈴垂在雙腿之間，手臂完全伸展。", "以一種流暢的動作，爆發性地伸展你的臀部和膝蓋，同時將壺鈴拉向你的肩膀。", "當壺鈴到達肩膀高度時，旋轉手腕，使壺鈴底部朝上。", "在與肩同高的位置抓住壺鈴，肘部彎曲，手掌朝上。", "通過反向運動將壺鈴降低回到起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0526', 'exercise', 1, '{"id": "0526", "target": "biceps", "name_en": "kettlebell double alternating hang clean", "name_zh": "壶铃双侧交替悬垂翻举", "body_part": "upper arms", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0526-a4F9Oyc.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴雙側交替懸垂翻舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a kettlebell in each hand with an overhand grip.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.", "Allow the kettlebells to hang straight down in front of your body.", "In one fluid motion, explosively extend your hips and knees while shrugging your shoulders.", "As the kettlebells rise, pull them up towards your shoulders, keeping your elbows high and out to the sides.", "Catch the kettlebells at shoulder height, with your palms facing inward and your elbows pointing forward.", "Lower the kettlebells back down to the starting position and repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个壶铃，正手握住。", "稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。", "让壶铃垂直悬挂在身体前方。", "以一种流畅的动作，爆发性地伸展臀部和膝盖，同时耸肩。", "当壶铃上升时，将其拉向肩膀，保持肘部高且向两侧伸展。", "在与肩同高的位置抓住壶铃，手掌朝内，肘部向前。", "将壶铃放回起始位置，然后重复所需的重复次数。"], "secondary_muscles": ["forearms", "shoulders"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個壺鈴，正手握住。", "稍微彎曲膝蓋，臀部向前轉動，保持背部挺直，挺胸。", "讓壺鈴垂直懸掛在身體前方。", "以一種流暢的動作，爆發性地伸展臀部和膝蓋，同時聳肩。", "當壺鈴上升時，將其拉向肩膀，保持肘部高且向兩側伸展。", "在與肩同高的位置抓住壺鈴，手掌朝內，肘部向前。", "將壺鈴放回起始位置，然后重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0535', 'exercise', 1, '{"id": "0535", "target": "hamstrings", "name_en": "kettlebell hang clean", "name_zh": "壶铃悬垂翻举", "body_part": "upper legs", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0535-LHWF7us.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴懸垂翻舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a kettlebell in front of your thighs.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Lower the kettlebell towards the ground, allowing it to swing between your legs.", "Quickly extend your hips and knees, using the momentum to swing the kettlebell up to shoulder height.", "As the kettlebell reaches shoulder height, rotate your wrists and catch the kettlebell in the rack position, with your elbow tucked in and the kettlebell resting on your forearm.", "Lower the kettlebell back down to the starting position between your legs, and repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，将壶铃放在大腿前面。", "稍微弯曲膝盖，髋部向前转动，保持背部挺直。", "将壶铃放低至地面，使其在双腿之间摆动。", "快速伸展臀部和膝盖，利用动量将壶铃摆动到肩膀高度。", "当壶铃达到肩膀高度时，旋转手腕，将壶铃置于架子位置，肘部内收，壶铃靠在前臂上。", "将壶铃放回双腿之间的起始位置，然后重复所需的重复次数。"], "secondary_muscles": ["glutes", "quadriceps", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，將壺鈴放在大腿前面。", "稍微彎曲膝蓋，髖部向前轉動，保持背部挺直。", "將壺鈴放低至地面，使其在雙腿之間擺動。", "快速伸展臀部和膝蓋，利用動量將壺鈴擺動到肩膀高度。", "當壺鈴達到肩膀高度時，旋轉手腕，將壺鈴置于架子位置，肘部內收，壺鈴靠在前臂上。", "將壺鈴放回雙腿之間的起始位置，然后重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0527', 'exercise', 1, '{"id": "0527", "target": "delts", "name_en": "kettlebell double jerk", "name_zh": "壶铃双侧挺举", "body_part": "shoulders", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0527-tznL2Ad.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴雙側挺舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.", "Bend your knees slightly and engage your core.", "Press the kettlebells overhead, fully extending your arms.", "Bend your knees and quickly drop into a partial squat.", "Explosively extend your hips and knees, driving the kettlebells overhead.", "Lock out your arms and catch the kettlebells overhead with your knees slightly bent.", "Stand up straight and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个壶铃，与肩同高。", "稍微弯曲膝盖并启动核心。", "将壶铃压过头顶，充分伸展手臂。", "弯曲膝盖并快速半蹲。", "爆发性地伸展臀部和膝盖，将壶铃举过头顶。", "锁定双臂，将壶铃举过头顶，膝盖稍微弯曲。", "站直并回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "core"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個壺鈴，與肩同高。", "稍微彎曲膝蓋并啟動核心。", "將壺鈴壓過頭頂，充分伸展手臂。", "彎曲膝蓋并快速半蹲。", "爆發性地伸展臀部和膝蓋，將壺鈴舉過頭頂。", "鎖定雙臂，將壺鈴舉過頭頂，膝蓋稍微彎曲。", "站直并回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0528', 'exercise', 1, '{"id": "0528", "target": "delts", "name_en": "kettlebell double push press", "name_zh": "双壶铃借力推举", "body_part": "shoulders", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0528-I4KkPdl.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "雙壺鈴借力推舉", "instructions_en": ["Start by standing with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.", "Bend your knees slightly and engage your core.", "Initiate the movement by explosively extending your hips, knees, and ankles, driving the kettlebells overhead.", "As the kettlebells reach the top, press them fully overhead, locking out your arms.", "Lower the kettlebells back to the starting position by bending your elbows and bringing them back down to shoulder height.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先，双脚分开与肩同宽，每只手握住一个壶铃，与肩同高。", "稍微弯曲膝盖并启动核心。", "通过爆发性伸展臀部、膝盖和脚踝来开始运动，将壶铃举过头顶。", "当壶铃到达顶部时，将它们完全压过头顶，锁定手臂。", "弯曲肘部并将壶铃放回至肩膀高度，将壶铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "core"], "instructions_zh_hant": ["首先，雙腳分開與肩同寬，每只手握住一個壺鈴，與肩同高。", "稍微彎曲膝蓋并啟動核心。", "通過爆發性伸展臀部、膝蓋和腳踝來開始運動，將壺鈴舉過頭頂。", "當壺鈴到達頂部時，將它們完全壓過頭頂，鎖定手臂。", "彎曲肘部并將壺鈴放回至肩膀高度，將壺鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0529', 'exercise', 1, '{"id": "0529", "target": "delts", "name_en": "kettlebell double snatch", "name_zh": "壶铃双侧抓举", "body_part": "shoulders", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0529-M74kdvm.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴雙側抓舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at arm''s length in front of your thighs.", "Bend your knees slightly and hinge forward at the hips, keeping your back flat and chest up.", "In one explosive motion, extend your hips, knees, and ankles, and simultaneously pull the kettlebells up towards your shoulders.", "As the kettlebells reach shoulder level, rotate your wrists and punch the kettlebells overhead, fully extending your arms.", "Lower the kettlebells back down to the starting position and repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，每只手各握一个壶铃，放在大腿前面，与手臂保持一定距离。", "稍微弯曲膝盖，臀部向前转动，保持背部平坦，挺胸。", "以一种爆发力动作，伸展臀部、膝盖和脚踝，同时将壶铃拉向肩膀。", "当壶铃达到肩膀水平时，旋转手腕并将壶铃击过头顶，充分伸展手臂。", "将壶铃放回起始位置，然后重复所需的重复次数。"], "secondary_muscles": ["trapezius", "forearms", "core"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，每只手各握一個壺鈴，放在大腿前面，與手臂保持一定距離。", "稍微彎曲膝蓋，臀部向前轉動，保持背部平坦，挺胸。", "以一種爆發力動作，伸展臀部、膝蓋和腳踝，同時將壺鈴拉向肩膀。", "當壺鈴達到肩膀水平時，旋轉手腕并將壺鈴擊過頭頂，充分伸展手臂。", "將壺鈴放回起始位置，然后重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0530', 'exercise', 1, '{"id": "0530", "target": "abs", "name_en": "kettlebell double windmill", "name_zh": "壶铃双侧风车", "body_part": "waist", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0530-OaE7CpD.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴雙側風車", "instructions_en": ["Stand with your feet shoulder-width apart, holding a kettlebell in your right hand.", "Extend your right arm overhead, keeping your eyes on the kettlebell.", "Rotate your left foot 45 degrees to the left and your right foot 90 degrees to the right.", "Bend at the waist to the left, keeping your right arm extended overhead.", "Lower the kettlebell towards the ground, reaching towards your left foot.", "Pause for a moment, then engage your core and push through your right foot to return to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["双脚分开与肩同宽站立，右手握住壶铃。", "将右臂伸过头顶，眼睛盯着壶铃。", "左脚向左旋转 45 度，右脚向右旋转 90 度。", "腰部向左弯曲，保持右臂伸过头顶。", "将壶铃向地面降低，伸向左脚。", "暂停片刻，然后启动核心并推动右脚返回起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["shoulders", "hamstrings"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，右手握住壺鈴。", "將右臂伸過頭頂，眼睛盯著壺鈴。", "左腳向左旋轉 45 度，右腳向右旋轉 90 度。", "腰部向左彎曲，保持右臂伸過頭頂。", "將壺鈴向地面降低，伸向左腳。", "暫停片刻，然后啟動核心并推動右腳返回起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0531', 'exercise', 1, '{"id": "0531", "target": "pectorals", "name_en": "kettlebell extended range one arm press on floor", "name_zh": "壶铃单臂地板卧推（加大幅度）", "body_part": "chest", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0531-rseLfH3.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴單臂地板臥推（加大幅度）", "instructions_en": ["Start by lying on your back on the floor with your knees bent and feet flat on the ground.", "Hold a kettlebell in one hand, with your palm facing towards your feet.", "Extend your arm straight up towards the ceiling, keeping your elbow locked and your wrist straight.", "Slowly lower the kettlebell back down to the starting position, maintaining control throughout the movement.", "Repeat for the desired number of repetitions, then switch to the other arm."], "instructions_zh": ["首先仰卧在地板上，膝盖弯曲，双脚平放在地面上。", "一只手握住壶铃，手掌朝向脚部。", "将手臂伸直向上伸向天花板，保持肘部锁定且手腕伸直。", "慢慢地将壶铃放回起始位置，在整个运动过程中保持控制。", "重复所需的重复次数，然后换到另一只手臂。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["首先仰臥在地板上，膝蓋彎曲，雙腳平放在地面上。", "一只手握住壺鈴，手掌朝向腳部。", "將手臂伸直向上伸向天花板，保持肘部鎖定且手腕伸直。", "慢慢地將壺鈴放回起始位置，在整個運動過程中保持控制。", "重復所需的重復次數，然后換到另一只手臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0532', 'exercise', 1, '{"id": "0532", "target": "abs", "name_en": "kettlebell figure 8", "name_zh": "壶铃8字绕环", "body_part": "waist", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0532-L4ay0PW.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴8字繞環", "instructions_en": ["Stand with your feet shoulder-width apart, holding a kettlebell in one hand.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Pass the kettlebell between your legs, switching hands as it reaches the back of your legs.", "As the kettlebell comes forward, pass it to the other hand between your legs.", "Continue passing the kettlebell between your legs in a figure 8 motion.", "Maintain a steady pace and engage your core throughout the exercise.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，一只手握住壶铃。", "稍微弯曲膝盖，髋部向前转动，保持背部挺直。", "将壶铃放在双腿之间，当壶铃到达双腿后部时交换双手。", "当壶铃向前移动时，将其传递到两腿之间的另一只手。", "继续以 8 字形动作将壶铃传递到双腿之间。", "在整个练习过程中保持稳定的节奏并调动核心力量。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，一只手握住壺鈴。", "稍微彎曲膝蓋，髖部向前轉動，保持背部挺直。", "將壺鈴放在雙腿之間，當壺鈴到達雙腿后部時交換雙手。", "當壺鈴向前移動時，將其傳遞到兩腿之間的另一只手。", "繼續以 8 字形動作將壺鈴傳遞到雙腿之間。", "在整個練習過程中保持穩定的節奏并調動核心力量。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0533', 'exercise', 1, '{"id": "0533", "target": "glutes", "name_en": "kettlebell front squat", "name_zh": "壶铃前蹲", "body_part": "upper legs", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0533-DB0n8AG.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴前蹲", "instructions_en": ["Stand with your feet shoulder-width apart, toes slightly turned out.", "Hold the kettlebell with both hands in front of your chest, close to your body.", "Engage your core and keep your chest up as you lower your hips down and back, as if sitting into a chair.", "Lower until your thighs are parallel to the ground, or as low as you can comfortably go.", "Drive through your heels to stand back up, squeezing your glutes at the top.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站立，双脚分开与肩同宽，脚趾稍微向外。", "双手将壶铃放在胸前，靠近身体。", "收紧核心并保持挺胸，同时降低臀部和向后倾斜，就像坐在椅子上一样。", "降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。", "通过脚跟发力站起来，在顶部挤压臀部。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["站立，雙腳分開與肩同寬，腳趾稍微向外。", "雙手將壺鈴放在胸前，靠近身體。", "收緊核心并保持挺胸，同時降低臀部和向后傾斜，就像坐在椅子上一樣。", "降低直到大腿與地面平行，或者盡可能降低到您能舒服的高度。", "通過腳跟發力站起來，在頂部擠壓臀部。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0534', 'exercise', 1, '{"id": "0534", "target": "glutes", "name_en": "kettlebell goblet squat", "name_zh": "壶铃高脚杯深蹲", "body_part": "upper legs", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0534-ZA8b5hc.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴高腳杯深蹲", "instructions_en": ["Stand with your feet shoulder-width apart, holding a kettlebell close to your chest with both hands.", "Keeping your chest up and core engaged, lower your body down into a squat position by bending at the knees and hips.", "Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.", "Pause for a moment at the bottom, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手握住壶铃靠近胸部。", "保持胸部挺直，核心收紧，弯曲膝盖和臀部，将身体降低至蹲姿。", "继续降低，直到大腿与地面平行，或者尽可能低。", "在底部停顿片刻，然后推动脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手握住壺鈴靠近胸部。", "保持胸部挺直，核心收緊，彎曲膝蓋和臀部，將身體降低至蹲姿。", "繼續降低，直到大腿與地面平行，或者盡可能低。", "在底部停頓片刻，然后推動腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0537', 'exercise', 1, '{"id": "0537", "target": "delts", "name_en": "kettlebell one arm clean and jerk", "name_zh": "壶铃单臂翻举与挺举", "body_part": "shoulders", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0537-vzAxBtt.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴單臂翻舉與挺舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.", "Bend your knees slightly and hinge at the hips, lowering the kettlebell between your legs.", "Explosively extend your hips, knees, and ankles, using the momentum to swing the kettlebell up to shoulder height.", "As the kettlebell reaches shoulder height, rotate your wrist and punch your hand straight up, locking out your arm overhead.", "Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，一只手握住壶铃，正手握住。", "稍微弯曲膝盖并以臀部为铰链，将壶铃放在两腿之间。", "爆发性地伸展你的臀部、膝盖和脚踝，利用动量将壶铃摆动到肩膀的高度。", "当壶铃到达肩膀高度时，旋转手腕并向上挥拳，将手臂锁定在头顶上方。", "将壶铃放回起始位置，然后重复所需的重复次数。"], "secondary_muscles": ["triceps", "core"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，一只手握住壺鈴，正手握住。", "稍微彎曲膝蓋并以臀部為鉸鏈，將壺鈴放在兩腿之間。", "爆發性地伸展你的臀部、膝蓋和腳踝，利用動量將壺鈴擺動到肩膀的高度。", "當壺鈴到達肩膀高度時，旋轉手腕并向上揮拳，將手臂鎖定在頭頂上方。", "將壺鈴放回起始位置，然后重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1298', 'exercise', 1, '{"id": "1298", "target": "pectorals", "name_en": "kettlebell one arm floor press", "name_zh": "壶铃单臂地板卧推", "body_part": "chest", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/1298-rg59QCH.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴單臂地板臥推", "instructions_en": ["Lie flat on your back on the floor with your knees bent and feet flat on the ground.", "Hold the kettlebell in one hand with your palm facing towards your feet and your arm extended straight up towards the ceiling.", "Slowly lower the kettlebell towards your chest by bending your elbow, keeping your upper arm close to your body.", "Pause for a moment when the kettlebell is just above your chest, then push it back up to the starting position by extending your elbow.", "Repeat for the desired number of repetitions, then switch to the other arm."], "instructions_zh": ["仰卧在地板上，膝盖弯曲，双脚平放在地面上。", "一只手握住壶铃，手掌朝向脚部，手臂笔直向上伸向天花板。", "弯曲肘部，慢慢将壶铃降低到胸部，保持上臂靠近身体。", "当壶铃位于胸部正上方时暂停片刻，然后通过伸展肘部将壶铃推回起始位置。", "重复所需的重复次数，然后换到另一只手臂。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["仰臥在地板上，膝蓋彎曲，雙腳平放在地面上。", "一只手握住壺鈴，手掌朝向腳部，手臂筆直向上伸向天花板。", "彎曲肘部，慢慢將壺鈴降低到胸部，保持上臂靠近身體。", "當壺鈴位于胸部正上方時暫停片刻，然后通過伸展肘部將壺鈴推回起始位置。", "重復所需的重復次數，然后換到另一只手臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0538', 'exercise', 1, '{"id": "0538", "target": "delts", "name_en": "kettlebell one arm jerk", "name_zh": "壶铃单臂挺举", "body_part": "shoulders", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0538-S37C94C.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴單臂挺舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder height.", "Bend your knees slightly and engage your core.", "Press the kettlebell overhead in a straight line, fully extending your arm.", "As you press the kettlebell overhead, simultaneously dip your knees and quickly straighten them to generate momentum.", "As the kettlebell reaches its highest point, quickly drop underneath it by bending your knees and hips.", "Catch the kettlebell with a slight bend in your knees and hips, and your arm fully extended overhead.", "Stand up straight, fully extending your knees and hips, and stabilize the kettlebell overhead.", "Lower the kettlebell back to the starting position by bending your knees and hips, and repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，一只手握住壶铃，与肩同高。", "稍微弯曲膝盖并启动核心。", "将壶铃沿直线压过头顶，充分伸展手臂。", "当你将壶铃举过头顶时，同时弯曲膝盖并快速伸直以产生动力。", "当壶铃到达最高点时，弯曲膝盖和臀部，快速落到壶铃下方。", "膝盖和臀部稍微弯曲，抓住壶铃，手臂完全伸过头顶。", "站直，充分伸展膝盖和臀部，并将壶铃稳定在头顶上。", "弯曲膝盖和臀部，将壶铃放回起始位置，然后重复所需的重复次数。"], "secondary_muscles": ["triceps", "core"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，一只手握住壺鈴，與肩同高。", "稍微彎曲膝蓋并啟動核心。", "將壺鈴沿直線壓過頭頂，充分伸展手臂。", "當你將壺鈴舉過頭頂時，同時彎曲膝蓋并快速伸直以產生動力。", "當壺鈴到達最高點時，彎曲膝蓋和臀部，快速落到壺鈴下方。", "膝蓋和臀部稍微彎曲，抓住壺鈴，手臂完全伸過頭頂。", "站直，充分伸展膝蓋和臀部，并將壺鈴穩定在頭頂上。", "彎曲膝蓋和臀部，將壺鈴放回起始位置，然后重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0539', 'exercise', 1, '{"id": "0539", "target": "delts", "name_en": "kettlebell one arm military press to the side", "name_zh": "壶铃单臂侧向推举", "body_part": "shoulders", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0539-yCvYdi7.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴單臂側向推舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder height.", "Engage your core and keep your back straight.", "Press the kettlebell overhead, extending your arm fully.", "Pause for a moment at the top, then slowly lower the kettlebell back to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["双脚分开与肩同宽站立，一只手握住壶铃，与肩同高。", "启动你的核心并保持背部挺直。", "将壶铃压过头顶，充分伸展手臂。", "在顶部暂停片刻，然后慢慢将壶铃放回起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["triceps", "core"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，一只手握住壺鈴，與肩同高。", "啟動你的核心并保持背部挺直。", "將壺鈴壓過頭頂，充分伸展手臂。", "在頂部暫停片刻，然后慢慢將壺鈴放回起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0540', 'exercise', 1, '{"id": "0540", "target": "delts", "name_en": "kettlebell one arm push press", "name_zh": "壶铃单臂借力推举", "body_part": "shoulders", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0540-osdXT3K.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴單臂借力推舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder level.", "Bend your knees slightly and engage your core.", "Press the kettlebell overhead by extending your arm and fully extending your legs.", "Lower the kettlebell back to the starting position by bending your knees and bringing the kettlebell back to your shoulder.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["双脚分开与肩同宽站立，一只手握住壶铃，与肩同高。", "稍微弯曲膝盖并启动核心。", "伸展手臂并完全伸展双腿，将壶铃压过头顶。", "弯曲膝盖并将壶铃放回肩膀，将壶铃放回起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["triceps", "core"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，一只手握住壺鈴，與肩同高。", "稍微彎曲膝蓋并啟動核心。", "伸展手臂并完全伸展雙腿，將壺鈴壓過頭頂。", "彎曲膝蓋并將壺鈴放回肩膀，將壺鈴放回起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0541', 'exercise', 1, '{"id": "0541", "target": "upper back", "name_en": "kettlebell one arm row", "name_zh": "壶铃单臂划船", "body_part": "back", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0541-g9AsZ8P.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴單臂劃船", "instructions_en": ["Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.", "Pull the kettlebell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the kettlebell back down to the starting position.", "Repeat for the desired number of repetitions, then switch sides and repeat with the other arm."], "instructions_zh": ["双脚分开与肩同宽站立，一只手握住壶铃，正手握住。", "稍微弯曲膝盖，髋部向前转动，保持背部挺直，核心肌群参与。", "将壶铃向上拉向胸部，保持肘部靠近身体并将肩胛骨挤压在一起。", "在顶部暂停片刻，然后慢慢将壶铃放回起始位置。", "重复所需的重复次数，然后换边并用另一只手臂重复。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，一只手握住壺鈴，正手握住。", "稍微彎曲膝蓋，髖部向前轉動，保持背部挺直，核心肌群參與。", "將壺鈴向上拉向胸部，保持肘部靠近身體并將肩胛骨擠壓在一起。", "在頂部暫停片刻，然后慢慢將壺鈴放回起始位置。", "重復所需的重復次數，然后換邊并用另一只手臂重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3640', 'exercise', 1, '{"id": "3640", "target": "abs", "name_en": "knee touch crunch", "name_zh": "膝部触碰卷腹", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3640-dTg95eZ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "膝部觸碰卷腹", "instructions_en": ["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, lift your shoulder blades off the ground and reach your right hand towards your left knee.", "Return to the starting position and repeat, this time reaching your left hand towards your right knee.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["平躺，膝盖弯曲，双脚平放在地上。", "将双手放在脑后，肘部朝外。", "收紧腹肌，将肩胛骨抬离地面，并将右手伸向左膝盖。", "返回起始位置并重复，这次将左手伸向右膝盖。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["平躺，膝蓋彎曲，雙腳平放在地上。", "將雙手放在腦后，肘部朝外。", "收緊腹肌，將肩胛骨抬離地面，并將右手伸向左膝蓋。", "返回起始位置并重復，這次將左手伸向右膝蓋。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0542', 'exercise', 1, '{"id": "0542", "target": "delts", "name_en": "kettlebell one arm snatch", "name_zh": "壶铃单臂抓举", "body_part": "shoulders", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0542-aXcUyKb.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴單臂抓舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a kettlebell in one hand between your legs.", "Bend your knees slightly and hinge at the hips, lowering the kettlebell towards the ground.", "Explosively extend your hips and knees, using the momentum to swing the kettlebell up towards your shoulder.", "As the kettlebell reaches shoulder height, rotate your hand and punch it straight up overhead, fully extending your arm.", "Lower the kettlebell back down between your legs and repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，一只手将壶铃放在两腿之间。", "稍微弯曲膝盖并铰接臀部，将壶铃降低到地面。", "爆发性地伸展你的臀部和膝盖，利用动量将壶铃向上摆动到你的肩膀上。", "当壶铃到达肩膀高度时，旋转你的手并将其直接击打到头顶，完全伸展你的手臂。", "将壶铃放回到双腿之间，然后重复所需的重复次数。"], "secondary_muscles": ["trapezius", "forearms", "core"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，一只手將壺鈴放在兩腿之間。", "稍微彎曲膝蓋并鉸接臀部，將壺鈴降低到地面。", "爆發性地伸展你的臀部和膝蓋，利用動量將壺鈴向上擺動到你的肩膀上。", "當壺鈴到達肩膀高度時，旋轉你的手并將其直接擊打到頭頂，完全伸展你的手臂。", "將壺鈴放回到雙腿之間，然后重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0543', 'exercise', 1, '{"id": "0543", "target": "delts", "name_en": "kettlebell pirate supper legs", "name_zh": "壶铃海盗式腿部训练", "body_part": "shoulders", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0543-kuXhl0o.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴海盜式腿部訓練", "instructions_en": ["Stand with your feet shoulder-width apart, holding a kettlebell in one hand.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Raise the kettlebell up to shoulder height, keeping your elbow close to your body.", "Extend your arm fully overhead, straightening your elbow.", "Lower the kettlebell back down to shoulder height, then return to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["双脚分开与肩同宽站立，一只手握住壶铃。", "稍微弯曲膝盖，髋部向前转动，保持背部挺直。", "将壶铃举至肩膀高度，保持肘部靠近身体。", "将手臂完全伸过头顶，伸直肘部。", "将壶铃降低至肩膀高度，然后返回起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["triceps", "forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，一只手握住壺鈴。", "稍微彎曲膝蓋，髖部向前轉動，保持背部挺直。", "將壺鈴舉至肩膀高度，保持肘部靠近身體。", "將手臂完全伸過頭頂，伸直肘部。", "將壺鈴降低至肩膀高度，然后返回起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0544', 'exercise', 1, '{"id": "0544", "target": "glutes", "name_en": "kettlebell pistol squat", "name_zh": "壶铃手枪式深蹲", "body_part": "upper legs", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0544-5bpPTHv.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴手槍式深蹲", "instructions_en": ["Stand with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands.", "Lift your left foot off the ground and extend it forward, keeping it parallel to the ground.", "Slowly lower your body down into a squat position, keeping your right foot flat on the ground and your left leg extended.", "Pause for a moment at the bottom of the squat, then push through your right heel to return to the starting position.", "Repeat for the desired number of repetitions, then switch legs."], "instructions_zh": ["双脚分开与肩同宽站立，双手握住壶铃放在胸前。", "将左脚抬离地面并向前伸展，保持与地面平行。", "慢慢地将身体降低到蹲姿，保持右脚平放在地面上，左腿伸展。", "在深蹲底部暂停片刻，然后推动右脚跟返回到起始位置。", "重复所需的重复次数，然后换腿。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手握住壺鈴放在胸前。", "將左腳抬離地面并向前伸展，保持與地面平行。", "慢慢地將身體降低到蹲姿，保持右腳平放在地面上，左腿伸展。", "在深蹲底部暫停片刻，然后推動右腳跟返回到起始位置。", "重復所需的重復次數，然后換腿。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0545', 'exercise', 1, '{"id": "0545", "target": "pectorals", "name_en": "kettlebell plyo push-up", "name_zh": "壶铃爆发式俯卧撑", "body_part": "chest", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0545-ktf3nvW.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴爆發式俯臥撐", "instructions_en": ["Start in a high plank position with your hands on the kettlebells, shoulder-width apart.", "Lower your chest towards the ground, keeping your elbows close to your body.", "Push through your hands explosively, lifting your hands off the kettlebells and extending your arms fully.", "Land softly back on the kettlebells and immediately lower your chest back down for the next repetition.", "Repeat for the desired number of repetitions."], "instructions_zh": ["从高平板支撑位置开始，双手放在壶铃上，距离与肩同宽。", "将胸部压向地面，保持肘部靠近身体。", "爆发性地推动你的手，将你的手从壶铃上抬起并完全伸展你的手臂。", "轻轻地回到壶铃上，并立即降低胸部以进行下一次重复。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders", "core"], "instructions_zh_hant": ["從高平板支撐位置開始，雙手放在壺鈴上，距離與肩同寬。", "將胸部壓向地面，保持肘部靠近身體。", "爆發性地推動你的手，將你的手從壺鈴上抬起并完全伸展你的手臂。", "輕輕地回到壺鈴上，并立即降低胸部以進行下一次重復。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0546', 'exercise', 1, '{"id": "0546", "target": "delts", "name_en": "kettlebell seated press", "name_zh": "壶铃坐姿推举", "body_part": "shoulders", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0546-BkxB8LW.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴坐姿推舉", "instructions_en": ["Sit on a bench with your back straight and feet flat on the ground.", "Hold a kettlebell in each hand at shoulder height, palms facing forward.", "Press the kettlebells overhead, fully extending your arms.", "Lower the kettlebells back to shoulder height.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，背部挺直，双脚平放在地上。", "每只手握住一个壶铃，与肩同高，手掌朝前。", "将壶铃压过头顶，充分伸展手臂。", "将壶铃降低至肩膀高度。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "core"], "instructions_zh_hant": ["坐在長凳上，背部挺直，雙腳平放在地上。", "每只手握住一個壺鈴，與肩同高，手掌朝前。", "將壺鈴壓過頭頂，充分伸展手臂。", "將壺鈴降低至肩膀高度。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1438', 'exercise', 1, '{"id": "1438", "target": "delts", "name_en": "kettlebell seated two arm military press", "name_zh": "壶铃坐姿双臂肩上推举", "body_part": "shoulders", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/1438-ZEkjZDi.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴坐姿雙臂肩上推舉", "instructions_en": ["Sit on a bench with your back straight and feet flat on the ground.", "Hold a kettlebell in each hand at shoulder level with your palms facing forward.", "Press the kettlebells overhead by extending your arms fully.", "Pause for a moment at the top, then slowly lower the kettlebells back to shoulder level.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，背部挺直，双脚平放在地上。", "每只手握住一个壶铃，与肩同高，手掌朝前。", "完全伸展双臂，将壶铃压过头顶。", "在顶部暂停片刻，然后慢慢将壶铃放回肩部水平。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "upper back"], "instructions_zh_hant": ["坐在長凳上，背部挺直，雙腳平放在地上。", "每只手握住一個壺鈴，與肩同高，手掌朝前。", "完全伸展雙臂，將壺鈴壓過頭頂。", "在頂部暫停片刻，然后慢慢將壺鈴放回肩部水平。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0547', 'exercise', 1, '{"id": "0547", "target": "delts", "name_en": "kettlebell seesaw press", "name_zh": "壶铃交替跷跷板式推举", "body_part": "shoulders", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0547-UDm6cGl.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴交替蹺蹺板式推舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.", "Press one kettlebell overhead while keeping the other kettlebell at shoulder height.", "Lower the pressed kettlebell back to shoulder height while simultaneously pressing the other kettlebell overhead.", "Continue alternating the pressing motion, creating a seesaw-like movement.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个壶铃，与肩同高。", "将一个壶铃压过头顶，同时将另一个壶铃保持在肩膀高度。", "将按下的壶铃降低至肩膀高度，同时将另一个壶铃压过头顶。", "继续交替按压动作，形成跷跷板状的运动。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "core"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個壺鈴，與肩同高。", "將一個壺鈴壓過頭頂，同時將另一個壺鈴保持在肩膀高度。", "將按下的壺鈴降低至肩膀高度，同時將另一個壺鈴壓過頭頂。", "繼續交替按壓動作，形成蹺蹺板狀的運動。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0548', 'exercise', 1, '{"id": "0548", "target": "traps", "name_en": "kettlebell sumo high pull", "name_zh": "壶铃相扑高拉", "body_part": "back", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0548-8ARQ9Hw.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴相撲高拉", "instructions_en": ["Stand with your feet wider than shoulder-width apart, toes pointing outwards.", "Hold a kettlebell with both hands in front of your body, arms extended downwards.", "Bend your knees and lower your hips into a squat position, keeping your back straight.", "Drive through your heels and explosively extend your hips and knees, pulling the kettlebell up towards your chin.", "As you pull the kettlebell up, keep your elbows high and wide, and squeeze your shoulder blades together.", "Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions."], "instructions_zh": ["站立，双脚分开比肩宽，脚趾朝外。", "双手握住壶铃放在身体前方，手臂向下伸展。", "弯曲膝盖，降低臀部至下蹲位置，保持背部挺直。", "脚后跟发力，爆发性伸展臀部和膝盖，将壶铃拉向下巴。", "当你向上拉壶铃时，保持肘部高且宽，并将肩胛骨挤压在一起。", "将壶铃放回起始位置，然后重复所需的重复次数。"], "secondary_muscles": ["shoulders", "glutes", "hamstrings"], "instructions_zh_hant": ["站立，雙腳分開比肩寬，腳趾朝外。", "雙手握住壺鈴放在身體前方，手臂向下伸展。", "彎曲膝蓋，降低臀部至下蹲位置，保持背部挺直。", "腳后跟發力，爆發性伸展臀部和膝蓋，將壺鈴拉向下巴。", "當你向上拉壺鈴時，保持肘部高且寬，并將肩胛骨擠壓在一起。", "將壺鈴放回起始位置，然后重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0550', 'exercise', 1, '{"id": "0550", "target": "delts", "name_en": "kettlebell thruster", "name_zh": "壶铃深蹲推举", "body_part": "shoulders", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0550-yWxMvB5.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴深蹲推舉", "instructions_en": ["Start by standing with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands, palms facing each other.", "Lower into a squat position by bending your knees and pushing your hips back, keeping your chest up and your back straight.", "As you reach the bottom of the squat, explosively drive through your heels to stand up, simultaneously pressing the kettlebell overhead.", "Lock out your arms at the top of the movement, fully extending your elbows.", "Lower the kettlebell back to the starting position by reversing the movement, bending your elbows and lowering the weight back to your chest.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先，双脚分开与肩同宽站立，双手将壶铃放在胸前，手掌相对。", "弯曲膝盖并将臀部向后推，保持挺胸、背部挺直，进入蹲姿。", "当你到达深蹲底部时，爆发性地通过脚后跟站起来，同时将壶铃压过头顶。", "在动作的最高点锁定你的手臂，完全伸展你的肘部。", "通过反转动作，弯曲肘部并将重量放回胸部，将壶铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "glutes", "core"], "instructions_zh_hant": ["首先，雙腳分開與肩同寬站立，雙手將壺鈴放在胸前，手掌相對。", "彎曲膝蓋并將臀部向后推，保持挺胸、背部挺直，進入蹲姿。", "當你到達深蹲底部時，爆發性地通過腳后跟站起來，同時將壺鈴壓過頭頂。", "在動作的最高點鎖定你的手臂，完全伸展你的肘部。", "通過反轉動作，彎曲肘部并將重量放回胸部，將壺鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0551', 'exercise', 1, '{"id": "0551", "target": "glutes", "name_en": "kettlebell turkish get up (squat style)", "name_zh": "壶铃土耳其起立（深蹲式）", "body_part": "upper legs", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0551-Ha7SZ3y.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴土耳其起立（深蹲式）", "instructions_en": ["Start by lying on your back with your legs extended and the kettlebell held in your right hand, arm fully extended above your shoulder.", "Bend your right knee and place your right foot flat on the ground, keeping your left leg extended.", "Pressing through your right foot, lift your hips off the ground, coming into a bridge position.", "Slide your left leg underneath your body, bending your left knee and placing your left foot flat on the ground.", "Rotate your torso to the left, bringing your left hand to the ground for support.", "Pressing through your right foot and left hand, lift your torso off the ground, coming into a kneeling position.", "From the kneeling position, stand up, keeping the kettlebell extended overhead.", "Reverse the movement to return to the starting position.", "Repeat the exercise on the other side, starting with the kettlebell in your left hand."], "instructions_zh": ["首先仰卧，双腿伸展，右手握住壶铃，手臂完全伸展到肩膀上方。", "弯曲右膝，将右脚平放在地面上，保持左腿伸展。", "压右脚，将臀部抬离地面，进入桥位。", "将左腿滑到身体下方，弯曲左膝并将左脚平放在地面上。", "将躯干向左旋转，将左手放在地面上以获得支撑。", "压右脚和左手，将躯干抬离地面，形成跪姿。", "从跪姿站起来，保持壶铃伸过头顶。", "反向运动以返回到起始位置。", "从左手的壶铃开始，在另一侧重复练习。"], "secondary_muscles": ["quadriceps", "hamstrings", "core"], "instructions_zh_hant": ["首先仰臥，雙腿伸展，右手握住壺鈴，手臂完全伸展到肩膀上方。", "彎曲右膝，將右腳平放在地面上，保持左腿伸展。", "壓右腳，將臀部抬離地面，進入橋位。", "將左腿滑到身體下方，彎曲左膝并將左腳平放在地面上。", "將軀幹向左旋轉，將左手放在地面上以獲得支撐。", "壓右腳和左手，將軀幹抬離地面，形成跪姿。", "從跪姿站起來，保持壺鈴伸過頭頂。", "反向運動以返回到起始位置。", "從左手的壺鈴開始，在另一側重復練習。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0553', 'exercise', 1, '{"id": "0553", "target": "delts", "name_en": "kettlebell two arm military press", "name_zh": "壶铃双臂肩上推举", "body_part": "shoulders", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0553-blBXysN.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴雙臂肩上推舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder level with your palms facing forward.", "Engage your core and press the kettlebells overhead, fully extending your arms.", "Pause for a moment at the top, then slowly lower the kettlebells back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个壶铃，与肩同高，手掌朝前。", "启动你的核心并将壶铃压过头顶，充分伸展你的手臂。", "在顶部暂停片刻，然后慢慢将壶铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "upper back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個壺鈴，與肩同高，手掌朝前。", "啟動你的核心并將壺鈴壓過頭頂，充分伸展你的手臂。", "在頂部暫停片刻，然后慢慢將壺鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1345', 'exercise', 1, '{"id": "1345", "target": "upper back", "name_en": "kettlebell two arm row", "name_zh": "壶铃双臂划船", "body_part": "back", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/1345-wf24o8S.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴雙臂劃船", "instructions_en": ["Stand with your feet shoulder-width apart, knees slightly bent, and hold a kettlebell in each hand with your palms facing your body.", "Bend forward at the hips, keeping your back straight and your core engaged.", "Pull the kettlebells up towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the kettlebells back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，膝盖稍微弯曲，双手各握一个壶铃，手掌朝向身体。", "臀部向前弯曲，保持背部挺直，核心肌群参与。", "将壶铃拉向胸部，将肩胛骨挤压在一起。", "在顶部暂停片刻，然后慢慢将壶铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，膝蓋稍微彎曲，雙手各握一個壺鈴，手掌朝向身體。", "臀部向前彎曲，保持背部挺直，核心肌群參與。", "將壺鈴拉向胸部，將肩胛骨擠壓在一起。", "在頂部暫停片刻，然后慢慢將壺鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0554', 'exercise', 1, '{"id": "0554", "target": "abs", "name_en": "kettlebell windmill", "name_zh": "壶铃风车", "body_part": "waist", "equipment": "kettlebell", "gif_asset": "assets/fitness/videos/0554-9Tkqa9O.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "壺鈴風車", "instructions_en": ["Stand with your feet shoulder-width apart, holding a kettlebell in your right hand overhead.", "Rotate your left foot outwards about 45 degrees and keep your right foot pointing forward.", "Bend your torso to the left side, keeping your right arm extended overhead and your eyes on the kettlebell.", "Lower your torso as far as you can while keeping your right arm straight and your left arm extended to the side.", "Pause for a moment, then return to the starting position by pushing through your right foot and engaging your obliques.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["双脚分开与肩同宽站立，右手握住壶铃举过头顶。", "将左脚向外旋转约 45 度，并保持右脚指向前方。", "将你的躯干向左侧弯曲，保持右臂伸过头顶，眼睛盯着壶铃。", "尽可能降低躯干，同时保持右臂伸直，左臂向一侧伸展。", "暂停片刻，然后通过推动右脚并接合斜肌返回到起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["obliques", "shoulders"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，右手握住壺鈴舉過頭頂。", "將左腳向外旋轉約 45 度，并保持右腳指向前方。", "將你的軀幹向左側彎曲，保持右臂伸過頭頂，眼睛盯著壺鈴。", "盡可能降低軀幹，同時保持右臂伸直，左臂向一側伸展。", "暫停片刻，然后通過推動右腳并接合斜肌返回到起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0555', 'exercise', 1, '{"id": "0555", "target": "hamstrings", "name_en": "kick out sit", "name_zh": "坐姿踢腿", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0555-v7p5bYl.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "坐姿踢腿", "instructions_en": ["Sit on the edge of a bench or chair with your feet flat on the ground and your knees bent at a 90-degree angle.", "Lean back slightly and place your hands on the edge of the bench or chair for support.", "Engaging your hamstrings, lift your feet off the ground and extend your legs straight out in front of you.", "Pause for a moment at the top, then slowly bend your knees and bring your feet back towards your body.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳或椅子的边缘，双脚平放在地上，膝盖弯曲成 90 度角。", "稍微向后倾斜，将双手放在长凳或椅子的边缘以获得支撑。", "启动腿筋，将脚抬离地面，并将双腿伸直到身前。", "在顶部停顿片刻，然后慢慢弯曲膝盖，将脚放回身体。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "glutes"], "instructions_zh_hant": ["坐在長凳或椅子的邊緣，雙腳平放在地上，膝蓋彎曲成 90 度角。", "稍微向后傾斜，將雙手放在長凳或椅子的邊緣以獲得支撐。", "啟動腿筋，將腳抬離地面，并將雙腿伸直到身前。", "在頂部停頓片刻，然后慢慢彎曲膝蓋，將腳放回身體。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0558', 'exercise', 1, '{"id": "0558", "target": "lats", "name_en": "kipping muscle up", "name_zh": "借力双力臂", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0558-pM07UxU.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "借力雙力臂", "instructions_en": ["Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.", "Engage your core and use a swinging motion to generate momentum.", "As you swing forward, pull your chest towards the bar, using your lats and biceps to initiate the movement.", "Continue the upward motion until your chest reaches the bar, then transition into a dip position by pushing down on the bar and extending your arms.", "Lower yourself back down to the starting position by bending your arms and controlling the descent.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先，用正手握法悬挂在引体向上杆上，双手分开的距离略大于肩宽。", "启动你的核心并使用摆动动作来产生动力。", "当你向前挥杆时，将胸部拉向杠铃，用背阔肌和二头肌开始动作。", "继续向上运动，直到胸部到达杠铃，然后向下推杠铃并伸展手臂，过渡到双臂屈伸姿势。", "弯曲手臂并控制下降，将自己放回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "triceps", "shoulders", "core"], "instructions_zh_hant": ["首先，用正手握法懸掛在引體向上桿上，雙手分開的距離略大于肩寬。", "啟動你的核心并使用擺動動作來產生動力。", "當你向前揮桿時，將胸部拉向杠鈴，用背闊肌和二頭肌開始動作。", "繼續向上運動，直到胸部到達杠鈴，然后向下推杠鈴并伸展手臂，過渡到雙臂屈伸姿勢。", "彎曲手臂并控制下降，將自己放回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1420', 'exercise', 1, '{"id": "1420", "target": "glutes", "name_en": "kneeling jump squat", "name_zh": "跪姿跳跃深蹲", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/1420-UgDm3oy.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "跪姿跳躍深蹲", "instructions_en": ["Start by kneeling on the ground with your feet hip-width apart and your toes pointing forward.", "Hold a barbell across your upper back, resting it on your shoulders.", "Engage your core and glutes, then explosively jump up into the air, extending your hips and knees.", "As you jump, push through your toes and fully extend your ankles, knees, and hips.", "Land softly back on the ground, bending your knees to absorb the impact.", "Immediately go into the next repetition, repeating the jump squat motion."], "instructions_zh": ["首先跪在地上，双脚分开与臀部同宽，脚趾向前。", "将杠铃放在上背部，将其放在肩膀上。", "启动你的核心和臀部，然后爆发性地跳到空中，伸展你的臀部和膝盖。", "跳跃时，用脚趾推动并充分伸展脚踝、膝盖和臀部。", "轻轻地回到地面，弯曲膝盖以吸收冲击力。", "立即进入下一个重复，重复跳蹲动作。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["首先跪在地上，雙腳分開與臀部同寬，腳趾向前。", "將杠鈴放在上背部，將其放在肩膀上。", "啟動你的核心和臀部，然后爆發性地跳到空中，伸展你的臀部和膝蓋。", "跳躍時，用腳趾推動并充分伸展腳踝、膝蓋和臀部。", "輕輕地回到地面，彎曲膝蓋以吸收沖擊力。", "立即進入下一個重復，重復跳蹲動作。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1346', 'exercise', 1, '{"id": "1346", "target": "lats", "name_en": "kneeling lat stretch", "name_zh": "跪姿背阔肌拉伸", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1346-f38OEuO.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "跪姿背闊肌拉伸", "instructions_en": ["Kneel on the ground with your knees hip-width apart and your toes pointing back.", "Extend your arms overhead and interlace your fingers.", "Keeping your back straight, slowly lean to the right side, feeling a stretch in your left lat muscle.", "Hold the stretch for 20-30 seconds, then return to the starting position.", "Repeat the stretch on the left side, leaning to the left and feeling a stretch in your right lat muscle.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["跪在地上，膝盖分开与臀部同宽，脚趾向后。", "将双臂伸过头顶，手指交叉。", "保持背部挺直，慢慢向右侧倾斜，感受左侧背阔肌的拉伸。", "保持伸展动作 20-30 秒，然后回到起始位置。", "在左侧重复该拉伸动作，向左侧倾斜，感受右侧背阔肌的拉伸。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["跪在地上，膝蓋分開與臀部同寬，腳趾向后。", "將雙臂伸過頭頂，手指交叉。", "保持背部挺直，慢慢向右側傾斜，感受左側背闊肌的拉伸。", "保持伸展動作 20-30 秒，然后回到起始位置。", "在左側重復該拉伸動作，向左側傾斜，感受右側背闊肌的拉伸。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3239', 'exercise', 1, '{"id": "3239", "target": "abs", "name_en": "kneeling plank tap shoulder (male)", "name_zh": "跪姿平板支撑点触肩部（男性示范）", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3239-h1ezqSu.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "跪姿平板支撐點觸肩部（男性示范）", "instructions_en": ["Start in a kneeling position with your hands on the ground, shoulder-width apart.", "Extend your legs behind you, resting on your toes, and lift your body into a plank position.", "Keeping your core engaged and your hips stable, lift one hand off the ground and tap the opposite shoulder.", "Return the hand to the ground and repeat with the other hand.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["从跪姿开始，双手放在地上，与肩同宽。", "将双腿伸到身后，用脚趾支撑，将身体抬起成平板支撑姿势。", "保持核心参与并保持臀部稳定，将一只手抬离地面并拍打另一侧的肩膀。", "将手放回地面并用另一只手重复此操作。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["從跪姿開始，雙手放在地上，與肩同寬。", "將雙腿伸到身后，用腳趾支撐，將身體抬起成平板支撐姿勢。", "保持核心參與并保持臀部穩定，將一只手抬離地面并拍打另一側的肩膀。", "將手放回地面并用另一只手重復此操作。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3211', 'exercise', 1, '{"id": "3211", "target": "pectorals", "name_en": "kneeling push-up (male)", "name_zh": "跪姿俯卧撑（男性示范）", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3211-ZOuKWir.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "跪姿俯臥撐（男性示范）", "instructions_en": ["Start by kneeling on the ground with your hands shoulder-width apart, fingers pointing forward.", "Extend your legs behind you, resting on the balls of your feet, so that your body forms a straight line from head to heels.", "Engage your core and lower your body towards the ground by bending your elbows, keeping them close to your sides.", "Continue lowering until your chest is just above the ground, then push back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先跪在地上，双手与肩同宽，手指指向前方。", "将双腿伸到身后，放在脚掌上，使身体从头到脚跟形成一条直线。", "弯曲肘部，保持核心靠近身体两侧，将身体压向地面。", "继续降低，直到胸部刚好高于地面，然后伸直手臂，将其推回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["首先跪在地上，雙手與肩同寬，手指指向前方。", "將雙腿伸到身后，放在腳掌上，使身體從頭到腳跟形成一條直線。", "彎曲肘部，保持核心靠近身體兩側，將身體壓向地面。", "繼續降低，直到胸部剛好高于地面，然后伸直手臂，將其推回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3288', 'exercise', 1, '{"id": "3288", "target": "pectorals", "name_en": "korean dips", "name_zh": "韩式臂屈伸", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3288-rWoBmi5.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "韓式臂屈伸", "instructions_en": ["Position yourself between two parallel bars with your arms extended and supporting your body weight.", "Lower your body by bending your elbows until your upper arms are parallel to the ground.", "Pause for a moment, then push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将自己定位在两个双杠之间，双臂伸展并支撑体重。", "弯曲肘部降低身体，直到上臂与地面平行。", "暂停片刻，然后伸直手臂，将自己推回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["將自己定位在兩個雙杠之間，雙臂伸展并支撐體重。", "彎曲肘部降低身體，直到上臂與地面平行。", "暫停片刻，然后伸直手臂，將自己推回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0624', 'exercise', 1, '{"id": "0624", "target": "glutes", "name_en": "march sit (wall)", "name_zh": "靠墙静蹲交替抬腿", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0624-sVQCCeG.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "靠墻靜蹲交替抬腿", "instructions_en": ["Stand with your back against a wall and your feet hip-width apart.", "Slowly slide your back down the wall until your knees are bent at a 90-degree angle.", "Lift your right foot off the ground and bring your knee towards your chest.", "Lower your right foot back down and lift your left foot off the ground, bringing your knee towards your chest.", "Continue alternating between lifting your right and left foot for the desired number of repetitions."], "instructions_zh": ["背靠墙站立，双脚分开与臀部同宽。", "慢慢地将背部滑下墙壁，直到膝盖弯曲成 90 度角。", "将右脚抬离地面，并将膝盖靠近胸部。", "将右脚放低，将左脚抬离地面，将膝盖靠近胸部。", "继续交替抬起右脚和左脚，达到所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["背靠墻站立，雙腳分開與臀部同寬。", "慢慢地將背部滑下墻壁，直到膝蓋彎曲成 90 度角。", "將右腳抬離地面，并將膝蓋靠近胸部。", "將右腳放低，將左腳抬離地面，將膝蓋靠近胸部。", "繼續交替抬起右腳和左腳，達到所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3418', 'exercise', 1, '{"id": "3418", "target": "lats", "name_en": "l-pull-up", "name_zh": "L形引体向上", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3418-d1GgzTU.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "L形引體向上", "instructions_en": ["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.", "Hang with your arms fully extended and your body straight.", "Engage your lats and biceps to pull your body up towards the bar, keeping your elbows close to your body.", "Continue pulling until your chin is above the bar.", "Pause for a moment at the top, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["正手握住引体向上杆，握距略宽于肩宽。", "双臂完全伸展，身体伸直。", "收紧背阔肌和二头肌，将身体拉向杠铃杆，保持肘部靠近身体。", "继续拉，直到下巴位于杠铃上方。", "在顶部停顿片刻，然后慢慢将身体放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["正手握住引體向上桿，握距略寬于肩寬。", "雙臂完全伸展，身體伸直。", "收緊背闊肌和二頭肌，將身體拉向杠鈴桿，保持肘部靠近身體。", "繼續拉，直到下巴位于杠鈴上方。", "在頂部停頓片刻，然后慢慢將身體放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1439', 'exercise', 1, '{"id": "1439", "target": "traps", "name_en": "lever gripless shrug v. 2", "name_zh": "器械免握耸肩变式2", "body_part": "back", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/1439-cbuFJrn.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械免握聳肩變式2", "instructions_en": ["Adjust the seat height and position yourself on the machine with your back against the pad.", "Grasp the handles or bars with an overhand grip, keeping your arms straight.", "Keeping your back straight, lift your shoulders up towards your ears as high as possible.", "Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度并将自己放在机器上，背部靠在垫子上。", "正手握住手柄或杆，保持手臂伸直。", "保持背部挺直，将肩膀尽可能高地抬向耳朵。", "保持收缩一会儿，然后慢慢将肩膀放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "forearms"], "instructions_zh_hant": ["調整座椅高度并將自己放在機器上，背部靠在墊子上。", "正手握住手柄或桿，保持手臂伸直。", "保持背部挺直，將肩膀盡可能高地抬向耳朵。", "保持收縮一會兒，然后慢慢將肩膀放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3419', 'exercise', 1, '{"id": "3419", "target": "abs", "name_en": "l-sit on floor", "name_zh": "L形支撑（地板）", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3419-UpWmA5E.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "L形支撐（地板）", "instructions_en": ["Sit on the floor with your legs extended in front of you.", "Place your hands on the floor beside your hips, fingers pointing forward.", "Engage your core and lift your legs off the ground, keeping them straight.", "Try to bring your legs parallel to the floor, forming an ''L'' shape with your body.", "Hold this position for as long as you can.", "Slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在地板上，双腿伸到身前。", "将双手放在臀部旁边的地板上，手指指向前方。", "启动你的核心并将双腿抬离地面，保持伸直。", "尝试使双腿与地面平行，与身体形成“L”形。", "尽可能长时间地保持这个姿势。", "慢慢地将双腿放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["坐在地板上，雙腿伸到身前。", "將雙手放在臀部旁邊的地板上，手指指向前方。", "啟動你的核心并將雙腿抬離地面，保持伸直。", "嘗試使雙腿與地面平行，與身體形成“L”形。", "盡可能長時間地保持這個姿勢。", "慢慢地將雙腿放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0562', 'exercise', 1, '{"id": "0562", "target": "abs", "name_en": "landmine 180", "name_zh": "地雷杆180度转体", "body_part": "waist", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0562-QYysSLV.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "地雷桿180度轉體", "instructions_en": ["Stand with your feet shoulder-width apart and hold the barbell with both hands in front of your chest.", "Bend your knees slightly and rotate your torso to the right, swinging the barbell down towards your right hip.", "As you reach the bottom of the movement, quickly reverse the motion and rotate your torso to the left, swinging the barbell up and across your body towards your left shoulder.", "Continue this twisting motion, alternating sides, for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手握住杠铃于胸前。", "稍微弯曲膝盖并将躯干向右旋转，将杠铃向下朝右臀部摆动。", "当你到达动作的底部时，快速反向运动并向左旋转你的躯干，向上摆动杠铃并穿过你的身体朝向左肩。", "继续这个扭转动作，两侧交替，达到所需的重复次数。"], "secondary_muscles": ["obliques", "quadriceps"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手握住杠鈴于胸前。", "稍微彎曲膝蓋并將軀幹向右旋轉，將杠鈴向下朝右臀部擺動。", "當你到達動作的底部時，快速反向運動并向左旋轉你的軀幹，向上擺動杠鈴并穿過你的身體朝向左肩。", "繼續這個扭轉動作，兩側交替，達到所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3237', 'exercise', 1, '{"id": "3237", "target": "delts", "name_en": "landmine lateral raise", "name_zh": "地雷杆侧平举", "body_part": "shoulders", "equipment": "barbell", "gif_asset": "assets/fitness/videos/3237-eXMFHww.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "地雷桿側平舉", "instructions_en": ["Stand with your feet shoulder-width apart and knees slightly bent.", "Hold the barbell with an overhand grip, resting it on the front of your shoulders.", "Keeping your core engaged and back straight, lift the barbell up and away from your body, raising it to shoulder height.", "Pause for a moment at the top, then slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站立，双脚分开与肩同宽，膝盖稍微弯曲。", "正手握住杠铃，将其放在肩膀前面。", "保持核心收紧并保持背部挺直，将杠铃向上举起并远离身体，将其提升至肩膀高度。", "在顶部停顿片刻，然后慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["traps", "upper back"], "instructions_zh_hant": ["站立，雙腳分開與肩同寬，膝蓋稍微彎曲。", "正手握住杠鈴，將其放在肩膀前面。", "保持核心收緊并保持背部挺直，將杠鈴向上舉起并遠離身體，將其提升至肩膀高度。", "在頂部停頓片刻，然后慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3300', 'exercise', 1, '{"id": "3300", "target": "abs", "name_en": "lean planche", "name_zh": "倾身俄式挺身", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3300-LYJodFS.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "傾身俄式挺身", "instructions_en": ["Start in a push-up position with your hands shoulder-width apart and your body straight.", "Engage your core and slowly shift your weight forward, bringing your shoulders past your hands.", "Keep your elbows slightly bent and your body straight as you lean forward.", "Hold this position for a few seconds, then slowly return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["从俯卧撑位置开始，双手分开与肩同宽，身体伸直。", "启动你的核心，慢慢地将你的重心向前移动，让你的肩膀越过你的手。", "向前倾时，保持肘部稍微弯曲，身体伸直。", "保持这个姿势几秒钟，然后慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "chest", "triceps"], "instructions_zh_hant": ["從俯臥撐位置開始，雙手分開與肩同寬，身體伸直。", "啟動你的核心，慢慢地將你的重心向前移動，讓你的肩膀越過你的手。", "向前傾時，保持肘部稍微彎曲，身體伸直。", "保持這個姿勢幾秒鐘，然后慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2288', 'exercise', 1, '{"id": "2288", "target": "forearms", "name_en": "lever gripper hands", "name_zh": "器械握力器双手", "body_part": "lower arms", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/2288-mKwcrHn.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械握力器雙手", "instructions_en": ["Adjust the seat height and grip the handles of the leverage machine.", "Keep your back straight and your feet flat on the ground.", "Exhale and squeeze the handles, contracting your forearms.", "Hold the contraction for a second, then slowly release and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度并握住杠杆机的手柄。", "保持背部挺直，双脚平放在地面上。", "呼气并挤压手柄，收缩前臂。", "保持收缩一秒钟，然后慢慢释放并返回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "triceps"], "instructions_zh_hant": ["調整座椅高度并握住杠桿機的手柄。", "保持背部挺直，雙腳平放在地面上。", "呼氣并擠壓手柄，收縮前臂。", "保持收縮一秒鐘，然后慢慢釋放并返回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2271', 'exercise', 1, '{"id": "2271", "target": "delts", "name_en": "left hook. boxing", "name_zh": "拳击左勾拳", "body_part": "shoulders", "equipment": "body weight", "gif_asset": "assets/fitness/videos/2271-hoXt6wv.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "拳擊左勾拳", "instructions_en": ["Stand with your feet shoulder-width apart and your knees slightly bent.", "Keep your left hand up to protect your face and your right hand by your chin.", "Rotate your hips and pivot on your left foot as you extend your left arm forward in a punching motion.", "Twist your torso and engage your core muscles to generate power in the punch.", "Snap your arm back to the starting position and repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，膝盖稍微弯曲。", "左手举起以保护脸部，右手握住下巴。", "旋转臀部并以左脚为轴心，同时以出拳动作向前伸展左臂。", "扭转你的躯干并调动你的核心肌肉以产生出拳的力量。", "将手臂拉回到起始位置，然后重复所需的重复次数。"], "secondary_muscles": ["biceps", "triceps", "forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，膝蓋稍微彎曲。", "左手舉起以保護臉部，右手握住下巴。", "旋轉臀部并以左腳為軸心，同時以出拳動作向前伸展左臂。", "扭轉你的軀幹并調動你的核心肌肉以產生出拳的力量。", "將手臂拉回到起始位置，然后重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0570', 'exercise', 1, '{"id": "0570", "target": "abs", "name_en": "leg pull in flat bench", "name_zh": "平凳坐姿收腿", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0570-OyoZ3Pu.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "平凳坐姿收腿", "instructions_en": ["Sit on a flat bench with your legs extended straight out in front of you.", "Place your hands on the bench beside your hips for support.", "Engage your abs and lift your legs off the ground, bringing your knees towards your chest.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在平坦的长凳上，双腿在身前伸直。", "将双手放在臀部旁边的长凳上以获得支撑。", "收紧腹肌，将双腿抬离地面，使膝盖靠近胸部。", "在顶部暂停片刻，然后慢慢将双腿放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors", "lower back"], "instructions_zh_hant": ["坐在平坦的長凳上，雙腿在身前伸直。", "將雙手放在臀部旁邊的長凳上以獲得支撐。", "收緊腹肌，將雙腿抬離地面，使膝蓋靠近胸部。", "在頂部暫停片刻，然后慢慢將雙腿放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1576', 'exercise', 1, '{"id": "1576", "target": "hamstrings", "name_en": "leg up hamstring stretch", "name_zh": "抬腿腘绳肌拉伸", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1576-sU5BrfP.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "抬腿腘繩肌拉伸", "instructions_en": ["Lie flat on your back with your legs extended.", "Bend one knee and bring it towards your chest, holding onto your thigh or shin.", "Straighten your leg as much as possible while keeping it elevated.", "Hold the stretch for 20-30 seconds.", "Repeat with the other leg."], "instructions_zh": ["平躺，双腿伸展。", "弯曲一侧膝盖，将其靠近胸部，握住大腿或小腿。", "尽可能伸直腿，同时保持腿抬高。", "保持拉伸 20-30 秒。", "换另一条腿重复上述步骤。"], "secondary_muscles": ["glutes"], "instructions_zh_hant": ["平躺，雙腿伸展。", "彎曲一側膝蓋，將其靠近胸部，握住大腿或小腿。", "盡可能伸直腿，同時保持腿抬高。", "保持拉伸 20-30 秒。", "換另一條腿重復上述步驟。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2287', 'exercise', 1, '{"id": "2287", "target": "quads", "name_en": "lever alternate leg press", "name_zh": "器械交替腿举", "body_part": "upper legs", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/2287-V07qpXy.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械交替腿舉", "instructions_en": ["Adjust the seat and foot platform of the leverage machine to your desired position.", "Sit on the machine with your back against the backrest and your feet on the foot platform.", "Place your hands on the handles or sides of the machine for stability.", "Push one foot against the foot platform, extending your leg until it is almost fully straight.", "Pause for a moment, then slowly bend your leg and return to the starting position.", "Repeat with the other leg.", "Continue alternating legs for the desired number of repetitions."], "instructions_zh": ["将杠杆机的座椅和脚踏平台调整到您想要的位置。", "坐在机器上，背部靠在靠背上，双脚放在脚踏板上。", "将手放在机器的手柄或侧面以保持稳定性。", "将一只脚推到脚平台上，伸展腿直到几乎完全伸直。", "暂停片刻，然后慢慢弯曲腿，回到起始位置。", "换另一条腿重复上述步骤。", "继续交替双腿达到所需的重复次数。"], "secondary_muscles": ["hamstrings", "glutes"], "instructions_zh_hant": ["將杠桿機的座椅和腳踏平臺調整到您想要的位置。", "坐在機器上，背部靠在靠背上，雙腳放在腳踏板上。", "將手放在機器的手柄或側面以保持穩定性。", "將一只腳推到腳平臺上，伸展腿直到幾乎完全伸直。", "暫停片刻，然后慢慢彎曲腿，回到起始位置。", "換另一條腿重復上述步驟。", "繼續交替雙腿達到所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0571', 'exercise', 1, '{"id": "0571", "target": "upper back", "name_en": "lever alternating narrow grip seated row", "name_zh": "器械交替窄握坐姿划船", "body_part": "back", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0571-w2oRpuH.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械交替窄握坐姿劃船", "instructions_en": ["Adjust the seat height and footplate position to ensure proper alignment.", "Sit on the machine with your back straight and feet flat on the footplate.", "Grasp the handles with a narrow grip, palms facing each other.", "Keep your chest up and shoulders back throughout the exercise.", "Pull one handle towards your torso while keeping the other handle stationary.", "Squeeze your shoulder blades together at the end of the movement.", "Slowly return the handle to the starting position and repeat with the other side.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["调整座椅高度和踏板位置以确保正确对齐。", "坐在机器上，背部挺直，双脚平放在踏板上。", "紧紧握住手柄，手掌相对。", "在整个练习过程中保持挺胸、肩膀向后。", "将一个手柄拉向您的躯干，同时保持另一个手柄静止。", "在动作结束时将肩胛骨挤压在一起。", "慢慢地将手柄返回到起始位置，并在另一侧重复此操作。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["調整座椅高度和踏板位置以確保正確對齊。", "坐在機器上，背部挺直，雙腳平放在踏板上。", "緊緊握住手柄，手掌相對。", "在整個練習過程中保持挺胸、肩膀向后。", "將一個手柄拉向您的軀幹，同時保持另一個手柄靜止。", "在動作結束時將肩胛骨擠壓在一起。", "慢慢地將手柄返回到起始位置，并在另一側重復此操作。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0572', 'exercise', 1, '{"id": "0572", "target": "lats", "name_en": "lever assisted chin-up", "name_zh": "器械辅助反握引体向上", "body_part": "back", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0572-MaMuGH6.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械輔助反握引體向上", "instructions_en": ["Adjust the leverage machine to your desired resistance level.", "Stand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart.", "Hang with your arms fully extended, keeping your body straight.", "Engage your back muscles and pull your body up towards the handles, leading with your chest.", "Continue pulling until your chin is above the handles.", "Pause for a moment at the top, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将杠杆机调整至您想要的阻力水平。", "站在脚踏板上，正手握住手柄，握距略宽于肩宽。", "双臂完全伸展，保持身体挺直。", "收紧背部肌肉，将身体拉向手柄，以胸部为主导。", "继续拉，直到下巴位于手柄上方。", "在顶部停顿片刻，然后慢慢将身体放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["將杠桿機調整至您想要的阻力水平。", "站在腳踏板上，正手握住手柄，握距略寬于肩寬。", "雙臂完全伸展，保持身體挺直。", "收緊背部肌肉，將身體拉向手柄，以胸部為主導。", "繼續拉，直到下巴位于手柄上方。", "在頂部停頓片刻，然后慢慢將身體放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0573', 'exercise', 1, '{"id": "0573", "target": "spine", "name_en": "lever back extension", "name_zh": "器械背伸展", "body_part": "back", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0573-rUXfn3R.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械背伸展", "instructions_en": ["Adjust the machine to fit your body size and range of motion.", "Sit on the machine with your back against the pad and your feet secured.", "Place your hands on the handles or grip bars.", "Engage your core and slowly lean forward, allowing your back to round slightly.", "Pause for a moment at the bottom position, feeling a stretch in your lower back.", "Using your back muscles, slowly raise your torso back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整机器以适合您的身体尺寸和运动范围。", "坐在机器上，背部靠在垫子上，双脚固定。", "将手放在手柄或握杆上。", "启动你的核心并慢慢向前倾斜，让你的背部稍微弯曲。", "在底部位置暂停片刻，感觉下背部有拉伸感。", "使用背部肌肉，慢慢将躯干抬回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings"], "instructions_zh_hant": ["調整機器以適合您的身體尺寸和運動范圍。", "坐在機器上，背部靠在墊子上，雙腳固定。", "將手放在手柄或握桿上。", "啟動你的核心并慢慢向前傾斜，讓你的背部稍微彎曲。", "在底部位置暫停片刻，感覺下背部有拉伸感。", "使用背部肌肉，慢慢將軀幹抬回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0574', 'exercise', 1, '{"id": "0574", "target": "upper back", "name_en": "lever bent over row", "name_zh": "器械俯身划船", "body_part": "back", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0574-X3cqyXz.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械俯身劃船", "instructions_en": ["Stand with your feet shoulder-width apart and knees slightly bent.", "Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.", "Bend forward at the hips, keeping your back straight and chest up.", "Pull the barbell towards your lower chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站立，双脚分开与肩同宽，膝盖稍微弯曲。", "正手握住杠铃，双手分开略宽于肩宽。", "臀部向前弯曲，保持背部挺直，挺胸。", "将杠铃拉向下胸部，将肩胛骨挤压在一起。", "在顶部停顿片刻，然后慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["站立，雙腳分開與肩同寬，膝蓋稍微彎曲。", "正手握住杠鈴，雙手分開略寬于肩寬。", "臀部向前彎曲，保持背部挺直，挺胸。", "將杠鈴拉向下胸部，將肩胛骨擠壓在一起。", "在頂部停頓片刻，然后慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3200', 'exercise', 1, '{"id": "3200", "target": "upper back", "name_en": "lever bent-over row with v-bar", "name_zh": "器械俯身划船配合V形把手", "body_part": "back", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/3200-LuBEORI.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械俯身劃船配合V形把手", "instructions_en": ["Adjust the seat height and position yourself facing the machine.", "Grasp the v-bar with an overhand grip, keeping your back straight and your knees slightly bent.", "Pull the v-bar towards your abdomen, squeezing your shoulder blades together.", "Pause for a moment at the top of the movement, then slowly release the weight back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度并将自己面向机器。", "正手握住 V 形杆，保持背部挺直，膝盖稍微弯曲。", "将 V 形杆拉向腹部，将肩胛骨挤压在一起。", "在动作的最高点暂停片刻，然后慢慢释放重量回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["調整座椅高度并將自己面向機器。", "正手握住 V 形桿，保持背部挺直，膝蓋稍微彎曲。", "將 V 形桿拉向腹部，將肩胛骨擠壓在一起。", "在動作的最高點暫停片刻，然后慢慢釋放重量回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0575', 'exercise', 1, '{"id": "0575", "target": "biceps", "name_en": "lever bicep curl", "name_zh": "器械二头弯举", "body_part": "upper arms", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0575-q6y3OhV.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械二頭彎舉", "instructions_en": ["Adjust the seat height and position yourself on the machine with your back against the pad.", "Grasp the handles with an underhand grip, palms facing up, and keep your elbows close to your sides.", "Exhale and curl the handles upward, contracting your biceps.", "Pause for a moment at the top of the movement, squeezing your biceps.", "Inhale and slowly lower the handles back to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度并将自己放在机器上，背部靠在垫子上。", "反手握住手柄，手掌朝上，肘部靠近身体两侧。", "呼气并向上弯曲手柄，收缩二头肌。", "在动作的最高点暂停片刻，挤压你的二头肌。", "吸气，慢慢将手柄放回起始位置，充分伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["調整座椅高度并將自己放在機器上，背部靠在墊子上。", "反手握住手柄，手掌朝上，肘部靠近身體兩側。", "呼氣并向上彎曲手柄，收縮二頭肌。", "在動作的最高點暫停片刻，擠壓你的二頭肌。", "吸氣，慢慢將手柄放回起始位置，充分伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2289', 'exercise', 1, '{"id": "2289", "target": "calves", "name_en": "lever calf press", "name_zh": "器械小腿推举", "body_part": "lower legs", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/2289-7B4F5nZ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械小腿推舉", "instructions_en": ["Adjust the seat of the leverage machine so that your shoulders are aligned with the lever pad.", "Place your toes on the lever pad, with your heels hanging off the edge.", "Grasp the handles or side supports for stability.", "Push the lever pad down by extending your ankles, contracting your calf muscles.", "Pause for a moment at the bottom of the movement.", "Slowly return to the starting position by allowing your heels to rise back up.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整杠杆机的座椅，使肩膀与杠杆垫对齐。", "将脚趾放在杠杆垫上，脚跟悬在边缘上。", "抓住手柄或侧面支撑以保持稳定性。", "伸展脚踝，收缩小腿肌肉，将杠杆垫向下推。", "在动作的底部停顿片刻。", "让脚后跟重新抬起，慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings"], "instructions_zh_hant": ["調整杠桿機的座椅，使肩膀與杠桿墊對齊。", "將腳趾放在杠桿墊上，腳跟懸在邊緣上。", "抓住手柄或側面支撐以保持穩定性。", "伸展腳踝，收縮小腿肌肉，將杠桿墊向下推。", "在動作的底部停頓片刻。", "讓腳后跟重新抬起，慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0576', 'exercise', 1, '{"id": "0576", "target": "pectorals", "name_en": "lever chest press", "name_zh": "器械推胸", "body_part": "chest", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0576-DOoWcnA.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械推胸", "instructions_en": ["Adjust the seat height and position yourself on the machine with your back flat against the pad.", "Grasp the handles with an overhand grip and position your elbows at a 90-degree angle.", "Push the handles forward until your arms are fully extended, exhaling during the movement.", "Pause briefly at the end of the movement, then slowly return to the starting position, inhaling as you do so.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度，将自己放在机器上，背部平放在垫子上。", "正手握住手柄，肘部呈 90 度角。", "向前推动手柄，直到手臂完全伸展，运动过程中呼气。", "动作结束时短暂暂停，然后慢慢回到起始位置，同时吸气。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["調整座椅高度，將自己放在機器上，背部平放在墊子上。", "正手握住手柄，肘部呈 90 度角。", "向前推動手柄，直到手臂完全伸展，運動過程中呼氣。", "動作結束時短暫暫停，然后慢慢回到起始位置，同時吸氣。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0578', 'exercise', 1, '{"id": "0578", "target": "glutes", "name_en": "lever deadlift", "name_zh": "器械硬拉", "body_part": "upper legs", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0578-GUT8I22.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械硬拉", "instructions_en": ["Adjust the seat height and foot platform to your desired position.", "Sit on the machine with your back against the pad and your feet flat on the foot platform.", "Grasp the handles or the sides of the seat for stability.", "Engage your glutes and hamstrings, and push through your heels to lift the weight up.", "Keep your back straight and avoid rounding your shoulders.", "Extend your hips fully at the top of the movement, squeezing your glutes.", "Lower the weight back down in a controlled manner, keeping tension on your glutes and hamstrings.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将座椅高度和脚踏板调整到您想要的位置。", "坐在机器上，背部靠在垫子上，双脚平放在脚踏板上。", "抓住把手或座椅侧面以保持稳定性。", "收紧臀肌和腿筋，并通过脚后跟推动举重。", "保持背部挺直，避免圆肩。", "在动作的最高点完全伸展臀部，挤压臀部。", "以受控的方式降低重量，保持臀肌和腿筋的张力。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "quadriceps"], "instructions_zh_hant": ["將座椅高度和腳踏板調整到您想要的位置。", "坐在機器上，背部靠在墊子上，雙腳平放在腳踏板上。", "抓住把手或座椅側面以保持穩定性。", "收緊臀肌和腿筋，并通過腳后跟推動舉重。", "保持背部挺直，避免圓肩。", "在動作的最高點完全伸展臀部，擠壓臀部。", "以受控的方式降低重量，保持臀肌和腿筋的張力。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1300', 'exercise', 1, '{"id": "1300", "target": "pectorals", "name_en": "lever decline chest press", "name_zh": "器械下斜推胸", "body_part": "chest", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/1300-vsVoPHt.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械下斜推胸", "instructions_en": ["Adjust the seat height and backrest of the leverage machine to a comfortable position.", "Sit on the machine with your back against the backrest and your feet flat on the floor.", "Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.", "Push the handles forward and away from your body until your arms are fully extended.", "Slowly lower the handles back towards your chest, keeping your elbows slightly bent.", "Pause for a moment at the bottom, then push the handles back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将杠杆机的座椅高度和靠背调整到舒适的位置。", "坐在机器上，背部靠在靠背上，双脚平放在地板上。", "正手握住手柄，双手之间的距离略大于肩宽。", "向前推动手柄并使其远离身体，直到双臂完全伸展。", "慢慢地将手柄放回胸部，保持肘部稍微弯曲。", "在底部暂停片刻，然后将手柄推回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["將杠桿機的座椅高度和靠背調整到舒適的位置。", "坐在機器上，背部靠在靠背上，雙腳平放在地板上。", "正手握住手柄，雙手之間的距離略大于肩寬。", "向前推動手柄并使其遠離身體，直到雙臂完全伸展。", "慢慢地將手柄放回胸部，保持肘部稍微彎曲。", "在底部暫停片刻，然后將手柄推回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1615', 'exercise', 1, '{"id": "1615", "target": "biceps", "name_en": "lever hammer grip preacher curl", "name_zh": "器械锤式握牧师凳弯举", "body_part": "upper arms", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/1615-OAguZoG.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械錘式握牧師凳彎舉", "instructions_en": ["Adjust the seat height and position yourself on the leverage machine.", "Place your upper arms on the preacher pad, ensuring your chest is pressed against it.", "Grasp the handles with a hammer grip (palms facing each other).", "Keeping your upper arms stationary, exhale and curl the handles towards your shoulders.", "Pause for a moment at the top, squeezing your biceps.", "Inhale and slowly lower the handles back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度并将自己放在杠杆机上。", "将你的上臂放在讲道垫上，确保你的胸部压在上面。", "用锤子握把抓住手柄（手掌相对）。", "保持上臂静止，呼气并将手柄卷向肩膀。", "在顶部暂停片刻，挤压你的二头肌。", "吸气并慢慢将手柄放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["調整座椅高度并將自己放在杠桿機上。", "將你的上臂放在講道墊上，確保你的胸部壓在上面。", "用錘子握把抓住手柄（手掌相對）。", "保持上臂靜止，呼氣并將手柄卷向肩膀。", "在頂部暫停片刻，擠壓你的二頭肌。", "吸氣并慢慢將手柄放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1253', 'exercise', 1, '{"id": "1253", "target": "calves", "name_en": "lever donkey calf raise", "name_zh": "器械驴式提踵", "body_part": "lower legs", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/1253-C9LuR4A.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械驢式提踵", "instructions_en": ["Adjust the leverage machine to the appropriate height for your body.", "Position yourself facing the machine, with your toes on the foot platform and your heels hanging off the edge.", "Place your hands on the handles or the support bars for stability.", "Engage your calves and lift your heels as high as possible, using the balls of your feet.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将杠杆机调节至适合您身体的高度。", "面向机器定位，脚趾放在脚踏平台上，脚后跟悬在边缘。", "将手放在手柄或支撑杆上以保持稳定性。", "用脚掌收紧小腿并尽可能高地抬起脚后跟。", "在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "glutes"], "instructions_zh_hant": ["將杠桿機調節至適合您身體的高度。", "面向機器定位，腳趾放在腳踏平臺上，腳后跟懸在邊緣。", "將手放在手柄或支撐桿上以保持穩定性。", "用腳掌收緊小腿并盡可能高地抬起腳后跟。", "在頂部停頓片刻，然后慢慢降低腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0579', 'exercise', 1, '{"id": "0579", "target": "lats", "name_en": "lever front pulldown", "name_zh": "器械前下拉", "body_part": "back", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0579-7F1DVzn.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械前下拉", "instructions_en": ["Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.", "Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.", "Sit upright with your chest lifted and your shoulders back, maintaining a slight arch in your lower back.", "Engage your lats and pull the handles down towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度，将自己放在机器上，膝盖位于垫子下方，双脚平放在地面上。", "正手握住手柄，握距略宽于肩宽。", "坐直，胸部抬起，肩膀向后，保持下背部轻微的拱形。", "收紧背阔肌，将手柄向下拉向胸部，将肩胛骨挤压在一起。", "在动作底部暂停片刻，然后慢慢松开手柄回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "rhomboids", "rear deltoids"], "instructions_zh_hant": ["調整座椅高度，將自己放在機器上，膝蓋位于墊子下方，雙腳平放在地面上。", "正手握住手柄，握距略寬于肩寬。", "坐直，胸部抬起，肩膀向后，保持下背部輕微的拱形。", "收緊背闊肌，將手柄向下拉向胸部，將肩胛骨擠壓在一起。", "在動作底部暫停片刻，然后慢慢松開手柄回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0580', 'exercise', 1, '{"id": "0580", "target": "traps", "name_en": "lever gripless shrug", "name_zh": "器械免握耸肩", "body_part": "back", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0580-f91FwXG.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械免握聳肩", "instructions_en": ["Adjust the seat height and position yourself on the leverage machine.", "Grasp the handles with your palms facing inwards and your arms fully extended.", "Keeping your back straight, exhale and elevate your shoulders as high as possible.", "Hold the contraction for a brief moment, then inhale and slowly lower your shoulders back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度并将自己放在杠杆机上。", "手掌朝内，抓住手柄，双臂完全伸展。", "保持背部挺直，呼气并尽可能抬高肩膀。", "保持收缩一会儿，然后吸气并慢慢将肩膀放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "forearms"], "instructions_zh_hant": ["調整座椅高度并將自己放在杠桿機上。", "手掌朝內，抓住手柄，雙臂完全伸展。", "保持背部挺直，呼氣并盡可能抬高肩膀。", "保持收縮一會兒，然后吸氣并慢慢將肩膀放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0581', 'exercise', 1, '{"id": "0581", "target": "upper back", "name_en": "lever high row", "name_zh": "器械高位划船", "body_part": "back", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0581-nZZZy9m.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械高位劃船", "instructions_en": ["Adjust the seat height and foot platform to a comfortable position.", "Sit on the machine with your chest against the pad and your feet flat on the foot platform.", "Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.", "Keep your back straight and engage your core.", "Pull the handles towards your body, squeezing your shoulder blades together.", "Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将座椅高度和脚踏板调整至舒适的位置。", "坐在机器上，胸部靠在垫子上，双脚平放在脚踏平台上。", "正手握住手柄，握距略宽于肩宽。", "保持背部挺直并启动核心肌群。", "将手柄拉向身体，将肩胛骨挤压在一起。", "在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "rear deltoids"], "instructions_zh_hant": ["將座椅高度和腳踏板調整至舒適的位置。", "坐在機器上，胸部靠在墊子上，雙腳平放在腳踏平臺上。", "正手握住手柄，握距略寬于肩寬。", "保持背部挺直并啟動核心肌群。", "將手柄拉向身體，將肩胛骨擠壓在一起。", "在動作的最高點暫停片刻，然后慢慢松開手柄回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2286', 'exercise', 1, '{"id": "2286", "target": "glutes", "name_en": "lever hip extension v. 2", "name_zh": "器械髋伸展变式2", "body_part": "upper legs", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/2286-OPqShYN.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械髖伸展變式2", "instructions_en": ["Adjust the machine to fit your body and sit on it with your back against the backrest.", "Place your feet on the footrests and grip the handles for stability.", "Engage your glutes and hamstrings, then push against the footrests to extend your hips and raise your legs backward.", "Pause for a moment at the top, then slowly lower your legs back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整机器以适合您的身体，然后坐在机器上，背部靠在靠背上。", "将脚放在脚踏板上并握住手柄以保持稳定。", "启动臀肌和腿筋，然后推动脚踏板以伸展臀部并向后抬起双腿。", "在顶部暂停片刻，然后慢慢将双腿放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings"], "instructions_zh_hant": ["調整機器以適合您的身體，然后坐在機器上，背部靠在靠背上。", "將腳放在腳踏板上并握住手柄以保持穩定。", "啟動臀肌和腿筋，然后推動腳踏板以伸展臀部并向后抬起雙腿。", "在頂部暫停片刻，然后慢慢將雙腿放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2611', 'exercise', 1, '{"id": "2611", "target": "glutes", "name_en": "lever horizontal one leg press", "name_zh": "器械水平单腿推举", "body_part": "upper legs", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/2611-9KU9TYF.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械水平單腿推舉", "instructions_en": ["Adjust the seat of the machine so that your knees are at a 90-degree angle when your feet are on the footplate.", "Sit on the machine with your back against the backrest and your feet shoulder-width apart on the footplate.", "Place your hands on the handles or sides of the machine for stability.", "Push the footplate away from your body by extending your leg, keeping your back against the backrest.", "Pause for a moment at the fully extended position, then slowly bend your leg to return to the starting position.", "Repeat for the desired number of repetitions, then switch legs."], "instructions_zh": ["调整机器座椅，使双脚放在踏板上时膝盖呈 90 度角。", "坐在机器上，背部靠在靠背上，双脚与肩同宽放在踏板上。", "将手放在机器的手柄或侧面以保持稳定性。", "伸展腿，使背部紧靠靠背，将踏板推离身体。", "在完全伸展位置暂停片刻，然后慢慢弯曲腿回到起始位置。", "重复所需的重复次数，然后换腿。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["調整機器座椅，使雙腳放在踏板上時膝蓋呈 90 度角。", "坐在機器上，背部靠在靠背上，雙腳與肩同寬放在踏板上。", "將手放在機器的手柄或側面以保持穩定性。", "伸展腿，使背部緊靠靠背，將踏板推離身體。", "在完全伸展位置暫停片刻，然后慢慢彎曲腿回到起始位置。", "重復所需的重復次數，然后換腿。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1299', 'exercise', 1, '{"id": "1299", "target": "pectorals", "name_en": "lever incline chest press", "name_zh": "器械上斜推胸", "body_part": "chest", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/1299-jHAnWmT.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械上斜推胸", "instructions_en": ["Adjust the seat and backrest of the leverage machine to a comfortable position.", "Sit on the machine with your back against the backrest and your feet flat on the floor.", "Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.", "Push the handles forward and away from your body until your arms are fully extended.", "Pause for a moment, then slowly bend your elbows and lower the handles back towards your chest.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将杠杆机的座椅和靠背调整到舒适的位置。", "坐在机器上，背部靠在靠背上，双脚平放在地板上。", "正手握住手柄，双手之间的距离略大于肩宽。", "向前推动手柄并使其远离身体，直到双臂完全伸展。", "暂停片刻，然后慢慢弯曲肘部，将手柄放回到胸部。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["將杠桿機的座椅和靠背調整到舒適的位置。", "坐在機器上，背部靠在靠背上，雙腳平放在地板上。", "正手握住手柄，雙手之間的距離略大于肩寬。", "向前推動手柄并使其遠離身體，直到雙臂完全伸展。", "暫停片刻，然后慢慢彎曲肘部，將手柄放回到胸部。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1479', 'exercise', 1, '{"id": "1479", "target": "pectorals", "name_en": "lever incline chest press v. 2", "name_zh": "器械上斜推胸变式2", "body_part": "chest", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/1479-o17Jfkt.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械上斜推胸變式2", "instructions_en": ["Adjust the seat height and backrest angle on the leverage machine to a comfortable position.", "Sit on the machine with your back against the backrest and your feet flat on the floor.", "Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.", "Push the handles forward and away from your body until your arms are fully extended, but without locking your elbows.", "Pause for a moment at the fully extended position, then slowly bend your elbows and lower the handles back towards your chest.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将杠杆机上的座椅高度和靠背角度调整到舒适的位置。", "坐在机器上，背部靠在靠背上，双脚平放在地板上。", "正手握住手柄，双手之间的距离略大于肩宽。", "向前推动手柄并远离身体，直到手臂完全伸展，但不要锁定肘部。", "在完全伸展的位置暂停片刻，然后慢慢弯曲肘部并将手柄放回胸部。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["將杠桿機上的座椅高度和靠背角度調整到舒適的位置。", "坐在機器上，背部靠在靠背上，雙腳平放在地板上。", "正手握住手柄，雙手之間的距離略大于肩寬。", "向前推動手柄并遠離身體，直到手臂完全伸展，但不要鎖定肘部。", "在完全伸展的位置暫停片刻，然后慢慢彎曲肘部并將手柄放回胸部。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0582', 'exercise', 1, '{"id": "0582", "target": "hamstrings", "name_en": "lever kneeling leg curl", "name_zh": "器械跪姿腿弯举", "body_part": "upper legs", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0582-nnmCTLN.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械跪姿腿彎舉", "instructions_en": ["Adjust the machine to fit your body and select the desired weight.", "Kneel on the machine facing downwards, with your knees resting on the pad and your feet secured under the footpads.", "Grasp the handles or the sides of the machine for stability.", "Keeping your upper body stationary, exhale and curl your legs up towards your glutes by flexing your knees.", "Pause for a moment at the top of the movement, squeezing your hamstrings.", "Inhale and slowly lower your legs back to the starting position, fully extending your knees.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整机器以适合您的身体并选择所需的重量。", "面朝下跪在机器上，膝盖放在垫子上，双脚固定在脚垫下。", "抓住机器的手柄或侧面以保持稳定性。", "保持上半身静止，呼气，弯曲膝盖，将双腿向臀肌方向卷起。", "在动作的最高点暂停片刻，挤压你的腿筋。", "吸气，慢慢将双腿放回起始位置，充分伸展膝盖。", "重复所需的重复次数。"], "secondary_muscles": ["glutes"], "instructions_zh_hant": ["調整機器以適合您的身體并選擇所需的重量。", "面朝下跪在機器上，膝蓋放在墊子上，雙腳固定在腳墊下。", "抓住機器的手柄或側面以保持穩定性。", "保持上半身靜止，呼氣，彎曲膝蓋，將雙腿向臀肌方向卷起。", "在動作的最高點暫停片刻，擠壓你的腿筋。", "吸氣，慢慢將雙腿放回起始位置，充分伸展膝蓋。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0583', 'exercise', 1, '{"id": "0583", "target": "abs", "name_en": "lever kneeling twist", "name_zh": "器械跪姿转体", "body_part": "waist", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0583-sZOR9EV.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械跪姿轉體", "instructions_en": ["Adjust the seat height and position yourself on the machine with your knees resting on the pads and your upper body facing forward.", "Grasp the handles or the sides of the machine for stability.", "Keeping your core engaged, twist your torso to one side as far as comfortably possible.", "Pause for a moment, then slowly return to the starting position.", "Repeat the twist to the opposite side.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["调整座椅高度，将自己放在机器上，膝盖放在垫子上，上半身朝前。", "抓住机器的手柄或侧面以保持稳定性。", "保持核心参与，将躯干尽可能舒适地向一侧扭转。", "暂停片刻，然后慢慢回到起始位置。", "向另一侧重复扭转。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["obliques", "lower back"], "instructions_zh_hant": ["調整座椅高度，將自己放在機器上，膝蓋放在墊子上，上半身朝前。", "抓住機器的手柄或側面以保持穩定性。", "保持核心參與，將軀幹盡可能舒適地向一側扭轉。", "暫停片刻，然后慢慢回到起始位置。", "向另一側重復扭轉。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0584', 'exercise', 1, '{"id": "0584", "target": "delts", "name_en": "lever lateral raise", "name_zh": "器械侧平举", "body_part": "shoulders", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0584-dRTfGZT.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械側平舉", "instructions_en": ["Adjust the seat height and position yourself on the machine with your back against the pad.", "Grasp the handles with an overhand grip and keep your arms straight.", "Exhale and raise your arms out to the sides until they are parallel to the floor.", "Pause for a moment at the top, then inhale and slowly lower your arms back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度并将自己放在机器上，背部靠在垫子上。", "正手握住手柄并保持手臂伸直。", "呼气并将手臂向两侧抬起，直到与地板平行。", "在顶部停顿片刻，然后吸气，慢慢将手臂放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["traps", "upper back"], "instructions_zh_hant": ["調整座椅高度并將自己放在機器上，背部靠在墊子上。", "正手握住手柄并保持手臂伸直。", "呼氣并將手臂向兩側抬起，直到與地板平行。", "在頂部停頓片刻，然后吸氣，慢慢將手臂放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1403', 'exercise', 1, '{"id": "1403", "target": "levator scapulae", "name_en": "neck side stretch", "name_zh": "颈部侧拉伸", "body_part": "neck", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1403-x2chWLO.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "頸部側拉伸", "instructions_en": ["Stand or sit up straight with your shoulders relaxed.", "Tilt your head to one side, bringing your ear towards your shoulder.", "Hold the stretch for 15-30 seconds.", "Repeat on the other side.", "Perform 2-4 sets on each side."], "instructions_zh": ["站直或坐直，肩膀放松。", "将头向一侧倾斜，将耳朵靠近肩膀。", "保持拉伸 15-30 秒。", "在另一侧重复。", "每侧进行 2-4 组。"], "secondary_muscles": ["trapezius", "sternocleidomastoid"], "instructions_zh_hant": ["站直或坐直，肩膀放松。", "將頭向一側傾斜，將耳朵靠近肩膀。", "保持拉伸 15-30 秒。", "在另一側重復。", "每側進行 2-4 組。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0586', 'exercise', 1, '{"id": "0586", "target": "hamstrings", "name_en": "lever lying leg curl", "name_zh": "器械卧姿腿弯举", "body_part": "upper legs", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0586-17lJ1kr.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械臥姿腿彎舉", "instructions_en": ["Adjust the machine to fit your body and select the desired weight.", "Lie face down on the machine with your legs straight and your heels against the padded lever.", "Grasp the handles or the sides of the machine for stability.", "Keeping your upper body stationary, exhale and curl your legs up as far as possible without lifting your hips off the pad.", "Hold the contracted position for a brief pause as you squeeze your hamstrings.", "Inhale and slowly lower the lever back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整机器以适合您的身体并选择所需的重量。", "面朝下躺在机器上，双腿伸直，脚跟靠在带衬垫的杠杆上。", "抓住机器的手柄或侧面以保持稳定性。", "保持上半身静止，呼气并尽可能向上弯曲双腿，但不要将臀部抬离垫子。", "挤压腿筋时，保持收缩位置短暂停顿。", "吸气并缓慢地将控制杆降低回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["calves"], "instructions_zh_hant": ["調整機器以適合您的身體并選擇所需的重量。", "面朝下躺在機器上，雙腿伸直，腳跟靠在帶襯墊的杠桿上。", "抓住機器的手柄或側面以保持穩定性。", "保持上半身靜止，呼氣并盡可能向上彎曲雙腿，但不要將臀部抬離墊子。", "擠壓腿筋時，保持收縮位置短暫停頓。", "吸氣并緩慢地將控制桿降低回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3195', 'exercise', 1, '{"id": "3195", "target": "hamstrings", "name_en": "lever lying two-one leg curl", "name_zh": "器械卧姿双起单落腿弯举", "body_part": "upper legs", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/3195-UXpKJoq.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械臥姿雙起單落腿彎舉", "instructions_en": ["Adjust the machine to fit your body and sit on it with your back against the backrest.", "Place your legs on the lever pad, just above your ankles.", "Grasp the handles on the sides of the machine for support.", "Keeping your upper body still, exhale and curl your legs up towards your glutes.", "Pause for a moment at the top, then inhale and slowly lower your legs back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整机器以适合您的身体，然后坐在机器上，背部靠在靠背上。", "将双腿放在脚踝上方的杠杆垫上。", "抓住机器两侧的手柄以提供支撑。", "保持上半身不动，呼气并将双腿向上弯曲至臀部。", "在顶部停顿片刻，然后吸气，慢慢降低双腿回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes"], "instructions_zh_hant": ["調整機器以適合您的身體，然后坐在機器上，背部靠在靠背上。", "將雙腿放在腳踝上方的杠桿墊上。", "抓住機器兩側的手柄以提供支撐。", "保持上半身不動，呼氣并將雙腿向上彎曲至臀部。", "在頂部停頓片刻，然后吸氣，慢慢降低雙腿回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0587', 'exercise', 1, '{"id": "0587", "target": "delts", "name_en": "lever military press", "name_zh": "器械肩上推举", "body_part": "shoulders", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0587-CggQhII.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械肩上推舉", "instructions_en": ["Adjust the seat height and position yourself on the machine with your back against the backrest.", "Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.", "Push the handles upward until your arms are fully extended, but do not lock your elbows.", "Pause for a moment at the top, then slowly lower the handles back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度并将自己放在机器上，背部靠在靠背上。", "正手握住手柄，双手之间的距离略大于肩宽。", "向上推动手柄，直到手臂完全伸展，但不要锁住肘部。", "在顶部暂停片刻，然后慢慢将手柄放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "upper chest"], "instructions_zh_hant": ["調整座椅高度并將自己放在機器上，背部靠在靠背上。", "正手握住手柄，雙手之間的距離略大于肩寬。", "向上推動手柄，直到手臂完全伸展，但不要鎖住肘部。", "在頂部暫停片刻，然后慢慢將手柄放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0588', 'exercise', 1, '{"id": "0588", "target": "upper back", "name_en": "lever narrow grip seated row", "name_zh": "器械窄握坐姿划船", "body_part": "back", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0588-IGjKj1v.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械窄握坐姿劃船", "instructions_en": ["Adjust the seat height and footrests to ensure proper form.", "Sit on the machine with your feet flat on the footrests and your knees slightly bent.", "Grasp the handles with a narrow grip, palms facing each other.", "Keep your back straight and lean slightly forward.", "Pull the handles towards your torso, squeezing your shoulder blades together.", "Pause for a moment at the peak of the movement.", "Slowly release the handles and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度和脚踏板以确保形状正确。", "坐在机器上，双脚平放在脚踏板上，膝盖稍微弯曲。", "紧紧握住手柄，手掌相对。", "保持背部挺直并稍微向前倾斜。", "将手柄拉向躯干，将肩胛骨挤压在一起。", "在动作的最高点停顿片刻。", "慢慢松开手柄并返回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["調整座椅高度和腳踏板以確保形狀正確。", "坐在機器上，雙腳平放在腳踏板上，膝蓋稍微彎曲。", "緊緊握住手柄，手掌相對。", "保持背部挺直并稍微向前傾斜。", "將手柄拉向軀幹，將肩胛骨擠壓在一起。", "在動作的最高點停頓片刻。", "慢慢松開手柄并返回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0589', 'exercise', 1, '{"id": "0589", "target": "upper back", "name_en": "lever one arm bent over row", "name_zh": "器械单臂俯身划船", "body_part": "back", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0589-Fhdtwf3.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械單臂俯身劃船", "instructions_en": ["Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with an overhand grip.", "Bend forward at the hips, keeping your back straight and your head up.", "Let the barbell hang in front of you with your arms fully extended.", "Pull the barbell up towards your chest, keeping your elbows close to your body.", "Squeeze your shoulder blades together at the top of the movement.", "Lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，膝盖稍微弯曲，正手握住杠铃。", "臀部向前弯曲，保持背部挺直，头部抬起。", "让杠铃悬挂在你面前，双臂完全伸展。", "将杠铃拉向胸部，保持肘部靠近身体。", "在动作的最高点将肩胛骨挤压在一起。", "将杠铃降低回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，膝蓋稍微彎曲，正手握住杠鈴。", "臀部向前彎曲，保持背部挺直，頭部抬起。", "讓杠鈴懸掛在你面前，雙臂完全伸展。", "將杠鈴拉向胸部，保持肘部靠近身體。", "在動作的最高點將肩胛骨擠壓在一起。", "將杠鈴降低回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1356', 'exercise', 1, '{"id": "1356", "target": "upper back", "name_en": "lever one arm lateral high row", "name_zh": "器械单臂侧向高位划船", "body_part": "back", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/1356-OIFMAp1.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械單臂側向高位劃船", "instructions_en": ["Adjust the seat height and position yourself facing the machine.", "Grasp the handle with one hand and keep your back straight.", "Pull the handle towards your body, keeping your elbow close to your side.", "Squeeze your back muscles at the top of the movement.", "Slowly release the handle back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度并将自己面向机器。", "用一只手抓住手柄并保持背部挺直。", "将手柄拉向身体，保持肘部靠近身体两侧。", "在动作的最高点挤压背部肌肉。", "慢慢松开手柄回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "shoulders"], "instructions_zh_hant": ["調整座椅高度并將自己面向機器。", "用一只手抓住手柄并保持背部挺直。", "將手柄拉向身體，保持肘部靠近身體兩側。", "在動作的最高點擠壓背部肌肉。", "慢慢松開手柄回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1347', 'exercise', 1, '{"id": "1347", "target": "lats", "name_en": "lever one arm lateral wide pulldown", "name_zh": "器械单臂侧向宽距下拉", "body_part": "back", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/1347-tTuZSDT.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械單臂側向寬距下拉", "instructions_en": ["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.", "Grasp the handle with an overhand grip and fully extend your arm, keeping a slight bend in your elbow.", "Pull the handle down and across your body towards your opposite hip, squeezing your lat muscle at the bottom of the movement.", "Slowly return the handle to the starting position, fully extending your arm.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["调整座椅高度，将自己放在机器上，胸部靠在垫子上，双脚平放在地板上。", "正手握住手柄，完全伸展手臂，保持肘部轻微弯曲。", "将手柄向下拉，穿过身体向对面的臀部方向拉，在动作底部挤压背阔肌。", "慢慢地将手柄返回到起始位置，完全伸展手臂。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["biceps", "rhomboids", "rear deltoids"], "instructions_zh_hant": ["調整座椅高度，將自己放在機器上，胸部靠在墊子上，雙腳平放在地板上。", "正手握住手柄，完全伸展手臂，保持肘部輕微彎曲。", "將手柄向下拉，穿過身體向對面的臀部方向拉，在動作底部擠壓背闊肌。", "慢慢地將手柄返回到起始位置，完全伸展手臂。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0590', 'exercise', 1, '{"id": "0590", "target": "delts", "name_en": "lever one arm shoulder press", "name_zh": "器械单臂肩上推举", "body_part": "shoulders", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0590-2KGnL6M.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械單臂肩上推舉", "instructions_en": ["Adjust the seat height and position yourself on the machine with your back against the pad.", "Grasp the lever handle with one hand and position your elbow at a 90-degree angle.", "Press the lever upward until your arm is fully extended overhead.", "Pause for a moment at the top, then slowly lower the lever back down to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."], "instructions_zh": ["调整座椅高度并将自己放在机器上，背部靠在垫子上。", "用一只手抓住杠杆手柄，并将肘部置于 90 度角。", "向上按下控制杆，直到手臂完全伸过头顶。", "在顶部暂停片刻，然后慢慢将控制杆放回起始位置。", "重复所需的重复次数，然后换到另一只手臂。"], "secondary_muscles": ["triceps", "upper back"], "instructions_zh_hant": ["調整座椅高度并將自己放在機器上，背部靠在墊子上。", "用一只手抓住杠桿手柄，并將肘部置于 90 度角。", "向上按下控制桿，直到手臂完全伸過頭頂。", "在頂部暫停片刻，然后慢慢將控制桿放回起始位置。", "重復所需的重復次數，然后換到另一只手臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0591', 'exercise', 1, '{"id": "0591", "target": "triceps", "name_en": "lever overhand triceps dip", "name_zh": "器械正握臂屈伸", "body_part": "upper arms", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0591-D5yqP2p.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械正握臂屈伸", "instructions_en": ["Adjust the machine to the appropriate height and secure your body in position.", "Grasp the handles with an overhand grip and position your body so that your arms are fully extended.", "Lower your body by bending your elbows, keeping your upper arms close to your sides.", "Continue lowering until your upper arms are parallel to the floor.", "Pause for a moment, then push yourself back up to the starting position by extending your elbows.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将机器调整到合适的高度并将身体固定到位。", "正手握住手柄，调整身体位置，使手臂完全伸展。", "弯曲肘部降低身体，保持上臂靠近身体两侧。", "继续降低，直到上臂与地板平行。", "暂停片刻，然后伸展肘部将自己推回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["將機器調整到合適的高度并將身體固定到位。", "正手握住手柄，調整身體位置，使手臂完全伸展。", "彎曲肘部降低身體，保持上臂靠近身體兩側。", "繼續降低，直到上臂與地板平行。", "暫停片刻，然后伸展肘部將自己推回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0592', 'exercise', 1, '{"id": "0592", "target": "biceps", "name_en": "lever preacher curl", "name_zh": "器械牧师凳弯举", "body_part": "upper arms", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0592-b6hQYMb.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械牧師凳彎舉", "instructions_en": ["Adjust the seat height and position yourself on the leverage machine.", "Place your upper arms on the pad and grip the handles with an underhand grip.", "Keep your back straight and your elbows positioned on the pad.", "Exhale and curl your forearms towards your upper arms, contracting your biceps.", "Pause for a moment at the top of the movement, squeezing your biceps.", "Inhale and slowly lower the handles back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度并将自己放在杠杆机上。", "将上臂放在垫子上，并用反手握住手柄。", "保持背部挺直，并将肘部放在垫子上。", "呼气并将前臂向上臂弯曲，收缩二头肌。", "在动作的最高点暂停片刻，挤压你的二头肌。", "吸气并慢慢将手柄放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["調整座椅高度并將自己放在杠桿機上。", "將上臂放在墊子上，并用反手握住手柄。", "保持背部挺直，并將肘部放在墊子上。", "呼氣并將前臂向上臂彎曲，收縮二頭肌。", "在動作的最高點暫停片刻，擠壓你的二頭肌。", "吸氣并慢慢將手柄放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1614', 'exercise', 1, '{"id": "1614", "target": "biceps", "name_en": "lever preacher curl v. 2", "name_zh": "器械牧师凳弯举变式2", "body_part": "upper arms", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/1614-ye84CTU.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械牧師凳彎舉變式2", "instructions_en": ["Adjust the seat height and position yourself on the machine with your upper arms resting on the pad and your chest against the support.", "Grasp the handles with an underhand grip, slightly wider than shoulder-width apart.", "Keep your upper arms stationary and exhale as you curl the handles towards your shoulders, contracting your biceps.", "Pause for a moment at the top of the movement, squeezing your biceps.", "Inhale as you slowly lower the handles back to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度，将自己放在机器上，上臂放在垫子上，胸部靠在支撑物上。", "反手握住手柄，握距略宽于肩宽。", "保持上臂静止，呼气，同时将手柄向肩膀卷曲，收缩二头肌。", "在动作的最高点暂停片刻，挤压你的二头肌。", "吸气，慢慢将手柄放回起始位置，充分伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["調整座椅高度，將自己放在機器上，上臂放在墊子上，胸部靠在支撐物上。", "反手握住手柄，握距略寬于肩寬。", "保持上臂靜止，呼氣，同時將手柄向肩膀卷曲，收縮二頭肌。", "在動作的最高點暫停片刻，擠壓你的二頭肌。", "吸氣，慢慢將手柄放回起始位置，充分伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2285', 'exercise', 1, '{"id": "2285", "target": "lats", "name_en": "lever pullover", "name_zh": "器械仰卧上拉", "body_part": "back", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/2285-4U7iLb5.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械仰臥上拉", "instructions_en": ["Adjust the seat and handles of the leverage machine to a comfortable position.", "Sit on the machine with your back against the pad and grasp the handles with an overhand grip.", "Keep your arms slightly bent and your core engaged.", "Slowly pull the handles towards your chest, squeezing your lats.", "Pause for a moment at the peak contraction, then slowly return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将杠杆机的座椅和手柄调整到舒适的位置。", "坐在机器上，背部靠在垫子上，并用正手握住手柄。", "保持手臂稍微弯曲，核心肌群参与。", "慢慢地将手柄拉向胸部，挤压背阔肌。", "在收缩高峰时暂停片刻，然后慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["將杠桿機的座椅和手柄調整到舒適的位置。", "坐在機器上，背部靠在墊子上，并用正手握住手柄。", "保持手臂稍微彎曲，核心肌群參與。", "慢慢地將手柄拉向胸部，擠壓背闊肌。", "在收縮高峰時暫停片刻，然后慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2736', 'exercise', 1, '{"id": "2736", "target": "lats", "name_en": "lever reverse grip lateral pulldown", "name_zh": "器械反握侧向下拉", "body_part": "back", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/2736-ky8FLU8.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械反握側向下拉", "instructions_en": ["Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.", "Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.", "Sit upright with your chest out and shoulders back, maintaining a slight arch in your lower back.", "Pull the handles down towards your chest, leading with your elbows and squeezing your shoulder blades together.", "Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度，将自己放在机器上，膝盖位于垫子下方，双脚平放在地面上。", "正手握住手柄，握距略宽于肩宽。", "坐直，挺胸，肩膀向后，保持下背部轻微的拱形。", "将手柄向下拉向胸部，用肘部引导并将肩胛骨挤压在一起。", "在动作底部暂停片刻，然后慢慢松开手柄回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "rhomboids", "rear deltoids"], "instructions_zh_hant": ["調整座椅高度，將自己放在機器上，膝蓋位于墊子下方，雙腳平放在地面上。", "正手握住手柄，握距略寬于肩寬。", "坐直，挺胸，肩膀向后，保持下背部輕微的拱形。", "將手柄向下拉向胸部，用肘部引導并將肩胛骨擠壓在一起。", "在動作底部暫停片刻，然后慢慢松開手柄回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1599', 'exercise', 1, '{"id": "1599", "target": "hamstrings", "name_en": "standing hamstring and calf stretch with strap", "name_zh": "站姿腘绳肌与小腿拉伸配合吊带", "body_part": "upper legs", "equipment": "rope", "gif_asset": "assets/fitness/videos/1599-xTjr103.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "站姿腘繩肌與小腿拉伸配合吊帶", "instructions_en": ["Stand upright with your feet shoulder-width apart.", "Hold the strap with both hands and place it around the ball of your foot.", "Keep your leg straight and slowly lean forward from your hips, keeping your back straight.", "Feel the stretch in your hamstring and calf muscles.", "Hold the stretch for 20-30 seconds.", "Release the stretch and repeat with the other leg.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站直，双脚分开与肩同宽。", "用双手握住带子并将其放在脚掌周围。", "保持腿伸直，从臀部慢慢向前倾斜，保持背部挺直。", "感受腿筋和小腿肌肉的拉伸。", "保持拉伸 20-30 秒。", "放松拉伸并用另一条腿重复。", "重复所需的重复次数。"], "secondary_muscles": ["calves"], "instructions_zh_hant": ["站直，雙腳分開與肩同寬。", "用雙手握住帶子并將其放在腳掌周圍。", "保持腿伸直，從臀部慢慢向前傾斜，保持背部挺直。", "感受腿筋和小腿肌肉的拉伸。", "保持拉伸 20-30 秒。", "放松拉伸并用另一條腿重復。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1616', 'exercise', 1, '{"id": "1616", "target": "biceps", "name_en": "lever reverse grip preacher curl", "name_zh": "器械反握牧师凳弯举", "body_part": "upper arms", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/1616-kj3hy6W.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械反握牧師凳彎舉", "instructions_en": ["Adjust the seat height and position yourself on the leverage machine.", "Grasp the handles with an underhand grip, palms facing up.", "Rest your upper arms on the preacher pad, ensuring your elbows are fully extended.", "Keeping your upper arms stationary, exhale and curl the handles towards your shoulders.", "Pause for a moment at the top of the movement, squeezing your biceps.", "Inhale and slowly lower the handles back to the starting position, fully extending your elbows.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度并将自己放在杠杆机上。", "反手握住手柄，手掌朝上。", "将上臂放在牧师垫上，确保肘部完全伸展。", "保持上臂静止，呼气并将手柄卷向肩膀。", "在动作的最高点暂停片刻，挤压你的二头肌。", "吸气，慢慢将手柄放回起始位置，充分伸展肘部。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["調整座椅高度并將自己放在杠桿機上。", "反手握住手柄，手掌朝上。", "將上臂放在牧師墊上，確保肘部完全伸展。", "保持上臂靜止，呼氣并將手柄卷向肩膀。", "在動作的最高點暫停片刻，擠壓你的二頭肌。", "吸氣，慢慢將手柄放回起始位置，充分伸展肘部。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1348', 'exercise', 1, '{"id": "1348", "target": "upper back", "name_en": "lever reverse grip vertical row", "name_zh": "器械反握垂直划船", "body_part": "back", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/1348-ZqNOWQ6.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械反握垂直劃船", "instructions_en": ["Adjust the seat height and footplate position to ensure proper alignment.", "Sit on the machine with your chest against the pad and your feet flat on the footplate.", "Grasp the handles with an underhand grip, palms facing up.", "Keep your back straight and engage your core.", "Pull the handles towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度和踏板位置以确保正确对齐。", "坐在机器上，胸部靠在垫子上，双脚平放在踏板上。", "反手握住手柄，手掌朝上。", "保持背部挺直并启动核心肌群。", "将手柄拉向胸部，将肩胛骨挤压在一起。", "在动作的最高点停顿片刻，然后慢慢松开并伸展手臂回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["調整座椅高度和踏板位置以確保正確對齊。", "坐在機器上，胸部靠在墊子上，雙腳平放在踏板上。", "反手握住手柄，手掌朝上。", "保持背部挺直并啟動核心肌群。", "將手柄拉向胸部，將肩胛骨擠壓在一起。", "在動作的最高點停頓片刻，然后慢慢松開并伸展手臂回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0593', 'exercise', 1, '{"id": "0593", "target": "glutes", "name_en": "lever reverse hyperextension", "name_zh": "器械反向挺身", "body_part": "upper legs", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0593-Krmb3cB.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械反向挺身", "instructions_en": ["Adjust the leverage machine to fit your body and secure your feet in the foot pads.", "Lie face down on the machine with your upper body hanging off the edge and your hips resting on the pad.", "Cross your arms over your chest or place them behind your head.", "Engage your glutes and hamstrings to lift your legs upward until they are parallel to the ground.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整杠杆机以适合您的身体并将双脚固定在脚垫中。", "面朝下躺在机器上，上半身悬在机器边缘，臀部放在垫子上。", "双臂交叉放在胸前或放在脑后。", "用臀部和腿筋将双腿向上抬起，直到它们与地面平行。", "在顶部暂停片刻，然后慢慢将双腿放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "lower back"], "instructions_zh_hant": ["調整杠桿機以適合您的身體并將雙腳固定在腳墊中。", "面朝下躺在機器上，上半身懸在機器邊緣，臀部放在墊子上。", "雙臂交叉放在胸前或放在腦后。", "用臀部和腿筋將雙腿向上抬起，直到它們與地面平行。", "在頂部暫停片刻，然后慢慢將雙腿放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1349', 'exercise', 1, '{"id": "1349", "target": "upper back", "name_en": "lever reverse t-bar row", "name_zh": "器械反向地雷杆划船", "body_part": "back", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/1349-BgljGjd.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械反向地雷桿劃船", "instructions_en": ["Adjust the seat height and footplate position on the leverage machine.", "Sit on the machine with your chest against the pad and your feet flat on the footplate.", "Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.", "Keep your back straight and engage your core.", "Pull the handles towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整杠杆机上的座椅高度和踏板位置。", "坐在机器上，胸部靠在垫子上，双脚平放在踏板上。", "正手握住手柄，握距略宽于肩宽。", "保持背部挺直并启动核心肌群。", "将手柄拉向胸部，将肩胛骨挤压在一起。", "在动作的最高点停顿片刻，然后慢慢松开并伸展手臂回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["調整杠桿機上的座椅高度和踏板位置。", "坐在機器上，胸部靠在墊子上，雙腳平放在踏板上。", "正手握住手柄，握距略寬于肩寬。", "保持背部挺直并啟動核心肌群。", "將手柄拉向胸部，將肩胛骨擠壓在一起。", "在動作的最高點停頓片刻，然后慢慢松開并伸展手臂回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2315', 'exercise', 1, '{"id": "2315", "target": "calves", "name_en": "lever rotary calf", "name_zh": "器械旋转式提踵", "body_part": "lower legs", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/2315-MrgP9L6.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械旋轉式提踵", "instructions_en": ["Adjust the seat height so that your knees are slightly bent and your feet are flat on the footplate.", "Place your toes on the footplate, with your heels hanging off the edge.", "Grasp the handles or the sides of the machine for stability.", "Push through the balls of your feet, raising your heels as high as possible.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度，使膝盖稍微弯曲，双脚平放在踏板上。", "将脚趾放在踏板上，脚跟悬在踏板边缘。", "抓住机器的手柄或侧面以保持稳定性。", "用脚掌推动，尽可能高地抬高脚后跟。", "在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["soleus", "ankle stabilizers"], "instructions_zh_hant": ["調整座椅高度，使膝蓋稍微彎曲，雙腳平放在踏板上。", "將腳趾放在踏板上，腳跟懸在踏板邊緣。", "抓住機器的手柄或側面以保持穩定性。", "用腳掌推動，盡可能高地抬高腳后跟。", "在頂部停頓片刻，然后慢慢降低腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2335', 'exercise', 1, '{"id": "2335", "target": "calves", "name_en": "lever seated calf press", "name_zh": "器械坐姿小腿推举", "body_part": "lower legs", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/2335-Ie9UGty.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械坐姿小腿推舉", "instructions_en": ["Adjust the seat of the machine so that your shoulders are aligned with the lever pad.", "Place your toes on the lower portion of the platform and position your knees under the lever pad.", "Grasp the handles on the sides of the seat for stability.", "Press the lever pad down by extending your ankles, lifting your heels as high as possible.", "Pause for a moment at the top of the movement, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整机器的座椅，使您的肩膀与杠杆垫对齐。", "将脚趾放在平台的下部，并将膝盖放在杠杆垫下方。", "抓住座椅两侧的把手以保持稳定性。", "伸展脚踝，将杠杆垫压下，尽可能高地抬起脚后跟。", "在动作的最高点暂停片刻，然后慢慢降低脚跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["soleus", "hamstrings"], "instructions_zh_hant": ["調整機器的座椅，使您的肩膀與杠桿墊對齊。", "將腳趾放在平臺的下部，并將膝蓋放在杠桿墊下方。", "抓住座椅兩側的把手以保持穩定性。", "伸展腳踝，將杠桿墊壓下，盡可能高地抬起腳后跟。", "在動作的最高點暫停片刻，然后慢慢降低腳跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0594', 'exercise', 1, '{"id": "0594", "target": "calves", "name_en": "lever seated calf raise", "name_zh": "器械坐姿提踵", "body_part": "lower legs", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0594-bOOdeyc.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械坐姿提踵", "instructions_en": ["Adjust the seat height so that your knees are slightly bent and your feet are flat on the footplate.", "Place your toes on the footplate with your heels hanging off the edge.", "Grasp the handles or the sides of the seat for stability.", "Push through the balls of your feet to raise your heels as high as possible.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度，使膝盖稍微弯曲，双脚平放在踏板上。", "将脚趾放在踏板上，脚跟悬在踏板边缘。", "抓住把手或座椅侧面以保持稳定性。", "推动脚掌，将脚后跟尽可能抬高。", "在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["soleus", "ankle stabilizers"], "instructions_zh_hant": ["調整座椅高度，使膝蓋稍微彎曲，雙腳平放在踏板上。", "將腳趾放在踏板上，腳跟懸在踏板邊緣。", "抓住把手或座椅側面以保持穩定性。", "推動腳掌，將腳后跟盡可能抬高。", "在頂部停頓片刻，然后慢慢降低腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1452', 'exercise', 1, '{"id": "1452", "target": "abs", "name_en": "lever seated crunch", "name_zh": "器械坐姿卷腹", "body_part": "waist", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/1452-Wgaz7pm.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械坐姿卷腹", "instructions_en": ["Sit on the leverage machine with your back against the pad and your feet flat on the floor.", "Grasp the handles or place your hands on the side pads for support.", "Engage your abs and slowly lean back, allowing the pad to move with you.", "Once your upper body is at a 45-degree angle, contract your abs and crunch forward, bringing your chest towards your knees.", "Pause for a moment at the top, then slowly release and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在杠杆机上，背部靠在垫子上，双脚平放在地板上。", "抓住手柄或将手放在侧垫上以获得支撑。", "收紧腹肌并慢慢向后倾斜，让垫子随着您一起移动。", "一旦你的上半身呈 45 度角，收缩腹肌并向前卷腹，使胸部靠近膝盖。", "在顶部停顿片刻，然后慢慢松开并返回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["obliques"], "instructions_zh_hant": ["坐在杠桿機上，背部靠在墊子上，雙腳平放在地板上。", "抓住手柄或將手放在側墊上以獲得支撐。", "收緊腹肌并慢慢向后傾斜，讓墊子隨著您一起移動。", "一旦你的上半身呈 45 度角，收縮腹肌并向前卷腹，使胸部靠近膝蓋。", "在頂部停頓片刻，然后慢慢松開并返回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0595', 'exercise', 1, '{"id": "0595", "target": "abs", "name_en": "lever seated crunch (chest pad)", "name_zh": "器械坐姿卷腹（胸部靠垫）", "body_part": "waist", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0595-ZnJHhMk.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械坐姿卷腹（胸部靠墊）", "instructions_en": ["Adjust the seat height and chest pad position according to your comfort.", "Sit on the machine with your back against the chest pad and your feet flat on the floor.", "Grasp the handles or side bars for stability.", "Engage your abs and slowly lean back, allowing the chest pad to move with you.", "Pause for a moment at the maximum contraction, feeling the tension in your abs.", "Slowly return to the starting position by contracting your abs and pulling yourself back up.", "Repeat for the desired number of repetitions."], "instructions_zh": ["根据您的舒适度调整座椅高度和胸垫位置。", "坐在机器上，背部靠在胸垫上，双脚平放在地板上。", "抓住手柄或侧杆以保持稳定性。", "收紧腹肌并慢慢向后倾斜，让胸垫随着您一起移动。", "在最大收缩时暂停片刻，感受腹肌的紧张感。", "收缩腹肌并将自己拉回来，慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["obliques"], "instructions_zh_hant": ["根據您的舒適度調整座椅高度和胸墊位置。", "坐在機器上，背部靠在胸墊上，雙腳平放在地板上。", "抓住手柄或側桿以保持穩定性。", "收緊腹肌并慢慢向后傾斜，讓胸墊隨著您一起移動。", "在最大收縮時暫停片刻，感受腹肌的緊張感。", "收縮腹肌并將自己拉回來，慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3760', 'exercise', 1, '{"id": "3760", "target": "abs", "name_en": "lever seated crunch v. 2", "name_zh": "器械坐姿卷腹变式2", "body_part": "waist", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/3760-eXFXCY0.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械坐姿卷腹變式2", "instructions_en": ["Sit on the leverage machine with your back against the pad and your feet secured under the footpads.", "Place your hands on the handles or the sides of the seat for support.", "Engage your abs and slowly crunch forward, bringing your chest towards your knees.", "Pause for a moment at the top of the movement, squeezing your abs.", "Slowly return to the starting position, allowing your back to round slightly.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在杠杆机上，背部靠在垫子上，双脚固定在脚垫下。", "将手放在把手上或座椅两侧以获得支撑。", "收紧腹肌，慢慢向前挺胸，使胸部靠近膝盖。", "在动作的最高点暂停片刻，挤压腹肌。", "慢慢回到起始位置，让背部稍微弯曲。", "重复所需的重复次数。"], "secondary_muscles": ["obliques", "hip flexors"], "instructions_zh_hant": ["坐在杠桿機上，背部靠在墊子上，雙腳固定在腳墊下。", "將手放在把手上或座椅兩側以獲得支撐。", "收緊腹肌，慢慢向前挺胸，使胸部靠近膝蓋。", "在動作的最高點暫停片刻，擠壓腹肌。", "慢慢回到起始位置，讓背部稍微彎曲。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1451', 'exercise', 1, '{"id": "1451", "target": "triceps", "name_en": "lever seated dip", "name_zh": "器械坐姿臂屈伸", "body_part": "upper arms", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/1451-BRImeP8.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械坐姿臂屈伸", "instructions_en": ["Adjust the seat height so that your feet are flat on the ground and your knees are at a 90-degree angle.", "Grasp the handles of the leverage machine with your palms facing down and your arms fully extended.", "Slowly lower your body by bending your elbows until your upper arms are parallel to the ground.", "Pause for a moment, then push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度，使双脚平放在地面上，膝盖呈 90 度角。", "手掌朝下，抓住杠杆机的手柄，双臂完全伸展。", "弯曲肘部，慢慢降低身体，直到上臂与地面平行。", "暂停片刻，然后伸直手臂，将自己推回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["調整座椅高度，使雙腳平放在地面上，膝蓋呈 90 度角。", "手掌朝下，抓住杠桿機的手柄，雙臂完全伸展。", "彎曲肘部，慢慢降低身體，直到上臂與地面平行。", "暫停片刻，然后伸直手臂，將自己推回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0596', 'exercise', 1, '{"id": "0596", "target": "pectorals", "name_en": "lever seated fly", "name_zh": "器械坐姿飞鸟", "body_part": "chest", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0596-v3xmPAR.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械坐姿飛鳥", "instructions_en": ["Adjust the seat height and position yourself on the machine with your back against the pad.", "Grasp the handles with a pronated grip and keep your elbows slightly bent.", "Exhale and push the handles forward, bringing them together in front of your chest.", "Pause for a moment, squeezing your chest muscles.", "Inhale and slowly return to the starting position, allowing your chest muscles to stretch.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度并将自己放在机器上，背部靠在垫子上。", "旋前抓住手柄，并保持肘部稍微弯曲。", "呼气并将手柄向前推，将它们放在胸前。", "暂停片刻，挤压胸部肌肉。", "吸气并慢慢回到起始位置，让胸部肌肉伸展。", "重复所需的重复次数。"], "secondary_muscles": ["deltoids", "trapezius"], "instructions_zh_hant": ["調整座椅高度并將自己放在機器上，背部靠在墊子上。", "旋前抓住手柄，并保持肘部稍微彎曲。", "呼氣并將手柄向前推，將它們放在胸前。", "暫停片刻，擠壓胸部肌肉。", "吸氣并慢慢回到起始位置，讓胸部肌肉伸展。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3759', 'exercise', 1, '{"id": "3759", "target": "glutes", "name_en": "lever seated good morning", "name_zh": "器械坐姿早安式", "body_part": "upper legs", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/3759-XsCcxCC.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械坐姿早安式", "instructions_en": ["Adjust the seat height so that your hips are slightly higher than your knees.", "Sit on the machine with your back against the pad and your feet flat on the footrests.", "Grasp the handles or the sides of the seat for stability.", "Keeping your back straight, slowly lean forward from your hips until your upper body is parallel to the ground.", "Pause for a moment, then slowly return to the starting position by pushing through your glutes and hamstrings.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度，使臀部略高于膝盖。", "坐在机器上，背部靠在垫子上，双脚平放在脚踏板上。", "抓住把手或座椅侧面以保持稳定性。", "保持背部挺直，从臀部开始慢慢向前倾斜，直到上半身与地面平行。", "暂停片刻，然后通过推动臀肌和腿筋慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "lower back"], "instructions_zh_hant": ["調整座椅高度，使臀部略高于膝蓋。", "坐在機器上，背部靠在墊子上，雙腳平放在腳踏板上。", "抓住把手或座椅側面以保持穩定性。", "保持背部挺直，從臀部開始慢慢向前傾斜，直到上半身與地面平行。", "暫停片刻，然后通過推動臀肌和腿筋慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0597', 'exercise', 1, '{"id": "0597", "target": "abductors", "name_en": "lever seated hip abduction", "name_zh": "器械坐姿髋部外展", "body_part": "upper legs", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0597-CHpahtl.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械坐姿髖部外展", "instructions_en": ["Adjust the seat height so that your knees are at a 90-degree angle.", "Sit on the machine with your back against the backrest and your feet on the footrests.", "Place your hands on the side handles for stability.", "Engage your abductors and slowly push your legs apart, away from the midline of your body.", "Pause for a moment at the end of the movement, then slowly bring your legs back together to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度，使膝盖成 90 度角。", "坐在机器上，背部靠在靠背上，双脚放在脚踏板上。", "将手放在侧手柄上以保持稳定性。", "启动外展肌并慢慢将双腿分开，远离身体中线。", "动作结束时暂停片刻，然后慢慢将双腿放回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings"], "instructions_zh_hant": ["調整座椅高度，使膝蓋成 90 度角。", "坐在機器上，背部靠在靠背上，雙腳放在腳踏板上。", "將手放在側手柄上以保持穩定性。", "啟動外展肌并慢慢將雙腿分開，遠離身體中線。", "動作結束時暫停片刻，然后慢慢將雙腿放回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0598', 'exercise', 1, '{"id": "0598", "target": "adductors", "name_en": "lever seated hip adduction", "name_zh": "器械坐姿髋部内收", "body_part": "upper legs", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0598-oHsrypV.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械坐姿髖部內收", "instructions_en": ["Adjust the seat height and position yourself on the machine with your back against the backrest.", "Place your feet on the footrests and grasp the handles for stability.", "Engage your adductor muscles and slowly bring your legs together, squeezing your inner thighs.", "Pause for a moment at the peak contraction, then slowly return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度并将自己放在机器上，背部靠在靠背上。", "将脚放在脚踏板上并抓住手柄以保持稳定。", "收紧内收肌，慢慢将双腿并拢，挤压大腿内侧。", "在收缩高峰时暂停片刻，然后慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "glutes"], "instructions_zh_hant": ["調整座椅高度并將自己放在機器上，背部靠在靠背上。", "將腳放在腳踏板上并抓住手柄以保持穩定。", "收緊內收肌，慢慢將雙腿并攏，擠壓大腿內側。", "在收縮高峰時暫停片刻，然后慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0600', 'exercise', 1, '{"id": "0600", "target": "abs", "name_en": "lever seated leg raise crunch", "name_zh": "器械坐姿举腿卷腹", "body_part": "waist", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0600-PQ2AtC3.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械坐姿舉腿卷腹", "instructions_en": ["Sit on the leverage machine with your back against the backrest and your feet on the footrests.", "Grasp the handles or sidebars for stability.", "Engage your abs and slowly raise your legs up towards your chest, curling your torso forward at the same time.", "Pause for a moment at the top, then slowly lower your legs and torso back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在杠杆机上，背部靠在靠背上，双脚放在脚踏板上。", "抓住手柄或侧杆以保持稳定性。", "收紧腹肌，慢慢地将双腿抬向胸部，同时向前卷曲躯干。", "在顶部停顿片刻，然后慢慢降低双腿和躯干回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["坐在杠桿機上，背部靠在靠背上，雙腳放在腳踏板上。", "抓住手柄或側桿以保持穩定性。", "收緊腹肌，慢慢地將雙腿抬向胸部，同時向前卷曲軀幹。", "在頂部停頓片刻，然后慢慢降低雙腿和軀幹回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0602', 'exercise', 1, '{"id": "0602", "target": "delts", "name_en": "lever seated reverse fly", "name_zh": "器械坐姿反向飞鸟", "body_part": "shoulders", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0602-myfUsKf.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械坐姿反向飛鳥", "instructions_en": ["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.", "Grasp the handles with an overhand grip and keep your arms slightly bent.", "Exhale and squeeze your shoulder blades together as you pull the handles back and outward, away from your body.", "Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度，将自己放在机器上，胸部靠在垫子上，双脚平放在地板上。", "正手握住手柄，并保持手臂稍微弯曲。", "呼气并将肩胛骨挤压在一起，同时向后和向外拉动手柄，使其远离身体。", "在收缩峰值时停顿片刻，然后吸气，慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["trapezius", "rhomboids"], "instructions_zh_hant": ["調整座椅高度，將自己放在機器上，胸部靠在墊子上，雙腳平放在地板上。", "正手握住手柄，并保持手臂稍微彎曲。", "呼氣并將肩胛骨擠壓在一起，同時向后和向外拉動手柄，使其遠離身體。", "在收縮峰值時停頓片刻，然后吸氣，慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0601', 'exercise', 1, '{"id": "0601", "target": "delts", "name_en": "lever seated reverse fly (parallel grip)", "name_zh": "器械坐姿反向飞鸟（对握）", "body_part": "shoulders", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0601-xiHiJcA.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械坐姿反向飛鳥（對握）", "instructions_en": ["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.", "Grasp the handles with a parallel grip, palms facing each other, and keep your arms slightly bent.", "Exhale and squeeze your shoulder blades together as you pull the handles back and outward, away from your body.", "Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度，将自己放在机器上，胸部靠在垫子上，双脚平放在地板上。", "平行握住手柄，手掌相对，并保持手臂稍微弯曲。", "呼气并将肩胛骨挤压在一起，同时向后和向外拉动手柄，使其远离身体。", "在收缩峰值时停顿片刻，然后吸气，慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["trapezius", "rhomboids"], "instructions_zh_hant": ["調整座椅高度，將自己放在機器上，胸部靠在墊子上，雙腳平放在地板上。", "平行握住手柄，手掌相對，并保持手臂稍微彎曲。", "呼氣并將肩胛骨擠壓在一起，同時向后和向外拉動手柄，使其遠離身體。", "在收縮峰值時停頓片刻，然后吸氣，慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1350', 'exercise', 1, '{"id": "1350", "target": "upper back", "name_en": "lever seated row", "name_zh": "器械坐姿划船", "body_part": "back", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/1350-7I6LNUG.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械坐姿劃船", "instructions_en": ["Adjust the seat height and footrests to a comfortable position.", "Sit on the machine with your chest against the pad and your feet on the footrests.", "Grasp the handles with an overhand grip, shoulder-width apart.", "Keep your back straight and your core engaged.", "Pull the handles towards your body, squeezing your shoulder blades together.", "Pause for a moment at the peak of the movement.", "Slowly release the handles and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将座椅高度和脚踏板调整到舒适的位置。", "坐在机器上，胸部靠在垫子上，双脚放在脚踏板上。", "正手握住手柄，距离与肩同宽。", "保持背部挺直，核心肌群参与。", "将手柄拉向身体，将肩胛骨挤压在一起。", "在动作的最高点停顿片刻。", "慢慢松开手柄并返回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["將座椅高度和腳踏板調整到舒適的位置。", "坐在機器上，胸部靠在墊子上，雙腳放在腳踏板上。", "正手握住手柄，距離與肩同寬。", "保持背部挺直，核心肌群參與。", "將手柄拉向身體，將肩胛骨擠壓在一起。", "在動作的最高點停頓片刻。", "慢慢松開手柄并返回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0640', 'exercise', 1, '{"id": "0640", "target": "abs", "name_en": "one arm slam (with medicine ball)", "name_zh": "单臂砸地（配合药球）", "body_part": "waist", "equipment": "medicine ball", "gif_asset": "assets/fitness/videos/0640-jCrtE9b.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "單臂砸地（配合藥球）", "instructions_en": ["Stand with your feet shoulder-width apart, holding the medicine ball with one hand in front of your waist.", "Bend your knees slightly and engage your core.", "Raise the medicine ball above your head, fully extending your arm.", "Forcefully slam the medicine ball down to the ground, using your core and shoulders to generate power.", "Catch the medicine ball on the bounce and repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，一只手将健身球放在腰前。", "稍微弯曲膝盖并启动核心。", "将健身球举过头顶，充分伸展手臂。", "用力将药球摔到地上，用你的核心和肩膀产生力量。", "抓住弹起的实心球，然后重复所需的重复次数。"], "secondary_muscles": ["shoulders", "back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，一只手將健身球放在腰前。", "稍微彎曲膝蓋并啟動核心。", "將健身球舉過頭頂，充分伸展手臂。", "用力將藥球摔到地上，用你的核心和肩膀產生力量。", "抓住彈起的實心球，然后重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1385', 'exercise', 1, '{"id": "1385", "target": "calves", "name_en": "lever seated squat calf raise on leg press machine", "name_zh": "坐姿腿举机屈膝提踵", "body_part": "lower legs", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/1385-IeDEXTe.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "坐姿腿舉機屈膝提踵", "instructions_en": ["Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the footplate.", "Sit on the machine with your back against the backrest and your feet flat on the footplate, shoulder-width apart.", "Place your toes and the balls of your feet on the footplate, keeping your heels off the edge.", "Release the safety handles and push the footplate away from you by extending your knees.", "Once your knees are fully extended, slowly lower your heels by flexing your calves.", "Pause for a moment at the bottom, then push the footplate back up by extending your calves.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整压腿机的座椅，使双脚放在踏板上时膝盖稍微弯曲。", "坐在机器上，背部靠在靠背上，双脚平放在踏板上，与肩同宽。", "将脚趾和脚掌放在踏板上，使脚后跟远离边缘。", "松开安全手柄，并通过伸展膝盖将踏板推离您。", "一旦膝盖完全伸展，弯曲小腿，慢慢降低脚后跟。", "在底部停顿片刻，然后通过伸展小腿将踏板向后推。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "glutes"], "instructions_zh_hant": ["調整壓腿機的座椅，使雙腳放在踏板上時膝蓋稍微彎曲。", "坐在機器上，背部靠在靠背上，雙腳平放在踏板上，與肩同寬。", "將腳趾和腳掌放在踏板上，使腳后跟遠離邊緣。", "松開安全手柄，并通過伸展膝蓋將踏板推離您。", "一旦膝蓋完全伸展，彎曲小腿，慢慢降低腳后跟。", "在底部停頓片刻，然后通過伸展小腿將踏板向后推。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0603', 'exercise', 1, '{"id": "0603", "target": "delts", "name_en": "lever shoulder press", "name_zh": "器械肩上推举", "body_part": "shoulders", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0603-67n3r98.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械肩上推舉", "instructions_en": ["Adjust the seat height and position yourself on the machine with your back against the backrest.", "Grasp the handles with an overhand grip and position your hands at shoulder level.", "Push the handles upward until your arms are fully extended, but do not lock your elbows.", "Pause for a moment at the top, then slowly lower the handles back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度并将自己放在机器上，背部靠在靠背上。", "正手握住手柄，并将双手置于肩部水平。", "向上推动手柄，直到手臂完全伸展，但不要锁住肘部。", "在顶部暂停片刻，然后慢慢将手柄放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "chest"], "instructions_zh_hant": ["調整座椅高度并將自己放在機器上，背部靠在靠背上。", "正手握住手柄，并將雙手置于肩部水平。", "向上推動手柄，直到手臂完全伸展，但不要鎖住肘部。", "在頂部暫停片刻，然后慢慢將手柄放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0638', 'exercise', 1, '{"id": "0638", "target": "lats", "name_en": "one arm chin-up", "name_zh": "单臂反握引体向上", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0638-HjdqmZa.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "單臂反握引體向上", "instructions_en": ["Stand facing a pull-up bar with your feet shoulder-width apart.", "Reach up and grab the bar with an underhand grip, with one hand gripping the bar and the other hand holding your wrist for support.", "Hang from the bar with your arm fully extended, keeping your body straight and your core engaged.", "Pull yourself up towards the bar by bending your elbow and squeezing your back muscles.", "Continue pulling until your chin is above the bar, then slowly lower yourself back down to the starting position.", "Repeat for the desired number of repetitions, then switch arms and repeat."], "instructions_zh": ["面向引体向上杆站立，双脚分开与肩同宽。", "抬起手，用反握方式抓住杠铃，一只手握住杠铃，另一只手握住手腕以提供支撑。", "悬挂在杠上，手臂完全伸展，保持身体伸直，核心肌群参与。", "弯曲肘部并挤压背部肌肉，将自己拉向杠铃。", "继续拉，直到下巴高于杠铃，然后慢慢降低回到起始位置。", "重复所需的重复次数，然后换臂重复。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["面向引體向上桿站立，雙腳分開與肩同寬。", "抬起手，用反握方式抓住杠鈴，一只手握住杠鈴，另一只手握住手腕以提供支撐。", "懸掛在杠上，手臂完全伸展，保持身體伸直，核心肌群參與。", "彎曲肘部并擠壓背部肌肉，將自己拉向杠鈴。", "繼續拉，直到下巴高于杠鈴，然后慢慢降低回到起始位置。", "重復所需的重復次數，然后換臂重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0869', 'exercise', 1, '{"id": "0869", "target": "delts", "name_en": "lever shoulder press v. 2", "name_zh": "器械肩上推举变式2", "body_part": "shoulders", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0869-vqsbmL0.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械肩上推舉變式2", "instructions_en": ["Adjust the seat height and backrest of the leverage machine to a comfortable position.", "Sit on the machine with your back against the backrest and your feet flat on the floor.", "Grasp the handles of the machine with an overhand grip, slightly wider than shoulder-width apart.", "Push the handles upward and forward until your arms are fully extended, but not locked.", "Pause for a moment at the top, then slowly lower the handles back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将杠杆机的座椅高度和靠背调整到舒适的位置。", "坐在机器上，背部靠在靠背上，双脚平放在地板上。", "正手握住机器的手柄，握距略宽于肩宽。", "向上和向前推动手柄，直到手臂完全伸展，但未锁定。", "在顶部暂停片刻，然后慢慢将手柄放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "chest"], "instructions_zh_hant": ["將杠桿機的座椅高度和靠背調整到舒適的位置。", "坐在機器上，背部靠在靠背上，雙腳平放在地板上。", "正手握住機器的手柄，握距略寬于肩寬。", "向上和向前推動手柄，直到手臂完全伸展，但未鎖定。", "在頂部暫停片刻，然后慢慢將手柄放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2318', 'exercise', 1, '{"id": "2318", "target": "delts", "name_en": "lever shoulder press v. 3", "name_zh": "器械肩上推举变式3", "body_part": "shoulders", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/2318-dNFYIU1.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械肩上推舉變式3", "instructions_en": ["Adjust the seat height and backrest of the leverage machine to a comfortable position.", "Sit on the machine with your back against the backrest and your feet flat on the floor.", "Grasp the handles of the machine with an overhand grip, slightly wider than shoulder-width apart.", "Push the handles upward and forward until your arms are fully extended, but not locked.", "Pause for a moment at the top, then slowly lower the handles back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将杠杆机的座椅高度和靠背调整到舒适的位置。", "坐在机器上，背部靠在靠背上，双脚平放在地板上。", "正手握住机器的手柄，握距略宽于肩宽。", "向上和向前推动手柄，直到手臂完全伸展，但未锁定。", "在顶部暂停片刻，然后慢慢将手柄放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "chest"], "instructions_zh_hant": ["將杠桿機的座椅高度和靠背調整到舒適的位置。", "坐在機器上，背部靠在靠背上，雙腳平放在地板上。", "正手握住機器的手柄，握距略寬于肩寬。", "向上和向前推動手柄，直到手臂完全伸展，但未鎖定。", "在頂部暫停片刻，然后慢慢將手柄放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0604', 'exercise', 1, '{"id": "0604", "target": "traps", "name_en": "lever shrug", "name_zh": "器械耸肩", "body_part": "back", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0604-ZZKbeMw.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械聳肩", "instructions_en": ["Adjust the seat height and position yourself on the leverage machine with your back against the pad.", "Grasp the handles with an overhand grip and keep your arms straight.", "Keeping your back straight, lift your shoulders up towards your ears as high as possible.", "Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度，将自己放在杠杆机上，背部靠在垫子上。", "正手握住手柄并保持手臂伸直。", "保持背部挺直，将肩膀尽可能高地抬向耳朵。", "保持收缩一会儿，然后慢慢将肩膀放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["調整座椅高度，將自己放在杠桿機上，背部靠在墊子上。", "正手握住手柄并保持手臂伸直。", "保持背部挺直，將肩膀盡可能高地抬向耳朵。", "保持收縮一會兒，然后慢慢將肩膀放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1688', 'exercise', 1, '{"id": "1688", "target": "abs", "name_en": "lunge with twist", "name_zh": "弓步配合转体", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1688-K9VL0Jq.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "弓步配合轉體", "instructions_en": ["Start by standing with your feet shoulder-width apart.", "Take a step forward with your right foot, lowering your body into a lunge position.", "As you lunge, twist your torso to the right, bringing your left elbow towards your right knee.", "Pause for a moment, then return to the starting position.", "Repeat on the other side, stepping forward with your left foot and twisting your torso to the left.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["首先站立，双脚分开与肩同宽。", "右脚向前迈出一步，将身体降低至弓步位置。", "当你弓步时，将你的躯干向右扭转，将你的左肘拉向你的右膝盖。", "暂停片刻，然后回到起始位置。", "在另一侧重复，左脚向前迈出，并将躯干向左扭转。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["quadriceps", "glutes", "hamstrings"], "instructions_zh_hant": ["首先站立，雙腳分開與肩同寬。", "右腳向前邁出一步，將身體降低至弓步位置。", "當你弓步時，將你的軀幹向右扭轉，將你的左肘拉向你的右膝蓋。", "暫停片刻，然后回到起始位置。", "在另一側重復，左腳向前邁出，并將軀幹向左扭轉。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0605', 'exercise', 1, '{"id": "0605", "target": "calves", "name_en": "lever standing calf raise", "name_zh": "器械站姿提踵", "body_part": "lower legs", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0605-ykUOVze.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械站姿提踵", "instructions_en": ["Adjust the machine to your height and stand with your feet shoulder-width apart.", "Place your shoulders under the pads and hold onto the handles for stability.", "Raise your heels as high as possible by extending your ankles.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将机器调整到您的高度，双脚分开与肩同宽站立。", "将肩膀放在护垫下方，并握住手柄以保持稳定。", "伸展脚踝，将脚后跟尽可能抬高。", "在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["soleus", "ankle stabilizers"], "instructions_zh_hant": ["將機器調整到您的高度，雙腳分開與肩同寬站立。", "將肩膀放在護墊下方，并握住手柄以保持穩定。", "伸展腳踝，將腳后跟盡可能抬高。", "在頂部停頓片刻，然后慢慢降低腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3758', 'exercise', 1, '{"id": "3758", "target": "pectorals", "name_en": "lever standing chest press", "name_zh": "器械站姿推胸", "body_part": "chest", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/3758-WbNq5Xu.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械站姿推胸", "instructions_en": ["Adjust the seat height and position yourself on the machine with your feet flat on the ground.", "Grasp the handles with an overhand grip and position your hands at chest level.", "Push the handles forward until your arms are fully extended, keeping your elbows slightly bent.", "Pause for a moment, then slowly bring the handles back towards your chest, maintaining control throughout the movement.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度并将自己放在机器上，双脚平放在地面上。", "正手握住手柄，并将双手置于胸部水平。", "向前推动手柄，直到手臂完全伸展，保持肘部稍微弯曲。", "暂停片刻，然后慢慢地将手柄拉回到胸部，在整个动作过程中保持控制。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["調整座椅高度并將自己放在機器上，雙腳平放在地面上。", "正手握住手柄，并將雙手置于胸部水平。", "向前推動手柄，直到手臂完全伸展，保持肘部稍微彎曲。", "暫停片刻，然后慢慢地將手柄拉回到胸部，在整個動作過程中保持控制。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0606', 'exercise', 1, '{"id": "0606", "target": "upper back", "name_en": "lever t bar row", "name_zh": "器械地雷杆划船", "body_part": "back", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0606-aaXr7ld.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械地雷桿劃船", "instructions_en": ["Adjust the seat height and footplate position to ensure proper alignment.", "Sit on the machine with your chest against the pad and your feet flat on the footplate.", "Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.", "Keep your back straight and engage your core.", "Pull the handles towards your torso, squeezing your shoulder blades together.", "Pause for a moment at the peak contraction, then slowly release the handles back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度和踏板位置以确保正确对齐。", "坐在机器上，胸部靠在垫子上，双脚平放在踏板上。", "正手握住手柄，握距略宽于肩宽。", "保持背部挺直并启动核心肌群。", "将手柄拉向躯干，将肩胛骨挤压在一起。", "在收缩峰值时暂停片刻，然后慢慢松开手柄回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["調整座椅高度和踏板位置以確保正確對齊。", "坐在機器上，胸部靠在墊子上，雙腳平放在踏板上。", "正手握住手柄，握距略寬于肩寬。", "保持背部挺直并啟動核心肌群。", "將手柄拉向軀幹，將肩胛骨擠壓在一起。", "在收縮峰值時暫停片刻，然后慢慢松開手柄回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1351', 'exercise', 1, '{"id": "1351", "target": "upper back", "name_en": "lever t-bar reverse grip row", "name_zh": "器械地雷杆反握划船", "body_part": "back", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/1351-FVM1AUZ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械地雷桿反握劃船", "instructions_en": ["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.", "Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.", "Keep your back straight and engage your core.", "Pull the handles towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度，将自己放在机器上，胸部靠在垫子上，双脚平放在地板上。", "正手握住手柄，握距略宽于肩宽。", "保持背部挺直并启动核心肌群。", "将手柄拉向胸部，将肩胛骨挤压在一起。", "在动作的最高点停顿片刻，然后慢慢松开并伸展手臂回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["調整座椅高度，將自己放在機器上，胸部靠在墊子上，雙腳平放在地板上。", "正手握住手柄，握距略寬于肩寬。", "保持背部挺直并啟動核心肌群。", "將手柄拉向胸部，將肩胛骨擠壓在一起。", "在動作的最高點停頓片刻，然后慢慢松開并伸展手臂回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0607', 'exercise', 1, '{"id": "0607", "target": "triceps", "name_en": "lever triceps extension", "name_zh": "器械臂屈伸", "body_part": "upper arms", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0607-Ser9eQp.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械臂屈伸", "instructions_en": ["Adjust the seat height and position yourself on the machine with your back against the pad.", "Grasp the handles with an overhand grip and fully extend your arms in front of you.", "Keeping your upper arms stationary, slowly lower the handles towards your forehead by bending your elbows.", "Pause for a moment at the bottom, then push the handles back up to the starting position by extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度并将自己放在机器上，背部靠在垫子上。", "正手握住手柄，并将手臂完全伸展到身前。", "保持上臂不动，弯曲肘部，慢慢将手柄向前额降低。", "在底部暂停片刻，然后伸展双臂将手柄推回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["調整座椅高度并將自己放在機器上，背部靠在墊子上。", "正手握住手柄，并將手臂完全伸展到身前。", "保持上臂不動，彎曲肘部，慢慢將手柄向前額降低。", "在底部暫停片刻，然后伸展雙臂將手柄推回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1313', 'exercise', 1, '{"id": "1313", "target": "upper back", "name_en": "lever unilateral row", "name_zh": "器械单侧划船", "body_part": "back", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/1313-oROuvrX.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械單側劃船", "instructions_en": ["Adjust the seat height and position yourself facing the machine.", "Grasp the handles with an overhand grip and keep your back straight.", "Pull the handles towards your body, squeezing your shoulder blades together.", "Pause for a moment at the peak of the movement, then slowly release and extend your arms back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度并将自己面向机器。", "正手握住手柄并保持背部挺直。", "将手柄拉向身体，将肩胛骨挤压在一起。", "在动作的最高点停顿片刻，然后慢慢松开并伸展手臂回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["調整座椅高度并將自己面向機器。", "正手握住手柄并保持背部挺直。", "將手柄拉向身體，將肩胛骨擠壓在一起。", "在動作的最高點停頓片刻，然后慢慢松開并伸展手臂回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0609', 'exercise', 1, '{"id": "0609", "target": "upper back", "name_en": "london bridge", "name_zh": "伦敦式桥式", "body_part": "back", "equipment": "rope", "gif_asset": "assets/fitness/videos/0609-bLyQokI.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "倫敦式橋式", "instructions_en": ["Attach the rope to a high anchor point.", "Stand facing away from the anchor point with your feet shoulder-width apart.", "Grasp the rope with an overhand grip, palms facing down.", "Lean forward slightly, keeping your back straight and core engaged.", "Pull the rope towards your body, squeezing your shoulder blades together.", "Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将绳子连接到高锚点。", "背对锚点站立，双脚与肩同宽。", "正手握住绳子，手掌朝下。", "稍微向前倾，保持背部挺直，核心参与。", "将绳子拉向身体，将肩胛骨挤压在一起。", "在动作的最高点停顿片刻，然后慢慢释放张力，回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "biceps", "forearms"], "instructions_zh_hant": ["將繩子連接到高錨點。", "背對錨點站立，雙腳與肩同寬。", "正手握住繩子，手掌朝下。", "稍微向前傾，保持背部挺直，核心參與。", "將繩子拉向身體，將肩胛骨擠壓在一起。", "在動作的最高點停頓片刻，然后慢慢釋放張力，回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3013', 'exercise', 1, '{"id": "3013", "target": "glutes", "name_en": "low glute bridge on floor", "name_zh": "低位臀桥（地板）", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3013-u0cNiij.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "低位臀橋（地板）", "instructions_en": ["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your arms by your sides, palms facing down.", "Engage your glutes and core, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.", "Pause for a moment at the top, squeezing your glutes.", "Slowly lower your hips back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，膝盖弯曲，双脚平放在地上。", "将手臂放在身体两侧，手掌朝下。", "启动臀肌和核心肌群，然后将臀部抬离地面，直到身体从膝盖到肩膀形成一条直线。", "在顶部暂停片刻，挤压臀部。", "慢慢地将臀部放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "core"], "instructions_zh_hant": ["平躺，膝蓋彎曲，雙腳平放在地上。", "將手臂放在身體兩側，手掌朝下。", "啟動臀肌和核心肌群，然后將臀部抬離地面，直到身體從膝蓋到肩膀形成一條直線。", "在頂部暫停片刻，擠壓臀部。", "慢慢地將臀部放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1352', 'exercise', 1, '{"id": "1352", "target": "spine", "name_en": "lower back curl", "name_zh": "下背卷曲", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1352-ANbbry2.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "下背卷曲", "instructions_en": ["Lie flat on your stomach with your legs extended and your arms by your sides.", "Engage your glutes and hamstrings, and slowly lift your upper body off the ground, curling your back upwards.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，双腿伸直，双臂放在身体两侧。", "收紧臀肌和腿筋，慢慢将上半身抬离地面，向上弯曲背部。", "在顶部停顿片刻，然后慢慢将上半身放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings"], "instructions_zh_hant": ["平躺，雙腿伸直，雙臂放在身體兩側。", "收緊臀肌和腿筋，慢慢將上半身抬離地面，向上彎曲背部。", "在頂部停頓片刻，然后慢慢將上半身放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3582', 'exercise', 1, '{"id": "3582", "target": "glutes", "name_en": "lunge with jump", "name_zh": "弓步配合跳跃", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3582-PM1PZjg.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "弓步配合跳躍", "instructions_en": ["Start by standing with your feet shoulder-width apart.", "Take a step forward with your right foot, lowering your body into a lunge position.", "Push off with your right foot and jump into the air, switching the position of your feet mid-air.", "Land softly with your left foot forward and immediately lower your body into a lunge position.", "Continue alternating between lunges and jumps for the desired number of repetitions."], "instructions_zh": ["首先站立，双脚分开与肩同宽。", "右脚向前迈出一步，将身体降低至弓步位置。", "右脚蹬地，跳到空中，在空中改变脚的位置。", "左脚向前轻柔落地，并立即将身体降低至弓步位置。", "继续在弓步和跳跃之间交替进行所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["首先站立，雙腳分開與肩同寬。", "右腳向前邁出一步，將身體降低至弓步位置。", "右腳蹬地，跳到空中，在空中改變腳的位置。", "左腳向前輕柔落地，并立即將身體降低至弓步位置。", "繼續在弓步和跳躍之間交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0613', 'exercise', 1, '{"id": "0613", "target": "quads", "name_en": "lying (side) quads stretch", "name_zh": "卧姿（侧）股四头肌拉伸", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0613-BWnJR72.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "臥姿（側）股四頭肌拉伸", "instructions_en": ["Lie on your side with your legs straight.", "Bend your top leg and grab your ankle or foot with your hand.", "Gently pull your ankle or foot towards your glutes until you feel a stretch in your quads.", "Hold the stretch for 20-30 seconds.", "Release the stretch and repeat on the other side."], "instructions_zh": ["侧躺，双腿伸直。", "弯曲上面的那条腿，用手抓住脚踝或脚。", "轻轻地将脚踝或脚拉向臀部，直到感觉到股四头肌有拉伸感。", "保持拉伸 20-30 秒。", "松开拉伸并在另一侧重复。"], "secondary_muscles": ["hamstrings"], "instructions_zh_hant": ["側躺，雙腿伸直。", "彎曲上面的那條腿，用手抓住腳踝或腳。", "輕輕地將腳踝或腳拉向臀部，直到感覺到股四頭肌有拉伸感。", "保持拉伸 20-30 秒。", "松開拉伸并在另一側重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2312', 'exercise', 1, '{"id": "2312", "target": "abs", "name_en": "lying elbow to knee", "name_zh": "卧姿肘部至膝部", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/2312-AQIhRjM.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "臥姿肘部至膝部", "instructions_en": ["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engage your abs and lift your upper body off the ground, bringing your right elbow towards your left knee.", "At the same time, extend your right leg straight out and lift it off the ground.", "Pause for a moment, then return to the starting position.", "Repeat the movement, this time bringing your left elbow towards your right knee and extending your left leg.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["平躺，膝盖弯曲，双脚平放在地上。", "将双手放在脑后，肘部朝外。", "收紧腹肌，将上半身抬离地面，将右肘靠近左膝盖。", "同时，将右腿伸直并抬离地面。", "暂停片刻，然后回到起始位置。", "重复该动作，这次将左肘移向右膝盖并伸展左腿。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["hip flexors", "lower back"], "instructions_zh_hant": ["平躺，膝蓋彎曲，雙腳平放在地上。", "將雙手放在腦后，肘部朝外。", "收緊腹肌，將上半身抬離地面，將右肘靠近左膝蓋。", "同時，將右腿伸直并抬離地面。", "暫停片刻，然后回到起始位置。", "重復該動作，這次將左肘移向右膝蓋并伸展左腿。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0620', 'exercise', 1, '{"id": "0620", "target": "abs", "name_en": "lying leg raise flat bench", "name_zh": "平凳仰卧举腿", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0620-WhuFnR7.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "平凳仰臥舉腿", "instructions_en": ["Lie flat on a flat bench with your back pressed against it.", "Place your hands under your glutes for support.", "Keep your legs straight and together, and lift them up towards the ceiling.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在平坦的长凳上，背部紧贴长凳。", "将双手放在臀部下方以获得支撑。", "保持双腿伸直并拢，然后将它们抬向天花板。", "在顶部暂停片刻，然后慢慢将双腿放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["平躺在平坦的長凳上，背部緊貼長凳。", "將雙手放在臀部下方以獲得支撐。", "保持雙腿伸直并攏，然后將它們抬向天花板。", "在頂部暫停片刻，然后慢慢將雙腿放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0865', 'exercise', 1, '{"id": "0865", "target": "abs", "name_en": "lying leg-hip raise", "name_zh": "仰卧举腿提髋", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0865-9IxJdtC.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "仰臥舉腿提髖", "instructions_en": ["Lie flat on your back with your legs extended and your arms by your sides.", "Place your hands under your glutes for support.", "Engage your core and lift your legs off the ground, raising them towards the ceiling.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，双腿伸展，双臂放在身体两侧。", "将双手放在臀部下方以获得支撑。", "启动你的核心并将双腿抬离地面，将它们抬向天花板。", "在顶部暂停片刻，然后慢慢将双腿放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["平躺，雙腿伸展，雙臂放在身體兩側。", "將雙手放在臀部下方以獲得支撐。", "啟動你的核心并將雙腿抬離地面，將它們抬向天花板。", "在頂部暫停片刻，然后慢慢將雙腿放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1301', 'exercise', 1, '{"id": "1301", "target": "pectorals", "name_en": "machine inner chest press", "name_zh": "器械内侧推胸", "body_part": "chest", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/1301-wDN97Ca.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "器械內側推胸", "instructions_en": ["Adjust the seat height and position yourself on the machine with your back flat against the pad.", "Grasp the handles with an overhand grip and position your elbows at a 90-degree angle.", "Push the handles forward until your arms are fully extended, exhaling during the movement.", "Pause for a moment at the end of the movement, then slowly return to the starting position, inhaling as you do so.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度，将自己放在机器上，背部平放在垫子上。", "正手握住手柄，肘部呈 90 度角。", "向前推动手柄，直到手臂完全伸展，运动过程中呼气。", "动作结束时暂停片刻，然后慢慢回到起始位置，同时吸气。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["調整座椅高度，將自己放在機器上，背部平放在墊子上。", "正手握住手柄，肘部呈 90 度角。", "向前推動手柄，直到手臂完全伸展，運動過程中呼氣。", "動作結束時暫停片刻，然后慢慢回到起始位置，同時吸氣。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1353', 'exercise', 1, '{"id": "1353", "target": "lats", "name_en": "medicine ball catch and overhead throw", "name_zh": "药球接球与过顶投掷", "body_part": "back", "equipment": "medicine ball", "gif_asset": "assets/fitness/videos/1353-PsVS1QP.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "藥球接球與過頂投擲", "instructions_en": ["Stand with your feet shoulder-width apart, holding a medicine ball in both hands at chest level.", "Bend your knees slightly and engage your core.", "Lower your body into a squat position, keeping your back straight and chest up.", "Explosively extend your hips and legs, while simultaneously throwing the medicine ball overhead.", "Release the ball at the top of the movement and catch it on the way down.", "Lower your body back into the squat position and repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手握住健身球，与胸部齐平。", "稍微弯曲膝盖并启动核心。", "将身体降低至蹲姿，保持背部挺直、挺胸。", "爆发性伸展臀部和腿部，同时将药球扔过头顶。", "在动作的最高点释放球并在下降的过程中接住它。", "将身体放回蹲姿，然后重复所需的重复次数。"], "secondary_muscles": ["shoulders", "core"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手握住健身球，與胸部齊平。", "稍微彎曲膝蓋并啟動核心。", "將身體降低至蹲姿，保持背部挺直、挺胸。", "爆發性伸展臀部和腿部，同時將藥球扔過頭頂。", "在動作的最高點釋放球并在下降的過程中接住它。", "將身體放回蹲姿，然后重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1302', 'exercise', 1, '{"id": "1302", "target": "pectorals", "name_en": "medicine ball chest pass", "name_zh": "药球胸前传球", "body_part": "chest", "equipment": "medicine ball", "gif_asset": "assets/fitness/videos/1302-aDoFKrE.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "藥球胸前傳球", "instructions_en": ["Stand with your feet shoulder-width apart, holding the medicine ball at chest level.", "Extend your arms forward, pushing the medicine ball away from your chest with force.", "As you release the ball, follow through with your arms and torso, transferring your weight from your back foot to your front foot.", "Catch the ball as it rebounds off the wall or partner, and immediately repeat the movement.", "Continue for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，将健身球保持在胸部水平。", "向前伸展双臂，用力将药球推离胸部。", "当你释放球时，用你的手臂和躯干将球从后脚转移到前脚。", "当球从墙壁或伙伴身上反弹时接住球，并立即重复该动作。", "继续进行所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，將健身球保持在胸部水平。", "向前伸展雙臂，用力將藥球推離胸部。", "當你釋放球時，用你的手臂和軀幹將球從后腳轉移到前腳。", "當球從墻壁或伙伴身上反彈時接住球，并立即重復該動作。", "繼續進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1303', 'exercise', 1, '{"id": "1303", "target": "pectorals", "name_en": "medicine ball chest push from 3 point stance", "name_zh": "三点支撑药球胸前推球", "body_part": "chest", "equipment": "medicine ball", "gif_asset": "assets/fitness/videos/1303-dCJnuVq.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "三點支撐藥球胸前推球", "instructions_en": ["Start in a 3 point stance with one hand on the medicine ball and the other hand on the ground.", "Extend your legs and position your body in a straight line.", "Lower your chest towards the ground while keeping your back straight.", "Push the medicine ball away from your body, extending your arm fully.", "Return to the starting position and repeat for the desired number of repetitions."], "instructions_zh": ["以三点姿势开始，一只手放在健身球上，另一只手放在地上。", "伸展双腿并将身体摆成一条直线。", "将胸部压向地面，同时保持背部挺直。", "将药球推离身体，完全伸展手臂。", "返回起始位置并重复所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["以三點姿勢開始，一只手放在健身球上，另一只手放在地上。", "伸展雙腿并將身體擺成一條直線。", "將胸部壓向地面，同時保持背部挺直。", "將藥球推離身體，完全伸展手臂。", "返回起始位置并重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1304', 'exercise', 1, '{"id": "1304", "target": "pectorals", "name_en": "medicine ball chest push multiple response", "name_zh": "药球胸前连续反弹推球", "body_part": "chest", "equipment": "medicine ball", "gif_asset": "assets/fitness/videos/1304-7aolH9D.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "藥球胸前連續反彈推球", "instructions_en": ["Stand with your feet shoulder-width apart, holding a medicine ball at chest level.", "Extend your arms forward, pushing the medicine ball away from your chest.", "Pause for a moment, then slowly bring the medicine ball back to your chest.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，将药球举至胸部水平。", "向前伸展双臂，将药球推离胸部。", "暂停片刻，然后慢慢地将健身球放回胸前。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，將藥球舉至胸部水平。", "向前伸展雙臂，將藥球推離胸部。", "暫停片刻，然后慢慢地將健身球放回胸前。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0627', 'exercise', 1, '{"id": "0627", "target": "lats", "name_en": "mixed grip chin-up", "name_zh": "混合握反握引体向上", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0627-T8UpLkb.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "混合握反握引體向上", "instructions_en": ["Grab the pull-up bar with an underhand grip (palms facing towards you) and your hands slightly wider than shoulder-width apart.", "Hang from the bar with your arms fully extended and your feet off the ground.", "Engage your back muscles and pull your body up towards the bar, leading with your chest.", "Continue pulling until your chin is above the bar.", "Pause for a moment at the top, then slowly lower your body back down to the starting position with control.", "Repeat for the desired number of repetitions."], "instructions_zh": ["反握（手掌朝向自己）抓住引体向上杆，双手之间的距离略大于肩宽。", "悬挂在杠上，双臂完全伸展，双脚离开地面。", "调动背部肌肉，将身体拉向杠铃杆，以胸部为主导。", "继续拉，直到下巴位于杠铃上方。", "在顶部停顿片刻，然后有控制地慢慢将身体放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["反握（手掌朝向自己）抓住引體向上桿，雙手之間的距離略大于肩寬。", "懸掛在杠上，雙臂完全伸展，雙腳離開地面。", "調動背部肌肉，將身體拉向杠鈴桿，以胸部為主導。", "繼續拉，直到下巴位于杠鈴上方。", "在頂部停頓片刻，然后有控制地慢慢將身體放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1305', 'exercise', 1, '{"id": "1305", "target": "pectorals", "name_en": "medicine ball chest push single response", "name_zh": "药球胸前单次反弹推球", "body_part": "chest", "equipment": "medicine ball", "gif_asset": "assets/fitness/videos/1305-jeHtrlO.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "藥球胸前單次反彈推球", "instructions_en": ["Stand with your feet shoulder-width apart, holding the medicine ball at chest level.", "Extend your arms forward, pushing the medicine ball away from your chest.", "Pause for a moment, then slowly bring the medicine ball back to your chest.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，将健身球保持在胸部水平。", "向前伸展双臂，将药球推离胸部。", "暂停片刻，然后慢慢地将健身球放回胸前。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，將健身球保持在胸部水平。", "向前伸展雙臂，將藥球推離胸部。", "暫停片刻，然后慢慢地將健身球放回胸前。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1312', 'exercise', 1, '{"id": "1312", "target": "pectorals", "name_en": "medicine ball chest push with run release", "name_zh": "跑动药球胸前推球", "body_part": "chest", "equipment": "medicine ball", "gif_asset": "assets/fitness/videos/1312-pX9Elbe.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "跑動藥球胸前推球", "instructions_en": ["Stand with your feet shoulder-width apart, holding a medicine ball at chest level.", "Step forward with your right foot and simultaneously push the medicine ball forward, extending your arms fully.", "As you push the ball forward, release it and let it roll forward.", "Quickly run forward and catch the ball before it hits the ground.", "Once you catch the ball, bring it back to your chest and repeat the movement with your left foot forward.", "Continue alternating legs and repeating the exercise for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，将药球举至胸部水平。", "右脚向前迈出一步，同时向前推动药球，充分伸展双臂。", "当你向前推动球时，松开它并让它向前滚动。", "快速向前跑，在球落地之前接住球。", "接住球后，将其放回胸前，左脚向前重复该动作。", "继续交替双腿并重复练习达到所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders", "core"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，將藥球舉至胸部水平。", "右腳向前邁出一步，同時向前推動藥球，充分伸展雙臂。", "當你向前推動球時，松開它并讓它向前滾動。", "快速向前跑，在球落地之前接住球。", "接住球后，將其放回胸前，左腳向前重復該動作。", "繼續交替雙腿并重復練習達到所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1701', 'exercise', 1, '{"id": "1701", "target": "triceps", "name_en": "medicine ball close grip push up", "name_zh": "药球窄握俯卧撑", "body_part": "upper arms", "equipment": "medicine ball", "gif_asset": "assets/fitness/videos/1701-8K7m2SS.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "藥球窄握俯臥撐", "instructions_en": ["Start in a high plank position with your hands on the medicine ball, shoulder-width apart.", "Lower your body towards the ground by bending your elbows, keeping them close to your sides.", "Push back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["从高平板支撑位置开始，双手放在健身球上，距离与肩同宽。", "弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。", "推回起始位置，完全伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["從高平板支撐位置開始，雙手放在健身球上，距離與肩同寬。", "彎曲肘部，使肘部靠近身體兩側，將身體降低到地面。", "推回起始位置，完全伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1354', 'exercise', 1, '{"id": "1354", "target": "upper back", "name_en": "medicine ball overhead slam", "name_zh": "药球过顶砸地", "body_part": "back", "equipment": "medicine ball", "gif_asset": "assets/fitness/videos/1354-oHg8eop.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "藥球過頂砸地", "instructions_en": ["Stand with your feet shoulder-width apart, holding a medicine ball with both hands above your head.", "Engage your core and keep your back straight.", "Bend your knees slightly and forcefully slam the medicine ball down to the ground in front of you.", "As you slam the ball down, use your entire body to generate power, including your shoulders and core.", "Catch the ball on the bounce and repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手握住药球举过头顶。", "启动你的核心并保持背部挺直。", "稍微弯曲膝盖，用力将药球摔到你面前的地面上。", "当你击球时，用你的整个身体来产生力量，包括你的肩膀和核心。", "接住球的弹跳并重复所需的重复次数。"], "secondary_muscles": ["shoulders", "core"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手握住藥球舉過頭頂。", "啟動你的核心并保持背部挺直。", "稍微彎曲膝蓋，用力將藥球摔到你面前的地面上。", "當你擊球時，用你的整個身體來產生力量，包括你的肩膀和核心。", "接住球的彈跳并重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1750', 'exercise', 1, '{"id": "1750", "target": "triceps", "name_en": "medicine ball supine chest throw", "name_zh": "药球仰卧胸部投掷", "body_part": "upper arms", "equipment": "medicine ball", "gif_asset": "assets/fitness/videos/1750-Al3tP0D.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "藥球仰臥胸部投擲", "instructions_en": ["Lie flat on your back on a bench with your knees bent and feet flat on the ground.", "Hold the medicine ball with both hands, extending your arms straight up above your chest.", "Lower the medicine ball towards your chest, keeping your elbows close to your body.", "Explosively push the medicine ball upwards, extending your arms fully and throwing the ball as high as possible.", "Catch the medicine ball and repeat for the desired number of repetitions."], "instructions_zh": ["平躺在长凳上，膝盖弯曲，双脚平放在地上。", "双手握住药球，将手臂伸直至胸部上方。", "将健身球降低到胸部，保持肘部靠近身体。", "爆发性地将药球向上推，充分伸展双臂并将球扔得尽可能高。", "接住药球并重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["平躺在長凳上，膝蓋彎曲，雙腳平放在地上。", "雙手握住藥球，將手臂伸直至胸部上方。", "將健身球降低到胸部，保持肘部靠近身體。", "爆發性地將藥球向上推，充分伸展雙臂并將球扔得盡可能高。", "接住藥球并重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3217', 'exercise', 1, '{"id": "3217", "target": "pectorals", "name_en": "modified hindu push-up (male)", "name_zh": "改良式印度式俯卧撑（男性示范）", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3217-epOSYUZ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "改良式印度式俯臥撐（男性示范）", "instructions_en": ["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet hip-width apart.", "Lower your body towards the ground, bending your elbows and keeping your core engaged.", "As you lower your body, shift your weight back and lift your hips up towards the ceiling, creating an inverted V shape with your body.", "Continue to lower your body until your chest is just above the ground, then reverse the movement, pushing your hips back down and extending your arms to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["从俯卧撑位置开始，双手分开略宽于肩宽，双脚分开与臀部同宽。", "将身体向地面降低，弯曲肘部并保持核心参与。", "当你降低身体时，将你的重心向后转移，并将臀部向上抬向天花板，与你的身体形成一个倒V形。", "继续降低身体，直到胸部刚好高于地面，然后反向运动，将臀部向下推，并伸展手臂回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders", "core"], "instructions_zh_hant": ["從俯臥撐位置開始，雙手分開略寬于肩寬，雙腳分開與臀部同寬。", "將身體向地面降低，彎曲肘部并保持核心參與。", "當你降低身體時，將你的重心向后轉移，并將臀部向上抬向天花板，與你的身體形成一個倒V形。", "繼續降低身體，直到胸部剛好高于地面，然后反向運動，將臀部向下推，并伸展手臂回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1421', 'exercise', 1, '{"id": "1421", "target": "forearms", "name_en": "modified push up to lower arms", "name_zh": "跪姿俯卧撑转前臂支撑", "body_part": "lower arms", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1421-arvaszz.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "跪姿俯臥撐轉前臂支撐", "instructions_en": ["Start in a push-up position with your hands directly under your shoulders and your body in a straight line.", "Lower your body down towards the ground by bending your elbows, keeping them close to your sides.", "Once your elbows are at a 90-degree angle, lower your forearms to the ground, keeping your elbows directly under your shoulders.", "Pause for a moment, then push through your palms to lift your forearms back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["从俯卧撑位置开始，双手直接放在肩膀下方，身体呈一条直线。", "弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。", "一旦肘部成 90 度角，将前臂放低至地面，将肘部保持在肩膀正下方。", "暂停片刻，然后用手掌推动前臂，使其回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "chest", "shoulders"], "instructions_zh_hant": ["從俯臥撐位置開始，雙手直接放在肩膀下方，身體呈一條直線。", "彎曲肘部，使肘部靠近身體兩側，將身體降低到地面。", "一旦肘部成 90 度角，將前臂放低至地面，將肘部保持在肩膀正下方。", "暫停片刻，然后用手掌推動前臂，使其回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0628', 'exercise', 1, '{"id": "0628", "target": "glutes", "name_en": "monster walk", "name_zh": "怪兽步行走", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0628-O95afRA.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "怪獸步行走", "instructions_en": ["Place a resistance band around your ankles.", "Stand with your feet shoulder-width apart and slightly bend your knees.", "Take a step to the side with your right foot, maintaining tension on the resistance band.", "Follow with your left foot, stepping to the side to return to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["在脚踝周围放置一根阻力带。", "双脚分开与肩同宽站立，稍微弯曲膝盖。", "右脚向一侧迈出一步，保持阻力带的张力。", "左脚跟随，向一侧迈步以返回起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["hamstrings", "quadriceps"], "instructions_zh_hant": ["在腳踝周圍放置一根阻力帶。", "雙腳分開與肩同寬站立，稍微彎曲膝蓋。", "右腳向一側邁出一步，保持阻力帶的張力。", "左腳跟隨，向一側邁步以返回起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0634', 'exercise', 1, '{"id": "0634", "target": "abs", "name_en": "negative crunch", "name_zh": "离心卷腹", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0634-szIn2UK.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "離心卷腹", "instructions_en": ["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，膝盖弯曲，双脚平放在地上。", "将双手放在脑后，肘部朝外。", "收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。", "在顶部停顿片刻，然后慢慢将上半身放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["平躺，膝蓋彎曲，雙腳平放在地上。", "將雙手放在腦后，肘部朝外。", "收緊腹肌，慢慢將上半身抬離地面，向前卷曲，直到軀幹呈 45 度角。", "在頂部停頓片刻，然后慢慢將上半身放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0630', 'exercise', 1, '{"id": "0630", "target": "cardiovascular system", "name_en": "mountain climber", "name_zh": "登山跑", "body_part": "cardio", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0630-RJgzwny.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "登山跑", "instructions_en": ["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.", "Engage your core and bring your right knee towards your chest, then quickly switch and bring your left knee towards your chest.", "Continue alternating legs in a running motion, keeping your hips low and your core engaged.", "Maintain a steady pace and breathe evenly throughout the exercise.", "Repeat for the desired number of repetitions."], "instructions_zh": ["从高平板支撑位置开始，双手直接放在肩膀下方，身体呈一条直线。", "启动你的核心并将你的右膝盖靠近你的胸部，然后快速切换并将你的左膝盖靠近你的胸部。", "继续以跑步动作交替双腿，保持臀部较低，核心肌群参与。", "在整个练习过程中保持稳定的节奏和均匀的呼吸。", "重复所需的重复次数。"], "secondary_muscles": ["core", "shoulders", "triceps"], "instructions_zh_hant": ["從高平板支撐位置開始，雙手直接放在肩膀下方，身體呈一條直線。", "啟動你的核心并將你的右膝蓋靠近你的胸部，然后快速切換并將你的左膝蓋靠近你的胸部。", "繼續以跑步動作交替雙腿，保持臀部較低，核心肌群參與。", "在整個練習過程中保持穩定的節奏和均勻的呼吸。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0631', 'exercise', 1, '{"id": "0631", "target": "lats", "name_en": "muscle up", "name_zh": "双力臂", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0631-yJUHKTn.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "雙力臂", "instructions_en": ["Start by hanging from a pull-up bar with your palms facing away from you and your arms fully extended.", "Engage your core and pull your body up towards the bar, leading with your chest.", "As you reach the top of the movement, transition your grip so that your palms are facing towards you.", "Continue pulling yourself up until your chest is above the bar and your arms are fully flexed.", "Reverse the movement by slowly lowering yourself back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先悬挂在引体向上杆上，手掌背向自己，手臂完全伸展。", "启动核心肌群，将身体拉向杠铃杆，以胸部为主导。", "当你到达动作的最高点时，改变你的握力，使你的手掌朝向你。", "继续将自己向上拉，直到胸部位于杠铃上方并且手臂完全弯曲。", "通过慢慢降低自己回到起始位置来反转动作。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "triceps", "shoulders", "chest"], "instructions_zh_hant": ["首先懸掛在引體向上桿上，手掌背向自己，手臂完全伸展。", "啟動核心肌群，將身體拉向杠鈴桿，以胸部為主導。", "當你到達動作的最高點時，改變你的握力，使你的手掌朝向你。", "繼續將自己向上拉，直到胸部位于杠鈴上方并且手臂完全彎曲。", "通過慢慢降低自己回到起始位置來反轉動作。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1401', 'exercise', 1, '{"id": "1401", "target": "lats", "name_en": "muscle-up (on vertical bar)", "name_zh": "双力臂（于垂直杆）", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1401-Af0EW2I.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "雙力臂（于垂直桿）", "instructions_en": ["Start by hanging from a vertical bar with your palms facing away from you and your arms fully extended.", "Engage your core and pull your body up towards the bar, leading with your chest.", "As you pull yourself up, lean back slightly and bring your elbows towards your sides.", "Continue pulling until your chest reaches the bar and your elbows are fully bent.", "Pause for a moment at the top, then slowly lower yourself back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先悬挂在垂直杆上，手掌背对自己，手臂完全伸展。", "启动核心肌群，将身体拉向杠铃杆，以胸部为主导。", "当你站起来时，稍微向后倾斜，并将肘部移向身体两侧。", "继续拉，直到胸部到达杠铃并且肘部完全弯曲。", "在最高点暂停片刻，然后慢慢降低回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "triceps", "forearms"], "instructions_zh_hant": ["首先懸掛在垂直桿上，手掌背對自己，手臂完全伸展。", "啟動核心肌群，將身體拉向杠鈴桿，以胸部為主導。", "當你站起來時，稍微向后傾斜，并將肘部移向身體兩側。", "繼續拉，直到胸部到達杠鈴并且肘部完全彎曲。", "在最高點暫停片刻，然后慢慢降低回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2328', 'exercise', 1, '{"id": "2328", "target": "triceps", "name_en": "narrow push-up on exercise ball", "name_zh": "窄距俯卧撑（健身球）", "body_part": "upper arms", "equipment": "stability ball", "gif_asset": "assets/fitness/videos/2328-4cWjYEN.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "窄距俯臥撐（健身球）", "instructions_en": ["Place the stability ball on the ground and position yourself in a push-up position with your hands on the ball, slightly narrower than shoulder-width apart.", "Engage your core and keep your body in a straight line from head to toe.", "Lower your chest towards the ball by bending your elbows, keeping them close to your body.", "Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将稳定球放在地面上，将自己置于俯卧撑位置，双手放在球上，距离略窄于肩宽。", "调动你的核心力量，让你的身体从头到脚保持在一条直线上。", "弯曲肘部，使胸部靠近球，使胸部靠近球。", "在底部暂停片刻，然后伸直手臂将自己推回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["將穩定球放在地面上，將自己置于俯臥撐位置，雙手放在球上，距離略窄于肩寬。", "調動你的核心力量，讓你的身體從頭到腳保持在一條直線上。", "彎曲肘部，使胸部靠近球，使胸部靠近球。", "在底部暫停片刻，然后伸直手臂將自己推回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1495', 'exercise', 1, '{"id": "1495", "target": "abs", "name_en": "oblique crunch v. 2", "name_zh": "腹斜肌卷腹变式2", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1495-cJgSTmh.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "腹斜肌卷腹變式2", "instructions_en": ["Lie on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head or cross them over your chest.", "Engage your abs and lift your shoulder blades off the ground, rotating your torso to one side.", "Pause for a moment, then lower your shoulder blades back down to the starting position.", "Repeat on the other side.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["仰卧，膝盖弯曲，双脚平放在地上。", "将双手放在脑后或交叉放在胸前。", "收紧腹肌，将肩胛骨抬离地面，将躯干旋转到一侧。", "暂停片刻，然后将肩胛骨放回起始位置。", "在另一侧重复。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["obliques"], "instructions_zh_hant": ["仰臥，膝蓋彎曲，雙腳平放在地上。", "將雙手放在腦后或交叉放在胸前。", "收緊腹肌，將肩胛骨抬離地面，將軀幹旋轉到一側。", "暫停片刻，然后將肩胛骨放回起始位置。", "在另一側重復。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0635', 'exercise', 1, '{"id": "0635", "target": "abs", "name_en": "oblique crunches floor", "name_zh": "腹斜肌卷腹地板", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0635-QUDd8WS.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "腹斜肌卷腹地板", "instructions_en": ["Lie on your back with your knees bent and feet flat on the floor.", "Place your hands behind your head or cross them over your chest.", "Engage your abs and lift your shoulder blades off the floor, rotating your torso to one side.", "Pause for a moment, then lower your shoulder blades back down to the floor.", "Repeat on the other side, alternating sides with each repetition."], "instructions_zh": ["仰卧，膝盖弯曲，双脚平放在地板上。", "将双手放在脑后或交叉放在胸前。", "收紧腹肌，将肩胛骨抬离地面，将躯干旋转到一侧。", "暂停片刻，然后将肩胛骨放回到地板上。", "在另一侧重复，每次重复时交替进行。"], "secondary_muscles": ["obliques"], "instructions_zh_hant": ["仰臥，膝蓋彎曲，雙腳平放在地板上。", "將雙手放在腦后或交叉放在胸前。", "收緊腹肌，將肩胛骨抬離地面，將軀幹旋轉到一側。", "暫停片刻，然后將肩胛骨放回到地板上。", "在另一側重復，每次重復時交替進行。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0636', 'exercise', 1, '{"id": "0636", "target": "biceps", "name_en": "olympic barbell hammer curl", "name_zh": "奥林匹克杠铃锤式弯举", "body_part": "upper arms", "equipment": "olympic barbell", "gif_asset": "assets/fitness/videos/0636-o1ntciW.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "奧林匹克槓鈴錘式彎舉", "instructions_en": ["Stand up straight with your feet shoulder-width apart and hold an Olympic barbell with an overhand grip.", "Let the barbell hang at arm''s length in front of your thighs, with your palms facing your body.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站直，双脚分开与肩同宽，正手握住奥林匹克杠铃。", "让杠铃悬挂在大腿前面，手掌与身体保持一臂距离。", "保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。", "继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。", "挤压二头肌时，保持收缩位置短暂停顿。", "吸气并慢慢开始将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["站直，雙腳分開與肩同寬，正手握住奧林匹克杠鈴。", "讓杠鈴懸掛在大腿前面，手掌與身體保持一臂距離。", "保持上臂靜止，呼氣并彎舉啞鈴，同時收縮二頭肌。", "繼續舉起杠鈴，直到二頭肌完全收縮并且杠鈴與肩部齊平。", "擠壓二頭肌時，保持收縮位置短暫停頓。", "吸氣并慢慢開始將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0637', 'exercise', 1, '{"id": "0637", "target": "triceps", "name_en": "olympic barbell triceps extension", "name_zh": "奥林匹克杠铃臂屈伸", "body_part": "upper arms", "equipment": "olympic barbell", "gif_asset": "assets/fitness/videos/0637-wu5LXwz.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "奧林匹克槓鈴臂屈伸", "instructions_en": ["Start by standing with your feet shoulder-width apart and holding the barbell with an overhand grip.", "Raise the barbell above your head, fully extending your arms.", "Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.", "Pause for a moment, then extend your arms back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先，双脚分开与肩同宽站立，并用正手握住杠铃。", "将杠铃举过头顶，充分伸展双臂。", "保持上臂靠近头部，弯曲肘部，慢慢将杠铃降低到脑后。", "暂停片刻，然后将手臂伸回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["首先，雙腳分開與肩同寬站立，并用正手握住杠鈴。", "將杠鈴舉過頭頂，充分伸展雙臂。", "保持上臂靠近頭部，彎曲肘部，慢慢將杠鈴降低到腦后。", "暫停片刻，然后將手臂伸回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1355', 'exercise', 1, '{"id": "1355", "target": "lats", "name_en": "one arm against wall", "name_zh": "单臂扶墙拉伸", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1355-ZZTGMKh.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "單臂扶墻拉伸", "instructions_en": ["Stand facing a wall with your feet shoulder-width apart.", "Extend one arm straight out in front of you and place your palm against the wall.", "Engage your core and lean your body forward, keeping your arm straight and your back flat.", "Slowly push against the wall with your palm, activating your lat muscles.", "Hold the position for a few seconds, then release and repeat with the other arm."], "instructions_zh": ["面向墙壁站立，双脚分开与肩同宽。", "将一只手臂伸直到身前，将手掌靠在墙上。", "启动你的核心，身体向前倾斜，保持手臂伸直，背部平坦。", "用手掌慢慢推向墙壁，激活背阔肌。", "保持该姿势几秒钟，然后松开并用另一只手臂重复该动作。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["面向墻壁站立，雙腳分開與肩同寬。", "將一只手臂伸直到身前，將手掌靠在墻上。", "啟動你的核心，身體向前傾斜，保持手臂伸直，背部平坦。", "用手掌慢慢推向墻壁，激活背闊肌。", "保持該姿勢幾秒鐘，然后松開并用另一只手臂重復該動作。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0639', 'exercise', 1, '{"id": "0639", "target": "triceps", "name_en": "one arm dip", "name_zh": "单臂臂屈伸", "body_part": "upper arms", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0639-FAoIFMw.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "單臂臂屈伸", "instructions_en": ["Stand facing away from a bench or chair, with your feet shoulder-width apart.", "Place one hand on the bench or chair behind you, fingers pointing towards your body.", "Extend your legs out in front of you, keeping your heels on the ground.", "Bend your elbows and lower your body towards the ground, keeping your back close to the bench or chair.", "Pause for a moment at the bottom, then push through your palms to straighten your arms and return to the starting position.", "Repeat for the desired number of repetitions, then switch sides and repeat with the other arm."], "instructions_zh": ["背对长凳或椅子站立，双脚分开与肩同宽。", "将一只手放在身后的长凳或椅子上，手指指向您的身体。", "将双腿向前方伸展，脚跟保持在地面上。", "弯曲肘部，将身体放低至地面，使背部靠近长凳或椅子。", "在底部停顿片刻，然后用手掌推直手臂，回到起始位置。", "重复所需的重复次数，然后换边并用另一只手臂重复。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["背對長凳或椅子站立，雙腳分開與肩同寬。", "將一只手放在身后的長凳或椅子上，手指指向您的身體。", "將雙腿向前方伸展，腳跟保持在地面上。", "彎曲肘部，將身體放低至地面，使背部靠近長凳或椅子。", "在底部停頓片刻，然后用手掌推直手臂，回到起始位置。", "重復所需的重復次數，然后換邊并用另一只手臂重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1773', 'exercise', 1, '{"id": "1773", "target": "upper back", "name_en": "one arm towel row", "name_zh": "单臂毛巾划船", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1773-bKWbrTA.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "單臂毛巾劃船", "instructions_en": ["Stand with your feet shoulder-width apart, knees slightly bent, and hold a towel with one hand.", "Bend forward at the waist, keeping your back straight and your core engaged.", "Extend your arm fully, allowing the towel to hang in front of you.", "Pull the towel towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the towel back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."], "instructions_zh": ["双脚分开与肩同宽站立，膝盖微曲，单手握住毛巾。", "腰部向前弯曲，保持背部挺直，核心肌群参与。", "完全伸展手臂，让毛巾挂在您面前。", "将毛巾拉向胸部，将肩胛骨挤压在一起。", "在顶部停顿片刻，然后慢慢将毛巾放回起始位置。", "重复所需的重复次数，然后换臂。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，膝蓋微曲，單手握住毛巾。", "腰部向前彎曲，保持背部挺直，核心肌群參與。", "完全伸展手臂，讓毛巾掛在您面前。", "將毛巾拉向胸部，將肩胛骨擠壓在一起。", "在頂部停頓片刻，然后慢慢將毛巾放回起始位置。", "重復所需的重復次數，然后換臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1386', 'exercise', 1, '{"id": "1386", "target": "calves", "name_en": "one leg donkey calf raise", "name_zh": "单腿驴式提踵", "body_part": "lower legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1386-A2upspL.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "單腿驢式提踵", "instructions_en": ["Stand with your feet shoulder-width apart, toes pointing forward.", "Place your hands on a stable surface for support, such as a wall or a bar.", "Lift one leg off the ground, keeping your knee slightly bent.", "Raise your heel as high as possible, using your calf muscles.", "Pause for a moment at the top, then slowly lower your heel back down.", "Repeat for the desired number of repetitions, then switch legs."], "instructions_zh": ["双脚分开与肩同宽站立，脚趾指向前方。", "将双手放在稳定的表面上以获得支撑，例如墙壁或酒吧。", "将一条腿抬离地面，保持膝盖稍微弯曲。", "使用小腿肌肉，尽可能高地抬高脚跟。", "在顶部停顿片刻，然后慢慢降低脚跟。", "重复所需的重复次数，然后换腿。"], "secondary_muscles": ["hamstrings", "glutes"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，腳趾指向前方。", "將雙手放在穩定的表面上以獲得支撐，例如墻壁或酒吧。", "將一條腿抬離地面，保持膝蓋稍微彎曲。", "使用小腿肌肉，盡可能高地抬高腳跟。", "在頂部停頓片刻，然后慢慢降低腳跟。", "重復所需的重復次數，然后換腿。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1387', 'exercise', 1, '{"id": "1387", "target": "calves", "name_en": "one leg floor calf raise", "name_zh": "单腿地板提踵", "body_part": "lower legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1387-0jp9Rlz.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "單腿地板提踵", "instructions_en": ["Stand with your feet hip-width apart and place your hands on a wall or sturdy object for balance.", "Lift one foot off the ground and balance on the other foot.", "Slowly raise your heel off the ground, lifting your body up onto the ball of your foot.", "Pause for a moment at the top, then slowly lower your heel back down to the starting position.", "Repeat for the desired number of repetitions, then switch legs and repeat."], "instructions_zh": ["双脚分开与臀部同宽站立，双手放在墙壁或坚固的物体上以保持平衡。", "将一只脚抬离地面并用另一只脚保持平衡。", "慢慢地将脚跟抬离地面，将身体抬起到脚掌上。", "在顶部暂停片刻，然后慢慢将脚跟放回起始位置。", "重复所需的重复次数，然后换腿并重复。"], "secondary_muscles": ["ankles", "feet"], "instructions_zh_hant": ["雙腳分開與臀部同寬站立，雙手放在墻壁或堅固的物體上以保持平衡。", "將一只腳抬離地面并用另一只腳保持平衡。", "慢慢地將腳跟抬離地面，將身體抬起到腳掌上。", "在頂部暫停片刻，然后慢慢將腳跟放回起始位置。", "重復所需的重復次數，然后換腿并重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0641', 'exercise', 1, '{"id": "0641", "target": "abs", "name_en": "otis up", "name_zh": "奥蒂斯负重仰卧起坐", "body_part": "waist", "equipment": "weighted", "gif_asset": "assets/fitness/videos/0641-UVL20oz.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "奧蒂斯負重仰臥起坐", "instructions_en": ["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，膝盖弯曲，双脚平放在地上。", "将双手放在脑后，肘部朝外。", "收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。", "在顶部停顿片刻，然后慢慢将上半身放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors", "lower back"], "instructions_zh_hant": ["平躺，膝蓋彎曲，雙腳平放在地上。", "將雙手放在腦后，肘部朝外。", "收緊腹肌，慢慢將上半身抬離地面，向前卷曲，直到軀幹呈 45 度角。", "在頂部停頓片刻，然后慢慢將上半身放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0642', 'exercise', 1, '{"id": "0642", "target": "glutes", "name_en": "outside leg kick push-up", "name_zh": "外侧踢腿俯卧撑", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0642-jNU1gFQ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "外側踢腿俯臥撐", "instructions_en": ["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.", "Lower your body towards the ground by bending your elbows, keeping your back straight and core engaged.", "As you push back up, kick one leg out to the side, extending it fully and engaging your glutes.", "Return your leg to the starting position and repeat the push-up, alternating legs with each repetition.", "Continue alternating leg kicks and push-ups for the desired number of repetitions."], "instructions_zh": ["从俯卧撑位置开始，双手分开略宽于肩宽，双脚并拢。", "弯曲肘部，将身体降低到地面，保持背部挺直，核心参与。", "当你向后推时，将一条腿踢向一侧，完全伸展并启动臀部。", "将腿恢复到起始位置并重复俯卧撑，每次重复时交替腿。", "继续交替踢腿和俯卧撑，达到所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["從俯臥撐位置開始，雙手分開略寬于肩寬，雙腳并攏。", "彎曲肘部，將身體降低到地面，保持背部挺直，核心參與。", "當你向后推時，將一條腿踢向一側，完全伸展并啟動臀部。", "將腿恢復到起始位置并重復俯臥撐，每次重復時交替腿。", "繼續交替踢腿和俯臥撐，達到所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0643', 'exercise', 1, '{"id": "0643", "target": "triceps", "name_en": "overhead triceps stretch", "name_zh": "过顶肱三头肌拉伸", "body_part": "upper arms", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0643-Z5YStHW.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "過頂肱三頭肌拉伸", "instructions_en": ["Stand or sit upright with your feet shoulder-width apart.", "Extend one arm overhead, bending at the elbow so that your hand reaches towards the opposite shoulder blade.", "With your other hand, gently pull the elbow of the extended arm towards the opposite side of your head, feeling a stretch in your triceps.", "Hold the stretch for 15-30 seconds, then release.", "Repeat on the other side."], "instructions_zh": ["站立或坐直，双脚分开与肩同宽。", "将一只手臂伸过头顶，弯曲肘部，使手伸向对面的肩胛骨。", "用另一只手轻轻地将伸出的手臂的肘部拉向头部的另一侧，感受三头肌的拉伸。", "保持拉伸 15-30 秒，然后放松。", "在另一侧重复。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["站立或坐直，雙腳分開與肩同寬。", "將一只手臂伸過頭頂，彎曲肘部，使手伸向對面的肩胛骨。", "用另一只手輕輕地將伸出的手臂的肘部拉向頭部的另一側，感受三頭肌的拉伸。", "保持拉伸 15-30 秒，然后放松。", "在另一側重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3147', 'exercise', 1, '{"id": "3147", "target": "abs", "name_en": "pelvic tilt", "name_zh": "骨盆倾斜", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3147-NKJ8o6x.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "骨盆傾斜", "instructions_en": ["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands by your sides.", "Engage your abs and tilt your pelvis upward, pressing your lower back into the ground.", "Hold this position for a few seconds, focusing on contracting your abs.", "Release the tilt and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，膝盖弯曲，双脚平放在地上。", "将双手放在身体两侧。", "收紧腹肌，向上倾斜骨盆，将下背部压入地面。", "保持这个姿势几秒钟，专注于收缩腹肌。", "释放倾斜并返回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["lower back"], "instructions_zh_hant": ["平躺，膝蓋彎曲，雙腳平放在地上。", "將雙手放在身體兩側。", "收緊腹肌，向上傾斜骨盆，將下背部壓入地面。", "保持這個姿勢幾秒鐘，專注于收縮腹肌。", "釋放傾斜并返回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1422', 'exercise', 1, '{"id": "1422", "target": "glutes", "name_en": "pelvic tilt into bridge", "name_zh": "骨盆倾斜进入桥式", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1422-D9qe7CM.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "骨盆傾斜進入橋式", "instructions_en": ["Lie on your back with your knees bent and feet flat on the ground.", "Place your arms by your sides with your palms facing down.", "Engage your glutes and core muscles.", "Tilt your pelvis upward, lifting your hips off the ground.", "Hold the bridge position for a few seconds.", "Slowly lower your hips back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["仰卧，膝盖弯曲，双脚平放在地上。", "将手臂放在身体两侧，手掌朝下。", "调动你的臀肌和核心肌肉。", "向上倾斜骨盆，将臀部抬离地面。", "保持桥位置几秒钟。", "慢慢地将臀部放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "core"], "instructions_zh_hant": ["仰臥，膝蓋彎曲，雙腳平放在地上。", "將手臂放在身體兩側，手掌朝下。", "調動你的臀肌和核心肌肉。", "向上傾斜骨盆，將臀部抬離地面。", "保持橋位置幾秒鐘。", "慢慢地將臀部放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1388', 'exercise', 1, '{"id": "1388", "target": "calves", "name_en": "peroneals stretch", "name_zh": "腓骨肌拉伸", "body_part": "lower legs", "equipment": "rope", "gif_asset": "assets/fitness/videos/1388-XhfS1DZ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "腓骨肌拉伸", "instructions_en": ["Sit on the ground with your legs extended in front of you.", "Loop the rope around the ball of your foot and hold the ends of the rope with your hands.", "Gently pull the rope towards you, flexing your foot and stretching your calf muscles.", "Hold the stretch for 15-30 seconds.", "Release the tension on the rope and repeat the stretch on the other leg.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在地上，双腿在身前伸展。", "将绳子绕在脚掌上，并用手握住绳子的末端。", "轻轻地将绳子拉向自己，弯曲脚并伸展小腿肌肉。", "保持拉伸 15-30 秒。", "释放绳子上的张力，然后在另一条腿上重复拉伸。", "重复所需的重复次数。"], "secondary_muscles": ["ankles", "feet"], "instructions_zh_hant": ["坐在地上，雙腿在身前伸展。", "將繩子繞在腳掌上，并用手握住繩子的末端。", "輕輕地將繩子拉向自己，彎曲腳并伸展小腿肌肉。", "保持拉伸 15-30 秒。", "釋放繩子上的張力，然后在另一條腿上重復拉伸。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3201', 'exercise', 1, '{"id": "3201", "target": "abs", "name_en": "quarter sit-up", "name_zh": "四分之一程仰卧起坐", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3201-enxnJcM.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "四分之一程仰臥起坐", "instructions_en": ["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，膝盖弯曲，双脚平放在地上。", "将双手放在脑后，肘部朝外。", "收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。", "在顶部停顿片刻，然后慢慢将上半身放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["平躺，膝蓋彎曲，雙腳平放在地上。", "將雙手放在腦后，肘部朝外。", "收緊腹肌，慢慢將上半身抬離地面，向前卷曲，直到軀幹呈 45 度角。", "在頂部停頓片刻，然后慢慢將上半身放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3662', 'exercise', 1, '{"id": "3662", "target": "glutes", "name_en": "pike-to-cobra push-up", "name_zh": "折髋至眼镜蛇式俯卧撑", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3662-XPUDTt7.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "折髖至眼鏡蛇式俯臥撐", "instructions_en": ["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.", "Engage your core and lift your hips up towards the ceiling, forming an inverted V shape with your body.", "Lower your upper body towards the ground by bending your elbows, keeping them close to your body.", "As you lower down, shift your weight forward and transition into a cobra pose by straightening your arms and lifting your chest up.", "Reverse the movement by bending your elbows and lowering your chest back down towards the ground.", "Push through your hands to return to the inverted V position.", "Continue the movement by lowering your hips back down towards the ground, returning to the starting push-up position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["从俯卧撑位置开始，双手分开略宽于肩宽，双脚并拢。", "收紧核心肌群，将臀部抬向天花板，与身体形成倒V字形。", "弯曲肘部，使上半身靠近地面，使上半身靠近地面。", "当你下降时，将你的重心向前移动，并通过伸直手臂并抬起胸部来过渡到眼镜蛇姿势。", "通过弯曲肘部并将胸部放回到地面来扭转运动。", "双手用力推回到倒V字形。", "通过将臀部放回地面继续运动，回到起始俯卧撑位置。", "重复所需的重复次数。"], "secondary_muscles": ["core", "shoulders", "triceps"], "instructions_zh_hant": ["從俯臥撐位置開始，雙手分開略寬于肩寬，雙腳并攏。", "收緊核心肌群，將臀部抬向天花板，與身體形成倒V字形。", "彎曲肘部，使上半身靠近地面，使上半身靠近地面。", "當你下降時，將你的重心向前移動，并通過伸直手臂并抬起胸部來過渡到眼鏡蛇姿勢。", "通過彎曲肘部并將胸部放回到地面來扭轉運動。", "雙手用力推回到倒V字形。", "通過將臀部放回地面繼續運動，回到起始俯臥撐位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1306', 'exercise', 1, '{"id": "1306", "target": "pectorals", "name_en": "plyo push up", "name_zh": "爆发式俯卧撑", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1306-Snj1wSv.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "爆發式俯臥撐", "instructions_en": ["Start in a high plank position with your hands slightly wider than shoulder-width apart.", "Lower your chest towards the ground by bending your elbows, keeping your body in a straight line.", "Push explosively off the ground, using your chest muscles to propel your upper body off the ground.", "Land softly with your hands back in the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["从高平板支撑位置开始，双手分开略宽于肩宽。", "弯曲肘部，将胸部压向地面，保持身体呈一条直线。", "爆发性地推离地面，利用胸部肌肉将上半身推离地面。", "双手回到起始位置，轻轻落地。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders", "core"], "instructions_zh_hant": ["從高平板支撐位置開始，雙手分開略寬于肩寬。", "彎曲肘部，將胸部壓向地面，保持身體呈一條直線。", "爆發性地推離地面，利用胸部肌肉將上半身推離地面。", "雙手回到起始位置，輕輕落地。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1687', 'exercise', 1, '{"id": "1687", "target": "abs", "name_en": "posterior step to overhead reach", "name_zh": "后撤步接过顶伸展", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1687-ErqK3UL.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "后撤步接過頂伸展", "instructions_en": ["Stand with your feet hip-width apart and your arms by your sides.", "Take a step back with your right foot, landing on the ball of your foot.", "Bend your left knee and lower your body into a lunge position.", "As you lower into the lunge, simultaneously reach your arms overhead.", "Pause for a moment at the bottom of the lunge, then return to the starting position by pushing through your left heel and bringing your right foot forward.", "Repeat the movement on the other side, stepping back with your left foot and bending your right knee.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["站立，双脚分开与臀部同宽，双臂放在身体两侧。", "右脚向后退一步，用脚掌着地。", "弯曲左膝并将身体降低至弓步位置。", "当你降低弓步时，同时将手臂举过头顶。", "在弓步底部暂停片刻，然后通过推动左脚跟并将右脚向前拉回到起始位置。", "在另一侧重复该动作，左脚向后退一步并弯曲右膝盖。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings", "quadriceps", "shoulders"], "instructions_zh_hant": ["站立，雙腳分開與臀部同寬，雙臂放在身體兩側。", "右腳向后退一步，用腳掌著地。", "彎曲左膝并將身體降低至弓步位置。", "當你降低弓步時，同時將手臂舉過頭頂。", "在弓步底部暫停片刻，然后通過推動左腳跟并將右腳向前拉回到起始位置。", "在另一側重復該動作，左腳向后退一步并彎曲右膝蓋。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1389', 'exercise', 1, '{"id": "1389", "target": "calves", "name_en": "posterior tibialis stretch", "name_zh": "后侧胫骨肌拉伸", "body_part": "lower legs", "equipment": "rope", "gif_asset": "assets/fitness/videos/1389-DEEqoI2.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "后側脛骨肌拉伸", "instructions_en": ["Sit on the ground with your legs extended in front of you.", "Loop the rope around the ball of your foot and hold the ends of the rope with your hands.", "Gently pull the rope towards you, flexing your foot and stretching your calf muscles.", "Hold the stretch for 20-30 seconds.", "Release the tension on the rope and relax your foot.", "Repeat the stretch on the other leg."], "instructions_zh": ["坐在地上，双腿在身前伸展。", "将绳子绕在脚掌上，并用手握住绳子的末端。", "轻轻地将绳子拉向自己，弯曲脚并伸展小腿肌肉。", "保持拉伸 20-30 秒。", "释放绳子上的张力并放松脚。", "在另一条腿上重复该拉伸动作。"], "secondary_muscles": ["hamstrings", "quadriceps"], "instructions_zh_hant": ["坐在地上，雙腿在身前伸展。", "將繩子繞在腳掌上，并用手握住繩子的末端。", "輕輕地將繩子拉向自己，彎曲腳并伸展小腿肌肉。", "保持拉伸 20-30 秒。", "釋放繩子上的張力并放松腳。", "在另一條腿上重復該拉伸動作。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3119', 'exercise', 1, '{"id": "3119", "target": "abs", "name_en": "potty squat", "name_zh": "蹲坐式深蹲", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3119-75Bgtjy.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "蹲坐式深蹲", "instructions_en": ["Stand with your feet shoulder-width apart, toes pointing slightly outward.", "Lower your body down by bending your knees and pushing your hips back as if you were sitting on a chair.", "Keep your chest up and your back straight throughout the movement.", "Lower yourself until your thighs are parallel to the ground or as low as you can comfortably go.", "Pause for a moment at the bottom, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，脚趾稍微向外。", "弯曲膝盖并将臀部向后推，降低身体，就像坐在椅子上一样。", "在整个动作过程中保持挺胸、背部挺直。", "降低自己，直到大腿与地面平行或尽可能低。", "在底部停顿片刻，然后推动脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "glutes"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，腳趾稍微向外。", "彎曲膝蓋并將臀部向后推，降低身體，就像坐在椅子上一樣。", "在整個動作過程中保持挺胸、背部挺直。", "降低自己，直到大腿與地面平行或盡可能低。", "在底部停頓片刻，然后推動腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3132', 'exercise', 1, '{"id": "3132", "target": "glutes", "name_en": "potty squat with support", "name_zh": "蹲坐式深蹲配合支撑", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3132-b63ZzGe.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "蹲坐式深蹲配合支撐", "instructions_en": ["Stand with your feet shoulder-width apart, toes pointing slightly outward.", "Hold onto a stable support, such as a chair or wall, for balance.", "Lower your body down into a squat position by bending your knees and pushing your hips back.", "Keep your chest up and your back straight throughout the movement.", "Pause for a moment at the bottom, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，脚趾稍微向外。", "抓住稳定的支撑物，例如椅子或墙壁，以保持平衡。", "弯曲膝盖并将臀部向后推，将身体降低至蹲姿。", "在整个动作过程中保持挺胸、背部挺直。", "在底部停顿片刻，然后推动脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，腳趾稍微向外。", "抓住穩定的支撐物，例如椅子或墻壁，以保持平衡。", "彎曲膝蓋并將臀部向后推，將身體降低至蹲姿。", "在整個動作過程中保持挺胸、背部挺直。", "在底部停頓片刻，然后推動腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0648', 'exercise', 1, '{"id": "0648", "target": "hamstrings", "name_en": "power clean", "name_zh": "爆发式翻举", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0648-SiWCcTN.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "爆發式翻舉", "instructions_en": ["Start with the barbell on the ground in front of you, with your feet shoulder-width apart.", "Bend down and grip the barbell with an overhand grip, slightly wider than shoulder-width apart.", "Keep your back straight and chest up as you lift the barbell off the ground, extending your hips and knees.", "As the barbell reaches your mid-thigh, explosively pull it upwards, shrugging your shoulders and pulling your elbows high and to the sides.", "As the barbell reaches its highest point, quickly drop underneath it, rotating your elbows around and catching the barbell on your shoulders in a front squat position.", "Stand up with the barbell, fully extending your hips and knees.", "Lower the barbell back down to the starting position, keeping control of the weight throughout the movement.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先将杠铃放在你面前的地面上，双脚分开与肩同宽。", "弯腰，正手握住杠铃，握距略宽于肩宽。", "将杠铃提离地面时，保持背部挺直，挺胸，伸展臀部和膝盖。", "当杠铃到达大腿中部时，爆发性地将其向上拉，耸肩并将肘部拉高并向两侧拉。", "当杠铃到达最高点时，迅速下降到其下方，旋转肘部，以前蹲姿势将杠铃接在肩膀上。", "握住杠铃站起来，充分伸展臀部和膝盖。", "将杠铃放回起始位置，在整个运动过程中保持对重量的控制。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "quadriceps", "calves"], "instructions_zh_hant": ["首先將杠鈴放在你面前的地面上，雙腳分開與肩同寬。", "彎腰，正手握住杠鈴，握距略寬于肩寬。", "將杠鈴提離地面時，保持背部挺直，挺胸，伸展臀部和膝蓋。", "當杠鈴到達大腿中部時，爆發性地將其向上拉，聳肩并將肘部拉高并向兩側拉。", "當杠鈴到達最高點時，迅速下降到其下方，旋轉肘部，以前蹲姿勢將杠鈴接在肩膀上。", "握住杠鈴站起來，充分伸展臀部和膝蓋。", "將杠鈴放回起始位置，在整個運動過程中保持對重量的控制。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3203', 'exercise', 1, '{"id": "3203", "target": "abs", "name_en": "prisoner half sit-up (male)", "name_zh": "抱头式半程仰卧起坐（男性示范）", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3203-mgejmGP.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "抱頭式半程仰臥起坐（男性示范）", "instructions_en": ["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，膝盖弯曲，双脚平放在地上。", "将双手放在脑后，肘部朝外。", "收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。", "在顶部停顿片刻，然后慢慢将上半身放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["平躺，膝蓋彎曲，雙腳平放在地上。", "將雙手放在腦后，肘部朝外。", "收緊腹肌，慢慢將上半身抬離地面，向前卷曲，直到軀幹呈 45 度角。", "在頂部停頓片刻，然后慢慢將上半身放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0651', 'exercise', 1, '{"id": "0651", "target": "lats", "name_en": "pull up (neutral grip)", "name_zh": "引体向上（中立握）", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0651-0V2YQjW.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "引體向上（中立握）", "instructions_en": ["Hang from a pull-up bar with a neutral grip (palms facing each other) and your arms fully extended.", "Engage your core and squeeze your shoulder blades together.", "Pull your body up towards the bar by bending your elbows and driving your elbows down towards your hips.", "Continue pulling until your chin is above the bar.", "Pause for a moment at the top, then slowly lower your body back down to the starting position with control.", "Repeat for the desired number of repetitions."], "instructions_zh": ["用中立握法（手掌相对）悬挂在引体向上杆上，双臂完全伸展。", "启动你的核心并将肩胛骨挤压在一起。", "弯曲肘部并将肘部向下推向臀部，将身体向上拉向杠铃。", "继续拉，直到下巴位于杠铃上方。", "在顶部停顿片刻，然后有控制地慢慢将身体放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["用中立握法（手掌相對）懸掛在引體向上桿上，雙臂完全伸展。", "啟動你的核心并將肩胛骨擠壓在一起。", "彎曲肘部并將肘部向下推向臀部，將身體向上拉向杠鈴。", "繼續拉，直到下巴位于杠鈴上方。", "在頂部停頓片刻，然后有控制地慢慢將身體放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0650', 'exercise', 1, '{"id": "0650", "target": "abs", "name_en": "pull-in (on stability ball)", "name_zh": "收腿（健身球）", "body_part": "waist", "equipment": "stability ball", "gif_asset": "assets/fitness/videos/0650-UQr48Oi.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "收腿（健身球）", "instructions_en": ["Start by sitting on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.", "Place your hands on the sides of the stability ball for support.", "Engage your abs and slowly roll your hips forward, bringing your knees towards your chest.", "Pause for a moment at the top of the movement, then slowly extend your legs back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。", "将双手放在稳定球的两侧以获得支撑。", "收紧腹肌，慢慢向前滚动臀部，使膝盖靠近胸部。", "在动作的最高点停顿片刻，然后慢慢将双腿伸展回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["首先坐在穩定球上，雙腳平放在地面上，膝蓋彎曲成 90 度角。", "將雙手放在穩定球的兩側以獲得支撐。", "收緊腹肌，慢慢向前滾動臀部，使膝蓋靠近胸部。", "在動作的最高點停頓片刻，然后慢慢將雙腿伸展回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1689', 'exercise', 1, '{"id": "1689", "target": "pectorals", "name_en": "push and pull bodyweight", "name_zh": "自重推拉组合", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1689-wXvUZC8.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "自重推拉組合", "instructions_en": ["Start in a push-up position with your hands slightly wider than shoulder-width apart and your body in a straight line.", "Lower your chest towards the ground by bending your elbows, keeping your body straight.", "Push through your palms to extend your arms and return to the starting position.", "From the push-up position, pull your chest towards the ground by bending your elbows, keeping your body straight.", "Push through your palms to extend your arms and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["从俯卧撑位置开始，双手分开略宽于肩宽，身体呈一条直线。", "弯曲肘部，将胸部压向地面，保持身体伸直。", "推动手掌以伸展手臂并返回到起始位置。", "从俯卧撑位置开始，弯曲肘部，将胸部拉向地面，保持身体伸直。", "推动手掌以伸展手臂并返回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "deltoids"], "instructions_zh_hant": ["從俯臥撐位置開始，雙手分開略寬于肩寬，身體呈一條直線。", "彎曲肘部，將胸部壓向地面，保持身體伸直。", "推動手掌以伸展手臂并返回到起始位置。", "從俯臥撐位置開始，彎曲肘部，將胸部拉向地面，保持身體伸直。", "推動手掌以伸展手臂并返回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3638', 'exercise', 1, '{"id": "3638", "target": "cardiovascular system", "name_en": "push to run", "name_zh": "俯撑起跑", "body_part": "cardio", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3638-PrQbjvB.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "俯撐起跑", "instructions_en": ["Start in a push-up position with your hands shoulder-width apart and your body in a straight line.", "Lower your chest towards the ground by bending your elbows, keeping your body straight.", "Push through your hands to extend your arms and return to the starting position.", "Quickly bring one knee towards your chest, then quickly switch and bring the other knee towards your chest.", "Continue alternating knees as fast as you can while maintaining good form.", "Continue for the desired duration or number of repetitions."], "instructions_zh": ["从俯卧撑位置开始，双手分开与肩同宽，身体呈一条直线。", "弯曲肘部，将胸部压向地面，保持身体伸直。", "用手推动以伸展手臂并返回到起始位置。", "快速将一个膝盖靠近胸部，然后快速切换并将另一只膝盖靠近胸部。", "继续尽可能快地交替膝盖，同时保持良好的姿势。", "继续所需的持续时间或重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["從俯臥撐位置開始，雙手分開與肩同寬，身體呈一條直線。", "彎曲肘部，將胸部壓向地面，保持身體伸直。", "用手推動以伸展手臂并返回到起始位置。", "快速將一個膝蓋靠近胸部，然后快速切換并將另一只膝蓋靠近胸部。", "繼續盡可能快地交替膝蓋，同時保持良好的姿勢。", "繼續所需的持續時間或重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1307', 'exercise', 1, '{"id": "1307", "target": "pectorals", "name_en": "push up on bosu ball", "name_zh": "俯卧撑于波速球", "body_part": "chest", "equipment": "bosu ball", "gif_asset": "assets/fitness/videos/1307-wVompEp.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "俯臥撐于波速球", "instructions_en": ["Place the bosu ball on the ground with the flat side facing up.", "Position yourself in a push-up position with your hands on the outer edges of the bosu ball.", "Engage your core and lower your body down towards the bosu ball by bending your elbows.", "Push yourself back up to the starting position by extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将博苏球平放在地上，平面朝上。", "将自己置于俯卧撑位置，双手放在博苏球的外边缘。", "弯曲肘部，调动核心力量，将身体向博苏球方向降低。", "伸展双臂，将自己推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders", "core"], "instructions_zh_hant": ["將博蘇球平放在地上，平面朝上。", "將自己置于俯臥撐位置，雙手放在博蘇球的外邊緣。", "彎曲肘部，調動核心力量，將身體向博蘇球方向降低。", "伸展雙臂，將自己推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0653', 'exercise', 1, '{"id": "0653", "target": "pectorals", "name_en": "push-up (bosu ball)", "name_zh": "俯卧撑（波速球）", "body_part": "chest", "equipment": "bosu ball", "gif_asset": "assets/fitness/videos/0653-2kr2lWy.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "俯臥撐（波速球）", "instructions_en": ["Place the bosu ball on the ground with the flat side facing up.", "Position yourself in a push-up position with your hands on the outer edges of the bosu ball.", "Engage your core and lower your body down towards the bosu ball by bending your elbows.", "Push yourself back up to the starting position by extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将博苏球平放在地上，平面朝上。", "将自己置于俯卧撑位置，双手放在博苏球的外边缘。", "弯曲肘部，调动核心力量，将身体向博苏球方向降低。", "伸展双臂，将自己推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders", "core"], "instructions_zh_hant": ["將博蘇球平放在地上，平面朝上。", "將自己置于俯臥撐位置，雙手放在博蘇球的外邊緣。", "彎曲肘部，調動核心力量，將身體向博蘇球方向降低。", "伸展雙臂，將自己推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0655', 'exercise', 1, '{"id": "0655", "target": "pectorals", "name_en": "push-up (on stability ball)", "name_zh": "俯卧撑（健身球）", "body_part": "chest", "equipment": "stability ball", "gif_asset": "assets/fitness/videos/0655-Y4BRNQF.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "俯臥撐（健身球）", "instructions_en": ["Place the stability ball on the ground and position yourself facing down with your hands on the ball, shoulder-width apart.", "Extend your legs straight out behind you, balancing on your toes.", "Engage your core and lower your chest towards the ball by bending your elbows, keeping your body in a straight line.", "Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将稳定球放在地上，面朝下，双手放在球上，与肩同宽。", "将双腿伸直在身后，用脚趾保持平衡。", "弯曲肘部，调动核心力量，将胸部向球方向降低，保持身体呈一条直线。", "在底部暂停片刻，然后伸直手臂将自己推回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders", "core"], "instructions_zh_hant": ["將穩定球放在地上，面朝下，雙手放在球上，與肩同寬。", "將雙腿伸直在身后，用腳趾保持平衡。", "彎曲肘部，調動核心力量，將胸部向球方向降低，保持身體呈一條直線。", "在底部暫停片刻，然后伸直手臂將自己推回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0656', 'exercise', 1, '{"id": "0656", "target": "pectorals", "name_en": "push-up (on stability ball)", "name_zh": "俯卧撑（健身球）", "body_part": "chest", "equipment": "stability ball", "gif_asset": "assets/fitness/videos/0656-tgryw5Y.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "俯臥撐（健身球）", "instructions_en": ["Place the stability ball on the ground and position yourself facing down with your hands on the ball, shoulder-width apart.", "Extend your legs straight out behind you, balancing on your toes.", "Engage your core and lower your chest towards the ball by bending your elbows, keeping your body in a straight line.", "Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将稳定球放在地上，面朝下，双手放在球上，与肩同宽。", "将双腿伸直在身后，用脚趾保持平衡。", "弯曲肘部，调动核心力量，将胸部向球方向降低，保持身体呈一条直线。", "在底部暂停片刻，然后伸直手臂将自己推回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders", "core"], "instructions_zh_hant": ["將穩定球放在地上，面朝下，雙手放在球上，與肩同寬。", "將雙腿伸直在身后，用腳趾保持平衡。", "彎曲肘部，調動核心力量，將胸部向球方向降低，保持身體呈一條直線。", "在底部暫停片刻，然后伸直手臂將自己推回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0659', 'exercise', 1, '{"id": "0659", "target": "pectorals", "name_en": "push-up (wall)", "name_zh": "俯卧撑（靠墙）", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0659-LEH9jxP.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "俯臥撐（靠墻）", "instructions_en": ["Stand facing a wall, about arm''s length away.", "Place your hands on the wall at shoulder height, slightly wider than shoulder-width apart.", "Step back a few feet, keeping your body straight and your feet hip-width apart.", "Bend your elbows and lower your chest towards the wall, keeping your body in a straight line.", "Push back up to the starting position, straightening your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["面向墙壁站立，距离大约一臂距离。", "将双手放在墙上，与肩同高，距离略宽于肩宽。", "后退几英尺，保持身体挺直，双脚分开与臀部同宽。", "弯曲肘部，将胸部向墙壁降低，保持身体呈一条直线。", "推回起始位置，伸直手臂。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "deltoids"], "instructions_zh_hant": ["面向墻壁站立，距離大約一臂距離。", "將雙手放在墻上，與肩同高，距離略寬于肩寬。", "后退幾英尺，保持身體挺直，雙腳分開與臀部同寬。", "彎曲肘部，將胸部向墻壁降低，保持身體呈一條直線。", "推回起始位置，伸直手臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0658', 'exercise', 1, '{"id": "0658", "target": "pectorals", "name_en": "push-up (wall) v. 2", "name_zh": "俯卧撑（靠墙）变式2", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0658-NCmbLCw.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "俯臥撐（靠墻）變式2", "instructions_en": ["Stand facing a wall, about arm''s length away.", "Place your hands on the wall at shoulder height, slightly wider than shoulder-width apart.", "Step back with your feet, keeping them hip-width apart.", "Engage your core and keep your body in a straight line from head to heels.", "Bend your elbows and lower your chest towards the wall, keeping your body straight.", "Pause for a moment, then push yourself back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["面向墙壁站立，距离大约一臂距离。", "将双手放在墙上，与肩同高，距离略宽于肩宽。", "双脚向后退一步，保持与臀部同宽。", "收紧核心肌群，保持身体从头到脚跟呈一条直线。", "弯曲肘部，将胸部向墙壁降低，保持身体挺直。", "暂停片刻，然后将自己推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["面向墻壁站立，距離大約一臂距離。", "將雙手放在墻上，與肩同高，距離略寬于肩寬。", "雙腳向后退一步，保持與臀部同寬。", "收緊核心肌群，保持身體從頭到腳跟呈一條直線。", "彎曲肘部，將胸部向墻壁降低，保持身體挺直。", "暫停片刻，然后將自己推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0660', 'exercise', 1, '{"id": "0660", "target": "triceps", "name_en": "push-up close-grip off dumbbell", "name_zh": "哑铃支撑窄距俯卧撑", "body_part": "upper arms", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0660-KZXAtKQ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "啞鈴支撐窄距俯臥撐", "instructions_en": ["Start in a push-up position with your hands placed close together, directly under your shoulders.", "Hold a dumbbell in each hand, resting them on the ground.", "Lower your body towards the ground by bending your elbows, keeping them close to your sides.", "Push through your palms to extend your arms and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["从俯卧撑位置开始，双手并拢，直接放在肩膀下方。", "每只手握住一个哑铃，将其放在地上。", "弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。", "推动手掌以伸展手臂并返回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["從俯臥撐位置開始，雙手并攏，直接放在肩膀下方。", "每只手握住一個啞鈴，將其放在地上。", "彎曲肘部，使肘部靠近身體兩側，將身體降低到地面。", "推動手掌以伸展手臂并返回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0661', 'exercise', 1, '{"id": "0661", "target": "glutes", "name_en": "push-up inside leg kick", "name_zh": "内侧踢腿俯卧撑", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0661-0br45wL.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "內側踢腿俯臥撐", "instructions_en": ["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.", "Lower your body towards the ground by bending your elbows, keeping your back straight and your core engaged.", "As you push back up, lift one leg off the ground and kick it out to the side, keeping it straight.", "Lower your leg back down and repeat the push-up, then switch to the other leg.", "Continue alternating leg kicks with each push-up repetition."], "instructions_zh": ["从俯卧撑位置开始，双手分开略宽于肩宽，双脚并拢。", "弯曲肘部，将身体降低到地面，保持背部挺直，核心肌群参与。", "当你向后推时，将一条腿抬离地面并将其踢向一侧，保持伸直。", "将腿放下并重复俯卧撑，然后换另一条腿。", "每次重复俯卧撑时继续交替踢腿。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves", "core"], "instructions_zh_hant": ["從俯臥撐位置開始，雙手分開略寬于肩寬，雙腳并攏。", "彎曲肘部，將身體降低到地面，保持背部挺直，核心肌群參與。", "當你向后推時，將一條腿抬離地面并將其踢向一側，保持伸直。", "將腿放下并重復俯臥撐，然后換另一條腿。", "每次重復俯臥撐時繼續交替踢腿。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0663', 'exercise', 1, '{"id": "0663", "target": "pectorals", "name_en": "push-up medicine ball", "name_zh": "药球俯卧撑", "body_part": "chest", "equipment": "medicine ball", "gif_asset": "assets/fitness/videos/0663-W8KAlkI.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "藥球俯臥撐", "instructions_en": ["Start in a high plank position with your hands on the medicine ball, shoulder-width apart.", "Engage your core and lower your body towards the ground by bending your elbows, keeping your back straight.", "Push through your palms to extend your arms and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["从高平板支撑位置开始，双手放在健身球上，距离与肩同宽。", "弯曲肘部，保持背部挺直，调动核心力量，将身体降低至地面。", "推动手掌以伸展手臂并返回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders", "core"], "instructions_zh_hant": ["從高平板支撐位置開始，雙手放在健身球上，距離與肩同寬。", "彎曲肘部，保持背部挺直，調動核心力量，將身體降低至地面。", "推動手掌以伸展手臂并返回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1467', 'exercise', 1, '{"id": "1467", "target": "triceps", "name_en": "push-up on lower arms", "name_zh": "前臂俯卧撑", "body_part": "upper arms", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1467-4Jt8QsQ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "前臂俯臥撐", "instructions_en": ["Start in a plank position with your forearms on the ground and elbows directly below your shoulders.", "Engage your core and keep your body in a straight line from head to toe.", "Lower your chest towards the ground by bending your elbows, keeping them close to your body.", "Pause for a moment at the bottom, then push yourself back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["从平板支撑位置开始，前臂放在地面上，肘部位于肩膀正下方。", "调动你的核心力量，让你的身体从头到脚保持在一条直线上。", "弯曲肘部，使胸部靠近地面，使胸部靠近地面。", "在底部暂停片刻，然后将自己推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["從平板支撐位置開始，前臂放在地面上，肘部位于肩膀正下方。", "調動你的核心力量，讓你的身體從頭到腳保持在一條直線上。", "彎曲肘部，使胸部靠近地面，使胸部靠近地面。", "在底部暫停片刻，然后將自己推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3145', 'exercise', 1, '{"id": "3145", "target": "pectorals", "name_en": "push-up plus", "name_zh": "俯卧撑加肩胛前伸", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3145-pvBMLHA.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "俯臥撐加肩胛前伸", "instructions_en": ["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels.", "Lower your body towards the ground by bending your elbows, keeping them close to your sides.", "Once your chest is just above the ground, push through your hands to extend your arms and lift your upper body up.", "At the top of the movement, protract your shoulder blades by pushing your upper back towards the ceiling.", "Pause for a moment, then reverse the movement by retracting your shoulder blades and lowering your body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["从高位平板支撑开始，双手分开略宽于肩宽，身体从头到脚跟呈一条直线。", "弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。", "一旦你的胸部刚好高于地面，用力推动你的手臂，伸展你的手臂并抬起你的上半身。", "在动作的最高点，将上背部推向天花板，从而伸展肩胛骨。", "暂停片刻，然后通过缩回肩胛骨并将身体放回起始位置来反转动作。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["從高位平板支撐開始，雙手分開略寬于肩寬，身體從頭到腳跟呈一條直線。", "彎曲肘部，使肘部靠近身體兩側，將身體降低到地面。", "一旦你的胸部剛好高于地面，用力推動你的手臂，伸展你的手臂并抬起你的上半身。", "在動作的最高點，將上背部推向天花板，從而伸展肩胛骨。", "暫停片刻，然后通過縮回肩胛骨并將身體放回起始位置來反轉動作。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0670', 'exercise', 1, '{"id": "0670", "target": "lats", "name_en": "rear pull-up", "name_zh": "颈后引体向上", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0670-CbFSYC1.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "頸后引體向上", "instructions_en": ["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.", "Hang from the bar with your arms fully extended and your body straight.", "Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.", "Continue pulling until your chin is above the bar.", "Pause for a moment at the top, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["正手握住引体向上杆，握距略宽于肩宽。", "悬挂在杠上，双臂完全伸展，身体伸直。", "收紧背部肌肉，将身体拉向杠铃杆，保持肘部靠近身体。", "继续拉，直到下巴位于杠铃上方。", "在顶部停顿片刻，然后慢慢将身体放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["正手握住引體向上桿，握距略寬于肩寬。", "懸掛在杠上，雙臂完全伸展，身體伸直。", "收緊背部肌肉，將身體拉向杠鈴桿，保持肘部靠近身體。", "繼續拉，直到下巴位于杠鈴上方。", "在頂部停頓片刻，然后慢慢將身體放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0664', 'exercise', 1, '{"id": "0664", "target": "abs", "name_en": "push-up to side plank", "name_zh": "俯卧撑至侧平板支撑", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0664-KhHJ338.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "俯臥撐至側平板支撐", "instructions_en": ["Start in a push-up position with your hands shoulder-width apart and your body in a straight line.", "Lower your body towards the ground by bending your elbows, keeping your core engaged.", "Push back up to the starting position.", "Shift your weight onto your left hand and rotate your body to the right, lifting your right arm towards the ceiling.", "Hold the side plank position for a few seconds, then return to the starting position.", "Repeat the push-up and side plank on the opposite side.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["从俯卧撑位置开始，双手分开与肩同宽，身体呈一条直线。", "弯曲肘部，将身体降低到地面，保持核心参与。", "推回到起始位置。", "将体重转移到左手上，然后将身体向右旋转，将右臂举向天花板。", "保持侧板姿势几秒钟，然后返回到起始位置。", "在另一侧重复俯卧撑和侧板支撑。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["shoulders", "chest", "triceps"], "instructions_zh_hant": ["從俯臥撐位置開始，雙手分開與肩同寬，身體呈一條直線。", "彎曲肘部，將身體降低到地面，保持核心參與。", "推回到起始位置。", "將體重轉移到左手上，然后將身體向右旋轉，將右臂舉向天花板。", "保持側板姿勢幾秒鐘，然后返回到起始位置。", "在另一側重復俯臥撐和側板支撐。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3533', 'exercise', 1, '{"id": "3533", "target": "quads", "name_en": "quads", "name_zh": "自重深蹲（股四头肌）", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3533-6YUfHPL.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "自重深蹲（股四頭肌）", "instructions_en": ["Stand with your feet shoulder-width apart.", "Lower your body by bending your knees and pushing your hips back as if sitting on a chair.", "Keep your chest up and your back straight.", "Lower yourself until your thighs are parallel to the ground.", "Push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立。", "弯曲膝盖并将臀部向后推，降低身体，就像坐在椅子上一样。", "保持挺胸、背部挺直。", "降低身体直到大腿与地面平行。", "推动脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "glutes"], "instructions_zh_hant": ["雙腳分開與肩同寬站立。", "彎曲膝蓋并將臀部向后推，降低身體，就像坐在椅子上一樣。", "保持挺胸、背部挺直。", "降低身體直到大腿與地面平行。", "推動腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3552', 'exercise', 1, '{"id": "3552", "target": "quads", "name_en": "quick feet v. 2", "name_zh": "快速碎步（变式2）", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3552-mweqJin.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "快速碎步（變式2）", "instructions_en": ["Stand with your feet shoulder-width apart and your arms by your sides.", "Begin by rapidly moving your feet up and down, as if you were running in place.", "Keep your movements quick and light, focusing on staying on the balls of your feet.", "Continue for the desired duration or number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双臂放在身体两侧。", "首先快速上下移动双脚，就像原地跑步一样。", "保持动作快速而轻盈，重点放在脚掌上。", "继续所需的持续时间或重复次数。"], "secondary_muscles": ["calves", "hamstrings"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙臂放在身體兩側。", "首先快速上下移動雙腳，就像原地跑步一樣。", "保持動作快速而輕盈，重點放在腳掌上。", "繼續所需的持續時間或重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0666', 'exercise', 1, '{"id": "0666", "target": "pectorals", "name_en": "raise single arm push-up", "name_zh": "单臂抬起俯卧撑", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0666-13TpY4H.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "單臂抬起俯臥撐", "instructions_en": ["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.", "Extend one arm straight out to the side, parallel to the ground.", "Lower your body towards the ground by bending your elbows, keeping your back straight and core engaged.", "Push back up to the starting position, using your chest muscles to lift your body.", "Repeat with the other arm extended."], "instructions_zh": ["从俯卧撑位置开始，双手分开略宽于肩宽，双脚并拢。", "将一只手臂伸直至一侧，与地面平行。", "弯曲肘部，将身体降低到地面，保持背部挺直，核心参与。", "推回起始位置，使用胸部肌肉抬起身体。", "另一只手臂伸出，重复上述动作。"], "secondary_muscles": ["triceps", "shoulders", "core"], "instructions_zh_hant": ["從俯臥撐位置開始，雙手分開略寬于肩寬，雙腳并攏。", "將一只手臂伸直至一側，與地面平行。", "彎曲肘部，將身體降低到地面，保持背部挺直，核心參與。", "推回起始位置，使用胸部肌肉抬起身體。", "另一只手臂伸出，重復上述動作。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0668', 'exercise', 1, '{"id": "0668", "target": "glutes", "name_en": "rear decline bridge", "name_zh": "后下斜桥式", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0668-UpAlold.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "后下斜橋式", "instructions_en": ["Lie on your back with your feet flat on the ground and your knees bent.", "Place your arms by your sides with your palms facing down.", "Engage your glutes and hamstrings, and lift your hips off the ground until your body forms a straight line from your knees to your shoulders.", "Hold this position for a few seconds, then slowly lower your hips back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["仰卧，双脚平放在地上，膝盖弯曲。", "将手臂放在身体两侧，手掌朝下。", "收紧臀肌和腿筋，将臀部抬离地面，直到身体从膝盖到肩膀形成一条直线。", "保持这个姿势几秒钟，然后慢慢地将臀部放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "lower back"], "instructions_zh_hant": ["仰臥，雙腳平放在地上，膝蓋彎曲。", "將手臂放在身體兩側，手掌朝下。", "收緊臀肌和腿筋，將臀部抬離地面，直到身體從膝蓋到肩膀形成一條直線。", "保持這個姿勢幾秒鐘，然后慢慢地將臀部放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1582', 'exercise', 1, '{"id": "1582", "target": "hamstrings", "name_en": "reclining big toe pose with rope", "name_zh": "绳带辅助仰卧手抓脚趾式", "body_part": "upper legs", "equipment": "rope", "gif_asset": "assets/fitness/videos/1582-K5xgdvI.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩帶輔助仰臥手抓腳趾式", "instructions_en": ["Lie on your back with your legs extended and your arms by your sides.", "Loop the rope around the ball of your right foot and hold the ends of the rope with your hands.", "Slowly raise your right leg towards your chest, keeping your knee straight and your foot flexed.", "Hold the stretch for a few seconds, then slowly lower your leg back down to the starting position.", "Repeat with your left leg.", "Continue alternating legs for the desired number of repetitions."], "instructions_zh": ["仰卧，双腿伸展，双臂放在身体两侧。", "将绳子绕在右脚掌上，并用手握住绳子的末端。", "慢慢地将右腿抬向胸部，保持膝盖伸直，脚弯曲。", "保持伸展几秒钟，然后慢慢将腿放回起始位置。", "左腿重复上述动作。", "继续交替双腿达到所需的重复次数。"], "secondary_muscles": ["calves", "glutes"], "instructions_zh_hant": ["仰臥，雙腿伸展，雙臂放在身體兩側。", "將繩子繞在右腳掌上，并用手握住繩子的末端。", "慢慢地將右腿抬向胸部，保持膝蓋伸直，腳彎曲。", "保持伸展幾秒鐘，然后慢慢將腿放回起始位置。", "左腿重復上述動作。", "繼續交替雙腿達到所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3236', 'exercise', 1, '{"id": "3236", "target": "glutes", "name_en": "resistance band hip thrusts on knees (female)", "name_zh": "阻力带跪姿挺髋（女性示范）", "body_part": "upper legs", "equipment": "resistance band", "gif_asset": "assets/fitness/videos/3236-Pjbc0Kt.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "阻力帶跪姿挺髖（女性示范）", "instructions_en": ["Start by kneeling on the ground with your knees hip-width apart and your feet flexed.", "Wrap the resistance band around your thighs, just above your knees.", "Place your hands on your hips or extend them out in front of you for balance.", "Engage your glutes and core muscles.", "Push your hips forward and squeeze your glutes as you lift your knees off the ground, extending your hips until your thighs are parallel to the ground.", "Hold the position for a moment, then slowly lower your knees back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先跪在地上，膝盖分开与臀部同宽，双脚弯曲。", "将阻力带缠绕在大腿上，就在膝盖上方。", "将双手放在臀部或向前伸展以保持平衡。", "调动你的臀肌和核心肌肉。", "当你将膝盖抬离地面时，向前推动臀部并挤压臀部，伸展臀部直到大腿与地面平行。", "保持该姿势片刻，然后慢慢将膝盖放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "quadriceps"], "instructions_zh_hant": ["首先跪在地上，膝蓋分開與臀部同寬，雙腳彎曲。", "將阻力帶纏繞在大腿上，就在膝蓋上方。", "將雙手放在臀部或向前伸展以保持平衡。", "調動你的臀肌和核心肌肉。", "當你將膝蓋抬離地面時，向前推動臀部并擠壓臀部，伸展臀部直到大腿與地面平行。", "保持該姿勢片刻，然后慢慢將膝蓋放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3007', 'exercise', 1, '{"id": "3007", "target": "quads", "name_en": "resistance band leg extension", "name_zh": "阻力带腿屈伸", "body_part": "upper legs", "equipment": "resistance band", "gif_asset": "assets/fitness/videos/3007-Y1MsI1l.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "阻力帶腿屈伸", "instructions_en": ["Attach the resistance band to a sturdy anchor point and secure it around your ankle.", "Stand facing the anchor point with your feet shoulder-width apart.", "Keeping your core engaged and your upper body stable, extend your leg straight out in front of you.", "Pause for a moment at the top, then slowly return your leg to the starting position.", "Repeat for the desired number of repetitions, then switch legs."], "instructions_zh": ["将阻力带固定在坚固的锚点上，并将其固定在脚踝上。", "面向锚点站立，双脚分开与肩同宽。", "保持核心参与并保持上半身稳定，将腿伸直到身前。", "在顶部暂停片刻，然后慢慢地将腿放回起始位置。", "重复所需的重复次数，然后换腿。"], "secondary_muscles": ["hamstrings"], "instructions_zh_hant": ["將阻力帶固定在堅固的錨點上，并將其固定在腳踝上。", "面向錨點站立，雙腳分開與肩同寬。", "保持核心參與并保持上半身穩定，將腿伸直到身前。", "在頂部暫停片刻，然后慢慢地將腿放回起始位置。", "重復所需的重復次數，然后換腿。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3123', 'exercise', 1, '{"id": "3123", "target": "biceps", "name_en": "resistance band seated biceps curl", "name_zh": "阻力带坐姿二头弯举", "body_part": "upper arms", "equipment": "resistance band", "gif_asset": "assets/fitness/videos/3123-XFc3vpY.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "阻力帶坐姿二頭彎舉", "instructions_en": ["Sit on a chair or bench with your back straight and feet flat on the ground.", "Hold the resistance band with an underhand grip, palms facing up, and arms extended down by your sides.", "Keeping your upper arms stationary, exhale and curl the resistance band up towards your shoulders.", "Pause for a moment at the top, squeezing your biceps.", "Inhale and slowly lower the resistance band back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在椅子或长凳上，背部挺直，双脚平放在地面上。", "反手握住阻力带，手掌朝上，手臂向下伸展到身体两侧。", "保持上臂静止，呼气并将阻力带向上卷向肩膀。", "在顶部暂停片刻，挤压你的二头肌。", "吸气并慢慢降低阻力带回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在椅子或長凳上，背部挺直，雙腳平放在地面上。", "反手握住阻力帶，手掌朝上，手臂向下伸展到身體兩側。", "保持上臂靜止，呼氣并將阻力帶向上卷向肩膀。", "在頂部暫停片刻，擠壓你的二頭肌。", "吸氣并慢慢降低阻力帶回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0872', 'exercise', 1, '{"id": "0872", "target": "abs", "name_en": "reverse crunch", "name_zh": "反向卷腹", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0872-nCU1Ekp.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "反向卷腹", "instructions_en": ["Lie flat on your back with your arms extended along your sides.", "Bend your knees and lift your feet off the ground, bringing your thighs perpendicular to the floor.", "Contract your abs and curl your hips off the floor, bringing your knees towards your chest.", "Pause for a moment at the top, then slowly lower your hips back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，双臂沿着身体两侧伸展。", "弯曲膝盖，将脚抬离地面，使大腿垂直于地板。", "收缩腹肌，将臀部卷离地板，使膝盖靠近胸部。", "在顶部暂停片刻，然后慢慢将臀部放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["平躺，雙臂沿著身體兩側伸展。", "彎曲膝蓋，將腳抬離地面，使大腿垂直于地板。", "收縮腹肌，將臀部卷離地板，使膝蓋靠近胸部。", "在頂部暫停片刻，然后慢慢將臀部放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3124', 'exercise', 1, '{"id": "3124", "target": "pectorals", "name_en": "resistance band seated chest press", "name_zh": "阻力带坐姿推胸", "body_part": "chest", "equipment": "resistance band", "gif_asset": "assets/fitness/videos/3124-4x5Okof.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "阻力帶坐姿推胸", "instructions_en": ["Sit on a chair or bench with your back straight and feet flat on the ground.", "Hold the resistance band handles in each hand, with your palms facing down and elbows bent at a 90-degree angle.", "Extend your arms forward, pushing the resistance band away from your chest.", "Pause for a moment at the end of the movement, then slowly return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在椅子或长凳上，背部挺直，双脚平放在地面上。", "每只手握住阻力带手柄，手掌朝下，肘部弯曲成 90 度角。", "向前伸展双臂，将阻力带推离胸部。", "动作结束时暂停片刻，然后慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["坐在椅子或長凳上，背部挺直，雙腳平放在地面上。", "每只手握住阻力帶手柄，手掌朝下，肘部彎曲成 90 度角。", "向前伸展雙臂，將阻力帶推離胸部。", "動作結束時暫停片刻，然后慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3006', 'exercise', 1, '{"id": "3006", "target": "abductors", "name_en": "resistance band seated hip abduction", "name_zh": "阻力带坐姿髋部外展", "body_part": "upper legs", "equipment": "resistance band", "gif_asset": "assets/fitness/videos/3006-0xDpB4L.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "阻力帶坐姿髖部外展", "instructions_en": ["Sit on a chair or bench with your back straight and feet flat on the ground.", "Wrap the resistance band around your thighs, just above your knees.", "Place your hands on the sides of the chair or bench for support.", "Engage your abductors (outer thigh muscles) and slowly push your knees apart, against the resistance of the band.", "Pause for a moment at the end of the movement, then slowly bring your knees back together.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在椅子或长凳上，背部挺直，双脚平放在地面上。", "将阻力带缠绕在大腿上，就在膝盖上方。", "将双手放在椅子或长凳的两侧以获得支撑。", "启动外展肌（大腿外侧肌肉），并克服弹力带的阻力，慢慢将膝盖分开。", "动作结束时暂停片刻，然后慢慢将膝盖放回一起。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings"], "instructions_zh_hant": ["坐在椅子或長凳上，背部挺直，雙腳平放在地面上。", "將阻力帶纏繞在大腿上，就在膝蓋上方。", "將雙手放在椅子或長凳的兩側以獲得支撐。", "啟動外展肌（大腿外側肌肉），并克服彈力帶的阻力，慢慢將膝蓋分開。", "動作結束時暫停片刻，然后慢慢將膝蓋放回一起。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3122', 'exercise', 1, '{"id": "3122", "target": "delts", "name_en": "resistance band seated shoulder press", "name_zh": "阻力带坐姿肩上推举", "body_part": "shoulders", "equipment": "resistance band", "gif_asset": "assets/fitness/videos/3122-S93zLTG.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "阻力帶坐姿肩上推舉", "instructions_en": ["Sit on a chair or bench with your back straight and feet flat on the ground.", "Hold the resistance band with both hands, palms facing forward, and bring it up to shoulder level.", "Press the band overhead, extending your arms fully.", "Pause for a moment at the top, then slowly lower the band back down to shoulder level.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在椅子或长凳上，背部挺直，双脚平放在地面上。", "双手握住阻力带，手掌朝前，将其拉至肩部水平。", "将弹力带压过头顶，充分伸展双臂。", "在顶部停顿片刻，然后慢慢将弹力带降低至肩部水平。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "upper back"], "instructions_zh_hant": ["坐在椅子或長凳上，背部挺直，雙腳平放在地面上。", "雙手握住阻力帶，手掌朝前，將其拉至肩部水平。", "將彈力帶壓過頭頂，充分伸展雙臂。", "在頂部停頓片刻，然后慢慢將彈力帶降低至肩部水平。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3144', 'exercise', 1, '{"id": "3144", "target": "upper back", "name_en": "resistance band seated straight back row", "name_zh": "阻力带坐姿背部挺直划船", "body_part": "back", "equipment": "resistance band", "gif_asset": "assets/fitness/videos/3144-Nu7jqFE.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "阻力帶坐姿背部挺直劃船", "instructions_en": ["Sit on the floor with your legs extended and loop the resistance band around your feet.", "Hold the ends of the resistance band with your hands, palms facing each other.", "Keep your back straight and lean slightly back, engaging your core.", "Pull the resistance band towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly release the tension and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在地板上，双腿伸展，将阻力带绕在脚上。", "双手握住阻力带的两端，手掌相对。", "保持背部挺直，稍微向后倾斜，锻炼核心肌群。", "将阻力带拉向胸部，将肩胛骨挤压在一起。", "在最高点停顿片刻，然后慢慢释放张力，回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "shoulders"], "instructions_zh_hant": ["坐在地板上，雙腿伸展，將阻力帶繞在腳上。", "雙手握住阻力帶的兩端，手掌相對。", "保持背部挺直，稍微向后傾斜，鍛煉核心肌群。", "將阻力帶拉向胸部，將肩胛骨擠壓在一起。", "在最高點停頓片刻，然后慢慢釋放張力，回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0673', 'exercise', 1, '{"id": "0673", "target": "lats", "name_en": "reverse grip machine lat pulldown", "name_zh": "反握器械背阔肌下拉", "body_part": "back", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/0673-ecpY0rH.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "反握器械背闊肌下拉", "instructions_en": ["Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.", "Grasp the handles with an underhand grip, slightly wider than shoulder-width apart.", "Sit upright with your chest out and shoulders back, maintaining a slight arch in your lower back.", "Pull the handles down towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度，将自己放在机器上，膝盖位于垫子下方，双脚平放在地面上。", "反手握住手柄，握距略宽于肩宽。", "坐直，挺胸，肩膀向后，保持下背部轻微的拱形。", "将手柄向下拉向胸部，将肩胛骨挤压在一起。", "在动作底部暂停片刻，然后慢慢松开手柄回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["調整座椅高度，將自己放在機器上，膝蓋位于墊子下方，雙腳平放在地面上。", "反手握住手柄，握距略寬于肩寬。", "坐直，挺胸，肩膀向后，保持下背部輕微的拱形。", "將手柄向下拉向胸部，將肩胛骨擠壓在一起。", "在動作底部暫停片刻，然后慢慢松開手柄回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0674', 'exercise', 1, '{"id": "0674", "target": "lats", "name_en": "reverse grip pull-up", "name_zh": "反握引体向上", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0674-YAk5dIw.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "反握引體向上", "instructions_en": ["Grab the pull-up bar with an underhand grip, hands shoulder-width apart.", "Hang from the bar with your arms fully extended and your body straight.", "Engage your back muscles and pull your body up towards the bar, leading with your chest.", "Continue pulling until your chin is above the bar.", "Pause for a moment at the top, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双手分开与肩同宽，反握抓住引体向上杆。", "悬挂在杠上，双臂完全伸展，身体伸直。", "调动背部肌肉，将身体拉向杠铃杆，以胸部为主导。", "继续拉，直到下巴位于杠铃上方。", "在顶部停顿片刻，然后慢慢将身体放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["雙手分開與肩同寬，反握抓住引體向上桿。", "懸掛在杠上，雙臂完全伸展，身體伸直。", "調動背部肌肉，將身體拉向杠鈴桿，以胸部為主導。", "繼續拉，直到下巴位于杠鈴上方。", "在頂部停頓片刻，然后慢慢將身體放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0675', 'exercise', 1, '{"id": "0675", "target": "glutes", "name_en": "reverse hyper extension (on stability ball)", "name_zh": "健身球反向挺身", "body_part": "upper legs", "equipment": "stability ball", "gif_asset": "assets/fitness/videos/0675-vM5YS2g.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球反向挺身", "instructions_en": ["Lie face down on a stability ball with your hips resting on the ball and your legs extended straight behind you.", "Place your hands on the ground in front of you for stability.", "Engaging your glutes and hamstrings, lift your legs up towards the ceiling as high as you can.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["面朝下躺在稳定球上，臀部放在球上，双腿伸直在身后。", "将双手放在身前的地面上以保持稳定。", "调动臀肌和腿筋，将双腿尽可能高地抬向天花板。", "在顶部暂停片刻，然后慢慢将双腿放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "lower back"], "instructions_zh_hant": ["面朝下躺在穩定球上，臀部放在球上，雙腿伸直在身后。", "將雙手放在身前的地面上以保持穩定。", "調動臀肌和腿筋，將雙腿盡可能高地抬向天花板。", "在頂部暫停片刻，然后慢慢將雙腿放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1423', 'exercise', 1, '{"id": "1423", "target": "glutes", "name_en": "reverse hyper on flat bench", "name_zh": "反向挺身（平凳）", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1423-OrETs32.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "反向挺身（平凳）", "instructions_en": ["Lie face down on a flat bench with your hips at the edge and your legs hanging off the bench.", "Hold onto the bench for stability.", "Keeping your legs straight, raise them up towards the ceiling as high as you can.", "Squeeze your glutes at the top of the movement.", "Slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["脸朝下躺在平坦的长凳上，臀部位于边缘，双腿悬在长凳上。", "抓住长凳以保持稳定。", "保持双腿伸直，尽可能将它们抬向天花板。", "在动作的最高点挤压臀部。", "慢慢地将双腿放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "lower back"], "instructions_zh_hant": ["臉朝下躺在平坦的長凳上，臀部位于邊緣，雙腿懸在長凳上。", "抓住長凳以保持穩定。", "保持雙腿伸直，盡可能將它們抬向天花板。", "在動作的最高點擠壓臀部。", "慢慢地將雙腿放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3663', 'exercise', 1, '{"id": "3663", "target": "abs", "name_en": "reverse plank with leg lift", "name_zh": "反向平板支撑配合腿部抬举", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3663-tFToB7l.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "反向平板支撐配合腿部抬舉", "instructions_en": ["Sit on the ground with your legs extended in front of you and your hands resting on the ground behind you, fingers pointing towards your feet.", "Press through your hands and lift your hips off the ground, coming into a reverse plank position.", "Engage your core and lift one leg off the ground, extending it straight up towards the ceiling.", "Hold for a moment, then lower your leg back down.", "Repeat with the other leg.", "Continue alternating legs for the desired number of repetitions."], "instructions_zh": ["坐在地上，双腿向前伸展，双手放在身后的地面上，手指指向脚部。", "双手用力，将臀部抬离地面，进入反向平板支撑位置。", "启动你的核心并将一条腿抬离地面，将其笔直向上伸向天花板。", "保持一会儿，然后将腿放下。", "换另一条腿重复上述步骤。", "继续交替双腿达到所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings", "shoulders"], "instructions_zh_hant": ["坐在地上，雙腿向前伸展，雙手放在身后的地面上，手指指向腳部。", "雙手用力，將臀部抬離地面，進入反向平板支撐位置。", "啟動你的核心并將一條腿抬離地面，將其筆直向上伸向天花板。", "保持一會兒，然后將腿放下。", "換另一條腿重復上述步驟。", "繼續交替雙腿達到所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0677', 'exercise', 1, '{"id": "0677", "target": "triceps", "name_en": "ring dips", "name_zh": "吊环臂屈伸", "body_part": "upper arms", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0677-ezTvXcr.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "吊環臂屈伸", "instructions_en": ["Start by hanging from the rings with your arms fully extended and your body straight.", "Lower your body by bending your elbows until your shoulders are below your elbows.", "Push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先，将手臂完全伸展，身体伸直，挂在吊环上。", "弯曲肘部，降低身体，直到肩膀低于肘部。", "伸直手臂，将自己推回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["首先，將手臂完全伸展，身體伸直，掛在吊環上。", "彎曲肘部，降低身體，直到肩膀低于肘部。", "伸直手臂，將自己推回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2571', 'exercise', 1, '{"id": "2571", "target": "glutes", "name_en": "rocking frog stretch", "name_zh": "摇摆蛙式拉伸", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/2571-2Dk4xQV.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "搖擺蛙式拉伸", "instructions_en": ["Start by kneeling on the ground with your knees hip-width apart.", "Place your hands on the ground in front of you for support.", "Slowly lean forward, shifting your weight onto your hands and extending your legs behind you.", "Keep your back straight and engage your glutes as you push your hips back and up towards the ceiling.", "Hold this position for a few seconds, feeling a stretch in your glutes.", "Slowly return to the starting position by bending your knees and lowering your hips back down.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先跪在地上，膝盖分开与臀部同宽。", "将双手放在身前的地面上以获得支撑。", "慢慢向前倾，将重心转移到双手上，并将双腿伸到身后。", "当你将臀部向后推向天花板时，保持背部挺直并收紧臀部。", "保持这个姿势几秒钟，感受臀部的拉伸。", "弯曲膝盖并降低臀部，慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "quadriceps"], "instructions_zh_hant": ["首先跪在地上，膝蓋分開與臀部同寬。", "將雙手放在身前的地面上以獲得支撐。", "慢慢向前傾，將重心轉移到雙手上，并將雙腿伸到身后。", "當你將臀部向后推向天花板時，保持背部挺直并收緊臀部。", "保持這個姿勢幾秒鐘，感受臀部的拉伸。", "彎曲膝蓋并降低臀部，慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0678', 'exercise', 1, '{"id": "0678", "target": "lats", "name_en": "rocky pull-up pulldown", "name_zh": "洛基式颈前后引体向上", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0678-cQ19bBP.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "洛基式頸前后引體向上", "instructions_en": ["Stand in front of a pull-up bar with your feet shoulder-width apart.", "Reach up and grab the bar with an overhand grip, slightly wider than shoulder-width apart.", "Hang from the bar with your arms fully extended and your body straight.", "Engage your back muscles and pull your body up towards the bar, leading with your chest.", "Pause for a moment at the top, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站在引体向上杆前，双脚分开与肩同宽。", "向上伸手，正手握住杠铃，握距略宽于肩宽。", "悬挂在杠上，双臂完全伸展，身体伸直。", "调动背部肌肉，将身体拉向杠铃杆，以胸部为主导。", "在顶部停顿片刻，然后慢慢将身体放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["站在引體向上桿前，雙腳分開與肩同寬。", "向上伸手，正手握住杠鈴，握距略寬于肩寬。", "懸掛在杠上，雙臂完全伸展，身體伸直。", "調動背部肌肉，將身體拉向杠鈴桿，以胸部為主導。", "在頂部停頓片刻，然后慢慢將身體放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2208', 'exercise', 1, '{"id": "2208", "target": "spine", "name_en": "roller back stretch", "name_zh": "滚轮背部拉伸", "body_part": "back", "equipment": "roller", "gif_asset": "assets/fitness/videos/2208-isofgzg.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "滾輪背部拉伸", "instructions_en": ["Start by sitting on the ground with your legs extended in front of you.", "Place the roller perpendicular to your body, just below your glutes.", "Slowly roll your body backwards, allowing the roller to move up your back.", "Continue rolling until the roller reaches your upper back.", "Pause for a moment, then slowly roll back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先坐在地上，双腿在身前伸展。", "将滚轮垂直于您的身体放置，位于臀部下方。", "慢慢向后滚动你的身体，让滚轮向上移动你的背部。", "继续滚动，直到滚轮到达您的上背部。", "暂停片刻，然后慢慢滚回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "glutes"], "instructions_zh_hant": ["首先坐在地上，雙腿在身前伸展。", "將滾輪垂直于您的身體放置，位于臀部下方。", "慢慢向后滾動你的身體，讓滾輪向上移動你的背部。", "繼續滾動，直到滾輪到達您的上背部。", "暫停片刻，然后慢慢滾回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2204', 'exercise', 1, '{"id": "2204", "target": "abs", "name_en": "roller body saw", "name_zh": "滚轮身体锯式", "body_part": "waist", "equipment": "roller", "gif_asset": "assets/fitness/videos/2204-XeMvLgE.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "滾輪身體鋸式", "instructions_en": ["Start in a plank position with your forearms on the roller and your body in a straight line.", "Engage your core and slowly roll the roller forward, extending your body as far as you can while maintaining control.", "Pause for a moment at the furthest point, then slowly roll the roller back towards your starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["从平板支撑位置开始，前臂放在滚轴上，身体呈一条直线。", "启动你的核心并缓慢向前滚动滚轮，在保持控制的同时尽可能地伸展你的身体。", "在最远点暂停片刻，然后慢慢地将滚轮滚回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps", "core"], "instructions_zh_hant": ["從平板支撐位置開始，前臂放在滾軸上，身體呈一條直線。", "啟動你的核心并緩慢向前滾動滾輪，在保持控制的同時盡可能地伸展你的身體。", "在最遠點暫停片刻，然后慢慢地將滾輪滾回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2205', 'exercise', 1, '{"id": "2205", "target": "glutes", "name_en": "roller hip lat stretch", "name_zh": "滚轮髋部背阔肌拉伸", "body_part": "upper legs", "equipment": "roller", "gif_asset": "assets/fitness/videos/2205-0L2KwtI.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "滾輪髖部背闊肌拉伸", "instructions_en": ["Start by kneeling on the ground with the roller positioned under your hips.", "Place your hands on the roller for support.", "Slowly roll the roller forward, extending your hips and stretching your glutes.", "Hold the stretch for a few seconds, then roll back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先跪在地上，将滚轮放在臀部下方。", "将双手放在滚轮上以获得支撑。", "慢慢地向前滚动滚轮，伸展臀部并伸展臀部。", "保持伸展几秒钟，然后滚回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "quadriceps"], "instructions_zh_hant": ["首先跪在地上，將滾輪放在臀部下方。", "將雙手放在滾輪上以獲得支撐。", "慢慢地向前滾動滾輪，伸展臀部并伸展臀部。", "保持伸展幾秒鐘，然后滾回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2202', 'exercise', 1, '{"id": "2202", "target": "glutes", "name_en": "roller hip stretch", "name_zh": "滚轮髋部拉伸", "body_part": "upper legs", "equipment": "roller", "gif_asset": "assets/fitness/videos/2202-oMypNrz.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "滾輪髖部拉伸", "instructions_en": ["Start by sitting on the ground with your legs extended in front of you.", "Place the roller under your glutes, just above your knees.", "Lean back and place your hands on the ground behind you for support.", "Engage your glutes and slowly roll the roller forward, bending your knees and bringing them towards your chest.", "Pause for a moment at the end of the movement, feeling a stretch in your glutes.", "Slowly roll the roller back to the starting position, extending your legs.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先坐在地上，双腿在身前伸展。", "将滚轮放在臀部下方、膝盖上方。", "向后倾斜，双手放在身后的地面上以获得支撑。", "收紧臀部，慢慢向前滚动滚轮，弯曲膝盖并将其拉向胸部。", "动作结束时暂停片刻，感受臀部的拉伸。", "慢慢地将滚轮滚回起始位置，伸展双腿。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "quadriceps"], "instructions_zh_hant": ["首先坐在地上，雙腿在身前伸展。", "將滾輪放在臀部下方、膝蓋上方。", "向后傾斜，雙手放在身后的地面上以獲得支撐。", "收緊臀部，慢慢向前滾動滾輪，彎曲膝蓋并將其拉向胸部。", "動作結束時暫停片刻，感受臀部的拉伸。", "慢慢地將滾輪滾回起始位置，伸展雙腿。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2206', 'exercise', 1, '{"id": "2206", "target": "abs", "name_en": "roller reverse crunch", "name_zh": "滚轮反向卷腹", "body_part": "waist", "equipment": "roller", "gif_asset": "assets/fitness/videos/2206-SKXQAx3.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "滾輪反向卷腹", "instructions_en": ["Lie flat on your back with your arms extended straight above your head and your legs straight out in front of you.", "Place the roller between your feet and grip it with your toes.", "Engaging your abs, lift your legs off the ground and curl your knees towards your chest, rolling the roller towards your body.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position, rolling the roller away from your body.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，双臂伸直过头顶，双腿伸直在身前。", "将滚筒放在双脚之间，并用脚趾抓住它。", "收紧腹肌，将双腿抬离地面，将膝盖向胸部弯曲，将滚轮向身体方向滚动。", "在顶部停顿片刻，然后慢慢将双腿放回起始位置，将滚轮滚离身体。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["平躺，雙臂伸直過頭頂，雙腿伸直在身前。", "將滾筒放在雙腳之間，并用腳趾抓住它。", "收緊腹肌，將雙腿抬離地面，將膝蓋向胸部彎曲，將滾輪向身體方向滾動。", "在頂部停頓片刻，然后慢慢將雙腿放回起始位置，將滾輪滾離身體。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2203', 'exercise', 1, '{"id": "2203", "target": "pectorals", "name_en": "roller seated shoulder flexor depresor retractor", "name_zh": "滚轮坐姿肩部屈肌下沉后缩", "body_part": "chest", "equipment": "roller", "gif_asset": "assets/fitness/videos/2203-8coXSYU.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "滾輪坐姿肩部屈肌下沉后縮", "instructions_en": ["Sit on a flat surface with your legs extended in front of you.", "Hold the roller with both hands, palms facing down, and place it on your thighs.", "Lean forward slightly and roll the roller away from your body, extending your arms straight in front of you.", "Pause for a moment, then slowly roll the roller back towards your body, bending your arms and bringing the roller back to your thighs.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在平坦的表面上，双腿在身前伸展。", "双手握住滚轮，掌心朝下，将其放在大腿上。", "稍微向前倾，将滚轮滚离身体，将手臂伸直在身前。", "暂停片刻，然后慢慢将滚轮向身体方向滚动，弯曲手臂，将滚轮拉回到大腿处。", "重复所需的重复次数。"], "secondary_muscles": ["deltoids", "triceps"], "instructions_zh_hant": ["坐在平坦的表面上，雙腿在身前伸展。", "雙手握住滾輪，掌心朝下，將其放在大腿上。", "稍微向前傾，將滾輪滾離身體，將手臂伸直在身前。", "暫停片刻，然后慢慢將滾輪向身體方向滾動，彎曲手臂，將滾輪拉回到大腿處。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2209', 'exercise', 1, '{"id": "2209", "target": "pectorals", "name_en": "roller seated single leg shoulder flexor depresor retractor", "name_zh": "滚轮坐姿单腿肩部屈肌下沉后缩", "body_part": "chest", "equipment": "roller", "gif_asset": "assets/fitness/videos/2209-CjETvlw.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "滾輪坐姿單腿肩部屈肌下沉后縮", "instructions_en": ["Sit on a flat surface with your legs extended in front of you.", "Hold the roller with both hands, palms facing down, and place it on your thighs.", "Lean back slightly and engage your core muscles.", "Raise the roller up to shoulder level, keeping your arms straight.", "Slowly lower the roller back down to your thighs.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在平坦的表面上，双腿在身前伸展。", "双手握住滚轮，掌心朝下，将其放在大腿上。", "稍微向后倾斜并锻炼核心肌肉。", "将滚轮抬高至肩部高度，保持手臂伸直。", "慢慢地将滚轮放回到大腿处。", "重复所需的重复次数。"], "secondary_muscles": ["deltoids", "triceps"], "instructions_zh_hant": ["坐在平坦的表面上，雙腿在身前伸展。", "雙手握住滾輪，掌心朝下，將其放在大腿上。", "稍微向后傾斜并鍛煉核心肌肉。", "將滾輪抬高至肩部高度，保持手臂伸直。", "慢慢地將滾輪放回到大腿處。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2207', 'exercise', 1, '{"id": "2207", "target": "lats", "name_en": "roller side lat stretch", "name_zh": "滚轮侧背阔肌拉伸", "body_part": "back", "equipment": "roller", "gif_asset": "assets/fitness/videos/2207-c3Pfhti.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "滾輪側背闊肌拉伸", "instructions_en": ["Stand with your feet shoulder-width apart and hold the roller with both hands in front of your body.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Extend your arms forward and roll the roller down towards your feet, feeling a stretch in your lats.", "Hold the stretch for a few seconds, then slowly roll the roller back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手握住滚轮放在身体前方。", "稍微弯曲膝盖，髋部向前转动，保持背部挺直。", "向前伸展双臂，将滚轮向脚部方向滚动，感受背阔肌的拉伸。", "保持拉伸几秒钟，然后慢慢地将滚轮滚动回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手握住滾輪放在身體前方。", "稍微彎曲膝蓋，髖部向前轉動，保持背部挺直。", "向前伸展雙臂，將滾輪向腳部方向滾動，感受背闊肌的拉伸。", "保持拉伸幾秒鐘，然后慢慢地將滾輪滾動回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0680', 'exercise', 1, '{"id": "0680", "target": "upper back", "name_en": "rope climb", "name_zh": "绳索攀爬", "body_part": "back", "equipment": "rope", "gif_asset": "assets/fitness/videos/0680-yaAxcQr.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "繩索攀爬", "instructions_en": ["Stand facing the rope with your feet shoulder-width apart.", "Grab the rope with both hands, palms facing towards you.", "Bend your knees slightly and engage your core.", "Begin pulling yourself up the rope by alternating hand-over-hand movements.", "Use your legs to assist in the upward movement.", "Continue climbing until you reach the desired height or the top of the rope.", "To descend, reverse the hand-over-hand movement while controlling your descent.", "Repeat for the desired number of repetitions."], "instructions_zh": ["面向绳子站立，双脚分开与肩同宽。", "用双手抓住绳子，手掌朝向自己。", "稍微弯曲膝盖并启动核心。", "开始通过交替的双手动作将自己拉上绳子。", "用双腿协助向上运动。", "继续攀爬，直到到达所需的高度或绳索的顶部。", "要下降，请在控制下降的同时反转双手的动作。", "重复所需的重复次数。"], "secondary_muscles": ["forearms", "biceps", "shoulders"], "instructions_zh_hant": ["面向繩子站立，雙腳分開與肩同寬。", "用雙手抓住繩子，手掌朝向自己。", "稍微彎曲膝蓋并啟動核心。", "開始通過交替的雙手動作將自己拉上繩子。", "用雙腿協助向上運動。", "繼續攀爬，直到到達所需的高度或繩索的頂部。", "要下降，請在控制下降的同時反轉雙手的動作。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3021', 'exercise', 1, '{"id": "3021", "target": "serratus anterior", "name_en": "scapula push-up", "name_zh": "肩胛俯卧撑", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3021-jV65tKx.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "肩胛俯臥撐", "instructions_en": ["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.", "Lower your chest towards the ground, keeping your elbows close to your body.", "As you lower, squeeze your shoulder blades together and push your chest forward.", "Pause for a moment at the bottom, then push back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["从高平板支撑位置开始，双手直接放在肩膀下方，身体呈一条直线。", "将胸部压向地面，保持肘部靠近身体。", "当你下降时，将肩胛骨挤压在一起并将胸部向前推。", "在底部停顿片刻，然后推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["從高平板支撐位置開始，雙手直接放在肩膀下方，身體呈一條直線。", "將胸部壓向地面，保持肘部靠近身體。", "當你下降時，將肩胛骨擠壓在一起并將胸部向前推。", "在底部停頓片刻，然后推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0685', 'exercise', 1, '{"id": "0685", "target": "cardiovascular system", "name_en": "run", "name_zh": "跑步", "body_part": "cardio", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0685-oLrKqDH.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "跑步", "instructions_en": ["Start by standing upright with your feet hip-width apart.", "Engage your core and keep your upper body relaxed.", "Begin jogging in place, lifting your knees up towards your chest and landing softly on the balls of your feet.", "Maintain a steady pace and continue jogging for the desired duration or distance.", "Remember to breathe deeply and maintain good posture throughout the exercise."], "instructions_zh": ["首先站直，双脚分开与臀部同宽。", "启动你的核心并保持上半身放松。", "开始原地慢跑，将膝盖抬向胸部，然后轻轻落在脚掌上。", "保持稳定的步伐并继续慢跑所需的时间或距离。", "记住在整个练习过程中深呼吸并保持良好的姿势。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["首先站直，雙腳分開與臀部同寬。", "啟動你的核心并保持上半身放松。", "開始原地慢跑，將膝蓋抬向胸部，然后輕輕落在腳掌上。", "保持穩定的步伐并繼續慢跑所需的時間或距離。", "記住在整個練習過程中深呼吸并保持良好的姿勢。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0684', 'exercise', 1, '{"id": "0684", "target": "cardiovascular system", "name_en": "run (equipment)", "name_zh": "跑步（器械）", "body_part": "cardio", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0684-y5p0H8a.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "跑步（器械）", "instructions_en": ["Start by standing upright with your feet hip-width apart.", "Engage your core and keep your upper body relaxed.", "Begin jogging in place, lifting your knees up towards your chest and landing softly on the balls of your feet.", "Maintain a steady pace and continue jogging for the desired duration or distance.", "Remember to breathe deeply and maintain good posture throughout the exercise."], "instructions_zh": ["首先站直，双脚分开与臀部同宽。", "启动你的核心并保持上半身放松。", "开始原地慢跑，将膝盖抬向胸部，然后轻轻落在脚掌上。", "保持稳定的步伐并继续慢跑所需的时间或距离。", "记住在整个练习过程中深呼吸并保持良好的姿势。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["首先站直，雙腳分開與臀部同寬。", "啟動你的核心并保持上半身放松。", "開始原地慢跑，將膝蓋抬向胸部，然后輕輕落在腳掌上。", "保持穩定的步伐并繼續慢跑所需的時間或距離。", "記住在整個練習過程中深呼吸并保持良好的姿勢。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1585', 'exercise', 1, '{"id": "1585", "target": "hamstrings", "name_en": "runners stretch", "name_zh": "跑者式拉伸", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1585-0mB6wHO.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "跑者式拉伸", "instructions_en": ["Stand with your feet hip-width apart.", "Take a step forward with your right foot, keeping your left foot planted.", "Bend your right knee and lower your body down, keeping your left leg straight.", "Place your hands on your right thigh for support.", "Hold the stretch for 20-30 seconds, then switch sides and repeat."], "instructions_zh": ["双脚分开与臀部同宽站立。", "右脚向前迈出一步，保持左脚踩地。", "弯曲右膝，降低身体，保持左腿伸直。", "将双手放在右大腿上以获得支撑。", "保持拉伸 20-30 秒，然后换边重复。"], "secondary_muscles": ["calves", "quadriceps"], "instructions_zh_hant": ["雙腳分開與臀部同寬站立。", "右腳向前邁出一步，保持左腳踩地。", "彎曲右膝，降低身體，保持左腿伸直。", "將雙手放在右大腿上以獲得支撐。", "保持拉伸 20-30 秒，然后換邊重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0687', 'exercise', 1, '{"id": "0687", "target": "abs", "name_en": "russian twist", "name_zh": "俄罗斯转体", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0687-XVDdcoj.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "俄羅斯轉體", "instructions_en": ["Sit on the ground with your knees bent and feet flat on the floor.", "Lean back slightly while keeping your back straight and your core engaged.", "Hold your hands together in front of your chest or hold a weight if desired.", "Lift your feet off the ground, balancing on your sit bones.", "Twist your torso to the right, bringing your hands or weight towards the right side of your body.", "Pause for a moment, then twist your torso to the left, bringing your hands or weight towards the left side of your body.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["坐在地上，膝盖弯曲，双脚平放在地板上。", "稍微向后倾斜，同时保持背部挺直并且核心参与。", "如果需要，双手合拢放在胸前或举重物。", "将脚抬离地面，在坐骨上保持平衡。", "将你的躯干向右扭转，将你的手或重量移向身体的右侧。", "暂停片刻，然后将躯干向左扭转，将手或体重移向身体的左侧。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["obliques"], "instructions_zh_hant": ["坐在地上，膝蓋彎曲，雙腳平放在地板上。", "稍微向后傾斜，同時保持背部挺直并且核心參與。", "如果需要，雙手合攏放在胸前或舉重物。", "將腳抬離地面，在坐骨上保持平衡。", "將你的軀幹向右扭轉，將你的手或重量移向身體的右側。", "暫停片刻，然后將軀幹向左扭轉，將手或體重移向身體的左側。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3012', 'exercise', 1, '{"id": "3012", "target": "traps", "name_en": "scapula dips", "name_zh": "肩胛臂屈伸", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3012-7xeukSt.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "肩胛臂屈伸", "instructions_en": ["Start by standing with your feet shoulder-width apart and your arms extended in front of you.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Lower your body by bending your elbows and retracting your shoulder blades, as if you are trying to squeeze a pencil between them.", "Pause for a moment at the bottom, then push through your hands to extend your elbows and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先站立，双脚分开与肩同宽，双臂在身前伸展。", "稍微弯曲膝盖，髋部向前转动，保持背部挺直。", "弯曲肘部并缩回肩胛骨来降低身体，就像你试图在它们之间挤一支铅笔一样。", "在底部停顿片刻，然后双手用力，伸展肘部，回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["rhomboids", "deltoids"], "instructions_zh_hant": ["首先站立，雙腳分開與肩同寬，雙臂在身前伸展。", "稍微彎曲膝蓋，髖部向前轉動，保持背部挺直。", "彎曲肘部并縮回肩胛骨來降低身體，就像你試圖在它們之間擠一支鉛筆一樣。", "在底部停頓片刻，然后雙手用力，伸展肘部，回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0688', 'exercise', 1, '{"id": "0688", "target": "traps", "name_en": "scapular pull-up", "name_zh": "肩胛引体向上", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0688-uTBt1HV.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "肩胛引體向上", "instructions_en": ["Start by hanging from a pull-up bar with your palms facing away from you and your arms fully extended.", "Retract your shoulder blades by pulling them down and back.", "Engage your back muscles and pull your body up towards the bar, focusing on squeezing your shoulder blades together.", "Pause for a moment at the top of the movement, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先悬挂在引体向上杆上，手掌背向自己，手臂完全伸展。", "通过向下拉和向后拉动肩胛骨来缩回肩胛骨。", "启动背部肌肉，将身体拉向杠铃杆，重点是将肩胛骨挤压在一起。", "在动作的最高点停顿片刻，然后慢慢降低身体回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "rhomboids", "rear deltoids"], "instructions_zh_hant": ["首先懸掛在引體向上桿上，手掌背向自己，手臂完全伸展。", "通過向下拉和向后拉動肩胛骨來縮回肩胛骨。", "啟動背部肌肉，將身體拉向杠鈴桿，重點是將肩胛骨擠壓在一起。", "在動作的最高點停頓片刻，然后慢慢降低身體回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3219', 'exercise', 1, '{"id": "3219", "target": "cardiovascular system", "name_en": "scissor jumps (male)", "name_zh": "剪刀式跳跃（男性示范）", "body_part": "cardio", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3219-Eh2v5Iu.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "剪刀式跳躍（男性示范）", "instructions_en": ["Stand with your feet shoulder-width apart.", "Jump off the ground and simultaneously cross your right leg in front of your left leg.", "As you land, quickly switch legs, crossing your left leg in front of your right leg.", "Continue alternating legs and jumping as quickly as possible.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立。", "跳离地面，同时将右腿交叉到左腿前面。", "落地时，快速换腿，将左腿交叉在右腿前面。", "继续交替双腿并尽可能快地跳跃。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立。", "跳離地面，同時將右腿交叉到左腿前面。", "落地時，快速換腿，將左腿交叉在右腿前面。", "繼續交替雙腿并盡可能快地跳躍。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1390', 'exercise', 1, '{"id": "1390", "target": "calves", "name_en": "seated calf stretch (male)", "name_zh": "坐姿小腿拉伸（男性示范）", "body_part": "lower legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1390-17bqEXD.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "坐姿小腿拉伸（男性示范）", "instructions_en": ["Sit on the edge of a chair or bench with your feet flat on the ground.", "Extend one leg straight out in front of you, keeping your heel on the ground.", "Lean forward slightly, feeling a stretch in your calf muscle.", "Hold the stretch for 20-30 seconds.", "Switch legs and repeat the stretch."], "instructions_zh": ["坐在椅子或长凳的边缘，双脚平放在地面上。", "将一只腿伸直在身前，脚跟保持在地面上。", "稍微向前倾，感受小腿肌肉的拉伸。", "保持拉伸 20-30 秒。", "换腿并重复拉伸。"], "secondary_muscles": ["hamstrings"], "instructions_zh_hant": ["坐在椅子或長凳的邊緣，雙腳平放在地面上。", "將一只腿伸直在身前，腳跟保持在地面上。", "稍微向前傾，感受小腿肌肉的拉伸。", "保持拉伸 20-30 秒。", "換腿并重復拉伸。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1424', 'exercise', 1, '{"id": "1424", "target": "glutes", "name_en": "seated glute stretch", "name_zh": "坐姿臀部拉伸", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1424-DeDThfG.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "坐姿臀部拉伸", "instructions_en": ["Sit on the ground with your legs extended in front of you.", "Bend your right knee and cross your right ankle over your left thigh.", "Place your right hand on the ground behind you for support.", "With your left hand, gently press down on your right knee to deepen the stretch.", "Hold the stretch for 30 seconds to 1 minute.", "Switch sides and repeat."], "instructions_zh": ["坐在地上，双腿在身前伸展。", "弯曲右膝，将右脚踝交叉在左大腿上。", "将右手放在身后的地面上以获得支撑。", "用左手轻轻按下右膝盖以加深伸展。", "保持拉伸 30 秒到 1 分钟。", "换边并重复。"], "secondary_muscles": ["hamstrings"], "instructions_zh_hant": ["坐在地上，雙腿在身前伸展。", "彎曲右膝，將右腳踝交叉在左大腿上。", "將右手放在身后的地面上以獲得支撐。", "用左手輕輕按下右膝蓋以加深伸展。", "保持拉伸 30 秒到 1 分鐘。", "換邊并重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0689', 'exercise', 1, '{"id": "0689", "target": "abs", "name_en": "seated leg raise", "name_zh": "坐姿举腿", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0689-Hgs6Nl1.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "坐姿舉腿", "instructions_en": ["Sit on a flat bench with your back straight and your feet flat on the ground.", "Place your hands on the sides of the bench for support.", "Keeping your legs straight, slowly raise them up in front of you until they are parallel to the ground.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在平坦的长凳上，背部挺直，双脚平放在地面上。", "将双手放在长凳两侧以获得支撑。", "保持双腿伸直，慢慢将它们抬起到您面前，直到它们与地面平行。", "在顶部暂停片刻，然后慢慢将双腿放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["坐在平坦的長凳上，背部挺直，雙腳平放在地面上。", "將雙手放在長凳兩側以獲得支撐。", "保持雙腿伸直，慢慢將它們抬起到您面前，直到它們與地面平行。", "在頂部暫停片刻，然后慢慢將雙腿放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2567', 'exercise', 1, '{"id": "2567", "target": "glutes", "name_en": "seated piriformis stretch", "name_zh": "坐姿梨状肌拉伸", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/2567-QY39eBr.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "坐姿梨狀肌拉伸", "instructions_en": ["Sit on the ground with your legs extended in front of you.", "Bend your right knee and place your right foot on the outside of your left knee.", "Place your left elbow on the outside of your right knee and gently twist your torso to the right.", "Hold the stretch for 20-30 seconds, then switch sides and repeat."], "instructions_zh": ["坐在地上，双腿在身前伸展。", "弯曲右膝，将右脚放在左膝外侧。", "将左肘放在右膝外侧，轻轻地将躯干向右扭转。", "保持拉伸 20-30 秒，然后换边重复。"], "secondary_muscles": ["hamstrings"], "instructions_zh_hant": ["坐在地上，雙腿在身前伸展。", "彎曲右膝，將右腳放在左膝外側。", "將左肘放在右膝外側，輕輕地將軀幹向右扭轉。", "保持拉伸 20-30 秒，然后換邊重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0691', 'exercise', 1, '{"id": "0691", "target": "abs", "name_en": "seated side crunch (wall)", "name_zh": "坐姿侧卷腹（靠墙）", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0691-Y9hNPcN.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "坐姿側卷腹（靠墻）", "instructions_en": ["Sit on the floor with your back against a wall and your legs extended in front of you.", "Bend your knees and place your feet flat on the floor, hip-width apart.", "Place your hands behind your head with your elbows pointing outwards.", "Engage your abs and lean to one side, bringing your elbow towards your hip.", "Pause for a moment, then return to the starting position.", "Repeat on the other side.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["坐在地板上，背靠墙，双腿在身前伸展。", "弯曲膝盖，将双脚平放在地板上，与臀部同宽。", "将双手放在脑后，肘部朝外。", "收紧腹肌并向一侧倾斜，将肘部靠近臀部。", "暂停片刻，然后回到起始位置。", "在另一侧重复。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["obliques"], "instructions_zh_hant": ["坐在地板上，背靠墻，雙腿在身前伸展。", "彎曲膝蓋，將雙腳平放在地板上，與臀部同寬。", "將雙手放在腦后，肘部朝外。", "收緊腹肌并向一側傾斜，將肘部靠近臀部。", "暫停片刻，然后回到起始位置。", "在另一側重復。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1587', 'exercise', 1, '{"id": "1587", "target": "hamstrings", "name_en": "seated wide angle pose sequence", "name_zh": "坐姿宽距角度体式组合", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1587-HIgYKAB.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "坐姿寬距角度體式組合", "instructions_en": ["Sit on the ground with your legs extended in a wide angle.", "Flex your feet and engage your quadriceps.", "Place your hands on the ground behind you for support.", "Keeping your back straight, lean forward from your hips.", "Continue leaning forward until you feel a stretch in your hamstrings.", "Hold this position for a few breaths.", "Slowly release the stretch and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在地上，双腿大角度伸展。", "弯曲你的脚并锻炼你的股四头肌。", "将双手放在身后的地面上以获得支撑。", "保持背部挺直，从臀部向前倾。", "继续向前倾斜，直到感觉到腿筋被拉伸。", "保持这个姿势几个呼吸。", "慢慢释放拉伸并返回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "calves"], "instructions_zh_hant": ["坐在地上，雙腿大角度伸展。", "彎曲你的腳并鍛煉你的股四頭肌。", "將雙手放在身后的地面上以獲得支撐。", "保持背部挺直，從臀部向前傾。", "繼續向前傾斜，直到感覺到腿筋被拉伸。", "保持這個姿勢幾個呼吸。", "慢慢釋放拉伸并返回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0697', 'exercise', 1, '{"id": "0697", "target": "hamstrings", "name_en": "self assisted inverse leg curl", "name_zh": "自助辅助反向腿弯举", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0697-GwYwElT.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "自助輔助反向腿彎舉", "instructions_en": ["Lie flat on your back on a mat or bench with your legs extended.", "Place your hands by your sides or under your glutes for support.", "Bend your knees and lift your feet off the ground, bringing your thighs towards your chest.", "Pause for a moment at the top, then slowly lower your legs back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在垫子或长凳上，双腿伸展。", "将双手放在身体两侧或臀部下方以获得支撑。", "弯曲膝盖，将脚抬离地面，将大腿靠近胸部。", "在顶部暂停片刻，然后慢慢将双腿放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "calves"], "instructions_zh_hant": ["平躺在墊子或長凳上，雙腿伸展。", "將雙手放在身體兩側或臀部下方以獲得支撐。", "彎曲膝蓋，將腳抬離地面，將大腿靠近胸部。", "在頂部暫停片刻，然后慢慢將雙腿放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1766', 'exercise', 1, '{"id": "1766", "target": "hamstrings", "name_en": "self assisted inverse leg curl", "name_zh": "自助辅助反向腿弯举", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1766-ZSY3MsL.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "自助輔助反向腿彎舉", "instructions_en": ["Lie face down on a leg curl machine with your legs extended and your ankles hooked under the padded lever.", "Place your hands on the side handles of the machine for support.", "Keeping your upper body stationary, exhale and curl your legs upward as far as possible.", "Hold the contracted position for a brief pause as you squeeze your hamstrings.", "Slowly lower your legs back to the starting position while inhaling.", "Repeat for the desired number of repetitions."], "instructions_zh": ["面朝下躺在腿弯举机上，双腿伸展，脚踝钩在带衬垫的杠杆下。", "将双手放在机器的侧手柄上以获得支撑。", "保持上半身静止，呼气并尽可能向上弯曲双腿。", "挤压腿筋时，保持收缩位置短暂停顿。", "吸气时慢慢将双腿放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "calves"], "instructions_zh_hant": ["面朝下躺在腿彎舉機上，雙腿伸展，腳踝鉤在帶襯墊的杠桿下。", "將雙手放在機器的側手柄上以獲得支撐。", "保持上半身靜止，呼氣并盡可能向上彎曲雙腿。", "擠壓腿筋時，保持收縮位置短暫停頓。", "吸氣時慢慢將雙腿放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0696', 'exercise', 1, '{"id": "0696", "target": "hamstrings", "name_en": "self assisted inverse leg curl (on floor)", "name_zh": "自助辅助反向腿弯举（地板）", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0696-E4PwJqI.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "自助輔助反向腿彎舉（地板）", "instructions_en": ["Lie flat on your back with your legs extended and your arms by your sides.", "Bend your knees and place your feet flat on the ground, hip-width apart.", "Lift your hips off the ground, engaging your glutes and hamstrings.", "Slowly curl your legs towards your glutes, keeping your hips lifted.", "Pause for a moment at the top, then slowly extend your legs back to the starting position.", "Lower your hips back down to the ground.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，双腿伸展，双臂放在身体两侧。", "弯曲膝盖，将双脚平放在地面上，距离与臀部同宽。", "将臀部抬离地面，锻炼臀肌和腿筋。", "慢慢地将双腿向臀部弯曲，保持臀部抬起。", "在顶部停顿片刻，然后慢慢将双腿伸展回起始位置。", "将臀部放回地面。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "calves"], "instructions_zh_hant": ["平躺，雙腿伸展，雙臂放在身體兩側。", "彎曲膝蓋，將雙腳平放在地面上，距離與臀部同寬。", "將臀部抬離地面，鍛煉臀肌和腿筋。", "慢慢地將雙腿向臀部彎曲，保持臀部抬起。", "在頂部停頓片刻，然后慢慢將雙腿伸展回起始位置。", "將臀部放回地面。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3222', 'exercise', 1, '{"id": "3222", "target": "cardiovascular system", "name_en": "semi squat jump (male)", "name_zh": "半程深蹲跳跃（男性示范）", "body_part": "cardio", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3222-6FMU51h.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "半程深蹲跳躍（男性示范）", "instructions_en": ["Stand with your feet shoulder-width apart.", "Bend your knees and lower your body into a squat position.", "Jump explosively, extending your hips and knees while swinging your arms for momentum.", "Land softly on the balls of your feet and immediately go into the next repetition.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立。", "弯曲膝盖并将身体降低至蹲姿。", "爆发性跳跃，伸展臀部和膝盖，同时摆动手臂以获得动力。", "脚掌轻轻落地，然后立即进入下一个重复动作。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立。", "彎曲膝蓋并將身體降低至蹲姿。", "爆發性跳躍，伸展臀部和膝蓋，同時擺動手臂以獲得動力。", "腳掌輕輕落地，然后立即進入下一個重復動作。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3656', 'exercise', 1, '{"id": "3656", "target": "cardiovascular system", "name_en": "short stride run", "name_zh": "短程步幅跑步", "body_part": "cardio", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3656-CcWEoWV.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "短程步幅跑步", "instructions_en": ["Find an open space or a treadmill to perform the exercise.", "Stand tall with your feet hip-width apart.", "Start jogging in place, lifting your knees high and pumping your arms.", "After a few seconds, start taking short strides forward, maintaining a quick pace.", "Continue running with short strides for the desired duration or distance."], "instructions_zh": ["找一个空地或跑步机来进行锻炼。", "站直，双脚分开与臀部同宽。", "开始原地慢跑，抬起膝盖并挥动手臂。", "几秒钟后，开始小步前进，保持快速的步伐。", "继续小步跑所需的时间或距离。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["找一個空地或跑步機來進行鍛煉。", "站直，雙腳分開與臀部同寬。", "開始原地慢跑，抬起膝蓋并揮動手臂。", "幾秒鐘后，開始小步前進，保持快速的步伐。", "繼續小步跑所需的時間或距離。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1763', 'exercise', 1, '{"id": "1763", "target": "lats", "name_en": "shoulder grip pull-up", "name_zh": "肩宽握距引体向上", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1763-YtgD7Xq.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "肩寬握距引體向上", "instructions_en": ["Grab the pull-up bar with a shoulder-width grip, palms facing away from you.", "Hang freely with your arms fully extended.", "Engage your back muscles and pull your body up towards the bar until your chin is above the bar.", "Pause for a moment at the top, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["握距与肩同宽，抓住引体向上杆，手掌背向自己。", "双臂完全伸展，自由悬挂。", "启动背部肌肉，将身体向上拉向杠铃，直到下巴位于杠铃上方。", "在顶部停顿片刻，然后慢慢将身体放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["握距與肩同寬，抓住引體向上桿，手掌背向自己。", "雙臂完全伸展，自由懸掛。", "啟動背部肌肉，將身體向上拉向杠鈴，直到下巴位于杠鈴上方。", "在頂部停頓片刻，然后慢慢將身體放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3699', 'exercise', 1, '{"id": "3699", "target": "abs", "name_en": "shoulder tap", "name_zh": "平板支撑交替触肩", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3699-yRpV5TC.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "平板支撐交替觸肩", "instructions_en": ["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.", "Engage your core and lift your right hand off the ground, reaching across to tap your left shoulder.", "Place your right hand back on the ground and repeat with your left hand tapping your right shoulder.", "Continue alternating shoulder taps while keeping your hips and torso stable.", "Repeat for the desired number of repetitions."], "instructions_zh": ["从高平板支撑位置开始，双手直接放在肩膀下方，身体呈一条直线。", "启动你的核心并将右手抬离地面，伸手拍打你的左肩。", "将右手放回地面，然后用左手轻拍右肩，重复此操作。", "继续交替轻拍肩膀，同时保持臀部和躯干稳定。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["從高平板支撐位置開始，雙手直接放在肩膀下方，身體呈一條直線。", "啟動你的核心并將右手抬離地面，伸手拍打你的左肩。", "將右手放回地面，然后用左手輕拍右肩，重復此操作。", "繼續交替輕拍肩膀，同時保持臀部和軀幹穩定。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0699', 'exercise', 1, '{"id": "0699", "target": "pectorals", "name_en": "shoulder tap push-up", "name_zh": "肩部点触俯卧撑", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0699-qEse6fe.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "肩部點觸俯臥撐", "instructions_en": ["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels.", "Lower your body towards the ground by bending your elbows, keeping them close to your sides.", "As you push back up, lift your right hand off the ground and tap your left shoulder.", "Return your right hand to the ground and repeat the push-up, this time lifting your left hand and tapping your right shoulder.", "Continue alternating shoulder taps with each push-up repetition.", "Maintain a stable core and avoid excessive hip rotation throughout the exercise.", "Repeat for the desired number of repetitions."], "instructions_zh": ["从高位平板支撑开始，双手分开略宽于肩宽，身体从头到脚跟呈一条直线。", "弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。", "当你向后推时，将右手抬离地面并轻拍左肩。", "将右手放回地面并重复俯卧撑，这次抬起左手并拍打右肩。", "每次重复俯卧撑时，继续交替拍肩。", "在整个练习过程中保持核心稳定并避免臀部过度旋转。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "core"], "instructions_zh_hant": ["從高位平板支撐開始，雙手分開略寬于肩寬，身體從頭到腳跟呈一條直線。", "彎曲肘部，使肘部靠近身體兩側，將身體降低到地面。", "當你向后推時，將右手抬離地面并輕拍左肩。", "將右手放回地面并重復俯臥撐，這次抬起左手并拍打右肩。", "每次重復俯臥撐時，繼續交替拍肩。", "在整個練習過程中保持核心穩定并避免臀部過度旋轉。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1774', 'exercise', 1, '{"id": "1774", "target": "abductors", "name_en": "side bridge hip abduction", "name_zh": "侧桥式髋部外展", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1774-WL4EmxJ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "側橋式髖部外展", "instructions_en": ["Lie on your side with your legs extended and stacked on top of each other.", "Prop yourself up on your forearm, keeping your elbow directly below your shoulder.", "Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.", "While keeping your core engaged, lift your top leg as high as possible without rotating your hips.", "Pause for a moment at the top, then lower your leg back down.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["侧躺，双腿伸展并叠放在一起。", "用前臂支撑自己，将肘部保持在肩膀正下方。", "启动你的核心并将臀部抬离地面，从头到脚形成一条直线。", "在保持核心肌群参与的同时，尽可能高地抬起上面的那条腿，但不要旋转臀部。", "在顶部停顿片刻，然后将腿放下。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["glutes", "obliques"], "instructions_zh_hant": ["側躺，雙腿伸展并疊放在一起。", "用前臂支撐自己，將肘部保持在肩膀正下方。", "啟動你的核心并將臀部抬離地面，從頭到腳形成一條直線。", "在保持核心肌群參與的同時，盡可能高地抬起上面的那條腿，但不要旋轉臀部。", "在頂部停頓片刻，然后將腿放下。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0705', 'exercise', 1, '{"id": "0705", "target": "abs", "name_en": "side bridge v. 2", "name_zh": "侧桥式变式2", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0705-RKjH6Lt.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "側橋式變式2", "instructions_en": ["Lie on your side with your legs extended and stacked on top of each other.", "Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.", "Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.", "Hold this position for the desired amount of time.", "Lower your hips back down to the starting position.", "Repeat on the other side."], "instructions_zh": ["侧躺，双腿伸展并叠放在一起。", "将前臂放在肩膀正下方的地面上，肘部弯曲成 90 度角。", "启动你的核心并将臀部抬离地面，从头到脚形成一条直线。", "保持此位置所需的时间。", "将臀部放低至起始位置。", "在另一侧重复。"], "secondary_muscles": ["obliques", "glutes"], "instructions_zh_hant": ["側躺，雙腿伸展并疊放在一起。", "將前臂放在肩膀正下方的地面上，肘部彎曲成 90 度角。", "啟動你的核心并將臀部抬離地面，從頭到腳形成一條直線。", "保持此位置所需的時間。", "將臀部放低至起始位置。", "在另一側重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0709', 'exercise', 1, '{"id": "0709", "target": "abs", "name_en": "side hip (on parallel bars)", "name_zh": "双杠侧向提髋", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0709-jTkSc6o.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "雙槓側向提髖", "instructions_en": ["Stand between two parallel bars with your feet shoulder-width apart.", "Place your hands on the bars and lift your body off the ground, supporting your weight on your arms.", "Engage your abs and slowly lift your legs to the side, keeping them straight.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站在两根平行杠之间，双脚分开与肩同宽。", "将双手放在横杆上，将身体抬离地面，用手臂支撑体重。", "收紧腹肌，慢慢将双腿向一侧抬起，保持伸直。", "在顶部暂停片刻，然后慢慢将双腿放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["obliques", "hip flexors"], "instructions_zh_hant": ["站在兩根平行杠之間，雙腳分開與肩同寬。", "將雙手放在橫桿上，將身體抬離地面，用手臂支撐體重。", "收緊腹肌，慢慢將雙腿向一側抬起，保持伸直。", "在頂部暫停片刻，然后慢慢將雙腿放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0754', 'exercise', 1, '{"id": "0754", "target": "pectorals", "name_en": "smith decline reverse-grip press", "name_zh": "史密斯机下斜反握推举", "body_part": "chest", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/0754-MY9P1WA.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機下斜反握推舉", "instructions_en": ["Adjust the smith machine to a decline position.", "Lie down on the bench with your feet secured under the foot pads.", "Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.", "Unrack the barbell and lower it towards your chest, keeping your elbows tucked in.", "Pause for a moment at the bottom, then push the barbell back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将史密斯机调整至下降位置。", "躺在长凳上，双脚固定在脚垫下。", "反握抓住杠铃，双手分开略宽于肩宽。", "松开杠铃并将其向胸部降低，保持肘部内收。", "在底部停顿片刻，然后将杠铃推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["將史密斯機調整至下降位置。", "躺在長凳上，雙腳固定在腳墊下。", "反握抓住杠鈴，雙手分開略寬于肩寬。", "松開杠鈴并將其向胸部降低，保持肘部內收。", "在底部停頓片刻，然后將杠鈴推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0710', 'exercise', 1, '{"id": "0710", "target": "abductors", "name_en": "side hip abduction", "name_zh": "侧髋部外展", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0710-7WaDzyL.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "側髖部外展", "instructions_en": ["Stand with your feet shoulder-width apart and your hands on your hips.", "Shift your weight to one leg and lift the opposite leg out to the side, keeping it straight.", "Pause for a moment at the top, then slowly lower your leg back down to the starting position.", "Repeat on the other side.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手放在臀部。", "将重心转移到一条腿上，并将另一条腿向一侧抬起，保持伸直。", "在顶部暂停片刻，然后慢慢将腿放回起始位置。", "在另一侧重复。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["glutes", "quadriceps"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手放在臀部。", "將重心轉移到一條腿上，并將另一條腿向一側抬起，保持伸直。", "在頂部暫停片刻，然后慢慢將腿放回起始位置。", "在另一側重復。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1358', 'exercise', 1, '{"id": "1358", "target": "lats", "name_en": "side lying floor stretch", "name_zh": "侧卧地板拉伸", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1358-jDOKRM5.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "側臥地板拉伸", "instructions_en": ["Lie on your side with your legs straight and your bottom arm extended straight overhead.", "Bend your top knee and place your foot on the ground in front of your bottom leg.", "Reach your top arm over your head and grab onto something stable, like a wall or a piece of furniture.", "Slowly lift your bottom leg off the ground, keeping it straight, until you feel a stretch in your side.", "Hold the stretch for 20-30 seconds, then slowly lower your leg back down.", "Repeat on the other side."], "instructions_zh": ["侧躺，双腿伸直，下臂伸直过头顶。", "弯曲上面的膝盖，将脚放在下面的腿前面的地面上。", "将上臂伸过头顶，抓住稳定的东西，例如墙壁或一件家具。", "慢慢地将下面的腿抬离地面，保持伸直，直到感觉到身体一侧有拉伸感。", "保持拉伸 20-30 秒，然后慢慢将腿放下。", "在另一侧重复。"], "secondary_muscles": ["obliques", "glutes"], "instructions_zh_hant": ["側躺，雙腿伸直，下臂伸直過頭頂。", "彎曲上面的膝蓋，將腳放在下面的腿前面的地面上。", "將上臂伸過頭頂，抓住穩定的東西，例如墻壁或一件家具。", "慢慢地將下面的腿抬離地面，保持伸直，直到感覺到身體一側有拉伸感。", "保持拉伸 20-30 秒，然后慢慢將腿放下。", "在另一側重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3667', 'exercise', 1, '{"id": "3667", "target": "adductors", "name_en": "side lying hip adduction (male)", "name_zh": "侧卧髋部内收（男性示范）", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3667-c8f5cSY.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "側臥髖部內收（男性示范）", "instructions_en": ["Lie on your side with your legs straight and stacked on top of each other.", "Place your bottom arm under your head for support.", "Engage your adductors and lift your top leg as high as possible without rotating your hips or leaning backward.", "Pause for a moment at the top, then slowly lower your leg back down to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["侧躺，双腿伸直并叠放在一起。", "将下臂放在头下方以获得支撑。", "启动内收肌并尽可能高地抬起上面的腿，但不要旋转臀部或向后倾斜。", "在顶部暂停片刻，然后慢慢将腿放回起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["glutes", "hamstrings"], "instructions_zh_hant": ["側躺，雙腿伸直并疊放在一起。", "將下臂放在頭下方以獲得支撐。", "啟動內收肌并盡可能高地抬起上面的腿，但不要旋轉臀部或向后傾斜。", "在頂部暫停片刻，然后慢慢將腿放回起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1775', 'exercise', 1, '{"id": "1775", "target": "adductors", "name_en": "side plank hip adduction", "name_zh": "侧平板支撑髋部内收", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1775-VO2qeJg.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "側平板支撐髖部內收", "instructions_en": ["Start by lying on your side with your legs extended and stacked on top of each other.", "Prop yourself up on your forearm, keeping your elbow directly below your shoulder.", "Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.", "While maintaining the side plank position, lift your top leg towards the ceiling, keeping it straight.", "Slowly lower your leg back down to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["首先侧躺，双腿伸展并叠放在一起。", "用前臂支撑自己，将肘部保持在肩膀正下方。", "启动你的核心并将臀部抬离地面，从头到脚形成一条直线。", "在保持侧平板支撑位置的同时，将上面的腿抬向天花板，保持笔直。", "慢慢地将腿放回起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["obliques", "glutes"], "instructions_zh_hant": ["首先側躺，雙腿伸展并疊放在一起。", "用前臂支撐自己，將肘部保持在肩膀正下方。", "啟動你的核心并將臀部抬離地面，從頭到腳形成一條直線。", "在保持側平板支撐位置的同時，將上面的腿抬向天花板，保持筆直。", "慢慢地將腿放回起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0716', 'exercise', 1, '{"id": "0716", "target": "levator scapulae", "name_en": "side push neck stretch", "name_zh": "侧推颈部拉伸", "body_part": "neck", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0716-oQRJYkC.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "側推頸部拉伸", "instructions_en": ["Stand or sit up straight with your shoulders relaxed.", "Tilt your head to the right, bringing your right ear towards your right shoulder.", "Place your right hand on the left side of your head and gently apply pressure to increase the stretch.", "Hold the stretch for 15-30 seconds.", "Repeat on the other side, tilting your head to the left and applying pressure with your left hand.", "Repeat the stretch 2-3 times on each side."], "instructions_zh": ["站直或坐直，肩膀放松。", "将头向右倾斜，将右耳靠近右肩。", "将右手放在头部左侧，轻轻施加压力以增加拉伸。", "保持拉伸 15-30 秒。", "在另一侧重复，将头向左倾斜并用左手施加压力。", "每侧重复拉伸 2-3 次。"], "secondary_muscles": ["trapezius", "sternocleidomastoid"], "instructions_zh_hant": ["站直或坐直，肩膀放松。", "將頭向右傾斜，將右耳靠近右肩。", "將右手放在頭部左側，輕輕施加壓力以增加拉伸。", "保持拉伸 15-30 秒。", "在另一側重復，將頭向左傾斜并用左手施加壓力。", "每側重復拉伸 2-3 次。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0717', 'exercise', 1, '{"id": "0717", "target": "triceps", "name_en": "side push-up", "name_zh": "侧俯卧撑", "body_part": "upper arms", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0717-wpbD28t.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "側俯臥撐", "instructions_en": ["Start by lying on your side with your legs extended and stacked on top of each other.", "Place your bottom hand on the ground directly under your shoulder, fingers pointing forward.", "Press through your bottom hand to lift your body off the ground, keeping your legs straight and your core engaged.", "Extend your top arm straight up towards the ceiling, creating a straight line from your head to your heels.", "Lower your body back down to the starting position with control.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["首先侧躺，双腿伸展并叠放在一起。", "将下面的手放在肩膀正下方的地面上，手指指向前方。", "用下面的手将身体抬离地面，保持双腿伸直，核心肌群参与。", "将上臂伸向天花板，形成从头部到脚后跟的直线。", "有控制地降低身体回到起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["shoulders", "chest", "core"], "instructions_zh_hant": ["首先側躺，雙腿伸展并疊放在一起。", "將下面的手放在肩膀正下方的地面上，手指指向前方。", "用下面的手將身體抬離地面，保持雙腿伸直，核心肌群參與。", "將上臂伸向天花板，形成從頭部到腳后跟的直線。", "有控制地降低身體回到起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0721', 'exercise', 1, '{"id": "0721", "target": "forearms", "name_en": "side wrist pull stretch", "name_zh": "侧向腕部牵拉", "body_part": "lower arms", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0721-UtmIqcI.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "側向腕部牽拉", "instructions_en": ["Stand with your feet shoulder-width apart and your arms extended in front of you.", "Extend your right arm out to the side, parallel to the ground, with your palm facing down.", "With your left hand, grab your right hand and gently pull it towards your body, feeling a stretch in your right forearm.", "Hold the stretch for 15-30 seconds, then release.", "Repeat on the other side."], "instructions_zh": ["双脚分开与肩同宽站立，双臂在身前伸展。", "将右臂向侧面伸出，与地面平行，手掌朝下。", "用左手抓住右手，轻轻地将其拉向身体，感觉右前臂有拉伸感。", "保持拉伸 15-30 秒，然后放松。", "在另一侧重复。"], "secondary_muscles": ["wrists", "hands"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙臂在身前伸展。", "將右臂向側面伸出，與地面平行，手掌朝下。", "用左手抓住右手，輕輕地將其拉向身體，感覺右前臂有拉伸感。", "保持拉伸 15-30 秒，然后放松。", "在另一側重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0720', 'exercise', 1, '{"id": "0720", "target": "lats", "name_en": "side-to-side chin", "name_zh": "左右交替引体向上", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0720-isAAZWA.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "左右交替引體向上", "instructions_en": ["Stand with your feet shoulder-width apart and your knees slightly bent.", "Grasp a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.", "Hang from the bar with your arms fully extended and your body relaxed.", "Pull yourself up by bending your elbows and bringing your chin towards the bar, while keeping your body straight.", "Once your chin is above the bar, lower yourself back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，膝盖稍微弯曲。", "正手握住引体向上杆，双手之间的距离略大于肩宽。", "悬挂在杠上，双臂完全伸展，身体放松。", "弯曲肘部并将下巴朝向杠铃杆，将自己拉起，同时保持身体挺直。", "一旦你的下巴高于杠铃，就将自己放低回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，膝蓋稍微彎曲。", "正手握住引體向上桿，雙手之間的距離略大于肩寬。", "懸掛在杠上，雙臂完全伸展，身體放松。", "彎曲肘部并將下巴朝向杠鈴桿，將自己拉起，同時保持身體挺直。", "一旦你的下巴高于杠鈴，就將自己放低回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3213', 'exercise', 1, '{"id": "3213", "target": "abs", "name_en": "side-to-side toe touch (male)", "name_zh": "左右交替触脚尖（男性示范）", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3213-WCAvOfC.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "左右交替觸腳尖（男性示范）", "instructions_en": ["Stand with your feet shoulder-width apart and your arms extended to the sides.", "Bend at the waist to the right, reaching your right hand towards your right foot while keeping your left hand extended to the side.", "Return to the starting position and then bend at the waist to the left, reaching your left hand towards your left foot while keeping your right hand extended to the side.", "Repeat the side-to-side bending motion for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双臂向两侧伸展。", "腰部向右弯曲，将右手伸向右脚，同时保持左手向一侧延伸。", "返回起始位置，然后腰部向左弯曲，将左手伸向左脚，同时保持右手向侧面延伸。", "重复左右弯曲动作达到所需的重复次数。"], "secondary_muscles": ["obliques", "hip flexors"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙臂向兩側伸展。", "腰部向右彎曲，將右手伸向右腳，同時保持左手向一側延伸。", "返回起始位置，然后腰部向左彎曲，將左手伸向左腳，同時保持右手向側面延伸。", "重復左右彎曲動作達到所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0725', 'exercise', 1, '{"id": "0725", "target": "pectorals", "name_en": "single arm push-up", "name_zh": "单臂俯卧撑", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0725-MUic5zN.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "單臂俯臥撐", "instructions_en": ["Start in a push-up position with your hands shoulder-width apart and one hand placed slightly wider than the other.", "Engage your core and lower your body towards the ground by bending your elbows, keeping your back straight.", "As you lower yourself, shift your weight to one side and lift the opposite arm off the ground, extending it straight out to the side.", "Push through your chest and triceps to raise your body back up to the starting position, while simultaneously lowering your extended arm back to the ground.", "Repeat the movement, alternating the arm you extend with each repetition."], "instructions_zh": ["从俯卧撑位置开始，双手分开与肩同宽，一只手比另一只手稍宽。", "弯曲肘部，保持背部挺直，调动核心力量，将身体降低至地面。", "当你降低身体时，将你的重心转移到一侧，并将另一只手臂抬离地面，将其笔直延伸到一侧。", "推动胸部和三头肌，将身体抬回到起始位置，同时将伸出的手臂放回地面。", "重复该动作，每次重复时交替伸展手臂。"], "secondary_muscles": ["triceps", "shoulders", "core"], "instructions_zh_hant": ["從俯臥撐位置開始，雙手分開與肩同寬，一只手比另一只手稍寬。", "彎曲肘部，保持背部挺直，調動核心力量，將身體降低至地面。", "當你降低身體時，將你的重心轉移到一側，并將另一只手臂抬離地面，將其筆直延伸到一側。", "推動胸部和三頭肌，將身體抬回到起始位置，同時將伸出的手臂放回地面。", "重復該動作，每次重復時交替伸展手臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3304', 'exercise', 1, '{"id": "3304", "target": "upper back", "name_en": "skin the cat", "name_zh": "吊环穿身翻转", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3304-MSfvriJ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "吊環穿身翻轉", "instructions_en": ["Start by hanging from a bar with your arms fully extended and your body relaxed.", "Engage your core and lift your legs up, bringing your knees towards your chest.", "Continue to lift your legs up and over your head, allowing your body to pass through the arms.", "Once your legs are fully extended over your head, begin to lower them back down towards the starting position.", "As you lower your legs, allow your body to pass back through the arms until you are hanging with your arms fully extended again.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先，将双臂完全伸展，身体放松地悬挂在杆上。", "收紧核心并抬起双腿，使膝盖靠近胸部。", "继续将双腿举过头顶，让身体穿过手臂。", "一旦双腿完全伸过头顶，就开始将它们放回起始位置。", "当你降低双腿时，让你的身体通过手臂向后移动，直到你再次完全伸展手臂悬挂。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "core"], "instructions_zh_hant": ["首先，將雙臂完全伸展，身體放松地懸掛在桿上。", "收緊核心并抬起雙腿，使膝蓋靠近胸部。", "繼續將雙腿舉過頭頂，讓身體穿過手臂。", "一旦雙腿完全伸過頭頂，就開始將它們放回起始位置。", "當你降低雙腿時，讓你的身體通過手臂向后移動，直到你再次完全伸展手臂懸掛。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3645', 'exercise', 1, '{"id": "3645", "target": "glutes", "name_en": "single leg bridge with outstretched leg", "name_zh": "单腿桥式配合伸展腿部", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3645-rmEukuS.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "單腿橋式配合伸展腿部", "instructions_en": ["Lie on your back with your knees bent and feet flat on the ground.", "Extend one leg straight out in front of you.", "Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.", "Hold for a moment at the top, then slowly lower your hips back down to the starting position.", "Repeat for the desired number of repetitions, then switch legs."], "instructions_zh": ["仰卧，膝盖弯曲，双脚平放在地上。", "将一条腿伸直在您面前。", "收紧臀部并将臀部抬离地面，从膝盖到肩膀形成一条直线。", "在顶部保持片刻，然后慢慢将臀部放回起始位置。", "重复所需的重复次数，然后换腿。"], "secondary_muscles": ["hamstrings", "quadriceps"], "instructions_zh_hant": ["仰臥，膝蓋彎曲，雙腳平放在地上。", "將一條腿伸直在您面前。", "收緊臀部并將臀部抬離地面，從膝蓋到肩膀形成一條直線。", "在頂部保持片刻，然后慢慢將臀部放回起始位置。", "重復所需的重復次數，然后換腿。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0727', 'exercise', 1, '{"id": "0727", "target": "calves", "name_en": "single leg calf raise (on a dumbbell)", "name_zh": "单腿提踵（于哑铃）", "body_part": "lower legs", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0727-fKZgDEO.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "單腿提踵（于啞鈴）", "instructions_en": ["Stand with your feet hip-width apart and hold a dumbbell in one hand.", "Lift one foot off the ground and balance on the other foot.", "Slowly raise your heel as high as possible, using your calf muscles.", "Pause for a moment at the top, then slowly lower your heel back down.", "Repeat for the desired number of repetitions, then switch to the other leg."], "instructions_zh": ["双脚分开与臀部同宽站立，一只手握住哑铃。", "将一只脚抬离地面并用另一只脚保持平衡。", "使用小腿肌肉，慢慢地将脚跟抬高，尽可能高。", "在顶部停顿片刻，然后慢慢降低脚跟。", "重复所需的重复次数，然后换另一条腿。"], "secondary_muscles": ["ankles", "feet"], "instructions_zh_hant": ["雙腳分開與臀部同寬站立，一只手握住啞鈴。", "將一只腳抬離地面并用另一只腳保持平衡。", "使用小腿肌肉，慢慢地將腳跟抬高，盡可能高。", "在頂部停頓片刻，然后慢慢降低腳跟。", "重復所需的重復次數，然后換另一條腿。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0730', 'exercise', 1, '{"id": "0730", "target": "hamstrings", "name_en": "single leg platform slide", "name_zh": "单腿平台滑动", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0730-LNE3wfo.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "單腿平臺滑動", "instructions_en": ["Start by standing with one foot on a platform or slide board.", "Bend your knee slightly and slide the foot on the platform backward, extending your leg.", "Keep your core engaged and maintain a straight posture throughout the movement.", "Slowly return to the starting position by sliding your foot back to the initial position.", "Repeat the movement for the desired number of repetitions, then switch legs."], "instructions_zh": ["首先将一只脚站在平台或滑板上。", "稍微弯曲膝盖，将脚向后滑动到平台上，伸展腿。", "在整个运动过程中保持核心参与并保持笔直姿势。", "将脚滑回初始位置，慢慢返回起始位置。", "重复该动作达到所需的重复次数，然后换腿。"], "secondary_muscles": ["glutes", "quadriceps"], "instructions_zh_hant": ["首先將一只腳站在平臺或滑板上。", "稍微彎曲膝蓋，將腳向后滑動到平臺上，伸展腿。", "在整個運動過程中保持核心參與并保持筆直姿勢。", "將腳滑回初始位置，慢慢返回起始位置。", "重復該動作達到所需的重復次數，然后換腿。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1759', 'exercise', 1, '{"id": "1759", "target": "glutes", "name_en": "single leg squat (pistol) male", "name_zh": "单腿深蹲（手枪式）男性示范", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1759-nqs5HGV.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "單腿深蹲（手槍式）男性示范", "instructions_en": ["Stand with your feet shoulder-width apart and arms extended in front of you.", "Lift your right foot off the ground and extend it forward.", "Slowly lower your body down by bending your left knee and pushing your hips back.", "Keep your chest up and your back straight as you lower yourself down.", "Lower until your left thigh is parallel to the ground, or as low as you can comfortably go.", "Pause for a moment at the bottom, then push through your left heel to return to the starting position.", "Repeat for the desired number of repetitions, then switch legs."], "instructions_zh": ["双脚分开与肩同宽站立，双臂在身前伸展。", "将右脚抬离地面并向前伸展。", "弯曲左膝并将臀部向后推，慢慢降低身体。", "降低身体时，保持挺胸、背部挺直。", "降低直到左大腿与地面平行，或者尽可能降低到您能舒服的高度。", "在底部停顿片刻，然后推动左脚跟回到起始位置。", "重复所需的重复次数，然后换腿。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙臂在身前伸展。", "將右腳抬離地面并向前伸展。", "彎曲左膝并將臀部向后推，慢慢降低身體。", "降低身體時，保持挺胸、背部挺直。", "降低直到左大腿與地面平行，或者盡可能降低到您能舒服的高度。", "在底部停頓片刻，然后推動左腳跟回到起始位置。", "重復所需的重復次數，然后換腿。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1425', 'exercise', 1, '{"id": "1425", "target": "glutes", "name_en": "sled 45 degrees one leg press", "name_zh": "蹬腿机45度单腿推举", "body_part": "upper legs", "equipment": "sled machine", "gif_asset": "assets/fitness/videos/1425-WWD6FzI.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "蹬腿機45度單腿推舉", "instructions_en": ["Adjust the sled machine to a 45-degree angle.", "Sit on the sled machine with your back against the pad and your feet on the footplate.", "Place one foot on the footplate and extend your leg, pushing the sled away from you.", "Slowly bend your knee and lower the sled back to the starting position.", "Repeat with the other leg.", "Continue alternating legs for the desired number of repetitions."], "instructions_zh": ["将雪橇机调整至 45 度角。", "坐在雪橇机上，背部靠在垫子上，双脚放在踏板上。", "将一只脚放在踏板上并伸展腿，将雪橇推离您。", "慢慢弯曲膝盖，将雪橇放回起始位置。", "换另一条腿重复上述步骤。", "继续交替双腿达到所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["將雪橇機調整至 45 度角。", "坐在雪橇機上，背部靠在墊子上，雙腳放在踏板上。", "將一只腳放在踏板上并伸展腿，將雪橇推離您。", "慢慢彎曲膝蓋，將雪橇放回起始位置。", "換另一條腿重復上述步驟。", "繼續交替雙腿達到所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1489', 'exercise', 1, '{"id": "1489", "target": "quads", "name_en": "sissy squat", "name_zh": "西西式深蹲", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1489-xdYPUtE.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "西西式深蹲", "instructions_en": ["Stand with your feet shoulder-width apart and your toes pointing slightly outward.", "Hold onto a stable object for balance if needed.", "Slowly lower your body by bending your knees and leaning back, keeping your torso upright.", "Continue lowering until your thighs are parallel to the ground or as far as you can comfortably go.", "Pause for a moment, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，脚趾稍微向外。", "如果需要，请抓住一个稳定的物体以保持平衡。", "弯曲膝盖并向后倾斜，慢慢降低身体，保持躯干直立。", "继续降低，直到大腿与地面平行或尽可能舒适地下降。", "暂停片刻，然后用力推动脚后跟，回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["calves", "glutes"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，腳趾稍微向外。", "如果需要，請抓住一個穩定的物體以保持平衡。", "彎曲膝蓋并向后傾斜，慢慢降低身體，保持軀幹直立。", "繼續降低，直到大腿與地面平行或盡可能舒適地下降。", "暫停片刻，然后用力推動腳后跟，回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3679', 'exercise', 1, '{"id": "3679", "target": "abs", "name_en": "sit-up with arms on chest", "name_zh": "抱胸仰卧起坐", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3679-6ZCiYWQ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "抱胸仰臥起坐", "instructions_en": ["Lie flat on your back with your knees bent and feet flat on the ground.", "Cross your arms over your chest.", "Engaging your abs, lift your upper body off the ground towards your knees.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，膝盖弯曲，双脚平放在地上。", "双臂交叉于胸前。", "收紧腹肌，将上半身抬离地面，靠近膝盖。", "在顶部停顿片刻，然后慢慢将上半身放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["平躺，膝蓋彎曲，雙腳平放在地上。", "雙臂交叉于胸前。", "收緊腹肌，將上半身抬離地面，靠近膝蓋。", "在頂部停頓片刻，然后慢慢將上半身放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3361', 'exercise', 1, '{"id": "3361", "target": "cardiovascular system", "name_en": "skater hops", "name_zh": "滑冰式跳步", "body_part": "cardio", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3361-zfNHMN9.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "滑冰式跳步", "instructions_en": ["Stand with your feet shoulder-width apart.", "Bend your knees slightly and jump to the right, landing on your right foot.", "As you land, swing your left leg behind your right leg and tap the ground with your left toes.", "Immediately jump to the left, landing on your left foot.", "As you land, swing your right leg behind your left leg and tap the ground with your right toes.", "Continue alternating sides, jumping and tapping the ground with each leg.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立。", "稍微弯曲膝盖，向右跳，右脚着地。", "落地时，将左腿摆动到右腿后面，并用左脚趾敲击地面。", "立即向左侧跳跃，左脚着地。", "落地时，将右腿摆动到左腿后面，并用右脚趾敲击地面。", "继续交替两侧，跳跃并用每条腿敲击地面。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "glutes", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立。", "稍微彎曲膝蓋，向右跳，右腳著地。", "落地時，將左腿擺動到右腿后面，并用左腳趾敲擊地面。", "立即向左側跳躍，左腳著地。", "落地時，將右腿擺動到左腿后面，并用右腳趾敲擊地面。", "繼續交替兩側，跳躍并用每條腿敲擊地面。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1360', 'exercise', 1, '{"id": "1360", "target": "upper back", "name_en": "smith one arm row", "name_zh": "史密斯机单臂划船", "body_part": "back", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/1360-Q4DSJPC.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機單臂劃船", "instructions_en": ["Adjust the height of the smith machine bar to waist level.", "Stand facing the smith machine with your feet shoulder-width apart.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Grasp the bar with one hand using an overhand grip, with your palm facing down.", "Keep your elbow close to your body and pull the bar towards your waist, squeezing your shoulder blades together.", "Pause for a moment at the top of the movement, then slowly lower the bar back to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."], "instructions_zh": ["将史密斯机杆的高度调整至腰部水平。", "面对史密斯机站立，双脚与肩同宽。", "稍微弯曲膝盖，髋部向前转动，保持背部挺直。", "用一只手正手握住杠铃，手掌朝下。", "保持肘部靠近身体，将杠铃拉向腰部，将肩胛骨挤压在一起。", "在动作的最高点暂停片刻，然后慢慢将杠铃放回起始位置。", "重复所需的重复次数，然后换到另一只手臂。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["將史密斯機桿的高度調整至腰部水平。", "面對史密斯機站立，雙腳與肩同寬。", "稍微彎曲膝蓋，髖部向前轉動，保持背部挺直。", "用一只手正手握住杠鈴，手掌朝下。", "保持肘部靠近身體，將杠鈴拉向腰部，將肩胛骨擠壓在一起。", "在動作的最高點暫停片刻，然后慢慢將杠鈴放回起始位置。", "重復所需的重復次數，然后換到另一只手臂。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2142', 'exercise', 1, '{"id": "2142", "target": "triceps", "name_en": "ski ergometer", "name_zh": "滑雪功率车", "body_part": "upper arms", "equipment": "skierg machine", "gif_asset": "assets/fitness/videos/2142-vpQaQkH.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "滑雪功率車", "instructions_en": ["Adjust the seat height and footrests to a comfortable position.", "Grasp the handles with an overhand grip, palms facing down.", "Sit up straight with your feet flat on the footrests.", "Extend your arms straight out in front of you, keeping your elbows slightly bent.", "Engage your triceps and push the handles down towards your thighs.", "Pause for a moment at the bottom, then slowly return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将座椅高度和脚踏板调整到舒适的位置。", "正手握住手柄，手掌朝下。", "坐直，双脚平放在脚踏板上。", "将手臂伸直在身前，保持肘部稍微弯曲。", "收紧三头肌并将手柄向下推向大腿。", "在底部停顿片刻，然后慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "forearms"], "instructions_zh_hant": ["將座椅高度和腳踏板調整到舒適的位置。", "正手握住手柄，手掌朝下。", "坐直，雙腳平放在腳踏板上。", "將手臂伸直在身前，保持肘部稍微彎曲。", "收緊三頭肌并將手柄向下推向大腿。", "在底部停頓片刻，然后慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3671', 'exercise', 1, '{"id": "3671", "target": "cardiovascular system", "name_en": "ski step", "name_zh": "滑雪踏步", "body_part": "cardio", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3671-5MRH8H2.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "滑雪踏步", "instructions_en": ["Stand with your feet shoulder-width apart.", "Bend your knees slightly and keep your back straight.", "Jump to the right, landing on your right foot while swinging your left leg behind your right leg.", "Immediately jump to the left, landing on your left foot while swinging your right leg behind your left leg.", "Continue alternating jumps from side to side, mimicking a skiing motion.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立。", "稍微弯曲膝盖并保持背部挺直。", "跳到右侧，右脚着地，同时将左腿摆动到右腿后面。", "立即向左侧跳，左脚着地，同时将右腿摆动到左腿后面。", "继续从一侧到另一侧交替跳跃，模仿滑雪动作。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "glutes", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立。", "稍微彎曲膝蓋并保持背部挺直。", "跳到右側，右腳著地，同時將左腿擺動到右腿后面。", "立即向左側跳，左腳著地，同時將右腿擺動到左腿后面。", "繼續從一側到另一側交替跳躍，模仿滑雪動作。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0738', 'exercise', 1, '{"id": "0738", "target": "calves", "name_en": "sled 45в° calf press", "name_zh": "蹬腿机45°小腿推举", "body_part": "lower legs", "equipment": "sled machine", "gif_asset": "assets/fitness/videos/0738-qCNVnaU.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "蹬腿機45°小腿推舉", "instructions_en": ["Adjust the sled machine to a 45-degree angle.", "Place your feet on the sled platform with your toes pointing forward.", "Push the sled platform away from you by extending your ankles and calves.", "Pause for a moment at the top, then slowly lower the sled platform back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将雪橇机调整至 45 度角。", "将脚放在雪橇平台上，脚趾朝前。", "伸展脚踝和小腿，将雪橇平台推离您。", "在顶部暂停片刻，然后慢慢将雪橇平台放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings"], "instructions_zh_hant": ["將雪橇機調整至 45 度角。", "將腳放在雪橇平臺上，腳趾朝前。", "伸展腳踝和小腿，將雪橇平臺推離您。", "在頂部暫停片刻，然后慢慢將雪橇平臺放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1464', 'exercise', 1, '{"id": "1464", "target": "glutes", "name_en": "sled 45в° leg press (back pov)", "name_zh": "蹬腿机45°腿举（背面视角）", "body_part": "upper legs", "equipment": "sled machine", "gif_asset": "assets/fitness/videos/1464-yn2lLSI.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "蹬腿機45°腿舉（背面視角）", "instructions_en": ["Adjust the seat of the sled machine so that your knees are at a 45-degree angle.", "Sit on the sled machine with your back against the backrest and your feet shoulder-width apart on the footplate.", "Grip the handles on the sides of the seat for stability.", "Push the footplate away from your body by extending your legs, keeping your heels on the footplate.", "Pause for a moment at the fully extended position.", "Slowly bend your knees and lower the footplate back towards your body, controlling the movement.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整雪橇机的座椅，使膝盖成45度角。", "坐在雪橇机上，背部靠在靠背上，双脚与肩同宽放在踏板上。", "握住座椅两侧的把手以保持稳定性。", "伸展双腿，将脚踏板推离身体，脚后跟保持在脚踏板上。", "在完全伸展的位置暂停片刻。", "慢慢弯曲膝盖，将踏板放回到身体的方向，控制动作。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["調整雪橇機的座椅，使膝蓋成45度角。", "坐在雪橇機上，背部靠在靠背上，雙腳與肩同寬放在踏板上。", "握住座椅兩側的把手以保持穩定性。", "伸展雙腿，將腳踏板推離身體，腳后跟保持在腳踏板上。", "在完全伸展的位置暫停片刻。", "慢慢彎曲膝蓋，將踏板放回到身體的方向，控制動作。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1463', 'exercise', 1, '{"id": "1463", "target": "glutes", "name_en": "sled 45° leg press (side pov)", "name_zh": "蹬腿机45°腿举（侧面视角）", "body_part": "upper legs", "equipment": "sled machine", "gif_asset": "assets/fitness/videos/1463-2Qh2J1e.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "蹬腿機45°腿舉（側面視角）", "instructions_en": ["Adjust the seat of the sled machine so that your knees are at a 90-degree angle when your feet are on the footplate.", "Sit on the sled machine with your back flat against the backrest and your feet shoulder-width apart on the footplate.", "Grip the handles on the sides of the seat for stability.", "Push against the footplate to extend your legs, straightening them completely.", "Pause for a moment at the top, then slowly bend your knees to lower the footplate back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整雪橇机的座椅，使双脚放在踏板上时膝盖呈90度角。", "坐在雪橇机上，背部平放在靠背上，双脚与肩同宽放在踏板上。", "握住座椅两侧的把手以保持稳定性。", "推动脚踏板以伸展双腿，将其完全伸直。", "在顶部停顿片刻，然后慢慢弯曲膝盖，将踏板放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["調整雪橇機的座椅，使雙腳放在踏板上時膝蓋呈90度角。", "坐在雪橇機上，背部平放在靠背上，雙腳與肩同寬放在踏板上。", "握住座椅兩側的把手以保持穩定性。", "推動腳踏板以伸展雙腿，將其完全伸直。", "在頂部停頓片刻，然后慢慢彎曲膝蓋，將踏板放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0740', 'exercise', 1, '{"id": "0740", "target": "glutes", "name_en": "sled 45в° leg wide press", "name_zh": "蹬腿机45°腿部宽距推举", "body_part": "upper legs", "equipment": "sled machine", "gif_asset": "assets/fitness/videos/0740-tj41Nu6.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "蹬腿機45°腿部寬距推舉", "instructions_en": ["Adjust the sled machine to a 45-degree angle.", "Sit on the sled machine with your back against the pad and your feet on the foot platform.", "Position your feet wider than shoulder-width apart.", "Push against the foot platform to extend your legs and straighten your knees.", "Pause for a moment at the end of the movement, then slowly bend your knees to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将雪橇机调整至 45 度角。", "坐在雪橇机上，背部靠在垫子上，双脚放在脚踏平台上。", "双脚分开的距离比肩宽。", "推动脚部平台以伸展双腿并伸直膝盖。", "动作结束时暂停片刻，然后慢慢弯曲膝盖回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["將雪橇機調整至 45 度角。", "坐在雪橇機上，背部靠在墊子上，雙腳放在腳踏平臺上。", "雙腳分開的距離比肩寬。", "推動腳部平臺以伸展雙腿并伸直膝蓋。", "動作結束時暫停片刻，然后慢慢彎曲膝蓋回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1391', 'exercise', 1, '{"id": "1391", "target": "calves", "name_en": "sled calf press on leg press", "name_zh": "腿举机提踵", "body_part": "lower legs", "equipment": "sled machine", "gif_asset": "assets/fitness/videos/1391-ykHcWme.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "腿舉機提踵", "instructions_en": ["Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the sled.", "Place your feet shoulder-width apart on the sled, with your toes pointing forward.", "Release the safety handles and push the sled away from you by extending your knees and ankles.", "Pause for a moment at the top of the movement, then slowly lower the sled back down by bending your knees and ankles.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整压腿机的座椅，使双脚踩在雪橇上时膝盖稍微弯曲。", "将双脚与肩同宽放在雪橇上，脚趾指向前方。", "松开安全手柄，并通过伸展膝盖和脚踝将雪橇推离您。", "在动作的最高点暂停片刻，然后弯曲膝盖和脚踝，慢慢将雪橇放回原处。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "quadriceps"], "instructions_zh_hant": ["調整壓腿機的座椅，使雙腳踩在雪橇上時膝蓋稍微彎曲。", "將雙腳與肩同寬放在雪橇上，腳趾指向前方。", "松開安全手柄，并通過伸展膝蓋和腳踝將雪橇推離您。", "在動作的最高點暫停片刻，然后彎曲膝蓋和腳踝，慢慢將雪橇放回原處。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0742', 'exercise', 1, '{"id": "0742", "target": "calves", "name_en": "sled forward angled calf raise", "name_zh": "蹬腿机向前斜角提踵", "body_part": "lower legs", "equipment": "sled machine", "gif_asset": "assets/fitness/videos/0742-XDOiFns.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "蹬腿機向前斜角提踵", "instructions_en": ["Adjust the sled machine to a comfortable weight and position yourself on the machine with your toes on the platform and your heels hanging off.", "Place your hands on the handles or the sides of the machine for support.", "Engage your calves and slowly raise your heels as high as possible, pushing against the resistance of the sled.", "Pause for a moment at the top of the movement, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将雪橇机调整到舒适的重量，然后将自己放在机器上，脚趾放在平台上，脚后跟悬空。", "将手放在机器的手柄或侧面上以获得支撑。", "收紧小腿，慢慢地尽可能高地抬起脚后跟，克服雪橇的阻力。", "在动作的最高点暂停片刻，然后慢慢降低脚跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "glutes"], "instructions_zh_hant": ["將雪橇機調整到舒適的重量，然后將自己放在機器上，腳趾放在平臺上，腳后跟懸空。", "將手放在機器的手柄或側面上以獲得支撐。", "收緊小腿，慢慢地盡可能高地抬起腳后跟，克服雪橇的阻力。", "在動作的最高點暫停片刻，然后慢慢降低腳跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0743', 'exercise', 1, '{"id": "0743", "target": "glutes", "name_en": "sled hack squat", "name_zh": "蹬腿机哈克深蹲", "body_part": "upper legs", "equipment": "sled machine", "gif_asset": "assets/fitness/videos/0743-Qa55kX1.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "蹬腿機哈克深蹲", "instructions_en": ["Adjust the sled machine to a comfortable position for your height.", "Stand with your feet shoulder-width apart on the platform, toes slightly pointed outwards.", "Hold onto the handles or bars for stability.", "Lower your body by bending your knees and hips, keeping your back straight and chest up.", "Continue lowering until your thighs are parallel to the ground or slightly below.", "Pause for a moment, then push through your heels to raise your body back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将雪橇机调整到适合您身高的舒适位置。", "双脚与肩同宽站立在平台上，脚趾稍微向外。", "握住手柄或杆以保持稳定性。", "弯曲膝盖和臀部，降低身体，保持背部挺直，挺胸。", "继续降低，直到大腿与地面平行或略低于地面。", "暂停片刻，然后用脚后跟将身体抬回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["將雪橇機調整到適合您身高的舒適位置。", "雙腳與肩同寬站立在平臺上，腳趾稍微向外。", "握住手柄或桿以保持穩定性。", "彎曲膝蓋和臀部，降低身體，保持背部挺直，挺胸。", "繼續降低，直到大腿與地面平行或略低于地面。", "暫停片刻，然后用腳后跟將身體抬回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2334', 'exercise', 1, '{"id": "2334", "target": "calves", "name_en": "sled lying calf press", "name_zh": "蹬腿机卧姿小腿推举", "body_part": "lower legs", "equipment": "sled machine", "gif_asset": "assets/fitness/videos/2334-g376LuL.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "蹬腿機臥姿小腿推舉", "instructions_en": ["Adjust the sled machine to a comfortable weight.", "Sit on the sled machine with your back against the pad and your feet on the platform.", "Place your toes and the balls of your feet on the edge of the platform, with your heels hanging off.", "Push the platform away from you by extending your ankles, keeping your knees slightly bent.", "Continue pushing until your calves are fully contracted.", "Hold the contraction for a moment, then slowly lower the platform back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将雪橇机调整至舒适的重量。", "坐在雪橇机上，背部靠在垫子上，双脚放在平台上。", "将脚趾和脚掌放在平台边缘，脚跟悬空。", "伸展脚踝，将平台推离您，保持膝盖稍微弯曲。", "继续用力，直到小腿完全收缩。", "保持收缩一会儿，然后慢慢将平台放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "glutes"], "instructions_zh_hant": ["將雪橇機調整至舒適的重量。", "坐在雪橇機上，背部靠在墊子上，雙腳放在平臺上。", "將腳趾和腳掌放在平臺邊緣，腳跟懸空。", "伸展腳踝，將平臺推離您，保持膝蓋稍微彎曲。", "繼續用力，直到小腿完全收縮。", "保持收縮一會兒，然后慢慢將平臺放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0744', 'exercise', 1, '{"id": "0744", "target": "glutes", "name_en": "sled lying squat", "name_zh": "蹬腿机卧姿深蹲", "body_part": "upper legs", "equipment": "sled machine", "gif_asset": "assets/fitness/videos/0744-9n2149Z.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "蹬腿機臥姿深蹲", "instructions_en": ["Adjust the sled machine to a comfortable weight.", "Lie on your back on the sled machine with your feet on the footplate.", "Position your feet shoulder-width apart and slightly angled outwards.", "Grip the handles of the sled machine for stability.", "Engage your glutes and core muscles.", "Push through your heels and extend your legs to lift the sled.", "Lower the sled back down by bending your knees and hips.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将雪橇机调整至舒适的重量。", "仰卧在雪橇机上，双脚放在踏板上。", "双脚分开与肩同宽，并稍微向外倾斜。", "握住雪橇机的手柄以保持稳定。", "调动你的臀肌和核心肌肉。", "脚后跟用力，双腿伸直，抬起雪橇。", "弯曲膝盖和臀部，将雪橇放回原位。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["將雪橇機調整至舒適的重量。", "仰臥在雪橇機上，雙腳放在踏板上。", "雙腳分開與肩同寬，并稍微向外傾斜。", "握住雪橇機的手柄以保持穩定。", "調動你的臀肌和核心肌肉。", "腳后跟用力，雙腿伸直，抬起雪橇。", "彎曲膝蓋和臀部，將雪橇放回原位。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1392', 'exercise', 1, '{"id": "1392", "target": "calves", "name_en": "sled one leg calf press on leg press", "name_zh": "腿举机单腿提踵", "body_part": "lower legs", "equipment": "sled machine", "gif_asset": "assets/fitness/videos/1392-u0pLNgz.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "腿舉機單腿提踵", "instructions_en": ["Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the sled.", "Sit on the machine with your back against the backrest and your feet on the sled, shoulder-width apart.", "Place your toes and the balls of your feet on the sled, keeping your heels off.", "Push the sled forward by extending your ankles, keeping your knees slightly bent.", "Pause for a moment at the top, then slowly lower the sled back down by flexing your ankles.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整压腿机的座椅，使双脚踩在雪橇上时膝盖稍微弯曲。", "坐在机器上，背部靠在靠背上，双脚放在雪橇上，与肩同宽。", "将脚趾和脚掌放在雪橇上，保持脚跟离开。", "伸展脚踝，保持膝盖稍微弯曲，将雪橇向前推。", "在顶部停顿片刻，然后通过弯曲脚踝慢慢将雪橇放回原处。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "glutes"], "instructions_zh_hant": ["調整壓腿機的座椅，使雙腳踩在雪橇上時膝蓋稍微彎曲。", "坐在機器上，背部靠在靠背上，雙腳放在雪橇上，與肩同寬。", "將腳趾和腳掌放在雪橇上，保持腳跟離開。", "伸展腳踝，保持膝蓋稍微彎曲，將雪橇向前推。", "在頂部停頓片刻，然后通過彎曲腳踝慢慢將雪橇放回原處。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0746', 'exercise', 1, '{"id": "0746", "target": "traps", "name_en": "smith back shrug", "name_zh": "史密斯机背后耸肩", "body_part": "back", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/0746-MzNnwx9.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機背后聳肩", "instructions_en": ["Stand with your feet shoulder-width apart and your knees slightly bent.", "Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.", "Keep your arms straight and allow the barbell to hang in front of your thighs.", "Lift your shoulders straight up towards your ears, squeezing your traps at the top.", "Hold for a moment, then lower your shoulders back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，膝盖稍微弯曲。", "正手握住杠铃，双手间距略宽于肩宽。", "保持手臂伸直，让杠铃挂在大腿前面。", "将肩膀向耳朵方向伸直，挤压斜方肌顶部。", "保持一会儿，然后将肩膀放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，膝蓋稍微彎曲。", "正手握住杠鈴，雙手間距略寬于肩寬。", "保持手臂伸直，讓杠鈴掛在大腿前面。", "將肩膀向耳朵方向伸直，擠壓斜方肌頂部。", "保持一會兒，然后將肩膀放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0747', 'exercise', 1, '{"id": "0747", "target": "delts", "name_en": "smith behind neck press", "name_zh": "史密斯机颈后推举", "body_part": "shoulders", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/0747-Gpn4ADc.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機頸后推舉", "instructions_en": ["Adjust the seat height of the smith machine so that the bar is at shoulder level.", "Stand with your feet shoulder-width apart and your knees slightly bent.", "Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.", "Lift the bar off the rack and step back, maintaining a stable stance.", "Lower the bar down to the back of your neck, keeping your elbows pointing forward.", "Press the bar up overhead until your arms are fully extended.", "Pause for a moment at the top, then slowly lower the bar back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整史密斯机的座椅高度，使杠铃与肩部齐平。", "双脚分开与肩同宽站立，膝盖稍微弯曲。", "正手握住杠铃，握距略宽于肩宽。", "将杠铃从架子上抬起并向后退一步，保持稳定的姿势。", "将杠铃降低到颈后，保持肘部向前。", "将杠铃向上推过头顶，直到双臂完全伸展。", "在顶部暂停片刻，然后慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "upper back"], "instructions_zh_hant": ["調整史密斯機的座椅高度，使杠鈴與肩部齊平。", "雙腳分開與肩同寬站立，膝蓋稍微彎曲。", "正手握住杠鈴，握距略寬于肩寬。", "將杠鈴從架子上抬起并向后退一步，保持穩定的姿勢。", "將杠鈴降低到頸后，保持肘部向前。", "將杠鈴向上推過頭頂，直到雙臂完全伸展。", "在頂部暫停片刻，然后慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0748', 'exercise', 1, '{"id": "0748", "target": "pectorals", "name_en": "smith bench press", "name_zh": "史密斯机卧推", "body_part": "chest", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/0748-trqKQv2.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機臥推", "instructions_en": ["Adjust the height of the smith machine bar to chest level.", "Lie flat on the bench with your feet firmly planted on the ground.", "Grip the bar with an overhand grip slightly wider than shoulder-width apart.", "Unrack the bar and lower it towards your chest, keeping your elbows tucked in.", "Pause for a moment when the bar touches your chest.", "Push the bar back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将史密斯机杆的高度调整至胸部水平。", "平躺在长凳上，双脚牢牢踩在地上。", "正手握住杠铃，握距略宽于肩宽。", "松开杠铃并将其向胸部降低，保持肘部内收。", "当杠铃接触到你的胸部时暂停片刻。", "将杠铃推回到起始位置，完全伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["將史密斯機桿的高度調整至胸部水平。", "平躺在長凳上，雙腳牢牢踩在地上。", "正手握住杠鈴，握距略寬于肩寬。", "松開杠鈴并將其向胸部降低，保持肘部內收。", "當杠鈴接觸到你的胸部時暫停片刻。", "將杠鈴推回到起始位置，完全伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0749', 'exercise', 1, '{"id": "0749", "target": "glutes", "name_en": "smith bent knee good morning", "name_zh": "史密斯机屈膝早安式", "body_part": "upper legs", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/0749-1bQkKZK.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機屈膝早安式", "instructions_en": ["Start by standing with your feet shoulder-width apart, toes pointing forward.", "Place the barbell across your upper back, resting it on your traps.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.", "Engage your glutes and hamstrings to raise your torso back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先站立，双脚分开与肩同宽，脚趾指向前方。", "将杠铃放在上背部，放在斜方肌上。", "稍微弯曲膝盖，髋部向前转动，保持背部挺直。", "降低躯干直到与地面平行，感觉腿筋被拉伸。", "启动臀肌和腿筋，将躯干抬回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "lower back"], "instructions_zh_hant": ["首先站立，雙腳分開與肩同寬，腳趾指向前方。", "將杠鈴放在上背部，放在斜方肌上。", "稍微彎曲膝蓋，髖部向前轉動，保持背部挺直。", "降低軀幹直到與地面平行，感覺腿筋被拉伸。", "啟動臀肌和腿筋，將軀幹抬回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1359', 'exercise', 1, '{"id": "1359", "target": "upper back", "name_en": "smith bent over row", "name_zh": "史密斯机俯身划船", "body_part": "back", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/1359-ZX9UZmj.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機俯身劃船", "instructions_en": ["Set up the smith machine with the bar at hip height.", "Stand facing the bar with your feet shoulder-width apart.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.", "Pull the bar towards your lower chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the bar back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将史密斯机设置为与臀部高度相同的杠铃。", "面向杠铃站立，双脚分开与肩同宽。", "稍微弯曲膝盖，髋部向前转动，保持背部挺直。", "正手握住杠铃，双手距离略宽于肩宽。", "将杠铃拉向下胸部，将肩胛骨挤压在一起。", "在顶部暂停片刻，然后慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["將史密斯機設置為與臀部高度相同的杠鈴。", "面向杠鈴站立，雙腳分開與肩同寬。", "稍微彎曲膝蓋，髖部向前轉動，保持背部挺直。", "正手握住杠鈴，雙手距離略寬于肩寬。", "將杠鈴拉向下胸部，將肩胛骨擠壓在一起。", "在頂部暫停片刻，然后慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0750', 'exercise', 1, '{"id": "0750", "target": "quads", "name_en": "smith chair squat", "name_zh": "史密斯机椅上深蹲", "body_part": "upper legs", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/0750-Gu2rNJd.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機椅上深蹲", "instructions_en": ["Adjust the height of the smith machine bar to a comfortable position.", "Stand with your feet shoulder-width apart, toes slightly turned out.", "Place the barbell across your upper back, resting it on your traps.", "Engage your core and keep your chest up as you slowly lower your body by bending your knees and hips.", "Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.", "Pause for a moment, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将史密斯机杆的高度调整到舒适的位置。", "站立，双脚分开与肩同宽，脚趾稍微向外。", "将杠铃放在上背部，放在斜方肌上。", "通过弯曲膝盖和臀部慢慢降低身体，收紧核心并保持挺胸。", "继续降低，直到大腿与地面平行，或者尽可能低。", "暂停片刻，然后用力推动脚后跟，回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings", "calves"], "instructions_zh_hant": ["將史密斯機桿的高度調整到舒適的位置。", "站立，雙腳分開與肩同寬，腳趾稍微向外。", "將杠鈴放在上背部，放在斜方肌上。", "通過彎曲膝蓋和臀部慢慢降低身體，收緊核心并保持挺胸。", "繼續降低，直到大腿與地面平行，或者盡可能低。", "暫停片刻，然后用力推動腳后跟，回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0751', 'exercise', 1, '{"id": "0751", "target": "triceps", "name_en": "smith close-grip bench press", "name_zh": "史密斯机窄握卧推", "body_part": "upper arms", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/0751-WcHl7ru.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機窄握臥推", "instructions_en": ["Adjust the seat height and position yourself on the bench with your feet flat on the ground.", "Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.", "Lower the barbell towards your chest, keeping your elbows close to your body.", "Pause for a moment at the bottom, then push the barbell back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度，将自己放在长凳上，双脚平放在地面上。", "紧紧握住杠铃，握距略窄于肩宽。", "将杠铃向胸部降低，保持肘部靠近身体。", "在底部停顿片刻，然后将杠铃推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["調整座椅高度，將自己放在長凳上，雙腳平放在地面上。", "緊緊握住杠鈴，握距略窄于肩寬。", "將杠鈴向胸部降低，保持肘部靠近身體。", "在底部停頓片刻，然后將杠鈴推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0752', 'exercise', 1, '{"id": "0752", "target": "glutes", "name_en": "smith deadlift", "name_zh": "史密斯机硬拉", "body_part": "upper legs", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/0752-UfePqpx.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機硬拉", "instructions_en": ["Set up the smith machine with the bar at hip height.", "Stand with your feet shoulder-width apart, toes pointing slightly outward.", "Bend at the hips and knees, keeping your back straight and chest up, and grip the bar with an overhand grip slightly wider than shoulder-width apart.", "Engage your core and lift the bar by extending your hips and knees, keeping the bar close to your body.", "Stand up straight, fully extending your hips and knees.", "Lower the bar back down by bending at the hips and knees, maintaining control and keeping your back straight.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将史密斯机设置为与臀部高度相同的杠铃。", "双脚分开与肩同宽站立，脚趾稍微向外。", "弯曲臀部和膝盖，保持背部挺直，挺胸，正手握住杠铃，握距略宽于肩宽。", "伸展臀部和膝盖，调动核心力量并举起杠铃，保持杠铃靠近身体。", "站直，充分伸展臀部和膝盖。", "通过弯曲臀部和膝盖来降低杠铃，保持控制并保持背部挺直。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "quadriceps", "lower back"], "instructions_zh_hant": ["將史密斯機設置為與臀部高度相同的杠鈴。", "雙腳分開與肩同寬站立，腳趾稍微向外。", "彎曲臀部和膝蓋，保持背部挺直，挺胸，正手握住杠鈴，握距略寬于肩寬。", "伸展臀部和膝蓋，調動核心力量并舉起杠鈴，保持杠鈴靠近身體。", "站直，充分伸展臀部和膝蓋。", "通過彎曲臀部和膝蓋來降低杠鈴，保持控制并保持背部挺直。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0753', 'exercise', 1, '{"id": "0753", "target": "pectorals", "name_en": "smith decline bench press", "name_zh": "史密斯机下斜卧推", "body_part": "chest", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/0753-ETZfAbZ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機下斜臥推", "instructions_en": ["Adjust the decline bench to the desired angle.", "Lie down on the bench with your feet secured under the foot pads.", "Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.", "Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.", "Pause for a moment at the bottom, then push the barbell back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将下斜凳调整至所需角度。", "躺在长凳上，双脚固定在脚垫下。", "正手握住杠铃，握距略宽于肩宽。", "松开杠铃，慢慢将其降低到胸部，保持肘部内收。", "在底部停顿片刻，然后将杠铃推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["將下斜凳調整至所需角度。", "躺在長凳上，雙腳固定在腳墊下。", "正手握住杠鈴，握距略寬于肩寬。", "松開杠鈴，慢慢將其降低到胸部，保持肘部內收。", "在底部停頓片刻，然后將杠鈴推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1433', 'exercise', 1, '{"id": "1433", "target": "glutes", "name_en": "smith front squat (clean grip)", "name_zh": "史密斯机前蹲（翻举握法）", "body_part": "upper legs", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/1433-lFhb2Rw.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機前蹲（翻舉握法）", "instructions_en": ["Set up the smith machine with the barbell at shoulder height.", "Stand facing the barbell with your feet shoulder-width apart.", "Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.", "Step back and position the barbell on your front shoulders, resting it on your collarbone and deltoids.", "Keep your chest up, back straight, and core engaged.", "Lower your body by bending at the knees and hips, as if sitting back into a chair.", "Continue lowering until your thighs are parallel to the ground or slightly below.", "Pause for a moment, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将杠铃置于肩高的史密斯机上。", "面向杠铃站立，双脚与肩同宽。", "正手握住杠铃，握距略宽于肩宽。", "后退一步，将杠铃放在前肩上，放在锁骨和三角肌上。", "保持挺胸、背部挺直、核心收紧。", "弯曲膝盖和臀部，降低身体，就像坐回椅子上一样。", "继续降低，直到大腿与地面平行或略低于地面。", "暂停片刻，然后用力推动脚后跟，回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves", "core"], "instructions_zh_hant": ["將杠鈴置于肩高的史密斯機上。", "面向杠鈴站立，雙腳與肩同寬。", "正手握住杠鈴，握距略寬于肩寬。", "后退一步，將杠鈴放在前肩上，放在鎖骨和三角肌上。", "保持挺胸、背部挺直、核心收緊。", "彎曲膝蓋和臀部，降低身體，就像坐回椅子上一樣。", "繼續降低，直到大腿與地面平行或略低于地面。", "暫停片刻，然后用力推動腳后跟，回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3281', 'exercise', 1, '{"id": "3281", "target": "glutes", "name_en": "smith full squat", "name_zh": "史密斯机全蹲", "body_part": "upper legs", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/3281-NNoHCEA.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機全蹲", "instructions_en": ["Set up the smith machine with the barbell at shoulder height.", "Stand with your feet shoulder-width apart, toes slightly turned out.", "Step under the bar and position it across your upper back, resting on your traps.", "Grip the bar with your hands slightly wider than shoulder-width apart.", "Unrack the bar and take a step back, maintaining a stable stance.", "Keeping your chest up and core engaged, initiate the squat by pushing your hips back and bending your knees.", "Lower your body until your thighs are parallel to the ground, or as low as your flexibility allows.", "Pause for a moment at the bottom, then drive through your heels to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将杠铃置于肩高的史密斯机上。", "站立，双脚分开与肩同宽，脚趾稍微向外。", "走到杠铃下方，将其放在上背部上方，放在斜方肌上。", "双手握住杠铃，距离略大于肩宽。", "松开杠铃并后退一步，保持稳定的姿势。", "保持胸部挺直，核心参与，通过将臀部向后推并弯曲膝盖来开始深蹲。", "降低你的身体，直到你的大腿与地面平行，或者在你的灵活性允许的范围内尽可能低。", "在底部停顿片刻，然后用脚后跟恢复到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["將杠鈴置于肩高的史密斯機上。", "站立，雙腳分開與肩同寬，腳趾稍微向外。", "走到杠鈴下方，將其放在上背部上方，放在斜方肌上。", "雙手握住杠鈴，距離略大于肩寬。", "松開杠鈴并后退一步，保持穩定的姿勢。", "保持胸部挺直，核心參與，通過將臀部向后推并彎曲膝蓋來開始深蹲。", "降低你的身體，直到你的大腿與地面平行，或者在你的靈活性允許的范圍內盡可能低。", "在底部停頓片刻，然后用腳后跟恢復到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0755', 'exercise', 1, '{"id": "0755", "target": "glutes", "name_en": "smith hack squat", "name_zh": "史密斯机哈克深蹲", "body_part": "upper legs", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/0755-ZuPXtCK.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機哈克深蹲", "instructions_en": ["Adjust the barbell on the smith machine to an appropriate height for your body.", "Stand with your feet shoulder-width apart, toes slightly pointed outwards.", "Position yourself under the barbell, resting it on your upper traps and shoulders.", "Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.", "Engage your core and keep your chest up as you unrack the barbell.", "Take a step back and position your feet slightly wider than shoulder-width apart.", "Bend your knees and lower your body down, keeping your chest up and back straight.", "Continue descending until your thighs are parallel to the ground or slightly below.", "Pause for a moment at the bottom, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将史密斯机上的杠铃调整到适合您身体的高度。", "双脚分开与肩同宽站立，脚趾稍微向外。", "将自己置于杠铃下方，将其放在斜方肌上部和肩膀上。", "正手握住杠铃，握距略宽于肩宽。", "当你打开杠铃时，启动你的核心并保持挺胸。", "后退一步，双脚分开的距离略大于肩宽。", "弯曲膝盖，降低身体，保持挺胸、背部挺直。", "继续下降，直到大腿与地面平行或略低于地面。", "在底部停顿片刻，然后推动脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["將史密斯機上的杠鈴調整到適合您身體的高度。", "雙腳分開與肩同寬站立，腳趾稍微向外。", "將自己置于杠鈴下方，將其放在斜方肌上部和肩膀上。", "正手握住杠鈴，握距略寬于肩寬。", "當你打開杠鈴時，啟動你的核心并保持挺胸。", "后退一步，雙腳分開的距離略大于肩寬。", "彎曲膝蓋，降低身體，保持挺胸、背部挺直。", "繼續下降，直到大腿與地面平行或略低于地面。", "在底部停頓片刻，然后推動腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0756', 'exercise', 1, '{"id": "0756", "target": "abs", "name_en": "smith hip raise", "name_zh": "史密斯机髋部抬举", "body_part": "waist", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/0756-CqhoytW.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機髖部抬舉", "instructions_en": ["Position yourself on the smith machine with your back against the pad and your feet shoulder-width apart.", "Place your hands on the barbell, slightly wider than shoulder-width apart.", "Engage your core and glutes, then push through your heels to raise your hips off the ground.", "Continue lifting until your body forms a straight line from your knees to your shoulders.", "Hold for a moment at the top, then slowly lower your hips back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将自己放在史密斯机上，背部靠在垫子上，双脚分开与肩同宽。", "将双手放在杠铃上，距离略宽于肩宽。", "启动你的核心肌群和臀大肌，然后通过脚后跟将臀部抬离地面。", "继续提升，直到身体从膝盖到肩膀形成一条直线。", "在顶部保持片刻，然后慢慢将臀部放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings"], "instructions_zh_hant": ["將自己放在史密斯機上，背部靠在墊子上，雙腳分開與肩同寬。", "將雙手放在杠鈴上，距離略寬于肩寬。", "啟動你的核心肌群和臀大肌，然后通過腳后跟將臀部抬離地面。", "繼續提升，直到身體從膝蓋到肩膀形成一條直線。", "在頂部保持片刻，然后慢慢將臀部放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0771', 'exercise', 1, '{"id": "0771", "target": "forearms", "name_en": "smith standing back wrist curl", "name_zh": "史密斯机站姿背后腕弯举", "body_part": "lower arms", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/0771-hfmQ0Tz.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機站姿背后腕彎舉", "instructions_en": ["Stand facing the smith machine with your feet shoulder-width apart.", "Grasp the barbell with an overhand grip, hands shoulder-width apart.", "Keep your back straight and your elbows close to your body.", "Slowly curl your wrists upwards, bringing the barbell towards your body.", "Pause for a moment at the top, then slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["面对史密斯机站立，双脚与肩同宽。", "正手握住杠铃，双手与肩同宽。", "保持背部挺直，肘部靠近身体。", "慢慢向上弯曲手腕，将杠铃拉向身体。", "在顶部停顿片刻，然后慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "triceps"], "instructions_zh_hant": ["面對史密斯機站立，雙腳與肩同寬。", "正手握住杠鈴，雙手與肩同寬。", "保持背部挺直，肘部靠近身體。", "慢慢向上彎曲手腕，將杠鈴拉向身體。", "在頂部停頓片刻，然后慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0757', 'exercise', 1, '{"id": "0757", "target": "pectorals", "name_en": "smith incline bench press", "name_zh": "史密斯机上斜卧推", "body_part": "chest", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/0757-5v7KYld.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機上斜臥推", "instructions_en": ["Adjust the bench to a 30-45 degree incline.", "Sit on the bench with your back flat against the pad and feet firmly on the ground.", "Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.", "Unrack the barbell and lower it slowly towards your upper chest, keeping your elbows slightly tucked in.", "Pause for a moment at the bottom, then push the barbell back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将长凳调整至 30-45 度倾斜。", "坐在长凳上，背部平放在垫子上，双脚牢牢踩在地上。", "正手握住杠铃，握距略宽于肩宽。", "松开杠铃，慢慢地将其降低到上胸部，保持肘部稍微内收。", "在底部停顿片刻，然后将杠铃推回起始位置，充分伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["將長凳調整至 30-45 度傾斜。", "坐在長凳上，背部平放在墊子上，雙腳牢牢踩在地上。", "正手握住杠鈴，握距略寬于肩寬。", "松開杠鈴，慢慢地將其降低到上胸部，保持肘部稍微內收。", "在底部停頓片刻，然后將杠鈴推回起始位置，充分伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0758', 'exercise', 1, '{"id": "0758", "target": "pectorals", "name_en": "smith incline reverse-grip press", "name_zh": "史密斯机上斜反握推举", "body_part": "chest", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/0758-78VqWQK.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機上斜反握推舉", "instructions_en": ["Adjust the seat of the smith machine to a comfortable incline angle.", "Sit on the machine with your back against the pad and your feet flat on the ground.", "Grasp the bar with an overhand grip that is slightly wider than shoulder-width apart.", "Unrack the bar and lower it slowly towards your chest, keeping your elbows tucked in.", "Pause for a moment when the bar is just above your chest.", "Push the bar back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将史密斯机的座椅调整到舒适的倾斜角度。", "坐在机器上，背部靠在垫子上，双脚平放在地面上。", "正手握住杠铃，握距略宽于肩宽。", "松开杠铃并将其缓慢降低至胸部，同时保持肘部内收。", "当杠铃位于胸部正上方时，暂停片刻。", "将杠铃推回到起始位置，完全伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["將史密斯機的座椅調整到舒適的傾斜角度。", "坐在機器上，背部靠在墊子上，雙腳平放在地面上。", "正手握住杠鈴，握距略寬于肩寬。", "松開杠鈴并將其緩慢降低至胸部，同時保持肘部內收。", "當杠鈴位于胸部正上方時，暫停片刻。", "將杠鈴推回到起始位置，完全伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0759', 'exercise', 1, '{"id": "0759", "target": "serratus anterior", "name_en": "smith incline shoulder raises", "name_zh": "史密斯机上斜肩部抬举", "body_part": "chest", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/0759-ayAHcEm.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機上斜肩部抬舉", "instructions_en": ["Adjust the smith machine to an incline position.", "Stand facing the machine with your feet shoulder-width apart.", "Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.", "Keep your back straight and core engaged.", "Raise the barbell up towards the ceiling, leading with your elbows.", "Pause for a moment at the top, then slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将史密斯机调整至倾斜位置。", "面向机器站立，双脚分开与肩同宽。", "正手握住杠铃，握距略宽于肩宽。", "保持背部挺直，核心参与。", "将杠铃举向天花板，用肘部引导。", "在顶部停顿片刻，然后慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["deltoids", "trapezius"], "instructions_zh_hant": ["將史密斯機調整至傾斜位置。", "面向機器站立，雙腳分開與肩同寬。", "正手握住杠鈴，握距略寬于肩寬。", "保持背部挺直，核心參與。", "將杠鈴舉向天花板，用肘部引導。", "在頂部停頓片刻，然后慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0760', 'exercise', 1, '{"id": "0760", "target": "glutes", "name_en": "smith leg press", "name_zh": "史密斯机腿举", "body_part": "upper legs", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/0760-7zdxRTl.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機腿舉", "instructions_en": ["Adjust the seat and footplate of the smith machine to a comfortable position.", "Sit on the machine with your back against the backrest and your feet shoulder-width apart on the footplate.", "Grasp the handles or sides of the machine for stability.", "Push the footplate away from you by extending your legs, keeping your back against the backrest.", "Pause for a moment at the fully extended position.", "Slowly bend your knees and lower the footplate back towards you, returning to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将史密斯机的座椅和脚踏板调整到舒适的位置。", "坐在机器上，背部靠在靠背上，双脚与肩同宽放在踏板上。", "抓住机器的手柄或侧面以保持稳定性。", "伸展双腿，使背部紧靠靠背，将脚踏板推离您。", "在完全伸展的位置暂停片刻。", "慢慢弯曲膝盖，将脚踏板向您的方向放低，回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["將史密斯機的座椅和腳踏板調整到舒適的位置。", "坐在機器上，背部靠在靠背上，雙腳與肩同寬放在踏板上。", "抓住機器的手柄或側面以保持穩定性。", "伸展雙腿，使背部緊靠靠背，將腳踏板推離您。", "在完全伸展的位置暫停片刻。", "慢慢彎曲膝蓋，將腳踏板向您的方向放低，回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1434', 'exercise', 1, '{"id": "1434", "target": "glutes", "name_en": "smith low bar squat", "name_zh": "史密斯机低杠位深蹲", "body_part": "upper legs", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/1434-RGLscZM.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機低槓位深蹲", "instructions_en": ["Set up the smith machine with the barbell at a height that allows you to comfortably rest it on your upper back.", "Stand with your feet shoulder-width apart, toes slightly turned outwards.", "Step under the bar and position it across your upper back, resting it on your traps.", "Grip the bar with your hands slightly wider than shoulder-width apart.", "Unrack the bar by straightening your legs and stepping back from the rack.", "Take a deep breath and brace your core.", "Initiate the squat by pushing your hips back and bending your knees.", "Lower your body until your thighs are parallel to the ground or slightly below.", "Keep your chest up and your back straight throughout the movement.", "Drive through your heels to stand back up, extending your hips and knees.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将史密斯机与杠铃设置在一个高度，以便您可以将其舒适地放在上背部。", "站立，双脚分开与肩同宽，脚趾稍微向外转动。", "走到杠铃下方，将其放在上背部上方，将其放在斜方肌上。", "双手握住杠铃，距离略大于肩宽。", "伸直双腿并从架子上退后，将杠铃松开。", "深呼吸并支撑你的核心。", "通过向后推臀部并弯曲膝盖来开始深蹲。", "降低身体，直到大腿与地面平行或稍低于地面。", "在整个动作过程中保持挺胸、背部挺直。", "通过脚后跟站起来，伸展臀部和膝盖。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["將史密斯機與杠鈴設置在一個高度，以便您可以將其舒適地放在上背部。", "站立，雙腳分開與肩同寬，腳趾稍微向外轉動。", "走到杠鈴下方，將其放在上背部上方，將其放在斜方肌上。", "雙手握住杠鈴，距離略大于肩寬。", "伸直雙腿并從架子上退后，將杠鈴松開。", "深呼吸并支撐你的核心。", "通過向后推臀部并彎曲膝蓋來開始深蹲。", "降低身體，直到大腿與地面平行或稍低于地面。", "在整個動作過程中保持挺胸、背部挺直。", "通過腳后跟站起來，伸展臀部和膝蓋。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1683', 'exercise', 1, '{"id": "1683", "target": "biceps", "name_en": "smith machine bicep curl", "name_zh": "史密斯机二头弯举", "body_part": "upper arms", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/1683-zILLZ98.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機二頭彎舉", "instructions_en": ["Adjust the height of the smith machine bar to be at waist level.", "Stand facing the smith machine with your feet shoulder-width apart.", "Grasp the bar with an underhand grip, hands slightly wider than shoulder-width apart.", "Keep your elbows close to your sides and your upper arms stationary.", "Exhale and curl the bar up towards your shoulders, contracting your biceps.", "Pause for a moment at the top of the movement, squeezing your biceps.", "Inhale and slowly lower the bar back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将史密斯机杆的高度调整到腰部水平。", "面对史密斯机站立，双脚与肩同宽。", "反手握住杠铃，双手间距略大于肩宽。", "保持肘部靠近身体两侧，上臂保持静止。", "呼气并将杠铃向上卷向肩膀，收缩二头肌。", "在动作的最高点暂停片刻，挤压你的二头肌。", "吸气并慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["將史密斯機桿的高度調整到腰部水平。", "面對史密斯機站立，雙腳與肩同寬。", "反手握住杠鈴，雙手間距略大于肩寬。", "保持肘部靠近身體兩側，上臂保持靜止。", "呼氣并將杠鈴向上卷向肩膀，收縮二頭肌。", "在動作的最高點暫停片刻，擠壓你的二頭肌。", "吸氣并慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1625', 'exercise', 1, '{"id": "1625", "target": "triceps", "name_en": "smith machine decline close grip bench press", "name_zh": "史密斯机下斜窄握卧推", "body_part": "upper arms", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/1625-yB9SvIF.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機下斜窄握臥推", "instructions_en": ["Adjust the bench on the smith machine to a decline position.", "Lie down on the bench with your feet firmly planted on the ground.", "Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.", "Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.", "Pause for a moment when the barbell is just above your chest.", "Push the barbell back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将史密斯机上的长凳调整至下降位置。", "躺在长凳上，双脚牢牢踩在地上。", "紧紧握住杠铃，握距略窄于肩宽。", "松开杠铃并将其缓慢降低至胸部，保持肘部靠近身体。", "当杠铃位于胸部正上方时，暂停片刻。", "将杠铃推回到起始位置，完全伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["將史密斯機上的長凳調整至下降位置。", "躺在長凳上，雙腳牢牢踩在地上。", "緊緊握住杠鈴，握距略窄于肩寬。", "松開杠鈴并將其緩慢降低至胸部，保持肘部靠近身體。", "當杠鈴位于胸部正上方時，暫停片刻。", "將杠鈴推回到起始位置，完全伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1752', 'exercise', 1, '{"id": "1752", "target": "triceps", "name_en": "smith machine incline tricep extension", "name_zh": "史密斯机上斜臂屈伸", "body_part": "upper arms", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/1752-o8aOcrz.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機上斜臂屈伸", "instructions_en": ["Adjust the seat of the smith machine so that the bar is at shoulder height.", "Sit on the bench with your back against the pad and your feet flat on the ground.", "Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.", "Extend your arms fully, lifting the bar off the rack and holding it directly above your chest.", "Lower the bar slowly towards your forehead, keeping your elbows close to your head.", "Pause for a moment at the bottom, then push the bar back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整史密斯机的座椅，使杠铃处于肩部高度。", "坐在长凳上，背部靠在垫子上，双脚平放在地上。", "正手握住杠铃，握距略宽于肩宽。", "充分伸展双臂，将杠铃从架子上提起，并将其保持在胸部正上方。", "慢慢地将杠铃降低到前额，保持肘部靠近头部。", "在底部暂停片刻，然后将杠铃推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["調整史密斯機的座椅，使杠鈴處于肩部高度。", "坐在長凳上，背部靠在墊子上，雙腳平放在地上。", "正手握住杠鈴，握距略寬于肩寬。", "充分伸展雙臂，將杠鈴從架子上提起，并將其保持在胸部正上方。", "慢慢地將杠鈴降低到前額，保持肘部靠近頭部。", "在底部暫停片刻，然后將杠鈴推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1626', 'exercise', 1, '{"id": "1626", "target": "pectorals", "name_en": "smith machine reverse decline close grip bench press", "name_zh": "史密斯机反向下斜窄握卧推", "body_part": "chest", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/1626-QyO6Uma.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機反向下斜窄握臥推", "instructions_en": ["Adjust the smith machine to a decline position.", "Lie down on the bench with your feet secured under the foot pads.", "Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.", "Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.", "Pause for a moment at the bottom, then push the barbell back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将史密斯机调整至下降位置。", "躺在长凳上，双脚固定在脚垫下。", "紧紧握住杠铃，握距略窄于肩宽。", "松开杠铃，慢慢将其降低到胸部，保持肘部内收。", "在底部停顿片刻，然后将杠铃推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["將史密斯機調整至下降位置。", "躺在長凳上，雙腳固定在腳墊下。", "緊緊握住杠鈴，握距略窄于肩寬。", "松開杠鈴，慢慢將其降低到胸部，保持肘部內收。", "在底部停頓片刻，然后將杠鈴推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0761', 'exercise', 1, '{"id": "0761", "target": "upper back", "name_en": "smith narrow row", "name_zh": "史密斯机窄距划船", "body_part": "back", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/0761-JGKowMS.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機窄距劃船", "instructions_en": ["Adjust the seat height and position yourself on the machine with your feet flat on the floor.", "Grasp the handles with an overhand grip, slightly narrower than shoulder-width apart.", "Keep your back straight and your chest up as you pull the handles towards your body, squeezing your shoulder blades together.", "Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度并将自己放在机器上，双脚平放在地板上。", "正手握住手柄，握距略窄于肩宽。", "当您将手柄拉向身体时，保持背部挺直，挺胸，将肩胛骨挤压在一起。", "在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "rear deltoids"], "instructions_zh_hant": ["調整座椅高度并將自己放在機器上，雙腳平放在地板上。", "正手握住手柄，握距略窄于肩寬。", "當您將手柄拉向身體時，保持背部挺直，挺胸，將肩胛骨擠壓在一起。", "在動作的最高點暫停片刻，然后慢慢松開手柄回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1393', 'exercise', 1, '{"id": "1393", "target": "calves", "name_en": "smith one leg floor calf raise", "name_zh": "史密斯机单腿地板提踵", "body_part": "lower legs", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/1393-9GXrTE6.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機單腿地板提踵", "instructions_en": ["Position yourself on the floor under the smith machine bar, facing away from the machine.", "Place the balls of your feet on a raised surface, such as a weight plate or block.", "Position the smith machine bar across your lower legs, just above your ankles.", "Hold onto the bar with your hands for stability.", "Raise your heels off the ground by extending your ankles, lifting your body up.", "Pause at the top of the movement, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将自己放在史密斯机杆下方的地板上，背对机器。", "将脚掌放在凸起的表面上，例如举重板或杠铃块。", "将史密斯机杆放在小腿上，就在脚踝上方。", "用手握住横杆以保持稳定。", "伸展脚踝，将脚后跟抬离地面，抬起身体。", "在动作的最高点暂停，然后慢慢降低脚跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "glutes"], "instructions_zh_hant": ["將自己放在史密斯機桿下方的地板上，背對機器。", "將腳掌放在凸起的表面上，例如舉重板或杠鈴塊。", "將史密斯機桿放在小腿上，就在腳踝上方。", "用手握住橫桿以保持穩定。", "伸展腳踝，將腳后跟抬離地面，抬起身體。", "在動作的最高點暫停，然后慢慢降低腳跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0762', 'exercise', 1, '{"id": "0762", "target": "delts", "name_en": "smith rear delt row", "name_zh": "史密斯机三角肌后束划船", "body_part": "shoulders", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/0762-nFUwqG6.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機三角肌后束劃船", "instructions_en": ["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the ground.", "Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.", "Keep your back straight and your core engaged as you pull the handles towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top of the movement, then slowly release the handles back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度，将自己放在机器上，胸部靠在垫子上，双脚平放在地面上。", "正手握住手柄，握距略宽于肩宽。", "将手柄拉向胸部，将肩胛骨挤压在一起，保持背部挺直，核心肌群参与。", "在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["trapezius", "rhomboids", "biceps"], "instructions_zh_hant": ["調整座椅高度，將自己放在機器上，胸部靠在墊子上，雙腳平放在地面上。", "正手握住手柄，握距略寬于肩寬。", "將手柄拉向胸部，將肩胛骨擠壓在一起，保持背部挺直，核心肌群參與。", "在動作的最高點暫停片刻，然后慢慢松開手柄回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0763', 'exercise', 1, '{"id": "0763", "target": "calves", "name_en": "smith reverse calf raises", "name_zh": "史密斯机反向提踵", "body_part": "lower legs", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/0763-ywaNfuh.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機反向提踵", "instructions_en": ["Adjust the smith machine bar to a height just below your shoulders.", "Stand facing the bar with your feet hip-width apart and toes pointing forward.", "Place the balls of your feet on the edge of a step or platform, with your heels hanging off.", "Hold onto the bar for support, keeping your back straight and core engaged.", "Raise your heels as high as possible, lifting your body weight onto the balls of your feet.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将史密斯机杆调整到略低于肩膀的高度。", "面向杠铃站立，双脚分开与臀部同宽，脚趾向前。", "将脚掌放在台阶或平台的边缘，脚后跟悬空。", "握住杠铃以提供支撑，保持背部挺直，核心肌群参与。", "尽可能高地抬高脚后跟，将身体重量转移到脚掌上。", "在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings"], "instructions_zh_hant": ["將史密斯機桿調整到略低于肩膀的高度。", "面向杠鈴站立，雙腳分開與臀部同寬，腳趾向前。", "將腳掌放在臺階或平臺的邊緣，腳后跟懸空。", "握住杠鈴以提供支撐，保持背部挺直，核心肌群參與。", "盡可能高地抬高腳后跟，將身體重量轉移到腳掌上。", "在頂部停頓片刻，然后慢慢降低腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1394', 'exercise', 1, '{"id": "1394", "target": "calves", "name_en": "smith reverse calf raises", "name_zh": "史密斯机反向提踵", "body_part": "lower legs", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/1394-Lsqrgh4.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機反向提踵", "instructions_en": ["Adjust the smith machine bar to a height just below your shoulders.", "Stand facing the bar with your feet hip-width apart and toes pointing forward.", "Place the balls of your feet on the edge of a step or platform, with your heels hanging off.", "Hold onto the bar for support.", "Raise your heels as high as possible, lifting your body up onto your toes.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将史密斯机杆调整到略低于肩膀的高度。", "面向杠铃站立，双脚分开与臀部同宽，脚趾向前。", "将脚掌放在台阶或平台的边缘，脚后跟悬空。", "抓住横杆以获得支撑。", "尽可能高地抬高脚跟，将身体抬起到脚趾上。", "在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings"], "instructions_zh_hant": ["將史密斯機桿調整到略低于肩膀的高度。", "面向杠鈴站立，雙腳分開與臀部同寬，腳趾向前。", "將腳掌放在臺階或平臺的邊緣，腳后跟懸空。", "抓住橫桿以獲得支撐。", "盡可能高地抬高腳跟，將身體抬起到腳趾上。", "在頂部停頓片刻，然后慢慢降低腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1361', 'exercise', 1, '{"id": "1361", "target": "upper back", "name_en": "smith reverse grip bent over row", "name_zh": "史密斯机反握俯身划船", "body_part": "back", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/1361-aaxA3cm.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機反握俯身劃船", "instructions_en": ["Set up the smith machine with the bar at hip height.", "Stand facing the bar with your feet shoulder-width apart.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Grasp the bar with an underhand grip, hands shoulder-width apart.", "Pull the bar towards your lower chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the bar back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将史密斯机设置为与臀部高度相同的杠铃。", "面向杠铃站立，双脚分开与肩同宽。", "稍微弯曲膝盖，髋部向前转动，保持背部挺直。", "反手握住杠铃，双手与肩同宽。", "将杠铃拉向下胸部，将肩胛骨挤压在一起。", "在顶部暂停片刻，然后慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["將史密斯機設置為與臀部高度相同的杠鈴。", "面向杠鈴站立，雙腳分開與肩同寬。", "稍微彎曲膝蓋，髖部向前轉動，保持背部挺直。", "反手握住杠鈴，雙手與肩同寬。", "將杠鈴拉向下胸部，將肩胛骨擠壓在一起。", "在頂部暫停片刻，然后慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0764', 'exercise', 1, '{"id": "0764", "target": "pectorals", "name_en": "smith reverse-grip press", "name_zh": "史密斯机反握推举", "body_part": "chest", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/0764-zK8Fu1W.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機反握推舉", "instructions_en": ["Adjust the height of the smith machine bar to chest level.", "Stand facing the bar with your feet shoulder-width apart.", "Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.", "Step back and position yourself with a slight bend in your knees.", "Keep your chest up and core engaged throughout the exercise.", "Lower the bar towards your chest, keeping your elbows tucked in.", "Pause for a moment at the bottom, then push the bar back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将史密斯机杆的高度调整至胸部水平。", "面向杠铃站立，双脚分开与肩同宽。", "正手握住杠铃，双手距离略宽于肩宽。", "退后一步，膝盖稍微弯曲。", "在整个练习过程中保持挺胸并保持核心参与。", "将杠铃向胸部方向降低，保持肘部内收。", "在底部暂停片刻，然后将杠铃推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["將史密斯機桿的高度調整至胸部水平。", "面向杠鈴站立，雙腳分開與肩同寬。", "正手握住杠鈴，雙手距離略寬于肩寬。", "退后一步，膝蓋稍微彎曲。", "在整個練習過程中保持挺胸并保持核心參與。", "將杠鈴向胸部方向降低，保持肘部內收。", "在底部暫停片刻，然后將杠鈴推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1395', 'exercise', 1, '{"id": "1395", "target": "calves", "name_en": "smith seated one leg calf raise", "name_zh": "史密斯机坐姿单腿提踵", "body_part": "lower legs", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/1395-0S75mYG.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機坐姿單腿提踵", "instructions_en": ["Sit on the machine with your back against the pad and your feet on the footrest.", "Place one leg on the footrest and keep the other leg off the footrest.", "Using your calf muscles, raise your heel as high as possible.", "Pause for a moment at the top, then slowly lower your heel back down to the starting position.", "Repeat for the desired number of repetitions, then switch legs and repeat."], "instructions_zh": ["坐在机器上，背部靠在垫子上，双脚放在脚踏板上。", "将一条腿放在脚踏板上，另一条腿离开脚踏板。", "使用小腿肌肉，尽可能高地抬高脚跟。", "在顶部暂停片刻，然后慢慢将脚跟放回起始位置。", "重复所需的重复次数，然后换腿并重复。"], "secondary_muscles": ["hamstrings"], "instructions_zh_hant": ["坐在機器上，背部靠在墊子上，雙腳放在腳踏板上。", "將一條腿放在腳踏板上，另一條腿離開腳踏板。", "使用小腿肌肉，盡可能高地抬高腳跟。", "在頂部暫停片刻，然后慢慢將腳跟放回起始位置。", "重復所需的重復次數，然后換腿并重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0765', 'exercise', 1, '{"id": "0765", "target": "delts", "name_en": "smith seated shoulder press", "name_zh": "史密斯机坐姿肩上推举", "body_part": "shoulders", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/0765-xUwnBMT.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機坐姿肩上推舉", "instructions_en": ["Adjust the seat height so that the handles are at shoulder level.", "Sit on the machine with your back against the pad and your feet flat on the floor.", "Grasp the handles with an overhand grip and lift them off the supports, extending your arms fully.", "Lower the handles down to shoulder level, keeping your elbows slightly bent.", "Press the handles up overhead until your arms are fully extended.", "Pause for a moment at the top, then slowly lower the handles back down to shoulder level.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度，使手柄与肩部齐平。", "坐在机器上，背部靠在垫子上，双脚平放在地板上。", "正手握住手柄，将其提离支撑物，充分伸展双臂。", "将手柄降低至肩部水平，保持肘部稍微弯曲。", "将手柄向上推过头顶，直到手臂完全伸展。", "在顶部暂停片刻，然后慢慢将手柄放回至肩部水平。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "upper back"], "instructions_zh_hant": ["調整座椅高度，使手柄與肩部齊平。", "坐在機器上，背部靠在墊子上，雙腳平放在地板上。", "正手握住手柄，將其提離支撐物，充分伸展雙臂。", "將手柄降低至肩部水平，保持肘部稍微彎曲。", "將手柄向上推過頭頂，直到手臂完全伸展。", "在頂部暫停片刻，然后慢慢將手柄放回至肩部水平。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1426', 'exercise', 1, '{"id": "1426", "target": "forearms", "name_en": "smith seated wrist curl", "name_zh": "史密斯机坐姿腕弯举", "body_part": "lower arms", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/1426-B6dAO1t.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機坐姿腕彎舉", "instructions_en": ["Sit on a bench in front of a Smith machine with your feet flat on the ground.", "Grasp the barbell with an underhand grip, hands shoulder-width apart.", "Rest your forearms on your thighs, allowing your wrists to hang off.", "Slowly curl your wrists upward, bringing the barbell towards your forearms.", "Pause for a moment at the top, then slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在史密斯机前的长凳上，双脚平放在地面上。", "反握抓住杠铃，双手与肩同宽。", "将前臂放在大腿上，让手腕悬垂。", "慢慢向上弯曲手腕，将杠铃拉向前臂。", "在顶部停顿片刻，然后慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "brachialis"], "instructions_zh_hant": ["坐在史密斯機前的長凳上，雙腳平放在地面上。", "反握抓住杠鈴，雙手與肩同寬。", "將前臂放在大腿上，讓手腕懸垂。", "慢慢向上彎曲手腕，將杠鈴拉向前臂。", "在頂部停頓片刻，然后慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0775', 'exercise', 1, '{"id": "0775", "target": "delts", "name_en": "smith upright row", "name_zh": "史密斯机直立划船", "body_part": "shoulders", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/0775-1DN3iz4.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機直立劃船", "instructions_en": ["Stand with your feet shoulder-width apart, facing the smith machine.", "Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.", "Keep your back straight and your core engaged.", "Pull the barbell up towards your chin, leading with your elbows.", "Pause for a moment at the top, then slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，面向史密斯机。", "正手握住杠铃，双手间距略宽于肩宽。", "保持背部挺直，核心肌群参与。", "将杠铃拉向下巴，用肘部引导。", "在顶部停顿片刻，然后慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["traps", "biceps"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，面向史密斯機。", "正手握住杠鈴，雙手間距略寬于肩寬。", "保持背部挺直，核心肌群參與。", "將杠鈴拉向下巴，用肘部引導。", "在頂部停頓片刻，然后慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0766', 'exercise', 1, '{"id": "0766", "target": "delts", "name_en": "smith shoulder press", "name_zh": "史密斯机肩上推举", "body_part": "shoulders", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/0766-903mzG8.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機肩上推舉", "instructions_en": ["Adjust the seat height and position yourself on the smith machine with your feet shoulder-width apart.", "Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.", "Lift the bar off the rack and position it at shoulder level, with your elbows bent and palms facing forward.", "Press the bar upward until your arms are fully extended overhead.", "Pause for a moment at the top, then slowly lower the bar back down to shoulder level.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度，将自己放在史密斯机上，双脚分开与肩同宽。", "正手握住杠铃，握距略宽于肩宽。", "将杠铃从架子上提起，并将其置于与肩同高的位置，肘部弯曲，手掌朝前。", "向上推杠铃，直到手臂完全伸过头顶。", "在顶部暂停片刻，然后慢慢将杠铃放回至肩部水平。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "upper back"], "instructions_zh_hant": ["調整座椅高度，將自己放在史密斯機上，雙腳分開與肩同寬。", "正手握住杠鈴，握距略寬于肩寬。", "將杠鈴從架子上提起，并將其置于與肩同高的位置，肘部彎曲，手掌朝前。", "向上推杠鈴，直到手臂完全伸過頭頂。", "在頂部暫停片刻，然后慢慢將杠鈴放回至肩部水平。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0767', 'exercise', 1, '{"id": "0767", "target": "traps", "name_en": "smith shrug", "name_zh": "史密斯机耸肩", "body_part": "back", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/0767-OUQ0ZyW.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機聳肩", "instructions_en": ["Stand with your feet shoulder-width apart and your knees slightly bent.", "Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.", "Keep your arms straight and your shoulders relaxed.", "Lift your shoulders up towards your ears, squeezing your traps at the top.", "Hold for a moment, then slowly lower your shoulders back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，膝盖稍微弯曲。", "正手握住杠铃，双手间距略宽于肩宽。", "保持双臂伸直，肩膀放松。", "将肩膀向耳朵方向抬起，在顶部挤压斜方肌。", "保持一会儿，然后慢慢将肩膀放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，膝蓋稍微彎曲。", "正手握住杠鈴，雙手間距略寬于肩寬。", "保持雙臂伸直，肩膀放松。", "將肩膀向耳朵方向抬起，在頂部擠壓斜方肌。", "保持一會兒，然后慢慢將肩膀放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0768', 'exercise', 1, '{"id": "0768", "target": "quads", "name_en": "smith single leg split squat", "name_zh": "史密斯机单腿分腿蹲", "body_part": "upper legs", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/0768-wWFspEi.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機單腿分腿蹲", "instructions_en": ["Stand in front of the smith machine with your feet shoulder-width apart.", "Place one foot behind you on a bench or step, with your toes pointing forward.", "Hold onto the smith machine bar for stability.", "Bend your front knee and lower your body down into a lunge position, keeping your back straight.", "Pause for a moment at the bottom, then push through your front heel to return to the starting position.", "Repeat for the desired number of repetitions, then switch legs."], "instructions_zh": ["站在史密斯机前，双脚分开与肩同宽。", "将一只脚放在身后的长凳或台阶上，脚趾向前。", "握住史密斯机杆以保持稳定性。", "弯曲前膝盖，将身体降低到弓步位置，保持背部挺直。", "在底部停顿片刻，然后推动前脚跟回到起始位置。", "重复所需的重复次数，然后换腿。"], "secondary_muscles": ["glutes", "hamstrings"], "instructions_zh_hant": ["站在史密斯機前，雙腳分開與肩同寬。", "將一只腳放在身后的長凳或臺階上，腳趾向前。", "握住史密斯機桿以保持穩定性。", "彎曲前膝蓋，將身體降低到弓步位置，保持背部挺直。", "在底部停頓片刻，然后推動前腳跟回到起始位置。", "重復所需的重復次數，然后換腿。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0769', 'exercise', 1, '{"id": "0769", "target": "glutes", "name_en": "smith sprint lunge", "name_zh": "史密斯机冲刺弓步", "body_part": "upper legs", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/0769-HsjbB1z.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機沖刺弓步", "instructions_en": ["Set up the smith machine with the barbell at hip height.", "Stand facing away from the machine with your feet shoulder-width apart.", "Step back with your right foot and place it on the barbell, resting the top of your foot on the bar.", "Bend your left knee and lower your body into a lunge position, keeping your back straight.", "Push through your left heel to return to the starting position.", "Repeat on the other side, stepping back with your left foot.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["将杠铃置于臀部高度的史密斯机上。", "背对机器站立，双脚与肩同宽。", "右脚向后退一步，将其放在杠铃上，将脚尖放在杠上。", "弯曲左膝，将身体降低到弓步位置，保持背部挺直。", "推动左脚跟返回到起始位置。", "在另一侧重复，左脚向后退一步。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["將杠鈴置于臀部高度的史密斯機上。", "背對機器站立，雙腳與肩同寬。", "右腳向后退一步，將其放在杠鈴上，將腳尖放在杠上。", "彎曲左膝，將身體降低到弓步位置，保持背部挺直。", "推動左腳跟返回到起始位置。", "在另一側重復，左腳向后退一步。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0770', 'exercise', 1, '{"id": "0770", "target": "glutes", "name_en": "smith squat", "name_zh": "史密斯机深蹲", "body_part": "upper legs", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/0770-jFtipLl.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機深蹲", "instructions_en": ["Set up the smith machine with the barbell at an appropriate height for your squat.", "Stand with your feet shoulder-width apart, toes slightly turned out.", "Position yourself under the barbell, resting it on your upper traps and shoulders.", "Grip the barbell with a wide grip, slightly wider than shoulder-width apart.", "Engage your core and unrack the barbell, stepping back to clear the rack.", "Keeping your chest up and back straight, initiate the squat by bending at the hips and knees.", "Lower your body until your thighs are parallel to the ground or slightly below.", "Pause for a moment at the bottom, then drive through your heels to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将史密斯机和杠铃设置在适合深蹲的高度。", "站立，双脚分开与肩同宽，脚趾稍微向外。", "将自己置于杠铃下方，将其放在斜方肌上部和肩膀上。", "宽握距握住杠铃，握距略宽于肩宽。", "启动你的核心并打开杠铃，后退以清理架子。", "保持胸部挺直，背部挺直，通过弯曲臀部和膝盖开始深蹲。", "降低身体，直到大腿与地面平行或稍低于地面。", "在底部停顿片刻，然后用脚后跟恢复到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["將史密斯機和杠鈴設置在適合深蹲的高度。", "站立，雙腳分開與肩同寬，腳趾稍微向外。", "將自己置于杠鈴下方，將其放在斜方肌上部和肩膀上。", "寬握距握住杠鈴，握距略寬于肩寬。", "啟動你的核心并打開杠鈴，后退以清理架子。", "保持胸部挺直，背部挺直，通過彎曲臀部和膝蓋開始深蹲。", "降低身體，直到大腿與地面平行或稍低于地面。", "在底部停頓片刻，然后用腳后跟恢復到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0772', 'exercise', 1, '{"id": "0772", "target": "delts", "name_en": "smith standing behind head military press", "name_zh": "史密斯机站姿颈后肩上推举", "body_part": "shoulders", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/0772-ht8xDrP.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機站姿頸后肩上推舉", "instructions_en": ["Adjust the seat height of the smith machine so that the bar is at shoulder level.", "Stand with your feet shoulder-width apart and your knees slightly bent.", "Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.", "Lift the bar off the rack and step back, maintaining a stable stance.", "Position the bar behind your head, resting on your upper traps.", "Keep your core engaged and your chest lifted throughout the exercise.", "Press the bar overhead by extending your arms, fully straightening them.", "Pause briefly at the top of the movement, then slowly lower the bar back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整史密斯机的座椅高度，使杠铃与肩部齐平。", "双脚分开与肩同宽站立，膝盖稍微弯曲。", "正手握住杠铃，握距略宽于肩宽。", "将杠铃从架子上抬起并向后退一步，保持稳定的姿势。", "将杠铃放在脑后，放在斜方肌上部。", "在整个练习过程中保持核心收紧并抬起胸部。", "伸展双臂，完全伸直，将杠铃推过头顶。", "在动作的最高点稍作停顿，然后慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "upper back"], "instructions_zh_hant": ["調整史密斯機的座椅高度，使杠鈴與肩部齊平。", "雙腳分開與肩同寬站立，膝蓋稍微彎曲。", "正手握住杠鈴，握距略寬于肩寬。", "將杠鈴從架子上抬起并向后退一步，保持穩定的姿勢。", "將杠鈴放在腦后，放在斜方肌上部。", "在整個練習過程中保持核心收緊并抬起胸部。", "伸展雙臂，完全伸直，將杠鈴推過頭頂。", "在動作的最高點稍作停頓，然后慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0773', 'exercise', 1, '{"id": "0773", "target": "calves", "name_en": "smith standing leg calf raise", "name_zh": "史密斯机站姿提踵", "body_part": "lower legs", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/0773-6MaEjVA.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機站姿提踵", "instructions_en": ["Adjust the smith machine bar to a height that allows you to stand with your feet flat on the ground and your shoulders under the bar.", "Position yourself under the bar with your feet shoulder-width apart and your toes pointing forward.", "Place your hands on the bar for stability.", "Engage your calves and slowly raise your heels off the ground, lifting your body up onto your toes.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将史密斯机杆调整到一个高度，使您能够双脚平放在地面上且肩膀位于杆下方。", "将自己置于杠铃下方，双脚分开与肩同宽，脚趾向前。", "将双手放在横杆上以保持稳定。", "收紧小腿，慢慢将脚跟抬离地面，将身体抬起到脚趾上。", "在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "glutes"], "instructions_zh_hant": ["將史密斯機桿調整到一個高度，使您能夠雙腳平放在地面上且肩膀位于桿下方。", "將自己置于杠鈴下方，雙腳分開與肩同寬，腳趾向前。", "將雙手放在橫桿上以保持穩定。", "收緊小腿，慢慢將腳跟抬離地面，將身體抬起到腳趾上。", "在頂部停頓片刻，然后慢慢降低腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0774', 'exercise', 1, '{"id": "0774", "target": "delts", "name_en": "smith standing military press", "name_zh": "史密斯机站姿肩上推举", "body_part": "shoulders", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/0774-jjUPrze.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機站姿肩上推舉", "instructions_en": ["Stand with your feet shoulder-width apart and your knees slightly bent.", "Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.", "Lift the barbell off the rack and bring it down to shoulder level, with your palms facing forward.", "Press the barbell upward until your arms are fully extended overhead.", "Pause for a moment at the top, then slowly lower the barbell back down to shoulder level.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，膝盖稍微弯曲。", "正手握住杠铃，握距略宽于肩宽。", "将杠铃从架子上提起，并将其降至与肩同高，手掌朝前。", "向上推杠铃，直到手臂完全伸过头顶。", "在顶部停顿片刻，然后慢慢将杠铃放回至肩部水平。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "upper back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，膝蓋稍微彎曲。", "正手握住杠鈴，握距略寬于肩寬。", "將杠鈴從架子上提起，并將其降至與肩同高，手掌朝前。", "向上推杠鈴，直到手臂完全伸過頭頂。", "在頂部停頓片刻，然后慢慢將杠鈴放回至肩部水平。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3142', 'exercise', 1, '{"id": "3142", "target": "glutes", "name_en": "smith sumo squat", "name_zh": "史密斯机相扑式深蹲", "body_part": "upper legs", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/3142-dzz6BiV.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機相撲式深蹲", "instructions_en": ["Set up the smith machine with the barbell at hip height.", "Stand with your feet wider than shoulder-width apart, toes pointing outwards.", "Position yourself under the barbell, resting it on your upper back and shoulders.", "Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.", "Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go.", "Pause for a moment at the bottom, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将杠铃置于臀部高度的史密斯机上。", "站立，双脚分开比肩宽，脚趾朝外。", "将自己置于杠铃下方，将其放在上背部和肩膀上。", "当你将身体降低到蹲姿时，收紧核心并保持挺胸，将臀部向后推并弯曲膝盖。", "放低身体，直到大腿与地面平行，或者尽可能低到您能舒服的高度。", "在底部停顿片刻，然后推动脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["將杠鈴置于臀部高度的史密斯機上。", "站立，雙腳分開比肩寬，腳趾朝外。", "將自己置于杠鈴下方，將其放在上背部和肩膀上。", "當你將身體降低到蹲姿時，收緊核心并保持挺胸，將臀部向后推并彎曲膝蓋。", "放低身體，直到大腿與地面平行，或者盡可能低到您能舒服的高度。", "在底部停頓片刻，然后推動腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1396', 'exercise', 1, '{"id": "1396", "target": "calves", "name_en": "smith toe raise", "name_zh": "史密斯机提脚尖", "body_part": "lower legs", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/1396-Y4QlY8z.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機提腳尖", "instructions_en": ["Adjust the smith machine bar to a height that allows you to comfortably stand with your feet flat on the ground.", "Position yourself under the bar with your shoulders directly below it and your feet shoulder-width apart.", "Place the balls of your feet on a raised platform or weight plates, with your heels hanging off the edge.", "Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.", "Engage your core and keep your back straight throughout the exercise.", "Slowly raise your heels as high as possible, lifting your body weight onto the balls of your feet.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将史密斯机杆调整到一个高度，让您可以舒适地站立，双脚平放在地面上。", "将自己置于杠铃下方，肩膀位于杠铃正下方，双脚分开与肩同宽。", "将脚掌放在升高的平台或重量板上，脚后跟悬在边缘。", "正手握住杠铃，握距略宽于肩宽。", "在整个练习过程中启动你的核心并保持背部挺直。", "慢慢地尽可能高地抬起脚后跟，将身体重量转移到脚掌上。", "在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["ankles", "shins"], "instructions_zh_hant": ["將史密斯機桿調整到一個高度，讓您可以舒適地站立，雙腳平放在地面上。", "將自己置于杠鈴下方，肩膀位于杠鈴正下方，雙腳分開與肩同寬。", "將腳掌放在升高的平臺或重量板上，腳后跟懸在邊緣。", "正手握住杠鈴，握距略寬于肩寬。", "在整個練習過程中啟動你的核心并保持背部挺直。", "慢慢地盡可能高地抬起腳后跟，將身體重量轉移到腳掌上。", "在頂部停頓片刻，然后慢慢降低腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1308', 'exercise', 1, '{"id": "1308", "target": "pectorals", "name_en": "smith wide grip bench press", "name_zh": "史密斯机宽握卧推", "body_part": "chest", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/1308-zoOvPcx.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機寬握臥推", "instructions_en": ["Adjust the bench to a comfortable position on the smith machine.", "Lie down on the bench with your feet flat on the ground.", "Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.", "Unrack the barbell and lower it slowly towards your chest, keeping your elbows out to the sides.", "Pause for a moment when the barbell touches your chest.", "Push the barbell back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将史密斯机上的长凳调整到舒适的位置。", "躺在长凳上，双脚平放在地上。", "宽握距抓住杠铃，握距略宽于肩宽。", "松开杠铃并将其慢慢降低到胸部，保持肘部向两侧伸出。", "当杠铃触及胸部时暂停片刻。", "将杠铃推回到起始位置，完全伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["將史密斯機上的長凳調整到舒適的位置。", "躺在長凳上，雙腳平放在地上。", "寬握距抓住杠鈴，握距略寬于肩寬。", "松開杠鈴并將其慢慢降低到胸部，保持肘部向兩側伸出。", "當杠鈴觸及胸部時暫停片刻。", "將杠鈴推回到起始位置，完全伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1309', 'exercise', 1, '{"id": "1309", "target": "pectorals", "name_en": "smith wide grip decline bench press", "name_zh": "史密斯机宽握下斜卧推", "body_part": "chest", "equipment": "smith machine", "gif_asset": "assets/fitness/videos/1309-wi2H9QX.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "史密斯機寬握下斜臥推", "instructions_en": ["Adjust the decline bench to the desired angle.", "Lie down on the bench with your feet secured under the foot pads.", "Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.", "Unrack the barbell and lower it slowly towards your chest, keeping your elbows pointed outwards.", "Pause for a moment when the barbell touches your chest.", "Push the barbell back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将下斜凳调整至所需角度。", "躺在长凳上，双脚固定在脚垫下。", "宽握距抓住杠铃，握距略宽于肩宽。", "松开杠铃并将其慢慢降低到胸部，保持肘部朝外。", "当杠铃触及胸部时暂停片刻。", "将杠铃推回到起始位置，完全伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["將下斜凳調整至所需角度。", "躺在長凳上，雙腳固定在腳墊下。", "寬握距抓住杠鈴，握距略寬于肩寬。", "松開杠鈴并將其慢慢降低到胸部，保持肘部朝外。", "當杠鈴觸及胸部時暫停片刻。", "將杠鈴推回到起始位置，完全伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0776', 'exercise', 1, '{"id": "0776", "target": "quads", "name_en": "snatch pull", "name_zh": "抓举高拉", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0776-dG5Smob.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "抓舉高拉", "instructions_en": ["Stand with your feet shoulder-width apart and the barbell on the ground in front of you.", "Bend your knees and hinge at the hips to lower into a squat position, gripping the barbell with an overhand grip.", "Keep your back straight and chest up as you drive through your heels to lift the barbell off the ground, extending your hips and knees.", "As the barbell reaches hip level, explosively pull it upwards, shrugging your shoulders and pulling your elbows high and to the sides.", "As the barbell reaches its highest point, quickly drop underneath it, pulling yourself into a deep squat position.", "Catch the barbell overhead with your arms fully extended and your knees bent.", "Stand up by extending your hips and knees, keeping the barbell overhead.", "Lower the barbell back down to the starting position by reversing the movement.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，杠铃放在你面前的地面上。", "弯曲膝盖并以臀部为铰链，降低至下蹲位置，用正手握住杠铃。", "当你通过脚后跟将杠铃抬离地面时，保持背部挺直，挺胸，伸展臀部和膝盖。", "当杠铃到达臀部水平时，爆发性地将其向上拉，耸肩并将肘部向两侧拉高。", "当杠铃到达最高点时，迅速落到杠铃下方，将自己拉成深蹲位置。", "双臂完全伸展，膝盖弯曲，将杠铃举过头顶。", "伸展臀部和膝盖站起来，将杠铃保持在头顶上方。", "通过反向运动将杠铃降低回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "glutes", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，杠鈴放在你面前的地面上。", "彎曲膝蓋并以臀部為鉸鏈，降低至下蹲位置，用正手握住杠鈴。", "當你通過腳后跟將杠鈴抬離地面時，保持背部挺直，挺胸，伸展臀部和膝蓋。", "當杠鈴到達臀部水平時，爆發性地將其向上拉，聳肩并將肘部向兩側拉高。", "當杠鈴到達最高點時，迅速落到杠鈴下方，將自己拉成深蹲位置。", "雙臂完全伸展，膝蓋彎曲，將杠鈴舉過頭頂。", "伸展臀部和膝蓋站起來，將杠鈴保持在頭頂上方。", "通過反向運動將杠鈴降低回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0777', 'exercise', 1, '{"id": "0777", "target": "abs", "name_en": "spell caster", "name_zh": "施法式摆举", "body_part": "waist", "equipment": "dumbbell", "gif_asset": "assets/fitness/videos/0777-p9cCe2r.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "施法式擺舉", "instructions_en": ["Stand with your feet shoulder-width apart and hold a dumbbell in one hand.", "Bend your knees slightly and hinge forward at the waist, keeping your back straight.", "Extend your arm with the dumbbell towards the opposite foot, rotating your torso as you do so.", "Return to the starting position and repeat on the other side.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，一只手握住哑铃。", "稍微弯曲膝盖，腰部向前转动，保持背部挺直。", "将哑铃伸向另一只脚的手臂，同时旋转躯干。", "返回起始位置并在另一侧重复。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["obliques", "lower back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，一只手握住啞鈴。", "稍微彎曲膝蓋，腰部向前轉動，保持背部挺直。", "將啞鈴伸向另一只腳的手臂，同時旋轉軀幹。", "返回起始位置并在另一側重復。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1362', 'exercise', 1, '{"id": "1362", "target": "spine", "name_en": "sphinx", "name_zh": "狮身人面式", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1362-DIVyqrU.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "獅身人面式", "instructions_en": ["Lie face down on the ground with your forearms flat on the floor, elbows directly under your shoulders.", "Engage your core and lift your chest off the ground, keeping your forearms and toes on the floor.", "Hold this position for a few seconds, making sure to keep your neck in a neutral position.", "Slowly lower your chest back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["面朝下躺在地上，前臂平放在地板上，肘部直接位于肩膀下方。", "收紧核心肌群，将胸部抬离地面，将前臂和脚趾保持在地板上。", "保持这个姿势几秒钟，确保颈部保持在中立位置。", "慢慢地将胸部放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings"], "instructions_zh_hant": ["面朝下躺在地上，前臂平放在地板上，肘部直接位于肩膀下方。", "收緊核心肌群，將胸部抬離地面，將前臂和腳趾保持在地板上。", "保持這個姿勢幾秒鐘，確保頸部保持在中立位置。", "慢慢地將胸部放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0778', 'exercise', 1, '{"id": "0778", "target": "glutes", "name_en": "spider crawl push up", "name_zh": "蜘蛛式爬行俯卧撑", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0778-P9GFBME.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "蜘蛛式爬行俯臥撐", "instructions_en": ["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.", "Bring your right knee towards your right elbow, keeping it off the ground.", "As you bring your right knee back, simultaneously lower your body towards the ground by bending your elbows.", "Push back up to the starting position and repeat with your left knee towards your left elbow.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["从俯卧撑位置开始，双手分开略宽于肩宽，双脚并拢。", "将右膝靠近右肘，使其离开地面。", "当您将右膝向后拉时，同时弯曲肘部将身体降低到地面。", "推回起始位置，然后将左膝朝向左肘重复此动作。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["core", "chest", "shoulders"], "instructions_zh_hant": ["從俯臥撐位置開始，雙手分開略寬于肩寬，雙腳并攏。", "將右膝靠近右肘，使其離開地面。", "當您將右膝向后拉時，同時彎曲肘部將身體降低到地面。", "推回起始位置，然后將左膝朝向左肘重復此動作。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1363', 'exercise', 1, '{"id": "1363", "target": "spine", "name_en": "spine stretch", "name_zh": "脊柱拉伸", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1363-JbC2iaV.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "脊柱拉伸", "instructions_en": ["Sit on the ground with your legs extended in front of you.", "Place your hands on the ground behind you, fingers pointing towards your body.", "Engage your core and slowly lean back, keeping your back straight.", "Continue leaning back until you feel a stretch in your spine.", "Hold the stretch for a few seconds, then slowly return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在地上，双腿在身前伸展。", "将双手放在身后的地面上，手指指向身体。", "启动你的核心并慢慢向后倾斜，保持背部挺直。", "继续向后倾斜，直到感觉到脊柱被拉伸。", "保持伸展几秒钟，然后慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "glutes"], "instructions_zh_hant": ["坐在地上，雙腿在身前伸展。", "將雙手放在身后的地面上，手指指向身體。", "啟動你的核心并慢慢向后傾斜，保持背部挺直。", "繼續向后傾斜，直到感覺到脊柱被拉伸。", "保持伸展幾秒鐘，然后慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2329', 'exercise', 1, '{"id": "2329", "target": "abs", "name_en": "spine twist", "name_zh": "脊柱转体", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/2329-2jl9K55.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "脊柱轉體", "instructions_en": ["Sit on the ground with your legs extended in front of you.", "Bend your knees and place your feet flat on the ground, hip-width apart.", "Place your hands behind your head with your elbows pointing outwards.", "Engage your abs and slowly twist your torso to the right, bringing your right elbow towards your left knee.", "Pause for a moment at the end of the twist, then slowly return to the starting position.", "Repeat the twist to the left side, bringing your left elbow towards your right knee.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["坐在地上，双腿在身前伸展。", "弯曲膝盖，将双脚平放在地面上，距离与臀部同宽。", "将双手放在脑后，肘部朝外。", "收紧腹肌，慢慢向右扭转躯干，将右肘拉向左膝盖。", "扭转结束时暂停片刻，然后慢慢回到起始位置。", "向左侧重复扭转，将左肘拉向右膝盖。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["obliques", "lower back"], "instructions_zh_hant": ["坐在地上，雙腿在身前伸展。", "彎曲膝蓋，將雙腳平放在地面上，距離與臀部同寬。", "將雙手放在腦后，肘部朝外。", "收緊腹肌，慢慢向右扭轉軀幹，將右肘拉向左膝蓋。", "扭轉結束時暫停片刻，然后慢慢回到起始位置。", "向左側重復扭轉，將左肘拉向右膝蓋。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2368', 'exercise', 1, '{"id": "2368", "target": "quads", "name_en": "split squats", "name_zh": "分腿深蹲", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/2368-9E25EOx.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "分腿深蹲", "instructions_en": ["Stand with your feet shoulder-width apart.", "Take a step forward with one foot and place it about two feet in front of the other foot.", "Lower your body by bending your knees and hips, keeping your back straight.", "Continue lowering until your front thigh is parallel to the ground, and your back knee is hovering just above the ground.", "Pause for a moment, then push through your front heel to return to the starting position.", "Repeat for the desired number of repetitions, then switch legs and repeat."], "instructions_zh": ["双脚分开与肩同宽站立。", "一只脚向前迈出一步，并将其放在另一只脚前面约两英尺处。", "弯曲膝盖和臀部，降低身体，保持背部挺直。", "继续降低，直到前大腿与地面平行，后膝盖悬停在地面上方。", "暂停片刻，然后推动前脚跟回到起始位置。", "重复所需的重复次数，然后换腿并重复。"], "secondary_muscles": ["glutes", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立。", "一只腳向前邁出一步，并將其放在另一只腳前面約兩英尺處。", "彎曲膝蓋和臀部，降低身體，保持背部挺直。", "繼續降低，直到前大腿與地面平行，后膝蓋懸停在地面上方。", "暫停片刻，然后推動前腳跟回到起始位置。", "重復所需的重復次數，然后換腿并重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0786', 'exercise', 1, '{"id": "0786", "target": "quads", "name_en": "squat jerk", "name_zh": "深蹲挺举", "body_part": "upper legs", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0786-IMRsOCn.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "深蹲挺舉", "instructions_en": ["Start with the barbell resting on your shoulders, with your feet shoulder-width apart.", "Lower your body into a squat position, keeping your chest up and your knees tracking over your toes.", "As you reach the bottom of the squat, explosively drive through your legs and push the barbell overhead.", "As the barbell reaches its peak, quickly drop into a split position, with one foot forward and one foot back.", "Catch the barbell overhead with your arms fully extended and your back knee slightly touching the ground.", "Stand up from the split position, bringing your feet back together.", "Lower the barbell back to your shoulders and repeat for the desired number of repetitions."], "instructions_zh": ["首先将杠铃放在肩膀上，双脚分开与肩同宽。", "将身体降低至蹲姿，保持挺胸，膝盖位于脚趾上方。", "当你到达深蹲底部时，爆发性地用腿发力，并将杠铃推过头顶。", "当杠铃到达最高点时，迅速落入分体位置，一脚向前，一脚向后。", "双臂完全伸展，后膝盖稍微接触地面，将杠铃举过头顶。", "从分开的位置站起来，将双脚重新并拢。", "将杠铃放回肩膀处，然后重复所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings", "calves", "core"], "instructions_zh_hant": ["首先將杠鈴放在肩膀上，雙腳分開與肩同寬。", "將身體降低至蹲姿，保持挺胸，膝蓋位于腳趾上方。", "當你到達深蹲底部時，爆發性地用腿發力，并將杠鈴推過頭頂。", "當杠鈴到達最高點時，迅速落入分體位置，一腳向前，一腳向后。", "雙臂完全伸展，后膝蓋稍微接觸地面，將杠鈴舉過頭頂。", "從分開的位置站起來，將雙腳重新并攏。", "將杠鈴放回肩膀處，然后重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1705', 'exercise', 1, '{"id": "1705", "target": "quads", "name_en": "squat on bosu ball", "name_zh": "深蹲于波速球", "body_part": "upper legs", "equipment": "bosu ball", "gif_asset": "assets/fitness/videos/1705-T2fA5Ir.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "深蹲于波速球", "instructions_en": ["Place the bosu ball on the ground with the flat side up.", "Stand with your feet shoulder-width apart and position yourself on top of the bosu ball.", "Lower your body down by bending your knees and hips, as if sitting back into a chair.", "Keep your chest up and your weight on your heels.", "Lower yourself until your thighs are parallel to the ground.", "Pause for a moment, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将博苏球平放在地上。", "双脚分开与肩同宽站立，将自己放在博苏球的顶部。", "弯曲膝盖和臀部，降低身体，就像坐回椅子上一样。", "保持挺胸，将体重放在脚后跟上。", "降低身体直到大腿与地面平行。", "暂停片刻，然后用力推动脚后跟，回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings", "calves"], "instructions_zh_hant": ["將博蘇球平放在地上。", "雙腳分開與肩同寬站立，將自己放在博蘇球的頂部。", "彎曲膝蓋和臀部，降低身體，就像坐回椅子上一樣。", "保持挺胸，將體重放在腳后跟上。", "降低身體直到大腿與地面平行。", "暫停片刻，然后用力推動腳后跟，回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1685', 'exercise', 1, '{"id": "1685", "target": "quads", "name_en": "squat to overhead reach", "name_zh": "深蹲至过顶伸手", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1685-QChZi3x.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "深蹲至過頂伸手", "instructions_en": ["Stand with your feet shoulder-width apart and toes slightly turned out.", "Lower your body down into a squat position by bending your knees and pushing your hips back.", "As you come up from the squat, extend your arms overhead, reaching towards the ceiling.", "Return to the starting position by lowering your arms and bending your knees to squat down again.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站立，双脚分开与肩同宽，脚趾稍微外翻。", "弯曲膝盖并将臀部向后推，将身体降低至蹲姿。", "当你从深蹲中站起来时，将手臂伸过头顶，伸向天花板。", "放下手臂并弯曲膝盖再次蹲下，回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings", "core"], "instructions_zh_hant": ["站立，雙腳分開與肩同寬，腳趾稍微外翻。", "彎曲膝蓋并將臀部向后推，將身體降低至蹲姿。", "當你從深蹲中站起來時，將手臂伸過頭頂，伸向天花板。", "放下手臂并彎曲膝蓋再次蹲下，回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1686', 'exercise', 1, '{"id": "1686", "target": "quads", "name_en": "squat to overhead reach with twist", "name_zh": "深蹲至过顶伸手配合转体", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1686-5BZHW9s.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "深蹲至過頂伸手配合轉體", "instructions_en": ["Stand with your feet shoulder-width apart and toes slightly turned out.", "Lower your body into a squat position by bending your knees and pushing your hips back.", "As you come up from the squat, raise your arms overhead and twist your torso to one side.", "Return to the starting position and repeat the squat, this time twisting your torso to the opposite side.", "Continue alternating sides with each squat repetition."], "instructions_zh": ["站立，双脚分开与肩同宽，脚趾稍微外翻。", "弯曲膝盖并将臀部向后推，将身体降低至蹲姿。", "当你从深蹲中站起来时，将手臂举过头顶并将躯干扭转到一侧。", "返回起始位置并重复下蹲，这次将躯干扭转到另一侧。", "每次深蹲重复时继续交替进行。"], "secondary_muscles": ["glutes", "hamstrings", "core"], "instructions_zh_hant": ["站立，雙腳分開與肩同寬，腳趾稍微外翻。", "彎曲膝蓋并將臀部向后推，將身體降低至蹲姿。", "當你從深蹲中站起來時，將手臂舉過頭頂并將軀幹扭轉到一側。", "返回起始位置并重復下蹲，這次將軀幹扭轉到另一側。", "每次深蹲重復時繼續交替進行。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2297', 'exercise', 1, '{"id": "2297", "target": "abs", "name_en": "stability ball crunch (full range hands behind head)", "name_zh": "健身球卷腹（全程幅度双手颈后）", "body_part": "waist", "equipment": "stability ball", "gif_asset": "assets/fitness/videos/2297-Gn5FwYT.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健身球卷腹（全程幅度雙手頸后）", "instructions_en": ["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, slowly curl your upper body forward, bringing your chest towards your knees.", "Pause for a moment at the top, then slowly lower your upper body back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。", "将双手放在脑后，肘部朝外。", "收紧腹肌，慢慢向前弯曲上半身，使胸部靠近膝盖。", "在顶部停顿片刻，然后慢慢降低上半身回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["坐在穩定球上，雙腳平放在地面上，膝蓋彎曲成 90 度角。", "將雙手放在腦后，肘部朝外。", "收緊腹肌，慢慢向前彎曲上半身，使胸部靠近膝蓋。", "在頂部停頓片刻，然后慢慢降低上半身回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3291', 'exercise', 1, '{"id": "3291", "target": "triceps", "name_en": "stalder press", "name_zh": "斯托尔德推举", "body_part": "upper arms", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3291-zd4P4B2.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "斯托爾德推舉", "instructions_en": ["Start by standing with your feet shoulder-width apart and your arms extended overhead.", "Bend your knees slightly and engage your core.", "Lower your body down into a squat position while keeping your arms extended overhead.", "As you squat down, press your arms down towards the ground, engaging your triceps.", "Pause for a moment at the bottom of the squat, then push through your heels to stand back up while simultaneously raising your arms back overhead.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先站立，双脚分开与肩同宽，双臂伸过头顶。", "稍微弯曲膝盖并启动核心。", "将身体降低至蹲姿，同时保持手臂伸过头顶。", "当你蹲下时，将手臂向下压向地面，锻炼三头肌。", "在深蹲底部停顿片刻，然后用脚后跟站起来，同时将手臂举过头顶。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "core"], "instructions_zh_hant": ["首先站立，雙腳分開與肩同寬，雙臂伸過頭頂。", "稍微彎曲膝蓋并啟動核心。", "將身體降低至蹲姿，同時保持手臂伸過頭頂。", "當你蹲下時，將手臂向下壓向地面，鍛煉三頭肌。", "在深蹲底部停頓片刻，然后用腳后跟站起來，同時將手臂舉過頭頂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3669', 'exercise', 1, '{"id": "3669", "target": "upper back", "name_en": "standing archer", "name_zh": "站姿弓箭式拉伸", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3669-JF8AkMX.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "站姿弓箭式拉伸", "instructions_en": ["Stand with your feet shoulder-width apart and your knees slightly bent.", "Extend your arms straight out in front of you at shoulder height, parallel to the ground.", "Rotate your torso to the right, keeping your arms extended and your back straight.", "As you rotate, extend your right arm forward and your left arm back, mimicking the motion of drawing a bowstring.", "Hold the position for a moment, then return to the starting position.", "Repeat the motion, this time rotating your torso to the left and extending your left arm forward and your right arm back.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，膝盖稍微弯曲。", "将双臂伸直至前方，与肩同高，与地面平行。", "将躯干向右旋转，保持双臂伸展，背部挺直。", "旋转时，向前伸展右臂，向后伸展左臂，模仿拉弓弦的动作。", "保持该姿势片刻，然后回到起始位置。", "重复该动作，这次将躯干向左旋转，左臂向前伸展，右臂向后伸展。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["shoulders", "biceps", "forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，膝蓋稍微彎曲。", "將雙臂伸直至前方，與肩同高，與地面平行。", "將軀幹向右旋轉，保持雙臂伸展，背部挺直。", "旋轉時，向前伸展右臂，向后伸展左臂，模仿拉弓弦的動作。", "保持該姿勢片刻，然后回到起始位置。", "重復該動作，這次將軀幹向左旋轉，左臂向前伸展，右臂向后伸展。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0788', 'exercise', 1, '{"id": "0788", "target": "delts", "name_en": "standing behind neck press", "name_zh": "站姿颈后推举", "body_part": "shoulders", "equipment": "barbell", "gif_asset": "assets/fitness/videos/0788-xDh0lJr.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "站姿頸后推舉", "instructions_en": ["Stand with your feet shoulder-width apart and hold the barbell behind your neck with an overhand grip.", "Keep your back straight and core engaged.", "Press the barbell overhead by extending your arms, fully extending your elbows.", "Pause for a moment at the top, then slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，用正手握法将杠铃握在颈后。", "保持背部挺直，核心参与。", "伸展手臂，充分伸展肘部，将杠铃推过头顶。", "在顶部停顿片刻，然后慢慢将杠铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "upper back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，用正手握法將杠鈴握在頸后。", "保持背部挺直，核心參與。", "伸展手臂，充分伸展肘部，將杠鈴推過頭頂。", "在頂部停頓片刻，然后慢慢將杠鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1490', 'exercise', 1, '{"id": "1490", "target": "calves", "name_en": "standing calf raise (on a staircase)", "name_zh": "站姿提踵（于楼梯）", "body_part": "lower legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1490-6HmFgmx.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "站姿提踵（于樓梯）", "instructions_en": ["Stand on the edge of a step or a sturdy platform with your heels hanging off and your toes on the step.", "Hold onto a railing or wall for balance if needed.", "Slowly raise your heels as high as possible, lifting your body weight onto the balls of your feet.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站在台阶或坚固平台的边缘，脚后跟悬垂，脚趾放在台阶上。", "如果需要，抓住栏杆或墙壁以保持平衡。", "慢慢地尽可能高地抬起脚后跟，将身体重量转移到脚掌上。", "在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["ankles", "feet"], "instructions_zh_hant": ["站在臺階或堅固平臺的邊緣，腳后跟懸垂，腳趾放在臺階上。", "如果需要，抓住欄桿或墻壁以保持平衡。", "慢慢地盡可能高地抬起腳后跟，將身體重量轉移到腳掌上。", "在頂部停頓片刻，然后慢慢降低腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1397', 'exercise', 1, '{"id": "1397", "target": "calves", "name_en": "standing calves", "name_zh": "站姿提踵", "body_part": "lower legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1397-XIHEoCG.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "站姿提踵", "instructions_en": ["Stand with your feet shoulder-width apart, toes pointing forward.", "Raise your heels off the ground as high as possible, standing on your toes.", "Hold the position for a moment, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，脚趾指向前方。", "将脚后跟抬离地面，尽可能高，用脚趾站立。", "保持该姿势片刻，然后慢慢降低脚跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "glutes"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，腳趾指向前方。", "將腳后跟抬離地面，盡可能高，用腳趾站立。", "保持該姿勢片刻，然后慢慢降低腳跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1398', 'exercise', 1, '{"id": "1398", "target": "calves", "name_en": "standing calves calf stretch", "name_zh": "站姿小腿拉伸", "body_part": "lower legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1398-qOKcgVP.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "站姿小腿拉伸", "instructions_en": ["Stand facing a wall or sturdy object, about an arm''s length away.", "Place your hands on the wall or object at shoulder height.", "Step back with one foot, keeping your heel flat on the ground.", "Bend your front knee slightly and lean forward, keeping your back leg straight.", "You should feel a stretch in your calf muscle.", "Hold the stretch for 20-30 seconds.", "Repeat on the other leg."], "instructions_zh": ["面朝墙壁或坚固物体站立，距离大约一臂远。", "将手放在与肩同高的墙壁或物体上。", "一只脚向后退一步，保持脚跟平放在地面上。", "稍微弯曲前膝盖并向前倾斜，保持后腿伸直。", "您应该感觉到小腿肌肉有拉伸感。", "保持拉伸 20-30 秒。", "在另一条腿上重复。"], "secondary_muscles": ["hamstrings", "glutes"], "instructions_zh_hant": ["面朝墻壁或堅固物體站立，距離大約一臂遠。", "將手放在與肩同高的墻壁或物體上。", "一只腳向后退一步，保持腳跟平放在地面上。", "稍微彎曲前膝蓋并向前傾斜，保持后腿伸直。", "您應該感覺到小腿肌肉有拉伸感。", "保持拉伸 20-30 秒。", "在另一條腿上重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0794', 'exercise', 1, '{"id": "0794", "target": "lats", "name_en": "standing lateral stretch", "name_zh": "站姿侧向拉伸", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0794-1jXLYEw.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "站姿側向拉伸", "instructions_en": ["Stand with your feet shoulder-width apart and your knees slightly bent.", "Extend your arms straight out to the sides, parallel to the ground.", "Slowly lean your upper body to one side, feeling a stretch in your side and lats.", "Hold the stretch for 15-30 seconds.", "Return to the starting position and repeat on the other side.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，膝盖稍微弯曲。", "将双臂伸直至两侧，与地面平行。", "慢慢将上半身向一侧倾斜，感觉侧面和背阔肌有拉伸感。", "保持拉伸 15-30 秒。", "返回起始位置并在另一侧重复。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "obliques"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，膝蓋稍微彎曲。", "將雙臂伸直至兩側，與地面平行。", "慢慢將上半身向一側傾斜，感覺側面和背闊肌有拉伸感。", "保持拉伸 15-30 秒。", "返回起始位置并在另一側重復。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1364', 'exercise', 1, '{"id": "1364", "target": "spine", "name_en": "standing pelvic tilt", "name_zh": "站姿骨盆倾斜", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1364-cuKYxhu.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "站姿骨盆傾斜", "instructions_en": ["Stand with your feet shoulder-width apart and your knees slightly bent.", "Place your hands on your hips or let them hang by your sides.", "Engage your core muscles and tilt your pelvis forward, pushing your lower back towards the wall behind you.", "Hold the position for a few seconds, then release and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，膝盖稍微弯曲。", "将双手放在臀部或垂在身体两侧。", "调动核心肌肉并向前倾斜骨盆，将下背部推向身后的墙壁。", "保持该位置几秒钟，然后松开并返回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["abdominals"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，膝蓋稍微彎曲。", "將雙手放在臀部或垂在身體兩側。", "調動核心肌肉并向前傾斜骨盆，將下背部推向身后的墻壁。", "保持該位置幾秒鐘，然后松開并返回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0795', 'exercise', 1, '{"id": "0795", "target": "hamstrings", "name_en": "standing single leg curl", "name_zh": "站姿单腿弯举", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0795-C5jncD2.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "站姿單腿彎舉", "instructions_en": ["Stand with your feet hip-width apart and your hands on your hips.", "Shift your weight onto your left leg and lift your right foot off the ground, bending your knee.", "Slowly curl your right heel towards your glutes, squeezing your hamstring.", "Pause for a moment at the top, then slowly lower your right foot back down to the starting position.", "Repeat for the desired number of repetitions, then switch legs."], "instructions_zh": ["站立，双脚分开与臀部同宽，双手放在臀部。", "将体重转移到左腿上，将右脚抬离地面，弯曲膝盖。", "慢慢地将右脚跟卷向臀部，挤压腿筋。", "在顶部暂停片刻，然后慢慢将右脚放回起始位置。", "重复所需的重复次数，然后换腿。"], "secondary_muscles": ["glutes"], "instructions_zh_hant": ["站立，雙腳分開與臀部同寬，雙手放在臀部。", "將體重轉移到左腿上，將右腳抬離地面，彎曲膝蓋。", "慢慢地將右腳跟卷向臀部，擠壓腿筋。", "在頂部暫停片刻，然后慢慢將右腳放回起始位置。", "重復所需的重復次數，然后換腿。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0796', 'exercise', 1, '{"id": "0796", "target": "abs", "name_en": "standing wheel rollerout", "name_zh": "站姿健腹轮前推", "body_part": "waist", "equipment": "wheel roller", "gif_asset": "assets/fitness/videos/0796-KtRomty.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "站姿健腹輪前推", "instructions_en": ["Start by standing tall with your feet shoulder-width apart and the wheel roller in front of you.", "Bend at your waist and slowly roll the wheel forward, keeping your back straight and your core engaged.", "Continue rolling forward until you feel a stretch in your abs and your body is extended as far as possible.", "Pause for a moment, then slowly roll the wheel back towards your body, returning to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先，站直，双脚分开与肩同宽，滚轮位于您的前方。", "弯腰，慢慢向前滚动轮子，保持背部挺直，核心肌群参与。", "继续向前滚动，直到感觉到腹肌拉伸并且身体尽可能伸展。", "暂停片刻，然后慢慢地将轮子向身体方向滚动，回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["lower back", "shoulders"], "instructions_zh_hant": ["首先，站直，雙腳分開與肩同寬，滾輪位于您的前方。", "彎腰，慢慢向前滾動輪子，保持背部挺直，核心肌群參與。", "繼續向前滾動，直到感覺到腹肌拉伸并且身體盡可能伸展。", "暫停片刻，然后慢慢地將輪子向身體方向滾動，回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3223', 'exercise', 1, '{"id": "3223", "target": "cardiovascular system", "name_en": "star jump (male)", "name_zh": "星形跳跃（男性示范）", "body_part": "cardio", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3223-HtfCpfi.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "星形跳躍（男性示范）", "instructions_en": ["Stand with your feet shoulder-width apart and your arms by your sides.", "Bend your knees slightly and jump up explosively.", "As you jump, spread your legs and extend your arms out to the sides, forming a star shape with your body.", "Land softly on the balls of your feet with your knees slightly bent.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双臂放在身体两侧。", "稍微弯曲膝盖并爆发性地跳起来。", "跳跃时，张开双腿，将手臂向两侧伸展，与身体形成星形。", "膝盖轻轻弯曲，脚掌轻轻着地。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙臂放在身體兩側。", "稍微彎曲膝蓋并爆發性地跳起來。", "跳躍時，張開雙腿，將手臂向兩側伸展，與身體形成星形。", "膝蓋輕輕彎曲，腳掌輕輕著地。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2138', 'exercise', 1, '{"id": "2138", "target": "cardiovascular system", "name_en": "stationary bike run v. 3", "name_zh": "固定自行车快速骑行（变式3）", "body_part": "cardio", "equipment": "stationary bike", "gif_asset": "assets/fitness/videos/2138-H1PESYI.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "固定自行車快速騎行（變式3）", "instructions_en": ["Adjust the seat height and position to ensure proper alignment.", "Place your feet on the pedals and secure them with the straps if available.", "Start pedaling at a comfortable pace.", "Maintain a steady rhythm and increase the resistance as desired.", "Engage your core muscles to maintain stability and proper posture.", "Continue pedaling for the desired duration of your workout.", "Gradually decrease the resistance and slow down before coming to a complete stop.", "Stretch your legs and cool down after the workout."], "instructions_zh": ["调整座椅高度和位置以确保正确对齐。", "将脚放在踏板上，并用带子（如果有）将其固定。", "以舒适的速度开始踩踏板。", "保持稳定的节奏并根据需要增加阻力。", "调动核心肌肉以保持稳定性和正确的姿势。", "继续踩踏板达到所需的锻炼时间。", "逐渐减小阻力并减速，然后完全停止。", "锻炼后伸展双腿并放松。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["調整座椅高度和位置以確保正確對齊。", "將腳放在踏板上，并用帶子（如果有）將其固定。", "以舒適的速度開始踩踏板。", "保持穩定的節奏并根據需要增加阻力。", "調動核心肌肉以保持穩定性和正確的姿勢。", "繼續踩踏板達到所需的鍛煉時間。", "逐漸減小阻力并減速，然后完全停止。", "鍛煉后伸展雙腿并放松。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3314', 'exercise', 1, '{"id": "3314", "target": "abs", "name_en": "straddle maltese", "name_zh": "分腿马耳他十字", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3314-HfqciZF.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "分腿馬耳他十字", "instructions_en": ["Start by hanging from a pair of rings with your arms fully extended and your body in a straight line.", "Spread your legs wide apart, forming a straddle position.", "Engage your core and slowly lower your body until your arms are parallel to the ground.", "Hold this position for a few seconds, then push yourself back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先，悬挂在一对环上，双臂完全伸展，身体呈一条直线。", "双腿分开，形成跨坐姿势。", "启动你的核心并慢慢降低你的身体，直到你的手臂与地面平行。", "保持这个姿势几秒钟，然后将自己推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "chest"], "instructions_zh_hant": ["首先，懸掛在一對環上，雙臂完全伸展，身體呈一條直線。", "雙腿分開，形成跨坐姿勢。", "啟動你的核心并慢慢降低你的身體，直到你的手臂與地面平行。", "保持這個姿勢幾秒鐘，然后將自己推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3298', 'exercise', 1, '{"id": "3298", "target": "abs", "name_en": "straddle planche", "name_zh": "分腿俄式挺身", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3298-BL3GHeY.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "分腿俄式挺身", "instructions_en": ["Start in a push-up position with your hands shoulder-width apart and your feet spread wide apart.", "Engage your core and slowly shift your weight forward, bringing your shoulders over your hands.", "Bend your elbows and lower your body towards the ground, keeping your elbows close to your sides.", "Pause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["从俯卧撑位置开始，双手与肩同宽，双脚分开。", "启动你的核心，慢慢地将你的重心向前移动，将你的肩膀放在你的手上。", "弯曲肘部，将身体放低至地面，保持肘部靠近身体两侧。", "在底部停顿片刻，然后双手用力伸直手臂，将身体抬回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps", "chest"], "instructions_zh_hant": ["從俯臥撐位置開始，雙手與肩同寬，雙腳分開。", "啟動你的核心，慢慢地將你的重心向前移動，將你的肩膀放在你的手上。", "彎曲肘部，將身體放低至地面，保持肘部靠近身體兩側。", "在底部停頓片刻，然后雙手用力伸直手臂，將身體抬回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1427', 'exercise', 1, '{"id": "1427", "target": "abductors", "name_en": "straight leg outer hip abductor", "name_zh": "直腿髋外展", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1427-mQ1tBXn.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "直腿髖外展", "instructions_en": ["Lie on your side with your legs straight and stacked on top of each other.", "Place your bottom arm under your head for support.", "Engage your core and lift your top leg as high as possible without rotating your hips or leaning backward.", "Pause for a moment at the top, then slowly lower your leg back down to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["侧躺，双腿伸直并叠放在一起。", "将下臂放在头下方以获得支撑。", "启动你的核心并尽可能高地抬起你的上腿，不要旋转你的臀部或向后倾斜。", "在顶部暂停片刻，然后慢慢将腿放回起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["glutes", "hamstrings"], "instructions_zh_hant": ["側躺，雙腿伸直并疊放在一起。", "將下臂放在頭下方以獲得支撐。", "啟動你的核心并盡可能高地抬起你的上腿，不要旋轉你的臀部或向后傾斜。", "在頂部暫停片刻，然后慢慢將腿放回起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0803', 'exercise', 1, '{"id": "0803", "target": "pectorals", "name_en": "superman push-up", "name_zh": "超人式俯卧撑", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0803-4GqRrAk.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "超人式俯臥撐", "instructions_en": ["Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.", "Engage your core and lower your body towards the ground, keeping your elbows close to your sides.", "As you lower your body, simultaneously lift your right arm and left leg off the ground, extending them straight out.", "Pause for a moment at the top, then lower your arm and leg back down while pushing yourself back up to the starting position.", "Repeat the movement, this time lifting your left arm and right leg.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["从高位平板支撑开始，双手分开略宽于肩宽，双脚并拢。", "收紧核心，将身体降低到地面，保持肘部靠近身体两侧。", "当你降低身体时，同时将右臂和左腿抬离地面，笔直向外伸展。", "在顶部暂停片刻，然后放下手臂和腿，同时将自己推回起始位置。", "重复该动作，这次抬起左臂和右腿。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["core", "shoulders"], "instructions_zh_hant": ["從高位平板支撐開始，雙手分開略寬于肩寬，雙腳并攏。", "收緊核心，將身體降低到地面，保持肘部靠近身體兩側。", "當你降低身體時，同時將右臂和左腿抬離地面，筆直向外伸展。", "在頂部暫停片刻，然后放下手臂和腿，同時將自己推回起始位置。", "重復該動作，這次抬起左臂和右腿。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0805', 'exercise', 1, '{"id": "0805", "target": "abs", "name_en": "suspended abdominal fallout", "name_zh": "悬吊腹部前伸", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0805-X3TCNEU.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "懸吊腹部前伸", "instructions_en": ["Attach a suspension trainer to a high anchor point and adjust the straps to waist height.", "Stand facing away from the anchor point and hold the handles with your arms extended in front of you.", "Lean forward at the waist, keeping your body straight and your core engaged.", "Lower your body as far as you can while maintaining control and tension in your abs.", "Pause for a moment at the bottom, then slowly raise your body back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将悬挂训练器连接到高锚点并将带子调整至腰部高度。", "背对锚点站立，并握住手柄，双臂向前伸展。", "腰部向前倾，保持身体挺直，核心肌群参与。", "尽可能降低身体，同时保持腹肌的控制和紧张。", "在底部停顿片刻，然后慢慢抬起身体回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["obliques", "hip flexors"], "instructions_zh_hant": ["將懸掛訓練器連接到高錨點并將帶子調整至腰部高度。", "背對錨點站立，并握住手柄，雙臂向前伸展。", "腰部向前傾，保持身體挺直，核心肌群參與。", "盡可能降低身體，同時保持腹肌的控制和緊張。", "在底部停頓片刻，然后慢慢抬起身體回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0806', 'exercise', 1, '{"id": "0806", "target": "pectorals", "name_en": "suspended push-up", "name_zh": "悬吊俯卧撑", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0806-IaGQCrC.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "懸吊俯臥撐", "instructions_en": ["Find a suspension trainer and adjust it to an appropriate height.", "Stand facing away from the anchor point and hold the handles with an overhand grip.", "Walk your feet forward, leaning your body forward until your weight is supported by the suspension trainer.", "Keep your body straight from head to heels, engage your core, and lower your chest towards the handles.", "Push through your chest and arms to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["找到一个悬挂训练器并将其调整到合适的高度。", "背对锚点站立，并用正手握住手柄。", "双脚向前走，身体向前倾斜，直到悬架训练器支撑您的体重。", "保持身体从头到脚跟伸直，核心部位收紧，胸部朝手柄方向降低。", "推动你的胸部和手臂回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders", "core"], "instructions_zh_hant": ["找到一個懸掛訓練器并將其調整到合適的高度。", "背對錨點站立，并用正手握住手柄。", "雙腳向前走，身體向前傾斜，直到懸架訓練器支撐您的體重。", "保持身體從頭到腳跟伸直，核心部位收緊，胸部朝手柄方向降低。", "推動你的胸部和手臂回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0807', 'exercise', 1, '{"id": "0807", "target": "abs", "name_en": "suspended reverse crunch", "name_zh": "悬吊反向卷腹", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0807-R1WYG5D.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "懸吊反向卷腹", "instructions_en": ["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.", "Engage your core and lift your knees up towards your chest, curling your pelvis towards your ribcage.", "Pause for a moment at the top, then slowly lower your knees back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。", "收紧核心肌群，将膝盖抬向胸部，将骨盆卷向胸腔。", "在顶部暂停片刻，然后慢慢将膝盖放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["懸掛在引體向上桿上，雙臂完全伸展，手掌背向自己。", "收緊核心肌群，將膝蓋抬向胸部，將骨盆卷向胸腔。", "在頂部暫停片刻，然后慢慢將膝蓋放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0808', 'exercise', 1, '{"id": "0808", "target": "upper back", "name_en": "suspended row", "name_zh": "悬吊划船", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0808-4OaumBr.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "懸吊劃船", "instructions_en": ["Set up a suspension trainer at an appropriate height.", "Stand facing the anchor point with your feet shoulder-width apart.", "Hold the handles with an overhand grip, palms facing each other.", "Lean back, keeping your body straight and your heels on the ground.", "Pull your chest towards the handles, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower yourself back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将悬挂训练器设置在适当的高度。", "面向锚点站立，双脚分开与肩同宽。", "正手握住手柄，手掌相对。", "向后倾斜，保持身体挺直，脚后跟着地。", "将胸部拉向手柄，将肩胛骨挤压在一起。", "在顶部停顿片刻，然后慢慢降低回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "shoulders"], "instructions_zh_hant": ["將懸掛訓練器設置在適當的高度。", "面向錨點站立，雙腳分開與肩同寬。", "正手握住手柄，手掌相對。", "向后傾斜，保持身體挺直，腳后跟著地。", "將胸部拉向手柄，將肩胛骨擠壓在一起。", "在頂部停頓片刻，然后慢慢降低回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0809', 'exercise', 1, '{"id": "0809", "target": "quads", "name_en": "suspended split squat", "name_zh": "悬吊分腿蹲", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0809-QpXqiq8.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "懸吊分腿蹲", "instructions_en": ["Stand facing away from a suspension trainer with your feet shoulder-width apart.", "Extend one leg forward and place the top of your foot in the foot cradle of the suspension trainer.", "Bend your standing leg and lower your body down into a lunge position, keeping your chest up and your knee in line with your toes.", "Push through your heel to return to the starting position.", "Repeat for the desired number of repetitions, then switch legs."], "instructions_zh": ["背对悬吊训练器站立，双脚与肩同宽。", "向前伸展一条腿，将脚背放在悬吊训练器的脚托中。", "弯曲站立的腿，将身体降低到弓步位置，保持胸部向上，膝盖与脚趾对齐。", "推动脚后跟返回到起始位置。", "重复所需的重复次数，然后换腿。"], "secondary_muscles": ["glutes", "hamstrings", "calves"], "instructions_zh_hant": ["背對懸吊訓練器站立，雙腳與肩同寬。", "向前伸展一條腿，將腳背放在懸吊訓練器的腳托中。", "彎曲站立的腿，將身體降低到弓步位置，保持胸部向上，膝蓋與腳趾對齊。", "推動腳后跟返回到起始位置。", "重復所需的重復次數，然后換腿。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0814', 'exercise', 1, '{"id": "0814", "target": "triceps", "name_en": "triceps dip", "name_zh": "臂屈伸", "body_part": "upper arms", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0814-X6C6i5Y.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "臂屈伸", "instructions_en": ["Sit on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward.", "Slide your butt off the bench, supporting your weight with your hands.", "Bend your elbows and lower your body towards the ground, keeping your back close to the bench.", "Pause for a moment at the bottom, then push yourself back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳或椅子的边缘，双手抓住边缘，手指指向前方。", "将臀部滑离长凳，用手支撑体重。", "弯曲肘部，将身体放低至地面，保持背部靠近长凳。", "在底部暂停片刻，然后将自己推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["坐在長凳或椅子的邊緣，雙手抓住邊緣，手指指向前方。", "將臀部滑離長凳，用手支撐體重。", "彎曲肘部，將身體放低至地面，保持背部靠近長凳。", "在底部暫停片刻，然后將自己推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3433', 'exercise', 1, '{"id": "3433", "target": "glutes", "name_en": "swimmer kicks v. 2 (male)", "name_zh": "游泳式踢腿变式2（男性示范）", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3433-SP3hUez.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "游泳式踢腿變式2（男性示范）", "instructions_en": ["Lie face down on a mat with your arms extended overhead.", "Engage your core and lift your chest and legs off the ground simultaneously.", "Kick your legs up and down in a fluttering motion, as if you were swimming.", "Continue kicking for the desired number of repetitions.", "Lower your chest and legs back down to the starting position."], "instructions_zh": ["脸朝下躺在垫子上，双臂伸过头顶。", "启动核心肌群，同时将胸部和腿部抬离地面。", "以扑动的动作上下踢腿，就像在游泳一样。", "继续踢所需的重复次数。", "将胸部和双腿放低至起始位置。"], "secondary_muscles": ["hamstrings", "quadriceps", "calves"], "instructions_zh_hant": ["臉朝下躺在墊子上，雙臂伸過頭頂。", "啟動核心肌群，同時將胸部和腿部抬離地面。", "以撲動的動作上下踢腿，就像在游泳一樣。", "繼續踢所需的重復次數。", "將胸部和雙腿放低至起始位置。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3318', 'exercise', 1, '{"id": "3318", "target": "cardiovascular system", "name_en": "swing 360", "name_zh": "360度回环摆荡", "body_part": "cardio", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3318-tnaj0mT.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "360度回環擺蕩", "instructions_en": ["Stand with your feet shoulder-width apart and knees slightly bent.", "Hold your arms straight out in front of you, parallel to the ground.", "Engage your core and swing your arms in a circular motion, rotating your torso as you do so.", "Continue the circular motion, swinging your arms and rotating your torso for the desired number of repetitions.", "Remember to breathe throughout the exercise."], "instructions_zh": ["站立，双脚分开与肩同宽，膝盖稍微弯曲。", "将双臂伸直在身前，与地面平行。", "启动你的核心并以圆周运动摆动你的手臂，同时旋转你的躯干。", "继续圆周运动，摆动手臂并旋转躯干，达到所需的重复次数。", "记住在整个练习过程中保持呼吸。"], "secondary_muscles": ["shoulders", "core"], "instructions_zh_hant": ["站立，雙腳分開與肩同寬，膝蓋稍微彎曲。", "將雙臂伸直在身前，與地面平行。", "啟動你的核心并以圓周運動擺動你的手臂，同時旋轉你的軀幹。", "繼續圓周運動，擺動手臂并旋轉軀幹，達到所需的重復次數。", "記住在整個練習過程中保持呼吸。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1753', 'exercise', 1, '{"id": "1753", "target": "triceps", "name_en": "three bench dip", "name_zh": "三凳上臂屈伸", "body_part": "upper arms", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1753-DQ0cqkT.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "三凳上臂屈伸", "instructions_en": ["Sit on a bench with your hands gripping the edge, fingers pointing forward.", "Slide your butt off the bench, supporting your weight with your hands.", "Bend your elbows and lower your body until your upper arms are parallel to the ground.", "Push yourself back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双手抓住边缘，手指指向前方。", "将臀部滑离长凳，用手支撑体重。", "弯曲肘部并降低身体，直到上臂与地面平行。", "将自己推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["坐在長凳上，雙手抓住邊緣，手指指向前方。", "將臀部滑離長凳，用手支撐體重。", "彎曲肘部并降低身體，直到上臂與地面平行。", "將自己推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2459', 'exercise', 1, '{"id": "2459", "target": "glutes", "name_en": "tire flip", "name_zh": "轮胎翻转", "body_part": "upper legs", "equipment": "tire", "gif_asset": "assets/fitness/videos/2459-oZjMu1t.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "輪胎翻轉", "instructions_en": ["Stand with your feet shoulder-width apart, facing the tire.", "Bend your knees and hinge at the hips, lowering into a squat position.", "Reach down and grab the bottom edge of the tire with both hands, fingers facing towards you.", "Engage your glutes and leg muscles, and explosively drive through your legs to lift the tire off the ground.", "As the tire flips over, use your upper body strength to guide it and maintain control.", "Once the tire is fully flipped, quickly step back and reset your stance.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，面向轮胎。", "弯曲膝盖并以臀部为铰链，降低至蹲姿。", "向下伸手，用双手抓住轮胎的底部边缘，手指朝向您。", "调动你的臀部和腿部肌肉，并爆发性地推动你的腿，将轮胎抬离地面。", "当轮胎翻转时，用上半身的力量引导轮胎并保持控制。", "轮胎完全翻转后，迅速后退并重置姿势。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "quadriceps", "core"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，面向輪胎。", "彎曲膝蓋并以臀部為鉸鏈，降低至蹲姿。", "向下伸手，用雙手抓住輪胎的底部邊緣，手指朝向您。", "調動你的臀部和腿部肌肉，并爆發性地推動你的腿，將輪胎抬離地面。", "當輪胎翻轉時，用上半身的力量引導輪胎并保持控制。", "輪胎完全翻轉后，迅速后退并重置姿勢。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0811', 'exercise', 1, '{"id": "0811", "target": "glutes", "name_en": "trap bar deadlift", "name_zh": "六角杠铃硬拉", "body_part": "upper legs", "equipment": "trap bar", "gif_asset": "assets/fitness/videos/0811-jQGwmxN.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "六角槓鈴硬拉", "instructions_en": ["Stand with your feet shoulder-width apart and the trap bar on the ground in front of you.", "Bend at the hips and knees to lower yourself down and grip the handles of the trap bar with an overhand grip.", "Keep your back straight and chest up as you begin to lift the trap bar off the ground by extending your hips and knees.", "As you lift, focus on driving through your heels and squeezing your glutes at the top of the movement.", "Lower the trap bar back down to the ground by bending at the hips and knees, keeping your back straight throughout the movement.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，将陷阱杆放在你面前的地面上。", "弯曲臀部和膝盖，降低身体高度，并用正手握住陷阱杆的手柄。", "当你开始通过伸展臀部和膝盖将陷阱杆抬离地面时，保持背部挺直，挺胸。", "当你举起时，专注于通过脚后跟发力，并在运动的最高点挤压臀部。", "弯曲臀部和膝盖，将陷阱杆放回地面，在整个运动过程中保持背部挺直。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "quadriceps", "lower back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，將陷阱桿放在你面前的地面上。", "彎曲臀部和膝蓋，降低身體高度，并用正手握住陷阱桿的手柄。", "當你開始通過伸展臀部和膝蓋將陷阱桿抬離地面時，保持背部挺直，挺胸。", "當你舉起時，專注于通過腳后跟發力，并在運動的最高點擠壓臀部。", "彎曲臀部和膝蓋，將陷阱桿放回地面，在整個運動過程中保持背部挺直。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0812', 'exercise', 1, '{"id": "0812", "target": "triceps", "name_en": "triceps dip (bench leg)", "name_zh": "凳上垫腿臂屈伸", "body_part": "upper arms", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0812-VuoerH0.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "凳上墊腿臂屈伸", "instructions_en": ["Sit on the edge of a bench with your hands gripping the edge, fingers pointing forward.", "Walk your feet forward, sliding your butt off the bench, and straighten your arms.", "Bend your elbows and lower your body towards the ground, keeping your back close to the bench.", "Push through your palms to straighten your arms and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳边缘，双手抓住边缘，手指指向前方。", "双脚向前走，将臀部滑离长凳，然后伸直手臂。", "弯曲肘部，将身体放低至地面，保持背部靠近长凳。", "推动手掌以伸直手臂并返回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["坐在長凳邊緣，雙手抓住邊緣，手指指向前方。", "雙腳向前走，將臀部滑離長凳，然后伸直手臂。", "彎曲肘部，將身體放低至地面，保持背部靠近長凳。", "推動手掌以伸直手臂并返回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0813', 'exercise', 1, '{"id": "0813", "target": "triceps", "name_en": "triceps dip (between benches)", "name_zh": "双凳臂屈伸", "body_part": "upper arms", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0813-Wgbn9qo.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "雙凳臂屈伸", "instructions_en": ["Sit on a bench with your hands gripping the edge of the bench, fingers pointing forward.", "Slide your butt off the bench, supporting your weight with your hands.", "Bend your elbows and lower your body towards the ground, keeping your back close to the bench.", "Pause for a moment at the bottom, then push yourself back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双手抓住长凳边缘，手指指向前方。", "将臀部滑离长凳，用手支撑体重。", "弯曲肘部，将身体放低至地面，保持背部靠近长凳。", "在底部暂停片刻，然后将自己推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["坐在長凳上，雙手抓住長凳邊緣，手指指向前方。", "將臀部滑離長凳，用手支撐體重。", "彎曲肘部，將身體放低至地面，保持背部靠近長凳。", "在底部暫停片刻，然后將自己推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0815', 'exercise', 1, '{"id": "0815", "target": "triceps", "name_en": "triceps dips floor", "name_zh": "地板臂屈伸", "body_part": "upper arms", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0815-7aVz15j.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "地板臂屈伸", "instructions_en": ["Sit on the edge of a chair or bench with your hands next to your hips, fingers pointing forward.", "Slide your butt off the front of the chair with your legs extended in front of you.", "Straighten your arms, keeping a little bend in your elbows to keep tension on your triceps and off your elbow joints.", "Slowly bend your elbows to lower your body toward the floor until your elbows are at about a 90-degree angle.", "Once you reach the bottom of the movement, press down into the chair to straighten your elbows, returning to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在椅子或长凳的边缘，双手放在臀部旁边，手指指向前方。", "将你的屁股从椅子前面滑下来，双腿伸到你面前。", "伸直手臂，保持肘部稍微弯曲，以保持三头肌和肘关节的张力。", "慢慢弯曲你的肘部，将你的身体向地板降低，直到你的肘部成大约 90 度角。", "一旦到达动作的底部，向下压入椅子以伸直肘部，返回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["坐在椅子或長凳的邊緣，雙手放在臀部旁邊，手指指向前方。", "將你的屁股從椅子前面滑下來，雙腿伸到你面前。", "伸直手臂，保持肘部稍微彎曲，以保持三頭肌和肘關節的張力。", "慢慢彎曲你的肘部，將你的身體向地板降低，直到你的肘部成大約 90 度角。", "一旦到達動作的底部，向下壓入椅子以伸直肘部，返回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0816', 'exercise', 1, '{"id": "0816", "target": "triceps", "name_en": "triceps press", "name_zh": "肱三头肌推举", "body_part": "upper arms", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0816-fSrPP6B.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "肱三頭肌推舉", "instructions_en": ["Stand with your feet shoulder-width apart and your knees slightly bent.", "Extend your arms straight out in front of you, parallel to the ground.", "Bend your elbows and lower your body towards the ground, keeping your upper arms close to your sides.", "Pause for a moment at the bottom, then push yourself back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，膝盖稍微弯曲。", "将双臂伸直在身前，与地面平行。", "弯曲肘部，将身体放低至地面，保持上臂靠近身体两侧。", "在底部暂停片刻，然后将自己推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，膝蓋稍微彎曲。", "將雙臂伸直在身前，與地面平行。", "彎曲肘部，將身體放低至地面，保持上臂靠近身體兩側。", "在底部暫停片刻，然后將自己推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0817', 'exercise', 1, '{"id": "0817", "target": "triceps", "name_en": "triceps stretch", "name_zh": "肱三头肌拉伸", "body_part": "upper arms", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0817-uOV3Itw.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "肱三頭肌拉伸", "instructions_en": ["Stand or sit upright with your back straight.", "Extend one arm overhead, bending it at the elbow.", "Place your opposite hand on the bent elbow and gently pull it towards your head.", "Hold the stretch for 15-30 seconds, feeling a gentle stretch in your triceps.", "Release the stretch and repeat on the other arm."], "instructions_zh": ["站立或坐直，背部挺直。", "将一只手臂伸过头顶，肘部弯曲。", "将另一只手放在弯曲的肘部上，然后轻轻地将其拉向头部。", "保持拉伸 15-30 秒，感受三头肌的轻微拉伸。", "松开拉伸并在另一只手臂上重复。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["站立或坐直，背部挺直。", "將一只手臂伸過頭頂，肘部彎曲。", "將另一只手放在彎曲的肘部上，然后輕輕地將其拉向頭部。", "保持拉伸 15-30 秒，感受三頭肌的輕微拉伸。", "松開拉伸并在另一只手臂上重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0871', 'exercise', 1, '{"id": "0871", "target": "abs", "name_en": "tuck crunch", "name_zh": "团身卷腹", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0871-BMMolZ3.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "團身卷腹", "instructions_en": ["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, lift your shoulder blades off the ground and bring your knees towards your chest, simultaneously curling your upper body towards your knees.", "Pause for a moment at the top, then slowly lower your shoulder blades and extend your legs back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，膝盖弯曲，双脚平放在地上。", "将双手放在脑后，肘部朝外。", "收紧腹肌，将肩胛骨抬离地面，将膝盖靠近胸部，同时将上半身卷向膝盖。", "在顶部停顿片刻，然后慢慢降低肩胛骨并将双腿伸展回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["平躺，膝蓋彎曲，雙腳平放在地上。", "將雙手放在腦后，肘部朝外。", "收緊腹肌，將肩胛骨抬離地面，將膝蓋靠近胸部，同時將上半身卷向膝蓋。", "在頂部停頓片刻，然后慢慢降低肩胛骨并將雙腿伸展回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0818', 'exercise', 1, '{"id": "0818", "target": "lats", "name_en": "twin handle parallel grip lat pulldown", "name_zh": "双把手对握高位下拉", "body_part": "back", "equipment": "cable", "gif_asset": "assets/fitness/videos/0818-rkg41Fb.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "雙把手對握高位下拉", "instructions_en": ["Adjust the seat height and position yourself facing the cable machine.", "Grasp the handles with an overhand grip, hands shoulder-width apart.", "Sit down and position your thighs under the thigh pads, keeping your feet flat on the floor.", "Lean back slightly and keep your chest up, maintaining a neutral spine.", "Pull the handles down towards your upper chest, squeezing your shoulder blades together.", "Pause for a moment at the bottom of the movement, feeling the contraction in your lats.", "Slowly release the handles and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["调整座椅高度并将自己面向电缆机。", "正手握住手柄，双手与肩同宽。", "坐下来，将大腿放在大腿垫下方，保持双脚平放在地板上。", "稍微向后倾斜，挺胸，保持脊柱中立。", "将手柄向下拉至上胸部，将肩胛骨挤压在一起。", "在动作的底部暂停片刻，感受背阔肌的收缩。", "慢慢松开手柄并返回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "rhomboids", "rear deltoids"], "instructions_zh_hant": ["調整座椅高度并將自己面向電纜機。", "正手握住手柄，雙手與肩同寬。", "坐下來，將大腿放在大腿墊下方，保持雙腳平放在地板上。", "稍微向后傾斜，挺胸，保持脊柱中立。", "將手柄向下拉至上胸部，將肩胛骨擠壓在一起。", "在動作的底部暫停片刻，感受背闊肌的收縮。", "慢慢松開手柄并返回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1466', 'exercise', 1, '{"id": "1466", "target": "glutes", "name_en": "twist hip lift", "name_zh": "转体提髋", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1466-AX1kB0o.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "轉體提髖", "instructions_en": ["Lie on your back with your knees bent and feet flat on the ground.", "Place your hands by your sides for support.", "Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.", "While keeping your hips lifted, twist your lower body to the right side, bringing your knees towards the ground.", "Return to the starting position and repeat the twist to the left side.", "Continue alternating twists for the desired number of repetitions."], "instructions_zh": ["仰卧，膝盖弯曲，双脚平放在地上。", "将双手放在身体两侧以获得支撑。", "收紧臀部并将臀部抬离地面，从膝盖到肩膀形成一条直线。", "在保持臀部抬起的同时，将下半身扭转到右侧，使膝盖靠近地面。", "返回起始位置并向左侧重复扭转。", "继续交替扭转所需的重复次数。"], "secondary_muscles": ["obliques", "hamstrings"], "instructions_zh_hant": ["仰臥，膝蓋彎曲，雙腳平放在地上。", "將雙手放在身體兩側以獲得支撐。", "收緊臀部并將臀部抬離地面，從膝蓋到肩膀形成一條直線。", "在保持臀部抬起的同時，將下半身扭轉到右側，使膝蓋靠近地面。", "返回起始位置并向左側重復扭轉。", "繼續交替扭轉所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2802', 'exercise', 1, '{"id": "2802", "target": "abs", "name_en": "twisted leg raise", "name_zh": "转体举腿", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/2802-C0eCeEt.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "轉體舉腿", "instructions_en": ["Lie flat on your back with your legs extended and your arms by your sides.", "Place your hands under your glutes for support.", "Engage your abs and lift both legs off the ground, keeping them straight.", "As you lift your legs, twist your hips to one side, bringing your legs towards your opposite shoulder.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat the movement, this time twisting your hips to the other side.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["平躺，双腿伸展，双臂放在身体两侧。", "将双手放在臀部下方以获得支撑。", "收紧腹肌，将双腿抬离地面，保持伸直。", "当你抬起双腿时，将臀部扭向一侧，将双腿拉向对面的肩膀。", "在顶部暂停片刻，然后慢慢将双腿放回起始位置。", "重复这个动作，这次将臀部扭到另一侧。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["obliques", "hip flexors"], "instructions_zh_hant": ["平躺，雙腿伸展，雙臂放在身體兩側。", "將雙手放在臀部下方以獲得支撐。", "收緊腹肌，將雙腿抬離地面，保持伸直。", "當你抬起雙腿時，將臀部扭向一側，將雙腿拉向對面的肩膀。", "在頂部暫停片刻，然后慢慢將雙腿放回起始位置。", "重復這個動作，這次將臀部扭到另一側。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2801', 'exercise', 1, '{"id": "2801", "target": "abs", "name_en": "twisted leg raise (female)", "name_zh": "转体举腿（女性示范）", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/2801-yT9tk17.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "轉體舉腿（女性示范）", "instructions_en": ["Lie flat on your back with your legs extended and your arms by your sides.", "Bend your knees and lift your legs off the ground, bringing them towards your chest.", "As you lift your legs, twist your hips to one side, bringing your knees towards your opposite shoulder.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat the movement, this time twisting your hips to the other side.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["平躺，双腿伸展，双臂放在身体两侧。", "弯曲膝盖，将双腿抬离地面，将它们拉向胸部。", "当你抬起双腿时，将臀部扭向一侧，将膝盖移向另一侧的肩膀。", "在顶部暂停片刻，然后慢慢将双腿放回起始位置。", "重复这个动作，这次将臀部扭到另一侧。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["obliques", "hip flexors"], "instructions_zh_hant": ["平躺，雙腿伸展，雙臂放在身體兩側。", "彎曲膝蓋，將雙腿抬離地面，將它們拉向胸部。", "當你抬起雙腿時，將臀部扭向一側，將膝蓋移向另一側的肩膀。", "在頂部暫停片刻，然后慢慢將雙腿放回起始位置。", "重復這個動作，這次將臀部扭到另一側。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3231', 'exercise', 1, '{"id": "3231", "target": "spine", "name_en": "two toe touch (male)", "name_zh": "双手触脚尖（男性示范）", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3231-p195zsJ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "雙手觸腳尖（男性示范）", "instructions_en": ["Stand with your feet shoulder-width apart and your arms extended out to the sides.", "Bend forward at the waist, keeping your back straight and your knees slightly bent.", "Reach down towards your toes with both hands, keeping your legs straight.", "Pause for a moment at the bottom, then slowly return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双臂向两侧伸展。", "腰部向前弯曲，保持背部挺直，膝盖稍微弯曲。", "双手向下伸向脚趾，保持双腿伸直。", "在底部停顿片刻，然后慢慢回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hamstrings", "glutes"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙臂向兩側伸展。", "腰部向前彎曲，保持背部挺直，膝蓋稍微彎曲。", "雙手向下伸向腳趾，保持雙腿伸直。", "在底部停頓片刻，然后慢慢回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1365', 'exercise', 1, '{"id": "1365", "target": "upper back", "name_en": "upper back stretch", "name_zh": "上背拉伸", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1365-GSDioYu.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "上背拉伸", "instructions_en": ["Stand up straight with your feet shoulder-width apart.", "Extend your arms straight in front of you, parallel to the ground.", "Interlace your fingers and rotate your palms away from your body.", "Slowly raise your arms overhead, keeping them straight and parallel to each other.", "As you raise your arms, squeeze your shoulder blades together.", "Hold the stretch for 15-30 seconds, then release and repeat."], "instructions_zh": ["站直，双脚分开与肩同宽。", "将双臂伸直在身前，与地面平行。", "手指交叉，手掌旋转远离身体。", "慢慢地将手臂举过头顶，保持它们伸直并彼此平行。", "当你举起手臂时，将肩胛骨挤压在一起。", "保持拉伸 15-30 秒，然后松开并重复。"], "secondary_muscles": ["shoulders"], "instructions_zh_hant": ["站直，雙腳分開與肩同寬。", "將雙臂伸直在身前，與地面平行。", "手指交叉，手掌旋轉遠離身體。", "慢慢地將手臂舉過頭頂，保持它們伸直并彼此平行。", "當你舉起手臂時，將肩胛骨擠壓在一起。", "保持拉伸 15-30 秒，然后松開并重復。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1366', 'exercise', 1, '{"id": "1366", "target": "spine", "name_en": "upward facing dog", "name_zh": "上犬式", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1366-01qpYSe.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "上犬式", "instructions_en": ["Lie face down on the floor with your legs extended behind you.", "Place your hands on the floor next to your lower ribs, fingers pointing forward.", "Press your hands firmly into the floor and straighten your arms, lifting your torso and thighs off the ground.", "Roll your shoulders back and down, opening your chest and lifting your gaze towards the ceiling.", "Hold this position for a few breaths, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["脸朝下躺在地板上，双腿伸到身后。", "将双手放在下肋骨旁边的地板上，手指指向前方。", "双手用力按在地板上，伸直手臂，将躯干和大腿抬离地面。", "向后和向下转动肩膀，打开胸部，将目光转向天花板。", "保持这个姿势几次呼吸，然后慢慢将身体放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "chest"], "instructions_zh_hant": ["臉朝下躺在地板上，雙腿伸到身后。", "將雙手放在下肋骨旁邊的地板上，手指指向前方。", "雙手用力按在地板上，伸直手臂，將軀幹和大腿抬離地面。", "向后和向下轉動肩膀，打開胸部，將目光轉向天花板。", "保持這個姿勢幾次呼吸，然后慢慢將身體放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3420', 'exercise', 1, '{"id": "3420", "target": "abs", "name_en": "v-sit on floor", "name_zh": "V形坐撑（地板）", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3420-ZuXu4Eq.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "V形坐撐（地板）", "instructions_en": ["Sit on the floor with your legs extended in front of you.", "Lean back slightly and lift your legs off the ground, keeping them straight.", "Simultaneously, lift your upper body off the ground and reach your arms towards your legs.", "Hold this position for a few seconds, then slowly lower your upper body and legs back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在地板上，双腿伸到身前。", "稍微向后倾斜，将双腿抬离地面，保持伸直。", "同时，将上半身抬离地面，并将手臂伸向腿部。", "保持这个姿势几秒钟，然后慢慢降低上半身和双腿回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["坐在地板上，雙腿伸到身前。", "稍微向后傾斜，將雙腿抬離地面，保持伸直。", "同時，將上半身抬離地面，并將手臂伸向腿部。", "保持這個姿勢幾秒鐘，然后慢慢降低上半身和雙腿回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0826', 'exercise', 1, '{"id": "0826", "target": "abs", "name_en": "vertical leg raise (on parallel bars)", "name_zh": "垂直举腿（于平行双杠）", "body_part": "waist", "equipment": "body weight", "gif_asset": "assets/fitness/videos/0826-ZNgOYQU.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "垂直舉腿（于平行雙槓）", "instructions_en": ["Hang from the parallel bars with your arms fully extended and your body straight.", "Engage your core and lift your legs up in front of you, keeping them straight.", "Continue lifting until your legs are parallel to the ground or slightly higher.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["悬挂在双杠上，双臂完全伸展，身体伸直。", "启动你的核心并将双腿抬起到你面前，保持伸直。", "继续抬起，直到双腿与地面平行或稍高。", "在顶部暂停片刻，然后慢慢将双腿放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors"], "instructions_zh_hant": ["懸掛在雙杠上，雙臂完全伸展，身體伸直。", "啟動你的核心并將雙腿抬起到你面前，保持伸直。", "繼續抬起，直到雙腿與地面平行或稍高。", "在頂部暫停片刻，然后慢慢將雙腿放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3644', 'exercise', 1, '{"id": "3644", "target": "glutes", "name_en": "weighted lunge with swing", "name_zh": "负重弓步配合摆荡", "body_part": "upper legs", "equipment": "weighted", "gif_asset": "assets/fitness/videos/3644-5WiFcYk.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重弓步配合擺蕩", "instructions_en": ["Stand with your feet shoulder-width apart, holding a weight in each hand.", "Take a step forward with your right foot, lowering your body into a lunge position.", "As you lunge forward, swing the weights forward and upward, keeping your arms straight.", "Push off with your right foot and return to the starting position, swinging the weights back down.", "Repeat with your left foot and continue alternating legs for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，每只手各握一个重物。", "右脚向前迈出一步，将身体降低至弓步位置。", "当你向前冲时，向前和向上摆动重物，保持手臂伸直。", "用右脚推出并返回到起始位置，将重物向下摆动。", "用左脚重复上述动作，并继续交替双腿，完成所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，每只手各握一個重物。", "右腳向前邁出一步，將身體降低至弓步位置。", "當你向前沖時，向前和向上擺動重物，保持手臂伸直。", "用右腳推出并返回到起始位置，將重物向下擺動。", "用左腳重復上述動作，并繼續交替雙腿，完成所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3655', 'exercise', 1, '{"id": "3655", "target": "cardiovascular system", "name_en": "walking high knees lunge", "name_zh": "高抬膝行进弓步", "body_part": "cardio", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3655-J9zIWig.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "高抬膝行進弓步", "instructions_en": ["Stand with your feet hip-width apart.", "Lift your right knee up towards your chest as high as you can while balancing on your left leg.", "Step forward with your right foot and lower your body into a lunge position, bending both knees to a 90-degree angle.", "Push off with your right foot and bring your left knee up towards your chest.", "Step forward with your left foot and lower your body into a lunge position.", "Continue alternating legs and lunging forward, keeping your core engaged and maintaining a steady pace.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与臀部同宽站立。", "将右膝尽可能高地抬向胸部，同时用左腿保持平衡。", "右脚向前迈出一步，身体降低成弓步姿势，双膝弯曲成 90 度角。", "用右脚推出，并将左膝抬向胸部。", "左脚向前迈出一步，将身体降低至弓步位置。", "继续交替双腿并向前冲刺，保持核心参与并保持稳定的步伐。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "glutes", "calves"], "instructions_zh_hant": ["雙腳分開與臀部同寬站立。", "將右膝盡可能高地抬向胸部，同時用左腿保持平衡。", "右腳向前邁出一步，身體降低成弓步姿勢，雙膝彎曲成 90 度角。", "用右腳推出，并將左膝抬向胸部。", "左腳向前邁出一步，將身體降低至弓步位置。", "繼續交替雙腿并向前沖刺，保持核心參與并保持穩定的步伐。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1460', 'exercise', 1, '{"id": "1460", "target": "glutes", "name_en": "walking lunge", "name_zh": "行走弓步", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1460-IZVHb27.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "行走弓步", "instructions_en": ["Stand with your feet shoulder-width apart.", "Take a step forward with your right leg, lowering your body into a lunge position.", "Keep your torso upright and your front knee aligned with your ankle.", "Push off with your right foot and bring your left foot forward, stepping into a lunge position with your left leg.", "Continue alternating legs and walking forward, maintaining a controlled and steady pace.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立。", "右腿向前迈出一步，将身体降低至弓步位置。", "保持躯干直立，前膝与脚踝对齐。", "右脚蹬地，左脚向前，左腿呈弓步姿势。", "继续交替双腿向前行走，保持受控且稳定的步伐。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立。", "右腿向前邁出一步，將身體降低至弓步位置。", "保持軀幹直立，前膝與腳踝對齊。", "右腳蹬地，左腳向前，左腿呈弓步姿勢。", "繼續交替雙腿向前行走，保持受控且穩定的步伐。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3666', 'exercise', 1, '{"id": "3666", "target": "cardiovascular system", "name_en": "walking on incline treadmill", "name_zh": "行走（坡度跑步机）", "body_part": "cardio", "equipment": "leverage machine", "gif_asset": "assets/fitness/videos/3666-rjiM4L3.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "行走（坡度跑步機）", "instructions_en": ["Adjust the incline level on the treadmill to your desired intensity.", "Stand on the treadmill with your feet shoulder-width apart.", "Start walking at a comfortable pace, ensuring that you maintain proper form.", "Engage your core muscles and keep your back straight throughout the exercise.", "Continue walking on the incline treadmill for the desired duration of your cardio workout.", "Gradually decrease the incline and speed of the treadmill to cool down before stopping."], "instructions_zh": ["将跑步机的倾斜度调整到您想要的强度。", "站在跑步机上，双脚分开与肩同宽。", "开始以舒适的步伐行走，确保保持正确的姿势。", "在整个练习过程中，调动核心肌肉并保持背部挺直。", "继续在倾斜跑步机上行走，完成有氧运动所需的时间。", "逐渐降低跑步机的坡度和速度，使其冷却后再停止。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["將跑步機的傾斜度調整到您想要的強度。", "站在跑步機上，雙腳分開與肩同寬。", "開始以舒適的步伐行走，確保保持正確的姿勢。", "在整個練習過程中，調動核心肌肉并保持背部挺直。", "繼續在傾斜跑步機上行走，完成有氧運動所需的時間。", "逐漸降低跑步機的坡度和速度，使其冷卻后再停止。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2311', 'exercise', 1, '{"id": "2311", "target": "cardiovascular system", "name_en": "walking on stepmill", "name_zh": "行走（登阶机）", "body_part": "cardio", "equipment": "stepmill machine", "gif_asset": "assets/fitness/videos/2311-j9Q5crt.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "行走（登階機）", "instructions_en": ["Adjust the stepmill machine to a comfortable level.", "Step onto the machine and place your hands on the handrails for support.", "Start walking by placing one foot on a step and then the other, alternating between legs.", "Maintain an upright posture and engage your core muscles.", "Continue walking for the desired duration or distance.", "Gradually increase the intensity or speed as you become more comfortable with the exercise.", "Remember to cool down and stretch after completing the exercise."], "instructions_zh": ["将步进机调整到舒适的水平。", "走上机器，将双手放在扶手上以获得支撑。", "开始行走时，将一只脚放在台阶上，然后将另一只脚放在台阶上，双腿交替。", "保持直立姿势并锻炼核心肌肉。", "继续步行所需的时间或距离。", "当您对锻炼感到更加舒适时，逐渐增加强度或速度。", "完成练习后记得冷静下来并伸展身体。"], "secondary_muscles": ["quadriceps", "hamstrings", "glutes", "calves"], "instructions_zh_hant": ["將步進機調整到舒適的水平。", "走上機器，將雙手放在扶手上以獲得支撐。", "開始行走時，將一只腳放在臺階上，然后將另一只腳放在臺階上，雙腿交替。", "保持直立姿勢并鍛煉核心肌肉。", "繼續步行所需的時間或距離。", "當您對鍛煉感到更加舒適時，逐漸增加強度或速度。", "完成練習后記得冷靜下來并伸展身體。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0830', 'exercise', 1, '{"id": "0830", "target": "triceps", "name_en": "weighted bench dip", "name_zh": "负重凳上臂屈伸", "body_part": "upper arms", "equipment": "weighted", "gif_asset": "assets/fitness/videos/0830-MU9HnE7.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重凳上臂屈伸", "instructions_en": ["Sit on a bench with your hands gripping the edge, fingers pointing forward.", "Slide your butt off the bench, supporting your weight with your hands.", "Lower your body by bending your elbows until your upper arms are parallel to the floor.", "Push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳上，双手抓住边缘，手指指向前方。", "将臀部滑离长凳，用手支撑体重。", "弯曲肘部降低身体，直到上臂与地板平行。", "伸直手臂，将自己推回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["坐在長凳上，雙手抓住邊緣，手指指向前方。", "將臀部滑離長凳，用手支撐體重。", "彎曲肘部降低身體，直到上臂與地板平行。", "伸直手臂，將自己推回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2987', 'exercise', 1, '{"id": "2987", "target": "lats", "name_en": "weighted close grip chin-up on dip cage", "name_zh": "负重窄握反握引体向上于臂屈伸支架", "body_part": "back", "equipment": "weighted", "gif_asset": "assets/fitness/videos/2987-Gk1r408.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重窄握反握引體向上于臂屈伸支架", "instructions_en": ["Stand in front of the dip cage and grab the parallel bars with an underhand grip, hands shoulder-width apart.", "Hang from the bars with your arms fully extended, feet off the ground, and body straight.", "Engage your back muscles and pull your body up towards the bars, keeping your elbows close to your sides.", "Continue pulling until your chin is above the bars, then pause for a moment.", "Slowly lower your body back down to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["站在俯卧撑前面，用反握抓住双杠，双手与肩同宽。", "悬挂在杠上，双臂完全伸展，双脚离开地面，身体伸直。", "收紧背部肌肉，将身体拉向杠铃，保持肘部靠近身体两侧。", "继续拉，直到下巴高于杠铃，然后暂停片刻。", "慢慢地将身体放回起始位置，充分伸展双臂。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["站在俯臥撐前面，用反握抓住雙杠，雙手與肩同寬。", "懸掛在杠上，雙臂完全伸展，雙腳離開地面，身體伸直。", "收緊背部肌肉，將身體拉向杠鈴，保持肘部靠近身體兩側。", "繼續拉，直到下巴高于杠鈴，然后暫停片刻。", "慢慢地將身體放回起始位置，充分伸展雙臂。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3643', 'exercise', 1, '{"id": "3643", "target": "glutes", "name_en": "weighted cossack squats (male)", "name_zh": "负重哥萨克深蹲（男性示范）", "body_part": "upper legs", "equipment": "weighted", "gif_asset": "assets/fitness/videos/3643-GWoKnIm.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重哥薩克深蹲（男性示范）", "instructions_en": ["Stand with your feet wider than shoulder-width apart and toes pointing slightly outward.", "Hold a weight in front of your chest with both hands.", "Shift your weight to one side and lower your body by bending the knee of the side you shifted towards, while keeping the other leg straight.", "Go as low as you can while maintaining balance and keeping your chest up.", "Push through the heel of the bent leg to return to the starting position.", "Repeat on the other side, alternating between legs."], "instructions_zh": ["站立时双脚分开比肩宽，脚趾稍微向外。", "用双手将重物放在胸前。", "将您的体重转移到一侧，并通过弯曲您转移一侧的膝盖来降低身体，同时保持另一条腿伸直。", "尽可能降低身体高度，同时保持平衡并挺胸。", "推动弯曲腿的脚跟以返回到起始位置。", "在另一侧重复，双腿之间交替。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["站立時雙腳分開比肩寬，腳趾稍微向外。", "用雙手將重物放在胸前。", "將您的體重轉移到一側，并通過彎曲您轉移一側的膝蓋來降低身體，同時保持另一條腿伸直。", "盡可能降低身體高度，同時保持平衡并挺胸。", "推動彎曲腿的腳跟以返回到起始位置。", "在另一側重復，雙腿之間交替。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0832', 'exercise', 1, '{"id": "0832", "target": "abs", "name_en": "weighted crunch", "name_zh": "负重卷腹", "body_part": "waist", "equipment": "weighted", "gif_asset": "assets/fitness/videos/0832-s8nrDXF.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重卷腹", "instructions_en": ["Lie flat on your back with your knees bent and feet flat on the ground.", "Hold a weight plate or dumbbell on your chest.", "Engage your abs and lift your upper body off the ground, curling forward until your shoulder blades are off the ground.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺，膝盖弯曲，双脚平放在地上。", "将杠铃片或哑铃放在胸前。", "收紧腹肌，将上半身抬离地面，向前卷曲，直到肩胛骨离开地面。", "在顶部停顿片刻，然后慢慢将上半身放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["obliques"], "instructions_zh_hant": ["平躺，膝蓋彎曲，雙腳平放在地上。", "將杠鈴片或啞鈴放在胸前。", "收緊腹肌，將上半身抬離地面，向前卷曲，直到肩胛骨離開地面。", "在頂部停頓片刻，然后慢慢將上半身放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3670', 'exercise', 1, '{"id": "3670", "target": "abs", "name_en": "weighted decline sit-up", "name_zh": "负重下斜仰卧起坐", "body_part": "waist", "equipment": "weighted", "gif_asset": "assets/fitness/videos/3670-EZeDVzO.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重下斜仰臥起坐", "instructions_en": ["Lie flat on a decline bench with your feet secured under the foot pads.", "Place your hands behind your head or across your chest.", "Engage your abs and slowly lift your upper body off the bench, curling forward until your torso is perpendicular to the ground.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["平躺在倾斜的长凳上，双脚固定在脚垫下。", "将双手放在脑后或放在胸前。", "收紧腹肌，慢慢将上半身抬离长凳，向前卷曲，直到躯干垂直于地面。", "在顶部停顿片刻，然后慢慢将上半身放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors", "lower back"], "instructions_zh_hant": ["平躺在傾斜的長凳上，雙腳固定在腳墊下。", "將雙手放在腦后或放在胸前。", "收緊腹肌，慢慢將上半身抬離長凳，向前卷曲，直到軀幹垂直于地面。", "在頂部停頓片刻，然后慢慢將上半身放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1310', 'exercise', 1, '{"id": "1310", "target": "pectorals", "name_en": "weighted drop push up", "name_zh": "负重下落式俯卧撑", "body_part": "chest", "equipment": "weighted", "gif_asset": "assets/fitness/videos/1310-PSlvNMs.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重下落式俯臥撐", "instructions_en": ["Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.", "Lower your chest towards the ground, keeping your elbows close to your body.", "Once your chest is just above the ground, explosively push yourself up, lifting your hands off the ground.", "As you push up, quickly move your hands out to the sides and slightly forward, allowing your body to drop down towards the ground.", "Catch yourself with your hands in the wider position and immediately lower your chest towards the ground again.", "Repeat the push-up motion, dropping down and catching yourself with your hands in the narrower position.", "Continue alternating between the wider and narrower hand positions for the desired number of repetitions."], "instructions_zh": ["从高位平板支撑开始，双手分开略宽于肩宽，双脚并拢。", "将胸部压向地面，保持肘部靠近身体。", "一旦你的胸部刚好高于地面，爆发性地把自己推起来，将双手抬离地面。", "当你向上推时，快速将双手移至两侧并稍微向前，让你的身体向地面落下。", "将双手置于更宽的位置，然后立即再次将胸部降低到地面。", "重复俯卧撑动作，下降并用双手抓住自己在较窄的位置。", "继续在更宽和更窄的手位置之间交替，以达到所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["從高位平板支撐開始，雙手分開略寬于肩寬，雙腳并攏。", "將胸部壓向地面，保持肘部靠近身體。", "一旦你的胸部剛好高于地面，爆發性地把自己推起來，將雙手抬離地面。", "當你向上推時，快速將雙手移至兩側并稍微向前，讓你的身體向地面落下。", "將雙手置于更寬的位置，然后立即再次將胸部降低到地面。", "重復俯臥撐動作，下降并用雙手抓住自己在較窄的位置。", "繼續在更寬和更窄的手位置之間交替，以達到所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0834', 'exercise', 1, '{"id": "0834", "target": "delts", "name_en": "weighted front raise", "name_zh": "负重前平举", "body_part": "shoulders", "equipment": "weighted", "gif_asset": "assets/fitness/videos/0834-e4aFmFY.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重前平舉", "instructions_en": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.", "Keeping your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level.", "Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向大腿。", "保持双臂伸直，呼气并将哑铃举至身前，直至与肩齐平。", "在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴，手掌朝向大腿。", "保持雙臂伸直，呼氣并將啞鈴舉至身前，直至與肩齊平。", "在頂部停頓片刻，然后吸氣，慢慢將啞鈴放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0866', 'exercise', 1, '{"id": "0866", "target": "abs", "name_en": "weighted hanging leg-hip raise", "name_zh": "负重悬垂举腿提髋抬举", "body_part": "waist", "equipment": "weighted", "gif_asset": "assets/fitness/videos/0866-QOA0FD0.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重懸垂舉腿提髖抬舉", "instructions_en": ["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.", "Engage your core and lift your legs up in front of you, keeping them straight.", "Continue lifting until your legs are parallel to the ground or slightly higher.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。", "启动你的核心并将双腿抬起到你面前，保持伸直。", "继续抬起，直到双腿与地面平行或稍高。", "在顶部暂停片刻，然后慢慢将双腿放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["hip flexors", "lower back"], "instructions_zh_hant": ["懸掛在引體向上桿上，雙臂完全伸展，手掌背向自己。", "啟動你的核心并將雙腿抬起到你面前，保持伸直。", "繼續抬起，直到雙腿與地面平行或稍高。", "在頂部暫停片刻，然后慢慢將雙腿放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0835', 'exercise', 1, '{"id": "0835", "target": "spine", "name_en": "weighted hyperextension (on stability ball)", "name_zh": "负重挺身（健身球）", "body_part": "back", "equipment": "weighted", "gif_asset": "assets/fitness/videos/0835-8urJS9b.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重挺身（健身球）", "instructions_en": ["Position yourself face down on a stability ball with your hips resting on the ball and your feet against a wall for stability.", "Place your hands behind your head or cross them over your chest.", "Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将自己面朝下放在稳定球上，臀部放在球上，双脚靠在墙上以保持稳定。", "将双手放在脑后或交叉放在胸前。", "启动你的核心，慢慢地将你的上半身抬离球，伸展你的背部，直到你的身体形成一条直线。", "在顶部停顿片刻，然后慢慢将上半身放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings"], "instructions_zh_hant": ["將自己面朝下放在穩定球上，臀部放在球上，雙腳靠在墻上以保持穩定。", "將雙手放在腦后或交叉放在胸前。", "啟動你的核心，慢慢地將你的上半身抬離球，伸展你的背部，直到你的身體形成一條直線。", "在頂部停頓片刻，然后慢慢將上半身放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3641', 'exercise', 1, '{"id": "3641", "target": "delts", "name_en": "weighted kneeling step with swing", "name_zh": "负重跪姿踏步配合摆荡", "body_part": "shoulders", "equipment": "weighted", "gif_asset": "assets/fitness/videos/3641-7uFJuXp.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重跪姿踏步配合擺蕩", "instructions_en": ["Start in a kneeling position with your knees hip-width apart and your back straight.", "Hold a weight in each hand, with your arms extended straight down in front of you.", "Engage your core and swing the weights up and overhead, keeping your arms straight.", "Lower the weights back down to the starting position and repeat for the desired number of repetitions."], "instructions_zh": ["从跪姿开始，膝盖分开与臀部同宽，背部挺直。", "每只手各握一个重物，双臂在身前笔直向下伸展。", "启动你的核心肌群，将重物向上举过头顶，保持手臂伸直。", "将重量放回起始位置，然后重复所需的重复次数。"], "secondary_muscles": ["triceps", "core"], "instructions_zh_hant": ["從跪姿開始，膝蓋分開與臀部同寬，背部挺直。", "每只手各握一個重物，雙臂在身前筆直向下伸展。", "啟動你的核心肌群，將重物向上舉過頭頂，保持手臂伸直。", "將重量放回起始位置，然后重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3286', 'exercise', 1, '{"id": "3286", "target": "lats", "name_en": "weighted muscle up", "name_zh": "负重双力臂", "body_part": "back", "equipment": "weighted", "gif_asset": "assets/fitness/videos/3286-JsOV1SU.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重雙力臂", "instructions_en": ["Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart.", "Engage your core and pull your body up towards the bar, leading with your chest.", "As you reach the top of the movement, transition your grip so that your palms are facing towards you.", "Continue pulling yourself up until your chest reaches the bar, then pause for a moment.", "Slowly lower yourself back down to the starting position, maintaining control throughout the movement.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先悬挂在引体向上杆上，手掌背向自己，双手之间的距离略大于肩宽。", "启动核心肌群，将身体拉向杠铃杆，以胸部为主导。", "当你到达动作的最高点时，改变你的握力，使你的手掌朝向你。", "继续拉起自己，直到胸部到达杠铃，然后暂停片刻。", "慢慢地将自己放回到起始位置，在整个运动过程中保持控制。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "triceps", "shoulders", "chest"], "instructions_zh_hant": ["首先懸掛在引體向上桿上，手掌背向自己，雙手之間的距離略大于肩寬。", "啟動核心肌群，將身體拉向杠鈴桿，以胸部為主導。", "當你到達動作的最高點時，改變你的握力，使你的手掌朝向你。", "繼續拉起自己，直到胸部到達杠鈴，然后暫停片刻。", "慢慢地將自己放回到起始位置，在整個運動過程中保持控制。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3312', 'exercise', 1, '{"id": "3312", "target": "lats", "name_en": "weighted muscle up (on bar)", "name_zh": "负重双力臂（于杆）", "body_part": "back", "equipment": "weighted", "gif_asset": "assets/fitness/videos/3312-MCkqdKE.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重雙力臂（于桿）", "instructions_en": ["Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart.", "Engage your core and pull your shoulder blades down and back.", "Bend your elbows and pull your chest towards the bar, keeping your body straight.", "Once your chest reaches the bar, push down with your hands and drive your elbows back, lifting your body above the bar.", "Pause at the top of the movement, then slowly lower yourself back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["首先悬挂在引体向上杆上，手掌背向自己，双手之间的距离略大于肩宽。", "启动你的核心并将肩胛骨向下拉和向后拉。", "弯曲肘部，将胸部拉向杠铃杆，保持身体挺直。", "当你的胸部到达杠铃时，用手向下推并将肘部向后推，将身体提升到杠铃上方。", "在动作的最高点暂停，然后慢慢降低回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "triceps", "shoulders", "forearms"], "instructions_zh_hant": ["首先懸掛在引體向上桿上，手掌背向自己，雙手之間的距離略大于肩寬。", "啟動你的核心并將肩胛骨向下拉和向后拉。", "彎曲肘部，將胸部拉向杠鈴桿，保持身體挺直。", "當你的胸部到達杠鈴時，用手向下推并將肘部向后推，將身體提升到杠鈴上方。", "在動作的最高點暫停，然后慢慢降低回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3290', 'exercise', 1, '{"id": "3290", "target": "lats", "name_en": "weighted one hand pull up", "name_zh": "负重单手引体向上", "body_part": "back", "equipment": "weighted", "gif_asset": "assets/fitness/videos/3290-fXfqg1E.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重單手引體向上", "instructions_en": ["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.", "Hang from the bar with your arm fully extended and your body straight.", "Engage your core and pull your body up towards the bar by bending your elbow and squeezing your back muscles.", "Continue pulling until your chin is above the bar.", "Lower your body back down to the starting position with control.", "Repeat for the desired number of repetitions."], "instructions_zh": ["正手握住引体向上杆，握距略宽于肩宽。", "悬挂在杠上，手臂完全伸展，身体伸直。", "弯曲肘部并挤压背部肌肉，调动核心力量，将身体拉向杠铃杆。", "继续拉，直到下巴位于杠铃上方。", "有控制地降低身体回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["正手握住引體向上桿，握距略寬于肩寬。", "懸掛在杠上，手臂完全伸展，身體伸直。", "彎曲肘部并擠壓背部肌肉，調動核心力量，將身體拉向杠鈴桿。", "繼續拉，直到下巴位于杠鈴上方。", "有控制地降低身體回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0840', 'exercise', 1, '{"id": "0840", "target": "abs", "name_en": "weighted overhead crunch (on stability ball)", "name_zh": "负重过顶卷腹（健身球）", "body_part": "waist", "equipment": "weighted", "gif_asset": "assets/fitness/videos/0840-xmM75XG.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重過頂卷腹（健身球）", "instructions_en": ["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.", "Hold a weight plate or dumbbell with both hands and extend your arms overhead.", "Engage your abs and slowly curl your torso forward, bringing your chest towards your knees.", "Pause for a moment at the top, then slowly lower your torso back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。", "双手握住杠铃片或哑铃，并将手臂伸过头顶。", "收紧腹肌，慢慢向前弯曲躯干，使胸部靠近膝盖。", "在顶部暂停片刻，然后慢慢将躯干放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["obliques", "lower back"], "instructions_zh_hant": ["坐在穩定球上，雙腳平放在地面上，膝蓋彎曲成 90 度角。", "雙手握住杠鈴片或啞鈴，并將手臂伸過頭頂。", "收緊腹肌，慢慢向前彎曲軀幹，使胸部靠近膝蓋。", "在頂部暫停片刻，然后慢慢將軀幹放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0841', 'exercise', 1, '{"id": "0841", "target": "lats", "name_en": "weighted pull-up", "name_zh": "负重引体向上", "body_part": "back", "equipment": "weighted", "gif_asset": "assets/fitness/videos/0841-HMzLjXx.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重引體向上", "instructions_en": ["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.", "Hang from the bar with your arms fully extended and your body straight.", "Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.", "Continue pulling until your chin is above the bar.", "Pause for a moment at the top, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["正手握住引体向上杆，握距略宽于肩宽。", "悬挂在杠上，双臂完全伸展，身体伸直。", "收紧背部肌肉，将身体拉向杠铃杆，保持肘部靠近身体。", "继续拉，直到下巴位于杠铃上方。", "在顶部停顿片刻，然后慢慢将身体放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["正手握住引體向上桿，握距略寬于肩寬。", "懸掛在杠上，雙臂完全伸展，身體伸直。", "收緊背部肌肉，將身體拉向杠鈴桿，保持肘部靠近身體。", "繼續拉，直到下巴位于杠鈴上方。", "在頂部停頓片刻，然后慢慢將身體放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0844', 'exercise', 1, '{"id": "0844", "target": "delts", "name_en": "weighted round arm", "name_zh": "负重绕环手臂", "body_part": "shoulders", "equipment": "weighted", "gif_asset": "assets/fitness/videos/0844-VLYXo8S.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重繞環手臂", "instructions_en": ["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Raise your arms out to the sides, keeping a slight bend in your elbows.", "Continue lifting your arms until they are parallel to the ground.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，每只手各握一个哑铃。", "稍微弯曲膝盖，髋部向前转动，保持背部挺直。", "将手臂向两侧举起，肘部保持轻微弯曲。", "继续举起手臂，直到它们与地面平行。", "在顶部暂停片刻，然后慢慢将手臂放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "upper back"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，每只手各握一個啞鈴。", "稍微彎曲膝蓋，髖部向前轉動，保持背部挺直。", "將手臂向兩側舉起，肘部保持輕微彎曲。", "繼續舉起手臂，直到它們與地面平行。", "在頂部暫停片刻，然后慢慢將手臂放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0846', 'exercise', 1, '{"id": "0846", "target": "abs", "name_en": "weighted russian twist", "name_zh": "负重俄罗斯转体", "body_part": "waist", "equipment": "weighted", "gif_asset": "assets/fitness/videos/0846-fZFZ704.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重俄羅斯轉體", "instructions_en": ["Sit on the ground with your knees bent and your feet flat on the floor.", "Hold a weight or medicine ball with both hands in front of your chest.", "Lean back slightly, keeping your back straight and your core engaged.", "Slowly twist your torso to the right, bringing the weight or medicine ball towards the floor on your right side.", "Pause for a moment, then twist your torso to the left, bringing the weight or medicine ball towards the floor on your left side.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["坐在地上，膝盖弯曲，双脚平放在地板上。", "双手握住重物球或健身球放在胸前。", "稍微向后倾斜，保持背部挺直，核心肌群参与。", "慢慢地将你的躯干向右扭转，将重物或药球拉向右侧的地板。", "暂停片刻，然后将躯干向左扭转，将重物或健身球拉向左侧的地板。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["obliques", "lower back"], "instructions_zh_hant": ["坐在地上，膝蓋彎曲，雙腳平放在地板上。", "雙手握住重物球或健身球放在胸前。", "稍微向后傾斜，保持背部挺直，核心肌群參與。", "慢慢地將你的軀幹向右扭轉，將重物或藥球拉向右側的地板。", "暫停片刻，然后將軀幹向左扭轉，將重物或健身球拉向左側的地板。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0845', 'exercise', 1, '{"id": "0845", "target": "abs", "name_en": "weighted russian twist (legs up)", "name_zh": "负重俄罗斯转体（双腿向上）", "body_part": "waist", "equipment": "weighted", "gif_asset": "assets/fitness/videos/0845-WU9BLIs.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重俄羅斯轉體（雙腿向上）", "instructions_en": ["Sit on the ground with your knees bent and feet lifted off the ground, keeping your legs together.", "Hold the weight with both hands in front of your chest, keeping your elbows slightly bent.", "Lean back slightly to engage your core muscles.", "Twist your torso to the right, bringing the weight towards the ground on your right side.", "Pause for a moment, then twist your torso to the left, bringing the weight towards the ground on your left side.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["坐在地上，膝盖弯曲，双脚离开地面，保持双腿并拢。", "用双手将重物放在胸前，保持肘部稍微弯曲。", "稍微向后倾斜以锻炼核心肌肉。", "将躯干向右扭转，将重量移向右侧地面。", "暂停片刻，然后将躯干向左扭转，将重量转移到左侧地面。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["obliques", "hip flexors"], "instructions_zh_hant": ["坐在地上，膝蓋彎曲，雙腳離開地面，保持雙腿并攏。", "用雙手將重物放在胸前，保持肘部稍微彎曲。", "稍微向后傾斜以鍛煉核心肌肉。", "將軀幹向右扭轉，將重量移向右側地面。", "暫停片刻，然后將軀幹向左扭轉，將重量轉移到左側地面。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2371', 'exercise', 1, '{"id": "2371", "target": "abs", "name_en": "weighted russian twist v. 2", "name_zh": "负重俄罗斯转体变式2", "body_part": "waist", "equipment": "weighted", "gif_asset": "assets/fitness/videos/2371-YIUAtYf.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重俄羅斯轉體變式2", "instructions_en": ["Sit on the ground with your knees bent and feet flat on the floor.", "Hold the weight with both hands in front of your chest.", "Lean back slightly to engage your core muscles.", "Twist your torso to the right, bringing the weight towards the right side of your body.", "Pause for a moment, then twist your torso to the left, bringing the weight towards the left side of your body.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["坐在地上，膝盖弯曲，双脚平放在地板上。", "用双手将重物放在胸前。", "稍微向后倾斜以锻炼核心肌肉。", "将躯干向右扭转，将重量移至身体右侧。", "暂停片刻，然后将躯干向左扭转，将重量移向身体的左侧。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["obliques", "lower back"], "instructions_zh_hant": ["坐在地上，膝蓋彎曲，雙腳平放在地板上。", "用雙手將重物放在胸前。", "稍微向后傾斜以鍛煉核心肌肉。", "將軀幹向右扭轉，將重量移至身體右側。", "暫停片刻，然后將軀幹向左扭轉，將重量移向身體的左側。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0847', 'exercise', 1, '{"id": "0847", "target": "biceps", "name_en": "weighted seated bicep curl (on stability ball)", "name_zh": "负重坐姿二头弯举（健身球）", "body_part": "upper arms", "equipment": "medicine ball", "gif_asset": "assets/fitness/videos/0847-b4b6afT.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重坐姿二頭彎舉（健身球）", "instructions_en": ["Sit on a stability ball with your feet flat on the ground and your back straight.", "Hold a medicine ball with an underhand grip, palms facing up, and let your arms hang down by your sides.", "Keeping your upper arms stationary, exhale and curl the medicine ball up towards your shoulders.", "Pause for a moment at the top, squeezing your biceps.", "Inhale and slowly lower the medicine ball back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在稳定球上，双脚平放在地面上，背部挺直。", "反手握住健身球，手掌朝上，让手臂垂在身体两侧。", "保持上臂静止，呼气并将药球向上卷向肩膀。", "在顶部暂停片刻，挤压你的二头肌。", "吸气并缓慢地将健身球放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["坐在穩定球上，雙腳平放在地面上，背部挺直。", "反手握住健身球，手掌朝上，讓手臂垂在身體兩側。", "保持上臂靜止，呼氣并將藥球向上卷向肩膀。", "在頂部暫停片刻，擠壓你的二頭肌。", "吸氣并緩慢地將健身球放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0849', 'exercise', 1, '{"id": "0849", "target": "abs", "name_en": "weighted seated twist (on stability ball)", "name_zh": "负重坐姿转体（健身球）", "body_part": "waist", "equipment": "weighted", "gif_asset": "assets/fitness/videos/0849-s34Y4LR.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重坐姿轉體（健身球）", "instructions_en": ["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.", "Hold a weight plate or dumbbell with both hands close to your chest.", "Engage your core and slowly rotate your torso to one side, keeping your hips stable.", "Pause for a moment at the end of the rotation, then slowly return to the starting position.", "Repeat the rotation to the other side.", "Continue alternating sides for the desired number of repetitions."], "instructions_zh": ["坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。", "双手靠近胸部握住杠铃片或哑铃。", "启动你的核心并慢慢地将你的躯干旋转到一侧，保持臀部稳定。", "旋转结束时暂停片刻，然后慢慢回到起始位置。", "重复旋转到另一侧。", "继续交替进行所需的重复次数。"], "secondary_muscles": ["obliques", "lower back"], "instructions_zh_hant": ["坐在穩定球上，雙腳平放在地面上，膝蓋彎曲成 90 度角。", "雙手靠近胸部握住杠鈴片或啞鈴。", "啟動你的核心并慢慢地將你的軀幹旋轉到一側，保持臀部穩定。", "旋轉結束時暫停片刻，然后慢慢回到起始位置。", "重復旋轉到另一側。", "繼續交替進行所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0850', 'exercise', 1, '{"id": "0850", "target": "abs", "name_en": "weighted side bend (on stability ball)", "name_zh": "负重侧屈（健身球）", "body_part": "waist", "equipment": "weighted", "gif_asset": "assets/fitness/videos/0850-6bOA1Oi.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重側屈（健身球）", "instructions_en": ["Sit on a stability ball with your feet shoulder-width apart and flat on the ground.", "Hold a weight in one hand and place your other hand on your hip.", "Engage your core and slowly bend sideways towards the weighted side, keeping your back straight.", "Pause for a moment at the bottom, then slowly return to the starting position.", "Repeat for the desired number of repetitions, then switch sides."], "instructions_zh": ["坐在稳定球上，双脚分开与肩同宽，平放在地面上。", "一只手握住重物，另一只手放在臀部上。", "启动你的核心，慢慢向受重侧侧弯，保持背部挺直。", "在底部停顿片刻，然后慢慢回到起始位置。", "重复所需的重复次数，然后换边。"], "secondary_muscles": ["obliques", "lower back"], "instructions_zh_hant": ["坐在穩定球上，雙腳分開與肩同寬，平放在地面上。", "一只手握住重物，另一只手放在臀部上。", "啟動你的核心，慢慢向受重側側彎，保持背部挺直。", "在底部停頓片刻，然后慢慢回到起始位置。", "重復所需的重復次數，然后換邊。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0851', 'exercise', 1, '{"id": "0851", "target": "quads", "name_en": "weighted sissy squat", "name_zh": "负重西西式深蹲", "body_part": "upper legs", "equipment": "weighted", "gif_asset": "assets/fitness/videos/0851-0lQnxMZ.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重西西式深蹲", "instructions_en": ["Stand with your feet shoulder-width apart and your toes pointing slightly outward.", "Hold a weight in front of your chest with both hands, or place a barbell across your upper back.", "Keeping your chest up and your core engaged, slowly lower your body down by bending at the knees and hips.", "Continue lowering until your thighs are parallel to the ground or as low as you can comfortably go.", "Pause for a moment at the bottom, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，脚趾稍微向外。", "用双手将重物放在胸前，或将杠铃放在上背部。", "保持挺胸，核心收紧，弯曲膝盖和臀部，慢慢降低身体。", "继续降低，直到大腿与地面平行或尽可能低。", "在底部停顿片刻，然后推动脚后跟回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["glutes", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，腳趾稍微向外。", "用雙手將重物放在胸前，或將杠鈴放在上背部。", "保持挺胸，核心收緊，彎曲膝蓋和臀部，慢慢降低身體。", "繼續降低，直到大腿與地面平行或盡可能低。", "在底部停頓片刻，然后推動腳后跟回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0852', 'exercise', 1, '{"id": "0852", "target": "glutes", "name_en": "weighted squat", "name_zh": "负重深蹲", "body_part": "upper legs", "equipment": "weighted", "gif_asset": "assets/fitness/videos/0852-JZuApnB.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重深蹲", "instructions_en": ["Stand with your feet shoulder-width apart, toes pointing slightly outward.", "Hold a weight in front of your chest or on your shoulders.", "Engage your core and keep your chest up as you lower your hips down and back, as if sitting into a chair.", "Lower until your thighs are parallel to the ground, or as low as you can comfortably go.", "Push through your heels to stand back up, squeezing your glutes at the top.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，脚趾稍微向外。", "将重物放在胸前或肩膀上。", "收紧核心并保持挺胸，同时降低臀部和向后倾斜，就像坐在椅子上一样。", "降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。", "推动脚后跟站起来，在顶部挤压臀部。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，腳趾稍微向外。", "將重物放在胸前或肩膀上。", "收緊核心并保持挺胸，同時降低臀部和向后傾斜，就像坐在椅子上一樣。", "降低直到大腿與地面平行，或者盡可能降低到您能舒服的高度。", "推動腳后跟站起來，在頂部擠壓臀部。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1754', 'exercise', 1, '{"id": "1754", "target": "triceps", "name_en": "weighted three bench dips", "name_zh": "负重三凳上臂屈伸", "body_part": "upper arms", "equipment": "weighted", "gif_asset": "assets/fitness/videos/1754-gtO1ErP.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重三凳上臂屈伸", "instructions_en": ["Sit on the edge of a bench with your hands gripping the edge, fingers pointing forward.", "Walk your feet forward, sliding your butt off the bench and supporting your weight with your arms.", "Lower your body by bending your elbows, keeping your back close to the bench.", "Pause for a moment at the bottom, then push yourself back up to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳边缘，双手抓住边缘，手指指向前方。", "双脚向前走，将臀部滑离长凳，并用手臂支撑体重。", "弯曲肘部降低身体，使背部靠近长凳。", "在底部暂停片刻，然后将自己推回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["坐在長凳邊緣，雙手抓住邊緣，手指指向前方。", "雙腳向前走，將臀部滑離長凳，并用手臂支撐體重。", "彎曲肘部降低身體，使背部靠近長凳。", "在底部暫停片刻，然后將自己推回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0853', 'exercise', 1, '{"id": "0853", "target": "biceps", "name_en": "weighted standing curl", "name_zh": "负重站姿弯举", "body_part": "upper arms", "equipment": "weighted", "gif_asset": "assets/fitness/videos/0853-M5Y7GPg.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重站姿彎舉", "instructions_en": ["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.", "Keep your elbows close to your torso and exhale as you curl the weights up to shoulder level.", "Pause for a moment at the top, then inhale as you slowly lower the weights back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝前。", "保持肘部靠近躯干，并在将哑铃弯举至肩部水平时呼气。", "在顶部暂停片刻，然后吸气，慢慢将重量放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["forearms"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手各握一個啞鈴，手掌朝前。", "保持肘部靠近軀幹，并在將啞鈴彎舉至肩部水平時呼氣。", "在頂部暫停片刻，然后吸氣，慢慢將重量放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0854', 'exercise', 1, '{"id": "0854", "target": "forearms", "name_en": "weighted standing hand squeeze", "name_zh": "负重握力挤压", "body_part": "lower arms", "equipment": "weighted", "gif_asset": "assets/fitness/videos/0854-bjqbauy.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重握力擠壓", "instructions_en": ["Stand with your feet shoulder-width apart and hold a weight in each hand.", "Extend your arms straight in front of you, palms facing each other.", "Squeeze your hands together as hard as you can, engaging your forearms.", "Hold the squeeze for a few seconds, then release.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，每只手各握一个重物。", "将双臂伸直在身前，手掌相对。", "尽可能用力将双手握在一起，用力接触前臂。", "按住挤压几秒钟，然后松开。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "triceps"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，每只手各握一個重物。", "將雙臂伸直在身前，手掌相對。", "盡可能用力將雙手握在一起，用力接觸前臂。", "按住擠壓幾秒鐘，然后松開。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3642', 'exercise', 1, '{"id": "3642", "target": "glutes", "name_en": "weighted stretch lunge", "name_zh": "负重拉伸弓步", "body_part": "upper legs", "equipment": "weighted", "gif_asset": "assets/fitness/videos/3642-13VW2VO.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重拉伸弓步", "instructions_en": ["Stand with your feet shoulder-width apart.", "Take a step forward with your right foot, keeping your back straight.", "Lower your body by bending your knees until your right thigh is parallel to the ground.", "Push through your right heel to return to the starting position.", "Repeat with your left leg.", "Continue alternating legs for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立。", "右脚向前迈出一步，保持背部挺直。", "弯曲膝盖降低身体，直到右大腿与地面平行。", "推动右脚跟回到起始位置。", "左腿重复上述动作。", "继续交替双腿达到所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["雙腳分開與肩同寬站立。", "右腳向前邁出一步，保持背部挺直。", "彎曲膝蓋降低身體，直到右大腿與地面平行。", "推動右腳跟回到起始位置。", "左腿重復上述動作。", "繼續交替雙腿達到所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0856', 'exercise', 1, '{"id": "0856", "target": "pectorals", "name_en": "weighted svend press", "name_zh": "负重斯文推举", "body_part": "chest", "equipment": "weighted", "gif_asset": "assets/fitness/videos/0856-I1OBLnn.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重斯文推舉", "instructions_en": ["Stand with your feet shoulder-width apart and hold a weight plate in front of your chest with both hands.", "Keep your elbows slightly bent and your palms facing each other.", "Press the weight plate straight out in front of you, fully extending your arms.", "Pause for a moment at the end of the movement, then slowly bring the weight plate back to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["双脚分开与肩同宽站立，双手将杠铃片放在胸前。", "保持肘部稍微弯曲，手掌相对。", "将配重板直接压在您面前，完全伸展双臂。", "动作结束时暂停片刻，然后慢慢将配重板放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["shoulders", "triceps"], "instructions_zh_hant": ["雙腳分開與肩同寬站立，雙手將杠鈴片放在胸前。", "保持肘部稍微彎曲，手掌相對。", "將配重板直接壓在您面前，完全伸展雙臂。", "動作結束時暫停片刻，然后慢慢將配重板放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1755', 'exercise', 1, '{"id": "1755", "target": "triceps", "name_en": "weighted tricep dips", "name_zh": "负重肱三头肌臂屈伸", "body_part": "upper arms", "equipment": "weighted", "gif_asset": "assets/fitness/videos/1755-bZq4bwK.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重肱三頭肌臂屈伸", "instructions_en": ["Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.", "Slide your butt off the front of the bench with your legs extended in front of you.", "Keep your back close to the bench and your elbows slightly bent.", "Lower your body by bending your elbows until your upper arms are parallel to the floor.", "Push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["坐在长凳或椅子的边缘，双手抓住臀部旁边的边缘。", "将你的屁股从长凳前面滑下来，双腿在你面前伸展。", "保持背部靠近长凳，肘部稍微弯曲。", "弯曲肘部降低身体，直到上臂与地板平行。", "伸直手臂，将自己推回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["坐在長凳或椅子的邊緣，雙手抓住臀部旁邊的邊緣。", "將你的屁股從長凳前面滑下來，雙腿在你面前伸展。", "保持背部靠近長凳，肘部稍微彎曲。", "彎曲肘部降低身體，直到上臂與地板平行。", "伸直手臂，將自己推回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1767', 'exercise', 1, '{"id": "1767", "target": "triceps", "name_en": "weighted triceps dip on high parallel bars", "name_zh": "负重臂屈伸于高位平行双杠", "body_part": "upper arms", "equipment": "weighted", "gif_asset": "assets/fitness/videos/1767-K1vlode.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "負重臂屈伸于高位平行雙槓", "instructions_en": ["Position yourself between two parallel bars with your hands gripping the bars and your arms fully extended.", "Bend your elbows and lower your body until your upper arms are parallel to the ground.", "Pause for a moment, then push through your palms to straighten your arms and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将自己定位在两个双杠之间，双手握住杠，双臂完全伸展。", "弯曲肘部并降低身体，直到上臂与地面平行。", "暂停片刻，然后用手掌推直手臂并返回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["chest", "shoulders"], "instructions_zh_hant": ["將自己定位在兩個雙杠之間，雙手握住杠，雙臂完全伸展。", "彎曲肘部并降低身體，直到上臂與地面平行。", "暫停片刻，然后用手掌推直手臂并返回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0857', 'exercise', 1, '{"id": "0857", "target": "abs", "name_en": "wheel rollerout", "name_zh": "健腹轮前推", "body_part": "waist", "equipment": "wheel roller", "gif_asset": "assets/fitness/videos/0857-NAgVB3t.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健腹輪前推", "instructions_en": ["Kneel on the floor and place the wheel roller in front of you.", "Place your hands on the handles of the wheel roller and extend your arms straight out in front of you.", "Engage your core muscles and slowly roll the wheel forward, keeping your back straight and your abs tight.", "Continue rolling forward until your body is fully extended and your arms are overhead.", "Pause for a moment, then slowly roll the wheel back towards your knees, maintaining control and keeping your abs engaged.", "Repeat for the desired number of repetitions."], "instructions_zh": ["跪在地板上，将滚轮放在您面前。", "将双手放在滚轮的手柄上，并将手臂伸直至前方。", "调动你的核心肌肉，慢慢向前滚动轮子，保持背部挺直，腹肌紧张。", "继续向前滚动，直到身体完全伸展并且手臂举过头顶。", "暂停片刻，然后慢慢地将轮子向膝盖方向滚动，保持控制并保持腹肌接合。", "重复所需的重复次数。"], "secondary_muscles": ["lower back"], "instructions_zh_hant": ["跪在地板上，將滾輪放在您面前。", "將雙手放在滾輪的手柄上，并將手臂伸直至前方。", "調動你的核心肌肉，慢慢向前滾動輪子，保持背部挺直，腹肌緊張。", "繼續向前滾動，直到身體完全伸展并且手臂舉過頭頂。", "暫停片刻，然后慢慢地將輪子向膝蓋方向滾動，保持控制并保持腹肌接合。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('3637', 'exercise', 1, '{"id": "3637", "target": "cardiovascular system", "name_en": "wheel run", "name_zh": "健腹轮跑步", "body_part": "cardio", "equipment": "body weight", "gif_asset": "assets/fitness/videos/3637-km2Ljzj.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "健腹輪跑步", "instructions_en": ["Start in a plank position with your hands on the wheel and your body straight.", "Engage your core and start rolling the wheel forward by extending your arms.", "Continue rolling until your body is fully extended and your arms are overhead.", "Reverse the movement by pulling the wheel back towards your body, using your core and arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["从平板支撑位置开始，双手放在方向盘上，身体伸直。", "启动你的核心并通过伸展双臂开始向前滚动轮子。", "继续滚动，直到身体完全伸展并且手臂举过头顶。", "使用你的核心和手臂将轮子拉回你的身体，从而扭转运动。", "重复所需的重复次数。"], "secondary_muscles": ["quadriceps", "hamstrings", "calves"], "instructions_zh_hant": ["從平板支撐位置開始，雙手放在方向盤上，身體伸直。", "啟動你的核心并通過伸展雙臂開始向前滾動輪子。", "繼續滾動，直到身體完全伸展并且手臂舉過頭頂。", "使用你的核心和手臂將輪子拉回你的身體，從而扭轉運動。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1429', 'exercise', 1, '{"id": "1429", "target": "lats", "name_en": "wide grip pull-up", "name_zh": "宽握引体向上", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1429-Qqi7bko.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "寬握引體向上", "instructions_en": ["Hang from a pull-up bar with your palms facing away from you and your hands wider than shoulder-width apart.", "Engage your core and squeeze your shoulder blades together.", "Pull your body up towards the bar until your chin is above the bar.", "Lower your body back down to the starting position with control.", "Repeat for the desired number of repetitions."], "instructions_zh": ["悬挂在引体向上杆上，手掌背向自己，双手之间的距离比肩宽。", "启动你的核心并将肩胛骨挤压在一起。", "将身体向上拉向杠铃，直到下巴位于杠铃上方。", "有控制地降低身体回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["懸掛在引體向上桿上，手掌背向自己，雙手之間的距離比肩寬。", "啟動你的核心并將肩胛骨擠壓在一起。", "將身體向上拉向杠鈴，直到下巴位于杠鈴上方。", "有控制地降低身體回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1367', 'exercise', 1, '{"id": "1367", "target": "lats", "name_en": "wide grip rear pull-up", "name_zh": "宽握颈后引体向上", "body_part": "back", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1367-OYFhXVD.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "寬握頸后引體向上", "instructions_en": ["Grab the pull-up bar with a wide overhand grip, hands slightly wider than shoulder-width apart.", "Hang from the bar with your arms fully extended and your body straight.", "Engage your back muscles and pull your body up towards the bar, leading with your chest.", "Continue pulling until your chin is above the bar.", "Pause for a moment at the top, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["正手宽握抓住引体向上杆，双手间距略宽于肩宽。", "悬挂在杠上，双臂完全伸展，身体伸直。", "调动背部肌肉，将身体拉向杠铃杆，以胸部为主导。", "继续拉，直到下巴位于杠铃上方。", "在顶部停顿片刻，然后慢慢将身体放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "forearms"], "instructions_zh_hant": ["正手寬握抓住引體向上桿，雙手間距略寬于肩寬。", "懸掛在杠上，雙臂完全伸展，身體伸直。", "調動背部肌肉，將身體拉向杠鈴桿，以胸部為主導。", "繼續拉，直到下巴位于杠鈴上方。", "在頂部停頓片刻，然后慢慢將身體放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1311', 'exercise', 1, '{"id": "1311", "target": "pectorals", "name_en": "wide hand push up", "name_zh": "宽距手俯卧撑", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1311-JmMVpR3.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "寬距手俯臥撐", "instructions_en": ["Start in a high plank position with your hands wider than shoulder-width apart.", "Keep your body in a straight line from head to toe.", "Lower your chest towards the ground by bending your elbows, keeping them close to your sides.", "Push through your palms to extend your arms and return to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["从高平板支撑位置开始，双手分开比肩宽。", "保持身体从头到脚呈一条直线。", "弯曲肘部，将胸部压向地面，使其靠近身体两侧。", "推动手掌以伸展手臂并返回到起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["從高平板支撐位置開始，雙手分開比肩寬。", "保持身體從頭到腳呈一條直線。", "彎曲肘部，將胸部壓向地面，使其靠近身體兩側。", "推動手掌以伸展手臂并返回到起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('2363', 'exercise', 1, '{"id": "2363", "target": "pectorals", "name_en": "wide-grip chest dip on high parallel bars", "name_zh": "宽握双杠臂屈伸（偏胸）于高位平行双杠", "body_part": "chest", "equipment": "body weight", "gif_asset": "assets/fitness/videos/2363-O2K9Vb5.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "寬握雙槓臂屈伸（偏胸）于高位平行雙槓", "instructions_en": ["Position yourself on the parallel bars with your arms fully extended and your body suspended in the air.", "Lean forward slightly and lower your body by bending your elbows until your chest is just above the bars.", "Pause for a moment, then push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将自己置于双杠上，双臂完全伸展，身体悬浮在空中。", "稍微向前倾，弯曲肘部降低身体，直到胸部位于杠铃上方。", "暂停片刻，然后伸直手臂，将自己推回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["triceps", "shoulders"], "instructions_zh_hant": ["將自己置于雙杠上，雙臂完全伸展，身體懸浮在空中。", "稍微向前傾，彎曲肘部降低身體，直到胸部位于杠鈴上方。", "暫停片刻，然后伸直手臂，將自己推回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1604', 'exercise', 1, '{"id": "1604", "target": "hamstrings", "name_en": "world greatest stretch", "name_zh": "世界最伟大拉伸", "body_part": "upper legs", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1604-DFGXwZr.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "世界最偉大拉伸", "instructions_en": ["Start in a lunge position with your right foot forward and your left foot back.", "Place your hands on the ground on either side of your right foot.", "Lower your left knee to the ground and extend your right leg, keeping your right foot flat on the ground.", "Rotate your torso to the right, reaching your right arm up towards the ceiling.", "Hold this position for a few seconds, then return to the starting position.", "Switch sides and repeat the stretch with your left foot forward."], "instructions_zh": ["从弓步位置开始，右脚向前，左脚向后。", "将双手放在右脚两侧的地面上。", "将左膝降低到地面并伸展右腿，保持右脚平放在地面上。", "向右旋转你的躯干，将你的右臂伸向天花板。", "保持这个姿势几秒钟，然后回到起始位置。", "换边并重复拉伸，左脚向前。"], "secondary_muscles": ["glutes", "quadriceps", "calves"], "instructions_zh_hant": ["從弓步位置開始，右腳向前，左腳向后。", "將雙手放在右腳兩側的地面上。", "將左膝降低到地面并伸展右腿，保持右腳平放在地面上。", "向右旋轉你的軀幹，將你的右臂伸向天花板。", "保持這個姿勢幾秒鐘，然后回到起始位置。", "換邊并重復拉伸，左腳向前。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('1428', 'exercise', 1, '{"id": "1428", "target": "forearms", "name_en": "wrist circles", "name_zh": "手腕绕环", "body_part": "lower arms", "equipment": "body weight", "gif_asset": "assets/fitness/videos/1428-2zNKRUB.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "手腕繞環", "instructions_en": ["Extend your arms straight out in front of you.", "Make a fist with both hands.", "Rotate your wrists in a circular motion, keeping your arms still.", "Continue the wrist circles for the desired number of repetitions."], "instructions_zh": ["将双臂伸直在身前。", "双手握拳。", "以圆周运动旋转手腕，保持手臂静止。", "继续手腕转圈达到所需的重复次数。"], "secondary_muscles": ["hands", "wrists"], "instructions_zh_hant": ["將雙臂伸直在身前。", "雙手握拳。", "以圓周運動旋轉手腕，保持手臂靜止。", "繼續手腕轉圈達到所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
INSERT INTO public.official_fitness_content (id, kind, version, content, is_enabled, created_at, updated_at, updated_by) VALUES ('0859', 'exercise', 1, '{"id": "0859", "target": "forearms", "name_en": "wrist rollerer", "name_zh": "卷腕器训练", "body_part": "lower arms", "equipment": "weighted", "gif_asset": "assets/fitness/videos/0859-bd5b860.gif", "attribution": "© Gym visual — https://gymvisual.com/", "name_zh_hant": "卷腕器訓練", "instructions_en": ["Attach a weight to one end of a rope or bar.", "Hold the other end of the rope or bar with both hands, palms facing down.", "Stand with your feet shoulder-width apart and your arms fully extended in front of you.", "Slowly roll the weight up towards your hands by flexing your wrists.", "Pause for a moment at the top, then slowly lower the weight back down to the starting position.", "Repeat for the desired number of repetitions."], "instructions_zh": ["将重物固定在绳子或杆的一端。", "用双手握住绳子或杆的另一端，手掌朝下。", "双脚分开与肩同宽站立，双臂完全伸展在身前。", "弯曲手腕，慢慢地将重物向上滚动到手上。", "在顶部暂停片刻，然后慢慢将重量放回起始位置。", "重复所需的重复次数。"], "secondary_muscles": ["biceps", "triceps"], "instructions_zh_hant": ["將重物固定在繩子或桿的一端。", "用雙手握住繩子或桿的另一端，手掌朝下。", "雙腳分開與肩同寬站立，雙臂完全伸展在身前。", "彎曲手腕，慢慢地將重物向上滾動到手上。", "在頂部暫停片刻，然后慢慢將重量放回起始位置。", "重復所需的重復次數。"]}', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, '系统初始化');
